INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6,'На страницах книги начинают проявляться сотни чертежей и диаграмм. Одни из них вам прекрасно известны, а другие кажутся чуждыми, хотя и смутно знакомыми.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','На страницах книги начинают проявляться сотни чертежей и диаграмм. Одни из них вам прекрасно известны, а другие кажутся чуждыми, хотя и смутно знакомыми.',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7,'Различные изображения, фигуры и знаки складываются в ясную картину. Книга будто знает, насколько вы умело работаете с кожей, и предлагает вам выбор. Но помните, что выбрать можно только один раз, и потом вы не сможете изменить своего решения.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Различные изображения, фигуры и знаки складываются в ясную картину. Книга будто знает, насколько вы умело работаете с кожей, и предлагает вам выбор. Но помните, что выбрать можно только один раз, и потом вы не сможете изменить своего решения.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (521,'Ты $gубил:убила; Призрачный Вой. Ну ты даешь!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты $gубил:убила; Призрачный Вой. Ну ты даешь!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (522,'Подойди поближе, $gюноша:девушка;. Некогда я слышал стук сердца добычи, а теперь тебе придется говорить погромче, если хочешь, чтоб я тебя расслышал.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Подойди поближе, $gюноша:девушка;. Некогда я слышал стук сердца добычи, а теперь тебе придется говорить погромче, если хочешь, чтоб я тебя расслышал.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (523,'Много-много лет я проходил по этим равнинам и охотился тут на крупного зверя. Никто никогда не мог противостоять мне… пока я не повстречался с Призрачным Воем.$B$BДавным-давно огромный волк был союзником тауренов и храбро сражался с Пылающим Легионом. Но его жестоко ранил демон, и рана так никогда и не зажила. В конце концов… Призрачный Вой обезумел.$B$BТеперь он носится по равнинам, терзаемый болью, ища способ положить ей конец. К стыду своему должен сказать: когда мы сразились, я не сумел убить его…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Много-много лет я проходил по этим равнинам и охотился тут на крупного зверя. Никто никогда не мог противостоять мне… пока я не повстречался с Призрачным Воем.$B$BДавным-давно огромный волк был союзником тауренов и храбро сражался с Пылающим Легионом. Но его жестоко ранил демон, и рана так никогда и не зажила. В конце концов… Призрачный Вой обезумел.$B$BТеперь он носится по равнинам, терзаемый болью, ища способ положить ей конец. К стыду своему должен сказать: когда мы сразились, я не сумел убить его…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (538,'Здравствуй, маг. Тебе нужны новые знания о чудесном мире магии?','Здравствуй, маг. Тебе нужны новые знания о чудесном мире магии?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здравствуй, маг. Тебе нужны новые знания о чудесном мире магии?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Здравствуй, маг. Тебе нужны новые знания о чудесном мире магии?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (560,'Приветствую. Я гном, наставник магов. Ну а вы – маг.','Приветствую. Я гном, наставница магов. Ну а вы – маг.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приветствую. Я гном, наставник магов. Ну а вы – маг.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Приветствую. Я гном, наставница магов. Ну а вы – маг.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (561,'Здравствуйте, |3-6($c). Хотите совет? Подружитесь с магами! У нас много чего интересного в рукаве припрятано.','Здравствуйте, |3-6($c). Хотите совет? Подружитесь с магами! У нас много чего интересного в рукаве припрятано.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здравствуйте, |3-6($c). Хотите совет? Подружитесь с магами! У нас много чего интересного в рукаве припрятано.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Здравствуйте, |3-6($c). Хотите совет? Подружитесь с магами! У нас много чего интересного в рукаве припрятано.',`text0_1_loc8`);
