INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (562,'Приветствую. Я обучаю магов из нежити, а вы, стало быть, занимаетесь магией?','Приветствую. Я обучаю магов из нежити, а вы, стало быть, занимаетесь магией?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приветствую. Я обучаю магов из нежити, а вы, стало быть, занимаетесь магией?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Приветствую. Я обучаю магов из нежити, а вы, стало быть, занимаетесь магией?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (564,'Приветствую, |3-6($c). Ты желаешь обрести тайное знание?','Приветствую, |3-6($c). Ты желаешь обрести тайное знание?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приветствую, |3-6($c). Ты желаешь обрести тайное знание?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Приветствую, |3-6($c). Ты желаешь обрести тайное знание?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (580,'Твое время еще не пришло. Я помогу тебе вернуться в мир живых – но не даром.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Твое время еще не пришло. Я помогу тебе вернуться в мир живых – но не даром.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (623,'Что вы хотите, |3-6($c)? Я уже опаздываю, а мой хозяин этого ох как не любит.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что вы хотите, |3-6($c)? Я уже опаздываю, а мой хозяин этого ох как не любит.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (624,'Да, это я. А вам-то что?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да, это я. А вам-то что?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (678,'Зачем это $gтакой молодой:такая молодая:c; |3-6($c) $gпришел:пришла:c; к старому фермеру?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Зачем это $gтакой молодой:такая молодая:c; |3-6($c) $gпришел:пришла:c; к старому фермеру?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (699,'Повелители змей мертвы! Ты отлично $gсправился:справилась;, $n! $B$BНо ритуал пробуждения слишком сложен. В одиночку мне его не провести. $B$BЯ справлюсь со всеми приготовлениями, но мне нужна твоя защита. Кошмарные существа, вызванные Наралексом, погруженным в Изумрудный Сон, оказались очень грозными. Без твоей помощи наше дело обречено. $B$BСкажи, когда будешь $gготов:готова; защищать меня, и мы отправимся в обитель Наралекса.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Повелители змей мертвы! Ты отлично $gсправился:справилась;, $n! $B$BНо ритуал пробуждения слишком сложен. В одиночку мне его не провести. $B$BЯ справлюсь со всеми приготовлениями, но мне нужна твоя защита. Кошмарные существа, вызванные Наралексом, погруженным в Изумрудный Сон, оказались очень грозными. Без твоей помощи наше дело обречено. $B$BСкажи, когда будешь $gготов:готова; защищать меня, и мы отправимся в обитель Наралекса.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (718,'Машина разворачивается в вашу сторону.$B$BСзади у нее странная прорезь с надписью: "Собственность Гелхака Гиромачта".') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Машина разворачивается в вашу сторону.$B$BСзади у нее странная прорезь с надписью: "Собственность Гелхака Гиромачта".',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (720,'Эй! Это ты выполняешь поручения Тирта? Я бы на твоем месте убрался от него как можно скорее. Мозги он загубил выпивкой, но магия его сильна как прежде!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эй! Это ты выполняешь поручения Тирта? Я бы на твоем месте убрался от него как можно скорее. Мозги он загубил выпивкой, но магия его сильна как прежде!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (738,'Конечно, я постараюсь сказать вам эту фразу. Буду рассказывать до тех пор, пока Тирт меня куда-нибудь не позовет.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Конечно, я постараюсь сказать вам эту фразу. Буду рассказывать до тех пор, пока Тирт меня куда-нибудь не позовет.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (758,'Ключ Гелхака входит в свободную скважину.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ключ Гелхака входит в свободную скважину.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (759,'Вздумали насмехаться надо мной, пока я прикован к этому железному шару и не могу защищаться?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вздумали насмехаться надо мной, пока я прикован к этому железному шару и не могу защищаться?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (760,'Ключ от этой адской машины хранится у одного человека. Кажется, его зовут Эстон.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ключ от этой адской машины хранится у одного человека. Кажется, его зовут Эстон.',`text0_0_loc8`);
