INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (761,'Делай-ка ноги, |3-6($c), а то они и тебя закуют в цепи.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Делай-ка ноги, |3-6($c), а то они и тебя закуют в цепи.',`text0_0_loc8`);
