INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (762,'Марглен… Один из тюремщиков. У него ключ от моих оков.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Марглен… Один из тюремщиков. У него ключ от моих оков.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (766,'Я хотел бы чтобы весь снег растаял. Из-за него моя одежда вечно мокрая и всюду грязь!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я хотел бы чтобы весь снег растаял. Из-за него моя одежда вечно мокрая и всюду грязь!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`,`text2_0_loc8`,`text2_1_loc8`,`text3_0_loc8`,`text3_1_loc8`,`text4_0_loc8`,`text4_1_loc8`) VALUES (778,'Что касается меня, я считаю гоблинов фаворитами. У нас есть и оборудование, и талант!','Что касается меня, я считаю гоблинов фаворитами. У нас есть и оборудование, и талант!','Если бы не это треклятое гномское везение, они бы ни одной гонки не выиграли!','Если бы не это треклятое гномское везение, они бы ни одной гонки не выиграли!','Я бы на твоем месте поставил на гоблинов. Болеть за любую другую команду – пустая трата времени.','Я бы на твоем месте поставила на гоблинов. Болеть за любую другую команду – пустая трата времени.','Мои деньги у гоблинов! И если ты хоть что-нибудь соображаешь, то и твои должны быть там же!','Мои деньги у гоблинов! И если ты хоть что-нибудь соображаешь, то и твои должны быть там же!','Говорят, они собираются взорвать машину гномов в следующей гонке! Правда это или нет, но я буду держаться подальше от их боксов.','Говорят, они собираются взорвать машину гномов в следующей гонке! Правда это или нет, но я буду держаться подальше от их боксов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что касается меня, я считаю гоблинов фаворитами. У нас есть и оборудование, и талант!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Что касается меня, я считаю гоблинов фаворитами. У нас есть и оборудование, и талант!',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Если бы не это треклятое гномское везение, они бы ни одной гонки не выиграли!',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Если бы не это треклятое гномское везение, они бы ни одной гонки не выиграли!',`text1_1_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Я бы на твоем месте поставил на гоблинов. Болеть за любую другую команду – пустая трата времени.',`text2_0_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Я бы на твоем месте поставила на гоблинов. Болеть за любую другую команду – пустая трата времени.',`text2_1_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Мои деньги у гоблинов! И если ты хоть что-нибудь соображаешь, то и твои должны быть там же!',`text3_0_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','Мои деньги у гоблинов! И если ты хоть что-нибудь соображаешь, то и твои должны быть там же!',`text3_1_loc8`), `text4_0_loc8`=IF(`text4_0_loc8` IS NULL OR `text4_0_loc8`='','Говорят, они собираются взорвать машину гномов в следующей гонке! Правда это или нет, но я буду держаться подальше от их боксов.',`text4_0_loc8`), `text4_1_loc8`=IF(`text4_1_loc8` IS NULL OR `text4_1_loc8`='','Говорят, они собираются взорвать машину гномов в следующей гонке! Правда это или нет, но я буду держаться подальше от их боксов.',`text4_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (779,'А, вы имеете в виду Джонсона? Говорят, он сейчас в бегах.','А, вы имеете в виду Джонсона? Говорят, он сейчас в бегах.','Ха! Тирт уже который день его ищешь, но он все прячется, трус!','Ха! Тирт уже который день его ищешь, но он все прячется, трус!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','А, вы имеете в виду Джонсона? Говорят, он сейчас в бегах.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','А, вы имеете в виду Джонсона? Говорят, он сейчас в бегах.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Ха! Тирт уже который день его ищешь, но он все прячется, трус!',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Ха! Тирт уже который день его ищешь, но он все прячется, трус!',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`,`text2_0_loc8`,`text2_1_loc8`,`text3_0_loc8`,`text3_1_loc8`,`text4_0_loc8`,`text4_1_loc8`) VALUES (780,'Правду говорят: дуракам везет, иначе эти гоблины разбивали бы свои машины в каждой гонке!','Правду говорят: дуракам везет, иначе эти гоблины разбивали бы свои машины в каждой гонке!','Эти гонки дают отличную возможность продемонстрировать нашу изобретательность!','Эти гонки дают отличную возможность продемонстрировать нашу изобретательность!','Я усовершенствовал матричный регулометр нашей машины. Теперь ее скорость должна возрасти как минимум в пятнадцать раз!','Я усовершенствовала матричный регулометр нашей машины. Теперь ее скорость должна возрасти как минимум в пятнадцать раз!','Да мой сын может собрать машину лучше, чем рухлядь этого гоблина!','Да мой сын может собрать машину лучше, чем рухлядь этого гоблина!','Мой технологический альманахотрон говорит, что мы выиграем у гоблинов на двадцать секунд больше, чем в прошлый раз!','Мой технологический альманахотрон говорит, что мы выиграем у гоблинов на двадцать секунд больше, чем в прошлый раз!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Правду говорят: дуракам везет, иначе эти гоблины разбивали бы свои машины в каждой гонке!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Правду говорят: дуракам везет, иначе эти гоблины разбивали бы свои машины в каждой гонке!',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Эти гонки дают отличную возможность продемонстрировать нашу изобретательность!',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Эти гонки дают отличную возможность продемонстрировать нашу изобретательность!',`text1_1_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Я усовершенствовал матричный регулометр нашей машины. Теперь ее скорость должна возрасти как минимум в пятнадцать раз!',`text2_0_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Я усовершенствовала матричный регулометр нашей машины. Теперь ее скорость должна возрасти как минимум в пятнадцать раз!',`text2_1_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Да мой сын может собрать машину лучше, чем рухлядь этого гоблина!',`text3_0_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','Да мой сын может собрать машину лучше, чем рухлядь этого гоблина!',`text3_1_loc8`), `text4_0_loc8`=IF(`text4_0_loc8` IS NULL OR `text4_0_loc8`='','Мой технологический альманахотрон говорит, что мы выиграем у гоблинов на двадцать секунд больше, чем в прошлый раз!',`text4_0_loc8`), `text4_1_loc8`=IF(`text4_1_loc8` IS NULL OR `text4_1_loc8`='','Мой технологический альманахотрон говорит, что мы выиграем у гоблинов на двадцать секунд больше, чем в прошлый раз!',`text4_1_loc8`);
