INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (781,'Тирт в последнее время сам не свой, и его помощник тоже.','Тирт в последнее время сам не свой, и его помощник тоже.','Джонсон? Я думаю, он где-то здесь…','Джонсон? Я думаю, он где-то здесь…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тирт в последнее время сам не свой, и его помощник тоже.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Тирт в последнее время сам не свой, и его помощник тоже.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Джонсон? Я думаю, он где-то здесь…',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Джонсон? Я думаю, он где-то здесь…',`text1_1_loc8`);
