INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (799,'Наконец-то! Кто-то пришел освободить меня из этой камеры!$b$bВерховный палач Хадрик послал нас собирать сведения о крепости, чтобы можно было создать план для окончательной победы над Аругалом.$b$bНо у старого волшебника припрятана куча трюков, так что нас обнаружил волшебный кристалл-хранитель. Меня бросили в эту тюрьму. Винсенту повезло меньше.$b$bЯ должен немедленно вернуться к Хадрику, из-за отчета. Но сначала я вскрою для тебя ворота во внутренний двор. Наверное, ты можешь попытать счастья в борьбе с прячущимися там врагами.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Наконец-то! Кто-то пришел освободить меня из этой камеры!$b$bВерховный палач Хадрик послал нас собирать сведения о крепости, чтобы можно было создать план для окончательной победы над Аругалом.$b$bНо у старого волшебника припрятана куча трюков, так что нас обнаружил волшебный кристалл-хранитель. Меня бросили в эту тюрьму. Винсенту повезло меньше.$b$bЯ должен немедленно вернуться к Хадрику, из-за отчета. Но сначала я вскрою для тебя ворота во внутренний двор. Наверное, ты можешь попытать счастья в борьбе с прячущимися там врагами.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (821,'Дай отдых усталым ногам.','Дай отдых усталым ногам.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Дай отдых усталым ногам.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Дай отдых усталым ногам.',`text0_1_loc8`);
