INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (822,'Мы рады вам, как ветру на равнинах.','Мы рады вам, как ветру на равнинах.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы рады вам, как ветру на равнинах.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мы рады вам, как ветру на равнинах.',`text0_1_loc8`);
