INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (823,'Налей-ка себе полную кружку и садись рядом. Бочонки полны и нам есть о чем рассказать друг другу.','Налей-ка себе полную кружку и садись рядом. Бочонки полны и нам есть о чем рассказать друг другу.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Налей-ка себе полную кружку и садись рядом. Бочонки полны и нам есть о чем рассказать друг другу.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Налей-ка себе полную кружку и садись рядом. Бочонки полны и нам есть о чем рассказать друг другу.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (824,'Ты выглядишь $gусталым:усталой;, и твой дух утомлен. Прошу тебя, отдохни у нас, и да пребудет с тобой целебная сила Элуны.','Ты выглядишь $gусталым:усталой;, и твой дух утомлен. Прошу тебя, отдохни у нас, и да пребудет с тобой целебная сила Элуны.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты выглядишь $gусталым:усталой;, и твой дух утомлен. Прошу тебя, отдохни у нас, и да пребудет с тобой целебная сила Элуны.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты выглядишь $gусталым:усталой;, и твой дух утомлен. Прошу тебя, отдохни у нас, и да пребудет с тобой целебная сила Элуны.',`text0_1_loc8`);
