INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (825,'Проходи, проходи. Только не садись слишком близко к печи. Сегодня она еще ни разу не взрывалась, но кто ее знает…','Проходи, проходи. Только не садись слишком близко к печи. Сегодня она еще ни разу не взрывалась, но кто ее знает…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Проходи, проходи. Только не садись слишком близко к печи. Сегодня она еще ни разу не взрывалась, но кто ее знает…',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Проходи, проходи. Только не садись слишком близко к печи. Сегодня она еще ни разу не взрывалась, но кто ее знает…',`text0_1_loc8`);
