INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (878,'Так, так… и кого там кошка принесла… Хм, чем же я могу помочь тебе, |3-6($c)?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Так, так… и кого там кошка принесла… Хм, чем же я могу помочь тебе, |3-6($c)?',`text0_1_loc8`);
