INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`,`text2_0_loc8`,`text2_1_loc8`) VALUES (879,'Укротителя грифонов можно найти на северо-восточном валу Аллеи Героев.','Укротителя грифонов можно найти на северо-восточном валу Аллеи Героев.','А, тебе нужен Дунгар Долгопив. У него одни из самых быстрых грифонов по эту сторону Каз Модана! Ты можешь найти его на валу в Торговом квартале.','А, тебе нужен Дунгар Долгопив. У него одни из самых быстрых грифонов по эту сторону Каз Модана! Ты можешь найти его на валу в Торговом квартале.','Хочешь прокатиться на грифоне, а? Дунгар своих птичек держит на валу в Торговом квартале. Только не забывай держаться покрепче!','Хочешь прокатиться на грифоне, а? Дунгар своих птичек держит на валу в Торговом квартале. Только не забывай держаться покрепче!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Укротителя грифонов можно найти на северо-восточном валу Аллеи Героев.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Укротителя грифонов можно найти на северо-восточном валу Аллеи Героев.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','А, тебе нужен Дунгар Долгопив. У него одни из самых быстрых грифонов по эту сторону Каз Модана! Ты можешь найти его на валу в Торговом квартале.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','А, тебе нужен Дунгар Долгопив. У него одни из самых быстрых грифонов по эту сторону Каз Модана! Ты можешь найти его на валу в Торговом квартале.',`text1_1_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Хочешь прокатиться на грифоне, а? Дунгар своих птичек держит на валу в Торговом квартале. Только не забывай держаться покрепче!',`text2_0_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Хочешь прокатиться на грифоне, а? Дунгар своих птичек держит на валу в Торговом квартале. Только не забывай держаться покрепче!',`text2_1_loc8`);
