INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (898,'Какой класс вас интересует?','Какой класс вас интересует?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Какой класс вас интересует?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Какой класс вас интересует?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (900,'Значит, тебе надо поговорить с Осборном. Он – наилучший учитель искусства незаметности в Штормграде. Ищи его в Старом городе.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Значит, тебе надо поговорить с Осборном. Он – наилучший учитель искусства незаметности в Штормграде. Ищи его в Старом городе.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`,`text2_0_loc8`,`text2_1_loc8`) VALUES (901,'Воинов можно встретить либо в таверне "Свинья и свисток", либо в казармах Старого города. И мой тебе совет: сначала сходи в таверну.','Воинов можно встретить либо в таверне "Свинья и свисток", либо в казармах Старого города. И мой тебе совет: сначала сходи в таверну.','Хотите подучиться, да? Я мог бы обучить вас куда лучше, чем любой воин Штормграда, но стражам это запрещено. Думаю, вам придется поискать наставника возле казарм или в таверне "Свинья и свисток" в Старом городе.','Хотите подучиться, да? Я могла бы обучить вас куда лучше, чем любой воин Штормграда, но стражам это запрещено. Думаю, вам придется поискать наставника возле казарм или в таверне "Свинья и свисток" в Старом городе.','Посмотрите в Старом городе – в казармах или таверне "Свинья и свисток". Если зайдете в таверну, обязательно попробуйте тамошнего пива. Дворфийский эль и рядом не валялся, точно говорю.','Посмотрите в Старом городе – в казармах или таверне "Свинья и свисток". Если зайдете в таверну, обязательно попробуйте тамошнего пива. Дворфийский эль и рядом не валялся, точно говорю.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Воинов можно встретить либо в таверне "Свинья и свисток", либо в казармах Старого города. И мой тебе совет: сначала сходи в таверну.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Воинов можно встретить либо в таверне "Свинья и свисток", либо в казармах Старого города. И мой тебе совет: сначала сходи в таверну.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Хотите подучиться, да? Я мог бы обучить вас куда лучше, чем любой воин Штормграда, но стражам это запрещено. Думаю, вам придется поискать наставника возле казарм или в таверне "Свинья и свисток" в Старом городе.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Хотите подучиться, да? Я могла бы обучить вас куда лучше, чем любой воин Штормграда, но стражам это запрещено. Думаю, вам придется поискать наставника возле казарм или в таверне "Свинья и свисток" в Старом городе.',`text1_1_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Посмотрите в Старом городе – в казармах или таверне "Свинья и свисток". Если зайдете в таверну, обязательно попробуйте тамошнего пива. Дворфийский эль и рядом не валялся, точно говорю.',`text2_0_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Посмотрите в Старом городе – в казармах или таверне "Свинья и свисток". Если зайдете в таверну, обязательно попробуйте тамошнего пива. Дворфийский эль и рядом не валялся, точно говорю.',`text2_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text1_0_loc8`,`text1_1_loc8`) VALUES (903,'Лорена – верховная жрица Штормграда. Ее можно найти в Храме Света на Соборной площади.','Лорена – верховная жрица Штормграда. Ее можно найти в Храме Света на Соборной площади.') ON DUPLICATE KEY UPDATE `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Лорена – верховная жрица Штормграда. Ее можно найти в Храме Света на Соборной площади.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Лорена – верховная жрица Штормграда. Ее можно найти в Храме Света на Соборной площади.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (905,'Торфин Камнещит проделал долгий путь из Стальгорна к нам, чтобы донести до нас свои знания об охоте. Если ты не против подышать дымным воздухом Квартала Дворфов, ты найдешь его в его доме в северо-восточной части района.','Торфин Камнещит проделал долгий путь из Стальгорна к нам, чтобы донести до нас свои знания об охоте. Если ты не против подышать дымным воздухом Квартала Дворфов, ты найдешь его в его доме в северо-восточной части района.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Торфин Камнещит проделал долгий путь из Стальгорна к нам, чтобы донести до нас свои знания об охоте. Если ты не против подышать дымным воздухом Квартала Дворфов, ты найдешь его в его доме в северо-восточной части района.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Торфин Камнещит проделал долгий путь из Стальгорна к нам, чтобы донести до нас свои знания об охоте. Если ты не против подышать дымным воздухом Квартала Дворфов, ты найдешь его в его доме в северо-восточной части района.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (907,'Что привело тебя в эту часть мира, $n?','Что привело тебя в эту часть мира, $n?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что привело тебя в эту часть мира, $n?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Что привело тебя в эту часть мира, $n?',`text0_1_loc8`);
