INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (908,'С каждым днем он становится все жирней и испорченней. К тому же эта туша здорово воняет. Он грязен, и я имею в виду не только то, что ему не мешало бы помыться.$B$BВпрочем, Хальфдан слишком много болтает. Откуда ты и чем я могу тебе помочь, |3-6($c)?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','С каждым днем он становится все жирней и испорченней. К тому же эта туша здорово воняет. Он грязен, и я имею в виду не только то, что ему не мешало бы помыться.$B$BВпрочем, Хальфдан слишком много болтает. Откуда ты и чем я могу тебе помочь, |3-6($c)?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (918,'Какая профессия вас интересует?','Какая профессия вас интересует?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Какая профессия вас интересует?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Какая профессия вас интересует?',`text0_1_loc8`);
