INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (920,'Терум Подземная Кузня – как раз тот дворф, который тебе нужен. Один из лучших местных кузнецов, скажу я тебе. Ищи его в центре Квартала Дворфов.','Терум Подземная Кузня – как раз тот дворф, который тебе нужен. Один из лучших местных кузнецов, скажу я тебе. Ищи его в центре Квартала Дворфов.','Ты что, $gсам:сама; не чуешь запах дыма из дворфийских горнов? Если хочешь учиться кузнечному делу, поищи Терума Подземную Кузню. Он сейчас в Районе гномов, это прямо на север от Соборной площади.','Ты что, $gсам:сама; не чуешь запах дыма из дворфийских горнов? Если хочешь учиться кузнечному делу, поищи Терума Подземную Кузню. Он сейчас в Районе гномов, это прямо на север от Соборной площади.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Терум Подземная Кузня – как раз тот дворф, который тебе нужен. Один из лучших местных кузнецов, скажу я тебе. Ищи его в центре Квартала Дворфов.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Терум Подземная Кузня – как раз тот дворф, который тебе нужен. Один из лучших местных кузнецов, скажу я тебе. Ищи его в центре Квартала Дворфов.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Ты что, $gсам:сама; не чуешь запах дыма из дворфийских горнов? Если хочешь учиться кузнечному делу, поищи Терума Подземную Кузню. Он сейчас в Районе гномов, это прямо на север от Соборной площади.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Ты что, $gсам:сама; не чуешь запах дыма из дворфийских горнов? Если хочешь учиться кузнечному делу, поищи Терума Подземную Кузню. Он сейчас в Районе гномов, это прямо на север от Соборной площади.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text1_0_loc8`,`text1_1_loc8`) VALUES (921,'В таверне "Свинья и свисток", что в Старом городе, есть превосходный повар. Я наблюдал, как он управляется с ножом. Между нами говоря, не думаю, что он всегда был поваром… Но если ты действительно хочешь учиться, обратись к нему.','В таверне "Свинья и свисток", что в Старом городе, есть превосходный повар. Я наблюдала, как он управляется с ножом. Между нами говоря, не думаю, что он всегда был поваром… Но если ты действительно хочешь учиться, обратись к нему.') ON DUPLICATE KEY UPDATE `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','В таверне "Свинья и свисток", что в Старом городе, есть превосходный повар. Я наблюдал, как он управляется с ножом. Между нами говоря, не думаю, что он всегда был поваром… Но если ты действительно хочешь учиться, обратись к нему.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','В таверне "Свинья и свисток", что в Старом городе, есть превосходный повар. Я наблюдала, как он управляется с ножом. Между нами говоря, не думаю, что он всегда был поваром… Но если ты действительно хочешь учиться, обратись к нему.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (922,'Инженерному делу в Штормграде обучает гном по имени Лилиам Шпиндель. Его можно найти в задней части Квартала Дворфов.','Инженерному делу в Штормграде обучает гном по имени Лилиам Шпиндель. Его можно найти в задней части Квартала Дворфов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Инженерному делу в Штормграде обучает гном по имени Лилиам Шпиндель. Его можно найти в задней части Квартала Дворфов.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Инженерному делу в Штормграде обучает гном по имени Лилиам Шпиндель. Его можно найти в задней части Квартала Дворфов.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (925,'Хочешь научиться кожевничеству? Тогда тебе нужен Саймон Дубильщик. Его можно найти в "Прочной шкуре", что в Старом городе.','Хочешь научиться кожевничеству? Тогда тебе нужен Саймон Дубильщик. Его можно найти в "Прочной шкуре", что в Старом городе.','Интересуешься кожей, да? Видимо, тебе нужно поговорить с Саймоном Дубильщиком из Старого города. У него тут лавка "Прочная шкура".','Интересуешься кожей, да? Видимо, тебе нужно поговорить с Саймоном Дубильщиком из Старого города. У него тут лавка "Прочная шкура".') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Хочешь научиться кожевничеству? Тогда тебе нужен Саймон Дубильщик. Его можно найти в "Прочной шкуре", что в Старом городе.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Хочешь научиться кожевничеству? Тогда тебе нужен Саймон Дубильщик. Его можно найти в "Прочной шкуре", что в Старом городе.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Интересуешься кожей, да? Видимо, тебе нужно поговорить с Саймоном Дубильщиком из Старого города. У него тут лавка "Прочная шкура".',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Интересуешься кожей, да? Видимо, тебе нужно поговорить с Саймоном Дубильщиком из Старого города. У него тут лавка "Прочная шкура".',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text1_0_loc8`,`text1_1_loc8`) VALUES (927,'В духе дворфов прислать специалиста по шахтам из Стальгорна, чтобы научить нас уму-разуму. Разве сложно взять кирку и долбить по камню? Ну, раз уж он здесь, он, наверное, как раз тот, кто тебе нужен. Его зовут Гельман, и проживает он в Квартале Дворфов.','В духе дворфов прислать специалиста по шахтам из Стальгорна, чтобы научить нас уму-разуму. Разве сложно взять кирку и долбить по камню? Ну, раз уж он здесь, он, наверное, как раз тот, кто тебе нужен. Его зовут Гельман, и проживает он в Квартале Дворфов.') ON DUPLICATE KEY UPDATE `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','В духе дворфов прислать специалиста по шахтам из Стальгорна, чтобы научить нас уму-разуму. Разве сложно взять кирку и долбить по камню? Ну, раз уж он здесь, он, наверное, как раз тот, кто тебе нужен. Его зовут Гельман, и проживает он в Квартале Дворфов.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','В духе дворфов прислать специалиста по шахтам из Стальгорна, чтобы научить нас уму-разуму. Разве сложно взять кирку и долбить по камню? Ну, раз уж он здесь, он, наверное, как раз тот, кто тебе нужен. Его зовут Гельман, и проживает он в Квартале Дворфов.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (928,'Если вы хотите научиться искусству снятия шкур, отправляйтесь в Старый город и загляните в "Прочную шкуру".','Если вы хотите научиться искусству снятия шкур, отправляйтесь в Старый город и загляните в "Прочную шкуру".') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если вы хотите научиться искусству снятия шкур, отправляйтесь в Старый город и загляните в "Прочную шкуру".',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Если вы хотите научиться искусству снятия шкур, отправляйтесь в Старый город и загляните в "Прочную шкуру".',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (930,'Смелый не хочет, чтобы Тирт знал, что он все еще на Мерцающей равнине, поэтому он превратил себя в цыпленка!$B$BЕсли найдешь Смелого, попробуй подозвать его. Быть может, он выйдет из укрытия.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Смелый не хочет, чтобы Тирт знал, что он все еще на Мерцающей равнине, поэтому он превратил себя в цыпленка!$B$BЕсли найдешь Смелого, попробуй подозвать его. Быть может, он выйдет из укрытия.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (931,'Надеюсь, вы готовы к работе.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Надеюсь, вы готовы к работе.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`,`text2_0_loc8`,`text2_1_loc8`,`text3_0_loc8`,`text3_1_loc8`) VALUES (932,'Добро пожаловать на гонки! Надеемся, вам здесь понравится. Да, и не ставьте все деньги на одного!','Добро пожаловать на гонки! Надеемся, вам здесь понравится. Да, и не ставьте все деньги на одного!','Приветик, |3-6($c)! Добро пожаловать на гонки Мерцающей равнины!','Приветик, |3-6($c)! Добро пожаловать на гонки Мерцающей равнины!','У кого самая быстрая машина? Да кто ж знает?!','У кого самая быстрая машина? Да кто ж знает?!','Гонщики-гоблины обладают огромной мощью, но гномы всегда прячут пару-другую хитростей в их автомобилях…','Гонщики-гоблины обладают огромной мощью, но гномы всегда прячут пару-другую хитростей в их автомобилях…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать на гонки! Надеемся, вам здесь понравится. Да, и не ставьте все деньги на одного!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Добро пожаловать на гонки! Надеемся, вам здесь понравится. Да, и не ставьте все деньги на одного!',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Приветик, |3-6($c)! Добро пожаловать на гонки Мерцающей равнины!',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Приветик, |3-6($c)! Добро пожаловать на гонки Мерцающей равнины!',`text1_1_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','У кого самая быстрая машина? Да кто ж знает?!',`text2_0_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','У кого самая быстрая машина? Да кто ж знает?!',`text2_1_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Гонщики-гоблины обладают огромной мощью, но гномы всегда прячут пару-другую хитростей в их автомобилях…',`text3_0_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','Гонщики-гоблины обладают огромной мощью, но гномы всегда прячут пару-другую хитростей в их автомобилях…',`text3_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (938,'Если мы хотим забрать эти земли себе, нам понадобятся места, где можно будет дать отдых своим уставшим от боя телам. Положи топор у огня и поведай нам о своих великих подвигах.','Если мы хотим забрать эти земли себе, нам понадобятся места, где можно будет дать отдых своим уставшим от боя телам. Положи топор у огня и поведай нам о своих великих подвигах.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если мы хотим забрать эти земли себе, нам понадобятся места, где можно будет дать отдых своим уставшим от боя телам. Положи топор у огня и поведай нам о своих великих подвигах.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Если мы хотим забрать эти земли себе, нам понадобятся места, где можно будет дать отдых своим уставшим от боя телам. Положи топор у огня и поведай нам о своих великих подвигах.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text1_0_loc8`,`text1_1_loc8`) VALUES (941,'А, ты ищешь Лукана Корделла. Он держит лавку на внешней стороне Квартала Магов, возле дороги к тюрьме.','А, ты ищешь Лукана Корделла. Он держит лавку на внешней стороне Квартала Магов, возле дороги к тюрьме.') ON DUPLICATE KEY UPDATE `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','А, ты ищешь Лукана Корделла. Он держит лавку на внешней стороне Квартала Магов, возле дороги к тюрьме.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','А, ты ищешь Лукана Корделла. Он держит лавку на внешней стороне Квартала Магов, возле дороги к тюрьме.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1038,'Орден Изувеченной Длани существовал до Тралла и будет существовать, когда Тралла давно не будет.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Орден Изувеченной Длани существовал до Тралла и будет существовать, когда Тралла давно не будет.',`text0_0_loc8`);
