INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1041,'Машина оживает при вашем прикосновении.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Машина оживает при вашем прикосновении.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1058,'Он пиво подает,$bИ мед он подает,$bС улыбкой до ушей, он к нам на зов идет.$bОн нам приют дает,$bИ так из года в год!$bУлыбка Джим – у нас здесь всяк его зовет.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Он пиво подает,$bИ мед он подает,$bС улыбкой до ушей, он к нам на зов идет.$bОн нам приют дает,$bИ так из года в год!$bУлыбка Джим – у нас здесь всяк его зовет.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1059,'Это экзотическое растение встречается только в одном районе Тельдрассила.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Это экзотическое растение встречается только в одном районе Тельдрассила.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1060,'Это растение выделяется из общей растительной массы Тельдрассила. От него исходит странное пурпурное сияние.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Это растение выделяется из общей растительной массы Тельдрассила. От него исходит странное пурпурное сияние.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1088,'Когда матрица созданий земли дестабилизируется, возможны два результата. Запускаю визуальное сопровождение презентации номер один.$B$BПервый вариант матрицы – дегенеративный продукт синтеза, здесь обозначенный распространенной номенклатурой "трогг". Этот вариант поддерживает силу и выносливость, сравнимую с той, что обладают создания земли, но его возможности когнитивной деятельности почти полностью испорчены. Сила воли и сильное чувство хитрости – единственные движущие силы в психике троггов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Когда матрица созданий земли дестабилизируется, возможны два результата. Запускаю визуальное сопровождение презентации номер один.$B$BПервый вариант матрицы – дегенеративный продукт синтеза, здесь обозначенный распространенной номенклатурой "трогг". Этот вариант поддерживает силу и выносливость, сравнимую с той, что обладают создания земли, но его возможности когнитивной деятельности почти полностью испорчены. Сила воли и сильное чувство хитрости – единственные движущие силы в психике троггов.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1090,'Инициация визуального представления номер два.$B$BВторой результативный вариант матрицы земельников обладает многими необходимыми элементами по сравнению со стандартной подземной матрицей. В стандартной номенклатуре этот вариант называется "дворфом".$B$BОт земельников этот вариант унаследовал силу и выносливость. В некоторых случаях дворфы даже превосходят когнитивные силы матрицы земельников, однако они не обладают физическими особенностями различных каменных образований ядра Азерота.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Инициация визуального представления номер два.$B$BВторой результативный вариант матрицы земельников обладает многими необходимыми элементами по сравнению со стандартной подземной матрицей. В стандартной номенклатуре этот вариант называется "дворфом".$B$BОт земельников этот вариант унаследовал силу и выносливость. В некоторых случаях дворфы даже превосходят когнитивные силы матрицы земельников, однако они не обладают физическими особенностями различных каменных образований ядра Азерота.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1091,'Данные, хранящиеся здесь, подтверждают твою догадку.$B$BДворфы сохранили некоторые свойства земельников Азерота. В то же время в результате аномалии развития тело дворфов приобрело органические компоненты.$B$BСледовательно, дворфы произошли от земельников, и ответ на твой вопрос – положительный.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Данные, хранящиеся здесь, подтверждают твою догадку.$B$BДворфы сохранили некоторые свойства земельников Азерота. В то же время в результате аномалии развития тело дворфов приобрело органические компоненты.$B$BСледовательно, дворфы произошли от земельников, и ответ на твой вопрос – положительный.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1120,'Грумнус живет в Стальгорне, в самой его середке. Отправляйся туда и ищи Великую Кузню – там его и найдешь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Грумнус живет в Стальгорне, в самой его середке. Отправляйся туда и ищи Великую Кузню – там его и найдешь.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1122,'Хочешь учиться у Боргуса? Ну, я скажу тебе, где его найти. Отправляйся через площадь на северо-запад от моей кузницы, а затем – по западной дороге. И найдешь его во втором здании справа.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Хочешь учиться у Боргуса? Ну, я скажу тебе, где его найти. Отправляйся через площадь на северо-запад от моей кузницы, а затем – по западной дороге. И найдешь его во втором здании справа.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1123,'Ты что, не видишь – я занят! Ну, если у тебя какой пустяк…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты что, не видишь – я занят! Ну, если у тебя какой пустяк…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1127,'Добро пожаловать в Великую Кузню, $gпарень:девушка;. Пусть снаружи холодно, зато у нас тут тепло и уютно. Бери молот, становись к наковальне и докажи мне, что ты $gдостоин:достойна; быть кузнецом Великой Кузни!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать в Великую Кузню, $gпарень:девушка;. Пусть снаружи холодно, зато у нас тут тепло и уютно. Бери молот, становись к наковальне и докажи мне, что ты $gдостоин:достойна; быть кузнецом Великой Кузни!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1132,'Какая-то зараза в этой башне. Я заболел, остальные работники Торговой Компании, кто в башне работает или рядом, тоже расхворались.$B$BВот только на прошлой неделе у нас двое охранников умерло, – а потом они вернулись, только уже бездушными зомби!$B$BЖизненная сила из меня вытекает. Я чувствую, как теряю власть над собой. Что-то меня зовет... Что-то мерзкое... *Физзл бьет сам себя по лицу.* Еще не время... Послушай... Мое место предполагает власть. Это место дает мне доступ к кое-какой секретной информации.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Какая-то зараза в этой башне. Я заболел, остальные работники Торговой Компании, кто в башне работает или рядом, тоже расхворались.$B$BВот только на прошлой неделе у нас двое охранников умерло, – а потом они вернулись, только уже бездушными зомби!$B$BЖизненная сила из меня вытекает. Я чувствую, как теряю власть над собой. Что-то меня зовет... Что-то мерзкое... *Физзл бьет сам себя по лицу.* Еще не время... Послушай... Мое место предполагает власть. Это место дает мне доступ к кое-какой секретной информации.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1133,'Ты что, $gспятил:спятила;? Это ж не оружие, а кухонный нож. Новичками не занимаюсь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты что, $gспятил:спятила;? Это ж не оружие, а кухонный нож. Новичками не занимаюсь.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1135,'И ради этого ты меня $gпобеспокоил:побеспокоила;? Да если ты дохлого кролика на спину нацепишь и побежишь по логову троллей – и то больше пользы будет, чем от хлама, который ты носишь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','И ради этого ты меня $gпобеспокоил:побеспокоила;? Да если ты дохлого кролика на спину нацепишь и побежишь по логову троллей – и то больше пользы будет, чем от хлама, который ты носишь.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1138,'Месяцев пять назад подразделению Торговой Компании, работающему в Тернистой долине, попал в руки особый яд от одного подозрительного торговца из Пиратской Бухты по имени Шиззи Пузырикс. Шипучка, похоже, этот яд украл у Занзила!$B$BДа, Занзил Отверженный – тролль, изгнанный из собственного племени за "опыты" с некромантией.$B$BКонечно же, едва заполучив яд, они принялись испытывать его друг на друге. Результаты оказались катастрофическими.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Месяцев пять назад подразделению Торговой Компании, работающему в Тернистой долине, попал в руки особый яд от одного подозрительного торговца из Пиратской Бухты по имени Шиззи Пузырикс. Шипучка, похоже, этот яд украл у Занзила!$B$BДа, Занзил Отверженный – тролль, изгнанный из собственного племени за "опыты" с некромантией.$B$BКонечно же, едва заполучив яд, они принялись испытывать его друг на друге. Результаты оказались катастрофическими.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1158,'В итоге вмешался старший штейгер Пузик Нервотреп. Он забрал излишки яда в свою башню посреди Нефтяного болота, чтобы изучить изменчивую природу токсинов. В конце концов было принято решение передать секрет этой отравы Братству Справедливости – в обмен на большие запасы уже испытанного и проверенного яда.$B$BДальнейшую работу по изменению химических свойств смеси Занзила проводил Клейвен Мортвейк из Братства Справедливости.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','В итоге вмешался старший штейгер Пузик Нервотреп. Он забрал излишки яда в свою башню посреди Нефтяного болота, чтобы изучить изменчивую природу токсинов. В конце концов было принято решение передать секрет этой отравы Братству Справедливости – в обмен на большие запасы уже испытанного и проверенного яда.$B$BДальнейшую работу по изменению химических свойств смеси Занзила проводил Клейвен Мортвейк из Братства Справедливости.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (1202,'Надеюсь, ты прерываешь меня не зря. У меня тут очень важная работа.','Надеюсь, ты прерываешь меня не зря. У меня тут очень важная работа.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Надеюсь, ты прерываешь меня не зря. У меня тут очень важная работа.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Надеюсь, ты прерываешь меня не зря. У меня тут очень важная работа.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (1203,'Очередной травник, хмм. Сомневаюсь, что у тебя такой же великолепный навык, как и у меня, поэтому, может быть, я смогу обучить тебя парочке приемчиков.','Очередной травник, хмм. Сомневаюсь, что у тебя такой же великолепный навык, как и у меня, поэтому, может быть, я смогу обучить тебя парочке приемчиков.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Очередной травник, хмм. Сомневаюсь, что у тебя такой же великолепный навык, как и у меня, поэтому, может быть, я смогу обучить тебя парочке приемчиков.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Очередной травник, хмм. Сомневаюсь, что у тебя такой же великолепный навык, как и у меня, поэтому, может быть, я смогу обучить тебя парочке приемчиков.',`text0_1_loc8`);
