INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (1206,'Добро пожаловать в Штормград. Мы долго поднимали наш город из руин – но оно того стоило. Вы просто так приехали или по делу?','Добро пожаловать в Штормград. Мы долго поднимали наш город из руин – но оно того стоило. Вы просто так приехали или по делу?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать в Штормград. Мы долго поднимали наш город из руин – но оно того стоило. Вы просто так приехали или по делу?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Добро пожаловать в Штормград. Мы долго поднимали наш город из руин – но оно того стоило. Вы просто так приехали или по делу?',`text0_1_loc8`);
