INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (1207,'Тут мало кто интересуется кулинарией, но я могу показать вам кое-что из того, что умею.','Тут мало кто интересуется кулинарией, но я могу показать вам кое-что из того, что умею.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тут мало кто интересуется кулинарией, но я могу показать вам кое-что из того, что умею.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Тут мало кто интересуется кулинарией, но я могу показать вам кое-что из того, что умею.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (1208,'Думаешь, у меня есть время и силы нянчиться с каждым путешественником, который забредает ко мне в дом? Говори, что тебе нужно – и побыстрее.','Думаешь, у меня есть время и силы нянчиться с каждым путешественником, который забредает ко мне в дом? Говори, что тебе нужно – и побыстрее.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Думаешь, у меня есть время и силы нянчиться с каждым путешественником, который забредает ко мне в дом? Говори, что тебе нужно – и побыстрее.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Думаешь, у меня есть время и силы нянчиться с каждым путешественником, который забредает ко мне в дом? Говори, что тебе нужно – и побыстрее.',`text0_1_loc8`);
