INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (1210,'Тут мало кто интересуется снятием шкур. Если вы хотите, я могу вас кое-чему научить.','Тут мало кто интересуется снятием шкур. Если вы хотите, я могу вас кое-чему научить.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тут мало кто интересуется снятием шкур. Если вы хотите, я могу вас кое-чему научить.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Тут мало кто интересуется снятием шкур. Если вы хотите, я могу вас кое-чему научить.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (1215,'Может, большие войны и остались в прошлом, но это не повод забывать наши воинские навыки!','Может, большие войны и остались в прошлом, но это не повод забывать наши воинские навыки!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Может, большие войны и остались в прошлом, но это не повод забывать наши воинские навыки!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Может, большие войны и остались в прошлом, но это не повод забывать наши воинские навыки!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (1216,'Штормград – это оплот всей людской расы, хранимый несгибаемой волей и острым клинком.','Штормград – это оплот всей людской расы, хранимый несгибаемой волей и острым клинком.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Штормград – это оплот всей людской расы, хранимый несгибаемой волей и острым клинком.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Штормград – это оплот всей людской расы, хранимый несгибаемой волей и острым клинком.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (1217,'Приветствую. Ты желаешь выучиться искусству сражения?','Приветствую. Ты желаешь выучиться искусству сражения?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приветствую. Ты желаешь выучиться искусству сражения?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Приветствую. Ты желаешь выучиться искусству сражения?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (1218,'Чем больше ты учишься – тем острее осознаешь свое невежество.','Чем больше ты учишься – тем острее осознаешь свое невежество.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Чем больше ты учишься – тем острее осознаешь свое невежество.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Чем больше ты учишься – тем острее осознаешь свое невежество.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (1219,'Предназначение воина – защищать. Как защищаем мы в бою своих товарищей, так должны защищать и интересы Отрекшихся.','Предназначение воина – защищать. Как защищаем мы в бою наших соотечественников, так должны защищать и интересы Отрекшихся.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Предназначение воина – защищать. Как защищаем мы в бою своих товарищей, так должны защищать и интересы Отрекшихся.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Предназначение воина – защищать. Как защищаем мы в бою наших соотечественников, так должны защищать и интересы Отрекшихся.',`text0_1_loc8`);
