INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (1220,'О, коллега-врач. С радостью научу вас всему, что может пригодиться в поездках.','О, коллега-врач. С радостью научу вас всему, что может пригодиться в поездках.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','О, коллега-врач. С радостью научу вас всему, что может пригодиться в поездках.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','О, коллега-врач. С радостью научу вас всему, что может пригодиться в поездках.',`text0_1_loc8`);
