INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (1225,'Я из Стальгорна, помогаю здесь с ремонтом. Но если я смогу передать тебе свои знания, то, может быть, оставлю дело на тебя и вернусь домой.','Я из Стальгорна, помогаю здесь с ремонтом. Но если я смогу передать тебе свои знания, то, может быть, оставлю дело на тебя и вернусь домой.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я из Стальгорна, помогаю здесь с ремонтом. Но если я смогу передать тебе свои знания, то, может быть, оставлю дело на тебя и вернусь домой.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я из Стальгорна, помогаю здесь с ремонтом. Но если я смогу передать тебе свои знания, то, может быть, оставлю дело на тебя и вернусь домой.',`text0_1_loc8`);
