INSERT INTO `locales_npc_text` (`id`,`text1_0_loc8`,`text1_1_loc8`) VALUES (1231,'Я продаю лучшие чародейские товары, созданные ремесленниками и магами Штормграда.','Я продаю лучшие чародейские товары, созданные ремесленниками и магами Штормграда.') ON DUPLICATE KEY UPDATE `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Я продаю лучшие чародейские товары, созданные ремесленниками и магами Штормграда.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Я продаю лучшие чародейские товары, созданные ремесленниками и магами Штормграда.',`text1_1_loc8`);
