INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (1233,'Сделано лучшими мастерами всего Тельдрассила, на руках принесено из Калимдора в Азерот – в знак крепнущего союза между народом Великого Древа и здешними людьми. Если тебе чего-то нужно – только спроси.','Сделано лучшими мастерами всего Тельдрассила, на руках принесено из Калимдора в Азерот – в знак крепнущего союза между народом Великого Древа и здешними людьми. Если тебе чего-то нужно – только спроси.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Сделано лучшими мастерами всего Тельдрассила, на руках принесено из Калимдора в Азерот – в знак крепнущего союза между народом Великого Древа и здешними людьми. Если тебе чего-то нужно – только спроси.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Сделано лучшими мастерами всего Тельдрассила, на руках принесено из Калимдора в Азерот – в знак крепнущего союза между народом Великого Древа и здешними людьми. Если тебе чего-то нужно – только спроси.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (1234,'С тех пор как пал Даларан и был разрушен Кель\'Талас, такие товары почти не встречаются. Но Лукану Корделлу и еще нескольким торговцам все еще удается выполнять наши заказы.','С тех пор как пал Даларан и был разрушен Кель\'Талас, такие товары почти не встречаются. Но Лукану Корделлу и еще нескольким торговцам все еще удается выполнять наши заказы.','Я продаю лучшие чародейские товары, созданные ремесленниками и магами Штормграда.','Я продаю лучшие чародейские товары, созданные ремесленниками и магами Штормграда.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','С тех пор как пал Даларан и был разрушен Кель\'Талас, такие товары почти не встречаются. Но Лукану Корделлу и еще нескольким торговцам все еще удается выполнять наши заказы.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','С тех пор как пал Даларан и был разрушен Кель\'Талас, такие товары почти не встречаются. Но Лукану Корделлу и еще нескольким торговцам все еще удается выполнять наши заказы.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Я продаю лучшие чародейские товары, созданные ремесленниками и магами Штормграда.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Я продаю лучшие чародейские товары, созданные ремесленниками и магами Штормграда.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text1_0_loc8`,`text1_1_loc8`,`text2_0_loc8`,`text2_1_loc8`) VALUES (1237,'Лучшие цены в Штормграде, нигде дешевле не найдете. Так чем же я могу помочь?','Лучшие цены в Штормграде, нигде дешевле не найдете. Так чем же я могу помочь?','Ты просто разглядываешь товары, или ищешь что-то особенное?','Ты просто разглядываешь товары, или ищешь что-то особенное?') ON DUPLICATE KEY UPDATE `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Лучшие цены в Штормграде, нигде дешевле не найдете. Так чем же я могу помочь?',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Лучшие цены в Штормграде, нигде дешевле не найдете. Так чем же я могу помочь?',`text1_1_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Ты просто разглядываешь товары, или ищешь что-то особенное?',`text2_0_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Ты просто разглядываешь товары, или ищешь что-то особенное?',`text2_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (1240,'Я продаю только самое лучшее обмундирование, проверенное и подогнанное. Но цены у меня фиксированные. Хочешь торговаться – иди к гоблинам.','Я продаю только самое лучшее обмундирование, проверенное и подогнанное. Но цены у меня фиксированные. Хочешь торговаться – иди к гоблинам.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я продаю только самое лучшее обмундирование, проверенное и подогнанное. Но цены у меня фиксированные. Хочешь торговаться – иди к гоблинам.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я продаю только самое лучшее обмундирование, проверенное и подогнанное. Но цены у меня фиксированные. Хочешь торговаться – иди к гоблинам.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (1241,'Да хранит тебя Свет в твоих странствиях. Смотри, выбирай. Если понадоблюсь – я рядом.','Да хранит тебя Свет в твоих странствиях. Смотри, выбирай. Если понадоблюсь – я рядом.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да хранит тебя Свет в твоих странствиях. Смотри, выбирай. Если понадоблюсь – я рядом.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Да хранит тебя Свет в твоих странствиях. Смотри, выбирай. Если понадоблюсь – я рядом.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (1242,'Да хранит тебя свет в твоих странствиях. Если тебе понадобится помощь, я буду ждать здесь.','Да хранит тебя свет в твоих странствиях. Если тебе понадобится помощь, я буду ждать здесь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да хранит тебя свет в твоих странствиях. Если тебе понадобится помощь, я буду ждать здесь.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Да хранит тебя свет в твоих странствиях. Если тебе понадобится помощь, я буду ждать здесь.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (1243,'Не позволяй людям с базара задурить тебе голову, $gпарень:девица; – с построенным этими гномами туннелем перевозить грузы из Стальгорна куда проще, чем тебе могло бы казаться. Если они попытаются прикрутить к цене налоги за ввоз, просто скажи им, что лучше будешь у меня снаряжение покупать.','Не позволяй людям с базара задурить тебе голову, $gпарень:девица; – с построенным этими гномами туннелем перевозить грузы из Стальгорна куда проще, чем тебе могло бы казаться. Если они попытаются прикрутить к цене налоги за ввоз, просто скажи им, что лучше будешь у меня снаряжение покупать.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не позволяй людям с базара задурить тебе голову, $gпарень:девица; – с построенным этими гномами туннелем перевозить грузы из Стальгорна куда проще, чем тебе могло бы казаться. Если они попытаются прикрутить к цене налоги за ввоз, просто скажи им, что лучше будешь у меня снаряжение покупать.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Не позволяй людям с базара задурить тебе голову, $gпарень:девица; – с построенным этими гномами туннелем перевозить грузы из Стальгорна куда проще, чем тебе могло бы казаться. Если они попытаются прикрутить к цене налоги за ввоз, просто скажи им, что лучше будешь у меня снаряжение покупать.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (1249,'Если вставить панель А в гнездо Б, то, разумеется, оно РВАНЕТ! Вот, дайте я покажу вам, что у меня есть, а потом вы сможете спросить Лилиама о том, состыковать эти предметы, чтобы они не взорвались.','Если вставить панель А в гнездо Б, то, разумеется, оно РВАНЕТ! Вот, дайте я покажу вам, что у меня есть, а потом вы сможете спросить Лилиама о том, состыковать эти предметы, чтобы они не взорвались.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если вставить панель А в гнездо Б, то, разумеется, оно РВАНЕТ! Вот, дайте я покажу вам, что у меня есть, а потом вы сможете спросить Лилиама о том, состыковать эти предметы, чтобы они не взорвались.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Если вставить панель А в гнездо Б, то, разумеется, оно РВАНЕТ! Вот, дайте я покажу вам, что у меня есть, а потом вы сможете спросить Лилиама о том, состыковать эти предметы, чтобы они не взорвались.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (1250,'Никто и никогда ничего отсюда не крал. Такого не случалось за всю историю… всей истории!','Никто и никогда ничего отсюда не крал. Такого не случалось за всю историю… всей истории!','Добро пожаловать в банк Штормграда. У нас вы можете производить операции со счетом или пользоваться сейфом для хранения ценных предметов. У вас уже есть счет в нашем банке, $gсударь:сударыня;?','Добро пожаловать в банк Штормграда. У нас вы можете производить операции со счетом или пользоваться сейфом для хранения ценных предметов. У вас уже есть счет в нашем банке, $gсударь:сударыня;?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Никто и никогда ничего отсюда не крал. Такого не случалось за всю историю… всей истории!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Никто и никогда ничего отсюда не крал. Такого не случалось за всю историю… всей истории!',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Добро пожаловать в банк Штормграда. У нас вы можете производить операции со счетом или пользоваться сейфом для хранения ценных предметов. У вас уже есть счет в нашем банке, $gсударь:сударыня;?',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Добро пожаловать в банк Штормграда. У нас вы можете производить операции со счетом или пользоваться сейфом для хранения ценных предметов. У вас уже есть счет в нашем банке, $gсударь:сударыня;?',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (1253,'Послушай мой совет: не садись рядом с тенью.','Послушай мой совет: не садись рядом с тенью.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Послушай мой совет: не садись рядом с тенью.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Послушай мой совет: не садись рядом с тенью.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (1254,'Добро пожаловать в "Свинью и свисток"! Возьми кружечку, $gдруг:подруга;, да присаживайся, – чем нас больше, тем веселее!','Добро пожаловать в "Свинью и свисток"! Возьми кружечку, $gдруг:подруга;, да присаживайся – чем нас больше, тем веселее!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать в "Свинью и свисток"! Возьми кружечку, $gдруг:подруга;, да присаживайся, – чем нас больше, тем веселее!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Добро пожаловать в "Свинью и свисток"! Возьми кружечку, $gдруг:подруга;, да присаживайся – чем нас больше, тем веселее!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (1255,'Мы – единственные поставщики живых цветов во всем Штормграде. У нас есть прекрасные цветы на все случаи жизни.','Мы – единственные поставщики живых цветов во всем Штормграде. У нас есть прекрасные цветы на все случаи жизни.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы – единственные поставщики живых цветов во всем Штормграде. У нас есть прекрасные цветы на все случаи жизни.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мы – единственные поставщики живых цветов во всем Штормграде. У нас есть прекрасные цветы на все случаи жизни.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (1256,'Куда ты хочешь отправиться, $gюноша:девица;? Всего за несколько монет мои грифоны могут доставить тебя туда быстрее, чем самая быстрая лошадь.','Куда ты хочешь отправиться, $gюноша:девица;? Всего за несколько монет мои грифоны могут доставить тебя туда быстрее, чем самая быстрая лошадь.','Эти великолепные животные могут добраться в такие места, куда невозможно дойти пешком. Вы быстро долетите в нужное место, а если повезет, увидите кое-что интересное с высоты.','Эти великолепные животные могут добраться в такие места, куда невозможно дойти пешком. Вы быстро долетите в нужное место, а если повезет, увидите кое-что интересное с высоты.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Куда ты хочешь отправиться, $gюноша:девица;? Всего за несколько монет мои грифоны могут доставить тебя туда быстрее, чем самая быстрая лошадь.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Куда ты хочешь отправиться, $gюноша:девица;? Всего за несколько монет мои грифоны могут доставить тебя туда быстрее, чем самая быстрая лошадь.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Эти великолепные животные могут добраться в такие места, куда невозможно дойти пешком. Вы быстро долетите в нужное место, а если повезет, увидите кое-что интересное с высоты.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Эти великолепные животные могут добраться в такие места, куда невозможно дойти пешком. Вы быстро долетите в нужное место, а если повезет, увидите кое-что интересное с высоты.',`text1_1_loc8`);
