INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1261,'Уж надеюсь, ты не для того $gзашел:зашла; в Великую Кузню, чтобы просто погреться. Рассказывай, что тебе от меня нужно.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Уж надеюсь, ты не для того $gзашел:зашла; в Великую Кузню, чтобы просто погреться. Рассказывай, что тебе от меня нужно.',`text0_0_loc8`);
