INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1262,'Ты $gпохож:похожа; на кузнеца. Под ногтями копоть, в костях сталь. Да, в твоих жилах течет кровь настоящих кузнецов… Стало быть, учиться $gпришел:пришла;? Ну что ж, $gпарень:девица;, бери молоток. Посмотрим, чему я сумею тебя выучить.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты $gпохож:похожа; на кузнеца. Под ногтями копоть, в костях сталь. Да, в твоих жилах течет кровь настоящих кузнецов… Стало быть, учиться $gпришел:пришла;? Ну что ж, $gпарень:девица;, бери молоток. Посмотрим, чему я сумею тебя выучить.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (1272,'Что ты ищешь?','Что ты ищешь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что ты ищешь?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Что ты ищешь?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`) VALUES (1291,'Это вам надо Крумна разыскать. Он обычно бывает на Нижнем уступе, возле центра информации Громового Утеса.','Это вам надо Крумна разыскать. Он обычно бывает на Нижнем уступе, возле центра информации Громового Утеса.','Объединение родственных душ – огромная сила. Крумн поможет тебе обрести ее. Ищи его в информационном центре Громового Утеса. Это на нижнем уступе, рядом с подъемниками.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Это вам надо Крумна разыскать. Он обычно бывает на Нижнем уступе, возле центра информации Громового Утеса.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Это вам надо Крумна разыскать. Он обычно бывает на Нижнем уступе, возле центра информации Громового Утеса.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Объединение родственных душ – огромная сила. Крумн поможет тебе обрести ее. Ищи его в информационном центре Громового Утеса. Это на нижнем уступе, рядом с подъемниками.',`text1_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (1292,'Банк Громового Утеса можно найти на меньшем холме.','Банк Громового Утеса можно найти на меньшем холме.','Свои пожитки можно отдать на хранение в банк Громового Утеса на нижнем уступе.','Свои пожитки можно отдать на хранение в банк Громового Утеса на нижнем уступе.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Банк Громового Утеса можно найти на меньшем холме.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Банк Громового Утеса можно найти на меньшем холме.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Свои пожитки можно отдать на хранение в банк Громового Утеса на нижнем уступе.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Свои пожитки можно отдать на хранение в банк Громового Утеса на нижнем уступе.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text1_0_loc8`,`text1_1_loc8`) VALUES (1293,'А, хочешь парить в небе среди огромных птиц… Разыщи Тала в верхней части гнезда Крыла Ветра. Он доставит тебя куда нужно.','А, хочешь парить в небе среди огромных птиц… Разыщи Тала в верхней части гнезда Крыла Ветра. Он доставит тебя куда нужно.') ON DUPLICATE KEY UPDATE `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','А, хочешь парить в небе среди огромных птиц… Разыщи Тала в верхней части гнезда Крыла Ветра. Он доставит тебя куда нужно.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','А, хочешь парить в небе среди огромных птиц… Разыщи Тала в верхней части гнезда Крыла Ветра. Он доставит тебя куда нужно.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (1298,'Зал Духов – вот дом наших шаманов. Его ты найдешь на уступе Духов. И да хранят тебя наши предки.','Зал Духов – вот дом наших шаманов. Его ты найдешь на уступе Духов. И да хранят тебя наши предки.','Мать-Земля зовет – ты отвечаешь. Ищи зал Духов на уступе Духов.','Мать-Земля зовет – ты отвечаешь. Ищи зал Духов на уступе Духов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Зал Духов – вот дом наших шаманов. Его ты найдешь на уступе Духов. И да хранят тебя наши предки.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Зал Духов – вот дом наших шаманов. Его ты найдешь на уступе Духов. И да хранят тебя наши предки.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Мать-Земля зовет – ты отвечаешь. Ищи зал Духов на уступе Духов.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Мать-Земля зовет – ты отвечаешь. Ищи зал Духов на уступе Духов.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (1301,'Какая профессия?','Какая профессия?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Какая профессия?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Какая профессия?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1302,'Невероятно… Я слышал, что орки считают запах людей тошнотворным, а люди не переносят запах орков… Но для меня все расы этого мира пахнут одинаково – омерзительной, гнилой жадностью.$B$BТы сомневаешься в моих словах? Разве ты $gсам:сама; не видишь, что всей твоей жизнью управляет жадность? Она определяет каждое твое решение.$B$BДа будет так. Жадность выгнала меня из моего дома, она же и вернет меня туда.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Невероятно… Я слышал, что орки считают запах людей тошнотворным, а люди не переносят запах орков… Но для меня все расы этого мира пахнут одинаково – омерзительной, гнилой жадностью.$B$BТы сомневаешься в моих словах? Разве ты $gсам:сама; не видишь, что всей твоей жизнью управляет жадность? Она определяет каждое твое решение.$B$BДа будет так. Жадность выгнала меня из моего дома, она же и вернет меня туда.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1303,'Значит, ты $gвернулся:вернулась;, чтобы помочь Кум\'ише, |3-6($r)? Не бойся, та боль, что ты чувствуешь внутри, – всего лишь признак того, что ты утрачиваешь силу воли.$B$BНо она тебе тут и не понадобится. А вот безделушки, которые я тебе дам в награду, понадобятся точно. Но сначала принеси мне нужную вещь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Значит, ты $gвернулся:вернулась;, чтобы помочь Кум\'ише, |3-6($r)? Не бойся, та боль, что ты чувствуешь внутри, – всего лишь признак того, что ты утрачиваешь силу воли.$B$BНо она тебе тут и не понадобится. А вот безделушки, которые я тебе дам в награду, понадобятся точно. Но сначала принеси мне нужную вещь.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (1332,'Тогда отправляйся к "Лаборатории Бены" на среднем холме и поговори с самой Беной. Она сможет научить тебя искусству приготовления зелий.','Тогда отправляйся к "Лаборатории Бены" на среднем холме и поговори с самой Беной. Она сможет научить тебя искусству приготовления зелий.','Дары природы при должной обработке могут быть очень полезны. Чтобы продолжить обучение, навести Бену в ее лавке на Среднем уступе.','Дары природы при должной обработке могут быть очень полезны. Чтобы продолжить обучение, навести Бену в ее лавке на Среднем уступе.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тогда отправляйся к "Лаборатории Бены" на среднем холме и поговори с самой Беной. Она сможет научить тебя искусству приготовления зелий.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Тогда отправляйся к "Лаборатории Бены" на среднем холме и поговори с самой Беной. Она сможет научить тебя искусству приготовления зелий.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Дары природы при должной обработке могут быть очень полезны. Чтобы продолжить обучение, навести Бену в ее лавке на Среднем уступе.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Дары природы при должной обработке могут быть очень полезны. Чтобы продолжить обучение, навести Бену в ее лавке на Среднем уступе.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (1333,'Хочешь научиться работать с молотом и наковальней, а? Карн Каменное Копыто может тебе показать, как это делается. Его кузница находится на нижнем круге у пруда.','Хочешь научиться работать с молотом и наковальней, а? Карн Каменное Копыто может тебе показать, как это делается. Его кузница находится на нижнем круге у пруда.','Металл, как и все в этом мире, должен использоваться в гармонии с природой. У Карна Каменного Копыта есть кузница у пруда на нижнем уступе. Прислушайся к его мудрости.','Металл, как и все в этом мире, должен использоваться в гармонии с природой. Карн Каменное Копыто держит кузницу у пруда на нижнем уступе. Прислушайся к его мудрости.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Хочешь научиться работать с молотом и наковальней, а? Карн Каменное Копыто может тебе показать, как это делается. Его кузница находится на нижнем круге у пруда.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Хочешь научиться работать с молотом и наковальней, а? Карн Каменное Копыто может тебе показать, как это делается. Его кузница находится на нижнем круге у пруда.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Металл, как и все в этом мире, должен использоваться в гармонии с природой. У Карна Каменного Копыта есть кузница у пруда на нижнем уступе. Прислушайся к его мудрости.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Металл, как и все в этом мире, должен использоваться в гармонии с природой. Карн Каменное Копыто держит кузницу у пруда на нижнем уступе. Прислушайся к его мудрости.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (1336,'Умение оказывать первую помощь никогда не помешает. Сколько раз оно спасало мою собственную жизнь! Наведайтесь в "Духовное исцеление" на Уступе Духов. Панд Камневяз обучит вас всему необходимому.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Умение оказывать первую помощь никогда не помешает. Сколько раз оно спасало мою собственную жизнь! Наведайтесь в "Духовное исцеление" на Уступе Духов. Панд Камневяз обучит вас всему необходимому.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text1_0_loc8`) VALUES (1337,'Ках Вестник Туманов из "Снастей и наживки с горных вершин" на верхнем уступе подскажет вам, как обрести внутренний мир и спокойствие, ловя рыбу на обед.') ON DUPLICATE KEY UPDATE `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Ках Вестник Туманов из "Снастей и наживки с горных вершин" на верхнем уступе подскажет вам, как обрести внутренний мир и спокойствие, ловя рыбу на обед.',`text1_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (1339,'Вам нужна Уна. Ее можно найти в оружейных Громового Утеса на Среднем уступе.','Вам нужна Уна. Ее можно найти в оружейных Громового Утеса на Среднем уступе.','Определенно, есть что-то приятное в том, что шкура вашего врага защищает вас самих. Чтобы научиться лучше работать с кожей, обратитесь к Уне из "Оружейников Громового Утеса". Это на среднем уступе.','Определенно, есть что-то приятное в том, что шкура вашего врага защищает вас самих. Чтобы научиться лучше работать с кожей, обратитесь к Уне из "Оружейников Громового Утеса". Это на среднем уступе.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вам нужна Уна. Ее можно найти в оружейных Громового Утеса на Среднем уступе.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Вам нужна Уна. Ее можно найти в оружейных Громового Утеса на Среднем уступе.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Определенно, есть что-то приятное в том, что шкура вашего врага защищает вас самих. Чтобы научиться лучше работать с кожей, обратитесь к Уне из "Оружейников Громового Утеса". Это на среднем уступе.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Определенно, есть что-то приятное в том, что шкура вашего врага защищает вас самих. Чтобы научиться лучше работать с кожей, обратитесь к Уне из "Оружейников Громового Утеса". Это на среднем уступе.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (1341,'Мало кто работает с тканью лучше нашей Тепы. Ищи ее в "Оружейниках Громового Утеса" на среднем уступе.','Мало кто работает с тканью лучше нашей Тепы. Ищи ее в "Оружейниках Громового Утеса" на среднем уступе.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мало кто работает с тканью лучше нашей Тепы. Ищи ее в "Оружейниках Громового Утеса" на среднем уступе.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мало кто работает с тканью лучше нашей Тепы. Ищи ее в "Оружейниках Громового Утеса" на среднем уступе.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text1_0_loc8`,`text1_1_loc8`) VALUES (1343,'Чем меньше мы оставляем мусора и отходов, тем ближе мы к Матери-Земле. Муранта укажет тебе путь. Ты найдешь ее у входа в оружейные Громового Утеса на среднем уступе.','Чем меньше мы оставляем мусора и отходов, тем ближе мы к Матери-Земле. Муранта укажет тебе путь. Ты найдешь ее у входа в оружейные Громового Утеса на среднем уступе.') ON DUPLICATE KEY UPDATE `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Чем меньше мы оставляем мусора и отходов, тем ближе мы к Матери-Земле. Муранта укажет тебе путь. Ты найдешь ее у входа в оружейные Громового Утеса на среднем уступе.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Чем меньше мы оставляем мусора и отходов, тем ближе мы к Матери-Земле. Муранта укажет тебе путь. Ты найдешь ее у входа в оружейные Громового Утеса на среднем уступе.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1411,'Сожаление. Это все, что у меня осталось. Одно неверное решение повлекло за собой череду ужасных последствий. Если бы только я дождался тех приказов! Может быть, из них бы мы узнали больше об опасностях этой проклятой земли? Может, нас направили бы в другое место? В итоге во всем виноват я. Все это из-за меня.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Сожаление. Это все, что у меня осталось. Одно неверное решение повлекло за собой череду ужасных последствий. Если бы только я дождался тех приказов! Может быть, из них бы мы узнали больше об опасностях этой проклятой земли? Может, нас направили бы в другое место? В итоге во всем виноват я. Все это из-за меня.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1451,'Поверишь ли ты, что в самый черный свой час на вершине всей моей жизни я потерпел неудачу?$B$BКогда я бежал от бессмысленной, всеразрушающей силы, затопившей нас, то слышал только крики моих солдат и громкий стук собственного сердца.$B$BВскоре после того я вернулся в Выжженные земли, надеясь спасти своих людей и восстановить свою честь. Вместо этого меня схватили и забили насмерть.$B$BТо, что я обнаружил во время допроса и последовавшей за ним пытки, было чудовищно.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Поверишь ли ты, что в самый черный свой час на вершине всей моей жизни я потерпел неудачу?$B$BКогда я бежал от бессмысленной, всеразрушающей силы, затопившей нас, то слышал только крики моих солдат и громкий стук собственного сердца.$B$BВскоре после того я вернулся в Выжженные земли, надеясь спасти своих людей и восстановить свою честь. Вместо этого меня схватили и забили насмерть.$B$BТо, что я обнаружил во время допроса и последовавшей за ним пытки, было чудовищно.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1453,'Ни ты, ни я не можем даже вообразить ту боль, что испытывает несчастный, когда его душу отрывают от тела. Они не мертвы, но и не живы. Они бродят по земле, прислуживая тем, кто связал их с этим миром.$B$BЛорд Разелих, повелитель демонов этих земель, поработил их всех. Девятерых он забрал с собой, поместив связующие камни у Темного портала. Оставшиеся девять были распределены между его подчиненными.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ни ты, ни я не можем даже вообразить ту боль, что испытывает несчастный, когда его душу отрывают от тела. Они не мертвы, но и не живы. Они бродят по земле, прислуживая тем, кто связал их с этим миром.$B$BЛорд Разелих, повелитель демонов этих земель, поработил их всех. Девятерых он забрал с собой, поместив связующие камни у Темного портала. Оставшиеся девять были распределены между его подчиненными.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1455,'Именно их тебе надо уничтожить, чтобы спасти полк! Как я говорил тебе раньше, у Кирита был план.$B$BУ всех слуг обязательно есть слабости. Уничтожь их физические оболочки рядом с их камнями, доведя их почти до стадии разрушения. И только в этот момент камни Обета становятся уязвимы. Надо быстро уничтожить камни, чтобы порабощенные не пришли в себя, иначе во второй раз ты не сможешь их поразить.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Именно их тебе надо уничтожить, чтобы спасти полк! Как я говорил тебе раньше, у Кирита был план.$B$BУ всех слуг обязательно есть слабости. Уничтожь их физические оболочки рядом с их камнями, доведя их почти до стадии разрушения. И только в этот момент камни Обета становятся уязвимы. Надо быстро уничтожить камни, чтобы порабощенные не пришли в себя, иначе во второй раз ты не сможешь их поразить.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1493,'Тяжело жить в пустыне! Стоишь тут весь день на жаре, пить так хочется…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тяжело жить в пустыне! Стоишь тут весь день на жаре, пить так хочется…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1511,'На помощь! $b$bЕсли поможете мне отсюда выбраться, я смогу взорвать дверь к вождю Зул\'Фаррака!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','На помощь! $b$bЕсли поможете мне отсюда выбраться, я смогу взорвать дверь к вождю Зул\'Фаррака!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1513,'Надо убить больше троллей! Прикончи их – и я взорву дверь к их вождю!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Надо убить больше троллей! Прикончи их – и я взорву дверь к их вождю!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1515,'На помощь! Нас поймали тролли! Они хотят принести нас в жертву!$B$BПомоги нам выбраться – и я дам тебе все, что захочешь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','На помощь! Нас поймали тролли! Они хотят принести нас в жертву!$B$BПомоги нам выбраться – и я дам тебе все, что захочешь.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1597,'Нечасто встретишь кузнецов так далеко от Стальгорна. Чем я могу тебе помочь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Нечасто встретишь кузнецов так далеко от Стальгорна. Чем я могу тебе помочь?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1598,'Как-то неуютно мне без крепкого гранитного потолка над головой. От этих звезд аж мурашки по коже!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Как-то неуютно мне без крепкого гранитного потолка над головой. От этих звезд аж мурашки по коже!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1599,'Да, хороша железяка, ничего не скажешь. И форма какая, и подходит хоть парню, хоть девушке... Великолепно! Я только раз видел что-то подобное, работы мастера из Великой Кузни по имени Грумнус Сталевар. С тех пор, небось, еще лучше навострился, и тебя мог бы выучить.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да, хороша железяка, ничего не скажешь. И форма какая, и подходит хоть парню, хоть девушке... Великолепно! Я только раз видел что-то подобное, работы мастера из Великой Кузни по имени Грумнус Сталевар. С тех пор, небось, еще лучше навострился, и тебя мог бы выучить.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1600,'Отправляйтесь в Великую Кузню в самом центре Стальгорна. Учитель работает там вместе с другими нашими мастерами.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Отправляйтесь в Великую Кузню в самом центре Стальгорна. Учитель работает там вместе с другими нашими мастерами.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1605,'Добро пожаловать в мою кузницу, мастер! Позвольте поделиться с вами одним секретом. Не доверяйте никому, ни единой живой душе в мире! Ни мужчинам, ни женщинам, ни зверям! Единственное, чему можно доверять, – это сталь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать в мою кузницу, мастер! Позвольте поделиться с вами одним секретом. Не доверяйте никому, ни единой живой душе в мире! Ни мужчинам, ни женщинам, ни зверям! Единственное, чему можно доверять, – это сталь.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1606,'Что ты ищешь у моей кузницы? Ты по поводу обучения? Или хочешь узнать секреты стали? Загадки ковки? Поговори с рубакой!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что ты ищешь у моей кузницы? Ты по поводу обучения? Или хочешь узнать секреты стали? Загадки ковки? Поговори с рубакой!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1609,'Отправляйся в Оргриммар, на Аллею Чести. Там она и живет вместе с мужем и двумя дочерьми. Все они – на редкость искусные кузнецы, но духи говорят мне, что лучше всего научит тебя она.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Отправляйся в Оргриммар, на Аллею Чести. Там она и живет вместе с мужем и двумя дочерьми. Все они – на редкость искусные кузнецы, но духи говорят мне, что лучше всего научит тебя она.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1611,'У всего есть свой дух. Суть кузнечного дела не в том, чтобы колошматить металл, насильно изменяя его форму. Суть в том, чтобы слышать дух металла и направлять его к той форме, которая ему подходит.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','У всего есть свой дух. Суть кузнечного дела не в том, чтобы колошматить металл, насильно изменяя его форму. Суть в том, чтобы слышать дух металла и направлять его к той форме, которая ему подходит.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1615,'Ты, похоже, ищешь знания. Должно быть, тебе нужен учитель по обращению с молотом и наковальней. Думаю, я могу повести тебя этим путем. Но только после того, как ты примешь духов и услышишь их зов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты, похоже, ищешь знания. Должно быть, тебе нужен учитель по обращению с молотом и наковальней. Думаю, я могу повести тебя этим путем. Но только после того, как ты примешь духов и услышишь их зов.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1618,'Как там лезвие твоего клинка? Достаточно острое, чтобы вспороть брюхо врага? Давай-ка я покажу тебе, как сделать его еще острее.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Как там лезвие твоего клинка? Достаточно острое, чтобы вспороть брюхо врага? Давай-ка я покажу тебе, как сделать его еще острее.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1619,'Хотите стать кузнецом? Хотите ковать клинки, отсекающие головы врагам? Молоты, дробящие черепа? О, да. Я могу помочь, я с удовольствием помогу вам, если это повлечет за собой кровопролитие.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Хотите стать кузнецом? Хотите ковать клинки, отсекающие головы врагам? Молоты, дробящие черепа? О, да. Я могу помочь, я с удовольствием помогу вам, если это повлечет за собой кровопролитие.',`text0_0_loc8`);
-- ruRU; source: emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (1620,'Отправляйтесь в столицу орков, Оргриммар, там вы найдете его в Аллее Чести у магазина "Легендарное оружие".') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Отправляйтесь в столицу орков, Оргриммар, там вы найдете его в Аллее Чести у магазина "Легендарное оружие".',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1635,'Это еще что? Не видишь – я занят!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Это еще что? Не видишь – я занят!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (1640,'Меня не интересуют новички. Возвращайся, когда сможешь показать что-нибудь стоящее.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Меня не интересуют новички. Возвращайся, когда сможешь показать что-нибудь стоящее.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1674,'Приветствую. Я охраняю вход. Если в вашем наборе дисков нет Ульдумских пластин, вы не сможете посетить комплекс Ульдум.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приветствую. Я охраняю вход. Если в вашем наборе дисков нет Ульдумских пластин, вы не сможете посетить комплекс Ульдум.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1675,'Ульдумские пластины – это особые диски, произведенные Создателями и позволяющие проникнуть внутрь комплекса Ульдум. На этих дисках хранятся специфические данные, относящиеся к местной деятельности Творцов.$B$BФизически они почти идентичны тем дискам, которые есть у вас, однако пометки на них указывают на Ульдум, а не на Ульдаман.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ульдумские пластины – это особые диски, произведенные Создателями и позволяющие проникнуть внутрь комплекса Ульдум. На этих дисках хранятся специфические данные, относящиеся к местной деятельности Творцов.$B$BФизически они почти идентичны тем дискам, которые есть у вас, однако пометки на них указывают на Ульдум, а не на Ульдаман.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1676,'Моя задача – ограничение доступа Создателей в комплекс Ульдум. Вход разрешен только тем, кто имеет при себе правильный набор дисков. $B$BВ вашем наборе сейчас не хватает Ульдумских пластин. Без этих пластин доступ не может быть предоставлен.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Моя задача – ограничение доступа Создателей в комплекс Ульдум. Вход разрешен только тем, кто имеет при себе правильный набор дисков. $B$BВ вашем наборе сейчас не хватает Ульдумских пластин. Без этих пластин доступ не может быть предоставлен.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1677,'Несколько наборов ульдумских пластин было синтезировано Создателями для немедленного использования. Создатели контролируют распределение таких дисков для всех комплексов этого мира. Время визита Азерота, одного из комплексов, было изменено, и потому диски из будущего могут циркулировать в этом времени.$B$BСуществующие диски полностью распределены по партиям с надлежащим уровнем безопасности.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Несколько наборов ульдумских пластин было синтезировано Создателями для немедленного использования. Создатели контролируют распределение таких дисков для всех комплексов этого мира. Время визита Азерота, одного из комплексов, было изменено, и потому диски из будущего могут циркулировать в этом времени.$B$BСуществующие диски полностью распределены по партиям с надлежащим уровнем безопасности.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1678,'Создатели наносят эти визиты для того, чтобы вновь взять под контроль населенные миры, когда силы – как внешние, так и внутренние – разрушают их матричную динамику. Такую тактику, особенно в исполнении Творцов, нельзя недооценивать.$B$BДополнительную информацию о расписании посещений этого мира можно найти в соответствующей базе данных, относящейся к делам, связанным с Создателями.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Создатели наносят эти визиты для того, чтобы вновь взять под контроль населенные миры, когда силы – как внешние, так и внутренние – разрушают их матричную динамику. Такую тактику, особенно в исполнении Творцов, нельзя недооценивать.$B$BДополнительную информацию о расписании посещений этого мира можно найти в соответствующей базе данных, относящейся к делам, связанным с Создателями.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1679,'Ульдум – это центр исследований Творцов, продолжающих попытки улучшить биосферу Азерота. Доступ к специфичной информации, касающейся их работы в Ульдуме, есть лишь у владельцев Ульдумских пластин.$B$BХранилища информации в комплексе Ульдума разработаны специально для обработки особых экспериментов и наборов данных; пожалуйста, за более подробной информацией обратитесь к создателям.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ульдум – это центр исследований Творцов, продолжающих попытки улучшить биосферу Азерота. Доступ к специфичной информации, касающейся их работы в Ульдуме, есть лишь у владельцев Ульдумских пластин.$B$BХранилища информации в комплексе Ульдума разработаны специально для обработки особых экспериментов и наборов данных; пожалуйста, за более подробной информацией обратитесь к создателям.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1734,'Добро пожаловать в "Тысячу мелочей Синей Луны", |3-6($c). Если у вас есть вопросы, обращайтесь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать в "Тысячу мелочей Синей Луны", |3-6($c). Если у вас есть вопросы, обращайтесь.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1793,'Стражи Терамора – лучшие воины Альянса во всем Калимдоре. Наш долг – охранять законы Альянса в этом далеком краю.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Стражи Терамора – лучшие воины Альянса во всем Калимдоре. Наш долг – охранять законы Альянса в этом далеком краю.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1794,'Мы не много знаем о пожаре в таверне "Последний привал", кроме того, что жена Джеймса Хьяля и его ребенок не смогли спастись.$b$bМы сумели вытащить оттуда Джеймса, но с тех пор он сам не свой.$b$bУ нас множество улик, но ни одного свидетеля. Мы лишь надеемся, что с помощью стражи и бдительных жителей Терамора мы сможем раскрыть это ужасное преступление.$b$bЕсли ты захочешь помочь нам в расследовании, то остатки таверны находятся на границе со Степями.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы не много знаем о пожаре в таверне "Последний привал", кроме того, что жена Джеймса Хьяля и его ребенок не смогли спастись.$b$bМы сумели вытащить оттуда Джеймса, но с тех пор он сам не свой.$b$bУ нас множество улик, но ни одного свидетеля. Мы лишь надеемся, что с помощью стражи и бдительных жителей Терамора мы сможем раскрыть это ужасное преступление.$b$bЕсли ты захочешь помочь нам в расследовании, то остатки таверны находятся на границе со Степями.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1796,'Ты их видишь, $gсмертный:смертная;? Нет… едва ли. Тебя видят, а ты не видишь – вот твой дар и проклятие.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты их видишь, $gсмертный:смертная;? Нет… едва ли. Тебя видят, а ты не видишь – вот твой дар и проклятие.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1816,'Теперь их разум помутнен, |3-6($r). И даже сильнее, чем прежде. Они живут лишь для того, чтобы служить Разелиху и защищать его. Фрагменты амулета, которые хранит каждый из них, нужны для призыва владыки демонов. Но ты $gдолжен:должна; знать, что им невозможно причинить вред никакими обычными способами.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Теперь их разум помутнен, |3-6($r). И даже сильнее, чем прежде. Они живут лишь для того, чтобы служить Разелиху и защищать его. Фрагменты амулета, которые хранит каждый из них, нужны для призыва владыки демонов. Но ты $gдолжен:должна; знать, что им невозможно причинить вред никакими обычными способами.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1818,'Люди считали своей большую часть Пылевых топей, но клан Каменного Молота, с нашей помощью, смог отбросить их.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Люди считали своей большую часть Пылевых топей, но клан Каменного Молота, с нашей помощью, смог отбросить их.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1820,'Если Рит как-то связан с поджогом "Последнего привала", его надо найти и допросить.$b$bЯ отправил по его следу Огрона. Они ушли на юго-восток, в сторону главной дороги через топи. Повстречайся с Огроном, а затем найди Рита.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если Рит как-то связан с поджогом "Последнего привала", его надо найти и допросить.$b$bЯ отправил по его следу Огрона. Они ушли на юго-восток, в сторону главной дороги через топи. Повстречайся с Огроном, а затем найди Рита.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1875,'Наши Степи не столь бесплодны, как кажется на первый взгляд.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Наши Степи не столь бесплодны, как кажется на первый взгляд.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1914,'Мои товары из кожи и ткани – лучшие во всей долине!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мои товары из кожи и ткани – лучшие во всей долине!',`text0_0_loc8`);
