INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1918,'Похоже, алтарь манит тебя так, как будто он все еще жив.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Похоже, алтарь манит тебя так, как будто он все еще жив.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1920,'Хвала Элуне! Сколько же лет у меня не было посетителей!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Хвала Элуне! Сколько же лет у меня не было посетителей!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (1923,'Древний алтарь Хаккара стоит у входа в комнату.$B$BГлядя на балконы над ним, вы замечаете, что на каждом покоится большая змеевидная статуя. Статуи очень похожи на те, что на алтаре перед вами. Между ними должна быть какая-то связь…','Древний алтарь Хаккара стоит у входа в комнату.$B$BГлядя на балконы над ним, вы замечаете, что на каждом покоится большая змеевидная статуя. Статуи очень похожи на те, что на алтаре перед вами. Между ними должна быть какая-то связь…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Древний алтарь Хаккара стоит у входа в комнату.$B$BГлядя на балконы над ним, вы замечаете, что на каждом покоится большая змеевидная статуя. Статуи очень похожи на те, что на алтаре перед вами. Между ними должна быть какая-то связь…',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Древний алтарь Хаккара стоит у входа в комнату.$B$BГлядя на балконы над ним, вы замечаете, что на каждом покоится большая змеевидная статуя. Статуи очень похожи на те, что на алтаре перед вами. Между ними должна быть какая-то связь…',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (1935,'Яркий луч протягивается через комнату и исчезает. Потом еще один… и еще.$B$BКажется, это какой-то знак.','Яркий луч протягивается через комнату и исчезает. Потом еще один… и еще.$B$BКажется, это какой-то знак.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Яркий луч протягивается через комнату и исчезает. Потом еще один… и еще.$B$BКажется, это какой-то знак.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Яркий луч протягивается через комнату и исчезает. Потом еще один… и еще.$B$BКажется, это какой-то знак.',`text0_1_loc8`);
