INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1953,'Я отомщу!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я отомщу!',`text0_0_loc8`);
