INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (1955,'Как ты можешь видеть, я всего лишь один человек с бестолковым дылдой-оруженосцем. Силы дворфов Черного Железа и тварей под командой Рагнароса наверняка одержали бы верх надо мной одним, но я абсолютно уверен, что $gтакой смелый искатель:такая смелая искательница; приключений, как ты, без проблем справится с обитателями кратера. Если ты решишь помогать мне, я награжу тебя богатством и сокровищами, о которых ты не $gсмел:смела; мечтать.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Как ты можешь видеть, я всего лишь один человек с бестолковым дылдой-оруженосцем. Силы дворфов Черного Железа и тварей под командой Рагнароса наверняка одержали бы верх надо мной одним, но я абсолютно уверен, что $gтакой смелый искатель:такая смелая искательница; приключений, как ты, без проблем справится с обитателями кратера. Если ты решишь помогать мне, я награжу тебя богатством и сокровищами, о которых ты не $gсмел:смела; мечтать.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (2033,'Дни, проведенные нами в Азшаре, нельзя назвать ни славными, ни благополучными. Но мы еще молоды. Кровь еще течет в наших жилах – и мы победим! Это только вопрос времени.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Дни, проведенные нами в Азшаре, нельзя назвать ни славными, ни благополучными. Но мы еще молоды. Кровь еще течет в наших жилах – и мы победим! Это только вопрос времени.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (2034,'Белгром отправил нас сюда из Оргриммара на помощь своим так называемым "союзникам", но его замыслы можно обратить во благо для всей Орды.$B$BДа, его чрезмерное увлечение женщинами сгубило уже немало орков, но он по-прежнему наш командир. И наш долг – извлечь из этой ситуации максимум пользы.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Белгром отправил нас сюда из Оргриммара на помощь своим так называемым "союзникам", но его замыслы можно обратить во благо для всей Орды.$B$BДа, его чрезмерное увлечение женщинами сгубило уже немало орков, но он по-прежнему наш командир. И наш долг – извлечь из этой ситуации максимум пользы.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (2038,'Я знаю, знаю, что нахожусь не пойми где!$B$BВообще-то я из Кабестана, но мой дирижабль разбился, и я подумал, что можно исследовать чего-нибудь здесь!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я знаю, знаю, что нахожусь не пойми где!$B$BВообще-то я из Кабестана, но мой дирижабль разбился, и я подумал, что можно исследовать чего-нибудь здесь!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (2039,'Этот дух парит над павшим телом. Его призрачный взгляд пронзает вас насквозь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Этот дух парит над павшим телом. Его призрачный взгляд пронзает вас насквозь.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (2054,'Для безопасного спуска я даю крылья тем, кто в них нуждается.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Для безопасного спуска я даю крылья тем, кто в них нуждается.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (2113,'Спасибо, что $gспас:спасла; меня!$B$BЯ повар и алхимик из Штормграда. Я здесь искал местные травы и собирал рецепты для дяди Ангуса, когда меня похитили эти иглогривы. Если бы не ты, я бы, несомненно, окончил жизнь в качестве их ужина.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Спасибо, что $gспас:спасла; меня!$B$BЯ повар и алхимик из Штормграда. Я здесь искал местные травы и собирал рецепты для дяди Ангуса, когда меня похитили эти иглогривы. Если бы не ты, я бы, несомненно, окончил жизнь в качестве их ужина.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (2114,'Хм… да, у меня есть рецепт, который может вам пригодиться. Позвольте мне обучить вас!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Хм… да, у меня есть рецепт, который может вам пригодиться. Позвольте мне обучить вас!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (2115,'Да, я знаю один редкий алхимический рецепт. Могу поделиться!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да, я знаю один редкий алхимический рецепт. Могу поделиться!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (2135,'Здравствуй, $gюноша:девица;… Звать меня Карлс. Если у тебя есть какое-нибудь гномское устройство, скорее всего, его создал я! Впрочем, если оно взорвалось, тогда это точно не я, но вот если оно помогло тебе разбогатеть, можем обсудить авторский гонорар!$B$BАх да, если ты из Гномрегана, то лучше просто повернись на 180 градусов и иди прямо. С гномреганцами мне говорить не о чем.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здравствуй, $gюноша:девица;… Звать меня Карлс. Если у тебя есть какое-нибудь гномское устройство, скорее всего, его создал я! Впрочем, если оно взорвалось, тогда это точно не я, но вот если оно помогло тебе разбогатеть, можем обсудить авторский гонорар!$B$BАх да, если ты из Гномрегана, то лучше просто повернись на 180 градусов и иди прямо. С гномреганцами мне говорить не о чем.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (2138,'Позволь мне преподать тебе урок математики: "гоблин" плюс "инженерное дело" равно "НОУ-ХАУ", детка. Все, кто думает иначе, просто не умеют складывать.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Позволь мне преподать тебе урок математики: "гоблин" плюс "инженерное дело" равно "НОУ-ХАУ", детка. Все, кто думает иначе, просто не умеют складывать.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (2155,'Спасибо тебе, $gмаленький:маленькая:r; |3-6($r)!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Спасибо тебе, $gмаленький:маленькая:r; |3-6($r)!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (2173,'Ты пока не слишком хорошо готовишь. Подучись еще немного, а потом приходи ко мне.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты пока не слишком хорошо готовишь. Подучись еще немного, а потом приходи ко мне.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (2174,'Ваши познания в алхимии еще недостаточно глубоки для того, чтобы учиться у меня. Приходите как-нибудь потом...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ваши познания в алхимии еще недостаточно глубоки для того, чтобы учиться у меня. Приходите как-нибудь потом...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (2175,'Тайное знание гибельно только для тех, кто слаб. Даже если ты не пойдешь тропой чернокнижников, запомни это.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Тайное знание гибельно только для тех, кто слаб. Даже если ты не пойдешь тропой чернокнижников, запомни это.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (2213,'Я навсегда привязан к этому проклятому миру. Каково твое желание, $gсмертный:смертная;?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я навсегда привязан к этому проклятому миру. Каково твое желание, $gсмертный:смертная;?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (2235,'Обратитесь ко мне, когда будете готовы выслушать историю.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Обратитесь ко мне, когда будете готовы выслушать историю.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (2238,'В последнее время дворфы Черного Железа появляются на поверхности гораздо чаще. Они строят крепости в Бесплодных землях. Они отправляют экспедиции в Ульдаман. Более того, они даже вторглись на наши земли и нанесли удар по дамбе возле озера!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','В последнее время дворфы Черного Железа появляются на поверхности гораздо чаще. Они строят крепости в Бесплодных землях. Они отправляют экспедиции в Ульдаман. Более того, они даже вторглись на наши земли и нанесли удар по дамбе возле озера!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (2253,'Здрасьте! Если вы насчет призыва демонов или сбора налогов, то вы явно ошиблись адресом, да-да! Простите.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здрасьте! Если вы насчет призыва демонов или сбора налогов, то вы явно ошиблись адресом, да-да! Простите.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (2273,'Кажется, мое ожерелье упало в озеро. Это подарок от папы – вот он рассердится!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Кажется, мое ожерелье упало в озеро. Это подарок от папы – вот он рассердится!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (2274,'Спасибо, $gдядя:тетя;, что нашли мое ожерелье. Вы лучше всех!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Спасибо, $gдядя:тетя;, что нашли мое ожерелье. Вы лучше всех!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`,`text2_0_loc8`,`text2_1_loc8`) VALUES (2275,'Мы с братьями сражались на горе Хиджал – как и те воины, что стоят снаружи. Каждый, кто решит что-нибудь украсть, будет иметь дело с нами!','Мы с братьями сражались на горе Хиджал – как и те воины, что стоят снаружи. Каждый, кто решит что-нибудь украсть, будет иметь дело с нами!','Гарантия безопасности банка – моя жизнь. Вас это устраивает?','Гарантия безопасности банка – моя жизнь. Вас это устраивает?','Вы что, доверили бы свои товары гоблину?','Вы что, доверили бы свои товары гоблину?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы с братьями сражались на горе Хиджал – как и те воины, что стоят снаружи. Каждый, кто решит что-нибудь украсть, будет иметь дело с нами!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мы с братьями сражались на горе Хиджал – как и те воины, что стоят снаружи. Каждый, кто решит что-нибудь украсть, будет иметь дело с нами!',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Гарантия безопасности банка – моя жизнь. Вас это устраивает?',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Гарантия безопасности банка – моя жизнь. Вас это устраивает?',`text1_1_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Вы что, доверили бы свои товары гоблину?',`text2_0_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Вы что, доверили бы свои товары гоблину?',`text2_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (2276,'Здравствуйте, $gгосподин:госпожа;… Не будет ли у вас немного времени чтобы помочь мне? Пожалуйста?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здравствуйте, $gгосподин:госпожа;… Не будет ли у вас немного времени чтобы помочь мне? Пожалуйста?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (2278,'Как же приятно обзавестись собственным домом после стольких лет войны и рабства!','Как же приятно обзавестись собственным домом после стольких лет войны и рабства!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Как же приятно обзавестись собственным домом после стольких лет войны и рабства!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Как же приятно обзавестись собственным домом после стольких лет войны и рабства!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (2279,'Моя жизнь – в служении господину.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Моя жизнь – в служении господину.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (2280,'Даже когда повсюду царит мир, здесь продолжается война, и многие племена идут в бой под знаменем Вождя. Ты здесь, чтобы привести свой клан в ряды бойцов за Оргриммар?','Даже когда повсюду царит мир, здесь продолжается война, и многие племена идут в бой под знаменем Вождя. Ты здесь, чтобы привести свой клан в ряды бойцов за Оргриммар?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Даже когда повсюду царит мир, здесь продолжается война, и многие племена идут в бой под знаменем Вождя. Ты здесь, чтобы привести свой клан в ряды бойцов за Оргриммар?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Даже когда повсюду царит мир, здесь продолжается война, и многие племена идут в бой под знаменем Вождя. Ты здесь, чтобы привести свой клан в ряды бойцов за Оргриммар?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (2284,'Земля хранит немало тайн, |3-6($c). Наш долг – следить, чтобы то, чему положено быть тайной, ей же и оставалось.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Земля хранит немало тайн, |3-6($c). Наш долг – следить, чтобы то, чему положено быть тайной, ей же и оставалось.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (2313,'Кругом одни заговорщики. Эти глупцы не понимают важности моего дела и стараются держать меня в постоянном неведении! $B$BНе сочти за оскорбление.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Кругом одни заговорщики. Эти глупцы не понимают важности моего дела и стараются держать меня в постоянном неведении! $B$BНе сочти за оскорбление.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (2315,'Приветствую тебя, |3-6($r). Я Франклорн Искусник. Ты $gпришел:пришла;, чтобы узнать о Пике и Черном Железе?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приветствую тебя, |3-6($r). Я Франклорн Искусник. Ты $gпришел:пришла;, чтобы узнать о Пике и Черном Железе?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (2316,'Выбора у меня не было – по крайней мере, я так думал. Я должен был оставаться с королем и народом несмотря на падение Тауриссана.$B$BПодчиняясь Рагнаросу, король Дагран Тауриссан вырвал сердце горы и воздвиг Пик Черной горы. Мы же неустанно трудились, возводя город, по своей мощи превосходящий все крепости прошлого… и будущего.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Выбора у меня не было – по крайней мере, я так думал. Я должен был оставаться с королем и народом несмотря на падение Тауриссана.$B$BПодчиняясь Рагнаросу, король Дагран Тауриссан вырвал сердце горы и воздвиг Пик Черной горы. Мы же неустанно трудились, возводя город, по своей мощи превосходящий все крепости прошлого… и будущего.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (2317,'Я просто стоял и смотрел, как скверна Рагнароса просачивается через сердца и умы нации Черного Железа. Эта когда-то почтенная раса, доведенная до безумия… до зла.$B$BКогда Шпиль был построен, моя воля к жизни среди моего народа иссякла. Я умер как герой новой нации Черного Железа. Могилу устроили здесь – у входа в город, который я спланировал и построил, – в честь моих усилий.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я просто стоял и смотрел, как скверна Рагнароса просачивается через сердца и умы нации Черного Железа. Эта когда-то почтенная раса, доведенная до безумия… до зла.$B$BКогда Шпиль был построен, моя воля к жизни среди моего народа иссякла. Я умер как герой новой нации Черного Железа. Могилу устроили здесь – у входа в город, который я спланировал и построил, – в честь моих усилий.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text2_0_loc8`,`text2_1_loc8`,`text3_0_loc8`,`text3_1_loc8`,`text6_0_loc8`,`text6_1_loc8`,`text7_0_loc8`,`text7_1_loc8`) VALUES (2355,'Люблю пироги.','Люблю пироги.','Пирог вышел отличный, хотите?','Пирог вышел отличный, хотите?','У вас неудачный день? Попробуйте вишневого пирога!','У вас неудачный день? Попробуйте вишневого пирога!','Свежий вишневый пирог! Пальчики оближешь!','Свежий вишневый пирог! Пальчики оближешь!','Вишневый пирог – самое вкусное блюдо Азерота!','Вишневый пирог – самое вкусное блюдо Азерота!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Люблю пироги.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Люблю пироги.',`text0_1_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Пирог вышел отличный, хотите?',`text2_0_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Пирог вышел отличный, хотите?',`text2_1_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','У вас неудачный день? Попробуйте вишневого пирога!',`text3_0_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','У вас неудачный день? Попробуйте вишневого пирога!',`text3_1_loc8`), `text6_0_loc8`=IF(`text6_0_loc8` IS NULL OR `text6_0_loc8`='','Свежий вишневый пирог! Пальчики оближешь!',`text6_0_loc8`), `text6_1_loc8`=IF(`text6_1_loc8` IS NULL OR `text6_1_loc8`='','Свежий вишневый пирог! Пальчики оближешь!',`text6_1_loc8`), `text7_0_loc8`=IF(`text7_0_loc8` IS NULL OR `text7_0_loc8`='','Вишневый пирог – самое вкусное блюдо Азерота!',`text7_0_loc8`), `text7_1_loc8`=IF(`text7_1_loc8` IS NULL OR `text7_1_loc8`='','Вишневый пирог – самое вкусное блюдо Азерота!',`text7_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (2393,'О, если бы тут была ветка дерева, чтобы укрыться за ней. Тогда охранники ни за что бы меня не увидели.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','О, если бы тут была ветка дерева, чтобы укрыться за ней. Тогда охранники ни за что бы меня не увидели.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (2474,'Все потеряно...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Все потеряно...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (2477,'Слушай внимательно, |3-6($r).$B$BНесколько месяцев назад мировой судья Озер отправил посланца в Стальгорн. Они умоляли короля помочь защититься от захватчиков из Черной горы, приходящих из Красного Гребня и Пылающих Степей.$B$BПринцесса Мойра вызвалась помочь, несмотря на мои протесты. Мне выделили двадцать элитных стражников на защиту принцессы в ее опасном путешествии из озера Лок в Приозерье.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Слушай внимательно, |3-6($r).$B$BНесколько месяцев назад мировой судья Озер отправил посланца в Стальгорн. Они умоляли короля помочь защититься от захватчиков из Черной горы, приходящих из Красного Гребня и Пылающих Степей.$B$BПринцесса Мойра вызвалась помочь, несмотря на мои протесты. Мне выделили двадцать элитных стражников на защиту принцессы в ее опасном путешествии из озера Лок в Приозерье.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (2478,'*Каран откашливается.*$B$BМы прошли через туннель Тлеющего Ущелья в разоренную пустыню, включающую в себя ущелье. Задним числом можно сказать, что было подозрительно тихо. Единственная опасность, подстерегавшая нас, исходила от местных хищников – тварей, с которыми мои люди легко справлялись.$B$BМы достаточно легко добрались до Черной горы и пошли по каменному сооружению, как ни в чем не бывало.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','*Каран откашливается.*$B$BМы прошли через туннель Тлеющего Ущелья в разоренную пустыню, включающую в себя ущелье. Задним числом можно сказать, что было подозрительно тихо. Единственная опасность, подстерегавшая нас, исходила от местных хищников – тварей, с которыми мои люди легко справлялись.$B$BМы достаточно легко добрались до Черной горы и пошли по каменному сооружению, как ни в чем не бывало.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (2479,'По дороге через Огненный Гребень мы попали в засаду. Дворфы клана Черного Железа… их были сотни! Они прятались за стенами и камнями, в расщелинах и укромных уголках. Они налетели на нас, смяв стражу и нескольких храбрецов, согласившихся помочь в нашем деле. $B$BЯсно было одно: эту засаду прекрасно подготовили. Похоже было, что они знали каждый наш шаг заранее…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','По дороге через Огненный Гребень мы попали в засаду. Дворфы клана Черного Железа… их были сотни! Они прятались за стенами и камнями, в расщелинах и укромных уголках. Они налетели на нас, смяв стражу и нескольких храбрецов, согласившихся помочь в нашем деле. $B$BЯсно было одно: эту засаду прекрасно подготовили. Похоже было, что они знали каждый наш шаг заранее…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (2480,'Как еще такое могло случиться? Кто-то наверняка выдал все Черному Железу!$B$B<Каран грозит кулаком.>$B$BПомоги мне! Если я когда-нибудь выберусь отсюда, то потрачу остаток жизни на то, чтобы отыскать предателя!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Как еще такое могло случиться? Кто-то наверняка выдал все Черному Железу!$B$B<Каран грозит кулаком.>$B$BПомоги мне! Если я когда-нибудь выберусь отсюда, то потрачу остаток жизни на то, чтобы отыскать предателя!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (2481,'На чем я остановился? Ах да, нас поймали. Мои элитные стражи были убиты на месте. Но меня пощадили, а принцессу увезли в неизвестном направлении. Я же попал в Шлаковую яму, а потом в эту тюрьму.$B$BДумаю, я до сих пор жив только потому, что они хотят получить какую-то выгоду от моей ничтожной жизни. А может быть, им просто нравится смотреть, как я снова и снова переживаю события прошлого. Память – жестокий тюремщик, |3-6($r).') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','На чем я остановился? Ах да, нас поймали. Мои элитные стражи были убиты на месте. Но меня пощадили, а принцессу увезли в неизвестном направлении. Я же попал в Шлаковую яму, а потом в эту тюрьму.$B$BДумаю, я до сих пор жив только потому, что они хотят получить какую-то выгоду от моей ничтожной жизни. А может быть, им просто нравится смотреть, как я снова и снова переживаю события прошлого. Память – жестокий тюремщик, |3-6($r).',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (2493,'Только глупец станет тревожить меня в моем логове.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Только глупец станет тревожить меня в моем логове.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (2496,'Гррр, фррр…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Гррр, фррр…',`text0_0_loc8`);
