INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (2497,'Иди в лавку "Алхимия и Эликсиры Йелмака". Это в центре Волока, к западу от гигантского дерева.','Иди в лавку "Алхимия и Эликсиры Йелмака". Это в центре Волока, к западу от гигантского дерева.','Зелья и масла – вот чему тебя научит Йелмак, если ты $gдостоин:достойна;. Ищи его лавку в середине Волока.','Зелья и масла – вот чему тебя научит Йелмак, если ты $gдостоин:достойна;. Ищи его лавку в середине Волока.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Иди в лавку "Алхимия и Эликсиры Йелмака". Это в центре Волока, к западу от гигантского дерева.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Иди в лавку "Алхимия и Эликсиры Йелмака". Это в центре Волока, к западу от гигантского дерева.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Зелья и масла – вот чему тебя научит Йелмак, если ты $gдостоин:достойна;. Ищи его лавку в середине Волока.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Зелья и масла – вот чему тебя научит Йелмак, если ты $gдостоин:достойна;. Ищи его лавку в середине Волока.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (2501,'Тебе нужно в лавку Чародейских товаров Годана. Ищи его в западной части Волока, рядом с Аллеей Мудрости.','Тебе нужно в лавку Чародейских товаров Годана. Ищи его в западной части Волока, рядом с Аллеей Мудрости.','Топор мне зачаруешь? Только чтоб постоянно работало. Ладно, потом как-нибудь. А пока иди в лавку Чародейских товаров Годана. Это в западной части Волока, возле Аллеи Мудрости.','Топор мне зачаруешь? Только чтоб постоянно работало. Ладно, потом как-нибудь. А пока иди в лавку Чародейских товаров Годана. Это в западной части Волока, возле Аллеи Мудрости.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тебе нужно в лавку Чародейских товаров Годана. Ищи его в западной части Волока, рядом с Аллеей Мудрости.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Тебе нужно в лавку Чародейских товаров Годана. Ищи его в западной части Волока, рядом с Аллеей Мудрости.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Топор мне зачаруешь? Только чтоб постоянно работало. Ладно, потом как-нибудь. А пока иди в лавку Чародейских товаров Годана. Это в западной части Волока, возле Аллеи Мудрости.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Топор мне зачаруешь? Только чтоб постоянно работало. Ладно, потом как-нибудь. А пока иди в лавку Чародейских товаров Годана. Это в западной части Волока, возле Аллеи Мудрости.',`text1_1_loc8`);
