INSERT INTO `locales_npc_text` (`id`,`text1_0_loc8`,`text1_1_loc8`) VALUES (2516,'Это хорошо, что ты стремишься не убивать напрасно. Ищи Тьюда в лавке "Кодо-кожевники". Это в центре Волока.','Это хорошо, что ты стремишься не убивать напрасно. Ищи Тьюда в лавке "Кодо-кожевники". Это в центре Волока.') ON DUPLICATE KEY UPDATE `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Это хорошо, что ты стремишься не убивать напрасно. Ищи Тьюда в лавке "Кодо-кожевники". Это в центре Волока.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Это хорошо, что ты стремишься не убивать напрасно. Ищи Тьюда в лавке "Кодо-кожевники". Это в центре Волока.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (2518,'Портняжное ателье Магара находится на Волоке. Ищи ее к югу от огромного дерева, по соседству с кодо-кожевниками.','Портняжное ателье Магара находится на Волоке. Ищи ее к югу от огромного дерева, по соседству с кодо-кожевниками.','Платье?! Это не поможет тебе против хорошей стали! Ба, если ты точно хочешь стать портным, ищи ателье Магара на Волоке.','Платье?! Это не поможет тебе против хорошей стали! Ба, если ты точно хочешь стать портным, ищи ателье Магара на Волоке.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Портняжное ателье Магара находится на Волоке. Ищи ее к югу от огромного дерева, по соседству с кодо-кожевниками.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Портняжное ателье Магара находится на Волоке. Ищи ее к югу от огромного дерева, по соседству с кодо-кожевниками.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Платье?! Это не поможет тебе против хорошей стали! Ба, если ты точно хочешь стать портным, ищи ателье Магара на Волоке.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Платье?! Это не поможет тебе против хорошей стали! Ба, если ты точно хочешь стать портным, ищи ателье Магара на Волоке.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (2533,'У нас есть долг, |3-6($c). Долг перед Ордой.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','У нас есть долг, |3-6($c). Долг перед Ордой.',`text0_0_loc8`);
