INSERT INTO `locales_npc_text` (`id`,`text1_0_loc8`,`text1_1_loc8`) VALUES (2557,'Таверна у нас стоит в восточной части Аллеи Силы, к северу от главных городских ворот.','Таверна у нас стоит в восточной части Аллеи Силы, к северу от главных городских ворот.') ON DUPLICATE KEY UPDATE `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Таверна у нас стоит в восточной части Аллеи Силы, к северу от главных городских ворот.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Таверна у нас стоит в восточной части Аллеи Силы, к северу от главных городских ворот.',`text1_1_loc8`);
