INSERT INTO `locales_npc_text` (`id`,`text1_0_loc8`,`text1_1_loc8`) VALUES (2558,'Свои любовные письма вы можете забрать в почтовом ящике в центре Аллеи Силы.','Свои любовные письма вы можете забрать в почтовом ящике в центре Аллеи Силы.') ON DUPLICATE KEY UPDATE `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Свои любовные письма вы можете забрать в почтовом ящике в центре Аллеи Силы.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Свои любовные письма вы можете забрать в почтовом ящике в центре Аллеи Силы.',`text1_1_loc8`);
