INSERT INTO `locales_npc_text` (`id`,`text1_0_loc8`,`text1_1_loc8`) VALUES (2559,'Идите прямо на северо-запад Аллеи Чести. Там вы и найдете Зал Охотников.','Идите прямо на северо-запад Аллеи Чести. Там вы и найдете Зал Охотников.') ON DUPLICATE KEY UPDATE `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Идите прямо на северо-запад Аллеи Чести. Там вы и найдете Зал Охотников.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Идите прямо на северо-запад Аллеи Чести. Там вы и найдете Зал Охотников.',`text1_1_loc8`);
