INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (2568,'Меня редко кто ищет… Что я могу сделать для вас?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Меня редко кто ищет… Что я могу сделать для вас?',`text0_0_loc8`);
