INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (2574,'Да, но теперь тебе куда полезнее обратиться к травничеству! Ты будешь выращивать редчайшие растения! С сумой вечного цветения даже последний бездарь что-нибудь да вырастит, а уж опытный специалист добьется фантастических успехов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да, но теперь тебе куда полезнее обратиться к травничеству! Ты будешь выращивать редчайшие растения! С сумой вечного цветения даже последний бездарь что-нибудь да вырастит, а уж опытный специалист добьется фантастических успехов.',`text0_0_loc8`);
