INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (2595,'Смерть нашей плоти – это возрождение нашего духа и священного долга.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Смерть нашей плоти – это возрождение нашего духа и священного долга.',`text0_1_loc8`);
