INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (2598,'Я больше никогда не прикоснусь к камню. Никогда не испытаю радость отливки металла…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я больше никогда не прикоснусь к камню. Никогда не испытаю радость отливки металла…',`text0_0_loc8`);
