INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (2600,'Для вас проход закрыт. Вы не из наших, да и вызов вы нам не бросали.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Для вас проход закрыт. Вы не из наших, да и вызов вы нам не бросали.',`text0_1_loc8`);
