INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (2601,'Наша судьба – предостережение всем тем, кто захочет иметь дело с Великим огнем.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Наша судьба – предостережение всем тем, кто захочет иметь дело с Великим огнем.',`text0_0_loc8`);
