INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (2602,'Наша кара одновременно и наше благословение.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Наша кара одновременно и наше благословение.',`text0_0_loc8`);
