INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (2604,'Ты хочешь научиться древнему ремеслу? Ты хочешь плавить черное железо?$B$BПорадуй меня, |3-6($r). Принеси мне жертву, и я приму ее!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты хочешь научиться древнему ремеслу? Ты хочешь плавить черное железо?$B$BПорадуй меня, |3-6($r). Принеси мне жертву, и я приму ее!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (2605,'Ваша воля сильна, а намерения чисты.$B$BВозможно, вы и подойдете…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ваша воля сильна, а намерения чисты.$B$BВозможно, вы и подойдете…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (2633,'Я… Я не помню, как попал сюда…$B$BКажется, я плыл на… плоту…$B$B') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я… Я не помню, как попал сюда…$B$BКажется, я плыл на… плоту…$B$B',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text5_0_loc8`) VALUES (2634,'Это страшная тайна… даже для меня!$B$BХорошо, что вы нашли меня – по крайней мере мне не приходится прятаться в кустах или под горой.') ON DUPLICATE KEY UPDATE `text5_0_loc8`=IF(`text5_0_loc8` IS NULL OR `text5_0_loc8`='','Это страшная тайна… даже для меня!$B$BХорошо, что вы нашли меня – по крайней мере мне не приходится прятаться в кустах или под горой.',`text5_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`,`text2_0_loc8`,`text2_1_loc8`,`text3_0_loc8`,`text3_1_loc8`,`text4_0_loc8`,`text4_1_loc8`,`text5_0_loc8`,`text5_1_loc8`,`text7_0_loc8`,`text7_1_loc8`) VALUES (2636,'Рагнарос подчинит весь мир!','Рагнарос подчинит весь мир!','Пропустите стаканчик, |3-6($c)! Как знать, вдруг он последний…','Пропустите стаканчик, |3-6($c)! Как знать, вдруг он последний…','Если бы не "Угрюмый обжора", я бы только и делал, что дракончикам крылышки отрывал.','Если бы не "Угрюмый обжора", я бы только и делал, что дракончикам крылышки отрывала.','Не было бы "Угрюмого обжоры", я бы развлекался, обрывая крылышки дракончикам.','Не было бы "Угрюмого обжоры", я бы развлекалась, обрывая крылышки дракончикам.','Элементали воды воюют с элементалями огня, а значит – и с нами. Один из их лидеров, Гидраксис, собирает агентов для своих целей…','Элементали воды воюют с элементалями огня, а значит – и с нами. Один из их лидеров, Гидраксис, собирает агентов для своих целей…','Я слышал, что благородный элементаль воды Гидраксис ведет войну со служителями огня. Будем надеяться, что он проиграет!','Я слышала, что благородный элементаль воды Гидраксис ведет войну со служителями огня. Будем надеяться, что он проиграет!','Если Гидраксис привлечет на свою сторону еще больше народу, это может изменить расстановку сил…','Если Гидраксис привлечет на свою сторону еще больше народу, это может изменить расстановку сил…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Рагнарос подчинит весь мир!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Рагнарос подчинит весь мир!',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Пропустите стаканчик, |3-6($c)! Как знать, вдруг он последний…',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Пропустите стаканчик, |3-6($c)! Как знать, вдруг он последний…',`text1_1_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Если бы не "Угрюмый обжора", я бы только и делал, что дракончикам крылышки отрывал.',`text2_0_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Если бы не "Угрюмый обжора", я бы только и делал, что дракончикам крылышки отрывала.',`text2_1_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Не было бы "Угрюмого обжоры", я бы развлекался, обрывая крылышки дракончикам.',`text3_0_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','Не было бы "Угрюмого обжоры", я бы развлекалась, обрывая крылышки дракончикам.',`text3_1_loc8`), `text4_0_loc8`=IF(`text4_0_loc8` IS NULL OR `text4_0_loc8`='','Элементали воды воюют с элементалями огня, а значит – и с нами. Один из их лидеров, Гидраксис, собирает агентов для своих целей…',`text4_0_loc8`), `text4_1_loc8`=IF(`text4_1_loc8` IS NULL OR `text4_1_loc8`='','Элементали воды воюют с элементалями огня, а значит – и с нами. Один из их лидеров, Гидраксис, собирает агентов для своих целей…',`text4_1_loc8`), `text5_0_loc8`=IF(`text5_0_loc8` IS NULL OR `text5_0_loc8`='','Я слышал, что благородный элементаль воды Гидраксис ведет войну со служителями огня. Будем надеяться, что он проиграет!',`text5_0_loc8`), `text5_1_loc8`=IF(`text5_1_loc8` IS NULL OR `text5_1_loc8`='','Я слышала, что благородный элементаль воды Гидраксис ведет войну со служителями огня. Будем надеяться, что он проиграет!',`text5_1_loc8`), `text7_0_loc8`=IF(`text7_0_loc8` IS NULL OR `text7_0_loc8`='','Если Гидраксис привлечет на свою сторону еще больше народу, это может изменить расстановку сил…',`text7_0_loc8`), `text7_1_loc8`=IF(`text7_1_loc8` IS NULL OR `text7_1_loc8`='','Если Гидраксис привлечет на свою сторону еще больше народу, это может изменить расстановку сил…',`text7_1_loc8`);
