INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`,`text3_0_loc8`,`text3_1_loc8`) VALUES (2637,'Сплошные выстрелы и пламя, а потом кто-то проигрывает и умирает.','Сплошные выстрелы и пламя, а потом кто-то проигрывает и умирает.','Мой отец говорил, что настанет день, подобный сегодняшнему, когда $gнезнакомец:незнакомка; заговорит со мной, и я должен буду сдержаться, чтобы не убить $gего:ее;.','Мой отец говорил, что настанет день, подобный сегодняшнему, когда $gнезнакомец:незнакомка; заговорит со мной, и я должна буду сдержаться, чтобы не убить $gего:ее;.','Через час у меня служба, но до того… гори все огнем!','Через час у меня служба, но до того… гори все огнем!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Сплошные выстрелы и пламя, а потом кто-то проигрывает и умирает.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Сплошные выстрелы и пламя, а потом кто-то проигрывает и умирает.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Мой отец говорил, что настанет день, подобный сегодняшнему, когда $gнезнакомец:незнакомка; заговорит со мной, и я должен буду сдержаться, чтобы не убить $gего:ее;.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Мой отец говорил, что настанет день, подобный сегодняшнему, когда $gнезнакомец:незнакомка; заговорит со мной, и я должна буду сдержаться, чтобы не убить $gего:ее;.',`text1_1_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Через час у меня служба, но до того… гори все огнем!',`text3_0_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','Через час у меня служба, но до того… гори все огнем!',`text3_1_loc8`);
