INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (2820,'Знаки на табличке аккуратно расшифрованы…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Знаки на табличке аккуратно расшифрованы…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (2823,'Кратер Ун\'Горо – это далеко на юг от Калимдора. За Тысячей Игл, в Танарисе. Высматривай большие плавающие камни… Ими помечен вход в кратер. Только осторожно… Это нелегкий путь. Хищники скрываются недалеко от входа.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Кратер Ун\'Горо – это далеко на юг от Калимдора. За Тысячей Игл, в Танарисе. Высматривай большие плавающие камни… Ими помечен вход в кратер. Только осторожно… Это нелегкий путь. Хищники скрываются недалеко от входа.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (2836,'На Северный пилон можно поставить желтый, красный или зеленый кристалл.$B$BСредоточие – это энергия, которую можно создать, используя желтые кристаллы. У нее есть два возможных эффекта – нанесение урона и смягчение урона. $B$BДля кристалла Ожога нужны красные и желтые кристаллы. В результате получается мощный взрыв, оглушающий врагов.$B$BДля кристалла Восстановления нужны желтые и зеленые кристаллы. Этот кристалл исцелит вас или ваших союзников.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','На Северный пилон можно поставить желтый, красный или зеленый кристалл.$B$BСредоточие – это энергия, которую можно создать, используя желтые кристаллы. У нее есть два возможных эффекта – нанесение урона и смягчение урона. $B$BДля кристалла Ожога нужны красные и желтые кристаллы. В результате получается мощный взрыв, оглушающий врагов.$B$BДля кристалла Восстановления нужны желтые и зеленые кристаллы. Этот кристалл исцелит вас или ваших союзников.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (2837,'Западный пилон принимает красные, зеленые и синие кристаллы.$B$BПилон концентрирует энергию, получаемую при помощи красных кристаллов. Он может действовать двумя способами: либо усиливая твою защиту, либо ослабляя защиту противника.$B$BКристалл-хранитель потребляет красные и зеленые кристаллы. Он повышает твою броню. $B$BКристалл-губитель потребляет синие и красные кристаллы. Он понижает броню указанной цели.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Западный пилон принимает красные, зеленые и синие кристаллы.$B$BПилон концентрирует энергию, получаемую при помощи красных кристаллов. Он может действовать двумя способами: либо усиливая твою защиту, либо ослабляя защиту противника.$B$BКристалл-хранитель потребляет красные и зеленые кристаллы. Он повышает твою броню. $B$BКристалл-губитель потребляет синие и красные кристаллы. Он понижает броню указанной цели.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (2845,'"Дарнассэ?"$B$BНочная эльфийка-друид выжидающе смотрит на вас. Очевидно, что вы не можете говорить на одном языке. Бесстрашно улыбаясь, она показывает на себя. Потом показывает на вас и улыбается еще раз. Наконец она несколько раз показывает рукой куда-то на север.$B$BМожет быть, она имеет в виду, что дальше по дороге есть друид, понимающий ваш язык?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','"Дарнассэ?"$B$BНочная эльфийка-друид выжидающе смотрит на вас. Очевидно, что вы не можете говорить на одном языке. Бесстрашно улыбаясь, она показывает на себя. Потом показывает на вас и улыбается еще раз. Наконец она несколько раз показывает рукой куда-то на север.$B$BМожет быть, она имеет в виду, что дальше по дороге есть друид, понимающий ваш язык?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (2846,'ПОМОГИТЕ!!!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','ПОМОГИТЕ!!!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (2847,'Вы от Гребня?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вы от Гребня?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (2849,'Некоторые растения Оскверненного леса можно очистить от порчи с кенарийского бальзама исцеления растений. Для создания этого порошка мне нужно несколько разных компонентов. Ты можешь помочь мне разными способами – в зависимости от того, что ты умеешь.$B$BКроме того, для работы тебе понадобится маяк Кенария. Это устройство позволяет видеть признаки порчи, незаметные невооруженным глазом.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Некоторые растения Оскверненного леса можно очистить от порчи с кенарийского бальзама исцеления растений. Для создания этого порошка мне нужно несколько разных компонентов. Ты можешь помочь мне разными способами – в зависимости от того, что ты умеешь.$B$BКроме того, для работы тебе понадобится маяк Кенария. Это устройство позволяет видеть признаки порчи, незаметные невооруженным глазом.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (2850,'Останки покрыты червями и мухами.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Останки покрыты червями и мухами.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (2873,'Эта великая святыня была создана много лет назад ночными эльфами, которым тогда принадлежали эти земли.$B$BКакие секреты может она скрывать?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эта великая святыня была создана много лет назад ночными эльфами, которым тогда принадлежали эти земли.$B$BКакие секреты может она скрывать?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (2933,'Тайны пилонов Кратера Ун\'Горо отныне принадлежат тебе. Приходи к этим пилонам в любое время, чтобы воспользоваться их силой или найти полезные припасы.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тайны пилонов Кратера Ун\'Горо отныне принадлежат тебе. Приходи к этим пилонам в любое время, чтобы воспользоваться их силой или найти полезные припасы.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (2973,'Не люблю разговоров.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не люблю разговоров.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (2993,'Они утеряны, |3-6($r). Манускрипты, написанные эльфийскими мастерами… Их разбросало по всему миру, когда на Кель\'Талас обрушилась Плеть.$B$BСейчас мы ищем эти манускрипты. Ищем для того, чтобы познать сокрытые в них тайны и вернуть нашу былую силу.$B$BЯ ищу десять сочинений Кариэля Винтхалуса. Если вам попадется манускрипт этого автора, позвольте мне ознакомиться с его магическими свойствами, а я взамен изготовлю слияние силы… разумеется, за некоторую плату. Мои цены довольно высоки, но результат того стоит.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Они утеряны, |3-6($r). Манускрипты, написанные эльфийскими мастерами… Их разбросало по всему миру, когда на Кель\'Талас обрушилась Плеть.$B$BСейчас мы ищем эти манускрипты. Ищем для того, чтобы познать сокрытые в них тайны и вернуть нашу былую силу.$B$BЯ ищу десять сочинений Кариэля Винтхалуса. Если вам попадется манускрипт этого автора, позвольте мне ознакомиться с его магическими свойствами, а я взамен изготовлю слияние силы… разумеется, за некоторую плату. Мои цены довольно высоки, но результат того стоит.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (2995,'<Матредис пристально вглядывается в манускрипт.> $B$BТы $gпришел:пришла; за слиянием? Ты $gвыполнил:выполнила; инструкции манускрипта?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Матредис пристально вглядывается в манускрипт.> $B$BТы $gпришел:пришла; за слиянием? Ты $gвыполнил:выполнила; инструкции манускрипта?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (2996,'Дай мне чары, и я создам для тебя слияние, смертный.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Дай мне чары, и я создам для тебя слияние, смертный.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (2999,'Да хранит тебя Свет в этот день.','Да хранит тебя Свет в этот день.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да хранит тебя Свет в этот день.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Да хранит тебя Свет в этот день.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3001,'Что делать Пожару?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что делать Пожару?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (3014,'Где аукционный дом? Как же, он сразу за Вратами Стальгорна, как войдешь в наш славный город. Это напротив хранилища.','Где аукционный дом? Как же, он сразу за Вратами Стальгорна, как войдешь в наш славный город. Это напротив хранилища.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Где аукционный дом? Как же, он сразу за Вратами Стальгорна, как войдешь в наш славный город. Это напротив хранилища.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Где аукционный дом? Как же, он сразу за Вратами Стальгорна, как войдешь в наш славный город. Это напротив хранилища.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (3020,'Лично я считаю травяной ковер Тельдрассила лучшей из постелей, но для тех, кто любит роскошь, есть отличные кровати в таверне Саэлиэнн на Террасе ремесленников.','Лично я считаю травяной ковер Тельдрассила лучшей из постелей, но для тех, кто любит роскошь, есть отличные кровати в таверне Саэлиэнн на Террасе ремесленников.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Лично я считаю травяной ковер Тельдрассила лучшей из постелей, но для тех, кто любит роскошь, есть отличные кровати в таверне Саэлиэнн на Террасе ремесленников.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Лично я считаю травяной ковер Тельдрассила лучшей из постелей, но для тех, кто любит роскошь, есть отличные кровати в таверне Саэлиэнн на Террасе ремесленников.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (3025,'Храм Луны – это дом жрецов Элуны. Здесь ты найдешь Джандрию и Ларию, которые направят тебя на твоем пути жреческого обучения.','Храм Луны – это дом жрецов Элуны. Здесь ты найдешь Джандрию и Ларию, которые направят тебя на твоем пути жреческого обучения.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Храм Луны – это дом жрецов Элуны. Здесь ты найдешь Джандрию и Ларию, которые направят тебя на твоем пути жреческого обучения.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Храм Луны – это дом жрецов Элуны. Здесь ты найдешь Джандрию и Ларию, которые направят тебя на твоем пути жреческого обучения.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (3033,'Ты найдешь Сильданаиру на Террасе Воинов, среди стражников. Она бдительно высматривает врагов, которые могут выйти из леса к нашему прекрасному городу.','Ты найдешь Сильданаиру на Террасе Воинов, среди стражников. Она бдительно высматривает врагов, которые могут выйти из леса к нашему прекрасному городу.','Сильданаира обучала многих стражей, охраняющих наш возлюбленный город. Я уверен, что она сможет сделать из тебя воина. Ищи ее на Террасе Воинов возле входа в город.','Сильданаира обучала многих стражей, охраняющих наш возлюбленный город. Я уверена, что она сможет сделать из тебя воина. Ищи ее на Террасе Воинов возле входа в город.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты найдешь Сильданаиру на Террасе Воинов, среди стражников. Она бдительно высматривает врагов, которые могут выйти из леса к нашему прекрасному городу.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты найдешь Сильданаиру на Террасе Воинов, среди стражников. Она бдительно высматривает врагов, которые могут выйти из леса к нашему прекрасному городу.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Сильданаира обучала многих стражей, охраняющих наш возлюбленный город. Я уверен, что она сможет сделать из тебя воина. Ищи ее на Террасе Воинов возле входа в город.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Сильданаира обучала многих стражей, охраняющих наш возлюбленный город. Я уверена, что она сможет сделать из тебя воина. Ищи ее на Террасе Воинов возле входа в город.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text1_0_loc8`,`text1_1_loc8`) VALUES (3035,'Алхимия? Никаких проблем, |3-6($c). Айнетиль своим терпением и мастерством превзошла всех алхимиков с Террасы ремесленников. Тебе бы стоило уже бежать туда вприпрыжку. Вприпрыжку, говорю! Ну, ступай!','Алхимия? Никаких проблем, |3-6($c). Айнетиль своим терпением и мастерством превзошла всех алхимиков с Террасы ремесленников. Тебе бы стоило уже бежать туда вприпрыжку. Вприпрыжку, говорю! Ну, ступай!') ON DUPLICATE KEY UPDATE `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Алхимия? Никаких проблем, |3-6($c). Айнетиль своим терпением и мастерством превзошла всех алхимиков с Террасы ремесленников. Тебе бы стоило уже бежать туда вприпрыжку. Вприпрыжку, говорю! Ну, ступай!',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Алхимия? Никаких проблем, |3-6($c). Айнетиль своим терпением и мастерством превзошла всех алхимиков с Террасы ремесленников. Тебе бы стоило уже бежать туда вприпрыжку. Вприпрыжку, говорю! Ну, ступай!',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3036,'Элегорн – искусный повар, который столетиями оттачивал свое мастерство. Если он согласится тебя учить – считай, что ты $gдобился:добилась; великой милости. Раз думаешь, что $gзаслужил:заслужила; этого, ищи его на Террасе ремесленников.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Элегорн – искусный повар, который столетиями оттачивал свое мастерство. Если он согласится тебя учить – считай, что ты $gдобился:добилась; великой милости. Раз думаешь, что $gзаслужил:заслужила; этого, ищи его на Террасе ремесленников.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (3038,'Обучение занимает много времени, но оно того стоит. Поговори с Астайей на Террасе ремесленников – может быть, она научит тебя чему-нибудь полезному.','Обучение занимает много времени, но оно того стоит. Поговори с Астайей на Террасе ремесленников – может быть, она научит тебя чему-нибудь полезному.','За годы рыбалки Астайя выудила несколько прелюбопытных вещиц. Почему бы тебе не поговорить с ней? Найти ее можно на Террасе торговцев.','За годы рыбалки Астайя выудила несколько прелюбопытных вещиц. Почему бы тебе не поговорить с ней? Найти ее можно на Террасе торговцев.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Обучение занимает много времени, но оно того стоит. Поговори с Астайей на Террасе ремесленников – может быть, она научит тебя чему-нибудь полезному.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Обучение занимает много времени, но оно того стоит. Поговори с Астайей на Террасе ремесленников – может быть, она научит тебя чему-нибудь полезному.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','За годы рыбалки Астайя выудила несколько прелюбопытных вещиц. Почему бы тебе не поговорить с ней? Найти ее можно на Террасе торговцев.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','За годы рыбалки Астайя выудила несколько прелюбопытных вещиц. Почему бы тебе не поговорить с ней? Найти ее можно на Террасе торговцев.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text1_0_loc8`,`text1_1_loc8`) VALUES (3039,'Так ты – $gбудущий травник:будущая травница;? Тогда тебе стоит посетить Фиродрена Зовущего Луну в Храмовых садах. Он тебя чему-нибудь да научит.','Так ты – $gбудущий травник:будущая травница;? Тогда тебе стоит посетить Фиродрена Зовущего Луну в Храмовых садах. Он тебя чему-нибудь да научит.') ON DUPLICATE KEY UPDATE `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Так ты – $gбудущий травник:будущая травница;? Тогда тебе стоит посетить Фиродрена Зовущего Луну в Храмовых садах. Он тебя чему-нибудь да научит.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Так ты – $gбудущий травник:будущая травница;? Тогда тебе стоит посетить Фиродрена Зовущего Луну в Храмовых садах. Он тебя чему-нибудь да научит.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (3046,'Я обнаружила четыре вида растений, подвергшихся порче: песнецвет, ветроцвет, кнутокорень и Ночной дракон. Песнецвет и ветроцвет довольно часто встречаются в Оскверненном лесу, а вот кнутокорень с Ночным драконом придется поискать… Но все они важны для экосистемы Оскверненного леса.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я обнаружила четыре вида растений, подвергшихся порче: песнецвет, ветроцвет, кнутокорень и Ночной дракон. Песнецвет и ветроцвет довольно часто встречаются в Оскверненном лесу, а вот кнутокорень с Ночным драконом придется поискать… Но все они важны для экосистемы Оскверненного леса.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (3047,'Я обнаружила четыре вида растений, подвергшихся порче: песнецвет, ветроцвет, кнутокорень и Ночной дракон. Песнецвет и ветроцвет довольно часто встречаются в Оскверненном лесу, а вот кнутокорень с Ночным драконом придется поискать… Но все они важны для экосистемы Оскверненного леса.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я обнаружила четыре вида растений, подвергшихся порче: песнецвет, ветроцвет, кнутокорень и Ночной дракон. Песнецвет и ветроцвет довольно часто встречаются в Оскверненном лесу, а вот кнутокорень с Ночным драконом придется поискать… Но все они важны для экосистемы Оскверненного леса.',`text0_1_loc8`);
