INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3048,'Здесь была великая битва. Много великих битв.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здесь была великая битва. Много великих битв.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3049,'Поговорите с Регтаром. Он очень мудрый и обязательно поможет вам.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Поговорите с Регтаром. Он очень мудрый и обязательно поможет вам.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3055,'Эй?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эй?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3061,'Что предпочитаешь: ружья или луки?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что предпочитаешь: ружья или луки?',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (3073,'Подождите, |3-6($c), сюда идут наги! Поговорим, когда отобьем их нападение!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Подождите, |3-6($c), сюда идут наги! Поговорим, когда отобьем их нападение!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3074,'Так-с *ик*… Слушай, я где-то тебя видел *ик*. Не рассказывал ли я тебе, как мы с Виндзором отбились от тридц-э… от тыщ… от миллиона орков?$B$BО-о, устраивайся, дружок, это такая история!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Так-с *ик*… Слушай, я где-то тебя видел *ик*. Не рассказывал ли я тебе, как мы с Виндзором отбились от тридц-э… от тыщ… от миллиона орков?$B$BО-о, устраивайся, дружок, это такая история!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3077,'Изумительно, правда? Все эти артефакты, реликвии…$B$BНе знаю даже, чем восхищаться в первую очередь – их размерами или историей. Мне еще столько всего предстоит узнать…$B$BКстати, говорят, что многие расы имеют тесную историческую связь с ночными эльфами.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Изумительно, правда? Все эти артефакты, реликвии…$B$BНе знаю даже, чем восхищаться в первую очередь – их размерами или историей. Мне еще столько всего предстоит узнать…$B$BКстати, говорят, что многие расы имеют тесную историческую связь с ночными эльфами.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (3093,'Привет, меня зовут Петра. Справа от меня мой кодо Даданга. Мы живем в Экспедиции Маршалла уже несколько лет – еще с тех пор, когда Даданга была совсем маленькой. $B$BЕсли у тебя есть факел или еще что-нибудь такое, пожалуйста, спрячь его. Даданга не любит дыма.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Привет, меня зовут Петра. Справа от меня мой кодо Даданга. Мы живем в Экспедиции Маршалла уже несколько лет – еще с тех пор, когда Даданга была совсем маленькой. $B$BЕсли у тебя есть факел или еще что-нибудь такое, пожалуйста, спрячь его. Даданга не любит дыма.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3098,'Посмотри на эти образцы! Что это значит? Что это значит? Мне понадобится время, время, чтобы посмотреть на всю эту информацию. И мне понадобится больше информации. Информацию я не могу получить… проклятье! Думай, Ларис, думай!$B$BЧто ты собираешься сделать? Что?!$B$BДолжен быть выход!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Посмотри на эти образцы! Что это значит? Что это значит? Мне понадобится время, время, чтобы посмотреть на всю эту информацию. И мне понадобится больше информации. Информацию я не могу получить… проклятье! Думай, Ларис, думай!$B$BЧто ты собираешься сделать? Что?!$B$BДолжен быть выход!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3100,'Ну, не то чтобы я этого не знаю… Похоже, это зависит от области обитания. Одни расы говорят "слизь", другие – "слизнюк"…$B$BВсякий раз, когда я сталкиваюсь со слизью, слизнюком или слизненышем, по сути это оказывается одним и тем же существом. Разница, видимо, только в среде обитания. Вот потому-то нам и нужен чистый экземпляр.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ну, не то чтобы я этого не знаю… Похоже, это зависит от области обитания. Одни расы говорят "слизь", другие – "слизнюк"…$B$BВсякий раз, когда я сталкиваюсь со слизью, слизнюком или слизненышем, по сути это оказывается одним и тем же существом. Разница, видимо, только в среде обитания. Вот потому-то нам и нужен чистый экземпляр.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3101,'Чистым образцом можно назвать лишь тот, что не подвергся инородному влиянию. Существ нужно искать в самой естественной и свойственной им среде.$B$BВ месте, до которого еще не добралась цивилизация, которое еще не изменили господствующие расы Азерота. В месте, которое было бы… нетронутым.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Чистым образцом можно назвать лишь тот, что не подвергся инородному влиянию. Существ нужно искать в самой естественной и свойственной им среде.$B$BВ месте, до которого еще не добралась цивилизация, которое еще не изменили господствующие расы Азерота. В месте, которое было бы… нетронутым.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (3133,'Почему ты хочешь покинуть эти солнечные берега и прозрачную голубую воду? Для меня загадка. Здесь настоящий рай. Только не говори этого моему брату Запоте, он и так уже достаточно расстроен тем, что надолго застрял в Тирисфале. Этот дирижабль садится в Оргриммаре, так что можешь не волноваться о необходимости слушать, как он ноет. Но если скоро будешь в Тирисфале, послушай меня и не заводи его.','Почему ты хочешь покинуть эти солнечные берега и прозрачную голубую воду? Для меня загадка. Здесь настоящий рай. Только не говори этого моему брату Запоте, он и так уже достаточно расстроен тем, что надолго застрял в Тирисфале. Этот дирижабль садится в Оргриммаре, так что можешь не волноваться о необходимости слушать, как он ноет. Но если скоро будешь в Тирисфале, послушай меня и не заводи его.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Почему ты хочешь покинуть эти солнечные берега и прозрачную голубую воду? Для меня загадка. Здесь настоящий рай. Только не говори этого моему брату Запоте, он и так уже достаточно расстроен тем, что надолго застрял в Тирисфале. Этот дирижабль садится в Оргриммаре, так что можешь не волноваться о необходимости слушать, как он ноет. Но если скоро будешь в Тирисфале, послушай меня и не заводи его.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Почему ты хочешь покинуть эти солнечные берега и прозрачную голубую воду? Для меня загадка. Здесь настоящий рай. Только не говори этого моему брату Запоте, он и так уже достаточно расстроен тем, что надолго застрял в Тирисфале. Этот дирижабль садится в Оргриммаре, так что можешь не волноваться о необходимости слушать, как он ноет. Но если скоро будешь в Тирисфале, послушай меня и не заводи его.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (3154,'Почтовый ящик находится возле банка Громового Утеса, на Нижнем уступе.','Почтовый ящик находится возле банка Громового Утеса, на Нижнем уступе.','Да, я как раз недавно видел, как почту привозили… Почтовый ящик возле банка Громового Утеса, на нижнем уступе.','Да, я как раз недавно видела, как почту привозили… Почтовый ящик возле банка Громового Утеса, на нижнем уступе.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Почтовый ящик находится возле банка Громового Утеса, на Нижнем уступе.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Почтовый ящик находится возле банка Громового Утеса, на Нижнем уступе.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Да, я как раз недавно видел, как почту привозили… Почтовый ящик возле банка Громового Утеса, на нижнем уступе.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Да, я как раз недавно видела, как почту привозили… Почтовый ящик возле банка Громового Утеса, на нижнем уступе.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (3155,'Это недалеко – в самой нижней части Громового Утеса, возле банка.','Это недалеко – в самой нижней части Громового Утеса, возле банка.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Это недалеко – в самой нижней части Громового Утеса, возле банка.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Это недалеко – в самой нижней части Громового Утеса, возле банка.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3156,'Это может вас огорчить, но дела в последнее время идут не слишком хорошо…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Это может вас огорчить, но дела в последнее время идут не слишком хорошо…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3218,'Здравствуй, $gпарень:девушка;, если ты ищешь лучшие цены во всем Стальгорне, ты $gпришел:пришла; по адресу.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здравствуй, $gпарень:девушка;, если ты ищешь лучшие цены во всем Стальгорне, ты $gпришел:пришла; по адресу.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3234,'Привет. Я Груббер Блумп.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Привет. Я Груббер Блумп.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3253,'…жаренное на сковородке, глубоко прожаренное и быстро обжаренное…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','…жаренное на сковородке, глубоко прожаренное и быстро обжаренное…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3273,'При вашем приближении все жидкости и смеси начинают кипеть и булькать. Рядом с оборудованием лежат огромные клещи, пригодные для взятия проб у слизнюков.$B$BПоблизости есть и защитное снаряжение, но оно выглядит пыльным и неухоженным.$B$BВам кажется, что самым разумным было бы не трогать здесь ничего.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','При вашем приближении все жидкости и смеси начинают кипеть и булькать. Рядом с оборудованием лежат огромные клещи, пригодные для взятия проб у слизнюков.$B$BПоблизости есть и защитное снаряжение, но оно выглядит пыльным и неухоженным.$B$BВам кажется, что самым разумным было бы не трогать здесь ничего.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (3299,'А, $gприятель-чернокнижник:подруга-чернокнижница;, да еще и $gсведущий:сведущая;!$B$BРада с тобой познакомиться. Меня зовут Менара Расщепительница Бездны… и не без оснований.$B$BЯ вижу, у тебя достаточно сил и знаний, чтобы не отринуть новые средства… более могущественные, чем те, которые тебе известны. Если это так, продолжим разговор. Если же нет… Думаю, путь к причалу и назад через океан тебе уже известен.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','А, $gприятель-чернокнижник:подруга-чернокнижница;, да еще и $gсведущий:сведущая;!$B$BРада с тобой познакомиться. Меня зовут Менара Расщепительница Бездны… и не без оснований.$B$BЯ вижу, у тебя достаточно сил и знаний, чтобы не отринуть новые средства… более могущественные, чем те, которые тебе известны. Если это так, продолжим разговор. Если же нет… Думаю, путь к причалу и назад через океан тебе уже известен.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3301,'Давным-давно, задолго до нынешних войн и раздоров, из-за нашей доброты мы оказались на краю гибели. Мы пережили очень многое, |3-6($r).$B$BНападение Пылающего Легиона. Души демонов. Раскол Аспектов. Возвышение Смертокрыла. Пленение нашей королевы Алекстразы кланом Драконьей Пасти.$B$BНо, несмотря ни на что, наша несгибаемая воля всегда оставалась с нами. Только она позволила нам сохранить место под солнцем этого мира.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Давным-давно, задолго до нынешних войн и раздоров, из-за нашей доброты мы оказались на краю гибели. Мы пережили очень многое, |3-6($r).$B$BНападение Пылающего Легиона. Души демонов. Раскол Аспектов. Возвышение Смертокрыла. Пленение нашей королевы Алекстразы кланом Драконьей Пасти.$B$BНо, несмотря ни на что, наша несгибаемая воля всегда оставалась с нами. Только она позволила нам сохранить место под солнцем этого мира.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3303,'Наверное, следует рассказать, зачем я здесь.$B$BВы знаете об Аспекте Смертокрыле? Или о его потомках, Нефарионе и Ониксии?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Наверное, следует рассказать, зачем я здесь.$B$BВы знаете об Аспекте Смертокрыле? Или о его потомках, Нефарионе и Ониксии?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3305,'Несомненно. Предмет был окончательно уничтожен, а Смертокрыл – побежден объединенными усилиями четверых оставшихся Аспектов. Где сейчас сам Смертокрыл, я не знаю, но один из его потомков, Нефариан, правит цитаделью и желает завершить дело отца.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Несомненно. Предмет был окончательно уничтожен, а Смертокрыл – побежден объединенными усилиями четверых оставшихся Аспектов. Где сейчас сам Смертокрыл, я не знаю, но один из его потомков, Нефариан, правит цитаделью и желает завершить дело отца.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3311,'Не подноси это ближе. Я даже отсюда чувствую зло, которым пронизана эта печать.$B$BДержи этот предмет крепко – дай мне рассмотреть его.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не подноси это ближе. Я даже отсюда чувствую зло, которым пронизана эта печать.$B$BДержи этот предмет крепко – дай мне рассмотреть его.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3337,'Не бывает слишком острых клинков и слишком прочных доспехов, поэтому талантливые зачаровыватели всегда в цене. Один из таких – Таладан – может научить тебя, как улучшить оружие и доспехи с помощью магии. Его можно найти на террасе Ремесленников.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не бывает слишком острых клинков и слишком прочных доспехов, поэтому талантливые зачаровыватели всегда в цене. Один из таких – Таладан – может научить тебя, как улучшить оружие и доспехи с помощью магии. Его можно найти на террасе Ремесленников.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3357,'Рад видеть вас у себя в магазине, |3-6($c). Чем семейка Ладноскроев может вам помочь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Рад видеть вас у себя в магазине, |3-6($c). Чем семейка Ладноскроев может вам помочь?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (3375,'Ах, |3-6($r)… Я обладаю великими секретами и знаю, как создавать амулеты великой силы.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ах, |3-6($r)… Я обладаю великими секретами и знаю, как создавать амулеты великой силы.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (3377,'Мау\'ари знает, зачем ты ищешь ее…$B$BНайдешь э\'ко – принеси его мне, а я помогу его трансформировать.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мау\'ари знает, зачем ты ищешь ее…$B$BНайдешь э\'ко – принеси его мне, а я помогу его трансформировать.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3380,'Да, да, я знаю, что Даданга не любит дым. Судя по запаху, Даданга еще и мыться не любит.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да, да, я знаю, что Даданга не любит дым. Судя по запаху, Даданга еще и мыться не любит.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (3382,'Сокровище Мау\'ари бесценно… Блестящие осколки, из которых оно сделано, черпают энергию извне и отдают ее тебе.$B$BПоложи оберег в свой заплечный мешок, чтобы собирать э\'ко, духовную силу своих врагов. Если найдешь э\'ко, отнеси его Мау\'ари.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Сокровище Мау\'ари бесценно… Блестящие осколки, из которых оно сделано, черпают энергию извне и отдают ее тебе.$B$BПоложи оберег в свой заплечный мешок, чтобы собирать э\'ко, духовную силу своих врагов. Если найдешь э\'ко, отнеси его Мау\'ари.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (3383,'Э\'ко – это сила, которая есть у всего живого. Мой оберег поможет тебе забирать ее.$B$BЗнаю я одно заклятие – так, ты э\'ко найдешь, а оно его в джуджу превратит.$B$BА потом-то ты сможешь сокровище Мау\'ари взять, да и силу джуджу с его помощью на себя обратить.$B$BДа ты попробуй-то. Принеси э\'ко Мау\'ари, мы и позабавимся.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Э\'ко – это сила, которая есть у всего живого. Мой оберег поможет тебе забирать ее.$B$BЗнаю я одно заклятие – так, ты э\'ко найдешь, а оно его в джуджу превратит.$B$BА потом-то ты сможешь сокровище Мау\'ари взять, да и силу джуджу с его помощью на себя обратить.$B$BДа ты попробуй-то. Принеси э\'ко Мау\'ари, мы и позабавимся.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3395,'День добрый, $gпаренек:девушка;. Чем я могу быть полезен?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','День добрый, $gпаренек:девушка;. Чем я могу быть полезен?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3396,'Учиться $gпришел:пришла;, да? Я и сам пока учусь, но чем смогу – помогу.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Учиться $gпришел:пришла;, да? Я и сам пока учусь, но чем смогу – помогу.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3397,'Быстро же ты учишься, $gпарень:девица;, я уж за тобой и не поспеваю... Если хочешь учиться дальше, то поговори с моим наставником. Звать его Ротгат, Ротгат Камнебород, а живет он в Стальгорне, прямо в Великой Кузне.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Быстро же ты учишься, $gпарень:девица;, я уж за тобой и не поспеваю... Если хочешь учиться дальше, то поговори с моим наставником. Звать его Ротгат, Ротгат Камнебород, а живет он в Стальгорне, прямо в Великой Кузне.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3398,'Чего? Нету времени болтать, надо разобраться с этим заказом для папани.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Чего? Нету времени болтать, надо разобраться с этим заказом для папани.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3399,'Ты кое-что знаешь. Пожалуй, достаточно, чтобы я смог тебя учить дальше. Давай посмотрим, что я смогу тебе показать, да?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты кое-что знаешь. Пожалуй, достаточно, чтобы я смог тебя учить дальше. Давай посмотрим, что я смогу тебе показать, да?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3400,'Ты больше меня знаешь, это точно. Скажу тебе так: иди поговори кое с кем. Он, конечно, станет тебя проверять, но, даю слово, он хороший учитель. Его зовут Ротгат, он работает у старого Бенгуса.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты больше меня знаешь, это точно. Скажу тебе так: иди поговори кое с кем. Он, конечно, станет тебя проверять, но, даю слово, он хороший учитель. Его зовут Ротгат, он работает у старого Бенгуса.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3401,'Ну, $gдруг мой:подруга;, теперь ты умеешь побольше моего. Есть у меня приятель, Ротгат Камнебород, вот его найди. Когда я ушел в армию Джайны, он в Стальгорне остался. Даже если он сам и не возьмется тебя учить, то хорошего наставника точно подскажет. Ищи его в Великой Кузне.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ну, $gдруг мой:подруга;, теперь ты умеешь побольше моего. Есть у меня приятель, Ротгат Камнебород, вот его найди. Когда я ушел в армию Джайны, он в Стальгорне остался. Даже если он сам и не возьмется тебя учить, то хорошего наставника точно подскажет. Ищи его в Великой Кузне.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (3402,'Лучше всего начать с обитателей Зимних Ключей.$B$BХотя и в других местах можно глянуть…') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Лучше всего начать с обитателей Зимних Ключей.$B$BХотя и в других местах можно глянуть…',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3403,'Конечно же, я могу тебя научить. Хоть я и простой подмастерье, но кое-какие секреты знаю...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Конечно же, я могу тебя научить. Хоть я и простой подмастерье, но кое-какие секреты знаю...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3404,'Мне нелегко признать это, но ты намного лучший кузнец, чем я. Если ты хочешь научиться большему, чем мои жалкие познания, советую найти дворфа, которого зовут Терум Подземная Кузня из Стальгорна. Ты найдешь его в Квартале Дворфов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мне нелегко признать это, но ты намного лучший кузнец, чем я. Если ты хочешь научиться большему, чем мои жалкие познания, советую найти дворфа, которого зовут Терум Подземная Кузня из Стальгорна. Ты найдешь его в Квартале Дворфов.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3406,'Думаешь, у меня есть время на пустую болтовню?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Думаешь, у меня есть время на пустую болтовню?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3407,'Ты кое-что умеешь, но позволь-ка показать тебе пару трюков. Авось пригодится.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты кое-что умеешь, но позволь-ка показать тебе пару трюков. Авось пригодится.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3408,'Гораздо лучший кузнец, нежели я, это точно! Несмотря на то что я буду все отрицать, если ты расскажешь кому-то об этом, – но это правда. Тебе надо поговорить с Терумом Подземной Кузней. Если кто-нибудь и может тебя обучить, так это он.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Гораздо лучший кузнец, нежели я, это точно! Несмотря на то что я буду все отрицать, если ты расскажешь кому-то об этом, – но это правда. Тебе надо поговорить с Терумом Подземной Кузней. Если кто-нибудь и может тебя обучить, так это он.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3409,'Только попробуй назвать меня Однукком – убью и закопаю!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Только попробуй назвать меня Однукком – убью и закопаю!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3410,'Лупить молотом по наковальне – еще не значит быть кузнецом. Дай-ка мне эту штуку и смотри, чему я тебя научу, пока ты окончательно не $gопозорился:опозорилась; перед всеми нами.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Лупить молотом по наковальне – еще не значит быть кузнецом. Дай-ка мне эту штуку и смотри, чему я тебя научу, пока ты окончательно не $gопозорился:опозорилась; перед всеми нами.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3411,'Недурно. Тебе надо поговорить с Рыком, он как раз приехал в Оргриммар учиться у Сару. Ищи его в Районе воинов около кузницы Сару. И еще, он непременно захочет тебя проверить, так что подготовься как можно лучше.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Недурно. Тебе надо поговорить с Рыком, он как раз приехал в Оргриммар учиться у Сару. Ищи его в Районе воинов около кузницы Сару. И еще, он непременно захочет тебя проверить, так что подготовься как можно лучше.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3412,'Рык зовет меня простаком, потому что я слишком медлителен. А я просто хочу делать все как следует, а на это нужно время.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Рык зовет меня простаком, потому что я слишком медлителен. А я просто хочу делать все как следует, а на это нужно время.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3413,'Я могу показать вам то, что вы так хотите узнать, но имейте терпение. Поработайте со сталью не спеша и прочувствуйте, как она меняется под вашим молотком. Когда станете со сталью единым целом, сами прекрасно все поймете.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я могу показать вам то, что вы так хотите узнать, но имейте терпение. Поработайте со сталью не спеша и прочувствуйте, как она меняется под вашим молотком. Когда станете со сталью единым целом, сами прекрасно все поймете.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3414,'Ты быстро учишься. Это неплохо. Просто обязательно выполняй работу хорошо, пока требуется. А теперь, боюсь, я должен отослать тебя к Рыку поучиться еще. Учись всему, чему он может научить, и не слушай его сердитых слов. Он начинает сердиться, когда дочери Сару смеются над ним.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты быстро учишься. Это неплохо. Просто обязательно выполняй работу хорошо, пока требуется. А теперь, боюсь, я должен отослать тебя к Рыку поучиться еще. Учись всему, чему он может научить, и не слушай его сердитых слов. Он начинает сердиться, когда дочери Сару смеются над ним.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3415,'Я все слушаю и слушаю, но так и не слышу духов, о которых говорит Карн.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я все слушаю и слушаю, но так и не слышу духов, о которых говорит Карн.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3416,'Карн говорит, что мы должны прислушиваться к духам кузни и стали, и тогда они направят нашу руку. Но я не слышу никаких духов – только сплошной звон в ушах. Давай, бери молот – может, духи чего скажут, если мы возьмемся за дело вместе.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Карн говорит, что мы должны прислушиваться к духам кузни и стали, и тогда они направят нашу руку. Но я не слышу никаких духов – только сплошной звон в ушах. Давай, бери молот – может, духи чего скажут, если мы возьмемся за дело вместе.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3417,'Видимо, духи любят тебя больше, чем меня. Я до сих пор не слышу их зова, но ты, похоже, хорошо $gусвоил:усвоила; их уроки. Иди поговори с Карном – он будет рад поговорить с $gтем:той;, кто тоже слышит духов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Видимо, духи любят тебя больше, чем меня. Я до сих пор не слышу их зова, но ты, похоже, хорошо $gусвоил:усвоила; их уроки. Иди поговори с Карном – он будет рад поговорить с $gтем:той;, кто тоже слышит духов.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (3418,'Вы тратите мое бесценное время. Это должно быть действительно что-то важное.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Вы тратите мое бесценное время. Это должно быть действительно что-то важное.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (3419,'О да, еще $gодин желающий:одна желающая; разжечь огонь и выковать орудия войны. Конечно же, я возьмусь тебя учить.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','О да, еще $gодин желающий:одна желающая; разжечь огонь и выковать орудия войны. Конечно же, я возьмусь тебя учить.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (3420,'Ты хорошо $gучился:училась;, дитя мое. Отправляйся в Подгород и найди кузнеца по имени Джеймс ван Брюнт. Он научит тебя многому из того, что мне недоступно. Насколько я знаю, он обычно проводит время там, где тренируются воины, кует им оружие и доспехи.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты хорошо $gучился:училась;, дитя мое. Отправляйся в Подгород и найди кузнеца по имени Джеймс ван Брюнт. Он научит тебя многому из того, что мне недоступно. Насколько я знаю, он обычно проводит время там, где тренируются воины, кует им оружие и доспехи.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3421,'Я мечтаю научиться делать оружие и доспехи из костей моих врагов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я мечтаю научиться делать оружие и доспехи из костей моих врагов.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3422,'Не забывай: ты не наковальню молотом убиваешь, а куешь оружие, чтобы убивать врагов. Дай, покажу, как делать правильно.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не забывай: ты не наковальню молотом убиваешь, а куешь оружие, чтобы убивать врагов. Дай, покажу, как делать правильно.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3423,'Я передал тебе все свои знания. Теперь ищи Джеймса ван Брюнта – он сможет научить тебя большему.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я передал тебе все свои знания. Теперь ищи Джеймса ван Брюнта – он сможет научить тебя большему.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (3424,'Э\'ко – это неопределенная форма сверхъестественной силы, а джуджу – ее концентрированная суть. Я знаю сильное заклятие, которое превращает э\'ко в джуджу. Джуджу позволит тебе пользоваться сокровищем Мау\'ари и направлять силу на себя.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Э\'ко – это неопределенная форма сверхъестественной силы, а джуджу – ее концентрированная суть. Я знаю сильное заклятие, которое превращает э\'ко в джуджу. Джуджу позволит тебе пользоваться сокровищем Мау\'ари и направлять силу на себя.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3453,'Ты неплохо управляешься с молотом и наковальней, но этого недостаточно. Пойди поговори с Дейном Линдгреном, он подготовит тебя к тому, чтоб учиться у меня.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты неплохо управляешься с молотом и наковальней, но этого недостаточно. Пойди поговори с Дейном Линдгреном, он подготовит тебя к тому, чтоб учиться у меня.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3454,'Я говорил, что в тебе течет кровь кузнецов, и я был прав. Отправляйся в Стальгорн, в Великую Кузню, и найди там дворфа по имени Бенгус Подземная Кузня. Этой мой учитель – и один из лучших кузнецов, которых я знаю!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я говорил, что в тебе течет кровь кузнецов, и я был прав. Отправляйся в Стальгорн, в Великую Кузню, и найди там дворфа по имени Бенгус Подземная Кузня. Этой мой учитель – и один из лучших кузнецов, которых я знаю!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3456,'Жизнь кузнеца нелегка, но она делает кости стальными, а сердце огненным. Мой папаша был кузнец, а до него дед, в кузницах под Грим Батол. А сейчас и мой сын пошел по нашим стопам, так что мальчишкой можно гордиться.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Жизнь кузнеца нелегка, но она делает кости стальными, а сердце огненным. Мой папаша был кузнец, а до него дед, в кузницах под Грим Батол. А сейчас и мой сын пошел по нашим стопам, так что мальчишкой можно гордиться.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3457,'Прости, $gпарень:девушка;, но тебе еще рано учиться у меня. Лучше сходи к моему сыну Гроуму – он будет рад $gновому ученику:новой ученице;.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Прости, $gпарень:девушка;, но тебе еще рано учиться у меня. Лучше сходи к моему сыну Гроуму – он будет рад $gновому ученику:новой ученице;.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3458,'Да, вы кое-что умеете, но, прежде чем я приму вас, вы должны пройти последнее испытание.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да, вы кое-что умеете, но, прежде чем я приму вас, вы должны пройти последнее испытание.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3459,'Ну да, я б научил тебя ковать всякое. Надевай фартук, хватай молоток – и начнем урок, ага?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ну да, я б научил тебя ковать всякое. Надевай фартук, хватай молоток – и начнем урок, ага?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3460,'Учиться ты умеешь, да и ковать тоже. Я бы тебя хоть сейчас на работу взял, но ты заслуживаешь большего. Пойди поговори с Бенгусом Подземной Кузней. Характер у него тяжелый, но в своем деле он один из лучших.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Учиться ты умеешь, да и ковать тоже. Я бы тебя хоть сейчас на работу взял, но ты заслуживаешь большего. Пойди поговори с Бенгусом Подземной Кузней. Характер у него тяжелый, но в своем деле он один из лучших.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (3461,'Пожалуйста, в следующий раз не появляйся предо мной, как чертик из коробочки. Предупреждай как-нибудь, что ли.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Пожалуйста, в следующий раз не появляйся предо мной, как чертик из коробочки. Предупреждай как-нибудь, что ли.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (3462,'Хмм, ваша работа вполне приемлема, но от своих учеников я ожидаю гораздо большего. Поговорите с кузнецом Аргусом в Златоземье, он преподаст вам основы. Потом возвращайтесь ко мне: я проверю, насколько вы подготовлены.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Хмм, ваша работа вполне приемлема, но от своих учеников я ожидаю гораздо большего. Поговорите с кузнецом Аргусом в Златоземье, он преподаст вам основы. Потом возвращайтесь ко мне: я проверю, насколько вы подготовлены.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (3463,'Да, до меня дошли слухи, что ты заявишься ко мне рано или поздно. Однако я не беру абы кого, прежде надо бы убедиться, отвечаешь ли ты требованиям. $GСогласен:Согласна; ли ты на небольшое испытание?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Да, до меня дошли слухи, что ты заявишься ко мне рано или поздно. Однако я не беру абы кого, прежде надо бы убедиться, отвечаешь ли ты требованиям. $GСогласен:Согласна; ли ты на небольшое испытание?',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (3465,'А теперь уже мне неловко, ведь ничему новому я тебя научить не смогу. Но знаешь, кто сможет? Бенгус Подземная Кузня из Стальгорна, есть такой опытный дворф, мастер горнила. Поищи его возле Великой Кузни, что в Стальгорне, спроси, согласен ли он взять нового ученика.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','А теперь уже мне неловко, ведь ничему новому я тебя научить не смогу. Но знаешь, кто сможет? Бенгус Подземная Кузня из Стальгорна, есть такой опытный дворф, мастер горнила. Поищи его возле Великой Кузни, что в Стальгорне, спроси, согласен ли он взять нового ученика.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`) VALUES (3466,'Если я докажу Сару, что я достоин, у него не останется выбора, кроме как разрешить мне сражаться за одну из его дочерей. Тогда посмотрим, кто из нас будет смеяться.','Держись подальше от Суми и Туми. Они… в общем, они заняты.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если я докажу Сару, что я достоин, у него не останется выбора, кроме как разрешить мне сражаться за одну из его дочерей. Тогда посмотрим, кто из нас будет смеяться.',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Держись подальше от Суми и Туми. Они… в общем, они заняты.',`text1_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3467,'Еще раз придешь ко мне с такой никудышной работой, и я отправлю тебя домой в маленьком железном ящике, закаленном в козлиной моче. Иди поговори с этим идиотом Уг\'током, он тебе больше подходит.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Еще раз придешь ко мне с такой никудышной работой, и я отправлю тебя домой в маленьком железном ящике, закаленном в козлиной моче. Иди поговори с этим идиотом Уг\'током, он тебе больше подходит.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3468,'Так ты считаешь себя $gдостойным:достойной; учиться у меня? У великого Рыка? Да ты всего лишь жалкое ничтожество, пресмыкающееся под моими ногами. Впрочем, взяв себе подмастерье, я мог бы встретить больше приязни со стороны Суми и Туми. Посмотрим, какими крохами умения ты владеешь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Так ты считаешь себя $gдостойным:достойной; учиться у меня? У великого Рыка? Да ты всего лишь жалкое ничтожество, пресмыкающееся под моими ногами. Впрочем, взяв себе подмастерье, я мог бы встретить больше приязни со стороны Суми и Туми. Посмотрим, какими крохами умения ты владеешь.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3471,'Духи привели тебя ко мне… я чувствую их благословение.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Духи привели тебя ко мне… я чувствую их благословение.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3472,'Тебе следует пристальнее внимать голосам духов, $gюноша:девушка;. Ступай в Громовой Утес к Трагу Каменному Копыту. Возможно, он поделится с тобой мудростью.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тебе следует пристальнее внимать голосам духов, $gюноша:девушка;. Ступай в Громовой Утес к Трагу Каменному Копыту. Возможно, он поделится с тобой мудростью.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3473,'Скажите, вы готовы к испытанию, которое я приготовил? Духи говорят мне, что вы справитесь, но вы-то сами верите в них... или в себя?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Скажите, вы готовы к испытанию, которое я приготовил? Духи говорят мне, что вы справитесь, но вы-то сами верите в них... или в себя?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3475,'Наши жизненные пути пересеклись лишь на мгновение. Теперь нам пора расстаться. Я был счастлив потратить время на твое обучение – а теперь с легким сердцем отправляю тебя к следующему наставнику. Его зовут Сару Холодная Ярость, он из Оргриммара. Он научит тебя всему, что тебе нужно знать.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Наши жизненные пути пересеклись лишь на мгновение. Теперь нам пора расстаться. Я был счастлив потратить время на твое обучение – а теперь с легким сердцем отправляю тебя к следующему наставнику. Его зовут Сару Холодная Ярость, он из Оргриммара. Он научит тебя всему, что тебе нужно знать.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3476,'У вас огромный потенциал, но вы должны обрести понимание, прислушаться к зову духов. Только тогда вы будете готовы встать на путь, по которому должно вам следовать. Идите и говорите с Трагом – возможно, вы многому научитесь друг у друга.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','У вас огромный потенциал, но вы должны обрести понимание, прислушаться к зову духов. Только тогда вы будете готовы встать на путь, по которому должно вам следовать. Идите и говорите с Трагом – возможно, вы многому научитесь друг у друга.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3478,'Ты многое $gузнал:узнала;, но тебе еще есть чему поучиться у духов. Я могу указать тебе путь, но идти придется самостоятельно. Отправляйся в Оргриммар. Там ты найдешь Сару Холодную Ярость, он и продолжит твое обучение.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты многое $gузнал:узнала;, но тебе еще есть чему поучиться у духов. Я могу указать тебе путь, но идти придется самостоятельно. Отправляйся в Оргриммар. Там ты найдешь Сару Холодную Ярость, он и продолжит твое обучение.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3479,'У меня нет времени. Поговори с моим студентом Базилем.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','У меня нет времени. Поговори с моим студентом Базилем.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3481,'Ты делаешь весьма достойное снаряжение, даже очень. Отправляйся в город орков – Оргриммар и разыщи кузнеца по имени Сару Холодная Ярость. В чем оркам нельзя отказать, так это в том, что они производят великолепные орудия смерти.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты делаешь весьма достойное снаряжение, даже очень. Отправляйся в город орков – Оргриммар и разыщи кузнеца по имени Сару Холодная Ярость. В чем оркам нельзя отказать, так это в том, что они производят великолепные орудия смерти.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3482,'Мне жаль, $gпарень:девица;, но у тебя просто нет основы, необходимой для изучения того, чему я могу научить. Но не переживай, поговори с моим студентом Ротгатом, он тебя подтянет...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мне жаль, $gпарень:девица;, но у тебя просто нет основы, необходимой для изучения того, чему я могу научить. Но не переживай, поговори с моим студентом Ротгатом, он тебя подтянет...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3485,'Это тебе не игрушки! Иди поговори со Рыком, он снаружи. Может, я и пригрел змею на груди, но с молотом этот тип управляться умеет.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Это тебе не игрушки! Иди поговори со Рыком, он снаружи. Может, я и пригрел змею на груди, но с молотом этот тип управляться умеет.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3487,'Я смотрю, ты уже знаешь о стали больше меня самого. Прекрасно, прекрасно, именно для этого я и был тебе нужен. Теперь отправляйся в джунгли к югу от людских владений, в поселение Пиратская Бухта. Там отыщи гоблина по имени Брикк Мастерец. Я не очень-то люблю гоблинов, но вынужден признать, что его знания о металлах превосходят всякое воображение.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я смотрю, ты уже знаешь о стали больше меня самого. Прекрасно, прекрасно, именно для этого я и был тебе нужен. Теперь отправляйся в джунгли к югу от людских владений, в поселение Пиратская Бухта. Там отыщи гоблина по имени Брикк Мастерец. Я не очень-то люблю гоблинов, но вынужден признать, что его знания о металлах превосходят всякое воображение.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3488,'Да? Разумеется, я кузнец! А вы как думали, только дворфы могут по наковальне колотить? Ну и ладно! Вот пусть вам дворф и помогает!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да? Разумеется, я кузнец! А вы как думали, только дворфы могут по наковальне колотить? Ну и ладно! Вот пусть вам дворф и помогает!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3489,'Ты шутишь? Ты, должно быть, шутишь! Или так, или ты думаешь, что я клоун, пришедший развлечь тебя. Это ты думаешь? Что я клоун? Ха, да! Ты думаешь, что я клоун, да!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты шутишь? Ты, должно быть, шутишь! Или так, или ты думаешь, что я клоун, пришедший развлечь тебя. Это ты думаешь? Что я клоун? Ха, да! Ты думаешь, что я клоун, да!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3490,'Ты ведешь себя так, словно этот хлам может кого-то впечатлить. Нет, конечно, он очень даже ничего, но вещи такого уровня встречаются везде и всюду. Вот что: сумей меня удивить, и я научу тебя таким вещам, которые заставляют дворфов улыбаться во сне.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты ведешь себя так, словно этот хлам может кого-то впечатлить. Нет, конечно, он очень даже ничего, но вещи такого уровня встречаются везде и всюду. Вот что: сумей меня удивить, и я научу тебя таким вещам, которые заставляют дворфов улыбаться во сне.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3494,'Здесь, в приюте Странников, охотничьи навыки особенно в цене. Хочешь ко мне в ученики? Это еще заслужить надо.$B$BОтнесись серьезно к этому испытанию, $Gпарень:девица;!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здесь, в приюте Странников, охотничьи навыки особенно в цене. Хочешь ко мне в ученики? Это еще заслужить надо.$B$BОтнесись серьезно к этому испытанию, $Gпарень:девица;!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3496,'С удовольствием… прошу лишь, позволь мне растянуть удовольствие еще на минутку.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','С удовольствием… прошу лишь, позволь мне растянуть удовольствие еще на минутку.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (3513,'Они в Квартале Магов. Увидишь страшный череп – тебе туда.','Они в Квартале Магов. Увидишь страшный череп – тебе туда.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Они в Квартале Магов. Увидишь страшный череп – тебе туда.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Они в Квартале Магов. Увидишь страшный череп – тебе туда.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (3514,'Банк находится в центральной башне Торгового квартала. Мимо не пройдешь.','Банк находится в центральной башне Торгового квартала. Мимо не пройдешь.','Я своим единственным глазом и то лучше вижу! Банк в самом центре Подгорода!','Я своим единственным глазом и то лучше вижу! Банк в самом центре Подгорода!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Банк находится в центральной башне Торгового квартала. Мимо не пройдешь.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Банк находится в центральной башне Торгового квартала. Мимо не пройдешь.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Я своим единственным глазом и то лучше вижу! Банк в самом центре Подгорода!',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Я своим единственным глазом и то лучше вижу! Банк в самом центре Подгорода!',`text1_1_loc8`);
