INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (3515,'Майкл Гарретт на верхнем круге в Торговом квартале.','Майкл Гарретт на верхнем круге в Торговом квартале.','Летучие мыши – на верхнем уровне Торгового квартала.','Летучие мыши – на верхнем уровне Торгового квартала.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Майкл Гарретт на верхнем круге в Торговом квартале.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Майкл Гарретт на верхнем круге в Торговом квартале.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Летучие мыши – на верхнем уровне Торгового квартала.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Летучие мыши – на верхнем уровне Торгового квартала.',`text1_1_loc8`);
