INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (3516,'Ага, тебе нужен Кристофер Дракул из Торгового квартала. Он на восточной платформе.','Ага, тебе нужен Кристофер Дракул из Торгового квартала. Он на восточной платформе.','А нас в гильдию возьмешь? Нет? Ну ладно, ищи регистратора на восточной платформе Торгового квартала.','А нас в гильдию возьмешь? Нет? Ну ладно, ищи регистратора на восточной платформе Торгового квартала.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ага, тебе нужен Кристофер Дракул из Торгового квартала. Он на восточной платформе.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ага, тебе нужен Кристофер Дракул из Торгового квартала. Он на восточной платформе.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','А нас в гильдию возьмешь? Нет? Ну ладно, ищи регистратора на восточной платформе Торгового квартала.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','А нас в гильдию возьмешь? Нет? Ну ладно, ищи регистратора на восточной платформе Торгового квартала.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text1_0_loc8`,`text1_1_loc8`) VALUES (3517,'Нет покоя грешным душам, но с тобой, вроде бы, все в порядке. Норман держит свою таверну на верхнем кольце Торгового квартала.','Нет покоя грешным душам, но с тобой, вроде бы, все в порядке. Норман держит свою таверну на верхнем кольце Торгового квартала.') ON DUPLICATE KEY UPDATE `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Нет покоя грешным душам, но с тобой, вроде бы, все в порядке. Норман держит свою таверну на верхнем кольце Торгового квартала.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Нет покоя грешным душам, но с тобой, вроде бы, все в порядке. Норман держит свою таверну на верхнем кольце Торгового квартала.',`text1_1_loc8`);
