INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (3518,'Почтовый ящик в центре города. Торговый квартал, верхнее кольцо… рядом с таверной.','Почтовый ящик в центре города. Торговый квартал, верхнее кольцо… рядом с таверной.','О, кстати, надо глянуть, не продан ли еще наш мозго… как там его? А, мозгоруб! В общем, почтовый ящик возле таверны на верхнем кольце Торгового квартала.','О, кстати, надо глянуть, не продан ли еще наш мозго… как там его? А, мозгоруб! В общем, почтовый ящик возле таверны на верхнем кольце Торгового квартала.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Почтовый ящик в центре города. Торговый квартал, верхнее кольцо… рядом с таверной.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Почтовый ящик в центре города. Торговый квартал, верхнее кольцо… рядом с таверной.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','О, кстати, надо глянуть, не продан ли еще наш мозго… как там его? А, мозгоруб! В общем, почтовый ящик возле таверны на верхнем кольце Торгового квартала.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','О, кстати, надо глянуть, не продан ли еще наш мозго… как там его? А, мозгоруб! В общем, почтовый ящик возле таверны на верхнем кольце Торгового квартала.',`text1_1_loc8`);
