INSERT INTO `locales_npc_text` (`id`,`text1_0_loc8`,`text1_1_loc8`) VALUES (3526,'Мы как раз хотим завести гончую Скверны! Мы будем ее кормить, учить и играть с ней. А чернокнижники у нас живут в Квартале Магов на внешнем кольце города.','Мы как раз хотим завести гончую Скверны! Мы будем ее кормить, учить и играть с ней. А чернокнижники у нас живут в Квартале Магов на внешнем кольце города.') ON DUPLICATE KEY UPDATE `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Мы как раз хотим завести гончую Скверны! Мы будем ее кормить, учить и играть с ней. А чернокнижники у нас живут в Квартале Магов на внешнем кольце города.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Мы как раз хотим завести гончую Скверны! Мы будем ее кормить, учить и играть с ней. А чернокнижники у нас живут в Квартале Магов на внешнем кольце города.',`text1_1_loc8`);
