INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (3536,'Он на внутреннем кольце Квартала Разбойников.','Он на внутреннем кольце Квартала Разбойников.','Кожевничеству учит Артур Мур. Он живет на внутреннем кольце Квартала Разбойников.','Кожевничеству учит Артур Мур. Он живет на внутреннем кольце Квартала Разбойников.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Он на внутреннем кольце Квартала Разбойников.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Он на внутреннем кольце Квартала Разбойников.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Кожевничеству учит Артур Мур. Он живет на внутреннем кольце Квартала Разбойников.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Кожевничеству учит Артур Мур. Он живет на внутреннем кольце Квартала Разбойников.',`text1_1_loc8`);
