INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (3537,'Иди на внутреннее кольцо Квартала Воинов. Там Бром Килиан.','Иди на внутреннее кольцо Квартала Воинов. Там Бром Килиан.','Бром Килиан отлично научит тебя копать. Он во внутреннем круге Квартала Воинов.','Бром Килиан отлично научит тебя копать. Он во внутреннем круге Квартала Воинов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Иди на внутреннее кольцо Квартала Воинов. Там Бром Килиан.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Иди на внутреннее кольцо Квартала Воинов. Там Бром Килиан.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Бром Килиан отлично научит тебя копать. Он во внутреннем круге Квартала Воинов.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Бром Килиан отлично научит тебя копать. Он во внутреннем круге Квартала Воинов.',`text1_1_loc8`);
