INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (3538,'Киллиан Хаги учит снимать шкуры. Он живет на внутреннем кольце Квартала Разбойников.','Киллиан Хаги учит снимать шкуры. Он живет на внутреннем кольце Квартала Разбойников.','У нас есть крюк для снятия шкур. Киллиан Хаги дал, он учит снимать шкуры. У тебя хорошая шкура. Иди в Квартал Разбойников, на внутреннее кольцо.','У нас есть крюк для снятия шкур. Киллиан Хаги дал, он учит снимать шкуры. У тебя хорошая шкура. Иди в Квартал Разбойников, на внутреннее кольцо.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Киллиан Хаги учит снимать шкуры. Он живет на внутреннем кольце Квартала Разбойников.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Киллиан Хаги учит снимать шкуры. Он живет на внутреннем кольце Квартала Разбойников.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','У нас есть крюк для снятия шкур. Киллиан Хаги дал, он учит снимать шкуры. У тебя хорошая шкура. Иди в Квартал Разбойников, на внутреннее кольцо.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','У нас есть крюк для снятия шкур. Киллиан Хаги дал, он учит снимать шкуры. У тебя хорошая шкура. Иди в Квартал Разбойников, на внутреннее кольцо.',`text1_1_loc8`);
