INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (3539,'Тебе нужен Джозеф Грегориан. Ищи его в Квартале Магов на внутреннем берегу зеленого канала.','Тебе нужен Джозеф Грегориан. Ищи его в Квартале Магов на внутреннем берегу зеленого канала.','Хм, а ведь хорошая идея! Может, пойдем туда, заменим кое-какой шовный материал? Он хорошо шьет. Джозефа Грегориана можно найти во внутреннем круге Квартала Магов.','Хм, а ведь хорошая идея! Может, пойдем туда, заменим кое-какой шовный материал? Он хорошо шьет. Джозефа Грегориана можно найти во внутреннем круге Квартала Магов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тебе нужен Джозеф Грегориан. Ищи его в Квартале Магов на внутреннем берегу зеленого канала.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Тебе нужен Джозеф Грегориан. Ищи его в Квартале Магов на внутреннем берегу зеленого канала.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Хм, а ведь хорошая идея! Может, пойдем туда, заменим кое-какой шовный материал? Он хорошо шьет. Джозефа Грегориана можно найти во внутреннем круге Квартала Магов.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Хм, а ведь хорошая идея! Может, пойдем туда, заменим кое-какой шовный материал? Он хорошо шьет. Джозефа Грегориана можно найти во внутреннем круге Квартала Магов.',`text1_1_loc8`);
