INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (3557,'Это труп орка-воина.$B$BНесомненно, она погибла в бою. Противником, по всей видимости, был местный иглогрив.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Это труп орка-воина.$B$BНесомненно, она погибла в бою. Противником, по всей видимости, был местный иглогрив.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (3558,'Вы переворачиваете тело орка и ищете на нем следы от оружия и заклинаний. Ее доспехи разбиты в клочья, а лицо скрыто под спутанными волосами.$B$BПо некоторым приметам, которые сообщил вам Манкрик, вы опознаете в убитой его жену.$B$BНесомненно, он будет опечален такими новостями, но вы убеждены, что ему следует знать правду.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Вы переворачиваете тело орка и ищете на нем следы от оружия и заклинаний. Ее доспехи разбиты в клочья, а лицо скрыто под спутанными волосами.$B$BПо некоторым приметам, которые сообщил вам Манкрик, вы опознаете в убитой его жену.$B$BНесомненно, он будет опечален такими новостями, но вы убеждены, что ему следует знать правду.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3573,'Приветствую, $gюный:юная:c; |3-6($c).') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приветствую, $gюный:юная:c; |3-6($c).',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3575,'Да, $gюноша:девушка;, тебе не нужно убеждать меня в этом. У нас с военным вождем богатая история. Однако твоя преданность замечена. $B$BКак я говорил, Ренд нашел новый дом для своего народа, а я был среди тех, кто устало следовал за ним. $B$BОдин конфликт приводил к другому... к бесчисленному множеству других. В битвах за Пик Черной горы, которые вели между собой клан Черной горы и дворфы клана Черного Железа, погибли оба моих сына. Тогда я и осознал, что моя жизнь в клане Черной горы подошла к концу.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да, $gюноша:девушка;, тебе не нужно убеждать меня в этом. У нас с военным вождем богатая история. Однако твоя преданность замечена. $B$BКак я говорил, Ренд нашел новый дом для своего народа, а я был среди тех, кто устало следовал за ним. $B$BОдин конфликт приводил к другому... к бесчисленному множеству других. В битвах за Пик Черной горы, которые вели между собой клан Черной горы и дворфы клана Черного Железа, погибли оба моих сына. Тогда я и осознал, что моя жизнь в клане Черной горы подошла к концу.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3576,'И я ушел из клана Черной горы. Смерть моих сыновей была не напрасной. Я не смог далее служить этому глупому и жадному до власти Ренду.$B$BЯ скрылся в лесах Лордерона и стал жить отшельником неподалеку от Дольного Очага.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','И я ушел из клана Черной горы. Смерть моих сыновей была не напрасной. Я не смог далее служить этому глупому и жадному до власти Ренду.$B$BЯ скрылся в лесах Лордерона и стал жить отшельником неподалеку от Дольного Очага.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3577,'<Эйтригг смеется.>$B$BДитя мое, в этом мире не всегда царил хаос. Я помню те времена, когда Плеть еще не вторглась сюда, когда эту часть Лордерона еще не называли Чумными землями...$B$BВ те годы Тралл спас мне жизнь – и я присоединился к возрожденной Орде... Но я отвлекся. Я расскажу тебе эту историю когда-нибудь потом. Да, потом... когда-нибудь...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Эйтригг смеется.>$B$BДитя мое, в этом мире не всегда царил хаос. Я помню те времена, когда Плеть еще не вторглась сюда, когда эту часть Лордерона еще не называли Чумными землями...$B$BВ те годы Тралл спас мне жизнь – и я присоединился к возрожденной Орде... Но я отвлекся. Я расскажу тебе эту историю когда-нибудь потом. Да, потом... когда-нибудь...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3578,'Да, конечно. Возможно, когда-нибудь ты сможешь передать послание одному моему старому другу. Я слыхал, он все еще странствует в этих лесах.$B$B*Эйтригг на миг склоняет голову, словно молится.*$B$BЗначит, Ренд... Ренд со своим братом Меймом правят Черной скалой и постоянно конфликтуют с дворфами Черного Железа. Им удалось вытеснить дворфов из верхней части города, но только после появления драконов и смерти Мейма.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да, конечно. Возможно, когда-нибудь ты сможешь передать послание одному моему старому другу. Я слыхал, он все еще странствует в этих лесах.$B$B*Эйтригг на миг склоняет голову, словно молится.*$B$BЗначит, Ренд... Ренд со своим братом Меймом правят Черной скалой и постоянно конфликтуют с дворфами Черного Железа. Им удалось вытеснить дворфов из верхней части города, но только после появления драконов и смерти Мейма.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3580,'Возможно. А теперь иди, $gюноша:девушка;. Ищи совета у Вождя. Он непременно захочет узнать о твоем открытии.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Возможно. А теперь иди, $gюноша:девушка;. Ищи совета у Вождя. Он непременно захочет узнать о твоем открытии.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3583,'Пройдя Долину Испытаний, любой слабак превращается в воина, достойного служить Орде… или навсегда остается лежать под палящим солнцем пустыни.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Пройдя Долину Испытаний, любой слабак превращается в воина, достойного служить Орде… или навсегда остается лежать под палящим солнцем пустыни.',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (3591,'Инфернал – одно из самых могущественных демонических существ, которых чернокнижник может призвать себе на помощь. Это очень сильное и выносливое создание, наносящее врагам смертельные раны. Поместив сущность инфернала в свое оружие, вы приобретете некоторые из его достоинств: большой запас здоровья, ускоренную регенерацию и тому подобное.$B$BЕсли вы хотите узнать больше о гончих Скверны, поговорите с Витулой, она сидит напротив меня.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Инфернал – одно из самых могущественных демонических существ, которых чернокнижник может призвать себе на помощь. Это очень сильное и выносливое создание, наносящее врагам смертельные раны. Поместив сущность инфернала в свое оружие, вы приобретете некоторые из его достоинств: большой запас здоровья, ускоренную регенерацию и тому подобное.$B$BЕсли вы хотите узнать больше о гончих Скверны, поговорите с Витулой, она сидит напротив меня.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (3592,'Гончая Скверны... да, очень злобная тварь. Она не так сильна, как инфернал, но всякий чернокнижник знает, что сила – это не главное. Иначе бы мы все выбирали путь воина...$B$BГончая Скверны очень быстра и умеет похищать ману. В ней кроется таинственная мощь...$B$BЕсли тебя больше интересуют огненные големы, поговори с Магис, она тут рядом.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Гончая Скверны... да, очень злобная тварь. Она не так сильна, как инфернал, но всякий чернокнижник знает, что сила – это не главное. Иначе бы мы все выбирали путь воина...$B$BГончая Скверны очень быстра и умеет похищать ману. В ней кроется таинственная мощь...$B$BЕсли тебя больше интересуют огненные големы, поговори с Магис, она тут рядом.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3633,'Прошу, помоги мне, $gбратец:сестрица;…$B$BСкоро я умру, и хотя страдания мои велики, я знаю, что смерть будет всего лишь раз. Но дикая природа, $gбратец:сестрица;… природа тоже страдает и не знает облегчения… Я прошу твоей помощи, я на последнем издыхании…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Прошу, помоги мне, $gбратец:сестрица;…$B$BСкоро я умру, и хотя страдания мои велики, я знаю, что смерть будет всего лишь раз. Но дикая природа, $gбратец:сестрица;… природа тоже страдает и не знает облегчения… Я прошу твоей помощи, я на последнем издыхании…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3634,'Да, |3-6($r), я умею говорить на понятном тебе языке. Мы не животные, хотя твои сородичи и считают нас таковыми. Впрочем, все наши разногласия меркнут перед бедой, постигшей эти земли. Прошу тебя, забудь о вражде наших видов и услышь мою предсмертную мольбу.$B$BЯ прибыл в эти земли, чтобы излечить их. Если ты не поможешь мне, все будет напрасно. На последнем своем дыхании прошу тебя: помоги!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да, |3-6($r), я умею говорить на понятном тебе языке. Мы не животные, хотя твои сородичи и считают нас таковыми. Впрочем, все наши разногласия меркнут перед бедой, постигшей эти земли. Прошу тебя, забудь о вражде наших видов и услышь мою предсмертную мольбу.$B$BЯ прибыл в эти земли, чтобы излечить их. Если ты не поможешь мне, все будет напрасно. На последнем своем дыхании прошу тебя: помоги!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3653,'Я – городской чиновник, работаю над переписью населения Подгорода. Со времени нашего освобождения от Плети мы стараемся тщательно отслеживать численность населения города. Благодаря системе чар и усиленной работе над собой я способен осуществлять доступ к этим данным. Если у вас связанное с этим дело – изложите его, пожалуйста. Во всяком случае, вам следовало бы это знать.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я – городской чиновник, работаю над переписью населения Подгорода. Со времени нашего освобождения от Плети мы стараемся тщательно отслеживать численность населения города. Благодаря системе чар и усиленной работе над собой я способен осуществлять доступ к этим данным. Если у вас связанное с этим дело – изложите его, пожалуйста. Во всяком случае, вам следовало бы это знать.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3654,'Вождь повелел мне изучать все виды оружия и доспехов. Он прислал меня в Степи, где сливаются культуры орков и тауренов, чтобы я повстречал как можно больше путешественников и узнал как можно больше об этих землях.$B$BОн говорит, что даже у самых жалких народов есть чему поучиться… даже у иглогривов и кентавров.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вождь повелел мне изучать все виды оружия и доспехов. Он прислал меня в Степи, где сливаются культуры орков и тауренов, чтобы я повстречал как можно больше путешественников и узнал как можно больше об этих землях.$B$BОн говорит, что даже у самых жалких народов есть чему поучиться… даже у иглогривов и кентавров.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3657,'Добро пожаловать в Штормград! Я сотрудник городского бюро переписи населения. Если тебе требуется справка о местонахождении того или иного гражданина, я могу тебе помочь. Познания в области тайной магии позволяют мне мгновенно подавать запросы в архив.$B$BЕсли же у тебя есть какое-то особое дело ко мне, будь $gдобр:добра; изложить его!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать в Штормград! Я сотрудник городского бюро переписи населения. Если тебе требуется справка о местонахождении того или иного гражданина, я могу тебе помочь. Познания в области тайной магии позволяют мне мгновенно подавать запросы в архив.$B$BЕсли же у тебя есть какое-то особое дело ко мне, будь $gдобр:добра; изложить его!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3660,'Как? Ну, это длинная история.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Как? Ну, это длинная история.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3661,'Ну, тогда слушай! Итак, я спустился в лавовые ямы Огненного пути – надо было испытать жаропрочный костюм. Все шло отлично. Я даже искупался в лаве и ничуточки не пострадал!$B$BИ вот плыву я на спине, думаю о своем, и вдруг откуда ни возьмись эта тварь – и проглотила меня! Если бы не жаропрочный костюм и дозатор еды, мне бы и конец пришел!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ну, тогда слушай! Итак, я спустился в лавовые ямы Огненного пути – надо было испытать жаропрочный костюм. Все шло отлично. Я даже искупался в лаве и ничуточки не пострадал!$B$BИ вот плыву я на спине, думаю о своем, и вдруг откуда ни возьмись эта тварь – и проглотила меня! Если бы не жаропрочный костюм и дозатор еды, мне бы и конец пришел!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3662,'Похоже, ты мне не очень-то веришь, но именно так оно и было!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Похоже, ты мне не очень-то веришь, но именно так оно и было!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3663,'Я всего пару минут как спасся из пасти этой твари, а меня уже попрекают за плохие манеры? $GГосподин:дамочка;, я б вам дал по шее за такую глупость, если бы это не вы меня спасли! $B$BНу да ладно! Спасибо за помощь! Может, я вам тоже чем-то могу помочь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я всего пару минут как спасся из пасти этой твари, а меня уже попрекают за плохие манеры? $GГосподин:дамочка;, я б вам дал по шее за такую глупость, если бы это не вы меня спасли! $B$BНу да ладно! Спасибо за помощь! Может, я вам тоже чем-то могу помочь?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3665,'Ну так как, передашь мое сообщение?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ну так как, передашь мое сообщение?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3666,'Хочешь купить таракана?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Хочешь купить таракана?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`,`text2_1_loc8`,`text3_1_loc8`,`text4_1_loc8`) VALUES (3668,'Мое время истекает… наше общее время…','Джон, дорогой, ты где?','Что случилось? Мне так… холодно…','Тссс… Чуешь что-нибудь?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мое время истекает… наше общее время…',`text0_1_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Джон, дорогой, ты где?',`text2_1_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','Что случилось? Мне так… холодно…',`text3_1_loc8`), `text4_1_loc8`=IF(`text4_1_loc8` IS NULL OR `text4_1_loc8`='','Тссс… Чуешь что-нибудь?',`text4_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3673,'Братство Тория не тратит свое время на всякую мелочь. Ступай отсюда.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Братство Тория не тратит свое время на всякую мелочь. Ступай отсюда.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3674,'Для искусного ремесленника вроде меня это простая задача.$B$BСамое сложное в изготовлении изделий из шкур и панцирей животных – это добыча материала. Если ты принесешь мне безупречную шкуру этого зверя, я изготовлю из нее несколько полезных предметов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Для искусного ремесленника вроде меня это простая задача.$B$BСамое сложное в изготовлении изделий из шкур и панцирей животных – это добыча материала. Если ты принесешь мне безупречную шкуру этого зверя, я изготовлю из нее несколько полезных предметов.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3676,'Вы правда принесли мне эту шкуру? Ладно… Позвольте показать вам…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вы правда принесли мне эту шкуру? Ладно… Позвольте показать вам…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3693,'На обложке книги красивым почерком выведено название: "Дневник Морин Далсон".') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','На обложке книги красивым почерком выведено название: "Дневник Морин Далсон".',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3756,'В этом мире у меня немного времени, но, волею Света, его хватит, чтобы исполнить предначертание. Когда ты встретишься с бароном Ривендером, я буду с тобой.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','В этом мире у меня немного времени, но, волею Света, его хватит, чтобы исполнить предначертание. Когда ты встретишься с бароном Ривендером, я буду с тобой.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3758,'Не испытывай мое терпение, $gсмертный:смертная;.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не испытывай мое терпение, $gсмертный:смертная;.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3759,'Прикуси язык, |3-6($r), пока я не отрезал его и не пустил на шарф.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Прикуси язык, |3-6($r), пока я не отрезал его и не пустил на шарф.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3760,'Что я делаю, ну конечно. Я размышляю. Я плачу. Я ненавижу. Я составляю план. Когда цикл завершается, я снова размышляю. Что ты от меня хочешь? У меня много дел.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что я делаю, ну конечно. Я размышляю. Я плачу. Я ненавижу. Я составляю план. Когда цикл завершается, я снова размышляю. Что ты от меня хочешь? У меня много дел.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3761,'Ты?$B$B<Лоракс смеется.> $B$BСомневаюсь!$B$BЯ остаюсь в этих руинах и вижу сны. Сны о том дне, когда я поймаю этого презренного вора, Горалука Треснувшую Наковальню.$B$BМы с ним заключили сделку. А он ее нарушил. Он предал меня.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты?$B$B<Лоракс смеется.> $B$BСомневаюсь!$B$BЯ остаюсь в этих руинах и вижу сны. Сны о том дне, когда я поймаю этого презренного вора, Горалука Треснувшую Наковальню.$B$BМы с ним заключили сделку. А он ее нарушил. Он предал меня.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3762,'Я научу его кузнечным секретам демонов – в обмен на его душу. Конечно, душа орка Черной горы стоит недорого, но все-таки это душа.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я научу его кузнечным секретам демонов – в обмен на его душу. Конечно, душа орка Черной горы стоит недорого, но все-таки это душа.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3763,'Он взял некованую руническую кирасу, из которой можно сделать выкованную демоном, и сбежал, не заплатив. Он дурак, а я вот нет... Этот кусок металла бесполезен без соответствующих знаний и инструкций по их применению.$B$BИнтересно... Вот сейчас он, наверное, сидит на своем Пике Черной горы и пытается сделать из этой заготовки что-нибудь полезное... Высунуться оттуда он точно не посмеет!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Он взял некованую руническую кирасу, из которой можно сделать выкованную демоном, и сбежал, не заплатив. Он дурак, а я вот нет... Этот кусок металла бесполезен без соответствующих знаний и инструкций по их применению.$B$BИнтересно... Вот сейчас он, наверное, сидит на своем Пике Черной горы и пытается сделать из этой заготовки что-нибудь полезное... Высунуться оттуда он точно не посмеет!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3797,'Я… я серьезно ранен…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я… я серьезно ранен…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3798,'Слушай, |3-6($r). Слушай внимательно…$B$BВсадники прилетели ночью, верхом на черных драконах. Они ударили внезапно и точно, забрали молодых дракончиков – таких как я – и скрылись в ночи.$B$BЯ с ужасом наблюдал, как они ставят жуткие опыты над моими братьями и сестрами. Из наших душ хотели создать разноцветных драконов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Слушай, |3-6($r). Слушай внимательно…$B$BВсадники прилетели ночью, верхом на черных драконах. Они ударили внезапно и точно, забрали молодых дракончиков – таких как я – и скрылись в ночи.$B$BЯ с ужасом наблюдал, как они ставят жуткие опыты над моими братьями и сестрами. Из наших душ хотели создать разноцветных драконов.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3799,'Нефариан приказал немедленно умертвить этих непонятных существ, но его мерзкие твари сначала решили хорошенько нас помучить.$B$BОкончательно сломив нас, они взяли то, что от нас осталось, и бросили этим головорезам. Наши тела служили снарядами для их грязной игры. Нас бросали в лаву или, что еще хуже, прямо в лапы кровожадного легиона.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Нефариан приказал немедленно умертвить этих непонятных существ, но его мерзкие твари сначала решили хорошенько нас помучить.$B$BОкончательно сломив нас, они взяли то, что от нас осталось, и бросили этим головорезам. Наши тела служили снарядами для их грязной игры. Нас бросали в лаву или, что еще хуже, прямо в лапы кровожадного легиона.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3800,'Ты $gпришел:пришла; как раз тогда, когда они собирались сбросить меня к тем адским тварям внизу – за это тебе большое спасибо. Возможно, я или, скорее, мы, синие драконы, сможем помочь тебе?$B$BТы $gпрошел:прошла:r; столь долгий путь, |3-6($r), столь многим $gрисковал:рисковала;. Пойдешь ли ты еще дальше и сразишься с Нефарианом и его легионом из Черной горы?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты $gпришел:пришла; как раз тогда, когда они собирались сбросить меня к тем адским тварям внизу – за это тебе большое спасибо. Возможно, я или, скорее, мы, синие драконы, сможем помочь тебе?$B$BТы $gпрошел:прошла:r; столь долгий путь, |3-6($r), столь многим $gрисковал:рисковала;. Пойдешь ли ты еще дальше и сразишься с Нефарианом и его легионом из Черной горы?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3801,'Если ты $gпришел:пришла; охотиться на драконов – будь $gмоим гостем:моей гостьей;. Кстати, по какому адресу мне отправлять соболезнования?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если ты $gпришел:пришла; охотиться на драконов – будь $gмоим гостем:моей гостьей;. Кстати, по какому адресу мне отправлять соболезнования?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3802,'На твой запах сбегутся все окрестные драконы! Говори скорее, чего тебе надо!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','На твой запах сбегутся все окрестные драконы! Говори скорее, чего тебе надо!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3803,'Духи сказали мне, что ты придешь, что станешь искать меня по какой-то причине, которая, может статься, не будет известна даже тебе. Итак, ты знаешь, зачем $gпришел:пришла;?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Духи сказали мне, что ты придешь, что станешь искать меня по какой-то причине, которая, может статься, не будет известна даже тебе. Итак, ты знаешь, зачем $gпришел:пришла;?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (3804,'Привет! Меня зовут Сара. Чем могу помочь?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Привет! Меня зовут Сара. Чем могу помочь?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (3805,'Лес поведал мне о твоем появлении, но не о причинах твоего пребывания здесь. Так расскажи мне $gсам:сама;.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Лес поведал мне о твоем появлении, но не о причинах твоего пребывания здесь. Так расскажи мне $gсам:сама;.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3806,'Как жизнь, дружище?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Как жизнь, дружище?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text1_0_loc8`,`text1_1_loc8`) VALUES (3813,'$GСлышал:Слышала; про поезд, а? Ну и классно же на нем кататься! Он находится в дальней части Квартала Дворфов. О, главное – руки-ноги на ходу не высовывай!','$GСлышал:Слышала; про поезд, а? Ну и классно же на нем кататься! Он находится в дальней части Квартала Дворфов. О, главное – руки-ноги на ходу не высовывай!') ON DUPLICATE KEY UPDATE `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','$GСлышал:Слышала; про поезд, а? Ну и классно же на нем кататься! Он находится в дальней части Квартала Дворфов. О, главное – руки-ноги на ходу не высовывай!',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','$GСлышал:Слышала; про поезд, а? Ну и классно же на нем кататься! Он находится в дальней части Квартала Дворфов. О, главное – руки-ноги на ходу не высовывай!',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (3814,'Ну да, все хотят покататься на поезде, это тебе не ерунда какая-нибудь. Значит, так: поезд отходит из Города Механиков, от Врат Стальгорна прямо на восток.','Ну да, все хотят покататься на поезде, это тебе не ерунда какая-нибудь. Значит, так: поезд отходит из Города Механиков, от Врат Стальгорна прямо на восток.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ну да, все хотят покататься на поезде, это тебе не ерунда какая-нибудь. Значит, так: поезд отходит из Города Механиков, от Врат Стальгорна прямо на восток.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ну да, все хотят покататься на поезде, это тебе не ерунда какая-нибудь. Значит, так: поезд отходит из Города Механиков, от Врат Стальгорна прямо на восток.',`text0_1_loc8`);
