INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (3833,'Один из них открылся на Террасе торговцев. Если ты будешь держать свой путь юго-восточнее банка, то легко его найдешь.','Один из них открылся на Террасе торговцев. Если ты будешь держать свой путь юго-восточнее банка, то легко его найдешь.','Ох уж эта повсеместная жажда обогащения. Ну что же, удача тебе улыбнулась, ведь на Террасе торговцев ты найдешь аукционный дом.','Ох уж эта повсеместная жажда обогащения. Ну что же, фортуна тебе улыбнулась – ведь на Террасе торговцев ты найдешь аукционный дом.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Один из них открылся на Террасе торговцев. Если ты будешь держать свой путь юго-восточнее банка, то легко его найдешь.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Один из них открылся на Террасе торговцев. Если ты будешь держать свой путь юго-восточнее банка, то легко его найдешь.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Ох уж эта повсеместная жажда обогащения. Ну что же, удача тебе улыбнулась, ведь на Террасе торговцев ты найдешь аукционный дом.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Ох уж эта повсеместная жажда обогащения. Ну что же, фортуна тебе улыбнулась – ведь на Террасе торговцев ты найдешь аукционный дом.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text1_0_loc8`,`text1_1_loc8`) VALUES (3834,'Еще один предприниматель, а? Ну что ж, аукционный дом находится в Торговом квартале. Недалеко от банка.','Еще один предприниматель, а? Ну что ж, аукционный дом находится в Торговом квартале. Недалеко от банка.') ON DUPLICATE KEY UPDATE `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Еще один предприниматель, а? Ну что ж, аукционный дом находится в Торговом квартале. Недалеко от банка.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Еще один предприниматель, а? Ну что ж, аукционный дом находится в Торговом квартале. Недалеко от банка.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3855,'Предположительно существует. Подобный панцирь может принадлежать лишь большому всецветному дракониду или дракону.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Предположительно существует. Подобный панцирь может принадлежать лишь большому всецветному дракониду или дракону.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3856,'Основные разновидности мелких разноцветных драконов: дракончики, детеныши драконов, дракониды.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Основные разновидности мелких разноцветных драконов: дракончики, детеныши драконов, дракониды.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3857,'Легенда гласит, что в местах сильных конфликтов, на территории того, что сейчас известно как Чумные земли, чистые и священные источники воды могут начать бить из земли. Воду из этих источников называют "Кровь героев", как ремесленники, так и простой народ, – в честь тех, кто пал в войне против Плети.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Легенда гласит, что в местах сильных конфликтов, на территории того, что сейчас известно как Чумные земли, чистые и священные источники воды могут начать бить из земли. Воду из этих источников называют "Кровь героев", как ремесленники, так и простой народ, – в честь тех, кто пал в войне против Плети.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3859,'Этот предмет использовался семьей Баровых из Некроситета в качестве зеркала душ. Ценный подарок.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Этот предмет использовался семьей Баровых из Некроситета в качестве зеркала душ. Ценный подарок.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (3865,'Мне так холодно… И так голодно…$b$bМой бедный друг, я надеюсь, ты упокоился с миром. Мне невыносима одна мысль о том, что они могли сотворить с тобою.$b$bЭй! Вы, там! Пожалуйста, помогите мне выбраться! У кого-то из них есть ключ, не могли бы вы его найти? Если найдете, я смогу убежать. Трей наверняка уже мертв, но кто знает, может, еще не поздно! Пожалуйста, помогите!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мне так холодно… И так голодно…$b$bМой бедный друг, я надеюсь, ты упокоился с миром. Мне невыносима одна мысль о том, что они могли сотворить с тобою.$b$bЭй! Вы, там! Пожалуйста, помогите мне выбраться! У кого-то из них есть ключ, не могли бы вы его найти? Если найдете, я смогу убежать. Трей наверняка уже мертв, но кто знает, может, еще не поздно! Пожалуйста, помогите!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`,`text2_0_loc8`,`text2_1_loc8`,`text3_0_loc8`,`text3_1_loc8`,`text4_0_loc8`,`text4_1_loc8`) VALUES (3873,'Спасибо! Вы освободили меня!','Спасибо! Вы освободили меня!','О, спасибо! Как же долго длился этот кошмар…','О, спасибо! Как же долго длился этот кошмар…','Наконец-то моя душа свободна!','Наконец-то моя душа свободна!','Спасибо! Битва за Дарроушир принесла мне погибель, но ты $gосвободил:освободила; меня!','Спасибо! Битва за Дарроушир принесла мне погибель, но ты $gосвободил:освободила; меня!','Ах! Пожалуйста, если вы встретите уцелевших жителей Дарроушира, передайте им, что я свободен!','Ах! Пожалуйста, если вы встретите уцелевших жителей Дарроушира, передайте им, что я свободна!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Спасибо! Вы освободили меня!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Спасибо! Вы освободили меня!',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','О, спасибо! Как же долго длился этот кошмар…',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','О, спасибо! Как же долго длился этот кошмар…',`text1_1_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Наконец-то моя душа свободна!',`text2_0_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Наконец-то моя душа свободна!',`text2_1_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Спасибо! Битва за Дарроушир принесла мне погибель, но ты $gосвободил:освободила; меня!',`text3_0_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','Спасибо! Битва за Дарроушир принесла мне погибель, но ты $gосвободил:освободила; меня!',`text3_1_loc8`), `text4_0_loc8`=IF(`text4_0_loc8` IS NULL OR `text4_0_loc8`='','Ах! Пожалуйста, если вы встретите уцелевших жителей Дарроушира, передайте им, что я свободен!',`text4_0_loc8`), `text4_1_loc8`=IF(`text4_1_loc8` IS NULL OR `text4_1_loc8`='','Ах! Пожалуйста, если вы встретите уцелевших жителей Дарроушира, передайте им, что я свободна!',`text4_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (3874,'Изумрудный круг жаждет исцелить израненные земли Оскверненного леса. Мы верим, что однажды эти леса навсегда очистятся от скверны.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Изумрудный круг жаждет исцелить израненные земли Оскверненного леса. Мы верим, что однажды эти леса навсегда очистятся от скверны.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (3893,'Заг заг, $gхрабрый:храбрая:c; |3-6($c)! Я могу предложить тебе лучших верховых волков. Зверей, равных волку по выносливости и чутью, ты не найдешь нигде! Пожалуйста, можешь осмотреть их лично.','Заг заг, $gхрабрый:храбрая:c; |3-6($c)! Я могу предложить тебе лучших верховых волков. Зверей, равных волку по выносливости и чутью, ты не найдешь нигде! Пожалуйста, можешь осмотреть их лично.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Заг заг, $gхрабрый:храбрая:c; |3-6($c)! Я могу предложить тебе лучших верховых волков. Зверей, равных волку по выносливости и чутью, ты не найдешь нигде! Пожалуйста, можешь осмотреть их лично.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Заг заг, $gхрабрый:храбрая:c; |3-6($c)! Я могу предложить тебе лучших верховых волков. Зверей, равных волку по выносливости и чутью, ты не найдешь нигде! Пожалуйста, можешь осмотреть их лично.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3896,'Доброго тебе дня, $gхрабрый:храбрая:c; |3-6($c). Я знаю, ты ищешь доброго скакуна. Так вот что я скажу, $gбратишка:сестричка;: ручной ящер гораздо лучше! Вот, посмотри! Все как один – свирепые, потомки настоящих лютых бестий!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Доброго тебе дня, $gхрабрый:храбрая:c; |3-6($c). Я знаю, ты ищешь доброго скакуна. Так вот что я скажу, $gбратишка:сестричка;: ручной ящер гораздо лучше! Вот, посмотри! Все как один – свирепые, потомки настоящих лютых бестий!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3935,'Они дают мне тела, а я кидаю их в яму.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Они дают мне тела, а я кидаю их в яму.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (3940,'$gБрат:Сестра; по оружию, пришла пора покончить с Плетью!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','$gБрат:Сестра; по оружию, пришла пора покончить с Плетью!',`text0_1_loc8`);
