INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (3944,'Э… Боюсь, вы слишком велики для поездки на механодолгоноге, $gгосподин:госпожа;. Сервоприводы могут не выдержать!','Э… Боюсь, вы слишком велики для поездки на механодолгоноге, $gгосподин:госпожа;. Сервоприводы могут не выдержать!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Э… Боюсь, вы слишком велики для поездки на механодолгоноге, $gгосподин:госпожа;. Сервоприводы могут не выдержать!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Э… Боюсь, вы слишком велики для поездки на механодолгоноге, $gгосподин:госпожа;. Сервоприводы могут не выдержать!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (3945,'Если ты $gпришел:пришла; в поисках дара быстрой и безопасной мобильности, ты уже на месте! Модели новых механодолгоногов этого года недавно прибыли, и я готов показать тебе, что они умеют!','Если ты $gпришел:пришла; в поисках дара быстрой и безопасной мобильности, ты уже на месте! Модели новых механодолгоногов этого года недавно прибыли, и я готова показать тебе, что они умеют!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если ты $gпришел:пришла; в поисках дара быстрой и безопасной мобильности, ты уже на месте! Модели новых механодолгоногов этого года недавно прибыли, и я готов показать тебе, что они умеют!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Если ты $gпришел:пришла; в поисках дара быстрой и безопасной мобильности, ты уже на месте! Модели новых механодолгоногов этого года недавно прибыли, и я готова показать тебе, что они умеют!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3954,'Я Крахок, инспектор этих ремесленников.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я Крахок, инспектор этих ремесленников.',`text0_0_loc8`);
