INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (3974,'Да пребудет с тобой Свет, |3-6($c). Чем я могу помочь?','Да пребудет с тобой Свет, |3-6($c). Чем я могу помочь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да пребудет с тобой Свет, |3-6($c). Чем я могу помочь?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Да пребудет с тобой Свет, |3-6($c). Чем я могу помочь?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (3976,'Да хранит тебя Свет в этот день.','Да хранит тебя Свет в этот день.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да хранит тебя Свет в этот день.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Да хранит тебя Свет в этот день.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (3977,'Да хранит тебя Свет в этот день.','Да хранит тебя Свет в этот день.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да хранит тебя Свет в этот день.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Да хранит тебя Свет в этот день.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3978,'Надвигается сильный ветер – вот и коленка моя разболелась. Надеюсь, он не настигнет нас.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Надвигается сильный ветер – вот и коленка моя разболелась. Надеюсь, он не настигнет нас.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3982,'Исходя из принесенного тобой образца яда я полагаю, что тебе потребуется следующее: чародейский ускоритель, пять соматических усилителей и четыре куска рунической ткани. С помощью стеклянного фокусирующего устройства найди усилители в телах зомби или вурдалаков Чумных земель.$B$BКак только все это будет у тебя, ты сможешь залить противоядие в этот котел.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Исходя из принесенного тобой образца яда я полагаю, что тебе потребуется следующее: чародейский ускоритель, пять соматических усилителей и четыре куска рунической ткани. С помощью стеклянного фокусирующего устройства найди усилители в телах зомби или вурдалаков Чумных земель.$B$BКак только все это будет у тебя, ты сможешь залить противоядие в этот котел.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3983,'Мы изучили яд, который ты $Gпринес:принесла;, и решили, что тебе потребуется следующее: чародейский ускоритель, четыре эктоплазматических резонатора и четыре куска рунической ткани. Используя стеклянное фокусирующее устройство, найди резонаторов в призраках и духах Чумных земель!$B$BКогда соберешь все компоненты, мы сварим противоядие.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы изучили яд, который ты $Gпринес:принесла;, и решили, что тебе потребуется следующее: чародейский ускоритель, четыре эктоплазматических резонатора и четыре куска рунической ткани. Используя стеклянное фокусирующее устройство, найди резонаторов в призраках и духах Чумных земель!$B$BКогда соберешь все компоненты, мы сварим противоядие.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3984,'Шестнадцать с половиной в год – слишком мало за такую работу.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Шестнадцать с половиной в год – слишком мало за такую работу.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (3996,'Чума Плети все еще свирепствует в этом районе, и нам еще многое предстоит сделать. Собери необходимые припасы и помоги вести войну!','Чума Плети все еще свирепствует в этом районе, и нам еще многое предстоит сделать. Собери необходимые припасы и помоги вести войну!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Чума Плети все еще свирепствует в этом районе, и нам еще многое предстоит сделать. Собери необходимые припасы и помоги вести войну!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Чума Плети все еще свирепствует в этом районе, и нам еще многое предстоит сделать. Собери необходимые припасы и помоги вести войну!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (3998,'Мы научились обращать чуму Плети против нее самой, но до победы еще очень далеко! Помоги нам изменить ее котлы!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы научились обращать чуму Плети против нее самой, но до победы еще очень далеко! Помоги нам изменить ее котлы!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (3999,'Мы побеждаем Плеть – измененная чума будет действовать на нежить как минимум еще один день! Но чтобы закрепить эффект, нужно как можно скорее вывести из строя следующий котел!','Мы побеждаем Плеть – измененная чума будет действовать на нежить как минимум еще один день! Но чтобы закрепить эффект, нужно как можно скорее вывести из строя следующий котел!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы побеждаем Плеть – измененная чума будет действовать на нежить как минимум еще один день! Но чтобы закрепить эффект, нужно как можно скорее вывести из строя следующий котел!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мы побеждаем Плеть – измененная чума будет действовать на нежить как минимум еще один день! Но чтобы закрепить эффект, нужно как можно скорее вывести из строя следующий котел!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (4013,'Наставника охотников зовут Тотар. Его можно найти в его логове в юго-западной части Колючего Холма.','Наставника охотников зовут Тотар. Его можно найти в его логове в юго-западной части Колючего Холма.','А ты $gохотник:охотница;? Ну, тогда ты сможешь выследить нашего Тотара. Он прячется от солнца в своем логове в юго-западной части города.','А ты $gохотник:охотница;? Ну, тогда ты сможешь выследить нашего Тотара. Он прячется от солнца в своем логове в юго-западной части города.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Наставника охотников зовут Тотар. Его можно найти в его логове в юго-западной части Колючего Холма.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Наставника охотников зовут Тотар. Его можно найти в его логове в юго-западной части Колючего Холма.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','А ты $gохотник:охотница;? Ну, тогда ты сможешь выследить нашего Тотара. Он прячется от солнца в своем логове в юго-западной части города.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','А ты $gохотник:охотница;? Ну, тогда ты сможешь выследить нашего Тотара. Он прячется от солнца в своем логове в юго-западной части города.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (4014,'Поговори с Ун\'Тувой. Он живет южнее, в деревне Сен\'джин.','Поговори с Ун\'Тувой. Он живет южнее, в деревне Сен\'джин.','Этим тролли занимаются. Сходи к Ун\'Туве в деревню Сен\'джин, это к югу отсюда.','Этим тролли занимаются. Сходи к Ун\'Туве в деревню Сен\'джин, это к югу отсюда.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Поговори с Ун\'Тувой. Он живет южнее, в деревне Сен\'джин.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Поговори с Ун\'Тувой. Он живет южнее, в деревне Сен\'джин.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Этим тролли занимаются. Сходи к Ун\'Туве в деревню Сен\'джин, это к югу отсюда.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Этим тролли занимаются. Сходи к Ун\'Туве в деревню Сен\'джин, это к югу отсюда.',`text1_1_loc8`);
