INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (4016,'Ищи Каплака возле логова в юго-западной части города.','Ищи Каплака возле логова в юго-западной части города.','С чего это вдруг тебе понадобился Каплак? Впрочем, неважно. Можешь найти его возле логова на юго-западной окраине Колючего Холма. Только не вынимай рук из карманов!','С чего это вдруг тебе понадобился Каплак? Впрочем, неважно. Можешь найти его возле логова на юго-западной окраине Колючего Холма. Только не вынимай рук из карманов!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ищи Каплака возле логова в юго-западной части города.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ищи Каплака возле логова в юго-западной части города.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','С чего это вдруг тебе понадобился Каплак? Впрочем, неважно. Можешь найти его возле логова на юго-западной окраине Колючего Холма. Только не вынимай рук из карманов!',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','С чего это вдруг тебе понадобился Каплак? Впрочем, неважно. Можешь найти его возле логова на юго-западной окраине Колючего Холма. Только не вынимай рук из карманов!',`text1_1_loc8`);
