INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (4018,'На восточной стороне Колючего Холма, позади казармы – ищи Дхугру Кровожадного там.','На восточной стороне Колючего Холма, позади казармы – ищи Дхугру Кровожадного там.','Дхугру Кровожадный прячется за казармами на восточной стороне города. Но смотри, если узнаю, что ты на стороне Пылающего Легиона!..','Дхугру Кровожадный прячется за казармами на восточной стороне города. Но смотри, если узнаю, что ты на стороне Пылающего Легиона!..') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','На восточной стороне Колючего Холма, позади казармы – ищи Дхугру Кровожадного там.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','На восточной стороне Колючего Холма, позади казармы – ищи Дхугру Кровожадного там.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Дхугру Кровожадный прячется за казармами на восточной стороне города. Но смотри, если узнаю, что ты на стороне Пылающего Легиона!..',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Дхугру Кровожадный прячется за казармами на восточной стороне города. Но смотри, если узнаю, что ты на стороне Пылающего Легиона!..',`text1_1_loc8`);
