INSERT INTO `locales_npc_text` (`id`,`text1_0_loc8`,`text1_1_loc8`) VALUES (4019,'Тебе нужен Таршо Рваный Шрам. Ищи его в казармах на восточной стороне Колючего Холма. Служи Орде с честью, $gюноша:девушка;!','Тебе нужен Таршо Рваный Шрам. Ищи его в казармах на восточной стороне Колючего Холма. Служи Орде с честью, $gюноша:девушка;!') ON DUPLICATE KEY UPDATE `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Тебе нужен Таршо Рваный Шрам. Ищи его в казармах на восточной стороне Колючего Холма. Служи Орде с честью, $gюноша:девушка;!',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Тебе нужен Таршо Рваный Шрам. Ищи его в казармах на восточной стороне Колючего Холма. Служи Орде с честью, $gюноша:девушка;!',`text1_1_loc8`);
