INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (4021,'Это тебе нужен Двукк. Ищи его у работающей кузни в северо-западной части города.','Это тебе нужен Двукк. Ищи его у работающей кузни в северо-западной части города.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Это тебе нужен Двукк. Ищи его у работающей кузни в северо-западной части города.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Это тебе нужен Двукк. Ищи его у работающей кузни в северо-западной части города.',`text0_1_loc8`);
