INSERT INTO `locales_npc_text` (`id`,`text1_0_loc8`,`text1_1_loc8`) VALUES (4027,'Цветы? В этой пустыне? Если кто и научит тебя искать их здесь, так это Мишики из деревни Сен\'джин. Это к югу отсюда.','Цветы? В этой пустыне? Если кто и научит тебя искать их здесь, так это Мишики из деревни Сен\'джин. Это к югу отсюда.') ON DUPLICATE KEY UPDATE `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Цветы? В этой пустыне? Если кто и научит тебя искать их здесь, так это Мишики из деревни Сен\'джин. Это к югу отсюда.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Цветы? В этой пустыне? Если кто и научит тебя искать их здесь, так это Мишики из деревни Сен\'джин. Это к югу отсюда.',`text1_1_loc8`);
