INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (4031,'Тебе нужно в Оргриммар. Иди от Колючего Холма по северной дороге – и попадешь прямо туда. А там спроси любого рубаку.','Тебе нужно в Оргриммар. Иди от Колючего Холма по северной дороге – и попадешь прямо туда. А там спроси любого рубаку.','Шить учат в Оргриммаре. Это на севере. Там спросите любого оргриммарского рубаку.','Шить учат в Оргриммаре. Это на севере. Там спросите любого оргриммарского рубаку.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тебе нужно в Оргриммар. Иди от Колючего Холма по северной дороге – и попадешь прямо туда. А там спроси любого рубаку.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Тебе нужно в Оргриммар. Иди от Колючего Холма по северной дороге – и попадешь прямо туда. А там спроси любого рубаку.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Шить учат в Оргриммаре. Это на севере. Там спросите любого оргриммарского рубаку.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Шить учат в Оргриммаре. Это на севере. Там спросите любого оргриммарского рубаку.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (4032,'Что? Банк есть в Оргриммаре. Ступайте по дороге на север, а потом спросите у городской стражи.','Что? Банк есть в Оргриммаре. Ступайте по дороге на север, а потом спросите у городской стражи.','Да, мне и самому надо бы кое-что сбыть. Иди на север по дороге в Оргриммар, там расспросишь местных рубак.','Да, мне и самой надо бы кое-что сбыть. Иди на север по дороге в Оргриммар, там расспросишь местных рубак.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что? Банк есть в Оргриммаре. Ступайте по дороге на север, а потом спросите у городской стражи.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Что? Банк есть в Оргриммаре. Ступайте по дороге на север, а потом спросите у городской стражи.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Да, мне и самому надо бы кое-что сбыть. Иди на север по дороге в Оргриммар, там расспросишь местных рубак.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Да, мне и самой надо бы кое-что сбыть. Иди на север по дороге в Оргриммар, там расспросишь местных рубак.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
