INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (4040,'Теперь, когда котлы выведены из строя, мы сможем ввести в них противодействующее вещество. Пусть Плеть вкусит собственного зелья!$B$BПоговори насчет необходимых реагентов с аптекарем Дитерсом. Я буду лично изучать все доклады о том, как идет процесс обращения чумы против Плети!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Теперь, когда котлы выведены из строя, мы сможем ввести в них противодействующее вещество. Пусть Плеть вкусит собственного зелья!$B$BПоговори насчет необходимых реагентов с аптекарем Дитерсом. Я буду лично изучать все доклады о том, как идет процесс обращения чумы против Плети!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (4041,'Приветствую вас, $gюный господин:юная госпожа;. Я Ева Саркофф, а это мой муж Люсьен. Приятно с вами познакомиться.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Приветствую вас, $gюный господин:юная госпожа;. Я Ева Саркофф, а это мой муж Люсьен. Приятно с вами познакомиться.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (4042,'Разумеется, $gсэр:мисс;. Раньше мы служили в доме Баровых, в котором теперь Некроситет.$B$BЯ была старшей горничной, а Люсьен – дворецким господина Барова.$B$BМы работали на них многие десятилетия, пока…$B$B<Ева плачет.>') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Разумеется, $gсэр:мисс;. Раньше мы служили в доме Баровых, в котором теперь Некроситет.$B$BЯ была старшей горничной, а Люсьен – дворецким господина Барова.$B$BМы работали на них многие десятилетия, пока…$B$B<Ева плачет.>',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (4043,'О, это ужасная история, $gдобрый господин:добрая госпожа;. В поместье Баровых когда-то кипела жизнь… да, умели они жить. Они владели обширными землями…$B$BНо потом мы с Люсьеном заметили, что семейство Баровых приходит в упадок. Приступы страха и гнева часто охватывали и господина, и госпожу. По ночам мы слышали, как они ссорятся в своих покоях. Я думаю, что их погубила жадность.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','О, это ужасная история, $gдобрый господин:добрая госпожа;. В поместье Баровых когда-то кипела жизнь… да, умели они жить. Они владели обширными землями…$B$BНо потом мы с Люсьеном заметили, что семейство Баровых приходит в упадок. Приступы страха и гнева часто охватывали и господина, и госпожу. По ночам мы слышали, как они ссорятся в своих покоях. Я думаю, что их погубила жадность.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (4045,'И куда идти? Мы ничего не знали и не могли узнать.$B$BВ конце концов, мы потеряли связь с семейством Баровых и оказались отрезаны от остальных слуг. Мы не знали, что произошло с ними, только слышали крики. Чудовищные крики.$B$BНам с Люсьеном некуда было идти, и мы спрятались в наших комнатах. Днем, когда в школе было относительно тихо, Люсьен тайком выбирался добыть еду и питье.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','И куда идти? Мы ничего не знали и не могли узнать.$B$BВ конце концов, мы потеряли связь с семейством Баровых и оказались отрезаны от остальных слуг. Мы не знали, что произошло с ними, только слышали крики. Чудовищные крики.$B$BНам с Люсьеном некуда было идти, и мы спрятались в наших комнатах. Днем, когда в школе было относительно тихо, Люсьен тайком выбирался добыть еду и питье.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (4048,'Наконец-то выяснилось, что это были за крики. Мясник причинил нам такую боль, о которой ранее мы не могли и помыслить! Он ставил над нами бесчисленные эксперименты, чтобы вывести новую чуму.$b$bКаждый день тянулся как неделя… Мы бы умерли еще в первый день, но этот мерзавец поддерживал в нас жизнь с помощью магии.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Наконец-то выяснилось, что это были за крики. Мясник причинил нам такую боль, о которой ранее мы не могли и помыслить! Он ставил над нами бесчисленные эксперименты, чтобы вывести новую чуму.$b$bКаждый день тянулся как неделя… Мы бы умерли еще в первый день, но этот мерзавец поддерживал в нас жизнь с помощью магии.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (4049,'Кровавый мясник все говорил о "крови невинных" и своем господине по имени Киртонос, которого он должен задобрить.$B$BНаконец, злодей завершил свои опыты. Из нас по капле вытекла вся жизнь. Дух наш был сломлен. Сладостные объятья смерти уже манили нас, и мы стремились к ним от всего сердца. Но в своей безграничной жестокости Кровавый мясник вновь вернул нас к жизни.$B$BОн решил заживо скормить нас вурдалакам. Как он смеялся, когда эти твари терзали нашу плоть…') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Кровавый мясник все говорил о "крови невинных" и своем господине по имени Киртонос, которого он должен задобрить.$B$BНаконец, злодей завершил свои опыты. Из нас по капле вытекла вся жизнь. Дух наш был сломлен. Сладостные объятья смерти уже манили нас, и мы стремились к ним от всего сердца. Но в своей безграничной жестокости Кровавый мясник вновь вернул нас к жизни.$B$BОн решил заживо скормить нас вурдалакам. Как он смеялся, когда эти твари терзали нашу плоть…',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (4050,'Мы ничего не чувствуем. Наши души пребывают здесь вне времени… Мы не сможем освободиться, пока наши останки не будут найдены и упокоены.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мы ничего не чувствуем. Наши души пребывают здесь вне времени… Мы не сможем освободиться, пока наши останки не будут найдены и упокоены.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (4053,'Вам нужен трактирщик Каут. Он живет в западной части деревни в одном из длинных домов.','Вам нужен трактирщик Каут. Он живет в западной части деревни в одном из длинных домов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вам нужен трактирщик Каут. Он живет в западной части деревни в одном из длинных домов.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Вам нужен трактирщик Каут. Он живет в западной части деревни в одном из длинных домов.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text1_0_loc8`,`text1_1_loc8`) VALUES (4056,'В деревне живет мудрец по имени Нарм Небесный Охотник. Он может продолжить твое обучение искусству шаманов.','В деревне живет мудрец по имени Нарм Небесный Охотник. Он может продолжить твое обучение искусству шаманов.') ON DUPLICATE KEY UPDATE `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','В деревне живет мудрец по имени Нарм Небесный Охотник. Он может продолжить твое обучение искусству шаманов.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','В деревне живет мудрец по имени Нарм Небесный Охотник. Он может продолжить твое обучение искусству шаманов.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (4057,'Кранг Каменное Копыто обычно стоит возле своей тренировочной площадки в юго-восточном углу деревни.','Кранг Каменное Копыто обычно стоит возле своей тренировочной площадки в юго-восточном углу деревни.','Если ты хочешь постичь путь воина, ищи Кранга Каменное Копыто. Он учит бойцов на тренировочной площадке в юго-восточной части деревни.','Если ты хочешь постичь путь воина, ищи Кранга Каменное Копыто. Он учит бойцов на тренировочной площадке в юго-восточной части деревни.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Кранг Каменное Копыто обычно стоит возле своей тренировочной площадки в юго-восточном углу деревни.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Кранг Каменное Копыто обычно стоит возле своей тренировочной площадки в юго-восточном углу деревни.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Если ты хочешь постичь путь воина, ищи Кранга Каменное Копыто. Он учит бойцов на тренировочной площадке в юго-восточной части деревни.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Если ты хочешь постичь путь воина, ищи Кранга Каменное Копыто. Он учит бойцов на тренировочной площадке в юго-восточной части деревни.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (4060,'Пиалл Тихая Поступь стоит в большой палатке в северо-западной части деревни. Он научит тебя всему необходимому.','Пиалл Тихая Поступь стоит в большой палатке в северо-западной части деревни. Он научит тебя всему необходимому.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Пиалл Тихая Поступь стоит в большой палатке в северо-западной части деревни. Он научит тебя всему необходимому.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Пиалл Тихая Поступь стоит в большой палатке в северо-западной части деревни. Он научит тебя всему необходимому.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (4070,'Какая профессия?','Какая профессия?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Какая профессия?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Какая профессия?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (4079,'Наставницу разбойников зовут Марион Зов. Ее можно найти на юго-восточной окраине города, в таверне "Петля висельника". Она наверху, в читальном зале.','Наставницу разбойников зовут Марион Зов. Ее можно найти на юго-восточной окраине города, в таверне "Петля висельника". Она наверху, в читальном зале.','Марион Зов и темный священник Берил сидят в читальном зале на втором этаже "Петли висельника" и играют в гляделки. Интересно, кто из них выиграет?','Марион Зов и темный священник Берил сидят в читальном зале на втором этаже "Петли висельника" и играют в гляделки. Интересно, кто из них выиграет?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Наставницу разбойников зовут Марион Зов. Ее можно найти на юго-восточной окраине города, в таверне "Петля висельника". Она наверху, в читальном зале.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Наставницу разбойников зовут Марион Зов. Ее можно найти на юго-восточной окраине города, в таверне "Петля висельника". Она наверху, в читальном зале.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Марион Зов и темный священник Берил сидят в читальном зале на втором этаже "Петли висельника" и играют в гляделки. Интересно, кто из них выиграет?',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Марион Зов и темный священник Берил сидят в читальном зале на втором этаже "Петли висельника" и играют в гляделки. Интересно, кто из них выиграет?',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`) VALUES (4081,'Загляни в главный обеденный зал таверны "Петля висельника" и спроси там Остила де Мона. Таверна расположена на юго-восточной окраине Брилла.','Загляни в главный обеденный зал таверны "Петля висельника" и спроси там Остила де Мона. Таверна расположена на юго-восточной окраине Брилла.','Ага, похоже, вам нужен Остил де Мон. Он вечно ошивается в таверне в юго-восточной части города. Она называется "Петля висельника", мимо не пройдете.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Загляни в главный обеденный зал таверны "Петля висельника" и спроси там Остила де Мона. Таверна расположена на юго-восточной окраине Брилла.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Загляни в главный обеденный зал таверны "Петля висельника" и спроси там Остила де Мона. Таверна расположена на юго-восточной окраине Брилла.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Ага, похоже, вам нужен Остил де Мон. Он вечно ошивается в таверне в юго-восточной части города. Она называется "Петля висельника", мимо не пройдете.',`text1_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (4082,'Алхимией у нас занимается Каролай Аниса. Ее дом – на северо-западной окраине Брилла.','Алхимией у нас занимается Каролай Аниса. Ее дом – на северо-западной окраине Брилла.','Каролай Аниса пытается взорвать свой дом на северо-западной окраине города. Почему бы тебе не попробовать ей помочь?','Каролай Аниса пытается взорвать свой дом на северо-западной окраине города. Почему бы тебе не попробовать ей помочь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Алхимией у нас занимается Каролай Аниса. Ее дом – на северо-западной окраине Брилла.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Алхимией у нас занимается Каролай Аниса. Ее дом – на северо-западной окраине Брилла.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Каролай Аниса пытается взорвать свой дом на северо-западной окраине города. Почему бы тебе не попробовать ей помочь?',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Каролай Аниса пытается взорвать свой дом на северо-западной окраине города. Почему бы тебе не попробовать ей помочь?',`text1_1_loc8`);
