INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (4085,'Ванса Мрачнейшего можно найти на юго-восточной стороне Брилла, в таверне "Петля висельника", наверху.','Ванса Мрачнейшего можно найти на юго-восточной стороне Брилла, в таверне "Петля висельника", наверху.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ванса Мрачнейшего можно найти на юго-восточной стороне Брилла, в таверне "Петля висельника", наверху.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ванса Мрачнейшего можно найти на юго-восточной стороне Брилла, в таверне "Петля висельника", наверху.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (4087,'Сиделка Нила встречает всех своих потенциальных покупателей у входа в таверну "Петля висельника", это в юго-восточной части города.','Сиделка Нила встречает всех своих потенциальных покупателей у входа в таверну "Петля висельника", это в юго-восточной части города.','Первая помощь, говоришь? А не боишься наших коновалов? Держу пари, ты в обморок упадешь, как только увидишь сиделку Нилу из "Петли висельника"! Это таверна такая на юго-востоке.','Первая помощь, говоришь? А не боишься наших коновалов? Держу пари, ты в обморок упадешь, как только увидишь сиделку Нилу из "Петли висельника"! Это таверна такая на юго-востоке.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Сиделка Нила встречает всех своих потенциальных покупателей у входа в таверну "Петля висельника", это в юго-восточной части города.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Сиделка Нила встречает всех своих потенциальных покупателей у входа в таверну "Петля висельника", это в юго-восточной части города.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Первая помощь, говоришь? А не боишься наших коновалов? Держу пари, ты в обморок упадешь, как только увидишь сиделку Нилу из "Петли висельника"! Это таверна такая на юго-востоке.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Первая помощь, говоришь? А не боишься наших коновалов? Держу пари, ты в обморок упадешь, как только увидишь сиделку Нилу из "Петли висельника"! Это таверна такая на юго-востоке.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (4088,'Клайд Келлен, местный мастер рыбной ловли, очень любит рыбачить на озере Ясноводное к востоку от Брилла.','Клайд Келлен, местный мастер рыбной ловли, очень любит рыбачить на озере Ясноводное к востоку от Брилла.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Клайд Келлен, местный мастер рыбной ловли, очень любит рыбачить на озере Ясноводное к востоку от Брилла.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Клайд Келлен, местный мастер рыбной ловли, очень любит рыбачить на озере Ясноводное к востоку от Брилла.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (4089,'Поищите Фарузу. Последний раз ее видели стоящей между стойлами и домом в северо-западной части города.','Поищите Фарузу. Последний раз ее видели стоящей между стойлами и домом в северо-западной части города.','Вообще-то, я предпочитаю традиционную медицину… пиявки там, личинки… пила для костей, опять же… Ну да каждому свое. Нашу местную травницу Фарузу можно найти возле стойл в Брилле.','Вообще-то, я предпочитаю традиционную медицину… пиявки там, личинки… пила для костей, опять же… Ну да каждому свое. Нашу местную травницу Фарузу можно найти возле стойл в Брилле.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Поищите Фарузу. Последний раз ее видели стоящей между стойлами и домом в северо-западной части города.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Поищите Фарузу. Последний раз ее видели стоящей между стойлами и домом в северо-западной части города.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Вообще-то, я предпочитаю традиционную медицину… пиявки там, личинки… пила для костей, опять же… Ну да каждому свое. Нашу местную травницу Фарузу можно найти возле стойл в Брилле.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Вообще-то, я предпочитаю традиционную медицину… пиявки там, личинки… пила для костей, опять же… Ну да каждому свое. Нашу местную травницу Фарузу можно найти возле стойл в Брилле.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`) VALUES (4090,'Вам нужна Шелена Робарт. Идите из Брилла на юго-восток, а на перекрестке поверните на восток. Там увидите лагерь возле дороги.','Ничто не сравнится с тем чувством, когда вас касается что-то мертвое. Идите на юго-восток из города, а на перекрестке сверните на восток. Найдете Шелену Робарт в маленьком лагере у дороги.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вам нужна Шелена Робарт. Идите из Брилла на юго-восток, а на перекрестке поверните на восток. Там увидите лагерь возле дороги.',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Ничто не сравнится с тем чувством, когда вас касается что-то мертвое. Идите на юго-восток из города, а на перекрестке сверните на восток. Найдете Шелену Робарт в маленьком лагере у дороги.',`text1_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`) VALUES (4092,'Рэнд Робарт умеет снимать шкуры с нетопырей Скверны и прочих подобных тварей. Ищи его в лагере к юго-востоку от Брилла. Сейчас иди по юго-восточной дороге, а на перекрестке свернешь на восток.','Рэнд Робарт умеет снимать шкуры с нетопырей Скверны и прочих подобных тварей. Ищи его в лагере к юго-востоку от Брилла. Сейчас иди по юго-восточной дороге, а на перекрестке свернешь на восток.','Ты собираешься стать таксидермистом? Мне не нравится, когда некоторые думают, что могут набить меня и выставить в качестве экспоната, воображая, что я мертв. Нет? Хорошо! Рэнд Робарт в лагере к юго-востоку от города. Чтобы добраться до него, иди по дороге на юго-восток от Брилла и на перекрестке сверни налево.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Рэнд Робарт умеет снимать шкуры с нетопырей Скверны и прочих подобных тварей. Ищи его в лагере к юго-востоку от Брилла. Сейчас иди по юго-восточной дороге, а на перекрестке свернешь на восток.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Рэнд Робарт умеет снимать шкуры с нетопырей Скверны и прочих подобных тварей. Ищи его в лагере к юго-востоку от Брилла. Сейчас иди по юго-восточной дороге, а на перекрестке свернешь на восток.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Ты собираешься стать таксидермистом? Мне не нравится, когда некоторые думают, что могут набить меня и выставить в качестве экспоната, воображая, что я мертв. Нет? Хорошо! Рэнд Робарт в лагере к юго-востоку от города. Чтобы добраться до него, иди по дороге на юго-восток от Брилла и на перекрестке сверни налево.',`text1_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`) VALUES (4093,'Тебе нужен Боуэн Брисбойс. Его дом находится к юго-западу от Брилла, сразу за мостом, у поместья "Остывший Очаг".','Тебе нужен Боуэн Брисбойс. Его дом находится к юго-западу от Брилла, сразу за мостом, у поместья "Остывший Очаг".','Черный, серый и темно-фиолетовый – цвета сезона. Носи их, если хочешь следовать последней моде, дружище. Боуэн Брисбойс поможет тебе в этом непростом деле. Ты найдешь его в поместье "Остывший Очаг", на другой стороне моста в юго-западной части города.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тебе нужен Боуэн Брисбойс. Его дом находится к юго-западу от Брилла, сразу за мостом, у поместья "Остывший Очаг".',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Тебе нужен Боуэн Брисбойс. Его дом находится к юго-западу от Брилла, сразу за мостом, у поместья "Остывший Очаг".',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Черный, серый и темно-фиолетовый – цвета сезона. Носи их, если хочешь следовать последней моде, дружище. Боуэн Брисбойс поможет тебе в этом непростом деле. Ты найдешь его в поместье "Остывший Очаг", на другой стороне моста в юго-западной части города.',`text1_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (4095,'Какой учитель вам нужен?','Какой учитель вам нужен?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Какой учитель вам нужен?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Какой учитель вам нужен?',`text0_1_loc8`);
