INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (4114,'Когда вы видите клетку с ночной эльфийкой, у вас возникает странное чувство дежавю. Эльфийка почему-то отводит взгляд и старательно делает вид, что не замечает вас.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Когда вы видите клетку с ночной эльфийкой, у вас возникает странное чувство дежавю. Эльфийка почему-то отводит взгляд и старательно делает вид, что не замечает вас.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4117,'Они не понимают, что уже умерли, |3-6($r). Они – по крайней мере, большая их часть – обречены вечно переживать последние мгновения перед тем, как пал город. А некоторым повезло еще меньше.$B$BДумаете, это все дело рук Плети? Тогда Плети еще не существовало, а если бы она была, мы бы смогли ее остановить.$B$BНет, это результат чумы, пришедшей из Некроситета и уничтожившей город. Она была ужасной и смертоносной. Никто не выжил.$B$BА теперь оставьте меня наедине со своим горем.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Они не понимают, что уже умерли, |3-6($r). Они – по крайней мере, большая их часть – обречены вечно переживать последние мгновения перед тем, как пал город. А некоторым повезло еще меньше.$B$BДумаете, это все дело рук Плети? Тогда Плети еще не существовало, а если бы она была, мы бы смогли ее остановить.$B$BНет, это результат чумы, пришедшей из Некроситета и уничтожившей город. Она была ужасной и смертоносной. Никто не выжил.$B$BА теперь оставьте меня наедине со своим горем.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`,`text3_0_loc8`,`text4_0_loc8`) VALUES (4118,'Ты что, не видишь – мы готовимся к визиту Утера? Уйди с дороги, и так дел невпроворот!','Доводилось пробовать наш хлеб? По-моему, пекарь Мастерсон – величайший кулинар всех времен!','Добро пожаловать в Каэр Дарроу, $gнезнакомец:незнакомка;.','Мы не хотели показаться грубыми. Просто сейчас у нас все торопятся – к прибытию Утера все должно быть идеально. Светоносный не так часто приезжает в город.','Еще один великолепный день на нашем прекрасном острове.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты что, не видишь – мы готовимся к визиту Утера? Уйди с дороги, и так дел невпроворот!',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Доводилось пробовать наш хлеб? По-моему, пекарь Мастерсон – величайший кулинар всех времен!',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Добро пожаловать в Каэр Дарроу, $gнезнакомец:незнакомка;.',`text2_0_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Мы не хотели показаться грубыми. Просто сейчас у нас все торопятся – к прибытию Утера все должно быть идеально. Светоносный не так часто приезжает в город.',`text3_0_loc8`), `text4_0_loc8`=IF(`text4_0_loc8` IS NULL OR `text4_0_loc8`='','Еще один великолепный день на нашем прекрасном острове.',`text4_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`,`text3_0_loc8`,`text4_0_loc8`) VALUES (4119,'Будь $gосторожен, незнакомец:осторожна, незнакомка;. В нашем городе не терпят еретиков.','Я за тобой слежу, |3-6($r).','У меня много нерастраченной злобы и ярости. Только дай повод, бродяга.','У тебя вид, как у уличной шпаны!','Тунеядство, хулиганство, сквернословие, драки и все прочие непотребства, которыми ты собираешься заниматься, в Каэр Дарроу запрещены.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Будь $gосторожен, незнакомец:осторожна, незнакомка;. В нашем городе не терпят еретиков.',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Я за тобой слежу, |3-6($r).',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','У меня много нерастраченной злобы и ярости. Только дай повод, бродяга.',`text2_0_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','У тебя вид, как у уличной шпаны!',`text3_0_loc8`), `text4_0_loc8`=IF(`text4_0_loc8` IS NULL OR `text4_0_loc8`='','Тунеядство, хулиганство, сквернословие, драки и все прочие непотребства, которыми ты собираешься заниматься, в Каэр Дарроу запрещены.',`text4_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4122,'Культ Проклятых сильно разросся. Практически в каждом городе Орды и Альянса, начиная от столиц и заканчивая маленькими деревушками и даже шалашами, среди жителей прячутся члены культа.$B$BНе удивляйся. Служители культа носят форменную одежду лишь для ритуалов и церемоний. Очень может быть, что во время своих приключений ты $gвстречался:встречалась; с ними и даже не $gзнал:знала; об этом.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Культ Проклятых сильно разросся. Практически в каждом городе Орды и Альянса, начиная от столиц и заканчивая маленькими деревушками и даже шалашами, среди жителей прячутся члены культа.$B$BНе удивляйся. Служители культа носят форменную одежду лишь для ритуалов и церемоний. Очень может быть, что во время своих приключений ты $gвстречался:встречалась; с ними и даже не $gзнал:знала; об этом.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4123,'Правда? Узнаю их методы. Что ценнее для Кел\'Тузада и Плети? Живой последователь, который может внедриться в общество и распространить чуму, погубив тысячи жизней, или один из множества солдат нежити? Думаю, ты легко ответишь на этот вопрос.$B$BДа, |3-6($r), они живут, работают и плетут интриги среди вас.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Правда? Узнаю их методы. Что ценнее для Кел\'Тузада и Плети? Живой последователь, который может внедриться в общество и распространить чуму, погубив тысячи жизней, или один из множества солдат нежити? Думаю, ты легко ответишь на этот вопрос.$B$BДа, |3-6($r), они живут, работают и плетут интриги среди вас.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4124,'Остановить – нет. Замедлить – возможно.$B$BНекроситет – их главный центр обучения и тренировки. Именно там служители культа проходят подготовку, прежде чем внедриться в наше общество.$B$BМы должны нанести удар в самое сердце Культа Проклятых!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Остановить – нет. Замедлить – возможно.$B$BНекроситет – их главный центр обучения и тренировки. Именно там служители культа проходят подготовку, прежде чем внедриться в наше общество.$B$BМы должны нанести удар в самое сердце Культа Проклятых!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4125,'Не торопись, |3-6($r). Тот, кого тебе нужно убить, и так уже мертв, и убивать его заново бессмысленно. Способов избавиться от лича очень мало, и все они недоступны ни мне, ни тебе. Потому я придумал план. План, который нанесет серьезный удар по Культу.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не торопись, |3-6($r). Тот, кого тебе нужно убить, и так уже мертв, и убивать его заново бессмысленно. Способов избавиться от лича очень мало, и все они недоступны ни мне, ни тебе. Потому я придумал план. План, который нанесет серьезный удар по Культу.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4126,'Все очень просто. Лиши лича Ледяного Шепота его силы. Сделай его смертным и убей, вот и все.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Все очень просто. Лиши лича Ледяного Шепота его силы. Сделай его смертным и убей, вот и все.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4127,'Кажется, я забегаю вперед. Рас Ледяной Шепот – директор этой школы. Он отвечает за обучение всех Темных господ. Верный помощник и лучший ученик Кел\'Тузада. В свое время он нелегально колдовал в Стромгарде – ему так и не удалось пройти формальное обучение в Даларане.$B$BКогда Кел\'Тузад основал Культ, Рас одним из первых вступил в его ряды. Он знал, что черная магия даст ему возможность стать бессмертным.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Кажется, я забегаю вперед. Рас Ледяной Шепот – директор этой школы. Он отвечает за обучение всех Темных господ. Верный помощник и лучший ученик Кел\'Тузада. В свое время он нелегально колдовал в Стромгарде – ему так и не удалось пройти формальное обучение в Даларане.$B$BКогда Кел\'Тузад основал Культ, Рас одним из первых вступил в его ряды. Он знал, что черная магия даст ему возможность стать бессмертным.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4128,'И он получил, чего хотел. Рас добился высокого положения в Культе, и сам Король-лич даровал ему бессмертие. Так был рожден Рас Ледяной Шепот, лич.$B$BТеперь ты понимаешь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','И он получил, чего хотел. Рас добился высокого положения в Культе, и сам Король-лич даровал ему бессмертие. Так был рожден Рас Ледяной Шепот, лич.$B$BТеперь ты понимаешь?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4129,'Хорошо. Для исполнения моего плана первым делом нужно создать жизнекамень. Начнем?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Хорошо. Для исполнения моего плана первым делом нужно создать жизнекамень. Начнем?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4130,'Некоторые были избавлены от мук, вызванных воспоминаниями.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Некоторые были избавлены от мук, вызванных воспоминаниями.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`,`text3_0_loc8`) VALUES (4133,'Да уж, дом Баровых обеспечивает меня работой. Оттуда постоянно появляются какие-то отбросы.','Моя должность называется "специалист по обработке отходов".','Попробуй говорить в микрофоны, которые закреплены на моих КУЛАКАХ НЕИСТОВСТВА!','Ах, моя милая Брэнди, как мне ее не хватает!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да уж, дом Баровых обеспечивает меня работой. Оттуда постоянно появляются какие-то отбросы.',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Моя должность называется "специалист по обработке отходов".',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Попробуй говорить в микрофоны, которые закреплены на моих КУЛАКАХ НЕИСТОВСТВА!',`text2_0_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Ах, моя милая Брэнди, как мне ее не хватает!',`text3_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (4173,'Серебряный Рассвет приветствует тебя, |3-6($c). Я Хасана – одна из нескольких доверенных интендантов Рассвета.$B$BСражаясь со злом от нашего имени, и заручаясь при этом нашим доверием и уважением, ты заработаешь у офицера Серебряных знаки доблести. Они служат двум целям. Благодаря им ты сможешь добиться нашего доброго отношения или обменять их на наши особые товары.$B$BЧем лучше к тебе будут относиться в Серебряном Рассвете, тем больше предметов будет тебе доступно.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Серебряный Рассвет приветствует тебя, |3-6($c). Я Хасана – одна из нескольких доверенных интендантов Рассвета.$B$BСражаясь со злом от нашего имени, и заручаясь при этом нашим доверием и уважением, ты заработаешь у офицера Серебряных знаки доблести. Они служат двум целям. Благодаря им ты сможешь добиться нашего доброго отношения или обменять их на наши особые товары.$B$BЧем лучше к тебе будут относиться в Серебряном Рассвете, тем больше предметов будет тебе доступно.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (4174,'Присоединяйся к битве со злом! Вступи в ряды Серебряного Рассвета прямо сейчас!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Присоединяйся к битве со злом! Вступи в ряды Серебряного Рассвета прямо сейчас!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4233,'Здравствуй, |3-6($c).$B$BСтражи позволили мне остаться в лагере, если я буду сидеть тихо и никому не мешать. Ну, ты же понимаешь, дипломатия – наше все.$B$BЯ провожу исследования возмущений земли, а им это на руку, так что мне разрешили тут быть под соусом "укрепления шаткого союза между расами Азерота". Хочешь мне помочь? Я только рад. Только прошу, сиди тихо и никому не мешай.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здравствуй, |3-6($c).$B$BСтражи позволили мне остаться в лагере, если я буду сидеть тихо и никому не мешать. Ну, ты же понимаешь, дипломатия – наше все.$B$BЯ провожу исследования возмущений земли, а им это на руку, так что мне разрешили тут быть под соусом "укрепления шаткого союза между расами Азерота". Хочешь мне помочь? Я только рад. Только прошу, сиди тихо и никому не мешай.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4253,'Добро пожаловать в Поселок Сталежара!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать в Поселок Сталежара!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4254,'Раса сама по себе не делает чести, |3-6($r). Пока ты у меня на ферме, я прошу тебя помнить об этом.$B$BЯ знал орков, которые не уступали в благородстве любому рыцарю, и людей, столь же злобных, сколь худшие из Плети.$B$BНо я не буду тебя утомлять историями моей юности! Тебя ждет много работы – если ты этого желаешь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Раса сама по себе не делает чести, |3-6($r). Пока ты у меня на ферме, я прошу тебя помнить об этом.$B$BЯ знал орков, которые не уступали в благородстве любому рыцарю, и людей, столь же злобных, сколь худшие из Плети.$B$BНо я не буду тебя утомлять историями моей юности! Тебя ждет много работы – если ты этого желаешь.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (4259,'Что вы ищете?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Что вы ищете?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (4260,'Банк? Ну, ближайший банк у нас – Счетная палата Штормграда. Иди от городских ворот прямо по дороге, она там недалеко.','Банк? Ну, ближайший банк у нас – Счетная палата Штормграда. Иди от городских ворот прямо по дороге, она там недалеко.','А, так тебе нужна счетная палата… Она совсем рядом с воротами Штормграда.','А, так тебе нужна счетная палата… Она совсем рядом с воротами Штормграда.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Банк? Ну, ближайший банк у нас – Счетная палата Штормграда. Иди от городских ворот прямо по дороге, она там недалеко.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Банк? Ну, ближайший банк у нас – Счетная палата Штормграда. Иди от городских ворот прямо по дороге, она там недалеко.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','А, так тебе нужна счетная палата… Она совсем рядом с воротами Штормграда.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','А, так тебе нужна счетная палата… Она совсем рядом с воротами Штормграда.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (4261,'Ну, если тебе нужно куда-то слетать, ступай в Штормград. Там есть укротитель грифонов. Иди по Аллее Героев и смотри направо. Увидишь, где приземляются грифоны – туда тебе и надо.','Ну, если тебе нужно куда-то слетать, ступай в Штормград. Там есть укротитель грифонов. Иди по Аллее Героев и смотри направо. Увидишь, где приземляются грифоны – туда тебе и надо.','Укротитель грифонов обеспечивает воздушное сообщение Штормграда с другими землями. Если желаете полетать, обращайтесь к нему.','Укротитель грифонов обеспечивает воздушное сообщение Штормграда с другими землями. Если желаете полетать, обращайтесь к нему.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ну, если тебе нужно куда-то слетать, ступай в Штормград. Там есть укротитель грифонов. Иди по Аллее Героев и смотри направо. Увидишь, где приземляются грифоны – туда тебе и надо.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ну, если тебе нужно куда-то слетать, ступай в Штормград. Там есть укротитель грифонов. Иди по Аллее Героев и смотри направо. Увидишь, где приземляются грифоны – туда тебе и надо.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Укротитель грифонов обеспечивает воздушное сообщение Штормграда с другими землями. Если желаете полетать, обращайтесь к нему.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Укротитель грифонов обеспечивает воздушное сообщение Штормграда с другими землями. Если желаете полетать, обращайтесь к нему.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (4262,'Надеюсь, Альдвин Лолкинс – по-прежнему постоянный представитель Гильдии в Штормграде. Как пройдешь внутренние ворота, его дом будет слева.','Надеюсь, Альдвин Лолкинс – по-прежнему постоянный представитель Гильдии в Штормграде. Как пройдешь внутренние ворота, его дом будет слева.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Надеюсь, Альдвин Лолкинс – по-прежнему постоянный представитель Гильдии в Штормграде. Как пройдешь внутренние ворота, его дом будет слева.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Надеюсь, Альдвин Лолкинс – по-прежнему постоянный представитель Гильдии в Штормграде. Как пройдешь внутренние ворота, его дом будет слева.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (4263,'Иди сразу в Златоземье, в "Гордость льва". Увидишь, сколько у них сортов пива, – поймешь, что лучше места для отдыха просто не найти!','Иди сразу в Златоземье, в "Гордость льва". Увидишь, сколько у них сортов пива, – поймешь, что лучше места для отдыха просто не найти!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Иди сразу в Златоземье, в "Гордость льва". Увидишь, сколько у них сортов пива, – поймешь, что лучше места для отдыха просто не найти!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Иди сразу в Златоземье, в "Гордость льва". Увидишь, сколько у них сортов пива, – поймешь, что лучше места для отдыха просто не найти!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (4264,'В Элвиннском лесу много разных учителей. Тебе какой нужен?','В Элвиннском лесу много разных учителей. Тебе какой нужен?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','В Элвиннском лесу много разных учителей. Тебе какой нужен?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','В Элвиннском лесу много разных учителей. Тебе какой нужен?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (4265,'Друиды? Не встречал тут ни одного друида, хотя в Штормграде есть целый квартал ночных эльфов.','Друиды? Не встречала тут ни одного друида, хотя в Штормграде есть целый квартал ночных эльфов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Друиды? Не встречал тут ни одного друида, хотя в Штормграде есть целый квартал ночных эльфов.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Друиды? Не встречала тут ни одного друида, хотя в Штормграде есть целый квартал ночных эльфов.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (4266,'Я слышал, что есть один дворф в Штормграде, известный охотник. Возможно, тебе стоит обратиться за помощью к нему.','Я слышала, что есть один дворф в Штормграде, известный охотник. Возможно, тебе стоит обратиться за помощью к нему.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я слышал, что есть один дворф в Штормграде, известный охотник. Возможно, тебе стоит обратиться за помощью к нему.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я слышала, что есть один дворф в Штормграде, известный охотник. Возможно, тебе стоит обратиться за помощью к нему.',`text0_1_loc8`);
