INSERT INTO `locales_npc_text` (`id`,`text1_0_loc8`,`text1_1_loc8`) VALUES (4268,'Я в магии не особо смыслю, но в таверне "Гордость льва" сейчас живет маг Залдимар. Он наверняка сможет вам помочь.','Я в магии не особо смыслю, но в таверне "Гордость льва" сейчас живет маг Залдимар. Он наверняка сможет вам помочь.') ON DUPLICATE KEY UPDATE `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Я в магии не особо смыслю, но в таверне "Гордость льва" сейчас живет маг Залдимар. Он наверняка сможет вам помочь.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Я в магии не особо смыслю, но в таверне "Гордость льва" сейчас живет маг Залдимар. Он наверняка сможет вам помочь.',`text1_1_loc8`);
