INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (4269,'Найди брата Вильгельма – он обычно болтает с Лирией на задворках кузни. Он любит учить паладинов.','Найди брата Вильгельма – он обычно болтает с Лирией на задворках кузни. Он любит учить паладинов.','Брат Вильгельм часто тренируется с Лирией дю Лак за кузницей в Златоземье. Возможно, он сможет рассказать тебе что-то новое о пути паладина.','Брат Вильгельм часто тренируется с Лирией дю Лак за кузницей в Златоземье. Возможно, он сможет рассказать тебе что-то новое о пути паладина.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Найди брата Вильгельма – он обычно болтает с Лирией на задворках кузни. Он любит учить паладинов.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Найди брата Вильгельма – он обычно болтает с Лирией на задворках кузни. Он любит учить паладинов.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Брат Вильгельм часто тренируется с Лирией дю Лак за кузницей в Златоземье. Возможно, он сможет рассказать тебе что-то новое о пути паладина.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Брат Вильгельм часто тренируется с Лирией дю Лак за кузницей в Златоземье. Возможно, он сможет рассказать тебе что-то новое о пути паладина.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (4270,'Разбойник? Хммм… Ну, мне говорили, что Керин Сильвиус вечно якшается с какими-то подозрительными типами. Поговорите с ней, может, чему и научитесь.','Разбойник? Хммм… Ну, мне говорили, что Керин Сильвиус вечно якшается с какими-то подозрительными типами. Поговорите с ней, может, чему и научитесь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Разбойник? Хммм… Ну, мне говорили, что Керин Сильвиус вечно якшается с какими-то подозрительными типами. Поговорите с ней, может, чему и научитесь.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Разбойник? Хммм… Ну, мне говорили, что Керин Сильвиус вечно якшается с какими-то подозрительными типами. Поговорите с ней, может, чему и научитесь.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (4271,'Здесь мало кто может сравниться во владении мечом с Лирией дю Лак. Разыщи ее за кузней и узнай, захочет ли она чему-то тебя учить.','Здесь мало кто может сравниться во владении мечом с Лирией дю Лак. Разыщи ее за кузней и узнай, захочет ли она чему-то тебя учить.','Если хочешь подучиться, поговори с Лирией. Обычно она стоит за кузницей и ждет, пока там не изготовят очередной доспех или оружие.','Если хочешь подучиться, поговори с Лирией. Обычно она стоит за кузницей и ждет, пока там не изготовят очередной доспех или оружие.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здесь мало кто может сравниться во владении мечом с Лирией дю Лак. Разыщи ее за кузней и узнай, захочет ли она чему-то тебя учить.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Здесь мало кто может сравниться во владении мечом с Лирией дю Лак. Разыщи ее за кузней и узнай, захочет ли она чему-то тебя учить.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Если хочешь подучиться, поговори с Лирией. Обычно она стоит за кузницей и ждет, пока там не изготовят очередной доспех или оружие.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Если хочешь подучиться, поговори с Лирией. Обычно она стоит за кузницей и ждет, пока там не изготовят очередной доспех или оружие.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text1_0_loc8`,`text1_1_loc8`) VALUES (4272,'Чернокнижник? Ну, если бы я был чернокнижником, я бы спрятался в самом темном месте… Например, в подвал… Попробуй поискать в подвале таверны "Гордость льва".','Чернокнижник? Ну, если бы я была чернокнижницей, я бы спряталась в самом темном месте… Например, в подвал… Попробуй поискать в подвале таверны "Гордость льва".') ON DUPLICATE KEY UPDATE `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Чернокнижник? Ну, если бы я был чернокнижником, я бы спрятался в самом темном месте… Например, в подвал… Попробуй поискать в подвале таверны "Гордость льва".',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Чернокнижник? Ну, если бы я была чернокнижницей, я бы спряталась в самом темном месте… Например, в подвал… Попробуй поискать в подвале таверны "Гордость льва".',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (4273,'Есть у меня парочка знакомых – настоящие мастера своего дела. Что ты хочешь изучать?','Есть у меня парочка знакомых – настоящие мастера своего дела. Что ты хочешь изучать?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Есть у меня парочка знакомых – настоящие мастера своего дела. Что ты хочешь изучать?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Есть у меня парочка знакомых – настоящие мастера своего дела. Что ты хочешь изучать?',`text0_1_loc8`);
