INSERT INTO `locales_npc_text` (`id`,`text1_0_loc8`,`text1_1_loc8`) VALUES (4274,'Говорят, в холмах между Североземьем и Штормградом живет один алхимик. Почему бы тебе не навестить его?','Говорят, в холмах между Североземьем и Штормградом живет один алхимик. Почему бы тебе не навестить его?') ON DUPLICATE KEY UPDATE `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Говорят, в холмах между Североземьем и Штормградом живет один алхимик. Почему бы тебе не навестить его?',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Говорят, в холмах между Североземьем и Штормградом живет один алхимик. Почему бы тебе не навестить его?',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (4275,'Аргус – главный кузнец Златоземья. Уверен, у него есть чему поучиться.','Аргус – главный кузнец Златоземья. Уверена, у него есть чему поучиться.','Должно быть, ты ищешь кузнеца Аргуса. Он обычно присматривает за кузницей в Златоземье. Тебе, наверное, подучиться надо?','Должно быть, ты ищешь кузнеца Аргуса. Он обычно присматривает за кузницей в Златоземье. Тебе, наверное, подучиться надо?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Аргус – главный кузнец Златоземья. Уверен, у него есть чему поучиться.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Аргус – главный кузнец Златоземья. Уверена, у него есть чему поучиться.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Должно быть, ты ищешь кузнеца Аргуса. Он обычно присматривает за кузницей в Златоземье. Тебе, наверное, подучиться надо?',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Должно быть, ты ищешь кузнеца Аргуса. Он обычно присматривает за кузницей в Златоземье. Тебе, наверное, подучиться надо?',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (4276,'Томас, может, и не лучший повар в мире, но есть несколько блюд, которые ему очень удаются. Сейчас он работает в таверне "Гордость льва" – если хочешь научиться профессии.','Томас, может, и не лучший повар в мире, но есть несколько блюд, которые ему очень удаются. Сейчас он работает в таверне "Гордость льва" – если хочешь научиться профессии.','Почему бы тебе не поговорить с поваром из "Гордости льва"? Он может подсказать тебе парочку рецептов.','Почему бы тебе не поговорить с поваром из "Гордости льва"? Он может подсказать тебе парочку рецептов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Томас, может, и не лучший повар в мире, но есть несколько блюд, которые ему очень удаются. Сейчас он работает в таверне "Гордость льва" – если хочешь научиться профессии.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Томас, может, и не лучший повар в мире, но есть несколько блюд, которые ему очень удаются. Сейчас он работает в таверне "Гордость льва" – если хочешь научиться профессии.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Почему бы тебе не поговорить с поваром из "Гордости льва"? Он может подсказать тебе парочку рецептов.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Почему бы тебе не поговорить с поваром из "Гордости льва"? Он может подсказать тебе парочку рецептов.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text1_0_loc8`,`text1_1_loc8`) VALUES (4277,'Ммм… все мои знакомые зачаровыватели, живут в Штормграде. Почему бы тебе не отправиться туда и не расспросить местных стражников?','Ммм… все мои знакомые зачаровыватели, живут в Штормграде. Почему бы тебе не отправиться туда и не расспросить местных стражников?') ON DUPLICATE KEY UPDATE `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Ммм… все мои знакомые зачаровыватели, живут в Штормграде. Почему бы тебе не отправиться туда и не расспросить местных стражников?',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Ммм… все мои знакомые зачаровыватели, живут в Штормграде. Почему бы тебе не отправиться туда и не расспросить местных стражников?',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (4283,'Если хочешь научиться шахтерскому делу, тебе лучше всего направиться в Штормград, в Квартал Дворфов. Наверняка один из дворфов там может научить тебя этой профессии.','Если хочешь научиться шахтерскому делу, тебе лучше всего направиться в Штормград, в Квартал Дворфов. Наверняка один из дворфов там может научить тебя этой профессии.','Лучше вам в Штормграде поискать. Спросите там любого стража, они скажут, куда пройти.','Лучше вам в Штормграде поискать. Спросите там любого стража, они скажут, куда пройти.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если хочешь научиться шахтерскому делу, тебе лучше всего направиться в Штормград, в Квартал Дворфов. Наверняка один из дворфов там может научить тебя этой профессии.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Если хочешь научиться шахтерскому делу, тебе лучше всего направиться в Штормград, в Квартал Дворфов. Наверняка один из дворфов там может научить тебя этой профессии.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Лучше вам в Штормграде поискать. Спросите там любого стража, они скажут, куда пройти.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Лучше вам в Штормграде поискать. Спросите там любого стража, они скажут, куда пройти.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (4284,'Хелена Меховяз уже много лет снимает шкуры с животных, а Адель Филдер делает из этих кож всякие вещи. Хелену можно найти в ее доме возле озера Хрустального.','Хелена Меховяз уже много лет снимает шкуры с животных, а Адель Филдер делает из этих кож всякие вещи. Хелену можно найти в ее доме возле озера Хрустального.','У нас есть отличный учитель снятия шкур. Она живет в хижине возле Хрустального озера. Думаю, она с радостью преподаст тебе основы своей профессии.','У нас есть отличный учитель снятия шкур. Она живет в хижине возле Хрустального озера. Думаю, она с радостью преподаст тебе основы своей профессии.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Хелена Меховяз уже много лет снимает шкуры с животных, а Адель Филдер делает из этих кож всякие вещи. Хелену можно найти в ее доме возле озера Хрустального.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Хелена Меховяз уже много лет снимает шкуры с животных, а Адель Филдер делает из этих кож всякие вещи. Хелену можно найти в ее доме возле озера Хрустального.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','У нас есть отличный учитель снятия шкур. Она живет в хижине возле Хрустального озера. Думаю, она с радостью преподаст тебе основы своей профессии.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','У нас есть отличный учитель снятия шкур. Она живет в хижине возле Хрустального озера. Думаю, она с радостью преподаст тебе основы своей профессии.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (4285,'Элдрин – единственный житель Элвиннского леса, которого можно назвать портным. Ты найдешь его на лесозаготовках Восточной долины.','Элдрин – единственный житель Элвиннского леса, которого можно назвать портным. Ты найдешь его на лесозаготовках Восточной долины.','Хочешь заняться портняжным делом? Хмм… Кажется, портной был на Лесопилке Восточной долины. Попробуй поучиться у него.','Хочешь заняться портняжным делом? Хмм… Кажется, портной был на Лесопилке Восточной долины. Попробуй поучиться у него.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Элдрин – единственный житель Элвиннского леса, которого можно назвать портным. Ты найдешь его на лесозаготовках Восточной долины.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Элдрин – единственный житель Элвиннского леса, которого можно назвать портным. Ты найдешь его на лесозаготовках Восточной долины.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Хочешь заняться портняжным делом? Хмм… Кажется, портной был на Лесопилке Восточной долины. Попробуй поучиться у него.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Хочешь заняться портняжным делом? Хмм… Кажется, портной был на Лесопилке Восточной долины. Попробуй поучиться у него.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (4287,'Куда вы желаете пойти?','Куда вы желаете пойти?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Куда вы желаете пойти?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Куда вы желаете пойти?',`text0_1_loc8`);
