INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (4288,'Ближайший банк у нас тут в Стальгорне, $gпарень:девушка;.','Ближайший банк у нас тут в Стальгорне, $gпарень:девушка;.','Ближайший банк у нас в Стальгорне.','Ближайший банк у нас в Стальгорне.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ближайший банк у нас тут в Стальгорне, $gпарень:девушка;.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ближайший банк у нас тут в Стальгорне, $gпарень:девушка;.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Ближайший банк у нас в Стальгорне.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Ближайший банк у нас в Стальгорне.',`text1_1_loc8`);
