INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (4290,'Все официальные лица проживают в Стальгорне. Бумаги для создания гильдии можно получить в Гостевых покоях Стальгорна.','Все официальные лица проживают в Стальгорне. Бумаги для создания гильдии можно получить в Гостевых покоях Стальгорна.','Ежели тебе нужны какие-то гильдейские бумаги, ступай в Стальгорн и загляни в тамошние Гостевые покои.','Ежели тебе нужны какие-то гильдейские бумаги, ступай в Стальгорн и загляни в тамошние Гостевые покои.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Все официальные лица проживают в Стальгорне. Бумаги для создания гильдии можно получить в Гостевых покоях Стальгорна.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Все официальные лица проживают в Стальгорне. Бумаги для создания гильдии можно получить в Гостевых покоях Стальгорна.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Ежели тебе нужны какие-то гильдейские бумаги, ступай в Стальгорн и загляни в тамошние Гостевые покои.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Ежели тебе нужны какие-то гильдейские бумаги, ступай в Стальгорн и загляни в тамошние Гостевые покои.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text1_0_loc8`,`text1_1_loc8`) VALUES (4291,'Таверна, говоришь? Лучше всего, конечно, "Громоварка". Там и просто отдохнуть можно, но я тебе советую пропустить пару кружек местного эля.','Таверна, говоришь? Лучше всего, конечно, "Громоварка". Там и просто отдохнуть можно, но я тебе советую пропустить пару кружек местного эля.') ON DUPLICATE KEY UPDATE `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Таверна, говоришь? Лучше всего, конечно, "Громоварка". Там и просто отдохнуть можно, но я тебе советую пропустить пару кружек местного эля.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Таверна, говоришь? Лучше всего, конечно, "Громоварка". Там и просто отдохнуть можно, но я тебе советую пропустить пару кружек местного эля.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (4292,'Какой класс вас интересует?','Какой класс вас интересует?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Какой класс вас интересует?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Какой класс вас интересует?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (4293,'Есть только один охотник, к которому я бы тебе посоветовал обратиться. Его зовут Гриф Дикое Сердце. Ищи его возле кузницы в Караносе.','Есть только один охотник, к которому я бы тебе посоветовал обратиться. Его зовут Гриф Дикое Сердце. Ищи его возле кузницы в Караносе.','По мне, так Гриф слишком много возится со всяким зверьем. Однако охотник он хоть куда, уж в этом ему не откажешь. Поищите его около кузницы в Караносе.','По мне, так Гриф слишком много возится со всяким зверьем. Однако охотник он хоть куда, уж в этом ему не откажешь. Поищите его около кузницы в Караносе.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Есть только один охотник, к которому я бы тебе посоветовал обратиться. Его зовут Гриф Дикое Сердце. Ищи его возле кузницы в Караносе.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Есть только один охотник, к которому я бы тебе посоветовал обратиться. Его зовут Гриф Дикое Сердце. Ищи его возле кузницы в Караносе.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','По мне, так Гриф слишком много возится со всяким зверьем. Однако охотник он хоть куда, уж в этом ему не откажешь. Поищите его около кузницы в Караносе.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','По мне, так Гриф слишком много возится со всяким зверьем. Однако охотник он хоть куда, уж в этом ему не откажешь. Поищите его около кузницы в Караносе.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`) VALUES (4294,'В "Громоварке" есть один маг, который мог бы обучить тебя кой-каким новым заклинаниям. Кажется, его зовут Магис Искроплащ.','Ты $gуверен:уверена;, что не хочешь учиться на воина? Ну, это твой выбор. Если действительно хочешь научиться размахивать пальцем, лучше тебе поговорить с Магисом Искроплащом в "Громоварке".') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','В "Громоварке" есть один маг, который мог бы обучить тебя кой-каким новым заклинаниям. Кажется, его зовут Магис Искроплащ.',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Ты $gуверен:уверена;, что не хочешь учиться на воина? Ну, это твой выбор. Если действительно хочешь научиться размахивать пальцем, лучше тебе поговорить с Магисом Искроплащом в "Громоварке".',`text1_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (4297,'Что ж, тогда нам нужен один и тот же дворф – Хограл Баккан. Он рано или поздно обязательно отправится в "Громоварку", чтобы пропустить кружечку… А может, он уже там.','Что ж, тогда нам нужен один и тот же дворф – Хограл Баккан. Он рано или поздно обязательно отправится в "Громоварку", чтобы пропустить кружечку… А может, он уже там.','Ты ищешь Хограла? А в таверне $gсмотрел:смотрела;? Запомни: если тебе нужен дворф, да еще и разбойник, ищи его в таверне!','Ты ищешь Хограла? А в таверне $gсмотрел:смотрела;? Запомни: если тебе нужен дворф, да еще и разбойник, ищи его в таверне!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что ж, тогда нам нужен один и тот же дворф – Хограл Баккан. Он рано или поздно обязательно отправится в "Громоварку", чтобы пропустить кружечку… А может, он уже там.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Что ж, тогда нам нужен один и тот же дворф – Хограл Баккан. Он рано или поздно обязательно отправится в "Громоварку", чтобы пропустить кружечку… А может, он уже там.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Ты ищешь Хограла? А в таверне $gсмотрел:смотрела;? Запомни: если тебе нужен дворф, да еще и разбойник, ищи его в таверне!',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Ты ищешь Хограла? А в таверне $gсмотрел:смотрела;? Запомни: если тебе нужен дворф, да еще и разбойник, ищи его в таверне!',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (4298,'Чернокнижники… Терпеть их не могу! Вон тот же Гимризз – открыл, понимаешь, лавку прямо возле "Громоварки". Да от его рожи, скажу я тебе, там весь эль прокиснет! Чернокнижники, значит… фу!','Чернокнижники… Терпеть их не могу! Вон тот же Гимризз – открыл, понимаешь, лавку прямо возле "Громоварки". Да от его рожи, скажу я тебе, там весь эль прокиснет! Чернокнижники, значит… фу!','От этой разновидности магии – одни неприятности. Не представляю, кто этому Гримриззу вообще разрешил поселиться возле "Громоварки". Держись от него подальше!','От этой разновидности магии – одни неприятности. Не представляю, кто этому Гримриззу вообще разрешил поселиться возле "Громоварки". Держись от него подальше!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Чернокнижники… Терпеть их не могу! Вон тот же Гимризз – открыл, понимаешь, лавку прямо возле "Громоварки". Да от его рожи, скажу я тебе, там весь эль прокиснет! Чернокнижники, значит… фу!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Чернокнижники… Терпеть их не могу! Вон тот же Гимризз – открыл, понимаешь, лавку прямо возле "Громоварки". Да от его рожи, скажу я тебе, там весь эль прокиснет! Чернокнижники, значит… фу!',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','От этой разновидности магии – одни неприятности. Не представляю, кто этому Гримриззу вообще разрешил поселиться возле "Громоварки". Держись от него подальше!',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','От этой разновидности магии – одни неприятности. Не представляю, кто этому Гримриззу вообще разрешил поселиться возле "Громоварки". Держись от него подальше!',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (4300,'Какая профессия тебя интересует?','Какая профессия тебя интересует?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Какая профессия тебя интересует?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Какая профессия тебя интересует?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (4301,'Не, в Дун Мороге алхимиков нет. Поищи лучше в Стальгорне… например, среди гномов из Города Механиков.','Не, в Дун Мороге алхимиков нет. Поищи лучше в Стальгорне… например, среди гномов из Города Механиков.','Говорят, в Стальгорне есть отличная лавка гномов-алхимиков. Обязательно загляни туда.','Говорят, в Стальгорне есть отличная лавка гномов-алхимиков. Обязательно загляни туда.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не, в Дун Мороге алхимиков нет. Поищи лучше в Стальгорне… например, среди гномов из Города Механиков.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Не, в Дун Мороге алхимиков нет. Поищи лучше в Стальгорне… например, среди гномов из Города Механиков.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Говорят, в Стальгорне есть отличная лавка гномов-алхимиков. Обязательно загляни туда.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Говорят, в Стальгорне есть отличная лавка гномов-алхимиков. Обязательно загляни туда.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (4302,'О! Этому навыку стоит обучиться! Тогнус бьет по наковальне с силой, которую нечасто встретишь. Почему бы тебе не поговорить с ним и не посмотреть, чему он сможет тебя обучить?','О! Этому навыку стоит обучиться! Тогнус бьет по наковальне с силой, которую нечасто встретишь. Почему бы тебе не поговорить с ним и не посмотреть, чему он сможет тебя обучить?','Звон наковальни Тогнуса слышно даже в Караносе. Потому прочисти уши и загляни в кузню.','Звон наковальни Тогнуса слышно даже в Караносе. Потому прочисти уши и загляни в кузню.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','О! Этому навыку стоит обучиться! Тогнус бьет по наковальне с силой, которую нечасто встретишь. Почему бы тебе не поговорить с ним и не посмотреть, чему он сможет тебя обучить?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','О! Этому навыку стоит обучиться! Тогнус бьет по наковальне с силой, которую нечасто встретишь. Почему бы тебе не поговорить с ним и не посмотреть, чему он сможет тебя обучить?',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Звон наковальни Тогнуса слышно даже в Караносе. Потому прочисти уши и загляни в кузню.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Звон наковальни Тогнуса слышно даже в Караносе. Потому прочисти уши и загляни в кузню.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text1_0_loc8`,`text1_1_loc8`) VALUES (4303,'Гремлок – не слишком удачливый повар, но коллекция рецептов у него внушительная. Поболтай с ним и выведай пару секретов. Он сейчас в "Громоварке".','Гремлок – не слишком удачливый повар, но коллекция рецептов у него внушительная. Поболтай с ним и выведай пару секретов. Он сейчас в "Громоварке".') ON DUPLICATE KEY UPDATE `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Гремлок – не слишком удачливый повар, но коллекция рецептов у него внушительная. Поболтай с ним и выведай пару секретов. Он сейчас в "Громоварке".',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Гремлок – не слишком удачливый повар, но коллекция рецептов у него внушительная. Поболтай с ним и выведай пару секретов. Он сейчас в "Громоварке".',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (4306,'Может, первая помощь и не заменит искусства жрецов, но зато она всегда под рукой. Я б тебе советовал поговорить с Трамнером из "Громоварки" и научиться у него всему, чему сумеешь.','Может, первая помощь и не заменит искусства жрецов, но зато она всегда под рукой. Я б тебе советовала поговорить с Трамнером из "Громоварки" и научиться у него всему, чему сумеешь.','Меня однажды угораздило наткнуться на мерзкого трогга, так старик Трамнер тогда очень здорово перебинтовал, все сразу зажило. Думаю, Трамнер с радостью научит и вас накладывать повязки.','Меня однажды угораздило наткнуться на мерзкого трогга, так старик Трамнер тогда очень здорово перебинтовал, все сразу зажило. Думаю, Трамнер с радостью научит и вас накладывать повязки.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Может, первая помощь и не заменит искусства жрецов, но зато она всегда под рукой. Я б тебе советовал поговорить с Трамнером из "Громоварки" и научиться у него всему, чему сумеешь.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Может, первая помощь и не заменит искусства жрецов, но зато она всегда под рукой. Я б тебе советовала поговорить с Трамнером из "Громоварки" и научиться у него всему, чему сумеешь.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Меня однажды угораздило наткнуться на мерзкого трогга, так старик Трамнер тогда очень здорово перебинтовал, все сразу зажило. Думаю, Трамнер с радостью научит и вас накладывать повязки.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Меня однажды угораздило наткнуться на мерзкого трогга, так старик Трамнер тогда очень здорово перебинтовал, все сразу зажило. Думаю, Трамнер с радостью научит и вас накладывать повязки.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (4308,'Цветы, как ни странно, выдерживают холода Дун Морога, но травников ты здесь не найдешь. Чтобы учиться этому ремеслу, тебе нужно отправиться в Стальгорн.','Цветы, как ни странно, выдерживают холода Дун Морога, но травников ты здесь не найдешь. Чтобы учиться этому ремеслу, тебе нужно отправиться в Стальгорн.','Нет, здесь некому тебя научить травничеству. Но думаю, что тебе больше повезет в Стальгорне.','Нет, здесь некому тебя научить травничеству. Но думаю, что тебе больше повезет в Стальгорне.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Цветы, как ни странно, выдерживают холода Дун Морога, но травников ты здесь не найдешь. Чтобы учиться этому ремеслу, тебе нужно отправиться в Стальгорн.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Цветы, как ни странно, выдерживают холода Дун Морога, но травников ты здесь не найдешь. Чтобы учиться этому ремеслу, тебе нужно отправиться в Стальгорн.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Нет, здесь некому тебя научить травничеству. Но думаю, что тебе больше повезет в Стальгорне.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Нет, здесь некому тебя научить травничеству. Но думаю, что тебе больше повезет в Стальгорне.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (4310,'Если хочешь учиться кожевничеству, отправляйся в Стальгорн. Говорят, там возле Великой Кузни есть отличная мастерская.','Если хочешь учиться кожевничеству, отправляйся в Стальгорн. Говорят, там возле Великой Кузни есть отличная мастерская.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если хочешь учиться кожевничеству, отправляйся в Стальгорн. Говорят, там возле Великой Кузни есть отличная мастерская.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Если хочешь учиться кожевничеству, отправляйся в Стальгорн. Говорят, там возле Великой Кузни есть отличная мастерская.',`text0_1_loc8`);
