INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (4311,'Не $gдумал:думала; же ты, что найдешь город без горняка, правда? Ярра можно разыскать в Поселке Сталежара, сразу за границей Караноса.','Не $gдумал:думала; же ты, что найдешь город без горняка, правда? Ярра можно разыскать в Поселке Сталежара, сразу за границей Караноса.','Шахтер? Ты можешь не спрашивать есть ли, $gпарень:девица;, только где! Тебе нужен Ярр, и я думаю, что ты найдешь его прячущимся в "Поселке Сталежара".','Шахтер? Ты можешь не спрашивать есть ли, $gпарень:девица;, только где! Тебе нужен Ярр, и я думаю, что ты найдешь его прячущимся в "Поселке Сталежара".') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не $gдумал:думала; же ты, что найдешь город без горняка, правда? Ярра можно разыскать в Поселке Сталежара, сразу за границей Караноса.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Не $gдумал:думала; же ты, что найдешь город без горняка, правда? Ярра можно разыскать в Поселке Сталежара, сразу за границей Караноса.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Шахтер? Ты можешь не спрашивать есть ли, $gпарень:девица;, только где! Тебе нужен Ярр, и я думаю, что ты найдешь его прячущимся в "Поселке Сталежара".',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Шахтер? Ты можешь не спрашивать есть ли, $gпарень:девица;, только где! Тебе нужен Ярр, и я думаю, что ты найдешь его прячущимся в "Поселке Сталежара".',`text1_1_loc8`);
