INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (4312,'Здесь, в Дун Мороге, ты не найдешь ни одного специалиста по снятию шкур, $gпарень:девушка;. Если уж тебе так надо научиться снимать шкуры, ступай в Стальгорн.','Здесь, в Дун Мороге, ты не найдешь ни одного специалиста по снятию шкур, $gпарень:девушка;. Если уж тебе так надо научиться снимать шкуры, ступай в Стальгорн.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здесь, в Дун Мороге, ты не найдешь ни одного специалиста по снятию шкур, $gпарень:девушка;. Если уж тебе так надо научиться снимать шкуры, ступай в Стальгорн.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Здесь, в Дун Мороге, ты не найдешь ни одного специалиста по снятию шкур, $gпарень:девушка;. Если уж тебе так надо научиться снимать шкуры, ступай в Стальгорн.',`text0_1_loc8`);
