INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (4316,'В Тельдрассиле есть много интересных мест. Что именно ты ищешь?','В Тельдрассиле есть много интересных мест. Что именно ты ищешь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','В Тельдрассиле есть много интересных мест. Что именно ты ищешь?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','В Тельдрассиле есть много интересных мест. Что именно ты ищешь?',`text0_1_loc8`);
