INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (4322,'В Доланааре ты найдешь множество наставников, посвятивших своему делу долгие годы. Чему именно ты хочешь учиться?','В Доланааре ты найдешь множество наставников, посвятивших своему делу долгие годы. Чему именно ты хочешь учиться?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','В Доланааре ты найдешь множество наставников, посвятивших своему делу долгие годы. Чему именно ты хочешь учиться?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','В Доланааре ты найдешь множество наставников, посвятивших своему делу долгие годы. Чему именно ты хочешь учиться?',`text0_1_loc8`);
