INSERT INTO `locales_npc_text` (`id`,`text1_0_loc8`,`text1_1_loc8`) VALUES (4323,'Друид Кел проводит много времени у лунного колодца в Доланааре. Я уверен, что он мог бы научить тебя тому, что тебе нужно.','Друид Кел проводит много времени у лунного колодца в Доланааре. Я уверена, что он мог бы научить тебя тому, что тебе нужно.') ON DUPLICATE KEY UPDATE `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Друид Кел проводит много времени у лунного колодца в Доланааре. Я уверен, что он мог бы научить тебя тому, что тебе нужно.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Друид Кел проводит много времени у лунного колодца в Доланааре. Я уверена, что он мог бы научить тебя тому, что тебе нужно.',`text1_1_loc8`);
