INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (4324,'Если вы ищете охотника, вам нужен Далазар. Обычно его можно найти возле таверны в Доланааре.','Если вы ищете охотника, вам нужен Далазар. Обычно его можно найти возле таверны в Доланааре.','Дазалар – самый известный охотник Доланаара. Почему бы тебе не поговорить с ним?','Дазалар – самый известный охотник Доланаара. Почему бы тебе не поговорить с ним?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если вы ищете охотника, вам нужен Далазар. Обычно его можно найти возле таверны в Доланааре.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Если вы ищете охотника, вам нужен Далазар. Обычно его можно найти возле таверны в Доланааре.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Дазалар – самый известный охотник Доланаара. Почему бы тебе не поговорить с ним?',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Дазалар – самый известный охотник Доланаара. Почему бы тебе не поговорить с ним?',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (4325,'Жрица по имени Лорна Утренний Свет называет Доланаар своим домом. Кажется, ее можно встретить к северу от таверны.','Жрица по имени Лорна Утренний Свет называет Доланаар своим домом. Кажется, ее можно встретить к северу от таверны.','Лорна Утренний Свет лечит всех жителей Доланаара, которые в этом нуждаются. Многим жрецам стоит у нее поучиться.','Лорна Утренний Свет лечит всех жителей Доланаара, которые в этом нуждаются. Многим жрецам стоит у нее поучиться.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Жрица по имени Лорна Утренний Свет называет Доланаар своим домом. Кажется, ее можно встретить к северу от таверны.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Жрица по имени Лорна Утренний Свет называет Доланаар своим домом. Кажется, ее можно встретить к северу от таверны.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Лорна Утренний Свет лечит всех жителей Доланаара, которые в этом нуждаются. Многим жрецам стоит у нее поучиться.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Лорна Утренний Свет лечит всех жителей Доланаара, которые в этом нуждаются. Многим жрецам стоит у нее поучиться.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (4326,'Разбойник? Я не имею ничего общего с такими типами, но, думаю, Джаннок – тот, кто тебе нужен. Ищи его в таверне Доланаара.','Разбойник? Я не имею ничего общего с такими типами, но, думаю, Джаннок – тот, кто тебе нужен. Ищи его в таверне Доланаара.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Разбойник? Я не имею ничего общего с такими типами, но, думаю, Джаннок – тот, кто тебе нужен. Ищи его в таверне Доланаара.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Разбойник? Я не имею ничего общего с такими типами, но, думаю, Джаннок – тот, кто тебе нужен. Ищи его в таверне Доланаара.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (4327,'Кайра Ветрорез обладает невероятным мастерством в обращении с клинком. Она может научить тебя кое-чему. Ты можешь найти ее в таверне в Доланааре.','Кайра Ветрорез обладает невероятным мастерством в обращении с клинком. Она может научить тебя кое-чему. Ты можешь найти ее в таверне в Доланааре.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Кайра Ветрорез обладает невероятным мастерством в обращении с клинком. Она может научить тебя кое-чему. Ты можешь найти ее в таверне в Доланааре.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Кайра Ветрорез обладает невероятным мастерством в обращении с клинком. Она может научить тебя кое-чему. Ты можешь найти ее в таверне в Доланааре.',`text0_1_loc8`);
