INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (4328,'Путь того, кто выбрал себе профессию, долог и прибылен. Какую профессию вы выбрали для себя?','Путь того, кто выбрал себе профессию, долог и прибылен. Какую профессию вы выбрали для себя?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Путь того, кто выбрал себе профессию, долог и прибылен. Какую профессию вы выбрали для себя?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Путь того, кто выбрал себе профессию, долог и прибылен. Какую профессию вы выбрали для себя?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (4334,'Малорн ухитряется срывать даже самые хрупкие травы, не повредив их. Ясно, что учиться тебе надо у него. Он живет в Доланааре, к востоку от таверны.','Малорн ухитряется срывать даже самые хрупкие травы, не повредив их. Ясно, что учиться тебе надо у него. Он живет в Доланааре, к востоку от таверны.','Травничество требует осторожного подхода. Этому учат немногие – в том числе Малорн. Его можно найти восточнее таверны в Доланааре.','Травничество требует осторожного подхода. Этому учат немногие – в том числе Малорн. Его можно найти восточнее таверны в Доланааре.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Малорн ухитряется срывать даже самые хрупкие травы, не повредив их. Ясно, что учиться тебе надо у него. Он живет в Доланааре, к востоку от таверны.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Малорн ухитряется срывать даже самые хрупкие травы, не повредив их. Ясно, что учиться тебе надо у него. Он живет в Доланааре, к востоку от таверны.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Травничество требует осторожного подхода. Этому учат немногие – в том числе Малорн. Его можно найти восточнее таверны в Доланааре.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Травничество требует осторожного подхода. Этому учат немногие – в том числе Малорн. Его можно найти восточнее таверны в Доланааре.',`text1_1_loc8`);
