INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4353,'Здравствуй, |3-6($c). Мы встали лагерем у Бастиона, чтобы подготовиться к походу в Чумные земли. Говорят, в Дольный Очаг недавно прибыл могущественный маг-человек. Алый орден поручил ему создать новые луки и ружья для своих воинов и охотников. Как только он закончил работу, Алые убили его.$B$BДа, не доверяют они чародеям…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здравствуй, |3-6($c). Мы встали лагерем у Бастиона, чтобы подготовиться к походу в Чумные земли. Говорят, в Дольный Очаг недавно прибыл могущественный маг-человек. Алый орден поручил ему создать новые луки и ружья для своих воинов и охотников. Как только он закончил работу, Алые убили его.$B$BДа, не доверяют они чародеям…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (4354,'Приветствую тебя, |3-6($c). У нас мало времени на разговоры. Я зашла в лагерь Промозглого Ветра только для того, чтобы отдохнуть на пути в Дольный Очаг. Я слыхала, что на Алых, пока они не обезумели, работал один маг. Он пытался создать какие-то особенно мощные луки и ружья. Уж не знаю, добился ли он успеха… Алые убили его прежде, чем он закончил работу. Возможно, чтобы сохранить тайну… а может, от нелюбви к тайной магии.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Приветствую тебя, |3-6($c). У нас мало времени на разговоры. Я зашла в лагерь Промозглого Ветра только для того, чтобы отдохнуть на пути в Дольный Очаг. Я слыхала, что на Алых, пока они не обезумели, работал один маг. Он пытался создать какие-то особенно мощные луки и ружья. Уж не знаю, добился ли он успеха… Алые убили его прежде, чем он закончил работу. Возможно, чтобы сохранить тайну… а может, от нелюбви к тайной магии.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (4356,'Моя семья работала на лесопилке Северного Кряжа – там, где теперь Западные Чумные земли. Эти края принадлежали семейству Дамахов, но Алые захватили их вместе со всем Дольным Очагом!$B$BЯ не успокоюсь, пока не истреблю этих фанатиков во всем Азероте!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Моя семья работала на лесопилке Северного Кряжа – там, где теперь Западные Чумные земли. Эти края принадлежали семейству Дамахов, но Алые захватили их вместе со всем Дольным Очагом!$B$BЯ не успокоюсь, пока не истреблю этих фанатиков во всем Азероте!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4394,'Придумай, как показать Древобрюхам, что вы не враги. Если постараешься – сможешь расположить к себе этих фурболгов, даже если сейчас они относятся к тебе враждебно.$B$BНе забывай, что открытое нападение на это племя лишит тебя возможности заключить с ним союз. $B$BПопробуй начать с фурболгов племени Мертвого Леса, обитающих в Оскверненном лесу. Убивая их, ты сможешь улучшить свою репутацию среди Древобрюхов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Придумай, как показать Древобрюхам, что вы не враги. Если постараешься – сможешь расположить к себе этих фурболгов, даже если сейчас они относятся к тебе враждебно.$B$BНе забывай, что открытое нападение на это племя лишит тебя возможности заключить с ним союз. $B$BПопробуй начать с фурболгов племени Мертвого Леса, обитающих в Оскверненном лесу. Убивая их, ты сможешь улучшить свою репутацию среди Древобрюхов.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4395,'Мы, Древобрюхи, можем пропустить тебя через свою берлогу – но сначала покажи нам, чего ты стоишь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы, Древобрюхи, можем пропустить тебя через свою берлогу – но сначала покажи нам, чего ты стоишь.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4396,'Фурболги Зимней Спячки, обитающие здесь, в Зимних Ключах, когда-то были нашими союзниками… Но однажды все изменилось. $B$BПодчиняясь странным приказам своего Великого вождя, они стали нападать на всех, с кем общались, включая наше племя. Теперь они живут замкнуто…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Фурболги Зимней Спячки, обитающие здесь, в Зимних Ключах, когда-то были нашими союзниками… Но однажды все изменилось. $B$BПодчиняясь странным приказам своего Великого вождя, они стали нападать на всех, с кем общались, включая наше племя. Теперь они живут замкнуто…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4399,'Да, да. Я вижу тебя.$B$BОставайся на своем пути. Возможно, ты $gзаслужил:заслужила; кое-чье доверие, но у тебя уйдет гораздо больше времени, чтобы получить мое.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да, да. Я вижу тебя.$B$BОставайся на своем пути. Возможно, ты $gзаслужил:заслужила; кое-чье доверие, но у тебя уйдет гораздо больше времени, чтобы получить мое.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4401,'Если покажешь себя надежным союзником, я, может быть, и возьмусь тебя обучать…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если покажешь себя надежным союзником, я, может быть, и возьмусь тебя обучать…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (4434,'Не отворачивайся от Света, |3-6($c). Возможно, когда-нибудь он спасет тебя.','Не отворачивайся от Света, |3-6($c). Возможно, когда-нибудь он спасет тебя.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не отворачивайся от Света, |3-6($c). Возможно, когда-нибудь он спасет тебя.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Не отворачивайся от Света, |3-6($c). Возможно, когда-нибудь он спасет тебя.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
