INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (4440,'Берегись, |3-6($c). Уважай наши традиции, иначе проклятие не минует тебя.','Берегись, |3-6($c). Уважай наши традиции, иначе проклятие не минует тебя.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Берегись, |3-6($c). Уважай наши традиции, иначе проклятие не минует тебя.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Берегись, |3-6($c). Уважай наши традиции, иначе проклятие не минует тебя.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`,`text2_0_loc8`,`text2_1_loc8`,`text3_0_loc8`,`text3_1_loc8`,`text4_0_loc8`,`text4_1_loc8`,`text5_0_loc8`,`text5_1_loc8`,`text6_0_loc8`,`text6_1_loc8`,`text7_0_loc8`,`text7_1_loc8`) VALUES (4445,'Тихо! Не видишь – мастер говорит?','Тихо! Не видишь – мастер говорит?','Меньше болтай, больше слушай.','Меньше болтай, больше слушай.','Мы должны сосредоточить усилия, чтобы создать собственную стаю!','Мы должны сосредоточить усилия, чтобы создать собственную стаю!','Тише! Я не хочу пропустить ни слова из этой лекции!','Тише! Я не хочу пропустить ни слова из этой лекции!','Где твоя студенческая форма? Ты думаешь, что мода важнее господства Плети?','Где твоя студенческая форма? Ты думаешь, что мода важнее господства Плети?','Ты $gсделал:сделала; вчерашнее задание? Если да, садись рядом!','Ты $gсделал:сделала; вчерашнее задание? Если да, садись рядом!','Осторожней здесь, $gмальчик:девочка;. Хозяин все видит…','Осторожней здесь, $gмальчик:девочка;. Хозяин все видит…','Ты $gпринес:принесла; свои учебники? Можно я посмотрю их вместе с тобой?','Ты $gпринес:принесла; свои учебники? Можно я посмотрю их вместе с тобой?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тихо! Не видишь – мастер говорит?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Тихо! Не видишь – мастер говорит?',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Меньше болтай, больше слушай.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Меньше болтай, больше слушай.',`text1_1_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Мы должны сосредоточить усилия, чтобы создать собственную стаю!',`text2_0_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Мы должны сосредоточить усилия, чтобы создать собственную стаю!',`text2_1_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Тише! Я не хочу пропустить ни слова из этой лекции!',`text3_0_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','Тише! Я не хочу пропустить ни слова из этой лекции!',`text3_1_loc8`), `text4_0_loc8`=IF(`text4_0_loc8` IS NULL OR `text4_0_loc8`='','Где твоя студенческая форма? Ты думаешь, что мода важнее господства Плети?',`text4_0_loc8`), `text4_1_loc8`=IF(`text4_1_loc8` IS NULL OR `text4_1_loc8`='','Где твоя студенческая форма? Ты думаешь, что мода важнее господства Плети?',`text4_1_loc8`), `text5_0_loc8`=IF(`text5_0_loc8` IS NULL OR `text5_0_loc8`='','Ты $gсделал:сделала; вчерашнее задание? Если да, садись рядом!',`text5_0_loc8`), `text5_1_loc8`=IF(`text5_1_loc8` IS NULL OR `text5_1_loc8`='','Ты $gсделал:сделала; вчерашнее задание? Если да, садись рядом!',`text5_1_loc8`), `text6_0_loc8`=IF(`text6_0_loc8` IS NULL OR `text6_0_loc8`='','Осторожней здесь, $gмальчик:девочка;. Хозяин все видит…',`text6_0_loc8`), `text6_1_loc8`=IF(`text6_1_loc8` IS NULL OR `text6_1_loc8`='','Осторожней здесь, $gмальчик:девочка;. Хозяин все видит…',`text6_1_loc8`), `text7_0_loc8`=IF(`text7_0_loc8` IS NULL OR `text7_0_loc8`='','Ты $gпринес:принесла; свои учебники? Можно я посмотрю их вместе с тобой?',`text7_0_loc8`), `text7_1_loc8`=IF(`text7_1_loc8` IS NULL OR `text7_1_loc8`='','Ты $gпринес:принесла; свои учебники? Можно я посмотрю их вместе с тобой?',`text7_1_loc8`);
