INSERT INTO `locales_npc_text` (`id`,`text2_0_loc8`) VALUES (4446,'Ты $gвернулся:вернулась; из Пылающих степей? Яйца черных драконов у тебя?') ON DUPLICATE KEY UPDATE `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Ты $gвернулся:вернулась; из Пылающих степей? Яйца черных драконов у тебя?',`text2_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`,`text2_0_loc8`,`text2_1_loc8`) VALUES (4449,'Мне и в голову не приходило, что этой штукой можно приманивать кодо! Интересно, а на меня самого подействует инкапсулятор?..','Мне и в голову не приходило, что этой штукой можно приманивать кодо! Интересно, а на меня самого подействует инкапсулятор?..','Почему гоблины и другие малорослые создания так восхищаются крупными существами?','Почему гоблины и другие малорослые создания так восхищаются крупными существами?','Как же гоблинам удается хотя бы навьючить этих тварей? Ведь любой кодо в десять раз больше гоблина!','Как же гоблинам удается хотя бы навьючить этих тварей? Ведь любой кодо в десять раз больше гоблина!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мне и в голову не приходило, что этой штукой можно приманивать кодо! Интересно, а на меня самого подействует инкапсулятор?..',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мне и в голову не приходило, что этой штукой можно приманивать кодо! Интересно, а на меня самого подействует инкапсулятор?..',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Почему гоблины и другие малорослые создания так восхищаются крупными существами?',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Почему гоблины и другие малорослые создания так восхищаются крупными существами?',`text1_1_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Как же гоблинам удается хотя бы навьючить этих тварей? Ведь любой кодо в десять раз больше гоблина!',`text2_0_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Как же гоблинам удается хотя бы навьючить этих тварей? Ведь любой кодо в десять раз больше гоблина!',`text2_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4473,'Рад нашей встрече, |3-6($c). Если у тебя нет какого-то особого дела к моей госпоже Магате, ты можешь поговорить со мной.$B$BЯ веду практически все ее дела, чтобы она могла сосредоточиться на более важных вещах. Возможно, нам есть что обсудить, перед тем как ты встретишься с ней?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Рад нашей встрече, |3-6($c). Если у тебя нет какого-то особого дела к моей госпоже Магате, ты можешь поговорить со мной.$B$BЯ веду практически все ее дела, чтобы она могла сосредоточиться на более важных вещах. Возможно, нам есть что обсудить, перед тем как ты встретишься с ней?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4476,'Только осмелься говорить со мной на равных, |3-6($c). Сильвана – моя королева, и я выполняю ее приказы.$B$BЕсли ты не окажешь ей должного уважения, то, уверяю тебя, мы с удовольствием найдем тебе подходящее местечко в Пустоте.$B$BНо если ты согласишься помочь Темной Госпоже, то мы не станем этого делать…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Только осмелься говорить со мной на равных, |3-6($c). Сильвана – моя королева, и я выполняю ее приказы.$B$BЕсли ты не окажешь ей должного уважения, то, уверяю тебя, мы с удовольствием найдем тебе подходящее местечко в Пустоте.$B$BНо если ты согласишься помочь Темной Госпоже, то мы не станем этого делать…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4493,'Я должен принести свои извинения за то, что не был достаточно честен с тобой в отношении своей персоны. Я хотел убедиться, что тебе можно доверять. Немногие бы стали бескорыстно помогать старому позабытому отшельнику…$B$BИ теперь я вижу, что ты входишь в число этих немногих.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я должен принести свои извинения за то, что не был достаточно честен с тобой в отношении своей персоны. Я хотел убедиться, что тебе можно доверять. Немногие бы стали бескорыстно помогать старому позабытому отшельнику…$B$BИ теперь я вижу, что ты входишь в число этих немногих.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4513,'Прислушивайся к чужим словам и не принимай поспешных решений, |3-6($c). Ибо даже у самых верных друзей могут быть свои интересы.$B$BНаш великий вождь знает это. Чтобы доказать ему, что не все чернокнижники стремятся разрушить или подчинить Орду, я вызвался помогать ему в любых начинаниях.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Прислушивайся к чужим словам и не принимай поспешных решений, |3-6($c). Ибо даже у самых верных друзей могут быть свои интересы.$B$BНаш великий вождь знает это. Чтобы доказать ему, что не все чернокнижники стремятся разрушить или подчинить Орду, я вызвался помогать ему в любых начинаниях.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (4516,'Ву Пинг невероятно вынослив. Глядя, как он несколько часов подряд тренируется с оружием, я начал жалеть учебный манекен. Лучшего учителя оружейных навыков и придумать трудно.','Ву Пинг невероятно вынослив. Глядя, как он несколько часов подряд тренируется с оружием, я начала жалеть учебный манекен. Лучшего учителя оружейных навыков и придумать трудно.','Мастер Ву Пинг владеет всеми известными видами оружия! Особенно хорошо он управляется с мечом. Большую часть времени он проводит в арсенале Веллера, ожидая новых поставок оружия.','Мастер Ву Пинг владеет всеми известными видами оружия! Особенно хорошо он управляется с мечом. Большую часть времени он проводит в арсенале Веллера, ожидая новых поставок оружия.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ву Пинг невероятно вынослив. Глядя, как он несколько часов подряд тренируется с оружием, я начал жалеть учебный манекен. Лучшего учителя оружейных навыков и придумать трудно.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ву Пинг невероятно вынослив. Глядя, как он несколько часов подряд тренируется с оружием, я начала жалеть учебный манекен. Лучшего учителя оружейных навыков и придумать трудно.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Мастер Ву Пинг владеет всеми известными видами оружия! Особенно хорошо он управляется с мечом. Большую часть времени он проводит в арсенале Веллера, ожидая новых поставок оружия.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Мастер Ву Пинг владеет всеми известными видами оружия! Особенно хорошо он управляется с мечом. Большую часть времени он проводит в арсенале Веллера, ожидая новых поставок оружия.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (4517,'За тысячелетия Илиения Лунное Пламя освоила многочисленные виды оружия и теперь может учить других. Ты можешь найти ее на Террасе Воинов, если хочешь поучиться.','За тысячелетия Илиения Лунное Пламя освоила многочисленные виды оружия и теперь может учить других. Ты можешь найти ее на Террасе Воинов, если хочешь поучиться.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','За тысячелетия Илиения Лунное Пламя освоила многочисленные виды оружия и теперь может учить других. Ты можешь найти ее на Террасе Воинов, если хочешь поучиться.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','За тысячелетия Илиения Лунное Пламя освоила многочисленные виды оружия и теперь может учить других. Ты можешь найти ее на Террасе Воинов, если хочешь поучиться.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text1_0_loc8`,`text1_1_loc8`) VALUES (4518,'Хочешь умело обращаться с новым оружием? Тогда тебе прямая дорога в оружейную лавку Лесной Границы. Поговори там с Бикси и Бульвайфом – они по части оружия настоящие асы.','Хочешь умело обращаться с новым оружием? Тогда тебе прямая дорога в оружейную лавку Лесной Границы. Поговори там с Бикси и Бульвайфом – они по части оружия настоящие асы.') ON DUPLICATE KEY UPDATE `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Хочешь умело обращаться с новым оружием? Тогда тебе прямая дорога в оружейную лавку Лесной Границы. Поговори там с Бикси и Бульвайфом – они по части оружия настоящие асы.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Хочешь умело обращаться с новым оружием? Тогда тебе прямая дорога в оружейную лавку Лесной Границы. Поговори там с Бикси и Бульвайфом – они по части оружия настоящие асы.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text1_0_loc8`) VALUES (4520,'Никто так не разбирается в оружии, как Ансеква. Говорят, его направляют духи самых лучших воинов наших достопочтимых предков. Ищи его на нижнем уровне, и он научит тебя всему, что тебе требуется знать.') ON DUPLICATE KEY UPDATE `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Никто так не разбирается в оружии, как Ансеква. Говорят, его направляют духи самых лучших воинов наших достопочтимых предков. Ищи его на нижнем уровне, и он научит тебя всему, что тебе требуется знать.',`text1_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (4521,'Тебе нужен Арчибальд. Ищи его возле оружейной лавки во внутреннем круге Квартала Воинов.','Тебе нужен Арчибальд. Ищи его возле оружейной лавки во внутреннем круге Квартала Воинов.','Редкий Отрекшийся владеет всеми видами оружия. Арчибальд владеет. Ищи его на внутреннем круге Квартала Воинов.','Редкий Отрекшийся владеет всеми видами оружия. Арчибальд владеет. Ищи его на внутреннем круге Квартала Воинов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тебе нужен Арчибальд. Ищи его возле оружейной лавки во внутреннем круге Квартала Воинов.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Тебе нужен Арчибальд. Ищи его возле оружейной лавки во внутреннем круге Квартала Воинов.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Редкий Отрекшийся владеет всеми видами оружия. Арчибальд владеет. Ищи его на внутреннем круге Квартала Воинов.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Редкий Отрекшийся владеет всеми видами оружия. Арчибальд владеет. Ищи его на внутреннем круге Квартала Воинов.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4533,'Ага, еще $gодин:одна; из нас. Хорошо, что наши ряды пополняются так быстро, что я уже не запоминаю всех новичков.$B$BЭтот дурак Тралл думает, что я работаю не покладая рук, дабы обелить чернокнижников и доказать, что мы его верные слуги! Идиот! Сначала Пылающий Легион исчерпает весь его мир, а потом сожжет его до основания!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ага, еще $gодин:одна; из нас. Хорошо, что наши ряды пополняются так быстро, что я уже не запоминаю всех новичков.$B$BЭтот дурак Тралл думает, что я работаю не покладая рук, дабы обелить чернокнижников и доказать, что мы его верные слуги! Идиот! Сначала Пылающий Легион исчерпает весь его мир, а потом сожжет его до основания!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4534,'Какая наивность. Пылающий Клинок и есть Совет Теней! Под его правлением существует много культов и организаций, но все они – лишь продолжение их воли. Хоть я и управляю Пылающим Клинком, я всего лишь пешка в руках Совета, как ты – в моих руках. Взгляни на Огненный меч – большинство из них думают, что становятся могущественными чернокнижниками и что они свергнут Совет Теней.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Какая наивность. Пылающий Клинок и есть Совет Теней! Под его правлением существует много культов и организаций, но все они – лишь продолжение их воли. Хоть я и управляю Пылающим Клинком, я всего лишь пешка в руках Совета, как ты – в моих руках. Взгляни на Огненный меч – большинство из них думают, что становятся могущественными чернокнижниками и что они свергнут Совет Теней.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4535,'Ха-ха! Разве что кроме их вожаков – сатира Баззалана и чернокнижника Джергоша. Потому-то я и посылаю к ним приспешников Тралла. Тралл думает, что я искореняю зло в недрах его великого города… На самом деле я убиваю двух зайцев сразу: искореняю сподвижников Тралла и проверяю на прочность адептов Пламенеющего Клинка.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ха-ха! Разве что кроме их вожаков – сатира Баззалана и чернокнижника Джергоша. Потому-то я и посылаю к ним приспешников Тралла. Тралл думает, что я искореняю зло в недрах его великого города… На самом деле я убиваю двух зайцев сразу: искореняю сподвижников Тралла и проверяю на прочность адептов Пламенеющего Клинка.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4536,'Вот что я тебе скажу. Ты явно чего-то стоишь, раз уж так быстро $gстал:стала; лейтенантом. Возможно, если ты вернешься ко мне позже, у меня будут особые поручения. Совет благоволит к тем, кто искусен в тайной магии, но ему нужны и другие специалисты.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вот что я тебе скажу. Ты явно чего-то стоишь, раз уж так быстро $gстал:стала; лейтенантом. Возможно, если ты вернешься ко мне позже, у меня будут особые поручения. Совет благоволит к тем, кто искусен в тайной магии, но ему нужны и другие специалисты.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (4633,'Опасные времена сейчас… Будь $gосторожен:осторожна;.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Опасные времена сейчас… Будь $gосторожен:осторожна;.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (4634,'Приветствую! Зачем вы пришли в Зимние Ключи? Эти холодные просторы могут показаться довольно унылыми, однако они таят немало секретов…') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Приветствую! Зачем вы пришли в Зимние Ключи? Эти холодные просторы могут показаться довольно унылыми, однако они таят немало секретов…',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (4635,'Какая жалосссть… Прошшшлое нельзззя изззменить…') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Какая жалосссть… Прошшшлое нельзззя изззменить…',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4673,'Садись и слушай мой рассказ, |3-6($r).') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Садись и слушай мой рассказ, |3-6($r).',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (4694,'Сунь маленькую монетку в руку босса и посмотри, что из этого выйдет. Обожаю мою работу. Хотя, если бы я смог найти способ перевести этого живчика Снорка в этот порт… ну, лучше не придумаешь. Но спорим, ты здесь не для того, чтобы выслушивать мои рабочие проблемы. Ты ищешь дирижабль до Подгорода, я прав? Ну, это замечательно, потому что он причаливает прямо позади меня. Кстати, если увидишь Снорка, замолви за меня словечко, ладно?','Сунь маленькую монетку в руку босса и посмотри, что из этого выйдет. Обожаю мою работу. Хотя, если бы я смогла найти способ перевести этого живчика Снорка в этот порт… ну, лучше не придумаешь. Но спорим, ты здесь не для того, чтобы выслушивать мои рабочие проблемы. Ты ищешь дирижабль до Подгорода, я права? Ну, это замечательно, потому что он причаливает прямо позади меня. Кстати, если увидишь Снорка, замолви за меня словечко, ладно?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Сунь маленькую монетку в руку босса и посмотри, что из этого выйдет. Обожаю мою работу. Хотя, если бы я смог найти способ перевести этого живчика Снорка в этот порт… ну, лучше не придумаешь. Но спорим, ты здесь не для того, чтобы выслушивать мои рабочие проблемы. Ты ищешь дирижабль до Подгорода, я прав? Ну, это замечательно, потому что он причаливает прямо позади меня. Кстати, если увидишь Снорка, замолви за меня словечко, ладно?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Сунь маленькую монетку в руку босса и посмотри, что из этого выйдет. Обожаю мою работу. Хотя, если бы я смогла найти способ перевести этого живчика Снорка в этот порт… ну, лучше не придумаешь. Но спорим, ты здесь не для того, чтобы выслушивать мои рабочие проблемы. Ты ищешь дирижабль до Подгорода, я права? Ну, это замечательно, потому что он причаливает прямо позади меня. Кстати, если увидишь Снорка, замолви за меня словечко, ладно?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4713,'Кошмару пришел конец! Дарроушир, прости меня!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Кошмару пришел конец! Дарроушир, прости меня!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4714,'Низвергнутый дух Лунокогтя пристально смотрит на вас, будто чего-то ожидая.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Низвергнутый дух Лунокогтя пристально смотрит на вас, будто чего-то ожидая.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4715,'Дух пристально смотрит тебе в глаза и берет тебя за руку. Твое тело пронзает тепло, и ты чуть не падаешь на колени. $B$BКогда тепло уходит, ты ощущаешь в себе едва заметное присутствие медвежьего духа… укрепляющего твою решимость.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Дух пристально смотрит тебе в глаза и берет тебя за руку. Твое тело пронзает тепло, и ты чуть не падаешь на колени. $B$BКогда тепло уходит, ты ощущаешь в себе едва заметное присутствие медвежьего духа… укрепляющего твою решимость.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4716,'Мы все пережили немало ужасных трагедий, но не стоит впадать в отчаяние.$B$BВместо этого надо хранить память о прошлом, чтобы однажды совершить святую месть.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы все пережили немало ужасных трагедий, но не стоит впадать в отчаяние.$B$BВместо этого надо хранить память о прошлом, чтобы однажды совершить святую месть.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4719,'Дух медведя устремляет на вас взгляд, исполненный покоя. От него словно бы исходит голос, хотя морда зверя остается неподвижной.$B$B"Приветствую тебя, $gмой юный друг:моя юная подруга;. Если ты $gпришел:пришла; ко мне в поисках знаний, возможно, я сумею тебе помочь".') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Дух медведя устремляет на вас взгляд, исполненный покоя. От него словно бы исходит голос, хотя морда зверя остается неподвижной.$B$B"Приветствую тебя, $gмой юный друг:моя юная подруга;. Если ты $gпришел:пришла; ко мне в поисках знаний, возможно, я сумею тебе помочь".',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4721,'Я – дух силы, которая поддерживает в тебе умения молодого друида. Я – сила тела и сила сердца. Ты $gпришел:пришла; сюда, уже зная обо мне, и будешь вспоминать меня каждый раз, принимая облик медведя.$B$BМолодой друид, поддерживай равновесие во всех своих начинаниях и сохраняй ясность мыслей. Когда ты будешь нуждаться в моей помощи… я буду неподалеку.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я – дух силы, которая поддерживает в тебе умения молодого друида. Я – сила тела и сила сердца. Ты $gпришел:пришла; сюда, уже зная обо мне, и будешь вспоминать меня каждый раз, принимая облик медведя.$B$BМолодой друид, поддерживай равновесие во всех своих начинаниях и сохраняй ясность мыслей. Когда ты будешь нуждаться в моей помощи… я буду неподалеку.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4733,'Крепость тела дает движениям силу и быстроту. Тело, как и дух, нуждается в закалке. Массивное тело медведя сразу дает понять: этот зверь силен и опасен в бою. Но в этом же теле скрывается гибкость и быстрый ум. Все это ты сможешь использовать во благо себе.$B$BЧтобы идти по пути Медведя, надо развивать крепость тела.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Крепость тела дает движениям силу и быстроту. Тело, как и дух, нуждается в закалке. Массивное тело медведя сразу дает понять: этот зверь силен и опасен в бою. Но в этом же теле скрывается гибкость и быстрый ум. Все это ты сможешь использовать во благо себе.$B$BЧтобы идти по пути Медведя, надо развивать крепость тела.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4734,'Сила сердца – то, что побуждает тебя к действию… если намерения твои чисты и праведны. Хранить равновесие – не значит прислуживать кому-то или отвергать все новое.$B$BПроявляй решимость в том, во что ты веришь и что $Gготов:готова; защищать. Медведица дерется до конца, защищая медвежат. Так же поступает и матерый медведь, защищая берлогу. Тебе нужно услышать зов сердца и научиться решимости, если хочешь постичь путь Медведя.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Сила сердца – то, что побуждает тебя к действию… если намерения твои чисты и праведны. Хранить равновесие – не значит прислуживать кому-то или отвергать все новое.$B$BПроявляй решимость в том, во что ты веришь и что $Gготов:готова; защищать. Медведица дерется до конца, защищая медвежат. Так же поступает и матерый медведь, защищая берлогу. Тебе нужно услышать зов сердца и научиться решимости, если хочешь постичь путь Медведя.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4735,'Будущее покажет, $gготов:готова; ли ты, $gюноша:девушка;. Даже самые мудрые и старые друиды никогда по-настоящему не успевают подготовиться к последнему испытанию.$B$BТы $gслышал:слышала; мои слова, ступай теперь с миром. Помни мои уроки. Твоей силе еще будет брошен вызов. Тебе придется встретиться лицом к лицу с врагом, как это сделал бы медведь – со всей крепостью тела и силой духа. Сражения должны многому тебя научить, $gюноша:девушка;. Ступай… я благословляю тебя.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Будущее покажет, $gготов:готова; ли ты, $gюноша:девушка;. Даже самые мудрые и старые друиды никогда по-настоящему не успевают подготовиться к последнему испытанию.$B$BТы $gслышал:слышала; мои слова, ступай теперь с миром. Помни мои уроки. Твоей силе еще будет брошен вызов. Тебе придется встретиться лицом к лицу с врагом, как это сделал бы медведь – со всей крепостью тела и силой духа. Сражения должны многому тебя научить, $gюноша:девушка;. Ступай… я благословляю тебя.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4774,'Стремись поддерживать равновесие во всем, |3-6($c). В этом основа истинной гармонии.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Стремись поддерживать равновесие во всем, |3-6($c). В этом основа истинной гармонии.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4775,'Добро пожаловать, $gбрат:сестра;. Если ты $gпришел:пришла; учиться, я с радостью помогу тебе.$B$BКаждый должен соответствовать своему месту в Великом Равновесии. А мы, как хранители этого равновесия, должны всегда сохранять ясность разума и силу сердца. Обучение помогает нам в этом.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать, $gбрат:сестра;. Если ты $gпришел:пришла; учиться, я с радостью помогу тебе.$B$BКаждый должен соответствовать своему месту в Великом Равновесии. А мы, как хранители этого равновесия, должны всегда сохранять ясность разума и силу сердца. Обучение помогает нам в этом.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4776,'Битва окончена. Жители Дарроушира спасены.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Битва окончена. Жители Дарроушира спасены.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (4783,'Даже за холодными каменными стенами, вроде тех, что окружают этот город, можно обрести мир и покой. И вообще, обрести их можно где угодно – надо лишь заглянуть внутрь себя.','Даже за холодными каменными стенами, вроде тех, что окружают этот город, можно обрести мир и покой. И вообще, обрести их можно где угодно – надо лишь заглянуть внутрь себя.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Даже за холодными каменными стенами, вроде тех, что окружают этот город, можно обрести мир и покой. И вообще, обрести их можно где угодно – надо лишь заглянуть внутрь себя.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Даже за холодными каменными стенами, вроде тех, что окружают этот город, можно обрести мир и покой. И вообще, обрести их можно где угодно – надо лишь заглянуть внутрь себя.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (4787,'Еще раз благодарю, $n! Я очень довольна нашими находками.$B$BУдачи тебе!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Еще раз благодарю, $n! Я очень довольна нашими находками.$B$BУдачи тебе!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (4794,'Мы лишь темные тени. Вечные тени. Невидимые.','Мы лишь темные тени. Вечные тени. Невидимые.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы лишь темные тени. Вечные тени. Невидимые.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мы лишь темные тени. Вечные тени. Невидимые.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (4796,'Я не могу учить тебя. Найди учителя своего класса.','Я не могу учить тебя. Найди учителя своего класса.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я не могу учить тебя. Найди учителя своего класса.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я не могу учить тебя. Найди учителя своего класса.',`text0_1_loc8`);
