INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (4797,'Не могу помочь тебе, $n. Я обучаю только разбойников.','Не могу помочь тебе, $n. Я обучаю только разбойников.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не могу помочь тебе, $n. Я обучаю только разбойников.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Не могу помочь тебе, $n. Я обучаю только разбойников.',`text0_1_loc8`);
