INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (4799,'Извини, но я обучаю только разбойников.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Извини, но я обучаю только разбойников.',`text0_1_loc8`);
