INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4813,'А… $gклиент:клиентка;! Давайте поговорим о моем величайшем изобретении – о "Торготроне 1000". В нем есть все, что вам нужно… некоторые редчайшие предметы вы не найдете ни на одном рынке Калимдора… а еще его программирование не допускает торга. Какую цену вы видите, ту и платите.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','А… $gклиент:клиентка;! Давайте поговорим о моем величайшем изобретении – о "Торготроне 1000". В нем есть все, что вам нужно… некоторые редчайшие предметы вы не найдете ни на одном рынке Калимдора… а еще его программирование не допускает торга. Какую цену вы видите, ту и платите.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4814,'Еще $gодин простак, решивший:одна наивная особа, решившая; послужить Темной Госпоже…$B$B<Натанос вздыхает.>$B$BВсех ваших предшественников я отправил ей обратно… по частям. Почему бы сейчас не поступить так же?$B$BВпрочем, на этот раз я не буду задаваться вопросом, а просто выполню просьбу Госпожи.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Еще $gодин простак, решивший:одна наивная особа, решившая; послужить Темной Госпоже…$B$B<Натанос вздыхает.>$B$BВсех ваших предшественников я отправил ей обратно… по частям. Почему бы сейчас не поступить так же?$B$BВпрочем, на этот раз я не буду задаваться вопросом, а просто выполню просьбу Госпожи.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4815,'Тебе повезло: я только что закончил чинить "Робо-торговца 680". Его ассортимент огромен, а цены порадуют даже самого скупого дворфа. Да ты $gсам:сама; посмотри! Правда, мой брат Корк считает, что его "Торготрон 1000" будет торговать лучше…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тебе повезло: я только что закончил чинить "Робо-торговца 680". Его ассортимент огромен, а цены порадуют даже самого скупого дворфа. Да ты $gсам:сама; посмотри! Правда, мой брат Корк считает, что его "Торготрон 1000" будет торговать лучше…',`text0_0_loc8`);
