INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (4835,'Ты, похоже, из тех, при ком лучше не спускать глаз со своего кошелька. Чем я могу тебе помочь?','Ты, похоже, из тех, при ком лучше не спускать глаз со своего кошелька. Чем я могу тебе помочь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты, похоже, из тех, при ком лучше не спускать глаз со своего кошелька. Чем я могу тебе помочь?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты, похоже, из тех, при ком лучше не спускать глаз со своего кошелька. Чем я могу тебе помочь?',`text0_1_loc8`);
