INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4841,'Приветствую тебя, $gдруг мой:подруга;. Да хранит тебя Рассвет в эти нелегкие времена.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приветствую тебя, $gдруг мой:подруга;. Да хранит тебя Рассвет в эти нелегкие времена.',`text0_0_loc8`);
