INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (4855,'Считай, что ты и не $gвидел:видела; настоящих скакунов, пока не $gоседлал:оседлала; породистого горного барана Барак Торола. Не стесняйся, осмотри внимательно этих достойных спутников искателя приключений. Поверь, любой из них отлично послужит тебе.','Считай, что ты и не $gвидел:видела; настоящих скакунов, пока не $gоседлал:оседлала; породистого горного барана Барак Торола. Не стесняйся, осмотри внимательно этих достойных спутников искателя приключений. Поверь, любой из них отлично послужит тебе.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Считай, что ты и не $gвидел:видела; настоящих скакунов, пока не $gоседлал:оседлала; породистого горного барана Барак Торола. Не стесняйся, осмотри внимательно этих достойных спутников искателя приключений. Поверь, любой из них отлично послужит тебе.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Считай, что ты и не $gвидел:видела; настоящих скакунов, пока не $gоседлал:оседлала; породистого горного барана Барак Торола. Не стесняйся, осмотри внимательно этих достойных спутников искателя приключений. Поверь, любой из них отлично послужит тебе.',`text0_1_loc8`);
