INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4856,'Я – механический торговец последнего поколения… когда-нибудь мы захватим мир… не говорите шефу, что я ворую деньги с его продаж…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я – механический торговец последнего поколения… когда-нибудь мы захватим мир… не говорите шефу, что я ворую деньги с его продаж…',`text0_0_loc8`);
