INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4857,'Моя программа не позволяет мне снижать цены на товары.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Моя программа не позволяет мне снижать цены на товары.',`text0_0_loc8`);
