INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (4861,'Прежде чем начинать охоту, стоит расспросить кого-нибудь о ее цели.','Прежде чем начинать охоту, стоит расспросить кого-нибудь о ее цели.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Прежде чем начинать охоту, стоит расспросить кого-нибудь о ее цели.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Прежде чем начинать охоту, стоит расспросить кого-нибудь о ее цели.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (4862,'Взгляни на кодо, $gдруг мой:уважаемая;! Из этих зверей, приручаемых с малых лет и выпасаемых на золотистых равнинах Мулгора, получатся превосходные скакуны! Прошу, осмотри моих животных, и $gсам:сама; поймешь, почему мы, таурены, так полагаемся на них!','Взгляни на кодо, $gдруг мой:уважаемая;! Из этих зверей, приручаемых с малых лет и выпасаемых на золотистых равнинах Мулгора, получатся превосходные скакуны! Прошу, осмотри моих животных, и $gсам:сама; поймешь, почему мы, таурены, так полагаемся на них!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Взгляни на кодо, $gдруг мой:уважаемая;! Из этих зверей, приручаемых с малых лет и выпасаемых на золотистых равнинах Мулгора, получатся превосходные скакуны! Прошу, осмотри моих животных, и $gсам:сама; поймешь, почему мы, таурены, так полагаемся на них!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Взгляни на кодо, $gдруг мой:уважаемая;! Из этих зверей, приручаемых с малых лет и выпасаемых на золотистых равнинах Мулгора, получатся превосходные скакуны! Прошу, осмотри моих животных, и $gсам:сама; поймешь, почему мы, таурены, так полагаемся на них!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4864,'Давайте я научу вас охотничьим премудростям.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Давайте я научу вас охотничьим премудростям.',`text0_0_loc8`);
