INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4866,'Я много знаю и многое могу тебе поведать, |3-6($c). Научись же охотиться честно.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я много знаю и многое могу тебе поведать, |3-6($c). Научись же охотиться честно.',`text0_0_loc8`);
