INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (4869,'От имени Королевского фармацевтического общества я рада предложить вам лучших скакунов, какие только есть у Отрекшихся. Эти кони прошли вместе с нами все испытания и невзгоды, и теперь они сильнее и выносливее своих живых сородичей! Взгляните и убедитесь!','От имени Королевского фармацевтического общества я рада предложить вам лучших скакунов, какие только есть у Отрекшихся. Эти кони прошли вместе с нами все испытания и невзгоды, и теперь они сильнее и выносливее своих живых сородичей! Взгляните и убедитесь!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','От имени Королевского фармацевтического общества я рада предложить вам лучших скакунов, какие только есть у Отрекшихся. Эти кони прошли вместе с нами все испытания и невзгоды, и теперь они сильнее и выносливее своих живых сородичей! Взгляните и убедитесь!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','От имени Королевского фармацевтического общества я рада предложить вам лучших скакунов, какие только есть у Отрекшихся. Эти кони прошли вместе с нами все испытания и невзгоды, и теперь они сильнее и выносливее своих живых сородичей! Взгляните и убедитесь!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (4870,'Иди и познай путь охотников. Их гордость, славу и традиции.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Иди и познай путь охотников. Их гордость, славу и традиции.',`text0_1_loc8`);
