INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (4879,'Я могу научить тебя более быстрой езде на волке, конечно, если у тебя хватит золота заплатить за этот урок!','Я могу научить тебя более быстрой езде на волке, конечно, если у тебя хватит золота заплатить за этот урок!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я могу научить тебя более быстрой езде на волке, конечно, если у тебя хватит золота заплатить за этот урок!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я могу научить тебя более быстрой езде на волке, конечно, если у тебя хватит золота заплатить за этот урок!',`text0_1_loc8`);
