INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (4881,'Учить тебя вождению механодолгонога – пустая трата моего времени и твоего золота, |3-6($c). Больно уж ты $Gздоровый:широка в кости;.','Учить тебя вождению механодолгонога – пустая трата моего времени и твоего золота, |3-6($c). Больно уж ты $Gздоровый:широка в кости;.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Учить тебя вождению механодолгонога – пустая трата моего времени и твоего золота, |3-6($c). Больно уж ты $Gздоровый:широка в кости;.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Учить тебя вождению механодолгонога – пустая трата моего времени и твоего золота, |3-6($c). Больно уж ты $Gздоровый:широка в кости;.',`text0_1_loc8`);
