INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4888,'Я учу и наставляю молодых охотников в традициях, проверенных многими поколениями.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я учу и наставляю молодых охотников в традициях, проверенных многими поколениями.',`text0_0_loc8`);
