INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4890,'Если ты здесь, чтобы научиться стратегии и тактике охоты, то $gпришел:пришла; точно по адресу!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если ты здесь, чтобы научиться стратегии и тактике охоты, то $gпришел:пришла; точно по адресу!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (4893,'Взгляните, какой мудростью и знаниями обладает животное, – и все поймете. Научитесь у совы наблюдательности, у саблезуба – уму, а от волка переймите неукротимый дух.','Взгляните, какой мудростью и знаниями обладает животное, – и все поймете. Научитесь у совы наблюдательности, у саблезуба – уму, а от волка переймите неукротимый дух.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Взгляните, какой мудростью и знаниями обладает животное, – и все поймете. Научитесь у совы наблюдательности, у саблезуба – уму, а от волка переймите неукротимый дух.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Взгляните, какой мудростью и знаниями обладает животное, – и все поймете. Научитесь у совы наблюдательности, у саблезуба – уму, а от волка переймите неукротимый дух.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (4913,'Ты не друид!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты не друид!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (4915,'Если вы хотите улететь обратно в Громовой Утес, поговорите с моим товарищем Бунтеном Ветром Равнин.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Если вы хотите улететь обратно в Громовой Утес, поговорите с моим товарищем Бунтеном Ветром Равнин.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4916,'Ты не друид!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты не друид!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4917,'Если хочешь полететь в деревню Рут\'теран, поговори с моей подругой Сильвой Фил\'навет. Она из ночных эльфов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если хочешь полететь в деревню Рут\'теран, поговори с моей подругой Сильвой Фил\'навет. Она из ночных эльфов.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4918,'Не хотите ли совершить полет в Громовой Утес? Услугу предоставляет Круг Кенария.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не хотите ли совершить полет в Громовой Утес? Услугу предоставляет Круг Кенария.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4936,'Ах, красота Тенистой долины никогда не перестанет восхищать меня!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ах, красота Тенистой долины никогда не перестанет восхищать меня!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4938,'Эй! Ты крепко $gсложен:сложена;, а у нас тут стражей не хватает. Нам бы не помешала твоя помощь…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эй! Ты крепко $gсложен:сложена;, а у нас тут стражей не хватает. Нам бы не помешала твоя помощь…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4953,'Раз уж вы мне помогли, я расскажу вам все, что знаю об этой земле. Знаю я немного, но, может быть, я вспомню что-нибудь такое, что вас заинтересует.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Раз уж вы мне помогли, я расскажу вам все, что знаю об этой земле. Знаю я немного, но, может быть, я вспомню что-нибудь такое, что вас заинтересует.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4954,'Я немногое знаю о ночных эльфах, но говорят, что давным-давно, когда они еще владели священным искусством тайной магии, Азшара была величайшей среди них. Прекрасная леди, которую они называли королевой. Увы, но ее пристрастие к магии погубило ее... и привело к ужасным последствиям для всего мира.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я немногое знаю о ночных эльфах, но говорят, что давным-давно, когда они еще владели священным искусством тайной магии, Азшара была величайшей среди них. Прекрасная леди, которую они называли королевой. Увы, но ее пристрастие к магии погубило ее... и привело к ужасным последствиям для всего мира.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4955,'Когда-то этим великим городом ночных эльфов правили могущественные маги-высокорожденные. Но потом на них пало проклятие. Теперь они бесплотными духами рыщут по земле, а их город захватили наги из клана Бича Злобы. Похоже, этих полузмей интересуют артефакты высокорожденных, оставшиеся в руинах.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Когда-то этим великим городом ночных эльфов правили могущественные маги-высокорожденные. Но потом на них пало проклятие. Теперь они бесплотными духами рыщут по земле, а их город захватили наги из клана Бича Злобы. Похоже, этих полузмей интересуют артефакты высокорожденных, оставшиеся в руинах.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4956,'Говорят, что на севере живет могущественный маг-человек, который зачем-то следит за тамошними землями. Сам я там не был, но мне рассказывали, что он всегда рад гостям и щедро платит тем, кто ему помогает.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Говорят, что на севере живет могущественный маг-человек, который зачем-то следит за тамошними землями. Сам я там не был, но мне рассказывали, что он всегда рад гостям и щедро платит тем, кто ему помогает.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4957,'Я был свидетелем многих бедствий, которые постигли фурболгов за последние несколько лет. Но я так и не выяснил, почему они изменились. Может быть, их коснулась чума из Оскверненного леса? А может, они просто утратили свое миролюбие и ожесточилось на мир? В любом случае они враждебно относятся ко всем, кто приходит в их земли.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я был свидетелем многих бедствий, которые постигли фурболгов за последние несколько лет. Но я так и не выяснил, почему они изменились. Может быть, их коснулась чума из Оскверненного леса? А может, они просто утратили свое миролюбие и ожесточилось на мир? В любом случае они враждебно относятся ко всем, кто приходит в их земли.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (4958,'Самих синих драконов здесь нет, но последователи Малигоса здесь. Я не знаю причин этого, но могу сказать тебе следующее: где бы ни был синий дракон, можно ожидать тайной магии. Я не удивился бы, если бы драконоиды здесь что-то защищали... может быть, что-то, что оставили за собой высокорожденные.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Самих синих драконов здесь нет, но последователи Малигоса здесь. Я не знаю причин этого, но могу сказать тебе следующее: где бы ни был синий дракон, можно ожидать тайной магии. Я не удивился бы, если бы драконоиды здесь что-то защищали... может быть, что-то, что оставили за собой высокорожденные.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (4959,'Мне нужно кого-нибудь нанять. Я уже устала сидеть тут целыми днями и продавать рыболовные снасти. Лучше было бы отправиться на рыбалку, а потом продать улов.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мне нужно кого-нибудь нанять. Я уже устала сидеть тут целыми днями и продавать рыболовные снасти. Лучше было бы отправиться на рыбалку, а потом продать улов.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
