INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (5007,'Да пребудут с тобой духи. Чем тролли могут тебе помочь?','Да пребудут с тобой духи. Чем тролли могут тебе помочь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да пребудут с тобой духи. Чем тролли могут тебе помочь?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Да пребудут с тобой духи. Чем тролли могут тебе помочь?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (5008,'Да хранят тебя духи.','Да хранят тебя духи.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да хранят тебя духи.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Да хранят тебя духи.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5009,'Куда путь держишь? Ну, если ты ищешь способ добраться туда быстрее, то $gобратился:обратилась; куда надо!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Куда путь держишь? Ну, если ты ищешь способ добраться туда быстрее, то $gобратился:обратилась; куда надо!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5010,'Я снабжаю Сторожевой холм, хотя сейчас это не так-то просто.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я снабжаю Сторожевой холм, хотя сейчас это не так-то просто.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5013,'Здравствуйте, $gгосподин:госпожа;. Я бы пожал вам руку, но, как видите, порядком занят. Чем могу служить?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здравствуйте, $gгосподин:госпожа;. Я бы пожал вам руку, но, как видите, порядком занят. Чем могу служить?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5016,'Сидя в этом домишке, я мечтаю о великих битвах, которые гремят за городскими стенами. Но долг велит мне делиться знаниями с теми, кто сражается вместо меня… пока.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Сидя в этом домишке, я мечтаю о великих битвах, которые гремят за городскими стенами. Но долг велит мне делиться знаниями с теми, кто сражается вместо меня… пока.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5021,'Ваше мастерство уже превосходит мое. Вам нужен другой учитель. Советую вам обратиться к Лилиссии Ночной Бриз – она живет неподалеку и очень много знает.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ваше мастерство уже превосходит мое. Вам нужен другой учитель. Советую вам обратиться к Лилиссии Ночной Бриз – она живет неподалеку и очень много знает.',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5022,'Друиды говорят, что со временем природа сама изгонит Орду из Калимдора. Но порча продолжает охватывать землю, она проникла даже сюда, в Тельдрассил.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Друиды говорят, что со временем природа сама изгонит Орду из Калимдора. Но порча продолжает охватывать землю, она проникла даже сюда, в Тельдрассил.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5023,'Отлично! Ты быстро учишься варить зелья.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Отлично! Ты быстро учишься варить зелья.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5024,'К сожалению, немногому я могу обучить кого-то с таким опытом, друг мой. Ищи ночную эльфийку Сильванну Лесная Луна, живущую на Террасе ремесленников в Дарнасе.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','К сожалению, немногому я могу обучить кого-то с таким опытом, друг мой. Ищи ночную эльфийку Сильванну Лесная Луна, живущую на Террасе ремесленников в Дарнасе.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5026,'Разве не изумительно, сколько всего можно создавать из даров леса? Поистине, Элуна благословила нас своей милостью.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Разве не изумительно, сколько всего можно создавать из даров леса? Поистине, Элуна благословила нас своей милостью.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5027,'Очень мило с вашей стороны, что обратились ко мне, но я вряд ли смогу вас чему-то научить. Поговорите с Сильванной Лесной Луной. Она как раз ищет учеников.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Очень мило с вашей стороны, что обратились ко мне, но я вряд ли смогу вас чему-то научить. Поговорите с Сильванной Лесной Луной. Она как раз ищет учеников.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5028,'Это моя девочка Кали прислала тебя ко мне? Как же я ее люблю!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Это моя девочка Кали прислала тебя ко мне? Как же я ее люблю!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5029,'Вряд ли ты $gпришел:пришла;, чтобы поговорить о моей любимой Кали. Ну и ладно. Зелья так зелья. Тебе еще не говорили, что ты зануда?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вряд ли ты $gпришел:пришла;, чтобы поговорить о моей любимой Кали. Ну и ладно. Зелья так зелья. Тебе еще не говорили, что ты зануда?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5031,'Пусть эти большие невинные глаза тебя не обманывают. Талли свое дело знает – я каждый день чему-то новому учусь. С чего я, по-твоему, в Город Механиков подался? Я что, похож на инженера? Вот и я думаю, что нет.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Пусть эти большие невинные глаза тебя не обманывают. Талли свое дело знает – я каждый день чему-то новому учусь. С чего я, по-твоему, в Город Механиков подался? Я что, похож на инженера? Вот и я думаю, что нет.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5032,'Выкладывайся полностью, $gпарень:девушка;. Терпение и труд все перетрут! И не верь тем, кто говорит, что любое дело можно выучить по книгам!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Выкладывайся полностью, $gпарень:девушка;. Терпение и труд все перетрут! И не верь тем, кто говорит, что любое дело можно выучить по книгам!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5034,'Похоже, тебя тянет на приключения. А я от них уже устал еще до того, как мы, тролли, пришли сюда. Теперь я радуюсь каждому дню и обучаю других тому, что может понадобиться в приключениях.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Похоже, тебя тянет на приключения. А я от них уже устал еще до того, как мы, тролли, пришли сюда. Теперь я радуюсь каждому дню и обучаю других тому, что может понадобиться в приключениях.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5035,'$GГотов:Готова; к следующему уроку? Ну, хорошо. Во-первых, расслабься. Ты $gдолжен:должна; чувствовать себя свободно, чтобы приготовить это зелье.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','$GГотов:Готова; к следующему уроку? Ну, хорошо. Во-первых, расслабься. Ты $gдолжен:должна; чувствовать себя свободно, чтобы приготовить это зелье.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5037,'Во всех этих бутылочках зелья, которые я сварил сегодня. А говорят еще, что если на горшок смотреть, он никогда не закипит! Ха!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Во всех этих бутылочках зелья, которые я сварил сегодня. А говорят еще, что если на горшок смотреть, он никогда не закипит! Ха!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5038,'Меня обзывали дураком, но я им всем покажу! Буду присматривать за всеми котлами и докажу, что все годятся для варки. Да, я теперь в ударе! И кто из нас дурак, а? А?!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Меня обзывали дураком, но я им всем покажу! Буду присматривать за всеми котлами и докажу, что все годятся для варки. Да, я теперь в ударе! И кто из нас дурак, а? А?!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5039,'Ничем не могу помочь. Ты знаешь о зельях больше меня. А мне еще за горшками следить надо. Поговори с Йелмаком. Он о зельях многое знает.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ничем не могу помочь. Ты знаешь о зельях больше меня. А мне еще за горшками следить надо. Поговори с Йелмаком. Он о зельях многое знает.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5040,'Бена работает, как одержимая. День и ночь она корпит над своими зельями, не отвлекаясь ни на сон, ни на еду. Я знаю, что нашим союзникам-нежити необходима помощь, но начинаю опасаться, что она себе повредит.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Бена работает, как одержимая. День и ночь она корпит над своими зельями, не отвлекаясь ни на сон, ни на еду. Я знаю, что нашим союзникам-нежити необходима помощь, но начинаю опасаться, что она себе повредит.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5041,'Прежде чем у меня начали получаться зелья, я разбил больше сотни склянок. Это стекло такое хрупкое... Надеюсь, ты будешь половчее меня.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Прежде чем у меня начали получаться зелья, я разбил больше сотни склянок. Это стекло такое хрупкое... Надеюсь, ты будешь половчее меня.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5042,'Теперь ты знаешь все, что известно мне. Дальнейшие указания тебе даст Бена Заиндевевшее Копыто. Но не отнимай у нее слишком много времени – ей надо больше отдыхать.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Теперь ты знаешь все, что известно мне. Дальнейшие указания тебе даст Бена Заиндевевшее Копыто. Но не отнимай у нее слишком много времени – ей надо больше отдыхать.',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5043,'Приятно видеть дружелюбное лицо... Аптекарь Юхан не слишком-то разговорчив – рот открывает, только когда ему чего-то надо. Слишком уж давно он из могилы вылез. Наверно, и я когда-нибудь стану такой же. Да уж. Но, может быть, мне будет уже все равно.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Приятно видеть дружелюбное лицо... Аптекарь Юхан не слишком-то разговорчив – рот открывает, только когда ему чего-то надо. Слишком уж давно он из могилы вылез. Наверно, и я когда-нибудь стану такой же. Да уж. Но, может быть, мне будет уже все равно.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5044,'Хочешь узнать о зельях? Да, это ты правильно ко мне $gпришел:пришла;. Я хоть и мертвая, но мозгов не растеряла. Пока что.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Хочешь узнать о зельях? Да, это ты правильно ко мне $gпришел:пришла;. Я хоть и мертвая, но мозгов не растеряла. Пока что.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5045,'Мне приятна ваша компания, но ничего не поделаешь – вы готовите зелья лучше меня. Если хотите учиться дальше, поговорите с доктором Маршем в Районе Фармацевтов, что в Подгороде.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мне приятна ваша компания, но ничего не поделаешь – вы готовите зелья лучше меня. Если хотите учиться дальше, поговорите с доктором Маршем в Районе Фармацевтов, что в Подгороде.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5047,'Очень хорошо. Срежь еще кусочек плоти с одного из образцов. Проверим, чему ты $gнаучился:научилась;, и продолжим.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Очень хорошо. Срежь еще кусочек плоти с одного из образцов. Проверим, чему ты $gнаучился:научилась;, и продолжим.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5048,'Твое знание о зельях превосходит мое, но тебе еще предстоит многому научиться. Поднимись по ступеням на юго-востоке и обратись к доктору Маршу. Он покажет, что такое настоящие страдани... кхм. Твой будущий учитель – из Отрекшихся.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Твое знание о зельях превосходит мое, но тебе еще предстоит многому научиться. Поднимись по ступеням на юго-востоке и обратись к доктору Маршу. Он покажет, что такое настоящие страдани... кхм. Твой будущий учитель – из Отрекшихся.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5049,'Не смотри больше на меня так. Может быть, я не $gискатель:искательница; приключений вроде тебя, но это не значит, что у меня не может быть мышц. Все эти помешивания укрепляют руки.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не смотри больше на меня так. Может быть, я не $gискатель:искательница; приключений вроде тебя, но это не значит, что у меня не может быть мышц. Все эти помешивания укрепляют руки.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5053,'Ищешь моей помощи? Считай, что ты ее $gнашел:нашла;. Что тебе нужно?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ищешь моей помощи? Считай, что ты ее $gнашел:нашла;. Что тебе нужно?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5054,'Не дай маленьким ушам и густой бороде обмануть тебя. Восур талантливый ученик и хороший друг, даже если мне приходится растягивать шейную мышцу, чтобы поговорить с ним.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Не дай маленьким ушам и густой бороде обмануть тебя. Восур талантливый ученик и хороший друг, даже если мне приходится растягивать шейную мышцу, чтобы поговорить с ним.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5055,'Хм, я уже научила вас всему, что знала сама. Наверное, вам нужно обратиться к кому-то еще. Попробуйте поговорить с Айнетиль на Террасе ремесленников в Дарнасе. Она много чего знает!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Хм, я уже научила вас всему, что знала сама. Наверное, вам нужно обратиться к кому-то еще. Попробуйте поговорить с Айнетиль на Террасе ремесленников в Дарнасе. Она много чего знает!',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5058,'Кто ты и почему меня беспокоишь? А, ну да, ты изучаешь зелья. Верно. Чем могу помочь?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Кто ты и почему меня беспокоишь? А, ну да, ты изучаешь зелья. Верно. Чем могу помочь?',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5063,'Хоть мне и лестно, что ты так веришь в мои способности, но мне нечему тебя учить. Иди в Дарнас, найди там Террасу ремесленников и поговори с ночной эльфийкой Айнетиль. Она тебе поможет.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Хоть мне и лестно, что ты так веришь в мои способности, но мне нечему тебя учить. Иди в Дарнас, найди там Террасу ремесленников и поговори с ночной эльфийкой Айнетиль. Она тебе поможет.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5064,'Даже малейшее изменение состава зелья может полностью изменить его эффект. Терпение и аккуратность, $gюноша:девушка;, вот что сослужит тебе добрую службу в жизни.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Даже малейшее изменение состава зелья может полностью изменить его эффект. Терпение и аккуратность, $gюноша:девушка;, вот что сослужит тебе добрую службу в жизни.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5065,'Ты разбираешься в зельях намного лучше меня. Поговори с Айнетиль, стоящей рядом со мной. Она сразу поймет, что ты $gготов:готова; к дальнейшему обучению.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты разбираешься в зельях намного лучше меня. Поговори с Айнетиль, стоящей рядом со мной. Она сразу поймет, что ты $gготов:готова; к дальнейшему обучению.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5072,'Ты говоришь не с тем орком. Я не тренирую новичков. Иди к молодому Вууту... и постарайся говорить попроще.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты говоришь не с тем орком. Я не тренирую новичков. Иди к молодому Вууту... и постарайся говорить попроще.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5073,'Еще $gодин ученик:одна ученица;? Ну ладно. Посмотрим, чем я смогу тебе помочь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Еще $gодин ученик:одна ученица;? Ну ладно. Посмотрим, чем я смогу тебе помочь.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5074,'Мы с Гликсом отлично друг друга понимаем. Он доставляет мне товары, а я делаю его богатым. Серьезно! Знал бы ты, сколько этот пират сдирает с меня за каждый пучок королевской крови… Достаточно, чтобы гоблин расплакался!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы с Гликсом отлично друг друга понимаем. Он доставляет мне товары, а я делаю его богатым. Серьезно! Знал бы ты, сколько этот пират сдирает с меня за каждый пучок королевской крови… Достаточно, чтобы гоблин расплакался!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5075,'У меня множество рецептов и низкие цены!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','У меня множество рецептов и низкие цены!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5078,'Ты $gпревзошел:превзошла; меня! Тебе нужен более опытный наставник. Например, Айнетиль.Эта ночная эльфийка живет в Дарнасе, на террасе Ремесленников.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты $gпревзошел:превзошла; меня! Тебе нужен более опытный наставник. Например, Айнетиль.Эта ночная эльфийка живет в Дарнасе, на террасе Ремесленников.',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5081,'Я не могу тратить время на новичков, пока наши союзники из нежити терпят такие мучения. Пожалуйста, обратитесь к Крею – вон там, – он вам поможет.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я не могу тратить время на новичков, пока наши союзники из нежити терпят такие мучения. Пожалуйста, обратитесь к Крею – вон там, – он вам поможет.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5083,'Ты варишь зелья лучше меня. Отыщи доктора Герберта Галси – он из нежити, его можно встретить в Подгороде, в Районе Фармацевтов. Поучишься у него, а заодно сам посмотришь на участь его народа…') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты варишь зелья лучше меня. Отыщи доктора Герберта Галси – он из нежити, его можно встретить в Подгороде, в Районе Фармацевтов. Поучишься у него, а заодно сам посмотришь на участь его народа…',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5085,'Мне? Учить вас? Вы сами прекрасно знаете, что я не могу! Если вам нужен учитель, поговорите с доктором Гербертом Галси, Отрекшимся из Района Фармацевтов Подгорода.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мне? Учить вас? Вы сами прекрасно знаете, что я не могу! Если вам нужен учитель, поговорите с доктором Гербертом Галси, Отрекшимся из Района Фармацевтов Подгорода.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5087,'Не отнимай у меня время. Я работаю над проектами, которые старше тебя. Иди поговори с доктором Мартином Фелбеном в Районе Фармацевтов Подгорода. Он Отрекшийся, который, возможно, сможет научить тебя основам.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не отнимай у меня время. Я работаю над проектами, которые старше тебя. Иди поговори с доктором Мартином Фелбеном в Районе Фармацевтов Подгорода. Он Отрекшийся, который, возможно, сможет научить тебя основам.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5089,'Благодаря Алжернону я могу работать, не отвлекаясь на каждую травку. Если мне и суждено распрощаться с чудесами природы, это будет нескоро.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Благодаря Алжернону я могу работать, не отвлекаясь на каждую травку. Если мне и суждено распрощаться с чудесами природы, это будет нескоро.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5090,'У меня больше нет знаний, чтобы дать тебе. Иди через арку и вниз по скату на юго-восток и поговори с доктором Герберт Галси. Он Отрекшийся, который может тебя научить более продвинутым техникам.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','У меня больше нет знаний, чтобы дать тебе. Иди через арку и вниз по скату на юго-восток и поговори с доктором Герберт Галси. Он Отрекшийся, который может тебя научить более продвинутым техникам.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5092,'У тебя достаточно нахальства, чтобы прийти ко мне учиться, но я не могу сказать того же о твоих знаниях. Пройди через арку и спустись по склону на юго-восток, там поговоришь с доктором Мартином Фелбеном. Он из Отрекшихся, и он может преподать тебе основы.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','У тебя достаточно нахальства, чтобы прийти ко мне учиться, но я не могу сказать того же о твоих знаниях. Пройди через арку и спустись по склону на юго-восток, там поговоришь с доктором Мартином Фелбеном. Он из Отрекшихся, и он может преподать тебе основы.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5093,'$GПришел:Пришла; учиться? Очень хорошо. Думаю, то, что я возьмусь тебя учить, не слишком повредит нашим друзьям. Особенно если ты будешь вредить нашим врагам.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','$GПришел:Пришла; учиться? Очень хорошо. Думаю, то, что я возьмусь тебя учить, не слишком повредит нашим друзьям. Особенно если ты будешь вредить нашим врагам.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5094,'Мне кажется, что каждое новое зелье теряет в лечебной силе, хотя состав я не меняю. Вывод отсюда только один: меняются сами растения. Во что они превращаются и почему – я пока не знаю.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мне кажется, что каждое новое зелье теряет в лечебной силе, хотя состав я не меняю. Вывод отсюда только один: меняются сами растения. Во что они превращаются и почему – я пока не знаю.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5095,'Пора тебе посетить более мудрого учителя. В Фераласе, в Крепости Оперенной Луны, живет ночная эльфийка Кайланна Шепот Ветра. У нее блестящий ум; без сомнения, она сможет многому тебя научить.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Пора тебе посетить более мудрого учителя. В Фераласе, в Крепости Оперенной Луны, живет ночная эльфийка Кайланна Шепот Ветра. У нее блестящий ум; без сомнения, она сможет многому тебя научить.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5097,'Тебе нужно подучить основы алхимии, прежде чем ты сможешь стать $gмоим учеником:моей ученицей;. Обратись к Сильванне Лесной Луне или Милле Фаранкоре.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Тебе нужно подучить основы алхимии, прежде чем ты сможешь стать $gмоим учеником:моей ученицей;. Обратись к Сильванне Лесной Луне или Милле Фаранкоре.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5098,'Ты быстро учишься. Ты $gдолжен:должна; гордиться своими успехами.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты быстро учишься. Ты $gдолжен:должна; гордиться своими успехами.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5099,'Мы с коллегами собираем все известные яды и испытываем их на наших врагах. Как только мы закончим исследования, я создам такую чуму, какой этот мир еще не видел.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы с коллегами собираем все известные яды и испытываем их на наших врагах. Как только мы закончим исследования, я создам такую чуму, какой этот мир еще не видел.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5100,'Невероятно. Твои снадобья не хуже моих. Я больше не могу учить тебя, а вот орк Рогвар из Каменора, думаю, будет рад такому ученику. Ищи его на Болоте Печали.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Невероятно. Твои снадобья не хуже моих. Я больше не могу учить тебя, а вот орк Рогвар из Каменора, думаю, будет рад такому ученику. Ищи его на Болоте Печали.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5102,'У тебя пока не хватает навыков, чтобы заниматься со мной. Пойди поговори с доктором Мартином Фелбеном, вон там, или поднимись по скату на юго-восток к доктору Маршу. Они – Отрекшиеся, которые могут научить тебя тому, что тебе нужно.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','У тебя пока не хватает навыков, чтобы заниматься со мной. Пойди поговори с доктором Мартином Фелбеном, вон там, или поднимись по скату на юго-восток к доктору Маршу. Они – Отрекшиеся, которые могут научить тебя тому, что тебе нужно.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5104,'Когда-то я приветствовала темноту, ибо она была сестрой ночи. Теперь же темно всегда, даже днем, и леса взывают о помощи. Если мы не предпримем что-либо в скором времени, эта растущая тьма покроет весь мир.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Когда-то я приветствовала темноту, ибо она была сестрой ночи. Теперь же темно всегда, даже днем, и леса взывают о помощи. Если мы не предпримем что-либо в скором времени, эта растущая тьма покроет весь мир.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5105,'Ты $gпришел:пришла; ко мне учиться составлению зелий? Ну-ну. А ты $gуверен, что заслужил:уверена, что заслужила; такую честь? Иди – и не возвращайся, пока не наберешься опыта!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты $gпришел:пришла; ко мне учиться составлению зелий? Ну-ну. А ты $gуверен, что заслужил:уверена, что заслужила; такую честь? Иди – и не возвращайся, пока не наберешься опыта!',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5106,'У тебя действительно есть способности и желание учиться. Но прежде чем начать обучение, мне хотелось бы испытать тебя.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','У тебя действительно есть способности и желание учиться. Но прежде чем начать обучение, мне хотелось бы испытать тебя.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5108,'Меня позвал сюда сам Вождь Тралл. Я повиновался с радостью. Лучше места, чем Каменор, и не придумаешь. На здешнем перегное растут любые травы, какие только могут понадобиться.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Меня позвал сюда сам Вождь Тралл. Я повиновался с радостью. Лучше места, чем Каменор, и не придумаешь. На здешнем перегное растут любые травы, какие только могут понадобиться.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5110,'Хммм, хорошо, я вижу, ты кое-что знаешь о том, как составлять зелья. Но $gдостоин:достойна; ли ты стать $gмоим учеником:моей ученицей; – пока неизвестно. У меня есть для тебя работа. Произведи на меня впечатление.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Хммм, хорошо, я вижу, ты кое-что знаешь о том, как составлять зелья. Но $gдостоин:достойна; ли ты стать $gмоим учеником:моей ученицей; – пока неизвестно. У меня есть для тебя работа. Произведи на меня впечатление.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5111,'Да как ты смеешь просить меня об уроках, ничтожество? Буду я тебе тут лекции о сребролисте читать! Вон отсюда! И скажи спасибо, что я не вышиб тебе мозги!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да как ты смеешь просить меня об уроках, ничтожество? Буду я тебе тут лекции о сребролисте читать! Вон отсюда! И скажи спасибо, что я не вышиб тебе мозги!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5112,'Всего лишь небольшая поправка здесь… вот так!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Всего лишь небольшая поправка здесь… вот так!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5113,'Я б за тебя взялся, но тут нужен кто-то... как бишь это?.. Помозговитей! Ступай в Стальгорн и найди там Трикси Быстросмен. Скажешь, что ты от Бронка.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я б за тебя взялся, но тут нужен кто-то... как бишь это?.. Помозговитей! Ступай в Стальгорн и найди там Трикси Быстросмен. Скажешь, что ты от Бронка.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5114,'О, так вы хотите стать инженером? Клянусь Мурадином, вы пришли по адресу!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','О, так вы хотите стать инженером? Клянусь Мурадином, вы пришли по адресу!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5115,'Где мой ткач? Вроде был где-то здесь…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Где мой ткач? Вроде был где-то здесь…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5116,'Твои познания намного превосходят мои. Чтобы учиться дальше, ты $gдолжен:должна; обратиться к моей подруге Трикси Быстросмен, гному из Стальгорна.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Твои познания намного превосходят мои. Чтобы учиться дальше, ты $gдолжен:должна; обратиться к моей подруге Трикси Быстросмен, гному из Стальгорна.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5117,'Я с удовольствием помогу тебе! Сейчас захвачу своего ткача – и начнем...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я с удовольствием помогу тебе! Сейчас захвачу своего ткача – и начнем...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5118,'Я слышала, скоро с конвейера сойдет новая "Цыпа-6000". Как же я волнуюсь!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я слышала, скоро с конвейера сойдет новая "Цыпа-6000". Как же я волнуюсь!',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5119,'Ну... как ни печально это признавать, но дальше тебе придется учиться у моей сестры. Она меня превосходит – пока что. Ищи ее возле болида.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ну... как ни печально это признавать, но дальше тебе придется учиться у моей сестры. Она меня превосходит – пока что. Ищи ее возле болида.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5120,'Я с радостью буду учить тебя! Пусть моя сестра убедится, что не она одна что-то понимает в инженерном деле...') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я с радостью буду учить тебя! Пусть моя сестра убедится, что не она одна что-то понимает в инженерном деле...',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5121,'Приветик! Меня зовет Дженна! А тебя?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Приветик! Меня зовет Дженна! А тебя?',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5122,'Эге, да вам еще учиться и учиться! Я бы показала вам, как чего делать, да только я сама еще учусь... Вы лучше поговорите с Трикси Быстросмен в Стальгорне, она вам много чего порасскажет!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Эге, да вам еще учиться и учиться! Я бы показала вам, как чего делать, да только я сама еще учусь... Вы лучше поговорите с Трикси Быстросмен в Стальгорне, она вам много чего порасскажет!',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5123,'Хочешь учиться? У меня? Невероятно! Что может быть лучше, чем собирать снаряды и взрывные устройства – только делиться этим знанием с кем-нибудь еще! Начнем же!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Хочешь учиться? У меня? Невероятно! Что может быть лучше, чем собирать снаряды и взрывные устройства – только делиться этим знанием с кем-нибудь еще! Начнем же!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5124,'Отличный день для взрывов!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Отличный день для взрывов!',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5125,'Тебе теперь надо учить то, о чем я и понятия не имею! Обратись к Лилиаму Шпинделю, он здесь, возле входа.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Тебе теперь надо учить то, о чем я и понятия не имею! Обратись к Лилиаму Шпинделю, он здесь, возле входа.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5126,'Такая работа не для слабонервных! Мой дядя, например, руку потерял! Бедный старичок Пенек... Так что если это вам еще интересно, то я могу научить вас кое-чему.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Такая работа не для слабонервных! Мой дядя, например, руку потерял! Бедный старичок Пенек... Так что если это вам еще интересно, то я могу научить вас кое-чему.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5127,'Что? Ты что-то хочешь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что? Ты что-то хочешь?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5128,'Я не могу тебе помочь! Тебе нужен кто-то более опытный. Так... Ты у нас из Альянса, значит, тебе лучше пойти в Штормград к Лилиаму Шпинделю.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я не могу тебе помочь! Тебе нужен кто-то более опытный. Так... Ты у нас из Альянса, значит, тебе лучше пойти в Штормград к Лилиаму Шпинделю.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5129,'Да, я покажу тебе пару вещей. Посмотрим, как ты справишься – может быть, ты даже удивишь меня!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да, я покажу тебе пару вещей. Посмотрим, как ты справишься – может быть, ты даже удивишь меня!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5131,'Боюсь, теперь ты для меня слишком $gхорош:хороша;! Тебе надо встретиться с Ноггом из Оргриммара.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Боюсь, теперь ты для меня слишком $gхорош:хороша;! Тебе надо встретиться с Ноггом из Оргриммара.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5133,'Я люблю строить всякие штуковины. А еще больше люблю их взрывать!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я люблю строить всякие штуковины. А еще больше люблю их взрывать!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5134,'Знаете, у кого вам надо поучиться? У Ногга! Его можно найти в Оргриммаре.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Знаете, у кого вам надо поучиться? У Ногга! Его можно найти в Оргриммаре.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5135,'Да, я кое-что знаю. Хочешь покажу?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да, я кое-что знаю. Хочешь покажу?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5137,'Знаешь, кто по-настоящему умный? Ногг! Даже умнее, чем я. Поди скажи Ноггу, что тебя прислал Тунд! Ты найдешь его у пульта управления, вон там.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Знаешь, кто по-настоящему умный? Ногг! Даже умнее, чем я. Поди скажи Ноггу, что тебя прислал Тунд! Ты найдешь его у пульта управления, вон там.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5138,'Думаешь, ты достаточно $gумен:умна;? Думаешь, ты справишься? Ну, давай попробуем!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Думаешь, ты достаточно $gумен:умна;? Думаешь, ты справишься? Ну, давай попробуем!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5140,'Теперь ты $gготов:готова; к новым свершениям! Поговори с Франклином Ллойдом, что справа от меня. Отныне он станет направлять тебя.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Теперь ты $gготов:готова; к новым свершениям! Поговори с Франклином Ллойдом, что справа от меня. Отныне он станет направлять тебя.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5141,'Инженерное дело даст тебе знания и умение разобрать противников по винтику! Позволь, я покажу тебе...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Инженерное дело даст тебе знания и умение разобрать противников по винтику! Позволь, я покажу тебе...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5142,'Я всегда рад поговорить с $gнезнакомцем:незнакомкой;! Ну, почти всегда…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я всегда рад поговорить с $gнезнакомцем:незнакомкой;! Ну, почти всегда…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5144,'Я могу показать вам пару фокусов... Но сначала вам придется кое-что сделать для меня.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я могу показать вам пару фокусов... Но сначала вам придется кое-что сделать для меня.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5146,'Поразительно! Ты всегда $gтакой трудолюбивый:такая трудолюбивая;? Ну что, начнем?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Поразительно! Ты всегда $gтакой трудолюбивый:такая трудолюбивая;? Ну что, начнем?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5147,'Посмотрим… 14 плюс 7, два в уме… хм, да?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Посмотрим… 14 плюс 7, два в уме… хм, да?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5151,'Да, ты меня не $gразочаровал:разочаровала;! Теперь, когда все готово, можно и начать обучение!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да, ты меня не $gразочаровал:разочаровала;! Теперь, когда все готово, можно и начать обучение!',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5153,'Скажу по секрету – ты только никому не говори, – даже я не знаю всего на свете! Если хочешь учиться дальше, поговори с владельцем лавки Пружиннером Шумотором.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Скажу по секрету – ты только никому не говори, – даже я не знаю всего на свете! Если хочешь учиться дальше, поговори с владельцем лавки Пружиннером Шумотором.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5154,'Прежде чем я выдам свои секреты, ты $gдолжен:должна; будешь показать себя в деле! Есть для тебя тут одно испытание...') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Прежде чем я выдам свои секреты, ты $gдолжен:должна; будешь показать себя в деле! Есть для тебя тут одно испытание...',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5155,'Почти, но не совсем! Боюсь, сначала тебе придется поговорить с моей сестрицей, Джемой. Когда ты пройдешь с ней основы, приходи ко мне, и я покажу тебе кое-что интересное!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Почти, но не совсем! Боюсь, сначала тебе придется поговорить с моей сестрицей, Джемой. Когда ты пройдешь с ней основы, приходи ко мне, и я покажу тебе кое-что интересное!',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5156,'Неплохо для новичка! Думаю, меня не затруднит показать тебе кое-какие секреты...') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Неплохо для новичка! Думаю, меня не затруднит показать тебе кое-какие секреты...',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5157,'Если бы в сутках была еще пара лишних часов…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если бы в сутках была еще пара лишних часов…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5158,'Вы получили право обучаться у более опытного инструктора. Поговорите с моим другом Роксиком, он вон там.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вы получили право обучаться у более опытного инструктора. Поговорите с моим другом Роксиком, он вон там.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5159,'Каждый день – это испытание, и этот день не исключение. Если ты пройдешь мою проверку, я поделюсь с тобой знаниями...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Каждый день – это испытание, и этот день не исключение. Если ты пройдешь мою проверку, я поделюсь с тобой знаниями...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5160,'Ты не $gзаслужил:заслужила; права учиться у меня. Сначала поговори с Тундом – вон он, на другом краю стола. Возвращайся, когда он скажет, что ты $gготов:готова;!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты не $gзаслужил:заслужила; права учиться у меня. Сначала поговори с Тундом – вон он, на другом краю стола. Возвращайся, когда он скажет, что ты $gготов:готова;!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5161,'Ты $gпрошел:прошла; тест. Отлично! Теперь мы продолжим твое обучение.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты $gпрошел:прошла; тест. Отлично! Теперь мы продолжим твое обучение.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5162,'Мне некогда языком чесать, я профессионал!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мне некогда языком чесать, я профессионал!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5163,'Чему еще я могу тебя научить? Шел бы ты лучше к Роксику в Оргриммар. Давай, проваливай!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Чему еще я могу тебя научить? Шел бы ты лучше к Роксику в Оргриммар. Давай, проваливай!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5164,'Ну что, проверим твои знания? Если выполнишь задание, то я возьмусь тебя учить!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ну что, проверим твои знания? Если выполнишь задание, то я возьмусь тебя учить!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5165,'Мы зря теряем время! Если хочешь учиться, обратись к Грэхему Ван Талену. Он стоит слева от меня.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы зря теряем время! Если хочешь учиться, обратись к Грэхему Ван Талену. Он стоит слева от меня.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5167,'Если мои расчеты верны, колесо скоро уйдет в историю!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если мои расчеты верны, колесо скоро уйдет в историю!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5170,'Да у тебя мозги расплавятся от моих уроков! Возвращайся, когда будешь более $gподготовлен:подготовлена;!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да у тебя мозги расплавятся от моих уроков! Возвращайся, когда будешь более $gподготовлен:подготовлена;!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5171,'Отлично, ты $gпоказал:показала; себя в деле! Пора перейти к следующему этапу...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Отлично, ты $gпоказал:показала; себя в деле! Пора перейти к следующему этапу...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5172,'Иногда я сам себе удивляюсь!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Иногда я сам себе удивляюсь!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5173,'Я не могу учить тому, чего не знаю сам! Если бы тут был кто-нибудь, кто знает больше меня... А ведь есть такой! Отправляйтесь к Жужжеру Скрепокрылу в Прибамбасск!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я не могу учить тому, чего не знаю сам! Если бы тут был кто-нибудь, кто знает больше меня... А ведь есть такой! Отправляйтесь к Жужжеру Скрепокрылу в Прибамбасск!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5175,'Неплохо для новичка, но у меня тебе учиться все-таки рановато. Возвращайся к траншеям!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Неплохо для новичка, но у меня тебе учиться все-таки рановато. Возвращайся к траншеям!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5177,'Я придумал интереснейший проект подземной системы транспортировки нефти… Но все почему-то говорят мне, что дело – труба.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я придумал интереснейший проект подземной системы транспортировки нефти… Но все почему-то говорят мне, что дело – труба.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5179,'Покажите-ка, что у вас есть! Обещаю, вы не пожалеете!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Покажите-ка, что у вас есть! Обещаю, вы не пожалеете!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5180,'Я никогда не отказываю тем, кто готов учиться у меня. К сожалению, ты не $gготов:готова;! Тебе еще расти и расти!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я никогда не отказываю тем, кто готов учиться у меня. К сожалению, ты не $gготов:готова;! Тебе еще расти и расти!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5181,'Привет тебе, $gпутешественник:путешественница;! Что привело тебя ко мне?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Привет тебе, $gпутешественник:путешественница;! Что привело тебя ко мне?',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5182,'Боюсь, мне уже нечему тебя учить. Но ты еще не $gдостиг:достигла; совершенства. Поговори с Луканом Корделлом – он тут рядом, за углом. Он преподаст тебе дальнейшие уроки.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Боюсь, мне уже нечему тебя учить. Но ты еще не $gдостиг:достигла; совершенства. Поговори с Луканом Корделлом – он тут рядом, за углом. Он преподаст тебе дальнейшие уроки.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5183,'Хм... Похоже, способности у тебя есть. Если ты и вправду хочешь учиться, тебя ничто не удержит! Я помогу тебе сделать первые шаги на твоем, как я надеюсь, долгом и насыщенном пути.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Хм... Похоже, способности у тебя есть. Если ты и вправду хочешь учиться, тебя ничто не удержит! Я помогу тебе сделать первые шаги на твоем, как я надеюсь, долгом и насыщенном пути.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5185,'Ну и ну, ты в самом деле превосходный зачаровыватель! Теперь самое время двигаться вперед. Я хочу, чтобы ты $gпоговорил:поговорила; с Гимблом Чертополушем, там, наверху. Он немного странноват, но теперь именно он будет тебя подскажет, куда двигаться дальше!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ну и ну, ты в самом деле превосходный зачаровыватель! Теперь самое время двигаться вперед. Я хочу, чтобы ты $gпоговорил:поговорила; с Гимблом Чертополушем, там, наверху. Он немного странноват, но теперь именно он будет тебя подскажет, куда двигаться дальше!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5186,'А, да ты, видать, $gлюбопытный:любопытная;? Отлично! Смотри внимательно, это может когда-нибудь спасти твою шкуру!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','А, да ты, видать, $gлюбопытный:любопытная;? Отлично! Смотри внимательно, это может когда-нибудь спасти твою шкуру!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5187,'Богиня даровала мне мудрость, $gстранник:странница;. Если на то будет ее воля, я передам эту мудрость тебе.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Богиня даровала мне мудрость, $gстранник:странница;. Если на то будет ее воля, я передам эту мудрость тебе.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5188,'Ты куда искуснее меня. Пора тебе отправиться навстречу новым испытаниям. Таладан поможет тебе подготовиться. Он стоит прямо здесь, у стола.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты куда искуснее меня. Пора тебе отправиться навстречу новым испытаниям. Таладан поможет тебе подготовиться. Он стоит прямо здесь, у стола.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5189,'Я научу тебя всему, что умею. Каждый урок – дар самой Богини. Пользуйся ее дарами с умом, и не собьешься с пути.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я научу тебя всему, что умею. Каждый урок – дар самой Богини. Пользуйся ее дарами с умом, и не собьешься с пути.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5190,'Последователи Элуны хранят множество тайн, но делятся ими лишь с избранными.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Последователи Элуны хранят множество тайн, но делятся ими лишь с избранными.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5192,'Открой свой разум, $gстранник:странница;, и мы начнем.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Открой свой разум, $gстранник:странница;, и мы начнем.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5193,'У меня не так много времени, чтобы тратить его на всяких чужаков. Излагай свое дело или убирайся!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','У меня не так много времени, чтобы тратить его на всяких чужаков. Излагай свое дело или убирайся!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5194,'Ну да, ты $gсумел:сумела; дойти досюда... иди встреться с Лавинией Кроу у другого стеллажа, вон там. Если не напортачишь с ней, может быть, сможешь еще чему-нибудь научиться.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ну да, ты $gсумел:сумела; дойти досюда... иди встреться с Лавинией Кроу у другого стеллажа, вон там. Если не напортачишь с ней, может быть, сможешь еще чему-нибудь научиться.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5195,'С виду ты не $gопасен:опасна;, но кто знает – вдруг поблизости прячется какой-нибудь колдун!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','С виду ты не $gопасен:опасна;, но кто знает – вдруг поблизости прячется какой-нибудь колдун!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5196,'Я бы все отдал, чтобы не торчать на этих равнинах в такой день… но что поделаешь, служба.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я бы все отдал, чтобы не торчать на этих равнинах в такой день… но что поделаешь, служба.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5197,'Я не могу научить тебя ничему, чего бы ты уже не $gзнал:знала;. Однако знания моего отца намного превосходят мои. Заходи и поговори с ним. Удачи!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я не могу научить тебя ничему, чего бы ты уже не $gзнал:знала;. Однако знания моего отца намного превосходят мои. Заходи и поговори с ним. Удачи!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5198,'Есть много тайн, открыть которые помогут терпение и упорство. Приступим же.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Есть много тайн, открыть которые помогут терпение и упорство. Приступим же.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5199,'Тром-ка! Что ты ищешь, $gнезнакомец:незнакомка;?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тром-ка! Что ты ищешь, $gнезнакомец:незнакомка;?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5200,'Ты $gпришел:пришла; не по адресу. Поговори с экспертом Годаном. У него ты узнаешь больше.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты $gпришел:пришла; не по адресу. Поговори с экспертом Годаном. У него ты узнаешь больше.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5201,'Смерть в бою всегда почетна! Но, надеюсь, ты не умрешь слишком быстро. Все-таки чему-то я тебя научил.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Смерть в бою всегда почетна! Но, надеюсь, ты не умрешь слишком быстро. Все-таки чему-то я тебя научил.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5202,'Кто ты? Что ты от меня хочешь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Кто ты? Что ты от меня хочешь?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5203,'Я что, похож на величайшего зачаровывателя всех времен и народов? Обучением таких, как ты, должен заниматься профессионал! Разыщи Китту Огневетер в башне Азоры.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я что, похож на величайшего зачаровывателя всех времен и народов? Обучением таких, как ты, должен заниматься профессионал! Разыщи Китту Огневетер в башне Азоры.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5204,'Ну что ж, начнем... Ха! Обманул! Неужто ты думаешь, что все будет так просто? Нет, ты сначала докажи, что не лыком $gшит:шита;!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ну что ж, начнем... Ха! Обманул! Неужто ты думаешь, что все будет так просто? Нет, ты сначала докажи, что не лыком $gшит:шита;!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5205,'Ты шутишь, не так ли? Полагаю, тебе нужен ДРУГОЙ коротышка, Тонис Пилон. Он внизу. А теперь дуй отсюда!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты шутишь, не так ли? Полагаю, тебе нужен ДРУГОЙ коротышка, Тонис Пилон. Он внизу. А теперь дуй отсюда!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5207,'Если ты достаточно $gопытен:опытна;, я с радостью поделюсь с тобой своими знаниями.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если ты достаточно $gопытен:опытна;, я с радостью поделюсь с тобой своими знаниями.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5208,'Настоящий профессионал знает, что он может, а что нет, и я не стыжусь признавать, что твое умение превосходит мое. Я бы хотел, чтобы ты $gнанес:нанесла; визит Китте Огневетер в Башню Азоры. Ее имя хорошо известно, и не случайно.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Настоящий профессионал знает, что он может, а что нет, и я не стыжусь признавать, что твое умение превосходит мое. Я бы хотел, чтобы ты $gнанес:нанесла; визит Китте Огневетер в Башню Азоры. Ее имя хорошо известно, и не случайно.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5209,'Ты выглядишь уверенно. Я думаю, ты не будешь возражать против небольшой проверки твоего мастерства?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты выглядишь уверенно. Я думаю, ты не будешь возражать против небольшой проверки твоего мастерства?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5210,'Ты еще не $Gготов:готова;. Поговори с Бетти Куин – вон она, на лестнице стоит. Возвращайся, когда выучишься у нее.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты еще не $Gготов:готова;. Поговори с Бетти Куин – вон она, на лестнице стоит. Возвращайся, когда выучишься у нее.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5211,'Твоя уверенность в себе обоснованна, $gпутник:путница;. Теперь начнется твое настоящее обучение!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Твоя уверенность в себе обоснованна, $gпутник:путница;. Теперь начнется твое настоящее обучение!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5212,'Если ты хочешь охотиться за нагами, тебе пригодится любая помощь. На глубине есть расщелины, из которых поднимаются пузырьки воздуха. Чтобы вдохнуть, подплыви ближе к расщелине.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если ты хочешь охотиться за нагами, тебе пригодится любая помощь. На глубине есть расщелины, из которых поднимаются пузырьки воздуха. Чтобы вдохнуть, подплыви ближе к расщелине.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5213,'Это правда, у меня достаточно мастерства, чтобы обучать достойных. Ты входишь в их число?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Это правда, у меня достаточно мастерства, чтобы обучать достойных. Ты входишь в их число?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5214,'Ты – великолепный зачаровыватель. Боюсь, это тот случай, когда ученик превзошел учителя. Тебе нужна Китта Огневетер из башни Азоры. Только она сможет учить тебя дальше.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты – великолепный зачаровыватель. Боюсь, это тот случай, когда ученик превзошел учителя. Тебе нужна Китта Огневетер из башни Азоры. Только она сможет учить тебя дальше.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5216,'Ты еще не $gосвоил:освоила; азов, $gскиталец:скиталица;. Ты уже $gговорил:говорила; с моей помощницей, Лалиной Летней Луной? Может быть, стоило бы.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты еще не $gосвоил:освоила; азов, $gскиталец:скиталица;. Ты уже $gговорил:говорила; с моей помощницей, Лалиной Летней Луной? Может быть, стоило бы.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5217,'Превосходно! Воистину, ты $gдостоин:достойна; знаний, которые я передам тебе!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Превосходно! Воистину, ты $gдостоин:достойна; знаний, которые я передам тебе!',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5219,'Мне ведомо многое, $gнезнакомец:незнакомка;, но твои познания превышают мои собственные. Каждый, кто желает постичь вершины искусства наложения чар, рано или поздно отправляется в башню Азоры, к легендарной Китте Огневетер.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мне ведомо многое, $gнезнакомец:незнакомка;, но твои познания превышают мои собственные. Каждый, кто желает постичь вершины искусства наложения чар, рано или поздно отправляется в башню Азоры, к легендарной Китте Огневетер.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5220,'Почему бы нам не проверить ваши способности в деле? Выполните задание, и я с радостью продолжу ваше обучение.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Почему бы нам не проверить ваши способности в деле? Выполните задание, и я с радостью продолжу ваше обучение.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5223,'Колдовство в нашей крови уже много поколений. Я научился ему рано; сейчас этому обучается мой сын.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Колдовство в нашей крови уже много поколений. Я научился ему рано; сейчас этому обучается мой сын.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5224,'Есть наставник, чья премудрость выше моей. Теперь ты можешь его отыскать. Отправляйся в Когтистые горы, в Приют у Солнечного Камня. Разыщи там Хгарта и продолжай обучение.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Есть наставник, чья премудрость выше моей. Теперь ты можешь его отыскать. Отправляйся в Когтистые горы, в Приют у Солнечного Камня. Разыщи там Хгарта и продолжай обучение.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5226,'$GУверен:Уверена;, что Мот не посылал тебя ко мне? Ну, ему лучше знать. Ты пока еще не $gготов:готова; понять мои уроки. Поговори лучше с моим сыном Мотом, стоящим снаружи, и заверши обучение у него.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','$GУверен:Уверена;, что Мот не посылал тебя ко мне? Ну, ему лучше знать. Ты пока еще не $gготов:готова; понять мои уроки. Поговори лучше с моим сыном Мотом, стоящим снаружи, и заверши обучение у него.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5228,'У меня нечасто бывают посетители. Ты, никак, ищешь что-то особенное?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','У меня нечасто бывают посетители. Ты, никак, ищешь что-то особенное?',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5229,'Если бы я не проводила здесь дни и ночи напролет, то никогда бы не достигла таких вершин мастерства! Но твой час еще не настал. Иди и поговори с Хгартом в Приюте у Солнечного Камня, что в Когтистых горах.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Если бы я не проводила здесь дни и ночи напролет, то никогда бы не достигла таких вершин мастерства! Но твой час еще не настал. Иди и поговори с Хгартом в Приюте у Солнечного Камня, что в Когтистых горах.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5230,'Хм, услугу за услугу. Выполни мое задание как следует, и тогда я подумаю об уроках.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Хм, услугу за услугу. Выполни мое задание как следует, и тогда я подумаю об уроках.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5231,'Нет-нет, тебе еще учиться и учиться, прежде чем ты сможешь понять мои уроки! Сходи лучше поговори с этим надутым дилетантом Малькомбом Уинном. Он постоянно сидит, уткнувшись носом в свои книги.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Нет-нет, тебе еще учиться и учиться, прежде чем ты сможешь понять мои уроки! Сходи лучше поговори с этим надутым дилетантом Малькомбом Уинном. Он постоянно сидит, уткнувшись носом в свои книги.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5232,'Видала я и получше... Но у вас определенно есть способности. Будьте внимательнее, и из вас еще может выйти толк!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Видала я и получше... Но у вас определенно есть способности. Будьте внимательнее, и из вас еще может выйти толк!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5233,'Приветствую тебя, $Gпутник:путешественница;! Желаешь постичь тайную магию?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приветствую тебя, $Gпутник:путешественница;! Желаешь постичь тайную магию?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5239,'Твои навыки вне моей компетенции, $gнезнакомец:незнакомка;. Обратись к Хгарту в Приюте у Солнечного Камня в Когтистых горах. Его знания превосходят мои.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Твои навыки вне моей компетенции, $gнезнакомец:незнакомка;. Обратись к Хгарту в Приюте у Солнечного Камня в Когтистых горах. Его знания превосходят мои.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5240,'Может, у вас и получится. Сейчас узнаем!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Может, у вас и получится. Сейчас узнаем!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5241,'$n, вы еще недостаточно опытны, чтобы учиться у меня. Позанимайтесь сначала с моим помощником Джагом, вон он.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','$n, вы еще недостаточно опытны, чтобы учиться у меня. Позанимайтесь сначала с моим помощником Джагом, вон он.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5243,'Что привело тебя в Башню?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Что привело тебя в Башню?',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5246,'Ты хочешь учиться – и это хорошо. Но к таким мастерам, как я, тебе обращаться рановато.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты хочешь учиться – и это хорошо. Но к таким мастерам, как я, тебе обращаться рановато.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5247,'Ты $gдостиг:достигла; значительных успехов. Продолжим обучение!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты $gдостиг:достигла; значительных успехов. Продолжим обучение!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5248,'Ты $gпришел:пришла; учиться мудрости Хгарта?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты $gпришел:пришла; учиться мудрости Хгарта?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5251,'Учитесь, учитесь каждый день. А когда выучитесь, приходите ко мне.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Учитесь, учитесь каждый день. А когда выучитесь, приходите ко мне.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5252,'Ты $gдостиг:достигла; новых высот на пути к мастерству. Посмотрим, можешь ли ты пойти дальше...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты $gдостиг:достигла; новых высот на пути к мастерству. Посмотрим, можешь ли ты пойти дальше...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5253,'Здравствуй, $gстранник:странница;, и прими мою благодарность за то, что $gрасправился:расправилась; с этими жуткими тварями! Я уж начала думать, что прятаться мне придется вечно!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Здравствуй, $gстранник:странница;, и прими мою благодарность за то, что $gрасправился:расправилась; с этими жуткими тварями! Я уж начала думать, что прятаться мне придется вечно!',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5256,'Прежде чем я смогу тебя учить, ты $gдолжен:должна; набраться знаний у других мастеров. Не оставляй надежду и учись прилежно.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Прежде чем я смогу тебя учить, ты $gдолжен:должна; набраться знаний у других мастеров. Не оставляй надежду и учись прилежно.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5257,'С тех пор как мой муж ушел на фронт, меня защищает Хелена. Ее доброе сердце и острый меч не раз помогали мне в лихие времена. Не знаю, что бы я без нее делала.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','С тех пор как мой муж ушел на фронт, меня защищает Хелена. Ее доброе сердце и острый меч не раз помогали мне в лихие времена. Не знаю, что бы я без нее делала.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5258,'Ой, прости. Мне нечему тебя учить. Может, поговоришь с Саймоном Дубильщиком в Старом городе Штормграда? Ищи мужчину с крепкими мускулами и дивной рыжей шевелюрой.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ой, прости. Мне нечему тебя учить. Может, поговоришь с Саймоном Дубильщиком в Старом городе Штормграда? Ищи мужчину с крепкими мускулами и дивной рыжей шевелюрой.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5259,'Ну, как дела? Обожаю запах кожи… А ты?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ну, как дела? Обожаю запах кожи… А ты?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5260,'Я уже немало знаю о стиле. Осталось лишь отшлифовать технику работы с кожей. Как хорошо, что этот славный малый Саймон всегда готов помочь мне.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я уже немало знаю о стиле. Осталось лишь отшлифовать технику работы с кожей. Как хорошо, что этот славный малый Саймон всегда готов помочь мне.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5261,'Мне больше нечему тебя учить – разве что некоторым мелким нюансам. Поговори с Саймоном Кожевенником, он знает много сложных приемов работы с кожей.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мне больше нечему тебя учить – разве что некоторым мелким нюансам. Поговори с Саймоном Кожевенником, он знает много сложных приемов работы с кожей.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5262,'Правда, эта одежда мне идет? Да, мастерства мне не занимать, я могу и поделиться секретами профессии. Не перебивай, ладно?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Правда, эта одежда мне идет? Да, мастерства мне не занимать, я могу и поделиться секретами профессии. Не перебивай, ладно?',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5264,'Очень жаль, но я уже научила вас всему, что знаю сама. Теперь вам лучше обратиться к ночному эльфу Фальдрону. Поищите его на Террасе ремесленников в Дарнасе.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Очень жаль, но я уже научила вас всему, что знаю сама. Теперь вам лучше обратиться к ночному эльфу Фальдрону. Поищите его на Террасе ремесленников в Дарнасе.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5274,'Ох, извини, но ты работаешь с кожей лучше, чем я. Поговори с Фальдроном, если хочешь учиться дальше.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ох, извини, но ты работаешь с кожей лучше, чем я. Поговори с Фальдроном, если хочешь учиться дальше.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5276,'Эта шкура еще не готова. Жаль, что выделка кож отнимает столько времени… Должен же быть способ ее ускорить! Ты знаешь, что это еще и для здоровья вредно?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Эта шкура еще не готова. Жаль, что выделка кож отнимает столько времени… Должен же быть способ ее ускорить! Ты знаешь, что это еще и для здоровья вредно?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5277,'Вот невезение! Ты уже знаешь все, что мне известно. Ну ладно. Поговори с Фимблом Остроиглом возле ткацкого станка. Он работает с кожей куда дольше меня.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Вот невезение! Ты уже знаешь все, что мне известно. Ну ладно. Поговори с Фимблом Остроиглом возле ткацкого станка. Он работает с кожей куда дольше меня.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5279,'Нравится коврик? Я лично убила эту тварь и сняла шкуру. Если бы все кентавры так легко шли в руки!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Нравится коврик? Я лично убила эту тварь и сняла шкуру. Если бы все кентавры так легко шли в руки!',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5280,'Мне больше нечему тебя учить. Поговори с Каролеком, если хочешь узнать больше о кожевничестве.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мне больше нечему тебя учить. Поговори с Каролеком, если хочешь узнать больше о кожевничестве.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5281,'Жаль, что мы не можем сдирать кожу с людей и их союзников. Их шкура просто пропадает даром. Впрочем, она слишком тонкая, чтобы на что-то сгодиться.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Жаль, что мы не можем сдирать кожу с людей и их союзников. Их шкура просто пропадает даром. Впрочем, она слишком тонкая, чтобы на что-то сгодиться.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5282,'Кожа, чудесная кожа! Она удерживает ваши внутренности… внутри. Возможно, вы заметили, что моя кожа не так уж хороша. Подумать только, а когда-то я так переживала из-за пор и угрей! А теперь и переживать-то не из-за чего.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Кожа, чудесная кожа! Она удерживает ваши внутренности… внутри. Возможно, вы заметили, что моя кожа не так уж хороша. Подумать только, а когда-то я так переживала из-за пор и угрей! А теперь и переживать-то не из-за чего.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5283,'У тебя все отлично получается. Мне больше нечему тебя учить, а вот Артур Мур из Квартала Разбойников Подгорода мог бы тебе помочь. Только учти: он из нежити. Передай ему, что ты от меня.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','У тебя все отлично получается. Мне больше нечему тебя учить, а вот Артур Мур из Квартала Разбойников Подгорода мог бы тебе помочь. Только учти: он из нежити. Передай ему, что ты от меня.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5284,'Пока не пришла чума, я кожей вообще не интересовалась. А теперь вот знаю о ней столько, что и других могу учить. Смерть подарила мне уйму времени.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Пока не пришла чума, я кожей вообще не интересовалась. А теперь вот знаю о ней столько, что и других могу учить. Смерть подарила мне уйму времени.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5285,'Мясо, шкура, кости… У хорошего охотника ничего не пропадает. Даже мельчайший клочок кожи может пригодиться. Сотня таких клочков – вот и готовы доспехи другу. Порознь мы сильны, а вместе – непобедимы!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мясо, шкура, кости… У хорошего охотника ничего не пропадает. Даже мельчайший клочок кожи может пригодиться. Сотня таких клочков – вот и готовы доспехи другу. Порознь мы сильны, а вместе – непобедимы!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5286,'Ты $gпревзошел:превзошла; все мои наставления. Иди, и да благословит тебя Мать-Земля. Отыщи в магазинах на северо-западе центрального плато Громового Утеса таурена по имени Тарн. Внемли его мудрости.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты $gпревзошел:превзошла; все мои наставления. Иди, и да благословит тебя Мать-Земля. Отыщи в магазинах на северо-западе центрального плато Громового Утеса таурена по имени Тарн. Внемли его мудрости.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5289,'Вы научились работать с кожей лучше меня. Возможно, вам стоит отправиться в Степи и познакомиться с тауреном Крульмоо Полная Луна из Лагеря Таурахо. Он много чему сможет вас научить.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вы научились работать с кожей лучше меня. Возможно, вам стоит отправиться в Степи и познакомиться с тауреном Крульмоо Полная Луна из Лагеря Таурахо. Он много чему сможет вас научить.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5291,'Говорят, здесь живет сам Кэрн. Вот смастерю достойный подарок – и нанесу ему визит. Может быть, он поделится со мной своей мудростью.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Говорят, здесь живет сам Кэрн. Вот смастерю достойный подарок – и нанесу ему визит. Может быть, он поделится со мной своей мудростью.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5292,'Ты талантливей меня, $gдружище:подруга;. Поговори-ка с Тарном. Он разбирается в коже лучше меня и всегда рад новым ученикам.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты талантливей меня, $gдружище:подруга;. Поговори-ка с Тарном. Он разбирается в коже лучше меня и всегда рад новым ученикам.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5293,'Мой руки, перед тем как начинать любую работу. Запятнанная кровью или грязью кожа теряет свою природную красоту.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мой руки, перед тем как начинать любую работу. Запятнанная кровью или грязью кожа теряет свою природную красоту.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5294,'Когда я выбрался из могилы, то думал, что родственники встретят меня с радостью. Но они с криками выгнали меня из деревни, и я больше не понимал их языка.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Когда я выбрался из могилы, то думал, что родственники встретят меня с радостью. Но они с криками выгнали меня из деревни, и я больше не понимал их языка.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5295,'Я тебе ничем не помогу – ты и так меня превосходишь. Поговори с Артуром Муром, вон за теми гробами. У него ты можешь поучиться.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я тебе ничем не помогу – ты и так меня превосходишь. Поговори с Артуром Муром, вон за теми гробами. У него ты можешь поучиться.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5296,'Слушай, что я тебе скажу, и запоминай хорошенько. Пока враг жив, мы не должны упускать ни единой возможности отшлифовать наши навыки. Укрепи доспехи и всегда будь бдителен на посту.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Слушай, что я тебе скажу, и запоминай хорошенько. Пока враг жив, мы не должны упускать ни единой возможности отшлифовать наши навыки. Укрепи доспехи и всегда будь бдителен на посту.',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5314,'Моих скромных способностей для тебя мало. Найди ночную эльфийку Айнетиль на Террасе ремесленников в Дарнасе. Она научит тебя большему. Хотела бы я отправиться туда вместе с тобой...') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Моих скромных способностей для тебя мало. Найди ночную эльфийку Айнетиль на Террасе ремесленников в Дарнасе. Она научит тебя большему. Хотела бы я отправиться туда вместе с тобой...',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5316,'На данном этапе мои уроки будут для тебя слишком сложными. Если хочешь узнать о зельях больше, поговори с Тель\'Атиром.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','На данном этапе мои уроки будут для тебя слишком сложными. Если хочешь узнать о зельях больше, поговори с Тель\'Атиром.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5318,'Даже у меня есть свои пределы! Если хочешь учиться дальше – пойди поговори с Лавинией Кроу в Подгороде!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Даже у меня есть свои пределы! Если хочешь учиться дальше – пойди поговори с Лавинией Кроу в Подгороде!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5319,'Неплохо... Пожалуй, из тебя может выйти толк. Ну что ж, начнем!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Неплохо... Пожалуй, из тебя может выйти толк. Ну что ж, начнем!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5320,'Рэндал любит щегольнуть, но он – человек надежный, а это можно сказать мало о ком из моих учеников. Зато все остальные – заядлые авантюристы.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Рэндал любит щегольнуть, но он – человек надежный, а это можно сказать мало о ком из моих учеников. Зато все остальные – заядлые авантюристы.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5321,'Это все, чему я могу тебя научить. Если хочешь большего, наведайся к Телонису в Дарнас. Он там живет на Террасе ремесленников и, говорят, весьма преуспевает в своем деле.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Это все, чему я могу тебя научить. Если хочешь большего, наведайся к Телонису в Дарнас. Он там живет на Террасе ремесленников и, говорят, весьма преуспевает в своем деле.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5323,'Приходи, когда выучишь основы. Рэндал Ценни поможет тебе в этом.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приходи, когда выучишь основы. Рэндал Ценни поможет тебе в этом.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5324,'Хмм, наверно, еще одного ученика я потяну… Ну что ж, не стойте просто так. Говорите, чему вы хотите научиться?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Хмм, наверно, еще одного ученика я потяну… Ну что ж, не стойте просто так. Говорите, чему вы хотите научиться?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5326,'Если ты хочешь учиться у меня дальше, то ты переоцениваешь мои способности. Поговори лучше с Телонисом.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если ты хочешь учиться у меня дальше, то ты переоцениваешь мои способности. Поговори лучше с Телонисом.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5331,'Нет, боюсь, я не могу вам помочь. Вы и так знаете больше меня! Если хотите учиться дальше, разыщите ночного эльфа Телониса на Террасе ремесленников в Дарнасе. Он очень много знает!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Нет, боюсь, я не могу вам помочь. Вы и так знаете больше меня! Если хотите учиться дальше, разыщите ночного эльфа Телониса на Террасе ремесленников в Дарнасе. Он очень много знает!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5333,'Вот это да! $gНовый ученик:Новая ученица;! Я с радостью научу тебя всему, что знаю, как только ты немного наберешься опыта. Сходи-ка поговори с Греттой Остроигл. Она тебя в два счета подтянет до нужного уровня.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вот это да! $gНовый ученик:Новая ученица;! Я с радостью научу тебя всему, что знаю, как только ты немного наберешься опыта. Сходи-ка поговори с Греттой Остроигл. Она тебя в два счета подтянет до нужного уровня.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5335,'Лучшие шкуры получаются из тех кодо, которые прилегли отдохнуть в этой глуши.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Лучшие шкуры получаются из тех кодо, которые прилегли отдохнуть в этой глуши.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5336,'Теперь ты знаешь все, что знаю я. Отправляйся к таурену Уне. Ее можно найти в северо-западных мастерских на центральном плато Громового Утеса. Она продолжит твое обучение.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Теперь ты знаешь все, что знаю я. Отправляйся к таурену Уне. Ее можно найти в северо-западных мастерских на центральном плато Громового Утеса. Она продолжит твое обучение.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5338,'Я не предлагаю обучение новичкам. Ищи таурена Валдора в Пещерах Стенаний, здесь, в Степях. Он поможет тебе со всем чем надо.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я не предлагаю обучение новичкам. Ищи таурена Валдора в Пещерах Стенаний, здесь, в Степях. Он поможет тебе со всем чем надо.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5339,'Ты $Gпришел:пришла; учиться? Стряхни с одежды дорожную пыль – и приступим к работе.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты $Gпришел:пришла; учиться? Стряхни с одежды дорожную пыль – и приступим к работе.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5340,'Моя секира повидала много битв, и я предпочитаю держать ее под рукой. Враги уже несколько раз прорывались к нашей столице, но бояться нечего: мы всякий раз отбрасывали их.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Моя секира повидала много битв, и я предпочитаю держать ее под рукой. Враги уже несколько раз прорывались к нашей столице, но бояться нечего: мы всякий раз отбрасывали их.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5341,'Ты работаешь с кожей не хуже меня самого. Мне нечему тебя учить. Обратись к Уне, которая живет поблизости. Если потребуется, я за тебя поручусь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты работаешь с кожей не хуже меня самого. Мне нечему тебя учить. Обратись к Уне, которая живет поблизости. Если потребуется, я за тебя поручусь.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5343,'Твоих знаний недостаточно, чтобы учиться у меня. Лучше обратись к Маку – он тут, неподалеку. Он преподаст тебе основы.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Твоих знаний недостаточно, чтобы учиться у меня. Лучше обратись к Маку – он тут, неподалеку. Он преподаст тебе основы.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5344,'Пока что я очень доволен вашими успехами. Кажется, будто сама Мать-Земля вдохновляет вас.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Пока что я очень доволен вашими успехами. Кажется, будто сама Мать-Земля вдохновляет вас.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5345,'Пока что на этом континенте у нас есть лишь маленькая крепость, но люди не могут бороться с нами вечно. Когда-нибудь они заплатят за то, что поработили нас. За их предательство мы вырежем их лживые языки.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Пока что на этом континенте у нас есть лишь маленькая крепость, но люди не могут бороться с нами вечно. Когда-нибудь они заплатят за то, что поработили нас. За их предательство мы вырежем их лживые языки.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5346,'Я бы тебя научил, да самому знаний не хватает. Вот что я скажу: иди и поговори с тауреном Уной. Она работает в мастерских на северо-западе центрального плато Громового Утеса. Таланта ей не занимать.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я бы тебя научил, да самому знаний не хватает. Вот что я скажу: иди и поговори с тауреном Уной. Она работает в мастерских на северо-западе центрального плато Громового Утеса. Таланта ей не занимать.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5348,'Храбрости у тебя больше, чем мозгов, раз ты $gпришел:пришла; ко мне без должного обучения. Иди поищи более подходящего учителя – да хоть ту же орка Камари из оргриммарского Волока.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Храбрости у тебя больше, чем мозгов, раз ты $gпришел:пришла; ко мне без должного обучения. Иди поищи более подходящего учителя – да хоть ту же орка Камари из оргриммарского Волока.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5350,'Не занят ли я? Ты это о чем? Думаешь, что я тут целый день кукиши верчу? Хочешь что-нибудь купить – поговори с Хандором.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не занят ли я? Ты это о чем? Думаешь, что я тут целый день кукиши верчу? Хочешь что-нибудь купить – поговори с Хандором.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5351,'Мне нечему тебя учить – ты и так уже знаешь слишком много. Если хочешь продолжить обучение, поговори с тауреном Уной. Ищи ее в мастерских на северо-западе центрального плато Громового Утеса. И передай ей от меня привет, ладно?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мне нечему тебя учить – ты и так уже знаешь слишком много. Если хочешь продолжить обучение, поговори с тауреном Уной. Ищи ее в мастерских на северо-западе центрального плато Громового Утеса. И передай ей от меня привет, ладно?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5353,'Ты не поймешь моих методик, не изучив хотя бы основы. Если ты и вправду хочешь учиться, поговори с Камари.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты не поймешь моих методик, не изучив хотя бы основы. Если ты и вправду хочешь учиться, поговори с Камари.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5354,'Изгибы и повороты Оргриммара рассчитаны на то, чтобы отбить вторжение. Можешь себе представить, как быстро здесь заблудился бы один из этих хлипких гномов? Ха! Если бы ему повезло, я бы его выследил и держал, как домашнее животное.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Изгибы и повороты Оргриммара рассчитаны на то, чтобы отбить вторжение. Можешь себе представить, как быстро здесь заблудился бы один из этих хлипких гномов? Ха! Если бы ему повезло, я бы его выследил и держал, как домашнее животное.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5355,'До моей смерти я был библиотекарем, я не имел ничего общего с войнами и чумой. И никогда не хотел стать этим. С другой стороны, теперь, когда мой разум вновь принадлежит мне, я не сдамся без боя.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','До моей смерти я был библиотекарем, я не имел ничего общего с войнами и чумой. И никогда не хотел стать этим. С другой стороны, теперь, когда мой разум вновь принадлежит мне, я не сдамся без боя.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5356,'Я рад признать, что ты талантливей меня. А теперь иди. И поищи в мастерских на северо-западе центрального плато Громового Утеса таурена по имени Уна. Уверяю тебя, она настоящий мастер своего дела.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я рад признать, что ты талантливей меня. А теперь иди. И поищи в мастерских на северо-западе центрального плато Громового Утеса таурена по имени Уна. Уверяю тебя, она настоящий мастер своего дела.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5358,'Если бы я учил новичков, здесь было бы полно народу, а я терпеть не могу шума. Иди и поговори с Дэном Голтасом. Он резковат, но плохого не желает, и учитель достойный.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если бы я учил новичков, здесь было бы полно народу, а я терпеть не могу шума. Иди и поговори с Дэном Голтасом. Он резковат, но плохого не желает, и учитель достойный.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5359,'Я сначала открыл лавку в Квартале Магов, но там было слишком шумно. Сейчас куда лучше, если не считать нескольких назойливых учеников, которые преследуют меня даже после переезда.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я сначала открыл лавку в Квартале Магов, но там было слишком шумно. Сейчас куда лучше, если не считать нескольких назойливых учеников, которые преследуют меня даже после переезда.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5360,'Элуна наградила ночных эльфов многими дарами. В свою очередь, мы обязаны защищать эти леса от демонической скверны, которую несет в себе Орда.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Элуна наградила ночных эльфов многими дарами. В свою очередь, мы обязаны защищать эти леса от демонической скверны, которую несет в себе Орда.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5361,'Мне больше нечему тебя учить. Ступай в Дарнас и найди там Телониса на Террасе ремесленников. Он любит талантливых учеников.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мне больше нечему тебя учить. Ступай в Дарнас и найди там Телониса на Террасе ремесленников. Он любит талантливых учеников.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5363,'Я учу только тех, кто уже постиг основы. Тебе же лучше отправиться на Террасу ремесленников к ночной эльфийке по имени Дарианна.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я учу только тех, кто уже постиг основы. Тебе же лучше отправиться на Террасу ремесленников к ночной эльфийке по имени Дарианна.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5364,'Работая с кожей, помни правило: "семь раз отмерь, один отрежь". Нельзя допускать, чтобы такой материал пропадал впустую.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Работая с кожей, помни правило: "семь раз отмерь, один отрежь". Нельзя допускать, чтобы такой материал пропадал впустую.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5374,'В Серебряном бору, у Берега Северного прилива, на берегу покоится полуразвалившаяся лодка. К западу от нее лежит то, что ты ищешь; заплыви слишком далеко, и океан сокрушит тебя усталостью. Оно находится на дне океана, в сейфе, ожидая тебя.$B$BТебе будет тяжело пережить нырок на такую глубину без помощи, так что соберись с духом; разлом, из которого струятся пузырьки, дает второе дыхание ныряльщикам, ищущим эту половину подвески. Используй его мудро.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','В Серебряном бору, у Берега Северного прилива, на берегу покоится полуразвалившаяся лодка. К западу от нее лежит то, что ты ищешь; заплыви слишком далеко, и океан сокрушит тебя усталостью. Оно находится на дне океана, в сейфе, ожидая тебя.$B$BТебе будет тяжело пережить нырок на такую глубину без помощи, так что соберись с духом; разлом, из которого струятся пузырьки, дает второе дыхание ныряльщикам, ищущим эту половину подвески. Используй его мудро.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5394,'Твои знания намного превзошли мои. Отправляйся во Внутренние земли к Заоблачному пику и найди там дворфа по имени Дракк Крепкорук. Его работы гораздо лучше моих.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Твои знания намного превзошли мои. Отправляйся во Внутренние земли к Заоблачному пику и найди там дворфа по имени Дракк Крепкорук. Его работы гораздо лучше моих.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5396,'Сожалею, $gблагородный господин:прекрасная госпожа;, но пока вы не научитесь лучше работать с кожей, я не смогу помочь вам. Поговорите лучше с Фальдроном или Дарианной. Они обучат вас необходимым навыкам.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Сожалею, $gблагородный господин:прекрасная госпожа;, но пока вы не научитесь лучше работать с кожей, я не смогу помочь вам. Поговорите лучше с Фальдроном или Дарианной. Они обучат вас необходимым навыкам.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5397,'Не надо навязывать коже свою волю. Придавайте ей форму, исходя из ее природных свойств. Это не война, в которой надо победить. Работайте с кожей, а не против нее.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не надо навязывать коже свою волю. Придавайте ей форму, исходя из ее природных свойств. Это не война, в которой надо победить. Работайте с кожей, а не против нее.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5398,'Игла мала, но нить крепка и стежки ровны. Мы не нарушим договор с Траллом и остальными. Орда не покинет эти земли.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Игла мала, но нить крепка и стежки ровны. Мы не нарушим договор с Траллом и остальными. Орда не покинет эти земли.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5401,'Я давно забыла, чему надо учить новичков, поэтому вряд ли тебе помогу. Попробуй договориться с Тарном или Маком, они тут рядом. Возможно, кто-то из них сумеет тебе помочь.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я давно забыла, чему надо учить новичков, поэтому вряд ли тебе помогу. Попробуй договориться с Тарном или Маком, они тут рядом. Возможно, кто-то из них сумеет тебе помочь.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5405,'Я состязаться люблю, а ты? Да любишь, конечно же. Поэтому сделаешь то, что я скажу.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я состязаться люблю, а ты? Да любишь, конечно же. Поэтому сделаешь то, что я скажу.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5406,'Я здесь не для того, чтобы с младенцами нянчиться. Ты и в подметки не годишься тем, кого я учу. Скажу больше: вид у тебя, $gпарень:девушка;, прямо-таки жалкий. Сделай милость, не отвлекай меня болтовней.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я здесь не для того, чтобы с младенцами нянчиться. Ты и в подметки не годишься тем, кого я учу. Скажу больше: вид у тебя, $gпарень:девушка;, прямо-таки жалкий. Сделай милость, не отвлекай меня болтовней.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5407,'Я принимаю заказы только лично от покупателей. Орвин часто просит меня передумать, но мне так больше нравится. Ко мне ходят за броней лучшие воины!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я принимаю заказы только лично от покупателей. Орвин часто просит меня передумать, но мне так больше нравится. Ко мне ходят за броней лучшие воины!',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5408,'Побольше бы мне таких учеников, как ты... Мало кто отважится зайти так далеко в тыл врага. Восхищаюсь твоей смелостью.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Побольше бы мне таких учеников, как ты... Мало кто отважится зайти так далеко в тыл врага. Восхищаюсь твоей смелостью.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5409,'В этой войне мы не можем себе позволить ни малейшей слабости. Днем и ночью я делаю новые доспехи и латаю старые. На другие занятия у меня просто нет времени. Не поможешь мне с одним делом?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','В этой войне мы не можем себе позволить ни малейшей слабости. Днем и ночью я делаю новые доспехи и латаю старые. На другие занятия у меня просто нет времени. Не поможешь мне с одним делом?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5413,'Могу сказать, что твой гардероб остро нуждается в уходе.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Могу сказать, что твой гардероб остро нуждается в уходе.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5414,'Я всего лишь простой портной – моих знаний для тебя слишком мало. Но я слышал об одном искусном мастере из ночных эльфов, который живет в Квартале магов Штормграда.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я всего лишь простой портной – моих знаний для тебя слишком мало. Но я слышал об одном искусном мастере из ночных эльфов, который живет в Квартале магов Штормграда.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5415,'Так ты хочешь кое-чему научиться? С удовольствием помогу тебе!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Так ты хочешь кое-чему научиться? С удовольствием помогу тебе!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5416,'Жизнь – словно изысканно вытканный гобелен.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Жизнь – словно изысканно вытканный гобелен.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5417,'Хмм... То, что ты хочешь знать, выше моего разумения. Поговори с Селландусом из суконной лавки Ларсона – прямо по дорожке и направо. Это он меня всему научил!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Хмм... То, что ты хочешь знать, выше моего разумения. Поговори с Селландусом из суконной лавки Ларсона – прямо по дорожке и направо. Это он меня всему научил!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5418,'Ну что ж, начнем наше путешествие по миру портняжного дела.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ну что ж, начнем наше путешествие по миру портняжного дела.',`text0_0_loc8`);
