INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5419,'Шитье требует твердой руки. И терпения… главным образом терпения.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Шитье требует твердой руки. И терпения… главным образом терпения.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5420,'Отправляйся в Дарнас и поговори с Ме\'линн. Теперь она будет направлять тебя.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Отправляйся в Дарнас и поговори с Ме\'линн. Теперь она будет направлять тебя.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5421,'Я с радостью возьму тебя под крыло. Начнем же.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я с радостью возьму тебя под крыло. Начнем же.',`text0_0_loc8`);
