INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5422,'Добро пожаловать в мою лавку. Чем могу помочь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать в мою лавку. Чем могу помочь?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5423,'Э-э, я всего лишь помощник. Если вы хотите учиться всяким штукам, поговорите с Каменным Лбом.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Э-э, я всего лишь помощник. Если вы хотите учиться всяким штукам, поговорите с Каменным Лбом.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5424,'Замечательно! Я как раз ждал нового ученика. Ну что же, давайте начнем!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Замечательно! Я как раз ждал нового ученика. Ну что же, давайте начнем!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5425,'При создании изделий мы используем множество шкур и кож животных.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','При создании изделий мы используем множество шкур и кож животных.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5426,'Я кое-что знаю, но экспертом меня назвать нельзя. А вот Магара можно. Он сейчас как раз отдыхает в дальней части лавки. Попробуй договориться с ним о помощи, но учти: характер у него тот еще.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я кое-что знаю, но экспертом меня назвать нельзя. А вот Магара можно. Он сейчас как раз отдыхает в дальней части лавки. Попробуй договориться с ним о помощи, но учти: характер у него тот еще.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5427,'Я научу тебя всему, чему смогу.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я научу тебя всему, чему смогу.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5428,'Ни одна часть убитых нами животных не пропадает даром.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ни одна часть убитых нами животных не пропадает даром.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5429,'Тебе нужен кто-то более сведущий. Например, Тепа. Она как раз должна быть где-то поблизости...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тебе нужен кто-то более сведущий. Например, Тепа. Она как раз должна быть где-то поблизости...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5430,'Начнем, и да благословит нас Мать-Земля.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Начнем, и да благословит нас Мать-Земля.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5431,'Рад нашему знакомству. Могу ли я помочь вам?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Рад нашему знакомству. Могу ли я помочь вам?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5432,'Я многое знаю, но экспертом меня не назовешь. Знаете, с кем вам лучше поговорить? С Рианнон. Она тут недалеко. Поищите ее в Подгороде.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я многое знаю, но экспертом меня не назовешь. Знаете, с кем вам лучше поговорить? С Рианнон. Она тут недалеко. Поищите ее в Подгороде.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5433,'Итак... желаете стать портным? Ну что ж, желание – это хорошо. Посмотрим, как у вас с возможностями.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Итак... желаете стать портным? Ну что ж, желание – это хорошо. Посмотрим, как у вас с возможностями.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5434,'У нас здесь немного посетителей. Я могу заинтересовать тебя чем-нибудь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','У нас здесь немного посетителей. Я могу заинтересовать тебя чем-нибудь?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5435,'Я и сам всего лишь новичок. Вот у Рианнон есть чему поучиться. Она стоит рядом с ящиками.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я и сам всего лишь новичок. Вот у Рианнон есть чему поучиться. Она стоит рядом с ящиками.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5436,'Да, вроде талант у вас есть. Пожалуй, научу вас кое-чему.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да, вроде талант у вас есть. Пожалуй, научу вас кое-чему.',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5438,'Я еще только учусь, а твои познания превосходят мои. Если хочешь узнать больше, обратись к Ме\'линн. Она тебя научит.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я еще только учусь, а твои познания превосходят мои. Если хочешь узнать больше, обратись к Ме\'линн. Она тебя научит.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5439,'Ты не пожалеешь, $gстранник:странница;. Портняжное дело – весьма приятное занятие.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты не пожалеешь, $gстранник:странница;. Портняжное дело – весьма приятное занятие.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5440,'Эй, дружище, помочь чем?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эй, дружище, помочь чем?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5441,'Ты сейчас знаешь, ну, столько же, сколько и я. Может, тебе к Магару пойти, ну, который из Оргриммара? Он не самый веселый портной, конечно, но поможет без вопросов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты сейчас знаешь, ну, столько же, сколько и я. Может, тебе к Магару пойти, ну, который из Оргриммара? Он не самый веселый портной, конечно, но поможет без вопросов.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5442,'Правильный подход! Хватай иголку и нитку и давай работать!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Правильный подход! Хватай иголку и нитку и давай работать!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5443,'Боюсь, меня больше нельзя назвать ни тихим, ни скромным. Долгие годы и бессчетные битвы закалили мою кожу и мой дух. Возможно, именно поэтому Кэрн и отправил меня в Приют у Солнечного Камня… Мягкий ветер и теплое солнце облегчают боль.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Боюсь, меня больше нельзя назвать ни тихим, ни скромным. Долгие годы и бессчетные битвы закалили мою кожу и мой дух. Возможно, именно поэтому Кэрн и отправил меня в Приют у Солнечного Камня… Мягкий ветер и теплое солнце облегчают боль.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5453,'Приветствую. Наши летучие мыши хорошо обучены и сыто накормлены. Мышей быстрее ты не найдешь!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приветствую. Наши летучие мыши хорошо обучены и сыто накормлены. Мышей быстрее ты не найдешь!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5454,'Чем могу быть полезен?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Чем могу быть полезен?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5455,'Приветствую – и добро пожаловать. У меня не очень-то выходит улыбаться, но поверьте, я счастлив вам служить.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приветствую – и добро пожаловать. У меня не очень-то выходит улыбаться, но поверьте, я счастлив вам служить.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5473,'Гиппогрифы – благородные, сильные и быстрые создания. С их помощью можно быстро преодолевать огромные расстояния. Мы гордимся тем, что работаем с ними.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Гиппогрифы – благородные, сильные и быстрые создания. С их помощью можно быстро преодолевать огромные расстояния. Мы гордимся тем, что работаем с ними.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5477,'Снабжать искателей приключений – большая честь, ведь каждый из них – будущий герой!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Снабжать искателей приключений – большая честь, ведь каждый из них – будущий герой!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5481,'На этой-то пристани? Ну, можешь сесть на корабль, который ходит к ночным эльфам. Как оно там зовется? Э-э, Аубердин, вроде. Но я ошибаться могу, я ж грузчик простой.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','На этой-то пристани? Ну, можешь сесть на корабль, который ходит к ночным эльфам. Как оно там зовется? Э-э, Аубердин, вроде. Но я ошибаться могу, я ж грузчик простой.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5494,'Доставка этих бочек к месту раскопок – труд нелегкий, но ведь тамошнему народу позарез нужна взрывчатка.$B$BМы должны делать все возможное, чтобы противостоять Черному Железу!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Доставка этих бочек к месту раскопок – труд нелегкий, но ведь тамошнему народу позарез нужна взрывчатка.$B$BМы должны делать все возможное, чтобы противостоять Черному Железу!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5495,'Мои ветрокрылы привычны к раскаленному небу Степей.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мои ветрокрылы привычны к раскаленному небу Степей.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5496,'Степи с их жарким солнцем и враждебными обитателями – идеальное место для желающих испытать силу своего тела и духа.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Степи с их жарким солнцем и враждебными обитателями – идеальное место для желающих испытать силу своего тела и духа.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5497,'Здравствуй. Если ты ищешь товары из кожи, то у меня найдется все, что тебе нужно.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здравствуй. Если ты ищешь товары из кожи, то у меня найдется все, что тебе нужно.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5498,'Ты поможешь мне с доставкой? Миран уже готов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты поможешь мне с доставкой? Миран уже готов.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5500,'Сидя на спине ветрокрыла, ты в полной мере ощущаешь силу и скорость этого создания.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Сидя на спине ветрокрыла, ты в полной мере ощущаешь силу и скорость этого создания.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5501,'Это опасный бизнес!$B$BМиран только что ушел с заказом. Он вернется через пару минут.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Это опасный бизнес!$B$BМиран только что ушел с заказом. Он вернется через пару минут.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5513,'Вы успели превзойти меня в мастерстве! Теперь вам нужен более опытный учитель. Это доктор Герберт Галси. Он из нежити, работает в Районе Фармацевтов Подгорода.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вы успели превзойти меня в мастерстве! Теперь вам нужен более опытный учитель. Это доктор Герберт Галси. Он из нежити, работает в Районе Фармацевтов Подгорода.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5516,'Считайте, что вы не жили, пока не увидели мир с высоты полета ветрокрыла!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Считайте, что вы не жили, пока не увидели мир с высоты полета ветрокрыла!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5517,'В Терамор можно уехать с этой пристани. Только учти: людям из Альянса небезопасно путешествовать в тех краях. Будь $gосторожен:осторожна;.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','В Терамор можно уехать с этой пристани. Только учти: людям из Альянса небезопасно путешествовать в тех краях. Будь $gосторожен:осторожна;.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5519,'Добрый день.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добрый день.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5520,'Я недостаточно искусен. Возможно, Джорджио Болеро, владелец "Тканей Дункана", сможет научить тебя чему-то новому. Он здесь, за углом.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я недостаточно искусен. Возможно, Джорджио Болеро, владелец "Тканей Дункана", сможет научить тебя чему-то новому. Он здесь, за углом.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5522,'Поговори с Лоуренсом Шнайдером из "Тканей Дункана" – это за угол и налево. Он привык возиться с новичками.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Поговори с Лоуренсом Шнайдером из "Тканей Дункана" – это за угол и налево. Он привык возиться с новичками.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5523,'Прекрасная демонстрация способностей. Мы можем продолжить обучение.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Прекрасная демонстрация способностей. Мы можем продолжить обучение.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5525,'Ну и не умник ли ты? Ты знаешь больше, чем я, это уж точно! Я бы не стал слишком воображать о себе на твоем месте, но если хочешь продолжить обучение, поболтай с Джорджио Болеро в Штормграде. Говорят, он знает свое ремесло!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ну и не умник ли ты? Ты знаешь больше, чем я, это уж точно! Я бы не стал слишком воображать о себе на твоем месте, но если хочешь продолжить обучение, поболтай с Джорджио Болеро в Штормграде. Говорят, он знает свое ремесло!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5527,'Нет у меня времени с детьми возиться! С помощником моим говори, с Утраром!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Нет у меня времени с детьми возиться! С помощником моим говори, с Утраром!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5528,'Хм... ну, что-то в тебе есть, это точно. Ладно, на чем мы остановились?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Хм... ну, что-то в тебе есть, это точно. Ладно, на чем мы остановились?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5530,'Я лично изготовил большинство товаров, которые ты видишь в этом магазине. Что думаешь? От ответа может зависеть твоя жизнь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я лично изготовил большинство товаров, которые ты видишь в этом магазине. Что думаешь? От ответа может зависеть твоя жизнь.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5531,'Тебе нужно учиться у кого-нибудь, кто знает больше, чем я. Пойди поговори с Джозефом Грегорианом в Подгороде. Ну, почему ты еще здесь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тебе нужно учиться у кого-нибудь, кто знает больше, чем я. Пойди поговори с Джозефом Грегорианом в Подгороде. Ну, почему ты еще здесь?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5533,'Что? Ну чего тебе от меня надо? Ты ведь наверняка даже иголку держать толком не умеешь! Пойди поговори со Снангом. И не возвращайся, пока не обучишься как следует!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что? Ну чего тебе от меня надо? Ты ведь наверняка даже иголку держать толком не умеешь! Пойди поговори со Снангом. И не возвращайся, пока не обучишься как следует!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5534,'Наконец-то ты себя $gпоказал:показала;! Теперь и я покажу себя!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Наконец-то ты себя $gпоказал:показала;! Теперь и я покажу себя!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5535,'Не откладывай на завтра то, что можно сделать… ммм, послезавтра? Тьфу ты, забыл!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не откладывай на завтра то, что можно сделать… ммм, послезавтра? Тьфу ты, забыл!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5536,'Неплохо для новичка! Я научил тебя всему, что знаю сам. Если хочешь продолжить обучение, найди Джозефа Грегориана в Подгороде.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Неплохо для новичка! Я научил тебя всему, что знаю сам. Если хочешь продолжить обучение, найди Джозефа Грегориана в Подгороде.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5539,'Ну, не так уж и плохо. Может быть, я смогу тебя чему-то научить.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ну, не так уж и плохо. Может быть, я смогу тебя чему-то научить.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5540,'Какой прекрасный день! Он вдохновляет меня на новые идеи.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Какой прекрасный день! Он вдохновляет меня на новые идеи.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5541,'У тебя есть и талант, и вдохновение! Отправляйся к Джорджио Болеро в Штормград. Он пользуется большим уважением и может продолжить твое обучение.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','У тебя есть и талант, и вдохновение! Отправляйся к Джорджио Болеро в Штормград. Он пользуется большим уважением и может продолжить твое обучение.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5543,'Сначала тебе нужно научиться основам. Здесь недалеко живет Трианна, поговори с ней, а ко мне приходи потом.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Сначала тебе нужно научиться основам. Здесь недалеко живет Трианна, поговори с ней, а ко мне приходи потом.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5544,'Ты отлично $gсправился, странник:справилась, странница;! Я горжусь тем, что стала твоей наставницей!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты отлично $gсправился, странник:справилась, странница;! Я горжусь тем, что стала твоей наставницей!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5545,'Добро пожаловать. Чем могу служить?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Добро пожаловать. Чем могу служить?',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5546,'Твои познания многократно умножились, и мне больше нечему тебя учить. Пора двигаться дальше. Джозеф Грегориан прославился своей мудростью – найди его в Подгороде и попроси об уроках.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Твои познания многократно умножились, и мне больше нечему тебя учить. Пора двигаться дальше. Джозеф Грегориан прославился своей мудростью – найди его в Подгороде и попроси об уроках.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5549,'Превосходно! Продолжим ваше обучение...') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Превосходно! Продолжим ваше обучение...',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5551,'Разве эти выкройки не прекрасны? В каждой из них есть своя красота.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Разве эти выкройки не прекрасны? В каждой из них есть своя красота.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5552,'Увы, мои познания ограничены – я и сама еще учусь. Пора тебе двигаться дальше. Найди в Подгороде Джозефа Грегориана и скажи ему, что ты $gготов:готова;.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Увы, мои познания ограничены – я и сама еще учусь. Пора тебе двигаться дальше. Найди в Подгороде Джозефа Грегориана и скажи ему, что ты $gготов:готова;.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5554,'Перед тем как я смогу тебе помочь, ты $gдолжен:должна; научиться основам. Поговори с моим помощником Вханом. Он достаточно умен и терпелив, чтобы заняться твоим обучением.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Перед тем как я смогу тебе помочь, ты $gдолжен:должна; научиться основам. Поговори с моим помощником Вханом. Он достаточно умен и терпелив, чтобы заняться твоим обучением.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5555,'Ты очень $gприлежный ученик:прилежная ученица;. Я с радостью займусь твоим обучением!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты очень $gприлежный ученик:прилежная ученица;. Я с радостью займусь твоим обучением!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5556,'Навыки портного иногда бывают очень кстати. Мне вот как-то пришлось пришивать себе руку.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Навыки портного иногда бывают очень кстати. Мне вот как-то пришлось пришивать себе руку.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5559,'Новичку не понять моих уроков. Иди к Виктору Уорду.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Новичку не понять моих уроков. Иди к Виктору Уорду.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5560,'Да ты $gхрабрый парень:храбрая девушка;! Мне это нравится. Ну, начнем!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Да ты $gхрабрый парень:храбрая девушка;! Мне это нравится. Ну, начнем!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5561,'Да, я уже довольно давно держу тут лавку. Дела идут хорошо: здесь проходит много разных путешественников…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да, я уже довольно давно держу тут лавку. Дела идут хорошо: здесь проходит много разных путешественников…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5562,'Меня превосходит в мастерстве только один портной. Говорят, он живет на острове Терамор. Вот он-то тебе и нужен.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Меня превосходит в мастерстве только один портной. Говорят, он живет на острове Терамор. Вот он-то тебе и нужен.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5564,'Боюсь, что, прежде чем я смогу заняться твоим обучением, тебе придется набраться опыта.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Боюсь, что, прежде чем я смогу заняться твоим обучением, тебе придется набраться опыта.',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5565,'Хорошо! Уверяю вас, мои старания будут не напрасны!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Хорошо! Уверяю вас, мои старания будут не напрасны!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5566,'Ткань подойдет. Но я предпочитаю работать с человечьей кожей.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ткань подойдет. Но я предпочитаю работать с человечьей кожей.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5567,'Вам нужно учиться у настоящего мастера! Найдите Дерила Стака на Мельнице Таррен – вот кто поможет вам.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вам нужно учиться у настоящего мастера! Найдите Дерила Стака на Мельнице Таррен – вот кто поможет вам.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5569,'Я примусь за твое обучение, когда наступит подходящее время... Но пока оно не наступило. Тебе предстоит еще многому научиться!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я примусь за твое обучение, когда наступит подходящее время... Но пока оно не наступило. Тебе предстоит еще многому научиться!',`text0_0_loc8`);
