INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5570,'Хорошо! Уверяю вас, мои старания будут не напрасны!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Хорошо! Уверяю вас, мои старания будут не напрасны!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5571,'Я одевал королей. Поучись как следует – и ты так сможешь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я одевал королей. Поучись как следует – и ты так сможешь.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5573,'Ты $gпрошел:прошла; долгий путь, $gстранник:странница;. Тебе нужно выполнить еще одно задание...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты $gпрошел:прошла; долгий путь, $gстранник:странница;. Тебе нужно выполнить еще одно задание...',`text0_0_loc8`);
