INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5577,'Должен признать, ты достойно $gпроявил:проявила; себя в портняжном деле. Пришла пора проверить тебя всерьез...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Должен признать, ты достойно $gпроявил:проявила; себя в портняжном деле. Пришла пора проверить тебя всерьез...',`text0_0_loc8`);
