INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5578,'Кто тебя прислал? Ты еще не годишься мне в ученики! Когда ты будешь $gготов:готова;, тебе скажут.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Кто тебя прислал? Ты еще не годишься мне в ученики! Когда ты будешь $gготов:готова;, тебе скажут.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5580,'Попомните мои слова! Телcамарские грифоны – самые быстрые во всех Восточных королевствах!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Попомните мои слова! Телcамарские грифоны – самые быстрые во всех Восточных королевствах!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5581,'Нет лучше профессии, чем горняк. И нет лучше горняков, чем дворфы!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Нет лучше профессии, чем горняк. И нет лучше горняков, чем дворфы!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5582,'Может, у гномов Громового Молота и быстрокрылые скакуны, но могут ли грифоны Заоблачного пика выдержать жар Великой Кузни? Навряд ли!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Может, у гномов Громового Молота и быстрокрылые скакуны, но могут ли грифоны Заоблачного пика выдержать жар Великой Кузни? Навряд ли!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5583,'Хорошего горняка можно узнать по крепкой хватке, отважному сердцу и черной пыли в волосах.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Хорошего горняка можно узнать по крепкой хватке, отважному сердцу и черной пыли в волосах.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5593,'Этот медведь бродит по дороге возле Туннеля Когтя, к западу от озера Мистраль и альянсовского Приюта Серебряного Ветра. Он самый слабый из трех зверей, но не стоит его недооценивать. Этот медведь угрожает всем, кто путешествует между Ясеневым лесом и Когтистыми горами.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Этот медведь бродит по дороге возле Туннеля Когтя, к западу от озера Мистраль и альянсовского Приюта Серебряного Ветра. Он самый слабый из трех зверей, но не стоит его недооценивать. Этот медведь угрожает всем, кто путешествует между Ясеневым лесом и Когтистыми горами.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5595,'Говорят, что эта самка ночного саблезуба становится смирной в присутствии ночных эльфов и их союзников. Это делает ее особенно ценной добычей для нас. Охотничьи угодья Тенумбры простираются от Приюта в Ночных Лесах до западной границы наших земель. Ее мех черен, как смоль, а бегает она невероятно быстро.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Говорят, что эта самка ночного саблезуба становится смирной в присутствии ночных эльфов и их союзников. Это делает ее особенно ценной добычей для нас. Охотничьи угодья Тенумбры простираются от Приюта в Ночных Лесах до западной границы наших земель. Ее мех черен, как смоль, а бегает она невероятно быстро.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5613,'Приветствую тебя, |3-6($c)! Добро пожаловать на фронт! Если ты ищешь достойное дело, ты $gпришел:пришла; по адресу. Мы всегда рады $gкрепким парням:способным девушкам;, желающим прославить Орду!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приветствую тебя, |3-6($c)! Добро пожаловать на фронт! Если ты ищешь достойное дело, ты $gпришел:пришла; по адресу. Мы всегда рады $gкрепким парням:способным девушкам;, желающим прославить Орду!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5633,'Под королевской маской скрывается дракон. Таблички помогут раскрыть его – вернее, ее – истинную сущность... Если то, что я видел, правда, то мне не пережить этой битвы. Ты $gдолжен:должна; закончить то, что я начал. Готовы ли твои войска? $gГотов:Готова; ли ты $gсам:сама;? Мы ждем твоего слова.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Под королевской маской скрывается дракон. Таблички помогут раскрыть его – вернее, ее – истинную сущность... Если то, что я видел, правда, то мне не пережить этой битвы. Ты $gдолжен:должна; закончить то, что я начал. Готовы ли твои войска? $gГотов:Готова; ли ты $gсам:сама;? Мы ждем твоего слова.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5654,'Стихии говорят с нами, |3-6($c). Они делятся с нами своей мудростью, которую мы должны постичь, и секретами, которые обязаны хранить.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Стихии говорят с нами, |3-6($c). Они делятся с нами своей мудростью, которую мы должны постичь, и секретами, которые обязаны хранить.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (5673,'С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?','С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смогла учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смог учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','С помощью строгой переквалификации мне пришлось заставить множество учеников забыть все, что они знали, чтобы я смогла учить их заново. Услугу, что я предлагаю, с каждым разом все сложнее и сложнее оказать. Вот почему каждый раз при ее использовании я повышаю цену. Ты желаешь забыть все, что знаешь?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (5674,'Помимо обучения я в силах стереть знания из твоей памяти. Но предупреждаю: с каждым разом это сделать все сложнее, поэтому цена все выше и выше.','Помимо обучения я в силах стереть знания из твоей памяти. Но предупреждаю: с каждым разом это сделать все сложнее, поэтому цена все выше и выше.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Помимо обучения я в силах стереть знания из твоей памяти. Но предупреждаю: с каждым разом это сделать все сложнее, поэтому цена все выше и выше.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Помимо обучения я в силах стереть знания из твоей памяти. Но предупреждаю: с каждым разом это сделать все сложнее, поэтому цена все выше и выше.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (5693,'Тайная магия опасна только для тех, кто слаб. Так что тренируйся чаще.','Тайная магия опасна только для тех, кто слаб. Так что тренируйся чаще.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тайная магия опасна только для тех, кто слаб. Так что тренируйся чаще.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Тайная магия опасна только для тех, кто слаб. Так что тренируйся чаще.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (5694,'Добро пожаловать, $gбрат:сестра;. Если ты $gпришел:пришла; учиться, я с радостью поделюсь с тобой знаниями.$B$BВскоре ты погрузишься в Изумрудный Сон. Ты проспишь долгие годы и примешь множество обличий. Именно так будет проходить твое обучение.','Добро пожаловать, $gбрат:сестра;. Если ты $gпришел:пришла; учиться, я с радостью поделюсь с тобой знаниями.$B$BВскоре ты погрузишься в Изумрудный Сон. Ты проспишь долгие годы и примешь множество обличий. Именно так будет проходить твое обучение.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать, $gбрат:сестра;. Если ты $gпришел:пришла; учиться, я с радостью поделюсь с тобой знаниями.$B$BВскоре ты погрузишься в Изумрудный Сон. Ты проспишь долгие годы и примешь множество обличий. Именно так будет проходить твое обучение.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Добро пожаловать, $gбрат:сестра;. Если ты $gпришел:пришла; учиться, я с радостью поделюсь с тобой знаниями.$B$BВскоре ты погрузишься в Изумрудный Сон. Ты проспишь долгие годы и примешь множество обличий. Именно так будет проходить твое обучение.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (5695,'Чем мне тебе помочь?','Чем мне тебе помочь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Чем мне тебе помочь?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Чем мне тебе помочь?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5696,'Мне больше нечему учить! Нечему учить кого-то, знающего столько, как ты! Тебе, ордынцу, следует поговорить с Ноггом в Оргриммаре!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мне больше нечему учить! Нечему учить кого-то, знающего столько, как ты! Тебе, ордынцу, следует поговорить с Ноггом в Оргриммаре!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5713,'Я тебе ничего не сделаю. Я наблюдаю за иглогривами и составляю заметки об их поведении. Мои соплеменники заметили в этом районе какое-то странное излучение. Я вышла на разведку и обнаружила, что дело плохо.$B$BЗдесь, похоже, действует посланец нежити, сведущий в тайной магии. И вряд ли он из Отрекшихся… Думаю, тут все намного серьезнее.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я тебе ничего не сделаю. Я наблюдаю за иглогривами и составляю заметки об их поведении. Мои соплеменники заметили в этом районе какое-то странное излучение. Я вышла на разведку и обнаружила, что дело плохо.$B$BЗдесь, похоже, действует посланец нежити, сведущий в тайной магии. И вряд ли он из Отрекшихся… Думаю, тут все намного серьезнее.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (5715,'$C, твой дух недостаточно крепок, чтобы управлять теми силами, с которыми имеем дело мы.','$C, твой дух недостаточно крепок, чтобы управлять теми силами, с которыми имеем дело мы.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','$C, твой дух недостаточно крепок, чтобы управлять теми силами, с которыми имеем дело мы.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','$C, твой дух недостаточно крепок, чтобы управлять теми силами, с которыми имеем дело мы.',`text0_1_loc8`);
