INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (5717,'Пути Матери-Земли неисповедимы. Пусть ваши предки хранят вас, |3-6($c).','Пути Матери-Земли неисповедимы. Пусть ваши предки хранят вас, |3-6($c).') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Пути Матери-Земли неисповедимы. Пусть ваши предки хранят вас, |3-6($c).',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Пути Матери-Земли неисповедимы. Пусть ваши предки хранят вас, |3-6($c).',`text0_1_loc8`);
