INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (5721,'Достаточно бросить на тебя один взгляд, чтобы понять, что ты не воин.$B$BМожет пойдешь позанимаешься чем-нибудь безопасным? Книжку там почитаешь…','Достаточно бросить на тебя один взгляд, чтобы понять, что ты не воин.$B$BМожет пойдешь позанимаешься чем-нибудь безопасным? Книжку там почитаешь…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Достаточно бросить на тебя один взгляд, чтобы понять, что ты не воин.$B$BМожет пойдешь позанимаешься чем-нибудь безопасным? Книжку там почитаешь…',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Достаточно бросить на тебя один взгляд, чтобы понять, что ты не воин.$B$BМожет пойдешь позанимаешься чем-нибудь безопасным? Книжку там почитаешь…',`text0_1_loc8`);
