INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (5722,'Тьма не примет тебя, |3-6($c). Прекращай свой жалкий лепет и уйди с глаз долой! Исчезни!','Тьма не примет тебя, |3-6($c). Прекращай свой жалкий лепет и уйди с глаз долой! Исчезни!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тьма не примет тебя, |3-6($c). Прекращай свой жалкий лепет и уйди с глаз долой! Исчезни!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Тьма не примет тебя, |3-6($c). Прекращай свой жалкий лепет и уйди с глаз долой! Исчезни!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (5723,'Боюсь, твоя душа недостаточно темна, чтобы нам было о чем говорить. Оставь меня в покое.','Боюсь, твоя душа недостаточно темна, чтобы нам было о чем говорить. Оставь меня в покое.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Боюсь, твоя душа недостаточно темна, чтобы нам было о чем говорить. Оставь меня в покое.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Боюсь, твоя душа недостаточно темна, чтобы нам было о чем говорить. Оставь меня в покое.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (5724,'Ты не воин. Ты не выдержишь и дня моих тренировок! $B$BТоже мне, |3-6($c), $gвозомнивший:возомнившая; себя воином! Ха!','Ты не воин. Ты не выдержишь и дня моих тренировок! $B$BТоже мне, |3-6($c), $gвозомнивший:возомнившая; себя воином! Ха!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты не воин. Ты не выдержишь и дня моих тренировок! $B$BТоже мне, |3-6($c), $gвозомнивший:возомнившая; себя воином! Ха!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты не воин. Ты не выдержишь и дня моих тренировок! $B$BТоже мне, |3-6($c), $gвозомнивший:возомнившая; себя воином! Ха!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (5725,'Я не вижу в тебе воинского духа, дитя. Ты $gприрожденный:прирожденная:c; |3-6($c), и мне нечему тебя учить.','Я не вижу в тебе воинского духа, дитя. Ты $gприрожденный:прирожденная; |3-6($c), и мне нечему тебя учить.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я не вижу в тебе воинского духа, дитя. Ты $gприрожденный:прирожденная:c; |3-6($c), и мне нечему тебя учить.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я не вижу в тебе воинского духа, дитя. Ты $gприрожденный:прирожденная; |3-6($c), и мне нечему тебя учить.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5733,'Шпионы Изувеченной Длани добрались даже до верхней цитадели Черной горы. Сбор сведений идет не слишком быстро, но мы уже выяснили кое-что, на что нельзя закрывать глаза.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Шпионы Изувеченной Длани добрались даже до верхней цитадели Черной горы. Сбор сведений идет не слишком быстро, но мы уже выяснили кое-что, на что нельзя закрывать глаза.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5734,'Оказалось, что влияние черных драконов простирается далеко за пределы Пылающих степей. Под него попал даже Штормград! После этого узурпатор был разоблачен и изгнан.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Оказалось, что влияние черных драконов простирается далеко за пределы Пылающих степей. Под него попал даже Штормград! После этого узурпатор был разоблачен и изгнан.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5735,'Действительно. Царица черных драконов замаскировалась под члена королевского двора. Хуже того, похоже, она взяла под контроль верховного лорда Штормграда, Болвара Фордрагона.$B$BНеудивительно, что он принимал такие идиотские военные решения. Передвижение сил Альянса в последнее время не раз вызывало у нас недоумение. Теперь мы понимаем, что черные драконы пытались раздробить империю – уничтожить ее изнутри.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Действительно. Царица черных драконов замаскировалась под члена королевского двора. Хуже того, похоже, она взяла под контроль верховного лорда Штормграда, Болвара Фордрагона.$B$BНеудивительно, что он принимал такие идиотские военные решения. Передвижение сил Альянса в последнее время не раз вызывало у нас недоумение. Теперь мы понимаем, что черные драконы пытались раздробить империю – уничтожить ее изнутри.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5736,'*Тралл смеется.*$B$BЕще многому предстоит научиться, |3-6($r).$B$BТы слишком $gмолод:молода;, чтобы помнить войны и кровопролитие прежних эпох. Слишком $gмолод:молода;, чтобы помнить тяжесть проклятия, лежащего на нашем народе.$B$BНаша ситуация с Альянсом сейчас хрупка. Рейды и небольшие битвы происходят, но в целом есть мир – то, чего наш народ не знал тысячелетиями. Хотелось бы тебе пожертвовать всем этим и ввергнуть нас в хаос, но против нового врага? Врага, который не успокоится, пока мы все не будем уничтожены?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','*Тралл смеется.*$B$BЕще многому предстоит научиться, |3-6($r).$B$BТы слишком $gмолод:молода;, чтобы помнить войны и кровопролитие прежних эпох. Слишком $gмолод:молода;, чтобы помнить тяжесть проклятия, лежащего на нашем народе.$B$BНаша ситуация с Альянсом сейчас хрупка. Рейды и небольшие битвы происходят, но в целом есть мир – то, чего наш народ не знал тысячелетиями. Хотелось бы тебе пожертвовать всем этим и ввергнуть нас в хаос, но против нового врага? Врага, который не успокоится, пока мы все не будем уничтожены?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5740,'Добро пожаловать, $gбрат мой:сестра моя;. Если ты $gпришел:пришла; за знаниями, я буду счастлив обучить тебя.$B$BПока Малфурион лежит в Изумрудном сне, мы – единственные хранители равновесия. Никогда не забывай этого.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать, $gбрат мой:сестра моя;. Если ты $gпришел:пришла; за знаниями, я буду счастлив обучить тебя.$B$BПока Малфурион лежит в Изумрудном сне, мы – единственные хранители равновесия. Никогда не забывай этого.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5773,'В горах Каменного Когтя есть множество пещер, в которых уже сгинуло немало алчных искателей приключений.$B$BВидимо, |3-6($c), те богатства, что ты ищешь, можно отыскать лишь следуя зову сердца и души.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','В горах Каменного Когтя есть множество пещер, в которых уже сгинуло немало алчных искателей приключений.$B$BВидимо, |3-6($c), те богатства, что ты ищешь, можно отыскать лишь следуя зову сердца и души.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5793,'Рыбка такая вкусная. Ты хочешь учиться ловить рыбку? Есть рыбку? Мммммм…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Рыбка такая вкусная. Ты хочешь учиться ловить рыбку? Есть рыбку? Мммммм…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5794,'Ага, я могу научить тебя ловить рыбу.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ага, я могу научить тебя ловить рыбу.',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5796,'Зачарованный торий – весьма ценный металл. Достать его можно, поговорив с кузнецами и горняками, достигшими звания мастерового.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Зачарованный торий – весьма ценный металл. Достать его можно, поговорив с кузнецами и горняками, достигшими звания мастерового.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5798,'Может быть, мы и пострадали от засухи, но не испытываем нехватки мяса! Не хочешь изучить мои товары?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Может быть, мы и пострадали от засухи, но не испытываем нехватки мяса! Не хочешь изучить мои товары?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
