INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5819,'Приветствую, |3-6($c). Чем я могу помочь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приветствую, |3-6($c). Чем я могу помочь?',`text0_0_loc8`);
