INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5820,'Я вот о чем хочу тебя спросить, |3-6($c):$Bкто из Аспектов, созданных титанами, превратился в мерзкое существо по имени Смертокрыл?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я вот о чем хочу тебя спросить, |3-6($c):$Bкто из Аспектов, созданных титанами, превратился в мерзкое существо по имени Смертокрыл?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5821,'Всегда приятно, когда кто-то желает со мной поговорить. Как у тебя дела, |3-6($c)?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Всегда приятно, когда кто-то желает со мной поговорить. Как у тебя дела, |3-6($c)?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5833,'Ага, ты кое-что знаешь! Если хочешь узнать больше, поговори с Джорджио Болеро в Штормграде.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ага, ты кое-что знаешь! Если хочешь узнать больше, поговори с Джорджио Болеро в Штормграде.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5834,'Братство Тория обладает знаниями, необходимыми, чтобы изготовить священные оружие и доспехи Повелителя Огня, но нам не хватает людей, чтобы добыть нужные для этого материалы.$B$BЯ, Локтос Зловещий Торговец, получил от братства полномочия обменять лучшие рецепты на материалы, собранные в Огненных Недрах.$B$BСкажи, что ты предлагаешь, |3-6($r).') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Братство Тория обладает знаниями, необходимыми, чтобы изготовить священные оружие и доспехи Повелителя Огня, но нам не хватает людей, чтобы добыть нужные для этого материалы.$B$BЯ, Локтос Зловещий Торговец, получил от братства полномочия обменять лучшие рецепты на материалы, собранные в Огненных Недрах.$B$BСкажи, что ты предлагаешь, |3-6($r).',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (5835,'Хочешь сделать своих демонов более могущественными? Ты $gпришел:пришла; по адресу – если, конечно, у тебя достаточно золота.','Хочешь сделать своих демонов более могущественными? Ты $gпришел:пришла; по адресу – если, конечно, у тебя достаточно золота.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Хочешь сделать своих демонов более могущественными? Ты $gпришел:пришла; по адресу – если, конечно, у тебя достаточно золота.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Хочешь сделать своих демонов более могущественными? Ты $gпришел:пришла; по адресу – если, конечно, у тебя достаточно золота.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (5836,'Ты не $gчернокнижник:чернокнижница;! Ступай!','Ты не $gчернокнижник:чернокнижница;! Ступай!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты не $gчернокнижник:чернокнижница;! Ступай!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты не $gчернокнижник:чернокнижница;! Ступай!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (5838,'Ты хочешь учиться, чтобы передать знания своим питомцам?','Ты хочешь учиться, чтобы передать знания своим питомцам?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты хочешь учиться, чтобы передать знания своим питомцам?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты хочешь учиться, чтобы передать знания своим питомцам?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (5839,'Ах, $gдруг:подруга;, я помогаю только охотникам и их питомцам.','Ах, $gдруг:подруга;, я помогаю только охотникам и их питомцам.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ах, $gдруг:подруга;, я помогаю только охотникам и их питомцам.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ах, $gдруг:подруга;, я помогаю только охотникам и их питомцам.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (5840,'Королевское фармацевтическое общество не терпит дураков, как и я. Может быть, в следующий раз, когда мы будем говорить о моих скакунах, ты заслужишь полное доверие жителей Подгорода. А пока…','Королевское фармацевтическое общество не терпит дураков, как и я. Может быть, в следующий раз, когда мы будем говорить о моих скакунах, ты заслужишь полное доверие жителей Подгорода. А пока…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Королевское фармацевтическое общество не терпит дураков, как и я. Может быть, в следующий раз, когда мы будем говорить о моих скакунах, ты заслужишь полное доверие жителей Подгорода. А пока…',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Королевское фармацевтическое общество не терпит дураков, как и я. Может быть, в следующий раз, когда мы будем говорить о моих скакунах, ты заслужишь полное доверие жителей Подгорода. А пока…',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (5841,'Я продаю своих питомцев только тем, кого превозносят жители Оргриммара и весь народ орков. Докажите, что вы достойны, – и я выберу для вас самого сильного из своих волков!','Я продаю своих питомцев только тем, кого превозносят жители Оргриммара и весь народ орков. Докажите, что вы достойны, – и я выберу для вас самого сильного из своих волков!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я продаю своих питомцев только тем, кого превозносят жители Оргриммара и весь народ орков. Докажите, что вы достойны, – и я выберу для вас самого сильного из своих волков!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я продаю своих питомцев только тем, кого превозносят жители Оргриммара и весь народ орков. Докажите, что вы достойны, – и я выберу для вас самого сильного из своих волков!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (5842,'Извини, $gбрат:сестра;, но я продаю своих ящеров только настоящим друзьям Черного Копья. Вот когда будет наше племя тебя превозносить – тогда и приходи.','Извини, $gбрат:сестра;, но я продаю своих ящеров только настоящим друзьям Черного Копья. Вот когда будет наше племя тебя превозносить – тогда и приходи.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Извини, $gбрат:сестра;, но я продаю своих ящеров только настоящим друзьям Черного Копья. Вот когда будет наше племя тебя превозносить – тогда и приходи.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Извини, $gбрат:сестра;, но я продаю своих ящеров только настоящим друзьям Черного Копья. Вот когда будет наше племя тебя превозносить – тогда и приходи.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (5843,'Мой народ тебя не знает. Кодо – могучие скакуны. Мой народ любит их и заботится о них. Их не отдают чужим. Пока Старейшины Громового Утеса не сочтут тебя $gдостойным:достойной;, я не смогу продать тебе кодо.','Мой народ тебя не знает. Кодо – могучие скакуны. Мой народ любит их и заботится о них. Их не отдают чужим. Пока Старейшины Громового Утеса не сочтут тебя $gдостойным:достойной;, я не смогу продать тебе кодо.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мой народ тебя не знает. Кодо – могучие скакуны. Мой народ любит их и заботится о них. Их не отдают чужим. Пока Старейшины Громового Утеса не сочтут тебя $gдостойным:достойной;, я не смогу продать тебе кодо.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мой народ тебя не знает. Кодо – могучие скакуны. Мой народ любит их и заботится о них. Их не отдают чужим. Пока Старейшины Громового Утеса не сочтут тебя $gдостойным:достойной;, я не смогу продать тебе кодо.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5853,'Назад! Здесь не место детям! Уходи!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Назад! Здесь не место детям! Уходи!',`text0_0_loc8`);
