INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5920,'Лучшие котлеты из подземной крысы по эту сторону Каз Модана!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Лучшие котлеты из подземной крысы по эту сторону Каз Модана!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (5921,'Тебе, я вижу, работа нужна. Садись-ка ты на поезд и отправляйся к моему брату Монти в депо Стальгорна. У него наверняка для тебя задание найдется.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тебе, я вижу, работа нужна. Садись-ка ты на поезд и отправляйся к моему брату Монти в депо Стальгорна. У него наверняка для тебя задание найдется.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`) VALUES (5933,'Будь $gосторожен:осторожна;, $gнезнакомец:незнакомка;.','Тебя не знают в поместье "Черный Ворон", |3-6($c).','Наглость. Предводитель "Черного Ворона" не любит наглецов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Будь $gосторожен:осторожна;, $gнезнакомец:незнакомка;.',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Тебя не знают в поместье "Черный Ворон", |3-6($c).',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Наглость. Предводитель "Черного Ворона" не любит наглецов.',`text2_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text1_0_loc8`,`text2_0_loc8`) VALUES (5934,'Приветствую, |3-6($c). Ты уже $Gговорил:говорила; с Фарадом?','Синдикат – всего лишь кучка неорганизованных, неумелых и ленивых идиотов…') ON DUPLICATE KEY UPDATE `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Приветствую, |3-6($c). Ты уже $Gговорил:говорила; с Фарадом?',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Синдикат – всего лишь кучка неорганизованных, неумелых и ленивых идиотов…',`text2_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (5938,'Ничтожество, ты смеешь являться в поместье Черный Ворон?','Ничтожество, ты смеешь являться в поместье Черный Ворон?','Если выберешься отсюда без клинка в спине или яда в крови – можешь собой гордиться.','Если выберешься отсюда без клинка в спине или яда в крови – можешь собой гордиться.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ничтожество, ты смеешь являться в поместье Черный Ворон?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ничтожество, ты смеешь являться в поместье Черный Ворон?',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Если выберешься отсюда без клинка в спине или яда в крови – можешь собой гордиться.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Если выберешься отсюда без клинка в спине или яда в крови – можешь собой гордиться.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text1_0_loc8`,`text1_1_loc8`) VALUES (5939,'Вам нужно поговорить с Уинстоном. Кажется, он искал таких умелых воров, как вы.','Вам нужно поговорить с Уинстоном. Кажется, он искал таких умелых воров, как вы.') ON DUPLICATE KEY UPDATE `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Вам нужно поговорить с Уинстоном. Кажется, он искал таких умелых воров, как вы.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Вам нужно поговорить с Уинстоном. Кажется, он искал таких умелых воров, как вы.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (5943,'Да пребудет с тобой Элуна, |3-6($c). Храм Луны пришел на помощь обездоленным жителям Аубердина.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Да пребудет с тобой Элуна, |3-6($c). Храм Луны пришел на помощь обездоленным жителям Аубердина.',`text0_1_loc8`);
