INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (5973,'Ищи Шоя\'май возле таверны. Не задерживай меня, я занят.','Ищи Шоя\'май возле таверны. Не задерживай меня, я занята.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ищи Шоя\'май возле таверны. Не задерживай меня, я занят.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ищи Шоя\'май возле таверны. Не задерживай меня, я занята.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (5977,'Тебе нужна помощь Балруга. Его ты найдешь на нижнем уступе между таверной и банком Громового Утеса.','Тебе нужна помощь Балруга. Его ты найдешь на нижнем уступе между таверной и банком Громового Утеса.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тебе нужна помощь Балруга. Его ты найдешь на нижнем уступе между таверной и банком Громового Утеса.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Тебе нужна помощь Балруга. Его ты найдешь на нижнем уступе между таверной и банком Громового Утеса.',`text0_1_loc8`);
