INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (5978,'Как это ни странно, смотритель стойл Морганус сейчас стоит рядом со стойлами.','Как это ни странно, смотритель стойл Морганус сейчас стоит рядом со стойлами.','Ума у вас, вижу, немного… Если бы я был смотрителем стойл, то я, наверное, постоянно был около стойл, а? Там Моргануса и ищите.','Ума у вас, вижу, немного… Если бы я был смотрителем стойл, то я, наверное, постоянно был около стойл, а? Там Моргануса и ищите.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Как это ни странно, смотритель стойл Морганус сейчас стоит рядом со стойлами.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Как это ни странно, смотритель стойл Морганус сейчас стоит рядом со стойлами.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Ума у вас, вижу, немного… Если бы я был смотрителем стойл, то я, наверное, постоянно был около стойл, а? Там Моргануса и ищите.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Ума у вас, вижу, немного… Если бы я был смотрителем стойл, то я, наверное, постоянно был около стойл, а? Там Моргануса и ищите.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (5979,'Аню Молрэ можно найти в таверне на верхнем кольце Торгового квартала.','Аню Молрэ можно найти в таверне на верхнем кольце Торгового квартала.','Вам надо много питомцев. Аня Молрэ поможет за ними смотреть. Ищите ее в таверне на верхнем уровне Торгового квартала.','Вам надо много питомцев. Аня Молрэ поможет за ними смотреть. Ищите ее в таверне на верхнем уровне Торгового квартала.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Аню Молрэ можно найти в таверне на верхнем кольце Торгового квартала.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Аню Молрэ можно найти в таверне на верхнем кольце Торгового квартала.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Вам надо много питомцев. Аня Молрэ поможет за ними смотреть. Ищите ее в таверне на верхнем уровне Торгового квартала.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Вам надо много питомцев. Аня Молрэ поможет за ними смотреть. Ищите ее в таверне на верхнем уровне Торгового квартала.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (5983,'О животных тут уже много лет заботится старушка Ирма, она и за вашим с радостью приглядит. Ее можно найти возле таверны "Гордость льва".','О животных тут уже много лет заботится старушка Ирма, она и за вашим с радостью приглядит. Ее можно найти возле таверны "Гордость льва".') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','О животных тут уже много лет заботится старушка Ирма, она и за вашим с радостью приглядит. Ее можно найти возле таверны "Гордость льва".',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','О животных тут уже много лет заботится старушка Ирма, она и за вашим с радостью приглядит. Ее можно найти возле таверны "Гордость льва".',`text0_1_loc8`);
