INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (5984,'Тебе нужна Дженова Камнещит из Квартала Дворфов. Она заботится о питомцах охотников, пока те учатся у ее отца.','Тебе нужна Дженова Камнещит из Квартала Дворфов. Она заботится о питомцах охотников, пока те учатся у ее отца.','Если тебе нужно временно пристроить питомца, поговори с Дженовой Камнещит из Квартала Дворфов.','Если тебе нужно временно пристроить питомца, поговори с Дженовой Камнещит из Квартала Дворфов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тебе нужна Дженова Камнещит из Квартала Дворфов. Она заботится о питомцах охотников, пока те учатся у ее отца.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Тебе нужна Дженова Камнещит из Квартала Дворфов. Она заботится о питомцах охотников, пока те учатся у ее отца.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Если тебе нужно временно пристроить питомца, поговори с Дженовой Камнещит из Квартала Дворфов.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Если тебе нужно временно пристроить питомца, поговори с Дженовой Камнещит из Квартала Дворфов.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (5985,'Что ж, $gюноша:девушка;, ищите Шелби Щебенку прямо возле "Громоварки" в Караносе. Она прекрасно позаботится обо всех ваших питомцах.','Что ж, $gюноша:девушка;, ищите Шелби Щебенку прямо возле "Громоварки" в Караносе. Она прекрасно позаботится обо всех ваших питомцах.','У Шелби Щебенки полно всякого зверья. Ее можно найти в "Громоварке". Если что, она и за вашим питомцем присмотрит.','У Шелби Щебенки полно всякого зверья. Ее можно найти в "Громоварке". Если что, она и за вашим питомцем присмотрит.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что ж, $gюноша:девушка;, ищите Шелби Щебенку прямо возле "Громоварки" в Караносе. Она прекрасно позаботится обо всех ваших питомцах.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Что ж, $gюноша:девушка;, ищите Шелби Щебенку прямо возле "Громоварки" в Караносе. Она прекрасно позаботится обо всех ваших питомцах.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','У Шелби Щебенки полно всякого зверья. Ее можно найти в "Громоварке". Если что, она и за вашим питомцем присмотрит.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','У Шелби Щебенки полно всякого зверья. Ее можно найти в "Громоварке". Если что, она и за вашим питомцем присмотрит.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (5986,'Забота о животных – то, в чем Ульбрек Огненная Длань знает толк. Обычно он водит компанию с охотниками в Оружейной. Если хочешь доверить ему своего питомца, там его и ищи.','Забота о животных – то, в чем Ульбрек Огненная Длань знает толк. Обычно он водит компанию с охотниками в Оружейной. Если хочешь доверить ему своего питомца, там его и ищи.','Найди Ульбрека Огненную Длань в Оружейной. Он позаботится о том, чтобы твои питомцы были хорошо устроены и досыта накормлены.','Найди Ульбрека Огненную Длань в Оружейной. Он позаботится о том, чтобы твои питомцы были хорошо устроены и досыта накормлены.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Забота о животных – то, в чем Ульбрек Огненная Длань знает толк. Обычно он водит компанию с охотниками в Оружейной. Если хочешь доверить ему своего питомца, там его и ищи.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Забота о животных – то, в чем Ульбрек Огненная Длань знает толк. Обычно он водит компанию с охотниками в Оружейной. Если хочешь доверить ему своего питомца, там его и ищи.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Найди Ульбрека Огненную Длань в Оружейной. Он позаботится о том, чтобы твои питомцы были хорошо устроены и досыта накормлены.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Найди Ульбрека Огненную Длань в Оружейной. Он позаботится о том, чтобы твои питомцы были хорошо устроены и досыта накормлены.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6033,'Да, |3-6($c)? Ты $gприбыл:прибыла; на службу?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да, |3-6($c)? Ты $gприбыл:прибыла; на службу?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6058,'Рудник Ледяного Зуба находится на территории Орды, в горах к северу от Кладбища Северного Волка.$B$BСейчас там хозяйничают кобольды.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Рудник Ледяного Зуба находится на территории Орды, в горах к северу от Кладбища Северного Волка.$B$BСейчас там хозяйничают кобольды.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6062,'Это памятник павшим защитникам Штормграда. Нашему народу пришлось вынести неимоверные тяготы, чтобы вновь обрести свободу и распоряжаться собственными судьбами. Здесь мы отдаем дань памяти всем, кто погиб в первой войне.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Это памятник павшим защитникам Штормграда. Нашему народу пришлось вынести неимоверные тяготы, чтобы вновь обрести свободу и распоряжаться собственными судьбами. Здесь мы отдаем дань памяти всем, кто погиб в первой войне.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6066,'В Альтеракской долине вовсю идут бои. Там сейчас острая нехватка припасов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','В Альтеракской долине вовсю идут бои. Там сейчас острая нехватка припасов.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (6093,'Кровь наших врагов обагрит поле боя. Великие элементали ответят на наш призыв и сокрушат всех, кто встанет у нас на пути.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Кровь наших врагов обагрит поле боя. Великие элементали ответят на наш призыв и сокрушат всех, кто встанет у нас на пути.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (6095,'Отлично, боец. Мне надо вернуться в лагерь на базу. Прикроешь меня?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Отлично, боец. Мне надо вернуться в лагерь на базу. Прикроешь меня?',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (6096,'Ну наконец-то! Где ты так долго $gболтался:болталась;? А, неважно. Прикрой меня. Я собираюсь прорваться на базу!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ну наконец-то! Где ты так долго $gболтался:болталась;? А, неважно. Прикрой меня. Я собираюсь прорваться на базу!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6101,'Мне нужно несколько умелых ведомых, чтобы выбраться отсюда и вернуться на базу.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мне нужно несколько умелых ведомых, чтобы выбраться отсюда и вернуться на базу.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6104,'На страницах этой книги содержится информация о сделках, покупателях и других коммерческих делах.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','На страницах этой книги содержится информация о сделках, покупателях и других коммерческих делах.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`,`text1_1_loc8`,`text2_1_loc8`,`text3_1_loc8`) VALUES (6105,'Никогда не смотри командиру прямо в глаза.','У нас приказ Кэрна, |3-6($r). Не мешай нам выполнять задание командира.','С предводителем шаманов лучше не шутить, |3-6($r).','Скоро явится Локолар… Скоро… Совсем скоро…') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Никогда не смотри командиру прямо в глаза.',`text0_1_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','У нас приказ Кэрна, |3-6($r). Не мешай нам выполнять задание командира.',`text1_1_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','С предводителем шаманов лучше не шутить, |3-6($r).',`text2_1_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','Скоро явится Локолар… Скоро… Совсем скоро…',`text3_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6108,'Я герцог Гидраксис, верховный повелитель воды. Ты не элементаль, и поэтому тебе не понять нашей борьбы, но, может быть, мы сможем заключить взаимовыгодный договор…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я герцог Гидраксис, верховный повелитель воды. Ты не элементаль, и поэтому тебе не понять нашей борьбы, но, может быть, мы сможем заключить взаимовыгодный договор…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6153,'Если тебе нужны знания Круга Кенария, обращайся ко мне. Но чтобы я смог помочь, ты $gдолжен:должна; сообщить мне, какие именно знания тебе нужны.$B$BВидишь, как все устроено? Просто отлично!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если тебе нужны знания Круга Кенария, обращайся ко мне. Но чтобы я смог помочь, ты $gдолжен:должна; сообщить мне, какие именно знания тебе нужны.$B$BВидишь, как все устроено? Просто отлично!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6154,'Не слушай пульс мира – ответ сокрыт в тебе. Ты знаешь правду.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не слушай пульс мира – ответ сокрыт в тебе. Ты знаешь правду.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6159,'Добро пожаловать в подгородское бюро регистрации гильдий. Чего желаете?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать в подгородское бюро регистрации гильдий. Чего желаете?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`) VALUES (6161,'Говори с Гидраксисом.','Не о чем нам говорить, $gмалыш:малышка;.','Не говори со мной на своем грубом языке! Его вытерпит только Гидраксис.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Говори с Гидраксисом.',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Не о чем нам говорить, $gмалыш:малышка;.',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Не говори со мной на своем грубом языке! Его вытерпит только Гидраксис.',`text2_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text2_0_loc8`) VALUES (6162,'Здравствуй, $gмалыш:малышка;. У тебя есть дело к Повелителям Вод?','Наши враги – твои враги. Я с радостью разделю с тобой воду.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здравствуй, $gмалыш:малышка;. У тебя есть дело к Повелителям Вод?',`text0_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Наши враги – твои враги. Я с радостью разделю с тобой воду.',`text2_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text1_0_loc8`,`text2_0_loc8`) VALUES (6163,'Наш господин Гидраксис высокого о тебе мнения. Моя вода – твоя вода.','Когда в следующий раз отправишься в Огненные Недра, убей там повелителя огня. Ради меня, ладно?') ON DUPLICATE KEY UPDATE `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Наш господин Гидраксис высокого о тебе мнения. Моя вода – твоя вода.',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Когда в следующий раз отправишься в Огненные Недра, убей там повелителя огня. Ради меня, ладно?',`text2_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (6164,'Не думаю, что ты захочешь учиться у меня. Пусть лучше тебе помогает |3-6($c).','Не думаю, что ты захочешь учиться у меня. Пусть лучше тебе помогает |3-6($c).') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не думаю, что ты захочешь учиться у меня. Пусть лучше тебе помогает |3-6($c).',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Не думаю, что ты захочешь учиться у меня. Пусть лучше тебе помогает |3-6($c).',`text0_1_loc8`);
