INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (6165,'Глядя на тебя, мне хочется спрятать кошелек подальше. Чем могу помочь?','Глядя на тебя, мне хочется спрятать кошелек подальше. Чем могу помочь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Глядя на тебя, мне хочется спрятать кошелек подальше. Чем могу помочь?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Глядя на тебя, мне хочется спрятать кошелек подальше. Чем могу помочь?',`text0_1_loc8`);
