INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6167,'Нужно вернуть Всевидящее око!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Нужно вернуть Всевидящее око!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (6174,'Мою руку направляет вера, |3-6($r). Я знаю, Айвус придет.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мою руку направляет вера, |3-6($r). Я знаю, Айвус придет.',`text0_1_loc8`);
