INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6236,'Кладбище Грозовой Вершины лежит в горах, за мостом восточнее Дун Болдара.$B$BСейчас оно под контролем Альянса.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Кладбище Грозовой Вершины лежит в горах, за мостом восточнее Дун Болдара.$B$BСейчас оно под контролем Альянса.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6242,'Кладбище Северного Волка находится у дороги, к северу от одноименной деревни.$B$BСейчас оно под контролем Орды.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Кладбище Северного Волка находится у дороги, к северу от одноименной деревни.$B$BСейчас оно под контролем Орды.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`) VALUES (6250,'С праздником Зимнего Покрова, э-э… $gмалыш:малышка;. У всех торговцев Дымного Леса сейчас, э-э… скидки для хороших детей, да!','Есть у меня одна мыслишка о том, как Дедушка Зима сегодня будет отдыхать… Я припас бутылочку "Зимнего Покрова" – и я намерен высосать ее до самого донышка.','Нет… У меня на коленях сидеть нельзя.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','С праздником Зимнего Покрова, э-э… $gмалыш:малышка;. У всех торговцев Дымного Леса сейчас, э-э… скидки для хороших детей, да!',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Есть у меня одна мыслишка о том, как Дедушка Зима сегодня будет отдыхать… Я припас бутылочку "Зимнего Покрова" – и я намерен высосать ее до самого донышка.',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Нет… У меня на коленях сидеть нельзя.',`text2_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6255,'Голодный солдат – плохой солдат. Чтобы одержать победу, необходимо обеспечить армию едой и припасами.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Голодный солдат – плохой солдат. Чтобы одержать победу, необходимо обеспечить армию едой и припасами.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6257,'Кое-кто говорит, что для успеха армии важнее всего сила и храбрость. И это так! Но армии нужны еще и припасы, чтобы солдаты были в хорошей форме. Моя обязанность – следить за тем, чтобы припасов всегда хватало.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Кое-кто говорит, что для успеха армии важнее всего сила и храбрость. И это так! Но армии нужны еще и припасы, чтобы солдаты были в хорошей форме. Моя обязанность – следить за тем, чтобы припасов всегда хватало.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (6273,'Приветствую тебя, боец. Ты хочешь нам помочь?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Приветствую тебя, боец. Ты хочешь нам помочь?',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
