INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6277,'Чему тебя обучить?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Чему тебя обучить?',`text0_0_loc8`);
