INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6279,'Я почту за честь обучить тебя владению оружием… если, конечно, у тебя хватит упорства доучиться до конца.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я почту за честь обучить тебя владению оружием… если, конечно, у тебя хватит упорства доучиться до конца.',`text0_0_loc8`);
