INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6281,'Если хочешь учиться дальше, я с радостью порекомендую тебе наставников. Какое оружие ты предпочитаешь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если хочешь учиться дальше, я с радостью порекомендую тебе наставников. Какое оружие ты предпочитаешь?',`text0_0_loc8`);
