INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6282,'Смерть Грозовой Вершине!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Смерть Грозовой Вершине!',`text0_0_loc8`);
