INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6286,'Ты хочешь научиться владеть новым оружием? Ну так поторопись, у меня мало времени!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты хочешь научиться владеть новым оружием? Ну так поторопись, у меня мало времени!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6287,'Скажите мне, что вас интересует, и я скажу, куда вам надо пойти.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Скажите мне, что вас интересует, и я скажу, куда вам надо пойти.',`text0_0_loc8`);
