INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (6295,'Ну, привет! Хочешь освоить новое оружие?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ну, привет! Хочешь освоить новое оружие?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (6296,'Хм, не хочешь у меня поучиться? Какое же оружие тебя тогда интересует?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Хм, не хочешь у меня поучиться? Какое же оружие тебя тогда интересует?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6313,'Смерть Северному Волку!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Смерть Северному Волку!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6315,'Я жду приказа от командира!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я жду приказа от командира!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (6317,'Еще немного, и в наших стойлах не протолкнуться будет от верховых животных. И все же можешь спокойно доверить своего скакуна мне, боец. Я им сама займусь.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Еще немного, и в наших стойлах не протолкнуться будет от верховых животных. И все же можешь спокойно доверить своего скакуна мне, боец. Я им сама займусь.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (6335,'Я и мои сестры спустились с Когтистых гор, чтобы покончить с давним несчастьем. Увы, мы не настолько сильны, чтобы справиться самим, и потому ищем себе в помощь смертных вроде тебя.$B$BЕсли у тебя хватает сил, то мы, |3-6($c), можем многое обсудить. Если же нет, то, ради твоей же безопасности, я не стану разглашать здесь подробности моей миссии.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я и мои сестры спустились с Когтистых гор, чтобы покончить с давним несчастьем. Увы, мы не настолько сильны, чтобы справиться самим, и потому ищем себе в помощь смертных вроде тебя.$B$BЕсли у тебя хватает сил, то мы, |3-6($c), можем многое обсудить. Если же нет, то, ради твоей же безопасности, я не стану разглашать здесь подробности моей миссии.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6336,'Приветствую тебя, |3-6($r).') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приветствую тебя, |3-6($r).',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6353,'Мне не нужен дом, чтобы знать, что у меня есть место в этом мире, |3-6($c). Племена увидят… все увидят. Они сражаются друг с другом, и за что? За жалкие остатки пищи, оставленные стервятниками… За земли, кишащие приспешниками Легиона… пфа!$B$BКентавры должны гордиться своим наследием – оно такое же благородное, как у любого ночного эльфа или орка, – пришло время понять это!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мне не нужен дом, чтобы знать, что у меня есть место в этом мире, |3-6($c). Племена увидят… все увидят. Они сражаются друг с другом, и за что? За жалкие остатки пищи, оставленные стервятниками… За земли, кишащие приспешниками Легиона… пфа!$B$BКентавры должны гордиться своим наследием – оно такое же благородное, как у любого ночного эльфа или орка, – пришло время понять это!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6354,'Наконец-то я свободен от заклятья, приковавшего меня к этому месту…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Наконец-то я свободен от заклятья, приковавшего меня к этому месту…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6377,'Между цветами путь.$B$BСветится он на воде.$B$BТой, что тобой создана.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Между цветами путь.$B$BСветится он на воде.$B$BТой, что тобой создана.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6378,'Между оранжевым и лиловым проходами, что рядом с дверьми в Мародон, ты найдешь третий путь.$B$BКлюч к нему – скипетр, который ты держишь в руках.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Между оранжевым и лиловым проходами, что рядом с дверьми в Мародон, ты найдешь третий путь.$B$BКлюч к нему – скипетр, который ты держишь в руках.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6379,'Я устал…$B$BОтсюда ты можешь видеть водопады, $n… Скипетр вернет тебя на это самое место, если вдруг захочешь снова пройти через врата Мародона.$B$BВозле входа в Мародон есть путь, уходящий вниз. Чтобы создать портал для возвращения, воздействуй скипетром на место проведения ритуала.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я устал…$B$BОтсюда ты можешь видеть водопады, $n… Скипетр вернет тебя на это самое место, если вдруг захочешь снова пройти через врата Мародона.$B$BВозле входа в Мародон есть путь, уходящий вниз. Чтобы создать портал для возвращения, воздействуй скипетром на место проведения ритуала.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6384,'Когда яд Мародона начал проникать в мой разум, я стал терять связь с реальностью. Взволнованные тем, что это может быть использовано во зло, мои сестры-дриады тайно забрали у меня скипетр, разбили его на две части и спрятали в этих пещерах.$B$BВскоре они тоже пали жертвами этого безумия, и обе части скипетра попали в руки Злоязыкого. Сатир передал одну часть Ноксиону, злому элементалю, а другую все еще хранит у себя.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Когда яд Мародона начал проникать в мой разум, я стал терять связь с реальностью. Взволнованные тем, что это может быть использовано во зло, мои сестры-дриады тайно забрали у меня скипетр, разбили его на две части и спрятали в этих пещерах.$B$BВскоре они тоже пали жертвами этого безумия, и обе части скипетра попали в руки Злоязыкого. Сатир передал одну часть Ноксиону, злому элементалю, а другую все еще хранит у себя.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6385,'Не зная о чарах, которые объединили бы две части в одно целое, лорд Злоязыкий не смог воспользоваться скипетром. Теперь же, когда я избавлен от проклятья Злоязыкого, я могу тебе помочь. Но ты $gдолжен:должна; принести мне обе части скипетра – навершие и рукоять.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не зная о чарах, которые объединили бы две части в одно целое, лорд Злоязыкий не смог воспользоваться скипетром. Теперь же, когда я избавлен от проклятья Злоязыкого, я могу тебе помочь. Но ты $gдолжен:должна; принести мне обе части скипетра – навершие и рукоять.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6393,'Ты спрашиваешь о сыновьях Кенария – Ремуле и Зейтаре.$B$BМой отец Ремул был красив и силен, а мой дядя Зейтар – ловок и строен. Оба они пользовались равным уважением, но Зейтар всегда опасался, что ему не видать той славы и почета, которые, как он думал, есть у Ремула.$B$BКогда я и мои сестры появились на свет, Зейтар, ослепленный ревностью, восстал против брата… Он сам приблизил свою гибель. Сколько бы времени ни прошло, я так и не могу с этим смириться…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты спрашиваешь о сыновьях Кенария – Ремуле и Зейтаре.$B$BМой отец Ремул был красив и силен, а мой дядя Зейтар – ловок и строен. Оба они пользовались равным уважением, но Зейтар всегда опасался, что ему не видать той славы и почета, которые, как он думал, есть у Ремула.$B$BКогда я и мои сестры появились на свет, Зейтар, ослепленный ревностью, восстал против брата… Он сам приблизил свою гибель. Сколько бы времени ни прошло, я так и не могу с этим смириться…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6475,'Я отвечаю за вербовку новобранцев в клан Северного Волка. Будучи бойцом клана, ты $gдолжен:должна; докладывать мне о каждом своем повышении в звании.$B$BНа этих мерзлых полях тебя ждут честь и слава!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я отвечаю за вербовку новобранцев в клан Северного Волка. Будучи бойцом клана, ты $gдолжен:должна; докладывать мне о каждом своем повышении в звании.$B$BНа этих мерзлых полях тебя ждут честь и слава!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6476,'Здравствуй, |3-6($r)! Я лейтенант Хаггердин, отвечаю за вербовку новобранцев в Стражу Грозовой Вершины.$B$BКогда ты станешь достаточно $gизвестен:известна; и $gуважаем:уважаема; в наших рядах, возвращайся ко мне, и я, может статься, повышу тебя в звании. А если тебе случиться потерять знаки различия, я выдам тебе новые.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здравствуй, |3-6($r)! Я лейтенант Хаггердин, отвечаю за вербовку новобранцев в Стражу Грозовой Вершины.$B$BКогда ты станешь достаточно $gизвестен:известна; и $gуважаем:уважаема; в наших рядах, возвращайся ко мне, и я, может статься, повышу тебя в звании. А если тебе случиться потерять знаки различия, я выдам тебе новые.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6513,'Предки учили нас, что один в поле не воин – каким бы сильным он ни был. Хочешь ли ты прославить Громовой Утес, создав гильдию?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Предки учили нас, что один в поле не воин – каким бы сильным он ни был. Хочешь ли ты прославить Громовой Утес, создав гильдию?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6533,'Рад встрече, |3-6($c). Я Рокаро.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Рад встрече, |3-6($c). Я Рокаро.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (6534,'Почему ты интересуешься Синими драконами?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Почему ты интересуешься Синими драконами?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (6557,'Привет. Нет, Марвона здесь нет и еще некоторое время не будет. На самом деле я немного беспокоюсь за него… $B$BНадеюсь, он скоро вернется. Ему привезли большой сундук – такой тяжелый, что я не смогла затащить его внутрь. Так и пришлось оставить у дверей…') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Привет. Нет, Марвона здесь нет и еще некоторое время не будет. На самом деле я немного беспокоюсь за него… $B$BНадеюсь, он скоро вернется. Ему привезли большой сундук – такой тяжелый, что я не смогла затащить его внутрь. Так и пришлось оставить у дверей…',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (6574,'Это место… проклято.$B$BЯ едва сумела убежать – и теперь даже думать не хочу о том, чтобы снова спуститься в эти тоннели.$B$BА вот мои братья и сестры… им не повезло. Они заперты внутри и окутаны зловещей дымкой, которая стелется из этого сада зла.$B$BПрошу тебя, помоги им.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Это место… проклято.$B$BЯ едва сумела убежать – и теперь даже думать не хочу о том, чтобы снова спуститься в эти тоннели.$B$BА вот мои братья и сестры… им не повезло. Они заперты внутри и окутаны зловещей дымкой, которая стелется из этого сада зла.$B$BПрошу тебя, помоги им.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (6594,'Припасы нужны?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Припасы нужны?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6654,'Ты хочешь учиться военному ремеслу, |3-6($r)? Ты $gпришел:пришла; не по адресу.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты хочешь учиться военному ремеслу, |3-6($r)? Ты $gпришел:пришла; не по адресу.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6655,'Ты хочешь узнать о битвах, выигранных и проигранных на этом поле? Здесь не бывает победителей...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты хочешь узнать о битвах, выигранных и проигранных на этом поле? Здесь не бывает победителей...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`) VALUES (6657,'Поторапливайтесь, солдаты! Разведка Грозовой Вершины сообщила, что тролли из племени Ледяной Секиры захватили гоблинского инженера. Эти псы, называющие себя Северными Волками, активно пытаются освободить его, чтобы использовать его инженерские приспособления и уничтожить нас! Не дайте этому произойти.','Говорят, что в пещерах на восточном плато видели агентов Синдиката. Узнай, что им нужно! И берегись бойцов Северного Волка!','Остерегайся заходить на земли Северного Волка, солдат. Все это проклятое место в ловушках! Полным-полно мин! Поговори с нашим экспертом по взрывам в первой башне на линии фронта, он тебе еще больше расскажет. Я уверен, он сможет научить тебя, как разрядить обстановку.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Поторапливайтесь, солдаты! Разведка Грозовой Вершины сообщила, что тролли из племени Ледяной Секиры захватили гоблинского инженера. Эти псы, называющие себя Северными Волками, активно пытаются освободить его, чтобы использовать его инженерские приспособления и уничтожить нас! Не дайте этому произойти.',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Говорят, что в пещерах на восточном плато видели агентов Синдиката. Узнай, что им нужно! И берегись бойцов Северного Волка!',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Остерегайся заходить на земли Северного Волка, солдат. Все это проклятое место в ловушках! Полным-полно мин! Поговори с нашим экспертом по взрывам в первой башне на линии фронта, он тебе еще больше расскажет. Я уверен, он сможет научить тебя, как разрядить обстановку.',`text2_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6658,'Тогда слушай внимательно, |3-6($c).$B$BТы чувствуешь силу, исходящую от меня? Твой боевой дух крепнет? Так вот, на той стороне все точно так же. Прорвать их оборону и отбросить их войска будет нелегко, но это нужно сделать! Победа будет за нами!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тогда слушай внимательно, |3-6($c).$B$BТы чувствуешь силу, исходящую от меня? Твой боевой дух крепнет? Так вот, на той стороне все точно так же. Прорвать их оборону и отбросить их войска будет нелегко, но это нужно сделать! Победа будет за нами!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6659,'Первой линией обороны командуют шесть лейтенантов. Их нужно убить в первую очередь, и как можно быстрее! Нельзя допустить, чтобы их воскресили жрецы противника.$B$BЕсли все лейтенанты быстро погибнут, боевой дух противника упадет. Передовые отряды обратятся в бегство, оставив основные силы противника без прикрытия.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Первой линией обороны командуют шесть лейтенантов. Их нужно убить в первую очередь, и как можно быстрее! Нельзя допустить, чтобы их воскресили жрецы противника.$B$BЕсли все лейтенанты быстро погибнут, боевой дух противника упадет. Передовые отряды обратятся в бегство, оставив основные силы противника без прикрытия.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6694,'Беспомощен… Бессилен… Восстановить… Надо восстановить… Власть Зеврима… Прекратить эту пытку…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Беспомощен… Бессилен… Восстановить… Надо восстановить… Власть Зеврима… Прекратить эту пытку…',`text0_0_loc8`);
