INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6695,'Благодарю тебя, $gсмертный:смертная;. Я могу оказать тебе еще одну услугу, перед тем как вернуться в Сон.$B$BДверь, ведущая к хозяину Зеврима, Алззину, преграждает твой путь. Я собираюсь послужить в качестве твоего инструмента уничтожения. Дверь будет открыта, как только ты прикажешь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Благодарю тебя, $gсмертный:смертная;. Я могу оказать тебе еще одну услугу, перед тем как вернуться в Сон.$B$BДверь, ведущая к хозяину Зеврима, Алззину, преграждает твой путь. Я собираюсь послужить в качестве твоего инструмента уничтожения. Дверь будет открыта, как только ты прикажешь.',`text0_0_loc8`);
