INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6714,'Кладбище Каменного Очага расположено на Поле брани, к востоку от форта Каменного Очага.$B$BСейчас оно под контролем Альянса.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Кладбище Каменного Очага расположено на Поле брани, к востоку от форта Каменного Очага.$B$BСейчас оно под контролем Альянса.',`text0_0_loc8`);
