INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6718,'У нас уже много припасов, но их по-прежнему недостаточно для наступления на Поле брани.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','У нас уже много припасов, но их по-прежнему недостаточно для наступления на Поле брани.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6720,'Припасы у нас есть, но их слишком мало. Для полноценного наступления на Поле брани их надо гораздо больше.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Припасы у нас есть, но их слишком мало. Для полноценного наступления на Поле брани их надо гораздо больше.',`text0_0_loc8`);
