INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6721,'Припасов у нас совсем мало. Чтобы начать наступление на Поле брани, их нужно намного больше!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Припасов у нас совсем мало. Чтобы начать наступление на Поле брани, их нужно намного больше!',`text0_0_loc8`);
