INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6731,'Многих припасов у нас в избытке, однако нужно собрать гораздо больше, чтобы отослать помощь на Поле брани.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Многих припасов у нас в избытке, однако нужно собрать гораздо больше, чтобы отослать помощь на Поле брани.',`text0_0_loc8`);
