INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6796,'В Альтераке есть два рудника: Железный рудник на территории Альянса и рудник Ледяного Зуба на территории Орды. Оба они достаточно богаты; к тому же раньше на них хранили излишки припасов.$B$BТеперь за эти рудники постоянно сражаются Альянс, Орда и местные жители.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','В Альтераке есть два рудника: Железный рудник на территории Альянса и рудник Ледяного Зуба на территории Орды. Оба они достаточно богаты; к тому же раньше на них хранили излишки припасов.$B$BТеперь за эти рудники постоянно сражаются Альянс, Орда и местные жители.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6797,'Башни и укрытия Альтеракской долины – жизненно важные стратегические объекты. Если мы захватим башню, наши бойцы смогут стрелять с нее на большее расстояние.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Башни и укрытия Альтеракской долины – жизненно важные стратегические объекты. Если мы захватим башню, наши бойцы смогут стрелять с нее на большее расстояние.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
