INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6829,'Восточная Смотровая башня защищает проход между Полем брани и землями Орды на юге.$B$BСейчас она под контролем Орды.$B$BВосточная башня Северного Волка защищает проход между деревней и крепостью Северного Волка.$B$BСейчас она под контролем Орды.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Восточная Смотровая башня защищает проход между Полем брани и землями Орды на юге.$B$BСейчас она под контролем Орды.$B$BВосточная башня Северного Волка защищает проход между деревней и крепостью Северного Волка.$B$BСейчас она под контролем Орды.',`text0_0_loc8`);
