INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6842,'Я знаю многое. Слушай и запоминай, |3-6($r).') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я знаю многое. Слушай и запоминай, |3-6($r).',`text0_0_loc8`);
