INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6846,'На поле боя прибыли командиры Орды и Альянса. Наш капитан Балинда Каменный Очаг командует войсками Грозовой Вершины из форта Каменного Очага, а вражеский капитан Гальвангар отдает приказания из гарнизона Стылой Крови.$B$BК бою!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','На поле боя прибыли командиры Орды и Альянса. Наш капитан Балинда Каменный Очаг командует войсками Грозовой Вершины из форта Каменного Очага, а вражеский капитан Гальвангар отдает приказания из гарнизона Стылой Крови.$B$BК бою!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6848,'На поле боя прибыли командиры Орды и Альянса. Наш капитан Гальвангар отдает приказания из гарнизона Стылой Крови, а вражеский капитан Балинда Каменный Очаг командует войсками Грозовой Вершины из форта Каменного Очага.$B$BК бою!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','На поле боя прибыли командиры Орды и Альянса. Наш капитан Гальвангар отдает приказания из гарнизона Стылой Крови, а вражеский капитан Балинда Каменный Очаг командует войсками Грозовой Вершины из форта Каменного Очага.$B$BК бою!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6851,'Капитан Гальванар убит! Почтите его память, разгромите силы Альянса!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Капитан Гальванар убит! Почтите его память, разгромите силы Альянса!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6853,'Клан Северного Волка живет в Альтеракской долине уже много лет. Дворфам с их Альянсом здесь не место! Битве – быть!$B$BЧтобы отвоевать Альтерак, надо сокрушить вражеского генерала Вандара Грозовую Вершину из Дун Болдара.$B$BЗа Орду!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Клан Северного Волка живет в Альтеракской долине уже много лет. Дворфам с их Альянсом здесь не место! Битве – быть!$B$BЧтобы отвоевать Альтерак, надо сокрушить вражеского генерала Вандара Грозовую Вершину из Дун Болдара.$B$BЗа Орду!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6854,'Дворфы Грозовой Вершины отправились в Альтеракскую долину за древними артефактами, но орки клана Северного Волка встретили их войной. Что ж, если наши исследователи вынуждены сражаться за наследие предков, значит, так тому и быть!$B$BЧтобы выиграть эту битву, нужно победить орка Дрек\'Тара из крепости Северного Волка. Пусть тебе сопутствует удача, |3-6($c)!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Дворфы Грозовой Вершины отправились в Альтеракскую долину за древними артефактами, но орки клана Северного Волка встретили их войной. Что ж, если наши исследователи вынуждены сражаться за наследие предков, значит, так тому и быть!$B$BЧтобы выиграть эту битву, нужно победить орка Дрек\'Тара из крепости Северного Волка. Пусть тебе сопутствует удача, |3-6($c)!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6859,'Капитан Балинда Каменный Очаг возглавляет силы Альянса на линии фронта. Она находится в форте Каменного Очага, в северной части Поля брани.$B$BБелинда и сейчас внутри форта.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Капитан Балинда Каменный Очаг возглавляет силы Альянса на линии фронта. Она находится в форте Каменного Очага, в северной части Поля брани.$B$BБелинда и сейчас внутри форта.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6861,'Дрек\'Тар – военный и духовный лидер клана Северного Волка в Альтераке. Он направляет своих братьев из крепости Северного Волка.$B$BЕго гибель приведет к окончательному поражению Орды в Альтераке.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Дрек\'Тар – военный и духовный лидер клана Северного Волка в Альтераке. Он направляет своих братьев из крепости Северного Волка.$B$BЕго гибель приведет к окончательному поражению Орды в Альтераке.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6863,'Капитан Гальвангар – верный помощник Дрек\'Тара. Он командует армией Орды из гарнизона Стылой Крови, что в южной части Поля брани.$B$BСейчас капитан Гальвангар находится в гарнизоне.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Капитан Гальвангар – верный помощник Дрек\'Тара. Он командует армией Орды из гарнизона Стылой Крови, что в южной части Поля брани.$B$BСейчас капитан Гальвангар находится в гарнизоне.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6865,'Вандар Грозовая Вершина – главнокомандующий силами Альянса в Альтераке. Он руководит своей армией из Дун Болдара.$B$BВ случае его гибели Альянс обречен на поражение в битве за Альтерак.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вандар Грозовая Вершина – главнокомандующий силами Альянса в Альтераке. Он руководит своей армией из Дун Болдара.$B$BВ случае его гибели Альянс обречен на поражение в битве за Альтерак.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6868,'Рагнарос, Геддон и Гарр – вот кто виновен в заговоре против моего повелителя. Громораана застали врасплох.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Рагнарос, Геддон и Гарр – вот кто виновен в заговоре против моего повелителя. Громораана застали врасплох.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6870,'То немногое, что осталось от сущности Громораана, было помещено в талисман Стихийных оков. Затем Рагнарос расколол этот талисман на две равные части и отдал их своим ближайшим приспешникам…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','То немногое, что осталось от сущности Громораана, было помещено в талисман Стихийных оков. Затем Рагнарос расколол этот талисман на две равные части и отдал их своим ближайшим приспешникам…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6873,'Крепость Северного Волка находится в южной части Альтеракской долины. Она защищает деревню орочьего клана Северного Волка и является главным оплотом Орды в долине.$B$BСейчас крепость Северного Волка не повреждена.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Крепость Северного Волка находится в южной части Альтеракской долины. Она защищает деревню орочьего клана Северного Волка и является главным оплотом Орды в долине.$B$BСейчас крепость Северного Волка не повреждена.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6875,'Ты $gнашел:нашла; ключ? ТОТ САМЫЙ ключ? То есть он открывает эти оковы? Ну, $Gгосподин:госпожа;, сейчас мы это проверим!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты $gнашел:нашла; ключ? ТОТ САМЫЙ ключ? То есть он открывает эти оковы? Ну, $Gгосподин:госпожа;, сейчас мы это проверим!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6877,'Хочешь поиграть, вонючка?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Хочешь поиграть, вонючка?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6878,'Храню я ключ к земле свободной! Ступай за мной, и ты увидишь!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Храню я ключ к земле свободной! Ступай за мной, и ты увидишь!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6879,'Все еще живы? Вы меня удивляете. Смотрите, как я бегу!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Все еще живы? Вы меня удивляете. Смотрите, как я бегу!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6880,'Повеселее лицо сделай!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Повеселее лицо сделай!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6881,'Все, кончен бал, погасли свечи!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Все, кончен бал, погасли свечи!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6882,'А, ты убить король? Значит, занимать его место. Будешь новый хозяин! Да здравствует король!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','А, ты убить король? Значит, занимать его место. Будешь новый хозяин! Да здравствует король!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6883,'Ну, я тут кое-то слышал, пока они меня жрать готовились… Может, и не стоит каждого встречного огра убивать.$B$BОгры все судачили о том, как король Гордок к власти пришел. Говорят, он просто прибил прежнего короля и взял клятву верности с его уцелевших сторонников.$B$BКто знает – спасенный тобой огр может оказаться твоим… в переносном, конечно, смысле!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ну, я тут кое-то слышал, пока они меня жрать готовились… Может, и не стоит каждого встречного огра убивать.$B$BОгры все судачили о том, как король Гордок к власти пришел. Говорят, он просто прибил прежнего короля и взял клятву верности с его уцелевших сторонников.$B$BКто знает – спасенный тобой огр может оказаться твоим… в переносном, конечно, смысле!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6894,'Твоя теперь главный, да? Слава $gкоролю:королеве;!$B$BКриг показать тебе пойло Гордока. Пойло огров – лучшее пойло, пойло Гордока – лучшее пойло огров! Может, купить чуток у меня, хозяин?!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Твоя теперь главный, да? Слава $gкоролю:королеве;!$B$BКриг показать тебе пойло Гордока. Пойло огров – лучшее пойло, пойло Гордока – лучшее пойло огров! Может, купить чуток у меня, хозяин?!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6895,'Хорошо, хозяин, когда понадобится помощь – дайте знать!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Хорошо, хозяин, когда понадобится помощь – дайте знать!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (6896,'Покинь это место, $gнезнакомец:незнакомка;, пока оно не поглотило тебя, как все, к чему оно прикасается.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Покинь это место, $gнезнакомец:незнакомка;, пока оно не поглотило тебя, как все, к чему оно прикасается.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (6897,'Ты знаешь о высокорожденных? О Шен\'дралар?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты знаешь о высокорожденных? О Шен\'дралар?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (6899,'Принц собирался пленить невероятно могущественного демона Бессмер\'тера и заключить его в мощное силовое поле. Для направления и поддержки этого поля и были созданы пилоны.$B$BОжидалось, что Бессмер\'тер будет снабжать энергией население Эльдре\'Таласа.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Принц собирался пленить невероятно могущественного демона Бессмер\'тера и заключить его в мощное силовое поле. Для направления и поддержки этого поля и были созданы пилоны.$B$BОжидалось, что Бессмер\'тер будет снабжать энергией население Эльдре\'Таласа.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (6900,'Сила демона поддерживала высокорожденных, позволяя жителям Эльдре\'Таласа утолять свою неизбывную жажду магии.$B$BНо прошли тысячелетия, и эта сила начала угасать. Расход энергии на сдерживание Бессмер\'тера превысил скорость ее поступления. Прибыль обернулась убытком.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Сила демона поддерживала высокорожденных, позволяя жителям Эльдре\'Таласа утолять свою неизбывную жажду магии.$B$BНо прошли тысячелетия, и эта сила начала угасать. Расход энергии на сдерживание Бессмер\'тера превысил скорость ее поступления. Прибыль обернулась убытком.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (6901,'Призраки высокорожденных, бродившие по внутреннему двору и залам Эльдре\'Талас убиты, и уничтожили их не огры Гордока и не сатиры, а сам принц!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Призраки высокорожденных, бродившие по внутреннему двору и залам Эльдре\'Талас убиты, и уничтожили их не огры Гордока и не сатиры, а сам принц!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (6902,'Ради сохранения бессмертия и могущества принца был истреблен весь народ. Сила, некогда поделенная между тысячами обладателей, теперь питает лишь принца и Шен\'драларских ревнителей – и практически без остатка уходит в пилоны, которые удерживают Бессмер\'тера в плену.$B$BСлучись демону вырваться из этих уз, он непременно уничтожит то, что осталось от некогда великого оплота тайной магии.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ради сохранения бессмертия и могущества принца был истреблен весь народ. Сила, некогда поделенная между тысячами обладателей, теперь питает лишь принца и Шен\'драларских ревнителей – и практически без остатка уходит в пилоны, которые удерживают Бессмер\'тера в плену.$B$BСлучись демону вырваться из этих уз, он непременно уничтожит то, что осталось от некогда великого оплота тайной магии.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6903,'Ну, ты теперь круче всех!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ну, ты теперь круче всех!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6904,'Фенгус наполнит тебя яростью! Безумием! АРРР!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Фенгус наполнит тебя яростью! Безумием! АРРР!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6907,'Ты король Гордока! Ты лучше всех!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты король Гордока! Ты лучше всех!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6908,'Я слышал, что ты $gмертв:мертва;… ну, теперь-то умертвить тебя будет непросто!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я слышал, что ты $gмертв:мертва;… ну, теперь-то умертвить тебя будет непросто!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6909,'Я правил этим королевством 10 000 лет. За это время услышал немало удивительных историй от тех, кто странствовал по священным землям Дома Шен\'дралар.$B$BЯ не могу покинуть это место, поэтому люблю обмениваться историями с гостями. У вас есть что рассказать мне, или вы хотите сами что-нибудь послушать?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я правил этим королевством 10 000 лет. За это время услышал немало удивительных историй от тех, кто странствовал по священным землям Дома Шен\'дралар.$B$BЯ не могу покинуть это место, поэтому люблю обмениваться историями с гостями. У вас есть что рассказать мне, или вы хотите сами что-нибудь послушать?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`,`text2_0_loc8`,`text2_1_loc8`,`text3_0_loc8`,`text3_1_loc8`,`text4_0_loc8`,`text4_1_loc8`,`text5_0_loc8`,`text5_1_loc8`,`text6_0_loc8`,`text6_1_loc8`,`text7_0_loc8`,`text7_1_loc8`) VALUES (6911,'Нельзя злить господина. В гневе он жесток без меры.','Нельзя злить господина. В гневе он жесток без меры.','Говори потише, $gстранник:странница;. Не стоит прерывать медитацию Мастера.','Говори потише, $gстранник:странница;. Не стоит прерывать медитацию Мастера.','Многие вошли в это святилище, но немногие из него вышли.','Многие вошли в это святилище, но немногие из него вышли.','Хранитель мудрости очень стар. Он еще помнит нашу славную королеву!','Хранитель мудрости очень стар. Он еще помнит нашу славную королеву!','С недавних пор стали пропадать книги. Хранитель мудрости и его помощники обеспокоены. Они подозревают, что в Эльдре\'Таласе завелись лазутчики.','С недавних пор стали пропадать книги. Хранитель мудрости и его помощники обеспокоены. Они подозревают, что в Эльдре\'Таласе завелись лазутчики.','Принц отказался рассказать об Испепелителе? Эту его историю мы любим больше всего. А ему самому больше нравится ее продолжение. Но, разумеется, он его никому не рассказывает.','Принц отказался рассказать об Испепелителе? Эту его историю мы любим больше всего. А ему самому больше нравится ее продолжение. Но, разумеется, он его никому не рассказывает.','Подозреваю, что бесы крадут знания.','Подозреваю, что бесы крадут знания.','Мой господин очень интересуется логовом Нефариана. Вот если бы кто-нибудь победил дракона и его прихвостней, а затем рассказал принцу историю об этом… После этого принц точно заговорит. Испепелитель можно найти!','Мой господин очень интересуется логовом Нефариана. Вот если бы кто-нибудь победил дракона и его прихвостней, а затем рассказал принцу историю об этом… После этого принц точно заговорит. Испепелитель можно найти!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Нельзя злить господина. В гневе он жесток без меры.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Нельзя злить господина. В гневе он жесток без меры.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Говори потише, $gстранник:странница;. Не стоит прерывать медитацию Мастера.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Говори потише, $gстранник:странница;. Не стоит прерывать медитацию Мастера.',`text1_1_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Многие вошли в это святилище, но немногие из него вышли.',`text2_0_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Многие вошли в это святилище, но немногие из него вышли.',`text2_1_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Хранитель мудрости очень стар. Он еще помнит нашу славную королеву!',`text3_0_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','Хранитель мудрости очень стар. Он еще помнит нашу славную королеву!',`text3_1_loc8`), `text4_0_loc8`=IF(`text4_0_loc8` IS NULL OR `text4_0_loc8`='','С недавних пор стали пропадать книги. Хранитель мудрости и его помощники обеспокоены. Они подозревают, что в Эльдре\'Таласе завелись лазутчики.',`text4_0_loc8`), `text4_1_loc8`=IF(`text4_1_loc8` IS NULL OR `text4_1_loc8`='','С недавних пор стали пропадать книги. Хранитель мудрости и его помощники обеспокоены. Они подозревают, что в Эльдре\'Таласе завелись лазутчики.',`text4_1_loc8`), `text5_0_loc8`=IF(`text5_0_loc8` IS NULL OR `text5_0_loc8`='','Принц отказался рассказать об Испепелителе? Эту его историю мы любим больше всего. А ему самому больше нравится ее продолжение. Но, разумеется, он его никому не рассказывает.',`text5_0_loc8`), `text5_1_loc8`=IF(`text5_1_loc8` IS NULL OR `text5_1_loc8`='','Принц отказался рассказать об Испепелителе? Эту его историю мы любим больше всего. А ему самому больше нравится ее продолжение. Но, разумеется, он его никому не рассказывает.',`text5_1_loc8`), `text6_0_loc8`=IF(`text6_0_loc8` IS NULL OR `text6_0_loc8`='','Подозреваю, что бесы крадут знания.',`text6_0_loc8`), `text6_1_loc8`=IF(`text6_1_loc8` IS NULL OR `text6_1_loc8`='','Подозреваю, что бесы крадут знания.',`text6_1_loc8`), `text7_0_loc8`=IF(`text7_0_loc8` IS NULL OR `text7_0_loc8`='','Мой господин очень интересуется логовом Нефариана. Вот если бы кто-нибудь победил дракона и его прихвостней, а затем рассказал принцу историю об этом… После этого принц точно заговорит. Испепелитель можно найти!',`text7_0_loc8`), `text7_1_loc8`=IF(`text7_1_loc8` IS NULL OR `text7_1_loc8`='','Мой господин очень интересуется логовом Нефариана. Вот если бы кто-нибудь победил дракона и его прихвостней, а затем рассказал принцу историю об этом… После этого принц точно заговорит. Испепелитель можно найти!',`text7_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6913,'Ты чего прохлаждаешься? Почему эта шушера еще не в кандалах?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты чего прохлаждаешься? Почему эта шушера еще не в кандалах?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6914,'Ты теперь главный! Слава новому королю Гордока!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты теперь главный! Слава новому королю Гордока!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6915,'Они что же, до сих пор при оружии? Почему им оставили оружие?!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Они что же, до сих пор при оружии? Почему им оставили оружие?!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6916,'Все сторонники командира – Топотуна Крига, все трое стражников, капитан Давигром и Наблюдатель – все несут дань новому командиру. Если ты убьешь этих прихвостней, то они не смогут приносить дань! Каждый, кого ты оставишь в живых, будет приносить тебе еще больше дани. Пощади их всех, и ты получишь МНОГО дани!$B$BДа!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Все сторонники командира – Топотуна Крига, все трое стражников, капитан Давигром и Наблюдатель – все несут дань новому командиру. Если ты убьешь этих прихвостней, то они не смогут приносить дань! Каждый, кого ты оставишь в живых, будет приносить тебе еще больше дани. Пощади их всех, и ты получишь МНОГО дани!$B$BДа!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6918,'Э… Прости, что я драться, хозяин. Твоя не убивать меня, да? Твоя теперь главный, я помогать тебе собрать дань!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Э… Прости, что я драться, хозяин. Твоя не убивать меня, да? Твоя теперь главный, я помогать тебе собрать дань!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6919,'Из беглого осмотра костей видно, что плоть на них сгорела. Довольно жуткое зрелище.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Из беглого осмотра костей видно, что плоть на них сгорела. Довольно жуткое зрелище.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6920,'Может быть, ты сумеешь отобрать реликвию Гордока у этого ужасного высокорожденного. Старый главарь этого не смог!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Может быть, ты сумеешь отобрать реликвию Гордока у этого ужасного высокорожденного. Старый главарь этого не смог!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`,`text4_0_loc8`,`text5_0_loc8`,`text6_0_loc8`,`text7_0_loc8`) VALUES (6922,'Слава новому королю!','Вот перед тем, как ты королем стал, я на тебя волком смотрел… так это… я шутил просто.$B$BДа-да!','Другие-то огры, хозяин, болваны – на тебя напали! А вот я почему жив – умный потому что!','Пока ты с нами, ты король. Уйдешь – твое место займет другой огр. Так принято в Гордоке!','Я такой умный! У-М-Н-Й!','Старый король все? Быть не может!','Я тебе пригожусь, хозяин.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Слава новому королю!',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Вот перед тем, как ты королем стал, я на тебя волком смотрел… так это… я шутил просто.$B$BДа-да!',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Другие-то огры, хозяин, болваны – на тебя напали! А вот я почему жив – умный потому что!',`text2_0_loc8`), `text4_0_loc8`=IF(`text4_0_loc8` IS NULL OR `text4_0_loc8`='','Пока ты с нами, ты король. Уйдешь – твое место займет другой огр. Так принято в Гордоке!',`text4_0_loc8`), `text5_0_loc8`=IF(`text5_0_loc8` IS NULL OR `text5_0_loc8`='','Я такой умный! У-М-Н-Й!',`text5_0_loc8`), `text6_0_loc8`=IF(`text6_0_loc8` IS NULL OR `text6_0_loc8`='','Старый король все? Быть не может!',`text6_0_loc8`), `text7_0_loc8`=IF(`text7_0_loc8` IS NULL OR `text7_0_loc8`='','Я тебе пригожусь, хозяин.',`text7_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6924,'Значит… ты $gпобедил:победила; короля, да? Я знал, что эти типы посадят на трон тебя! Им, болванам, понятен один язык – язык силы.$B$BСудя по всему, чем больше бандитов ты $gоставил:оставила; в живых, тем большую дань будешь получать. Ну что ж, так даже интереснее. Но если ты уйдешь, не надейся, что трон оставят за тобой. Его займет один из этих деревенщин, дело ясное.$B$BДа, и еще… ты не $gнашел:нашла;, часом, мой ключ?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Значит… ты $gпобедил:победила; короля, да? Я знал, что эти типы посадят на трон тебя! Им, болванам, понятен один язык – язык силы.$B$BСудя по всему, чем больше бандитов ты $gоставил:оставила; в живых, тем большую дань будешь получать. Ну что ж, так даже интереснее. Но если ты уйдешь, не надейся, что трон оставят за тобой. Его займет один из этих деревенщин, дело ясное.$B$BДа, и еще… ты не $gнашел:нашла;, часом, мой ключ?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6925,'Прежде всего ты $gдолжен:должна; понять, что знание 10 000 лет всемирной истории изменило мой взгляд на жизнь. Все твои беды и невзгоды – ничто в историческом масштабе.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Прежде всего ты $gдолжен:должна; понять, что знание 10 000 лет всемирной истории изменило мой взгляд на жизнь. Все твои беды и невзгоды – ничто в историческом масштабе.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6926,'Каким же пафосным был мой юный господин… Можно подумать, судьба мира держалась прямо на его плечах! Только у смертных такое искаженное представление о нашем мире.$B$BУвы, мне он оставил лишь малую часть своих секретов… Манускрипты какие-то дурацкие. Мне все это ни к чему, но, может быть, тебе будет интересно.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Каким же пафосным был мой юный господин… Можно подумать, судьба мира держалась прямо на его плечах! Только у смертных такое искаженное представление о нашем мире.$B$BУвы, мне он оставил лишь малую часть своих секретов… Манускрипты какие-то дурацкие. Мне все это ни к чему, но, может быть, тебе будет интересно.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6927,'Их украли, |3-6($r)! Украли три самых ценных тома! Если вернешь нам книги, награда не заставит себя ждать.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Их украли, |3-6($r)! Украли три самых ценных тома! Если вернешь нам книги, награда не заставит себя ждать.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6930,'*На этом пергаменте изображен чертеж полевого ремонтного робота.*') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','*На этом пергаменте изображен чертеж полевого ремонтного робота.*',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6931,'*Ваших познаний в инженерном деле недостаточно, чтобы разобраться в этих сложных чертежах.*') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','*Ваших познаний в инженерном деле недостаточно, чтобы разобраться в этих сложных чертежах.*',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6932,'*Вы отлично разбираетесь в конструкции и функционировании этого робота.*') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','*Вы отлично разбираетесь в конструкции и функционировании этого робота.*',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6933,'Ткань, из которой соткан наш мир, очень тонка. Чтобы разорвать ее, достаточно малой толики знания и умения. Вот так и появляются расщелины.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ткань, из которой соткан наш мир, очень тонка. Чтобы разорвать ее, достаточно малой толики знания и умения. Вот так и появляются расщелины.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6934,'Посмотри на врага повнимательнее, |3-6($r). Видишь, во что мощь Орды превратила могущественнейшего из драконов? Так будет с каждым, кто встанет у нас на пути!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Посмотри на врага повнимательнее, |3-6($r). Видишь, во что мощь Орды превратила могущественнейшего из драконов? Так будет с каждым, кто встанет у нас на пути!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6935,'Я готов выполнить любой приказ Вождя. Я воин Орды.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я готов выполнить любой приказ Вождя. Я воин Орды.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6936,'Я живу, чтобы служить королю.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я живу, чтобы служить королю.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6939,'10 000 лет письменной истории привлекают в Читальню не только мудрецов, но и всякий сброд. Книги крадут, возвращают, крадут снова – и так каждый день.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','10 000 лет письменной истории привлекают в Читальню не только мудрецов, но и всякий сброд. Книги крадут, возвращают, крадут снова – и так каждый день.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6947,'Нет времени на разговоры.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Нет времени на разговоры.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6948,'Могу я быть полезен?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Могу я быть полезен?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6949,'Да, но я знаю его настоящее название – Эльдре\'Талас. Много лет назад это был оплот магической мощи ночных эльфов.$B$BТы знаешь про Эльдре\'Талас, юное создание? Можно сказать, что это простое совпадение… но в совпадения я не верю.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да, но я знаю его настоящее название – Эльдре\'Талас. Много лет назад это был оплот магической мощи ночных эльфов.$B$BТы знаешь про Эльдре\'Талас, юное создание? Можно сказать, что это простое совпадение… но в совпадения я не верю.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6950,'Агенты Круга Кенария передают тревожные сведения из Эльдре\'Таласа. Пока я не знаю, что с этим делать, но не сомневаюсь, что скоро нам понадобится помощь сноровистых бойцов.$B$BЧтобы окончательно прояснить ситуацию в Эльдре\'Таласе, нужно собрать информацию о некоем объекте, именуемом "Плод Изобилия".') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Агенты Круга Кенария передают тревожные сведения из Эльдре\'Таласа. Пока я не знаю, что с этим делать, но не сомневаюсь, что скоро нам понадобится помощь сноровистых бойцов.$B$BЧтобы окончательно прояснить ситуацию в Эльдре\'Таласе, нужно собрать информацию о некоем объекте, именуемом "Плод Изобилия".',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6951,'В давние времена Эльдре\'Талас был средоточием магической силы. Обитатели его священных чертогов обладали поистине немыслимым могуществом! В их число входила и Миллисента Безмятежная – ночная эльфийка, повелевавшая силами Природы.$B$BПлод Изобилия был ее любимым детищем… в специально подготовленном лунном колодце она вырастила яркую и необычную лозу, излучавшую ауру защиты и роста. Эта лоза принесла процветание всему Эльдре\'Таласу.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','В давние времена Эльдре\'Талас был средоточием магической силы. Обитатели его священных чертогов обладали поистине немыслимым могуществом! В их число входила и Миллисента Безмятежная – ночная эльфийка, повелевавшая силами Природы.$B$BПлод Изобилия был ее любимым детищем… в специально подготовленном лунном колодце она вырастила яркую и необычную лозу, излучавшую ауру защиты и роста. Эта лоза принесла процветание всему Эльдре\'Таласу.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6952,'Увы, все мы принимаем желаемое за действительное. Я – как и остальные в Круге Кенария – предполагал, что творение Милли было уничтожено во время Войны древних. Оказывается, это отнюдь не так.$B$BПлод Изобилия сохранился… хотя теперь он зовется сквернитом. Его осквернил демон, повелитель этой части Эльдре\'Таласа, Алззин Перевертень.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Увы, все мы принимаем желаемое за действительное. Я – как и остальные в Круге Кенария – предполагал, что творение Милли было уничтожено во время Войны древних. Оказывается, это отнюдь не так.$B$BПлод Изобилия сохранился… хотя теперь он зовется сквернитом. Его осквернил демон, повелитель этой части Эльдре\'Таласа, Алззин Перевертень.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6954,'*Демитриан падает на колени.*$B$BТы $gнашел:нашла; место вечного плена моего господина!$B$BКак же долго я ждал этого дня – и вот он настал.$B$BГосподина надо освободить!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','*Демитриан падает на колени.*$B$BТы $gнашел:нашла; место вечного плена моего господина!$B$BКак же долго я ждал этого дня – и вот он настал.$B$BГосподина надо освободить!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6955,'Я храню сосуд его возрождения. Когда ты будешь $Gготов:готова; выполнить задание, тебе потребуется укрепить этот сосуд и в конце концов освободить самого Рагнароса!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я храню сосуд его возрождения. Когда ты будешь $Gготов:готова; выполнить задание, тебе потребуется укрепить этот сосуд и в конце концов освободить самого Рагнароса!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6956,'Сосуд Возрождения необходимо укрепить элементием. Мне известен лишь один источник этого минерала: Обитель стихий в самом сердце нашего мира.$B$BГоворят, в мире есть некий демиург, сведущий в этом вопросе. Тебе необходимо найти его!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Сосуд Возрождения необходимо укрепить элементием. Мне известен лишь один источник этого минерала: Обитель стихий в самом сердце нашего мира.$B$BГоворят, в мире есть некий демиург, сведущий в этом вопросе. Тебе необходимо найти его!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6958,'Нужно уничтожить физическое воплощение Рагнароса. Когда его сущность покинет бренные останки, он больше не сможет удерживать Громораана в плену. Сама эта сущность и является ключом…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Нужно уничтожить физическое воплощение Рагнароса. Когда его сущность покинет бренные останки, он больше не сможет удерживать Громораана в плену. Сама эта сущность и является ключом…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
