INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (6974,'В Болотах Синежабрых, что к северу от Гавани Менетилов в Болотине, можно найти немало следов кораблекрушений. Попадаются там и ящики с припасами.','В Болотах Синежабрых, что к северу от Гавани Менетилов в Болотине, можно найти немало следов кораблекрушений. Попадаются там и ящики с припасами.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','В Болотах Синежабрых, что к северу от Гавани Менетилов в Болотине, можно найти немало следов кораблекрушений. Попадаются там и ящики с припасами.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','В Болотах Синежабрых, что к северу от Гавани Менетилов в Болотине, можно найти немало следов кораблекрушений. Попадаются там и ящики с припасами.',`text0_1_loc8`);
