INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (6980,'Орки утопили ящики с припасами в Озере Безмолвия. Это в Красногорье.','Орки утопили ящики с припасами в Озере Безмолвия. Это в Красногорье.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Орки утопили ящики с припасами в Озере Безмолвия. Это в Красногорье.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Орки утопили ящики с припасами в Озере Безмолвия. Это в Красногорье.',`text0_1_loc8`);
