INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (6981,'Когда наги напали на Зорамское взморье в Ясеневом лесу, мы потеряли много ящиков с припасами.','Когда наги напали на Зорамское взморье в Ясеневом лесу, мы потеряли много ящиков с припасами.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Когда наги напали на Зорамское взморье в Ясеневом лесу, мы потеряли много ящиков с припасами.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Когда наги напали на Зорамское взморье в Ясеневом лесу, мы потеряли много ящиков с припасами.',`text0_1_loc8`);
