INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (6982,'Торговая Компания, обосновавшаяся возле Утеса Ветрорезов в Каменном Когте, хранит свои припасы в закрытых ящиках.','Торговая Компания, обосновавшаяся возле Утеса Ветрорезов в Каменном Когте, хранит свои припасы в закрытых ящиках.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Торговая Компания, обосновавшаяся возле Утеса Ветрорезов в Каменном Когте, хранит свои припасы в закрытых ящиках.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Торговая Компания, обосновавшаяся возле Утеса Ветрорезов в Каменном Когте, хранит свои припасы в закрытых ящиках.',`text0_1_loc8`);
