INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (6983,'Синдикат хранит свои ящики с припасами в хилсбрадской крепости Дарнхольд.','Синдикат хранит свои ящики с припасами в хилсбрадской крепости Дарнхольд.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Синдикат хранит свои ящики с припасами в хилсбрадской крепости Дарнхольд.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Синдикат хранит свои ящики с припасами в хилсбрадской крепости Дарнхольд.',`text0_1_loc8`);
