INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6984,'*Демитриан смеется.*$B$BНаградой тебе, тупица, будет быстрая и болезненная смерть!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','*Демитриан смеется.*$B$BНаградой тебе, тупица, будет быстрая и болезненная смерть!',`text0_0_loc8`);
