INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6985,'Я изучаю известные и неизвестные стихии нашего мира.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я изучаю известные и неизвестные стихии нашего мира.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`,`text3_0_loc8`,`text4_0_loc8`,`text5_0_loc8`,`text6_0_loc8`,`text7_0_loc8`) VALUES (6992,'Ты из подземелья, да? $gПринес:Принесла; мне что-нибудь?','Когда я вырасту, я хочу стать королем Штормграда!','Я и раньше бывал в Стальгорне. Там очень странно пахнет.','Грибы всегда растут в сырых местах, и потому похожи на зонты.','Если халаты держатся на застежках сверху, то зачем тогда ремни?','А что будет, если козявки замерзнут в носу?','А рыбы когда-нибудь хотят пить?','Если ты попытался потерпеть поражение и у тебя получилось, то ты выиграл или проиграл?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты из подземелья, да? $gПринес:Принесла; мне что-нибудь?',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Когда я вырасту, я хочу стать королем Штормграда!',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Я и раньше бывал в Стальгорне. Там очень странно пахнет.',`text2_0_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Грибы всегда растут в сырых местах, и потому похожи на зонты.',`text3_0_loc8`), `text4_0_loc8`=IF(`text4_0_loc8` IS NULL OR `text4_0_loc8`='','Если халаты держатся на застежках сверху, то зачем тогда ремни?',`text4_0_loc8`), `text5_0_loc8`=IF(`text5_0_loc8` IS NULL OR `text5_0_loc8`='','А что будет, если козявки замерзнут в носу?',`text5_0_loc8`), `text6_0_loc8`=IF(`text6_0_loc8` IS NULL OR `text6_0_loc8`='','А рыбы когда-нибудь хотят пить?',`text6_0_loc8`), `text7_0_loc8`=IF(`text7_0_loc8` IS NULL OR `text7_0_loc8`='','Если ты попытался потерпеть поражение и у тебя получилось, то ты выиграл или проиграл?',`text7_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`,`text3_0_loc8`,`text4_0_loc8`,`text5_0_loc8`,`text7_0_loc8`) VALUES (6993,'Какая страшная у тебя броня. А ты $gсам страшный:сама страшная;?','Если ты настоящий герой Орды, сразись с драконом! Давай!','А когда в океан бьет молния, почему рыбы не умирают?','Если муху держать за ножки, она не летит. Значит, муха летает ножками?','У меня в носу камешек.','Если у черепахи нет панциря, она бездомная или голая?','А как правильно – "у големов нет проблемов", или "у голем нет проблем"?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Какая страшная у тебя броня. А ты $gсам страшный:сама страшная;?',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Если ты настоящий герой Орды, сразись с драконом! Давай!',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','А когда в океан бьет молния, почему рыбы не умирают?',`text2_0_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Если муху держать за ножки, она не летит. Значит, муха летает ножками?',`text3_0_loc8`), `text4_0_loc8`=IF(`text4_0_loc8` IS NULL OR `text4_0_loc8`='','У меня в носу камешек.',`text4_0_loc8`), `text5_0_loc8`=IF(`text5_0_loc8` IS NULL OR `text5_0_loc8`='','Если у черепахи нет панциря, она бездомная или голая?',`text5_0_loc8`), `text7_0_loc8`=IF(`text7_0_loc8` IS NULL OR `text7_0_loc8`='','А как правильно – "у големов нет проблемов", или "у голем нет проблем"?',`text7_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
