INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6996,'Итак, ты $gнашел:нашла; меня. Полагаю, ты $gпришел:пришла; обучиться выдержке и контролю.$B$BЯ научу тебя гораздо большему… я научу тебя самопожертвованию.$B$B*Дайо ухмыляется.*') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Итак, ты $gнашел:нашла; меня. Полагаю, ты $gпришел:пришла; обучиться выдержке и контролю.$B$BЯ научу тебя гораздо большему… я научу тебя самопожертвованию.$B$B*Дайо ухмыляется.*',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6997,'Ты сможешь выбрать демона, которого хочешь вызвать и поработить. Мы повелеваем темными силами – и платим большую цену за эту власть.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты сможешь выбрать демона, которого хочешь вызвать и поработить. Мы повелеваем темными силами – и платим большую цену за эту власть.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (6998,'Если ты хочешь продолжить дело, нам надо соорудить узилище для зверя.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если ты хочешь продолжить дело, нам надо соорудить узилище для зверя.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7001,'Склонись передо мной, насекомое! Ты $gдолжен:должна; чувствовать мою власть!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Склонись передо мной, насекомое! Ты $gдолжен:должна; чувствовать мою власть!',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7012,'Что ж, это очень мило. Ты, я так понимаю, добровольно участвуешь в Детской неделе, да, |3-6($c)? Ты $gдостоин:достойна; похвалы. Никогда не стоит забывать о тех, кому трудно. Особенно о детях.$B$BС радостью дам тебе автограф. Вот, держи.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Что ж, это очень мило. Ты, я так понимаю, добровольно участвуешь в Детской неделе, да, |3-6($c)? Ты $gдостоин:достойна; похвалы. Никогда не стоит забывать о тех, кому трудно. Особенно о детях.$B$BС радостью дам тебе автограф. Вот, держи.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7013,'Приветствую тебя, о $gюноша:дева;, и добро пожаловать в Громовой Утес. Здесь ты найдешь надежное убежище от бедствий и невзгод. Здесь рады всем, кто принадлежит к Орде.$B$BЗнай: духи прошлого и будущего оживают в этом священном месте. Воздай им должное – и да воздастся тебе.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приветствую тебя, о $gюноша:дева;, и добро пожаловать в Громовой Утес. Здесь ты найдешь надежное убежище от бедствий и невзгод. Здесь рады всем, кто принадлежит к Орде.$B$BЗнай: духи прошлого и будущего оживают в этом священном месте. Воздай им должное – и да воздастся тебе.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7014,'А, молодой воин! Участвуешь в Детской неделе, так? Старику приятно слышать, что ты подаешь другим пример, которому они, несомненно, последуют.$B$BБуду рад принести пользу тебе и парнишке. Хмм... какой же совет ему дать? Слушай волю духов, да... ну и овощи, заодно, кушай, они полезные...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','А, молодой воин! Участвуешь в Детской неделе, так? Старику приятно слышать, что ты подаешь другим пример, которому они, несомненно, последуют.$B$BБуду рад принести пользу тебе и парнишке. Хмм... какой же совет ему дать? Слушай волю духов, да... ну и овощи, заодно, кушай, они полезные...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (7017,'Могиль Быстроруб из Прибамбасска – мастер кулинарных искусств. Тебе обязательно стоит его разыскать!','Могиль Быстроруб из Прибамбасска – мастер кулинарных искусств. Тебе обязательно стоит его разыскать!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Могиль Быстроруб из Прибамбасска – мастер кулинарных искусств. Тебе обязательно стоит его разыскать!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Могиль Быстроруб из Прибамбасска – мастер кулинарных искусств. Тебе обязательно стоит его разыскать!',`text0_1_loc8`);
