INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (7025,'Бала Лок\'Вен из Деревни Гиблотопь в Пылевых топях торгует особыми книгами, очень полезными для таких, как ты!','Бала Лок\'Вен из Деревни Гиблотопь в Пылевых топях торгует особыми книгами, очень полезными для таких, как ты!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Бала Лок\'Вен из Деревни Гиблотопь в Пылевых топях торгует особыми книгами, очень полезными для таких, как ты!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Бала Лок\'Вен из Деревни Гиблотопь в Пылевых топях торгует особыми книгами, очень полезными для таких, как ты!',`text0_1_loc8`);
