INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (7026,'Достопочтенный доктор Густав ван Склифф может заняться твоим обучением. Он лечит раненых в казармах Терамора.','Достопочтенный доктор Густав ван Склифф может заняться твоим обучением. Он лечит раненых в казармах Терамора.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Достопочтенный доктор Густав ван Склифф может заняться твоим обучением. Он лечит раненых в казармах Терамора.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Достопочтенный доктор Густав ван Склифф может заняться твоим обучением. Он лечит раненых в казармах Терамора.',`text0_1_loc8`);
