INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (7027,'Я слышал, что у Денеба Уокера, укрывшегося в Стромгарде, есть книга, которая, бесспорно, поможет вам улучшить вашу технику оказания первой помощи.','Я слышала, что у Денеба Уокера, укрывшегося в Стромгарде, есть книга, которая, бесспорно, поможет вам улучшить вашу технику оказания первой помощи.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я слышал, что у Денеба Уокера, укрывшегося в Стромгарде, есть книга, которая, бесспорно, поможет вам улучшить вашу технику оказания первой помощи.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я слышала, что у Денеба Уокера, укрывшегося в Стромгарде, есть книга, которая, бесспорно, поможет вам улучшить вашу технику оказания первой помощи.',`text0_1_loc8`);
