INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7036,'Дух коня погибели яростно бьется.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Дух коня погибели яростно бьется.',`text0_0_loc8`);
