INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7037,'Пути Джеденара темны и зловещи. Будь $gосторожен:осторожна;, |3-6($c), иначе эти злодеи поработят твою душу…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Пути Джеденара темны и зловещи. Будь $gосторожен:осторожна;, |3-6($c), иначе эти злодеи поработят твою душу…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7038,'Прочь! Я совещаюсь с Повелителями ужаса! Наши речи – не для твоих ушей!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Прочь! Я совещаюсь с Повелителями ужаса! Наши речи – не для твоих ушей!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7039,'…Сообщение от Гиблопуста? Что за сообщение? Он зовет своего замечательного советника и слугу Улатека? Он требует моего присутствия?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','…Сообщение от Гиблопуста? Что за сообщение? Он зовет своего замечательного советника и слугу Улатека? Он требует моего присутствия?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7040,'Что? Но как? Нет! Это невозможно! Я был так осторожен… он не мог знать!$B$BТы лжешь! Ты лжешь, и за ложь свою поплатишься!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что? Но как? Нет! Это невозможно! Я был так осторожен… он не мог знать!$B$BТы лжешь! Ты лжешь, и за ложь свою поплатишься!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7041,'В такой прекрасный день, как этот, особенно хочется жить! Взгляни на окружающую тебя красоту! Наслаждайся дарами жизни!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','В такой прекрасный день, как этот, особенно хочется жить! Взгляни на окружающую тебя красоту! Наслаждайся дарами жизни!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7042,'*ГРРРР* *РАФФ* *РАФФ*') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','*ГРРРР* *РАФФ* *РАФФ*',`text0_0_loc8`);
