INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7043,'Лава? Не обращай внимания на нее, $gдруг:подруга;. Оглянись вокруг. Наслаждайся теми радостями, что дает нам природа.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Лава? Не обращай внимания на нее, $gдруг:подруга;. Оглянись вокруг. Наслаждайся теми радостями, что дает нам природа.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7044,'Я прихожу в Силитус каждый год примерно в это время. Погода необыкновенна для моих шишек.$B$BТы $gдолжен:должна; прогуляться со мной, $gдруг:подруга;. Наслаждайся тем, что можешь узреть и чего не можешь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я прихожу в Силитус каждый год примерно в это время. Погода необыкновенна для моих шишек.$B$BТы $gдолжен:должна; прогуляться со мной, $gдруг:подруга;. Наслаждайся тем, что можешь узреть и чего не можешь.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7045,'Как приятно увидеть живую душу в этом отдаленном уголке мира. Давай прогуляемся. Пусть наши тела согреют друг друга.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Как приятно увидеть живую душу в этом отдаленном уголке мира. Давай прогуляемся. Пусть наши тела согреют друг друга.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text1_0_loc8`,`text1_1_loc8`) VALUES (7046,'Тебе нужно в Зал Легенд. Он находится над Аллеей Силы, на западном склоне.','Тебе нужно в Зал Легенд. Он находится над Аллеей Силы, на западном склоне.') ON DUPLICATE KEY UPDATE `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Тебе нужно в Зал Легенд. Он находится над Аллеей Силы, на западном склоне.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Тебе нужно в Зал Легенд. Он находится над Аллеей Силы, на западном склоне.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (7047,'А ты уже, значит, Поборник Альянса?! Полагаю, сейчас ты захочешь отправиться в Зал Защитника. Это в Старом городе.','А ты уже, значит, Поборник Альянса?! Полагаю, сейчас ты захочешь отправиться в Зал Защитника. Это в Старом городе.','Так-так, пробиваем себе дорогу в жизни, значит? Тебе нужен Зал Защитника, а найдешь ты его на юго-восточной окраине Старого города. Удачи!','Так-так, пробиваем себе дорогу в жизни, значит? Тебе нужен Зал Защитника, а найдешь ты его на юго-восточной окраине Старого города. Удачи!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','А ты уже, значит, Поборник Альянса?! Полагаю, сейчас ты захочешь отправиться в Зал Защитника. Это в Старом городе.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','А ты уже, значит, Поборник Альянса?! Полагаю, сейчас ты захочешь отправиться в Зал Защитника. Это в Старом городе.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Так-так, пробиваем себе дорогу в жизни, значит? Тебе нужен Зал Защитника, а найдешь ты его на юго-восточной окраине Старого города. Удачи!',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Так-так, пробиваем себе дорогу в жизни, значит? Тебе нужен Зал Защитника, а найдешь ты его на юго-восточной окраине Старого города. Удачи!',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7055,'Если вы ищете лучшего мастера на этом и всех остальных континентах, значит, вы пришли по адресу!$B$BГриманд Элмор, к твоим услугам!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если вы ищете лучшего мастера на этом и всех остальных континентах, значит, вы пришли по адресу!$B$BГриманд Элмор, к твоим услугам!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7056,'Чтобы вызвать коня погибели, нужен круг Великого призыва – только в нем можно сотворить портал в Зорот.$B$BДля круга Великого призыва нужны три составляющих: Колокол Детмуры, Колесо Черного Похода и Свеча Судного дня.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Чтобы вызвать коня погибели, нужен круг Великого призыва – только в нем можно сотворить портал в Зорот.$B$BДля круга Великого призыва нужны три составляющих: Колокол Детмуры, Колесо Черного Похода и Свеча Судного дня.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7074,'Эх! Нет ничего лучше, чем смотреть, как народ дерется на арене! Если придете сюда в нужное время, может, тоже сможете подраться!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эх! Нет ничего лучше, чем смотреть, как народ дерется на арене! Если придете сюда в нужное время, может, тоже сможете подраться!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7094,'Да, это правда, я слеп, как крот. И пьян, как… э-э-э, пьян, как… ну, ты понимаешь.$B$BВот что я тебе скажу, |3-6($r). Я только с выпивки и соображаю. Известно ж, что когда одного чувства нет, то другие вроде как за него работают. Вот у меня со здравым смыслом проблемы, а с пьяным – просто блеск!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да, это правда, я слеп, как крот. И пьян, как… э-э-э, пьян, как… ну, ты понимаешь.$B$BВот что я тебе скажу, |3-6($r). Я только с выпивки и соображаю. Известно ж, что когда одного чувства нет, то другие вроде как за него работают. Вот у меня со здравым смыслом проблемы, а с пьяным – просто блеск!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7095,'Мы оставили блага и безопасность Глубин, чтобы пойти по миру… э… в смысле – ПУТЕШЕСТВОВАТЬ по миру.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мы оставили блага и безопасность Глубин, чтобы пойти по миру… э… в смысле – ПУТЕШЕСТВОВАТЬ по миру.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7117,'Когда Лоло не хочет проливать свой драгоценный эль или, там, одежку пачкать, он всегда зовет меня. Угу. Старого Хансела всегда зовут, когда надо кого-то справедливо наказать.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Когда Лоло не хочет проливать свой драгоценный эль или, там, одежку пачкать, он всегда зовет меня. Угу. Старого Хансела всегда зовут, когда надо кого-то справедливо наказать.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7120,'Будучи дежурным десятником, я обязан следить за тем, чтобы любые проявления торговли, труда, отдыха и релаксации были в должной мере утомительными.$B$BЕсли какое-либо задание покажется тебе слишком легким, немедленно доложи мне.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Будучи дежурным десятником, я обязан следить за тем, чтобы любые проявления торговли, труда, отдыха и релаксации были в должной мере утомительными.$B$BЕсли какое-либо задание покажется тебе слишком легким, немедленно доложи мне.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7122,'Не знаю, какое там братство Тория, но если я увижу дворфа из клана Черного Железа, то его сразу мотыгой по черепу огрею! И куда же мне тебя направить, $Gпарень:девушка;?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Не знаю, какое там братство Тория, но если я увижу дворфа из клана Черного Железа, то его сразу мотыгой по черепу огрею! И куда же мне тебя направить, $Gпарень:девушка;?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7154,'На поверхности шара виден отпечаток большой ладони. Несмотря на то что шар явно часто и много использовали, он в довольно хорошем состоянии.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','На поверхности шара виден отпечаток большой ладони. Несмотря на то что шар явно часто и много использовали, он в довольно хорошем состоянии.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7155,'Отметки на сфере совпадают с клеймом на вашей руке.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Отметки на сфере совпадают с клеймом на вашей руке.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7174,'Я тот, кто смотрит за ними. Я кулак возмездия. Я подавляю недовольных. Не боишься Вождя? Не боишься моего суда?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я тот, кто смотрит за ними. Я кулак возмездия. Я подавляю недовольных. Не боишься Вождя? Не боишься моего суда?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`,`text3_0_loc8`) VALUES (7175,'Ты не видишь – я здесь рыбачу!','Ты $gраспугал:распугала; всю рыбу! Чего тебе надо?','Чем могу быть полезен, |3-6($c)?','Я буду здесь, пока не поймаю во-о-от такого окуня! А ты уже хочешь куда-то сорваться, верно?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты не видишь – я здесь рыбачу!',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Ты $gраспугал:распугала; всю рыбу! Чего тебе надо?',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Чем могу быть полезен, |3-6($c)?',`text2_0_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Я буду здесь, пока не поймаю во-о-от такого окуня! А ты уже хочешь куда-то сорваться, верно?',`text3_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7176,'Взгляни на павшего дракона, |3-6($r). Мощь Орды неоспорима!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Взгляни на павшего дракона, |3-6($r). Мощь Орды неоспорима!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7179,'Проходи дальше. Не на что здесь смотреть.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Проходи дальше. Не на что здесь смотреть.',`text0_0_loc8`);
