INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (7180,'Не хочешь исследовать какое-нибудь подземелье?','Не хочешь исследовать какое-нибудь подземелье?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не хочешь исследовать какое-нибудь подземелье?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Не хочешь исследовать какое-нибудь подземелье?',`text0_1_loc8`);
