INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (7183,'Недавно друид из ночных эльфов по имени Наралекс обнаружил сеть подземных пещер в самом сердце Степей. Он решил, что родники в этих пещерах могут вернуть земле Степей былое плодородие, и начал забирать энергию из легендарного Изумрудного Сна. Однако его видения обернулись ночными кошмарами, и вскоре Пещеры Стенаний превратились в обитель злобных жестоких хищников. Говорят, что где-то в том лабиринте таится и сам Наралекс, плененный в Изумрудном Сне.','Недавно друид из ночных эльфов по имени Наралекс обнаружил сеть подземных пещер в самом сердце Степей. Он решил, что родники в этих пещерах могут вернуть земле Степей былое плодородие, и начал забирать энергию из легендарного Изумрудного Сна. Однако его видения обернулись ночными кошмарами, и вскоре Пещеры Стенаний превратились в обитель злобных жестоких хищников. Говорят, что где-то в том лабиринте таится и сам Наралекс, плененный в Изумрудном Сне.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Недавно друид из ночных эльфов по имени Наралекс обнаружил сеть подземных пещер в самом сердце Степей. Он решил, что родники в этих пещерах могут вернуть земле Степей былое плодородие, и начал забирать энергию из легендарного Изумрудного Сна. Однако его видения обернулись ночными кошмарами, и вскоре Пещеры Стенаний превратились в обитель злобных жестоких хищников. Говорят, что где-то в том лабиринте таится и сам Наралекс, плененный в Изумрудном Сне.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Недавно друид из ночных эльфов по имени Наралекс обнаружил сеть подземных пещер в самом сердце Степей. Он решил, что родники в этих пещерах могут вернуть земле Степей былое плодородие, и начал забирать энергию из легендарного Изумрудного Сна. Однако его видения обернулись ночными кошмарами, и вскоре Пещеры Стенаний превратились в обитель злобных жестоких хищников. Говорят, что где-то в том лабиринте таится и сам Наралекс, плененный в Изумрудном Сне.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7190,'Приветствую, $gбрат:сестра;… Я бы хотел отвлечь тебя ненадолго, если возможно.$B$BМы, таурены, перенесли многие испытания и несчастья, завоевывая родину. Теперь мы испытываем сильную нехватку ткани. Если у тебя есть лишние материалы, я бы попросил тебя пожертвовать их нам. Ты, несомненно, заслужишь признательность всех тауренов!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приветствую, $gбрат:сестра;… Я бы хотел отвлечь тебя ненадолго, если возможно.$B$BМы, таурены, перенесли многие испытания и несчастья, завоевывая родину. Теперь мы испытываем сильную нехватку ткани. Если у тебя есть лишние материалы, я бы попросил тебя пожертвовать их нам. Ты, несомненно, заслужишь признательность всех тауренов!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (7191,'Огненная Пропасть находится под Расселиной теней в центре Оргриммара.','Огненная Пропасть находится под Расселиной теней в центре Оргриммара.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Огненная Пропасть находится под Расселиной теней в центре Оргриммара.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Огненная Пропасть находится под Расселиной теней в центре Оргриммара.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (7192,'Вход в Пещеры Стенаний находится у Цветущего оазиса, к юго-западу от Перекрестка в Степях.','Вход в Пещеры Стенаний находится у Цветущего оазиса, к юго-западу от Перекрестка в Степях.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вход в Пещеры Стенаний находится у Цветущего оазиса, к юго-западу от Перекрестка в Степях.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Вход в Пещеры Стенаний находится у Цветущего оазиса, к юго-западу от Перекрестка в Степях.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7193,'Приветствую вас, друг мой. Прошу вас, уделите мне пару минут…$B$BМы немало пережили за время становления Тельдрассила. Вдобавок ко всем трудностям и невзгодам, у нас закончилась ткань. Если у вас найдется лишний материал, я прошу вас пожертвовать его на благое дело. Это, разумеется, поднимет вашу репутацию в глазах всех ночных эльфов!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приветствую вас, друг мой. Прошу вас, уделите мне пару минут…$B$BМы немало пережили за время становления Тельдрассила. Вдобавок ко всем трудностям и невзгодам, у нас закончилась ткань. Если у вас найдется лишний материал, я прошу вас пожертвовать его на благое дело. Это, разумеется, поднимет вашу репутацию в глазах всех ночных эльфов!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7196,'Друг, Штормград нуждается в твоей помощи и твоей щедрости!$B$BНаши когда-то огромные запасы ткани истощились. И теперь Штормград пытается восстановить эти запасы для производства ткани и бинтов! Пожертвовав нам ткань, ты очень поможешь Штормовому Оплоту и заслужишь уважение всех его жителей!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Друг, Штормград нуждается в твоей помощи и твоей щедрости!$B$BНаши когда-то огромные запасы ткани истощились. И теперь Штормград пытается восстановить эти запасы для производства ткани и бинтов! Пожертвовав нам ткань, ты очень поможешь Штормовому Оплоту и заслужишь уважение всех его жителей!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
