INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (7206,'Монастырь Алого ордена стоит на холмах к северо-востоку от Тирисфальских лесов.','Монастырь Алого ордена стоит на холмах к северо-востоку от Тирисфальских лесов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Монастырь Алого ордена стоит на холмах к северо-востоку от Тирисфальских лесов.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Монастырь Алого ордена стоит на холмах к северо-востоку от Тирисфальских лесов.',`text0_1_loc8`);
