INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7209,'Курганы Иглошкурых – это столица расы иглогривов, построенная по образцу лабиринтов. В них живет племя Мертвой Головы – целая армия дружественных нам иглогривов, возглавляемых верховными жрецами. Однако сейчас над их обителью сгустилась тьма. Армия Плети под предводительством лича Амненнара Хладовея подчинили иглогривов своей воле и превратили их город в цитадель нежити.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Курганы Иглошкурых – это столица расы иглогривов, построенная по образцу лабиринтов. В них живет племя Мертвой Головы – целая армия дружественных нам иглогривов, возглавляемых верховными жрецами. Однако сейчас над их обителью сгустилась тьма. Армия Плети под предводительством лича Амненнара Хладовея подчинили иглогривов своей воле и превратили их город в цитадель нежити.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
