INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (7212,'Ульдаман – это древняя подземная крепость титанов, созданная одновременно с этим миром. Археологи дворфов, раскопавшие ее, выпустили на волю троггов – первых живых существ, созданных титанами. По легенде, когда титаны окончательно убедились в провале эксперимента с троггами, они создали дворфов. Все эти секреты записаны на знаменитых дисках Норганнона – массивных артефактах, сокрытых в глубине Ульдамана. Их защищают гигантские существа из живого камня.','Ульдаман – это древняя подземная крепость титанов, созданная одновременно с этим миром. Археологи дворфов, раскопавшие ее, выпустили на волю троггов – первых живых существ, созданных титанами. По легенде, когда титаны окончательно убедились в провале эксперимента с троггами, они создали дворфов. Все эти секреты записаны на знаменитых дисках Норганнона – массивных артефактах, сокрытых в глубине Ульдамана. Их защищают гигантские существа из живого камня.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ульдаман – это древняя подземная крепость титанов, созданная одновременно с этим миром. Археологи дворфов, раскопавшие ее, выпустили на волю троггов – первых живых существ, созданных титанами. По легенде, когда титаны окончательно убедились в провале эксперимента с троггами, они создали дворфов. Все эти секреты записаны на знаменитых дисках Норганнона – массивных артефактах, сокрытых в глубине Ульдамана. Их защищают гигантские существа из живого камня.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ульдаман – это древняя подземная крепость титанов, созданная одновременно с этим миром. Археологи дворфов, раскопавшие ее, выпустили на волю троггов – первых живых существ, созданных титанами. По легенде, когда титаны окончательно убедились в провале эксперимента с троггами, они создали дворфов. Все эти секреты записаны на знаменитых дисках Норганнона – массивных артефактах, сокрытых в глубине Ульдамана. Их защищают гигантские существа из живого камня.',`text0_1_loc8`);
