INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (7215,'Мародон находится посреди западного берега Пустошей, в долине Копий.','Мародон находится посреди западного берега Пустошей, в долине Копий.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мародон находится посреди западного берега Пустошей, в долине Копий.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мародон находится посреди западного берега Пустошей, в долине Копий.',`text0_1_loc8`);
