INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7216,'Мародон – одно из самых священных мест Пустошей. В этом огромном пещерном храме погребен Зейтар, один из двух бессмертных сыновей полубога Кенария. Легенда гласит, что от Зейтара и принцессы элементалей земли Терадрас произошли презренные кентавры. Вскоре после своего появления на свет эти варвары предательски убили своего отца. Говорят, что Терадрас пленила дух Зейтара в лабиринте подземных ходов и использует его силу в каких-то дурных целях.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мародон – одно из самых священных мест Пустошей. В этом огромном пещерном храме погребен Зейтар, один из двух бессмертных сыновей полубога Кенария. Легенда гласит, что от Зейтара и принцессы элементалей земли Терадрас произошли презренные кентавры. Вскоре после своего появления на свет эти варвары предательски убили своего отца. Говорят, что Терадрас пленила дух Зейтара в лабиринте подземных ходов и использует его силу в каких-то дурных целях.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
