INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (7218,'Черная гора находится к югу от Тлеющего Ущелья и к северу от Пылающих степей.','Черная гора находится к югу от Тлеющего Ущелья и к северу от Пылающих степей.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Черная гора находится к югу от Тлеющего Ущелья и к северу от Пылающих степей.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Черная гора находится к югу от Тлеющего Ущелья и к северу от Пылающих степей.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (7220,'Мощная крепость, вытесанная в огненных недрах Черной горы, находилась во владении злобных дворфов Черного Железа, пока Нефариан – коварный сын дракона Смертокрыла – не обрел контроль над Пиком Черной горы, объявив войну дворфам, окопавшимся в вулканических глубинах горы. Выяснив, что дворфами руководит могучий элементаль огня Рагнарос, Нефариан поклялся сокрушить своих врагов и захватить всю Черную гору.','Мощная крепость, вытесанная в огненных недрах Черной горы, находилась во владении злобных дворфов Черного Железа, пока Нефариан – коварный сын дракона Смертокрыла – не обрел контроль над Пиком Черной горы, объявив войну дворфам, окопавшимся в вулканических глубинах горы. Выяснив, что дворфами руководит могучий элементаль огня Рагнарос, Нефариан поклялся сокрушить своих врагов и захватить всю Черную гору.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мощная крепость, вытесанная в огненных недрах Черной горы, находилась во владении злобных дворфов Черного Железа, пока Нефариан – коварный сын дракона Смертокрыла – не обрел контроль над Пиком Черной горы, объявив войну дворфам, окопавшимся в вулканических глубинах горы. Выяснив, что дворфами руководит могучий элементаль огня Рагнарос, Нефариан поклялся сокрушить своих врагов и захватить всю Черную гору.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мощная крепость, вытесанная в огненных недрах Черной горы, находилась во владении злобных дворфов Черного Железа, пока Нефариан – коварный сын дракона Смертокрыла – не обрел контроль над Пиком Черной горы, объявив войну дворфам, окопавшимся в вулканических глубинах горы. Выяснив, что дворфами руководит могучий элементаль огня Рагнарос, Нефариан поклялся сокрушить своих врагов и захватить всю Черную гору.',`text0_1_loc8`);
