INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7223,'Школа некромантов, известная как Некроситет, находится в Западных Чумных землях, среди руин на острове Каэр Дарроу.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Школа некромантов, известная как Некроситет, находится в Западных Чумных землях, среди руин на острове Каэр Дарроу.',`text0_0_loc8`);
