INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7225,'Город Стратхольм лежит в руинах в Восточных Чумных землях к северу от Чумного леса.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Город Стратхольм лежит в руинах в Восточных Чумных землях к северу от Чумного леса.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7226,'Когда-то город Стратхольм был жемчужиной северного Лордерона, и именно там принц Артас восстал против своего учителя, Утера Светоносного, и убил сотни своих подданных, решив, что они заражены чумой нежити. Вскоре Артас сдался Королю-личу, и теперь разрушенный город населяет нежить Плети под предводительством могущественного Кел\'Тузада и сборище крестоносцев Алого ордена, которых возглавляет Верховный рыцарь Датрохан. Эти две стороны ведут жестокую непрекращающуюся битву.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Когда-то город Стратхольм был жемчужиной северного Лордерона, и именно там принц Артас восстал против своего учителя, Утера Светоносного, и убил сотни своих подданных, решив, что они заражены чумой нежити. Вскоре Артас сдался Королю-личу, и теперь разрушенный город населяет нежить Плети под предводительством могущественного Кел\'Тузада и сборище крестоносцев Алого ордена, которых возглавляет Верховный рыцарь Датрохан. Эти две стороны ведут жестокую непрекращающуюся битву.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
