-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7241,'Знаешь, рыбалка – это так здорово… Умением ловить рыбу я обязан своему наставнику и лучшему рыбаку в мире – Нату Пэглу. Ты о нем $gслышал:слышала;?$B$BЕсли ищешь просветления, Нат Пэгл укажет тебе путь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Знаешь, рыбалка – это так здорово… Умением ловить рыбу я обязан своему наставнику и лучшему рыбаку в мире – Нату Пэглу. Ты о нем $gслышал:слышала;?$B$BЕсли ищешь просветления, Нат Пэгл укажет тебе путь.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7243,'Я Килрам, мастер топора.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я Килрам, мастер топора.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7244,'Да, когда-то вы были закаленным ветераном... Килрам может снова сделать вас $gтаким:такой;. Способности у вас есть, только попросите, и он обучит вас искусству школы Топора.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да, когда-то вы были закаленным ветераном... Килрам может снова сделать вас $gтаким:такой;. Способности у вас есть, только попросите, и он обучит вас искусству школы Топора.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7246,'Я могу научить тебя кузнечному делу. Только попроси вежливо.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я могу научить тебя кузнечному делу. Только попроси вежливо.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7247,'Отойди, а то разрублю напополам!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Отойди, а то разрублю напополам!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7248,'Если хочешь научиться ковать мечи – только попроси.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если хочешь научиться ковать мечи – только попроси.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7249,'Я только что закончил работу над новой пространственной подрывочной машиной, которая сделает меня богаче, чем в самых моих несбыточных гоблинских мечтах! Все, что мне нужно, – это найти толкового гоблина-инженера, чтобы тот сделал многомерный саморез, и останется только подсоединить и испробовать!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я только что закончил работу над новой пространственной подрывочной машиной, которая сделает меня богаче, чем в самых моих несбыточных гоблинских мечтах! Все, что мне нужно, – это найти толкового гоблина-инженера, чтобы тот сделал многомерный саморез, и останется только подсоединить и испробовать!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7251,'Благодаря открытиям храбрых гномов из Гномрегана мне удалось создать свое величайшее изобретение – Транспортер материи! Теперь мне нужен гном-инженер, чтобы создать для него достаточно мощный маяк.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Благодаря открытиям храбрых гномов из Гномрегана мне удалось создать свое величайшее изобретение – Транспортер материи! Теперь мне нужен гном-инженер, чтобы создать для него достаточно мощный маяк.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7252,'Как только вы соберете устройство, останется только включить его и перенестись в милый Прибамбасск! Почти все, кто пользовались такими устройствами, попадали на площадку лицом в ту же сторону, что и до переноса.\r\n\r\nПравда, говорят, что вместо некоторых путешественников в конечный пункт прибывали их злые двойники из альтернативной вселенной, но с этим мы пока не разобрались.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Как только вы соберете устройство, останется только включить его и перенестись в милый Прибамбасск! Почти все, кто пользовались такими устройствами, попадали на площадку лицом в ту же сторону, что и до переноса.\r\n\r\nПравда, говорят, что вместо некоторых путешественников в конечный пункт прибывали их злые двойники из альтернативной вселенной, но с этим мы пока не разобрались.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7253,'Если узнаешь, как можно улучшить устройство, дай мне знать!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если узнаешь, как можно улучшить устройство, дай мне знать!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7256,'Я окажу последнюю услугу. Надеюсь, она пойдет на пользу.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я окажу последнюю услугу. Надеюсь, она пойдет на пользу.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7257,'Возьми ключ и отопри оковы! Он у Хранительницы Хита\'йи… в глубине пещеры…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Возьми ключ и отопри оковы! Он у Хранительницы Хита\'йи… в глубине пещеры…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7274,'Работа/бюро находок/розыск:') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Работа/бюро находок/розыск:',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7294,'Заг-заг, мой друг! Я – Кельм Харгюнт, главный снабженец Всадников Песни Войны. Когда мы увидим, чего ты $gдостоин:достойна;, я покажу тебе прекрасную коллекцию товаров, которые пригодятся тебе в Ущелье Песни Войны. Если надо что-то починить, я также к твоим услугам.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Заг-заг, мой друг! Я – Кельм Харгюнт, главный снабженец Всадников Песни Войны. Когда мы увидим, чего ты $gдостоин:достойна;, я покажу тебе прекрасную коллекцию товаров, которые пригодятся тебе в Ущелье Песни Войны. Если надо что-то починить, я также к твоим услугам.',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7295,'Да пребудет с тобой благословение ночи, $gдруг:подруга;! Я Иллиана Лунное Сияние, главный снабженец Среброкрылых Часовых в Ясеневом лесу. Когда ты завоюешь авторитет среди Часовых, я предложу тебе богатый выбор товаров, которые ты сможешь использовать в Ущелье Песни Войны. Кроме того, я могу чинить твое снаряжение.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Да пребудет с тобой благословение ночи, $gдруг:подруга;! Я Иллиана Лунное Сияние, главный снабженец Среброкрылых Часовых в Ясеневом лесу. Когда ты завоюешь авторитет среди Часовых, я предложу тебе богатый выбор товаров, которые ты сможешь использовать в Ущелье Песни Войны. Кроме того, я могу чинить твое снаряжение.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`) VALUES (7315,'Куда же отправить тебя сегодня, |3-6($c)?','Хотя Перекресток – торговый и культурный центр всех Степей, мне больше по душе тишина Лагеря Таурахо. Куда ты хочешь отправиться?','Неисповедимы пути Матери-Земли. Пусть же она приглядит за тобой в твоих странствиях.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Куда же отправить тебя сегодня, |3-6($c)?',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Хотя Перекресток – торговый и культурный центр всех Степей, мне больше по душе тишина Лагеря Таурахо. Куда ты хочешь отправиться?',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Неисповедимы пути Матери-Земли. Пусть же она приглядит за тобой в твоих странствиях.',`text2_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7335,'Добро пожаловать на величайшее представление в Азероте, друг мой! Я искренне рад видеть тебя снова.$B$BПожалуйста, проходи и еще раз посмотри на наши товары. Загляни к каждому продавцу, потому что на каждой ярмарке Новолуния ты найдешь что-нибудь новенькое! Убедись $Gсам:сама; – чудеса существуют! Наша ярмарка – для всех возрастов!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать на величайшее представление в Азероте, друг мой! Я искренне рад видеть тебя снова.$B$BПожалуйста, проходи и еще раз посмотри на наши товары. Загляни к каждому продавцу, потому что на каждой ярмарке Новолуния ты найдешь что-нибудь новенькое! Убедись $Gсам:сама; – чудеса существуют! Наша ярмарка – для всех возрастов!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7337,'Выдача призов! Меняйте купоны на призы! Подходим, подходим!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Выдача призов! Меняйте купоны на призы! Подходим, подходим!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`,`text3_0_loc8`,`text5_0_loc8`,`text7_0_loc8`) VALUES (7338,'Прочь, деревенщина.','Так не пойдет, $gприятель:подруга;. Уходи.','Если вы пытаетесь проявить дружелюбие, то не старайтесь. Вы мне понравитесь разве что в виде трупа.','На всякий случай уточняю: работа с клиентами не входит в мои обязанности.','Если уж я собираюсь потерять голову, мне понадобится запасная.','В отличие от большинства огров я знаю, для чего эта постройка. В ней мочат врагов. А теперь убирайся.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Прочь, деревенщина.',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Так не пойдет, $gприятель:подруга;. Уходи.',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Если вы пытаетесь проявить дружелюбие, то не старайтесь. Вы мне понравитесь разве что в виде трупа.',`text2_0_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','На всякий случай уточняю: работа с клиентами не входит в мои обязанности.',`text3_0_loc8`), `text5_0_loc8`=IF(`text5_0_loc8` IS NULL OR `text5_0_loc8`='','Если уж я собираюсь потерять голову, мне понадобится запасная.',`text5_0_loc8`), `text7_0_loc8`=IF(`text7_0_loc8` IS NULL OR `text7_0_loc8`='','В отличие от большинства огров я знаю, для чего эта постройка. В ней мочат врагов. А теперь убирайся.',`text7_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text1_0_loc8`,`text1_1_loc8`) VALUES (7354,'Скоро будет ярмарка!','Скоро будет ярмарка!') ON DUPLICATE KEY UPDATE `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Скоро будет ярмарка!',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Скоро будет ярмарка!',`text1_1_loc8`);
