INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7376,'Ярмарка Новолуния откроется в Мулгоре. Мы поставим палатки к юго-западу от Громового Утеса.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ярмарка Новолуния откроется в Мулгоре. Мы поставим палатки к юго-западу от Громового Утеса.',`text0_0_loc8`);
