INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7377,'Ярмарка Новолуния сейчас проходит на золотистых равнинах Мулгора, к юго-западу от Громового Утеса. Не пропусти!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ярмарка Новолуния сейчас проходит на золотистых равнинах Мулгора, к юго-западу от Громового Утеса. Не пропусти!',`text0_0_loc8`);
