INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7379,'Ярмарка Новолуния сейчас проводится в Элвиннском лесу, к югу от Златоземья. Не пропусти!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ярмарка Новолуния сейчас проводится в Элвиннском лесу, к югу от Златоземья. Не пропусти!',`text0_0_loc8`);
