INSERT INTO `locales_npc_text` (`id`,`text2_1_loc8`,`text3_1_loc8`) VALUES (7382,'Не забудь купить выпивку и подарки!','Ярмарка Новолуния – величайшее событие Азерота!') ON DUPLICATE KEY UPDATE `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Не забудь купить выпивку и подарки!',`text2_1_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','Ярмарка Новолуния – величайшее событие Азерота!',`text3_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7383,'Добро пожаловать на ярмарку Новолуния, |3-6($c)!$B$BМеня зовут Керри Хикс. Я пожала бы тебе руку, да боюсь ее сломать, потому что я самая сильная женщина на свете!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Добро пожаловать на ярмарку Новолуния, |3-6($c)!$B$BМеня зовут Керри Хикс. Я пожала бы тебе руку, да боюсь ее сломать, потому что я самая сильная женщина на свете!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text2_0_loc8`) VALUES (7387,'У вас есть деньги, а у нас – еда. Так чего вы ждете?') ON DUPLICATE KEY UPDATE `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','У вас есть деньги, а у нас – еда. Так чего вы ждете?',`text2_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`,`text2_1_loc8`) VALUES (7389,'Все, что я продаю, я приобрела лично, и я гарантирую подлинность всех этих вещей.','Приходите взглянуть на мои товары, пока мы здесь. Мы пробудем тут неделю, а потом уедем в далекие края.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Все, что я продаю, я приобрела лично, и я гарантирую подлинность всех этих вещей.',`text0_1_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Приходите взглянуть на мои товары, пока мы здесь. Мы пробудем тут неделю, а потом уедем в далекие края.',`text2_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text3_0_loc8`) VALUES (7390,'Покупайте лягушек и кожаные мячики!') ON DUPLICATE KEY UPDATE `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Покупайте лягушек и кожаные мячики!',`text3_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7394,'Я рада видеть тебя снова, $n! Тебе понравилось на ярмарке? $B$BХочешь побороться? Да нет, конечно, тебе еще руки дороги!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я рада видеть тебя снова, $n! Тебе понравилось на ярмарке? $B$BХочешь побороться? Да нет, конечно, тебе еще руки дороги!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7395,'Приветствую тебя. Я – Хронос, помнящий все. Моя память безупречна и точна до малейшей детали.$B$BДоверься мне.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приветствую тебя. Я – Хронос, помнящий все. Моя память безупречна и точна до малейшей детали.$B$BДоверься мне.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7396,'Здравствуй, $n. Думаешь, я тебя забыл?$B$BНет, вряд ли ты так думаешь. Ты – $gумный:умная; и $gспособен:способна; с первого взгляда распознать обладателя абсолютной памяти.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здравствуй, $n. Думаешь, я тебя забыл?$B$BНет, вряд ли ты так думаешь. Ты – $gумный:умная; и $gспособен:способна; с первого взгляда распознать обладателя абсолютной памяти.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7398,'$n, вы вернулись! За обедом духи нашептали мне, что вы придете и мы будем обсуждать какое-то дело.$B$BОни были правы?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','$n, вы вернулись! За обедом духи нашептали мне, что вы придете и мы будем обсуждать какое-то дело.$B$BОни были правы?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7399,'Привет, $n! Рад тебя видеть! Правда, на ярмарке Новолуния очень весело?$B$BЗдесь есть на что посмотреть! Ну так смотри! Смотри – и, возможно, когда-нибудь тебе откроется еще больше…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Привет, $n! Рад тебя видеть! Правда, на ярмарке Новолуния очень весело?$B$BЗдесь есть на что посмотреть! Ну так смотри! Смотри – и, возможно, когда-нибудь тебе откроется еще больше…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7400,'Никак не могу найти свою лягушку, Жабжаб. Она любит эль Черного Железа – только его и пьет, а его бывает так трудно достать! Мои запасы кончились, и Жабжаб, должно быть, убежала искать эль!$B$BХочу, чтобы она вернулась…') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Никак не могу найти свою лягушку, Жабжаб. Она любит эль Черного Железа – только его и пьет, а его бывает так трудно достать! Мои запасы кончились, и Жабжаб, должно быть, убежала искать эль!$B$BХочу, чтобы она вернулась…',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7402,'Этот лагерь должен устоять во что бы то ни стало, |3-6($c). Нельзя уступить врагам ни дюйма этой земли, потому что они бы нам ни за что не уступили.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Этот лагерь должен устоять во что бы то ни стало, |3-6($c). Нельзя уступить врагам ни дюйма этой земли, потому что они бы нам ни за что не уступили.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7403,'Сейчас опасные времена, |3-6($r). Древнее зло восстает, и ему плевать, из Орды ты или из Альянса.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Сейчас опасные времена, |3-6($r). Древнее зло восстает, и ему плевать, из Орды ты или из Альянса.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`,`text1_1_loc8`,`text2_1_loc8`) VALUES (7404,'Только лучшая выпивка! Утолите жажду самыми вкусными напитками ярмарки Новолуния!','Не стесняйся, купи всем по кружечке!','Чаевые никогда не помешают, $gмилый друг:госпожа;.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Только лучшая выпивка! Утолите жажду самыми вкусными напитками ярмарки Новолуния!',`text0_1_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Не стесняйся, купи всем по кружечке!',`text1_1_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Чаевые никогда не помешают, $gмилый друг:госпожа;.',`text2_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`) VALUES (7406,'Ква.','Поцелуй меня.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ква.',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Поцелуй меня.',`text1_0_loc8`);
