INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7415,'Приветствую, |3-6($c). Именно здесь ваш военный вождь сразился с Оргримом Молотом Рока! Это было много лет назад, но я помню все на удивление отчетливо.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приветствую, |3-6($c). Именно здесь ваш военный вождь сразился с Оргримом Молотом Рока! Это было много лет назад, но я помню все на удивление отчетливо.',`text0_0_loc8`);
