INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7441,'Командиры Северного Волка: $966w, лейтенанты Северного Волка: $964w.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Командиры Северного Волка: $966w, лейтенанты Северного Волка: $964w.',`text0_0_loc8`);
