INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7454,'Если ты стремишься спасти мир, ты $gпришел:пришла; по адресу. Безликий кровавый бог Хаккар снова вернулся в наш мир!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если ты стремишься спасти мир, ты $gпришел:пришла; по адресу. Безликий кровавый бог Хаккар снова вернулся в наш мир!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7479,'Я буду охранять проход к крепости Северного Волка. Только прикажите мне, командир, – и я отправлюсь в полет.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я буду охранять проход к крепости Северного Волка. Только прикажите мне, командир, – и я отправлюсь в полет.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7481,'Здравствуйте, |3-6($c). Вы хотите помочь Среброкрылым Часовым в бою в Ущелье Песни Войны?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Здравствуйте, |3-6($c). Вы хотите помочь Среброкрылым Часовым в бою в Ущелье Песни Войны?',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7482,'Хвала Элуне! Вы ищете нашу военачальницу из Ущелья Песни Войны? Ее зовут Эталас, и она ждет вас возле наставников воинов.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Хвала Элуне! Вы ищете нашу военачальницу из Ущелья Песни Войны? Ее зовут Эталас, и она ждет вас возле наставников воинов.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (7483,'Итак, $gпарнишка:девочка;, ты считаешь, что можешь сражаться во славу Альянса в Альтеракской долине? Что ж, хорошо. Тогда отправляйся в Стальгорн и поговори с Глордрумом Сталебородом. Скорее всего, он будет сидеть в Оружейной и разрабатывать очередной план наступления.','Итак, $gпарнишка:девочка;, ты считаешь, что можешь сражаться во славу Альянса в Альтеракской долине? Что ж, хорошо. Тогда отправляйся в Стальгорн и поговори с Глордрумом Сталебородом. Скорее всего, он будет сидеть в Оружейной и разрабатывать очередной план наступления.','О, Альтеракская долина! Славные воспоминания! *вздыхает* Что ж, я не могу к вам присоединиться, но буду гордиться вами! Чтоб попасть туда, найдите в Оружейной Глордрума Сталеборода. Это здесь, в Оружейной Стальгорна.','О, Альтеракская долина! Славные воспоминания! *вздыхает* Что ж, я не могу к вам присоединиться, но буду гордиться вами! Чтоб попасть туда, найдите в Оружейной Глордрума Сталеборода. Это здесь, в Оружейной Стальгорна.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Итак, $gпарнишка:девочка;, ты считаешь, что можешь сражаться во славу Альянса в Альтеракской долине? Что ж, хорошо. Тогда отправляйся в Стальгорн и поговори с Глордрумом Сталебородом. Скорее всего, он будет сидеть в Оружейной и разрабатывать очередной план наступления.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Итак, $gпарнишка:девочка;, ты считаешь, что можешь сражаться во славу Альянса в Альтеракской долине? Что ж, хорошо. Тогда отправляйся в Стальгорн и поговори с Глордрумом Сталебородом. Скорее всего, он будет сидеть в Оружейной и разрабатывать очередной план наступления.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','О, Альтеракская долина! Славные воспоминания! *вздыхает* Что ж, я не могу к вам присоединиться, но буду гордиться вами! Чтоб попасть туда, найдите в Оружейной Глордрума Сталеборода. Это здесь, в Оружейной Стальгорна.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','О, Альтеракская долина! Славные воспоминания! *вздыхает* Что ж, я не могу к вам присоединиться, но буду гордиться вами! Чтоб попасть туда, найдите в Оружейной Глордрума Сталеборода. Это здесь, в Оружейной Стальгорна.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7484,'Если вы собираетесь в Альтеракскую долину, поговорите с Катрой Кровавый Рык. Ее можно найти в Зале Отважных, что на Аллее Чести.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если вы собираетесь в Альтеракскую долину, поговорите с Катрой Кровавый Рык. Ее можно найти в Зале Отважных, что на Аллее Чести.',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7495,'Война идет на нескольких полях боя. У каждого – свой военачальник. Куда ты хочешь отправиться?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Война идет на нескольких полях боя. У каждого – свой военачальник. Куда ты хочешь отправиться?',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7496,'Я знаю, кто вам нужен, |3-6($c). Поищите Брогуна Камнещита на Террасе Воинов.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я знаю, кто вам нужен, |3-6($c). Поищите Брогуна Камнещита на Террасе Воинов.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7497,'Ага, и на какое поле боя вы собирались?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ага, и на какое поле боя вы собирались?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`) VALUES (7498,'Ущелье Песни Войны? Что ж, вам нужно поговорить с пресветлой Лиландрис в Оружейной.','Когда можно подраться с Ордой, особенно с орками, я считаю это время проведенным с пользой. Ты увидишь большую заварушку в Ущелье Песни Войны, это точно. Отправляйся в Оружейную и поговори с Лиландрис. Она отправит тебя на место.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ущелье Песни Войны? Что ж, вам нужно поговорить с пресветлой Лиландрис в Оружейной.',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Когда можно подраться с Ордой, особенно с орками, я считаю это время проведенным с пользой. Ты увидишь большую заварушку в Ущелье Песни Войны, это точно. Отправляйся в Оружейную и поговори с Лиландрис. Она отправит тебя на место.',`text1_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7499,'Какое поле боя вас интересует?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Какое поле боя вас интересует?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`) VALUES (7500,'Тогда вам нужен Тельман Сланцевый Кулак. Он находится подле короля в крепости Штормграда.','Как бы мне хотелось пойти с вами, $n. Отправляйтесь в крепость Штормграда, там в зале для аудиенций найдите Тельмана Сланцевого Кулака. Он поможет вам добраться в Альтеракскую долину.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тогда вам нужен Тельман Сланцевый Кулак. Он находится подле короля в крепости Штормграда.',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Как бы мне хотелось пойти с вами, $n. Отправляйтесь в крепость Штормграда, там в зале для аудиенций найдите Тельмана Сланцевого Кулака. Он поможет вам добраться в Альтеракскую долину.',`text1_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`) VALUES (7501,'Да, Среброкрылым пригодится твоя помощь. Поговори с Эльфарран в зале аудиенций крепости Штормграда.','Среброкрылым Часовым понадобится вся возможная помощь в бою с Всадниками Песни Войны. $n, если вы готовы им помочь, отправляйтесь в крепость Штормграда и поговорите с Эльфарран.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да, Среброкрылым пригодится твоя помощь. Поговори с Эльфарран в зале аудиенций крепости Штормграда.',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Среброкрылым Часовым понадобится вся возможная помощь в бою с Всадниками Песни Войны. $n, если вы готовы им помочь, отправляйтесь в крепость Штормграда и поговорите с Эльфарран.',`text1_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`) VALUES (7502,'Мы должны вышибить эльфов и их трусливый Альянс из Ущелья Песни Войны. Если вы готовы помочь Орде, ступайте на Аллею Чести и найдите Бракгуля Смертоносного в Зале Отважных.','Среброкрылые Часовые – не слишком грозные противники. Но если ты рвешься перебить их, |3-6($c), найди Бракгуля Смертоносного в Зале Отважных.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы должны вышибить эльфов и их трусливый Альянс из Ущелья Песни Войны. Если вы готовы помочь Орде, ступайте на Аллею Чести и найдите Бракгуля Смертоносного в Зале Отважных.',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Среброкрылые Часовые – не слишком грозные противники. Но если ты рвешься перебить их, |3-6($c), найди Бракгуля Смертоносного в Зале Отважных.',`text1_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7503,'На каком поле боя ты хочешь искать славы?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','На каком поле боя ты хочешь искать славы?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7504,'На какое поле боя вы хотите отправиться?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','На какое поле боя вы хотите отправиться?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7505,'Тогда тебе нужен Тайм Тотем Ярости. Ищи его на Вершине Охотников.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тогда тебе нужен Тайм Тотем Ярости. Ищи его на Вершине Охотников.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`) VALUES (7506,'Кергул Кровавый Топор ждет тебя на Вершине Охотников, чтобы помочь добраться в Ущелье Песни Войны.','Такая бессмысленная склока... но если эльфы с заставы Среброкрылых не хотят мирных переговоров, то какую альтернативу они нам оставляют? С помощью Кергула Кровавого Топора, которого найдешь на Вершине Охотников, ты сможешь попасть в Ущелье Песни Войны.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Кергул Кровавый Топор ждет тебя на Вершине Охотников, чтобы помочь добраться в Ущелье Песни Войны.',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Такая бессмысленная склока... но если эльфы с заставы Среброкрылых не хотят мирных переговоров, то какую альтернативу они нам оставляют? С помощью Кергула Кровавого Топора, которого найдешь на Вершине Охотников, ты сможешь попасть в Ущелье Песни Войны.',`text1_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7507,'Какое поле боя тебя интересует?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Какое поле боя тебя интересует?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`) VALUES (7508,'Холодно тут! Иди в Королевский квартал, поговори с Седынем Полушкуром.','Его зовут Седынь Полушкур. Он живет в Королевском квартале при дворе королевы банши и Повелителя ужаса.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Холодно тут! Иди в Королевский квартал, поговори с Седынем Полушкуром.',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Его зовут Седынь Полушкур. Он живет в Королевском квартале при дворе королевы банши и Повелителя ужаса.',`text1_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`) VALUES (7509,'Он, поди, в Королевском квартале. Курден Жилотяг – мелкий такой орк.','Эльфы из Ущелья Песни Войны еще не скоро придут в себя. Хорошо вы им задали! Поговорите с Курденом Жилотягом в Королевском квартале.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Он, поди, в Королевском квартале. Курден Жилотяг – мелкий такой орк.',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Эльфы из Ущелья Песни Войны еще не скоро придут в себя. Хорошо вы им задали! Поговорите с Курденом Жилотягом в Королевском квартале.',`text1_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7514,'Я Джин\'рок Разрушитель, посланник Мугамбы Кулака Растахана!$B$BЯ веду дела с воинами и варварами.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я Джин\'рок Разрушитель, посланник Мугамбы Кулака Растахана!$B$BЯ веду дела с воинами и варварами.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7515,'Я Ал\'табим Всевидящий, посланник короля Растахана.$B$BЯ веду дела со жрецами, магами и чернокнижниками.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я Ал\'табим Всевидящий, посланник короля Растахана.$B$BЯ веду дела со жрецами, магами и чернокнижниками.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7516,'Лига Аратора поклялась отвоевать котловину Арати для людей Стромгарда и всего Альянса. Это сложная задача, но победа того стоит.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Лига Аратора поклялась отвоевать котловину Арати для людей Стромгарда и всего Альянса. Это сложная задача, но победа того стоит.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7517,'Если мы хотим победить в этой войне, то не должны сидеть сложа руки и ждать неизвестно чего. Мы должны нанести сильный и быстрый удар – или потеряем Арати навсегда.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Если мы хотим победить в этой войне, то не должны сидеть сложа руки и ждать неизвестно чего. Мы должны нанести сильный и быстрый удар – или потеряем Арати навсегда.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7519,'Война идет на нескольких полях боя. У каждого – свой военачальник. Куда ты хочешь отправиться?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Война идет на нескольких полях боя. У каждого – свой военачальник. Куда ты хочешь отправиться?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (7520,'Мы должны вышибить эльфов и их трусливый Альянс из Ущелья Песни Войны. Если вы готовы помочь Орде, ступайте на Аллею Чести и найдите Бракгуля Смертоносного в Зале Отважных.','Мы должны вышибить эльфов и их трусливый Альянс из Ущелья Песни Войны. Если вы готовы помочь Орде, ступайте на Аллею Чести и найдите Бракгуля Смертоносного в Зале Отважных.','Среброкрылые Часовые – не слишком грозные противники. Но если ты рвешься перебить их, |3-6($c), найди Бракгуля Смертоносного в Зале Отважных.','Среброкрылые Часовые – не слишком грозные противники. Но если ты рвешься перебить их, |3-6($c), найди Бракгуля Смертоносного в Зале Отважных.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы должны вышибить эльфов и их трусливый Альянс из Ущелья Песни Войны. Если вы готовы помочь Орде, ступайте на Аллею Чести и найдите Бракгуля Смертоносного в Зале Отважных.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мы должны вышибить эльфов и их трусливый Альянс из Ущелья Песни Войны. Если вы готовы помочь Орде, ступайте на Аллею Чести и найдите Бракгуля Смертоносного в Зале Отважных.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Среброкрылые Часовые – не слишком грозные противники. Но если ты рвешься перебить их, |3-6($c), найди Бракгуля Смертоносного в Зале Отважных.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Среброкрылые Часовые – не слишком грозные противники. Но если ты рвешься перебить их, |3-6($c), найди Бракгуля Смертоносного в Зале Отважных.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (7521,'На каком поле боя ты хочешь искать славы?','На каком поле боя ты хочешь искать славы?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','На каком поле боя ты хочешь искать славы?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','На каком поле боя ты хочешь искать славы?',`text0_1_loc8`);
