INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (7528,'Ущелье Песни Войны? Что ж, вам нужно поговорить с пресветлой Лиландрис в Оружейной.','Ущелье Песни Войны? Что ж, вам нужно поговорить с пресветлой Лиландрис в Оружейной.','Когда можно подраться с Ордой, особенно с орками, я считаю это время проведенным с пользой. Ты увидишь большую заварушку в Ущелье Песни Войны, это точно. Отправляйся в Оружейную и поговори с Лиландрис. Она отправит тебя на место.','Когда можно подраться с Ордой, особенно с орками, я считаю это время проведенным с пользой. Ты увидишь большую заварушку в Ущелье Песни Войны, это точно. Отправляйся в Оружейную и поговори с Лиландрис. Она отправит тебя на место.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ущелье Песни Войны? Что ж, вам нужно поговорить с пресветлой Лиландрис в Оружейной.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ущелье Песни Войны? Что ж, вам нужно поговорить с пресветлой Лиландрис в Оружейной.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Когда можно подраться с Ордой, особенно с орками, я считаю это время проведенным с пользой. Ты увидишь большую заварушку в Ущелье Песни Войны, это точно. Отправляйся в Оружейную и поговори с Лиландрис. Она отправит тебя на место.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Когда можно подраться с Ордой, особенно с орками, я считаю это время проведенным с пользой. Ты увидишь большую заварушку в Ущелье Песни Войны, это точно. Отправляйся в Оружейную и поговори с Лиландрис. Она отправит тебя на место.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (7529,'Ага, и на какое поле боя вы собирались?','Ага, и на какое поле боя вы собирались?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ага, и на какое поле боя вы собирались?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ага, и на какое поле боя вы собирались?',`text0_1_loc8`);
