INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (7532,'Какое поле боя вас интересует?','Какое поле боя вас интересует?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Какое поле боя вас интересует?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Какое поле боя вас интересует?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7554,'Мы не можем допустить, чтобы Альянс построил базу в Арати! Даже их жалкий Опорный пункт рано или поздно может стать серьезной угрозой!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мы не можем допустить, чтобы Альянс построил базу в Арати! Даже их жалкий Опорный пункт рано или поздно может стать серьезной угрозой!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7555,'Битва за Низину Арати – это битва за ресурсы. Строевой лес, руда, пища – все это необходимо для ведения войны. $B$BЛишить наших врагов сырья – это ничуть не хуже, чем разгромить их на поле боя.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Битва за Низину Арати – это битва за ресурсы. Строевой лес, руда, пища – все это необходимо для ведения войны. $B$BЛишить наших врагов сырья – это ничуть не хуже, чем разгромить их на поле боя.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7556,'Хоть я и слепой, но вижу не хуже зрячих.$B$BВ основном я имею дело с охотниками и разбойниками.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Хоть я и слепой, но вижу не хуже зрячих.$B$BВ основном я имею дело с охотниками и разбойниками.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7574,'Приветствую! Я Рин\'вошо, торговец Зулдазара. Я приехал из Южных морей и привез много экзотических товаров.$B$BЕсли вы докажете, что достойны, то я, пожалуй, поторгую с вами. А если у вас есть почетные знаки моего племени, я покажу вам все свои товары!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приветствую! Я Рин\'вошо, торговец Зулдазара. Я приехал из Южных морей и привез много экзотических товаров.$B$BЕсли вы докажете, что достойны, то я, пожалуй, поторгую с вами. А если у вас есть почетные знаки моего племени, я покажу вам все свои товары!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7594,'Я Занза, Лоа Зандалара. Я прибыл из Зандалара в этом астральном облике, чтобы помочь моему народу. У Хаккара нет власти над моей душой.$B$BЯ помогаю тем, кто помогал народу Зандалара.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я Занза, Лоа Зандалара. Я прибыл из Зандалара в этом астральном облике, чтобы помочь моему народу. У Хаккара нет власти над моей душой.$B$BЯ помогаю тем, кто помогал народу Зандалара.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7595,'Зандаларский друг! Ты $gпробрался:пробралась; глубоко в логово Кровавого бога, |3-6($c). Послушай, что я тебе скажу.$B$BМногие тысячелетия назад, когда малочисленные тролли империи Зул\'Амана сражались с нахлынувшими эльфийскими варварами, великая магия была украдена у Занзы. Эта магия была использована высшими эльфами для зачарования своих орудий и брони и использовалась для завоевания тролльских земель.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Зандаларский друг! Ты $gпробрался:пробралась; глубоко в логово Кровавого бога, |3-6($c). Послушай, что я тебе скажу.$B$BМногие тысячелетия назад, когда малочисленные тролли империи Зул\'Амана сражались с нахлынувшими эльфийскими варварами, великая магия была украдена у Занзы. Эта магия была использована высшими эльфами для зачарования своих орудий и брони и использовалась для завоевания тролльских земель.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (7599,'Не хочу тебя расстраивать, |3-6($c), но ты еще недостаточно $gопытен:опытна; для Ущелья Песни Войны.','Не хочу тебя расстраивать, |3-6($c), но ты еще недостаточно $gопытен:опытна; для Ущелья Песни Войны.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не хочу тебя расстраивать, |3-6($c), но ты еще недостаточно $gопытен:опытна; для Ущелья Песни Войны.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Не хочу тебя расстраивать, |3-6($c), но ты еще недостаточно $gопытен:опытна; для Ущелья Песни Войны.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7615,'Здравствуйте, |3-6($c). Я Экзал, слуга Растахана.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здравствуйте, |3-6($c). Я Экзал, слуга Растахана.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (7616,'К сожалению, |3-6($c), тебе нужно поднабраться опыта, иначе ты не выживешь в Альтеракской долине.','К сожалению, |3-6($c), тебе нужно поднабраться опыта, иначе ты не выживешь в Альтеракской долине.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','К сожалению, |3-6($c), тебе нужно поднабраться опыта, иначе ты не выживешь в Альтеракской долине.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','К сожалению, |3-6($c), тебе нужно поднабраться опыта, иначе ты не выживешь в Альтеракской долине.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7634,'Знаки Силы остались от древней империи Гурубаши. Мы, зандаларцы, ищем их. Они имеют не только чрезвычайную историческую ценность, но мы верим, что они также содержат скрытые признаки магии, которой пользовалась старая империя.$B$BТы, вероятно, отыщешь три вида Знаков в Зул\'Гурубе: монетки, драгоценности и древние вещи. Принеси их нам в тех количествах, что мы ищем, и получишь в награду лучшие вещи, которые когда-либо изготавливал Зандалар.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Знаки Силы остались от древней империи Гурубаши. Мы, зандаларцы, ищем их. Они имеют не только чрезвычайную историческую ценность, но мы верим, что они также содержат скрытые признаки магии, которой пользовалась старая империя.$B$BТы, вероятно, отыщешь три вида Знаков в Зул\'Гурубе: монетки, драгоценности и древние вещи. Принеси их нам в тех количествах, что мы ищем, и получишь в награду лучшие вещи, которые когда-либо изготавливал Зандалар.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7635,'На этой табличке начертаны древние схемы и ужасные слова силы, но их значение – загадка для вас.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','На этой табличке начертаны древние схемы и ужасные слова силы, но их значение – загадка для вас.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7636,'На этой табличке приведены схемы и заклинания, необходимые для создания амулета безумия Гурубаши.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','На этой табличке приведены схемы и заклинания, необходимые для создания амулета безумия Гурубаши.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7638,'Лично я думаю, что самое лучшее в рыбалке – это ее неспешность. Можно спокойно подумать, вспомнить прошлое и спланировать будущее.$B$BА еще хороший повод напиться. Как свинья.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Лично я думаю, что самое лучшее в рыбалке – это ее неспешность. Можно спокойно подумать, вспомнить прошлое и спланировать будущее.$B$BА еще хороший повод напиться. Как свинья.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7640,'Чтобы поймать Газ\'ранку, нужна наживка на грязнотинников. Я сам такие делаю!$B$BНо одной наживкой тут не обойдешься – нужны и сами грязнотинники… Положи их в приманку, и она пропитается этим мерзким запахом.$B$BКогда управишься с грязнотинниками, бросай наживку со стоянки Пэгла в Зул\'Гурубе, бери бутыль и жди… Только выбирай бутыль поменьше – с такой приманкой Газ\'ранка вряд ли заставит себя ждать.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Чтобы поймать Газ\'ранку, нужна наживка на грязнотинников. Я сам такие делаю!$B$BНо одной наживкой тут не обойдешься – нужны и сами грязнотинники… Положи их в приманку, и она пропитается этим мерзким запахом.$B$BКогда управишься с грязнотинниками, бросай наживку со стоянки Пэгла в Зул\'Гурубе, бери бутыль и жди… Только выбирай бутыль поменьше – с такой приманкой Газ\'ранка вряд ли заставит себя ждать.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (7642,'Мне жаль, |3-6($c), но тебе нужно еще кое-чему научиться, прежде чем я допущу тебя в Низину Арати.','Мне жаль, |3-6($c), но тебе нужно еще кое-чему научиться, прежде чем я допущу тебя в Низину Арати.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мне жаль, |3-6($c), но тебе нужно еще кое-чему научиться, прежде чем я допущу тебя в Низину Арати.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мне жаль, |3-6($c), но тебе нужно еще кое-чему научиться, прежде чем я допущу тебя в Низину Арати.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7643,'Гри\'лек из клана Железной Крови$B$BСтранник. Да не забудется его сила и жажда боя.$B$BГри\'лек теперь странствует далеко отсюда. Но однажды он может вернуться...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Гри\'лек из клана Железной Крови$B$BСтранник. Да не забудется его сила и жажда боя.$B$BГри\'лек теперь странствует далеко отсюда. Но однажды он может вернуться...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (7644,'Отправляйся в Зал Отважных. Осквернительница, Дези Холодная, поможет тебе добраться до Низины Арати.','Отправляйся в Зал Отважных. Осквернительница, Дези Холодная, поможет тебе добраться до Низины Арати.','Ты хочешь помочь Отрекшимся сражаться против людей в Низине Арати? Тогда отправляйся в Зал Отважных и поговори с Дези Холодной.','Ты хочешь помочь Отрекшимся сражаться против людей в Низине Арати? Тогда отправляйся в Зал Отважных и поговори с Дези Холодной.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Отправляйся в Зал Отважных. Осквернительница, Дези Холодная, поможет тебе добраться до Низины Арати.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Отправляйся в Зал Отважных. Осквернительница, Дези Холодная, поможет тебе добраться до Низины Арати.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Ты хочешь помочь Отрекшимся сражаться против людей в Низине Арати? Тогда отправляйся в Зал Отважных и поговори с Дези Холодной.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Ты хочешь помочь Отрекшимся сражаться против людей в Низине Арати? Тогда отправляйся в Зал Отважных и поговори с Дези Холодной.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7645,'Грязнотинник – это особо вонючая порода рыбы, обитающая в тропических водах. Больше всех отличился зульский грязнотинник – его запах ни с чем не спутаешь. Живет эта гадость в горячих водах Зул\'Гуруба.$B$BДумаю, как раз за зульскими грязнотинниками Газ\'ранка туда и пожаловал. Но тролли, конечно, уверены, что это один из их богов... $B$BВ общем, чему хочешь, тому и верь, но обязательно положи в приманку зульского грязнотинника. Увидишь – Газ\'ранка не заставит себя ждать!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Грязнотинник – это особо вонючая порода рыбы, обитающая в тропических водах. Больше всех отличился зульский грязнотинник – его запах ни с чем не спутаешь. Живет эта гадость в горячих водах Зул\'Гуруба.$B$BДумаю, как раз за зульскими грязнотинниками Газ\'ранка туда и пожаловал. Но тролли, конечно, уверены, что это один из их богов... $B$BВ общем, чему хочешь, тому и верь, но обязательно положи в приманку зульского грязнотинника. Увидишь – Газ\'ранка не заставит себя ждать!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (7646,'Идите в Королевский квартал. Найдите сэра Малори Вилера. Он страшный.','Идите в Королевский квартал. Найдите сэра Малори Вилера. Он страшный.','Пора отнять Низину Арати у мягкотелых людей! Сэр Малори Вилер отправит тебя туда.','Пора отнять Низину Арати у мягкотелых людей! Сэр Малори Вилер отправит тебя туда.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Идите в Королевский квартал. Найдите сэра Малори Вилера. Он страшный.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Идите в Королевский квартал. Найдите сэра Малори Вилера. Он страшный.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Пора отнять Низину Арати у мягкотелых людей! Сэр Малори Вилер отправит тебя туда.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Пора отнять Низину Арати у мягкотелых людей! Сэр Малори Вилер отправит тебя туда.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (7648,'Вам нужно найти Мартина Линдси в Прудах Видений под уступом Духов. Он проводит вас в Низину Арати.','Вам нужно найти Мартина Линдси в Прудах Видений под уступом Духов. Он проводит вас в Низину Арати.','Вы хотите помочь Осквернителям в их борьбе против Лиги Аратора в Низине Арати? Отлично, попросите вам помочь Мартина Линдси. Ищите его у Прудов Видений.','Вы хотите помочь Осквернителям в их борьбе против Лиги Аратора в Низине Арати? Отлично, попросите вам помочь Мартина Линдси. Ищите его у Прудов Видений.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вам нужно найти Мартина Линдси в Прудах Видений под уступом Духов. Он проводит вас в Низину Арати.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Вам нужно найти Мартина Линдси в Прудах Видений под уступом Духов. Он проводит вас в Низину Арати.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Вы хотите помочь Осквернителям в их борьбе против Лиги Аратора в Низине Арати? Отлично, попросите вам помочь Мартина Линдси. Ищите его у Прудов Видений.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Вы хотите помочь Осквернителям в их борьбе против Лиги Аратора в Низине Арати? Отлично, попросите вам помочь Мартина Линдси. Ищите его у Прудов Видений.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (7649,'Людям нужна ваша помощь в бою с Отрекшимися в Низине Арати. Ступайте в Оружейную и поговорите с их представителем Доналом Осгудом.','Людям нужна ваша помощь в бою с Отрекшимися в Низине Арати. Ступайте в Оружейную и поговорите с их представителем Доналом Осгудом.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Людям нужна ваша помощь в бою с Отрекшимися в Низине Арати. Ступайте в Оружейную и поговорите с их представителем Доналом Осгудом.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Людям нужна ваша помощь в бою с Отрекшимися в Низине Арати. Ступайте в Оружейную и поговорите с их представителем Доналом Осгудом.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (7650,'Леди Хотешем принимает посетителей в королевском зале для аудиенций. Она проводит вас в Низину Арати, где Лига Аратора нуждается в помощи в боях с Осквернителями.','Леди Хотешем принимает посетителей в королевском зале для аудиенций. Она проводит вас в Низину Арати, где Лига Аратора нуждается в помощи в боях с Осквернителями.','То, что Лига Аратора пытается сделать в Низине Арати, просто замечательно. К сожалению, им мешает нежить и ее приспешники из Орды. Направляйся в крепость Штормграда, леди Хотешем ожидает тебя в зале для аудиенций. Она поможет тебе попасть в Низину Арати.','То, что Лига Аратора пытается сделать в Низине Арати, просто замечательно. К сожалению, им мешает нежить и ее приспешники из Орды. Направляйся в крепость Штормграда, леди Хотешем ожидает тебя в зале для аудиенций. Она поможет тебе попасть в Низину Арати.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Леди Хотешем принимает посетителей в королевском зале для аудиенций. Она проводит вас в Низину Арати, где Лига Аратора нуждается в помощи в боях с Осквернителями.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Леди Хотешем принимает посетителей в королевском зале для аудиенций. Она проводит вас в Низину Арати, где Лига Аратора нуждается в помощи в боях с Осквернителями.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','То, что Лига Аратора пытается сделать в Низине Арати, просто замечательно. К сожалению, им мешает нежить и ее приспешники из Орды. Направляйся в крепость Штормграда, леди Хотешем ожидает тебя в зале для аудиенций. Она поможет тебе попасть в Низину Арати.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','То, что Лига Аратора пытается сделать в Низине Арати, просто замечательно. К сожалению, им мешает нежить и ее приспешники из Орды. Направляйся в крепость Штормграда, леди Хотешем ожидает тебя в зале для аудиенций. Она поможет тебе попасть в Низину Арати.',`text1_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`,`text1_1_loc8`) VALUES (7651,'Людям в Низине Арати несомненно нужна наша помощь. Найди Кераса Вульфхарта. Он готов помочь и ждет тебя на Террасе Воинов.','Если ты вправду этого хочешь, |3-6($c), найди Кераса Вульфхарта на Террасе Воинов. Он – представитель Лиги Аратора. Он может помочь тебе попасть в Низину Арати.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Людям в Низине Арати несомненно нужна наша помощь. Найди Кераса Вульфхарта. Он готов помочь и ждет тебя на Террасе Воинов.',`text0_1_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Если ты вправду этого хочешь, |3-6($c), найди Кераса Вульфхарта на Террасе Воинов. Он – представитель Лиги Аратора. Он может помочь тебе попасть в Низину Арати.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
