INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7656,'$c, нам нужна твоя помощь в Ущелье Песни Войны. Поможешь ли ты нам в битве с Всадниками Песни Войны?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','$c, нам нужна твоя помощь в Ущелье Песни Войны. Поможешь ли ты нам в битве с Всадниками Песни Войны?',`text0_1_loc8`);
