INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7657,'Ну что, $gюноша:девушка;, вы готовы отправиться в Альтеракскую долину и дать Орде то, на что она так напрашивается?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ну что, $gюноша:девушка;, вы готовы отправиться в Альтеракскую долину и дать Орде то, на что она так напрашивается?',`text0_0_loc8`);
