INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7661,'Нашим войскам в Альтеракской долине нужен мудрый командир. Думаю, |3-6($c), ты прекрасно подойдешь на эту роль.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Нашим войскам в Альтеракской долине нужен мудрый командир. Думаю, |3-6($c), ты прекрасно подойдешь на эту роль.',`text0_0_loc8`);
