INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7664,'Низина Арати когда-то была нашей. С твоей помощью мы можем ее вернуть. Поможешь ли ты нам, |3-6($c)?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Низина Арати когда-то была нашей. С твоей помощью мы можем ее вернуть. Поможешь ли ты нам, |3-6($c)?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7667,'Вы думаете, у вас хватит сил, чтобы справиться с Лигой Аратора, |3-6($c)? Надеюсь, что так оно и есть. Так чего вы хотели? Или просто отнимаете мое время?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вы думаете, у вас хватит сил, чтобы справиться с Лигой Аратора, |3-6($c)? Надеюсь, что так оно и есть. Так чего вы хотели? Или просто отнимаете мое время?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7668,'Оглянитесь вокруг, |3-6($c). Редко встретишь такую компанию… Однако вам все еще нужно проявить себя. Хм, возможно, вы сможете помочь нам в Низине Арати. Согласны?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Оглянитесь вокруг, |3-6($c). Редко встретишь такую компанию… Однако вам все еще нужно проявить себя. Хм, возможно, вы сможете помочь нам в Низине Арати. Согласны?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7669,'Гри\'лек из клана Железной Крови$B$BСтранник. Да будут вечными его сила и жажда боя.$B$BГри\'лек теперь странствует на грани безумия…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Гри\'лек из клана Железной Крови$B$BСтранник. Да будут вечными его сила и жажда боя.$B$BГри\'лек теперь странствует на грани безумия…',`text0_0_loc8`);
