INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7670,'Хазза\'рах, Ткач Снов.$B$BОн управляет кошмарами и погружает своих врагов в вечный сон. $B$BСейчас Хазза\'рах далеко отсюда. Но однажды он может вернуться…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Хазза\'рах, Ткач Снов.$B$BОн управляет кошмарами и погружает своих врагов в вечный сон. $B$BСейчас Хазза\'рах далеко отсюда. Но однажды он может вернуться…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7673,'Ренатаки из Тысячи Клинков.$B$BБоль – то, чем он живет. Страх – его лучший товарищ. Пусть он однажды вернется и принесет с собой живительное кровопролитие.$B$BСейчас Ренатаки живет на краю безумия.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ренатаки из Тысячи Клинков.$B$BБоль – то, чем он живет. Страх – его лучший товарищ. Пусть он однажды вернется и принесет с собой живительное кровопролитие.$B$BСейчас Ренатаки живет на краю безумия.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7677,'Эй-эй-эй! Если вы считаете, что умеете ловить рыбу, приходите к нам! В это воскресенье в Тернистой долине пройдет состязание рыбаков!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эй-эй-эй! Если вы считаете, что умеете ловить рыбу, приходите к нам! В это воскресенье в Тернистой долине пройдет состязание рыбаков!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
