INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (7680,'Как хорошо, что вы спросили! Сэр Малори Вилер живет в Королевском квартале, прямо рядом с нашей Темной Госпожой.','Как хорошо, что вы спросили! Сэр Малори Вилер живет в Королевском квартале, прямо рядом с нашей Темной Госпожой.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Как хорошо, что вы спросили! Сэр Малори Вилер живет в Королевском квартале, прямо рядом с нашей Темной Госпожой.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Как хорошо, что вы спросили! Сэр Малори Вилер живет в Королевском квартале, прямо рядом с нашей Темной Госпожой.',`text0_1_loc8`);
