INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (7681,'Конечно, конечно, |3-6($c). Поговорите с Дези Холодной из Зала Отважных. Это на Аллее Чести.','Конечно, конечно, |3-6($c). Поговорите с Дези Холодной из Зала Отважных. Это на Аллее Чести.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Конечно, конечно, |3-6($c). Поговорите с Дези Холодной из Зала Отважных. Это на Аллее Чести.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Конечно, конечно, |3-6($c). Поговорите с Дези Холодной из Зала Отважных. Это на Аллее Чести.',`text0_1_loc8`);
