INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (7684,'Приветствую тебя, |3-6($c). Сражаться в Альтеракской долине – не только долг, но и большая честь. Присоединишься ли ты к нашей битве против Стражи Грозовой Вершины?','Приветствую тебя, |3-6($c). Сражаться в Альтеракской долине – не только долг, но и большая честь. Присоединишься ли ты к нашей битве против Стражи Грозовой Вершины?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приветствую тебя, |3-6($c). Сражаться в Альтеракской долине – не только долг, но и большая честь. Присоединишься ли ты к нашей битве против Стражи Грозовой Вершины?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Приветствую тебя, |3-6($c). Сражаться в Альтеракской долине – не только долг, но и большая честь. Присоединишься ли ты к нашей битве против Стражи Грозовой Вершины?',`text0_1_loc8`);
