INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7689,'$C, нам очень нужна ваша помощь в борьбе против Среброкрылых Часовых в Ущелье Песни Войны. К тому же это принесет вам много чести и повысит вашу репутацию среди Всадников Песни Войны! Ну как, осмелитесь ли вступить в бой?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','$C, нам очень нужна ваша помощь в борьбе против Среброкрылых Часовых в Ущелье Песни Войны. К тому же это принесет вам много чести и повысит вашу репутацию среди Всадников Песни Войны! Ну как, осмелитесь ли вступить в бой?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (7690,'Для меня большая честь сообщить вам, что Бракгуль Смертоносный в полной готовности ожидает вас в Оружейной, дабы проводить в Ущелье Песни Войны. Отправляйтесь на Аллею Чести!','Для меня большая честь сообщить вам, что Бракгуль Смертоносный в полной готовности ожидает вас в Оружейной, дабы проводить в Ущелье Песни Войны. Отправляйтесь на Аллею Чести!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Для меня большая честь сообщить вам, что Бракгуль Смертоносный в полной готовности ожидает вас в Оружейной, дабы проводить в Ущелье Песни Войны. Отправляйтесь на Аллею Чести!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Для меня большая честь сообщить вам, что Бракгуль Смертоносный в полной готовности ожидает вас в Оружейной, дабы проводить в Ущелье Песни Войны. Отправляйтесь на Аллею Чести!',`text0_1_loc8`);
