INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (7693,'Боюсь, в Альтеракской долине вы долго не проживете, |3-6($c). Приходите, когда поднаберетесь немного опыта.','Боюсь, в Альтеракской долине вы долго не проживете, |3-6($c). Приходите, когда поднаберетесь немного опыта.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Боюсь, в Альтеракской долине вы долго не проживете, |3-6($c). Приходите, когда поднаберетесь немного опыта.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Боюсь, в Альтеракской долине вы долго не проживете, |3-6($c). Приходите, когда поднаберетесь немного опыта.',`text0_1_loc8`);
