INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (7700,'Поможешь ли ты Низине Арати в час великой нужды, |3-6($c)? Это отличный шанс завоевать немало чести и заслужить наше доброе отношение, если удастся одержать победу над Осквернителями. Можем ли мы рассчитывать на тебя?','Поможешь ли ты Низине Арати в час великой нужды, |3-6($c)? Это отличный шанс завоевать немало чести и заслужить наше доброе отношение, если удастся одержать победу над Осквернителями. Можем ли мы рассчитывать на тебя?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Поможешь ли ты Низине Арати в час великой нужды, |3-6($c)? Это отличный шанс завоевать немало чести и заслужить наше доброе отношение, если удастся одержать победу над Осквернителями. Можем ли мы рассчитывать на тебя?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Поможешь ли ты Низине Арати в час великой нужды, |3-6($c)? Это отличный шанс завоевать немало чести и заслужить наше доброе отношение, если удастся одержать победу над Осквернителями. Можем ли мы рассчитывать на тебя?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (7704,'Времена года сменяются в свой срок, но ты еще пребываешь в весенней поре жизни. Пожалуйста, возвращайся к нам позднее, |3-6($c), когда станешь более $gопытным:опытной;.','Времена года сменяются в свой срок, но ты еще пребываешь в весенней поре жизни. Пожалуйста, возвращайся к нам позднее, |3-6($c), когда станешь более $gопытным:опытной;.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Времена года сменяются в свой срок, но ты еще пребываешь в весенней поре жизни. Пожалуйста, возвращайся к нам позднее, |3-6($c), когда станешь более $gопытным:опытной;.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Времена года сменяются в свой срок, но ты еще пребываешь в весенней поре жизни. Пожалуйста, возвращайся к нам позднее, |3-6($c), когда станешь более $gопытным:опытной;.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (7705,'$C, мы не стыдимся сказать, что нуждаемся в любой помощи, которую сможем получить в битве за Ущелье Песни Войны. Принять участие в битве сегодня, использовать в ней свои умения – честь более великая, чем когда либо. Кроме того, Среброкрылые Часовые станут относиться к тебе более благосклонно, когда ты начнешь помогать нам. Ты присоединишься к битве?','$C, мы не стыдимся сказать, что нуждаемся в любой помощи, которую сможем получить в битве за Ущелье Песни Войны. Принять участие в битве сегодня, использовать в ней свои умения – честь более великая, чем когда либо. Кроме того, Среброкрылые Часовые станут относиться к тебе более благосклонно, когда ты начнешь помогать нам. Ты присоединишься к битве?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','$C, мы не стыдимся сказать, что нуждаемся в любой помощи, которую сможем получить в битве за Ущелье Песни Войны. Принять участие в битве сегодня, использовать в ней свои умения – честь более великая, чем когда либо. Кроме того, Среброкрылые Часовые станут относиться к тебе более благосклонно, когда ты начнешь помогать нам. Ты присоединишься к битве?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','$C, мы не стыдимся сказать, что нуждаемся в любой помощи, которую сможем получить в битве за Ущелье Песни Войны. Принять участие в битве сегодня, использовать в ней свои умения – честь более великая, чем когда либо. Кроме того, Среброкрылые Часовые станут относиться к тебе более благосклонно, когда ты начнешь помогать нам. Ты присоединишься к битве?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7713,'Знаки Силы – мощные амулеты. Они остались от древней империи Гурубаши. Мы, зандаларцы, ищем их, чтобы забрать себе. Кровавый бог не уничтожит нас!$B$BВ Зул\'Гурубе есть три вида знаков силы: монеты, драгоценности и изначальные предметы.$B$BОтправляйся в Зул\'Гуруб. Найди Знаки Силы. Принесешь их нам – заслужишь уважение племени и сможешь позаимствовать у нас обмундирование. Тогда ты узнаешь, что такое настоящая сила!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Знаки Силы – мощные амулеты. Они остались от древней империи Гурубаши. Мы, зандаларцы, ищем их, чтобы забрать себе. Кровавый бог не уничтожит нас!$B$BВ Зул\'Гурубе есть три вида знаков силы: монеты, драгоценности и изначальные предметы.$B$BОтправляйся в Зул\'Гуруб. Найди Знаки Силы. Принесешь их нам – заслужишь уважение племени и сможешь позаимствовать у нас обмундирование. Тогда ты узнаешь, что такое настоящая сила!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7717,'Позади меня находится алтарь Занзы, святыня Зандалара. Здесь мы молимся об укреплении нашей решимости в борьбе с кровавым богом Хаккаром.$B$BДокажите, что вы друг нашего племени – уничтожьте на алтаре все брелоки Хаккари, которые найдете в Зул\'Гурубе. Кстати, зул\'гурубские монеты я могу обменять на почетные знаки нашего народа. Приносите их мне!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Позади меня находится алтарь Занзы, святыня Зандалара. Здесь мы молимся об укреплении нашей решимости в борьбе с кровавым богом Хаккаром.$B$BДокажите, что вы друг нашего племени – уничтожьте на алтаре все брелоки Хаккари, которые найдете в Зул\'Гурубе. Кстати, зул\'гурубские монеты я могу обменять на почетные знаки нашего народа. Приносите их мне!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (7718,'Зандаларские тролли прошли долгий путь и перенесли немало тягот, чтобы добраться сюда, но не сделали ничего… что бы могло навлечь на нас такую судьбу.','Зандаларские тролли прошли долгий путь и перенесли немало тягот, чтобы добраться сюда, но не сделали ничего… что бы могло навлечь на нас такую судьбу.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Зандаларские тролли прошли долгий путь и перенесли немало тягот, чтобы добраться сюда, но не сделали ничего… что бы могло навлечь на нас такую судьбу.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Зандаларские тролли прошли долгий путь и перенесли немало тягот, чтобы добраться сюда, но не сделали ничего… что бы могло навлечь на нас такую судьбу.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7720,'Мы, зандаларские тролли, прибыли сюда с далеких островов, потому что не можем оставаться равнодушными к угрозе, нависшей над нашим миром.$B$BПредводитель нашей экспедиции, Молтор, привел нас на остров Йоджамба у северных берегов Тернистой долины. Сейчас он набирает героев для похода в древний город троллей… в Зул\'Гуруб.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы, зандаларские тролли, прибыли сюда с далеких островов, потому что не можем оставаться равнодушными к угрозе, нависшей над нашим миром.$B$BПредводитель нашей экспедиции, Молтор, привел нас на остров Йоджамба у северных берегов Тернистой долины. Сейчас он набирает героев для похода в древний город троллей… в Зул\'Гуруб.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7721,'Мы, зандаларские тролли, прибыли сюда с далеких островов, потому что не можем оставаться равнодушными к угрозе, нависшей над нашим миром.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы, зандаларские тролли, прибыли сюда с далеких островов, потому что не можем оставаться равнодушными к угрозе, нависшей над нашим миром.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7723,'Я – Резерфорд Оттяжка, главный поставщик Осквернителей Низины Арати. Если согласитесь стать нам $gдобрым соседом:доброй соседкой;, сможете покупать у меня товары и чинить поломки.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я – Резерфорд Оттяжка, главный поставщик Осквернителей Низины Арати. Если согласитесь стать нам $gдобрым соседом:доброй соседкой;, сможете покупать у меня товары и чинить поломки.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7724,'Я Самуэль Хок, главный снабженец Лиги Аратора в Низине Арати. Когда ты завоюешь наше доверие, я предложу тебе разнообразные полезные товары. Кроме того, я могу чинить твое снаряжение.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я Самуэль Хок, главный снабженец Лиги Аратора в Низине Арати. Когда ты завоюешь наше доверие, я предложу тебе разнообразные полезные товары. Кроме того, я могу чинить твое снаряжение.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7725,'Битва за Ущелье Песни Войны не из тех, что мы можем позволить себе проиграть. Мы бьемся за нашу честь и нашу землю, и ни орки, ни их заблудшие союзники не отнимут их у нас!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Битва за Ущелье Песни Войны не из тех, что мы можем позволить себе проиграть. Мы бьемся за нашу честь и нашу землю, и ни орки, ни их заблудшие союзники не отнимут их у нас!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7726,'Защищать лесозаготовки Орды в Ясеневом лесу не так-то просто, но мы никогда не боялись войны. Смерть ночным эльфам и их союзникам!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Защищать лесозаготовки Орды в Ясеневом лесу не так-то просто, но мы никогда не боялись войны. Смерть ночным эльфам и их союзникам!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7728,'Я поставляю сюда разные предметы, необходимые для колдовства и алхимии.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я поставляю сюда разные предметы, необходимые для колдовства и алхимии.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7729,'Великое зло пробудилось, |3-6($r). Ты чувствуешь?$B$BХа! Конечно же нет! Давай твои доспехи и оружие, и я приведу их в норму.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Великое зло пробудилось, |3-6($r). Ты чувствуешь?$B$BХа! Конечно же нет! Давай твои доспехи и оружие, и я приведу их в норму.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7730,'Ох, у меня опасно мало сырья! Где этого проклятого гоблина носит столько времени?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ох, у меня опасно мало сырья! Где этого проклятого гоблина носит столько времени?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7732,'Почему сейчас, |3-6($r)? Я не понимаю. Еще ведь столько работы…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Почему сейчас, |3-6($r)? Я не понимаю. Еще ведь столько работы…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7733,'Наш командир последнее время сам не свой. Его любимая поехала в археологическую экспедицию в южную пустыню – и там исчезла без следа! Очень странная история.$B$BА ты, небось, работу ищешь? Тебя огреть по голове, или ты сам намек понял?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Наш командир последнее время сам не свой. Его любимая поехала в археологическую экспедицию в южную пустыню – и там исчезла без следа! Очень странная история.$B$BА ты, небось, работу ищешь? Тебя огреть по голове, или ты сам намек понял?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7734,'Слышите? С каждым днем это гудение становится громче. Наверное, кристаллы сводят жуков с ума.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Слышите? С каждым днем это гудение становится громче. Наверное, кристаллы сводят жуков с ума.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7736,'Бронзобород опять исчез! У этого дворфа нет никакого здравомыслия, в отличие от его брата.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Бронзобород опять исчез! У этого дворфа нет никакого здравомыслия, в отличие от его брата.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7737,'Пепел горящего Плетеного человека излучает магическую энергию.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Пепел горящего Плетеного человека излучает магическую энергию.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7738,'Пепел от горящего Плетеного человека излучает магическую силу. Вы уже нанесли этот пепел на свое лицо.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Пепел от горящего Плетеного человека излучает магическую силу. Вы уже нанесли этот пепел на свое лицо.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`) VALUES (7739,'Счастливого Тыквовина, |3-6($c)!','Любите конфетки? Я вот люблю.','Вперед, Отрекшиеся! Ура!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Счастливого Тыквовина, |3-6($c)!',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Любите конфетки? Я вот люблю.',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Вперед, Отрекшиеся! Ура!',`text2_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7741,'Эй, ты! Я смотрю, ты выглядишь довольно $gсильным:сильной;… Нам нужна твоя помощь в обороне Южнобережья!$b$bПроклятые Отрекшиеся разбушевались из-за своего Тыквовина и скоро припрутся со своим "праздником" прямо сюда. Если у тебя есть время, помоги нам!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эй, ты! Я смотрю, ты выглядишь довольно $gсильным:сильной;… Нам нужна твоя помощь в обороне Южнобережья!$b$bПроклятые Отрекшиеся разбушевались из-за своего Тыквовина и скоро припрутся со своим "праздником" прямо сюда. Если у тебя есть время, помоги нам!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7742,'Первый удар должны нанести мы. Не стоит повторять прошлые ошибки…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Первый удар должны нанести мы. Не стоит повторять прошлые ошибки…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (7744,'Прочь, безбожник! Чтоб тебя Бездна поглотила!','Прочь, безбожник! Чтоб тебя Бездна поглотила!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Прочь, безбожник! Чтоб тебя Бездна поглотила!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Прочь, безбожник! Чтоб тебя Бездна поглотила!',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7748,'Дезертира из Сумеречного Молота так и не нашли? Проверьте горы к юго-востоку отсюда. Ходят слухи, что там видели некоего таинственного отшельника.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Дезертира из Сумеречного Молота так и не нашли? Проверьте горы к юго-востоку отсюда. Ходят слухи, что там видели некоего таинственного отшельника.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (7749,'Как ты смеешь обращаться к герцогу Совета, ничтожество?!','Как ты смеешь обращаться к герцогу Совета, ничтожество?!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Как ты смеешь обращаться к герцогу Совета, ничтожество?!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Как ты смеешь обращаться к герцогу Совета, ничтожество?!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7752,'Эй, спасибо, что спасли мою шкуру! Я пока что отсижусь в тишине, пока силы не восстановятся.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эй, спасибо, что спасли мою шкуру! Я пока что отсижусь в тишине, пока силы не восстановятся.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7753,'Кто ты? Где я? Я чувствую себя таким… слабым…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Кто ты? Где я? Я чувствую себя таким… слабым…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (7754,'Что за червь явился пред очи лордов Совета? Этот червь, разумеется, хочет быть раздавленным!','Что за червь явился пред очи Совета? Этот червь, разумеется, хочет быть раздавленным!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что за червь явился пред очи лордов Совета? Этот червь, разумеется, хочет быть раздавленным!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Что за червь явился пред очи Совета? Этот червь, разумеется, хочет быть раздавленным!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7760,'Как это – что значит? Она сдурела! Взяла да и накинулась на нас. Я вообще девушек не бью, но после того как очнулся, я был очень зол! Бранн, Рутгар, я и обезьяна – мы все были на нее злы, как орки! Не знаю уж, как нам удалось ее выгнать. Она как одержимая была!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Как это – что значит? Она сдурела! Взяла да и накинулась на нас. Я вообще девушек не бью, но после того как очнулся, я был очень зол! Бранн, Рутгар, я и обезьяна – мы все были на нее злы, как орки! Не знаю уж, как нам удалось ее выгнать. Она как одержимая была!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7761,'Кто знает? Во всяком случае, после этого я ее не видел. Может, Франкал что еще расскажет.$B$BНе хочу, конечно, отклоняться от темы – у тебя ведь важное задание от командира, но мы столкнулись с очень серьезным противником. Мы просили войско у Стальгорна, но от нас просто отмахнулись. Видимо, мы слишком рассредоточили силы, обороняя наши земли, или что-то в этом духе. Когда доложишь обо всем командиру, захвати товарищей и возвращайся сюда. Нам нужна твоя помощь!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Кто знает? Во всяком случае, после этого я ее не видел. Может, Франкал что еще расскажет.$B$BНе хочу, конечно, отклоняться от темы – у тебя ведь важное задание от командира, но мы столкнулись с очень серьезным противником. Мы просили войско у Стальгорна, но от нас просто отмахнулись. Видимо, мы слишком рассредоточили силы, обороняя наши земли, или что-то в этом духе. Когда доложишь обо всем командиру, захвати товарищей и возвращайся сюда. Нам нужна твоя помощь!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7762,'Ох, брат, только не это… Присаживайся, $gсынок:девчушка;.$B$BЯ уверен, что Рутгар уже кое-что рассказал тебе об этом, потому не стану докучать нудными подробностями и перейду сразу к сути.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ох, брат, только не это… Присаживайся, $gсынок:девчушка;.$B$BЯ уверен, что Рутгар уже кое-что рассказал тебе об этом, потому не стану докучать нудными подробностями и перейду сразу к сути.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7763,'Ну ладно! Так вот, Госпожа вернулась во второй раз в улей, но Бранн не болтал этой ерунды! Перед тем как завязалась схватка, она начала говорить с кем-то или с чем-то. Хуже того, она стала петь о чем-то на языке, которого никто из нас никогда не слышал.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ну ладно! Так вот, Госпожа вернулась во второй раз в улей, но Бранн не болтал этой ерунды! Перед тем как завязалась схватка, она начала говорить с кем-то или с чем-то. Хуже того, она стала петь о чем-то на языке, которого никто из нас никогда не слышал.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7765,'Послушай, $gсынок:дочка;, я хочу тебе сказать, что тварь, которая на нас напала, была никакая не жрица! Ее глаза горели злом, а изо рта шла пена! Она вошла, издала какой-то безумный крик, от которого мы кинулись врассыпную, а потом у нас мозги пошли вразнос. Я слышал у себя в голове темные слова и видел, как другие теряли сознание. Это было безумие! Мы бы все погибли, если бы не эта проклятая обезьяна.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Послушай, $gсынок:дочка;, я хочу тебе сказать, что тварь, которая на нас напала, была никакая не жрица! Ее глаза горели злом, а изо рта шла пена! Она вошла, издала какой-то безумный крик, от которого мы кинулись врассыпную, а потом у нас мозги пошли вразнос. Я слышал у себя в голове темные слова и видел, как другие теряли сознание. Это было безумие! Мы бы все погибли, если бы не эта проклятая обезьяна.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7766,'А что тут спрашивать? Он же обезьяна, придурок. Так или иначе, он взбесился, как только старина Бранн шмякнулся лицом в песок. В общем, Глибб разделал эту ночную эльфийку под орех.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','А что тут спрашивать? Он же обезьяна, придурок. Так или иначе, он взбесился, как только старина Бранн шмякнулся лицом в песок. В общем, Глибб разделал эту ночную эльфийку под орех.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7767,'Тогда я вам вот что скажу. Она побежала прямо в улей. И знаете, что еще? Ни один жук не встал у нее на пути и не попытался остановить ее. Она пробежала прямо через них, словно они сто лет как друзья!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тогда я вам вот что скажу. Она побежала прямо в улей. И знаете, что еще? Ни один жук не встал у нее на пути и не попытался остановить ее. Она пробежала прямо через них, словно они сто лет как друзья!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7768,'Угу.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Угу.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7770,'Кристалл покрыт замысловатыми знаками и рунами. Тебе они кажутся совершенно бессмысленными.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Кристалл покрыт замысловатыми знаками и рунами. Тебе они кажутся совершенно бессмысленными.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (7771,'Тихий шепот доносится из камня… $b$bПривет, $gмалыш:малышка;. Есть новости для храмовника?','Изнутри камня доносится тихий шепот…$b$bПривет, $gмалыш:малышка;. Есть новости для храмовника?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тихий шепот доносится из камня… $b$bПривет, $gмалыш:малышка;. Есть новости для храмовника?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Изнутри камня доносится тихий шепот…$b$bПривет, $gмалыш:малышка;. Есть новости для храмовника?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (7772,'Из камня доносится звонкий голос... $B$BГде твой статусный медальон, $gмалыш: малышка;? Ты сможешь поговорить с герцогом, лишь подтвердив свой титул...','Где твой статусный медальон, $gмалыш: малышка;? Ты сможешь поговорить с герцогом, лишь подтвердив свой титул...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Из камня доносится звонкий голос... $B$BГде твой статусный медальон, $gмалыш: малышка;? Ты сможешь поговорить с герцогом, лишь подтвердив свой титул...',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Где твой статусный медальон, $gмалыш: малышка;? Ты сможешь поговорить с герцогом, лишь подтвердив свой титул...',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (7773,'Из камня доносится ясный голос… $b$bТы $gпришел:пришла; к нам по праву, и мы выслушаем тебя. Но не испытывай наше терпение, |3-6($c). У Совета нет времени на праздную болтовню с такими, как ты.','Ты $gпришел:пришла; к нам по праву, и мы выслушаем тебя. Но не испытывай наше терпение, |3-6($c). У Совета нет времени на праздную болтовню с такими, как ты.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Из камня доносится ясный голос… $b$bТы $gпришел:пришла; к нам по праву, и мы выслушаем тебя. Но не испытывай наше терпение, |3-6($c). У Совета нет времени на праздную болтовню с такими, как ты.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты $gпришел:пришла; к нам по праву, и мы выслушаем тебя. Но не испытывай наше терпение, |3-6($c). У Совета нет времени на праздную болтовню с такими, как ты.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (7776,'Из камня раздается громоподобный голос…$B$BЧто это? Тут шныряет ничтожный служитель культа! Беги прочь, тварь, или ощути гнев лордов Совета!','Из камня раздается громоподобный голос…$B$BЧто это? Тут шныряет ничтожный служитель культа! Беги прочь, тварь, или ощути гнев лордов Совета!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Из камня раздается громоподобный голос…$B$BЧто это? Тут шныряет ничтожный служитель культа! Беги прочь, тварь, или ощути гнев лордов Совета!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Из камня раздается громоподобный голос…$B$BЧто это? Тут шныряет ничтожный служитель культа! Беги прочь, тварь, или ощути гнев лордов Совета!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (7778,'Куда бы вы хотели слетать?','Куда бы вы хотели слетать?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Куда бы вы хотели слетать?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Куда бы вы хотели слетать?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7779,'Духи Силитуса взывают к нам, $n. Земля рыдает, ибо наша история очень и очень печальна…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Духи Силитуса взывают к нам, $n. Земля рыдает, ибо наша история очень и очень печальна…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (7780,'Здравствуй, |3-6($c). Не тебя ли я недавно видел на одном собрании? Лицо вроде знакомое, хотя и город-то немаленький.$B$BЕсли ты там $gбыл:была;, то тебе наверняка дали секретный код. Скажи его мне, и получишь за это награду.','Здравствуй, |3-6($c). Не тебя ли я недавно видела на одном собрании? Лицо, вроде, знакомое, хотя и город-то немаленький.$B$BЕсли ты там $gбыл:была;, то тебе наверняка дали секретный код. Скажи его мне, и получишь за это награду.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здравствуй, |3-6($c). Не тебя ли я недавно видел на одном собрании? Лицо вроде знакомое, хотя и город-то немаленький.$B$BЕсли ты там $gбыл:была;, то тебе наверняка дали секретный код. Скажи его мне, и получишь за это награду.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Здравствуй, |3-6($c). Не тебя ли я недавно видела на одном собрании? Лицо, вроде, знакомое, хотя и город-то немаленький.$B$BЕсли ты там $gбыл:была;, то тебе наверняка дали секретный код. Скажи его мне, и получишь за это награду.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7783,'Призрачная фигура смотрит на тебя с недоверием и продолжает безмолвствовать.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Призрачная фигура смотрит на тебя с недоверием и продолжает безмолвствовать.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7785,'Ты можешь помочь своему народу выжить! Мы должны вместе выбраться из трясины, в которой мы увязли.$B$BЕсли ты $gготов:готова; к работе – начнем.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты можешь помочь своему народу выжить! Мы должны вместе выбраться из трясины, в которой мы увязли.$B$BЕсли ты $gготов:готова; к работе – начнем.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7786,'Знание – это сила, ИСТИННАЯ сила, $gмой юный друг:моя юная подруга;. Всегда нужно стремиться к новым знаниям и с уважением относиться к тем, кто знает больше тебя.$B$BДо уничтожения Солнечного Колодца мы наивно полагали, что наша цивилизация достигла высшей точки своего развития. Но Плеть сумела поставить нас на колени… и, в каком-то смысле, вернуть к реальности.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Знание – это сила, ИСТИННАЯ сила, $gмой юный друг:моя юная подруга;. Всегда нужно стремиться к новым знаниям и с уважением относиться к тем, кто знает больше тебя.$B$BДо уничтожения Солнечного Колодца мы наивно полагали, что наша цивилизация достигла высшей точки своего развития. Но Плеть сумела поставить нас на колени… и, в каком-то смысле, вернуть к реальности.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7787,'Ты $gзастал:застала; меня в важнейший момент моих исследований! В принципе, я ничего не имею против твоей компании… если только ты будешь вести себя тихо.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты $gзастал:застала; меня в важнейший момент моих исследований! В принципе, я ничего не имею против твоей компании… если только ты будешь вести себя тихо.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7788,'Если ты направляешься в город, у меня есть для тебя поручение!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Если ты направляешься в город, у меня есть для тебя поручение!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7792,'Здравствуйте, |3-6($c)! Добро пожаловать на ярмарку Новолуния! Здесь у нас столько всего, что у новичков иногда разбегаются глаза, и они не знают, что делать. Поэтому мне поручено помогать им. У вас есть какие-нибудь вопросы?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Здравствуйте, |3-6($c)! Добро пожаловать на ярмарку Новолуния! Здесь у нас столько всего, что у новичков иногда разбегаются глаза, и они не знают, что делать. Поэтому мне поручено помогать им. У вас есть какие-нибудь вопросы?',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7793,'Отличный вопрос! Мы продаем столько всяких разностей, что их все и за день не перечислишь. Если тебя мучает голод или жажда – у Стомпа и Силаннии есть то, что надо.$b$bЕсли тебя интересуют разномастные экзотические штуковины – обратись к Лахре. У нее отличный выбор иноземных диковинок!$b$bНу а Флик – если ты его поймаешь, конечно – продает метательные шары. У него же ты можешь обзавестись лягушкой-питомцем.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Отличный вопрос! Мы продаем столько всяких разностей, что их все и за день не перечислишь. Если тебя мучает голод или жажда – у Стомпа и Силаннии есть то, что надо.$b$bЕсли тебя интересуют разномастные экзотические штуковины – обратись к Лахре. У нее отличный выбор иноземных диковинок!$b$bНу а Флик – если ты его поймаешь, конечно – продает метательные шары. У него же ты можешь обзавестись лягушкой-питомцем.',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7794,'О, купоны? Призовые купоны нашей ярмарки служат для обмена на различные призы и подарки. Купоны можно получить, выполняя ежемесячные задания или играя в различные игры на ярмарке. Конечно, выполнение ежемесячных заданий принесет вам больше всего купонов, но и ежедневное участие в играх – тоже неплохой способ их заработать. Набранные вами купоны можно в любой момент обменять на подарки и призы у продавцов на нашей ярмарке.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','О, купоны? Призовые купоны нашей ярмарки служат для обмена на различные призы и подарки. Купоны можно получить, выполняя ежемесячные задания или играя в различные игры на ярмарке. Конечно, выполнение ежемесячных заданий принесет вам больше всего купонов, но и ежедневное участие в играх – тоже неплохой способ их заработать. Набранные вами купоны можно в любой момент обменять на подарки и призы у продавцов на нашей ярмарке.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7795,'О происхождении карт Новолуния достоверно ничего не известно, как, впрочем, и об их истинном предназначении. Но могу сказать, что их можно найти в самых разных уголках Азерота – как правило, у всяких злодеев, которые пытаются разгадать их тайну.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','О происхождении карт Новолуния достоверно ничего не известно, как, впрочем, и об их истинном предназначении. Но могу сказать, что их можно найти в самых разных уголках Азерота – как правило, у всяких злодеев, которые пытаются разгадать их тайну.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7801,'Приветствую тебя, путник. Это случилось здесь примерно 1000 лет назад, когда киражи начали свой марш уничтожения по всему Калимдору.$B$BТысячи погибли в той войне, и большинство – в этой проклятой пустыне в начале войны.$B$BЯ – одна из той горстки выживших, связанная с настоящим и прошлым. Я не знаю, почему все еще нахожусь здесь, но знаю, что обязана здесь быть.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Приветствую тебя, путник. Это случилось здесь примерно 1000 лет назад, когда киражи начали свой марш уничтожения по всему Калимдору.$B$BТысячи погибли в той войне, и большинство – в этой проклятой пустыне в начале войны.$B$BЯ – одна из той горстки выживших, связанная с настоящим и прошлым. Я не знаю, почему все еще нахожусь здесь, но знаю, что обязана здесь быть.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7802,'Меня убивали сотни раз, но каждый раз я просыпаюсь здесь. Некоторые говорят, что я заколдована, а другие…') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Меня убивали сотни раз, но каждый раз я просыпаюсь здесь. Некоторые говорят, что я заколдована, а другие…',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7803,'Говорят, что я благословенна – что я вестница новой эпохи!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Говорят, что я благословенна – что я вестница новой эпохи!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7804,'Пробуждаются древние силы – силы, которых никто не видел и не ощущал в течение тысячелетий. Мир плачет, |3-6($r). Быть может, грядет новый Раскол. Болезнь, разъедающая изнутри… $b$bСкверна просачивается в наши земли. Из Сна приходят кошмары. Кошмары, губящие нас и наяву…') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Пробуждаются древние силы – силы, которых никто не видел и не ощущал в течение тысячелетий. Мир плачет, |3-6($r). Быть может, грядет новый Раскол. Болезнь, разъедающая изнутри… $b$bСкверна просачивается в наши земли. Из Сна приходят кошмары. Кошмары, губящие нас и наяву…',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7805,'Счастливого Тыквовина! Тебе нравится моя маска? Правда, страшная?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Счастливого Тыквовина! Тебе нравится моя маска? Правда, страшная?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7806,'Счастливого Тыквовина! Как вам моя маска? Страшная, да?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Счастливого Тыквовина! Как вам моя маска? Страшная, да?',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7813,'Ты хочешь сказать, чего НЕЛЬЗЯ делать?!$B$BХозяева таверн по всему миру раздают угощения, а жители городов украшают их к празднику! Еще сержанту Дыгалу в Южнобережье нужна помощь в борьбе с Отрекшимися и их фестивалем Плетеного человека.$B$BДа, и еще. Говорят, больной малыш из приюта Штормграда ищет, кто бы помог ему собрать угощение к празднику.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты хочешь сказать, чего НЕЛЬЗЯ делать?!$B$BХозяева таверн по всему миру раздают угощения, а жители городов украшают их к празднику! Еще сержанту Дыгалу в Южнобережье нужна помощь в борьбе с Отрекшимися и их фестивалем Плетеного человека.$B$BДа, и еще. Говорят, больной малыш из приюта Штормграда ищет, кто бы помог ему собрать угощение к празднику.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7814,'Кто-то зовет меня… Бесенок?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Кто-то зовет меня… Бесенок?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7816,'Уходи сейчас же! Мне нет дела до чужаков.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Уходи сейчас же! Мне нет дела до чужаков.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7817,'Ты уже $gвернулся:вернулась;! Чем я могу тебе помочь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты уже $gвернулся:вернулась;! Чем я могу тебе помочь?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7820,'А вы занимаетесь кожевничеством, да? Этот запах выделанной кожи ни с чем не спутаешь!$b$bМой отец рассказывал об одном кожевнике-профессионале, который когда-то жил в деревне Южного Ветра. Жаль, что сейчас там все разрушено.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','А вы занимаетесь кожевничеством, да? Этот запах выделанной кожи ни с чем не спутаешь!$b$bМой отец рассказывал об одном кожевнике-профессионале, который когда-то жил в деревне Южного Ветра. Жаль, что сейчас там все разрушено.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7823,'Меди у нас уже достаточно. Спасибо за помощь, |3-6($c). Может быть, поможете и с другими материалами, которые тут собирают?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Меди у нас уже достаточно. Спасибо за помощь, |3-6($c). Может быть, поможете и с другими материалами, которые тут собирают?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7824,'$C, мне нужно больше медных слитков! У ворот Ан\'Киража вот-вот завяжется война, а у Альянса их всего $1997w. А нужно, между прочим, не меньше $1998w! Если мы не соберем достаточно этих слитков, мне голову оторвут!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','$C, мне нужно больше медных слитков! У ворот Ан\'Киража вот-вот завяжется война, а у Альянса их всего $1997w. А нужно, между прочим, не меньше $1998w! Если мы не соберем достаточно этих слитков, мне голову оторвут!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7825,'Ты видишь огромные глубокие туннели и коридоры, отраженные в кристалле. Ты узнаешь в этой местности Огненные Недра.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты видишь огромные глубокие туннели и коридоры, отраженные в кристалле. Ты узнаешь в этой местности Огненные Недра.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (7827,'Приветствую, |3-6($r). Чудесный день, чтобы остаться в живых, не так ли?','Приветствую, |3-6($r). Чудесный день, чтобы остаться в живых, не так ли?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приветствую, |3-6($r). Чудесный день, чтобы остаться в живых, не так ли?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Приветствую, |3-6($r). Чудесный день, чтобы остаться в живых, не так ли?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (7828,'Не все таурены презирают таких, как вы, |3-6($r). К сожалению, мне не положено предоставлять вам свои услуги.','Не все таурены презирают таких, как вы, |3-6($r). К сожалению, мне не положено предоставлять вам свои услуги.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не все таурены презирают таких, как вы, |3-6($r). К сожалению, мне не положено предоставлять вам свои услуги.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Не все таурены презирают таких, как вы, |3-6($r). К сожалению, мне не положено предоставлять вам свои услуги.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7829,'Слушай, пончик, мы собираемся драться не на жизнь, а на смерть с этими жуками в Ан\'Кираже, и нам нужно к этому подготовиться. Я собираю слитки железа. Сейчас у Альянса есть только $2002w слитков, но для нужд войны нам необходимо собрать $2003w.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Слушай, пончик, мы собираемся драться не на жизнь, а на смерть с этими жуками в Ан\'Кираже, и нам нужно к этому подготовиться. Я собираю слитки железа. Сейчас у Альянса есть только $2002w слитков, но для нужд войны нам необходимо собрать $2003w.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7830,'Благодаря всеобщим усилиям у нас есть все необходимые железные слитки. Поспрашивайте у других – наверняка кто-то еще собирает какие-то припасы для войны. А я постараюсь сегодня уйти пораньше и перекинуться в картишки.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Благодаря всеобщим усилиям у нас есть все необходимые железные слитки. Поспрашивайте у других – наверняка кто-то еще собирает какие-то припасы для войны. А я постараюсь сегодня уйти пораньше и перекинуться в картишки.',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7832,'Спасибо за интерес, |3-6($c). Ториевых слитков у нас уже вполне достаточно. Расспросите других собирателей – вдруг им нужна ваша помощь?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Спасибо за интерес, |3-6($c). Ториевых слитков у нас уже вполне достаточно. Расспросите других собирателей – вдруг им нужна ваша помощь?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7833,'Это правда, даже удавник может быть достаточно полезен для наших нужд в приближающейся войне в Ан\'Кираже! Он используется для многих целей, как-то: делать мороженое для жарких дней под солнцем Силитуса, или для бальзама от действия некоторых липких растений, для дыхания под водой, затвердевания кожи, для ускорения, для восстановления магической силы, для многого, всего и не упомню! Я уже говорил про мороженое?$B$BНу, как бы то ни было, у меня здесь около $2047w, а всего нужно $2048w!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Это правда, даже удавник может быть достаточно полезен для наших нужд в приближающейся войне в Ан\'Кираже! Он используется для многих целей, как-то: делать мороженое для жарких дней под солнцем Силитуса, или для бальзама от действия некоторых липких растений, для дыхания под водой, затвердевания кожи, для ускорения, для восстановления магической силы, для многого, всего и не упомню! Я уже говорил про мороженое?$B$BНу, как бы то ни было, у меня здесь около $2047w, а всего нужно $2048w!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7834,'Не то чтобы я не был уверен, что ты сможешь за огромное количество лет собрать весь нужный удавник, учитывая, сколько нам нужно мороженого, но у нас, похоже, уже достаточно. Или так мне сказали. Похоже, кое-кто из других сборщиков нуждается в помощи со сбором того, чего бы они там ни собирали. Оно и понятно, ведь то, что они собирают, собирать не так весело, как удавник.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не то чтобы я не был уверен, что ты сможешь за огромное количество лет собрать весь нужный удавник, учитывая, сколько нам нужно мороженого, но у нас, похоже, уже достаточно. Или так мне сказали. Похоже, кое-кто из других сборщиков нуждается в помощи со сбором того, чего бы они там ни собирали. Оно и понятно, ведь то, что они собирают, собирать не так весело, как удавник.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7837,'Мы готовимся к войне, |3-6($c). Мы забрали все, что собирались, у силитидов и их хозяев в Ан\'Кираже. Чтобы подготовиться к битвам, мы собираем все виды припасов. Я отвечаю за сбор слез Артаса. Но мне не вполне ясно, для чего они нам нужны. Я, если хочешь знать, не желаю иметь с этим безумцем никаких дел, даже если речь идет о цветке, названном в его честь.$B$BНо я все же дочь своего отца и воин, а потому исполняю приказы. Сейчас у нас $2057w, а всего нужно собрать $2058w.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мы готовимся к войне, |3-6($c). Мы забрали все, что собирались, у силитидов и их хозяев в Ан\'Кираже. Чтобы подготовиться к битвам, мы собираем все виды припасов. Я отвечаю за сбор слез Артаса. Но мне не вполне ясно, для чего они нам нужны. Я, если хочешь знать, не желаю иметь с этим безумцем никаких дел, даже если речь идет о цветке, названном в его честь.$B$BНо я все же дочь своего отца и воин, а потому исполняю приказы. Сейчас у нас $2057w, а всего нужно собрать $2058w.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7838,'Похоже, все. У нас уже достаточно слез Артаса. Расспроси остальных собирателей. Наверняка кому-то из них пригодится твоя помощь.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Похоже, все. У нас уже достаточно слез Артаса. Расспроси остальных собирателей. Наверняка кому-то из них пригодится твоя помощь.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7840,'Война в Ан\'Кираже скоро начнется, |3-6($c). Для подготовки к ней Альянс попросил мою семью собрать побольше легкой кожи. Всего ее нужно $2061w, а пока что есть только $2060w. Мне кажется, вы сможете нам помочь…') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Война в Ан\'Кираже скоро начнется, |3-6($c). Для подготовки к ней Альянс попросил мою семью собрать побольше легкой кожи. Всего ее нужно $2061w, а пока что есть только $2060w. Мне кажется, вы сможете нам помочь…',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7842,'Спасибо, что спросили, |3-6($c), но у нас достаточно легкой кожи. Может быть, ваша помощь нужна еще каким-нибудь собирателям?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Спасибо, что спросили, |3-6($c), но у нас достаточно легкой кожи. Может быть, ваша помощь нужна еще каким-нибудь собирателям?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7843,'$GСэр:Мэм;, есть, $gсэр:мэм;! Рядовой Портер готов помочь в сборе средней кожи. Мы должны как следует подготовиться к войне в Ан\'Кираже!$b$bДокладываю: в настоящий момент запас кожи составляет $2063w. Требуемое количество – $2064w.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','$GСэр:Мэм;, есть, $gсэр:мэм;! Рядовой Портер готов помочь в сборе средней кожи. Мы должны как следует подготовиться к войне в Ан\'Кираже!$b$bДокладываю: в настоящий момент запас кожи составляет $2063w. Требуемое количество – $2064w.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7844,'Э-э... ну... да, $gсэр:мэм;. Похоже, мы собрали всю среднюю кожу, которая требовались Альянсу для войны. Мне сказали, что ваша помощь в доставке необходимого может понадобиться еще кому-нибудь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Э-э... ну... да, $gсэр:мэм;. Похоже, мы собрали всю среднюю кожу, которая требовались Альянсу для войны. Мне сказали, что ваша помощь в доставке необходимого может понадобиться еще кому-нибудь.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7845,'Привет, |3-6($c)! Подготовка к ан\'киражской войне идет полным ходом. Я отвечаю за сбор плотной кожи. Сегодня ведь отличный день для сбора кожи, верно? Я притащила добычу сюда – похоже, у нас уже есть $2069w |4кусок:куска:кусков; кожи. А наше волшебное число – $2071w. Хочешь помочь?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Привет, |3-6($c)! Подготовка к ан\'киражской войне идет полным ходом. Я отвечаю за сбор плотной кожи. Сегодня ведь отличный день для сбора кожи, верно? Я притащила добычу сюда – похоже, у нас уже есть $2069w |4кусок:куска:кусков; кожи. А наше волшебное число – $2071w. Хочешь помочь?',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7846,'Ого! Да у нас, оказывается, уже достаточно плотной кожи. Быстро, однако! Знаете, здесь поблизости может быть кто-то еще, кому могла бы понадобиться ваша помощь.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ого! Да у нас, оказывается, уже достаточно плотной кожи. Быстро, однако! Знаете, здесь поблизости может быть кто-то еще, кому могла бы понадобиться ваша помощь.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7847,'Приветствую вас, |3-6($c). Я здесь собираю льняные бинты для войны в Ан\'Кираже. Подготовка к этой войне – испытание для всех нас, но она усилит нас в преддверии грядущих боев. Могу заверить вас, что все бинты, которые вы решите пожертвовать, будут использованы на благое дело спасения жизней наших солдат, когда придет время. Мне нужно $2077w бинтов, но пока нам удалось собрать $2076w. Вы поможете нам?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Приветствую вас, |3-6($c). Я здесь собираю льняные бинты для войны в Ан\'Кираже. Подготовка к этой войне – испытание для всех нас, но она усилит нас в преддверии грядущих боев. Могу заверить вас, что все бинты, которые вы решите пожертвовать, будут использованы на благое дело спасения жизней наших солдат, когда придет время. Мне нужно $2077w бинтов, но пока нам удалось собрать $2076w. Вы поможете нам?',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7848,'Спасибо за интерес, |3-6($c). Как ты можешь видеть, у меня уже достаточно льняных бинтов для армии Альянса в Ан\'Кираже. Но это не значит, что остальные собиратели столь же удачливы. Поговори с ними.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Спасибо за интерес, |3-6($c). Как ты можешь видеть, у меня уже достаточно льняных бинтов для армии Альянса в Ан\'Кираже. Но это не значит, что остальные собиратели столь же удачливы. Поговори с ними.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7851,'Привет, |3-6($c), как самочувствие? Надеюсь, неплохо. Должно быть, вы хотите узнать, что тут происходит. А происходит тут подготовка к войне в Ан\'Кираже. И готовимся к этой войне не только мы, но и Орда. $b$bРуководство Альянса попросило меня присмотреть за сбором шелковых бинтов. Сейчас у нас их $2082w, а всего нужно $2083w. Не хотите ли помочь?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Привет, |3-6($c), как самочувствие? Надеюсь, неплохо. Должно быть, вы хотите узнать, что тут происходит. А происходит тут подготовка к войне в Ан\'Кираже. И готовимся к этой войне не только мы, но и Орда. $b$bРуководство Альянса попросило меня присмотреть за сбором шелковых бинтов. Сейчас у нас их $2082w, а всего нужно $2083w. Не хотите ли помочь?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7852,'Очень мило с твоей стороны спросить об этом, но, похоже, у нас уже достаточно шелковых бинтов. Однако ты можешь поспрашивать, не нужна ли кому-нибудь еще твоя помощь.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Очень мило с твоей стороны спросить об этом, но, похоже, у нас уже достаточно шелковых бинтов. Однако ты можешь поспрашивать, не нужна ли кому-нибудь еще твоя помощь.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7854,'$C, благодаря всеобщим усилиям мы сумели собрать столько бинтов из рунической ткани, сколько может понадобиться Альянсу в грядущей войне. Но я бы на вашем месте расспросил остальных собирателей – возможно, кому-то из них все еще не хватает припасов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','$C, благодаря всеобщим усилиям мы сумели собрать столько бинтов из рунической ткани, сколько может понадобиться Альянсу в грядущей войне. Но я бы на вашем месте расспросил остальных собирателей – возможно, кому-то из них все еще не хватает припасов.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7856,'Мммм! Чуешь, как пахнет?! Еда тут – что надо, |3-6($c). Особенно радужный тунец. Позволь представиться – Гладень Гастрогном, кулинарных дел мастер и настоящий профи по части рыбных блюд. С приближением ан\'киражской войны Альянс счел разумным созвать экспертов, и вот я здесь, весь ваш.$B$BЧто касается запасов рыбы, сейчас цифры таковы: у нас есть $2092w из $2093w.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мммм! Чуешь, как пахнет?! Еда тут – что надо, |3-6($c). Особенно радужный тунец. Позволь представиться – Гладень Гастрогном, кулинарных дел мастер и настоящий профи по части рыбных блюд. С приближением ан\'киражской войны Альянс счел разумным созвать экспертов, и вот я здесь, весь ваш.$B$BЧто касается запасов рыбы, сейчас цифры таковы: у нас есть $2092w из $2093w.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7857,'Знаете, у нас уже достаточно тунца. Скоро мы его засолим и отправим в Ан\'Кираж. Но спасибо, что поинтересовались, $n. Если хотите, поговорите с другими собирателями. Я уверен, кому-нибудь из них наверняка пригодится ваша помощь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Знаете, у нас уже достаточно тунца. Скоро мы его засолим и отправим в Ан\'Кираж. Но спасибо, что поинтересовались, $n. Если хотите, поговорите с другими собирателями. Я уверен, кому-нибудь из них наверняка пригодится ваша помощь.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7859,'Привет, |3-6($c). Знаешь, Альянс попросил меня приехать сюда и последить за заготовкой съестных припасов для грядущих событий в Ан\'Кираже. Правда, занятно?$B$BНу, в любом случае тебе, наверное, интересно знать, сколько жареного мяса ящера у нас уже есть. При последнем подсчете у нас было $2098w, а всего нужно $2099w.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Привет, |3-6($c). Знаешь, Альянс попросил меня приехать сюда и последить за заготовкой съестных припасов для грядущих событий в Ан\'Кираже. Правда, занятно?$B$BНу, в любом случае тебе, наверное, интересно знать, сколько жареного мяса ящера у нас уже есть. При последнем подсчете у нас было $2098w, а всего нужно $2099w.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7860,'Похоже, вы опоздали, |3-6($c). У нас уже вполне достаточно жареных ящеров. Однако у других собирателей дела могут идти не столь хорошо. Вам следует поговорить с ними. А я пойду узнаю, можно ли мне наконец отправиться домой.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Похоже, вы опоздали, |3-6($c). У нас уже вполне достаточно жареных ящеров. Однако у других собирателей дела могут идти не столь хорошо. Вам следует поговорить с ними. А я пойду узнаю, можно ли мне наконец отправиться домой.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7861,'При должном уходе и снабжении даже самые тяжелые раны не означают смерти бойца. Вот так, |3-6($c). Если мы хотим победить в ан\'киражской войне, нам потребуются все припасы, которые мы сможем унести. Я вот собираю пятнистого желтохвоста.$B$BЯ уже собрал $2101w, но всего нужно $2103w, иначе мы не прокормим всю армию.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','При должном уходе и снабжении даже самые тяжелые раны не означают смерти бойца. Вот так, |3-6($c). Если мы хотим победить в ан\'киражской войне, нам потребуются все припасы, которые мы сможем унести. Я вот собираю пятнистого желтохвоста.$B$BЯ уже собрал $2101w, но всего нужно $2103w, иначе мы не прокормим всю армию.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7866,'Нам нужно очень много меди, |3-6($c). Для грядущей войны в Ан\'Кираже понадобится оружие, доспехи и еще много разной металлической всячины. Мне сказали, что одной только Орде нужно не меньше $1998w слитков меди. А у нас их только $2018w.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Нам нужно очень много меди, |3-6($c). Для грядущей войны в Ан\'Кираже понадобится оружие, доспехи и еще много разной металлической всячины. Мне сказали, что одной только Орде нужно не меньше $1998w слитков меди. А у нас их только $2018w.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7870,'Тром\'ка, |3-6($c). Ты $gпришел:пришла; помочь мне со слитками олова? Чтобы изготовить оружие и доспехи для грядущей ан\'киражской войны, их нужно не меньше $2006w, а у меня их только $2005w. Принеси мне еще!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тром\'ка, |3-6($c). Ты $gпришел:пришла; помочь мне со слитками олова? Чтобы изготовить оружие и доспехи для грядущей ан\'киражской войны, их нужно не меньше $2006w, а у меня их только $2005w. Принеси мне еще!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7875,'Капитан занят. Он изучает карты, которые мы недавно добыли в подземных ульях силитидов. Если хотите помочь – оставайтесь с нами, он может выйти в любой момент.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Капитан занят. Он изучает карты, которые мы недавно добыли в подземных ульях силитидов. Если хотите помочь – оставайтесь с нами, он может выйти в любой момент.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7876,'Эй, ты явно $gпришел:пришла;, чтобы принести мне мифриловые слитки. В этом Ан\'Кираже посреди пустыни Силитус назревает крупная заварушка. Что мы, что Альянс из шкуры лезем, чтобы только остановить этих проклятых жуков!$B$BОрде на этой войне понадобится не меньше $2009w мифриловых слитков, а у меня их всего-то $2008w. Ну что, поможешь?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Эй, ты явно $gпришел:пришла;, чтобы принести мне мифриловые слитки. В этом Ан\'Кираже посреди пустыни Силитус назревает крупная заварушка. Что мы, что Альянс из шкуры лезем, чтобы только остановить этих проклятых жуков!$B$BОрде на этой войне понадобится не меньше $2009w мифриловых слитков, а у меня их всего-то $2008w. Ну что, поможешь?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7878,'Здравствуй, $gюный:юная:c; |3-6($c). Ты хочешь принести мне немного мироцвета? Мы собираем его, чтобы делать зелья и эликсиры для воинов в Ан\'Кираже. Конечно, то, что мы вынуждены участвовать в войне, ужасно, но, если не подготовиться должным образом, все будет куда хуже.$B$BОрда поручила мне собрать побольше мироцвета, $2020w, а пока нам удалось раздобыть лишь $2021w. Если тебя это не затруднит, пожалуйста, собирай их на своем пути и приноси мне.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Здравствуй, $gюный:юная:c; |3-6($c). Ты хочешь принести мне немного мироцвета? Мы собираем его, чтобы делать зелья и эликсиры для воинов в Ан\'Кираже. Конечно, то, что мы вынуждены участвовать в войне, ужасно, но, если не подготовиться должным образом, все будет куда хуже.$B$BОрда поручила мне собрать побольше мироцвета, $2020w, а пока нам удалось раздобыть лишь $2021w. Если тебя это не затруднит, пожалуйста, собирай их на своем пути и приноси мне.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7880,'Ты хочешь причинить мне вред, |3-6($r)?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты хочешь причинить мне вред, |3-6($r)?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7881,'Мое бдение вечно, $gсмертный:смертная;.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мое бдение вечно, $gсмертный:смертная;.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7882,'Одних пассов руками для магии недостаточно… но вы ведь и сами это понимаете, да?$B$BВы пришли ко мне учиться, и я с радостью обучу вас, только слушайте внимательно и делайте все, что я говорю. Тайны демонов не предназначены для глупцов, как и мое время.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Одних пассов руками для магии недостаточно… но вы ведь и сами это понимаете, да?$B$BВы пришли ко мне учиться, и я с радостью обучу вас, только слушайте внимательно и делайте все, что я говорю. Тайны демонов не предназначены для глупцов, как и мое время.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7885,'Ищешь осколок скипетра, охраняемый синими драконами? $b$b*Азурегос словно бы улыбается.*') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ищешь осколок скипетра, охраняемый синими драконами? $b$b*Азурегос словно бы улыбается.*',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7886,'Конечно, я не ношу осколок с собой. Это было бы глупо. Тут же кругом дикари! Я и пяти шагов сделать не могу без того, чтобы какой-нибудь свихнувшийся орк или человек не попробовал ткнуть в меня чем-то острым. Тебе еще повезло, что $gвстретил:встретила; меня, а не мою бесплотную тень.$b$bКак бы там ни было… я спрятал его. $b$bНу же… спроси меня, где.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Конечно, я не ношу осколок с собой. Это было бы глупо. Тут же кругом дикари! Я и пяти шагов сделать не могу без того, чтобы какой-нибудь свихнувшийся орк или человек не попробовал ткнуть в меня чем-то острым. Тебе еще повезло, что $gвстретил:встретила; меня, а не мою бесплотную тень.$b$bКак бы там ни было… я спрятал его. $b$bНу же… спроси меня, где.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7887,'Тебе понравится мой рассказ, |3-6($r). Смотри, вот в чем дело. Когда Малигос поручил мне охранять обломок скипетра, я сразу понял, что это будет сплошная головная боль. $b$bВсе, чего мне хочется, – это изучать местную магию и выкапывать артефакты, которые могли сохраниться со времен Раскола. Ты же знаешь, здесь была процветающая цивилизация высокорожденных! Я уверен, что тут полно отличных магических предметов, |3-6($r). Я их за версту чую!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тебе понравится мой рассказ, |3-6($r). Смотри, вот в чем дело. Когда Малигос поручил мне охранять обломок скипетра, я сразу понял, что это будет сплошная головная боль. $b$bВсе, чего мне хочется, – это изучать местную магию и выкапывать артефакты, которые могли сохраниться со времен Раскола. Ты же знаешь, здесь была процветающая цивилизация высокорожденных! Я уверен, что тут полно отличных магических предметов, |3-6($r). Я их за версту чую!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7888,'Как я уже говорил, я хранил осколок этого скипетра добрых пять сотен лет, и это было сплошным мучением. Он привлекал к себе слишком много ненужного внимания. Я хочу спокойно заниматься своими делами, а не хранить чей-то будущий пропуск к славе. Поэтому… я отдал его рыбе.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Как я уже говорил, я хранил осколок этого скипетра добрых пять сотен лет, и это было сплошным мучением. Он привлекал к себе слишком много ненужного внимания. Я хочу спокойно заниматься своими делами, а не хранить чей-то будущий пропуск к славе. Поэтому… я отдал его рыбе.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7889,'Не просто рыба, смертный. Это была совершенно особенная рыба.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не просто рыба, смертный. Это была совершенно особенная рыба.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7890,'Вот именно!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вот именно!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7891,'Гений, я знаю… Ее никогда не найдут, но на тот случай, если все-таки найдут, я наделил ее особыми силами.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Гений, я знаю… Ее никогда не найдут, но на тот случай, если все-таки найдут, я наделил ее особыми силами.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7892,'Точно. А ты и правда $gслушал:слушала;! Эта рыба на самом деле – жуткое чудовище, которое создал я сам. В минуты расслабления мне нравится думать о злосчастных моряках, от которых после встречи с ней остались одни клочки. Держу пари, они были в шоке! $b$b*Азурегос смеется.*') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Точно. А ты и правда $gслушал:слушала;! Эта рыба на самом деле – жуткое чудовище, которое создал я сам. В минуты расслабления мне нравится думать о злосчастных моряках, от которых после встречи с ней остались одни клочки. Держу пари, они были в шоке! $b$b*Азурегос смеется.*',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7893,'Гениев часто понимают превратно, |3-6($r). Ну а насчет обломка скипетра… Если тебе нужен этот обломок и ты не хочешь разыскивать его ближайшие десять тысяч лет, слушай очень внимательно.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Гениев часто понимают превратно, |3-6($r). Ну а насчет обломка скипетра… Если тебе нужен этот обломок и ты не хочешь разыскивать его ближайшие десять тысяч лет, слушай очень внимательно.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7894,'Только два слова: арканитовый буй.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Только два слова: арканитовый буй.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7895,'Ну, ладно… Тебе нужно сделать буй из арканита и поместить его в океан. Эманации магии привлекут мою рыбку. Когда она подплывет поближе к бую – БАБАХ! Она взорвется в сиянии магической энергии и примет свой истинный облик. Правда, это может разгневать Нептулона – а может и не разгневать. Я бы сказал, твои шансы – пятьдесят на пятьдесят.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ну, ладно… Тебе нужно сделать буй из арканита и поместить его в океан. Эманации магии привлекут мою рыбку. Когда она подплывет поближе к бую – БАБАХ! Она взорвется в сиянии магической энергии и примет свой истинный облик. Правда, это может разгневать Нептулона – а может и не разгневать. Я бы сказал, твои шансы – пятьдесят на пятьдесят.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7896,'Если бы я знал чуть меньше, то решил бы, что ты надо мной насмехаешься, $gсмертный:смертная;. Но я знаю, что в целом ты $gправ:права;. Можешь оставаться $gодетым:одетой;.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если бы я знал чуть меньше, то решил бы, что ты надо мной насмехаешься, $gсмертный:смертная;. Но я знаю, что в целом ты $gправ:права;. Можешь оставаться $gодетым:одетой;.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7899,'Будь $gосторожен, смертный:осторожна, смертная;. Ты вступаешь туда, где встретили свою смерть и более могущественные создания.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Будь $gосторожен, смертный:осторожна, смертная;. Ты вступаешь туда, где встретили свою смерть и более могущественные создания.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7901,'А разве вы не спасаете мир?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','А разве вы не спасаете мир?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (7903,'Мы идем разными путями. Ступай учиться в другое место, |3-6($c).','Мы идем разными путями. Ступай учиться в другое место, |3-6($c).') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы идем разными путями. Ступай учиться в другое место, |3-6($c).',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мы идем разными путями. Ступай учиться в другое место, |3-6($c).',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7905,'Хе-хе, как делишки? Пелекейки думает, что ты можешь помочь ему в одном важном деле. Нам нужна целая куча огнецвета для ан\'киражской войны. Орда говорит: "Пелекейки, а принеси-ка нам не меньше $2051w лепестков огнецвета".$B$BА у Пелекейки их всего $2050w. Но ведь ты принесешь еще, а?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Хе-хе, как делишки? Пелекейки думает, что ты можешь помочь ему в одном важном деле. Нам нужна целая куча огнецвета для ан\'киражской войны. Орда говорит: "Пелекейки, а принеси-ка нам не меньше $2051w лепестков огнецвета".$B$BА у Пелекейки их всего $2050w. Но ведь ты принесешь еще, а?',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7907,'А, вот и ты. Мне было сказано обратиться за помощью, потому слушай, пожалуйста, внимательно. Дело вот в чем: мне было поручено собрать не менее $2055w цветков лилового лотоса для будущей войны в Ан\'Кираже. Сейчас у нас есть только $2054w.$B$BВообще-то собирать цветы – самое подходящее занятие для таких, как ты. А я нужна здесь, чтобы следить за припасами и изобретать новые способы их применения против силитидов.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','А, вот и ты. Мне было сказано обратиться за помощью, потому слушай, пожалуйста, внимательно. Дело вот в чем: мне было поручено собрать не менее $2055w цветков лилового лотоса для будущей войны в Ан\'Кираже. Сейчас у нас есть только $2054w.$B$BВообще-то собирать цветы – самое подходящее занятие для таких, как ты. А я нужна здесь, чтобы следить за припасами и изобретать новые способы их применения против силитидов.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7909,'Вы здесь, чтобы помочь со сбором тяжелой кожи для войны в Ан\'Кираже, да, |3-6($c)? Хорошо, хорошо. Как видите, у меня уже есть $2066w, но всего нужно $2067w. Это немало, и, я надеюсь, ваш нож не затупится. Собранная кожа пойдет на самые разные цели и, надеюсь, поможет нам выиграть войну.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Вы здесь, чтобы помочь со сбором тяжелой кожи для войны в Ан\'Кираже, да, |3-6($c)? Хорошо, хорошо. Как видите, у меня уже есть $2066w, но всего нужно $2067w. Это немало, и, я надеюсь, ваш нож не затупится. Собранная кожа пойдет на самые разные цели и, надеюсь, поможет нам выиграть войну.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7912,'Лок\'тар, |3-6($c), у меня важные сведения! В Ан\'Кираже грядет война и мы должны к ней готовиться. Я здесь собираю всю плотную кожу, какую только могу достать. Сейчас ее у нас $2070w, но Вождь поручил мне собрать $2071w. Как видишь, немного не хватает.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Лок\'тар, |3-6($c), у меня важные сведения! В Ан\'Кираже грядет война и мы должны к ней готовиться. Я здесь собираю всю плотную кожу, какую только могу достать. Сейчас ее у нас $2070w, но Вождь поручил мне собрать $2071w. Как видишь, немного не хватает.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7914,'Привет, |3-6($c). Надеюсь, ты $gпринес:принесла; хорошие новости о подготовке к ан\'киражской войне. Лично мне поручили собирать прочную кожу для нужд Орды. Я на редкость хорошо подхожу для этой задачи. Никогда нельзя недооценивать пользу острого ножа. $B$BЧто же касается прочной кожи, наш запас составляет уже $2073w, а всего нужно $2074w.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Привет, |3-6($c). Надеюсь, ты $gпринес:принесла; хорошие новости о подготовке к ан\'киражской войне. Лично мне поручили собирать прочную кожу для нужд Орды. Я на редкость хорошо подхожу для этой задачи. Никогда нельзя недооценивать пользу острого ножа. $B$BЧто же касается прочной кожи, наш запас составляет уже $2073w, а всего нужно $2074w.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7918,'А, |3-6($c), рад видеть тебя. Нам нужна помощь в сборе ресурсов в рамках подготовки к неизбежной войне в Ан\'Кираже. Меня попросили собрать множество полевых наборов, и главное, что мне нужно – это шерстяные бинты. У меня уже есть немного, $2079w, если быть точным, но мне требуется собрать $2080w.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','А, |3-6($c), рад видеть тебя. Нам нужна помощь в сборе ресурсов в рамках подготовки к неизбежной войне в Ан\'Кираже. Меня попросили собрать множество полевых наборов, и главное, что мне нужно – это шерстяные бинты. У меня уже есть немного, $2079w, если быть точным, но мне требуется собрать $2080w.',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7920,'Здравствуй, |3-6($c), хорошо, что здесь. Буду кратка; мы собираем припасы для наших войск в Ан\'Кираже. Нам ведь не нужны лишние жертвы войны, верно? Я руковожу сбором бинтов из магической ткани – мне нужно $2086w. Сейчас у нас собрано $2085w. Не желаешь помочь?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Здравствуй, |3-6($c), хорошо, что здесь. Буду кратка; мы собираем припасы для наших войск в Ан\'Кираже. Нам ведь не нужны лишние жертвы войны, верно? Я руковожу сбором бинтов из магической ткани – мне нужно $2086w. Сейчас у нас собрано $2085w. Не желаешь помочь?',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7923,'Мать-Земля помогает своим детям, но временами |3-2($c) недостаточно этой помощи. Поэтому я собираю бинты из рунической ткани для подготовки к войне в Ан\'Кираже. Сейчас у нас есть $2089w из $2090w бинтов.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мать-Земля помогает своим детям, но временами |3-2($c) недостаточно этой помощи. Поэтому я собираю бинты из рунической ткани для подготовки к войне в Ан\'Кираже. Сейчас у нас есть $2089w из $2090w бинтов.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7924,'Очень мило с вашей стороны заботиться о нас, |3-6($c). Но, оказывается, у нас уже достаточно бинтов из рунической ткани для этой войны. Не будете ли вы любезны расспросить других собирателей и предложить им свою помощь? Да хранят вас предки.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Очень мило с вашей стороны заботиться о нас, |3-6($c). Но, оказывается, у нас уже достаточно бинтов из рунической ткани для этой войны. Не будете ли вы любезны расспросить других собирателей и предложить им свою помощь? Да хранят вас предки.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7925,'Чего тебе надо, |3-6($r)? А, ты, наверное, по поводу постного стейка из волчатины для войны в Ан\'Кираже. Да, тебе верно сказали, я их собираю, и что? У тебя они с собой? Их нам нужно не меньше $2096w, а у меня всего $2095w.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Чего тебе надо, |3-6($r)? А, ты, наверное, по поводу постного стейка из волчатины для войны в Ан\'Кираже. Да, тебе верно сказали, я их собираю, и что? У тебя они с собой? Их нам нужно не меньше $2096w, а у меня всего $2095w.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7927,'Эй, $gприятель:подруга;, я тут собираю всякую рыбу для Орды. Они готовятся к большой войне в пустыне – в Ан\'Кираже, и им нужно не меньше $2103w пятнистых желтохвостов. А у меня их всего-то $2102w. Может, выручишь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эй, $gприятель:подруга;, я тут собираю всякую рыбу для Орды. Они готовятся к большой войне в пустыне – в Ан\'Кираже, и им нужно не меньше $2103w пятнистых желтохвостов. А у меня их всего-то $2102w. Может, выручишь?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7929,'Здравствуй, |3-6($c). Приятно видеть, что ты хочешь помочь с подготовкой к войне. Сейчас собиратели организуют сбор различных припасов, чтобы, когда настанет час, мы были готовы.$B$BМне поручено добыть печеного лосося, чтобы наши воины в Ан\'Кираже всегда были сыты. Всего нужно $2106w, а сейчас у нас есть только $2105w.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здравствуй, |3-6($c). Приятно видеть, что ты хочешь помочь с подготовкой к войне. Сейчас собиратели организуют сбор различных припасов, чтобы, когда настанет час, мы были готовы.$B$BМне поручено добыть печеного лосося, чтобы наши воины в Ан\'Кираже всегда были сыты. Всего нужно $2106w, а сейчас у нас есть только $2105w.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7933,'Новый год наступил, в небе ярко светит луна.$B$BЭто наше время… время, когда пробуждаются древние.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Новый год наступил, в небе ярко светит луна.$B$BЭто наше время… время, когда пробуждаются древние.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (7935,'Когда-то в давние времена мы жили охотой. Мы охотились ради славы, ради чести…$B$BНеужели все так изменилось?','Когда-то в давние времена мы жили охотой. Мы охотились ради славы, ради чести…$B$BНеужели все так изменилось?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Когда-то в давние времена мы жили охотой. Мы охотились ради славы, ради чести…$B$BНеужели все так изменилось?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Когда-то в давние времена мы жили охотой. Мы охотились ради славы, ради чести…$B$BНеужели все так изменилось?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7937,'Все твои попытки изучить драконий язык тщетны, $gсмертный:смертная;. Да и зачем тебе вдруг понадобилось это древнее наречие? Напрасный труд…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Все твои попытки изучить драконий язык тщетны, $gсмертный:смертная;. Да и зачем тебе вдруг понадобилось это древнее наречие? Напрасный труд…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7944,'Сколько слитков, говоришь? Вот что мне известно по последним сводкам Орды. Медные слитки – $2018w из $1998w, оловянные – $2005w из $2006w, мифриловые – $2009w из $2008w.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Сколько слитков, говоришь? Вот что мне известно по последним сводкам Орды. Медные слитки – $2018w из $1998w, оловянные – $2005w из $2006w, мифриловые – $2009w из $2008w.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7949,'Приветствую вас, |3-6($r). Я – командир Мощный Молот, полномочный представитель Альянса. Если у вас, $gмолодой человек:девушка;, есть вопросы об успехах Альянса в подготовке к войне, не стесняйтесь их задавать.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приветствую вас, |3-6($r). Я – командир Мощный Молот, полномочный представитель Альянса. Если у вас, $gмолодой человек:девушка;, есть вопросы об успехах Альянса в подготовке к войне, не стесняйтесь их задавать.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7952,'Посмотрим, посмотрим… Где-то у меня тут было записано. Ага, вот же. Так, удавник – $2047w из $2048w, лиловый лотос – $2053w из $2055w… И, наконец, слезы Артаса – $2057w из $2058w.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Посмотрим, посмотрим… Где-то у меня тут было записано. Ага, вот же. Так, удавник – $2047w из $2048w, лиловый лотос – $2053w из $2055w… И, наконец, слезы Артаса – $2057w из $2058w.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7953,'Забавно, что вы спросили именно сейчас… я как раз только что получил свежую сводку. К настоящему моменту в Альянсе собрали $2060w из $2061w кусков тонкой кожи, $2063w из $2064w кусков жесткой кожи и $2069w из $2071w кусков плотной кожи.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Забавно, что вы спросили именно сейчас… я как раз только что получил свежую сводку. К настоящему моменту в Альянсе собрали $2060w из $2061w кусков тонкой кожи, $2063w из $2064w кусков жесткой кожи и $2069w из $2071w кусков плотной кожи.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7954,'Бинты, говоришь? Да, ну, если мне не изменяет память, по последним сведениям, Альянс сделал: льняных бинтов – $2076w из $2077w, шелковых бинтов -$2082w из $2083w и бинтов из рунической ткани – $2088w из $2090w.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Бинты, говоришь? Да, ну, если мне не изменяет память, по последним сведениям, Альянс сделал: льняных бинтов – $2076w из $2077w, шелковых бинтов -$2082w из $2083w и бинтов из рунической ткани – $2088w из $2090w.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7955,'Это мне напомнило, что мне надо вскоре найти что-нибудь поесть. Насчет того, что готовят в Альянсе, мне сказали, что уже упаковано $2092w из $2093w радужного тунца. Кроме того, $2098w из $2099w жареного ящера и $2101w из $2103w пятнистого желтохвоста подготовлено и сейчас хранится в холодильнике, ожидая отправки в Крепость Кенария, в Силитусе.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Это мне напомнило, что мне надо вскоре найти что-нибудь поесть. Насчет того, что готовят в Альянсе, мне сказали, что уже упаковано $2092w из $2093w радужного тунца. Кроме того, $2098w из $2099w жареного ящера и $2101w из $2103w пятнистого желтохвоста подготовлено и сейчас хранится в холодильнике, ожидая отправки в Крепость Кенария, в Силитусе.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7958,'Все готово, ждем только сигнала. Припасы уже отправлены в Силитус. До их прибытия в Крепость Кенария осталось меньше $2113w дней. Вскоре после этого кто-нибудь восстановит скипетр, и война начнется.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Все готово, ждем только сигнала. Припасы уже отправлены в Силитус. До их прибытия в Крепость Кенария осталось меньше $2113w дней. Вскоре после этого кто-нибудь восстановит скипетр, и война начнется.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7960,'Эгей, мы выступаем! Все необходимые припасы уже собраны, сейчас их как раз везут в Силитус на дирижаблях. До прибытия последней партии осталось меньше $2113w дней. А потом кто-нибудь соберет скипетр – и мы начнем войну против этих грязных насекомых! Как говорится, "Вперед!"') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эгей, мы выступаем! Все необходимые припасы уже собраны, сейчас их как раз везут в Силитус на дирижаблях. До прибытия последней партии осталось меньше $2113w дней. А потом кто-нибудь соберет скипетр – и мы начнем войну против этих грязных насекомых! Как говорится, "Вперед!"',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7962,'Привет, |3-6($c). Судя по тому, что мне сказали, все припасы уже собраны – прямо сейчас их отправляют в Силитус. Не пройдет и $2113w дней, как они будут там. А потом, когда скипетр Зыбучих песков коснется гонга, начнется война.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Привет, |3-6($c). Судя по тому, что мне сказали, все припасы уже собраны – прямо сейчас их отправляют в Силитус. Не пройдет и $2113w дней, как они будут там. А потом, когда скипетр Зыбучих песков коснется гонга, начнется война.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7964,'Это все, что собрано обеими сторонами. Теперь все перевозится в Силитус и будет доставлено туда менее чем через $2113w дня. Как только с этим будет покончено и кто-то ударит в гонг на помосте Скарабея, начнется война!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Это все, что собрано обеими сторонами. Теперь все перевозится в Силитус и будет доставлено туда менее чем через $2113w дня. Как только с этим будет покончено и кто-то ударит в гонг на помосте Скарабея, начнется война!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7967,'Все готово, $gюный:юная:c; |3-6($c). Пока мы тут разговариваем, Орда и Альянс переправляют припасы в Силитус. Не пройдет и $2113w дней, как они будут в Крепости Кенария. После этого нужно ударить в гонг у ворот Ан\'Киража – и война начнется.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Все готово, $gюный:юная:c; |3-6($c). Пока мы тут разговариваем, Орда и Альянс переправляют припасы в Силитус. Не пройдет и $2113w дней, как они будут в Крепости Кенария. После этого нужно ударить в гонг у ворот Ан\'Киража – и война начнется.',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7969,'На службу $gприбыл:прибыла;, |3-6($c)? Все запасы для Орды и Альянса собраны и сейчас едут в Силитус. Они должны прибыть на место меньше чем через несколько дней – $2113w. Надеюсь, что кто-нибудь нашел части скипетра Зыбучих Песков и собрал их воедино.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','На службу $gприбыл:прибыла;, |3-6($c)? Все запасы для Орды и Альянса собраны и сейчас едут в Силитус. Они должны прибыть на место меньше чем через несколько дней – $2113w. Надеюсь, что кто-нибудь нашел части скипетра Зыбучих Песков и собрал их воедино.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7971,'Насколько я понимаю, дорогуша, все уже собрано и отправлено в Крепость Кенария. Груз прибудет через несколько дней – не меньше чем через $2113w. А когда все наши припасы и войска будут там, носитель скипетра Зыбучих Песков сможет ударить в гонг близ Ан\'Киража, чтобы открыть ворота. И тогда начнется война.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Насколько я понимаю, дорогуша, все уже собрано и отправлено в Крепость Кенария. Груз прибудет через несколько дней – не меньше чем через $2113w. А когда все наши припасы и войска будут там, носитель скипетра Зыбучих Песков сможет ударить в гонг близ Ан\'Киража, чтобы открыть ворота. И тогда начнется война.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7981,'Докладываю! Все припасы для Ан\'Киража собраны и отправлены в Крепость Кенария! Последняя порция груза прибудет туда менее чем через $2113w дня. Как только это произойдет, кто-нибудь должен ударить в этот гонг – и я гарантирую, что мы всыплем этим клопам по первое число!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Докладываю! Все припасы для Ан\'Киража собраны и отправлены в Крепость Кенария! Последняя порция груза прибудет туда менее чем через $2113w дня. Как только это произойдет, кто-нибудь должен ударить в этот гонг – и я гарантирую, что мы всыплем этим клопам по первое число!',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7984,'Здравствуйте, |3-6($c)! Похоже, Орда наконец закончила свои сборы, и теперь все припасы уже везут в Силитус. Не пройдет и $2113w дней, как они будут там, а потом кто-нибудь ударит в гонг у ворот Ан\'Киража и начнет войну.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Здравствуйте, |3-6($c)! Похоже, Орда наконец закончила свои сборы, и теперь все припасы уже везут в Силитус. Не пройдет и $2113w дней, как они будут там, а потом кто-нибудь ударит в гонг у ворот Ан\'Киража и начнет войну.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7988,'Пока мы говорим, |3-6($c), ресурсы, необходимые для войны, перевозятся в Силитус. Похоже, все они должны прибыть меньше чем через $2113w дней. И затем $gгерою:героине; нужно будет прибыть туда и ударить по гонгу на Помосте Скарабея. И тогда начнется война.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Пока мы говорим, |3-6($c), ресурсы, необходимые для войны, перевозятся в Силитус. Похоже, все они должны прибыть меньше чем через $2113w дней. И затем $gгерою:героине; нужно будет прибыть туда и ударить по гонгу на Помосте Скарабея. И тогда начнется война.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (7991,'До прибытия последней партии груза в Силитус осталось не больше $2113w дней. А потом кому-нибудь придется сделать следующий шаг – ударить в гонг на помосте Скарабея и открыть врата Ан\'Киража. Вот тогда-то наши бинты и пригодятся.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','До прибытия последней партии груза в Силитус осталось не больше $2113w дней. А потом кому-нибудь придется сделать следующий шаг – ударить в гонг на помосте Скарабея и открыть врата Ан\'Киража. Вот тогда-то наши бинты и пригодятся.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7994,'Все готово, |3-6($c). Припасы уже направляются в Силитус и будут там в течение $2113w дней. Наши объединенные силы ждут $gтого героя:ту героиню;, что соберет скипетр Зыбучих песков, ударит им в гонг и начнет ан\'киражскую войну.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Все готово, |3-6($c). Припасы уже направляются в Силитус и будут там в течение $2113w дней. Наши объединенные силы ждут $gтого героя:ту героиню;, что соберет скипетр Зыбучих песков, ударит им в гонг и начнет ан\'киражскую войну.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7997,'Эта рыба и остальное – все на пути в Силитус, и должно там оказаться меньше чем через $2113w дней. После этого кто-то должен стукнуть в гонг с помощью скипетра Зыбучих песков, чтобы начать войну.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эта рыба и остальное – все на пути в Силитус, и должно там оказаться меньше чем через $2113w дней. После этого кто-то должен стукнуть в гонг с помощью скипетра Зыбучих песков, чтобы начать войну.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (7998,'Говорят, мы собрали все, что было нужно. Теперь дело за Ордой – они тоже должны все собрать, а там уж можно отправлять припасы в Силитус и начинать войну.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Говорят, мы собрали все, что было нужно. Теперь дело за Ордой – они тоже должны все собрать, а там уж можно отправлять припасы в Силитус и начинать войну.',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8000,'Все материалы и съестные припасы, которые мы собирали здесь, уже отправлены в Силитус. Не пройдет и $2113w дней, как их доставят в Крепость Кенария. После этого кто-нибудь должен будет ударить в гонг на помосте Скарабея. Тогда врата Ан\'Киража распахнутся, и мы начнем войну.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Все материалы и съестные припасы, которые мы собирали здесь, уже отправлены в Силитус. Не пройдет и $2113w дней, как их доставят в Крепость Кенария. После этого кто-нибудь должен будет ударить в гонг на помосте Скарабея. Тогда врата Ан\'Киража распахнутся, и мы начнем войну.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8003,'Приветствую, |3-6($r). Материалы военного назначения были уже отправлены и должны прибыть в Крепость Кенария через $2113w часов. Мы можем лишь надеяться, что, как только они прибудут туда, найдется кто-то, обладающий скипетром Зыбучих песков, кто ударит по гонгу и откроет ворота.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Приветствую, |3-6($r). Материалы военного назначения были уже отправлены и должны прибыть в Крепость Кенария через $2113w часов. Мы можем лишь надеяться, что, как только они прибудут туда, найдется кто-то, обладающий скипетром Зыбучих песков, кто ударит по гонгу и откроет ворота.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8006,'Как это ни странно, но у вас тоже может быть порядок. И Альянс, и Орда уже закончили все приготовления к ан\'киражской войне. В данный момент припасы доставляются в Силитус. Не пройдет и $2113w дней, как они будут там. Потом кому-нибудь придется собрать скипетр Зыбучих песков и ударить им в гонг на помосте Скарабея. Тогда ворота Ан\'Киража распахнутся – и начнется настоящая война!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Как это ни странно, но у вас тоже может быть порядок. И Альянс, и Орда уже закончили все приготовления к ан\'киражской войне. В данный момент припасы доставляются в Силитус. Не пройдет и $2113w дней, как они будут там. Потом кому-нибудь придется собрать скипетр Зыбучих песков и ударить им в гонг на помосте Скарабея. Тогда ворота Ан\'Киража распахнутся – и начнется настоящая война!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8007,'Как и ожидалось, Орда закончила все приготовления раньше, чем ваш так называемый Альянс. Вы задерживаете всех нас, и мы не можем начать войну, пока вы не выполните своих обещаний.$B$BА теперь идите и делайте свое дело, |3-6($r).') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Как и ожидалось, Орда закончила все приготовления раньше, чем ваш так называемый Альянс. Вы задерживаете всех нас, и мы не можем начать войну, пока вы не выполните своих обещаний.$B$BА теперь идите и делайте свое дело, |3-6($r).',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8037,'Все уже собрано и отправлено в Силитус, |3-6($c). Припасы должны прибыть туда в течение $2113w дней. Остается только надеяться, что после того, как кто-нибудь ударит в гонг и начнет войну, наши усилия помогут сохранить множество жизней.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Все уже собрано и отправлено в Силитус, |3-6($c). Припасы должны прибыть туда в течение $2113w дней. Остается только надеяться, что после того, как кто-нибудь ударит в гонг и начнет войну, наши усилия помогут сохранить множество жизней.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8049,'Так, сколько дней осталось на рыбалку? $2113w? После этого все припасы отвезут в пустыню Силитуса. Затем, когда приготовления будут закончены, кто-нибудь ударит в тот гонг, что к югу от Крепости Кенария. Врата распахнутся, и начнется война.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Так, сколько дней осталось на рыбалку? $2113w? После этого все припасы отвезут в пустыню Силитуса. Затем, когда приготовления будут закончены, кто-нибудь ударит в тот гонг, что к югу от Крепости Кенария. Врата распахнутся, и начнется война.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8052,'Если ты слышал, что и Орда, и Альянс завершили сбор припасов, то это правда, |3-6($c). Все, что мы собрали и подготовили, сейчас отправляют в Силитус. Не пройдет и $2113w дней, как все припасы будут в Крепости Кенария. После этого нам надо будет просто подождать, пока кто-нибудь восстановит скипетр и ударит в гонг, чтобы открыть ворота Ан\'Киража.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если ты слышал, что и Орда, и Альянс завершили сбор припасов, то это правда, |3-6($c). Все, что мы собрали и подготовили, сейчас отправляют в Силитус. Не пройдет и $2113w дней, как все припасы будут в Крепости Кенария. После этого нам надо будет просто подождать, пока кто-нибудь восстановит скипетр и ударит в гонг, чтобы открыть ворота Ан\'Киража.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8059,'Мы служим Траллу с гордостью. Мы отправимся куда угодно, чтобы уничтожить врага.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы служим Траллу с гордостью. Мы отправимся куда угодно, чтобы уничтожить врага.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8063,'Чтобы незаметно подкрадываться к силитидам, нужен большой опыт. Я бы не советовал тебе делать этого без крайней необходимости.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Чтобы незаметно подкрадываться к силитидам, нужен большой опыт. Я бы не советовал тебе делать этого без крайней необходимости.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8064,'Не поймите меня неправильно, я вовсе не хочу целыми днями торчать в туннеле, полном силитидов. Но если наблюдения за перемещениями этих тварей хоть как-то помогут нам выиграть войну, то я останусь здесь столько, сколько потребуется.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не поймите меня неправильно, я вовсе не хочу целыми днями торчать в туннеле, полном силитидов. Но если наблюдения за перемещениями этих тварей хоть как-то помогут нам выиграть войну, то я останусь здесь столько, сколько потребуется.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8070,'Рекомендательный жетон Альянса присуждается $gгерою, добившемуся:героине, добившейся; выдающихся достижений на службе Альянсу. Сотрудники отдела Рекомендаций различных фракций Альянса есть во всех крупных городах, поговори с теми из них, кто представляет фракцию, доброе отношение которой ты хочешь заслужить, и добудь им нужное количество жетонов!$B$BКстати, если во время войны ты захочешь обменять жетоны на предметы, разыщи фельдмаршала Снегопада.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Рекомендательный жетон Альянса присуждается $gгерою, добившемуся:героине, добившейся; выдающихся достижений на службе Альянсу. Сотрудники отдела Рекомендаций различных фракций Альянса есть во всех крупных городах, поговори с теми из них, кто представляет фракцию, доброе отношение которой ты хочешь заслужить, и добудь им нужное количество жетонов!$B$BКстати, если во время войны ты захочешь обменять жетоны на предметы, разыщи фельдмаршала Снегопада.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8072,'Рекомендательные жетоны Альянса выдаются за особые заслуги перед нашими народами. Во всех крупных городах есть отделы рекомендаций, принадлежащие различным фракциям Альянса. Если вы хотите улучшить отношения с какой-либо фракцией, поговорите с ее представителем и отдайте ему нужное количество жетонов.$B$BАх, да! Во время войны жетоны можно обменивать не только на репутацию, но и на материальные ценности. По этому вопросу обращайтесь к фельдмаршалу Снегопаду.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Рекомендательные жетоны Альянса выдаются за особые заслуги перед нашими народами. Во всех крупных городах есть отделы рекомендаций, принадлежащие различным фракциям Альянса. Если вы хотите улучшить отношения с какой-либо фракцией, поговорите с ее представителем и отдайте ему нужное количество жетонов.$B$BАх, да! Во время войны жетоны можно обменивать не только на репутацию, но и на материальные ценности. По этому вопросу обращайтесь к фельдмаршалу Снегопаду.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8073,'Рекомендательный жетон Орды присуждается $gгерою, добившемуся:героине, добившейся; выдающихся достижений на службе Орде. Сотрудники отдела Рекомендаций различных фракций Орды есть во всех крупных городах, поговори с теми из них, кто представляет фракцию, доброе отношение которой ты хочешь заслужить, и добудь им нужное количество жетонов!$B$BКстати, если во время войны ты захочешь обменять жетоны на предметы, разыщи полководца Горчука.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Рекомендательный жетон Орды присуждается $gгерою, добившемуся:героине, добившейся; выдающихся достижений на службе Орде. Сотрудники отдела Рекомендаций различных фракций Орды есть во всех крупных городах, поговори с теми из них, кто представляет фракцию, доброе отношение которой ты хочешь заслужить, и добудь им нужное количество жетонов!$B$BКстати, если во время войны ты захочешь обменять жетоны на предметы, разыщи полководца Горчука.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8074,'Рекомендательные жетоны Орды выдаются за особые заслуги перед нашими народами. Во всех крупных городах есть отделы рекомендаций, принадлежащие различным фракциям Орды. Если вы хотите улучшить отношения с какой-либо фракцией, поговорите с ее представителем и отдайте ему нужное количество жетонов.$B$BАх, да! Во время войны жетоны можно обменивать не только на репутацию, но и на материальные ценности. По этому вопросу обращайтесь к вождю Горчуку.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Рекомендательные жетоны Орды выдаются за особые заслуги перед нашими народами. Во всех крупных городах есть отделы рекомендаций, принадлежащие различным фракциям Орды. Если вы хотите улучшить отношения с какой-либо фракцией, поговорите с ее представителем и отдайте ему нужное количество жетонов.$B$BАх, да! Во время войны жетоны можно обменивать не только на репутацию, но и на материальные ценности. По этому вопросу обращайтесь к вождю Горчуку.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8076,'На шее у оленя висит жетон с эмблемой Пастбищ Дымного Леса и кличкой "Метцен". $B$BМетцен печально и жалобно смотрит на тебя. Кажется, будто олень скован какой-то незримой силой.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','На шее у оленя висит жетон с эмблемой Пастбищ Дымного Леса и кличкой "Метцен". $B$BМетцен печально и жалобно смотрит на тебя. Кажется, будто олень скован какой-то незримой силой.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8078,'Даже если вы сумеете нас освободить, не победив К\'Туна, мы все равно не уйдем, пока не загоним эту тварь обратно в преисподнюю, из которой она явилась. ЛЮБОЙ ЦЕНОЙ.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Даже если вы сумеете нас освободить, не победив К\'Туна, мы все равно не уйдем, пока не загоним эту тварь обратно в преисподнюю, из которой она явилась. ЛЮБОЙ ЦЕНОЙ.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8079,'Герои драконьего племени? К\'Тун должен быть изгнан! Мы можем помочь тебе, $gсмертный:смертная;!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Герои драконьего племени? К\'Тун должен быть изгнан! Мы можем помочь тебе, $gсмертный:смертная;!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`,`text3_0_loc8`,`text3_1_loc8`) VALUES (8081,'Обязательно будь тут к началу следующего шоу фейерверков! Начиная с 6 часов оно будет происходить в начале каждого часа!','Обязательно будь тут к началу следующего шоу фейерверков! Начиная с 6 часов оно будет происходить в начале каждого часа!','Уж не знаю, что они держат в этих бочонках, но оно течет, как мед!','Уж не знаю, что они держат в этих бочонках, но оно течет, как мед!','Добро пожаловать!','Добро пожаловать!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Обязательно будь тут к началу следующего шоу фейерверков! Начиная с 6 часов оно будет происходить в начале каждого часа!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Обязательно будь тут к началу следующего шоу фейерверков! Начиная с 6 часов оно будет происходить в начале каждого часа!',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Уж не знаю, что они держат в этих бочонках, но оно течет, как мед!',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Уж не знаю, что они держат в этих бочонках, но оно течет, как мед!',`text1_1_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Добро пожаловать!',`text3_0_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','Добро пожаловать!',`text3_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8082,'Приветствую, |3-6($c). Я – фельдмаршал Снегопад, командующий военными действиями на этом поле. Нам предстоит преодолеть еще много трудностей на пути к победе, $gпарень:девица;, так что если ты можешь помочь, пожалуйста, помоги. И не стесняйся задавать вопросы.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приветствую, |3-6($c). Я – фельдмаршал Снегопад, командующий военными действиями на этом поле. Нам предстоит преодолеть еще много трудностей на пути к победе, $gпарень:девица;, так что если ты можешь помочь, пожалуйста, помоги. И не стесняйся задавать вопросы.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8084,'Мы все сделали, $gпарень:девушка;! Альянс и Орда собрали все, что сочли нужным, для войны в Ан\'Кираже. Прямо сейчас припасы везут в Силитус. Не пройдет и $2113w дней, как последняя партия будет в Крепости Кенария. После этого $gнекий храбрый герой:некая храбрая героиня; ударит скипетром Зыбучих песков в гонг Скарабея, чтобы открыть ворота Ан\'Киража. Вот тогда-то война и начнется!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы все сделали, $gпарень:девушка;! Альянс и Орда собрали все, что сочли нужным, для войны в Ан\'Кираже. Прямо сейчас припасы везут в Силитус. Не пройдет и $2113w дней, как последняя партия будет в Крепости Кенария. После этого $gнекий храбрый герой:некая храбрая героиня; ударит скипетром Зыбучих песков в гонг Скарабея, чтобы открыть ворота Ан\'Киража. Вот тогда-то война и начнется!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8085,'Хотите хорошую новость, |3-6($c)? Альянс закончил все предвоенные сборы! Теперь мы ждем, пока закончит Орда, а потом отправляем все припасы в Силитус. Пройдет немного времени – и начнется ан\'киражская война!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Хотите хорошую новость, |3-6($c)? Альянс закончил все предвоенные сборы! Теперь мы ждем, пока закончит Орда, а потом отправляем все припасы в Силитус. Пройдет немного времени – и начнется ан\'киражская война!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8087,'Хороший вопрос, |3-6($c). Вот последние цифры, о которых меня информировали. Слитки меди – $1997w из $1998w, слитки железа – $2002w из $2003w, слитки тория – $2011w из $2012w.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Хороший вопрос, |3-6($c). Вот последние цифры, о которых меня информировали. Слитки меди – $1997w из $1998w, слитки железа – $2002w из $2003w, слитки тория – $2011w из $2012w.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8091,'Докладываю обстановку на кулинарном фронте. Радужный тунец – $2092w из $2093w, жареный ящер – $2098w из $2099w, пятнистый желтохвост – $2101w из $2103w. Все продукты хранятся при положенной температуре.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Докладываю обстановку на кулинарном фронте. Радужный тунец – $2092w из $2093w, жареный ящер – $2098w из $2099w, пятнистый желтохвост – $2101w из $2103w. Все продукты хранятся при положенной температуре.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8092,'Тром\'ка, |3-6($c) Орды! Будь $gгордым:гордой;! Я полководец Горчук, командир военной кампании Орды. Нас ждут нелегкие времена, но мы победим, как всегда.$B$BЕсли у тебя есть вопросы – задавай.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тром\'ка, |3-6($c) Орды! Будь $gгордым:гордой;! Я полководец Горчук, командир военной кампании Орды. Нас ждут нелегкие времена, но мы победим, как всегда.$B$BЕсли у тебя есть вопросы – задавай.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8094,'Война скоро начнется, |3-6($c)! И Орда, и Альянс закончили все свои приготовления. Сейчас, пока мы разговариваем, припасы уже везут в Силитус, и до их прибытия осталось меньше $2113w. После этого храбрец, сумевший восстановить скипетр Зыбучих песков, ударит им в гонг на помосте Скарабея. Тогда врата Ан\'Киража распахнутся, и начнется битва, равных которой не было уже много веков!$b$bЛок\'тар огар!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Война скоро начнется, |3-6($c)! И Орда, и Альянс закончили все свои приготовления. Сейчас, пока мы разговариваем, припасы уже везут в Силитус, и до их прибытия осталось меньше $2113w. После этого храбрец, сумевший восстановить скипетр Зыбучих песков, ударит им в гонг на помосте Скарабея. Тогда врата Ан\'Киража распахнутся, и начнется битва, равных которой не было уже много веков!$b$bЛок\'тар огар!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8096,'Ситуация такова: медные слитки – $2018w из $1998w, оловянные – $2005w из $2006w, мифриловые – $2008w из $2009w.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ситуация такова: медные слитки – $2018w из $1998w, оловянные – $2005w из $2006w, мифриловые – $2008w из $2009w.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8097,'Мне только что принесли отчет. Сейчас у нас имеются следующие припасы: мироцвет – $2020w из $2021w, огнецвет – $2050w из $2051w, лиловый лотос – $2054w из $2055w.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мне только что принесли отчет. Сейчас у нас имеются следующие припасы: мироцвет – $2020w из $2021w, огнецвет – $2050w из $2051w, лиловый лотос – $2054w из $2055w.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8098,'Одну минутку… столько цифр – не упомнишь… Итак, по последним данным заготовлены следующие припасы: толстая кожа – $2066w из $2067w, плотная кожа – $2070w из $2071w, грубая кожа – $2073w из $2074w.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Одну минутку… столько цифр – не упомнишь… Итак, по последним данным заготовлены следующие припасы: толстая кожа – $2066w из $2067w, плотная кожа – $2070w из $2071w, грубая кожа – $2073w из $2074w.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8099,'Бинты? Что, надеешься выжить? Ха! Ладно, |3-6($r), я расскажу о текущих запасах. Шерстяные бинты – $2079w из $2080w, бинты из магической ткани – $2085w из $2086w, бинты из рунической ткани – $2089w из $2090w.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Бинты? Что, надеешься выжить? Ха! Ладно, |3-6($r), я расскажу о текущих запасах. Шерстяные бинты – $2079w из $2080w, бинты из магической ткани – $2085w из $2086w, бинты из рунической ткани – $2089w из $2090w.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8101,'Рад тебя видеть, |3-6($c). Надеюсь, ты $gпришел:пришла; узнать насчет подготовки к войне в Ан\'Кираже. Нам очень нужна помощь.$B$BПодготовка к войне – это объединенные усилия Альянса и Орды по подготовке объединенного фронта против силитидов и их владык в Ан\'Кираже. В Палатах Войны Стальгорна мы собираем все необходимое для обеспечения боевых действий, и для этих-то сборов нам и нужна твоя помощь.$B$BМожет быть, ты поговоришь с нашим командиром насчет участия в этом деле?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Рад тебя видеть, |3-6($c). Надеюсь, ты $gпришел:пришла; узнать насчет подготовки к войне в Ан\'Кираже. Нам очень нужна помощь.$B$BПодготовка к войне – это объединенные усилия Альянса и Орды по подготовке объединенного фронта против силитидов и их владык в Ан\'Кираже. В Палатах Войны Стальгорна мы собираем все необходимое для обеспечения боевых действий, и для этих-то сборов нам и нужна твоя помощь.$B$BМожет быть, ты поговоришь с нашим командиром насчет участия в этом деле?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8105,'Здравия желаю, |3-6($c). Уверен, вы здесь, чтобы спросить о подготовке к войне в Ан\'Кираже. Так вот, нам понадобится серьезная помощь. $b$bОрда и Альянс предпринимают совместные усилия по подготовке к надвигающейся войне против силитидов и их хозяев в Ан\'Кираж. В Оргриммаре, на Аллее Духов, мы собираем огромное количество различных товаров для формирования военных припасов, и как раз в сборе нам и понадобится ваша помощь.$b$bМогу ли я предложить вам переговорить с нашим командующим о помощи?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здравия желаю, |3-6($c). Уверен, вы здесь, чтобы спросить о подготовке к войне в Ан\'Кираже. Так вот, нам понадобится серьезная помощь. $b$bОрда и Альянс предпринимают совместные усилия по подготовке к надвигающейся войне против силитидов и их хозяев в Ан\'Кираж. В Оргриммаре, на Аллее Духов, мы собираем огромное количество различных товаров для формирования военных припасов, и как раз в сборе нам и понадобится ваша помощь.$b$bМогу ли я предложить вам переговорить с нашим командующим о помощи?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8108,'Здравствуй, |3-6($c). Я Леорен, смотритель стойл Крепости Кенария.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здравствуй, |3-6($c). Я Леорен, смотритель стойл Крепости Кенария.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8109,'Здесь лежит куча упакованных подарков.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здесь лежит куча упакованных подарков.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8112,'Наша свобода не стоила бы ни гроша, если бы К\'Тун остался жив. Ты – $gнастоящий защитник:настоящая защитница; из пророчества.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Наша свобода не стоила бы ни гроша, если бы К\'Тун остался жив. Ты – $gнастоящий защитник:настоящая защитница; из пророчества.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8113,'Весь мир узнает о том, что произошло в этом проклятом храме. Об этом напишут во всех исторических книгах, а легенды разойдутся от Азерота до дальних пределов Пустоты!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Весь мир узнает о том, что произошло в этом проклятом храме. Об этом напишут во всех исторических книгах, а легенды разойдутся от Азерота до дальних пределов Пустоты!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8114,'Война идет полным ходом, и у нас нет недостатка в отважных воинах Орды и Альянса.$B$BЕсли бы они еще друг друга не убивали…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Война идет полным ходом, и у нас нет недостатка в отважных воинах Орды и Альянса.$B$BЕсли бы они еще друг друга не убивали…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8120,'Дневник Джандис Баровой заполнен всяческими рассуждениями и размышлениями на тему нежити. Ближе к концу тетради обнаруживается выкройка какой-то необычной сумки. Вашего мастерства в портняжном деле недостаточно, чтобы разобраться в этой выкройке.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Дневник Джандис Баровой заполнен всяческими рассуждениями и размышлениями на тему нежити. Ближе к концу тетради обнаруживается выкройка какой-то необычной сумки. Вашего мастерства в портняжном деле недостаточно, чтобы разобраться в этой выкройке.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8123,'Лишь тот, кого Древобрюхи не считают своим врагом, может спокойно пройти через берлогу. Вы сделали хоть что-нибудь, чтобы завоевать наше доверие?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Лишь тот, кого Древобрюхи не считают своим врагом, может спокойно пройти через берлогу. Вы сделали хоть что-нибудь, чтобы завоевать наше доверие?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8125,'Новинка года: PX-238 Чудовольт Мороза. Не стесняйтесь, поднимайтесь!$b$bДа, сначала подпишите эти бумажки, потому что у нас тут осталось несколько мелких недоработок…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Новинка года: PX-238 Чудовольт Мороза. Не стесняйтесь, поднимайтесь!$b$bДа, сначала подпишите эти бумажки, потому что у нас тут осталось несколько мелких недоработок…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8129,'Здравствуй, |3-6($c). Я – сотрудница отдела рекомендаций, представляющая здесь Стальгорн. В мои обязанности входит помогать искателям приключений, получившим Рекомендательные Жетоны Альянса.$B$BЯ принимаю жетоны в разных количествах, но выгоднее всего для тебя возвращать их мне их порциями по десять. Когда ты отдашь мне жетоны, я занесу твои деяния в наши списки. В результате ты получишь признательность Стальгорна за проделанную работу.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Здравствуй, |3-6($c). Я – сотрудница отдела рекомендаций, представляющая здесь Стальгорн. В мои обязанности входит помогать искателям приключений, получившим Рекомендательные Жетоны Альянса.$B$BЯ принимаю жетоны в разных количествах, но выгоднее всего для тебя возвращать их мне их порциями по десять. Когда ты отдашь мне жетоны, я занесу твои деяния в наши списки. В результате ты получишь признательность Стальгорна за проделанную работу.',`text0_1_loc8`);
