INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`,`text2_1_loc8`,`text3_1_loc8`) VALUES (8143,'Погода стоит просто сказочная, вы не находите?','Последней смеяться буду я… они еще увидят! О, привет, |3-6($c), я вас не заметила!','$gДорогой мой:Дорогая моя:c; |3-6($c)! Два процента изобретений совершаются по пьяной лавочке, четыре – после солнечного удара, еще шесть подобны грому среди ясного неба, а оставшиеся девяносто три процента принадлежат Румпельшникер.$b$bХм, что-то не сходится… Где там мои записи?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Погода стоит просто сказочная, вы не находите?',`text0_1_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Последней смеяться буду я… они еще увидят! О, привет, |3-6($c), я вас не заметила!',`text2_1_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','$gДорогой мой:Дорогая моя:c; |3-6($c)! Два процента изобретений совершаются по пьяной лавочке, четыре – после солнечного удара, еще шесть подобны грому среди ясного неба, а оставшиеся девяносто три процента принадлежат Румпельшникер.$b$bХм, что-то не сходится… Где там мои записи?',`text3_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
