INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8209,'Мы заодно с Альянсом, |3-6($r). Зло, столь древнее, что мир позабыл о нем, стремится поглотить нас всех – сначала Калимдор, а затем и весь остальной Азерот. Им движет ненависть ко всем творениям великих Творцов: Титанов Вечности.$B$BМы все стоим на пути войск К\'Туна. Мы ударим первыми и сломим силы Ан\'Киража. Пусть Азерот дрожит от объединенной мощи Орды и Альянса.$B$BТы $gнужен:нужна; фронту!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы заодно с Альянсом, |3-6($r). Зло, столь древнее, что мир позабыл о нем, стремится поглотить нас всех – сначала Калимдор, а затем и весь остальной Азерот. Им движет ненависть ко всем творениям великих Творцов: Титанов Вечности.$B$BМы все стоим на пути войск К\'Туна. Мы ударим первыми и сломим силы Ан\'Киража. Пусть Азерот дрожит от объединенной мощи Орды и Альянса.$B$BТы $gнужен:нужна; фронту!',`text0_0_loc8`);
