INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (8211,'Предка Звездный Луг можно найти у ворот Зул\'Гуруба в Тернистой долине.','Предка Звездный Луг можно найти у ворот Зул\'Гуруба в Тернистой долине.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Предка Звездный Луг можно найти у ворот Зул\'Гуруба в Тернистой долине.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Предка Звездный Луг можно найти у ворот Зул\'Гуруба в Тернистой долине.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8212,'Они мне говорят: "Молодец, тебе полагается повышение!" Сказали бы уж сразу: "Отправляйся к ульям Силитуса и торчи там с потными дворфами, Кернс!"$B$BСпасибо за повышение, капитан!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Они мне говорят: "Молодец, тебе полагается повышение!" Сказали бы уж сразу: "Отправляйся к ульям Силитуса и торчи там с потными дворфами, Кернс!"$B$BСпасибо за повышение, капитан!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8213,'Я, как и мой брат, уважаю тех, кто чтит своих предков. Я с радостью передам секреты мастерства достойным участникам Лунного фестиваля!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я, как и мой брат, уважаю тех, кто чтит своих предков. Я с радостью передам секреты мастерства достойным участникам Лунного фестиваля!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8215,'Какими бы смертоносными ни казались силитиды, они всего лишь ручные звери своих хозяев киражи.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Какими бы смертоносными ни казались силитиды, они всего лишь ручные звери своих хозяев киражи.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`,`text2_0_loc8`,`text2_1_loc8`,`text3_0_loc8`,`text3_1_loc8`) VALUES (8218,'Они тут, на Лунной поляне, знают, как вечеринки закатывать. И кто бы мог подумать!..','Они тут, на Лунной поляне, знают, как вечеринки закатывать. И кто бы мог подумать!..','Попробуй эти установки для фейерверков. Они так здорово бабахают!','Попробуй эти установки для фейерверков. Они так здорово бабахают!','Этот луч лунного света ведет в Штормград. Когда будешь $gготов:готова;, воспользуйся приглашением.','Этот луч лунного света ведет в Штормград. Когда будешь $gготов:готова;, воспользуйся приглашением.','Не пытайся телепортироваться в город врага. Ничего не выйдет – пусть здесь мы дружелюбны, но дома мигом вспомним все обиды.','Не пытайся телепортироваться в город врага. Ничего не выйдет – пусть здесь мы дружелюбны, но дома мигом вспомним все обиды.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Они тут, на Лунной поляне, знают, как вечеринки закатывать. И кто бы мог подумать!..',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Они тут, на Лунной поляне, знают, как вечеринки закатывать. И кто бы мог подумать!..',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Попробуй эти установки для фейерверков. Они так здорово бабахают!',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Попробуй эти установки для фейерверков. Они так здорово бабахают!',`text1_1_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Этот луч лунного света ведет в Штормград. Когда будешь $gготов:готова;, воспользуйся приглашением.',`text2_0_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Этот луч лунного света ведет в Штормград. Когда будешь $gготов:готова;, воспользуйся приглашением.',`text2_1_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Не пытайся телепортироваться в город врага. Ничего не выйдет – пусть здесь мы дружелюбны, но дома мигом вспомним все обиды.',`text3_0_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','Не пытайся телепортироваться в город врага. Ничего не выйдет – пусть здесь мы дружелюбны, но дома мигом вспомним все обиды.',`text3_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`,`text2_0_loc8`,`text2_1_loc8`,`text3_0_loc8`,`text3_1_loc8`) VALUES (8219,'Жители Ночной Гавани умеют повеселиться!','Жители Ночной Гавани умеют повеселиться!','Правда, эти фейерверки здорово бабахают?','Правда, эти фейерверки здорово бабахают?','Этот столп лунного света приведет тебя в Стальгорн. Но кто же захочет покинуть праздник?','Этот столп лунного света приведет тебя в Стальгорн. Но кто же захочет покинуть праздник?','Не пытайся телепортироваться в город врага. Ничего не выйдет – пусть здесь мы дружелюбны, но дома мигом вспомним все обиды.','Не пытайся телепортироваться в город врага. Ничего не выйдет – пусть здесь мы дружелюбны, но дома мигом вспомним все обиды.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Жители Ночной Гавани умеют повеселиться!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Жители Ночной Гавани умеют повеселиться!',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Правда, эти фейерверки здорово бабахают?',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Правда, эти фейерверки здорово бабахают?',`text1_1_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Этот столп лунного света приведет тебя в Стальгорн. Но кто же захочет покинуть праздник?',`text2_0_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Этот столп лунного света приведет тебя в Стальгорн. Но кто же захочет покинуть праздник?',`text2_1_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Не пытайся телепортироваться в город врага. Ничего не выйдет – пусть здесь мы дружелюбны, но дома мигом вспомним все обиды.',`text3_0_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','Не пытайся телепортироваться в город врага. Ничего не выйдет – пусть здесь мы дружелюбны, но дома мигом вспомним все обиды.',`text3_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`,`text2_0_loc8`,`text2_1_loc8`,`text3_0_loc8`,`text3_1_loc8`) VALUES (8220,'Лунный фестиваль в этом году совершенно бесподобен!','Лунный фестиваль в этом году совершенно бесподобен!','Говорят, что эти фейерверки наделены силой самой Луны!','Говорят, что эти фейерверки наделены силой самой Луны!','Этот столп лунного света перенесет тебя в Дарнас.','Этот столп лунного света перенесет тебя в Дарнас.','Не пытайся телепортироваться в город врага. Ничего не выйдет – пусть здесь мы дружелюбны, но дома мигом вспомним все обиды.','Не пытайся телепортироваться в город врага. Ничего не выйдет – пусть здесь мы дружелюбны, но дома мигом вспомним все обиды.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Лунный фестиваль в этом году совершенно бесподобен!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Лунный фестиваль в этом году совершенно бесподобен!',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Говорят, что эти фейерверки наделены силой самой Луны!',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Говорят, что эти фейерверки наделены силой самой Луны!',`text1_1_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Этот столп лунного света перенесет тебя в Дарнас.',`text2_0_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Этот столп лунного света перенесет тебя в Дарнас.',`text2_1_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Не пытайся телепортироваться в город врага. Ничего не выйдет – пусть здесь мы дружелюбны, но дома мигом вспомним все обиды.',`text3_0_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','Не пытайся телепортироваться в город врага. Ничего не выйдет – пусть здесь мы дружелюбны, но дома мигом вспомним все обиды.',`text3_1_loc8`);
