INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text2_0_loc8`,`text2_1_loc8`,`text3_0_loc8`,`text3_1_loc8`) VALUES (8221,'Не знай я наверняка – решил бы, что эту вечеринку устроили орки.','Не знай я наверняка – решила бы, что эту вечеринку устроили орки.','Этот столп лунного света приведет тебя в Оргриммар. Когда будешь $gготов:готова;, воспользуйся приглашением.','Этот столп лунного света приведет тебя в Оргриммар. Когда будешь $gготов:готова;, воспользуйся приглашением.','Не пытайся телепортироваться в город врага. Ничего не выйдет – пусть здесь мы дружелюбны, но дома мигом вспомним все обиды.','Не пытайся телепортироваться в город врага. Ничего не выйдет – пусть здесь мы дружелюбны, но дома мигом вспомним все обиды.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не знай я наверняка – решил бы, что эту вечеринку устроили орки.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Не знай я наверняка – решила бы, что эту вечеринку устроили орки.',`text0_1_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Этот столп лунного света приведет тебя в Оргриммар. Когда будешь $gготов:готова;, воспользуйся приглашением.',`text2_0_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Этот столп лунного света приведет тебя в Оргриммар. Когда будешь $gготов:готова;, воспользуйся приглашением.',`text2_1_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Не пытайся телепортироваться в город врага. Ничего не выйдет – пусть здесь мы дружелюбны, но дома мигом вспомним все обиды.',`text3_0_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','Не пытайся телепортироваться в город врага. Ничего не выйдет – пусть здесь мы дружелюбны, но дома мигом вспомним все обиды.',`text3_1_loc8`);
