INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`,`text2_0_loc8`,`text2_1_loc8`,`text3_0_loc8`,`text3_1_loc8`) VALUES (8222,'Я обожаю Лунный фестиваль! Отличное время, чтобы копыта размять как следует!','Я обожаю Лунный фестиваль! Отличное время, чтобы копыта размять как следует!','Не знаю, как эти фейерверки работают, но огни в небе мне ужасно нравятся!','Не знаю, как эти фейерверки работают, но огни в небе мне ужасно нравятся!','Этот столп лунного света перенесет тебя в Громовой Утес. Воспользуйся им, когда захочешь покинуть фестиваль.','Этот столп лунного света перенесет тебя в Громовой Утес. Воспользуйся им, когда захочешь покинуть фестиваль.','Не пытайся телепортироваться в город врага. Ничего не выйдет – пусть здесь мы дружелюбны, но дома мигом вспомним все обиды.','Не пытайся телепортироваться в город врага. Ничего не выйдет – пусть здесь мы дружелюбны, но дома мигом вспомним все обиды.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я обожаю Лунный фестиваль! Отличное время, чтобы копыта размять как следует!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я обожаю Лунный фестиваль! Отличное время, чтобы копыта размять как следует!',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Не знаю, как эти фейерверки работают, но огни в небе мне ужасно нравятся!',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Не знаю, как эти фейерверки работают, но огни в небе мне ужасно нравятся!',`text1_1_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Этот столп лунного света перенесет тебя в Громовой Утес. Воспользуйся им, когда захочешь покинуть фестиваль.',`text2_0_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Этот столп лунного света перенесет тебя в Громовой Утес. Воспользуйся им, когда захочешь покинуть фестиваль.',`text2_1_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Не пытайся телепортироваться в город врага. Ничего не выйдет – пусть здесь мы дружелюбны, но дома мигом вспомним все обиды.',`text3_0_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','Не пытайся телепортироваться в город врага. Ничего не выйдет – пусть здесь мы дружелюбны, но дома мигом вспомним все обиды.',`text3_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`,`text2_0_loc8`,`text2_1_loc8`,`text3_0_loc8`,`text3_1_loc8`) VALUES (8223,'Где еще так хорошо погреешь косточки, как на Лунном фестивале!','Где еще так хорошо погреешь косточки, как на Лунном фестивале!','Когда не чувствуешь пальцев, запускать фейерверки надо аккуратно.','Когда не чувствуешь пальцев, запускать фейерверки надо аккуратно.','Этот лунный луч ведет в Подгород. Возвращайтесь, когда будете готовы.','Этот лунный луч ведет в Подгород. Возвращайтесь, когда будете готовы.','Не пытайся телепортироваться в город врага. Ничего не выйдет – пусть здесь мы дружелюбны, но дома мигом вспомним все обиды.','Не пытайся телепортироваться в город врага. Ничего не выйдет – пусть здесь мы дружелюбны, но дома мигом вспомним все обиды.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Где еще так хорошо погреешь косточки, как на Лунном фестивале!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Где еще так хорошо погреешь косточки, как на Лунном фестивале!',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Когда не чувствуешь пальцев, запускать фейерверки надо аккуратно.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Когда не чувствуешь пальцев, запускать фейерверки надо аккуратно.',`text1_1_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Этот лунный луч ведет в Подгород. Возвращайтесь, когда будете готовы.',`text2_0_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Этот лунный луч ведет в Подгород. Возвращайтесь, когда будете готовы.',`text2_1_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Не пытайся телепортироваться в город врага. Ничего не выйдет – пусть здесь мы дружелюбны, но дома мигом вспомним все обиды.',`text3_0_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','Не пытайся телепортироваться в город врага. Ничего не выйдет – пусть здесь мы дружелюбны, но дома мигом вспомним все обиды.',`text3_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8226,'Многие годы мы трудимся не покладая рук, чтобы вернуть нашей земле былую славу, |3-6($c). Мы не позволим чужакам снова вторгнуться в Кель\'Талас и осквернить его. И в наших сердцах не будет покоя, пока враги не исчезнут из виду.$B$BНикто не посмеет встать на пути син\'дорай!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Многие годы мы трудимся не покладая рук, чтобы вернуть нашей земле былую славу, |3-6($c). Мы не позволим чужакам снова вторгнуться в Кель\'Талас и осквернить его. И в наших сердцах не будет покоя, пока враги не исчезнут из виду.$B$BНикто не посмеет встать на пути син\'дорай!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8227,'Все пропало, |3-6($c), и я сама виновата! Мне же советовали уйти с причала, пока не поздно, но разве я послушалась? Нет.$B$BЧто же мне теперь делать? Эти противные эльфы крови, Презренные, сбежали с моими товарами, и уже их, наверное, съели. Так что вернуть их, сдается мне, нельзя. А мурлоки из племени Темной Чешуи выкрали под покровом ночи остальные мои товары! Но мало того, чтобы окончательно добить честную торговку, мой корабль оставила команда!$B$BКажется, я сейчас заплачу.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Все пропало, |3-6($c), и я сама виновата! Мне же советовали уйти с причала, пока не поздно, но разве я послушалась? Нет.$B$BЧто же мне теперь делать? Эти противные эльфы крови, Презренные, сбежали с моими товарами, и уже их, наверное, съели. Так что вернуть их, сдается мне, нельзя. А мурлоки из племени Темной Чешуи выкрали под покровом ночи остальные мои товары! Но мало того, чтобы окончательно добить честную торговку, мой корабль оставила команда!$B$BКажется, я сейчас заплачу.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8228,'Здравствуй, |3-6($c)! Воистину дурные настали времена, если уж наш любимый Кель\'Талас превратился в такое…') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Здравствуй, |3-6($c)! Воистину дурные настали времена, если уж наш любимый Кель\'Талас превратился в такое…',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8233,'$C, многие очень долго живут наедине со своим чувством вины, прежде чем решаются исправить ошибку.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','$C, многие очень долго живут наедине со своим чувством вины, прежде чем решаются исправить ошибку.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8234,'Жуть – вот что это было! Все эти твари выскочили из ниоткуда и вышли из-под контроля. Магистр с учениками удрали неведомо куда, а меня оставили, а я только и могу, что сказать: "Привет, я Виллитен, чего изволите?"$B$BКошмар!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Жуть – вот что это было! Все эти твари выскочили из ниоткуда и вышли из-под контроля. Магистр с учениками удрали неведомо куда, а меня оставили, а я только и могу, что сказать: "Привет, я Виллитен, чего изволите?"$B$BКошмар!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8235,'Мы были так поглощены этой войной, что часто забывали о любви.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мы были так поглощены этой войной, что часто забывали о любви.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8237,'Вот это сражение! Давайте немного переведем дух.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Вот это сражение! Давайте немного переведем дух.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8238,'Эй, $n. Ты $gпохож:похожа; на |3-3($c), $Gзнающего:знающую:c; толк в вине. Я хочу попросить тебя об одной услуге и, думаю, могу сделать тебе предложение, от которого ты не сможешь отказаться… а ладно, проехали!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эй, $n. Ты $gпохож:похожа; на |3-3($c), $Gзнающего:знающую:c; толк в вине. Я хочу попросить тебя об одной услуге и, думаю, могу сделать тебе предложение, от которого ты не сможешь отказаться… а ладно, проехали!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8240,'А, ты, должно быть, $gтот самый парень, которому:та самая девушка, которой; поручили помогать мне в Лесах Вечной Песни? Не очень-то ты $gторопился:торопилась; сюда, а?$B$BЛадно, неважно. Не будем терять времени.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','А, ты, должно быть, $gтот самый парень, которому:та самая девушка, которой; поручили помогать мне в Лесах Вечной Песни? Не очень-то ты $gторопился:торопилась; сюда, а?$B$BЛадно, неважно. Не будем терять времени.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (8241,'Похоже, ты уже $gнашел:нашла; свою любовь. Можешь дать мне знак любви, но за это тебе ничего не светит. Мне нужен кто-то особенный.','Похоже, ты уже $gнашел:нашла; свою любовь. Можешь дать мне знак любви, но за это тебе ничего не светит. Мне нужен кто-то особенный.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Похоже, ты уже $gнашел:нашла; свою любовь. Можешь дать мне знак любви, но за это тебе ничего не светит. Мне нужен кто-то особенный.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Похоже, ты уже $gнашел:нашла; свою любовь. Можешь дать мне знак любви, но за это тебе ничего не светит. Мне нужен кто-то особенный.',`text0_1_loc8`);
