INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8245,'Мы были так поглощены этой войной, что забывали выкроить время для любви.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мы были так поглощены этой войной, что забывали выкроить время для любви.',`text0_1_loc8`);
