INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8251,'Не понимаю, что это со мной. Мое сердце горячее, словно раскаленная сталь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не понимаю, что это со мной. Мое сердце горячее, словно раскаленная сталь.',`text0_0_loc8`);
