INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8254,'Когда долго имеешь дело с механизмами, забываешь о живых, бьющихся сердцах.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Когда долго имеешь дело с механизмами, забываешь о живых, бьющихся сердцах.',`text0_0_loc8`);
