INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8255,'Прожив с мое, нетрудно забыть о любви… Но всегда приятно, когда о ней напоминают.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Прожив с мое, нетрудно забыть о любви… Но всегда приятно, когда о ней напоминают.',`text0_1_loc8`);
