INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (8283,'Похоже, твое сердце разбито… Приходи, когда оправишься от этого потрясения.','Похоже, твое сердце разбито… Приходи, когда оправишься от этого потрясения.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Похоже, твое сердце разбито… Приходи, когда оправишься от этого потрясения.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Похоже, твое сердце разбито… Приходи, когда оправишься от этого потрясения.',`text0_1_loc8`);
