INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8286,'Как, у тебя нет для меня знака любви? Ты что же, не любишь меня?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Как, у тебя нет для меня знака любви? Ты что же, не любишь меня?',`text0_1_loc8`);
