INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (8287,'Я с тобой поговорю, если от тебя будет пахнуть получше. Например, одеколоном.','Я с тобой поговорю, если от тебя будет пахнуть получше. Например, одеколоном.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я с тобой поговорю, если от тебя будет пахнуть получше. Например, одеколоном.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я с тобой поговорю, если от тебя будет пахнуть получше. Например, одеколоном.',`text0_1_loc8`);
