INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8289,'Мне бы очень понравилось, если бы от вас шел тонкий аромат духов.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мне бы очень понравилось, если бы от вас шел тонкий аромат духов.',`text0_1_loc8`);
