INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text2_0_loc8`,`text3_0_loc8`) VALUES (8292,'Что?! Как ты $gпроскользнул:проскользнула; мимо моего тюре… э-э, приспешника? Ладно, думаю, оно и к лучшему. В последнее время торговля малость ухудшилась. $B$BЧто я могу сделать для твоих низменных нужд, |3-6($c)?','Ты $gпришел:пришла; за жезлом? Или просто хочешь запастись рунами?$B$BПостой-ка! Ты хочешь свалить весь этот хлам на меня?! Будь проклята моя вечная жажда покупать, покупать и снова покупать!','Что? Нет, я не чиню доспехи. Круговзор в миле к северу отсюда, $gбратишка:сестренка;. $B$BА теперь покупай что-нибудь или убирайся, пока я не вызвал своего чернокнижника, чтобы он с тобой разобрался!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что?! Как ты $gпроскользнул:проскользнула; мимо моего тюре… э-э, приспешника? Ладно, думаю, оно и к лучшему. В последнее время торговля малость ухудшилась. $B$BЧто я могу сделать для твоих низменных нужд, |3-6($c)?',`text0_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Ты $gпришел:пришла; за жезлом? Или просто хочешь запастись рунами?$B$BПостой-ка! Ты хочешь свалить весь этот хлам на меня?! Будь проклята моя вечная жажда покупать, покупать и снова покупать!',`text2_0_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Что? Нет, я не чиню доспехи. Круговзор в миле к северу отсюда, $gбратишка:сестренка;. $B$BА теперь покупай что-нибудь или убирайся, пока я не вызвал своего чернокнижника, чтобы он с тобой разобрался!',`text3_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8301,'Ты бы мне больше $gпонравился:понравилась;, если бы $gвоспользовался:воспользовалась; духами.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты бы мне больше $gпонравился:понравилась;, если бы $gвоспользовался:воспользовалась; духами.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8304,'Нам приказано уничтожить Раджакса. Уничтожить с особой жестокостью, если быть точным.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Нам приказано уничтожить Раджакса. Уничтожить с особой жестокостью, если быть точным.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8305,'Я выполнил задание. Если тебе нужны припасы, возможно, у меня есть лишние.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я выполнил задание. Если тебе нужны припасы, возможно, у меня есть лишние.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (8306,'Нет, меня самого это не интересует, но все остальные сейчас ищут любовь. Купи у меня знаки любви, воспользуйся одеколоном или духами, а потом сделай подарки своим любимым!','Нет, меня саму это не интересует, но все остальные сейчас ищут любовь. Купи у меня знаки любви, воспользуйся одеколоном или духами, а потом сделай подарки своим любимым!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Нет, меня самого это не интересует, но все остальные сейчас ищут любовь. Купи у меня знаки любви, воспользуйся одеколоном или духами, а потом сделай подарки своим любимым!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Нет, меня саму это не интересует, но все остальные сейчас ищут любовь. Купи у меня знаки любви, воспользуйся одеколоном или духами, а потом сделай подарки своим любимым!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (8307,'Знаки любви можно дарить романтически настроенным жителям городов. В ответ вы получите дары любви.$b$bЕсли же вас уже кто-то любит, то в ответ вы получите дары дружбы.','Знаки любви можно дарить романтически настроенным жителям городов. В ответ вы получите дары любви.$b$bЕсли же вас уже кто-то любит, то в ответ вы получите дары дружбы.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Знаки любви можно дарить романтически настроенным жителям городов. В ответ вы получите дары любви.$b$bЕсли же вас уже кто-то любит, то в ответ вы получите дары дружбы.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Знаки любви можно дарить романтически настроенным жителям городов. В ответ вы получите дары любви.$b$bЕсли же вас уже кто-то любит, то в ответ вы получите дары дружбы.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (8308,'Если ты воспользуешься одеколоном или духами, то узнаешь, кто ищет любви. Кто готов принять знак любви… и вручить подарок в ответ.$B$BНо помни: чтобы дать кому-либо знак любви, надо пахнуть правильно! Мужчинам нравится запах духов, а женщины предпочитают одеколон.','Если ты воспользуешься одеколоном или духами, то узнаешь, кто ищет любви. Кто готов принять знак любви… и вручить подарок в ответ.$B$BНо помни: чтобы дать кому-либо знак любви, надо пахнуть правильно! Мужчинам нравится запах духов, а женщины предпочитают одеколон.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если ты воспользуешься одеколоном или духами, то узнаешь, кто ищет любви. Кто готов принять знак любви… и вручить подарок в ответ.$B$BНо помни: чтобы дать кому-либо знак любви, надо пахнуть правильно! Мужчинам нравится запах духов, а женщины предпочитают одеколон.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Если ты воспользуешься одеколоном или духами, то узнаешь, кто ищет любви. Кто готов принять знак любви… и вручить подарок в ответ.$B$BНо помни: чтобы дать кому-либо знак любви, надо пахнуть правильно! Мужчинам нравится запах духов, а женщины предпочитают одеколон.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (8315,'Вот окончательные результаты!$B$BТралл: $2200w$BКэрн: $2201w$BСильвана: $2202w$BВсего у Орды: $2207w$B$BБолвар: $2203w$BМагни: $2204w$BТиранда: $2205w$BВсего у Альянса: $2206w$B$BСамый популярный герой – у Альянса!','Вот окончательные результаты!$B$BТралл: $2200w$BКэрн: $2201w$BСильвана: $2202w$BВсего у Орды: $2207w$B$BБолвар: $2203w$BМагни: $2204w$BТиранда: $2205w$BВсего у Альянса: $2206w$B$BСамый популярный герой – у Альянса!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вот окончательные результаты!$B$BТралл: $2200w$BКэрн: $2201w$BСильвана: $2202w$BВсего у Орды: $2207w$B$BБолвар: $2203w$BМагни: $2204w$BТиранда: $2205w$BВсего у Альянса: $2206w$B$BСамый популярный герой – у Альянса!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Вот окончательные результаты!$B$BТралл: $2200w$BКэрн: $2201w$BСильвана: $2202w$BВсего у Орды: $2207w$B$BБолвар: $2203w$BМагни: $2204w$BТиранда: $2205w$BВсего у Альянса: $2206w$B$BСамый популярный герой – у Альянса!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (8317,'Раздавая горожанам знаки любви, ты будешь получать различные подарки. Часть из них можно оставить себе, а все остальные стоит передать своему любимому герою! Если хочешь сделать это, навести Кви К. Мелкошустра. $B$BКви можно встретить рядом с Болваром, Магни или Тирандой.','Раздавая горожанам знаки любви, ты будешь получать различные подарки. Часть из них можно оставить себе, а все остальные стоит передать своему любимому герою! Если хочешь сделать это, навести Кви К. Мелкошустра. $B$BКви можно встретить рядом с Болваром, Магни или Тирандой.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Раздавая горожанам знаки любви, ты будешь получать различные подарки. Часть из них можно оставить себе, а все остальные стоит передать своему любимому герою! Если хочешь сделать это, навести Кви К. Мелкошустра. $B$BКви можно встретить рядом с Болваром, Магни или Тирандой.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Раздавая горожанам знаки любви, ты будешь получать различные подарки. Часть из них можно оставить себе, а все остальные стоит передать своему любимому герою! Если хочешь сделать это, навести Кви К. Мелкошустра. $B$BКви можно встретить рядом с Болваром, Магни или Тирандой.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8318,'Я навсегда привязан к этому проклятому миру. Каково твое желание, $gсмертный:смертная;?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я навсегда привязан к этому проклятому миру. Каково твое желание, $gсмертный:смертная;?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (8319,'Дари горожанам знаки любви, и получишь в ответ различные предметы. Некоторые из них будут ценны и полезны, а оставшиеся можно собрать и отдать любимому герою! Для этого навести Кви К. Мелкошустра. $B$BОн не отходит далеко от Кэрна, Сильваны и Тралла.','Дари горожанам знаки любви, и получишь в ответ различные предметы. Некоторые из них будут ценны и полезны, а оставшиеся можно собрать и отдать любимому герою! Для этого навести Кви К. Мелкошустра. $B$BОн не отходит далеко от Кэрна, Сильваны и Тралла.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Дари горожанам знаки любви, и получишь в ответ различные предметы. Некоторые из них будут ценны и полезны, а оставшиеся можно собрать и отдать любимому герою! Для этого навести Кви К. Мелкошустра. $B$BОн не отходит далеко от Кэрна, Сильваны и Тралла.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Дари горожанам знаки любви, и получишь в ответ различные предметы. Некоторые из них будут ценны и полезны, а оставшиеся можно собрать и отдать любимому герою! Для этого навести Кви К. Мелкошустра. $B$BОн не отходит далеко от Кэрна, Сильваны и Тралла.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8321,'Текст на страницах этой книги постоянно изменяется. Вы чувствуете, что она словно бы вытягивает из вашей головы мысли и поглощает их.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Текст на страницах этой книги постоянно изменяется. Вы чувствуете, что она словно бы вытягивает из вашей головы мысли и поглощает их.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8334,'С угрозой потери жизни я как-то примирился. Но потерю Исиды я не перенесу, даже после собственной смерти.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','С угрозой потери жизни я как-то примирился. Но потерю Исиды я не перенесу, даже после собственной смерти.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8335,'Привет, $gдружище:подруга;. Эктоплазматическими конденсаторами не интересуешься? А как насчет всенаправленных спектральных ассимиляторов?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Привет, $gдружище:подруга;. Эктоплазматическими конденсаторами не интересуешься? А как насчет всенаправленных спектральных ассимиляторов?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8336,'Чего тебе? Не видишь, я занят?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Чего тебе? Не видишь, я занят?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8347,'Наш новейший аттракцион – и совершенно бесплатный! Для управления этими миниатюрными паровыми танками можно использовать любую из панелей управления, расставленных по всей ярмарке.$B$BОт вас требуется только включить ближайшую панель. Каждый танк оборудован комплектом стандартных приспособлений и одной случайно выбранной особой возможностью!$B$BВедите эпические битвы с друзьями, катайтесь по окрестностям или просто устраивайте веселую суматоху… Выбор за вами!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Наш новейший аттракцион – и совершенно бесплатный! Для управления этими миниатюрными паровыми танками можно использовать любую из панелей управления, расставленных по всей ярмарке.$B$BОт вас требуется только включить ближайшую панель. Каждый танк оборудован комплектом стандартных приспособлений и одной случайно выбранной особой возможностью!$B$BВедите эпические битвы с друзьями, катайтесь по окрестностям или просто устраивайте веселую суматоху… Выбор за вами!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8350,'Говорят, что Кел\'Тузад ищет легендарный Атиеш, посох Хранителя.$B$BДа, тот самый посох, которым когда-то владел Медив.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Говорят, что Кел\'Тузад ищет легендарный Атиеш, посох Хранителя.$B$BДа, тот самый посох, которым когда-то владел Медив.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8355,'Прозвище обманчиво. На самом деле, если узнать меня поближе, я очень добрый.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Прозвище обманчиво. На самом деле, если узнать меня поближе, я очень добрый.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8356,'Они едва не отправили моего брата, Локси, на эту встречу. Он за псами-то своими уследить не может, что уж говорить о том, чтобы представлять Алый орден!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Они едва не отправили моего брата, Локси, на эту встречу. Он за псами-то своими уследить не может, что уж говорить о том, чтобы представлять Алый орден!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8364,'Только после его неоднозначной гибели рыцари и воины Лордерона стали носить одежды сходного вида в честь их павшего героя. Смерть Могрейна была большой победой Кел\'Тузада, но создавшийся образ мученика значительно повлиял на весь период окончания войны.$B$BГде пал один, восстанут многие...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Только после его неоднозначной гибели рыцари и воины Лордерона стали носить одежды сходного вида в честь их павшего героя. Смерть Могрейна была большой победой Кел\'Тузада, но создавшийся образ мученика значительно повлиял на весь период окончания войны.$B$BГде пал один, восстанут многие...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8366,'Таких, как я, зовут капиталистами, |3-6($r).') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Таких, как я, зовут капиталистами, |3-6($r).',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8375,'Здравствуйте, |3-6($c). Вижу, вам здесь нравится. Вечеринка удалась на славу! Надеюсь, напитков и закусок хватит на всех, иначе веселье быстро закончится!$B$BЧто ж, мне пора к другим гостям. Развлекайтесь!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здравствуйте, |3-6($c). Вижу, вам здесь нравится. Вечеринка удалась на славу! Надеюсь, напитков и закусок хватит на всех, иначе веселье быстро закончится!$B$BЧто ж, мне пора к другим гостям. Развлекайтесь!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8378,'Приветствую вас, $gгосподин мой:госпожа моя;. Надеюсь, вы хорошо проводите время?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Приветствую вас, $gгосподин мой:госпожа моя;. Надеюсь, вы хорошо проводите время?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8379,'Правда, здорово? Я так рада, что лорд Салтерил устраивает приемы каждый вечер, особенно теперь, когда на юге творятся такие гадости. Все проблемы как будто исчезают, правда?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Правда, здорово? Я так рада, что лорд Салтерил устраивает приемы каждый вечер, особенно теперь, когда на юге творятся такие гадости. Все проблемы как будто исчезают, правда?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8388,'Как и Кел\'Тузад, я тоже когда-то входила в число магов Кирин-Тора. И, как и он, я искала легендарный Атиеш, посох Хранителя. Наши судьбы переплетены, |3-6($c).') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Как и Кел\'Тузад, я тоже когда-то входила в число магов Кирин-Тора. И, как и он, я искала легендарный Атиеш, посох Хранителя. Наши судьбы переплетены, |3-6($c).',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8389,'Потомок самой Эгвин, он должен был стать последним хранителем Тирисфаля… Медив.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Потомок самой Эгвин, он должен был стать последним хранителем Тирисфаля… Медив.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8390,'Это легенда, причем та, пересказывать которую у меня нет ни времени, ни желания. Знай лишь, что Медив был последним из хранителей. А большой посох, Атиеш, был средоточием его силы и его зла.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Это легенда, причем та, пересказывать которую у меня нет ни времени, ни желания. Знай лишь, что Медив был последним из хранителей. А большой посох, Атиеш, был средоточием его силы и его зла.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8391,'Порча падшего титана. Порча Разрушителя. Все же этот посох был создан из зерна ненависти. Именно это и привело меня сюда…') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Порча падшего титана. Порча Разрушителя. Все же этот посох был создан из зерна ненависти. Именно это и привело меня сюда…',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8392,'После падения Каражана Кирин-Тор послал группу магов, чтобы обыскать башню и вынести из нее все нужное… для "исследований". Тогда-то знаменитый посох был обнаружен и возвращен в Даларан.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','После падения Каражана Кирин-Тор послал группу магов, чтобы обыскать башню и вынести из нее все нужное… для "исследований". Тогда-то знаменитый посох был обнаружен и возвращен в Даларан.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8393,'А потом развернулись трагические события… Каждый маг Кирин-Тора, соприкасавшийся с Атиешем, погибал.$B$BВидишь ли, это был артефакт с элементами сознания. А сознание он получил от Саргераса…') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','А потом развернулись трагические события… Каждый маг Кирин-Тора, соприкасавшийся с Атиешем, погибал.$B$BВидишь ли, это был артефакт с элементами сознания. А сознание он получил от Саргераса…',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8395,'Рассказывать особо нечего. Даларан был почти полностью уничтожен Архимондом, а посох пропал. Предположительно, его уничтожили защитные механизмы барьера.$B$BНо некоторые верят, что именно из-за этого посоха Архимонд может вернуться.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Рассказывать особо нечего. Даларан был почти полностью уничтожен Архимондом, а посох пропал. Предположительно, его уничтожили защитные механизмы барьера.$B$BНо некоторые верят, что именно из-за этого посоха Архимонд может вернуться.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8396,'После падения Даларана я оставила Кирин-Тор. Я охраняла Атиеш долгие годы, а потом лишилась смысла пребывания в Кирин-Тор в мгновение ока. Я решила найти посох, положив на эту всю свою жизнь. Вот почему я вступила в ряды Серебряного Рассвета и оказалась здесь.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','После падения Даларана я оставила Кирин-Тор. Я охраняла Атиеш долгие годы, а потом лишилась смысла пребывания в Кирин-Тор в мгновение ока. Я решила найти посох, положив на эту всю свою жизнь. Вот почему я вступила в ряды Серебряного Рассвета и оказалась здесь.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8397,'Разыскивая фрагменты посоха по всему миру, я узнала, что Кел\'Тузад тоже собирается его восстановить. Он уже нашел несколько частей посоха и передал их на хранение своим самым верным помощникам.$B$BЯ не могу выразить словами, насколько важно, чтобы большой посох Стража не достался Кел\'Тузаду. Если это произойдет, нас ждет вселенская катастрофа.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Разыскивая фрагменты посоха по всему миру, я узнала, что Кел\'Тузад тоже собирается его восстановить. Он уже нашел несколько частей посоха и передал их на хранение своим самым верным помощникам.$B$BЯ не могу выразить словами, насколько важно, чтобы большой посох Стража не достался Кел\'Тузаду. Если это произойдет, нас ждет вселенская катастрофа.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8398,'Это сила, глупое создание.$B$B*Взгляд Матеуса темнеет.*$B$BЭти безумцы посылают таких, как ты, в Наксрамас за оскверненными доспехами. Они надеются очистить их и вернуть себе кусочек былой славы.$B$B*Матеус сплевывает.*$B$BОт одной мысли об этом у меня начинается изжога.$B$BЯ тоже ищу эти доспехи, но мне они нужны именно в нынешнем, оскверненном виде.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Это сила, глупое создание.$B$B*Взгляд Матеуса темнеет.*$B$BЭти безумцы посылают таких, как ты, в Наксрамас за оскверненными доспехами. Они надеются очистить их и вернуть себе кусочек былой славы.$B$B*Матеус сплевывает.*$B$BОт одной мысли об этом у меня начинается изжога.$B$BЯ тоже ищу эти доспехи, но мне они нужны именно в нынешнем, оскверненном виде.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8399,'Ничего это не отговорки, придурок. Тьма, заключенная в подобных вещах, запросто может уничтожить нас обоих. Потому-то цена так высока. Если мне предстоит умереть, я намерен умереть богачом.$B$BИ мне глубоко начхать, как ты умрешь, – мне только нужно, чтоб ты сделал, как я говорю. Принеси то, что мне нужно, – и мы оба будем в выигрыше или умрем, но это я уже объяснил...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ничего это не отговорки, придурок. Тьма, заключенная в подобных вещах, запросто может уничтожить нас обоих. Потому-то цена так высока. Если мне предстоит умереть, я намерен умереть богачом.$B$BИ мне глубоко начхать, как ты умрешь, – мне только нужно, чтоб ты сделал, как я говорю. Принеси то, что мне нужно, – и мы оба будем в выигрыше или умрем, но это я уже объяснил...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8401,'Здравствуйте, путники. Мне приказано принимать всех, кто обладает ключом от Каражана, как почетных гостей моего господина. Можете спрашивать меня о чем пожелаете. Чем я могу вам помочь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здравствуйте, путники. Мне приказано принимать всех, кто обладает ключом от Каражана, как почетных гостей моего господина. Можете спрашивать меня о чем пожелаете. Чем я могу вам помочь?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8404,'А, гости Наставника. Надеюсь, вы были внимательны по пути сюда.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','А, гости Наставника. Надеюсь, вы были внимательны по пути сюда.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8406,'Будь прокляты все эти ядовитые твари! Полагаю, вы не сумеете мне помочь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Будь прокляты все эти ядовитые твари! Полагаю, вы не сумеете мне помочь?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (8407,'Я не могу учить тауренов езде на ящерах.','Я не могу учить тауренов езде на ящерах.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я не могу учить тауренов езде на ящерах.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я не могу учить тауренов езде на ящерах.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8410,'Еще один чудесный мрачный день в Транквиллионе, не так ли, |3-6($c)?..$B$BЧем я могу тебе помочь?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Еще один чудесный мрачный день в Транквиллионе, не так ли, |3-6($c)?..$B$BЧем я могу тебе помочь?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8411,'Нет большей свободы, чем парить высоко в небесах, |3-6($c). Чем я могу тебе помочь сегодня?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Нет большей свободы, чем парить высоко в небесах, |3-6($c). Чем я могу тебе помочь сегодня?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8412,'Приветствую тебя! Чем я могу помочь на этот раз?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приветствую тебя! Чем я могу помочь на этот раз?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8413,'Ну что, |3-6($c), ты прямо сегодня отправишься в Транквиллион или тебе все еще нужна моя помощь?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ну что, |3-6($c), ты прямо сегодня отправишься в Транквиллион или тебе все еще нужна моя помощь?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8414,'Ага, хороший вопрос.$B$BЕсли предпочитаешь охотиться на открытых пространствах, в Чумных землях, Азшаре, Пылающих степях, Оскверненном лесу, Силитусе, Зимних Ключах, и даже Кратере Ун\'Горо полно элементалей.$B$BЕсли ты из тех, кто смеется в лицо опасностям, тебе, возможно, стоит наведаться в Забытый Город. Я слышала, что в его стенах есть много стихийных аномалий. Еще неплохо было бы тебе поискать элементалей, что на службе у дворфов Черного Железа в глубинах Черной горы.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ага, хороший вопрос.$B$BЕсли предпочитаешь охотиться на открытых пространствах, в Чумных землях, Азшаре, Пылающих степях, Оскверненном лесу, Силитусе, Зимних Ключах, и даже Кратере Ун\'Горо полно элементалей.$B$BЕсли ты из тех, кто смеется в лицо опасностям, тебе, возможно, стоит наведаться в Забытый Город. Я слышала, что в его стенах есть много стихийных аномалий. Еще неплохо было бы тебе поискать элементалей, что на службе у дворфов Черного Железа в глубинах Черной горы.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8416,'Если ты предпочитаешь охотиться на открытом воздухе, древни Оскверненного леса и хлестуны Ун\'Горо – отличный источник ростков.$B$BЕсли же ты $gсклонен:склонна; рисковать, в восточном и западном секторах Забытого Города есть почти неограниченные запасы диких ростков.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Если ты предпочитаешь охотиться на открытом воздухе, древни Оскверненного леса и хлестуны Ун\'Горо – отличный источник ростков.$B$BЕсли же ты $gсклонен:склонна; рисковать, в восточном и западном секторах Забытого Города есть почти неограниченные запасы диких ростков.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8417,'Смотри, |3-6($c), что они сделали с нашей любимой землей. Плеть должна быть уничтожена!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Смотри, |3-6($c), что они сделали с нашей любимой землей. Плеть должна быть уничтожена!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8418,'Думаю, мы можем спасти жизнь этого эльфа крови, хотя это будет и нелегко.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Думаю, мы можем спасти жизнь этого эльфа крови, хотя это будет и нелегко.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8419,'Кто ты? Мне… так… холодно.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Кто ты? Мне… так… холодно.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8421,'Мы, син\'дорай, потеряли те земли, которые называли домом. Это наша беда и наш позор. Но скоро мы восстановим силы и вернем себе южные земли, отвоевав их у Плети!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мы, син\'дорай, потеряли те земли, которые называли домом. Это наша беда и наш позор. Но скоро мы восстановим силы и вернем себе южные земли, отвоевав их у Плети!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8422,'Я слишком занят, чтоб играть с тобой в угадайку, |3-6($r). Говори, что у тебя за дело, или сгинь с глаз моих!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я слишком занят, чтоб играть с тобой в угадайку, |3-6($r). Говори, что у тебя за дело, или сгинь с глаз моих!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8423,'Верховный палач и госпожа Златилен заставляют себя ждать, но у меня нет времени на это! Мои друзья гибнут, |3-6($c)!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Верховный палач и госпожа Златилен заставляют себя ждать, но у меня нет времени на это! Мои друзья гибнут, |3-6($c)!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8424,'Я отправила Салиссу на юг в анклав, а Летвалина – на запад в Транквиллион. С тех пор прошло уже больше суток! Ты не $gвидел:видела; кого-нибудь из них? Не тебя ли прислали на помощь?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я отправила Салиссу на юг в анклав, а Летвалина – на запад в Транквиллион. С тех пор прошло уже больше суток! Ты не $gвидел:видела; кого-нибудь из них? Не тебя ли прислали на помощь?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8425,'Иногда мне кажется, что никогда не вернусь на службу к госпоже Златилен. Все-таки война – это не мое.$B$BКак хорошо, что есть такие, как ты! Вы на все готовы, чтобы вернуть Кель\'Таласу былое величие. Что ж, разгроми Плеть, |3-6($c)! Не оставь от них и мокрого места!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Иногда мне кажется, что никогда не вернусь на службу к госпоже Златилен. Все-таки война – это не мое.$B$BКак хорошо, что есть такие, как ты! Вы на все готовы, чтобы вернуть Кель\'Таласу былое величие. Что ж, разгроми Плеть, |3-6($c)! Не оставь от них и мокрого места!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8428,'Мне сообщили, что ты можешь помочь следопыту Валанне и лейтенанту в Зеб\'Соре.$B$BСпасибо тебе, |3-6($c). Думаю, теперь я могу вернуться обратно в Анклав Странников.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мне сообщили, что ты можешь помочь следопыту Валанне и лейтенанту в Зеб\'Соре.$B$BСпасибо тебе, |3-6($c). Думаю, теперь я могу вернуться обратно в Анклав Странников.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8429,'Что привело тебя сюда, |3-6($c)?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что привело тебя сюда, |3-6($c)?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8431,'А, привет, |3-6($r). Как видишь, я еще не открылся. Извини, я очень занят.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','А, привет, |3-6($r). Как видишь, я еще не открылся. Извини, я очень занят.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8432,'Такое удовольствие – видеть тебя снова, |3-6($c). Нет, правда. Ведь ты – источник моих денег.$B$BИтак, что я могу предложить тебе сегодня?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Такое удовольствие – видеть тебя снова, |3-6($c). Нет, правда. Ведь ты – источник моих денег.$B$BИтак, что я могу предложить тебе сегодня?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8433,'Добро пожаловать в Транквиллион, |3-6($c). Прошу извинить за его состояние. Как видишь, у нас тут некоторые неприятности, но Отрекшиеся и их повелительница, Сильвана Ветрокрылая, были настолько любезны, что помогли нам в беде.$B$BЕсли и ты можешь нам помочь – прошу, сделай это без колебания. В нашей борьбе с ордами злобных врагов нам пригодится любая помощь.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Добро пожаловать в Транквиллион, |3-6($c). Прошу извинить за его состояние. Как видишь, у нас тут некоторые неприятности, но Отрекшиеся и их повелительница, Сильвана Ветрокрылая, были настолько любезны, что помогли нам в беде.$B$BЕсли и ты можешь нам помочь – прошу, сделай это без колебания. В нашей борьбе с ордами злобных врагов нам пригодится любая помощь.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8435,'Не бойся меча, ничтожество. Да тебя даже овца загрызет!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не бойся меча, ничтожество. Да тебя даже овца загрызет!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8438,'Жуть, что случилось с мулами-то… Метц с меня за этот промах шкуру спустит.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Жуть, что случилось с мулами-то… Метц с меня за этот промах шкуру спустит.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8441,'Ты из подкрепления? Ночные эльфы разбиты!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты из подкрепления? Ночные эльфы разбиты!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8442,'Хорошо, что ты $gдеактивировал:деактивировала; лунный кристалл в Ан\'овине, |3-6($c)! Приходи в любое время, когда пожелаешь присоединиться к моим исследованиям.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Хорошо, что ты $gдеактивировал:деактивировала; лунный кристалл в Ан\'овине, |3-6($c)! Приходи в любое время, когда пожелаешь присоединиться к моим исследованиям.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8445,'И как можно работать в таких условиях?! Да еще вокруг эти мерзкие Отрекшиеся! Хочу в Транквиллион и Кель\'Талас!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','И как можно работать в таких условиях?! Да еще вокруг эти мерзкие Отрекшиеся! Хочу в Транквиллион и Кель\'Талас!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8447,'$R, докладывай! Что за новости чрезвычайной важности ты $gпринес:принесла;? Да побыстрее… Мы с госпожой Златилен как раз ведем дискуссию о стратегии.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','$R, докладывай! Что за новости чрезвычайной важности ты $gпринес:принесла;? Да побыстрее… Мы с госпожой Златилен как раз ведем дискуссию о стратегии.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8452,'Наши караваны уходят два раза в день, но будь я проклят, если Плеть не уберется с наших путей, чтобы остановить Дидье и его мулов при попытке доставить подкрепление на фронт. Самая сумасшедшая вещь, что я когда-либо видел. Если бы только у нас были героические искатели приключений, чтобы помочь защитить караван…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Наши караваны уходят два раза в день, но будь я проклят, если Плеть не уберется с наших путей, чтобы остановить Дидье и его мулов при попытке доставить подкрепление на фронт. Самая сумасшедшая вещь, что я когда-либо видел. Если бы только у нас были героические искатели приключений, чтобы помочь защитить караван…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (8454,'У меня много дел и мало времени, |3-6($r)! Пожалуйста, не мешай.','У меня много дел и мало времени, |3-6($r)! Пожалуйста, не мешай.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','У меня много дел и мало времени, |3-6($r)! Пожалуйста, не мешай.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','У меня много дел и мало времени, |3-6($r)! Пожалуйста, не мешай.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (8455,'У меня слишком много дел и слишком мало времени, |3-6($r)! Пожалуйста, уйди с моего пути!$B$BЕсли ты $gболен:больна; слизняком или вурдалачьим гноем, я могу тебе помочь.','У меня слишком много дел и слишком мало времени, |3-6($r)! Пожалуйста, уйди с моего пути!$B$BЕсли ты $gболен:больна; слизняком или вурдалачьим гноем, я могу тебе помочь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','У меня слишком много дел и слишком мало времени, |3-6($r)! Пожалуйста, уйди с моего пути!$B$BЕсли ты $gболен:больна; слизняком или вурдалачьим гноем, я могу тебе помочь.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','У меня слишком много дел и слишком мало времени, |3-6($r)! Пожалуйста, уйди с моего пути!$B$BЕсли ты $gболен:больна; слизняком или вурдалачьим гноем, я могу тебе помочь.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8456,'*После того как вы даете эльфу крови лекарство, он быстро приходит в себя.*$B$BЯ обязан вам жизнью, |3-6($c). Без вашей помощи я бы не пережил пыток Плети.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','*После того как вы даете эльфу крови лекарство, он быстро приходит в себя.*$B$BЯ обязан вам жизнью, |3-6($c). Без вашей помощи я бы не пережил пыток Плети.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8459,'*На полу лежит, скорчившись, женщина-Отрекшаяся. Ее лицо искажено. Похоже, она не в силах встать.*') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','*На полу лежит, скорчившись, женщина-Отрекшаяся. Ее лицо искажено. Похоже, она не в силах встать.*',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8460,'Оххх… Голова раскалывается… $B$BТебя прислали мне на помощь, да? Долго же тянули! Ты хоть представляешь, что здесь делают с пленниками?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Оххх… Голова раскалывается… $B$BТебя прислали мне на помощь, да? Долго же тянули! Ты хоть представляешь, что здесь делают с пленниками?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8461,'*На столе лежит эльф крови. Он еще дышит, но, похоже, находится под воздействием сильнодействующего седативного вещества.*') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','*На столе лежит эльф крови. Он еще дышит, но, похоже, находится под воздействием сильнодействующего седативного вещества.*',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8462,'Верно, |3-6($r). Я здесь в качестве советника верховного палача; как он применит мои советы – его дело. Я уверен, что общими усилиями мы сделаем Орду еще более мощной, чем раньше, и раз и навсегда уничтожим угрозу, исходящую от Плети!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Верно, |3-6($r). Я здесь в качестве советника верховного палача; как он применит мои советы – его дело. Я уверен, что общими усилиями мы сделаем Орду еще более мощной, чем раньше, и раз и навсегда уничтожим угрозу, исходящую от Плети!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8463,'*Варнис сильно кашляет, когда исцеляющее лекарство начинает действовать.*$B$BСпасибо тебе за то, что $gспас:спасла; меня. Я должен немедленно вернуться к Транквиллиону!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','*Варнис сильно кашляет, когда исцеляющее лекарство начинает действовать.*$B$BСпасибо тебе за то, что $gспас:спасла; меня. Я должен немедленно вернуться к Транквиллиону!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8464,'Порывы свежего ветра, частенько дующего из Вечной Песни, расстраивают мой желудок, если ты понимаешь, о чем я.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Порывы свежего ветра, частенько дующего из Вечной Песни, расстраивают мой желудок, если ты понимаешь, о чем я.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8466,'Если вы хотите обсудить вопросы импорта, |3-6($c), вам уместнее попросить аудиенции у госпожи Златилен. Но предупреждаю: она очень занята. Возможно, вам придется подождать.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Если вы хотите обсудить вопросы импорта, |3-6($c), вам уместнее попросить аудиенции у госпожи Златилен. Но предупреждаю: она очень занята. Возможно, вам придется подождать.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8467,'Вообще-то не мое дело говорить с тобой лично; тебе бы следовало искать встречи с миледи. С другой стороны, я уже давала тебе задание… Ну, так что же нам надо обсудить теперь?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Вообще-то не мое дело говорить с тобой лично; тебе бы следовало искать встречи с миледи. С другой стороны, я уже давала тебе задание… Ну, так что же нам надо обсудить теперь?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8468,'$C, госпожа Златилен с чрезвычайной похвалой отзывалась о том, что тебе довелось сделать для нас. Она также выражает надежду, что ты еще не раз выступишь на защиту син\'дорай в Призрачных землях.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','$C, госпожа Златилен с чрезвычайной похвалой отзывалась о том, что тебе довелось сделать для нас. Она также выражает надежду, что ты еще не раз выступишь на защиту син\'дорай в Призрачных землях.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8472,'Да уж, ну и дела! И как мне теперь собирать для магистров образцы руды, если все шахты заполонили вонючие гноллы?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Да уж, ну и дела! И как мне теперь собирать для магистров образцы руды, если все шахты заполонили вонючие гноллы?',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8473,'Спасибо, что $gдостал:достала; этот минерал и $gдоставил:доставила; магистру Квалестису, |3-6($c). Мне тоже надо бы вернуться – вот только боюсь, меня накажут за то, что я не добыла руду сама.$B$BНе говори ничего магистру, ладно?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Спасибо, что $gдостал:достала; этот минерал и $gдоставил:доставила; магистру Квалестису, |3-6($c). Мне тоже надо бы вернуться – вот только боюсь, меня накажут за то, что я не добыла руду сама.$B$BНе говори ничего магистру, ладно?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8474,'Где же она? Я не так давно послал свою ученицу Шатарию на запад, к Беспросветным рудникам. Нам необходимо получить некоторые образцы руды, и как можно быстрее, иначе наш эксперимент провалится!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Где же она? Я не так давно послал свою ученицу Шатарию на запад, к Беспросветным рудникам. Нам необходимо получить некоторые образцы руды, и как можно быстрее, иначе наш эксперимент провалится!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8475,'Если бы мы не получили руду из Беспросветных рудников вовремя, у нас сорвались бы все исследования.$B$BПусть только Шатария покажет сюда свой нос, я ей таких интересных заданий дам, надолго запомнит!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если бы мы не получили руду из Беспросветных рудников вовремя, у нас сорвались бы все исследования.$B$BПусть только Шатария покажет сюда свой нос, я ей таких интересных заданий дам, надолго запомнит!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8476,'Син\'дорай слишком многое потеряли за прошедшие годы. Землю, дома, даже самобытность…$B$BНо близок час, когда мы вернем все это себе.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Син\'дорай слишком многое потеряли за прошедшие годы. Землю, дома, даже самобытность…$B$BНо близок час, когда мы вернем все это себе.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8477,'Прежде чем мы сумеем преодолеть препятствия внешние, наподобие Плети и троллей Амани, нам необходимо преодолеть препятствия внутренние. Презренные достаточно мешали нам. Пора их покорить.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Прежде чем мы сумеем преодолеть препятствия внешние, наподобие Плети и троллей Амани, нам необходимо преодолеть препятствия внутренние. Презренные достаточно мешали нам. Пора их покорить.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8478,'Думаешь, ты сможешь помочь мне выбраться отсюда?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Думаешь, ты сможешь помочь мне выбраться отсюда?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8479,'Среди различных кусков рукописей, содержащих техническую документацию и другую информацию о Странниках, один лежит отдельно. На нем изображен ужасный тролль, возможно, самое страшное существо, которое ты когда-либо $gвидел:видела;!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Среди различных кусков рукописей, содержащих техническую документацию и другую информацию о Странниках, один лежит отдельно. На нем изображен ужасный тролль, возможно, самое страшное существо, которое ты когда-либо $gвидел:видела;!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8480,'Действительно, Зимние Ключи пытаются противостоять новым нападениям Плети. Твоя помощь была бы неоценима.$B$BСейчас там $2284W |4некрополь:некрополя:некрополей;.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Действительно, Зимние Ключи пытаются противостоять новым нападениям Плети. Твоя помощь была бы неоценима.$B$BСейчас там $2284W |4некрополь:некрополя:некрополей;.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8481,'Пока что на этой территории нет войск Плети. Но, боюсь, их возвращение – только вопрос времени.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Пока что на этой территории нет войск Плети. Но, боюсь, их возвращение – только вопрос времени.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8484,'Если немедленно не отправить дополнительную помощь в Пылающие степи, то, боюсь, Плеть полностью захватит эти земли. Если можешь, отправляйся туда и помоги обороняющимся.$B$BЧисленность некрополей на данный момент – $2281W.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если немедленно не отправить дополнительную помощь в Пылающие степи, то, боюсь, Плеть полностью захватит эти земли. Если можешь, отправляйся туда и помоги обороняющимся.$B$BЧисленность некрополей на данный момент – $2281W.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8486,'Плеть создает небольшие опорные пункты в атакуемых районах, а для связи и снабжения использует летающие некрополи. Судя по тому, что нам известно, избавиться от них можно только одним способом: уничтожив наземные войска под ними.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Плеть создает небольшие опорные пункты в атакуемых районах, а для связи и снабжения использует летающие некрополи. Судя по тому, что нам известно, избавиться от них можно только одним способом: уничтожив наземные войска под ними.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8488,'Сбившиеся с пути тайные силы могут творить странные вещи с землей, стихиями и даже духами мертвых.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Сбившиеся с пути тайные силы могут творить странные вещи с землей, стихиями и даже духами мертвых.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8489,'Верховный палач и без того обременен массой дел, |3-6($c). Может, я могу как-нибудь помочь тебе?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Верховный палач и без того обременен массой дел, |3-6($c). Может, я могу как-нибудь помочь тебе?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8491,'Рад снова видеть тебя, $gпарень:красавица;! Работать с тобой одно удовольствие, $gувидимся:надеюсь, не в последний раз;.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Рад снова видеть тебя, $gпарень:красавица;! Работать с тобой одно удовольствие, $gувидимся:надеюсь, не в последний раз;.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8495,'Твоя помощь с троллями Призрачной Сосны была неоценима, |3-6($c). Продолжай в том же духе – и может быть, мы сможем вновь сосредоточить наше внимание на борьбе с Плетью.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Твоя помощь с троллями Призрачной Сосны была неоценима, |3-6($c). Продолжай в том же духе – и может быть, мы сможем вновь сосредоточить наше внимание на борьбе с Плетью.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8505,'Ну, ты же здесь не чтобы чаи гонять. Посмотрим, как ты сможешь нам помочь.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ну, ты же здесь не чтобы чаи гонять. Посмотрим, как ты сможешь нам помочь.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8506,'Кое-кто утверждает, что Серебряный Авангард остался лишь в прошлом, и я – один из них. Но дело не в том, что Плеть пала.$B$BНет... все дело в том, что они закоснели. Стали похожи на церковь, от которой они когда-то откололись. Их ослепили идеалы чести и порядка. Именно это я и пытался объяснить Барталомею.$B$BДа, конечно, это отдает шовинизмом, но это отличная тема для разговора.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Кое-кто утверждает, что Серебряный Авангард остался лишь в прошлом, и я – один из них. Но дело не в том, что Плеть пала.$B$BНет... все дело в том, что они закоснели. Стали похожи на церковь, от которой они когда-то откололись. Их ослепили идеалы чести и порядка. Именно это я и пытался объяснить Барталомею.$B$BДа, конечно, это отдает шовинизмом, но это отличная тема для разговора.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8513,'Мастер-ремесленник Омарион однажды ночью просто исчез. Прямо как растворился… Ффф! И нету! Выходит, кроме меня, теперь и некому делать товары для фронта.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мастер-ремесленник Омарион однажды ночью просто исчез. Прямо как растворился… Ффф! И нету! Выходит, кроме меня, теперь и некому делать товары для фронта.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8517,'*Тарсис стонет.*$B$BМожет, еще не поздно... Слушай меня внимательно.$B$BЯ обыскал все время и всю Пустоту. Но сделки с повелителем зла и жестокости никогда не бывают честными...$B$B*Тарсис кашляет кровью.*$B$BМожешь ли ты... поверить, что сама Элуна отвернулась от меня, |3-6($r)? И теперь я умираю здесь, вот так...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','*Тарсис стонет.*$B$BМожет, еще не поздно... Слушай меня внимательно.$B$BЯ обыскал все время и всю Пустоту. Но сделки с повелителем зла и жестокости никогда не бывают честными...$B$B*Тарсис кашляет кровью.*$B$BМожешь ли ты... поверить, что сама Элуна отвернулась от меня, |3-6($r)? И теперь я умираю здесь, вот так...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8518,'Что я наделал... Чудовищно, непредставимо...$B$B*Тарсис начинает всхлипывать.*') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что я наделал... Чудовищно, непредставимо...$B$B*Тарсис начинает всхлипывать.*',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8519,'Я из высокорожденных, |3-6($r). Теперь это ничего не значит. Однако раньше высокорожденные правили этим миром. С тех пор прошло десять тысяч лет...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я из высокорожденных, |3-6($r). Теперь это ничего не значит. Однако раньше высокорожденные правили этим миром. С тех пор прошло десять тысяч лет...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8520,'Я бы получил это назад. Атиеш... Из него я создал бы высокорожденных заново. Я вернул бы все. Даже королеву...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я бы получил это назад. Атиеш... Из него я создал бы высокорожденных заново. Я вернул бы все. Даже королеву...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8521,'*Тарсис слабеющей рукой вцепляется в твой ворот. Даже в преддверии смерти его глаза лучатся невероятной силой.*$B$BВот как? Тогда послушай: я хочу поведать тебе еще несколько глупостей. В этой цитадели хранится труд всей моей жизни – в нем обозначено точное местонахождение каждого кусочка расщепленного посоха.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','*Тарсис слабеющей рукой вцепляется в твой ворот. Даже в преддверии смерти его глаза лучатся невероятной силой.*$B$BВот как? Тогда послушай: я хочу поведать тебе еще несколько глупостей. В этой цитадели хранится труд всей моей жизни – в нем обозначено точное местонахождение каждого кусочка расщепленного посоха.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8522,'Атиеш, посох Хранителя. Этот посох с незапамятных времен переходил от одного Хранителя Тирисфаля к другому. Посох, оскверненный Саргерасом. Посох последнего Хранителя. Посох Медива.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Атиеш, посох Хранителя. Этот посох с незапамятных времен переходил от одного Хранителя Тирисфаля к другому. Посох, оскверненный Саргерасом. Посох последнего Хранителя. Посох Медива.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8523,'*Глаза Тарсиса загораются.*$B$BЯ обладал ею когда-то... Я обладал ею, несмотря на предупреждения Кирин-Тора. Я обладал ею, смертный... Бесконечной силой. Силой делать что пожелаю и как пожелаю. И очень быстро ее отобрали у меня. Но я вкусил... И ради этого вкуса стоило рисковать.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','*Глаза Тарсиса загораются.*$B$BЯ обладал ею когда-то... Я обладал ею, несмотря на предупреждения Кирин-Тора. Я обладал ею, смертный... Бесконечной силой. Силой делать что пожелаю и как пожелаю. И очень быстро ее отобрали у меня. Но я вкусил... И ради этого вкуса стоило рисковать.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8524,'*Тарсис тяжело ранен.*') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','*Тарсис тяжело ранен.*',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (8526,'Чаша весов склоняется в нашу сторону. Силы Плети, кажется, истощены. Я уверен, что изгнание Плети – лишь дело времени. Я помогу тебе в этой борьбе своей магией.','Чаша весов склоняется в нашу сторону. Силы Плети, кажется, истощены. Я уверена, что изгнание Плети – лишь дело времени. Я помогу тебе в этой борьбе своей магией.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Чаша весов склоняется в нашу сторону. Силы Плети, кажется, истощены. Я уверен, что изгнание Плети – лишь дело времени. Я помогу тебе в этой борьбе своей магией.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Чаша весов склоняется в нашу сторону. Силы Плети, кажется, истощены. Я уверена, что изгнание Плети – лишь дело времени. Я помогу тебе в этой борьбе своей магией.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (8527,'Первый этап нашей борьбы против Плети прошел хорошо. Мы добились некоторых успехов. Надеюсь, моя помощь приведет тебя к дальнейшим победам.','Первый этап нашей борьбы против Плети прошел хорошо. Мы добились некоторых успехов. Надеюсь, моя помощь приведет тебя к дальнейшим победам.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Первый этап нашей борьбы против Плети прошел хорошо. Мы добились некоторых успехов. Надеюсь, моя помощь приведет тебя к дальнейшим победам.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Первый этап нашей борьбы против Плети прошел хорошо. Мы добились некоторых успехов. Надеюсь, моя помощь приведет тебя к дальнейшим победам.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8529,'Он был утрачен, когда пала Аметистовая цитадель... Расколот на 42 части.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Он был утрачен, когда пала Аметистовая цитадель... Расколот на 42 части.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8530,'Кел\'Тузад приложил изрядные усилия, пытаясь воссоздать посох. Части его были некогда рассеяны по миру, от Калимдора до Южных морей. У меня у самого когда-то было двадцать частей, пока их не украли у меня приспешники Кел\'Тузада. Потому-то я здесь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Кел\'Тузад приложил изрядные усилия, пытаясь воссоздать посох. Части его были некогда рассеяны по миру, от Калимдора до Южных морей. У меня у самого когда-то было двадцать частей, пока их не украли у меня приспешники Кел\'Тузада. Потому-то я здесь.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8531,'Ты что, не $gслушал:слушала;? Нет, я очень сомневаюсь, что мы могли бы сейчас говорить, если бы Кел\'Тузад собрал посох. Кел\'Тузад не теряет головы. 40 обломков Атиеша находятся у его подчиненных. Последний кусок – основной – был найден Бранном Бронзобородом. Последний раз его видели в пустыне Силитуса, несомненно, делающего все, чтобы убежать как можно дальше от безжалостных охотников, которых Кел\'Тузад разослал по всему миру.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты что, не $gслушал:слушала;? Нет, я очень сомневаюсь, что мы могли бы сейчас говорить, если бы Кел\'Тузад собрал посох. Кел\'Тузад не теряет головы. 40 обломков Атиеша находятся у его подчиненных. Последний кусок – основной – был найден Бранном Бронзобородом. Последний раз его видели в пустыне Силитуса, несомненно, делающего все, чтобы убежать как можно дальше от безжалостных охотников, которых Кел\'Тузад разослал по всему миру.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8534,'Наши святилища поглощают тайную магию силовых линий, незримыми потоками пересекающих землю.$B$BПосле разрушения Солнечного Колодца они служат нам надежным источником энергии.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Наши святилища поглощают тайную магию силовых линий, незримыми потоками пересекающих землю.$B$BПосле разрушения Солнечного Колодца они служат нам надежным источником энергии.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (8536,'Дорогу, грязный пес! Ревилгаз избавил меня от виселицы, но мое наказание может быть почти таким же скверным.','Дорогу, грязный пес! Ревилгаз избавил меня от виселицы, но мое наказание может быть почти таким же скверным.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Дорогу, грязный пес! Ревилгаз избавил меня от виселицы, но мое наказание может быть почти таким же скверным.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Дорогу, грязный пес! Ревилгаз избавил меня от виселицы, но мое наказание может быть почти таким же скверным.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8539,'Чем я могу помочь тебе? Нет, постой! Чем ты можешь мне помочь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Чем я могу помочь тебе? Нет, постой! Чем ты можешь мне помочь?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8550,'Это заказ из виллы Салтерила? Несомненно, его светлости нужна бутылка моего лучшего вина. И, конечно, всякий друг лорда Салтерила имеет право купить такое же вино по специальной цене…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Это заказ из виллы Салтерила? Несомненно, его светлости нужна бутылка моего лучшего вина. И, конечно, всякий друг лорда Салтерила имеет право купить такое же вино по специальной цене…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8552,'Если у тебя есть деньги, у меня есть еда и питье для тебя. Каждая монетка идет на поддержание и развитие приюта.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Если у тебя есть деньги, у меня есть еда и питье для тебя. Каждая монетка идет на поддержание и развитие приюта.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8553,'Это у тебя там список от лорда Салтерила? Да, я могу продать тебе немного освежающих напитков…') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Это у тебя там список от лорда Салтерила? Да, я могу продать тебе немного освежающих напитков…',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8556,'У меня есть товары на любой вкус, |3-6($c). Вот, полюбуйся!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','У меня есть товары на любой вкус, |3-6($c). Вот, полюбуйся!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8557,'Список… как интересно. Ах да, партия фейерверков для лорда Салтерила. Он не заплатил за них. Вы приехали, чтобы выкупить их от его имени, да, |3-6($c)?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Список… как интересно. Ах да, партия фейерверков для лорда Салтерила. Он не заплатил за них. Вы приехали, чтобы выкупить их от его имени, да, |3-6($c)?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8558,'Закончится ли когда-нибудь эта нежить? Похоже, что, когда мы убиваем вурдалака или скелета, двое новых занимают его место.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Закончится ли когда-нибудь эта нежить? Похоже, что, когда мы убиваем вурдалака или скелета, двое новых занимают его место.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8561,'$C, не встречался ли тебе курьер по дороге сюда? Мы ожидаем послания из Луносвета, и их гонец опаздывает!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','$C, не встречался ли тебе курьер по дороге сюда? Мы ожидаем послания из Луносвета, и их гонец опаздывает!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8565,'Мы действительно должны найти лучший способ расправиться с этими зловонными троллями Призрачной Сосны!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы действительно должны найти лучший способ расправиться с этими зловонными троллями Призрачной Сосны!',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8567,'Нам действительно необходимо улучшить ведение дел с этими вонючими троллями Призрачной Сосны.$B$BО, не обижайся, |3-6($c).$B$B*Аптекарь наивно улыбается и пожимает плечами.*') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Нам действительно необходимо улучшить ведение дел с этими вонючими троллями Призрачной Сосны.$B$BО, не обижайся, |3-6($c).$B$B*Аптекарь наивно улыбается и пожимает плечами.*',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8570,'Я рада, что ты $gпришел:пришла; на помощь, |3-6($c). Чем быстрее мы совладаем с этими троллями, тем быстрее сможем отправить войско Плети туда, откуда оно пришло.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я рада, что ты $gпришел:пришла; на помощь, |3-6($c). Чем быстрее мы совладаем с этими троллями, тем быстрее сможем отправить войско Плети туда, откуда оно пришло.',`text0_1_loc8`);
