INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (8589,'Мы, практикующие тайную магию и магию Стихий, идем по бесконечному пути открытий. Почему ты ищешь моего совета? Хочешь учиться дальше?','Мы, практикующие тайную магию и магию Стихий, идем по бесконечному пути открытий. Почему ты ищешь моего совета? Хочешь учиться дальше?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы, практикующие тайную магию и магию Стихий, идем по бесконечному пути открытий. Почему ты ищешь моего совета? Хочешь учиться дальше?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мы, практикующие тайную магию и магию Стихий, идем по бесконечному пути открытий. Почему ты ищешь моего совета? Хочешь учиться дальше?',`text0_1_loc8`);
