INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (8592,'Несмотря на то что не могу обучить тебя, $gюный:юная:c; |3-6($c), я могу дать тебе мое благословение. Ступай со Светом…','Несмотря на то что не могу обучить тебя, $gюный:юная; |3-6($c), я могу дать тебе мое благословение. Ступай со Светом…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Несмотря на то что не могу обучить тебя, $gюный:юная:c; |3-6($c), я могу дать тебе мое благословение. Ступай со Светом…',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Несмотря на то что не могу обучить тебя, $gюный:юная; |3-6($c), я могу дать тебе мое благословение. Ступай со Светом…',`text0_1_loc8`);
