INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (8618,'Я предоставляю самое надежное укрытие, какое только возможно в наших истерзанных землях.','Я предоставляю самое надежное укрытие, какое только возможно в наших истерзанных землях.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я предоставляю самое надежное укрытие, какое только возможно в наших истерзанных землях.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я предоставляю самое надежное укрытие, какое только возможно в наших истерзанных землях.',`text0_1_loc8`);
