INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8619,'Рад видеть тебя, $gбрат:сестра;! У меня от этого места мурашки. Пока ты здесь, извлекай выгоду из тех возможностей, что предоставляют эти так называемые Отрекшиеся.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Рад видеть тебя, $gбрат:сестра;! У меня от этого места мурашки. Пока ты здесь, извлекай выгоду из тех возможностей, что предоставляют эти так называемые Отрекшиеся.',`text0_0_loc8`);
