INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8634,'Уют – моя работа… Расслабься и успокойся, |3-6($r)… Чувствуй себя как дома…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Уют – моя работа… Расслабься и успокойся, |3-6($r)… Чувствуй себя как дома…',`text0_0_loc8`);
