INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8638,'Здравствуй, |3-6($c). Тебе непременно нужно поговорить со странницей Соланной, если, конечно, ты этого еще не $gсделал:сделала;.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Здравствуй, |3-6($c). Тебе непременно нужно поговорить со странницей Соланной, если, конечно, ты этого еще не $gсделал:сделала;.',`text0_1_loc8`);
