INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8642,'Если ты $gпотерял:потеряла; часть зандаларского доспеха, я могу помочь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если ты $gпотерял:потеряла; часть зандаларского доспеха, я могу помочь.',`text0_0_loc8`);
