INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8658,'Сид – вот как меня звать. Рад видеть новое лицо в наших краях. Чем могу помочь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Сид – вот как меня звать. Рад видеть новое лицо в наших краях. Чем могу помочь?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8662,'Все что угодно бы отдал за исцеляющий кристалл!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Все что угодно бы отдал за исцеляющий кристалл!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8665,'Спасибо, что $gпозаботился:позаботилась; об озере, корнехлестах и совунах, |3-6($c).') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Спасибо, что $gпозаботился:позаботилась; об озере, корнехлестах и совунах, |3-6($c).',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8666,'Твой поступок не подлежит обсуждению, |3-6($c). Ты $gсделал:сделала; то, что должно.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Твой поступок не подлежит обсуждению, |3-6($c). Ты $gсделал:сделала; то, что должно.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8669,'Еще раз спасибо за пополнение нашего запаса исцеляющих кристаллов. Говорят, ты помогаешь всем вокруг. Это благое дело!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Еще раз спасибо за пополнение нашего запаса исцеляющих кристаллов. Говорят, ты помогаешь всем вокруг. Это благое дело!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8672,'Миррен и я – два самых лучших охотника по эту сторону Темного портала. Оставайся с нами, и, может быть, переймешь кое-какой опыт.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Миррен и я – два самых лучших охотника по эту сторону Темного портала. Оставайся с нами, и, может быть, переймешь кое-какой опыт.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8673,'Надеюсь, вы не за нашим элем сюда явились. Мы не продадим ни капли!$B$BМы не виноваты, что кроме нас никто не додумался притащить в Запределье пива!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Надеюсь, вы не за нашим элем сюда явились. Мы не продадим ни капли!$B$BМы не виноваты, что кроме нас никто не додумался притащить в Запределье пива!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8675,'Существующее в Запределье демоническое создание гораздо более могущественно, чем все, что мы когда-либо видели в нашем старом мире. $B$BВеликая сила придет к любому, кто не испугается ее, но нужно учиться управлять и владеть ею.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Существующее в Запределье демоническое создание гораздо более могущественно, чем все, что мы когда-либо видели в нашем старом мире. $B$BВеликая сила придет к любому, кто не испугается ее, но нужно учиться управлять и владеть ею.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8676,'Я родился здесь, |3-6($r). Это мой мир, только его я и знаю. В детстве мама и папа рассказывали мне о вашем мире и обо всех его чудесах, а я мечтал поскорее покинуть это место.$B$BК сожалению, судьба ко мне не благоволила. Мои родители давно умерли и покоятся на этом самом кладбище, а я остался, чтобы хранить их честь и честь моей семьи – Сынов Лотара.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я родился здесь, |3-6($r). Это мой мир, только его я и знаю. В детстве мама и папа рассказывали мне о вашем мире и обо всех его чудесах, а я мечтал поскорее покинуть это место.$B$BК сожалению, судьба ко мне не благоволила. Мои родители давно умерли и покоятся на этом самом кладбище, а я остался, чтобы хранить их честь и честь моей семьи – Сынов Лотара.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (8678,'Чем могу служить?','Чем могу служить?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Чем могу служить?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Чем могу служить?',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8679,'Исчезни, отвратительная тварь! Не понимаю, как вообще кто-то может терпеть такую мерзость.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Исчезни, отвратительная тварь! Не понимаю, как вообще кто-то может терпеть такую мерзость.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8681,'Моего мужа нет уже несколько дней. Мы отправились в паломничество вместе, и завершить его должны были вместе.$B$BЯ так волнуюсь, что слишком часто теперь прикладываюсь к кристаллам маны.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Моего мужа нет уже несколько дней. Мы отправились в паломничество вместе, и завершить его должны были вместе.$B$BЯ так волнуюсь, что слишком часто теперь прикладываюсь к кристаллам маны.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8682,'Дракондоры, если их правильно растить, вполне ручные. Тебе не кажется, что это поразительно? Такие дружелюбные, если их правильно вырастить, и такие злобные и смертельно опасные в природе… Я просто обожаю их.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Дракондоры, если их правильно растить, вполне ручные. Тебе не кажется, что это поразительно? Такие дружелюбные, если их правильно вырастить, и такие злобные и смертельно опасные в природе… Я просто обожаю их.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8683,'Не… беспокойся… обо мне…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не… беспокойся… обо мне…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8684,'Мне совсем не кажется, что наши дела так уж плохи. Я уверена, что скоро все придет в норму и сила Солнечного Колодца будет восстановлена. Все не может быть так плохо, как все изображают.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мне совсем не кажется, что наши дела так уж плохи. Я уверена, что скоро все придет в норму и сила Солнечного Колодца будет восстановлена. Все не может быть так плохо, как все изображают.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8685,'Дружба с Солнечными Скитальцами окупила себя: я получил возможность заняться исследованием предметов, которые могу найти лишь в Запределье, и они получили возможность любоваться… моей обаятельной личностью и демонически приятной внешностью.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Дружба с Солнечными Скитальцами окупила себя: я получил возможность заняться исследованием предметов, которые могу найти лишь в Запределье, и они получили возможность любоваться… моей обаятельной личностью и демонически приятной внешностью.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8698,'Ты думаешь, я был жесток к этому гаду?$B$BОни только в этом месяце убили двух моих людей! Мы слишком добры к этим мерзавцам!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты думаешь, я был жесток к этому гаду?$B$BОни только в этом месяце убили двух моих людей! Мы слишком добры к этим мерзавцам!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`,`text1_1_loc8`) VALUES (8700,'Задание у меня всего одно – следить за порядком в Западном Святилище.$B$BПрости мне мою несдержанность – как видишь, все здесь пошло немного наперекосяк.','Уж не стоят ли за всем этим ночные эльфы? Хотя вряд ли. С таким грузом для Западного Святилища рано или поздно обязательно произошла бы какая-нибудь неприятность.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Задание у меня всего одно – следить за порядком в Западном Святилище.$B$BПрости мне мою несдержанность – как видишь, все здесь пошло немного наперекосяк.',`text0_1_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Уж не стоят ли за всем этим ночные эльфы? Хотя вряд ли. С таким грузом для Западного Святилища рано или поздно обязательно произошла бы какая-нибудь неприятность.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8701,'Теперь, когда императоры мертвы, магическая защита, не позволяющая телепортироваться в храм, изрядно ослабела. Если хочешь, я могу переместить тебя в логово императоров.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Теперь, когда императоры мертвы, магическая защита, не позволяющая телепортироваться в храм, изрядно ослабела. Если хочешь, я могу переместить тебя в логово императоров.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8702,'Со смертью Оуро открыта дорога в последнюю палату. Я могу доставить тебя туда, если пожелаешь.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Со смертью Оуро открыта дорога в последнюю палату. Я могу доставить тебя туда, если пожелаешь.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8712,'Если ты ищешь работу, |3-6($c), хватай кирку и начинай копать. Руины тянутся отсюда и насколько глаз хватает!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если ты ищешь работу, |3-6($c), хватай кирку и начинай копать. Руины тянутся отсюда и насколько глаз хватает!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8716,'Грустно наблюдать за тем, что произошло с этой землей. Кенарийская экспедиция сделает все возможное, чтобы разобраться в случившемся и возместить нанесенный ущерб.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Грустно наблюдать за тем, что произошло с этой землей. Кенарийская экспедиция сделает все возможное, чтобы разобраться в случившемся и возместить нанесенный ущерб.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8717,'Ты выглядишь потерянно, |3-6($c). Не заставляй меня отправлять тебя на работу к стенам вместе с другими батраками.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты выглядишь потерянно, |3-6($c). Не заставляй меня отправлять тебя на работу к стенам вместе с другими батраками.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8718,'Рада вас видеть, |3-6($c). Вы добрались в Траллмар как раз вовремя. Вождь надеется на нас, поскольку сам не может сюда приехать.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Рада вас видеть, |3-6($c). Вы добрались в Траллмар как раз вовремя. Вождь надеется на нас, поскольку сам не может сюда приехать.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8719,'Ты $gнужен:нужна; Траллмару, |3-6($c). Ты $gнужен:нужна; вождю. Будь $gготов:готова; исполнить свой долг.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты $gнужен:нужна; Траллмару, |3-6($c). Ты $gнужен:нужна; вождю. Будь $gготов:готова; исполнить свой долг.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (8724,'Немногие схватки выигрываются грубой силой. Обычно к победе приводят хитрость, рефлексы и знание своего оружия.','Немногие схватки выигрываются грубой силой. Обычно к победе приводят хитрость, рефлексы и знание своего оружия.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Немногие схватки выигрываются грубой силой. Обычно к победе приводят хитрость, рефлексы и знание своего оружия.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Немногие схватки выигрываются грубой силой. Обычно к победе приводят хитрость, рефлексы и знание своего оружия.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8750,'Добро пожаловать, |3-6($c).') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Добро пожаловать, |3-6($c).',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8751,'Мне не до болтовни, |3-6($c). Я должен позаботиться о паломниках и подготовить их к предстоящему долгому путешествию.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мне не до болтовни, |3-6($c). Я должен позаботиться о паломниках и подготовить их к предстоящему долгому путешествию.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8752,'Приветствую в Соколином Дозоре, |3-6($c). Я вижу нужды скитальцев и помогаю им в продолжении своих долгих странствий. Если ты еще не стал скитальцем, я могу помочь тебе, рассказав нужную информацию.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приветствую в Соколином Дозоре, |3-6($c). Я вижу нужды скитальцев и помогаю им в продолжении своих долгих странствий. Если ты еще не стал скитальцем, я могу помочь тебе, рассказав нужную информацию.',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8753,'Привет тебе, |3-6($c)!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Привет тебе, |3-6($c)!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8755,'Добро пожаловать в Обитель Странников. Мы скитальцы, поклявшиеся защищать наш народ от любого врага.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Добро пожаловать в Обитель Странников. Мы скитальцы, поклявшиеся защищать наш народ от любого врага.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8756,'Я думаю, что начинаю сожалеть о том, что затеяла это паломничество. Я понимала, что дорога будет тяжелой, и я не новичок в путешествиях, но не была готова к суровости Запределья.$B$BВ довершение всего этот Талерис, похоже, хочет изгнать меня отсюда до того, как я окончательно восстановлю силы.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я думаю, что начинаю сожалеть о том, что затеяла это паломничество. Я понимала, что дорога будет тяжелой, и я не новичок в путешествиях, но не была готова к суровости Запределья.$B$BВ довершение всего этот Талерис, похоже, хочет изгнать меня отсюда до того, как я окончательно восстановлю силы.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`,`text2_0_loc8`,`text2_1_loc8`,`text3_0_loc8`,`text3_1_loc8`) VALUES (8759,'О… мы знакомы?','О… мы знакомы?','Простите, я не разговариваю с помощниками.','Простите, я не разговариваю с помощниками.','А вы кто?','А вы кто?','Боюсь, ты путаешь меня с кем-то, кто хотел поговорить с тобой.','Боюсь, ты путаешь меня с кем-то, кто хотел поговорить с тобой.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','О… мы знакомы?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','О… мы знакомы?',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Простите, я не разговариваю с помощниками.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Простите, я не разговариваю с помощниками.',`text1_1_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','А вы кто?',`text2_0_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','А вы кто?',`text2_1_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Боюсь, ты путаешь меня с кем-то, кто хотел поговорить с тобой.',`text3_0_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','Боюсь, ты путаешь меня с кем-то, кто хотел поговорить с тобой.',`text3_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text2_0_loc8`,`text2_1_loc8`,`text3_0_loc8`,`text3_1_loc8`,`text4_0_loc8`,`text4_1_loc8`,`text7_0_loc8`,`text7_1_loc8`) VALUES (8760,'Быстро же слухами земля полнится. Спасибо, что $gпомог:помогла; нам с пополнением припасов!','Быстро же слухами земля полнится. Спасибо, что $gпомог:помогла; нам с пополнением припасов!','Замечательный праздник, ведь так?','Замечательный праздник, ведь так?','Тебе необходимо попробовать закуску из прыголапа, ради этого стоит умереть!','Тебе необходимо попробовать закуску из прыголапа, ради этого стоит умереть!','Ты можешь поверить страданиям этой Элисары Солнцесвет? Думает, что может заставить лорда Салтерила обратить на нее внимание? А помнишь, во что она одевается? Такая старомодная. Это очень печально, очень.','Ты можешь поверить страданиям этой Элисары Солнцесвет? Думает, что может заставить лорда Салтерила обратить на нее внимание? А помнишь, во что она одевается? Такая старомодная. Это очень печально, очень.') ON DUPLICATE KEY UPDATE `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Быстро же слухами земля полнится. Спасибо, что $gпомог:помогла; нам с пополнением припасов!',`text2_0_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Быстро же слухами земля полнится. Спасибо, что $gпомог:помогла; нам с пополнением припасов!',`text2_1_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Замечательный праздник, ведь так?',`text3_0_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','Замечательный праздник, ведь так?',`text3_1_loc8`), `text4_0_loc8`=IF(`text4_0_loc8` IS NULL OR `text4_0_loc8`='','Тебе необходимо попробовать закуску из прыголапа, ради этого стоит умереть!',`text4_0_loc8`), `text4_1_loc8`=IF(`text4_1_loc8` IS NULL OR `text4_1_loc8`='','Тебе необходимо попробовать закуску из прыголапа, ради этого стоит умереть!',`text4_1_loc8`), `text7_0_loc8`=IF(`text7_0_loc8` IS NULL OR `text7_0_loc8`='','Ты можешь поверить страданиям этой Элисары Солнцесвет? Думает, что может заставить лорда Салтерила обратить на нее внимание? А помнишь, во что она одевается? Такая старомодная. Это очень печально, очень.',`text7_0_loc8`), `text7_1_loc8`=IF(`text7_1_loc8` IS NULL OR `text7_1_loc8`='','Ты можешь поверить страданиям этой Элисары Солнцесвет? Думает, что может заставить лорда Салтерила обратить на нее внимание? А помнишь, во что она одевается? Такая старомодная. Это очень печально, очень.',`text7_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`,`text2_0_loc8`,`text2_1_loc8`,`text3_0_loc8`,`text3_1_loc8`) VALUES (8761,'Уходи!','Уходи!','Что такое? Что случилось?','Что такое? Что случилось?','Уходи… Я тут спать пытаюсь.','Уходи… Я тут спать пытаюсь.','Ох, я себя неважно чувствую.','Ох, я себя неважно чувствую.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Уходи!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Уходи!',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Что такое? Что случилось?',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Что такое? Что случилось?',`text1_1_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Уходи… Я тут спать пытаюсь.',`text2_0_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Уходи… Я тут спать пытаюсь.',`text2_1_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Ох, я себя неважно чувствую.',`text3_0_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','Ох, я себя неважно чувствую.',`text3_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8767,'Да уж, вот это называется поработал… Предсказательница Регулкут предупреждала меня, но я не слушал, за что и поплатился.$B$BЯ пришел сюда изучать руины Зет\'Гор, но по пути наткнулся на отряд Легиона. И вот, полюбуйтесь теперь, что за рана у меня на ноге…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да уж, вот это называется поработал… Предсказательница Регулкут предупреждала меня, но я не слушал, за что и поплатился.$B$BЯ пришел сюда изучать руины Зет\'Гор, но по пути наткнулся на отряд Легиона. И вот, полюбуйтесь теперь, что за рана у меня на ноге…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
