INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8769,'Послушай, |3-6($c), нам нужно знать, что замышляют ночные эльфы! Постарайся это выяснить.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Послушай, |3-6($c), нам нужно знать, что замышляют ночные эльфы! Постарайся это выяснить.',`text0_1_loc8`);
