INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8771,'О героях рода Троллебоев сложены легенды. Я всегда преклонялся перед ним…$B$BА когда увидел его живым, в Запределье…$B$B*Ромус смотрит мимо вас.*$B$BКогда я впервые увидел его, то чуть не потерял рассудок – настолько я был потрясен. Я склонился перед ним, едва сдерживая слезы.$B$BИ я готов сделать все, что только смогу, лишь бы Сыны Лотара были в безопасности.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','О героях рода Троллебоев сложены легенды. Я всегда преклонялся перед ним…$B$BА когда увидел его живым, в Запределье…$B$B*Ромус смотрит мимо вас.*$B$BКогда я впервые увидел его, то чуть не потерял рассудок – настолько я был потрясен. Я склонился перед ним, едва сдерживая слезы.$B$BИ я готов сделать все, что только смогу, лишь бы Сыны Лотара были в безопасности.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8775,'Этот передатчик с ума меня сведет! У меня нет ни единой детали, чтобы его починить.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Этот передатчик с ума меня сведет! У меня нет ни единой детали, чтобы его починить.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8777,'Нет, до сих пор не закончили этот ремонт. Тем не менее он не займет много времени.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Нет, до сих пор не закончили этот ремонт. Тем не менее он не займет много времени.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8780,'<Всхлипывает> Ненавижу кладбища. Так много мертвых. И моя милая Луанна…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Всхлипывает> Ненавижу кладбища. Так много мертвых. И моя милая Луанна…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (8785,'Не забывай выказывать должное почтение к мировым стихиям.','Не забывай выказывать должное почтение к мировым стихиям.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не забывай выказывать должное почтение к мировым стихиям.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Не забывай выказывать должное почтение к мировым стихиям.',`text0_1_loc8`);
