INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8790,'Приветствую тебя, |3-6($r)! Как поживаешь?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Приветствую тебя, |3-6($r)! Как поживаешь?',`text0_1_loc8`);
