INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8792,'Подойди ближе, друг. Не дай моим глазам испугать себя.$B$BМожет быть, я и потерял зрение много лет назад, но я никогда не нуждался в нем, чтобы видеть истинную природу вещей.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Подойди ближе, друг. Не дай моим глазам испугать себя.$B$BМожет быть, я и потерял зрение много лет назад, но я никогда не нуждался в нем, чтобы видеть истинную природу вещей.',`text0_0_loc8`);
