INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8793,'Хватай сеть, $gмолодой:молодая:c; |3-6($c). Нашему народу нужна пища!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Хватай сеть, $gмолодой:молодая:c; |3-6($c). Нашему народу нужна пища!',`text0_1_loc8`);
