INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8794,'Привет. Надеюсь, сегодняшний день застал вас в полном здравии?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Привет. Надеюсь, сегодняшний день застал вас в полном здравии?',`text0_0_loc8`);
