INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8796,'Вы оказали мне честь нашим знакомством.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вы оказали мне честь нашим знакомством.',`text0_0_loc8`);
