INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8797,'Спасибо, что обращаешься ко мне. Прошу, помоги Альянсу чем только можешь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Спасибо, что обращаешься ко мне. Прошу, помоги Альянсу чем только можешь.',`text0_0_loc8`);
