INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8798,'Здравствуйте. Я анахорет Делан, своего рода учитель. А вы кто $gтакой:такая;?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здравствуйте. Я анахорет Делан, своего рода учитель. А вы кто $gтакой:такая;?',`text0_0_loc8`);
