INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8799,'Мы можем многому научить другие расы Альянса, но и научиться у них можем не меньшему. Держи свои глаза, уши и разум нараспашку, |3-6($c).') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы можем многому научить другие расы Альянса, но и научиться у них можем не меньшему. Держи свои глаза, уши и разум нараспашку, |3-6($c).',`text0_0_loc8`);
