INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8803,'Я искренне надеюсь, что мы сможем принести Свет в те места Ясеневого леса, где от него отреклись.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я искренне надеюсь, что мы сможем принести Свет в те места Ясеневого леса, где от него отреклись.',`text0_1_loc8`);
