INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8804,'Я слишком занят, чтобы тратить время на праздную болтовню. Если ты ищешь работу охотника, поговори с Диктинной, найдешь ее на краю реки к востоку отсюда. Без сомнения, она отстает в выполнении своего долга…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я слишком занят, чтобы тратить время на праздную болтовню. Если ты ищешь работу охотника, поговори с Диктинной, найдешь ее на краю реки к востоку отсюда. Без сомнения, она отстает в выполнении своего долга…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8805,'Это так интересно! Правда, радость моя?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Это так интересно! Правда, радость моя?',`text0_1_loc8`);
