INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8808,'Балиндар Ясная Звезда послал тебя спасти меня?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Балиндар Ясная Звезда послал тебя спасти меня?',`text0_1_loc8`);
