INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8809,'Здорово мы Заблудших провели, а? Теперь им не избежать проклятья! Еще немного, и можно будет заняться самими дренеями.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Здорово мы Заблудших провели, а? Теперь им не избежать проклятья! Еще немного, и можно будет заняться самими дренеями.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8810,'Да направят тебя духи на путь истинный, |3-6($r).') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Да направят тебя духи на путь истинный, |3-6($r).',`text0_1_loc8`);
