INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8827,'Достаточно ли ты знаешь, чтобы продолжить, шаман? Тебе известно, почему ты здесь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Достаточно ли ты знаешь, чтобы продолжить, шаман? Тебе известно, почему ты здесь?',`text0_0_loc8`);
