INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8829,'Хороший день, чтобы быть живым и с духами стихий…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Хороший день, чтобы быть живым и с духами стихий…',`text0_0_loc8`);
