INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8840,'Здравствуй, |3-6($c). Меня прислали из Экзодара для наблюдения за строительством Лазурной заставы.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здравствуй, |3-6($c). Меня прислали из Экзодара для наблюдения за строительством Лазурной заставы.',`text0_0_loc8`);
