INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8844,'Алхимик может из обычных трав делать удивительные вещи, преобразовывая их в зелья с разными эффектами: от лечения до подводного дыхания.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Алхимик может из обычных трав делать удивительные вещи, преобразовывая их в зелья с разными эффектами: от лечения до подводного дыхания.',`text0_0_loc8`);
