INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8868,'Я – Адамант Железное Сердце из великого города Стальгорна. Как ты, наверное, можешь догадаться, глядя на мою форму, когда-то я был частью элитной гвардии Стальгорна. Да, я был правой рукой Магни! По крайней мере, пока не ушел в отставку. Теперь я немного занимаюсь археологией. На самом деле, это просто хобби, к тому же, я подумал, что это отличный способ посмотреть мир!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я – Адамант Железное Сердце из великого города Стальгорна. Как ты, наверное, можешь догадаться, глядя на мою форму, когда-то я был частью элитной гвардии Стальгорна. Да, я был правой рукой Магни! По крайней мере, пока не ушел в отставку. Теперь я немного занимаюсь археологией. На самом деле, это просто хобби, к тому же, я подумал, что это отличный способ посмотреть мир!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8871,'Если не боги, то кто же? Как? Что могло вызвать такой раздор?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если не боги, то кто же? Как? Что могло вызвать такой раздор?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8878,'Хотя ты и $gнанес:нанесла; демонам с юга серьезный удар, я по-прежнему чувствую беду в этих землях.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Хотя ты и $gнанес:нанесла; демонам с юга серьезный удар, я по-прежнему чувствую беду в этих землях.',`text0_0_loc8`);
