INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8881,'Ты |3-6($r), верно? Хорошо, что ты здесь, даже на сердце полегчало! Нам сейчас пригодится любая помощь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты |3-6($r), верно? Хорошо, что ты здесь, даже на сердце полегчало! Нам сейчас пригодится любая помощь.',`text0_0_loc8`);
