INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8883,'Нужно убить демонов, |3-6($c). Достаточно ли у тебя силы воли, чтобы справиться с задачей?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Нужно убить демонов, |3-6($c). Достаточно ли у тебя силы воли, чтобы справиться с задачей?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8887,'Когда добрая часть демонов будет перебита, Легион дважды подумает, прежде чем вновь нападать на наш лагерь. Однако я все еще чувствую, как шевелится демоническое зло.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Когда добрая часть демонов будет перебита, Легион дважды подумает, прежде чем вновь нападать на наш лагерь. Однако я все еще чувствую, как шевелится демоническое зло.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text1_0_loc8`,`text2_0_loc8`,`text3_0_loc8`,`text4_0_loc8`,`text5_0_loc8`) VALUES (8892,'Историю твоего путешествия будут рассказывать на протяжении долгих лет всем приезжим!','Наконец-то у меня есть история, которую я смог бы рассказать внукам… Среди нас жил предатель королевства!','По правде сказать, никогда не любил этого гнома…','Нам повезло, что мы выжили в этом суровом испытании. Если бы не ты, все на этом острове были бы уже мертвы!','Поразительно, сколь много их живет средь нас. Я знаю Искра уже многие годы и никогда не мог даже предположить, что он предатель.') ON DUPLICATE KEY UPDATE `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Историю твоего путешествия будут рассказывать на протяжении долгих лет всем приезжим!',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Наконец-то у меня есть история, которую я смог бы рассказать внукам… Среди нас жил предатель королевства!',`text2_0_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','По правде сказать, никогда не любил этого гнома…',`text3_0_loc8`), `text4_0_loc8`=IF(`text4_0_loc8` IS NULL OR `text4_0_loc8`='','Нам повезло, что мы выжили в этом суровом испытании. Если бы не ты, все на этом острове были бы уже мертвы!',`text4_0_loc8`), `text5_0_loc8`=IF(`text5_0_loc8` IS NULL OR `text5_0_loc8`='','Поразительно, сколь много их живет средь нас. Я знаю Искра уже многие годы и никогда не мог даже предположить, что он предатель.',`text5_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`,`text1_1_loc8`,`text2_1_loc8`,`text3_1_loc8`,`text4_1_loc8`,`text5_1_loc8`) VALUES (8893,'Приветствуем тебя, прославленный герой!','О твоем путешествии будут рассказывать долгие годы!','Вот теперь будет что внукам рассказать… Среди нас жил предатель всего королевства!','По правде говоря, мне этот гном никогда не нравился…','Нам всем повезло, что мы прошли через это суровое испытание. Если бы не ты, все на этом острове были бы уже мертвы!','Интересно, сколькие из них еще живут среди нас. Я знала Искру многие годы – никогда не могла представить, что он окажется предателем.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Приветствуем тебя, прославленный герой!',`text0_1_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','О твоем путешествии будут рассказывать долгие годы!',`text1_1_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Вот теперь будет что внукам рассказать… Среди нас жил предатель всего королевства!',`text2_1_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','По правде говоря, мне этот гном никогда не нравился…',`text3_1_loc8`), `text4_1_loc8`=IF(`text4_1_loc8` IS NULL OR `text4_1_loc8`='','Нам всем повезло, что мы прошли через это суровое испытание. Если бы не ты, все на этом острове были бы уже мертвы!',`text4_1_loc8`), `text5_1_loc8`=IF(`text5_1_loc8` IS NULL OR `text5_1_loc8`='','Интересно, сколькие из них еще живут среди нас. Я знала Искру многие годы – никогда не могла представить, что он окажется предателем.',`text5_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
