INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (8956,'Приветствую, |3-6($c). Ко мне не часто приходят гости. Чем обязана удовольствию общаться с вами?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Приветствую, |3-6($c). Ко мне не часто приходят гости. Чем обязана удовольствию общаться с вами?',`text0_1_loc8`);
