INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8958,'Приплыть ко мне – поистине храбрый поступок для живущего на твердой земле.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приплыть ко мне – поистине храбрый поступок для живущего на твердой земле.',`text0_0_loc8`);
