INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8963,'Ты еще не $gпоговорил:поговорила; с верховной жрицей? Она очень хочет услышать историю этого паломничества с твоей точки зрения.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты еще не $gпоговорил:поговорила; с верховной жрицей? Она очень хочет услышать историю этого паломничества с твоей точки зрения.',`text0_0_loc8`);
