INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8966,'Я прямо не знаю, как отблагодарить тебя за возможность совершить паломничество!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я прямо не знаю, как отблагодарить тебя за возможность совершить паломничество!',`text0_0_loc8`);
