INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (8969,'Давно пора получить подкрепление от гильдии! Жаль, что ты $gпроделал:проделала; весь этот путь зря. Можешь себе представить: нам не разрешают устроить представление для наших гостей. Мороуз запретил нам, и мои сторонники сходят с ума! Что-то с Мороузом нужно сделать…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Давно пора получить подкрепление от гильдии! Жаль, что ты $gпроделал:проделала; весь этот путь зря. Можешь себе представить: нам не разрешают устроить представление для наших гостей. Мороуз запретил нам, и мои сторонники сходят с ума! Что-то с Мороузом нужно сделать…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
