INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9029,'Добро пожаловать на Кровавую заставу, |3-6($c). В своих странствиях я собрал множество инструментов, артефактов и знаний – почерпнул у людей, встречавшихся на пути.$B$BЕсли тебе понадобятся эти знания – спрашивай!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать на Кровавую заставу, |3-6($c). В своих странствиях я собрал множество инструментов, артефактов и знаний – почерпнул у людей, встречавшихся на пути.$B$BЕсли тебе понадобятся эти знания – спрашивай!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9030,'Как следует из названия, его можно найти рядом с развалинами. Ответ можно найти в Лорет-Аране.$B$BНа самом деле из названия ничего подобного не следует – я просто старался придумать получше названия для грибов…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Как следует из названия, его можно найти рядом с развалинами. Ответ можно найти в Лорет-Аране.$B$BНа самом деле из названия ничего подобного не следует – я просто старался придумать получше названия для грибов…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9031,'Вид "Поганка конусовидная" сформировался под воздействием магической скверны. Эти грибы можно найти в лагере сатиров Наззивиана к западу отсюда.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вид "Поганка конусовидная" сформировался под воздействием магической скверны. Эти грибы можно найти в лагере сатиров Наззивиана к западу отсюда.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9032,'Кровавые грибы встречаются чаще других грибов, и найти их можно в любом лесу острова Кровавой Дымки. Если вам дорога ваша жизнь, советую поискать к югу от дороги, делящей остров пополам.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Кровавые грибы встречаются чаще других грибов, и найти их можно в любом лесу острова Кровавой Дымки. Если вам дорога ваша жизнь, советую поискать к югу от дороги, делящей остров пополам.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9033,'Если ты чему-то и $gнаучился:научилась; во время своего пребывания на Кровавой Дымке, |3-6($c), надеюсь этим чем-то была бдительность. Этот остров захватывает сначала неосторожных, а потом и наиболее бдительных воинов.$B$BГде бы ты ни $gповернулся:повернулась;, за твоей спиной может быть враг, желающий отнять твою жизнь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если ты чему-то и $gнаучился:научилась; во время своего пребывания на Кровавой Дымке, |3-6($c), надеюсь этим чем-то была бдительность. Этот остров захватывает сначала неосторожных, а потом и наиболее бдительных воинов.$B$BГде бы ты ни $gповернулся:повернулась;, за твоей спиной может быть враг, желающий отнять твою жизнь.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (9034,'Все, что случилось с момента крушения, мало что значит. Мне кажется, что на борту Экзодара я была еще в другой жизни.$B$BА теперь моя жизнь – этот остров с живущими на нем мутантами и полчищами приспешников эльфов крови. Скоро мне будет казаться, что другого я и не знала…') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Все, что случилось с момента крушения, мало что значит. Мне кажется, что на борту Экзодара я была еще в другой жизни.$B$BА теперь моя жизнь – этот остров с живущими на нем мутантами и полчищами приспешников эльфов крови. Скоро мне будет казаться, что другого я и не знала…',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9036,'Другие смотрят на этот ландшафт и видят лишь смерть, разрушение и несчастья. Всего этого у нас в избытке, это правда, но такое видение игнорирует те благоприятные возможности, что дарует нам земля.$B$BЯ не буду стоять в стороне и смотреть, как игнорируют такие перспективы, |3-6($c). С твоей помощью мы сможем продемонстрировать остальным на Кровавой заставе, как можно использовать окружающую среду и населяющих ее созданий.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Другие смотрят на этот ландшафт и видят лишь смерть, разрушение и несчастья. Всего этого у нас в избытке, это правда, но такое видение игнорирует те благоприятные возможности, что дарует нам земля.$B$BЯ не буду стоять в стороне и смотреть, как игнорируют такие перспективы, |3-6($c). С твоей помощью мы сможем продемонстрировать остальным на Кровавой заставе, как можно использовать окружающую среду и населяющих ее созданий.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9037,'Привет, |3-6($c).$B$BСтарик Кессел вон там, он умен. На твоем месте я был бы поосторожнее, имея с ним дело.$B$BОн предложил мне работу – ухаживать за элекками, и я, по глупости, подумал, что речь идет о кормежке, дрессировке и тому подобном. Все сразу стало ясно, когда он протянул мне лопату…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Привет, |3-6($c).$B$BСтарик Кессел вон там, он умен. На твоем месте я был бы поосторожнее, имея с ним дело.$B$BОн предложил мне работу – ухаживать за элекками, и я, по глупости, подумал, что речь идет о кормежке, дрессировке и тому подобном. Все сразу стало ясно, когда он протянул мне лопату…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9041,'Я Кессел, владыка элекков, адепт Длани Аргуса. Ты новый рекрут?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я Кессел, владыка элекков, адепт Длани Аргуса. Ты новый рекрут?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9042,'Я Акелус, старший офицер экспедиционных войск Кровавой заставы.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я Акелус, старший офицер экспедиционных войск Кровавой заставы.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9043,'Я доставляю почту на остров Лазурной дымки и обратно, |3-6($c). Если тебе необходимо доставить туда послание, то, скорее всего, оно пройдет через меня.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я доставляю почту на остров Лазурной дымки и обратно, |3-6($c). Если тебе необходимо доставить туда послание, то, скорее всего, оно пройдет через меня.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9044,'Каково это – быть Дланью Аргуса… Мы – служители Света. Мы служим без сомнений и умираем тоже без них.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Каково это – быть Дланью Аргуса… Мы – служители Света. Мы служим без сомнений и умираем тоже без них.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9045,'Тебя послали за мной? Так вот, без своих помощников я не вернусь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тебя послали за мной? Так вот, без своих помощников я не вернусь.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9050,'Да, я один из Сломленных. Надеюсь, тебя это не беспокоит? Падшим, как и дренеям, приходится сносить чужие насмешки. Все, что для нас важно, – это лучшее понимание элементов этого мира и общение с ними.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да, я один из Сломленных. Надеюсь, тебя это не беспокоит? Падшим, как и дренеям, приходится сносить чужие насмешки. Все, что для нас важно, – это лучшее понимание элементов этого мира и общение с ними.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9051,'Прошу, сядь и устройся поудобнее.','Прошу, сядь и устройся поудобнее.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Прошу, сядь и устройся поудобнее.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Прошу, сядь и устройся поудобнее.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9052,'Добрый день, |3-6($c). Вам нужен надежный гиппогриф?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добрый день, |3-6($c). Вам нужен надежный гиппогриф?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9053,'Если вам нужно в Экзодар, я подберу вам отличного гиппогрифа!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если вам нужно в Экзодар, я подберу вам отличного гиппогрифа!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9056,'Ты с ума $gсошел:сошла;? Оглянись вокруг, $gсмертный:смертная;. Ты что, не видишь, что стоишь на разломленной земле? Покинь это место, чтобы не страдать так же, как страдаю я и мой народ…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты с ума $gсошел:сошла;? Оглянись вокруг, $gсмертный:смертная;. Ты что, не видишь, что стоишь на разломленной земле? Покинь это место, чтобы не страдать так же, как страдаю я и мой народ…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9057,'Ты еще и $gслеп:слепа; в дополнение к тому, что $gбезумен:безумна;?$B$BЯ – призрак, жестокое напоминание о цивилизации, которая давно прекратила свое существование… привязанный к земле, которую не смог защитить.$B$BДавным-давно – десять тысяч лет назад – я состоял из плоти и крови, как и ты. Я был принцем этих земель и наездником дракона, благословленного самой Изерой Спящей.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты еще и $gслеп:слепа; в дополнение к тому, что $gбезумен:безумна;?$B$BЯ – призрак, жестокое напоминание о цивилизации, которая давно прекратила свое существование… привязанный к земле, которую не смог защитить.$B$BДавным-давно – десять тысяч лет назад – я состоял из плоти и крови, как и ты. Я был принцем этих земель и наездником дракона, благословленного самой Изерой Спящей.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9058,'Ты $gслышал:слышала; об Изере? Хранительнице природы, Изере Спящей? Она – мать всех зеленых драконов! Изера подарила моему королевству свое племя. Мы стояли плечом к плечу с этими благородными созданиями, и они позволяли нам летать на них верхом в битвах. Все было хорошо много веков… пока…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты $gслышал:слышала; об Изере? Хранительнице природы, Изере Спящей? Она – мать всех зеленых драконов! Изера подарила моему королевству свое племя. Мы стояли плечом к плечу с этими благородными созданиями, и они позволяли нам летать на них верхом в битвах. Все было хорошо много веков… пока…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9061,'Ученики в чем-то похожи на овец. Если их опекать и возиться с ними, они бывают полезными и даже милыми.$B$BНо стоит оставить их одних на минуту, как они свалятся с обрыва или утонут в реке.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ученики в чем-то похожи на овец. Если их опекать и возиться с ними, они бывают полезными и даже милыми.$B$BНо стоит оставить их одних на минуту, как они свалятся с обрыва или утонут в реке.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9062,'На знаке теснятся многочисленные объявления о наградах за выполнение рискованных заданий. Впрочем, ничего интересного там нет. Возможно, лучше вернуться сюда в другой раз.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','На знаке теснятся многочисленные объявления о наградах за выполнение рискованных заданий. Впрочем, ничего интересного там нет. Возможно, лучше вернуться сюда в другой раз.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9063,'Приветствую вас, горожанин. Проходите, пожалуйста, если не хотите ни о чем меня спрашивать.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приветствую вас, горожанин. Проходите, пожалуйста, если не хотите ни о чем меня спрашивать.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9065,'У вас получилось! Потрясающе! Маршал Виндзор как раз ждет вас. Хотите, чтобы я подал ему сигнал?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','У вас получилось! Потрясающе! Маршал Виндзор как раз ждет вас. Хотите, чтобы я подал ему сигнал?',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9066,'Славься, защитник! Легенды о ваших деяниях будут жить в веках. Может быть, однажды ваша статуя займет место среди других изображений героев Штормграда...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Славься, защитник! Легенды о ваших деяниях будут жить в веках. Может быть, однажды ваша статуя займет место среди других изображений героев Штормграда...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9067,'Не подходи ко мне, |3-6($r)! Я не знаю, когда болезнь скрутит меня снова.$B$BЛучше уйди, пока этого не случилось.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не подходи ко мне, |3-6($r)! Я не знаю, когда болезнь скрутит меня снова.$B$BЛучше уйди, пока этого не случилось.',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9068,'Как вы узнали про руду? Про нее не знал даже барон...$B$BВозьмите эти проклятые вещи. Они принесли мне одни неудачи. Я спрятал их в стойлах, возле внутреннего двора.$B$B*Лондэн издает низкое горловое рычание.*') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Как вы узнали про руду? Про нее не знал даже барон...$B$BВозьмите эти проклятые вещи. Они принесли мне одни неудачи. Я спрятал их в стойлах, возле внутреннего двора.$B$B*Лондэн издает низкое горловое рычание.*',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9070,'Исследуя труп, вы приходите к выводу, что это, должно быть, рыцарь крови Утренняя Звезда, возглавлявший неудачное нападение на Смертхольм.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Исследуя труп, вы приходите к выводу, что это, должно быть, рыцарь крови Утренняя Звезда, возглавлявший неудачное нападение на Смертхольм.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9071,'Я могу тебе помочь основать гильдию.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я могу тебе помочь основать гильдию.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (9073,'Да благословит тебя Элуна! Чем я могу тебе помочь?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Да благословит тебя Элуна! Чем я могу тебе помочь?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9077,'Здравствуйте, |3-6($c). Я Курос, второй из Триумвирата Длани.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здравствуйте, |3-6($c). Я Курос, второй из Триумвирата Длани.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9079,'Я смотрел, как они избивали его безо всякой пощады. Их безжалостный лейтенант вел себя так, как будто этот акт жестокости в порядке вещей. Видя это, я чувствовал, как во мне что-то ломается.$B$BКогда я увидел, как они бьют Поборника Саруана, я начал рыдать. Видел, как ужасно обращаются с дренеем Триумвирата. Если бы я только мог освободиться от моих пут… Если бы только…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я смотрел, как они избивали его безо всякой пощады. Их безжалостный лейтенант вел себя так, как будто этот акт жестокости в порядке вещей. Видя это, я чувствовал, как во мне что-то ломается.$B$BКогда я увидел, как они бьют Поборника Саруана, я начал рыдать. Видел, как ужасно обращаются с дренеем Триумвирата. Если бы я только мог освободиться от моих пут… Если бы только…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9080,'Казалось, прошла целая вечность, прежде чем поборник потерял сознание. Такой пытки не выдержал даже он. Тот злодей – Матис его звали – попытался разбудить Саруана, облив его тело заразной водой, но Саруан так и не проснулся.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Казалось, прошла целая вечность, прежде чем поборник потерял сознание. Такой пытки не выдержал даже он. Тот злодей – Матис его звали – попытался разбудить Саруана, облив его тело заразной водой, но Саруан так и не проснулся.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9081,'Я хотел закричать, но из моего рта вырвался лишь слабый хрип. Меня тут же ударили за этот акт неповиновения. Пока я лежал на земле, видел, как Матис шагнул к телу Саруана. Он казался явно взволнованным. Он сказал, что Сиронас, или Сирона, или кто-то подобный снимет с него шкуру, если Саруан погибнет от побоев.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я хотел закричать, но из моего рта вырвался лишь слабый хрип. Меня тут же ударили за этот акт неповиновения. Пока я лежал на земле, видел, как Матис шагнул к телу Саруана. Он казался явно взволнованным. Он сказал, что Сиронас, или Сирона, или кто-то подобный снимет с него шкуру, если Саруан погибнет от побоев.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9084,'Добрый день, |3-6($c). Если вы хотите научиться кузнечному мастерству, то вы пришли по адресу.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добрый день, |3-6($c). Если вы хотите научиться кузнечному мастерству, то вы пришли по адресу.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (9085,'Ох, не обращайте внимания на Малыша. Он вас не тронет, просто иногда любит поточить коготки.$B$BОн ведь как большой котенок.$B$BПравда, Малыш? Да, конечно, ты мой сладенький! Ты мой малышок, мамочкина радость!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ох, не обращайте внимания на Малыша. Он вас не тронет, просто иногда любит поточить коготки.$B$BОн ведь как большой котенок.$B$BПравда, Малыш? Да, конечно, ты мой сладенький! Ты мой малышок, мамочкина радость!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9090,'Ты кто $gтакой:такая;? Оставь меня.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты кто $gтакой:такая;? Оставь меня.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9100,'Мне удалось найти оазис, и я решил остаться там до тех пор, пока не получу ответ на свой вопрос. Я сидел, шевелясь только тогда, когда было абсолютно необходимо, и питаясь созданиями, приходившими к пруду. Таково было мое просветление.$B$BКак я уже говорил, ответ не приходил ко мне десятки лет. Но я помню один особенно красивый закат. Землю обдувал теплый ветерок, и я мог бы поклясться, что слышал голос, но никого рядом не было.$B$BЯ, как ты понимаешь, начал думать, что схожу с ума.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мне удалось найти оазис, и я решил остаться там до тех пор, пока не получу ответ на свой вопрос. Я сидел, шевелясь только тогда, когда было абсолютно необходимо, и питаясь созданиями, приходившими к пруду. Таково было мое просветление.$B$BКак я уже говорил, ответ не приходил ко мне десятки лет. Но я помню один особенно красивый закат. Землю обдувал теплый ветерок, и я мог бы поклясться, что слышал голос, но никого рядом не было.$B$BЯ, как ты понимаешь, начал думать, что схожу с ума.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9101,'Этот ветер был какой-то странный, он не затихал, дул целыми неделями, завывал, но так и не утихал. И все это время звучал голос, хотя я не мог разобрать ни слова и не знал, откуда он.$B$BВремя, проведенное в одиночестве, научило меня успокаиваться и смотреть внутрь себя, что я и сделал с целью сохранить рассудок. И тогда я смог понять то, что говорил голос! Это говорил сам ветер, и ему было что рассказать мне!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Этот ветер был какой-то странный, он не затихал, дул целыми неделями, завывал, но так и не утихал. И все это время звучал голос, хотя я не мог разобрать ни слова и не знал, откуда он.$B$BВремя, проведенное в одиночестве, научило меня успокаиваться и смотреть внутрь себя, что я и сделал с целью сохранить рассудок. И тогда я смог понять то, что говорил голос! Это говорил сам ветер, и ему было что рассказать мне!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9102,'Оно поведало мне о тайнах и силе, а также о правде. Свет не покинул Сломленных! Та энергия скверны, которую применяли орки в войне против дренеев, вселилась в нас, не позволяя нам быть услышанными Светом или хотя бы слышать его. Эта же энергия была причиной деградации наших тел.$B$BНо дух наш не сломлен, и Воздух указал мне другой путь, по которому я могу повести свой народ.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Оно поведало мне о тайнах и силе, а также о правде. Свет не покинул Сломленных! Та энергия скверны, которую применяли орки в войне против дренеев, вселилась в нас, не позволяя нам быть услышанными Светом или хотя бы слышать его. Эта же энергия была причиной деградации наших тел.$B$BНо дух наш не сломлен, и Воздух указал мне другой путь, по которому я могу повести свой народ.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9104,'Я вернулся к моему народу и был встречен улыбающимися лицами и распростертыми объятиями – больше всех мне радовались Сломленные. В мое отсутствие многие дренеи продолжали относиться к нам с предубеждением. Но такое ощущение, что они знали, что я приду, и скоро я понял, почему.$B$BВелен, предсказатель и вождь всех дренеев, видел мое возвращение в одном из своих видений и тоже пришел меня поприветствовать. Он попросил меня поговорить с ним наедине, и я рассказал ему мою историю, а он кивал и улыбался, поскольку и это тоже он предвидел.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я вернулся к моему народу и был встречен улыбающимися лицами и распростертыми объятиями – больше всех мне радовались Сломленные. В мое отсутствие многие дренеи продолжали относиться к нам с предубеждением. Но такое ощущение, что они знали, что я приду, и скоро я понял, почему.$B$BВелен, предсказатель и вождь всех дренеев, видел мое возвращение в одном из своих видений и тоже пришел меня поприветствовать. Он попросил меня поговорить с ним наедине, и я рассказал ему мою историю, а он кивал и улыбался, поскольку и это тоже он предвидел.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9105,'Велен поставил меня во главе Сломленных. Но, что гораздо важнее, он велел меня обучить всех шаманизму – как дренеев, так и Сломленных. И я согласился.$b$bМы знали, что, даже если отбросить все предрассудки, это будет очень нелегким делом. Есть те, кто ненавидят Сломленных из-за ужасного прошлого, а есть те, кто считают, что быть шаманом – это преступление против Света.$b$bНо в любом случае разбираться со всем этим должен я.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Велен поставил меня во главе Сломленных. Но, что гораздо важнее, он велел меня обучить всех шаманизму – как дренеев, так и Сломленных. И я согласился.$b$bМы знали, что, даже если отбросить все предрассудки, это будет очень нелегким делом. Есть те, кто ненавидят Сломленных из-за ужасного прошлого, а есть те, кто считают, что быть шаманом – это преступление против Света.$b$bНо в любом случае разбираться со всем этим должен я.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9106,'Если наши враги увидят, что мы хотим жить с ними в мире, может быть, нам не придется атаковать их, чтобы выжить самим?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если наши враги увидят, что мы хотим жить с ними в мире, может быть, нам не придется атаковать их, чтобы выжить самим?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9108,'Когда новые враги стучатся в дверь, мы не должны позволить нашим древним противникам одержать верх.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Когда новые враги стучатся в дверь, мы не должны позволить нашим древним противникам одержать верх.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (9109,'Ты можешь поверить в существование этого места? Конечно, тут немного душновато, если тебя интересует мое мнение.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты можешь поверить в существование этого места? Конечно, тут немного душновато, если тебя интересует мое мнение.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9111,'Грязные грибные великаны! Что ж нам с ними делать?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Грязные грибные великаны! Что ж нам с ними делать?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (9112,'Если бы я не вывернула лодыжку, добираясь сюда, была бы там внутри, с друзьями. Хмм, а, вообще-то, может и к лучшему, что я здесь, а не там?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Если бы я не вывернула лодыжку, добираясь сюда, была бы там внутри, с друзьями. Хмм, а, вообще-то, может и к лучшему, что я здесь, а не там?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9113,'Фхвур любит маленьких спорлингов. Они спасли Фхвура. Их не есть.$B$BФхвур ненавидит нага. Фхвур бьет!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Фхвур любит маленьких спорлингов. Они спасли Фхвура. Их не есть.$B$BФхвур ненавидит нага. Фхвур бьет!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9117,'Я Эсом, третий из Триумвирата.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я Эсом, третий из Триумвирата.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (9123,'Чтоб они сгинули, эти эльфы крови и их неуемное колдунство!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Чтоб они сгинули, эти эльфы крови и их неуемное колдунство!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`,`text2_0_loc8`,`text2_1_loc8`,`text3_0_loc8`,`text3_1_loc8`) VALUES (9124,'Не заставляй меня терять время. Что тебе нужно?','Не заставляй меня терять время. Что тебе нужно?','Ты что, не видишь, что я занят?','Ты что, не видишь, что я занята?','Да? Чего угодно?','Да? Чего угодно?','А ты?','А ты?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не заставляй меня терять время. Что тебе нужно?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Не заставляй меня терять время. Что тебе нужно?',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Ты что, не видишь, что я занят?',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Ты что, не видишь, что я занята?',`text1_1_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Да? Чего угодно?',`text2_0_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Да? Чего угодно?',`text2_1_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','А ты?',`text3_0_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','А ты?',`text3_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (9127,'Пусть Cвет будет благосклонен к вам во всех начинаниях.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Пусть Cвет будет благосклонен к вам во всех начинаниях.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (9128,'Все сущее в природе объединено и связано, это называется экология. Если мы будем достаточно осторожны, чтобы не нарушить эту систему, и ограничимся наблюдением, нам, возможно, удастся воссоздать сложные взаимоотношения между окружающими нас живыми существами.$B$BА постигнув их, мы сможем сделать так, чтобы все эти существа жили в гармонии. Стоит лишь вмешаться в ход вещей, не обладая знанием, и беды не миновать.$B$BЯ прибыла сюда наблюдать за сложными взаимоотношениями спорлингов и болотников.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Все сущее в природе объединено и связано, это называется экология. Если мы будем достаточно осторожны, чтобы не нарушить эту систему, и ограничимся наблюдением, нам, возможно, удастся воссоздать сложные взаимоотношения между окружающими нас живыми существами.$B$BА постигнув их, мы сможем сделать так, чтобы все эти существа жили в гармонии. Стоит лишь вмешаться в ход вещей, не обладая знанием, и беды не миновать.$B$BЯ прибыла сюда наблюдать за сложными взаимоотношениями спорлингов и болотников.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9131,'Друиды защищают меня от наг и злых Заблудших. Взамен я рассказываю им о растениях и животных болот.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Друиды защищают меня от наг и злых Заблудших. Взамен я рассказываю им о растениях и животных болот.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9138,'Это была идея Сиронас… Эта мерзость на самом деле – один из них самих. Это какой-то высокопоставленный член дренейского военного ордена – Триумвирата или еще какая-то ерунда.$B$BЧто бы это ни было, оно огромное, мощное и разгневанное. Любые попытки атаковать Векторную Спираль будут наверняка провалены, до тех пор пока там находится эта мерзость.','Это была идея Сиронас… Эта мерзость на самом деле – один из них самих. Это какой-то высокопоставленный член дренейского военного ордена – Триумвирата или еще какая-то ерунда.$B$BЧто бы это ни было, оно огромное, мощное и разгневанное. Любые попытки атаковать Векторную Спираль будут наверняка провалены, до тех пор пока там находится эта мерзость.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Это была идея Сиронас… Эта мерзость на самом деле – один из них самих. Это какой-то высокопоставленный член дренейского военного ордена – Триумвирата или еще какая-то ерунда.$B$BЧто бы это ни было, оно огромное, мощное и разгневанное. Любые попытки атаковать Векторную Спираль будут наверняка провалены, до тех пор пока там находится эта мерзость.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Это была идея Сиронас… Эта мерзость на самом деле – один из них самих. Это какой-то высокопоставленный член дренейского военного ордена – Триумвирата или еще какая-то ерунда.$B$BЧто бы это ни было, оно огромное, мощное и разгневанное. Любые попытки атаковать Векторную Спираль будут наверняка провалены, до тех пор пока там находится эта мерзость.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9140,'Разумеется. Как еще она могла внедриться в их ряды и сойти за дренея? Она прожила среди них очень долго…','Разумеется. Как еще она могла внедриться в их ряды и сойти за дренея? Она прожила среди них очень долго…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Разумеется. Как еще она могла внедриться в их ряды и сойти за дренея? Она прожила среди них очень долго…',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Разумеется. Как еще она могла внедриться в их ряды и сойти за дренея? Она прожила среди них очень долго…',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9142,'Пришло время уничтожить Векторную Спираль!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Пришло время уничтожить Векторную Спираль!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (9143,'Я терпеливо жду ваших приказов, |3-6($c).') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я терпеливо жду ваших приказов, |3-6($c).',`text0_1_loc8`);
