INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9145,'[На ломаном Общем] Пора начинай праздновать нам.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','[На ломаном Общем] Пора начинай праздновать нам.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9146,'$gИзбранный:Избранная;, помнишь ли ты нас? Вспоминаешь ли пророчество Курца? Этот момент был предрешен. Ты $gсделал:сделала; то, для чего $gбыл призван:была призвана; в этот мир. $b$b*Верховный вождь племени Тихвой склоняется перед вами в поклоне.* $b$bДренеи всегда будут у нас желанными гостями.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','$gИзбранный:Избранная;, помнишь ли ты нас? Вспоминаешь ли пророчество Курца? Этот момент был предрешен. Ты $gсделал:сделала; то, для чего $gбыл призван:была призвана; в этот мир. $b$b*Верховный вождь племени Тихвой склоняется перед вами в поклоне.* $b$bДренеи всегда будут у нас желанными гостями.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9159,'Ради встречи с вами я пересек бы и Великое море, друг мой. Мы никогда не забудем, что вы сделали для нас.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ради встречи с вами я пересек бы и Великое море, друг мой. Мы никогда не забудем, что вы сделали для нас.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9160,'Я бы хотел еще раз поблагодарить тебя за то, что ты для меня $gсделал:сделала;. Ты $gдал:дала; мне мужество отбить мой дом у зверей из леса. А выполняя это, я нашел Магвин!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я бы хотел еще раз поблагодарить тебя за то, что ты для меня $gсделал:сделала;. Ты $gдал:дала; мне мужество отбить мой дом у зверей из леса. А выполняя это, я нашел Магвин!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9162,'Среди нас – герой дренейского народа! Этот праздник – в честь спасителя Лазурной дымки и Кровавой дымки!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Среди нас – герой дренейского народа! Этот праздник – в честь спасителя Лазурной дымки и Кровавой дымки!',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (9166,'Мы не можем сейчас терять бдительность, |3-6($c). Повсюду кишат шпионы и союзники Пылающего Легиона. Если заметите что-то странное, немедленно покажите мне!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мы не можем сейчас терять бдительность, |3-6($c). Повсюду кишат шпионы и союзники Пылающего Легиона. Если заметите что-то странное, немедленно покажите мне!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9167,'Исиэль ожидала, что встретится с некоторым сопротивлением ее набегам на Запределье. Для этого и создали нас, стражников.$B$BМы даже не предполагали, что встретимся с такой силой, что стояла за нагами. Они оказались так многочисленны…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Исиэль ожидала, что встретится с некоторым сопротивлением ее набегам на Запределье. Для этого и создали нас, стражников.$B$BМы даже не предполагали, что встретимся с такой силой, что стояла за нагами. Они оказались так многочисленны…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (9168,'Я не знаю, кто ты, но твое присутствие здесь весьма желанно. Архимонд и его армия Плети могут начать атаку в любой момент, |3-6($c). Встанешь ли ты вместе с нами на защиту от зла?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я не знаю, кто ты, но твое присутствие здесь весьма желанно. Архимонд и его армия Плети могут начать атаку в любой момент, |3-6($c). Встанешь ли ты вместе с нами на защиту от зла?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (9169,'Спасибо, |3-6($r). А теперь приготовься. Архимонд на марше, и нам надо как можно дольше оттягивать неизбежное.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Спасибо, |3-6($r). А теперь приготовься. Архимонд на марше, и нам надо как можно дольше оттягивать неизбежное.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (9170,'Мы должны держаться до последнего! В бой!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мы должны держаться до последнего! В бой!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9173,'[на ломаном общем языке] Племя Тихвой быть готов! Много спасибо!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','[на ломаном общем языке] Племя Тихвой быть готов! Много спасибо!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9174,'Добро пожаловать в штаб-квартиру рыцарей крови, защитников Кель\'Таласа, преданных слуг Луносвета и истинных повелителей Света.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать в штаб-квартиру рыцарей крови, защитников Кель\'Таласа, преданных слуг Луносвета и истинных повелителей Света.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9177,'В природе – могучая сила, |3-6($r). Те, кто пытаются подчинить ее, не смогут сделать это навечно.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','В природе – могучая сила, |3-6($r). Те, кто пытаются подчинить ее, не смогут сделать это навечно.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9180,'Духи не знают отдыха, |3-6($r). Обращайте внимание на то, что вас окружает, пребывая в Награнде, а не то их ярость пожрет вас.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Духи не знают отдыха, |3-6($r). Обращайте внимание на то, что вас окружает, пребывая в Награнде, а не то их ярость пожрет вас.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9181,'Служители Земли стараются сохранить силу и величие стихий.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Служители Земли стараются сохранить силу и величие стихий.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (9182,'Как мой народ может бороться, когда стихии так бушуют? Они не видят, что ли, что без поддержки стихий мир попросту не сможет существовать?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Как мой народ может бороться, когда стихии так бушуют? Они не видят, что ли, что без поддержки стихий мир попросту не сможет существовать?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9183,'Я Унтраг из Служителей Земли. Постарайся не раздражать стихии, пока остаешься вблизи Трона Стихий.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я Унтраг из Служителей Земли. Постарайся не раздражать стихии, пока остаешься вблизи Трона Стихий.',`text0_0_loc8`);
