INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (9190,'Приятно видеть здесь кого-то в здравом уме. Чем могу помочь?','Приятно видеть здесь кого-то в здравом уме. Чем могу помочь?','А, друг-следопыт. Что тебе нужно?','А, друг-следопыт. Что тебе нужно?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приятно видеть здесь кого-то в здравом уме. Чем могу помочь?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Приятно видеть здесь кого-то в здравом уме. Чем могу помочь?',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','А, друг-следопыт. Что тебе нужно?',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','А, друг-следопыт. Что тебе нужно?',`text1_1_loc8`);
