INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9191,'У тебя явно нет способностей к изучению сложных чар, |3-6($c). Ступай.','У тебя явно нет способностей к изучению сложных чар, |3-6($c). Ступай.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','У тебя явно нет способностей к изучению сложных чар, |3-6($c). Ступай.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','У тебя явно нет способностей к изучению сложных чар, |3-6($c). Ступай.',`text0_1_loc8`);
