INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (9192,'Какую помощь в твоих изысканиях могу я тебе оказать?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Какую помощь в твоих изысканиях могу я тебе оказать?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9193,'Наша стезя подходит лишь для тех, чья воля тверда, а решимость – непоколебима. В тебе, |3-6($c), я не вижу ни того, ни другого.','Наша стезя подходит лишь для тех, чья воля тверда, а решимость – непоколебима. В тебе, |3-6($c), я не вижу ни того, ни другого.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Наша стезя подходит лишь для тех, чья воля тверда, а решимость – непоколебима. В тебе, |3-6($c), я не вижу ни того, ни другого.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Наша стезя подходит лишь для тех, чья воля тверда, а решимость – непоколебима. В тебе, |3-6($c), я не вижу ни того, ни другого.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9195,'Приветствую, $gбрат:сестра; $gмой:моя;. Чем я могу тебе помочь?','Приветствую, $gбрат:сестра; $gмой:моя;. Чем я могу тебе помочь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приветствую, $gбрат:сестра; $gмой:моя;. Чем я могу тебе помочь?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Приветствую, $gбрат:сестра; $gмой:моя;. Чем я могу тебе помочь?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9197,'В этой книге содержится информация о видах растений в Запределье. Большинство растений родом из Зангартопи.$B$BТаблицы и диаграммы тебе будет немного непонятны. Возможно, автор оставил там какие-нибудь сноски.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','В этой книге содержится информация о видах растений в Запределье. Большинство растений родом из Зангартопи.$B$BТаблицы и диаграммы тебе будет немного непонятны. Возможно, автор оставил там какие-нибудь сноски.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`,`text1_1_loc8`) VALUES (9199,'Я всегда любила все сортировать и раскладывать. Наверное, это в маму.','Нашу экспедицию очень интересуют новые виды растений. И не только лечебных или съедобных.$B$BРастения – основа существования множества других форм жизни. Чем лучше мы понимаем их, тем лучше понимаем природу в целом.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я всегда любила все сортировать и раскладывать. Наверное, это в маму.',`text0_1_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Нашу экспедицию очень интересуют новые виды растений. И не только лечебных или съедобных.$B$BРастения – основа существования множества других форм жизни. Чем лучше мы понимаем их, тем лучше понимаем природу в целом.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9201,'Я пока не знаю, что думать о таких, как ты, |3-6($r). Некоторые из вас могут быть жестокими и убивать спорлингов, как только их увидят.$B$BТы выглядишь $gдружелюбным:дружелюбной;… хотя и немного $gстранным:странной;.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я пока не знаю, что думать о таких, как ты, |3-6($r). Некоторые из вас могут быть жестокими и убивать спорлингов, как только их увидят.$B$BТы выглядишь $gдружелюбным:дружелюбной;… хотя и немного $gстранным:странной;.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9202,'Приветствую тебя в Спореггаре, |3-6($r)! Нечасто мы тут таких встречаем, но ты $gдоказал: доказала; нам, что многого стоишь. Будь здесь как дома.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приветствую тебя в Спореггаре, |3-6($r)! Нечасто мы тут таких встречаем, но ты $gдоказал: доказала; нам, что многого стоишь. Будь здесь как дома.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9203,'Болотники пожирают мешочки со спорами! Надо их остановить!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Болотники пожирают мешочки со спорами! Надо их остановить!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9218,'Мой отец уехал в более экзотические места, чтобы поохотиться на добычу покрупнее. Но не переживайте, нам и тут есть на кого охотиться!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мой отец уехал в более экзотические места, чтобы поохотиться на добычу покрупнее. Но не переживайте, нам и тут есть на кого охотиться!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9219,'Гляди в оба, |3-6($c). Никогда не знаешь, когда какой-нибудь зверек вздумает поохотиться на тебя, а не наоборот.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Гляди в оба, |3-6($c). Никогда не знаешь, когда какой-нибудь зверек вздумает поохотиться на тебя, а не наоборот.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9225,'Войска леди Праудмур пали, чтобы задержать Архимонда и Пылающий Легион, а теперь эта мрачная участь выпадает нам. Ты $gготов:готова; останавливать атаку вместе со мной?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Войска леди Праудмур пали, чтобы задержать Архимонда и Пылающий Легион, а теперь эта мрачная участь выпадает нам. Ты $gготов:готова; останавливать атаку вместе со мной?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9228,'Пусть Легион развернется в полную силу!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Пусть Легион развернется в полную силу!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9230,'Пылающий Легион сильно нажимает на нас, но наша оборона держится. Каждый миг, что нам удается удержать Архимонда вдали от Древа Жизни, приближает нас к победе.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Пылающий Легион сильно нажимает на нас, но наша оборона держится. Каждый миг, что нам удается удержать Архимонда вдали от Древа Жизни, приближает нас к победе.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9236,'Макту не узнает вас, |3-6($r), но он рад с вами познакомиться. Если вам когда-нибудь потребуется купить доспехи или починить их, не ищите никого, кроме Макту.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Макту не узнает вас, |3-6($r), но он рад с вами познакомиться. Если вам когда-нибудь потребуется купить доспехи или починить их, не ищите никого, кроме Макту.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9237,'Воспоминания об этом храме застилают мой разум густым туманом, но я не могу собрать их в связный рассказ. Это место некогда что-то значило для меня. Пока я не восстановлю эти воспоминания, буду чувствовать, как будто часть меня отсутствует. $b$bМожет быть, дренеи помогут мне вернуть то, что я утратил.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Воспоминания об этом храме застилают мой разум густым туманом, но я не могу собрать их в связный рассказ. Это место некогда что-то значило для меня. Пока я не восстановлю эти воспоминания, буду чувствовать, как будто часть меня отсутствует. $b$bМожет быть, дренеи помогут мне вернуть то, что я утратил.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9238,'Есть те, кто зовет меня "Тим", но для друзей я – "специалист".') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Есть те, кто зовет меня "Тим", но для друзей я – "специалист".',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9239,'Если вам нужно что-то спросить, то вы слишком мало меня знаете, чтобы обращаться ко мне подобным образом.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если вам нужно что-то спросить, то вы слишком мало меня знаете, чтобы обращаться ко мне подобным образом.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9240,'Приветствую, |3-6($c). Хочешь довести свое мастерство охоты до предела? Ты $gпришел:пришла; по адресу.$B$BХеминг Эрнестуэй организовал лучшую экспедицию, которую знали руины этого мира. Отправляйся вместе с нами, если не трусишь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приветствую, |3-6($c). Хочешь довести свое мастерство охоты до предела? Ты $gпришел:пришла; по адресу.$B$BХеминг Эрнестуэй организовал лучшую экспедицию, которую знали руины этого мира. Отправляйся вместе с нами, если не трусишь.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9243,'Мудрость наару выше нашего понимания. Я узнал от А\'дала за последние пять месяцев больше, чем за все годы, проведенные мною в библиотеках Даларана.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мудрость наару выше нашего понимания. Я узнал от А\'дала за последние пять месяцев больше, чем за все годы, проведенные мною в библиотеках Даларана.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9244,'Здесь размещены объявления о наградах, полагающихся за головы известных преступников и злобных зверей. Прямо сейчас для вас было бы слишком опасно пытаться заработать вознаграждение, но стоит вернуться к доске объявлений, когда станете сильнее.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здесь размещены объявления о наградах, полагающихся за головы известных преступников и злобных зверей. Прямо сейчас для вас было бы слишком опасно пытаться заработать вознаграждение, но стоит вернуться к доске объявлений, когда станете сильнее.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9246,'На этой доске размещены различные объявления и уведомления о выплате наград.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','На этой доске размещены различные объявления и уведомления о выплате наград.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9248,'Добро пожаловать в Забра\'джин, |3-6($c). Я темный охотник Дэнжай, смотритель этого аванпоста и командир сил Черного Копья в Зангартопи.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать в Забра\'джин, |3-6($c). Я темный охотник Дэнжай, смотритель этого аванпоста и командир сил Черного Копья в Зангартопи.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9249,'И не думай даже пробовать удрать от меня с моими мурлочьими младенцами! У меня глаза ястреба и уши… уши… В общем, я отлично слышу!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','И не думай даже пробовать удрать от меня с моими мурлочьими младенцами! У меня глаза ястреба и уши… уши… В общем, я отлично слышу!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9259,'Когда я впервые увидел грибы выше деревьев, я не был уверен, что смогу назвать такое место своим домом. А потом просто перестал замечать.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Когда я впервые увидел грибы выше деревьев, я не был уверен, что смогу назвать такое место своим домом. А потом просто перестал замечать.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (9260,'Пока ты в Зангартопи – выдели время на рыбалку. Неизвестно ведь, когда ты снова увидишь воду.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Пока ты в Зангартопи – выдели время на рыбалку. Неизвестно ведь, когда ты снова увидишь воду.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (9262,'Не правда ли, с вершины Терелдора открывается прекрасный вид?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Не правда ли, с вершины Терелдора открывается прекрасный вид?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9263,'Добро пожаловать в Телредор, |3-6($c). Если тебе что-то нужно – спрашивай, не стесняйся.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать в Телредор, |3-6($c). Если тебе что-то нужно – спрашивай, не стесняйся.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9267,'Темный охотник Дэнжай прислал меня сюда с небольшим отрядом строителей и воинов, дабы заложить здесь форпост. Мы едва-едва закончили строить, а он уже требует рапортов!$B$BЕсли тебе нужны припасы, я могу предложить кое-что, но мы все еще ждем первой поставки.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Темный охотник Дэнжай прислал меня сюда с небольшим отрядом строителей и воинов, дабы заложить здесь форпост. Мы едва-едва закончили строить, а он уже требует рапортов!$B$BЕсли тебе нужны припасы, я могу предложить кое-что, но мы все еще ждем первой поставки.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9268,'Если ты когда-нибудь встретишь знахаря Тор\'геша, передай ему, что его зелья и амулеты не работают! Я сделал все так, как он мне сказал, но Магаша до сих пор заглядывается на Зурая.$B$BНе верь ни единому слову этого знахаря!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если ты когда-нибудь встретишь знахаря Тор\'геша, передай ему, что его зелья и амулеты не работают! Я сделал все так, как он мне сказал, но Магаша до сих пор заглядывается на Зурая.$B$BНе верь ни единому слову этого знахаря!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (9269,'Реавиж грациозен, словно кодо! Забавно то, что он и сам не понимает, как неуклюже прячется. Я же вижу, как он якобы незаметно смотрит на меня.$B$BОн меня пугает. Хорошо бы темный охотник Дэнжай его с нами не посылал. На заставе Болотной Крысы было бы очень удобно от него сбежать.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Реавиж грациозен, словно кодо! Забавно то, что он и сам не понимает, как неуклюже прячется. Я же вижу, как он якобы незаметно смотрит на меня.$B$BОн меня пугает. Хорошо бы темный охотник Дэнжай его с нами не посылал. На заставе Болотной Крысы было бы очень удобно от него сбежать.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9270,'Здравствуй, |3-6($c). Я то, что называют одним из Сломленных. Подобно Заблудшим, хотя и не так тяжко, мы пострадали от энергии Скверны, которая исказила нашу изначальную форму дренеев.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здравствуй, |3-6($c). Я то, что называют одним из Сломленных. Подобно Заблудшим, хотя и не так тяжко, мы пострадали от энергии Скверны, которая исказила нашу изначальную форму дренеев.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9273,'Здесь написано о наградах за предводителей наг из племен Темного Гребня и Кровавой Чешуи. Оба они, как видно, очень опасны, возможно, тебе стоит зайти попозже.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здесь написано о наградах за предводителей наг из племен Темного Гребня и Кровавой Чешуи. Оба они, как видно, очень опасны, возможно, тебе стоит зайти попозже.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9276,'Нас ждут смутные времена, $gнезнакомец:незнакомка;.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Нас ждут смутные времена, $gнезнакомец:незнакомка;.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9277,'Духи сильно взволнованы. Нам нужно выяснить причину их беспокойства.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Духи сильно взволнованы. Нам нужно выяснить причину их беспокойства.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9286,'Да-да, я чувствую себя лучше, но мне здесь вроде как понравилось.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да-да, я чувствую себя лучше, но мне здесь вроде как понравилось.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9287,'Консорциум планировал эту операцию не один месяц! Мы собирались выкопать Ошу\'гун, самый большой алмаз во вселенной!$B$BИ за минуту до начала работ пришло сообщение от принца Харамада, в котором он приказывал нам задержаться до тех пор, пока не будет улажен некий политический вопрос в Пустоверти. Я заставил весь народ отмывать контрабандные драгоценные камни, но это занятие уже начинает приносить нам убытки.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Консорциум планировал эту операцию не один месяц! Мы собирались выкопать Ошу\'гун, самый большой алмаз во вселенной!$B$BИ за минуту до начала работ пришло сообщение от принца Харамада, в котором он приказывал нам задержаться до тех пор, пока не будет улажен некий политический вопрос в Пустоверти. Я заставил весь народ отмывать контрабандные драгоценные камни, но это занятие уже начинает приносить нам убытки.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9288,'Гезхе здесь, чтобы закончить работу. А я здесь, чтобы его в это время никто не беспокоил.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Гезхе здесь, чтобы закончить работу. А я здесь, чтобы его в это время никто не беспокоил.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9289,'Ты знаешь, кто мы, $gнезнакомец:незнакомка;? Мы маг\'хары – коричневые орки, как вы называете нас. Маг\'хары – племя выживших членов сгинувшей династии, выживших после Алой Чумы, выживших в расколотом мире…$B$BЯ Джорин, сын Килрогга, последний из рода Мертвого Глаза, военный вождь клана Кровавой Глазницы.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты знаешь, кто мы, $gнезнакомец:незнакомка;? Мы маг\'хары – коричневые орки, как вы называете нас. Маг\'хары – племя выживших членов сгинувшей династии, выживших после Алой Чумы, выживших в расколотом мире…$B$BЯ Джорин, сын Килрогга, последний из рода Мертвого Глаза, военный вождь клана Кровавой Глазницы.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (9290,'Мы бы никогда не разбились, если бы Хеминг не прострелил элерон, когда палил по дичи на земле!$B$BНо ничего страшного, я скоро все починю.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мы бы никогда не разбились, если бы Хеминг не прострелил элерон, когда палил по дичи на земле!$B$BНо ничего страшного, я скоро все починю.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (9292,'Я так рада, что злобный Ганкли Тухлопал получил по заслугам! У меня есть много кожи – на случай, если ты захочешь вручить такую Гарольду…') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я так рада, что злобный Ганкли Тухлопал получил по заслугам! У меня есть много кожи – на случай, если ты захочешь вручить такую Гарольду…',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`,`text1_1_loc8`) VALUES (9297,'Всех нас воспитала Великая Мать. Она так или иначе связана с каждым маг\'харом, которого ты видишь. Когда она умрет, мы все будем по ней скучать.','Великая Мать говорит, что меня назвали в честь великого героя орков.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Всех нас воспитала Великая Мать. Она так или иначе связана с каждым маг\'харом, которого ты видишь. Когда она умрет, мы все будем по ней скучать.',`text0_1_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Великая Мать говорит, что меня назвали в честь великого героя орков.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9312,'Похоже, вы довольно $gблагоразумный:благоразумная:r; |3-6($r). Мы могли бы помочь друг другу.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Похоже, вы довольно $gблагоразумный:благоразумная:r; |3-6($r). Мы могли бы помочь друг другу.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9315,'Будь $gсильным:сильной;. Кель\'тас предал нас, грядут большие перемены, но не стоит падать духом. Мы выстоим, как выстаивали раньше. Если уж Артас, разоривший наши земли, не сломил наш дух, то и Келю это не под силу. Пусть это послужит нам уроком на пути к светлому будущему.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Будь $gсильным:сильной;. Кель\'тас предал нас, грядут большие перемены, но не стоит падать духом. Мы выстоим, как выстаивали раньше. Если уж Артас, разоривший наши земли, не сломил наш дух, то и Келю это не под силу. Пусть это послужит нам уроком на пути к светлому будущему.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9316,'Что в нашем славном городе ты желаешь посетить?','Что в нашем славном городе ты желаешь посетить?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что в нашем славном городе ты желаешь посетить?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Что в нашем славном городе ты желаешь посетить?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9317,'В Луносвете у нас два аукционных дома. Какой ты хочешь посетить?','В Луносвете у нас два аукционных дома. Какой ты хочешь посетить?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','В Луносвете у нас два аукционных дома. Какой ты хочешь посетить?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','В Луносвете у нас два аукционных дома. Какой ты хочешь посетить?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9318,'Западный аукционный дом можно найти посредине базара, к западу от Пути Старейшин.','Западный аукционный дом можно найти посредине базара, к западу от Пути Старейшин.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Западный аукционный дом можно найти посредине базара, к западу от Пути Старейшин.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Западный аукционный дом можно найти посредине базара, к западу от Пути Старейшин.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9319,'Аукционный дом Королевской биржи можно найти в восточной части города, к югу от тренировочного полигона рыцарей Крови и следопытов.','Аукционный дом Королевской биржи можно найти в восточной части города, к югу от тренировочного полигона рыцарей Крови и следопытов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Аукционный дом Королевской биржи можно найти в восточной части города, к югу от тренировочного полигона рыцарей Крови и следопытов.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Аукционный дом Королевской биржи можно найти в восточной части города, к югу от тренировочного полигона рыцарей Крови и следопытов.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9320,'По какому пути ты хочешь следовать?','По какому пути ты хочешь следовать?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','По какому пути ты хочешь следовать?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','По какому пути ты хочешь следовать?',`text0_1_loc8`);
