INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9321,'Банк Луносвета находится на территории базара. Вы найдете его в юго-восточной части.','Банк Луносвета находится на территории базара. Вы найдете его в юго-восточной части.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Банк Луносвета находится на территории базара. Вы найдете его в юго-восточной части.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Банк Луносвета находится на территории базара. Вы найдете его в юго-восточной части.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9322,'Если вы в восточной части города ищете банк, вам не придется идти дальше, чем до королевской биржи. Он находится вон там, у северной стены.','Если вы в восточной части города ищете банк, вам не придется идти дальше, чем до королевской биржи. Он находится вон там, у северной стены.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если вы в восточной части города ищете банк, вам не придется идти дальше, чем до королевской биржи. Он находится вон там, у северной стены.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Если вы в восточной части города ищете банк, вам не придется идти дальше, чем до королевской биржи. Он находится вон там, у северной стены.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9324,'Регистратор гильдий Луносвета – Тандрина. Жилище ее стоит на Пути Старейшин, рядом с Магистерскими воротами.','Регистратор гильдий Луносвета – Тандрина. Жилище ее стоит на Пути Старейшин, рядом с Магистерскими воротами.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Регистратор гильдий Луносвета – Тандрина. Жилище ее стоит на Пути Старейшин, рядом с Магистерскими воротами.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Регистратор гильдий Луносвета – Тандрина. Жилище ее стоит на Пути Старейшин, рядом с Магистерскими воротами.',`text0_1_loc8`);
