INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9326,'В нашем славном городе почтовых ящиков с избытком. Тот, что находится в Королевском Валютном банке, наверняка удовлетворит твои нужды.','В нашем славном городе почтовых ящиков с избытком. Тот, что находится в Королевском Валютном банке, наверняка удовлетворит твои нужды.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','В нашем славном городе почтовых ящиков с избытком. Тот, что находится в Королевском Валютном банке, наверняка удовлетворит твои нужды.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','В нашем славном городе почтовых ящиков с избытком. Тот, что находится в Королевском Валютном банке, наверняка удовлетворит твои нужды.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9327,'Шаленна присматривает за питомцами и не дает им сбежать, пока их хозяева занимаются неизвестно чем. Ее можно найти на площади Странников.','Шаленна присматривает за питомцами и не дает им сбежать, пока их хозяева занимаются неизвестно чем. Ее можно найти на площади Странников.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Шаленна присматривает за питомцами и не дает им сбежать, пока их хозяева занимаются неизвестно чем. Ее можно найти на площади Странников.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Шаленна присматривает за питомцами и не дает им сбежать, пока их хозяева занимаются неизвестно чем. Ее можно найти на площади Странников.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9328,'Рыцари Крови с площади Странников любезно предоставили место в своих комнатах Иледе, эксперту по оружию из Луносвета. Хотя ее уроки стоят недешево, ты высоко оценишь ее многолетний опыт.','Рыцари Крови с площади Странников любезно предоставили место в своих комнатах Иледе, эксперту по оружию из Луносвета. Хотя ее уроки стоят недешево, ты высоко оценишь ее многолетний опыт.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Рыцари Крови с площади Странников любезно предоставили место в своих комнатах Иледе, эксперту по оружию из Луносвета. Хотя ее уроки стоят недешево, ты высоко оценишь ее многолетний опыт.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Рыцари Крови с площади Странников любезно предоставили место в своих комнатах Иледе, эксперту по оружию из Луносвета. Хотя ее уроки стоят недешево, ты высоко оценишь ее многолетний опыт.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9329,'Военачальники отдыхают в глубинах залов анклава Рыцарей Крови на площади Странников. Они немного… грубоваты, но их можно простить.','Военачальники отдыхают в глубинах залов анклава Рыцарей Крови на площади Странников. Они немного… грубоваты, но их можно простить.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Военачальники отдыхают в глубинах залов анклава Рыцарей Крови на площади Странников. Они немного… грубоваты, но их можно простить.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Военачальники отдыхают в глубинах залов анклава Рыцарей Крови на площади Странников. Они немного… грубоваты, но их можно простить.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (9330,'$GОдин:Одна; из друидов? Наш народ не следует этими путями… но тебе повезло. Женщина тауренов, – по крайней мере мне кажется, что это женщина, – построила скромное жилище в северной части Пути Старейшин. Ее зовут Харена Равнинная Странница.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','$GОдин:Одна; из друидов? Наш народ не следует этими путями… но тебе повезло. Женщина тауренов, – по крайней мере мне кажется, что это женщина, – построила скромное жилище в северной части Пути Старейшин. Ее зовут Харена Равнинная Странница.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9331,'По какому пути ты хочешь следовать?','По какому пути ты хочешь следовать?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','По какому пути ты хочешь следовать?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','По какому пути ты хочешь следовать?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9332,'Ох. Ты ищешь одного из них? Ну, если ты действительно хочешь тратить свое время на разговоры с этими отсталыми индивидуумами, ты найдешь следопытов на площади Странников. Зандина там о тебе позаботится.','Ох. Ты ищешь одного из них? Ну, если ты действительно хочешь тратить свое время на разговоры с этими отсталыми индивидуумами, ты найдешь следопытов на площади Странников. Зандина там о тебе позаботится.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ох. Ты ищешь одного из них? Ну, если ты действительно хочешь тратить свое время на разговоры с этими отсталыми индивидуумами, ты найдешь следопытов на площади Странников. Зандина там о тебе позаботится.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ох. Ты ищешь одного из них? Ну, если ты действительно хочешь тратить свое время на разговоры с этими отсталыми индивидуумами, ты найдешь следопытов на площади Странников. Зандина там о тебе позаботится.',`text0_1_loc8`);
