INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9333,'А, ищешь просвещенных магистров? Тогда обратись к Квитасу. Он с коллегами заседает в Дворце Ярости Солнца.','А, ищешь просвещенных магистров? Тогда обратись к Квитасу. Он с коллегами заседает в Дворце Ярости Солнца.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','А, ищешь просвещенных магистров? Тогда обратись к Квитасу. Он с коллегами заседает в Дворце Ярости Солнца.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','А, ищешь просвещенных магистров? Тогда обратись к Квитасу. Он с коллегами заседает в Дворце Ярости Солнца.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9334,'Леди Лиадрин, матриарх рыцарей Крови, находится в штаб-квартире рыцарей в анклаве на площади Странников. Если вы ждете указаний, то поговорите там с воителем Баки. И проявите уважение, иначе вам не сносить головы.','Леди Лиадрин, матриарх рыцарей Крови, находится в штаб-квартире рыцарей в анклаве на площади Странников. Если вы ждете указаний, то поговорите там с воителем Баки. И проявите уважение, иначе вам не сносить головы.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Леди Лиадрин, матриарх рыцарей Крови, находится в штаб-квартире рыцарей в анклаве на площади Странников. Если вы ждете указаний, то поговорите там с воителем Баки. И проявите уважение, иначе вам не сносить головы.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Леди Лиадрин, матриарх рыцарей Крови, находится в штаб-квартире рыцарей в анклаве на площади Странников. Если вы ждете указаний, то поговорите там с воителем Баки. И проявите уважение, иначе вам не сносить головы.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9335,'Жрецы нашего прекрасного города находятся у Дворца Ярости Солнца. Поищите леди Белестру.','Жрецы нашего прекрасного города находятся у Дворца Ярости Солнца. Поищите леди Белестру.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Жрецы нашего прекрасного города находятся у Дворца Ярости Солнца. Поищите леди Белестру.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Жрецы нашего прекрасного города находятся у Дворца Ярости Солнца. Поищите леди Белестру.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9336,'Самых ловких из нас порой трудно заметить, но, возможно, вам удастся поймать разбойника Зеланиса и его отряд в Закоулке Душегубов.','Самых ловких из нас порой трудно заметить, но, возможно, вам удастся поймать разбойника Зеланиса и его отряд в Закоулке Душегубов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Самых ловких из нас порой трудно заметить, но, возможно, вам удастся поймать разбойника Зеланиса и его отряд в Закоулке Душегубов.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Самых ловких из нас порой трудно заметить, но, возможно, вам удастся поймать разбойника Зеланиса и его отряд в Закоулке Душегубов.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9337,'Призыв демонов – опасное занятие, но и результат колоссальный. Наш постоянный эксперт Аламма, приглядывающий за чернокнижниками, живет в Закоулке Душегубов.','Призыв демонов – опасное занятие, но и результат колоссальный. Наш постоянный эксперт Аламма, приглядывающий за чернокнижниками, живет в Закоулке Душегубов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Призыв демонов – опасное занятие, но и результат колоссальный. Наш постоянный эксперт Аламма, приглядывающий за чернокнижниками, живет в Закоулке Душегубов.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Призыв демонов – опасное занятие, но и результат колоссальный. Наш постоянный эксперт Аламма, приглядывающий за чернокнижниками, живет в Закоулке Душегубов.',`text0_1_loc8`);
