INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9338,'Какую профессию вы бы хотели изучить?','Какую профессию вы бы хотели изучить?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Какую профессию вы бы хотели изучить?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Какую профессию вы бы хотели изучить?',`text0_1_loc8`);
