INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9340,'Бемаррин учит кузнечному делу на площади Странников. Несмотря на то что это немного… грязное занятие, я думаю, у него есть свои плюсы.','Бемаррин учит кузнечному делу на площади Странников. Несмотря на то что это немного… грязное занятие, я думаю, у него есть свои плюсы.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Бемаррин учит кузнечному делу на площади Странников. Несмотря на то что это немного… грязное занятие, я думаю, у него есть свои плюсы.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Бемаррин учит кузнечному делу на площади Странников. Несмотря на то что это немного… грязное занятие, я думаю, у него есть свои плюсы.',`text0_1_loc8`);
