INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9341,'Насколько мне известно, зачаровывательница Седана набирает учеников. Ты найдешь ее в одной из беседок во Дворе Солнца.','Насколько мне известно, зачаровывательница Седана набирает учеников. Ты найдешь ее в одной из беседок во Дворе Солнца.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Насколько мне известно, зачаровывательница Седана набирает учеников. Ты найдешь ее в одной из беседок во Дворе Солнца.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Насколько мне известно, зачаровывательница Седана набирает учеников. Ты найдешь ее в одной из беседок во Дворе Солнца.',`text0_1_loc8`);
