INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9343,'Алестус – мастер по… художественной штопке ран. Если ты хочешь научиться первой помощи, поищи его на Пути Старейшин, у входа в Королевскую биржу.','Алестус – мастер по… художественной штопке ран. Если ты хочешь научиться первой помощи, поищи его на Пути Старейшин, у входа в Королевскую биржу.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Алестус – мастер по… художественной штопке ран. Если ты хочешь научиться первой помощи, поищи его на Пути Старейшин, у входа в Королевскую биржу.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Алестус – мастер по… художественной штопке ран. Если ты хочешь научиться первой помощи, поищи его на Пути Старейшин, у входа в Королевскую биржу.',`text0_1_loc8`);
