INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9344,'Воды Кель\'Таласа кишат рыбой; полагаю, она и тебя привлекает? Дратен изрядно поднаторел в рыболовстве, а найти его можно на Пути Старейшин, рядом с Королевской биржей.','Воды Кель\'Таласа кишат рыбой; полагаю, она и тебя привлекает? Дратен изрядно поднаторел в рыболовстве, а найти его можно на Пути Старейшин, рядом с Королевской биржей.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Воды Кель\'Таласа кишат рыбой; полагаю, она и тебя привлекает? Дратен изрядно поднаторел в рыболовстве, а найти его можно на Пути Старейшин, рядом с Королевской биржей.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Воды Кель\'Таласа кишат рыбой; полагаю, она и тебя привлекает? Дратен изрядно поднаторел в рыболовстве, а найти его можно на Пути Старейшин, рядом с Королевской биржей.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9345,'Ботаник Натера умеет собирать травы и, полагаю, может поделиться своей мудростью с кем-нибудь вроде тебя. Ты найдешь ее рядом с алхимиками в беседке во Дворе Солнца.','Ботаник Натера умеет собирать травы и, полагаю, может поделиться своей мудростью с кем-нибудь вроде тебя. Ты найдешь ее рядом с алхимиками в беседке во Дворе Солнца.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ботаник Натера умеет собирать травы и, полагаю, может поделиться своей мудростью с кем-нибудь вроде тебя. Ты найдешь ее рядом с алхимиками в беседке во Дворе Солнца.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ботаник Натера умеет собирать травы и, полагаю, может поделиться своей мудростью с кем-нибудь вроде тебя. Ты найдешь ее рядом с алхимиками в беседке во Дворе Солнца.',`text0_1_loc8`);
