INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9347,'У юго-восточного конца Пути Старейшин Линалис поставила отличный станок для выделки кожи. Она тебя обучит… за небольшую плату.','У юго-восточного конца Пути Старейшин Линалис поставила отличный станок для выделки кожи. Она тебя обучит… за небольшую плату.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','У юго-восточного конца Пути Старейшин Линалис поставила отличный станок для выделки кожи. Она тебя обучит… за небольшую плату.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','У юго-восточного конца Пути Старейшин Линалис поставила отличный станок для выделки кожи. Она тебя обучит… за небольшую плату.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9348,'Если лучшим развлечением ты полагаешь рытье в грязи, найди себе подобного – например, Беллила на площади Странников. Он, я думаю, рад будет узнать, что не одинок в своем чудачестве.','Если лучшим развлечением ты полагаешь рытье в грязи, найди себе подобного – например, Беллила на площади Странников. Он, я думаю, рад будет узнать, что не одинок в своем чудачестве.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если лучшим развлечением ты полагаешь рытье в грязи, найди себе подобного – например, Беллила на площади Странников. Он, я думаю, рад будет узнать, что не одинок в своем чудачестве.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Если лучшим развлечением ты полагаешь рытье в грязи, найди себе подобного – например, Беллила на площади Странников. Он, я думаю, рад будет узнать, что не одинок в своем чудачестве.',`text0_1_loc8`);
