INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9349,'Тайн – очень талантливый специалист по снятию шкур. Она выделывает самые лучшие рысьи шкуры, какие я только видел. Если хочешь учиться у нее, ищи ее в юго-восточной части Пути Старейшин.','Тайн – очень талантливый специалист по снятию шкур. Она выделывает самые лучшие рысьи шкуры, какие я только видел. Если хочешь учиться у нее, ищи ее в юго-восточной части Пути Старейшин.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тайн – очень талантливый специалист по снятию шкур. Она выделывает самые лучшие рысьи шкуры, какие я только видел. Если хочешь учиться у нее, ищи ее в юго-восточной части Пути Старейшин.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Тайн – очень талантливый специалист по снятию шкур. Она выделывает самые лучшие рысьи шкуры, какие я только видел. Если хочешь учиться у нее, ищи ее в юго-восточной части Пути Старейшин.',`text0_1_loc8`);
