INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9350,'Портной Килен всегда ищет любознательных подмастерьев для обучения своему утонченному ремеслу. Его ателье поначалу трудновато найти, но вообще оно находится прямо к северу от аукционного дома на Базаре. Его можно найти на нижнем уровне здания.','Портной Килен всегда ищет любознательных подмастерьев для обучения своему утонченному ремеслу. Его ателье поначалу трудновато найти, но вообще оно находится прямо к северу от аукционного дома на Базаре. Его можно найти на нижнем уровне здания.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Портной Килен всегда ищет любознательных подмастерьев для обучения своему утонченному ремеслу. Его ателье поначалу трудновато найти, но вообще оно находится прямо к северу от аукционного дома на Базаре. Его можно найти на нижнем уровне здания.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Портной Килен всегда ищет любознательных подмастерьев для обучения своему утонченному ремеслу. Его ателье поначалу трудновато найти, но вообще оно находится прямо к северу от аукционного дома на Базаре. Его можно найти на нижнем уровне здания.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9361,'Кто это так смело встал перед Лантрезором Клинком? Неужели ты не узнаешь смерть в лицо, $gпарень:девушка;?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Кто это так смело встал перед Лантрезором Клинком? Неужели ты не узнаешь смерть в лицо, $gпарень:девушка;?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9362,'Значит, ты тупица. Разве тебе не известно, кто я?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Значит, ты тупица. Разве тебе не известно, кто я?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9363,'Орк…$B$B*Лантрезор смеется.*$B$BЯ – мастер клинка и сам наполовину орк.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Орк…$B$B*Лантрезор смеется.*$B$BЯ – мастер клинка и сам наполовину орк.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9364,'Дренеи… Из-за этого я никто. Ни орк, ни дреней. Мое племя – редкий вид. Большую часть перебили десятилетия назад… Я живу лишь благодаря своей силе воли.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Дренеи… Из-за этого я никто. Ни орк, ни дреней. Мое племя – редкий вид. Большую часть перебили десятилетия назад… Я живу лишь благодаря своей силе воли.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9365,'Прикуси язык, |3-6($r). Я за свою жизнь навидался такого, о чем ты только в легендах $gслышал:слышала;. Я без жалости убивал мужчин, женщин и детей. Я служил под знаменами двух вождей Орды… А теперь я правлю кланом Тяжелого Кулака.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Прикуси язык, |3-6($r). Я за свою жизнь навидался такого, о чем ты только в легендах $gслышал:слышала;. Я без жалости убивал мужчин, женщин и детей. Я служил под знаменами двух вождей Орды… А теперь я правлю кланом Тяжелого Кулака.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9366,'И что вашему племени требуется от Лантрезора, |3-6($r)?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','И что вашему племени требуется от Лантрезора, |3-6($r)?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9367,'*Лантрезор громко хохочет.* $b$bИ где ж ты, по-твоему, находишься, дурачина? Это же земля огров. Раньше, чем орки, раньше, чем дренеи – здесь были огры. И все же ты хочешь начать войну, в которой неизбежно проиграешь? Тяжелый Кулак сокрушит тебя. А если тебя не уничтожит Тяжелый Кулак, это сделает Боевой Молот… $b$bНо, я думаю, твое начальство об этом и так знает…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','*Лантрезор громко хохочет.* $b$bИ где ж ты, по-твоему, находишься, дурачина? Это же земля огров. Раньше, чем орки, раньше, чем дренеи – здесь были огры. И все же ты хочешь начать войну, в которой неизбежно проиграешь? Тяжелый Кулак сокрушит тебя. А если тебя не уничтожит Тяжелый Кулак, это сделает Боевой Молот… $b$bНо, я думаю, твое начальство об этом и так знает…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9368,'*Лантрезор пристально смотрит на тебя так, будто видит тебя насквозь.*$B$BВозможно, есть другой путь… Я соглашусь на требование вашего лидера только в том случае, если ты выполнишь в точности то, что я попрошу.$B$BС твоей помощью мы, может быть, сможем очень хорошо помочь друг другу.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','*Лантрезор пристально смотрит на тебя так, будто видит тебя насквозь.*$B$BВозможно, есть другой путь… Я соглашусь на требование вашего лидера только в том случае, если ты выполнишь в точности то, что я попрошу.$B$BС твоей помощью мы, может быть, сможем очень хорошо помочь друг другу.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9369,'Вы разыграете серию сцен, которые заставят орков бастиона Вечной Скорби поверить, что на их базу напали огры клана Боевого Молота, и устроите другую серию событий, которая убедит огров клана Боевого Молота в том, что орки бастиона Вечной Скорби напали на их базу.$B$BСделай так, и ты избавишь нас от обеих проблем.$B$BОгры клана Тяжелого Кулака получат назад свои территории, а наш народ будет защищен от нападений Тяжелого Кулака, Боевого Молота и Совета Теней.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вы разыграете серию сцен, которые заставят орков бастиона Вечной Скорби поверить, что на их базу напали огры клана Боевого Молота, и устроите другую серию событий, которая убедит огров клана Боевого Молота в том, что орки бастиона Вечной Скорби напали на их базу.$B$BСделай так, и ты избавишь нас от обеих проблем.$B$BОгры клана Тяжелого Кулака получат назад свои территории, а наш народ будет защищен от нападений Тяжелого Кулака, Боевого Молота и Совета Теней.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9373,'Желающие подать заявку должны переговорить со стражем-смотрителем Быккроком, прежде чем опубликовать какое-либо задание. $b$bТе, кого застанут за публикацией несанкционированных объявлений, будут наказаны.$b$bСчета на доску не помещать.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Желающие подать заявку должны переговорить со стражем-смотрителем Быккроком, прежде чем опубликовать какое-либо задание. $b$bТе, кого застанут за публикацией несанкционированных объявлений, будут наказаны.$b$bСчета на доску не помещать.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9374,'Прежде чем выставлять задание, обсудите его со стражем-смотрителем Мой\'прном Джиллом.$B$BНесанкционированное выставление заданий наказуемо.$B$BВывешивать объявления воспрещается.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Прежде чем выставлять задание, обсудите его со стражем-смотрителем Мой\'прном Джиллом.$B$BНесанкционированное выставление заданий наказуемо.$B$BВывешивать объявления воспрещается.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9375,'Если тебе нужна работа, взгляни на доску объявлений, |3-6($r).') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если тебе нужна работа, взгляни на доску объявлений, |3-6($r).',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9376,'Они не уважают мертвых, |3-6($r). Ограм надо преподать урок.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Они не уважают мертвых, |3-6($r). Ограм надо преподать урок.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9377,'Надо поискать выживших. Если кто-нибудь еще жив, надо хотя бы попытаться вернуть их.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Надо поискать выживших. Если кто-нибудь еще жив, надо хотя бы попытаться вернуть их.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (9380,'Отлично сделано, $gискатель:искательница; приключений. Смерть Лютого Хлада дала нам небольшую передышку между нападениями врага. Используйте это время с умом. Исцелите своих раненых и приготовьтесь защищаться, поскольку скоро Архимонд направит против нас еще более смертоносные войска. Мои немногочисленные вспомогательные отряды помогут вам, когда вновь начнется битва.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Отлично сделано, $gискатель:искательница; приключений. Смерть Лютого Хлада дала нам небольшую передышку между нападениями врага. Используйте это время с умом. Исцелите своих раненых и приготовьтесь защищаться, поскольку скоро Архимонд направит против нас еще более смертоносные войска. Мои немногочисленные вспомогательные отряды помогут вам, когда вновь начнется битва.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (9381,'Тогда позвольте Архимонду сделать самое худшее, что он может.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Тогда позвольте Архимонду сделать самое худшее, что он может.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`,`text3_0_loc8`,`text4_0_loc8`,`text5_0_loc8`,`text6_0_loc8`,`text7_0_loc8`) VALUES (9383,'Кто ты? Что тебе здесь надо?','Почему ты так поступил с нами?','Там ЧЕТЫРЕ огонька!','Мои пухоспинки отомстят за меня!','Куда все делись?','Гостям на ужине стоит быть повежливей!','О, какому святому месту пришел конец!','Помажь мне голову целебным бальзамом. Как тебе нравится моя корона из шипов?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Кто ты? Что тебе здесь надо?',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Почему ты так поступил с нами?',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Там ЧЕТЫРЕ огонька!',`text2_0_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Мои пухоспинки отомстят за меня!',`text3_0_loc8`), `text4_0_loc8`=IF(`text4_0_loc8` IS NULL OR `text4_0_loc8`='','Куда все делись?',`text4_0_loc8`), `text5_0_loc8`=IF(`text5_0_loc8` IS NULL OR `text5_0_loc8`='','Гостям на ужине стоит быть повежливей!',`text5_0_loc8`), `text6_0_loc8`=IF(`text6_0_loc8` IS NULL OR `text6_0_loc8`='','О, какому святому месту пришел конец!',`text6_0_loc8`), `text7_0_loc8`=IF(`text7_0_loc8` IS NULL OR `text7_0_loc8`='','Помажь мне голову целебным бальзамом. Как тебе нравится моя корона из шипов?',`text7_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9384,'Я могу обучить вас горному делу. Вам это интересно?','Я могу обучить вас горному делу. Вам это интересно?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я могу обучить вас горному делу. Вам это интересно?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я могу обучить вас горному делу. Вам это интересно?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9385,'Могу поучить тебя травничеству. Интересуешься?','Могу поучить тебя травничеству. Интересуешься?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Могу поучить тебя травничеству. Интересуешься?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Могу поучить тебя травничеству. Интересуешься?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (9387,'Потрясающе! Поражение Анатерона от вашей руки отдалило Архимонда от его целей и приводит нас к близкой победе. И все же мои силы не могут тут оставаться. И я, и мои войска обессилели, и теперь настал момент для отступления. Если ваша сила не изменила вам, отправляйтесь на восток, к лагерю Тралла. Там наша следующая остановка. Будьте здоровы.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Потрясающе! Поражение Анатерона от вашей руки отдалило Архимонда от его целей и приводит нас к близкой победе. И все же мои силы не могут тут оставаться. И я, и мои войска обессилели, и теперь настал момент для отступления. Если ваша сила не изменила вам, отправляйтесь на восток, к лагерю Тралла. Там наша следующая остановка. Будьте здоровы.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (9389,'Нам надо вернуть ящики с припасами назад!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Нам надо вернуть ящики с припасами назад!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9391,'Будь $gосторожен:осторожна;, когда отправишься в чащу, |3-6($c). Это место окутывает губительная аура. Должно быть, она осталась от того, что уничтожило моих друзей друидов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Будь $gосторожен:осторожна;, когда отправишься в чащу, |3-6($c). Это место окутывает губительная аура. Должно быть, она осталась от того, что уничтожило моих друзей друидов.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9392,'Этот лес – странное место. Он полон плохих джуджу, которые даже хуже Альянса, – так что будь настороже.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Этот лес – странное место. Он полон плохих джуджу, которые даже хуже Альянса, – так что будь настороже.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (9393,'Орда – не единственная опасность в этом лесу. Не позволяй кажущемуся спокойствию обмануть тебя.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Орда – не единственная опасность в этом лесу. Не позволяй кажущемуся спокойствию обмануть тебя.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9395,'Прочь с дороги, |3-6($r). Не видишь – мы здесь бьемся!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Прочь с дороги, |3-6($r). Не видишь – мы здесь бьемся!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9396,'Отлично! Предсмертный крик Каз\'рогала должен вселить страх в Пылающий Легион. Теперь они знают, насколько сильно твое войско, и потому ожидать от них стоит самого худшего.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Отлично! Предсмертный крик Каз\'рогала должен вселить страх в Пылающий Легион. Теперь они знают, насколько сильно твое войско, и потому ожидать от них стоит самого худшего.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9397,'Да пребудут с тобой духи.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да пребудут с тобой духи.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9398,'Потрясающе! Убить такого властителя преисподней, как Азгалор, – дело отнюдь не простое! Будь у нас больше времени, я бы с удовольствием послушал историю о том, как вам и вашим товарищам это удалось, но Архимонд не даст нам передышки. Мои разведчики уже доложили, что Легион собирает огромное войско рядом с нашим лагерем, и сам Архимонд находится в опасной близости от Древа Жизни. Леди Праудмур помогает нам эвакуироваться, а вам следует немедленно отправиться к Древу Жизни. Судьба нашего мира висит на волоске.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Потрясающе! Убить такого властителя преисподней, как Азгалор, – дело отнюдь не простое! Будь у нас больше времени, я бы с удовольствием послушал историю о том, как вам и вашим товарищам это удалось, но Архимонд не даст нам передышки. Мои разведчики уже доложили, что Легион собирает огромное войско рядом с нашим лагерем, и сам Архимонд находится в опасной близости от Древа Жизни. Леди Праудмур помогает нам эвакуироваться, а вам следует немедленно отправиться к Древу Жизни. Судьба нашего мира висит на волоске.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9401,'Труп одного из Сломленных лежит здесь. Странно, но непохоже, чтобы его убили бабочки-мутанты.$B$BВозможно, дело в странном предмете, лежащем прямо рядом с его вытянутой рукой?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Труп одного из Сломленных лежит здесь. Странно, но непохоже, чтобы его убили бабочки-мутанты.$B$BВозможно, дело в странном предмете, лежащем прямо рядом с его вытянутой рукой?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9403,'Приветствую, воин! Вы никогда не думали о том, чтобы полностью посвятить себя гладиаторским боям? Кучу денег бы заработали!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приветствую, воин! Вы никогда не думали о том, чтобы полностью посвятить себя гладиаторским боям? Кучу денег бы заработали!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9405,'Очень занят… я очень занят! Что?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Очень занят… я очень занят! Что?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9406,'А теперь, когда на мне живого места не осталось, чего тебе нужно?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','А теперь, когда на мне живого места не осталось, чего тебе нужно?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9407,'Мы разузнаем всю правду об этой резне, чего бы это нам ни стоило!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы разузнаем всю правду об этой резне, чего бы это нам ни стоило!',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (9408,'Твоя помощь в битве с Пылающим Легионом была бы очень кстати. Леди Джайне Праудмур пригодится твоя помощь на линии фронта.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Твоя помощь в битве с Пылающим Легионом была бы очень кстати. Леди Джайне Праудмур пригодится твоя помощь на линии фронта.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (9410,'День, которого мы так боялись, настал, |3-6($c). Архимонд добрался до Нодрассила и начал поглощать энергию Древа Жизни. Малфурион не сможет так быстро воплотить свои планы в жизнь, так что придется принять крайние меры. Пока мои войска сдерживают полчища Пылающего Легиона у вершины горы, ты нападешь на самого Архимонда!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','День, которого мы так боялись, настал, |3-6($c). Архимонд добрался до Нодрассила и начал поглощать энергию Древа Жизни. Малфурион не сможет так быстро воплотить свои планы в жизнь, так что придется принять крайние меры. Пока мои войска сдерживают полчища Пылающего Легиона у вершины горы, ты нападешь на самого Архимонда!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`) VALUES (9414,'Добро пожаловать в таверну Времени!','Дай отдых ногам, времени у нас полно…','Могу я предложить тебе выпивку? Честное слово, по выдержке ей нет равных!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать в таверну Времени!',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Дай отдых ногам, времени у нас полно…',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Могу я предложить тебе выпивку? Честное слово, по выдержке ей нет равных!',`text2_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9417,'Таверна "На краю земли" не может ничего предложить таким, как я. Однако же я вижу, что она привлекает как раз таких клиентов, которых могут заинтересовать мои товары.$B$BЯ специализируюсь на экзотических инженерных товарах из самых разных источников. Время от времени у меня даже может быть редкая вещь – или две – на продажу.$B$BХочешь что-нибудь посмотреть?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Таверна "На краю земли" не может ничего предложить таким, как я. Однако же я вижу, что она привлекает как раз таких клиентов, которых могут заинтересовать мои товары.$B$BЯ специализируюсь на экзотических инженерных товарах из самых разных источников. Время от времени у меня даже может быть редкая вещь – или две – на продажу.$B$BХочешь что-нибудь посмотреть?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9419,'Что ты видишь, глядя на запад, $gсмертный:смертная;?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что ты видишь, глядя на запад, $gсмертный:смертная;?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9425,'О нет, опять ты! Убирайся!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','О нет, опять ты! Убирайся!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9429,'Я, пожалуй, подзаработаю на стороне, пока другие решают, стоит ли отправляться в Ошу\'гун.$B$BВремя – деньги!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я, пожалуй, подзаработаю на стороне, пока другие решают, стоит ли отправляться в Ошу\'гун.$B$BВремя – деньги!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9431,'Руины Двух Башен еще не наши! Мне приказано поднять боевой штандарт лишь тогда, когда оба маяка будут гореть и вокруг не останется врагов. Марш туда и захвати эти маяки!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Руины Двух Башен еще не наши! Мне приказано поднять боевой штандарт лишь тогда, когда оба маяка будут гореть и вокруг не останется врагов. Марш туда и захвати эти маяки!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9432,'Маяки зажжены, пора нанести удар! Возьми один из боевых штандартов и установи его на кладбище во славу Альянса!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Маяки зажжены, пора нанести удар! Возьми один из боевых штандартов и установи его на кладбище во славу Альянса!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9433,'Руины Двух Башен еще не наши! Мне приказано поднять боевой штандарт лишь тогда, когда оба маяка будут гореть и вокруг не останется врагов. Марш туда и захвати эти маяки!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Руины Двух Башен еще не наши! Мне приказано поднять боевой штандарт лишь тогда, когда оба маяка будут гореть и вокруг не останется врагов. Марш туда и захвати эти маяки!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9437,'*Хранитель Древлос странно смотрит на вас и делает паузу, явно борясь с собой.*$B$BЗангартопь… слишком близко к истине.$B$B*Его взгляд снова становится безумным.*$B$BОн еще смотрит?!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','*Хранитель Древлос странно смотрит на вас и делает паузу, явно борясь с собой.*$B$BЗангартопь… слишком близко к истине.$B$B*Его взгляд снова становится безумным.*$B$BОн еще смотрит?!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9438,'Куда? В Зангартопь? А с какой стати мне хотеть туда попасть?$B$B*Древлос задумывается.*$B$BДа, Зангартопь… мы… Друиды там приближаются к разгадке того, почему уровень воды все время понижается. Это всему грозит уничтожением!$B$B*Вы видите, как безумие возвращается в глаза смотрящего в ночь.*$B$BВсех нас уничтожило! Яркий свет! БУУУМ!!!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Куда? В Зангартопь? А с какой стати мне хотеть туда попасть?$B$B*Древлос задумывается.*$B$BДа, Зангартопь… мы… Друиды там приближаются к разгадке того, почему уровень воды все время понижается. Это всему грозит уничтожением!$B$B*Вы видите, как безумие возвращается в глаза смотрящего в ночь.*$B$BВсех нас уничтожило! Яркий свет! БУУУМ!!!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9439,'Эльфы крови Огнекрылов… почему-то они хотят помешать нам.$B$B*Хранитель Древлос изо всех сил пытается не потерять сознание.*$B$BОни… они прислали одного из Сломленных в качестве дипломата… Но у него оказалась бомба!$B$BОни умерли, все до единого! Они пытались убежать, а самые счастливые даже ничего не поняли.$B$BЯ, должно быть, оказался на границе взрыва. Это было так ужа… ОНО СНОВА СМОТРИТ НА НАС!!!$B$B*Древлос в отчаянии смотрит сквозь вас, словно вас нет радом с ним.*') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эльфы крови Огнекрылов… почему-то они хотят помешать нам.$B$B*Хранитель Древлос изо всех сил пытается не потерять сознание.*$B$BОни… они прислали одного из Сломленных в качестве дипломата… Но у него оказалась бомба!$B$BОни умерли, все до единого! Они пытались убежать, а самые счастливые даже ничего не поняли.$B$BЯ, должно быть, оказался на границе взрыва. Это было так ужа… ОНО СНОВА СМОТРИТ НА НАС!!!$B$B*Древлос в отчаянии смотрит сквозь вас, словно вас нет радом с ним.*',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9440,'ЧЕГО ТЕБЕ НАДО?!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','ЧЕГО ТЕБЕ НАДО?!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9441,'Фшшшшшссссфхххх?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Фшшшшшссссфхххх?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (9451,'Моя работа – заботиться об этих несчастных душах. Я готова принять помощь от любого, кто хочет помочь, будь то Алдоры или Провидцы.$B$BНам так не хватает рук! Я бы даже огру не отказала, умей он накладывать жгут. Здешняя политика меня не касается.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Моя работа – заботиться об этих несчастных душах. Я готова принять помощь от любого, кто хочет помочь, будь то Алдоры или Провидцы.$B$BНам так не хватает рук! Я бы даже огру не отказала, умей он накладывать жгут. Здешняя политика меня не касается.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (9452,'Ты можешь поверить? У этого духа нет на счету ни единого глаза василиска!$B$BА его командир смеет называть себя "Принцем Контрабандистов"!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты можешь поверить? У этого духа нет на счету ни единого глаза василиска!$B$BА его командир смеет называть себя "Принцем Контрабандистов"!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (9458,'Дословный перевод слова Ша\'тар – "рожденные от света". Этим именем мы называем наару, отбивших Шаттрат у воинов Иллидана.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Дословный перевод слова Ша\'тар – "рожденные от света". Этим именем мы называем наару, отбивших Шаттрат у воинов Иллидана.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9471,'Добро пожаловать в Бастион Аллерии, |3-6($c).') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать в Бастион Аллерии, |3-6($c).',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9472,'Будь начеку, |3-6($c). Этот лес полон скрытых опасностей и потенциальных врагов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Будь начеку, |3-6($c). Этот лес полон скрытых опасностей и потенциальных врагов.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9477,'Это просто ужасно.$B$BНаши неудобства меня не волнуют, но ведь надо же что-то сделать, чтобы облегчить страдания мертвых в Костяных пустошах!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Это просто ужасно.$B$BНаши неудобства меня не волнуют, но ведь надо же что-то сделать, чтобы облегчить страдания мертвых в Костяных пустошах!',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (9478,'Ты здесь, чтобы помогать Алдорам?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты здесь, чтобы помогать Алдорам?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9481,'Если вы ждете официальных приветствий, то вынужден вас разочаровать, |3-6($c). Традиций мы тут не соблюдаем, бесполезное это занятие.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если вы ждете официальных приветствий, то вынужден вас разочаровать, |3-6($c). Традиций мы тут не соблюдаем, бесполезное это занятие.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9482,'Одно объявление выделяется среди тех, что приклеены к доске. Это заказ на истребление костеклювов на Костяных пустошах.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Одно объявление выделяется среди тех, что приклеены к доске. Это заказ на истребление костеклювов на Костяных пустошах.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9485,'Костеклювы – я их всех ненавижу!!!$b$bЕсли бы не потеря глаза и эти ослабевающие заклинания, которые на меня иногда воздействуют, я бы только и делал, что их отстреливал!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Костеклювы – я их всех ненавижу!!!$b$bЕсли бы не потеря глаза и эти ослабевающие заклинания, которые на меня иногда воздействуют, я бы только и делал, что их отстреливал!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9486,'Я наблюдал за тем, как Алдоры работали над стенами. Знаешь, они ведь весь город отстроят заново.$B$BРаботают они куда быстрее, чем это делал штейгер Ослоу у себя в Приозерье. У него то инструменты падали в озеро, то гноллы крали материал.$B$BНадо бы попросить Алдоров, пусть они ему помогут. С ними мост в два счета будет починен.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я наблюдал за тем, как Алдоры работали над стенами. Знаешь, они ведь весь город отстроят заново.$B$BРаботают они куда быстрее, чем это делал штейгер Ослоу у себя в Приозерье. У него то инструменты падали в озеро, то гноллы крали материал.$B$BНадо бы попросить Алдоров, пусть они ему помогут. С ними мост в два счета будет починен.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (9487,'Здесь целый огромный лес, |3-6($c). Пусть шаманы играют себе с духами, а воины – с мечами. Я же сделаю состояние в Тероккаре.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Здесь целый огромный лес, |3-6($c). Пусть шаманы играют себе с духами, а воины – с мечами. Я же сделаю состояние в Тероккаре.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9488,'Малуказ без умолку болтает об исторической важности этого леса. По мне, так у нас и в настоящем забот хватает, чтоб еще о былом печься.$B$BДа, да, его дело тоже важно, но кто-то должен думать о насущном – например, о защите и припасах.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Малуказ без умолку болтает об исторической важности этого леса. По мне, так у нас и в настоящем забот хватает, чтоб еще о былом печься.$B$BДа, да, его дело тоже важно, но кто-то должен думать о насущном – например, о защите и припасах.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9489,'Пока я не прошел через Награнд и не вышел в лес, мне казалось, что большая часть нашей культуры утеряна. Я рад, что ошибался.$B$BЗдесь так много надо сделать!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Пока я не прошел через Награнд и не вышел в лес, мне казалось, что большая часть нашей культуры утеряна. Я рад, что ошибался.$B$BЗдесь так много надо сделать!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (9490,'Открытие Темного портала принесло мне известия о судьбе моего народа. Ссылка, можно сказать, уберегла меня от их печальной судьбы, но видеть, как Странники набрасываются на Кель\'таса…$B$BЯ и не думала, что мои былые братья способны на такое.$B$BВозвращение на родину, о котором я мечтала, так никогда и не случится. Этот лес – мой единственный дом.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Открытие Темного портала принесло мне известия о судьбе моего народа. Ссылка, можно сказать, уберегла меня от их печальной судьбы, но видеть, как Странники набрасываются на Кель\'таса…$B$BЯ и не думала, что мои былые братья способны на такое.$B$BВозвращение на родину, о котором я мечтала, так никогда и не случится. Этот лес – мой единственный дом.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9493,'Видал, как Роз\'алета мне подмигивает, когда я захожу прикупить одежду или шляпу? Когда тут станет поспокойнее, я приглашу ее погулять в лесу.$B$BА сейчас я скучаю по отличным тавернам Штормграда…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Видал, как Роз\'алета мне подмигивает, когда я захожу прикупить одежду или шляпу? Когда тут станет поспокойнее, я приглашу ее погулять в лесу.$B$BА сейчас я скучаю по отличным тавернам Штормграда…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9495,'Может, мы и работаем вместе, но тем важнее осмотрительность. Еще раз: следи за своими словами и поступками.$B$BЯ могу гарантировать, что мы здесь далеко не единственные.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Может, мы и работаем вместе, но тем важнее осмотрительность. Еще раз: следи за своими словами и поступками.$B$BЯ могу гарантировать, что мы здесь далеко не единственные.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9497,'Да, чего надо? Не видишь, я занят? Совет Теней мне не по часам платит!','Да, чего надо? Не видишь, я занята? Совет Теней мне не по часам платит!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да, чего надо? Не видишь, я занят? Совет Теней мне не по часам платит!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Да, чего надо? Не видишь, я занята? Совет Теней мне не по часам платит!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9498,'А я что, по-твоему, делаю? Чиню тут все – и никто мне не помогает, кстати, – чтобы мы могли тут поселиться!$B$BОбосновавшись в лесу, нам легче будет отслеживать, что делают друиды Шаттрата, Аллерийской крепости, Форта Камнеломов и Кенария. Из Аукиндона следить за ними несподручно.$B$BПостой-ка, а я тебя знаю?','А я что, по-твоему, делаю? Чиню тут все – и никто мне не помогает, кстати, – чтобы мы могли тут поселиться!$B$BОбосновавшись в лесу, нам легче будет отслеживать, что делают друиды Шаттрата, Аллерийской крепости, Форта Камнеломов и Кенария. Из Аукиндона следить за ними несподручно.$B$BПостой-ка, а я тебя знаю?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','А я что, по-твоему, делаю? Чиню тут все – и никто мне не помогает, кстати, – чтобы мы могли тут поселиться!$B$BОбосновавшись в лесу, нам легче будет отслеживать, что делают друиды Шаттрата, Аллерийской крепости, Форта Камнеломов и Кенария. Из Аукиндона следить за ними несподручно.$B$BПостой-ка, а я тебя знаю?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','А я что, по-твоему, делаю? Чиню тут все – и никто мне не помогает, кстати, – чтобы мы могли тут поселиться!$B$BОбосновавшись в лесу, нам легче будет отслеживать, что делают друиды Шаттрата, Аллерийской крепости, Форта Камнеломов и Кенария. Из Аукиндона следить за ними несподручно.$B$BПостой-ка, а я тебя знаю?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9502,'Да? Архиморд… Архимонд побери! Теперь придется начинать все сначала!','Да? Архиморд… Архимонд побери! Теперь придется начинать все сначала!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да? Архиморд… Архимонд побери! Теперь придется начинать все сначала!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Да? Архиморд… Архимонд побери! Теперь придется начинать все сначала!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9505,'И что же, по-твоему, я могу для тебя сделать? Ты не видишь, что я занят, что я обсуждаю торговые дела с нашим славным предводителем?$B$BБыстро выкладывай свое дело, или получишь палкой, собака!','И что же, по-твоему, я могу для тебя сделать? Ты не видишь, что я занята, что я обсуждаю торговые дела с нашим славным предводителем?$B$BБыстро выкладывай свое дело, или получишь палкой, собака!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','И что же, по-твоему, я могу для тебя сделать? Ты не видишь, что я занят, что я обсуждаю торговые дела с нашим славным предводителем?$B$BБыстро выкладывай свое дело, или получишь палкой, собака!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','И что же, по-твоему, я могу для тебя сделать? Ты не видишь, что я занята, что я обсуждаю торговые дела с нашим славным предводителем?$B$BБыстро выкладывай свое дело, или получишь палкой, собака!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (9507,'Здравствуй, $gюный:юная:r; |3-6($r).') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Здравствуй, $gюный:юная:r; |3-6($r).',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (9511,'Хотела бы я знать, дорогуша. Он не станет слушать ни тебя, ни меня. Откровенно говоря, поэтому я до сих пор и здесь. Поэтому я не ушла вместе с Матерью Кашур. Он должен воспрянуть духом. Без предводителя нашим людям не пережить зиму.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Хотела бы я знать, дорогуша. Он не станет слушать ни тебя, ни меня. Откровенно говоря, поэтому я до сих пор и здесь. Поэтому я не ушла вместе с Матерью Кашур. Он должен воспрянуть духом. Без предводителя нашим людям не пережить зиму.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9517,'Я во что бы то ни стало выясню, что нужно этим подозрительным типам!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я во что бы то ни стало выясню, что нужно этим подозрительным типам!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (9520,'Надо узнать, что эти мрачные личности делают в деревне Грангол\'вар!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Надо узнать, что эти мрачные личности делают в деревне Грангол\'вар!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9521,'Мы здесь на службе, $gпарень:девушка;, смотрим, чтобы никто не смог застать нас врасплох.$B$BЭто называется упреждающий тактикой!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы здесь на службе, $gпарень:девушка;, смотрим, чтобы никто не смог застать нас врасплох.$B$BЭто называется упреждающий тактикой!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (9522,'Должно быть, я где-то ошиблась, раз меня назначили сюда.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Должно быть, я где-то ошиблась, раз меня назначили сюда.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text1_0_loc8`,`text1_1_loc8`,`text2_0_loc8`,`text2_1_loc8`,`text4_0_loc8`,`text4_1_loc8`,`text5_0_loc8`,`text5_1_loc8`) VALUES (9523,'Они никогда с нами за это не расплатятся. Но, безусловно, лучше эта разрушенная деревня, чем бесцельные скитания по Аукиндону.','Они никогда с нами за это не расплатятся. Но, безусловно, лучше эта разрушенная деревня, чем бесцельные скитания по Аукиндону.','Я присоединился к ним потому, что они пообещали оплатить мне путь в академию. Дядя говорит, что в следующий раз я туда иду!','Я присоединилась к ним потому, что они пообещали оплатить мне путь в академию. Дядя говорит, что в следующий раз я туда иду!','Если интересуетесь, чуть попозже мы собирались в Шаттрат, выпить.','Если интересуетесь, чуть попозже мы собирались в Шаттрат, выпить.','Не желаешь присоединиться к лиге игроков в кожаный мяч? Мы играем, как правило, с понедельника по среду. Со следующего цикла можешь к нам присоединиться. Мы тут собираемся жребий бросать.','Не желаешь присоединиться к лиге игроков в кожаный мяч? Мы играем, как правило, с понедельника по среду. Со следующего цикла можешь к нам присоединиться. Мы тут собираемся жребий бросать.') ON DUPLICATE KEY UPDATE `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Они никогда с нами за это не расплатятся. Но, безусловно, лучше эта разрушенная деревня, чем бесцельные скитания по Аукиндону.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Они никогда с нами за это не расплатятся. Но, безусловно, лучше эта разрушенная деревня, чем бесцельные скитания по Аукиндону.',`text1_1_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Я присоединился к ним потому, что они пообещали оплатить мне путь в академию. Дядя говорит, что в следующий раз я туда иду!',`text2_0_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Я присоединилась к ним потому, что они пообещали оплатить мне путь в академию. Дядя говорит, что в следующий раз я туда иду!',`text2_1_loc8`), `text4_0_loc8`=IF(`text4_0_loc8` IS NULL OR `text4_0_loc8`='','Если интересуетесь, чуть попозже мы собирались в Шаттрат, выпить.',`text4_0_loc8`), `text4_1_loc8`=IF(`text4_1_loc8` IS NULL OR `text4_1_loc8`='','Если интересуетесь, чуть попозже мы собирались в Шаттрат, выпить.',`text4_1_loc8`), `text5_0_loc8`=IF(`text5_0_loc8` IS NULL OR `text5_0_loc8`='','Не желаешь присоединиться к лиге игроков в кожаный мяч? Мы играем, как правило, с понедельника по среду. Со следующего цикла можешь к нам присоединиться. Мы тут собираемся жребий бросать.',`text5_0_loc8`), `text5_1_loc8`=IF(`text5_1_loc8` IS NULL OR `text5_1_loc8`='','Не желаешь присоединиться к лиге игроков в кожаный мяч? Мы играем, как правило, с понедельника по среду. Со следующего цикла можешь к нам присоединиться. Мы тут собираемся жребий бросать.',`text5_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9524,'Кем ты себя $gвозомнил:возомнила;, что так просто входишь сюда и обращаешься ко мне? Я представляю в этой деревне Совет Теней. Прочь с глаз моих!$B$BЕсли попадешься мне еще раз, больше не увидишь уже никого. Ясно?$B$BЧто с тобой сделать – похоронить в лабиринте Аукиндона или отдать в жертву Бормотуну?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Кем ты себя $gвозомнил:возомнила;, что так просто входишь сюда и обращаешься ко мне? Я представляю в этой деревне Совет Теней. Прочь с глаз моих!$B$BЕсли попадешься мне еще раз, больше не увидишь уже никого. Ясно?$B$BЧто с тобой сделать – похоронить в лабиринте Аукиндона или отдать в жертву Бормотуну?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9528,'Хотя накопление богатства больше не является движущей силой нашей жизни, мы понимаем, что вертеться мир заставляют деньги. Наш аукционный дом находится рядом с Троном Наару.','Хотя накопление богатства больше не является движущей силой нашей жизни, мы понимаем, что вертеться мир заставляют деньги. Наш аукционный дом находится рядом с Троном Наару.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Хотя накопление богатства больше не является движущей силой нашей жизни, мы понимаем, что вертеться мир заставляют деньги. Наш аукционный дом находится рядом с Троном Наару.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Хотя накопление богатства больше не является движущей силой нашей жизни, мы понимаем, что вертеться мир заставляют деньги. Наш аукционный дом находится рядом с Троном Наару.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9529,'Ты найдешь наш банк в центральном ядре Экзодара. Иди со Светом!','Ты найдешь наш банк в центральном ядре Экзодара. Иди со Светом!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты найдешь наш банк в центральном ядре Экзодара. Иди со Светом!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты найдешь наш банк в центральном ядре Экзодара. Иди со Светом!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9537,'Клянусь Светом! Какое счастье, когда рядом тот, кто заботится о других! Сейчас такое время, что мы рады любой помощи. Нус может обучить тебя первой помощи. Она сейчас у хрустальной пещеры в Хрустальном зале. Да пребудет с тобой Свет!','Клянусь Светом! Какое счастье, когда рядом тот, кто заботится о других! Сейчас такое время, что мы рады любой помощи. Нус может обучить тебя первой помощи. Она сейчас у хрустальной пещеры в Хрустальном зале. Да пребудет с тобой Свет!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Клянусь Светом! Какое счастье, когда рядом тот, кто заботится о других! Сейчас такое время, что мы рады любой помощи. Нус может обучить тебя первой помощи. Она сейчас у хрустальной пещеры в Хрустальном зале. Да пребудет с тобой Свет!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Клянусь Светом! Какое счастье, когда рядом тот, кто заботится о других! Сейчас такое время, что мы рады любой помощи. Нус может обучить тебя первой помощи. Она сейчас у хрустальной пещеры в Хрустальном зале. Да пребудет с тобой Свет!',`text0_1_loc8`);
