INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9554,'Наших наставников жрецов можно найти в покоях Ордена Света, на входе в Трон Наару. Да пребудет с тобой Свет!','Наших наставников жрецов можно найти в покоях Ордена Света, на входе в Трон Наару. Да пребудет с тобой Свет!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Наших наставников жрецов можно найти в покоях Ордена Света, на входе в Трон Наару. Да пребудет с тобой Свет!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Наших наставников жрецов можно найти в покоях Ордена Света, на входе в Трон Наару. Да пребудет с тобой Свет!',`text0_1_loc8`);
