INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9555,'Какого учителя профессий ты ищешь?','Какого учителя профессий ты ищешь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Какого учителя профессий ты ищешь?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Какого учителя профессий ты ищешь?',`text0_1_loc8`);
