INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9556,'Ты найдешь несколько наставников шаманов в Хрустальном Зале. Возможно, тебе следует нанести визит предсказателю Нобундо и оказать милость этому Сломленному. Да пребудет с тобой Свет!','Ты найдешь несколько наставников шаманов в Хрустальном Зале. Возможно, тебе следует нанести визит предсказателю Нобундо и оказать милость этому Сломленному. Да пребудет с тобой Свет!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты найдешь несколько наставников шаманов в Хрустальном Зале. Возможно, тебе следует нанести визит предсказателю Нобундо и оказать милость этому Сломленному. Да пребудет с тобой Свет!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты найдешь несколько наставников шаманов в Хрустальном Зале. Возможно, тебе следует нанести визит предсказателю Нобундо и оказать милость этому Сломленному. Да пребудет с тобой Свет!',`text0_1_loc8`);
