INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (9558,'Нашего смотрителя стойл, Артаида, можно найти снаружи Центра помощи. Он поселился на верхнем уровне центрального ядра, неподалеку от главного входа в Экзодар.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Нашего смотрителя стойл, Артаида, можно найти снаружи Центра помощи. Он поселился на верхнем уровне центрального ядра, неподалеку от главного входа в Экзодар.',`text0_1_loc8`);
