INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (9563,'Добро пожаловать в Королевский Валютный банк, $gсэр:мадам;. Чем я могу вам помочь?','Добро пожаловать в Королевский Валютный банк, $gсэр:мадам;. Чем я могу вам помочь?','Здравствуйте. Чем Королевский Валютный банк может быть вам полезен?','Здравствуйте. Чем Королевский Валютный банк может быть вам полезен?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать в Королевский Валютный банк, $gсэр:мадам;. Чем я могу вам помочь?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Добро пожаловать в Королевский Валютный банк, $gсэр:мадам;. Чем я могу вам помочь?',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Здравствуйте. Чем Королевский Валютный банк может быть вам полезен?',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Здравствуйте. Чем Королевский Валютный банк может быть вам полезен?',`text1_1_loc8`);
