INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9566,'Слушаю тебя, $gгорожанин:горожанка;. О каком важном деле ты желаешь со мной говорить?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Слушаю тебя, $gгорожанин:горожанка;. О каком важном деле ты желаешь со мной говорить?',`text0_0_loc8`);
