INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (9568,'Привет! А не поможешь мне отсюда выбраться?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Привет! А не поможешь мне отсюда выбраться?',`text0_1_loc8`);
