INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9574,'Да? Что такое?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да? Что такое?',`text0_0_loc8`);
