INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9575,'Не думаю, что ты $gпринес:принесла; новости о рудниках, верно?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не думаю, что ты $gпринес:принесла; новости о рудниках, верно?',`text0_0_loc8`);
