INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (9577,'Не на что здесь смотреть. Проходи.','Не на что здесь смотреть. Проходи.','Это вас не касается. Идите своей дорогой.','Это вас не касается. Идите своей дорогой.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не на что здесь смотреть. Проходи.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Не на что здесь смотреть. Проходи.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Это вас не касается. Идите своей дорогой.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Это вас не касается. Идите своей дорогой.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9578,'Спасибо, друзья, я обязан вам свободой. Где Тарета? Я надеялся увидеть ее в последний раз и отблагодарить, прежде чем уйду в горы.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Спасибо, друзья, я обязан вам свободой. Где Тарета? Я надеялся увидеть ее в последний раз и отблагодарить, прежде чем уйду в горы.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9579,'Что ты имеешь в виду? Тарета в опасности?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что ты имеешь в виду? Тарета в опасности?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9580,'Я этого не сделаю. Я не могу оставить Тарету в опасности и бежать в горы. Я не трус. А где она?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я этого не сделаю. Я не могу оставить Тарету в опасности и бежать в горы. Я не трус. А где она?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9583,'Не удивляйся мне так, |3-6($r). Приход дренеев и их союз с моим народом предсказал Курц Прорицатель.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не удивляйся мне так, |3-6($r). Приход дренеев и их союз с моим народом предсказал Курц Прорицатель.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9587,'Пожалуйста, не говорите мне ничего. Я не хочу больше ввязываться из-за них в неприятности.','Пожалуйста, не говорите мне ничего. Я не хочу больше ввязываться из-за них в неприятности.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Пожалуйста, не говорите мне ничего. Я не хочу больше ввязываться из-за них в неприятности.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Пожалуйста, не говорите мне ничего. Я не хочу больше ввязываться из-за них в неприятности.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (9591,'За то время, что мы здесь, слишком многие из наших друзей умерли.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','За то время, что мы здесь, слишком многие из наших друзей умерли.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (9595,'Если не собираешься помогать, уходи.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Если не собираешься помогать, уходи.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9596,'С твоей помощью мы, возможно, победим!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','С твоей помощью мы, возможно, победим!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9597,'Мельница Таррен прямо за этими деревьями. Суматоха в Дарнхольде поможет нам выиграть немного времени, до того как здесь все заполонят солдаты людей. Давай заглянем в ближайший амбар, а потом сразу пойдем в город.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мельница Таррен прямо за этими деревьями. Суматоха в Дарнхольде поможет нам выиграть немного времени, до того как здесь все заполонят солдаты людей. Давай заглянем в ближайший амбар, а потом сразу пойдем в город.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9598,'Ты можешь расплачиваться со мной жетонами Халаа.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты можешь расплачиваться со мной жетонами Халаа.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9599,'Могу поучить тебя снимать шкуры. Интересуешься?','Могу поучить тебя снимать шкуры. Интересуешься?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Могу поучить тебя снимать шкуры. Интересуешься?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Могу поучить тебя снимать шкуры. Интересуешься?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9603,'Таверна "Приют скитальца" находится между Путем Старейшин и базаром. Ты можешь добраться до нее как тебе удобно – так или так.','Таверна "Приют скитальца" находится между Путем Старейшин и базаром. Ты можешь добраться до нее как тебе удобно – так или так.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Таверна "Приют скитальца" находится между Путем Старейшин и базаром. Ты можешь добраться до нее как тебе удобно – так или так.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Таверна "Приют скитальца" находится между Путем Старейшин и базаром. Ты можешь добраться до нее как тебе удобно – так или так.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (9610,'Спасибо, что вы помогли Траллу бежать, друзья. Теперь я надеюсь, что вы сможете помочь и мне. Я проснулась этим утром и обнаружила, что заключена в эту магическую тюрьму. Странный волшебник сказал мне, что я останусь здесь на некоторое время.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Спасибо, что вы помогли Траллу бежать, друзья. Теперь я надеюсь, что вы сможете помочь и мне. Я проснулась этим утром и обнаружила, что заключена в эту магическую тюрьму. Странный волшебник сказал мне, что я останусь здесь на некоторое время.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (9613,'Да, друзья. Этот мужчина не был волшебником из Даларана. Его одежды выглядели несколько непривычно и его акцент был незнаком. Все, что он мог пробормотать, это – время то, время се. Найдите этого волшебника и убедите его освободить меня.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Да, друзья. Этот мужчина не был волшебником из Даларана. Его одежды выглядели несколько непривычно и его акцент был незнаком. Все, что он мог пробормотать, это – время то, время се. Найдите этого волшебника и убедите его освободить меня.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9614,'Я рад, что Тарета жива. Теперь нам надо узнать, как освободить ее от магических уз.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я рад, что Тарета жива. Теперь нам надо узнать, как освободить ее от магических уз.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (9615,'Как представитель Нижнего Города, я хочу указать на то, что Аукиндон необходимо избавить от Совета Теней, если мы хотим быть уверены в своем будущем и исключить всякую возможность возникновения страшных катастроф, вроде Костяных пустошей!$B$BВсем нашим народам и так пришлось слишком многое пережить. Я здесь, чтобы убедиться, что страданиям будет положен конец!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Как представитель Нижнего Города, я хочу указать на то, что Аукиндон необходимо избавить от Совета Теней, если мы хотим быть уверены в своем будущем и исключить всякую возможность возникновения страшных катастроф, вроде Костяных пустошей!$B$BВсем нашим народам и так пришлось слишком многое пережить. Я здесь, чтобы убедиться, что страданиям будет положен конец!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9617,'Присаживайся, $gбрат:сестра;. Разрушители Зангартопи могут унести множество $gмужчин:женщин;.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Присаживайся, $gбрат:сестра;. Разрушители Зангартопи могут унести множество $gмужчин:женщин;.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9618,'Ты коль отдохнуть хочешь – спрашивай-то!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты коль отдохнуть хочешь – спрашивай-то!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (9620,'Добро пожаловать в Гарадар, $gнезнакомец:незнакомка;. Ищешь, где бы отдохнуть?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Добро пожаловать в Гарадар, $gнезнакомец:незнакомка;. Ищешь, где бы отдохнуть?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9621,'А... верно, еще один шаман ищет просветления? Ты не можешь истолковать голос духов? Хочешь, я помогу тебе увидеть грядущее?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','А... верно, еще один шаман ищет просветления? Ты не можешь истолковать голос духов? Хочешь, я помогу тебе увидеть грядущее?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9622,'Я Скальтеш, проводник шаманов, ищущих здесь просветления… но даже тем, кто следует иным путем, можно кое-что показать. Ты желаешь это увидеть?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я Скальтеш, проводник шаманов, ищущих здесь просветления… но даже тем, кто следует иным путем, можно кое-что показать. Ты желаешь это увидеть?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9623,'Испей из этого сосуда, и туман ненадолго рассеется. Ступай, и да хранят тебя духи.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Испей из этого сосуда, и туман ненадолго рассеется. Ступай, и да хранят тебя духи.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9624,'Силанну, одну из лучших кулинаров города, можно найти в "Отдыхе путника", наверху. Там же ты можешь купить у ее помощников принадлежности для готовки.','Силанну, одну из лучших кулинаров города, можно найти в "Отдыхе путника", наверху. Там же ты можешь купить у ее помощников принадлежности для готовки.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Силанну, одну из лучших кулинаров города, можно найти в "Отдыхе путника", наверху. Там же ты можешь купить у ее помощников принадлежности для готовки.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Силанну, одну из лучших кулинаров города, можно найти в "Отдыхе путника", наверху. Там же ты можешь купить у ее помощников принадлежности для готовки.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9631,'Мне не до болтовни, |3-6($r). Или ты хочешь мне помочь с этой шахтной проблемой?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мне не до болтовни, |3-6($r). Или ты хочешь мне помочь с этой шахтной проблемой?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9632,'Уж как я тебе благодарен, за помощь-то с шахтами. Теперь бы шахтеров убедить, чтоб за работу взялись.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Уж как я тебе благодарен, за помощь-то с шахтами. Теперь бы шахтеров убедить, чтоб за работу взялись.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9636,'Вот он, наш шанс! Выпусти меня из клетки!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вот он, наш шанс! Выпусти меня из клетки!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9638,'Сетекки считают себя самыми верными последователями властелина всех араккоа. Не спрашивай о нем, |3-6($r), так как его тайны предназначены лишь для народа с перьями.$B$BСетекки интерпретировали разрушение Аукиндона как прибытие властелина на эту планету. Они направились к руинам, взяв с собой реликвии нашего величайшего героя, Терокка.$B$BОни все еще ищут властелина в развалинах храма, но я здесь, чтобы разоблачить их ложь. Я больше не отношусь к ним!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Сетекки считают себя самыми верными последователями властелина всех араккоа. Не спрашивай о нем, |3-6($r), так как его тайны предназначены лишь для народа с перьями.$B$BСетекки интерпретировали разрушение Аукиндона как прибытие властелина на эту планету. Они направились к руинам, взяв с собой реликвии нашего величайшего героя, Терокка.$B$BОни все еще ищут властелина в развалинах храма, но я здесь, чтобы разоблачить их ложь. Я больше не отношусь к ним!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9639,'Когда я последний раз был в залах, король воронов Айкисс носил перо Терокка как знак своей власти.$B$BМой брат, Темнопряд Сит, надевал маску Терокка во время ритуалов.$B$BЧто касается "Сказания о Терокке", то никто не знает, где оно сейчас, но обычно его хранят в огромном чертоге, в кольце рун.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Когда я последний раз был в залах, король воронов Айкисс носил перо Терокка как знак своей власти.$B$BМой брат, Темнопряд Сит, надевал маску Терокка во время ритуалов.$B$BЧто касается "Сказания о Терокке", то никто не знает, где оно сейчас, но обычно его хранят в огромном чертоге, в кольце рун.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9640,'Король воронов Айкисс – один из лидеров Сетекков, как и мой брат, Темнопряд Сит.$B$BЭто они возглавили исход Сетекков из Скеттиса в руины Аукиндона. Вначале Айкисс был харизматичным лидером, но теперь он впал в безумие.$B$BОн открыто провозглашает, что Терокк возродился в нем! Он действительно ждет, что араккоа начнут поклонятся ему как своему повелителю. Представляешь, какая самонадеянность?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Король воронов Айкисс – один из лидеров Сетекков, как и мой брат, Темнопряд Сит.$B$BЭто они возглавили исход Сетекков из Скеттиса в руины Аукиндона. Вначале Айкисс был харизматичным лидером, но теперь он впал в безумие.$B$BОн открыто провозглашает, что Терокк возродился в нем! Он действительно ждет, что араккоа начнут поклонятся ему как своему повелителю. Представляешь, какая самонадеянность?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9641,'Он – величайший герой араккоа всех времен.$B$BГоворят, что давным-давно он построил город Скеттис своими собственными когтями. Он был нашим защитником и покровителем, но покинул нас в тот день, когда мы перестали почитать Рукмару.$B$BМы стали поклоняться новому хозяину, который посулил нам невероятную силу и положение в космосе.$B$BНекоторые говорят, что Терокк и Рукмар едины, и он покинул нас, когда мы отвернулись от него.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Он – величайший герой араккоа всех времен.$B$BГоворят, что давным-давно он построил город Скеттис своими собственными когтями. Он был нашим защитником и покровителем, но покинул нас в тот день, когда мы перестали почитать Рукмару.$B$BМы стали поклоняться новому хозяину, который посулил нам невероятную силу и положение в космосе.$B$BНекоторые говорят, что Терокк и Рукмар едины, и он покинул нас, когда мы отвернулись от него.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (9643,'Ну, как тебе тут, |3-6($c)?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ну, как тебе тут, |3-6($c)?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9644,'Если у тебя есть деньги, у меня есть нужный товар.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если у тебя есть деньги, у меня есть нужный товар.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (9645,'Осмотритесь и скажите, заинтересовало ли вас что-нибудь.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Осмотритесь и скажите, заинтересовало ли вас что-нибудь.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (9646,'Не торопись, внимательно изучи оружие. Его, как и доспехи, я, между прочим, могу чинить.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Не торопись, внимательно изучи оружие. Его, как и доспехи, я, между прочим, могу чинить.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9648,'Чтобы вернуть Награнду покой, потребуется острый клинок и крепкий доспех. Хотите, я починю вашу экипировку, чтобы вы могли вершить справедливость?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Чтобы вернуть Награнду покой, потребуется острый клинок и крепкий доспех. Хотите, я починю вашу экипировку, чтобы вы могли вершить справедливость?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9650,'Я продаю товары для ремесленников. Лишь самое необходимое, ничего особенного.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я продаю товары для ремесленников. Лишь самое необходимое, ничего особенного.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (9652,'Ты $gзаблудился:заблудилась;? Большая часть торговцев обнаруживается у центра города.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты $gзаблудился:заблудилась;? Большая часть торговцев обнаруживается у центра города.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (9653,'Торгую всем нужным и ненужным, но чаще все-таки нужным.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Торгую всем нужным и ненужным, но чаще все-таки нужным.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9654,'Я с ума схожу из-за этого. Никак не достану из гнезда эти проклятые яйца!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я с ума схожу из-за этого. Никак не достану из гнезда эти проклятые яйца!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (9657,'Досадно то, что среди полчищ наших врагов на Полуострове Адского Пламени присутствуют и орки из Цитадели Адского Пламени.$B$BНо… Кто лучше орков может лучше сражаться с Ордой?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Досадно то, что среди полчищ наших врагов на Полуострове Адского Пламени присутствуют и орки из Цитадели Адского Пламени.$B$BНо… Кто лучше орков может лучше сражаться с Ордой?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9688,'Ступай в Палаты Магии Стальгорна и поговори с ночными эльфами-друидами. Они могут перенести тебя в Лунную поляну, прямо на празднование Лунного фестиваля.','Ступай в Палаты Магии Стальгорна и поговори с ночными эльфами-друидами. Они могут перенести тебя в Лунную поляну, прямо на празднование Лунного фестиваля.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ступай в Палаты Магии Стальгорна и поговори с ночными эльфами-друидами. Они могут перенести тебя в Лунную поляну, прямо на празднование Лунного фестиваля.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ступай в Палаты Магии Стальгорна и поговори с ночными эльфами-друидами. Они могут перенести тебя в Лунную поляну, прямо на празднование Лунного фестиваля.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9692,'Лунный фестиваль на Лунной поляне в самом разгаре. Делегацию друидов можно найти в тронном зале у входа в Подгород, оттуда они всех и телепортируют.','Лунный фестиваль на Лунной поляне в самом разгаре. Делегацию друидов можно найти в тронном зале у входа в Подгород, оттуда они всех и телепортируют.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Лунный фестиваль на Лунной поляне в самом разгаре. Делегацию друидов можно найти в тронном зале у входа в Подгород, оттуда они всех и телепортируют.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Лунный фестиваль на Лунной поляне в самом разгаре. Делегацию друидов можно найти в тронном зале у входа в Подгород, оттуда они всех и телепортируют.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9694,'Я был во множестве миров, но нигде не видел такого веселого праздника, как этот Зимний Покров. Советую тебе побывать в Стальгорне, столице дворфов, и увидеть все своими глазами.','Я была во множестве миров, но нигде не видала такого веселого праздника, как этот Зимний Покров. Советую тебе побывать в Стальгорне, столице дворфов, и увидеть все своими глазами.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я был во множестве миров, но нигде не видел такого веселого праздника, как этот Зимний Покров. Советую тебе побывать в Стальгорне, столице дворфов, и увидеть все своими глазами.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я была во множестве миров, но нигде не видала такого веселого праздника, как этот Зимний Покров. Советую тебе побывать в Стальгорне, столице дворфов, и увидеть все своими глазами.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9696,'Друиды Азерота отмечают великий праздник на Лунной поляне. Если ты встретишь гуляк Лунного фестиваля в городе, они помогут тебе попасть туда.','Друиды Азерота отмечают великий праздник на Лунной поляне. Если ты встретишь гуляк Лунного фестиваля в городе, они помогут тебе попасть туда.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Друиды Азерота отмечают великий праздник на Лунной поляне. Если ты встретишь гуляк Лунного фестиваля в городе, они помогут тебе попасть туда.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Друиды Азерота отмечают великий праздник на Лунной поляне. Если ты встретишь гуляк Лунного фестиваля в городе, они помогут тебе попасть туда.',`text0_1_loc8`);
