INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9698,'Если вы хотите как следует отпраздновать Зимний Покров, отправляйтесь в Оргриммар.','Если вы хотите как следует отпраздновать Зимний Покров, отправляйтесь в Оргриммар.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если вы хотите как следует отпраздновать Зимний Покров, отправляйтесь в Оргриммар.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Если вы хотите как следует отпраздновать Зимний Покров, отправляйтесь в Оргриммар.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9700,'Если ты встретишь гуляк Лунного фестиваля в Луносвете, они помогут тебе попасть на Лунный фестиваль.','Если ты встретишь гуляк Лунного фестиваля в Луносвете, они помогут тебе попасть на Лунный фестиваль.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если ты встретишь гуляк Лунного фестиваля в Луносвете, они помогут тебе попасть на Лунный фестиваль.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Если ты встретишь гуляк Лунного фестиваля в Луносвете, они помогут тебе попасть на Лунный фестиваль.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9704,'В Лунной поляне проходит самое пышное празднование Лунного фестиваля. Если ты слишком далеко оттуда, друиды доставят тебя на праздник из Аллеи Мудрости.','В Лунной поляне проходит самое пышное празднование Лунного фестиваля. Если ты слишком далеко оттуда, друиды доставят тебя на праздник из Аллеи Мудрости.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','В Лунной поляне проходит самое пышное празднование Лунного фестиваля. Если ты слишком далеко оттуда, друиды доставят тебя на праздник из Аллеи Мудрости.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','В Лунной поляне проходит самое пышное празднование Лунного фестиваля. Если ты слишком далеко оттуда, друиды доставят тебя на праздник из Аллеи Мудрости.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9706,'Празднование Зимнего Покрова отлично греет всех зимой, а главный источник тепла – Оргриммар…','Празднование Зимнего Покрова отлично греет всех зимой, а главный источник тепла – Оргриммар…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Празднование Зимнего Покрова отлично греет всех зимой, а главный источник тепла – Оргриммар…',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Празднование Зимнего Покрова отлично греет всех зимой, а главный источник тепла – Оргриммар…',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9710,'Мы все еще продолжаем отмечать, но празднование Зимнего Покрова уже почти закончилось. Вот в Оргриммаре по-настоящему отмечают.','Мы все еще продолжаем отмечать, но празднование Зимнего Покрова уже почти закончилось. Вот в Оргриммаре по-настоящему отмечают.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы все еще продолжаем отмечать, но празднование Зимнего Покрова уже почти закончилось. Вот в Оргриммаре по-настоящему отмечают.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мы все еще продолжаем отмечать, но празднование Зимнего Покрова уже почти закончилось. Вот в Оргриммаре по-настоящему отмечают.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9712,'У многих Отрекшихся в сердцах царит луна, как некогда сияло солнце. Как бы то ни было, если ты решишь присоединиться к празднованию, отправляйся на Лунную поляну в Калимдор. Ты найдешь друидов в тронном зале над Подгородом, они переправят тебя туда.','У многих Отрекшихся в сердцах царит луна, как некогда сияло солнце. Как бы то ни было, если ты решишь присоединиться к празднованию, отправляйся на Лунную поляну в Калимдор. Ты найдешь друидов в тронном зале над Подгородом, они переправят тебя туда.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','У многих Отрекшихся в сердцах царит луна, как некогда сияло солнце. Как бы то ни было, если ты решишь присоединиться к празднованию, отправляйся на Лунную поляну в Калимдор. Ты найдешь друидов в тронном зале над Подгородом, они переправят тебя туда.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','У многих Отрекшихся в сердцах царит луна, как некогда сияло солнце. Как бы то ни было, если ты решишь присоединиться к празднованию, отправляйся на Лунную поляну в Калимдор. Ты найдешь друидов в тронном зале над Подгородом, они переправят тебя туда.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9713,'Эй, поди-ка сюда! Взгляни, разве это не превосходные клинки? Разумеется, ты хочешь купить их у меня! Оружия, сделанного с таким умением и заботой, не найти больше нигде, |3-6($r)!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эй, поди-ка сюда! Взгляни, разве это не превосходные клинки? Разумеется, ты хочешь купить их у меня! Оружия, сделанного с таким умением и заботой, не найти больше нигде, |3-6($r)!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9714,'На что ты пялишься, |3-6($r)?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','На что ты пялишься, |3-6($r)?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9715,'Ступай в Палаты Магии Стальгорна и поговори с ночными эльфами-друидами. Они могут перенести тебя в Лунную поляну, прямо на празднование Лунного фестиваля.','Ступай в Палаты Магии Стальгорна и поговори с ночными эльфами-друидами. Они могут перенести тебя в Лунную поляну, прямо на празднование Лунного фестиваля.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ступай в Палаты Магии Стальгорна и поговори с ночными эльфами-друидами. Они могут перенести тебя в Лунную поляну, прямо на празднование Лунного фестиваля.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ступай в Палаты Магии Стальгорна и поговори с ночными эльфами-друидами. Они могут перенести тебя в Лунную поляну, прямо на празднование Лунного фестиваля.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9716,'Самое яркое празднество Лунного фестиваля проходит на Лунной поляне. Но не ходи пешком, друиды из Аллеи Мудрости могут перенести тебя туда.','Самое яркое празднество Лунного фестиваля проходит на Лунной поляне. Но не ходи пешком, друиды из Аллеи Мудрости могут перенести тебя туда.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Самое яркое празднество Лунного фестиваля проходит на Лунной поляне. Но не ходи пешком, друиды из Аллеи Мудрости могут перенести тебя туда.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Самое яркое празднество Лунного фестиваля проходит на Лунной поляне. Но не ходи пешком, друиды из Аллеи Мудрости могут перенести тебя туда.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9717,'Дедушку Зиму можно найти перед банком Стальгорна. Подарки выдаются у дерева, под которым он стоит.','Дедушку Зиму можно найти перед банком Стальгорна. Подарки выдаются у дерева, под которым он стоит.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Дедушку Зиму можно найти перед банком Стальгорна. Подарки выдаются у дерева, под которым он стоит.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Дедушку Зиму можно найти перед банком Стальгорна. Подарки выдаются у дерева, под которым он стоит.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (9718,'Ты увидишь Дедушку Зиму в центре Аллеи Силы. Просто поищи дерево.','Ты увидишь Дедушку Зиму в центре Аллеи Силы. Просто поищи дерево.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты увидишь Дедушку Зиму в центре Аллеи Силы. Просто поищи дерево.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты увидишь Дедушку Зиму в центре Аллеи Силы. Просто поищи дерево.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (9729,'Я нигде не видал такой отличной охоты, как на диких равнинах Награнда!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я нигде не видал такой отличной охоты, как на диких равнинах Награнда!',`text0_0_loc8`);
