INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10186,'Охотников обучает Ханновия, Странница, она живет на северо-востоке, в здании на площади Соколиных крыльев.','Охотников обучает Ханновия, Странница, она живет на северо-востоке, в здании на площади Соколиных крыльев.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Охотников обучает Ханновия, Странница, она живет на северо-востоке, в здании на площади Соколиных крыльев.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Охотников обучает Ханновия, Странница, она живет на северо-востоке, в здании на площади Соколиных крыльев.',`text0_1_loc8`);
