INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10187,'Гарридель обучает тайным искусствам на площади Соколиных крыльев. Вы можете найти ее в таверне, на втором этаже.','Гарридель обучает тайным искусствам на площади Соколиных крыльев. Вы можете найти ее в таверне, на втором этаже.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Гарридель обучает тайным искусствам на площади Соколиных крыльев. Вы можете найти ее в таверне, на втором этаже.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Гарридель обучает тайным искусствам на площади Соколиных крыльев. Вы можете найти ее в таверне, на втором этаже.',`text0_1_loc8`);
