INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10189,'Рыцарь Крови Ноэллена ждет новобранцев в северо-восточном здании площади.','Рыцарь Крови Ноэллена ждет новобранцев в северо-восточном здании площади.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Рыцарь Крови Ноэллена ждет новобранцев в северо-восточном здании площади.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Рыцарь Крови Ноэллена ждет новобранцев в северо-восточном здании площади.',`text0_1_loc8`);
