INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10190,'Если тебе нужны знания жреца, отправляйся к Понарису. Он работает с другими на втором этаже таверны Деланиэль.','Если тебе нужны знания жреца, отправляйся к Понарису. Он работает с другими на втором этаже таверны Деланиэль.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если тебе нужны знания жреца, отправляйся к Понарису. Он работает с другими на втором этаже таверны Деланиэль.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Если тебе нужны знания жреца, отправляйся к Понарису. Он работает с другими на втором этаже таверны Деланиэль.',`text0_1_loc8`);
