INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10191,'На северо-востоке площади Соколиных Крыльев есть здание, и в нем ты, скорее всего, найдешь Таннарию, женщину, что очень хорошо умеет исчезать из виду.','На северо-востоке площади Соколиных Крыльев есть здание, и в нем ты, скорее всего, найдешь Таннарию, женщину, что очень хорошо умеет исчезать из виду.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','На северо-востоке площади Соколиных Крыльев есть здание, и в нем ты, скорее всего, найдешь Таннарию, женщину, что очень хорошо умеет исчезать из виду.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','На северо-востоке площади Соколиных Крыльев есть здание, и в нем ты, скорее всего, найдешь Таннарию, женщину, что очень хорошо умеет исчезать из виду.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10192,'Целон – наш специалист по призыву демонов. Он живет на постоялом дворе на площади Соколиных Крыльев – без сомнения, на втором этаже.','Целон – наш специалист по призыву демонов. Он живет на постоялом дворе на площади Соколиных Крыльев – без сомнения, на втором этаже.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Целон – наш специалист по призыву демонов. Он живет на постоялом дворе на площади Соколиных Крыльев – без сомнения, на втором этаже.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Целон – наш специалист по призыву демонов. Он живет на постоялом дворе на площади Соколиных Крыльев – без сомнения, на втором этаже.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10193,'Я знаю местного алхимика. Мне кажется, его зовут Шэйнатрен. Когда я его видел последний раз, он направлялся на виллу Салтерила, наверняка, чтобы вступить в очередную смехотворную партию…','Я знаю местного алхимика. Мне кажется, его зовут Шэйнатрен. Когда я его видела в последний раз, он направлялся в Гавань Салтерила – наверняка, чтобы вступить в очередную смехотворную партию…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я знаю местного алхимика. Мне кажется, его зовут Шэйнатрен. Когда я его видел последний раз, он направлялся на виллу Салтерила, наверняка, чтобы вступить в очередную смехотворную партию…',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я знаю местного алхимика. Мне кажется, его зовут Шэйнатрен. Когда я его видела в последний раз, он направлялся в Гавань Салтерила – наверняка, чтобы вступить в очередную смехотворную партию…',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10194,'В лагере Странников, что на востоке Вечной Песни, есть кузнец Аратель. Возможно, она сможет тебе помочь.','В лагере Странников, что на востоке Вечной Песни, есть кузнец Аратель. Возможно, она сможет тебе помочь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','В лагере Странников, что на востоке Вечной Песни, есть кузнец Аратель. Возможно, она сможет тебе помочь.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','В лагере Странников, что на востоке Вечной Песни, есть кузнец Аратель. Возможно, она сможет тебе помочь.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10195,'У Деланиэль работает отличная повариха по имени Кварелестра. Она может многому вас научить. Спросите ее в таверне на площади Соколиных крыльев.','У Деланиэль работает отличная повариха по имени Кварелестра. Она может многому вас научить. Спросите ее в таверне на площади Соколиных крыльев.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','У Деланиэль работает отличная повариха по имени Кварелестра. Она может многому вас научить. Спросите ее в таверне на площади Соколиных крыльев.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','У Деланиэль работает отличная повариха по имени Кварелестра. Она может многому вас научить. Спросите ее в таверне на площади Соколиных крыльев.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10196,'Если вы ищете зачаровывательницу Эреданию, отправляйтесь на вечеринку Салтерила. Ее пригласили туда пару дней назад.','Если вы ищете зачаровывательницу Эреданию, отправляйтесь на вечеринку Салтерила. Ее пригласили туда пару дней назад.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если вы ищете зачаровывательницу Эреданию, отправляйтесь на вечеринку Салтерила. Ее пригласили туда пару дней назад.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Если вы ищете зачаровывательницу Эреданию, отправляйтесь на вечеринку Салтерила. Ее пригласили туда пару дней назад.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10197,'Занимаясь такой опасной и непредсказуемой профессией в наших древних рощах, нельзя быть уверенным, что последствия не окажутся гибельными. Лучше попробуй в Луносвете: стены там крепкие и выдержат взрывы.','Занимаясь такой опасной и непредсказуемой профессией в наших древних рощах, нельзя быть уверенным, что последствия не окажутся гибельными. Лучше попробуй в Луносвете; стены там крепкие и выдержат взрывы.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Занимаясь такой опасной и непредсказуемой профессией в наших древних рощах, нельзя быть уверенным, что последствия не окажутся гибельными. Лучше попробуй в Луносвете: стены там крепкие и выдержат взрывы.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Занимаясь такой опасной и непредсказуемой профессией в наших древних рощах, нельзя быть уверенным, что последствия не окажутся гибельными. Лучше попробуй в Луносвете; стены там крепкие и выдержат взрывы.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10198,'Те, кто предпочитает полагаться на привычные способы исцеления плоти, могу обратиться к Канарии, у нее медицинский пункт на площади Соколиных крыльев.','Те, кто предпочитает полагаться на привычные способы исцеления плоти, могу обратиться к Канарии, у нее медицинский пункт на площади Соколиных крыльев.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Те, кто предпочитает полагаться на привычные способы исцеления плоти, могу обратиться к Канарии, у нее медицинский пункт на площади Соколиных крыльев.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Те, кто предпочитает полагаться на привычные способы исцеления плоти, могу обратиться к Канарии, у нее медицинский пункт на площади Соколиных крыльев.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10199,'У нас в городе есть рыболов. Тебе что, нравится возиться с колючими, мокрыми, скользкими тварями?','У нас в городе есть рыболов. Тебе что, нравится возиться с колючими, мокрыми, скользкими тварями?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','У нас в городе есть рыболов. Тебе что, нравится возиться с колючими, мокрыми, скользкими тварями?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','У нас в городе есть рыболов. Тебе что, нравится возиться с колючими, мокрыми, скользкими тварями?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10200,'Кто лучше справится с составлением букетов для приема, чем ботаник Тиниаррель? Наверняка Салтерил расплачивается с ним вином…','Кто лучше справится с составлением букетов для приема, чем ботаник Тиниаррель? Наверняка Салтерил расплачивается с ним вином…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Кто лучше справится с составлением букетов для приема, чем ботаник Тиниаррель? Наверняка Салтерил расплачивается с ним вином…',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Кто лучше справится с составлением букетов для приема, чем ботаник Тиниаррель? Наверняка Салтерил расплачивается с ним вином…',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10202,'Может, Амир и беспокоится насчет братства Эфириум, но меня сейчас волнует только одна настоящая опасность – Пространствус.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Может, Амир и беспокоится насчет братства Эфириум, но меня сейчас волнует только одна настоящая опасность – Пространствус.',`text0_0_loc8`);
