INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10203,'Нашего ювелира зовут Алейния, ее можно найти на постоялом дворе Деланиэль, это на площади Соколиных Крыльев. Вполне вероятно, что она ищет себе ученика.','Нашего ювелира зовут Алейния, ее можно найти на постоялом дворе Деланиэль, это на площади Соколиных Крыльев. Вполне вероятно, что она ищет себе ученика.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Нашего ювелира зовут Алейния, ее можно найти на постоялом дворе Деланиэль, это на площади Соколиных Крыльев. Вполне вероятно, что она ищет себе ученика.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Нашего ювелира зовут Алейния, ее можно найти на постоялом дворе Деланиэль, это на площади Соколиных Крыльев. Вполне вероятно, что она ищет себе ученика.',`text0_1_loc8`);
