INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10204,'Сатейн находит, что шкуры рысей из Вечной Песни идеально подходят для его творений. Тебе стоит с ним поговорить – он стоит с Матрейном к юго-западу от Магистерских ворот.','Сатейн находит, что шкуры рысей из Вечной Песни идеально подходят для его творений. Тебе стоит с ним поговорить – он стоит с Матрейном к юго-западу от Магистерских ворот.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Сатейн находит, что шкуры рысей из Вечной Песни идеально подходят для его творений. Тебе стоит с ним поговорить – он стоит с Матрейном к юго-западу от Магистерских ворот.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Сатейн находит, что шкуры рысей из Вечной Песни идеально подходят для его творений. Тебе стоит с ним поговорить – он стоит с Матрейном к юго-западу от Магистерских ворот.',`text0_1_loc8`);
