INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10205,'Мастеровых можно найти в Луносвете, там они наверняка находятся близко к пышущим жаром кузням, где и работают.','Мастеровых можно найти в Луносвете, там они наверняка находятся близко к пышущим жаром кузням, где и работают.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мастеровых можно найти в Луносвете, там они наверняка находятся близко к пышущим жаром кузням, где и работают.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мастеровых можно найти в Луносвете, там они наверняка находятся близко к пышущим жаром кузням, где и работают.',`text0_1_loc8`);
