INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10206,'Если вы так желаете научиться варварскому искусству снятия шкур, обратитесь к Матрейн. Он поставляет в Сатейн шкуры, а найти его можно к юго-западу от Магистерских ворот.','Если вы так желаете научиться варварскому искусству снятия шкур, обратитесь к Матрейн. Он поставляет в Сатейн шкуры, а найти его можно к юго-западу от Магистерских ворот.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если вы так желаете научиться варварскому искусству снятия шкур, обратитесь к Матрейн. Он поставляет в Сатейн шкуры, а найти его можно к юго-западу от Магистерских ворот.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Если вы так желаете научиться варварскому искусству снятия шкур, обратитесь к Матрейн. Он поставляет в Сатейн шкуры, а найти его можно к юго-западу от Магистерских ворот.',`text0_1_loc8`);
