INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10207,'На вилле Салтерила недавно поселилась отличная швея. В умении обращаться с ниткой и иголкой ей нет равных!','На вилле Салтерила недавно поселилась отличная швея. В умении обращаться с ниткой и иголкой ей нет равных!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','На вилле Салтерила недавно поселилась отличная швея. В умении обращаться с ниткой и иголкой ей нет равных!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','На вилле Салтерила недавно поселилась отличная швея. В умении обращаться с ниткой и иголкой ей нет равных!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10208,'Чего ты добиваешься? Скажи прямо.','Чего ты добиваешься? Скажи прямо.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Чего ты добиваешься? Скажи прямо.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Чего ты добиваешься? Скажи прямо.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10209,'В другое время и в другом месте меня сочли бы всего лишь подростком. Здесь я бывалый воин, готовый жить и умереть ради славы наару.$B$BДесятеро из нас пошли в Манагорн Ара. Все остальные достались Легиону.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','В другое время и в другом месте меня сочли бы всего лишь подростком. Здесь я бывалый воин, готовый жить и умереть ради славы наару.$B$BДесятеро из нас пошли в Манагорн Ара. Все остальные достались Легиону.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10211,'Тебя послали ко мне Провидцы? Ты совсем не $gпохож:похожа; на $gодного:одну; из них…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тебя послали ко мне Провидцы? Ты совсем не $gпохож:похожа; на $gодного:одну; из них…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (10212,'Говори побыстрее, мне некогда болтать впустую. Отрекшиеся стали силой, с которой приходится считаться, но работы еще много. Город сам собою управляться не будет.$B$BЧего тебе надо?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Говори побыстрее, мне некогда болтать впустую. Отрекшиеся стали силой, с которой приходится считаться, но работы еще много. Город сам собою управляться не будет.$B$BЧего тебе надо?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10215,'Хорошо, |3-6($c). Думаешь, у тебя хватит сил выдержать бой в Боевом Круге Хитрой Шестеренки?','Хорошо, |3-6($c). Думаешь, у тебя хватит сил выдержать бой в Боевом Круге Хитрой Шестеренки?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Хорошо, |3-6($c). Думаешь, у тебя хватит сил выдержать бой в Боевом Круге Хитрой Шестеренки?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Хорошо, |3-6($c). Думаешь, у тебя хватит сил выдержать бой в Боевом Круге Хитрой Шестеренки?',`text0_1_loc8`);
