INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10216,'Ты можешь найти военачальников за столом военных советов в Оружейной.','Ты можешь найти военачальников за столом военных советов в Оружейной.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты можешь найти военачальников за столом военных советов в Оружейной.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты можешь найти военачальников за столом военных советов в Оружейной.',`text0_1_loc8`);
