INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (10217,'Военачальники сейчас собрались на Террасе Воинов.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Военачальники сейчас собрались на Террасе Воинов.',`text0_1_loc8`);
