INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10220,'Отправляйся на Вершину Охотников. Там ты и найдешь военачальников.','Отправляйся на Вершину Охотников. Там ты и найдешь военачальников.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Отправляйся на Вершину Охотников. Там ты и найдешь военачальников.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Отправляйся на Вершину Охотников. Там ты и найдешь военачальников.',`text0_1_loc8`);
