INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10222,'Ты топай в Королевский квартал. Они все там, в круглой такой комнате.','Ты топай в Королевский квартал. Они все там, в круглой такой комнате.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты топай в Королевский квартал. Они все там, в круглой такой комнате.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты топай в Королевский квартал. Они все там, в круглой такой комнате.',`text0_1_loc8`);
