INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10223,'Ты найдешь его в Центре помощи рядом с Троном Наару. Да пребудет с тобой Свет.','Ты найдешь его в Центре помощи рядом с Троном Наару. Да пребудет с тобой Свет.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты найдешь его в Центре помощи рядом с Троном Наару. Да пребудет с тобой Свет.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты найдешь его в Центре помощи рядом с Троном Наару. Да пребудет с тобой Свет.',`text0_1_loc8`);
