INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10224,'Ура, мне дали кексов!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ура, мне дали кексов!',`text0_0_loc8`);
