INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10233,'Добро пожаловать в заповедник "Среднее королевство", $gпутник:странница;. Я хотел бы предупредить вас об осторожности вон с тем гоблином, Шаули. Мне еще не доводилось слышать, чтобы кто-нибудь использовал слово "приятель" в качестве вводного слова.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать в заповедник "Среднее королевство", $gпутник:странница;. Я хотел бы предупредить вас об осторожности вон с тем гоблином, Шаули. Мне еще не доводилось слышать, чтобы кто-нибудь использовал слово "приятель" в качестве вводного слова.',`text0_0_loc8`);
