INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (10236,'Если ты собираешься явиться сюда, постарайся быть $gполезным:полезной;, потому что здешний тенелов себя не утруждает.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Если ты собираешься явиться сюда, постарайся быть $gполезным:полезной;, потому что здешний тенелов себя не утруждает.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (10237,'Битва за Хиджал – одно из самых тщательно охраняемых событий на нашей временной шкале. Случись кому-то изменить ее исход, последствия этого отразятся на всей истории.$B$BКак ближайшая спутница Ноздорму, я гораздо лучше чувствую течение времени, чем другие бронзовые драконы. Недавно до меня донеслось минутное колебание во времени, исходящее от событий, близких к битве за гору Хиджал. Кто-то или что-то пытается повлиять на время, и его надо остановить.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Битва за Хиджал – одно из самых тщательно охраняемых событий на нашей временной шкале. Случись кому-то изменить ее исход, последствия этого отразятся на всей истории.$B$BКак ближайшая спутница Ноздорму, я гораздо лучше чувствую течение времени, чем другие бронзовые драконы. Недавно до меня донеслось минутное колебание во времени, исходящее от событий, близких к битве за гору Хиджал. Кто-то или что-то пытается повлиять на время, и его надо остановить.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10239,'Чего ты добиваешься? Я не могу доверить тебе кого-нибудь из моих элекков, пока ты не докажешь свою преданность и дружеские чувства к нашему народу.','Чего ты добиваешься? Я не могу доверить тебе кого-нибудь из моих элекков, пока ты не докажешь свою преданность и дружеские чувства к нашему народу.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Чего ты добиваешься? Я не могу доверить тебе кого-нибудь из моих элекков, пока ты не докажешь свою преданность и дружеские чувства к нашему народу.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Чего ты добиваешься? Я не могу доверить тебе кого-нибудь из моих элекков, пока ты не докажешь свою преданность и дружеские чувства к нашему народу.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (10245,'Нельзя подвергать опасности нашу работу в Живой роще. От этого зависят жизни всех нас!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Нельзя подвергать опасности нашу работу в Живой роще. От этого зависят жизни всех нас!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10247,'Если мне правильно сказали, то ты уже работаешь на Сильванаар.$b$bПродолжай в том же духе, и, возможно, нам удастся сохранить свой дом.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если мне правильно сказали, то ты уже работаешь на Сильванаар.$b$bПродолжай в том же духе, и, возможно, нам удастся сохранить свой дом.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10249,'Отдохни с дороги, $gскиталец:скиталица;. Будь как дома.','Отдохни с дороги, $gскиталец:скиталица;. Будь как дома.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Отдохни с дороги, $gскиталец:скиталица;. Будь как дома.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Отдохни с дороги, $gскиталец:скиталица;. Будь как дома.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10252,'Не так давно мы вырвали Оплот Громоборцев из-под контроля живущих по соседству огров.$B$BТы $gпришел:пришла; помочь нам обороняться? Я слыхал, Гор\'дрек ищет помощь…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не так давно мы вырвали Оплот Громоборцев из-под контроля живущих по соседству огров.$B$BТы $gпришел:пришла; помочь нам обороняться? Я слыхал, Гор\'дрек ищет помощь…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10253,'И как вам на войне, $n? Просто вспомните, почему мы здесь… это делает бой – и смерть – намного легче.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','И как вам на войне, $n? Просто вспомните, почему мы здесь… это делает бой – и смерть – намного легче.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10254,'В Троне Наару два почтовых ящика – около банка и около аукционного дома.','В Троне Наару два почтовых ящика – около банка и около аукционного дома.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','В Троне Наару два почтовых ящика – около банка и около аукционного дома.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','В Троне Наару два почтовых ящика – около банка и около аукционного дома.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10255,'Лагерь экспедиции– суровое место, но оно очень важно для защиты Оплота Чести. Сюда стекается информация, а схватки наших солдат с Легионом и орками Зет\'Гора неоценимы для альянсовской кампании Адского Пламени.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Лагерь экспедиции– суровое место, но оно очень важно для защиты Оплота Чести. Сюда стекается информация, а схватки наших солдат с Легионом и орками Зет\'Гора неоценимы для альянсовской кампании Адского Пламени.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10256,'Я слышал, что ты уже $gприступил:приступила; к работе.$B$BОтлично. Я уж боялся, что придется тебя "убеждать".') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я слышал, что ты уже $gприступил:приступила; к работе.$B$BОтлично. Я уж боялся, что придется тебя "убеждать".',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10257,'На куске кожи, растянутой между двумя костями, написан призыв вступить в бой с главным защитником города Альянса Сильванаара и Живой рощи на западе.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','На куске кожи, растянутой между двумя костями, написан призыв вступить в бой с главным защитником города Альянса Сильванаара и Живой рощи на западе.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (10258,'Здравствуй, я Азими! Я часто выхожу сюда торговать водой и свежими фруктами. Ты хочешь есть? А, может, пить?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Здравствуй, я Азими! Я часто выхожу сюда торговать водой и свежими фруктами. Ты хочешь есть? А, может, пить?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10259,'Ба! Я что, похож на праздного болтуна?$B$BДа?$B$BДавай быстрее, что там у тебя? Смотри, сколько еще огров нужно убить!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ба! Я что, похож на праздного болтуна?$B$BДа?$B$BДавай быстрее, что там у тебя? Смотри, сколько еще огров нужно убить!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10264,'$R, что заботится о благосостоянии Сильванаара – зрелище отрадное. Мы сделали здесь много, и за весьма короткий срок, но силы, что окружают нас, угрожают самой нашей жизни.$B$BЯ выслушаю то, что ты хочешь сказать. Говори же, |3-6($c).') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','$R, что заботится о благосостоянии Сильванаара – зрелище отрадное. Мы сделали здесь много, и за весьма короткий срок, но силы, что окружают нас, угрожают самой нашей жизни.$B$BЯ выслушаю то, что ты хочешь сказать. Говори же, |3-6($c).',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10269,'Ты $gготов:готова; сражаться с кланом Грозовой Вершины в Альтеракской долине, $n?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты $gготов:готова; сражаться с кланом Грозовой Вершины в Альтеракской долине, $n?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10270,'В качестве представителей Лиги исследователей по распоряжению Альянса Бронвин и я хотим изучить эти горы.$B$BНо, между нами говоря, после длительного пребывания в Силитусе нам просто нужен был отпуск. А это, похоже, достаточно милое местечко.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','В качестве представителей Лиги исследователей по распоряжению Альянса Бронвин и я хотим изучить эти горы.$B$BНо, между нами говоря, после длительного пребывания в Силитусе нам просто нужен был отпуск. А это, похоже, достаточно милое местечко.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (10271,'Возможно, Богрим прав. Наверное, нам следует передохнуть.$B$BНо сейчас мы здесь, и мне не терпится закопаться в грязь и изучить, что сулит эта земля.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Возможно, Богрим прав. Наверное, нам следует передохнуть.$B$BНо сейчас мы здесь, и мне не терпится закопаться в грязь и изучить, что сулит эта земля.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10272,'Рад тебя видеть, $n. Наши союзники-дворфы просят поддержать их в Альтеракской долине. Поможешь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Рад тебя видеть, $n. Наши союзники-дворфы просят поддержать их в Альтеракской долине. Поможешь?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10275,'Сыны Лотара бесконечно сражались. Я удивлен, что мы сохранили нашу экипировку в столь хорошем виде!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Сыны Лотара бесконечно сражались. Я удивлен, что мы сохранили нашу экипировку в столь хорошем виде!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10277,'Тром\'ка, $n. Ущелью Песни Войны нужны такие герои, как ты.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тром\'ка, $n. Ущелью Песни Войны нужны такие герои, как ты.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10278,'Наши союзники из Альянса помогают Лиге Аратора в защите Низины Арати. Им могла бы понадобиться твоя помощь в борьбе против нежити Осквернителей, |3-6($c).') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Наши союзники из Альянса помогают Лиге Аратора в защите Низины Арати. Им могла бы понадобиться твоя помощь в борьбе против нежити Осквернителей, |3-6($c).',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (10279,'Наши друзья по Альянсу собираются сражаться вместе со Среброкрылыми Часовыми в Ущелье Песни Войны. Вы поможете им там?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Наши друзья по Альянсу собираются сражаться вместе со Среброкрылыми Часовыми в Ущелье Песни Войны. Вы поможете им там?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10280,'Здравствуйте, путник. Я Оронок. Пожалуйста, присаживайтесь у огня, погрейтесь.$B$BТолько осторожней – внизу водятся страшные чудовища!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здравствуйте, путник. Я Оронок. Пожалуйста, присаживайтесь у огня, погрейтесь.$B$BТолько осторожней – внизу водятся страшные чудовища!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10283,'Тром\'ка, |3-6($c). Ты знаешь, что наш бой со Среброкрылыми Часовыми в Ущелье Песни Войны еще не закончен? Твоя помощь была бы очень кстати…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тром\'ка, |3-6($c). Ты знаешь, что наш бой со Среброкрылыми Часовыми в Ущелье Песни Войны еще не закончен? Твоя помощь была бы очень кстати…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (10285,'Как дела-то? Надоело уже в Запределье, решил вернуться в Альтеракскую долину и всыпать Орде как следует?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Как дела-то? Надоело уже в Запределье, решил вернуться в Альтеракскую долину и всыпать Орде как следует?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (10291,'Магия порталов доступна только магам, |3-6($c).') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Магия порталов доступна только магам, |3-6($c).',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (10293,'Королевское Фармацевтическое общество из Подгорода радо помочь нашим союзникам-оркам здесь, в Запределье. Это отличный шанс укрепить наши отношения и найти новые образцы и ингредиенты для изучения.$b$bГоворя про ингредиенты, я имею в виду яд.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Королевское Фармацевтическое общество из Подгорода радо помочь нашим союзникам-оркам здесь, в Запределье. Это отличный шанс укрепить наши отношения и найти новые образцы и ингредиенты для изучения.$b$bГоворя про ингредиенты, я имею в виду яд.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10299,'Мягко говоря, на заставе Белого Плеса мне пришлось сделать непредвиденную остановку. Мои клиенты ждут меня с товарами, и я уже начал сомневаться, успею ли я вовремя со всеми этими задержками.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мягко говоря, на заставе Белого Плеса мне пришлось сделать непредвиденную остановку. Мои клиенты ждут меня с товарами, и я уже начал сомневаться, успею ли я вовремя со всеми этими задержками.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (10300,'Эй, не трогай клетку, ясно?$B$BЭти огры поймали меня, а я-то хотела их поймать…') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Эй, не трогай клетку, ясно?$B$BЭти огры поймали меня, а я-то хотела их поймать…',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10301,'Говорят, будто пыль и жара Полуострова Адского Пламени сильно раздражают… Сам не видел, но вполне доверяю моим уважаемым и все еще живым союзникам.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Говорят, будто пыль и жара Полуострова Адского Пламени сильно раздражают… Сам не видел, но вполне доверяю моим уважаемым и все еще живым союзникам.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10302,'Забыть о кожевничестве школы силы стихий будет непросто. Если вы решите расстаться с этим умением, то лишитесь всех выкроек, требующих этой школы!','Забыть о кожевничестве школы силы стихий будет непросто. Если вы решите расстаться с этим умением, то лишитесь всех выкроек, требующих этой школы!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Забыть о кожевничестве школы силы стихий будет непросто. Если вы решите расстаться с этим умением, то лишитесь всех выкроек, требующих этой школы!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Забыть о кожевничестве школы силы стихий будет непросто. Если вы решите расстаться с этим умением, то лишитесь всех выкроек, требующих этой школы!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10306,'Видно, этим оркам и впрямь что-то нужно в Запределье! Если б вы знали, сколько они предлагали мне за союз, вы б меня прирезали от зависти!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Видно, этим оркам и впрямь что-то нужно в Запределье! Если б вы знали, сколько они предлагали мне за союз, вы б меня прирезали от зависти!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10310,'Для того чтобы я обучил вас верховой езде, |3-6($c), вы должны заслужить полное доверие эльфов крови.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Для того чтобы я обучил вас верховой езде, |3-6($c), вы должны заслужить полное доверие эльфов крови.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10314,'Код Проклятия находился в частных владениях Гул\'дана в Караборе двадцать лет. Ах да, ты же не знаешь, что такое Карабор, не так ли?$B$BЧерный храм…$B$BДа, теперь это дом Иллидана Ярости Бури.$B$BКогда Иллидан захватил Черный храм, он обнаружил там код. Он осознавал, что этот мир уже пострадал, но посчитал разумным оставить код себе для дальнейшего использования.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Код Проклятия находился в частных владениях Гул\'дана в Караборе двадцать лет. Ах да, ты же не знаешь, что такое Карабор, не так ли?$B$BЧерный храм…$B$BДа, теперь это дом Иллидана Ярости Бури.$B$BКогда Иллидан захватил Черный храм, он обнаружил там код. Он осознавал, что этот мир уже пострадал, но посчитал разумным оставить код себе для дальнейшего использования.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10317,'Мне вдруг резко подурнело. Когда ритуал окончился, я сразу же побежал домой, к детям. Я собрал все вещи, какие смог унести, и покинул дом вместе с сыновьями. Мы скрылись среди холмов… Другого выхода у нас и в самом деле не было.$B$BНе проходит и дня, чтобы я не думал о расколе. 20 лет ушло на то, чтобы восстановить связь со стихиями. После 20 лет стихии только начали восстанавливать силу.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мне вдруг резко подурнело. Когда ритуал окончился, я сразу же побежал домой, к детям. Я собрал все вещи, какие смог унести, и покинул дом вместе с сыновьями. Мы скрылись среди холмов… Другого выхода у нас и в самом деле не было.$B$BНе проходит и дня, чтобы я не думал о расколе. 20 лет ушло на то, чтобы восстановить связь со стихиями. После 20 лет стихии только начали восстанавливать силу.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (10322,'Я пришла сюда, потому что изучаю ветвь древней культуры, особенно распространенную в клане Громоборцев.$B$BОни были слабы и поддались соблазну силы, приходящей с преображением в орков Скверны с помощью крови Маннорота.$B$BЯ читала все их тексты. Мне особенно хотелось бы вернуть артефакт, барабан, стрелу и табличку, утраченные, когда мы сокрушили огров Камнерогов и загнали их обратно в их крепость.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я пришла сюда, потому что изучаю ветвь древней культуры, особенно распространенную в клане Громоборцев.$B$BОни были слабы и поддались соблазну силы, приходящей с преображением в орков Скверны с помощью крови Маннорота.$B$BЯ читала все их тексты. Мне особенно хотелось бы вернуть артефакт, барабан, стрелу и табличку, утраченные, когда мы сокрушили огров Камнерогов и загнали их обратно в их крепость.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10323,'Безжизненное тело Ар\'тора висит в воздухе, удерживаемое магией демонов. Даже после смерти они не оставили его в покое!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Безжизненное тело Ар\'тора висит в воздухе, удерживаемое магией демонов. Даже после смерти они не оставили его в покое!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10327,'Я… умер.$B$BНо почему я еще здесь? Разве нет охотничьих угодий, куда я мог бы отправиться?$B$BНет… Мне нужно закончить свое дело. Прежде чем я покину этот мир, нужно найти вторую часть Кода Проклятия.','Я… умерла.$B$BНо почему я еще здесь? Разве нет охотничьих угодий, куда я могла бы отправиться?$B$BНет… Мне нужно закончить свое дело. Прежде чем я покину этот мир, нужно найти вторую часть Кода Проклятия.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я… умер.$B$BНо почему я еще здесь? Разве нет охотничьих угодий, куда я мог бы отправиться?$B$BНет… Мне нужно закончить свое дело. Прежде чем я покину этот мир, нужно найти вторую часть Кода Проклятия.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я… умерла.$B$BНо почему я еще здесь? Разве нет охотничьих угодий, куда я могла бы отправиться?$B$BНет… Мне нужно закончить свое дело. Прежде чем я покину этот мир, нужно найти вторую часть Кода Проклятия.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10329,'Забывание навыков школы Меча – серьезное дело. Если ты решишь от него отказаться, то забудешь все чертежи, которые удалось выучить в школе Меча!','Забывание навыков школы Меча – серьезное дело. Если ты решишь от него отказаться, то забудешь все чертежи, которые удалось выучить в школе Меча!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Забывание навыков школы Меча – серьезное дело. Если ты решишь от него отказаться, то забудешь все чертежи, которые удалось выучить в школе Меча!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Забывание навыков школы Меча – серьезное дело. Если ты решишь от него отказаться, то забудешь все чертежи, которые удалось выучить в школе Меча!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10341,'Огры – они закопали меня по шею, а потом забыли вернуться. $b$bДа, дружок, очень забавно. Смейся, смейся. Прямо голова профессора Доуэля.$b$bКонечно, если ты хочешь мне помочь, я, должно быть, смогу тебя отблагодарить $b$bДа ладно, продолжай смеяться.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Огры – они закопали меня по шею, а потом забыли вернуться. $b$bДа, дружок, очень забавно. Смейся, смейся. Прямо голова профессора Доуэля.$b$bКонечно, если ты хочешь мне помочь, я, должно быть, смогу тебя отблагодарить $b$bДа ладно, продолжай смеяться.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10352,'На этой земле все еще остались шрамы прошлого. Исчезнут ли они когда-нибудь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','На этой земле все еще остались шрамы прошлого. Исчезнут ли они когда-нибудь?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10354,'Обитатели Дикотопи в Зангартопи плетут ивовые корзины с хитрыми замками. Возможно, даже вам будет нелегко их вскрыть.','Обитатели Дикотопи в Зангартопи плетут ивовые корзины с хитрыми замками. Возможно, даже вам будет нелегко их вскрыть.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Обитатели Дикотопи в Зангартопи плетут ивовые корзины с хитрыми замками. Возможно, даже вам будет нелегко их вскрыть.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Обитатели Дикотопи в Зангартопи плетут ивовые корзины с хитрыми замками. Возможно, даже вам будет нелегко их вскрыть.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10355,'С сундучками из бастиона Вечной Скорби в Награнде нелегко будет справиться даже такому опытному разбойнику, как ты.','С сундучками из бастиона Вечной Скорби в Награнде нелегко будет справиться даже такому опытному разбойнику, как ты.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','С сундучками из бастиона Вечной Скорби в Награнде нелегко будет справиться даже такому опытному разбойнику, как ты.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','С сундучками из бастиона Вечной Скорби в Награнде нелегко будет справиться даже такому опытному разбойнику, как ты.',`text0_1_loc8`);
