INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10356,'Ступай осторожно, |3-6($r). Под этим мостом – ад.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ступай осторожно, |3-6($r). Под этим мостом – ад.',`text0_0_loc8`);
