INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10359,'Станция Тошли – самая лучшая! Уединение и источники странной силы Запределья – идеальное сочетание для проведения экспериментов!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Станция Тошли – самая лучшая! Уединение и источники странной силы Запределья – идеальное сочетание для проведения экспериментов!',`text0_0_loc8`);
