INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10360,'Ты уже $gбеседовал:беседовала; с моим клоном… эм… я хотел сказать… с моим двойником?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты уже $gбеседовал:беседовала; с моим клоном… эм… я хотел сказать… с моим двойником?',`text0_0_loc8`);
