INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`) VALUES (10373,'Спасибо за то, что выпустили меня отсюда! Я ваш должник!','Отсюда я теперь смогу выбраться. Спасибо!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Спасибо за то, что выпустили меня отсюда! Я ваш должник!',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Отсюда я теперь смогу выбраться. Спасибо!',`text1_0_loc8`);
