INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10375,'Вот. Больше, смотри, не потеряй!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вот. Больше, смотри, не потеряй!',`text0_0_loc8`);
