INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10378,'Это просто маленький песенник, я подумал, что он понравится тебе. Там есть текст песни под названием "Плач высокорожденных" – той, что звучит из воздуха для леди Сильваны.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Это просто маленький песенник, я подумал, что он понравится тебе. Там есть текст песни под названием "Плач высокорожденных" – той, что звучит из воздуха для леди Сильваны.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10379,'В Шаттрате есть два банка, оба находятся вдоль границы центральной части города. Одним владеют дренеи из Алдоров, другим – эльфы крови из Провидцев.','В Шаттрате есть два банка, оба находятся вдоль границы центральной части города. Одним владеют дренеи из Алдоров, другим – эльфы крови из Провидцев.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','В Шаттрате есть два банка, оба находятся вдоль границы центральной части города. Одним владеют дренеи из Алдоров, другим – эльфы крови из Провидцев.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','В Шаттрате есть два банка, оба находятся вдоль границы центральной части города. Одним владеют дренеи из Алдоров, другим – эльфы крови из Провидцев.',`text0_1_loc8`);
