INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10380,'Банк Алдоров находится к северо-западу от центра города.','Банк Алдоров находится к северо-западу от центра города.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Банк Алдоров находится к северо-западу от центра города.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Банк Алдоров находится к северо-западу от центра города.',`text0_1_loc8`);
