INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10381,'Банк Провидцев находится к юго-востоку от центра города.','Банк Провидцев находится к юго-востоку от центра города.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Банк Провидцев находится к юго-востоку от центра города.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Банк Провидцев находится к юго-востоку от центра города.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10382,'Постоялые дворы Шаттрата переполнены ранеными беженцами. Но у дренеев на Возвышенности Алдоров и у эльфов крови на Ярусе Провидцев можно найти место.','Постоялые дворы Шаттрата переполнены ранеными беженцами. Но у дренеев на Возвышенности Алдоров и у эльфов крови на Ярусе Провидцев можно найти место.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Постоялые дворы Шаттрата переполнены ранеными беженцами. Но у дренеев на Возвышенности Алдоров и у эльфов крови на Ярусе Провидцев можно найти место.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Постоялые дворы Шаттрата переполнены ранеными беженцами. Но у дренеев на Возвышенности Алдоров и у эльфов крови на Ярусе Провидцев можно найти место.',`text0_1_loc8`);
