INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10384,'Таверна Провидцев находится над Шаттратом, на ярусе Провидцев. Туда можно подняться на подъемнике, он находится к юго-западу от центра города.','Таверна Провидцев находится над Шаттратом, на ярусе Провидцев. Туда можно подняться на подъемнике, он находится к юго-западу от центра города.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Таверна Провидцев находится над Шаттратом, на ярусе Провидцев. Туда можно подняться на подъемнике, он находится к юго-западу от центра города.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Таверна Провидцев находится над Шаттратом, на ярусе Провидцев. Туда можно подняться на подъемнике, он находится к юго-западу от центра города.',`text0_1_loc8`);
