INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10386,'Почтовые ящики находятся рядом с тавернами и банками Алдоров и Провидцев, или внутри них.','Почтовые ящики находятся рядом с тавернами и банками Алдоров и Провидцев, или внутри них.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Почтовые ящики находятся рядом с тавернами и банками Алдоров и Провидцев, или внутри них.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Почтовые ящики находятся рядом с тавернами и банками Алдоров и Провидцев, или внутри них.',`text0_1_loc8`);
