INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10388,'Военачальники Шаттрата часто собираются на ступенях между верхним и нижним городом. Сбор распорядителей арены Альянса проходит в одном месте, распорядителей арены Орды – в другом, а вербовщики арены стоят между ними.','Военачальники Шаттрата часто собираются на ступенях между верхним и нижним городом. Сбор распорядителей арены Альянса проходит в одном месте, распорядителей арены Орды – в другом, а вербовщики арены стоят между ними.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Военачальники Шаттрата часто собираются на ступенях между верхним и нижним городом. Сбор распорядителей арены Альянса проходит в одном месте, распорядителей арены Орды – в другом, а вербовщики арены стоят между ними.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Военачальники Шаттрата часто собираются на ступенях между верхним и нижним городом. Сбор распорядителей арены Альянса проходит в одном месте, распорядителей арены Орды – в другом, а вербовщики арены стоят между ними.',`text0_1_loc8`);
