INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10389,'Военачальников Альянса обычно можно найти на лестнице северо-восточнее центра города.','Военачальников Альянса обычно можно найти на лестнице северо-восточнее центра города.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Военачальников Альянса обычно можно найти на лестнице северо-восточнее центра города.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Военачальников Альянса обычно можно найти на лестнице северо-восточнее центра города.',`text0_1_loc8`);
