INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10404,'Смотрителей стойл можно найти рядом с тавернами дренеев и эльфов крови, на Возвышенности Алдоров и на Ярусе Провидцев.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Смотрителей стойл можно найти рядом с тавернами дренеев и эльфов крови, на Возвышенности Алдоров и на Ярусе Провидцев.',`text0_0_loc8`);
