INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10407,'Слушай меня, батрак. У нас свой способ доставки и сохранения фрагмента Кода. Посланник должен предъявить письмо с печатью владыки Иллидана. Нет письма – нет и Кода.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Слушай меня, батрак. У нас свой способ доставки и сохранения фрагмента Кода. Посланник должен предъявить письмо с печатью владыки Иллидана. Нет письма – нет и Кода.',`text0_0_loc8`);
