INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10411,'Инессера – весьма умная женщина, торгующая как самоцветами, так и инструментом для ювелиров. Найти ее лавку можно в северной части Возвышенности Алдоров.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Инессера – весьма умная женщина, торгующая как самоцветами, так и инструментом для ювелиров. Найти ее лавку можно в северной части Возвышенности Алдоров.',`text0_0_loc8`);
