INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10413,'*Элементаль воды готов нахлынуть.*') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','*Элементаль воды готов нахлынуть.*',`text0_0_loc8`);
