INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10415,'Верховного зачаровывателя Бардолана можно найти в Библиотеке Провидца на Ярусе Провидцев. Великий мастер, он окружен своими учениками – мастерами, ремесленниками, знатоками и подмастерьями.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Верховного зачаровывателя Бардолана можно найти в Библиотеке Провидца на Ярусе Провидцев. Великий мастер, он окружен своими учениками – мастерами, ремесленниками, знатоками и подмастерьями.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10419,'Сеймура, главного Шаттратского специалиста по снятию шкур и великого мастера торговли, можно найти в Нижнем Городе, на открытом рынке.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Сеймура, главного Шаттратского специалиста по снятию шкур и великого мастера торговли, можно найти в Нижнем Городе, на открытом рынке.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10422,'Я свободно говорю на языках дворфов, карликов и на самом распространенном людском наречии. Но я понятия не имею, что ты говоришь! $B$BГовори громче! Я тебя не слышу за скрежетом механизмов!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я свободно говорю на языках дворфов, карликов и на самом распространенном людском наречии. Но я понятия не имею, что ты говоришь! $B$BГовори громче! Я тебя не слышу за скрежетом механизмов!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10423,'Ну да, типа того… добро пожаловать на мою станцию.$B$BИтак, что ты думаешь? Тут неплохо все обустроили, ведь правда?$B$BВ любом случае я очень рад, что мы избавились от этих скучных эльфов из Сильванаара.$B$BНайди, чем тут заняться, мы здесь проводим массу экспериментов, и почему бы тебе не помочь с ними.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ну да, типа того… добро пожаловать на мою станцию.$B$BИтак, что ты думаешь? Тут неплохо все обустроили, ведь правда?$B$BВ любом случае я очень рад, что мы избавились от этих скучных эльфов из Сильванаара.$B$BНайди, чем тут заняться, мы здесь проводим массу экспериментов, и почему бы тебе не помочь с ними.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10425,'*У рубаки текут слюни в ожидании кровавой бойни.*') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','*У рубаки текут слюни в ожидании кровавой бойни.*',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10427,'Дворф, похоже, был застигнут и убит во время выполнения шпионского задания. Служители Кузницы Смерти оставили труп на виду, возможно – в назидание другим потенциальным незваным гостям.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Дворф, похоже, был застигнут и убит во время выполнения шпионского задания. Служители Кузницы Смерти оставили труп на виду, возможно – в назидание другим потенциальным незваным гостям.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
