INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10444,'Я ученый, изучающий время и звук, так что я не вполне понимаю, как я должен думать или найти время для выполнения какой-нибудь работы, когда вокруг так шумят?!$B$BПочему эти дураки не могут пойти и подорваться где-нибудь еще??$B$BА, ладно, по крайней мере, я хорошо выгляжу. Скажи, $gмальчик:милашка;, я тебя раньше здесь видел?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я ученый, изучающий время и звук, так что я не вполне понимаю, как я должен думать или найти время для выполнения какой-нибудь работы, когда вокруг так шумят?!$B$BПочему эти дураки не могут пойти и подорваться где-нибудь еще??$B$BА, ладно, по крайней мере, я хорошо выгляжу. Скажи, $gмальчик:милашка;, я тебя раньше здесь видел?',`text0_0_loc8`);
