INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10446,'Труп орка небрежно отбросили в сторону, чтобы не загромождать проход.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Труп орка небрежно отбросили в сторону, чтобы не загромождать проход.',`text0_0_loc8`);
