INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10447,'Почти весь мой народ считает меня предателем… прихвостнем Иллидана. Пусть пока так и думают.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Почти весь мой народ считает меня предателем… прихвостнем Иллидана. Пусть пока так и думают.',`text0_0_loc8`);
