INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10448,'Все награды за предоставленные услуги выдает военный глашатай Сардон Чистый Удар.$B$BВывешивать объявления воспрещается.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Все награды за предоставленные услуги выдает военный глашатай Сардон Чистый Удар.$B$BВывешивать объявления воспрещается.',`text0_0_loc8`);
