INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10450,'Добро пожаловать в таверну станции Тошли. Чем могу быть полезен?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать в таверну станции Тошли. Чем могу быть полезен?',`text0_0_loc8`);
