INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (10451,'Хочешь научиться тонкостям ювелирного дела?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Хочешь научиться тонкостям ювелирного дела?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (10455,'Мы поговорим снова только после того, как ты постигнешь базовый уровень знаний ювелирного дела.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мы поговорим снова только после того, как ты постигнешь базовый уровень знаний ювелирного дела.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (10456,'Я поделюсь с вами своими познаниями в ювелирном деле.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я поделюсь с вами своими познаниями в ювелирном деле.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10457,'Я посвятил свою жизнь созданию украшений и огранке самоцветов. Могу я разделить свою страсть с тобой?','Я посвятила свою жизнь созданию украшений (ювелирных изделий) и огранке самоцветов. Могу я разделить свою страсть с тобой?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я посвятил свою жизнь созданию украшений и огранке самоцветов. Могу я разделить свою страсть с тобой?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я посвятила свою жизнь созданию украшений (ювелирных изделий) и огранке самоцветов. Могу я разделить свою страсть с тобой?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (10458,'Хотела бы я, чтобы у меня было побольше времени, чтобы учить всех, кто ко мне приходит, но, к сожалению, так нельзя. Пока вы не будете знать все, чему может научить Падаар, ничем не могу вам помочь.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Хотела бы я, чтобы у меня было побольше времени, чтобы учить всех, кто ко мне приходит, но, к сожалению, так нельзя. Пока вы не будете знать все, чему может научить Падаар, ничем не могу вам помочь.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (10459,'На мою долю выпало счастье помочь столь даровитому созданию, как вы, узнать больше о ювелирном деле. Что бы вы хотели узнать?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','На мою долю выпало счастье помочь столь даровитому созданию, как вы, узнать больше о ювелирном деле. Что бы вы хотели узнать?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (10460,'Я очень занята, |3-6($r). $b$bУ нас тут ужасная проблема, с которой нужно срочно разобраться!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я очень занята, |3-6($r). $b$bУ нас тут ужасная проблема, с которой нужно срочно разобраться!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (10466,'Когда имеешь дело с берейторами Разака, можно научиться паре моментов насчет выполнения приказов.$B$BПервое – биться надо, пока жив. Второе – смотри первое.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Когда имеешь дело с берейторами Разака, можно научиться паре моментов насчет выполнения приказов.$B$BПервое – биться надо, пока жив. Второе – смотри первое.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10467,'Нужно наточить клинок или, может быть, приобрести новое оружие? Лучше перестраховаться, чем потом пожалеть…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Нужно наточить клинок или, может быть, приобрести новое оружие? Лучше перестраховаться, чем потом пожалеть…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10468,'Если вы ищете молот, то вы пришли туда, куда надо.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если вы ищете молот, то вы пришли туда, куда надо.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10469,'$GСынок:Девушка;, врать не стану, дела здесь творятся скверные. На нас постоянно нападают жуки и под угрозой сам наш образ жизни, наша свобода!$B$BХочешь проявить патриотизм и помочь нам?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','$GСынок:Девушка;, врать не стану, дела здесь творятся скверные. На нас постоянно нападают жуки и под угрозой сам наш образ жизни, наша свобода!$B$BХочешь проявить патриотизм и помочь нам?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10470,'Терон Кровожад? Да… я знаю его.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Терон Кровожад? Да… я знаю его.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10471,'Превосходно! Великолепное представление!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Превосходно! Великолепное представление!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (10473,'В юности я старательно училась, чтобы стать жрецом-анахоретом. Женщин-экзархов тогда почти нигде не было.$B$BСейчас же пол мало что значит, главное – смелость и твердая вера.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','В юности я старательно училась, чтобы стать жрецом-анахоретом. Женщин-экзархов тогда почти нигде не было.$B$BСейчас же пол мало что значит, главное – смелость и твердая вера.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10475,'Формирование потока времени – очень сложная и весьма тонкая работа, но вы сегодня великолепно справились с ней.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Формирование потока времени – очень сложная и весьма тонкая работа, но вы сегодня великолепно справились с ней.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10491,'Вы здесь для того, чтобы помочь справиться с беспорядками?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вы здесь для того, чтобы помочь справиться с беспорядками?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10492,'В качестве награды за годы службы Иллидан позволил Келю послать ему пятерых воинов для обучения. Впервые Эльфы крови стали тренироваться как охотники на демонов.$B$BОбучение было жестоким. Иллидан подверг воинов Кель\'таса таким испытаниям, что сломили бы любого охотника на демонов.$B$BТрое эльфов Кель\'таса погибли в процессе обучения, еще один сошел с ума.$B$BИ только один смог закончить обучение.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','В качестве награды за годы службы Иллидан позволил Келю послать ему пятерых воинов для обучения. Впервые Эльфы крови стали тренироваться как охотники на демонов.$B$BОбучение было жестоким. Иллидан подверг воинов Кель\'таса таким испытаниям, что сломили бы любого охотника на демонов.$B$BТрое эльфов Кель\'таса погибли в процессе обучения, еще один сошел с ума.$B$BИ только один смог закончить обучение.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10493,'Его зовут Варедис. К удивлению Иллидана, не только он преуспел в мучительных ритуалах перехода, что являются частью обучения; Варедис уже овладел силой лучше многих охотников на демонов.$B$BИллидан оценил возможности Варедиса и поручил трем лучшим охотникам на демонов обучать его.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Его зовут Варедис. К удивлению Иллидана, не только он преуспел в мучительных ритуалах перехода, что являются частью обучения; Варедис уже овладел силой лучше многих охотников на демонов.$B$BИллидан оценил возможности Варедиса и поручил трем лучшим охотникам на демонов обучать его.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10494,'После года обучения под руководством трех лучших охотников на демонов, служивших Иллидану, Варедис превзошел их. $b$bПоскольку его более не удовлетворял уровень обучения, который они могли ему предложить, Варедис проник в Совет Теней, где он изучал могущественную реликвию, известную как Книга Имен Скверны. Он втайне читал эту книгу, впечатывая в память каждый абзац.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','После года обучения под руководством трех лучших охотников на демонов, служивших Иллидану, Варедис превзошел их. $b$bПоскольку его более не удовлетворял уровень обучения, который они могли ему предложить, Варедис проник в Совет Теней, где он изучал могущественную реликвию, известную как Книга Имен Скверны. Он втайне читал эту книгу, впечатывая в память каждый абзац.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10495,'Говорят, что зная настоящее имя демона, можно обрести над ним некоторую власть.$B$BКнига Имен Скверны содержит истинные имена каждого когда-либо существовавшего демона. Изучая книгу, Варедис обнаружил источник силы, соперничающий с самим испитием Иллидана из Черепа Гул\'дана.$B$BПо просьбе Иллидана Варедис теперь возглавляет учебный полигон в Руинах Карабора – вместе с тремя учителями, тренировавшими Варедиса.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Говорят, что зная настоящее имя демона, можно обрести над ним некоторую власть.$B$BКнига Имен Скверны содержит истинные имена каждого когда-либо существовавшего демона. Изучая книгу, Варедис обнаружил источник силы, соперничающий с самим испитием Иллидана из Черепа Гул\'дана.$B$BПо просьбе Иллидана Варедис теперь возглавляет учебный полигон в Руинах Карабора – вместе с тремя учителями, тренировавшими Варедиса.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10497,'Неудивительно, что эльфы крови обладают таким недюжинным умением охотиться на демонов. В конце концов, син\'дорай не питают отвращения к демонической магии, как ночные эльфы.$B$BОднако не от всех ожидаю больших успехов – многим из них, в том числе и Варедису, эта сила нужна лишь для собственных нужд. Рано или поздно она поглотит их и подчинит себе, потому что в них нет той чистоты, которая должна быть в сердце каждого охотника на демонов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Неудивительно, что эльфы крови обладают таким недюжинным умением охотиться на демонов. В конце концов, син\'дорай не питают отвращения к демонической магии, как ночные эльфы.$B$BОднако не от всех ожидаю больших успехов – многим из них, в том числе и Варедису, эта сила нужна лишь для собственных нужд. Рано или поздно она поглотит их и подчинит себе, потому что в них нет той чистоты, которая должна быть в сердце каждого охотника на демонов.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10501,'Мумман держит свою скромную лавочку у входа в город, сразу за таверной. Стряпуха она отменная.','Мумман держит свою скромную лавочку у входа в город, сразу за таверной. Стряпуха она отменная.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мумман держит свою скромную лавочку у входа в город, сразу за таверной. Стряпуха она отменная.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мумман держит свою скромную лавочку у входа в город, сразу за таверной. Стряпуха она отменная.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (10502,'В портняжной мастерской Килена, что стоит в северо-западном углу Базара, есть ткацкий станок, подходящий под твое описание.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','В портняжной мастерской Килена, что стоит в северо-западном углу Базара, есть ткацкий станок, подходящий под твое описание.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10505,'"Для вас слишком рано контролировать меня, ведь вы совсем недавно вышли из игры".') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','"Для вас слишком рано контролировать меня, ведь вы совсем недавно вышли из игры".',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10506,'Чтобы пройти через мой зал, вам следует победить меня в игре разума! Возьмите под контроль вашего короля, когда будете готовы начать...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Чтобы пройти через мой зал, вам следует победить меня в игре разума! Возьмите под контроль вашего короля, когда будете готовы начать...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10508,'Я дам тебе любой совет, какой смогу, если это поможет тебе сражаться с ограми!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я дам тебе любой совет, какой смогу, если это поможет тебе сражаться с ограми!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10509,'В объявлении содержится призыв к убийству громадной волчицы. Ее логово находится к югу от Зазубренной гряды, у крепости Орды.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','В объявлении содержится призыв к убийству громадной волчицы. Ее логово находится к югу от Зазубренной гряды, у крепости Орды.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10514,'*Волшебный Страж указывает на место под Рядом – лестничный колодец к юго-востоку от центра города.*') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','*Волшебный Страж указывает на место под Рядом – лестничный колодец к юго-востоку от центра города.*',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10516,'*Волшебный Страж показывает в северо-западную часть города, где обитают араккоа Шаттрата.*') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','*Волшебный Страж показывает в северо-западную часть города, где обитают араккоа Шаттрата.*',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10517,'*Волшебный Страж указывает на Нижний Город, где можно найти большую кузню.*') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','*Волшебный Страж указывает на Нижний Город, где можно найти большую кузню.*',`text0_0_loc8`);
