INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10518,'*Волшебный Страж указывает на уличный базар на юго-востоке нижнего города.*') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','*Волшебный Страж указывает на уличный базар на юго-востоке нижнего города.*',`text0_0_loc8`);
