INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10524,'Добро пожаловать на Возвышенность Алдоров. Ты ищешь наставника?','Добро пожаловать на Возвышенность Алдоров. Ты ищешь наставника?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать на Возвышенность Алдоров. Ты ищешь наставника?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Добро пожаловать на Возвышенность Алдоров. Ты ищешь наставника?',`text0_1_loc8`);
