INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10526,'Почтовый ящик находится рядом с центром помощи.','Почтовый ящик находится рядом с центром помощи.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Почтовый ящик находится рядом с центром помощи.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Почтовый ящик находится рядом с центром помощи.',`text0_1_loc8`);
