INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10530,'Приветствую, |3-6($c), я – сотрудник отдела рекомендаций и действую по заданию Луносвета. Моя обязанность – помогать искателям приключений, получившим рекомендательный жетон Орды.$B$BЯ принимаю жетоны в любых количествах, но наиболее выгодно для тебя – сдавать их по 10 сразу. Когда ты сдаешь нам жетоны, я заношу это в летописи. В результате ты получишь признание в Луносвете за то, что $gвыполнил:выполнила; свой долг.','Приветствую, |3-6($c), я – сотрудница отдела рекомендаций и действую по приказу Луносвета. Моя обязанность – помогать искателям приключений, получившим рекомендательный жетон Орды.$B$BЯ принимаю жетоны в любых количествах, но наиболее выгодно для тебя – сдавать их по 10 сразу. Когда ты сдаешь нам жетоны, я заношу это в летописи. В результате ты получишь признание в Луносвете за то, что $gвыполнил:выполнила; свой долг.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приветствую, |3-6($c), я – сотрудник отдела рекомендаций и действую по заданию Луносвета. Моя обязанность – помогать искателям приключений, получившим рекомендательный жетон Орды.$B$BЯ принимаю жетоны в любых количествах, но наиболее выгодно для тебя – сдавать их по 10 сразу. Когда ты сдаешь нам жетоны, я заношу это в летописи. В результате ты получишь признание в Луносвете за то, что $gвыполнил:выполнила; свой долг.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Приветствую, |3-6($c), я – сотрудница отдела рекомендаций и действую по приказу Луносвета. Моя обязанность – помогать искателям приключений, получившим рекомендательный жетон Орды.$B$BЯ принимаю жетоны в любых количествах, но наиболее выгодно для тебя – сдавать их по 10 сразу. Когда ты сдаешь нам жетоны, я заношу это в летописи. В результате ты получишь признание в Луносвете за то, что $gвыполнил:выполнила; свой долг.',`text0_1_loc8`);
