INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10531,'Здравствуйте, |3-6($c). Я – сотрудник отдела рекомендаций и действую от имени Экзодара. Мой долг – помогать тем, кто получил рекомендательные жетоны Альянса.$b$bЯ принимаю жетоны в разных количествах, но лучше всего сдавать их по десять штук за раз, после чего все совершенные вами подвиги будут внесены в наши летописи и, как результат, вам будет оказан должный почет со стороны Экзодара.','Здравствуйте, |3-6($c). Я – сотрудница отдела рекомендаций и действую от имени Экзодара. Мой долг – помогать тем, кто получил рекомендательные жетоны Альянса.$b$bЯ принимаю жетоны в разных количествах, но лучше всего сдавать их по десять штук за раз, после чего все совершенные вами подвиги будут внесены в наши летописи и, как результат, вам будет оказан должный почет со стороны Экзодара.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здравствуйте, |3-6($c). Я – сотрудник отдела рекомендаций и действую от имени Экзодара. Мой долг – помогать тем, кто получил рекомендательные жетоны Альянса.$b$bЯ принимаю жетоны в разных количествах, но лучше всего сдавать их по десять штук за раз, после чего все совершенные вами подвиги будут внесены в наши летописи и, как результат, вам будет оказан должный почет со стороны Экзодара.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Здравствуйте, |3-6($c). Я – сотрудница отдела рекомендаций и действую от имени Экзодара. Мой долг – помогать тем, кто получил рекомендательные жетоны Альянса.$b$bЯ принимаю жетоны в разных количествах, но лучше всего сдавать их по десять штук за раз, после чего все совершенные вами подвиги будут внесены в наши летописи и, как результат, вам будет оказан должный почет со стороны Экзодара.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10534,'Мы прибыли в Чащобу Рууан, чтобы понять, сможем ли мы восстановить природный баланс в этих горах. $b$bОднако вмешательство араккоа и Культа Змея сильно осложнило задачу. $b$bК счастью, есть такие, как вы и Самия, всегда готовые предложить руку помощи.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы прибыли в Чащобу Рууан, чтобы понять, сможем ли мы восстановить природный баланс в этих горах. $b$bОднако вмешательство араккоа и Культа Змея сильно осложнило задачу. $b$bК счастью, есть такие, как вы и Самия, всегда готовые предложить руку помощи.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10535,'Хех, ты $gвернулся:вернулась;? Ты же не ждешь, в самом деле, что я изменю свое отношение к тебе? $b$bИсчезни.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Хех, ты $gвернулся:вернулась;? Ты же не ждешь, в самом деле, что я изменю свое отношение к тебе? $b$bИсчезни.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10539,'Нуаар, что с тобой? Ты как-то странно выглядишь сегодня.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Нуаар, что с тобой? Ты как-то странно выглядишь сегодня.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10540,'Прочь, надсмотрщик! Мы уже поговорили. $B$BХватит тянуть время, пора выполнять твои приказания в Чащобе Рууан!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Прочь, надсмотрщик! Мы уже поговорили. $B$BХватит тянуть время, пора выполнять твои приказания в Чащобе Рууан!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10543,'Ты мог хотя бы попытаться быть чуть убедительнее.$B$BСлушай, Нуаар, я вообще не собирался тебе этого говорить, но, похоже, придется и тебя привлечь к этому делу. Макснар планирует напасть на друидов в Чащобе Рууан, чтобы выгнать их оттуда раз и навсегда.$B$BУ нас и без того хватает забот с ограми Камен\'мока, так что второго фронта нам совсем не надо. Поэтому я заключил временное перемирие с араккоа.$B$BНу, что скажешь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты мог хотя бы попытаться быть чуть убедительнее.$B$BСлушай, Нуаар, я вообще не собирался тебе этого говорить, но, похоже, придется и тебя привлечь к этому делу. Макснар планирует напасть на друидов в Чащобе Рууан, чтобы выгнать их оттуда раз и навсегда.$B$BУ нас и без того хватает забот с ограми Камен\'мока, так что второго фронта нам совсем не надо. Поэтому я заключил временное перемирие с араккоа.$B$BНу, что скажешь?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10544,'Пока мы разговариваем, заканчиваются последние приготовления. Остальное будет зависеть от того, как быстро ты сможешь организовать свои силы в Чащобе Рууан.$B$BДумаешь, что сможешь с этим справиться и сделать это быстро?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Пока мы разговариваем, заканчиваются последние приготовления. Остальное будет зависеть от того, как быстро ты сможешь организовать свои силы в Чащобе Рууан.$B$BДумаешь, что сможешь с этим справиться и сделать это быстро?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10545,'Вот это дух!$B$BЯ рад, что мы устроили эту маленькую встречу. Теперь я меньше беспокоюсь насчет нападения. С такими соратниками, как ты, мы проиграть не можем!$B$BЛадно, у тебя есть приказ о выступлении. Теперь возвращайся в Чащобу Рууан и исполни его!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вот это дух!$B$BЯ рад, что мы устроили эту маленькую встречу. Теперь я меньше беспокоюсь насчет нападения. С такими соратниками, как ты, мы проиграть не можем!$B$BЛадно, у тебя есть приказ о выступлении. Теперь возвращайся в Чащобу Рууан и исполни его!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (10546,'Каражан не всегда был таким… зловещим. Тьма опустилась на него лишь после смерти Медива. Или того, что, как мы думаем, было смертью Медива.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Каражан не всегда был таким… зловещим. Тьма опустилась на него лишь после смерти Медива. Или того, что, как мы думаем, было смертью Медива.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10548,'Должен сказать, в Пиратской Бухте готовят лучшую похлебку из моллюсков во всех Южных морях. О, не интересуешься кулинарными искусствами, а? Тогда позволь первым пригласить тебя на борт "Девичьего Каприза", самого лучшего пассажирского корабля, плавающего между Восточными королевствами и Калимдором. Скоро он вернется из плавания в Кабестан, так что располагайся поудобнее до тех пор, пока он не причалит.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Должен сказать, в Пиратской Бухте готовят лучшую похлебку из моллюсков во всех Южных морях. О, не интересуешься кулинарными искусствами, а? Тогда позволь первым пригласить тебя на борт "Девичьего Каприза", самого лучшего пассажирского корабля, плавающего между Восточными королевствами и Калимдором. Скоро он вернется из плавания в Кабестан, так что располагайся поудобнее до тех пор, пока он не причалит.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10549,'Раз уж ты сюда $gдобрался:добралась;, то назад теперь дороги нет.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Раз уж ты сюда $gдобрался:добралась;, то назад теперь дороги нет.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10554,'Эти друиды нашли источник невероятной силы! Они могут превращаться в животных, метать молнии и излучать яркий лунный свет… Мне непременно нужно узнать, как они это делают!$B$BМожет, они под своими мантиями батарейки носят?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эти друиды нашли источник невероятной силы! Они могут превращаться в животных, метать молнии и излучать яркий лунный свет… Мне непременно нужно узнать, как они это делают!$B$BМожет, они под своими мантиями батарейки носят?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10557,'В Терамор можно уехать с этой пристани. Только учти: людям из Альянса небезопасно путешествовать в тех краях. Будь $gосторожен:осторожна;.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','В Терамор можно уехать с этой пристани. Только учти: людям из Альянса небезопасно путешествовать в тех краях. Будь $gосторожен:осторожна;.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10561,'Этот полет закончится в самой дальней точке Звенящего гребня. Очень опасно!$B$BВ этот раз мне понадобится письменный приказ…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Этот полет закончится в самой дальней точке Звенящего гребня. Очень опасно!$B$BВ этот раз мне понадобится письменный приказ…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10562,'Мы всегда с удовольствием собираем информацию о полетах! Куда желаете отправиться?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы всегда с удовольствием собираем информацию о полетах! Куда желаете отправиться?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10563,'Что еще? Ты что не видишь, что я очень занятой дворф?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что еще? Ты что не видишь, что я очень занятой дворф?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10565,'Исследование этих новых земель, несомненно, важно, но и об Азероте забывать нельзя! Сейчас вы нужны нам еще больше в войне с Осквернителями. Сохраним же наши ресурсы!','Исследование этих новых земель, несомненно, важно, но и об Азероте забывать нельзя! Сейчас вы нужны нам еще больше в войне с Осквернителями. Сохраним же наши ресурсы!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Исследование этих новых земель, несомненно, важно, но и об Азероте забывать нельзя! Сейчас вы нужны нам еще больше в войне с Осквернителями. Сохраним же наши ресурсы!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Исследование этих новых земель, несомненно, важно, но и об Азероте забывать нельзя! Сейчас вы нужны нам еще больше в войне с Осквернителями. Сохраним же наши ресурсы!',`text0_1_loc8`);
