INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10566,'$C! Нам нужна твоя помощь! Жестокие орки из клана Песни Войны опустошают Ясеневый лес. Нам нужна твоя сила, чтобы встретиться с ними на поле боя. Возвращайся с нами в Азерот и сразись за честь Среброкрылых Часовых! Присоединишься ли ты к нам?','$c! Нам нужна твоя помощь! Жестокие орки из клана Песни Войны опустошают Ясеневый лес. Нам нужна твоя сила, чтобы встретиться с ними на поле боя. Возвращайся с нами в Азерот и сразись за честь Среброкрылых Часовых! Присоединишься ли ты к нам?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','$C! Нам нужна твоя помощь! Жестокие орки из клана Песни Войны опустошают Ясеневый лес. Нам нужна твоя сила, чтобы встретиться с ними на поле боя. Возвращайся с нами в Азерот и сразись за честь Среброкрылых Часовых! Присоединишься ли ты к нам?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','$c! Нам нужна твоя помощь! Жестокие орки из клана Песни Войны опустошают Ясеневый лес. Нам нужна твоя сила, чтобы встретиться с ними на поле боя. Возвращайся с нами в Азерот и сразись за честь Среброкрылых Часовых! Присоединишься ли ты к нам?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10568,'Есть старая пословица: "Дай кому-то рыбу, и он будет сыт целый день. Научи его ловить рыбу, и он будет сыт всю жизнь". Но рыбу еще надо приготовить, и как раз в этом я вам помогу!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Есть старая пословица: "Дай кому-то рыбу, и он будет сыт целый день. Научи его ловить рыбу, и он будет сыт всю жизнь". Но рыбу еще надо приготовить, и как раз в этом я вам помогу!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10569,'Привет, $n! Ну, как там ваши приключения? Мои эксперименты идут своим чередом… $b$bОбязательно пообщайтесь со мной попозже! Может быть, у меня появятся новые возможности для испытательных полетов!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Привет, $n! Ну, как там ваши приключения? Мои эксперименты идут своим чередом… $b$bОбязательно пообщайтесь со мной попозже! Может быть, у меня появятся новые возможности для испытательных полетов!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10570,'Сила и честь, |3-6($c). В Альтеракской долине нужны такие солдаты, как ты. Мы должны защитить территорию клана Северного Волка! Вернешься ли ты в Азерот и поможешь ли нам?','Сила и честь, |3-6($c). В Альтеракской долине нужны такие солдаты, как ты. Мы должны защитить территорию клана Северного Волка! Вернешься ли ты в Азерот и поможешь ли нам?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Сила и честь, |3-6($c). В Альтеракской долине нужны такие солдаты, как ты. Мы должны защитить территорию клана Северного Волка! Вернешься ли ты в Азерот и поможешь ли нам?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Сила и честь, |3-6($c). В Альтеракской долине нужны такие солдаты, как ты. Мы должны защитить территорию клана Северного Волка! Вернешься ли ты в Азерот и поможешь ли нам?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10571,'$R! Да, ты! Зачем тебе тратить время, шатаясь по этим развалинам, ведь твое место – в Низине Арати? Напор Лиги Аратора очень силен, нужна твоя помощь, и награда ждать не заставит!','$r! Да, ты! Зачем тебе тратить время, шатаясь по этим развалинам, ведь твое место – в Низине Арати? Напор Лиги Аратора очень силен, нужна твоя помощь, и награда ждать не заставит!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','$R! Да, ты! Зачем тебе тратить время, шатаясь по этим развалинам, ведь твое место – в Низине Арати? Напор Лиги Аратора очень силен, нужна твоя помощь, и награда ждать не заставит!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','$r! Да, ты! Зачем тебе тратить время, шатаясь по этим развалинам, ведь твое место – в Низине Арати? Напор Лиги Аратора очень силен, нужна твоя помощь, и награда ждать не заставит!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10572,'$C, там, в Азероте, Среброкрылые Часовые препятствуют нашему продвижению в лесах. Нам нужна твоя помощь на поле боя, чтобы отбросить их назад! Ты завоюешь великую славу и репутацию среди Всадников Песни Войны, если поможешь нам, – присоединяйся!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','$C, там, в Азероте, Среброкрылые Часовые препятствуют нашему продвижению в лесах. Нам нужна твоя помощь на поле боя, чтобы отбросить их назад! Ты завоюешь великую славу и репутацию среди Всадников Песни Войны, если поможешь нам, – присоединяйся!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10573,'Спасайся, |3-6($r). Беги отсюда! Кровавая Печать уничтожит тебя на месте, если обнаружит!','Спасайся, |3-6($r). Беги отсюда! Кровавая Печать уничтожит тебя на месте, если обнаружит!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Спасайся, |3-6($r). Беги отсюда! Кровавая Печать уничтожит тебя на месте, если обнаружит!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Спасайся, |3-6($r). Беги отсюда! Кровавая Печать уничтожит тебя на месте, если обнаружит!',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10576,'Вскоре начнется состязание Боевого Круга Хитрой Шестеренки. Сейчас у них на аренах идут тренировочные схватки, а состязание начинается в $4262d.','Вскоре начнется состязание Боевого Круга Хитрой Шестеренки. Сейчас у них на аренах идут тренировочные схватки, а состязание начинается в $4262d.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вскоре начнется состязание Боевого Круга Хитрой Шестеренки. Сейчас у них на аренах идут тренировочные схватки, а состязание начинается в $4262d.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Вскоре начнется состязание Боевого Круга Хитрой Шестеренки. Сейчас у них на аренах идут тренировочные схватки, а состязание начинается в $4262d.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10578,'Боевой Круг Хитрой Шестеренки начался. Ты можешь найти организаторов боев на арене, продающих хартии командам, в Прибамбасске, у арен в Награнде и в Острогорье.','Боевой Круг Хитрой Шестеренки начался. Ты можешь найти организаторов боев на арене, продающих хартии командам, в Прибамбасске, у арен в Награнде и в Острогорье.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Боевой Круг Хитрой Шестеренки начался. Ты можешь найти организаторов боев на арене, продающих хартии командам, в Прибамбасске, у арен в Награнде и в Острогорье.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Боевой Круг Хитрой Шестеренки начался. Ты можешь найти организаторов боев на арене, продающих хартии командам, в Прибамбасске, у арен в Награнде и в Острогорье.',`text0_1_loc8`);
