INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10597,'<Седой гладиатор говорит на ломаном всеобщем: "Что? Проблемы? Решим их на арене. Мне жалко времени на все эти ваши "орды" и "альянсы".>"') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Седой гладиатор говорит на ломаном всеобщем: "Что? Проблемы? Решим их на арене. Мне жалко времени на все эти ваши "орды" и "альянсы".>"',`text0_0_loc8`);
