INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10598,'Гладиаторы заслуживают право носить доспехи, подобные моим, побеждая на арене.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Гладиаторы заслуживают право носить доспехи, подобные моим, побеждая на арене.',`text0_0_loc8`);
