INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10600,'Гладиаторы заслуживают право носить доспехи, подобные моим, побеждая на арене.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Гладиаторы заслуживают право носить доспехи, подобные моим, побеждая на арене.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10602,'Привет. Отдыхаешь, инспектор? Теперь мы нечасто видим тебя тут, с тех пор как тебя перевели в Чащобу Рууан.$B$BВзгляни на то, что у меня есть. Может быть, оно и не поменялось с прошлого нашего разговора, но у меня его много.$B$BИ не будет таким букой!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Привет. Отдыхаешь, инспектор? Теперь мы нечасто видим тебя тут, с тех пор как тебя перевели в Чащобу Рууан.$B$BВзгляни на то, что у меня есть. Может быть, оно и не поменялось с прошлого нашего разговора, но у меня его много.$B$BИ не будет таким букой!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10603,'Больше, чем помехи, я ненавижу лишь Груула Драконобоя и семь его сыновей!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Больше, чем помехи, я ненавижу лишь Груула Драконобоя и семь его сыновей!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10604,'Соревнования на арене начнутся через $4262d. Будущие чемпионы уже вовсю тренируются и подбирают себе самое лучшее оружие. А $gготов:готова; ли ты?','Соревнования на арене начнутся через $4262d. Будущие чемпионы уже вовсю тренируются и подбирают себе самое лучшее оружие. А $gготов:готова; ли ты?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Соревнования на арене начнутся через $4262d. Будущие чемпионы уже вовсю тренируются и подбирают себе самое лучшее оружие. А $gготов:готова; ли ты?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Соревнования на арене начнутся через $4262d. Будущие чемпионы уже вовсю тренируются и подбирают себе самое лучшее оружие. А $gготов:готова; ли ты?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (10605,'Ты $gдолжен:должна; освободить… моих детей…') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты $gдолжен:должна; освободить… моих детей…',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10606,'Они недолго продержатся! Их крылья скоро…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Они недолго продержатся! Их крылья скоро…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (10610,'Застава Хребтолома – отличное место! Эти ублюдки из Кровавой Глазницы так близко, что чуешь запах их вонючей крови! Самое подходящее место, чтобы покарать клан, отрекшийся от братьев и заключивший договор с демонами!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Застава Хребтолома – отличное место! Эти ублюдки из Кровавой Глазницы так близко, что чуешь запах их вонючей крови! Самое подходящее место, чтобы покарать клан, отрекшийся от братьев и заключивший договор с демонами!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10613,'Здравствуй, $gсмертный:смертная;.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здравствуй, $gсмертный:смертная;.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10614,'На востоке Полей Крыльев Пустоты находится крепость Драконьей Пасти. Именно там жестокий орочий клан Драконьей Пасти мучает пленных драконов, пытаясь сломить их волю. Многие теряют надежду и соглашаются выполнять приказы Драконьей Пасти. Другие… они отказываются приземляться, боясь, что боевые отряды орков схватят их и утащат в крепость.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','На востоке Полей Крыльев Пустоты находится крепость Драконьей Пасти. Именно там жестокий орочий клан Драконьей Пасти мучает пленных драконов, пытаясь сломить их волю. Многие теряют надежду и соглашаются выполнять приказы Драконьей Пасти. Другие… они отказываются приземляться, боясь, что боевые отряды орков схватят их и утащат в крепость.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10615,'Я… Мы бессильны. Иллидан нашел и доставил в Драконью Пасть их лидера – Зулухеда. Этот орк ответственен за пленение и заключение в оковы Алекстразы. Как мы могли сражаться против такой силы? Он захватил Аспект!$B$BИ с такой же легкостью он пленил мою подругу…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я… Мы бессильны. Иллидан нашел и доставил в Драконью Пасть их лидера – Зулухеда. Этот орк ответственен за пленение и заключение в оковы Алекстразы. Как мы могли сражаться против такой силы? Он захватил Аспект!$B$BИ с такой же легкостью он пленил мою подругу…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (10625,'Борьба против Кель\'таса и Иллидана продолжается на всех фронтах. О поражении и речи быть не может.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Борьба против Кель\'таса и Иллидана продолжается на всех фронтах. О поражении и речи быть не может.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10631,'Насколько я понимаю, ты с нами недавно и можешь не знать всех наших традиций. В Лунной поляне сейчас проходит пышное празднество. В это время года мы воздаем должное нашим предкам; отпразднуй с нами и ты! Если желаешь поучаствовать в празднике, отправляйся в один из наших городов!','Насколько я понимаю, ты с нами недавно и можешь не знать всех наших традиций. В Лунной поляне сейчас проходит пышное празднество. В это время года мы воздаем должное нашим предкам; отпразднуй с нами и ты! Если желаешь поучаствовать в празднике, отправляйся в один из наших городов!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Насколько я понимаю, ты с нами недавно и можешь не знать всех наших традиций. В Лунной поляне сейчас проходит пышное празднество. В это время года мы воздаем должное нашим предкам; отпразднуй с нами и ты! Если желаешь поучаствовать в празднике, отправляйся в один из наших городов!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Насколько я понимаю, ты с нами недавно и можешь не знать всех наших традиций. В Лунной поляне сейчас проходит пышное празднество. В это время года мы воздаем должное нашим предкам; отпразднуй с нами и ты! Если желаешь поучаствовать в празднике, отправляйся в один из наших городов!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10634,'В Азероте полным ходом идет Лунный фестиваль! Вернись туда и воздай должное своим предкам! Главные торжества проходят в Лунной поляне, мы отправляем туда желающих из Штормграда, Стальгорна, Дарнаса, Громового Утеса, Оргриммара и Подгорода. Надеемся, что и ты будешь там!','В Азероте полным ходом идет Лунный фестиваль! Вернись туда и воздай должное своим предкам! Главные торжества проходят в Лунной поляне, мы отправляем туда желающих из Штормграда, Стальгорна, Дарнаса, Громового Утеса, Оргриммара и Подгорода. Надеемся, что и ты будешь там!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','В Азероте полным ходом идет Лунный фестиваль! Вернись туда и воздай должное своим предкам! Главные торжества проходят в Лунной поляне, мы отправляем туда желающих из Штормграда, Стальгорна, Дарнаса, Громового Утеса, Оргриммара и Подгорода. Надеемся, что и ты будешь там!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','В Азероте полным ходом идет Лунный фестиваль! Вернись туда и воздай должное своим предкам! Главные торжества проходят в Лунной поляне, мы отправляем туда желающих из Штормграда, Стальгорна, Дарнаса, Громового Утеса, Оргриммара и Подгорода. Надеемся, что и ты будешь там!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10636,'Это место скрывает тайны, которые мы, орки, отчаялись раскрыть. Тайны нашего прошлого, тайны нашего будущего, тайны, проблескивающие у нас внутри.$B$BЯ надеюсь разгадать их… Пройдешь ли ты этот путь со мной?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Это место скрывает тайны, которые мы, орки, отчаялись раскрыть. Тайны нашего прошлого, тайны нашего будущего, тайны, проблескивающие у нас внутри.$B$BЯ надеюсь разгадать их… Пройдешь ли ты этот путь со мной?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10637,'В лесу неспокойно. Мы должны выяснить, в чем дело, пока не стало слишком поздно!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','В лесу неспокойно. Мы должны выяснить, в чем дело, пока не стало слишком поздно!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10640,'Скоро я пущу корни и засну. Но прежде чем я погружусь в отдых, мне нужно сделать некоторые дела…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Скоро я пущу корни и засну. Но прежде чем я погружусь в отдых, мне нужно сделать некоторые дела…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10641,'Ты на короткое время $gпринес:принесла; зелень на мою землю. Этого достаточно. Я в умиротворении и могу готовиться к долгому сну…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты на короткое время $gпринес:принесла; зелень на мою землю. Этого достаточно. Я в умиротворении и могу готовиться к долгому сну…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10645,'Нас окружают наши враги. Я хотел лучшей жизни для потомков Мок\'Натала, но силы, с которыми мы сражаемся, не оставляют нам другого выбора.$B$BЕсли ты хочешь показаться $gдостойным:достойной; Мок\'Натала, помоги нам их уничтожить.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Нас окружают наши враги. Я хотел лучшей жизни для потомков Мок\'Натала, но силы, с которыми мы сражаемся, не оставляют нам другого выбора.$B$BЕсли ты хочешь показаться $gдостойным:достойной; Мок\'Натала, помоги нам их уничтожить.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10647,'Что, $gнезнакомец:незнакомка; пытаешься понять, что это?$B$BМы возносим хвалу духам наших предков, поддерживая огонь в их честь и оказывая почести.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что, $gнезнакомец:незнакомка; пытаешься понять, что это?$B$BМы возносим хвалу духам наших предков, поддерживая огонь в их честь и оказывая почести.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
