INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10655,'Рад видеть тебя снова, $gдруг:подруга;.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Рад видеть тебя снова, $gдруг:подруга;.',`text0_0_loc8`);
