INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10657,'Приятно прогуляться и размять конечности. Я могу тебе чем-нибудь помочь, |3-6($c)?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приятно прогуляться и размять конечности. Я могу тебе чем-нибудь помочь, |3-6($c)?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10661,'Поиски моего народа. Наша борьба против Альянса. Война с ограми и владыками гроннов.$B$BВсе это тяжким грузом лежит на моих плечах, |3-6($c).$B$BДаже мне время от времени не помешала бы помощь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Поиски моего народа. Наша борьба против Альянса. Война с ограми и владыками гроннов.$B$BВсе это тяжким грузом лежит на моих плечах, |3-6($c).$B$BДаже мне время от времени не помешала бы помощь.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10662,'Аукиндон – дом духов моих предков. Может, со стороны и не похоже, но все Сломленные когда-то были дренеями… духи у нас одинаковые.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Аукиндон – дом духов моих предков. Может, со стороны и не похоже, но все Сломленные когда-то были дренеями… духи у нас одинаковые.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10664,'Кузницей Смерти управляет Совет Теней, под бдительным оком Легиона.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Кузницей Смерти управляет Совет Теней, под бдительным оком Легиона.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10666,'То, что находится внизу, по праву именуется Кузницей Смерти. Если предоставить их самим себе, Совет Теней будет снабжать Легион бесчисленным множеством инферналов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','То, что находится внизу, по праву именуется Кузницей Смерти. Если предоставить их самим себе, Совет Теней будет снабжать Легион бесчисленным множеством инферналов.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (10670,'Боюсь, я мало чему могу тебя научить, |3-6($c). Ты, конечно, можешь посмотреть мои товары, но не найдешь среди них ничего полезного.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Боюсь, я мало чему могу тебя научить, |3-6($c). Ты, конечно, можешь посмотреть мои товары, но не найдешь среди них ничего полезного.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (10672,'Если ты не портной, вряд ли тебя заинтересуют мои выкройки, но если хочешь – смотри…') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Если ты не портной, вряд ли тебя заинтересуют мои выкройки, но если хочешь – смотри…',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10674,'Извини, |3-6($c), но мои товары лучше всего подходят тем, кто знает, в какой конец иголки вставляется нитка.$B$BУверяю тебя, портняжное дело – это гораздо больше, чем просто вышивание монограмм на носовых платках.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Извини, |3-6($c), но мои товары лучше всего подходят тем, кто знает, в какой конец иголки вставляется нитка.$B$BУверяю тебя, портняжное дело – это гораздо больше, чем просто вышивание монограмм на носовых платках.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (10675,'Эти Слезы Богини были благословлены Элуной. Их сила поможет тебе бороться с мерзкими колдунишками Архимонда. Используй силу Слез разумно.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Эти Слезы Богини были благословлены Элуной. Их сила поможет тебе бороться с мерзкими колдунишками Архимонда. Используй силу Слез разумно.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10677,'Эти пустоши изуродованы чудовищной магией. Мы должны сделать все, что сможем, для исцеления этих ран…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эти пустоши изуродованы чудовищной магией. Мы должны сделать все, что сможем, для исцеления этих ран…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10679,'Двери Смерти – это портал, который открывается в тот мир, куда хочет проникнуть Пылающий Легион со всеми своими гончими Скверны и прочими чудовищами. Если вы увидите такое существо, то не сомневайтесь, что оно пришло именно оттуда и именно через портал.$B$BНедавно мы узнали, что Пылающий Легион научился призывать своих псов прямо через портал, поэтому Двери Смерти нужно непременно закрыть, пока чудовища не наводнили весь наш мир!','Двери Смерти – это портал, который открывается в тот мир, куда хочет проникнуть Пылающий Легион со всеми своими гончими Скверны и прочими чудовищами. Если вы увидите такое существо, то не сомневайтесь, что оно пришло именно оттуда и именно через портал.$B$BНедавно мы узнали, что Пылающий Легион научился призывать своих псов прямо через портал, поэтому Двери Смерти нужно непременно закрыть, пока чудовища не наводнили весь наш мир!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Двери Смерти – это портал, который открывается в тот мир, куда хочет проникнуть Пылающий Легион со всеми своими гончими Скверны и прочими чудовищами. Если вы увидите такое существо, то не сомневайтесь, что оно пришло именно оттуда и именно через портал.$B$BНедавно мы узнали, что Пылающий Легион научился призывать своих псов прямо через портал, поэтому Двери Смерти нужно непременно закрыть, пока чудовища не наводнили весь наш мир!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Двери Смерти – это портал, который открывается в тот мир, куда хочет проникнуть Пылающий Легион со всеми своими гончими Скверны и прочими чудовищами. Если вы увидите такое существо, то не сомневайтесь, что оно пришло именно оттуда и именно через портал.$B$BНедавно мы узнали, что Пылающий Легион научился призывать своих псов прямо через портал, поэтому Двери Смерти нужно непременно закрыть, пока чудовища не наводнили весь наш мир!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10680,'Я пришел, чтобы очистить эти земли от неупокоенных духов, но после первого же боя понял, что мне не справиться. Столько народу попало в беду… Пожалуйста, помогите им.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я пришел, чтобы очистить эти земли от неупокоенных духов, но после первого же боя понял, что мне не справиться. Столько народу попало в беду… Пожалуйста, помогите им.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10682,'Да ведет тебя Свет, $n!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да ведет тебя Свет, $n!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10683,'Я с гордостью предоставляю свои услуги Оплоту Чести.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я с гордостью предоставляю свои услуги Оплоту Чести.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`,`text4_1_loc8`) VALUES (10686,'Когда я впервые основала Академию разбойников в Шаттрате, там было далеко не так тесно. А потом начали прибывать беженцы, и наару понадобились все свободные здания, чтобы их разместить.$B$BСейчас двери моей академии закрыты, но это не навсегда. Я найду для нее новое место.$B$BА потом новое поколение разбойников изучит такие важные приемы, как обман с улыбкой, боевой грабеж и обвинение другого в сбое превращения. И разве можно забыть главное правило разбоя – настоящие разбойники не промахиваются.','Всегда имейте при себе запас воспламеняющегося порошка, особенно когда собираетесь поработать в команде! Вот увидите, он обязательно у кого-нибудь закончится!$b$bКогда дело доходит до выбора – поделиться материалами или дать товарищу умереть, то я всегда делюсь! Ну, почти всегда.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Когда я впервые основала Академию разбойников в Шаттрате, там было далеко не так тесно. А потом начали прибывать беженцы, и наару понадобились все свободные здания, чтобы их разместить.$B$BСейчас двери моей академии закрыты, но это не навсегда. Я найду для нее новое место.$B$BА потом новое поколение разбойников изучит такие важные приемы, как обман с улыбкой, боевой грабеж и обвинение другого в сбое превращения. И разве можно забыть главное правило разбоя – настоящие разбойники не промахиваются.',`text0_1_loc8`), `text4_1_loc8`=IF(`text4_1_loc8` IS NULL OR `text4_1_loc8`='','Всегда имейте при себе запас воспламеняющегося порошка, особенно когда собираетесь поработать в команде! Вот увидите, он обязательно у кого-нибудь закончится!$b$bКогда дело доходит до выбора – поделиться материалами или дать товарищу умереть, то я всегда делюсь! Ну, почти всегда.',`text4_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10691,'Раньше я принимал вызовы от кого угодно, но давно уже устал от таких легких побед.$B$BТеперь я пытаюсь торговать реагентами и пишу книгу о том, что было со мной в Сумеречном Молоте.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Раньше я принимал вызовы от кого угодно, но давно уже устал от таких легких побед.$B$BТеперь я пытаюсь торговать реагентами и пишу книгу о том, что было со мной в Сумеречном Молоте.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10696,'Действительно, наш городской алхимик Лороким привез с собой свое оборудование. Оно может оказаться немного непривычным для тебя, – в конце концов, он араккоа, – но оно может удовлетворить твои потребности. Он обитает в северо-западной части нижнего города.','Действительно, наш городской алхимик Лороким привез с собой свое оборудование. Оно может оказать немного непривычным для тебя, – в конце концов, он араккоа, – но оно может удовлетворить твои потребности. Он обитает в северо-западной части нижнего города.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Действительно, наш городской алхимик Лороким привез с собой свое оборудование. Оно может оказаться немного непривычным для тебя, – в конце концов, он араккоа, – но оно может удовлетворить твои потребности. Он обитает в северо-западной части нижнего города.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Действительно, наш городской алхимик Лороким привез с собой свое оборудование. Оно может оказать немного непривычным для тебя, – в конце концов, он араккоа, – но оно может удовлетворить твои потребности. Он обитает в северо-западной части нижнего города.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10697,'Здесь проживают двое торговцев самоцветами: один близко сотрудничает с Провидцами, а другой верен Алдорам. Какой из них тебе нужен?','Здесь проживают двое торговцев самоцветами: один близко сотрудничает с Провидцами, а другой верен Алдорам. Какой из них тебе нужен?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здесь проживают двое торговцев самоцветами: один близко сотрудничает с Провидцами, а другой верен Алдорам. Какой из них тебе нужен?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Здесь проживают двое торговцев самоцветами: один близко сотрудничает с Провидцами, а другой верен Алдорам. Какой из них тебе нужен?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10698,'Инессера – весьма умная женщина, торгующая как самоцветами, так и инструментом для ювелиров. Найти ее лавку можно в северной части Возвышенности Алдоров.','Инессера – весьма умная женщина, торгующая как самоцветами, так и инструментом для ювелиров. Найти ее лавку можно в северной части Возвышенности Алдоров.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Инессера – весьма умная женщина, торгующая как самоцветами, так и инструментом для ювелиров. Найти ее лавку можно в северной части Возвышенности Алдоров.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Инессера – весьма умная женщина, торгующая как самоцветами, так и инструментом для ювелиров. Найти ее лавку можно в северной части Возвышенности Алдоров.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10699,'Лизрита может поначалу немного... пугать, но у нее есть то, что ты ищешь. Она торгует в восточной части Яруса Провидцев.','Лизрита может поначалу немного... пугать, но у нее есть то, что ты ищешь. Она торгует в восточной части Яруса Провидцев.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Лизрита может поначалу немного... пугать, но у нее есть то, что ты ищешь. Она торгует в восточной части Яруса Провидцев.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Лизрита может поначалу немного... пугать, но у нее есть то, что ты ищешь. Она торгует в восточной части Яруса Провидцев.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10701,'*Волшебный Страж показывает в северо-западную часть города, где обитают араккоа Шаттрата.*') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','*Волшебный Страж показывает в северо-западную часть города, где обитают араккоа Шаттрата.*',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10702,'*Фигура показывает в восточную часть ряда.*') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','*Фигура показывает в восточную часть ряда.*',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10705,'Я не буду обучать вас, пока дренеи не будут вас превозносить.','Я не буду обучать вас, пока дренеи не будут вас превозносить.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я не буду обучать вас, пока дренеи не будут вас превозносить.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я не буду обучать вас, пока дренеи не будут вас превозносить.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10706,'О, благодарю тебя! Бездонная пропасть во мне закрылась! Я снова могу видеть… и вижу лицо $gмоего спасителя:моей спасительницы;!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','О, благодарю тебя! Бездонная пропасть во мне закрылась! Я снова могу видеть… и вижу лицо $gмоего спасителя:моей спасительницы;!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10707,'Уходи, |3-6($c)! Оставь нас, или мы войдем в тебя и покажем, что такое настоящее отчаяние!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Уходи, |3-6($c)! Оставь нас, или мы войдем в тебя и покажем, что такое настоящее отчаяние!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10717,'Не волнуйся. Парящая застава вполне крепка. Но на всякий случай будь $gготов:готова; вскочить на грифона, если основание начнет рушиться…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не волнуйся. Парящая застава вполне крепка. Но на всякий случай будь $gготов:готова; вскочить на грифона, если основание начнет рушиться…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10718,'Теперь, когда вы одержали надо мной верх, проверьте ваши умения в бою против друг друга! Возьмите под контроль одного из королей, чтобы начать игру.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Теперь, когда вы одержали надо мной верх, проверьте ваши умения в бою против друг друга! Возьмите под контроль одного из королей, чтобы начать игру.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10720,'Хочешь поговорить со мной, |3-6($r)?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Хочешь поговорить со мной, |3-6($r)?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10721,'Я немало опасностей видел в этих пустынных землях. Кто знает, что за существа таятся в пыли, готовые напасть на неосторожного путника?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я немало опасностей видел в этих пустынных землях. Кто знает, что за существа таятся в пыли, готовые напасть на неосторожного путника?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10722,'У вас недостаточно репутации, или вы не давали клятву верности Алдорам.','У вас недостаточно репутации, или вы не давали клятву верности Алдорам.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','У вас недостаточно репутации, или вы не давали клятву верности Алдорам.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','У вас недостаточно репутации, или вы не давали клятву верности Алдорам.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (10729,'Конфликты в Запределье повлекли за собой множество смертей. А больше всего страдают от войны дети. Об этом часто забывают.$B$BТеперь когда Шаттрату угрожают араккоа Скеттиса, вероятно, появится еще больше сирот, о которых нужно заботиться. Эти дети часто живут без всякой надежды на светлое будущее.$b$bНо ты можешь кое-что сделать для них. Сейчас идет Детская неделя, |3-6($c), и я прошу тебя взять шефство над кем-то из сирот. Ты можешь сделать жизнь ребенка немного радостнее.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Конфликты в Запределье повлекли за собой множество смертей. А больше всего страдают от войны дети. Об этом часто забывают.$B$BТеперь когда Шаттрату угрожают араккоа Скеттиса, вероятно, появится еще больше сирот, о которых нужно заботиться. Эти дети часто живут без всякой надежды на светлое будущее.$b$bНо ты можешь кое-что сделать для них. Сейчас идет Детская неделя, |3-6($c), и я прошу тебя взять шефство над кем-то из сирот. Ты можешь сделать жизнь ребенка немного радостнее.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10730,'Мне одиноко. Как бы мне хотелось, чтобы здесь были дети моего возраста. Иногда я скучаю по приюту в Шаттрате…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мне одиноко. Как бы мне хотелось, чтобы здесь были дети моего возраста. Иногда я скучаю по приюту в Шаттрате…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`,`text1_1_loc8`,`text2_1_loc8`,`text3_1_loc8`,`text4_1_loc8`,`text5_1_loc8`,`text6_1_loc8`,`text7_1_loc8`) VALUES (10732,'Мы уже пришли?','Если демоны падшие, откуда они упали?','Мне надо помыться. *принюхивается* И тебе тоже!','А таурен-паладин был бы священной коровой?','Это платье меня не полнит?','Я уверена, что в глубине души Иллидан не такой уж плохой. Просто ему тоже нужна мама.','Спорим, мороженое было бы вкуснее, если бы в него можно было вставлять самоцветы?','У мальчиков – букашки, у девочек – кудряшки!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мы уже пришли?',`text0_1_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Если демоны падшие, откуда они упали?',`text1_1_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Мне надо помыться. *принюхивается* И тебе тоже!',`text2_1_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','А таурен-паладин был бы священной коровой?',`text3_1_loc8`), `text4_1_loc8`=IF(`text4_1_loc8` IS NULL OR `text4_1_loc8`='','Это платье меня не полнит?',`text4_1_loc8`), `text5_1_loc8`=IF(`text5_1_loc8` IS NULL OR `text5_1_loc8`='','Я уверена, что в глубине души Иллидан не такой уж плохой. Просто ему тоже нужна мама.',`text5_1_loc8`), `text6_1_loc8`=IF(`text6_1_loc8` IS NULL OR `text6_1_loc8`='','Спорим, мороженое было бы вкуснее, если бы в него можно было вставлять самоцветы?',`text6_1_loc8`), `text7_1_loc8`=IF(`text7_1_loc8` IS NULL OR `text7_1_loc8`='','У мальчиков – букашки, у девочек – кудряшки!',`text7_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`,`text1_1_loc8`,`text2_1_loc8`,`text3_1_loc8`,`text4_1_loc8`,`text5_1_loc8`,`text6_1_loc8`,`text7_1_loc8`) VALUES (10734,'Почему Запределье больше не зовется Дренором?','Скажи, а Круговерть Пустоты похожа на крендель? А что такое преисподняя? Хозяйка приюта сказала, что нельзя спрашивать людей про исподнее…','Мы уже пришли?','Если я задержу дыхание, какого я стану цвета?','Если можно подковать лошадь, то почему нельзя подковать дренея?','Если Пылающий Легион – такая проблема, почему бы просто не вылить на них воды? Тогда они станут просто Легионом…','Как у тебя получается столько есть и пить и ни капельки не толстеть?','А правда, что наару выключает Свет, когда хочет спать?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Почему Запределье больше не зовется Дренором?',`text0_1_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Скажи, а Круговерть Пустоты похожа на крендель? А что такое преисподняя? Хозяйка приюта сказала, что нельзя спрашивать людей про исподнее…',`text1_1_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Мы уже пришли?',`text2_1_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','Если я задержу дыхание, какого я стану цвета?',`text3_1_loc8`), `text4_1_loc8`=IF(`text4_1_loc8` IS NULL OR `text4_1_loc8`='','Если можно подковать лошадь, то почему нельзя подковать дренея?',`text4_1_loc8`), `text5_1_loc8`=IF(`text5_1_loc8` IS NULL OR `text5_1_loc8`='','Если Пылающий Легион – такая проблема, почему бы просто не вылить на них воды? Тогда они станут просто Легионом…',`text5_1_loc8`), `text6_1_loc8`=IF(`text6_1_loc8` IS NULL OR `text6_1_loc8`='','Как у тебя получается столько есть и пить и ни капельки не толстеть?',`text6_1_loc8`), `text7_1_loc8`=IF(`text7_1_loc8` IS NULL OR `text7_1_loc8`='','А правда, что наару выключает Свет, когда хочет спать?',`text7_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10736,'Гезхе очень добрый: он разрешил мне пойти сюда в ученики, обучиться всем этим классным штукам.$B$B<Джил понуро опускает голову.>$B$BНо я очень скучаю по своей сестре.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Гезхе очень добрый: он разрешил мне пойти сюда в ученики, обучиться всем этим классным штукам.$B$B<Джил понуро опускает голову.>$B$BНо я очень скучаю по своей сестре.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10745,'*Друид, похоже, глубоко спит, безразличный к окружающему.*') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','*Друид, похоже, глубоко спит, безразличный к окружающему.*',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10746,'Прошу тебя, |3-6($r), поспеши! Они не прекратят преследовать меня! Я не смогу убежать от них даже здесь!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Прошу тебя, |3-6($r), поспеши! Они не прекратят преследовать меня! Я не смогу убежать от них даже здесь!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10752,'Я здесь по приказу принца Хараманда. Странные вещи происходят у подножья Штормовой Вершины…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я здесь по приказу принца Хараманда. Странные вещи происходят у подножья Штормовой Вершины…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10756,'Ву Пинг – мастер древкового оружия. Он тренирует своих учеников в арсенале Веллера в Штормграде.','Ву Пинг – мастер древкового оружия. Он тренирует своих учеников в арсенале Веллера в Штормграде.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ву Пинг – мастер древкового оружия. Он тренирует своих учеников в арсенале Веллера в Штормграде.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ву Пинг – мастер древкового оружия. Он тренирует своих учеников в арсенале Веллера в Штормграде.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10763,'Лучшего мастера топоров, чем Бульвайф, я здесь не знаю! Одноручное оружие, двуручное – он во всем разбирается здорово!','Лучшего мастера топоров, чем Бульвайф, я здесь не знаю! Одноручное оружие, двуручное – он во всем разбирается здорово!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Лучшего мастера топоров, чем Бульвайф, я здесь не знаю! Одноручное оружие, двуручное – он во всем разбирается здорово!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Лучшего мастера топоров, чем Бульвайф, я здесь не знаю! Одноручное оружие, двуручное – он во всем разбирается здорово!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10765,'Бульвайф будет счастлив научить тебя всему, что знает о ружьях сам!','Бульвайф будет счастлив научить тебя всему, что знает о ружьях сам!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Бульвайф будет счастлив научить тебя всему, что знает о ружьях сам!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Бульвайф будет счастлив научить тебя всему, что знает о ружьях сам!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10767,'Если ты хочешь научиться обращению с оружием, я могу помочь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если ты хочешь научиться обращению с оружием, я могу помочь.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10768,'А, ты хочешь получить образование за границей? Я направлю тебя. Расскажи мне, какие оружие разожгло твой интерес.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','А, ты хочешь получить образование за границей? Я направлю тебя. Расскажи мне, какие оружие разожгло твой интерес.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10771,'Эксперты по оружию из Аллеи Чести в Оргриммаре, Сайок и Ханаши, могут научить тебя стрелять из лука. Еще хороша в этом Иледа, эксперт по оружию из Луносвета, ее можно найти на площади Странников.','Мастера боя из Аллеи Чести в Оргриммаре, Сайок и Ханаши, могут научить тебя стрелять из лука. Еще хороша в этом Иледа, эксперт по оружию из Луносвета, ее можно найти на площади Странников.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эксперты по оружию из Аллеи Чести в Оргриммаре, Сайок и Ханаши, могут научить тебя стрелять из лука. Еще хороша в этом Иледа, эксперт по оружию из Луносвета, ее можно найти на площади Странников.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мастера боя из Аллеи Чести в Оргриммаре, Сайок и Ханаши, могут научить тебя стрелять из лука. Еще хороша в этом Иледа, эксперт по оружию из Луносвета, ее можно найти на площади Странников.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10772,'Арчибальд – мастер арбалетов. Он эксперт по оружию, найдешь его в Подгороде, в Квартале Воинов.','Арчибальд – мастер арбалетов. Он эксперт по оружию, найдешь его в Подгороде, в Квартале Воинов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Арчибальд – мастер арбалетов. Он эксперт по оружию, найдешь его в Подгороде, в Квартале Воинов.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Арчибальд – мастер арбалетов. Он эксперт по оружию, найдешь его в Подгороде, в Квартале Воинов.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10777,'Арчибальд, эксперт по оружию Отрекшихся, очень умело обращается с древковым оружием. Его можно найти в Квартале Воинов Подгорода. Еще можно поучиться у Иледы, эксперт по оружию эльфов крови на площади Странников в Луносвете.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Арчибальд, эксперт по оружию Отрекшихся, очень умело обращается с древковым оружием. Его можно найти в Квартале Воинов Подгорода. Еще можно поучиться у Иледы, эксперт по оружию эльфов крови на площади Странников в Луносвете.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10781,'Арчибальд – мастер арбалетов. Он эксперт по оружию, найдешь его в Подгороде, в Квартале Воинов.','Арчибальд – мастер арбалетов. Он эксперт по оружию, найдешь его в Подгороде, в Квартале Воинов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Арчибальд – мастер арбалетов. Он эксперт по оружию, найдешь его в Подгороде, в Квартале Воинов.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Арчибальд – мастер арбалетов. Он эксперт по оружию, найдешь его в Подгороде, в Квартале Воинов.',`text0_1_loc8`);
