INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10783,'Хочешь бить кулаками по всяким штукам, да? Поговори с Сайоком. Он научит тебя.','Хочешь бить кулаками по всяким штукам, да? Поговори с Сайоком. Он научит тебя.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Хочешь бить кулаками по всяким штукам, да? Поговори с Сайоком. Он научит тебя.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Хочешь бить кулаками по всяким штукам, да? Поговори с Сайоком. Он научит тебя.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10784,'Наш наставник – Ансеква – эксперт по оружию тауренов, его можно найти внизу на центральном уступе Громового Утеса.','Наш наставник – Ансеква – эксперт по оружию тауренов, его можно найти внизу на центральном уступе Громового Утеса.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Наш наставник – Ансеква – эксперт по оружию тауренов, его можно найти внизу на центральном уступе Громового Утеса.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Наш наставник – Ансеква – эксперт по оружию тауренов, его можно найти внизу на центральном уступе Громового Утеса.',`text0_1_loc8`);
