INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10785,'Владению ударным оружием обучает Ансеква, который живет в нижней части центрального уступа Громового Утеса.','Владению ударным оружием обучает Ансеква, который живет в нижней части центрального уступа Громового Утеса.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Владению ударным оружием обучает Ансеква, который живет в нижней части центрального уступа Громового Утеса.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Владению ударным оружием обучает Ансеква, который живет в нижней части центрального уступа Громового Утеса.',`text0_1_loc8`);
