INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (10789,'Если ты $gпришел:пришла; не учиться, уйди и оставь меня в покое, мне нужно работать.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Если ты $gпришел:пришла; не учиться, уйди и оставь меня в покое, мне нужно работать.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10791,'Опасайся порождений Эфириума, окруживших нас со всех сторон.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Опасайся порождений Эфириума, окруживших нас со всех сторон.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10792,'Пойдем, и я покажу тебе, как ездить верхом на лучших животных, которых тебе доведется увидеть. У тебя, конечно, хватит золота, чтобы заплатить за это?','Пойдем, и я покажу тебе, как ездить верхом на лучших животных, которых тебе доведется увидеть. У тебя, конечно, хватит золота, чтобы заплатить за это?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Пойдем, и я покажу тебе, как ездить верхом на лучших животных, которых тебе доведется увидеть. У тебя, конечно, хватит золота, чтобы заплатить за это?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Пойдем, и я покажу тебе, как ездить верхом на лучших животных, которых тебе доведется увидеть. У тебя, конечно, хватит золота, чтобы заплатить за это?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (10793,'Добро пожаловать в Вечную рощу, |3-6($c). Времион и я уже некоторое время изучаем араккоа в Острогорье, и мы обнаружили несколько тревожных различий между ними и их родственниками в Тероккаре.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Добро пожаловать в Вечную рощу, |3-6($c). Времион и я уже некоторое время изучаем араккоа в Острогорье, и мы обнаружили несколько тревожных различий между ними и их родственниками в Тероккаре.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10794,'*Призрак араккоа подходит к вам и словно бы пытается узнать. У вас складывается впечатление, что он не очень хорошо видит.*$B$BРоккарам, это ты?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','*Призрак араккоа подходит к вам и словно бы пытается узнать. У вас складывается впечатление, что он не очень хорошо видит.*$B$BРоккарам, это ты?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10795,'Прости меня за вопросы, сын мой. Мое зрение совсем не то, что раньше, хоть ворон и одарил меня долгой жизнью.$B$BВскоре придет время, и ты займешь мое место. Мне удалось передать тебе все свои знания. Я лишь жалею, что мне не позволено было обрести нашу священную Книгу Ворона.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Прости меня за вопросы, сын мой. Мое зрение совсем не то, что раньше, хоть ворон и одарил меня долгой жизнью.$B$BВскоре придет время, и ты займешь мое место. Мне удалось передать тебе все свои знания. Я лишь жалею, что мне не позволено было обрести нашу священную Книгу Ворона.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10796,'Истинные верующие жили в стыде с того дня, когда наши вероломные родственники из Скеттиса украли нашу книгу, сломали ее и закопали обломки в своем проклятом городе!$B$BМолись, чтобы ворон избрал тебя для ее возвращения, сын мой. Будь честен и всегда помни слова пророчества: "Из вражьих снов ворон вылетит в мир".') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Истинные верующие жили в стыде с того дня, когда наши вероломные родственники из Скеттиса украли нашу книгу, сломали ее и закопали обломки в своем проклятом городе!$B$BМолись, чтобы ворон избрал тебя для ее возвращения, сын мой. Будь честен и всегда помни слова пророчества: "Из вражьих снов ворон вылетит в мир".',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10797,'Грок искать помощь. $gМаленький:Маленькая:r; |3-6($r), идти в горы и помогать ограм Кровавого Молота!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Грок искать помощь. $gМаленький:Маленькая:r; |3-6($r), идти в горы и помогать ограм Кровавого Молота!',`text0_0_loc8`);
-- ruRU; source: emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (10798,'Ты идешь смотреть на Могдорна?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты идешь смотреть на Могдорна?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10799,'Я ищу $gгероя:героиню;, $gобладающего:обладающую; непревзойденными умениями. $GОн:Она; соберет других, чтобы спасти клан Кровавого Молота и всех огров этих гор от тирании наших угнетателей гроннов.$B$BВозвращайся ко мне, когда узнаешь все, что сможешь. Но, |3-6($c), держи все это при себе до времени, чтобы гронны не узнали о нашем движении сопротивления.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я ищу $gгероя:героиню;, $gобладающего:обладающую; непревзойденными умениями. $GОн:Она; соберет других, чтобы спасти клан Кровавого Молота и всех огров этих гор от тирании наших угнетателей гроннов.$B$BВозвращайся ко мне, когда узнаешь все, что сможешь. Но, |3-6($c), держи все это при себе до времени, чтобы гронны не узнали о нашем движении сопротивления.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10801,'Я боюсь, полковник Джулс может быть спасен лишь после совершения опасного ритуала, экзорцизма.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я боюсь, полковник Джулс может быть спасен лишь после совершения опасного ритуала, экзорцизма.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10807,'Мои глаза меня обманывают? Это правда ты, брат Роккарам? После всех этих лет?$B$BЕсли ты ищешь Сайкала, он блуждает среди кристаллов в западной части Вершины Смерча. Он занят исследованиями чего-то, как он пишет, "грубого и примитивного", присутствующего там – хоть и кажется, что там все в порядке.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мои глаза меня обманывают? Это правда ты, брат Роккарам? После всех этих лет?$B$BЕсли ты ищешь Сайкала, он блуждает среди кристаллов в западной части Вершины Смерча. Он занят исследованиями чего-то, как он пишет, "грубого и примитивного", присутствующего там – хоть и кажется, что там все в порядке.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (10808,'Ты можешь знать пару-другую вещей о том, как обращаться с животными, но ты когда-нибудь $gвзмывал:взмывала; к небесам? Мы, Громовые Молоты, знаем, как обгонять ветер верхом на наших лучших питомцах. За небольшую плату, если у тебя кишка не тонка, я научу тебя этому, как надо.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты можешь знать пару-другую вещей о том, как обращаться с животными, но ты когда-нибудь $gвзмывал:взмывала; к небесам? Мы, Громовые Молоты, знаем, как обгонять ветер верхом на наших лучших питомцах. За небольшую плату, если у тебя кишка не тонка, я научу тебя этому, как надо.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10817,'Похоже, ты знаешь, как обращаться с животными, летающими над землей, но если ты хочешь стать хорошим пилотом, тебе придется самоотверженно тренироваться. И платить деньги. У тебя ведь есть деньги, да?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Похоже, ты знаешь, как обращаться с животными, летающими над землей, но если ты хочешь стать хорошим пилотом, тебе придется самоотверженно тренироваться. И платить деньги. У тебя ведь есть деньги, да?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (10818,'Прекрасные животные, правда? Взращенные нами виверны обучены справляться с самыми жесткими и странными погодными условиями, что только бывают в Дреноре. Ты убедишься в надежности и отваге этих животных.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Прекрасные животные, правда? Взращенные нами виверны обучены справляться с самыми жесткими и странными погодными условиями, что только бывают в Дреноре. Ты убедишься в надежности и отваге этих животных.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10821,'Когда я вырасту, я хочу стать кожевником!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Когда я вырасту, я хочу стать кожевником!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (10837,'Шшш! Тише. Детки спят.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Шшш! Тише. Детки спят.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text3_0_loc8`,`text5_0_loc8`,`text6_0_loc8`,`text7_0_loc8`) VALUES (10838,'Да, $gкороль:королева;?','Ты $gубил:убила; гронна! Теперь будешь сражаться с тварями с неба?','Это хороший напиток!','$Gкороль:королева; не гневается на меня?','Чего вы на меня так смотрите?! Целоваться я с вами не буду!','Слушайте, Сыны Груула! Теперь $gновый:новая; $gкороль:королева; поведет всех огров Огри\'лы!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да, $gкороль:королева;?',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Ты $gубил:убила; гронна! Теперь будешь сражаться с тварями с неба?',`text1_0_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Это хороший напиток!',`text3_0_loc8`), `text5_0_loc8`=IF(`text5_0_loc8` IS NULL OR `text5_0_loc8`='','$Gкороль:королева; не гневается на меня?',`text5_0_loc8`), `text6_0_loc8`=IF(`text6_0_loc8` IS NULL OR `text6_0_loc8`='','Чего вы на меня так смотрите?! Целоваться я с вами не буду!',`text6_0_loc8`), `text7_0_loc8`=IF(`text7_0_loc8` IS NULL OR `text7_0_loc8`='','Слушайте, Сыны Груула! Теперь $gновый:новая; $gкороль:королева; поведет всех огров Огри\'лы!',`text7_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10842,'Предсказателя Джавада ищите на восточной стороне Великой Кузни, это чуть к северу по восточной стороне. Все ясно?','Предсказателя Джавада ищите на восточной стороне Великой Кузни, это чуть к северу по восточной стороне. Все ясно?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Предсказателя Джавада ищите на восточной стороне Великой Кузни, это чуть к северу по восточной стороне. Все ясно?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Предсказателя Джавада ищите на восточной стороне Великой Кузни, это чуть к северу по восточной стороне. Все ясно?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10846,'Я могу обучить вас ювелирному делу. Не угодно ли?','Я могу обучить вас ювелирному делу. Не угодно ли?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я могу обучить вас ювелирному делу. Не угодно ли?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я могу обучить вас ювелирному делу. Не угодно ли?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10847,'Что твоя хотеть? Пахнуть странно для орк Скверна…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что твоя хотеть? Пахнуть странно для орк Скверна…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10848,'Твоя не сделать здесь свой дом. Может хотеть поесть что-нибудь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Твоя не сделать здесь свой дом. Может хотеть поесть что-нибудь?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`,`text3_0_loc8`) VALUES (10850,'О ДА! Хочешь отведать этих ружей, насекомое? Поторапливайся!','Как ты состязаешься с этими демонами? О-о-о-о-о, да-а-а-а, брат!','Слышишь? Слышишь это пение, брат? Они приветствуют Ракстера!','Что ты будешь делать, когда Ракс-мания выйдет из-под твоего контроля, брат?!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','О ДА! Хочешь отведать этих ружей, насекомое? Поторапливайся!',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Как ты состязаешься с этими демонами? О-о-о-о-о, да-а-а-а, брат!',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Слышишь? Слышишь это пение, брат? Они приветствуют Ракстера!',`text2_0_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Что ты будешь делать, когда Ракс-мания выйдет из-под твоего контроля, брат?!',`text3_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10854,'$GБрат:Сестра;, теперь ты $gсвязан:связана; с Крыльями Пустоты кровными узами. Все драконы Крыльев Пустоты теперь будет за тебя! Пришло время ударить в сердце наших врагов, друг! Мы должны обрести наше потерянное мужество!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','$GБрат:Сестра;, теперь ты $gсвязан:связана; с Крыльями Пустоты кровными узами. Все драконы Крыльев Пустоты теперь будет за тебя! Пришло время ударить в сердце наших врагов, друг! Мы должны обрести наше потерянное мужество!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10862,'Ха, еще кто-то? Ты никогда этого не сделаешь…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ха, еще кто-то? Ты никогда этого не сделаешь…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10863,'Не забывайте, что каждый день вы можете собирать только что-то одно. Но вообще кристаллы нам всегда нужны, так что их можно приносить в наш лагерь в любое время.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не забывайте, что каждый день вы можете собирать только что-то одно. Но вообще кристаллы нам всегда нужны, так что их можно приносить в наш лагерь в любое время.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10864,'У меня нет ничего нового для тебя, $gпарень:девушка;. Ты уже слишком $gумен:умна; для физического труда.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','У меня нет ничего нового для тебя, $gпарень:девушка;. Ты уже слишком $gумен:умна; для физического труда.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10877,'Не трепись о том, что ты видишь и слышишь в этих местах, |3-6($r).') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не трепись о том, что ты видишь и слышишь в этих местах, |3-6($r).',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10878,'$gКороль:Королева;! Фырк готов служить.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','$gКороль:Королева;! Фырк готов служить.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10879,'Грок слышать, что твоя теперь $gновый:новая; $gкороль:королева; всех огров. Поздар… поздралв… Молодец, $gмаленький:маленькая:r; |3-6($r).') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Грок слышать, что твоя теперь $gновый:новая; $gкороль:королева; всех огров. Поздар… поздралв… Молодец, $gмаленький:маленькая:r; |3-6($r).',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10886,'Добро пожаловать в "Почтенное ателье Килена". Я думаю, мой магазин тебе подойдет. А если хочешь у меня поучиться – только скажи, я с радостью тебя обучу.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать в "Почтенное ателье Килена". Я думаю, мой магазин тебе подойдет. А если хочешь у меня поучиться – только скажи, я с радостью тебя обучу.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (10889,'Если ищешь всякие штуки, штучки, штуковинки, штукенции, прибамбасы, навороты и загогулины, то ты $gпришел:пришла; по адресу!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Если ищешь всякие штуки, штучки, штуковинки, штукенции, прибамбасы, навороты и загогулины, то ты $gпришел:пришла; по адресу!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10892,'Ты выглядишь $gзнакомым:знакомой;…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты выглядишь $gзнакомым:знакомой;…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10893,'Мой разум наполняют видения событий, что происходят по всему миру и тех, что только должны произойти. Многие из них зловещи, но мы не должны верить, что их невозможно изменить.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мой разум наполняют видения событий, что происходят по всему миру и тех, что только должны произойти. Многие из них зловещи, но мы не должны верить, что их невозможно изменить.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10894,'Если тебе нужны реагенты, ты $gпришел:пришла; по адресу. У меня лучший выбор во всем Шаттрате.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если тебе нужны реагенты, ты $gпришел:пришла; по адресу. У меня лучший выбор во всем Шаттрате.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10901,'Стоять смирно, ворчун!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Стоять смирно, ворчун!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10903,'Проклинаю тебя тысячу раз, |3-6($r)! Эта тюрьма не задержит меня надолго!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Проклинаю тебя тысячу раз, |3-6($r)! Эта тюрьма не задержит меня надолго!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10904,'Убирайся, пока я не надавал тебе ботирангов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Убирайся, пока я не надавал тебе ботирангов.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10909,'Горящие глаза наполняют ваш разум ужасом…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Горящие глаза наполняют ваш разум ужасом…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10910,'С помощью хрустальной кузницы Скверны можно трансформировать апекситовые осколки в нестабильные настои Зверя. Эти настои придают ловкости, силы и храбрости.$B$BВыбирайте.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','С помощью хрустальной кузницы Скверны можно трансформировать апекситовые осколки в нестабильные настои Зверя. Эти настои придают ловкости, силы и храбрости.$B$BВыбирайте.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10911,'*"Вы помещаете апекситовые осколки внутрь Хрустальной кузницы Скверны, тянете рычаг, и устройство перемалывает их в пыль, издавая странные звуки. Через несколько мгновений изо "рта" устройства появляется ваш настой."*') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','*"Вы помещаете апекситовые осколки внутрь Хрустальной кузницы Скверны, тянете рычаг, и устройство перемалывает их в пыль, издавая странные звуки. Через несколько мгновений изо "рта" устройства появляется ваш настой."*',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10912,'*"Вы помещаете апекситовые осколки внутрь Хрустальной кузницы Скверны, тянете рычаг, и устройство перемалывает их в пыль, издавая странные звуки. Через несколько мгновений изо "рта" устройства появляется ваши настои."*') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','*"Вы помещаете апекситовые осколки внутрь Хрустальной кузницы Скверны, тянете рычаг, и устройство перемалывает их в пыль, издавая странные звуки. Через несколько мгновений изо "рта" устройства появляется ваши настои."*',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10913,'С помощью хрустальной кузницы Баш\'ира можно превратить апекситовые осколки в нестабильный настой Волшебника. Этот настой придаст ясность мыслей, смелости и повысит эффективность боевых и исцеляющих заклинаний.$B$BВыбирайте.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','С помощью хрустальной кузницы Баш\'ира можно превратить апекситовые осколки в нестабильный настой Волшебника. Этот настой придаст ясность мыслей, смелости и повысит эффективность боевых и исцеляющих заклинаний.$B$BВыбирайте.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10915,'*Когда вы кладете свои осколки апексита в полость в хрустальной кузнице Баш\'ира и тянете за рычаг, устройство буквально расщепляет их на части. Через несколько секунд ваши настои появляются у ваших ног.*') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','*Когда вы кладете свои осколки апексита в полость в хрустальной кузнице Баш\'ира и тянете за рычаг, устройство буквально расщепляет их на части. Через несколько секунд ваши настои появляются у ваших ног.*',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10916,'Мы надеемся, что ты сумеешь избавить нас от головной боли. Шутка ли – десять сыновей, и каждый хочет то, что ему не пристало!$B$BМы, как отец, делаем то, что должны.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы надеемся, что ты сумеешь избавить нас от головной боли. Шутка ли – десять сыновей, и каждый хочет то, что ему не пристало!$B$BМы, как отец, делаем то, что должны.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10917,'У тебя есть сыновья, |3-6($c)?$B$BПозволь нам кое-что тебе сказать: до того, как мы пришли в Огри\'лу и кристаллы сделали нас умнее, жилось нам куда веселей. Раньше мы бы просто стукнули их по голове и заставили умолкнуть. А теперь они целыми днями жужжат нам про Стражу Небес Ша\'тар.$B$BНезнание – сила!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','У тебя есть сыновья, |3-6($c)?$B$BПозволь нам кое-что тебе сказать: до того, как мы пришли в Огри\'лу и кристаллы сделали нас умнее, жилось нам куда веселей. Раньше мы бы просто стукнули их по голове и заставили умолкнуть. А теперь они целыми днями жужжат нам про Стражу Небес Ша\'тар.$B$BНезнание – сила!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10918,'У парня еще не хватает соображалки, чтобы сказать тебе спасибо – он еще недостаточно облучен кристаллами – но он действительно благодарен за то, что ты $gдобыл:добыла; для него эти настои.$B$BТеперь осталось пристроить еще девять сыновей. О-хо-хо!$B$B*Обе головы Торкуса вздыхают.* Хочешь, отдадим одного тебе? Недорого возьмем!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','У парня еще не хватает соображалки, чтобы сказать тебе спасибо – он еще недостаточно облучен кристаллами – но он действительно благодарен за то, что ты $gдобыл:добыла; для него эти настои.$B$BТеперь осталось пристроить еще девять сыновей. О-хо-хо!$B$B*Обе головы Торкуса вздыхают.* Хочешь, отдадим одного тебе? Недорого возьмем!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10921,'Хрустальную кузницу Баш\'ира можно использовать, чтобы преобразовать апекситовые осколки в нестабильные настои Волшебника. Этот настой делает выпившего умнее, крепче и увеличивает эффективность боевой и целительской магии.$B$BПохоже только, что у тебя нет десяти осколков, нужных для создания хотя бы одного настоя.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Хрустальную кузницу Баш\'ира можно использовать, чтобы преобразовать апекситовые осколки в нестабильные настои Волшебника. Этот настой делает выпившего умнее, крепче и увеличивает эффективность боевой и целительской магии.$B$BПохоже только, что у тебя нет десяти осколков, нужных для создания хотя бы одного настоя.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10922,'Хрустальную кузницу Баш\'ира можно использовать, чтобы преобразовать апекситовые осколки в нестабильные настои Волшебника. Этот настой делает выпившего умнее, крепче и увеличивает эффективность боевой и целительской магии.$B$BПохоже только, что у тебя нет десяти осколков, нужных для создания хотя бы одного настоя.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Хрустальную кузницу Баш\'ира можно использовать, чтобы преобразовать апекситовые осколки в нестабильные настои Волшебника. Этот настой делает выпившего умнее, крепче и увеличивает эффективность боевой и целительской магии.$B$BПохоже только, что у тебя нет десяти осколков, нужных для создания хотя бы одного настоя.',`text0_0_loc8`);
-- ruRU; source: emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (10926,'Добро пожаловать в Огри\'лу, $c.$B$B Здешние огры смогли обрести большую остроту мышления благодаря магическим эманациям здешних кристаллов. Хотя мы не вполне понимаем, как они работают, мы стали ценить наше новое место обитания и хотим лишь жить спокойно.$B$BЖаль лишь, что демоны, духи Астрала и в особенности черные драконы не дают нам этого самого покоя.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Добро пожаловать в Огри\'лу, $c.$B$B Здешние огры смогли обрести большую остроту мышления благодаря магическим эманациям здешних кристаллов. Хотя мы не вполне понимаем, как они работают, мы стали ценить наше новое место обитания и хотим лишь жить спокойно.$B$BЖаль лишь, что демоны, духи Астрала и в особенности черные драконы не дают нам этого самого покоя.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (10929,'Нет. Ты еще недостаточно $gсилен:сильна;, чтобы участвовать в соревнованиях. Но ты можешь найти распорядителя арены и поучаствовать в тренировочных схватках. Никогда не рано начать тренироваться.','Нет. Ты еще недостаточно $gсилен:сильна;, чтобы участвовать в соревнованиях. Но ты можешь найти распорядителя арены и поучаствовать в тренировочных схватках. Никогда не рано начать тренироваться.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Нет. Ты еще недостаточно $gсилен:сильна;, чтобы участвовать в соревнованиях. Но ты можешь найти распорядителя арены и поучаствовать в тренировочных схватках. Никогда не рано начать тренироваться.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Нет. Ты еще недостаточно $gсилен:сильна;, чтобы участвовать в соревнованиях. Но ты можешь найти распорядителя арены и поучаствовать в тренировочных схватках. Никогда не рано начать тренироваться.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10931,'Яйцо кажется прочным, как и подобает яйцу черного дракона. Может быть, если бы ты $gпоместил:поместила; очень много осколков апексита рядом с ним, их вибрации заставили бы его расколоться?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Яйцо кажется прочным, как и подобает яйцу черного дракона. Может быть, если бы ты $gпоместил:поместила; очень много осколков апексита рядом с ним, их вибрации заставили бы его расколоться?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10932,'Яйцо выглядит упругим, таким, каким и должно быть яйцо черного дракона. Возможно, поставь вы рядом с ним побольше апекситовых осколков, их дрожь расколола бы яйцо?$B$BЖаль, что нужных для этого 35 апекситовых осколков у вас нет.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Яйцо выглядит упругим, таким, каким и должно быть яйцо черного дракона. Возможно, поставь вы рядом с ним побольше апекситовых осколков, их дрожь расколола бы яйцо?$B$BЖаль, что нужных для этого 35 апекситовых осколков у вас нет.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (10939,'Мы должны вернуть контроль над этими шахтами!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мы должны вернуть контроль над этими шахтами!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10941,'Они послали тебя, чтобы убить меня, да? Так предсказуемо… Существа, управляемые ужасом, все одинаковы.$B$BНо ты… ты не $gодин:одна; из них…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Они послали тебя, чтобы убить меня, да? Так предсказуемо… Существа, управляемые ужасом, все одинаковы.$B$BНо ты… ты не $gодин:одна; из них…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10942,'Инспектор?$B$BЕсли ты инспектор, то я король Штормграда. Да… это я о тебе говорю.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Инспектор?$B$BЕсли ты инспектор, то я король Штормграда. Да… это я о тебе говорю.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10943,'Драконы Крыльев Пустоты. Они говорят с нами. Они предложили нам мир и защиту. То, чего еще никогда не знали Сломленные. Мы приняли их предложение, мы помогли Торанаку разбудить созданий, живущих в этой шахте – и очень дорого за это заплатили. В этой атаке многие из моих братьев отдали свои жизни. Мы пытались сделать шахту непригодной для жизни, вынудить Драконью Пасть уйти и окончательно покинуть остров.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Драконы Крыльев Пустоты. Они говорят с нами. Они предложили нам мир и защиту. То, чего еще никогда не знали Сломленные. Мы приняли их предложение, мы помогли Торанаку разбудить созданий, живущих в этой шахте – и очень дорого за это заплатили. В этой атаке многие из моих братьев отдали свои жизни. Мы пытались сделать шахту непригодной для жизни, вынудить Драконью Пасть уйти и окончательно покинуть остров.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10944,'Клан Драконьей Пасти продажен. Они добывают все естественные ресурсы, которые есть на острове, и используют их для поставок армиям Иллидана из Черного храма. Многое они оставляют себе и продают тому, кто больше заплатит.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Клан Драконьей Пасти продажен. Они добывают все естественные ресурсы, которые есть на острове, и используют их для поставок армиям Иллидана из Черного храма. Многое они оставляют себе и продают тому, кто больше заплатит.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10946,'Я с радостью принесу эту жертву, если она поможет свергнуть Драконью Пасть!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я с радостью принесу эту жертву, если она поможет свергнуть Драконью Пасть!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10947,'Мне нужно немедленно покинуть это место!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мне нужно немедленно покинуть это место!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10948,'Апекситовая реликвия мерцает, выдавая скрытый внутри разум.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Апекситовая реликвия мерцает, выдавая скрытый внутри разум.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10950,'Стойте смирно, капитан!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Стойте смирно, капитан!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10951,'Горящие в глубине призмы глаза наполняют вас ужасом… они знают, что у вас нет 35 апекситовых осколков, чтобы призвать демона.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Горящие в глубине призмы глаза наполняют вас ужасом… они знают, что у вас нет 35 апекситовых осколков, чтобы призвать демона.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10957,'Забудь ты о Викстоне. Хочешь отличный товар? Поговори с Крикселем. У меня есть все, что тебе нужно, если, конечно, у тебя репутация подходящая. Ну, на арене. Товар-то мой не для трусов разных, $gпарень:девушка;.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Забудь ты о Викстоне. Хочешь отличный товар? Поговори с Крикселем. У меня есть все, что тебе нужно, если, конечно, у тебя репутация подходящая. Ну, на арене. Товар-то мой не для трусов разных, $gпарень:девушка;.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10961,'Мы сейчас концентрируемся на тестировании битвы за гору Хиджал. Для участия тебе нужно, по меньшей мере, уважительное отношение Аметистового Ока.$B$BТакую репутацию ты получаешь, пока служишь Каражану.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы сейчас концентрируемся на тестировании битвы за гору Хиджал. Для участия тебе нужно, по меньшей мере, уважительное отношение Аметистового Ока.$B$BТакую репутацию ты получаешь, пока служишь Каражану.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10962,'Теперь, когда ты $gнастроен:настроена; на гору Хиджал, я могу телепортировать тебя в Пещеры Времени. Просто дай мне знать, когда будешь $gготов:готова;.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Теперь, когда ты $gнастроен:настроена; на гору Хиджал, я могу телепортировать тебя в Пещеры Времени. Просто дай мне знать, когда будешь $gготов:готова;.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10964,'Теперь, когда у тебя есть ключ от Черного храма (медальон Карабора), я могу перенести тебя прямо туда. Скажи, когда будешь $gготов:готова;.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Теперь, когда у тебя есть ключ от Черного храма (медальон Карабора), я могу перенести тебя прямо туда. Скажи, когда будешь $gготов:готова;.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10965,'Добро пожаловать, друг! Что ты хочешь увидеть?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать, друг! Что ты хочешь увидеть?',`text0_0_loc8`);
