INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10975,'Мы щедро тебя угостим.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы щедро тебя угостим.',`text0_0_loc8`);
