INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (10976,'Какие яства ты желаешь отведать?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Какие яства ты желаешь отведать?',`text0_1_loc8`);
