INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (10977,'Привет, товарищ. Если хорошо себя зарекомендуешь в Страже Небес, я смогу предложить тебя прямой полет к нашей базе, лагерю Черного Ветра в горах Скетил.$B$BТебе нравится мой красивый скат Пустоты? Он чудесен!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Привет, товарищ. Если хорошо себя зарекомендуешь в Страже Небес, я смогу предложить тебя прямой полет к нашей базе, лагерю Черного Ветра в горах Скетил.$B$BТебе нравится мой красивый скат Пустоты? Он чудесен!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10979,'Привет, $gгосподин:госпожа;! Если хочешь, у меня есть скат Пустоты, готовый тебя доставить на заставу Стражи Небес на вершине Острогорья.$B$BПросто дай мне знать.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Привет, $gгосподин:госпожа;! Если хочешь, у меня есть скат Пустоты, готовый тебя доставить на заставу Стражи Небес на вершине Острогорья.$B$BПросто дай мне знать.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10980,'Доброго тебе дня. Когда ты станешь чуть повыше чином у Стражи Небес Ша\'тар, я смогу предложить тебе полет без пересадок к заставе Стражи Небес, нашу базу на вершине Острогорья.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Доброго тебе дня. Когда ты станешь чуть повыше чином у Стражи Небес Ша\'тар, я смогу предложить тебе полет без пересадок к заставе Стражи Небес, нашу базу на вершине Острогорья.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10983,'Вот наш тайный рецепт счастья – веселись сколько хочешь и пей допьяна! А мы поможем.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вот наш тайный рецепт счастья – веселись сколько хочешь и пей допьяна! А мы поможем.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10984,'Все должны выпить. Чего прикажешь подать?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Все должны выпить. Чего прикажешь подать?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10985,'Приветствую, $Gбрат:сестра;, чем мы можем помочь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приветствую, $Gбрат:сестра;, чем мы можем помочь?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10986,'Наши напитки утолят даже самую сильную жажду.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Наши напитки утолят даже самую сильную жажду.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10987,'Пей или убирайся!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Пей или убирайся!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10989,'Вот это задор, $gпарнишка:девчонка;! Ты заставляешь нас всех гордиться всем тем, что делаешь!$B$BИ знаешь, если ты хочешь быстренько сгонять на другую нашу базу в горах Скетил, спустись и поговори со укротителем Иреной из Стражи Небес. Она это устроит без проблем.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вот это задор, $gпарнишка:девчонка;! Ты заставляешь нас всех гордиться всем тем, что делаешь!$B$BИ знаешь, если ты хочешь быстренько сгонять на другую нашу базу в горах Скетил, спустись и поговори со укротителем Иреной из Стражи Небес. Она это устроит без проблем.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10990,'Да ты так скоро станешь здесь пользоваться почтительным отношением, $gпарень:девушка;! Не знай я тебя лучше, подумал бы, что ты за моей работой охотишься!!!$B$BНу что, если будешь продолжать в том же духе, заслужишь и работу!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да ты так скоро станешь здесь пользоваться почтительным отношением, $gпарень:девушка;! Не знай я тебя лучше, подумал бы, что ты за моей работой охотишься!!!$B$BНу что, если будешь продолжать в том же духе, заслужишь и работу!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (10992,'Я вижу, что ты $gуделял:уделяла; много своего времени здешним делам, |3-6($c).$B$BПродолжай в том же духе; демоны еще не исчезли, новичок.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я вижу, что ты $gуделял:уделяла; много своего времени здешним делам, |3-6($c).$B$BПродолжай в том же духе; демоны еще не исчезли, новичок.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10993,'Чем мы можем служить, $gвозвышенный:возвышенная;?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Чем мы можем служить, $gвозвышенный:возвышенная;?',`text0_0_loc8`);
