INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (10996,'Мы счастливы обеспечить тебя припасами.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы счастливы обеспечить тебя припасами.',`text0_0_loc8`);
