INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11000,'Что ты ищешь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что ты ищешь?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11007,'Эти реликвии – поистине великая тайна. Возможно, если ты будешь прилежно их изучать, то лучше поймешь их предназначение.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эти реликвии – поистине великая тайна. Возможно, если ты будешь прилежно их изучать, то лучше поймешь их предназначение.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11008,'Сталь не так уж сильна, $gвозвышенный:возвышенная;, плоть сильнее. Вся сила оружия – в его владельце. Но довольно об этом... Чем мы можем тебе помочь, $gвозвышенный:возвышенная;?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Сталь не так уж сильна, $gвозвышенный:возвышенная;, плоть сильнее. Вся сила оружия – в его владельце. Но довольно об этом... Чем мы можем тебе помочь, $gвозвышенный:возвышенная;?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11012,'Мало чему вообще можно верить. Стали верить можно.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мало чему вообще можно верить. Стали верить можно.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11013,'Это честь для нас, что $gтакой:такая:r;, как ты, |3-6($r), помогает нам, ограм. Вы сохраняете нам надежду на лучшее будущее.$B$BВот если бы еще мы смогли избавиться от этих головных болей. Ты $gуверен:уверена;, что не хочешь одного из наших сыновей?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Это честь для нас, что $gтакой:такая:r;, как ты, |3-6($r), помогает нам, ограм. Вы сохраняете нам надежду на лучшее будущее.$B$BВот если бы еще мы смогли избавиться от этих головных болей. Ты $gуверен:уверена;, что не хочешь одного из наших сыновей?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11014,'Что такое сталь по сравнению с рукой того, кто придает ей форму?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что такое сталь по сравнению с рукой того, кто придает ей форму?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11015,'То, что ты $gсделал:сделала;, – просто поразительно. Пожалуй, не будь тебя здесь, нас бы уже сразили демоны, а то и поджарили бы дочерна черные драконы!$B$BКстати, а мы ведь говорили, что готовы продать тебе одного из своих сыновей, дешево, так ведь? Нет, не интересуешься?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','То, что ты $gсделал:сделала;, – просто поразительно. Пожалуй, не будь тебя здесь, нас бы уже сразили демоны, а то и поджарили бы дочерна черные драконы!$B$BКстати, а мы ведь говорили, что готовы продать тебе одного из своих сыновей, дешево, так ведь? Нет, не интересуешься?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11016,'Здесь, в Огри\'ле, о стали знают побольше всех остальных! Но чем еще мы можем помочь вам?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здесь, в Огри\'ле, о стали знают побольше всех остальных! Но чем еще мы можем помочь вам?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11017,'У тебя есть сталь, нуждающаяся в ковке?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','У тебя есть сталь, нуждающаяся в ковке?',`text0_0_loc8`);
