INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11051,'Я слышал рассказы про очень искусного заморского кузнеца по имени Сару Холодная Ярость. Если хочешь усовершенствоваться в своем ремесле, |3-6($c), тебе надо отправляться к нему в Оргриммар. Желаю удачи.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я слышал рассказы про очень искусного заморского кузнеца по имени Сару Холодная Ярость. Если хочешь усовершенствоваться в своем ремесле, |3-6($c), тебе надо отправляться к нему в Оргриммар. Желаю удачи.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (11055,'Пойдем, |3-6($r). Какая формула тебя сегодня интересует?','Пойдем, |3-6($r). Какая формула тебя сегодня интересует?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Пойдем, |3-6($r). Какая формула тебя сегодня интересует?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Пойдем, |3-6($r). Какая формула тебя сегодня интересует?',`text0_1_loc8`);
