INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11056,'Мы готовим штурм Лагеря Баш\'ира, чтобы изучить их Хрустальную кузницу. Помоги нам, если можешь! Наш эфир-тех Стражи Небес отправится примерно через $4581d.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы готовим штурм Лагеря Баш\'ира, чтобы изучить их Хрустальную кузницу. Помоги нам, если можешь! Наш эфир-тех Стражи Небес отправится примерно через $4581d.',`text0_0_loc8`);
