INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11061,'Требуется собрать какие-то припасы?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Требуется собрать какие-то припасы?',`text0_0_loc8`);
