INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11063,'Никогда нельзя быть слишком подготовленным.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Никогда нельзя быть слишком подготовленным.',`text0_0_loc8`);
