INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (11064,'Приветствую, $gпутешественник:путешественница;.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Приветствую, $gпутешественник:путешественница;.',`text0_1_loc8`);
