INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11065,'Наш эфир-тех и сопровождающие направляются к Лагерю Баш\'ира. Встреть их там и окажи им всяческую помощь!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Наш эфир-тех и сопровождающие направляются к Лагерю Баш\'ира. Встреть их там и окажи им всяческую помощь!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11066,'Наша эфир-тех Стражи Небес и ее сопровождающие изучают хрустальную кузницу Баш\'ира. Ей нужна помощь! Отправляйся в Лагерь Баш\'ира, найди эфир-теха и защити ее!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Наша эфир-тех Стражи Небес и ее сопровождающие изучают хрустальную кузницу Баш\'ира. Ей нужна помощь! Отправляйся в Лагерь Баш\'ира, найди эфир-теха и защити ее!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11081,'Я чувствую, что ты $gрасчистил:расчистила; тропинку к моим собратьям. Моя связь с ними и храмом все еще сильна. Ты хочешь зайти глубже?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я чувствую, что ты $gрасчистил:расчистила; тропинку к моим собратьям. Моя связь с ними и храмом все еще сильна. Ты хочешь зайти глубже?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11082,'Мои собратья недавно были здесь. Моя связь с ними стала непрочной. Во дворе – источник большой силы, и он препятствует моему продвижению.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мои собратья недавно были здесь. Моя связь с ними стала непрочной. Во дворе – источник большой силы, и он препятствует моему продвижению.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11089,'Невидимые араккоа… они вокруг нас… следят за нами… ждут!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Невидимые араккоа… они вокруг нас… следят за нами… ждут!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11091,'Что тебе нужно, |3-6($c)?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что тебе нужно, |3-6($c)?',`text0_0_loc8`);
