INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11095,'Кристальное средоточие? Разумеется, мы объясним, потому что вас, как видно, умом обделили.$B$BРазряженное кристальное средоточие можно скомбинировать с десятью апекситовыми осколками и в результате простого процесса преобразовать в заряженное кристальное средоточие. Заряженные кристальные средоточия обладают некими целебными свойствами, но гораздо правильнее будет применить их на призванного демона.$B$BВсе дело в том, что эти кристаллы могут наделить демона некими особыми умениями. Если у вас есть темная руна, вам расскажет о ней Гахк.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Кристальное средоточие? Разумеется, мы объясним, потому что вас, как видно, умом обделили.$B$BРазряженное кристальное средоточие можно скомбинировать с десятью апекситовыми осколками и в результате простого процесса преобразовать в заряженное кристальное средоточие. Заряженные кристальные средоточия обладают некими целебными свойствами, но гораздо правильнее будет применить их на призванного демона.$B$BВсе дело в том, что эти кристаллы могут наделить демона некими особыми умениями. Если у вас есть темная руна, вам расскажет о ней Гахк.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11126,'Мы обязаны раскрыть это преступление. Учитывая местоположение таверны и количество жертв, дело очень щекотливое. Исследуй место преступления как можно осторожнее.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы обязаны раскрыть это преступление. Учитывая местоположение таверны и количество жертв, дело очень щекотливое. Исследуй место преступления как можно осторожнее.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11136,'Мне кажется, что вы очень $gотзывчивый:отзывчивая:c; |3-6($c). Вы помните славные дни Терамора – еще до того, как Джайна заставила нас прекратить войну с Ордой? Вы тоже устали держать свой клинок в ножнах, пока орки продолжают провоцировать нас?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мне кажется, что вы очень $gотзывчивый:отзывчивая:c; |3-6($c). Вы помните славные дни Терамора – еще до того, как Джайна заставила нас прекратить войну с Ордой? Вы тоже устали держать свой клинок в ножнах, пока орки продолжают провоцировать нас?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (11143,'Всадник без головы просто одержимый! На празднике Тыквовина он жестоко и методично атакует эту деревню.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Всадник без головы просто одержимый! На празднике Тыквовина он жестоко и методично атакует эту деревню.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (11145,'Всадник без головы напал на деревню! Необходимо спасти детей и остановить его!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Всадник без головы напал на деревню! Необходимо спасти детей и остановить его!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (11147,'На время мы освободились от Всадника без головы. Но пока он не получит обратно свою голову и не успокоится, нам все время нужно быть начеку!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','На время мы освободились от Всадника без головы. Но пока он не получит обратно свою голову и не успокоится, нам все время нужно быть начеку!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
