INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (11189,'Я день-деньской собираю части разбитого дирижабля, а Фрезза даже не установит мне почасовую плату! Но вы же здесь не за этим, да? Вам ведь нужен дирижабль. Ну что ж, на ваше счастье, у меня есть специальное устройство, отслеживающее их!','Я день-деньской собираю части разбитого дирижабля, а Фрезза даже не установит мне почасовую плату! Но вы же здесь не за этим, да? Вам ведь нужен дирижабль. Ну что ж, на ваше счастье, у меня есть специальное устройство, отслеживающее их!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я день-деньской собираю части разбитого дирижабля, а Фрезза даже не установит мне почасовую плату! Но вы же здесь не за этим, да? Вам ведь нужен дирижабль. Ну что ж, на ваше счастье, у меня есть специальное устройство, отслеживающее их!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я день-деньской собираю части разбитого дирижабля, а Фрезза даже не установит мне почасовую плату! Но вы же здесь не за этим, да? Вам ведь нужен дирижабль. Ну что ж, на ваше счастье, у меня есть специальное устройство, отслеживающее их!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11196,'Торговец Жуль был изгнан из города за мошенническую деятельность. Мы намерены очень осторожно осмотреть эти вещички, которые он продавал. Пожалуйста, оставьте его лавку в покое и дайте нам работать.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Торговец Жуль был изгнан из города за мошенническую деятельность. Мы намерены очень осторожно осмотреть эти вещички, которые он продавал. Пожалуйста, оставьте его лавку в покое и дайте нам работать.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11209,'Лучшего пива ты не найдешь во всем Азероте.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Лучшего пива ты не найдешь во всем Азероте.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11211,'Ух ты! Ты вправду хочешь что-то купить у нас?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ух ты! Ты вправду хочешь что-то купить у нас?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11217,'Я полагаю, ты знаешь, кто я такой. И все же стремишься меня побеспокоить?$B$BЧто у тебя такого, что непременно требует моего внимания?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я полагаю, ты знаешь, кто я такой. И все же стремишься меня побеспокоить?$B$BЧто у тебя такого, что непременно требует моего внимания?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11219,'Ой, да перестаньте! Я – единственный и неповторимый Бадд Недрек!$b$bЯ обошел всю эту землю, от вершины горы Хиджал до самых глубин Затонувшего храма. Собственно, я первый и назвал этот храм затонувшим!$b$bДа, это был я. Даже и не сомневайтесь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ой, да перестаньте! Я – единственный и неповторимый Бадд Недрек!$b$bЯ обошел всю эту землю, от вершины горы Хиджал до самых глубин Затонувшего храма. Собственно, я первый и назвал этот храм затонувшим!$b$bДа, это был я. Даже и не сомневайтесь.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (11220,'Я тебе очень советую навестить Воржея, узнать твою судьбу. Знаю, знаю… он – гнолл. Но он особый гнолл, способный предсказывать будущее!$B$BА еще на нашей ярмарке постоянно появляются новые аттракционы!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я тебе очень советую навестить Воржея, узнать твою судьбу. Знаю, знаю… он – гнолл. Но он особый гнолл, способный предсказывать будущее!$B$BА еще на нашей ярмарке постоянно появляются новые аттракционы!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11221,'Да, да, послушай, |3-6($c). Я старше, чем выгляжу, и куда мудрее своих ровесников. Тебе не стоит так часто сомневаться во мне.\r\n\r\nСмотри, тебе не обязательно верить мне на слово. Почитай любую местную доску объявлений. Я там повсюду!$b$bТолько окажи себе услугу, не обращай внимания на объявления, озаглавленные "РАЗЫСКИВАЕТСЯ" в заглавии. Простые недоразумения, уверяю тебя.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да, да, послушай, |3-6($c). Я старше, чем выгляжу, и куда мудрее своих ровесников. Тебе не стоит так часто сомневаться во мне.\r\n\r\nСмотри, тебе не обязательно верить мне на слово. Почитай любую местную доску объявлений. Я там повсюду!$b$bТолько окажи себе услугу, не обращай внимания на объявления, озаглавленные "РАЗЫСКИВАЕТСЯ" в заглавии. Простые недоразумения, уверяю тебя.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (11226,'Привет, $gкрасавчик:красотка;! Чего ищешь?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Привет, $gкрасавчик:красотка;! Чего ищешь?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (11231,'Я – стряпуха? Пожалуй, так. Официантке приходится время от времени работать на кухне, и за прошедшие годы я освоила несколько рецептов. Ничего особенного, но достаточно питательно, чтоб набить солидное брюхо Грока.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я – стряпуха? Пожалуй, так. Официантке приходится время от времени работать на кухне, и за прошедшие годы я освоила несколько рецептов. Ничего особенного, но достаточно питательно, чтоб набить солидное брюхо Грока.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11245,'Теперь, когда дезертиры захватили Разрушенную башню, самой далекой заставой Терамора осталась Северная башня.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Теперь, когда дезертиры захватили Разрушенную башню, самой далекой заставой Терамора осталась Северная башня.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text1_0_loc8`,`text2_0_loc8`) VALUES (11258,'Ага, никогда не знаешь, кто твой напарник и кому черед погибать.$b$bХочешь совет? Не заводи ни с кем дружбы.','Согласен. Бадд собрал всякий сброд со всех уголков мира.$b$bОно и понятно: когда речь идет о бесплатной выпивке, все мигом забывают о разногласиях.') ON DUPLICATE KEY UPDATE `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Ага, никогда не знаешь, кто твой напарник и кому черед погибать.$b$bХочешь совет? Не заводи ни с кем дружбы.',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Согласен. Бадд собрал всякий сброд со всех уголков мира.$b$bОно и понятно: когда речь идет о бесплатной выпивке, все мигом забывают о разногласиях.',`text2_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text2_0_loc8`) VALUES (11259,'А-а, это. Видишь ли, в лагере сейчас осталось только орочье пойло.$b$bА его моя душа не принимает… понимаешь, да?') ON DUPLICATE KEY UPDATE `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','А-а, это. Видишь ли, в лагере сейчас осталось только орочье пойло.$b$bА его моя душа не принимает… понимаешь, да?',`text2_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11264,'Добро пожаловать на Сторожевой пост, |3-6($c).') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать на Сторожевой пост, |3-6($c).',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11279,'Слушай!$B$BЯ расскажу тебе все, что знаю, но сначала спаси меня от этих дикарей и их медведей!$B$BЛадно?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Слушай!$B$BЯ расскажу тебе все, что знаю, но сначала спаси меня от этих дикарей и их медведей!$B$BЛадно?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11281,'Брогг рад, что гоблины Шестермути позволили ему остаться здесь, но иногда ему кажется, что они над ним смеются.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Брогг рад, что гоблины Шестермути позволили ему остаться здесь, но иногда ему кажется, что они над ним смеются.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (11285,'Никогда в жизни мне не было так холодно, |3-6($r). Я замерзаю даже на расчищенных от снега и льда равнинах Нордскола.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Никогда в жизни мне не было так холодно, |3-6($r). Я замерзаю даже на расчищенных от снега и льда равнинах Нордскола.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`) VALUES (11287,'По-моему, я тебя уже где-то видел…','Мы знакомы?','Вот тебе мудрый совет: никогда не верь гномам.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','По-моему, я тебя уже где-то видел…',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Мы знакомы?',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Вот тебе мудрый совет: никогда не верь гномам.',`text2_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11289,'Ладно, $Gприятель:мадам;, раз уж договорились…$b$bЭто было ночью, когда мы тайком пробрались в Зул\'Аман, чтобы там осмотреться. $b$bВсе было тихо, пока мы не услышали шорох – будто ветер прошелестел в ветвях. И не успели мы опомниться, как нас окружили эти дикари со своими зверюгами! На следующий день я очнулся в клетке.$b$bПленников убивали одного за другим, днем и ночью. И с каждой нашей смертью этот тролль-медведь набирался сил.$b$bВот все, что мне известно об этом месте. И больше я и знать не хочу!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ладно, $Gприятель:мадам;, раз уж договорились…$b$bЭто было ночью, когда мы тайком пробрались в Зул\'Аман, чтобы там осмотреться. $b$bВсе было тихо, пока мы не услышали шорох – будто ветер прошелестел в ветвях. И не успели мы опомниться, как нас окружили эти дикари со своими зверюгами! На следующий день я очнулся в клетке.$b$bПленников убивали одного за другим, днем и ночью. И с каждой нашей смертью этот тролль-медведь набирался сил.$b$bВот все, что мне известно об этом месте. И больше я и знать не хочу!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11291,'Когда вырасту – стану конюшенным!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Когда вырасту – стану конюшенным!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (11293,'Слава Свету, эту таверну построили еще до того, как начались бедствия на севере.$B$BТы к нам надолго?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Слава Свету, эту таверну построили еще до того, как начались бедствия на севере.$B$BТы к нам надолго?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11302,'Ну, ну, $n, расслабься, дыши глубже! Научись, наконец, доверять мне!$b$bТы не знаешь, как вести себя в таких ситуациях, поэтому паникуешь и преувеличиваешь. На самом деле ничего особо страшного тут нет.$b$bА теперь, пожалуйста, успокойся. Так ты всех остальных перепугаешь…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ну, ну, $n, расслабься, дыши глубже! Научись, наконец, доверять мне!$b$bТы не знаешь, как вести себя в таких ситуациях, поэтому паникуешь и преувеличиваешь. На самом деле ничего особо страшного тут нет.$b$bА теперь, пожалуйста, успокойся. Так ты всех остальных перепугаешь…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11309,'Если хочешь поговорить с учеником Гарионом, отправляйся к дому Табеты. Там он хотя бы не утащит все реагенты.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если хочешь поговорить с учеником Гарионом, отправляйся к дому Табеты. Там он хотя бы не утащит все реагенты.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11311,'Эх, сюда бы жреца или друида. С такими ранами мне учебу не продолжить.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эх, сюда бы жреца или друида. С такими ранами мне учебу не продолжить.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11315,'Слушай, $n, тебе следовало бы знать, что когда фортуна стучит в дверь, ей отпирают, а вопросы задают потом. Такие шансы выпадают не каждый день!$b$bНу, ты с нами или нет, |3-6($c)?$b$b*Бадд не дожидается вашего ответа.*$b$bКонечно с нами! Ну а теперь пора за работу, а то разговоров много, а дела мало. Покажи-ка мне, на что ты $Gспособен:способна;, пока я не нашел кого-нибудь другого.$b$bЯ тебя уверяю, куча народу перегрызла бы тебе глотку ради такой возможности!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Слушай, $n, тебе следовало бы знать, что когда фортуна стучит в дверь, ей отпирают, а вопросы задают потом. Такие шансы выпадают не каждый день!$b$bНу, ты с нами или нет, |3-6($c)?$b$b*Бадд не дожидается вашего ответа.*$b$bКонечно с нами! Ну а теперь пора за работу, а то разговоров много, а дела мало. Покажи-ка мне, на что ты $Gспособен:способна;, пока я не нашел кого-нибудь другого.$b$bЯ тебя уверяю, куча народу перегрызла бы тебе глотку ради такой возможности!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11316,'Так вот ты о чем. Это печальная история...$b$bОни исчезли за стенами Зул\'Амана. Я уже много дней от них вестей не получал.$b$bИзо дня в день одно и то же: приходят всякие, приключений да славу им подавай. Пытался я их удержать, говорил им: не готовы вы – но куда там, все равно вышли судьбе навстречу...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Так вот ты о чем. Это печальная история...$b$bОни исчезли за стенами Зул\'Амана. Я уже много дней от них вестей не получал.$b$bИзо дня в день одно и то же: приходят всякие, приключений да славу им подавай. Пытался я их удержать, говорил им: не готовы вы – но куда там, все равно вышли судьбе навстречу...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11320,'Эй! Эти проклятые пираты отрезали нас от гавани!$B$BПожалуйста, помоги нам прорвать блокаду! Садись на аэроплан и сбрось на них парочку бомб!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эй! Эти проклятые пираты отрезали нас от гавани!$B$BПожалуйста, помоги нам прорвать блокаду! Садись на аэроплан и сбрось на них парочку бомб!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11322,'Эй! Эти проклятые пираты отрезали нас от гавани!$B$BПожалуйста, помоги нам прорвать блокаду! Наш аэроплан будет здесь через $3078w |4минуту:минуты:минут;. Садись на борт и сбрось на них парочку бомб.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эй! Эти проклятые пираты отрезали нас от гавани!$B$BПожалуйста, помоги нам прорвать блокаду! Наш аэроплан будет здесь через $3078w |4минуту:минуты:минут;. Садись на борт и сбрось на них парочку бомб.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11324,'Эй! Эти проклятые пираты отрезали нас от гавани!$B$BПожалуйста, помоги нам прорвать блокаду! Наш аэроплан вот-вот прилетит. Садись на борт и сбрось на них парочку бомб.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эй! Эти проклятые пираты отрезали нас от гавани!$B$BПожалуйста, помоги нам прорвать блокаду! Наш аэроплан вот-вот прилетит. Садись на борт и сбрось на них парочку бомб.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11330,'Я пленник! Меня подстрелили, и мой прекрасный дирижабль рухнул с неба прямо в лапы этих мерзавцев! Вот скажи, за что мне такое наказание? За то, что я занимался поставками материалов для Орды? И что в этом такого? Все этим занимаются!$B$BА теперь они гоняют мою малютку по кругу над заливом и заставляют сбрасывать бомбы на пиратов. Вот помяни мое слово – когда-нибудь этот чудесный дирижабль развалится прямо в небе! Он и так на соплях держится, а запчастей мне не поставляют!$B$BНу ладно, если хочешь им помогать – твое дело. Через минуту дирижабль вернется в порт.$B$BНо все равно, я с этим не смирюсь!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я пленник! Меня подстрелили, и мой прекрасный дирижабль рухнул с неба прямо в лапы этих мерзавцев! Вот скажи, за что мне такое наказание? За то, что я занимался поставками материалов для Орды? И что в этом такого? Все этим занимаются!$B$BА теперь они гоняют мою малютку по кругу над заливом и заставляют сбрасывать бомбы на пиратов. Вот помяни мое слово – когда-нибудь этот чудесный дирижабль развалится прямо в небе! Он и так на соплях держится, а запчастей мне не поставляют!$B$BНу ладно, если хочешь им помогать – твое дело. Через минуту дирижабль вернется в порт.$B$BНо все равно, я с этим не смирюсь!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11332,'Я пленник! Меня подстрелили, и мой прекрасный дирижабль рухнул с неба прямо в лапы этих мерзавцев! Вот скажи, за что мне такое наказание? За то, что я занимался поставками материалов для Орды? И что в этом такого? Все этим занимаются!$B$BА теперь они гоняют мою малютку по кругу над заливом и заставляют сбрасывать бомбы на пиратов. Вот помяни мое слово – когда-нибудь этот чудесный дирижабль развалится прямо в небе! Он и так на соплях держится, а запчастей мне не поставляют!$B$BНу ладно, если хочешь им помогать – твое дело. Не позже чем через $3078w |4минуту:минуты:минут; дирижабль вернется в порт.$B$BНо все равно, я с этим не смирюсь!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я пленник! Меня подстрелили, и мой прекрасный дирижабль рухнул с неба прямо в лапы этих мерзавцев! Вот скажи, за что мне такое наказание? За то, что я занимался поставками материалов для Орды? И что в этом такого? Все этим занимаются!$B$BА теперь они гоняют мою малютку по кругу над заливом и заставляют сбрасывать бомбы на пиратов. Вот помяни мое слово – когда-нибудь этот чудесный дирижабль развалится прямо в небе! Он и так на соплях держится, а запчастей мне не поставляют!$B$BНу ладно, если хочешь им помогать – твое дело. Не позже чем через $3078w |4минуту:минуты:минут; дирижабль вернется в порт.$B$BНо все равно, я с этим не смирюсь!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11338,'Терпение, $n. Известность ко мне пришла не потому, что я все время спешил.$b$bСейчас идут последние приготовления, и скоро все секреты и сокровища Зул\'Амана будут моими!$b$b*Бадд замолкает, смотрит на вас и хихикает.*$b$bТо есть я хотел сказать, нашими.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Терпение, $n. Известность ко мне пришла не потому, что я все время спешил.$b$bСейчас идут последние приготовления, и скоро все секреты и сокровища Зул\'Амана будут моими!$b$b*Бадд замолкает, смотрит на вас и хихикает.*$b$bТо есть я хотел сказать, нашими.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11354,'Послушай, |3-6($c), ясно, что вы с друзьями обошли весь Азерот. У вас наверняка полно знакомых, жадных до славы и денег.$B$BПришли мне кого-нибудь, кто может согласиться пойти в Зул\'Аман, и я в долгу не останусь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Послушай, |3-6($c), ясно, что вы с друзьями обошли весь Азерот. У вас наверняка полно знакомых, жадных до славы и денег.$B$BПришли мне кого-нибудь, кто может согласиться пойти в Зул\'Аман, и я в долгу не останусь.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`,`text2_0_loc8`,`text2_1_loc8`,`text3_0_loc8`,`text3_1_loc8`,`text4_0_loc8`,`text4_1_loc8`) VALUES (11356,'Что происходит?','Что происходит?','Хочу обратно в приют!','Хочу обратно в приют!','Попечительница! Этот плохой человек хочет нас съесть?','Попечительница! Этот плохой человек хочет нас съесть?','Был бы папа жив – он бы потушил пожар!','Был бы папа жив – он бы потушил пожар!','Была бы мама жива – она бы потушила пожар!','Была бы мама жива – она бы потушила пожар!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что происходит?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Что происходит?',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Хочу обратно в приют!',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Хочу обратно в приют!',`text1_1_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Попечительница! Этот плохой человек хочет нас съесть?',`text2_0_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Попечительница! Этот плохой человек хочет нас съесть?',`text2_1_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Был бы папа жив – он бы потушил пожар!',`text3_0_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','Был бы папа жив – он бы потушил пожар!',`text3_1_loc8`), `text4_0_loc8`=IF(`text4_0_loc8` IS NULL OR `text4_0_loc8`='','Была бы мама жива – она бы потушила пожар!',`text4_0_loc8`), `text4_1_loc8`=IF(`text4_1_loc8` IS NULL OR `text4_1_loc8`='','Была бы мама жива – она бы потушила пожар!',`text4_1_loc8`);
