INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`,`text2_0_loc8`,`text2_1_loc8`,`text3_0_loc8`,`text3_1_loc8`) VALUES (11358,'Он ушел? Ур-ра!','Он ушел? Ур-ра!','Всадник без головы жуткий с виду, но мне совсем не было страшно! Ни капельки!','Всадник без головы жуткий с виду, но мне совсем не было страшно! Ни капельки!','Всадника без головы удалось отпугнуть!','Всадника без головы удалось отпугнуть!','Если он снова придет, вы будете с ним сражаться?','Если он снова придет, вы будете с ним сражаться?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Он ушел? Ур-ра!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Он ушел? Ур-ра!',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Всадник без головы жуткий с виду, но мне совсем не было страшно! Ни капельки!',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Всадник без головы жуткий с виду, но мне совсем не было страшно! Ни капельки!',`text1_1_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Всадника без головы удалось отпугнуть!',`text2_0_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Всадника без головы удалось отпугнуть!',`text2_1_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Если он снова придет, вы будете с ним сражаться?',`text3_0_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','Если он снова придет, вы будете с ним сражаться?',`text3_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`,`text2_0_loc8`,`text2_1_loc8`,`text3_0_loc8`,`text3_1_loc8`,`text4_0_loc8`,`text4_1_loc8`) VALUES (11359,'Тыквовин – жуткий праздник, но мне нравится!','Тыквовин – жуткий праздник, но мне нравится!','А вы видели Всадника без головы? Воспитательница говорит, что если посмотреть на него, то превратишься в тыкву!','А вы видели Всадника без головы? Воспитательница говорит, что если посмотреть на него, то превратишься в тыкву!','Ведром можно зачерпнуть воды из бочки. Я люблю в ней брызгаться!','Ведром можно зачерпнуть воды из бочки. Я люблю в ней брызгаться!','Однажды солдаты Штормграда воевали с огнем, как настоящие герои!','Однажды солдаты Штормграда воевали с огнем, как настоящие герои!','Всадник без головы живет в Монастыре Алого ордена. Иногда он выходит и пугает взрослых, а вот я его ни капли не боюсь!','Всадник без головы живет в Монастыре Алого ордена. Иногда он выходит и пугает взрослых, а вот я его ни капли не боюсь!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тыквовин – жуткий праздник, но мне нравится!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Тыквовин – жуткий праздник, но мне нравится!',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','А вы видели Всадника без головы? Воспитательница говорит, что если посмотреть на него, то превратишься в тыкву!',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','А вы видели Всадника без головы? Воспитательница говорит, что если посмотреть на него, то превратишься в тыкву!',`text1_1_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Ведром можно зачерпнуть воды из бочки. Я люблю в ней брызгаться!',`text2_0_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Ведром можно зачерпнуть воды из бочки. Я люблю в ней брызгаться!',`text2_1_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Однажды солдаты Штормграда воевали с огнем, как настоящие герои!',`text3_0_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','Однажды солдаты Штормграда воевали с огнем, как настоящие герои!',`text3_1_loc8`), `text4_0_loc8`=IF(`text4_0_loc8` IS NULL OR `text4_0_loc8`='','Всадник без головы живет в Монастыре Алого ордена. Иногда он выходит и пугает взрослых, а вот я его ни капли не боюсь!',`text4_0_loc8`), `text4_1_loc8`=IF(`text4_1_loc8` IS NULL OR `text4_1_loc8`='','Всадник без головы живет в Монастыре Алого ордена. Иногда он выходит и пугает взрослых, а вот я его ни капли не боюсь!',`text4_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11362,'Многие века назад в этих лесах обитала древняя магия, охранявшая царицу племени протодраконов и ее супругов.$B$BНо теперь древнее зло пробудилось и стремится взять контроль над матерью драконьего племени, чтобы использовать ее в своих чудовищных целях.$B$BЭто врайкулы вмешиваются в ход природы, тем самым угрожая вашим народам.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Многие века назад в этих лесах обитала древняя магия, охранявшая царицу племени протодраконов и ее супругов.$B$BНо теперь древнее зло пробудилось и стремится взять контроль над матерью драконьего племени, чтобы использовать ее в своих чудовищных целях.$B$BЭто врайкулы вмешиваются в ход природы, тем самым угрожая вашим народам.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11365,'На этой доске представители Хитрой Шестеренки в Шестермути размещают объявления о премиях и вакансиях.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','На этой доске представители Хитрой Шестеренки в Шестермути размещают объявления о премиях и вакансиях.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11370,'И в самом деле! Я сделал для них все, что мог. Даже представить не могу, что там пошло не так.$b$bВот, |3-6($c), возьми. Я тут кое-что дополнил и улучшил, так что смотри, возвращайся с победой!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','И в самом деле! Я сделал для них все, что мог. Даже представить не могу, что там пошло не так.$b$bВот, |3-6($c), возьми. Я тут кое-что дополнил и улучшил, так что смотри, возвращайся с победой!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11372,'Да ни за что!$b$bЯ лишь пытаюсь избавить мир от страшной угрозы, а такие вещи, знаешь ли, задаром не делаются.$b$bПосмотри на ситуацию с другой стороны, $n. Ты ведь дашь простонародью шанс стать героями! Редкая, что ни говори, возможность!$b$bПришли их ко мне, а об остальном я позабочусь...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да ни за что!$b$bЯ лишь пытаюсь избавить мир от страшной угрозы, а такие вещи, знаешь ли, задаром не делаются.$b$bПосмотри на ситуацию с другой стороны, $n. Ты ведь дашь простонародью шанс стать героями! Редкая, что ни говори, возможность!$b$bПришли их ко мне, а об остальном я позабочусь...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11376,'Если хочешь – можешь отойти. Потрошить рыбу – грязная работа.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если хочешь – можешь отойти. Потрошить рыбу – грязная работа.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11384,'Королевское фармацевтическое общество приветствует тебя в Нордсколе, |3-6($c). Надеюсь, ты $gпришел:пришла; помочь нам?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Королевское фармацевтическое общество приветствует тебя в Нордсколе, |3-6($c). Надеюсь, ты $gпришел:пришла; помочь нам?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (11403,'Все куда хуже, чем я думала! Мой дирижабль превратился в груду покореженного железа и горящего топлива!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Все куда хуже, чем я думала! Мой дирижабль превратился в груду покореженного железа и горящего топлива!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (11406,'Добро пожаловать в Терамор, |3-6($c).') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Добро пожаловать в Терамор, |3-6($c).',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (11419,'Хочешь отдохнуть, дорогуша? Или, может быть, перекусить?$B$BСудя по твоему виду, небольшой отдых тебе не помешает.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Хочешь отдохнуть, дорогуша? Или, может быть, перекусить?$B$BСудя по твоему виду, небольшой отдых тебе не помешает.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11424,'Мне некогда говорить – разве что это срочно… Я отвечаю за врата Терамора.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мне некогда говорить – разве что это срочно… Я отвечаю за врата Терамора.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11426,'Лейтенант Аден всегда вызывается добровольцем на сторожевой пост у ворот. Я не возражаю.$b$bПотому что с моего поста видно сразу все стратегические объекты: и стражу, и дочерей местных лавочников.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Лейтенант Аден всегда вызывается добровольцем на сторожевой пост у ворот. Я не возражаю.$b$bПотому что с моего поста видно сразу все стратегические объекты: и стражу, и дочерей местных лавочников.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11428,'Вы пришли, чтобы меня сменить? Сейчас самое время. В общем, если что, дайте мне знать. Я бы сейчас с удовольствием пропустил пару стаканчиков.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вы пришли, чтобы меня сменить? Сейчас самое время. В общем, если что, дайте мне знать. Я бы сейчас с удовольствием пропустил пару стаканчиков.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11432,'Слава Свету, что в Братстве Справедливости нырять совершенно не умеют!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Слава Свету, что в Братстве Справедливости нырять совершенно не умеют!',`text0_0_loc8`);
