INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (11459,'Может, показать тебе сегодня парочку выкроек?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Может, показать тебе сегодня парочку выкроек?',`text0_1_loc8`);
