INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (11473,'Всадник без головы лишился разума! Во время Тыквовина он может напасть в любой момент.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Всадник без головы лишился разума! Во время Тыквовина он может напасть в любой момент.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (11474,'Всадник без головы поджег деревню! Спасайте детей!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Всадник без головы поджег деревню! Спасайте детей!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (11475,'Всадник без головы атакует! Скорее, помоги своим братьям из Орды защитить деревню!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Всадник без головы атакует! Скорее, помоги своим братьям из Орды защитить деревню!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (11476,'Всадник без головы на время изгнан. Пока что мы можем вздохнуть свободно, но он вернется, мы не должны терять бдительности.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Всадник без головы на время изгнан. Пока что мы можем вздохнуть свободно, но он вернется, мы не должны терять бдительности.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`,`text3_0_loc8`,`text3_1_loc8`,`text4_0_loc8`,`text4_1_loc8`,`text5_0_loc8`,`text5_1_loc8`) VALUES (11477,'Тыквовин – жуткий праздник, но мне нравится!','Тыквовин – жуткий праздник, но мне нравится!','Вы видели Всадника без головы? Если он придет, я поколочу его и отберу у него тыкву!','Вы видели Всадника без головы? Если он придет, я поколочу его и отберу у него тыкву!','Говорят, что бочки и ведра нужны для борьбы с огнем. Вы с ним тоже боретесь?','Говорят, что бочки и ведра нужны для борьбы с огнем. Вы с ним тоже боретесь?','Всадник без головы живет в Монастыре Алого ордена вместе с остальными жуткими призраками и людьми.','Всадник без головы живет в Монастыре Алого ордена вместе с остальными жуткими призраками и людьми.','В таверне раздают угощение и свечки! Стражник Лютая Стража сказал, что, если они нам ничего не дадут, мы сможем над ними подшутить!','В таверне раздают угощение и свечки! Стражник Лютая Стража сказал, что, если они нам ничего не дадут, мы сможем над ними подшутить!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тыквовин – жуткий праздник, но мне нравится!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Тыквовин – жуткий праздник, но мне нравится!',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Вы видели Всадника без головы? Если он придет, я поколочу его и отберу у него тыкву!',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Вы видели Всадника без головы? Если он придет, я поколочу его и отберу у него тыкву!',`text1_1_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Говорят, что бочки и ведра нужны для борьбы с огнем. Вы с ним тоже боретесь?',`text3_0_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','Говорят, что бочки и ведра нужны для борьбы с огнем. Вы с ним тоже боретесь?',`text3_1_loc8`), `text4_0_loc8`=IF(`text4_0_loc8` IS NULL OR `text4_0_loc8`='','Всадник без головы живет в Монастыре Алого ордена вместе с остальными жуткими призраками и людьми.',`text4_0_loc8`), `text4_1_loc8`=IF(`text4_1_loc8` IS NULL OR `text4_1_loc8`='','Всадник без головы живет в Монастыре Алого ордена вместе с остальными жуткими призраками и людьми.',`text4_1_loc8`), `text5_0_loc8`=IF(`text5_0_loc8` IS NULL OR `text5_0_loc8`='','В таверне раздают угощение и свечки! Стражник Лютая Стража сказал, что, если они нам ничего не дадут, мы сможем над ними подшутить!',`text5_0_loc8`), `text5_1_loc8`=IF(`text5_1_loc8` IS NULL OR `text5_1_loc8`='','В таверне раздают угощение и свечки! Стражник Лютая Стража сказал, что, если они нам ничего не дадут, мы сможем над ними подшутить!',`text5_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11494,'Мы не должны были оставлять так много войск в Валгарде. Это все адмирал Келлер, напыщенный, эгоистичный маньяк!$B$BКак мне выполнять его приказы, когда у меня нет людей? Мне нужны солдаты для защиты этого аванпоста и целый гарнизон для крепости Вилдервар, которая вот-вот будет достроена.$B$BНо теперь я хотя бы смогу рассчитывать на твою помощь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы не должны были оставлять так много войск в Валгарде. Это все адмирал Келлер, напыщенный, эгоистичный маньяк!$B$BКак мне выполнять его приказы, когда у меня нет людей? Мне нужны солдаты для защиты этого аванпоста и целый гарнизон для крепости Вилдервар, которая вот-вот будет достроена.$B$BНо теперь я хотя бы смогу рассчитывать на твою помощь.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11538,'Вожди тауренов выходят на эту сцену в конце каждого часа. Поаплодируйте нашим менестрелям! Проникнитесь духом праздника!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вожди тауренов выходят на эту сцену в конце каждого часа. Поаплодируйте нашим менестрелям! Проникнитесь духом праздника!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11549,'Цыц! Уважай старших. Кайаарт – вот кому следует тебя учить.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Цыц! Уважай старших. Кайаарт – вот кому следует тебя учить.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11562,'Земля… смерзлась. Мы тут застряли.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Земля… смерзлась. Мы тут застряли.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11564,'На что это похоже? Земля там промерзла до самого основания!$B$BКолеса этих повозок не приспособлены ехать по такой поверхности! Нам понадобится поганище и пара цепей, чтобы вытащить их отсюда.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','На что это похоже? Земля там промерзла до самого основания!$B$BКолеса этих повозок не приспособлены ехать по такой поверхности! Нам понадобится поганище и пара цепей, чтобы вытащить их отсюда.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11567,'Я никогда не назову Деревню Гиблотопь своим домом. Это значит – отказаться от надежды вернуть наши земли.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я никогда не назову Деревню Гиблотопь своим домом. Это значит – отказаться от надежды вернуть наши земли.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11578,'Выходит, я тебя отблагодарить должен, |3-6($r).$b$bЯ-то думал, последняя кружка – и все, но тут ты.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Выходит, я тебя отблагодарить должен, |3-6($r).$b$bЯ-то думал, последняя кружка – и все, но тут ты.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11580,'Грустная история, да и ясно-то в ней не все.$b$bНарод мой, знаешь ли, любит эль. Да и я не исключение. Но выпил я, видно, больше, чем следует.$b$bВстречаю я, значит, старого Бадда, а он мне и предлагает сколько угодно грога, если я к нему в команду пойду, – ох и долго же я потом об этом жалел.$b$bКак-то ночью, когда я высосал столько грогу, что и кодо бы с ног свалился, меня уболтали двинуть вместе с Баддовой бандой неудачников в Зул\'Аман.$b$bА потом я ничего не помню, очнулся уже в клетке.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Грустная история, да и ясно-то в ней не все.$b$bНарод мой, знаешь ли, любит эль. Да и я не исключение. Но выпил я, видно, больше, чем следует.$b$bВстречаю я, значит, старого Бадда, а он мне и предлагает сколько угодно грога, если я к нему в команду пойду, – ох и долго же я потом об этом жалел.$b$bКак-то ночью, когда я высосал столько грогу, что и кодо бы с ног свалился, меня уболтали двинуть вместе с Баддовой бандой неудачников в Зул\'Аман.$b$bА потом я ничего не помню, очнулся уже в клетке.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text1_1_loc8`,`text2_1_loc8`) VALUES (11586,'Через несколько часов остатки флота Альянса на Обнажившемся Дне будут разбиты. Они окружены и обречены.','Наши враги падут, ибо такова воля Сильваны.') ON DUPLICATE KEY UPDATE `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Через несколько часов остатки флота Альянса на Обнажившемся Дне будут разбиты. Они окружены и обречены.',`text1_1_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Наши враги падут, ибо такова воля Сильваны.',`text2_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (11588,'Нам мешают только эти две пушки вдоль стены. Если бы их не было, наши войска смогли бы с легкостью взять их укрепления без значительных потерь.$B$BНадо либо уничтожить пушки, либо дождаться, когда у них кончатся боеприпасы. Похоже, Ансельм склоняется ко второму варианту.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Нам мешают только эти две пушки вдоль стены. Если бы их не было, наши войска смогли бы с легкостью взять их укрепления без значительных потерь.$B$BНадо либо уничтожить пушки, либо дождаться, когда у них кончатся боеприпасы. Похоже, Ансельм склоняется ко второму варианту.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11602,'Свобода! А Краз ведь чуть не умереть.$b$bСпасибо тебе, |3-6($c).') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Свобода! А Краз ведь чуть не умереть.$b$bСпасибо тебе, |3-6($c).',`text0_0_loc8`);
