INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11604,'Кразу нечего было делать в этом проклятом месте… и зачем я только поверил человеку? Я был глупым слепцом, |3-6($c), да и вы станете $gтаким же:такой же;, если будете следовать его советам.$B$BМоего сына, который уже две луны как пропал без вести, последний раз видели с человеком, Баддом. Он сказал, что я найду его за стенами Зул\'Амана…$B$BЯ последовал сюда за его людьми и был схвачен, как и все остальные. Без вашей помощи я давно бы погиб.$B$BСпасибо, $gнезнакомец:незнакомка;.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Кразу нечего было делать в этом проклятом месте… и зачем я только поверил человеку? Я был глупым слепцом, |3-6($c), да и вы станете $gтаким же:такой же;, если будете следовать его советам.$B$BМоего сына, который уже две луны как пропал без вести, последний раз видели с человеком, Баддом. Он сказал, что я найду его за стенами Зул\'Амана…$B$BЯ последовал сюда за его людьми и был схвачен, как и все остальные. Без вашей помощи я давно бы погиб.$B$BСпасибо, $gнезнакомец:незнакомка;.',`text0_0_loc8`);
