INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (11607,'Заходи сюда с холода и дай немного отдохнуть своим утомленным косточкам. Воспользуйся нашим гостеприимством!','Заходи сюда с холода и дай немного отдохнуть своим утомленным косточкам. Воспользуйся нашим гостеприимством!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Заходи сюда с холода и дай немного отдохнуть своим утомленным косточкам. Воспользуйся нашим гостеприимством!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Заходи сюда с холода и дай немного отдохнуть своим утомленным косточкам. Воспользуйся нашим гостеприимством!',`text0_1_loc8`);
