INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11622,'$GСэр:Мэм;! Мне было приказано оказывать вам посильную помощь и обеспечивать защиту.$B$BКакие будут указания?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','$GСэр:Мэм;! Мне было приказано оказывать вам посильную помощь и обеспечивать защиту.$B$BКакие будут указания?',`text0_0_loc8`);
