INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11625,'Я блуждал в неизвестности целую вечность. И только сейчас понял, как черна стала моя душа…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я блуждал в неизвестности целую вечность. И только сейчас понял, как черна стала моя душа…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11645,'Тыквенная голова угрожающе дымится…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тыквенная голова угрожающе дымится…',`text0_0_loc8`);
