INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (11655,'Поторопись, |3-6($c)!$b$bСитуация критическая, и мы почти не можем ее контролировать!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Поторопись, |3-6($c)!$b$bСитуация критическая, и мы почти не можем ее контролировать!',`text0_1_loc8`);
