INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (11671,'Нет, эти губошлепы Альянса определенно сошли с ума! Пытаться пилотировать на разрушителях Отрекшихся… это же самоубийство!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Нет, эти губошлепы Альянса определенно сошли с ума! Пытаться пилотировать на разрушителях Отрекшихся… это же самоубийство!',`text0_1_loc8`);
