INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (11673,'Мы с моими сестрами приветствуем тебя, |3-6($r).') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мы с моими сестрами приветствуем тебя, |3-6($r).',`text0_1_loc8`);
