INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11676,'Держи ухо востро, $n.$b$bМы еще не выбрались из чащи.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Держи ухо востро, $n.$b$bМы еще не выбрались из чащи.',`text0_0_loc8`);
