INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11688,'Приветствую тебя, $gнезнакомец:незнакомка;! В этих краях нуждаются в твоей помощи.$B$BСтрашные корабли с мертвецами причалили к нашим берегам. В этом фьорде стало слишком опасно находиться, и мы решили уйти на север из этих земель.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приветствую тебя, $gнезнакомец:незнакомка;! В этих краях нуждаются в твоей помощи.$B$BСтрашные корабли с мертвецами причалили к нашим берегам. В этом фьорде стало слишком опасно находиться, и мы решили уйти на север из этих земель.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11689,'Мой долг – помочь и защитить тебя от врагов.$B$BЧто мы собираемся предпринять?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мой долг – помочь и защитить тебя от врагов.$B$BЧто мы собираемся предпринять?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (11691,'Подойди поближе, $gмилый:милая;, слух у меня уже не тот, а кричать мне бы не хотелось.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Подойди поближе, $gмилый:милая;, слух у меня уже не тот, а кричать мне бы не хотелось.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (11714,'Добро пожаловать в мою таверну, усталый путешественник. Что я могу сделать для тебя?','Добро пожаловать в мою таверну, усталый путешественник. Что я могу сделать для тебя?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать в мою таверну, усталый путешественник. Что я могу сделать для тебя?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Добро пожаловать в мою таверну, усталый путешественник. Что я могу сделать для тебя?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11724,'Так много применений для нового штамма чумы – и так мало времени на работу!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Так много применений для нового штамма чумы – и так мало времени на работу!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (11738,'Ты услада для усталых глаз!$B$BАх, у меня еще столько дел и так мало времени!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты услада для усталых глаз!$B$BАх, у меня еще столько дел и так мало времени!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`) VALUES (11742,'Горт не боится смерти. Отрекшиеся просто соберут меня заново.','Горт иногда что-то не понимает. Горт умеет убивать. Поэтому Горта сделали сержантом. Но теперь Горта не посылают никого убивать!','Врайкулы больше и сильнее нас. Но мы зато не такие ужасные на вид!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Горт не боится смерти. Отрекшиеся просто соберут меня заново.',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Горт иногда что-то не понимает. Горт умеет убивать. Поэтому Горта сделали сержантом. Но теперь Горта не посылают никого убивать!',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Врайкулы больше и сильнее нас. Но мы зато не такие ужасные на вид!',`text2_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11756,'Пожалуй, я совершил ошибку, путешествуя так близко от Вырубок и Гьялерброна.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Пожалуй, я совершил ошибку, путешествуя так близко от Вырубок и Гьялерброна.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11797,'Есть хочешь? Можешь здесь и поспать.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Есть хочешь? Можешь здесь и поспать.',`text0_0_loc8`);
