INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11808,'И как это я позволил Петрову уговорить меня поработать с этими никчемными дворфами?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','И как это я позволил Петрову уговорить меня поработать с этими никчемными дворфами?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11827,'Мы, распространители чумы, обычно экспериментируем больше обычных аптекарей. В конце концов, наша основная задача – заразить чумой все живущее.$B$BНо это не значит, что наши теоретические познания недостаточно основательны. Просто мы предпочитаем сразу переходить к делу.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы, распространители чумы, обычно экспериментируем больше обычных аптекарей. В конце концов, наша основная задача – заразить чумой все живущее.$B$BНо это не значит, что наши теоретические познания недостаточно основательны. Просто мы предпочитаем сразу переходить к делу.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11851,'Большое тебе спасибо, |3-6($c).$b$bЕсли когда чего где понадобится – ты только свистни!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Большое тебе спасибо, |3-6($c).$b$bЕсли когда чего где понадобится – ты только свистни!',`text0_0_loc8`);
