INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11872,'Как? Ты ее $gпотерял:потеряла;? Ладно, возьми другую личину и береги ее!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Как? Ты ее $gпотерял:потеряла;? Ладно, возьми другую личину и береги ее!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (11874,'Я буду скучать по Лагерю Заиндевевшего Копыта. Но я понимаю, почему вождь Прахтотем принял такое решение. Сейчас мы должны заботиться о нашем выживании, а не о комфорте родного очага.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я буду скучать по Лагерю Заиндевевшего Копыта. Но я понимаю, почему вождь Прахтотем принял такое решение. Сейчас мы должны заботиться о нашем выживании, а не о комфорте родного очага.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (11884,'Кости… плоть… мускулы… жилы… моя пила распилит что угодно!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Кости… плоть… мускулы… жилы… моя пила распилит что угодно!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (11907,'Ура, вы убили злого тролля, который уже собирался разорвать меня на части и поработить мою несчастную душу, чтобы воплотить в жизнь планы по захвату Азорота, и за то, что вы рисковали жизнью ради спасения меня от неминуемой смерти, я вас щедро отблагодарю, кто бы вы ни были и откуда бы ни пришли, так что помогите мне отсюда выбраться – и получите щедрое вознаграждение…$b$b*Эшли набирает в легкие побольше воздуха.*$b$bНадеюсь, вы конфеты любите…') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ура, вы убили злого тролля, который уже собирался разорвать меня на части и поработить мою несчастную душу, чтобы воплотить в жизнь планы по захвату Азорота, и за то, что вы рисковали жизнью ради спасения меня от неминуемой смерти, я вас щедро отблагодарю, кто бы вы ни были и откуда бы ни пришли, так что помогите мне отсюда выбраться – и получите щедрое вознаграждение…$b$b*Эшли набирает в легкие побольше воздуха.*$b$bНадеюсь, вы конфеты любите…',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11910,'Конечно. Я нашел это на теле дворфа.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Конечно. Я нашел это на теле дворфа.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (11943,'Дай угадаю, еще одна группа отребья Бадда?$b$bУходи, |3-6($r), пока не поранили или чего хуже не сделали.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Дай угадаю, еще одна группа отребья Бадда?$b$bУходи, |3-6($r), пока не поранили или чего хуже не сделали.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (11957,'Я так понимаю, этот праздник придумали не союзники, а Орда. Так какого беса мы его празднуем?','Я так понимаю, этот праздник придумали не союзники, а Орда. Так какого беса мы его празднуем?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я так понимаю, этот праздник придумали не союзники, а Орда. Так какого беса мы его празднуем?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я так понимаю, этот праздник придумали не союзники, а Орда. Так какого беса мы его празднуем?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (11958,'Так кто там от чего освободился? А, какая разница! Еще сладостей!','Так кто там от чего освободился? А, какая разница! Еще сладостей!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Так кто там от чего освободился? А, какая разница! Еще сладостей!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Так кто там от чего освободился? А, какая разница! Еще сладостей!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (11959,'Ну почему все говорят, что нам, гномам, надо перестать есть сахар?!','Ну почему все говорят, что нам, гномам, надо перестать есть сахар?!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ну почему все говорят, что нам, гномам, надо перестать есть сахар?!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ну почему все говорят, что нам, гномам, надо перестать есть сахар?!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (11960,'Ну и толку продавцам от бесплатных конфеток? Хотя… может, это уловка такая. Заманят тебя в таверну, а там уж обдерут как липку. Ловко!','Ну и толку продавцам от бесплатных конфеток? Хотя… может, это уловка такая. Заманят тебя в таверну, а там уж обдерут как липку. Ловко!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ну и толку продавцам от бесплатных конфеток? Хотя… может, это уловка такая. Заманят тебя в таверну, а там уж обдерут как липку. Ловко!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ну и толку продавцам от бесплатных конфеток? Хотя… может, это уловка такая. Заманят тебя в таверну, а там уж обдерут как липку. Ловко!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (11961,'Когда окончится Тыквовин, мы разобьем все-все тыквы! Вот веселье-то будет!','Когда окончится Тыквовин, мы разобьем все-все тыквы! Вот веселье-то будет!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Когда окончится Тыквовин, мы разобьем все-все тыквы! Вот веселье-то будет!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Когда окончится Тыквовин, мы разобьем все-все тыквы! Вот веселье-то будет!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (11962,'Веселиться в честь рождения одного из злейших врагов – затея, мягко говоря, странная. Но мы праздники союзников не пропускаем!','Веселиться в честь рождения одного из злейших врагов – затея, мягко говоря, странная. Но мы праздники союзников не пропускаем!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Веселиться в честь рождения одного из злейших врагов – затея, мягко говоря, странная. Но мы праздники союзников не пропускаем!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Веселиться в честь рождения одного из злейших врагов – затея, мягко говоря, странная. Но мы праздники союзников не пропускаем!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (11963,'Отрекшиеся правильно поступают, что празднуют день освобождения. Такое забывать нельзя.','Отрекшиеся правильно поступают, что празднуют день освобождения. Такое забывать нельзя.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Отрекшиеся правильно поступают, что празднуют день освобождения. Такое забывать нельзя.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Отрекшиеся правильно поступают, что празднуют день освобождения. Такое забывать нельзя.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (11964,'Не возьму в толк, чего ради Отрекшиеся сжигают каждую ночь чучело из прутьев. Хотя им наши обычаи тоже странными кажутся, наверное.','Не возьму в толк, чего ради Отрекшиеся сжигают каждую ночь чучело из прутьев. Хотя им наши обычаи тоже странными кажутся, наверное.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не возьму в толк, чего ради Отрекшиеся сжигают каждую ночь чучело из прутьев. Хотя им наши обычаи тоже странными кажутся, наверное.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Не возьму в толк, чего ради Отрекшиеся сжигают каждую ночь чучело из прутьев. Хотя им наши обычаи тоже странными кажутся, наверное.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (11965,'Не понимаю, зачем Отрекшиеся каждую ночь Тыквовина сжигают чучело? Лучше б кого живого сожгли!','Не понимаю, зачем Отрекшиеся каждую ночь Тыквовина сжигают чучело? Лучше б кого живого сожгли!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не понимаю, зачем Отрекшиеся каждую ночь Тыквовина сжигают чучело? Лучше б кого живого сожгли!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Не понимаю, зачем Отрекшиеся каждую ночь Тыквовина сжигают чучело? Лучше б кого живого сожгли!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (11966,'Во время Тыквовина мы отмечаем тот день, когда королева банши вырвала нашу свободу из лап Короля-лича и Плети. Не забудь посетить фестиваль Плетеного человека, что проводится каждый вечер рядом с Подгородом.','Во время Тыквовина мы отмечаем тот день, когда королева банши вырвала нашу свободу из лап Короля-лича и Плети. Не забудь посетить фестиваль Плетеного человека, что проводится каждый вечер рядом с Подгородом.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Во время Тыквовина мы отмечаем тот день, когда королева банши вырвала нашу свободу из лап Короля-лича и Плети. Не забудь посетить фестиваль Плетеного человека, что проводится каждый вечер рядом с Подгородом.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Во время Тыквовина мы отмечаем тот день, когда королева банши вырвала нашу свободу из лап Короля-лича и Плети. Не забудь посетить фестиваль Плетеного человека, что проводится каждый вечер рядом с Подгородом.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12044,'Моих клиентов интересуют редкие и ценные вещи.$b$bВы могли бы их добыть, |3-6($c), а взамен получить то, что вам нужно.$b$bПоговорим о том, что мне нужно сегодня?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Моих клиентов интересуют редкие и ценные вещи.$b$bВы могли бы их добыть, |3-6($c), а взамен получить то, что вам нужно.$b$bПоговорим о том, что мне нужно сегодня?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (12049,'Здесь мы учимся тушить пожары. Пламя может вспыхнуть в любой момент!','Здесь мы учимся тушить пожары. Пламя может вспыхнуть в любой момент!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здесь мы учимся тушить пожары. Пламя может вспыхнуть в любой момент!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Здесь мы учимся тушить пожары. Пламя может вспыхнуть в любой момент!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12052,'Хе, думаешь, у тебя силенок много, а? Тогда иди-ка, продержись на арене, а потом я кое-что дам тебе в награду. Не пожалеешь, точно тебе говорю!$b$bАх да, и желаю удачи.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Хе, думаешь, у тебя силенок много, а? Тогда иди-ка, продержись на арене, а потом я кое-что дам тебе в награду. Не пожалеешь, точно тебе говорю!$b$bАх да, и желаю удачи.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12082,'Не правда ли, красавец? Хочешь прокатиться?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не правда ли, красавец? Хочешь прокатиться?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (12083,'Привет! Хочешь, расскажу о премудростях гонок на баранах?','Привет! Хочешь, расскажу о премудростях гонок на баранах?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Привет! Хочешь, расскажу о премудростях гонок на баранах?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Привет! Хочешь, расскажу о премудростях гонок на баранах?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (12084,'Если возьмешься за какое-нибудь из этих заданий, мы одолжим тебе барана. Именно одолжим, потом его надо будет вернуть. Сначала баран идет медленно, но если ослабить поводья, он поскачет быстрее.$b$bНаши бараны любят яблоки. Мы расставили бочонки с яблоками вдоль дороги, так что не забывай у них останавливаться. Поев яблок, твой баран забудет об усталости.','Если возьмешься за какое-нибудь из этих заданий, мы одолжим тебе барана. Именно одолжим, потом его надо будет вернуть. Сначала баран идет медленно, но если ослабить поводья, он поскачет быстрее.$b$bНаши бараны любят яблоки. Мы расставили бочонки с яблоками вдоль дороги, так что не забывай у них останавливаться. Поев яблок, твой баран забудет об усталости.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если возьмешься за какое-нибудь из этих заданий, мы одолжим тебе барана. Именно одолжим, потом его надо будет вернуть. Сначала баран идет медленно, но если ослабить поводья, он поскачет быстрее.$b$bНаши бараны любят яблоки. Мы расставили бочонки с яблоками вдоль дороги, так что не забывай у них останавливаться. Поев яблок, твой баран забудет об усталости.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Если возьмешься за какое-нибудь из этих заданий, мы одолжим тебе барана. Именно одолжим, потом его надо будет вернуть. Сначала баран идет медленно, но если ослабить поводья, он поскачет быстрее.$b$bНаши бараны любят яблоки. Мы расставили бочонки с яблоками вдоль дороги, так что не забывай у них останавливаться. Поев яблок, твой баран забудет об усталости.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12087,'Если слишком долго вести барана галопом или легким галопом, он выдохнется. Чтобы дать животному отдохнуть, пусти его шагом или рысью. Увидишь кадки с яблоками – подведи барана к ним: он сможет поесть и восстановить силы.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Если слишком долго вести барана галопом или легким галопом, он выдохнется. Чтобы дать животному отдохнуть, пусти его шагом или рысью. Увидишь кадки с яблоками – подведи барана к ним: он сможет поесть и восстановить силы.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12088,'Бараньи скачки – это легче, чем может показаться, но они требуют умения управлять бараном. Просто рули с помощью поводьев, ешь яблоки, если можешь, и не изнуряй своего барана.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Бараньи скачки – это легче, чем может показаться, но они требуют умения управлять бараном. Просто рули с помощью поводьев, ешь яблоки, если можешь, и не изнуряй своего барана.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12090,'А? Ну, что еще?$B$BВремя никого не ждет!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','А? Ну, что еще?$B$BВремя никого не ждет!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (12092,'Если ты соберешь достаточно призовых купонов фестиваля, выдающий призы в лагере Хмельного фестиваля поставит тебе на руку печать "Почетный любитель пива". $B$BЭта печать позволит мне продать тебе скакового барана фестиваля. Но учти, они достаются недешево!','Если ты соберешь достаточно призовых купонов фестиваля, выдающий призы в лагере Хмельного фестиваля поставит тебе на руку печать "Почетный любитель пива". $B$BЭта печать позволит мне продать тебе скакового барана фестиваля. Но учти, они достаются недешево!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если ты соберешь достаточно призовых купонов фестиваля, выдающий призы в лагере Хмельного фестиваля поставит тебе на руку печать "Почетный любитель пива". $B$BЭта печать позволит мне продать тебе скакового барана фестиваля. Но учти, они достаются недешево!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Если ты соберешь достаточно призовых купонов фестиваля, выдающий призы в лагере Хмельного фестиваля поставит тебе на руку печать "Почетный любитель пива". $B$BЭта печать позволит мне продать тебе скакового барана фестиваля. Но учти, они достаются недешево!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12097,'Мы построили этот порт голыми руками! Слезами, потом и кровью!$B$BПоверь мне на слово – мы никогда не позволим захватить Валгард!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы построили этот порт голыми руками! Слезами, потом и кровью!$B$BПоверь мне на слово – мы никогда не позволим захватить Валгард!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12098,'Эй, $gприятель:подруга;, у меня тут такая вещица завалялась, единственная в своем роде! И я ее продаю, да совсем недорого!$b$bВидишь ли, надоело мне тратить деньги в тавернах и разыскивать идеального спутника жизни. И тогда я смастерила эти очки – сквозь них все просто красавцы! Вот увидишь!$b$bНу что, может, купишь, поможешь мне карманы-то набить слегка? Я тебе за красоту даже скидку сделаю!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Эй, $gприятель:подруга;, у меня тут такая вещица завалялась, единственная в своем роде! И я ее продаю, да совсем недорого!$b$bВидишь ли, надоело мне тратить деньги в тавернах и разыскивать идеального спутника жизни. И тогда я смастерила эти очки – сквозь них все просто красавцы! Вот увидишь!$b$bНу что, может, купишь, поможешь мне карманы-то набить слегка? Я тебе за красоту даже скидку сделаю!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12100,'А я тебя давно приметил, все ждал, когда же ты зайдешь! Итак, что ищешь, $gкрасавчик:милашка;?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','А я тебя давно приметил, все ждал, когда же ты зайдешь! Итак, что ищешь, $gкрасавчик:милашка;?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12103,'Теперь обычные собаки ко мне даже не подходят… Честно говоря, меня это очень огорчает… когда-то я очень любил животных.$B$BНо чумные псы тоже очень милые, хотя с первого взгляда так не скажешь! Впрочем, взгляни на меня – сразу поймешь, что не надо судить по внешности.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Теперь обычные собаки ко мне даже не подходят… Честно говоря, меня это очень огорчает… когда-то я очень любил животных.$B$BНо чумные псы тоже очень милые, хотя с первого взгляда так не скажешь! Впрочем, взгляни на меня – сразу поймешь, что не надо судить по внешности.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12104,'Лучшей выпивки ты во всем Азероте не сыщешь!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Лучшей выпивки ты во всем Азероте не сыщешь!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12105,'Эй, $gприятель:подруга;, не хочешь пропустить кружку лучшего пива в мире?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эй, $gприятель:подруга;, не хочешь пропустить кружку лучшего пива в мире?',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12108,'Здесь мы тренируемся тушить пожары. Силу Отрекшимся!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Здесь мы тренируемся тушить пожары. Силу Отрекшимся!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12114,'Этих баранов мы купили в соответствии со всеми законами. Хочешь такого же? Хочешь окунуться в мир бараньих бегов? Что ж, никто не запрещает, но сначала придется поработать.$b$bВпрочем, работа больше на игру похожа.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Этих баранов мы купили в соответствии со всеми законами. Хочешь такого же? Хочешь окунуться в мир бараньих бегов? Что ж, никто не запрещает, но сначала придется поработать.$b$bВпрочем, работа больше на игру похожа.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (12119,'Здесь мы учимся тушить пожары. Пламя может вспыхнуть в любой момент!','Здесь мы учимся тушить пожары. Пламя может вспыхнуть в любой момент!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здесь мы учимся тушить пожары. Пламя может вспыхнуть в любой момент!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Здесь мы учимся тушить пожары. Пламя может вспыхнуть в любой момент!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`,`text3_0_loc8`) VALUES (12120,'Эй, дружище! Что, потрепало тебя жизнью, соленая ты треска?$B$BА у нас тут все тип-топ!','Ого, ну и свезло тебе! Че, удалось обчистить жирного маркитанта? Поделись добычей-то. Нечего жмотничать!','Эй, трави концы, друг! Этот вонючий салага мне всю морду расквасил, сечешь? Ну, я ему задам перцу, тухлая кобыла его мать… своей башкой померяет, сколько футов под килем…','Клянусь хвостом русалки, это правда, приятель! Характеры пиратов северных морей будут посолонее воды здешнего моря, морской дьявол мне в брюхо. Лучше никому не ложиться на наш курс, тысяча чертей! Только моряк с протухшими мозгами добровольно подведет себя под поцелуй дочки канонира!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эй, дружище! Что, потрепало тебя жизнью, соленая ты треска?$B$BА у нас тут все тип-топ!',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Ого, ну и свезло тебе! Че, удалось обчистить жирного маркитанта? Поделись добычей-то. Нечего жмотничать!',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Эй, трави концы, друг! Этот вонючий салага мне всю морду расквасил, сечешь? Ну, я ему задам перцу, тухлая кобыла его мать… своей башкой померяет, сколько футов под килем…',`text2_0_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Клянусь хвостом русалки, это правда, приятель! Характеры пиратов северных морей будут посолонее воды здешнего моря, морской дьявол мне в брюхо. Лучше никому не ложиться на наш курс, тысяча чертей! Только моряк с протухшими мозгами добровольно подведет себя под поцелуй дочки канонира!',`text3_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12124,'<Старый Ледоспин чертит какие-то знаки на песке. Присмотревшись к рисункам, вы понимаете, что он просит вас о помощи>.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Старый Ледоспин чертит какие-то знаки на песке. Присмотревшись к рисункам, вы понимаете, что он просит вас о помощи>.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12130,'<Старый Ледоспин настороженно смотрит на вас, прогоняя кивком головы.>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Старый Ледоспин настороженно смотрит на вас, прогоняя кивком головы.>',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12135,'Вот тебе мудрый совет: отправляйся туда, откуда $gпришел:пришла;! Тут тебе не место для искателей веселых приключений, тут тебя сожрут и не подавятся.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вот тебе мудрый совет: отправляйся туда, откуда $gпришел:пришла;! Тут тебе не место для искателей веселых приключений, тут тебя сожрут и не подавятся.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12137,'Этот большой светильник из тыквы находится в самом центре поселения.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Этот большой светильник из тыквы находится в самом центре поселения.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12138,'Тыкву уже распотрошили, и сокровищ больше не осталось.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тыкву уже распотрошили, и сокровищ больше не осталось.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12140,'Разбив тыкву, вы видите, что в ней спрятано сокровище. Это самый удачный день вашей жизни!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Разбив тыкву, вы видите, что в ней спрятано сокровище. Это самый удачный день вашей жизни!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12144,'А? Что? Полетать хочешь? Не-не-не, за-за-забудь…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','А? Что? Полетать хочешь? Не-не-не, за-за-забудь…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12162,'Здравствуй, и да пребудет с тобой Свет Элуны.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Здравствуй, и да пребудет с тобой Свет Элуны.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12173,'Я тут занимаюсь организацией боев. Так что если хочешь сделать ставку – не бойся, у нас все по-честному. Если кто-то пытается мухлевать, его быстро отправляют на рею!$B$BЯ лично за этим слежу!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я тут занимаюсь организацией боев. Так что если хочешь сделать ставку – не бойся, у нас все по-честному. Если кто-то пытается мухлевать, его быстро отправляют на рею!$B$BЯ лично за этим слежу!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12174,'Сокровища эльфов крови не похожи ни на какие другие ценности. Это не просто золото, шелк или драгоценности. Работа мастеров син\'дорай ценится сама по себе.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Сокровища эльфов крови не похожи ни на какие другие ценности. Это не просто золото, шелк или драгоценности. Работа мастеров син\'дорай ценится сама по себе.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12175,'Я заплачу! Я все отдам, слышишь! Не бей меня!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я заплачу! Я все отдам, слышишь! Не бей меня!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12176,'День за днем этот псих Иона Стерлинг заставляет меня драить палубы.$B$BДраить палубы, представляешь!$B$BЯ маг, раздери меня акула, а не полотер!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','День за днем этот псих Иона Стерлинг заставляет меня драить палубы.$B$BДраить палубы, представляешь!$B$BЯ маг, раздери меня акула, а не полотер!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12178,'<Этот пират, очевидно, выпил лишнего и теперь какое-то время будет без сознания.>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Этот пират, очевидно, выпил лишнего и теперь какое-то время будет без сознания.>',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12179,'И что тебе налить? Рома? Эля?$B$BИли, может, чего-нибудь другого?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','И что тебе налить? Рома? Эля?$B$BИли, может, чего-нибудь другого?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12180,'Ты $gсобрался:собралась; обчистить Джека у всех на глазах?$B$BЛибо ты очень $gсмелый, либо глупый:смелая, либо глупая;. Ну… это тебе недешево обойдется. Я не собираюсь просто так рисковать жизнью. Да смотри, сначала дождись, когда я уйду – а потом действуй!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты $gсобрался:собралась; обчистить Джека у всех на глазах?$B$BЛибо ты очень $gсмелый, либо глупый:смелая, либо глупая;. Ну… это тебе недешево обойдется. Я не собираюсь просто так рисковать жизнью. Да смотри, сначала дождись, когда я уйду – а потом действуй!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12188,'Как много изменений произошли с этими землями…$B$BМы, камагуанцы, боимся того, что происходит. Но что ты можешь сделать?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Как много изменений произошли с этими землями…$B$BМы, камагуанцы, боимся того, что происходит. Но что ты можешь сделать?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12189,'Это я-то проиграл? Уолт несет чушь! Я этих железных дворфов одной левой уделаю!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Это я-то проиграл? Уолт несет чушь! Я этих железных дворфов одной левой уделаю!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (12191,'Добрый вечер…','Добрый вечер…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добрый вечер…',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Добрый вечер…',`text0_1_loc8`);
