INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12193,'По…полагаю, ты хочешь вернуться обратно на аванпост, да?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','По…полагаю, ты хочешь вернуться обратно на аванпост, да?',`text0_0_loc8`);
