INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12194,'Верстак Уолта готов к работе.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Верстак Уолта готов к работе.',`text0_0_loc8`);
