INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12210,'Ты что, не видишь? Я работаю! Уходи, пока Ковальски не увидел.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты что, не видишь? Я работаю! Уходи, пока Ковальски не увидел.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12211,'Отличный денек! Самое то, чтобы под парусом походить!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Отличный денек! Самое то, чтобы под парусом походить!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12212,'Торголей гоняет нас до седьмого пота, но он – хороший капитан, да…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Торголей гоняет нас до седьмого пота, но он – хороший капитан, да…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12214,'Я должен присматривать за кораблем и командой, $gсэр:мадам;. Извините, что не могу с вами поговорить.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я должен присматривать за кораблем и командой, $gсэр:мадам;. Извините, что не могу с вами поговорить.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12216,'Добро пожаловать на корабль "Леди Мели". Я капитан Торголей.$b$bЕсли хочешь расспросить меня о корабле – пожалуйста; если нет – получай удовольствие от плавания, как я всегда и делаю… Ведь, как говорится в моей любимой цитате: "Когда плывешь на корабле, забываешь обо всем на свете и кажется, что сам этот свет уже и ни к чему".') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать на корабль "Леди Мели". Я капитан Торголей.$b$bЕсли хочешь расспросить меня о корабле – пожалуйста; если нет – получай удовольствие от плавания, как я всегда и делаю… Ведь, как говорится в моей любимой цитате: "Когда плывешь на корабле, забываешь обо всем на свете и кажется, что сам этот свет уже и ни к чему".',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12217,'Да, так он и называется, и это славный корабль.$b$bЗнаешь, от таких судов ведь многому можно научиться. Великий поэт сказал однажды так: Бродят в ночи корабли и друг друга зовут неустанно:/Голос – короткий гудок, отзвук далекий в тумане./Так же мы ищем друг друга в жизни, как в океане:/Голос и взгляд, а потом – лишь темнота да молчанье.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да, так он и называется, и это славный корабль.$b$bЗнаешь, от таких судов ведь многому можно научиться. Великий поэт сказал однажды так: Бродят в ночи корабли и друг друга зовут неустанно:/Голос – короткий гудок, отзвук далекий в тумане./Так же мы ищем друг друга в жизни, как в океане:/Голос и взгляд, а потом – лишь темнота да молчанье.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12218,'Если вам нужно продовольствие, об этом позаботится галерный повар Грейс.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если вам нужно продовольствие, об этом позаботится галерный повар Грейс.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12219,'Комбс, корабельный механик и квартирмейстер, выдаст вам все припасы, какие могут потребоваться. Кроме того, он хороший ремонтник – на случай, если вам нужно что-нибудь починить.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Комбс, корабельный механик и квартирмейстер, выдаст вам все припасы, какие могут потребоваться. Кроме того, он хороший ремонтник – на случай, если вам нужно что-нибудь починить.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12220,'Ах, да… имя. Ну, говорят, доброе имя – что добрая слава: обрести трудно, потерять легко. Далеко ходить не надо: взять хотя бы меня.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ах, да… имя. Ну, говорят, доброе имя – что добрая слава: обрести трудно, потерять легко. Далеко ходить не надо: взять хотя бы меня.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12221,'Мертвые поднимутся из могил и отомстят тем, кто осмелится шагнуть на их землю. Поверни назад, пока не поздно!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мертвые поднимутся из могил и отомстят тем, кто осмелится шагнуть на их землю. Поверни назад, пока не поздно!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12222,'Везет мне, все-таки. Многим ли тауренам удается послужить юнгой на таком фрегате? Греззикс даже позволяет мне управлять этими боевыми шлюпками!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Везет мне, все-таки. Многим ли тауренам удается послужить юнгой на таком фрегате? Греззикс даже позволяет мне управлять этими боевыми шлюпками!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12227,'Этот портал не похож на другие, ведущие обратно на Азерот. Чтоб сохранить его, нам потребуется еще больше контейнеров с маной.$B$BБез этого мы рискуем потерять доступ на остров Кель\'Данас и к Солнечному Колодцу.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Этот портал не похож на другие, ведущие обратно на Азерот. Чтоб сохранить его, нам потребуется еще больше контейнеров с маной.$B$BБез этого мы рискуем потерять доступ на остров Кель\'Данас и к Солнечному Колодцу.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12237,'Здравствуйте, |3-6($r).$b$bМоя лавка наконец-то открыта. Надеюсь, вам тут все понравится!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Здравствуйте, |3-6($r).$b$bМоя лавка наконец-то открыта. Надеюсь, вам тут все понравится!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12238,'Добрый день, |3-6($c).$b$bМногое нужно сделать, чтоб помочь нам. К сожалению, я очень мало могу для тебя сделать, пока не соберу все свои припасы.$b$bСейчас у меня имеется $3223w |4процент:процента:процентов; корней острошипа, нужных мне для начала. Любая помощь с твоей стороны пригодится.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Добрый день, |3-6($c).$b$bМногое нужно сделать, чтоб помочь нам. К сожалению, я очень мало могу для тебя сделать, пока не соберу все свои припасы.$b$bСейчас у меня имеется $3223w |4процент:процента:процентов; корней острошипа, нужных мне для начала. Любая помощь с твоей стороны пригодится.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12239,'Вот врата, через которые войска Келя отступили к Солнечному Колодцу. Некоторые из его прихвостней остались здесь. Легион вознаградил их очень… необычным способом.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Вот врата, через которые войска Келя отступили к Солнечному Колодцу. Некоторые из его прихвостней остались здесь. Легион вознаградил их очень… необычным способом.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12240,'Ты $gвидел:видела; раненых охранников, которые бродят по острову? Небольшие изменения в кристаллах, контролирующих их поведение, позволит нам взять их под контроль и использовать для охраны тактических позиций.$B$BСвятилище Солнечного Края будет нашим в ближайшее время. Мы на $3244w |4процент:процента:процентов; добились этой цели.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты $gвидел:видела; раненых охранников, которые бродят по острову? Небольшие изменения в кристаллах, контролирующих их поведение, позволит нам взять их под контроль и использовать для охраны тактических позиций.$B$BСвятилище Солнечного Края будет нашим в ближайшее время. Мы на $3244w |4процент:процента:процентов; добились этой цели.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12241,'Наша попытка захватить Святилище увенчалась успехом. Мы можем продолжать обращать стражей и использовать их в качестве стражников в других стратегически важных территориях.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Наша попытка захватить Святилище увенчалась успехом. Мы можем продолжать обращать стражей и использовать их в качестве стражников в других стратегически важных территориях.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12242,'Хей! Хочешь прокатиться на "Сестренке милосердия"? А билет у тебя есть?..') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Хей! Хочешь прокатиться на "Сестренке милосердия"? А билет у тебя есть?..',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (12243,'Мы должно убедиться, что больше мы не потеряем в этих морях ни одной живой души.','Мы должно убедиться, что больше мы не потеряем в этих морях ни одной живой души.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы должно убедиться, что больше мы не потеряем в этих морях ни одной живой души.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мы должно убедиться, что больше мы не потеряем в этих морях ни одной живой души.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
