INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (12245,'Море унесло очень много жизней. Мы с духами разыскиваем тела погибших.','Море унесло очень много жизней. Мы с духами разыскиваем тела погибших.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Море унесло очень много жизней. Мы с духами разыскиваем тела погибших.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Море унесло очень много жизней. Мы с духами разыскиваем тела погибших.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (12246,'Мы с огоньками ищем в морях все погибшие души.','Мы с огоньками ищем в морях все погибшие души.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы с огоньками ищем в морях все погибшие души.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мы с огоньками ищем в морях все погибшие души.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (12247,'Море – опасное место, |3-6($c). Нам нужно быть начеку.','Море – опасное место, |3-6($c). Нам нужно быть начеку.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Море – опасное место, |3-6($c). Нам нужно быть начеку.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Море – опасное место, |3-6($c). Нам нужно быть начеку.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (12248,'Боюсь, сейчас я не могу с тобой говорить.','Боюсь, сейчас я не могу с тобой говорить.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Боюсь, сейчас я не могу с тобой говорить.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Боюсь, сейчас я не могу с тобой говорить.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12252,'На моей работе не так часто видишь сражения. Служить рядом с передовой в зоне военных действий – неплохая смена обстановки.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','На моей работе не так часто видишь сражения. Служить рядом с передовой в зоне военных действий – неплохая смена обстановки.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12256,'Мы захватили арсенал, но наша работа на острове еще не закончена.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы захватили арсенал, но наша работа на острове еще не закончена.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12260,'Если мы вооружим охрану святилища, это поможет обеспечить его безопасность. Нам не нужно, чтобы кто-то из Презренных помешал нам, когда мы начнем массированную атаку на Легион и Келя.$B$BМы на $3244w % добились нашей цели.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если мы вооружим охрану святилища, это поможет обеспечить его безопасность. Нам не нужно, чтобы кто-то из Презренных помешал нам, когда мы начнем массированную атаку на Легион и Келя.$B$BМы на $3244w % добились нашей цели.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12262,'Команда "Доблести" сделает все, чтобы ваше путешествие было быстрым и приятным!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Команда "Доблести" сделает все, чтобы ваше путешествие было быстрым и приятным!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12263,'Извини, но нам придется поговорить как-нибудь в другой раз. Прощай.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Извини, но нам придется поговорить как-нибудь в другой раз. Прощай.',`text0_0_loc8`);
-- ruRU; source: emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12264,'Добро пожаловать на борт "Доблести", $gсэр:мадам;. А теперь прошу меня извинить…') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Добро пожаловать на борт "Доблести", $gсэр:мадам;. А теперь прошу меня извинить…',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12266,'Я почти ревную к нашему первому помощнику, Волнопеву. Подумать только, он, может быть, красивее меня!..') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я почти ревную к нашему первому помощнику, Волнопеву. Подумать только, он, может быть, красивее меня!..',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12267,'Сомнительное имечко для моряка, м-да.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Сомнительное имечко для моряка, м-да.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12268,'Я не только старше всех на корабле, но и всех сильнее! Каково, а? Ручищи, как у огра!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я не только старше всех на корабле, но и всех сильнее! Каково, а? Ручищи, как у огра!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12272,'Да, на нем ты и стоишь. Красивый корабль, правда? Барон не так давно назначил меня капитаном. Но сам корабль не мой, имя ему давал не я, и как по мне, тот, кто это имя давал, слишком уж много времени провел в море, и слишком мало – на берегу, если ты понимаешь, про что я.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да, на нем ты и стоишь. Красивый корабль, правда? Барон не так давно назначил меня капитаном. Но сам корабль не мой, имя ему давал не я, и как по мне, тот, кто это имя давал, слишком уж много времени провел в море, и слишком мало – на берегу, если ты понимаешь, про что я.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12273,'Если твой живот урчит, поговори с галерным коком Сталебрюхом, но, между нами говоря, ты бы лучше $gподождал:подождала;. У него недаром такое прозвище.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если твой живот урчит, поговори с галерным коком Сталебрюхом, но, между нами говоря, ты бы лучше $gподождал:подождала;. У него недаром такое прозвище.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12274,'Ну что за корабль без механика, а? Гнутая Игла поможет вам во всем, что нужно. И очень ловко и быстро все починит.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ну что за корабль без механика, а? Гнутая Игла поможет вам во всем, что нужно. И очень ловко и быстро все починит.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12275,'Добро пожаловать на борт переправы Оперенной Луны. Мы ходим между крепостью и Забытым берегом, разыскивая тех, кто пропал в море. Для того, кто не готов, море может быть очень опасным.$b$bЕсли хочешь подготовиться как следует, поговори, пожалуйста, с нашими поставщиками. Они с огромной радостью тебе помогут.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать на борт переправы Оперенной Луны. Мы ходим между крепостью и Забытым берегом, разыскивая тех, кто пропал в море. Для того, кто не готов, море может быть очень опасным.$b$bЕсли хочешь подготовиться как следует, поговори, пожалуйста, с нашими поставщиками. Они с огромной радостью тебе помогут.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12276,'От имени команды "Лунной пыли" я приветствую тебя, |3-6($c). Надеюсь, ты воспользуешься услугами наших поставщиков продукции прежде, чем отправиться с нами.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','От имени команды "Лунной пыли" я приветствую тебя, |3-6($c). Надеюсь, ты воспользуешься услугами наших поставщиков продукции прежде, чем отправиться с нами.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12277,'Ступай осторожно на борту "Благословения Элуны", |3-6($r). Хотя Элуна благословила нас встречей с новыми друзьями, на нашу долю выпало и немало тягот на море.$b$bОднако спасение душ, потерянных в море или в новом мире, – настоящее благословение Элуны.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ступай осторожно на борту "Благословения Элуны", |3-6($r). Хотя Элуна благословила нас встречей с новыми друзьями, на нашу долю выпало и немало тягот на море.$b$bОднако спасение душ, потерянных в море или в новом мире, – настоящее благословение Элуны.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (12278,'Элуна не раз благословляла нас и подсказывала нам пути к новым открытиям. Но нам стоит сохранять бдительность, |3-6($c).','Элуна не раз благословляла нас и подсказывала нам пути к новым открытиям. Но нам стоит сохранять бдительность, |3-6($c).') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Элуна не раз благословляла нас и подсказывала нам пути к новым открытиям. Но нам стоит сохранять бдительность, |3-6($c).',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Элуна не раз благословляла нас и подсказывала нам пути к новым открытиям. Но нам стоит сохранять бдительность, |3-6($c).',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12279,'Пожалуйста, |3-6($r), не отвлекай меня от работы.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Пожалуйста, |3-6($r), не отвлекай меня от работы.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12280,'Извини, мне некогда болтать. Я еле успеваю говорить с огоньками и отчитываться перед капитаном о находках. Прости меня.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Извини, мне некогда болтать. Я еле успеваю говорить с огоньками и отчитываться перед капитаном о находках. Прости меня.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12281,'Добро пожаловать на борт "Девичьего каприза". Нас ожидает приятное плавание.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать на борт "Девичьего каприза". Нас ожидает приятное плавание.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12282,'Просто поразительно, как много можно узнать от гнома, если прижать его как следует: как делать всякие хитрые штучки, помогающие выбраться из безвыходного положения, готовить вкусное печенье, и даже как построить ветролет!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Просто поразительно, как много можно узнать от гнома, если прижать его как следует: как делать всякие хитрые штучки, помогающие выбраться из безвыходного положения, готовить вкусное печенье, и даже как построить ветролет!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12283,'Чем чаще, тем лучше! Прекрасно помогает держать себя в форме, знаешь ли. А еще это хороший способ выведать, чего они там замышляют (как правило, ничего хорошего).') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Чем чаще, тем лучше! Прекрасно помогает держать себя в форме, знаешь ли. А еще это хороший способ выведать, чего они там замышляют (как правило, ничего хорошего).',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12284,'Урр… Если этот грязный корабельный повар предложит тебе свое блюдо, окажи услугу – выбрось еду в океан. Этим можно убить несколько макрур – вместо твоего здоровья.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Урр… Если этот грязный корабельный повар предложит тебе свое блюдо, окажи услугу – выбрось еду в океан. Этим можно убить несколько макрур – вместо твоего здоровья.',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12285,'Привет, |3-6($r).$b$bДавай-ка возьмемся за дело! Какой смысл дожидаться поставок, которые могут и вовсе не прибыть!$b$bМне нужна моя наковальня, чтобы как следует снарядить наши войска. Сейчас она готова на $3228w |4процент:процента:процентов;.$b$bСообщи всем, кого знаешь: мне пригодится любая помощь!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Привет, |3-6($r).$b$bДавай-ка возьмемся за дело! Какой смысл дожидаться поставок, которые могут и вовсе не прибыть!$b$bМне нужна моя наковальня, чтобы как следует снарядить наши войска. Сейчас она готова на $3228w |4процент:процента:процентов;.$b$bСообщи всем, кого знаешь: мне пригодится любая помощь!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12286,'Привет, $n.$b$bТеперь, когда я закончила работу над своей наковальней, я могу заняться экипировкой наших войск. Это важный шаг, но сделать нужно еще очень много.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Привет, $n.$b$bТеперь, когда я закончила работу над своей наковальней, я могу заняться экипировкой наших войск. Это важный шаг, но сделать нужно еще очень много.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12288,'Добро пожаловать на борт "Призывателя грома"!$b$bНе обращайте внимания на тех, кто жалуется на взрывы и все такое. Ну, то есть – у всех бывают ошибки. Надо быть снисходительнее к людям.$b$bЯ понимаю, если капитан разбил корабль 22-23 раза… Но если меньше – тут и говорить не о чем.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать на борт "Призывателя грома"!$b$bНе обращайте внимания на тех, кто жалуется на взрывы и все такое. Ну, то есть – у всех бывают ошибки. Надо быть снисходительнее к людям.$b$bЯ понимаю, если капитан разбил корабль 22-23 раза… Но если меньше – тут и говорить не о чем.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text3_0_loc8`,`text4_0_loc8`,`text5_0_loc8`) VALUES (12289,'Я, конечно, рад, что сосновые ветви не особо повредили наш корабль.$b$bНо это слабое утешение, учитывая, что мы три раза врезались в деревья.','Я никогда не думал, что увижу Тельдрассил… И уж точно мне и в голову не приходило, что мы грохнемся туда.','Нам удалось пролететь сквозь Громовой Утес уже дважды!') ON DUPLICATE KEY UPDATE `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Я, конечно, рад, что сосновые ветви не особо повредили наш корабль.$b$bНо это слабое утешение, учитывая, что мы три раза врезались в деревья.',`text3_0_loc8`), `text4_0_loc8`=IF(`text4_0_loc8` IS NULL OR `text4_0_loc8`='','Я никогда не думал, что увижу Тельдрассил… И уж точно мне и в голову не приходило, что мы грохнемся туда.',`text4_0_loc8`), `text5_0_loc8`=IF(`text5_0_loc8` IS NULL OR `text5_0_loc8`='','Нам удалось пролететь сквозь Громовой Утес уже дважды!',`text5_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12290,'Любишь острые ощущения? Тогда тебе у нас понравится! Я свою работу обожаю!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Любишь острые ощущения? Тогда тебе у нас понравится! Я свою работу обожаю!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12291,'Не спрашивай…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не спрашивай…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12292,'Я ни в чем не виноват… Я даже не вижу, куда мы летим!$b$bХотя, возможно, это как раз значит, что я виноват…$b$bНет! Погоди! Я вполне могу приземлить этот корабль… Наверное, это все приказы нашего капитана! Видимо, он захотел проверить пределы возможностей экипажа, испытать наши навыки выживания и инженерную смекалку.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я ни в чем не виноват… Я даже не вижу, куда мы летим!$b$bХотя, возможно, это как раз значит, что я виноват…$b$bНет! Погоди! Я вполне могу приземлить этот корабль… Наверное, это все приказы нашего капитана! Видимо, он захотел проверить пределы возможностей экипажа, испытать наши навыки выживания и инженерную смекалку.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12294,'Меня звали Иололом, пока в городе не прошло тайное голосование, в результате которого меня заставили сменить имя. Так и сказали: либо меняй его, либо иди по стопам Корки. Ты бы $gсам:сама; так же $gпоступил:поступила;. А как тебе мое новое имя? Правда, намного лучше?$B$BКстати, если ты ищешь работу, глянь на доску объявлений.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Меня звали Иололом, пока в городе не прошло тайное голосование, в результате которого меня заставили сменить имя. Так и сказали: либо меняй его, либо иди по стопам Корки. Ты бы $gсам:сама; так же $gпоступил:поступила;. А как тебе мое новое имя? Правда, намного лучше?$B$BКстати, если ты ищешь работу, глянь на доску объявлений.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12300,'Я рад, что ты $gспросил:спросила; об этом. Оружейная захвачена всего на $3233w |4процент:процента:процентов; от запланированного.$B$BЯ знаю, что боевой маг Аринна и Предвестник Иннуро нуждаются в твоей помощи. Их можно найти в святилище Солнечного Края на острове Кель\'Данас.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я рад, что ты $gспросил:спросила; об этом. Оружейная захвачена всего на $3233w |4процент:процента:процентов; от запланированного.$B$BЯ знаю, что боевой маг Аринна и Предвестник Иннуро нуждаются в твоей помощи. Их можно найти в святилище Солнечного Края на острове Кель\'Данас.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12304,'Мы пытаемся уничтожить первые врата, Агамат. $C, прошу тебя, отправляйся на остров Кель\'Данас и помоги, чем можешь!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы пытаемся уничтожить первые врата, Агамат. $C, прошу тебя, отправляйся на остров Кель\'Данас и помоги, чем можешь!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12305,'Агамат пал! Первые врата уничтожены! Теперь надо уничтожить двух приспешниц Кил\'джедена, леди Сакролаш и главную чернокнижницу Алитессу.$B$BСобирай друзей, |3-6($c), и вступай в бой! Следующая цель – Рохендор, вторые врата!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Агамат пал! Первые врата уничтожены! Теперь надо уничтожить двух приспешниц Кил\'джедена, леди Сакролаш и главную чернокнижницу Алитессу.$B$BСобирай друзей, |3-6($c), и вступай в бой! Следующая цель – Рохендор, вторые врата!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12314,'"Железный орел". Хм. Это же пассажирское судно, а не военное! Но что поделать, работа есть работа, буду ублажать капитана "Надутого" пока принц платит.$b$bКак бы то ни было, добро пожаловать на борт.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','"Железный орел". Хм. Это же пассажирское судно, а не военное! Но что поделать, работа есть работа, буду ублажать капитана "Надутого" пока принц платит.$b$bКак бы то ни было, добро пожаловать на борт.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text3_0_loc8`,`text3_1_loc8`) VALUES (12315,'Тебе нужно что-то починить? Воспользуйся "Торг-о-троном делюкс"!','Тебе нужно что-то починить? Воспользуйся "Торг-о-троном делюкс"!') ON DUPLICATE KEY UPDATE `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Тебе нужно что-то починить? Воспользуйся "Торг-о-троном делюкс"!',`text3_0_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','Тебе нужно что-то починить? Воспользуйся "Торг-о-троном делюкс"!',`text3_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (12316,'Мы защищаем этот дирижабль в пути от Оргриммара до лагеря Гром\'гол в Тернистой долине.','Мы защищаем этот дирижабль в пути от Оргриммара до лагеря Гром\'гол в Тернистой долине.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы защищаем этот дирижабль в пути от Оргриммара до лагеря Гром\'гол в Тернистой долине.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мы защищаем этот дирижабль в пути от Оргриммара до лагеря Гром\'гол в Тернистой долине.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12317,'Не сейчас, $gпарень:красотка;… У меня дел много. В другой раз.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не сейчас, $gпарень:красотка;… У меня дел много. В другой раз.',`text0_0_loc8`);
