INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12319,'Мы почти установили контроль над Солнечным Краем. Если нам удастся не пропустить в порт подкрепление, мы победим.$B$BМы на $3238w % добились нашей цели.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы почти установили контроль над Солнечным Краем. Если нам удастся не пропустить в порт подкрепление, мы победим.$B$BМы на $3238w % добились нашей цели.',`text0_0_loc8`);
