INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12322,'Я собираю средства для возведения монумента в честь погибших на войне. Это важно: не забывать, на какие жертвы мы пошли ради победы.$B$BМы на $3275w |4процент:процента:процентов; добились этой цели.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я собираю средства для возведения монумента в честь погибших на войне. Это важно: не забывать, на какие жертвы мы пошли ради победы.$B$BМы на $3275w |4процент:процента:процентов; добились этой цели.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12323,'Правда, этот памятник прекрасен? Очень важно помнить те моменты нашей истории, когда были принесены великие жертвы, и не забывать цену войн – даже выигранных.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Правда, этот памятник прекрасен? Очень важно помнить те моменты нашей истории, когда были принесены великие жертвы, и не забывать цену войн – даже выигранных.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12327,'Добро пожаловать на борт, |3-6($c). Размещайте свои вещи и наслаждайтесь путешествием. Мы хотим, чтобы на борту "Лиловой принцессы" вы отдохнули как следует. Внизу у нас стоят торговые автоматы – на тот случай, если вам что-нибудь понадобится.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Добро пожаловать на борт, |3-6($c). Размещайте свои вещи и наслаждайтесь путешествием. Мы хотим, чтобы на борту "Лиловой принцессы" вы отдохнули как следует. Внизу у нас стоят торговые автоматы – на тот случай, если вам что-нибудь понадобится.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12328,'Отдых – залог успеха. Если ребята хорошо отдохнули, дело у них спорится.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Отдых – залог успеха. Если ребята хорошо отдохнули, дело у них спорится.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12329,'Капитан у нас золотой! Когда мы стоим в доке, нам дают отдохнуть. Эти моменты я люблю больше всего.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Капитан у нас золотой! Когда мы стоим в доке, нам дают отдохнуть. Эти моменты я люблю больше всего.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12330,'Пожалуйста, дайте передохнуть несколько секунд.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Пожалуйста, дайте передохнуть несколько секунд.',`text0_0_loc8`);
