INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12331,'Ну, дайте ж поспать пять минут…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ну, дайте ж поспать пять минут…',`text0_0_loc8`);
