INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`,`text2_0_loc8`,`text2_1_loc8`) VALUES (12332,'Сейчас я занят.','Сейчас я занята.','Тебе нужно что-то починить? Воспользуйся "Торг-о-троном"!','Тебе нужно что-то починить? Воспользуйся "Торг-о-троном"!','У меня сейчас нет времени говорить.','У меня сейчас нет времени говорить.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Сейчас я занят.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Сейчас я занята.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Тебе нужно что-то починить? Воспользуйся "Торг-о-троном"!',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Тебе нужно что-то починить? Воспользуйся "Торг-о-троном"!',`text1_1_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','У меня сейчас нет времени говорить.',`text2_0_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','У меня сейчас нет времени говорить.',`text2_1_loc8`);
