INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12333,'Полеты из Гром\'гола в Подгород красивы, хоть и проходят без особых происшествий. Но это не повод спать на работе.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Полеты из Гром\'гола в Подгород красивы, хоть и проходят без особых происшествий. Но это не повод спать на работе.',`text0_1_loc8`);
