INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12334,'Заходи, отряхни с одежды грязь и пепел. Передохни с пути.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Заходи, отряхни с одежды грязь и пепел. Передохни с пути.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`,`text2_0_loc8`,`text2_1_loc8`,`text3_0_loc8`,`text3_1_loc8`) VALUES (12336,'А тебе удалось попасть на их концерт в лесу Тероккар? Это было потрясающе!','А тебе удалось попасть на их концерт в лесу Тероккар? Это было потрясающе!','"Вожди тауренов" – самая отвязная группа во всем Азероте!','"Вожди тауренов" – самая отвязная группа во всем Азероте!','Интересно, сколько они еще будут в Луносвете. Надеюсь, они тут играют!','Интересно, сколько они еще будут в Луносвете. Надеюсь, они тут играют!','Я бы почти все отдал за возможность подняться туда и поговорить с ними…','Я бы почти все отдала за возможность подняться туда и поговорить с ними…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','А тебе удалось попасть на их концерт в лесу Тероккар? Это было потрясающе!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','А тебе удалось попасть на их концерт в лесу Тероккар? Это было потрясающе!',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','"Вожди тауренов" – самая отвязная группа во всем Азероте!',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','"Вожди тауренов" – самая отвязная группа во всем Азероте!',`text1_1_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Интересно, сколько они еще будут в Луносвете. Надеюсь, они тут играют!',`text2_0_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Интересно, сколько они еще будут в Луносвете. Надеюсь, они тут играют!',`text2_1_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Я бы почти все отдал за возможность подняться туда и поговорить с ними…',`text3_0_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','Я бы почти все отдала за возможность подняться туда и поговорить с ними…',`text3_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12339,'Надо преподать лакеям Келя урок скромности. Мы сокрушим армию Клинка Рассвета и отобьем у них бухту Солнечного Края.$B$BМы на $3238w |4процент:процента:процентов; добились своей цели.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Надо преподать лакеям Келя урок скромности. Мы сокрушим армию Клинка Рассвета и отобьем у них бухту Солнечного Края.$B$BМы на $3238w |4процент:процента:процентов; добились своей цели.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12343,'Ммррглглглгл? Глбмр брммрггл глмррбмргл.$B$BГрглгрлбрр мргл!!!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ммррглглглгл? Глбмр брммрггл глмррбмргл.$B$BГрглгрлбрр мргл!!!',`text0_0_loc8`);
