INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12357,'Я недавно прибыл сюда для наблюдения за мурлоками из клана Зимних Плавников. Загримировавшись под одного из них, я держался на расстоянии и делал заметки об их повседневной жизни.$B$BОднако вскоре, после моего прибытия, все изменилось.$B$BЗемлетрясение в Хладарре вызвало оползень, обнаживший близлежащие пещеры. Из них выбрался странный макрура, который утащил головастиков Зимних Плавников. Когда мурлоки отправились в пещеры, чтобы спасти своих детенышей, они вернулись светящимися и попавшими под влияние макруры.$B$BТеперь незатронутые всем этим отступили сюда, а мне поневоле пришлось взять на себя командование ими.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я недавно прибыл сюда для наблюдения за мурлоками из клана Зимних Плавников. Загримировавшись под одного из них, я держался на расстоянии и делал заметки об их повседневной жизни.$B$BОднако вскоре, после моего прибытия, все изменилось.$B$BЗемлетрясение в Хладарре вызвало оползень, обнаживший близлежащие пещеры. Из них выбрался странный макрура, который утащил головастиков Зимних Плавников. Когда мурлоки отправились в пещеры, чтобы спасти своих детенышей, они вернулись светящимися и попавшими под влияние макруры.$B$BТеперь незатронутые всем этим отступили сюда, а мне поневоле пришлось взять на себя командование ими.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12360,'Блург аврургле мрр?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Блург аврургле мрр?',`text0_0_loc8`);
