INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12364,'Я – Атуик, старейшина Калу\'ак из Камагуа.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я – Атуик, старейшина Калу\'ак из Камагуа.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12370,'Проклятие Кель\'тасу и его сброду! Все, над чем мы трудились, погублено, но напрасно они думают, что мы не станем сражаться. Леди Лиадрин уже ищет новый источник силы для нашего ордена. Нас так легко не уничтожишь!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Проклятие Кель\'тасу и его сброду! Все, над чем мы трудились, погублено, но напрасно они думают, что мы не станем сражаться. Леди Лиадрин уже ищет новый источник силы для нашего ордена. Нас так легко не уничтожишь!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12373,'Разрушение Оргриммара было направлено не только против орков, это был вызов всей Орде. Атака против самого нашего существования! $B$BКороль-лич думал посеять панику и страх.$B$BЭто…$B$B<Гаррош указывает пальцем на укрепленные стены, окружающие его.>$B$BЭто результат кампании Артаса.$B$BОрда не боится ничего и никого…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Разрушение Оргриммара было направлено не только против орков, это был вызов всей Орде. Атака против самого нашего существования! $B$BКороль-лич думал посеять панику и страх.$B$BЭто…$B$B<Гаррош указывает пальцем на укрепленные стены, окружающие его.>$B$BЭто результат кампании Артаса.$B$BОрда не боится ничего и никого…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12374,'Ты $gпришел:пришла; к костру Орды! Оскверни и затопчи этот костер!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты $gпришел:пришла; к костру Орды! Оскверни и затопчи этот костер!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`,`text2_0_loc8`,`text2_1_loc8`,`text3_0_loc8`,`text3_1_loc8`) VALUES (12376,'На празднике Огненного солнцеворота развлечения найдутся для всех!','На празднике Огненного солнцеворота развлечения найдутся для всех!','Наши огни пылают по всей земле!','Наши огни пылают по всей земле!','Удалось уже поплясать у праздничного шеста?','Удалось уже поплясать у праздничного шеста?','Я восхищаюсь мастерством огненных жонглеров.','Я восхищаюсь мастерством огненных жонглеров.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','На празднике Огненного солнцеворота развлечения найдутся для всех!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','На празднике Огненного солнцеворота развлечения найдутся для всех!',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Наши огни пылают по всей земле!',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Наши огни пылают по всей земле!',`text1_1_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Удалось уже поплясать у праздничного шеста?',`text2_0_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Удалось уже поплясать у праздничного шеста?',`text2_1_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Я восхищаюсь мастерством огненных жонглеров.',`text3_0_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','Я восхищаюсь мастерством огненных жонглеров.',`text3_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12377,'Ты $gпришел:пришла; к костру Альянса! Оскверни и затопчи этот костер!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты $gпришел:пришла; к костру Альянса! Оскверни и затопчи этот костер!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12381,'Страх всегда был нашим лучшим оружием. Целые войны выигрывались и проигрывались на шатких плечах трепета и сомнения. Так как тогда сражаться с врагом, не ведающим страха?$B$B<Саурфанг качает головой.>$B$BМы не просто сражаемся с армией Плети в Нордсколе, мы стремимся получить контроль над нашими чувствами прежде, чем они разорвут нас на части…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Страх всегда был нашим лучшим оружием. Целые войны выигрывались и проигрывались на шатких плечах трепета и сомнения. Так как тогда сражаться с врагом, не ведающим страха?$B$B<Саурфанг качает головой.>$B$BМы не просто сражаемся с армией Плети в Нордсколе, мы стремимся получить контроль над нашими чувствами прежде, чем они разорвут нас на части…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12382,'Нам необходимо подготовить этот аванпост к маршу на Низину Шолазар.$B$BДа не стой столбом, |3-6($c). Выметайся и покажи всем, что значит быть Ордой: купаться в лучах славы и реках крови!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Нам необходимо подготовить этот аванпост к маршу на Низину Шолазар.$B$BДа не стой столбом, |3-6($c). Выметайся и покажи всем, что значит быть Ордой: купаться в лучах славы и реках крови!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12384,'Мне нужно тут убрать весь этот беспорядок, но на это я жаловаться не стану.$B$BА ты поможешь мне, если у тебя есть хоть капля гордости настоящего ордынца!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мне нужно тут убрать весь этот беспорядок, но на это я жаловаться не стану.$B$BА ты поможешь мне, если у тебя есть хоть капля гордости настоящего ордынца!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12387,'Духи разговаривают рядом с нами. Ты слушаешь их, |3-6($r)?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Духи разговаривают рядом с нами. Ты слушаешь их, |3-6($r)?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
