INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (12390,'Культ Сумеречного Молота стремится уничтожить все, что мы хотим сохранить. Наш долг – не допустить беды, |3-6($r).','Культ Сумеречного Молота стремится уничтожить все, что мы хотим сохранить. Наш долг – не допустить беды, |3-6($r).') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Культ Сумеречного Молота стремится уничтожить все, что мы хотим сохранить. Наш долг – не допустить беды, |3-6($r).',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Культ Сумеречного Молота стремится уничтожить все, что мы хотим сохранить. Наш долг – не допустить беды, |3-6($r).',`text0_1_loc8`);
