INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12394,'Я обесчещен. Мне лучше было умереть вместе с предсказателем в Магмоте.$B$BОставь меня наедине с моими мыслями.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я обесчещен. Мне лучше было умереть вместе с предсказателем в Магмоте.$B$BОставь меня наедине с моими мыслями.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12395,'Духи воздуха встревожены. Берегись… они не позволят тебе пройти $gневредимым:невредимой;.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Духи воздуха встревожены. Берегись… они не позволят тебе пройти $gневредимым:невредимой;.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12403,'Мне больно видеть, как моих предков беспокоят в их могилах.$B$BМы должны сразить проклятый дух вашего командира соединения Стальная Челюсть, по глупости проведшего свой караван через эти священные места.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мне больно видеть, как моих предков беспокоят в их могилах.$B$BМы должны сразить проклятый дух вашего командира соединения Стальная Челюсть, по глупости проведшего свой караван через эти священные места.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12417,'Мы потеряли довольно много ветрокрылов во время разведывательных миссий на западе. Силы Плети безжалостны к потенциальным шпионам.$B$BК счастью, я нашел решение, при котором риску подвергается только всадник. Выживают 30% из тех, кого провозят через равнины Назама. Это ж на целых 30% лучше, чем при использовании ветрокрылов!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы потеряли довольно много ветрокрылов во время разведывательных миссий на западе. Силы Плети безжалостны к потенциальным шпионам.$B$BК счастью, я нашел решение, при котором риску подвергается только всадник. Выживают 30% из тех, кого провозят через равнины Назама. Это ж на целых 30% лучше, чем при использовании ветрокрылов!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12419,'Я опозорен. Мне следовало умереть в Магмоте вместе с предсказателем!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я опозорен. Мне следовало умереть в Магмоте вместе с предсказателем!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12422,'И лагерь Гарроша, и Пал\'ия были стерты с лица земли этим туманом. Мы единственные сумасшедшие, кто остался здесь, дружище!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','И лагерь Гарроша, и Пал\'ия были стерты с лица земли этим туманом. Мы единственные сумасшедшие, кто остался здесь, дружище!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12423,'Как я могу что-то сделать, если Выкрутень все время стоит у меня над душой, а у меня в руках нет моих инструментов?!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Как я могу что-то сделать, если Выкрутень все время стоит у меня над душой, а у меня в руках нет моих инструментов?!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12424,'То, что ты видишь на берегу – это не фокусы Плети. На самом деле, мы думаем, что приспешники Плети тоже боятся тумана, и поэтому, может быть, они сюда и не приходят.$B$BВидишь ли, этот туман живой, друг. Внутри этих клубов воздуха находится смерть… $B$BЕсли ты вступишь в одно из его призрачных щупальцев, ты исчезнешь. Туман заберет тебя!$B$BМы никогда не видели, чтобы кто-то вернулся живым из тумана.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','То, что ты видишь на берегу – это не фокусы Плети. На самом деле, мы думаем, что приспешники Плети тоже боятся тумана, и поэтому, может быть, они сюда и не приходят.$B$BВидишь ли, этот туман живой, друг. Внутри этих клубов воздуха находится смерть… $B$BЕсли ты вступишь в одно из его призрачных щупальцев, ты исчезнешь. Туман заберет тебя!$B$BМы никогда не видели, чтобы кто-то вернулся живым из тумана.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12426,'После высадки здесь я видел ужасы, которые ранее посещали меня лишь в самых жутких кошмарах, но ничто не могло меня подготовить к тому, что лежит за туманом.$B$B<Муту кивает.>$B$BЗа этим туманом не далее, чем в нескольких ярдах от нас, стоят кровожадные существа, известные как квалдиры. Никто не вернулся из тумана, и мало из тех, кто был на месте высадки, когда накатил туман, уцелел. Эта местность была позднее проклята Адским Криком. Входи на свой страх и риск…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','После высадки здесь я видел ужасы, которые ранее посещали меня лишь в самых жутких кошмарах, но ничто не могло меня подготовить к тому, что лежит за туманом.$B$B<Муту кивает.>$B$BЗа этим туманом не далее, чем в нескольких ярдах от нас, стоят кровожадные существа, известные как квалдиры. Никто не вернулся из тумана, и мало из тех, кто был на месте высадки, когда накатил туман, уцелел. Эта местность была позднее проклята Адским Криком. Входи на свой страх и риск…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12427,'Я… А ты…$B$B<Муту сотрясает дрожь>$B$BТы хочешь меня спасти?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я… А ты…$B$B<Муту сотрясает дрожь>$B$BТы хочешь меня спасти?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12433,'Как я рад тебя видеть! Я слишком слаб, чтобы разбить звенья этой ржавой цепи.$B$BНу же, не стой столбом! Освободи меня!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Как я рад тебя видеть! Я слишком слаб, чтобы разбить звенья этой ржавой цепи.$B$BНу же, не стой столбом! Освободи меня!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12435,'Я сейчас по горло занят, |3-6($c).$B$BЧем могу помочь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я сейчас по горло занят, |3-6($c).$B$BЧем могу помочь?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12440,'Говори помедленнее, дитя, я еще не привыкла к твоему странному говору.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Говори помедленнее, дитя, я еще не привыкла к твоему странному говору.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12441,'Пожалуйста, говори потише, |3-6($r). Хамат стара, и ей нужен отдых.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Пожалуйста, говори потише, |3-6($r). Хамат стара, и ей нужен отдых.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12472,'Действия этих дезертиров позорят нас всех. Позорят столь сильно, что это могут понять лишь те, кто знает, что это такое. Вот почему Уг\'тор здесь… Пареньку нужно знать.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Действия этих дезертиров позорят нас всех. Позорят столь сильно, что это могут понять лишь те, кто знает, что это такое. Вот почему Уг\'тор здесь… Пареньку нужно знать.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12475,'Будь поосторожнее тут, |3-6($r). Местные обитатели совершенно безжалостны.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Будь поосторожнее тут, |3-6($r). Местные обитатели совершенно безжалостны.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12485,'Твои помыслы чисты, а на сердце светло? Тогда добро пожаловать в обитель друидов, ратующих за этичное и гуманное отношение к животным. До тех пор, пока ты не станешь на темный путь греха и не причинишь вред животным, позволившим нам сосуществовать с ними в их мире, Д.Э.Г.О.Ж. будет считать тебя своим союзником.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Твои помыслы чисты, а на сердце светло? Тогда добро пожаловать в обитель друидов, ратующих за этичное и гуманное отношение к животным. До тех пор, пока ты не станешь на темный путь греха и не причинишь вред животным, позволившим нам сосуществовать с ними в их мире, Д.Э.Г.О.Ж. будет считать тебя своим союзником.',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12496,'Вы знали, что алхимики могут преобразовать определенные драгоценные камни? Мы говорили об этом с Мар\'ной.$B$BЯ убежден, что, благодаря ее мастерству, как только она завершит свое исследование, мы будем в состоянии воссоздать драгоценные камни, утерянные в веках.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Вы знали, что алхимики могут преобразовать определенные драгоценные камни? Мы говорили об этом с Мар\'ной.$B$BЯ убежден, что, благодаря ее мастерству, как только она завершит свое исследование, мы будем в состоянии воссоздать драгоценные камни, утерянные в веках.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
