INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (12524,'Камень излучает мертвенный холод, так что все вокруг – и даже воздух – становится холоднее льда. В глубине граней камня пульсирует синий свет…','Камень излучает мертвенный холод, так что все вокруг – и даже воздух – становится холоднее льда. В глубине граней камня пульсирует синий свет…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Камень излучает мертвенный холод, так что все вокруг – и даже воздух – становится холоднее льда. В глубине граней камня пульсирует синий свет…',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Камень излучает мертвенный холод, так что все вокруг – и даже воздух – становится холоднее льда. В глубине граней камня пульсирует синий свет…',`text0_1_loc8`);
