INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12556,'Сейчас я очень занята, |3-6($r). Прошу тебя, оставь меня в покое.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Сейчас я очень занята, |3-6($r). Прошу тебя, оставь меня в покое.',`text0_1_loc8`);
