INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12566,'Соберись, $gсмертный:смертная;. Здесь проходит линия фронта войны, не сравнимой с любой другой, которую тебе доводилось видеть.$b$bТебе понадобится полный контроль над собой, чтобы принести нам пользу.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Соберись, $gсмертный:смертная;. Здесь проходит линия фронта войны, не сравнимой с любой другой, которую тебе доводилось видеть.$b$bТебе понадобится полный контроль над собой, чтобы принести нам пользу.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (12571,'Тебе придется сдерживать натиск слуг Ахуна, пока мы будем направлять в цель огненные заклятья. Не приближайся к Повелителю Холода, пока он не утратит свою силу.','Тебе придется сдерживать натиск слуг Ахуна, пока мы будем направлять в цель огненные заклятья. Не приближайся к Повелителю Холода, пока он не утратит свою силу.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тебе придется сдерживать натиск слуг Ахуна, пока мы будем направлять в цель огненные заклятья. Не приближайся к Повелителю Холода, пока он не утратит свою силу.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Тебе придется сдерживать натиск слуг Ахуна, пока мы будем направлять в цель огненные заклятья. Не приближайся к Повелителю Холода, пока он не утратит свою силу.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (12572,'Когда Ахун выползет, будем ли мы готовы?','Когда Ахун выползет, будем ли мы готовы?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Когда Ахун выползет, будем ли мы готовы?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Когда Ахун выползет, будем ли мы готовы?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12575,'Земля в полном смятении!$B$BСнова надвигается Темный со своим Сен\'лейном, драконы сражаются в своей великой войне Нексуса, и снова проснулись врайкулы.$B$BТвой народ плавает на север на своих деревянных кораблях, чтобы сражаться с ними и друг с другом, а мы, народ калу\'ак, меж двух огней.$B$BА теперь свершилось какое-то великое зло, и земля взрывается от магической энергии мира. Мы должны найти безопасную гавань, где у нас будет шанс выжить.$B$BОт этих двух послов у меня голова раскалывается… может быть, ты сможешь помочь моему народу, |3-6($r)?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Земля в полном смятении!$B$BСнова надвигается Темный со своим Сен\'лейном, драконы сражаются в своей великой войне Нексуса, и снова проснулись врайкулы.$B$BТвой народ плавает на север на своих деревянных кораблях, чтобы сражаться с ними и друг с другом, а мы, народ калу\'ак, меж двух огней.$B$BА теперь свершилось какое-то великое зло, и земля взрывается от магической энергии мира. Мы должны найти безопасную гавань, где у нас будет шанс выжить.$B$BОт этих двух послов у меня голова раскалывается… может быть, ты сможешь помочь моему народу, |3-6($r)?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12577,'Ох…$b$bГде я?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ох…$b$bГде я?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (12582,'Добро пожаловать, |3-6($c). Ты $gпришел:пришла;, чтобы почтить праздничный огонь?$b$bЗнай: этот огонь горит во всех землях, где есть поселения Орды, – в каждом из них. Если сумеешь, попытайся найти время, чтобы почтить каждый праздничный костер.$b$bВ поселениях Альянса также зажигают свой праздничный огонь, но это – нечестивая насмешка над нашим древним ритуалом. Большим благом для нас стало бы, если бы тебе удалось пресечь святотатство и погасить эти костры.','Добро пожаловать, |3-6($c). Ты $gпришел:пришла;, чтобы почтить праздничный огонь?$b$bЗнай: этот огонь горит во всех землях, где есть поселения Орды, – в каждом из них. Если сумеешь, попытайся найти время, чтобы почтить каждый праздничный костер.$b$bВ поселениях Альянса также зажигают свой праздничный огонь, но это – нечестивая насмешка над нашим древним ритуалом. Большим благом для нас стало бы, если бы тебе удалось пресечь святотатство и погасить эти костры.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать, |3-6($c). Ты $gпришел:пришла;, чтобы почтить праздничный огонь?$b$bЗнай: этот огонь горит во всех землях, где есть поселения Орды, – в каждом из них. Если сумеешь, попытайся найти время, чтобы почтить каждый праздничный костер.$b$bВ поселениях Альянса также зажигают свой праздничный огонь, но это – нечестивая насмешка над нашим древним ритуалом. Большим благом для нас стало бы, если бы тебе удалось пресечь святотатство и погасить эти костры.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Добро пожаловать, |3-6($c). Ты $gпришел:пришла;, чтобы почтить праздничный огонь?$b$bЗнай: этот огонь горит во всех землях, где есть поселения Орды, – в каждом из них. Если сумеешь, попытайся найти время, чтобы почтить каждый праздничный костер.$b$bВ поселениях Альянса также зажигают свой праздничный огонь, но это – нечестивая насмешка над нашим древним ритуалом. Большим благом для нас стало бы, если бы тебе удалось пресечь святотатство и погасить эти костры.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (12587,'Я рад, что ты здесь. Теперь, когда ты знаешь все о наших праздничных огнях и о традиции их почитания… а также о кострах наших врагов и о том, что им должно угаснуть… ты можешь вернуться и получить свою награду.','Я рада, что ты здесь. Теперь, когда ты знаешь все о наших праздничных огнях и о традиции их почитания… а также о кострах наших врагов и о том, что им должно угаснуть… ты можешь вернуться и получить свою награду.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я рад, что ты здесь. Теперь, когда ты знаешь все о наших праздничных огнях и о традиции их почитания… а также о кострах наших врагов и о том, что им должно угаснуть… ты можешь вернуться и получить свою награду.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я рада, что ты здесь. Теперь, когда ты знаешь все о наших праздничных огнях и о традиции их почитания… а также о кострах наших врагов и о том, что им должно угаснуть… ты можешь вернуться и получить свою награду.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12591,'Мы продвигаемся, |3-6($r), но слишком медленно.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы продвигаемся, |3-6($r), но слишком медленно.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12592,'Мы должны победить! На кону – судьба Азерота…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы должны победить! На кону – судьба Азерота…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12596,'Хорошо, что ты здесь, |3-6($c). Обстановка на плато Солнечного Колодца становится напряженной.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Хорошо, что ты здесь, |3-6($c). Обстановка на плато Солнечного Колодца становится напряженной.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12598,'Армия Расколотого Солнца добилась больших успехов на внешних рубежах острова Кель\'Данас. Силы Кил\'джедена были оттеснены и в образовавшейся суматохе мне удалось провести небольшой отряд разведчиков сюда, на плато Солнечного Колодца. Моя группа пересекла Площадь Паргелия и обнаружила небольшой отряд эльфов крови Солнечного Клинка. А потом завязалась битва, переросшая в побоище.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Армия Расколотого Солнца добилась больших успехов на внешних рубежах острова Кель\'Данас. Силы Кил\'джедена были оттеснены и в образовавшейся суматохе мне удалось провести небольшой отряд разведчиков сюда, на плато Солнечного Колодца. Моя группа пересекла Площадь Паргелия и обнаружила небольшой отряд эльфов крови Солнечного Клинка. А потом завязалась битва, переросшая в побоище.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12599,'Защитники Кил\'джедена здесь на Плато Солнечного Колодца сильнее, чем кто бы то ни было, с кем мы сталкивались на этом острове. Легион к тому же смог извратить нашего Волшебного Стража, превратив его во что-то куда более жестокое. Только один такой Заступник клана Солнечного Клинка практически вырезал мой отряд, и я приказала отступить. Я ожидала, что моя команда будет полностью вытеснена с плато, но к моему удивлению они не стали нас преследовать.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Защитники Кил\'джедена здесь на Плато Солнечного Колодца сильнее, чем кто бы то ни было, с кем мы сталкивались на этом острове. Легион к тому же смог извратить нашего Волшебного Стража, превратив его во что-то куда более жестокое. Только один такой Заступник клана Солнечного Клинка практически вырезал мой отряд, и я приказала отступить. Я ожидала, что моя команда будет полностью вытеснена с плато, но к моему удивлению они не стали нас преследовать.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12600,'Не знаю, но я рада, что они сделали это. Отсрочка позволила Анахорету Илбадону спасти многих из моей команды. Я послала несколько своих самых хитрых разведчиков вперед, и они сообщили очень интересные сведения. Почти все Заступники клана Солнечного Клинка деактивированы! Войска Кил\'джедена, кажется, берегут силы и довольствуются тем, что удерживают нас на месте одним действующим Заступником. Если вы и ваши соратники хотите пробиться туда, позвольте мне изложить свой план.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Не знаю, но я рада, что они сделали это. Отсрочка позволила Анахорету Илбадону спасти многих из моей команды. Я послала несколько своих самых хитрых разведчиков вперед, и они сообщили очень интересные сведения. Почти все Заступники клана Солнечного Клинка деактивированы! Войска Кил\'джедена, кажется, берегут силы и довольствуются тем, что удерживают нас на месте одним действующим Заступником. Если вы и ваши соратники хотите пробиться туда, позвольте мне изложить свой план.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12601,'Воспользуемся тем, что они деактивировали заступников клана Солнечного Клинка. Но если кто-то из их разведчиков засечет вас, я уверена, он попытается включить ближайшего заступника. Убейте его как можно скорее, чтобы предотвратить это. После того как вы разберетесь с эльфами крови, заступники перестанут представлять для вас какую-либо опасность. Если, конечно, не подходить к ним в упор.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Воспользуемся тем, что они деактивировали заступников клана Солнечного Клинка. Но если кто-то из их разведчиков засечет вас, я уверена, он попытается включить ближайшего заступника. Убейте его как можно скорее, чтобы предотвратить это. После того как вы разберетесь с эльфами крови, заступники перестанут представлять для вас какую-либо опасность. Если, конечно, не подходить к ним в упор.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12608,'Анвина – не простая смертная, о |3-6($r). Те, кто знает ее истинную суть, не остановятся ни перед чем, чтобы завладеть ею.$b$bОднажды она спасла меня, и я намерен вернуть ей долг.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Анвина – не простая смертная, о |3-6($r). Те, кто знает ее истинную суть, не остановятся ни перед чем, чтобы завладеть ею.$b$bОднажды она спасла меня, и я намерен вернуть ей долг.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (12609,'Ну что, |3-6($c), наслаждаешься праздником?..$b$bХранители огня поддерживают сегодняшние костры; я же, скорее, кто-то вроде историка – меня более волнуют прошлые празднества. Разумеется, я записываю и все события праздников этого года. Пока что все шло неплохо, не так ли?$b$bЗнаешь ли, $n, праздничные костры обладают своей собственной силой. Мы следим за нашими кострами, но я уверен: в городах наших врагов также горит священное пламя…','Ну что, |3-6($c), наслаждаешься праздником?..$b$bХранители огня поддерживают сегодняшние костры; я же, скорее, кто-то вроде историка – меня более волнуют прошлые празднества. Разумеется, я записываю и все события праздников этого года. Пока что все шло неплохо, не так ли?$b$bЗнаешь ли, $n, праздничные костры обладают своей собственной силой. Мы следим за нашими кострами, но я уверена: в городах наших врагов также горит священное пламя…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ну что, |3-6($c), наслаждаешься праздником?..$b$bХранители огня поддерживают сегодняшние костры; я же, скорее, кто-то вроде историка – меня более волнуют прошлые празднества. Разумеется, я записываю и все события праздников этого года. Пока что все шло неплохо, не так ли?$b$bЗнаешь ли, $n, праздничные костры обладают своей собственной силой. Мы следим за нашими кострами, но я уверен: в городах наших врагов также горит священное пламя…',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ну что, |3-6($c), наслаждаешься праздником?..$b$bХранители огня поддерживают сегодняшние костры; я же, скорее, кто-то вроде историка – меня более волнуют прошлые празднества. Разумеется, я записываю и все события праздников этого года. Пока что все шло неплохо, не так ли?$b$bЗнаешь ли, $n, праздничные костры обладают своей собственной силой. Мы следим за нашими кострами, но я уверена: в городах наших врагов также горит священное пламя…',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (12610,'Добро пожаловать в наш лагерь, |3-6($c). Если хочешь, можешь отдохнуть здесь.','Добро пожаловать в наш лагерь, |3-6($c). Если хочешь, можешь отдохнуть здесь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать в наш лагерь, |3-6($c). Если хочешь, можешь отдохнуть здесь.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Добро пожаловать в наш лагерь, |3-6($c). Если хочешь, можешь отдохнуть здесь.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`,`text2_0_loc8`,`text2_1_loc8`,`text3_0_loc8`,`text3_1_loc8`,`text4_0_loc8`,`text4_1_loc8`,`text5_0_loc8`,`text5_1_loc8`,`text6_0_loc8`,`text6_1_loc8`) VALUES (12611,'У нас здесь ничего не осталось.','У нас здесь ничего не осталось.','Мою семью безжалостно уничтожили. Даже детей.','Мою семью безжалостно уничтожили. Даже детей.','Пусть Король-лич горит в аду за то, что он призвал на эту землю.','Пусть Король-лич горит в аду за то, что он призвал на эту землю.','Мы теперь народ, у которого нет своего дома.','Мы теперь народ, у которого теперь нет своего дома.','Плеть – машина, не ведающая страха и направленная на уничтожение всей жизни в этом мире.','Плеть – машина, не ведающая страха и направленная на уничтожение всей жизни в этом мире.','Тот, кого они называют Адским Криком, может оказаться нашей единственной надеждой.','Тот, кого они называют Адским Криком, может оказаться нашей единственной надеждой.','Теперь лишь Орда может спасти нас.','Теперь лишь Орда может спасти нас.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','У нас здесь ничего не осталось.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','У нас здесь ничего не осталось.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Мою семью безжалостно уничтожили. Даже детей.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Мою семью безжалостно уничтожили. Даже детей.',`text1_1_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Пусть Король-лич горит в аду за то, что он призвал на эту землю.',`text2_0_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Пусть Король-лич горит в аду за то, что он призвал на эту землю.',`text2_1_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Мы теперь народ, у которого нет своего дома.',`text3_0_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','Мы теперь народ, у которого теперь нет своего дома.',`text3_1_loc8`), `text4_0_loc8`=IF(`text4_0_loc8` IS NULL OR `text4_0_loc8`='','Плеть – машина, не ведающая страха и направленная на уничтожение всей жизни в этом мире.',`text4_0_loc8`), `text4_1_loc8`=IF(`text4_1_loc8` IS NULL OR `text4_1_loc8`='','Плеть – машина, не ведающая страха и направленная на уничтожение всей жизни в этом мире.',`text4_1_loc8`), `text5_0_loc8`=IF(`text5_0_loc8` IS NULL OR `text5_0_loc8`='','Тот, кого они называют Адским Криком, может оказаться нашей единственной надеждой.',`text5_0_loc8`), `text5_1_loc8`=IF(`text5_1_loc8` IS NULL OR `text5_1_loc8`='','Тот, кого они называют Адским Криком, может оказаться нашей единственной надеждой.',`text5_1_loc8`), `text6_0_loc8`=IF(`text6_0_loc8` IS NULL OR `text6_0_loc8`='','Теперь лишь Орда может спасти нас.',`text6_0_loc8`), `text6_1_loc8`=IF(`text6_1_loc8` IS NULL OR `text6_1_loc8`='','Теперь лишь Орда может спасти нас.',`text6_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text4_0_loc8`,`text5_0_loc8`) VALUES (12617,'<Бадд держится очень прямо, притворяясь, что не слышит тебя. Приглядевшись к нему поближе, вы видите струйку слюны, стекающую из-под его маски.>','<Бадд качается с пятки на носок, невнятно бормоча что-то на тролльском наречии.>','Сила троллей, прикинь?','Что с тобой, $gбраток:сестренка;? Ты что, никогда раньше троллей не $gвидал:видала;?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Бадд держится очень прямо, притворяясь, что не слышит тебя. Приглядевшись к нему поближе, вы видите струйку слюны, стекающую из-под его маски.>',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','<Бадд качается с пятки на носок, невнятно бормоча что-то на тролльском наречии.>',`text1_0_loc8`), `text4_0_loc8`=IF(`text4_0_loc8` IS NULL OR `text4_0_loc8`='','Сила троллей, прикинь?',`text4_0_loc8`), `text5_0_loc8`=IF(`text5_0_loc8` IS NULL OR `text5_0_loc8`='','Что с тобой, $gбраток:сестренка;? Ты что, никогда раньше троллей не $gвидал:видала;?',`text5_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (12618,'Даст ли Орда мне шанс сразиться с Плетью?','Даст ли Орда мне шанс сразиться с Плетью?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Даст ли Орда мне шанс сразиться с Плетью?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Даст ли Орда мне шанс сразиться с Плетью?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (12619,'Чтобы отомстить за свой народ, чтобы изгнать заразу, захватившую нашу землю – я принесу вашу клятву. Я отдам Орде все, что у меня есть, и все, что я собой представляю.','Чтобы отомстить за свой народ, чтобы изгнать заразу, захватившую нашу землю – я принесу вашу клятву. Я отдам Орде все, что у меня есть, и все, что я собой представляю.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Чтобы отомстить за свой народ, чтобы изгнать заразу, захватившую нашу землю – я принесу вашу клятву. Я отдам Орде все, что у меня есть, и все, что я собой представляю.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Чтобы отомстить за свой народ, чтобы изгнать заразу, захватившую нашу землю – я принесу вашу клятву. Я отдам Орде все, что у меня есть, и все, что я собой представляю.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (12620,'Лок\'тар огар! Победа или смерть – вот первые слова моей присяги Орде. В них заключена священная истина, суть существования каждого воина Орды.$b$bОтныне мои плоть и кровь принадлежат Вождю. Все, что я делаю, я делаю ради Вождя. Я – оружие в его руках.$b$bС этого момента и до конца своих дней я буду жить и умру – ЗА ОРДУ!','Лок\'тар огар! Победа или смерть – вот первые слова моей присяги Орде. В них заключена священная истина, суть существования каждого воина Орды.$b$bОтныне мои плоть и кровь принадлежат Вождю. Все, что я делаю, я делаю ради Вождя. Я – оружие в его руках.$b$bС этого момента и до конца своих дней я буду жить и умру – ЗА ОРДУ!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Лок\'тар огар! Победа или смерть – вот первые слова моей присяги Орде. В них заключена священная истина, суть существования каждого воина Орды.$b$bОтныне мои плоть и кровь принадлежат Вождю. Все, что я делаю, я делаю ради Вождя. Я – оружие в его руках.$b$bС этого момента и до конца своих дней я буду жить и умру – ЗА ОРДУ!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Лок\'тар огар! Победа или смерть – вот первые слова моей присяги Орде. В них заключена священная истина, суть существования каждого воина Орды.$b$bОтныне мои плоть и кровь принадлежат Вождю. Все, что я делаю, я делаю ради Вождя. Я – оружие в его руках.$b$bС этого момента и до конца своих дней я буду жить и умру – ЗА ОРДУ!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`,`text3_0_loc8`,`text4_0_loc8`,`text5_0_loc8`,`text6_0_loc8`,`text7_0_loc8`) VALUES (12622,'Эй! Отведи меня к моим собратьям-троллям!','Пора платить за слежку за троллем!','Мои соплеменники хорошо сегодня повеселятся!','Хе-хе-хе! Скоро мы с тобой повеселимся!','Ты точно знаешь, что мы идем в правильную сторону?','<принюхивается> Я их чую.','Никто и не говорил, что любовь – это сплошные нежности.','Никто и не говорил, что любовь – это сплошные нежности.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эй! Отведи меня к моим собратьям-троллям!',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Пора платить за слежку за троллем!',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Мои соплеменники хорошо сегодня повеселятся!',`text2_0_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Хе-хе-хе! Скоро мы с тобой повеселимся!',`text3_0_loc8`), `text4_0_loc8`=IF(`text4_0_loc8` IS NULL OR `text4_0_loc8`='','Ты точно знаешь, что мы идем в правильную сторону?',`text4_0_loc8`), `text5_0_loc8`=IF(`text5_0_loc8` IS NULL OR `text5_0_loc8`='','<принюхивается> Я их чую.',`text5_0_loc8`), `text6_0_loc8`=IF(`text6_0_loc8` IS NULL OR `text6_0_loc8`='','Никто и не говорил, что любовь – это сплошные нежности.',`text6_0_loc8`), `text7_0_loc8`=IF(`text7_0_loc8` IS NULL OR `text7_0_loc8`='','Никто и не говорил, что любовь – это сплошные нежности.',`text7_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12627,'Наша обязанность – защитить этих таунка и предоставить им хотя бы те скудные удобства, которыми располагаем.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Наша обязанность – защитить этих таунка и предоставить им хотя бы те скудные удобства, которыми располагаем.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12628,'Эти дети будут жить. Окруженные любовью и заботой, они станут сильными воинами Орды и со временем забудут ужасы своей прежней жизни.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Эти дети будут жить. Окруженные любовью и заботой, они станут сильными воинами Орды и со временем забудут ужасы своей прежней жизни.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12637,'Большая морская черепаха Идущая-по-Волнам плавает от этой пристани до гавани Моа\'ки на Драконьем Погосте.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Большая морская черепаха Идущая-по-Волнам плавает от этой пристани до гавани Моа\'ки на Драконьем Погосте.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12641,'Не терпится попасть в Нордскол, да? Оснащенный мощным паровым двигателем "Кракен" отбывает отсюда в крепость Отваги, что в Борейской тундре.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Не терпится попасть в Нордскол, да? Оснащенный мощным паровым двигателем "Кракен" отбывает отсюда в крепость Отваги, что в Борейской тундре.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12645,'Наша большая морская черепаха, "Зеленый остров", может довезти тебя до Гавани Моа\'Ки в Драконьем Погосте.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Наша большая морская черепаха, "Зеленый остров", может довезти тебя до Гавани Моа\'Ки в Драконьем Погосте.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12646,'Хай! Хочешь попасть обратно, в Старый свет? " Мой "Поцелуй небес" доставит тебя в Тирисфальские леса в мгновение ока!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Хай! Хочешь попасть обратно, в Старый свет? " Мой "Поцелуй небес" доставит тебя в Тирисфальские леса в мгновение ока!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12647,'Эй, ты. Если хочешь попасть в Нордскол, тогда твой выбор – "Могучий Ветер". Он донесет тебя прямо до крепости Песни Войны в Борейской тундре.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эй, ты. Если хочешь попасть в Нордскол, тогда твой выбор – "Могучий Ветер". Он донесет тебя прямо до крепости Песни Войны в Борейской тундре.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12657,'Разыскиваются приговоренные к СМЕРТИ за измену и прочую вероломную деятельность против Орды!$B$BВсе вознаграждения выплачивает капитан Горт.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Разыскиваются приговоренные к СМЕРТИ за измену и прочую вероломную деятельность против Орды!$B$BВсе вознаграждения выплачивает капитан Горт.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12663,'Все, что я хотел, – это вновь служить моему королю. Защищать наш народ, бороться против общего врага.$B$BА вместо этого я обнаружил, что в наши ряды проникли отродья из культа… и все признаки указывают на Наксанар – источник этой гнили.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Все, что я хотел, – это вновь служить моему королю. Защищать наш народ, бороться против общего врага.$B$BА вместо этого я обнаружил, что в наши ряды проникли отродья из культа… и все признаки указывают на Наксанар – источник этой гнили.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12665,'Самопожертвование Анвины дало нам новую надежду.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Самопожертвование Анвины дало нам новую надежду.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12666,'А? Что?! Проваливай.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','А? Что?! Проваливай.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12668,'На этом можно наварить деньжат! Как говорят в народе: если хочешь сколотить состояние – сколоти его на войне.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','На этом можно наварить деньжат! Как говорят в народе: если хочешь сколотить состояние – сколоти его на войне.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12669,'Стоя перед этим древним идолом, вы ощущаете чье-то незримое присутствие.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Стоя перед этим древним идолом, вы ощущаете чье-то незримое присутствие.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12670,'Там, где тысячи лет пребывало Око пророка, теперь осталась лишь пустая ниша.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Там, где тысячи лет пребывало Око пророка, теперь осталась лишь пустая ниша.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (12673,'Добро пожаловать! Если тебе нужно отдохнуть, я могу помочь с решением этой проблемы.','Добро пожаловать! Если тебе нужно отдохнуть, я могу помочь с решением этой проблемы.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать! Если тебе нужно отдохнуть, я могу помочь с решением этой проблемы.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Добро пожаловать! Если тебе нужно отдохнуть, я могу помочь с решением этой проблемы.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12678,'Мы сокрушим Артаса! Плети не устоять перед мощью Орды!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы сокрушим Артаса! Плети не устоять перед мощью Орды!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (12684,'Ищешь распорядителя арены? Их можно встретить на дороге между городами или в столицах...$B$BМожешь и со мной заключить сделку. Я также могу отправить тебя в одну из столиц.','Ищешь распорядителя арены? Их можно встретить на дороге между городами или в столицах...$B$BМожешь и со мной заключить сделку. Я также могу отправить тебя в одну из столиц.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ищешь распорядителя арены? Их можно встретить на дороге между городами или в столицах...$B$BМожешь и со мной заключить сделку. Я также могу отправить тебя в одну из столиц.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ищешь распорядителя арены? Их можно встретить на дороге между городами или в столицах...$B$BМожешь и со мной заключить сделку. Я также могу отправить тебя в одну из столиц.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12694,'Тебе бы лучше убраться отсюда, если не хочешь оказаться в одной из этих клеток…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тебе бы лучше убраться отсюда, если не хочешь оказаться в одной из этих клеток…',`text0_0_loc8`);
