INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (12696,'Спасибо, |3-6($c), что проследил, чтобы я получил письмо от брата.$B$BБудь спокоен, его смерть не будет напрасной. Синие драконы заплатят за это.$B$BЯ сам прослежу за этим!','Спасибо, |3-6($c), что проследил, чтобы я получила письмо от брата.$B$BБудь спокоен, его смерть не будет напрасной. Синие драконы заплатят за это.$B$BЯ сама прослежу за этим!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Спасибо, |3-6($c), что проследил, чтобы я получил письмо от брата.$B$BБудь спокоен, его смерть не будет напрасной. Синие драконы заплатят за это.$B$BЯ сам прослежу за этим!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Спасибо, |3-6($c), что проследил, чтобы я получила письмо от брата.$B$BБудь спокоен, его смерть не будет напрасной. Синие драконы заплатят за это.$B$BЯ сама прослежу за этим!',`text0_1_loc8`);
