INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12698,'Выполняй свои обязанности по сдерживанию сил Плети, солдат! Докладывай обо всей подозрительной активности и сначала убивай, а потом задавай вопросы!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Выполняй свои обязанности по сдерживанию сил Плети, солдат! Докладывай обо всей подозрительной активности и сначала убивай, а потом задавай вопросы!',`text0_0_loc8`);
