INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`,`text3_0_loc8`,`text4_0_loc8`) VALUES (12699,'Попомните мои слова, эти отрекшиеся дураки всех нас до могилы доведут!','Если ты хочешь узнать мое мнение, а ты $gЗАХОТЕЛ:ЗАХОТЕЛА;, я считаю, что мы должны убить всех фармацевтов, пока еще не слишком поздно!','Орда – это честь и война. А в действиях аптекарей, я уверен, нет ничего честного.','Я приглядываю за этими отрекшимися идиотами. За ними нужен глаз да глаз!','Если у тебя есть дело вон к тому доктору, будь $gосторожен:осторожна;. Чем бы они там не занимались, это противоестественно.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Попомните мои слова, эти отрекшиеся дураки всех нас до могилы доведут!',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Если ты хочешь узнать мое мнение, а ты $gЗАХОТЕЛ:ЗАХОТЕЛА;, я считаю, что мы должны убить всех фармацевтов, пока еще не слишком поздно!',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Орда – это честь и война. А в действиях аптекарей, я уверен, нет ничего честного.',`text2_0_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Я приглядываю за этими отрекшимися идиотами. За ними нужен глаз да глаз!',`text3_0_loc8`), `text4_0_loc8`=IF(`text4_0_loc8` IS NULL OR `text4_0_loc8`='','Если у тебя есть дело вон к тому доктору, будь $gосторожен:осторожна;. Чем бы они там не занимались, это противоестественно.',`text4_0_loc8`);
