INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12701,'$gБрат:Сестренка;, западные пустоши наводнили плохие ребята. Держись оттуда подальше, если хочешь жить!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','$gБрат:Сестренка;, западные пустоши наводнили плохие ребята. Держись оттуда подальше, если хочешь жить!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12703,'Мои обязанности в Молоте Агмара простираются гораздо дальше, чем уход за животными в конюшне.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мои обязанности в Молоте Агмара простираются гораздо дальше, чем уход за животными в конюшне.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12705,'Погибаю? Я? Хе, это вряд ли, $Gмалыш:девчушка;. Это просто царапина.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Погибаю? Я? Хе, это вряд ли, $Gмалыш:девчушка;. Это просто царапина.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12706,'Впечатляет, правда? Из этих великанов вышло бы идеальное пушеч… э-э, союзники. Вот этот – их предводитель, но он продолжает отказываться со мной говорить.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Впечатляет, правда? Из этих великанов вышло бы идеальное пушеч… э-э, союзники. Вот этот – их предводитель, но он продолжает отказываться со мной говорить.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12707,'Здравствуй, |3-6($r). Добро пожаловать, располагайся в этом каньоне вместе с нами, он служит нам укрытием от драконов. Остерегайся гоблинов… им нельзя доверять.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здравствуй, |3-6($r). Добро пожаловать, располагайся в этом каньоне вместе с нами, он служит нам укрытием от драконов. Остерегайся гоблинов… им нельзя доверять.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12708,'Будь у меня достаточно денег, я бы купил весь мир…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Будь у меня достаточно денег, я бы купил весь мир…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12713,'Добро пожаловать в храм Драконьего Покоя, $gпутешественник:путешественница;.$B$BЗдесь драконы мирно обсуждают свои дела посреди костей своих прославленных предков.$B$BПо крайней мере, так было до тех пор, пока синие драконы внезапно не напали на наш храм.$B$BСтупай, мы благословляем тебя, но знай, что мы не приемлем никакой агрессии внутри наших стен.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать в храм Драконьего Покоя, $gпутешественник:путешественница;.$B$BЗдесь драконы мирно обсуждают свои дела посреди костей своих прославленных предков.$B$BПо крайней мере, так было до тех пор, пока синие драконы внезапно не напали на наш храм.$B$BСтупай, мы благословляем тебя, но знай, что мы не приемлем никакой агрессии внутри наших стен.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12714,'Хочешь отправиться обратно, |3-6($c)?$B$BЯ могу позаботиться о том, чтобы один из этих драконов донес тебя в целости и сохранности туда, куда ты хочешь попасть.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Хочешь отправиться обратно, |3-6($c)?$B$BЯ могу позаботиться о том, чтобы один из этих драконов донес тебя в целости и сохранности туда, куда ты хочешь попасть.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12715,'Оставь меня в покое, балда!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Оставь меня в покое, балда!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12718,'Что? Ты хочешь у меня тренироваться, |3-6($c)? Тогда будь $Gготов:готова; к кропотливому труду.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что? Ты хочешь у меня тренироваться, |3-6($c)? Тогда будь $Gготов:готова; к кропотливому труду.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12720,'Ты можешь лечь спать в казармах, если хочешь. Только не разбуди моих воинов, а то я собственноручно выкину тебя оттуда прямо в сугроб.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты можешь лечь спать в казармах, если хочешь. Только не разбуди моих воинов, а то я собственноручно выкину тебя оттуда прямо в сугроб.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12725,'Ты не станешь $gнастоящим:настоящей; $gбратком:сестренкой;, пока не убьешь дракона… $gбраток:сестренка;.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты не станешь $gнастоящим:настоящей; $gбратком:сестренкой;, пока не убьешь дракона… $gбраток:сестренка;.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12726,'Ничто так не будоражит, как охота на драконов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ничто так не будоражит, как охота на драконов.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12730,'Почему ты меня беспокоишь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Почему ты меня беспокоишь?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12732,'Привет. Если тебе что-нибудь потребуется, дай мне знать.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Привет. Если тебе что-нибудь потребуется, дай мне знать.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12733,'Эти уроды из Плети… скоро они получат по заслугам!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эти уроды из Плети… скоро они получат по заслугам!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (12734,'У меня есть еда, если ты $gголоден:голодна;, и есть палатка, если тебе требуется отдых.','У меня есть еда, если ты $gголоден:голодна;, и есть палатка, если тебе требуется отдых.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','У меня есть еда, если ты $gголоден:голодна;, и есть палатка, если тебе требуется отдых.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','У меня есть еда, если ты $gголоден:голодна;, и есть палатка, если тебе требуется отдых.',`text0_1_loc8`);
