INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12735,'Может быть, тут не очень снежно, но ночью здесь можно запросто отморозить свой нос. Койки сзади – просто не мешайте нам.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Может быть, тут не очень снежно, но ночью здесь можно запросто отморозить свой нос. Койки сзади – просто не мешайте нам.',`text0_0_loc8`);
