INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12736,'Хех. Ничего не имею против тебя, щенок, но тебе лучше бы поискать другое место для ночлега на эту ночь. Не хочу, чтобы эта твоя нежная кожа вся потемнела от синяков.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Хех. Ничего не имею против тебя, щенок, но тебе лучше бы поискать другое место для ночлега на эту ночь. Не хочу, чтобы эта твоя нежная кожа вся потемнела от синяков.',`text0_0_loc8`);
