INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (12738,'Подходи к огню и отдохни, |3-6($r). Надеюсь, ты не возражаешь против запаха рыбы.','Подходи к огню и отдохни, |3-6($r). Надеюсь, ты не возражаешь против запаха рыбы.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Подходи к огню и отдохни, |3-6($r). Надеюсь, ты не возражаешь против запаха рыбы.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Подходи к огню и отдохни, |3-6($r). Надеюсь, ты не возражаешь против запаха рыбы.',`text0_1_loc8`);
