INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12750,'Верховный палач Рос выдает вознаграждения по предъявлении свидетельства.$B$BТребуются серьезно настроенные личности.$B$BКОММИВОЯЖЕРАМ ВХОД ВОСПРЕЩЕН!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Верховный палач Рос выдает вознаграждения по предъявлении свидетельства.$B$BТребуются серьезно настроенные личности.$B$BКОММИВОЯЖЕРАМ ВХОД ВОСПРЕЩЕН!',`text0_0_loc8`);
