INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12751,'Мы уничтожим живых… ну, в смысле, Плеть, конечно.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы уничтожим живых… ну, в смысле, Плеть, конечно.',`text0_0_loc8`);
