INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12752,'Хромоногий Джо, это ты. Это правда ты!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Хромоногий Джо, это ты. Это правда ты!',`text0_0_loc8`);
