INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (12755,'<Клыкарр смотрит на тебя подозрительно.>$b$bНе задерживайся надолго. Тебе не понять нашего народа, я не хочу, чтобы из-за тебя были неприятности.','<Клыкарр смотрит на тебя подозрительно.>$b$bНе задерживайся надолго. Тебе не понять нашего народа, я не хочу, чтобы из-за тебя были неприятности.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Клыкарр смотрит на тебя подозрительно.>$b$bНе задерживайся надолго. Тебе не понять нашего народа, я не хочу, чтобы из-за тебя были неприятности.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','<Клыкарр смотрит на тебя подозрительно.>$b$bНе задерживайся надолго. Тебе не понять нашего народа, я не хочу, чтобы из-за тебя были неприятности.',`text0_1_loc8`);
