INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12756,'Небо небезопасно, друг. Будь бдителен!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Небо небезопасно, друг. Будь бдителен!',`text0_0_loc8`);
