INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12759,'Вам что-то нужно? Может быть, починить броню или оружие? Мм?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вам что-то нужно? Может быть, починить броню или оружие? Мм?',`text0_0_loc8`);
