INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12770,'Отчаянное время требует отчаянных мер, |3-6($c).') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Отчаянное время требует отчаянных мер, |3-6($c).',`text0_1_loc8`);
