INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12773,'Эти горы прекрасны, но в глубине таят великую тьму… Будь $gосторожен:осторожна;!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Эти горы прекрасны, но в глубине таят великую тьму… Будь $gосторожен:осторожна;!',`text0_1_loc8`);
