INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (12774,'Будь $gосторожен:осторожна;, побеги чумы, взлелеянной Королем-личом, растут незаметно даже здесь.','Будь $gосторожен:осторожна;, побеги чумы, взлелеянной Королем-личом, растут незаметно даже здесь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Будь $gосторожен:осторожна;, побеги чумы, взлелеянной Королем-личом, растут незаметно даже здесь.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Будь $gосторожен:осторожна;, побеги чумы, взлелеянной Королем-личом, растут незаметно даже здесь.',`text0_1_loc8`);
