INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12775,'Похоже, туалет в данный момент занят.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Похоже, туалет в данный момент занят.',`text0_0_loc8`);
