INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12781,'Спасибо за помощь, $n. Эта снежевика в буквальном смысле слова – плод твоего труда.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Спасибо за помощь, $n. Эта снежевика в буквальном смысле слова – плод твоего труда.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12785,'Когда я услышал о том, что у меня есть родственники здесь, на севере, я пришел сюда, чтобы познакомиться с ними поближе. И что я увидел – воинственные племена, идущие против самой нашей природы.$B$BУ меня не осталось никакой надежды, |3-6($r). Даже сам великий Урсок запятнан этим проклятым местом.$B$BЯ потерял надежду.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Когда я услышал о том, что у меня есть родственники здесь, на севере, я пришел сюда, чтобы познакомиться с ними поближе. И что я увидел – воинственные племена, идущие против самой нашей природы.$B$BУ меня не осталось никакой надежды, |3-6($r). Даже сам великий Урсок запятнан этим проклятым местом.$B$BЯ потерял надежду.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12787,'Да… Я чувствую магию Фордрассила… ничем не запятнанную.$B$BПожалуйста! Позволь мне помочь тебе. Судьба привела меня сюда – возможно, я смогу исполнить свое предназначение!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да… Я чувствую магию Фордрассила… ничем не запятнанную.$B$BПожалуйста! Позволь мне помочь тебе. Судьба привела меня сюда – возможно, я смогу исполнить свое предназначение!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12790,'Зибарус от всего сердца благодарит тебя. Если бы не ты, Зибарус бы умер, или хуже того – Зибарус превратился бы в одного из них…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Зибарус от всего сердца благодарит тебя. Если бы не ты, Зибарус бы умер, или хуже того – Зибарус превратился бы в одного из них…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12793,'Когда-то я вольно бродил по Седым холмам, сын великого Урсока, властителя этих земель.$B$BНо теперь… теперь я обречен провести остаток жизни в этой пещере.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Когда-то я вольно бродил по Седым холмам, сын великого Урсока, властителя этих земель.$B$BНо теперь… теперь я обречен провести остаток жизни в этой пещере.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12795,'Потише, |3-6($c). Я тут под прикрытием и шпионю в пользу Ядозлоби.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Потише, |3-6($c). Я тут под прикрытием и шпионю в пользу Ядозлоби.',`text0_1_loc8`);
