INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12797,'Я – Кодиан, дочь Урсока. Я присматриваю за этой некогда священной гробницей.$B$BЯ не видела здесь чужаков уже долгое время.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я – Кодиан, дочь Урсока. Я присматриваю за этой некогда священной гробницей.$B$BЯ не видела здесь чужаков уже долгое время.',`text0_0_loc8`);
