INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12805,'О, отлично, ты $gпришел:пришла; меня спасти. А теперь выпусти меня отсюда!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','О, отлично, ты $gпришел:пришла; меня спасти. А теперь выпусти меня отсюда!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12806,'Привет, $gприятель:красавица;. Я смотрю, ты тут рядом…$B$BКак насчет того, чтобы вытащить меня отсюда?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Привет, $gприятель:красавица;. Я смотрю, ты тут рядом…$B$BКак насчет того, чтобы вытащить меня отсюда?',`text0_0_loc8`);
