INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12808,'Я не знаю, что случилось. Я приехал в Ядозлобь, а потом вдруг очнулся в этой клетке!$B$BТы $gпришел:пришла;, чтобы спасти меня?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я не знаю, что случилось. Я приехал в Ядозлобь, а потом вдруг очнулся в этой клетке!$B$BТы $gпришел:пришла;, чтобы спасти меня?',`text0_0_loc8`);
