INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12811,'Здесь прикован яростный протодракон тана Торвальда Эрикксона') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здесь прикован яростный протодракон тана Торвальда Эрикксона',`text0_0_loc8`);
