INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12812,'Да, чего тебе?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да, чего тебе?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (12819,'Раз в два года Духи Соперничества впадают в неистовство… И сейчас такое время настало! Мы надеваем эту гербовую накидку, выходя на поле боя, чтобы почтить духов, дабы они послали нам победу, а нашим соперникам – позорное поражение.','Раз в два года Духи Соперничества впадают в неистовство… И сейчас такое время настало! Мы надеваем эту гербовую накидку, выходя на поле боя, чтобы почтить духов, дабы они послали нам победу, а нашим соперникам – поражение.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Раз в два года Духи Соперничества впадают в неистовство… И сейчас такое время настало! Мы надеваем эту гербовую накидку, выходя на поле боя, чтобы почтить духов, дабы они послали нам победу, а нашим соперникам – позорное поражение.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Раз в два года Духи Соперничества впадают в неистовство… И сейчас такое время настало! Мы надеваем эту гербовую накидку, выходя на поле боя, чтобы почтить духов, дабы они послали нам победу, а нашим соперникам – поражение.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (12820,'Ты просто $gдолжен:должна; сойтись с соперниками лицом к лицу на поле боя. Неважно, победишь ты или проиграешь: достаточно продержаться все время боя, и ты получишь гербовую накидку участника соревнований.','Ты просто $gдолжен:должна; сойтись с соперниками лицом к лицу на поле боя. Неважно, победишь ты или проиграешь: достаточно продержаться все время боя, и ты получишь гербовую накидку участника соревнований.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты просто $gдолжен:должна; сойтись с соперниками лицом к лицу на поле боя. Неважно, победишь ты или проиграешь: достаточно продержаться все время боя, и ты получишь гербовую накидку участника соревнований.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты просто $gдолжен:должна; сойтись с соперниками лицом к лицу на поле боя. Неважно, победишь ты или проиграешь: достаточно продержаться все время боя, и ты получишь гербовую накидку участника соревнований.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (12821,'Ты $gдолжен:должна; победить наших противников на поле боя. С каждой победой шансы на то, что ты получишь Золотой медальон, растут…','Ты $gдолжен:должна; победить наших противников на поле боя. С каждой победой шансы на то, что ты получишь Золотой медальон, растут…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты $gдолжен:должна; победить наших противников на поле боя. С каждой победой шансы на то, что ты получишь Золотой медальон, растут…',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты $gдолжен:должна; победить наших противников на поле боя. С каждой победой шансы на то, что ты получишь Золотой медальон, растут…',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (12822,'Тебе известны рассказы о Духах Соперничества, так ведь?$B$BРаз в два года они приближаются к смертным землям, и в такое время воины Альянса и Орды облачаются в ритуальные гербовые накидки и выходят на поле боя, дабы почтить духов. Воины сражаются и побеждают противников, надеясь заслужить благоволение Духов Соперничества.$B$BЯ храню некоторые вещицы на память о таких временах. Если ты узнаешь нужное слово, быть может, я расстанусь с одной из них…','Тебе известны рассказы о Духах Соперничества, так ведь?$B$BРаз в два года они приближаются к смертным землям, и в такое время воины Альянса и Орды облачаются в ритуальные гербовые накидки и выходят на поле боя, дабы почтить духов. Воины сражаются и побеждают противников, надеясь заслужить благоволение Духов Соперничества.$B$BЯ храню некоторые вещицы на память о таких временах. Если ты узнаешь нужное слово, быть может, я расстанусь с одной из них…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тебе известны рассказы о Духах Соперничества, так ведь?$B$BРаз в два года они приближаются к смертным землям, и в такое время воины Альянса и Орды облачаются в ритуальные гербовые накидки и выходят на поле боя, дабы почтить духов. Воины сражаются и побеждают противников, надеясь заслужить благоволение Духов Соперничества.$B$BЯ храню некоторые вещицы на память о таких временах. Если ты узнаешь нужное слово, быть может, я расстанусь с одной из них…',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Тебе известны рассказы о Духах Соперничества, так ведь?$B$BРаз в два года они приближаются к смертным землям, и в такое время воины Альянса и Орды облачаются в ритуальные гербовые накидки и выходят на поле боя, дабы почтить духов. Воины сражаются и побеждают противников, надеясь заслужить благоволение Духов Соперничества.$B$BЯ храню некоторые вещицы на память о таких временах. Если ты узнаешь нужное слово, быть может, я расстанусь с одной из них…',`text0_1_loc8`);
