INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (12827,'Я думаю, они посадили его в клетку возле лесопилки.','Я думаю, они посадили его в клетку возле лесопилки.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я думаю, они посадили его в клетку возле лесопилки.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я думаю, они посадили его в клетку возле лесопилки.',`text0_1_loc8`);
