INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12829,'Ты просто $gдолжен:должна; сойтись с соперниками лицом к лицу на поле боя. Неважно, победишь ты или проиграешь: достаточно продержаться все время боя, и ты получишь гербовую накидку участника соревнований.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты просто $gдолжен:должна; сойтись с соперниками лицом к лицу на поле боя. Неважно, победишь ты или проиграешь: достаточно продержаться все время боя, и ты получишь гербовую накидку участника соревнований.',`text0_0_loc8`);
