INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (12830,'Я думаю, он в южной части аббатства.','Я думаю, он в южной части аббатства.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я думаю, он в южной части аббатства.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я думаю, он в южной части аббатства.',`text0_1_loc8`);
