INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (12831,'Раз в два года Духи Соперничества впадают в неистовство… И сейчас такое время настало! Выходя на поле боя, воины Альянса и Орды надевают такую гербовую накидку, чтобы почтить духов, и каждый воин просит о победе себе и поражении своему противнику.','Раз в два года Духи Соперничества впадают в неистовство… И сейчас такое время настало! Выходя на поле боя, воины Альянса и Орды надевают такую гербовую накидку, чтобы почтить духов, и каждый воин просит о победе себе и поражении своему противнику.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Раз в два года Духи Соперничества впадают в неистовство… И сейчас такое время настало! Выходя на поле боя, воины Альянса и Орды надевают такую гербовую накидку, чтобы почтить духов, и каждый воин просит о победе себе и поражении своему противнику.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Раз в два года Духи Соперничества впадают в неистовство… И сейчас такое время настало! Выходя на поле боя, воины Альянса и Орды надевают такую гербовую накидку, чтобы почтить духов, и каждый воин просит о победе себе и поражении своему противнику.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (12832,'Мне кажется, они ее держат возле виселицы.','Мне кажется, они ее держат возле виселицы.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мне кажется, они ее держат возле виселицы.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мне кажется, они ее держат возле виселицы.',`text0_1_loc8`);
