INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (12833,'Мне кажется, я видел, как они вели его по северной части аббатства, около мишеней для стрельбы.','Мне кажется, я видела, как они вели его по северной части аббатства, около мишеней для стрельбы.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мне кажется, я видел, как они вели его по северной части аббатства, около мишеней для стрельбы.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мне кажется, я видела, как они вели его по северной части аббатства, около мишеней для стрельбы.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12838,'Приветствую, |3-6($c).$b$bХочешь, чтобы Даррок отправил тебя в Бухту торговцев?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приветствую, |3-6($c).$b$bХочешь, чтобы Даррок отправил тебя в Бухту торговцев?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12843,'Верховный лорд Болвар Фордрагон сражается за нас всех, новичок. Если бы не он, Артас уже давно восседал бы на троне Штормграда.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Верховный лорд Болвар Фордрагон сражается за нас всех, новичок. Если бы не он, Артас уже давно восседал бы на троне Штормграда.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12844,'Я так близок к разгадке этой руды. Теперь с минуты на минуту я найду ответ!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я так близок к разгадке этой руды. Теперь с минуты на минуту я найду ответ!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12845,'Привет, |3-6($c)!$b$b$gГотов:Готова; направиться в Бухту торговцев и расколотить пару ордынских черепов?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Привет, |3-6($c)!$b$b$gГотов:Готова; направиться в Бухту торговцев и расколотить пару ордынских черепов?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12846,'Да, $gсын мой:дочь моя;?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да, $gсын мой:дочь моя;?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12848,'<Верховный аббат внимательно смотрит на вас несколько секунд, затем улыбается.>$B$BОчень хорошо, я знаю подходящее место, дитя мое. Просто поцелуй мое кольцо и дай мне знать, когда будешь $gготов:готова;.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Верховный аббат внимательно смотрит на вас несколько секунд, затем улыбается.>$B$BОчень хорошо, я знаю подходящее место, дитя мое. Просто поцелуй мое кольцо и дай мне знать, когда будешь $gготов:готова;.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12849,'Потом встреть меня у входа в монастырь. Я приду туда довольно скоро.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Потом встреть меня у входа в монастырь. Я приду туда довольно скоро.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12850,'Я сыграл свою роль в уничтожении целых цивилизаций… то, что мне приходится разбираться с каким-то жалким Культом Проклятых, вызывает у меня отвращение.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я сыграл свою роль в уничтожении целых цивилизаций… то, что мне приходится разбираться с каким-то жалким Культом Проклятых, вызывает у меня отвращение.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12851,'Хорошо, но в следующий раз будь поосторожнее!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Хорошо, но в следующий раз будь поосторожнее!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12853,'Не беспокой меня по мелочам!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не беспокой меня по мелочам!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`) VALUES (12856,'Ты что, не видишь, я занят! Нам никак не подготовить эту базу к возвращению Принца!','Если бы не эти проклятые твари, поджигающие наши корабли, мы бы уже были дома. А теперь оставь меня в покое, чтобы я мог вернуться к работе!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты что, не видишь, я занят! Нам никак не подготовить эту базу к возвращению Принца!',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Если бы не эти проклятые твари, поджигающие наши корабли, мы бы уже были дома. А теперь оставь меня в покое, чтобы я мог вернуться к работе!',`text1_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12857,'Здесь присутствуют значительные силы Серебряного Авангарда, друг. Уж не $gдумал:думала; ли ты, что мы позволим тебе стяжать всю славу $gодному:одной;!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здесь присутствуют значительные силы Серебряного Авангарда, друг. Уж не $gдумал:думала; ли ты, что мы позволим тебе стяжать всю славу $gодному:одной;!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12858,'Эти проклятые крестьяне должны работать быстрее! Я хочу вернуться домой в Стальгорн. Я очень скучаю по жене и детям.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эти проклятые крестьяне должны работать быстрее! Я хочу вернуться домой в Стальгорн. Я очень скучаю по жене и детям.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`) VALUES (12859,'Когда мы увидели, что корабли были сожжены этими свирепыми зверьми, мы пришли в отчаяние. Никогда я не ощущал такой беспомощности…','Ярость. Вот вкратце мои чувства по отношению ко всей этой каше. Мы продирались через лес к берегу изо всех сил лишь для того, чтобы обнаружить, что опоздали. Наш единственный путь домой был уничтожен.','Несмотря на тяготы, через которые мы прошли в этой бесплодной земле, я верю, что молодой принц приведет нас к победе. Я каждый вечер молюсь за его безопасность.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Когда мы увидели, что корабли были сожжены этими свирепыми зверьми, мы пришли в отчаяние. Никогда я не ощущал такой беспомощности…',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Ярость. Вот вкратце мои чувства по отношению ко всей этой каше. Мы продирались через лес к берегу изо всех сил лишь для того, чтобы обнаружить, что опоздали. Наш единственный путь домой был уничтожен.',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Несмотря на тяготы, через которые мы прошли в этой бесплодной земле, я верю, что молодой принц приведет нас к победе. Я каждый вечер молюсь за его безопасность.',`text2_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`) VALUES (12860,'<Забытый пехотинец качает головой.>$B$BМы не можем так продолжать, друг. Если принц Артас скоро не вернется, мы все погибнем.','Нам никогда не успеть подготовить эти корабли вовремя. Зима приближается, и с ней приближается наша судьба. Я боюсь, что молодой принц проклял нас всех.','Артас и Мурадин пропали очень давно. Надеюсь, с ними все в порядке.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Забытый пехотинец качает головой.>$B$BМы не можем так продолжать, друг. Если принц Артас скоро не вернется, мы все погибнем.',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Нам никогда не успеть подготовить эти корабли вовремя. Зима приближается, и с ней приближается наша судьба. Я боюсь, что молодой принц проклял нас всех.',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Артас и Мурадин пропали очень давно. Надеюсь, с ними все в порядке.',`text2_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12862,'Куда желаешь отправиться?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Куда желаешь отправиться?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (12863,'Вступив в хороший клуб, ты можешь изменить всю свою жизнь.','Вступив в хороший клуб, ты можешь изменить всю свою жизнь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вступив в хороший клуб, ты можешь изменить всю свою жизнь.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Вступив в хороший клуб, ты можешь изменить всю свою жизнь.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (12864,'Эй, дружище! Гляжу, у тебя есть несколько жетонов Хмельного фестиваля. А у меня еще остались кое-какие вещи с Фестиваля на продажу!','Эй, дружище! Гляжу, у тебя есть несколько жетонов Хмельного фестиваля. А у меня еще остались кое-какие вещи с Фестиваля на продажу!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эй, дружище! Гляжу, у тебя есть несколько жетонов Хмельного фестиваля. А у меня еще остались кое-какие вещи с Фестиваля на продажу!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Эй, дружище! Гляжу, у тебя есть несколько жетонов Хмельного фестиваля. А у меня еще остались кое-какие вещи с Фестиваля на продажу!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12865,'Привет, |3-6($r)!$b$bЕсли ты ищешь крошшер для езды, тебе придется отправиться вверх, в холмы.$b$bЭтого придется списать в утиль.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Привет, |3-6($r)!$b$bЕсли ты ищешь крошшер для езды, тебе придется отправиться вверх, в холмы.$b$bЭтого придется списать в утиль.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (12867,'Хорошее пиво – крепкое пиво!','Хорошее пиво – крепкое пиво!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Хорошее пиво – крепкое пиво!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Хорошее пиво – крепкое пиво!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12868,'До того как здесь начались крупные неприятности, мы с их помощью собирали урожай деревьев.$b$bОднако в последнее время им приходится сражаться против Орды. Как оказалось, из них получаются неплохие боевые машины. Так что если у тебя есть ключ – было бы глупо не воспользоваться одним из этих малюток!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','До того как здесь начались крупные неприятности, мы с их помощью собирали урожай деревьев.$b$bОднако в последнее время им приходится сражаться против Орды. Как оказалось, из них получаются неплохие боевые машины. Так что если у тебя есть ключ – было бы глупо не воспользоваться одним из этих малюток!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (12869,'Клево быть членом клуба "Пиво месяца"!','Клево быть членом клуба "Пиво месяца"!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Клево быть членом клуба "Пиво месяца"!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Клево быть членом клуба "Пиво месяца"!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12871,'У моего брата, Синипуса, их множество. Ты должен направиться на север в лесозаготовки Синего Неба и поговорить с ним.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','У моего брата, Синипуса, их множество. Ты должен направиться на север в лесозаготовки Синего Неба и поговорить с ним.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12876,'Если у тебя достаточно жетонов, ты можешь вступить в клуб "Пиво месяца". Став членом нашего клуба, ты сможешь праздновать Хмельной фестиваль круглый год!$b$bКаждый месяц мы будем посылать тебе образец нашего нового пива на пробу. Если оно тебе понравится, наши представители будут ждать тебя в Пристанище Темнотерна, которое находится на Аллее Духов в Оргриммаре.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если у тебя достаточно жетонов, ты можешь вступить в клуб "Пиво месяца". Став членом нашего клуба, ты сможешь праздновать Хмельной фестиваль круглый год!$b$bКаждый месяц мы будем посылать тебе образец нашего нового пива на пробу. Если оно тебе понравится, наши представители будут ждать тебя в Пристанище Темнотерна, которое находится на Аллее Духов в Оргриммаре.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (12878,'Ты не $gслышал:слышала; про клуб "Пиво месяца"? О, эти ребята знают толк в веселье. Была б на то их воля – Хмельной фестиваль длился бы вечно! Хотя у меня такое ощущение, что он и так никогда не кончается.$b$bПредставляешь, они нашли способ поддерживать дух фестиваля в течение всего года. К тому же, теперь в их клуб может вступить любой желающий!$b$bДаже ты можешь к ним присоединиться – всего за несколько жетонов Фестиваля! А потом ты будешь каждый месяц получать от них посылочку с образцами пива, которое можно купить у их распространителей. Таким образом, Хмельной фестиваль всегда будет с тобой!','Ты не $gслышал:слышала; про клуб "Пиво месяца"? О, эти ребята знают толк в веселье. Была б на то их воля – Хмельной фестиваль длился бы вечно! Хотя у меня такое ощущение, что он и так никогда не кончается.$b$bПредставляешь, они нашли способ поддерживать дух фестиваля в течение всего года. К тому же, теперь в их клуб может вступить любой желающий!$b$bДаже ты можешь к ним присоединиться – всего за несколько жетонов Фестиваля! А потом ты будешь каждый месяц получать от них посылочку с образцами пива, которое можно купить у их распространителей. Таким образом, Хмельной фестиваль всегда будет с тобой!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты не $gслышал:слышала; про клуб "Пиво месяца"? О, эти ребята знают толк в веселье. Была б на то их воля – Хмельной фестиваль длился бы вечно! Хотя у меня такое ощущение, что он и так никогда не кончается.$b$bПредставляешь, они нашли способ поддерживать дух фестиваля в течение всего года. К тому же, теперь в их клуб может вступить любой желающий!$b$bДаже ты можешь к ним присоединиться – всего за несколько жетонов Фестиваля! А потом ты будешь каждый месяц получать от них посылочку с образцами пива, которое можно купить у их распространителей. Таким образом, Хмельной фестиваль всегда будет с тобой!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты не $gслышал:слышала; про клуб "Пиво месяца"? О, эти ребята знают толк в веселье. Была б на то их воля – Хмельной фестиваль длился бы вечно! Хотя у меня такое ощущение, что он и так никогда не кончается.$b$bПредставляешь, они нашли способ поддерживать дух фестиваля в течение всего года. К тому же, теперь в их клуб может вступить любой желающий!$b$bДаже ты можешь к ним присоединиться – всего за несколько жетонов Фестиваля! А потом ты будешь каждый месяц получать от них посылочку с образцами пива, которое можно купить у их распространителей. Таким образом, Хмельной фестиваль всегда будет с тобой!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (12880,'Ты не $gслышал:слышала; про клуб "Пиво месяца"? Эти веселые ребята хотят праздновать Хмельной фестиваль круглый год! Раньше они пытались организовывать больше фестивалей, но все мероприятия длились недолго.$b$bЗато теперь, если ты вступишь в их клуб, они будут каждый месяц посылать тебе новые образцы пива. Если оно тебе понравится, ты сможешь обратиться к продавцам в Стальгорне и купить себе еще бутылочку-другую.$b$bПо-моему, такого симпатичного |3-3($c) с радостью примут в клуб. Принеси мне несколько призовых жетонов – и я дам тебе регистрационную форму. Тогда мы сможем вместе праздновать Хмельной фестиваль круглый год!','Ты не $gслышал:слышала; про клуб "Пиво месяца"? Эти веселые ребята хотят праздновать Хмельной фестиваль круглый год! Раньше они пытались организовывать больше фестивалей, но все мероприятия длились недолго.$b$bЗато теперь, если ты вступишь в их клуб, они будут каждый месяц посылать тебе новые образцы пива. Если оно тебе понравится, ты сможешь обратиться к продавцам в Стальгорне и купить себе еще бутылочку-другую.$b$bПо-моему, такого симпатичного |3-3($c) с радостью примут в клуб. Принеси мне несколько призовых жетонов – и я дам тебе регистрационную форму. Тогда мы сможем вместе праздновать Хмельной фестиваль круглый год!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты не $gслышал:слышала; про клуб "Пиво месяца"? Эти веселые ребята хотят праздновать Хмельной фестиваль круглый год! Раньше они пытались организовывать больше фестивалей, но все мероприятия длились недолго.$b$bЗато теперь, если ты вступишь в их клуб, они будут каждый месяц посылать тебе новые образцы пива. Если оно тебе понравится, ты сможешь обратиться к продавцам в Стальгорне и купить себе еще бутылочку-другую.$b$bПо-моему, такого симпатичного |3-3($c) с радостью примут в клуб. Принеси мне несколько призовых жетонов – и я дам тебе регистрационную форму. Тогда мы сможем вместе праздновать Хмельной фестиваль круглый год!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты не $gслышал:слышала; про клуб "Пиво месяца"? Эти веселые ребята хотят праздновать Хмельной фестиваль круглый год! Раньше они пытались организовывать больше фестивалей, но все мероприятия длились недолго.$b$bЗато теперь, если ты вступишь в их клуб, они будут каждый месяц посылать тебе новые образцы пива. Если оно тебе понравится, ты сможешь обратиться к продавцам в Стальгорне и купить себе еще бутылочку-другую.$b$bПо-моему, такого симпатичного |3-3($c) с радостью примут в клуб. Принеси мне несколько призовых жетонов – и я дам тебе регистрационную форму. Тогда мы сможем вместе праздновать Хмельной фестиваль круглый год!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12883,'Что ты еще здесь делаешь? Иди назад в город!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что ты еще здесь делаешь? Иди назад в город!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12887,'Королева Алекстраза поставила меня во главе защитников Храма Драконьего Покоя.$B$BКак тебе известно, силы Малигоса уничтожили находившийся неподалеку якорь силовых линий. Затем драконы перенаправили эту силу в Лазуритовое святилище драконов.$B$BСиние драконы используют ее, чтобы стать сильнее; причем настолько, что они смеют атаковать сам замок! Они начинают побеждать.$B$BТы здесь, чтобы помочь нам, |3-6($r)?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Королева Алекстраза поставила меня во главе защитников Храма Драконьего Покоя.$B$BКак тебе известно, силы Малигоса уничтожили находившийся неподалеку якорь силовых линий. Затем драконы перенаправили эту силу в Лазуритовое святилище драконов.$B$BСиние драконы используют ее, чтобы стать сильнее; причем настолько, что они смеют атаковать сам замок! Они начинают побеждать.$B$BТы здесь, чтобы помочь нам, |3-6($r)?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12895,'Эй, |3-6($c), ты $gвидел:видела;? Вон там, над поверхностью воды…$b$bТы ведь тоже это $gвидел:видела;, правда?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эй, |3-6($c), ты $gвидел:видела;? Вон там, над поверхностью воды…$b$bТы ведь тоже это $gвидел:видела;, правда?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12896,'Что?..$b$bНу, я называю их неопределенными плавающими помехами. И там, откуда я, большинство полностью отрицает их существование.$b$bНо мне лучше знать! Я видел их очень близко! Все прошедшие годы я потратил на то, чтобы построить это судно, дабы заняться их обнаружением, выслеживанием, описанием и, если потребуется, их уничтожением!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что?..$b$bНу, я называю их неопределенными плавающими помехами. И там, откуда я, большинство полностью отрицает их существование.$b$bНо мне лучше знать! Я видел их очень близко! Все прошедшие годы я потратил на то, чтобы построить это судно, дабы заняться их обнаружением, выслеживанием, описанием и, если потребуется, их уничтожением!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12897,'Не дай себя обмануть, |3-6($r). Это очень верткие твари. Сейчас они здесь, а моргнешь – и вот их уже нет. Совершенно необъяснимо!$b$bМежду нами говоря, я даже кусочек такой штуковины держал в руках, но не успел как следует исследовать – он попросту пропал.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не дай себя обмануть, |3-6($r). Это очень верткие твари. Сейчас они здесь, а моргнешь – и вот их уже нет. Совершенно необъяснимо!$b$bМежду нами говоря, я даже кусочек такой штуковины держал в руках, но не успел как следует исследовать – он попросту пропал.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12898,'Много ты понимаешь…$b$bКто-то говорит, что они просто наблюдают, кто-то думает, что они изменяют морскую фауну, а еще некоторые считают, что они здесь, чтобы захватить Азерот!$b$bВот когда я собью один из них своими боевыми ракетами, я во всем разберусь, можешь мне поверить!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Много ты понимаешь…$b$bКто-то говорит, что они просто наблюдают, кто-то думает, что они изменяют морскую фауну, а еще некоторые считают, что они здесь, чтобы захватить Азерот!$b$bВот когда я собью один из них своими боевыми ракетами, я во всем разберусь, можешь мне поверить!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
