INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12900,'Отлично, поехали!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Отлично, поехали!',`text0_0_loc8`);
