INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12904,'Грифоны нордскольских вершин – самые живучие из своего вида.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Грифоны нордскольских вершин – самые живучие из своего вида.',`text0_0_loc8`);
