INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12905,'Всадники на грифонах стоят в десяти шагах от нас, $gдруг:подруга;. Они подбросят тебя на заставу Торсона. Отправляйся!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Всадники на грифонах стоят в десяти шагах от нас, $gдруг:подруга;. Они подбросят тебя на заставу Торсона. Отправляйся!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12909,'Привет. Оруженосец Волтер и я отвечаем за уход за Старой Савраской и остальными лошадьми.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Привет. Оруженосец Волтер и я отвечаем за уход за Старой Савраской и остальными лошадьми.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12912,'Добро пожаловать в Лагерь Уанква.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать в Лагерь Уанква.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12926,'Большая часть моих братьев следует варварским обычаям Орды, и когда-то я тоже был среди них. Но когда меня впервые призвали в это чудное, мокрое и… ароматное место, я проклял свою прошлую жизнь.$b$bВо время учебы я научился ценить то, что меня окружает. Согласись, в этом месте есть своя привлекательность!$b$bАх, конечно – мои учения были направлены на то, чтобы позволить другим магам возвращаться сюда с помощью заклинания. Если хочешь, я поделюсь с тобой этим знанием.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Большая часть моих братьев следует варварским обычаям Орды, и когда-то я тоже был среди них. Но когда меня впервые призвали в это чудное, мокрое и… ароматное место, я проклял свою прошлую жизнь.$b$bВо время учебы я научился ценить то, что меня окружает. Согласись, в этом месте есть своя привлекательность!$b$bАх, конечно – мои учения были направлены на то, чтобы позволить другим магам возвращаться сюда с помощью заклинания. Если хочешь, я поделюсь с тобой этим знанием.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12927,'Большая часть моих братьев следует варварским обычаям Орды, и когда-то я тоже был среди них. Но когда меня впервые призвали в это чудное, мокрое и… ароматное место, я проклял свою прошлую жизнь.$b$bВо время учебы я научился ценить то, что меня окружает. Согласись, в этом месте есть своя привлекательность!$b$bЖаль, что ты не маг… тебе вряд ли будет интересно то, чем я занимаюсь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Большая часть моих братьев следует варварским обычаям Орды, и когда-то я тоже был среди них. Но когда меня впервые призвали в это чудное, мокрое и… ароматное место, я проклял свою прошлую жизнь.$b$bВо время учебы я научился ценить то, что меня окружает. Согласись, в этом месте есть своя привлекательность!$b$bЖаль, что ты не маг… тебе вряд ли будет интересно то, чем я занимаюсь.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (12929,'Что? А, прошу прощения, я немного задумался. Я беспокоюсь за ребят из Северной стражи. Надо было послать парочку моих студентов к ним на помощь. Кстати, чем я могу помочь тебе?','Что? А, прошу прощения, я немного задумалась. Я беспокоюсь за ребят из Северной стражи. Надо было послать парочку моих студентов к ним на помощь. Кстати, чем я могу помочь тебе?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что? А, прошу прощения, я немного задумался. Я беспокоюсь за ребят из Северной стражи. Надо было послать парочку моих студентов к ним на помощь. Кстати, чем я могу помочь тебе?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Что? А, прошу прощения, я немного задумалась. Я беспокоюсь за ребят из Северной стражи. Надо было послать парочку моих студентов к ним на помощь. Кстати, чем я могу помочь тебе?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (12930,'Что? А, прошу прощения, если я немного отвлекся. Я беспокоюсь за ребят из Северной стражи. Надо было послать парочку моих студентов к ним на помощь.','Что? А, прошу прощения, я немного задумалась. Я беспокоюсь за ребят из Северной стражи. Надо было послать парочку моих студентов к ним на помощь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что? А, прошу прощения, если я немного отвлекся. Я беспокоюсь за ребят из Северной стражи. Надо было послать парочку моих студентов к ним на помощь.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Что? А, прошу прощения, я немного задумалась. Я беспокоюсь за ребят из Северной стражи. Надо было послать парочку моих студентов к ним на помощь.',`text0_1_loc8`);
