INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12933,'Шину а\'манорэ. Если ты хочешь узнать, как открывать портал в Терамор, я могу тебя научить.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Шину а\'манорэ. Если ты хочешь узнать, как открывать портал в Терамор, я могу тебя научить.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12937,'Хочешь прокатиться, |3-6($r)?$B$BИли просто поболтать по душам?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Хочешь прокатиться, |3-6($r)?$B$BИли просто поболтать по душам?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12938,'Послушай-ка меня. Когда тебе нужен выход из сложной ситуации, то ничто не послужит тебе вернее большого взрыва – и чем он мощнее, тем лучше.$b$bНо, как мне кажется, |3-6($r), на сегодня хватит вопросов.$b$bМои боевые ракеты – штука секретная, а элемент 115, который я для них разработал, еще секретнее! $b$bКороче говоря, для всех будет лучше, если ты вернешься к своим обычным делам и сделаешь вид, что мы никогда не встречались.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Послушай-ка меня. Когда тебе нужен выход из сложной ситуации, то ничто не послужит тебе вернее большого взрыва – и чем он мощнее, тем лучше.$b$bНо, как мне кажется, |3-6($r), на сегодня хватит вопросов.$b$bМои боевые ракеты – штука секретная, а элемент 115, который я для них разработал, еще секретнее! $b$bКороче говоря, для всех будет лучше, если ты вернешься к своим обычным делам и сделаешь вид, что мы никогда не встречались.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12939,'Добро пожаловать, $gстранник:странница;. Ты $gпришел:пришла; как раз вовремя.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Добро пожаловать, $gстранник:странница;. Ты $gпришел:пришла; как раз вовремя.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12940,'Тель\'зан должен умереть, хотя бы для того, чтобы прекратить постоянное нытье!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тель\'зан должен умереть, хотя бы для того, чтобы прекратить постоянное нытье!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12943,'Слушай, |3-6($r).$b$bЕсли ты ищешь крошшер, на котором можно прокатиться, тебе нужно идти в холмы к северу отсюда.$b$bТам есть один списанный.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Слушай, |3-6($r).$b$bЕсли ты ищешь крошшер, на котором можно прокатиться, тебе нужно идти в холмы к северу отсюда.$b$bТам есть один списанный.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12944,'Сначала мы их отремонтировали, чтобы валить тут лес, но с тех пор, как сюда прибыли войска Альянса и развязалась битва, мы используем их в качестве военной техники.$b$bПоверь мне, |3-6($c). Если бы у тебя был ключ, было бы безумием его не использовать.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Сначала мы их отремонтировали, чтобы валить тут лес, но с тех пор, как сюда прибыли войска Альянса и развязалась битва, мы используем их в качестве военной техники.$b$bПоверь мне, |3-6($c). Если бы у тебя был ключ, было бы безумием его не использовать.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12945,'Они у Грекка.$b$bВозможно, он поделится с тобой, если ты его выручишь. В следующий раз, когда будешь на севере, на Лесозаготовках Синего Неба, обязательно поговори с ним.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Они у Грекка.$b$bВозможно, он поделится с тобой, если ты его выручишь. В следующий раз, когда будешь на севере, на Лесозаготовках Синего Неба, обязательно поговори с ним.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12946,'ДА!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','ДА!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12953,'Не думаю, что мы можем позволить себе пренебречь возможностью втереться в доверие к красным драконам. Учитывая предстоящие битвы, иметь их в качестве союзников стало бы просто неоценимым преимуществом.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Не думаю, что мы можем позволить себе пренебречь возможностью втереться в доверие к красным драконам. Учитывая предстоящие битвы, иметь их в качестве союзников стало бы просто неоценимым преимуществом.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12954,'Когда-то в прошлом чернокнижник Некрос Дробитель Черепов воспользовался мощным артефактом, чтобы поработить Алекстразу и значительную часть красных драконов. Зулухед и Некросс мертвы, но наш долг перед красными драконами еще далеко не выплачен.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Когда-то в прошлом чернокнижник Некрос Дробитель Черепов воспользовался мощным артефактом, чтобы поработить Алекстразу и значительную часть красных драконов. Зулухед и Некросс мертвы, но наш долг перед красными драконами еще далеко не выплачен.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12960,'Да, |3-6($c), что?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да, |3-6($c), что?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12965,'Жди приказа!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Жди приказа!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12966,'Добро пожаловать в Гранитные ключи, друг.$b$bЕсли у тебя получится поймать одного из этих ледяных троллей живым, обязательно дай мне знать. Мы за них хорошо платим.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать в Гранитные ключи, друг.$b$bЕсли у тебя получится поймать одного из этих ледяных троллей живым, обязательно дай мне знать. Мы за них хорошо платим.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (12968,'Эй, гляжу, у тебя есть несколько жетонов Хмельного фестиваля. Может быть, ты хочешь их обменять на что-нибудь?','Эй, гляжу, у тебя есть несколько жетонов Хмельного фестиваля. Может быть, ты хочешь их обменять на что-нибудь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эй, гляжу, у тебя есть несколько жетонов Хмельного фестиваля. Может быть, ты хочешь их обменять на что-нибудь?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Эй, гляжу, у тебя есть несколько жетонов Хмельного фестиваля. Может быть, ты хочешь их обменять на что-нибудь?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (12971,'Рад снова видеть тебя, $n. Надеюсь, тебе нравится быть членом нашего клуба.','Рада снова видеть тебя, $n. Надеюсь, тебе нравится быть членом нашего клуба.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Рад снова видеть тебя, $n. Надеюсь, тебе нравится быть членом нашего клуба.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Рада снова видеть тебя, $n. Надеюсь, тебе нравится быть членом нашего клуба.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (12973,'Эй, $n! Надеюсь, тебе нравится быть членом нашего клуба!','Эй, $n! Надеюсь, тебе нравится быть членом нашего клуба!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эй, $n! Надеюсь, тебе нравится быть членом нашего клуба!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Эй, $n! Надеюсь, тебе нравится быть членом нашего клуба!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (12995,'Удачи тебе и будь $gосторожен:осторожна;. Теперь сюда идут Утер и Джайна.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Удачи тебе и будь $gосторожен:осторожна;. Теперь сюда идут Утер и Джайна.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12998,'<Дракуру протягивает свою истекающую кровью руку через прутья клетки и выжидательно смотрит на тебя.>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Дракуру протягивает свою истекающую кровью руку через прутья клетки и выжидательно смотрит на тебя.>',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (12999,'Были времена, когда я вырвал бы тебе сердце просто для того, чтобы посмотреть, какое у тебя станет лицо…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Были времена, когда я вырвал бы тебе сердце просто для того, чтобы посмотреть, какое у тебя станет лицо…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13002,'Вот, держи. Постарайся хотя бы в этот раз не потерять, ладно?$b$bА теперь отправляйся в руины Драк\'Зина и выпей это у пьедестала!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вот, держи. Постарайся хотя бы в этот раз не потерять, ладно?$b$bА теперь отправляйся в руины Драк\'Зина и выпей это у пьедестала!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13003,'Именно с этого трона я отдаю команды Адского Крика. Его слово – жизнь и его слово – смерть.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Именно с этого трона я отдаю команды Адского Крика. Его слово – жизнь и его слово – смерть.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (13004,'Да благословит тебя Элуна, |3-6($r).') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Да благословит тебя Элуна, |3-6($r).',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13005,'Чем я могу помочь вам, $gсэр:мэм;?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Чем я могу помочь вам, $gсэр:мэм;?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13006,'Мой партнер убивает всяких существ, а я вытягиваю часть их сущности... самую капельку. Мелочи, право.$B$BНо, чтобы до конца выполнить свою часть контракта, я вынужден платить эфириальными монетами.$B$BЗа эти монеты можно купить у меня некоторые вещи. Я вынужден иметь при себе то, что может тебя заинтересовать...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мой партнер убивает всяких существ, а я вытягиваю часть их сущности... самую капельку. Мелочи, право.$B$BНо, чтобы до конца выполнить свою часть контракта, я вынужден платить эфириальными монетами.$B$BЗа эти монеты можно купить у меня некоторые вещи. Я вынужден иметь при себе то, что может тебя заинтересовать...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (13009,'Только так Гарри может заговорить со мной! И мне приходится все время носить эту дурацкую маску!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Только так Гарри может заговорить со мной! И мне приходится все время носить эту дурацкую маску!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13011,'Привет, $gбратишка:сестренка;!$b$bЭто не совсем то, чем кажется. Ну, может быть…$b$bВсе очень сложно.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Привет, $gбратишка:сестренка;!$b$bЭто не совсем то, чем кажется. Ну, может быть…$b$bВсе очень сложно.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13012,'Эй, ты! Я тебя знаю?$b$bАх, да, у Пригмона хорошая память на лица.$b$bА ты не следишь ли за мной случайно? Что бы там ни было, Пригмон этого не делал!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эй, ты! Я тебя знаю?$b$bАх, да, у Пригмона хорошая память на лица.$b$bА ты не следишь ли за мной случайно? Что бы там ни было, Пригмон этого не делал!',`text0_0_loc8`);
