INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (13022,'Чем я могу помочь тебе, дитя?','Чем я могу помочь тебе, дитя?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Чем я могу помочь тебе, дитя?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Чем я могу помочь тебе, дитя?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (13024,'Думаю, тебе лучше уйти. Ты пугаешь мистера Ушастика.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Думаю, тебе лучше уйти. Ты пугаешь мистера Ушастика.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13025,'Добро пожаловать в храм Драконьего Покоя, |3-6($r). Прости нас за шумиху внизу, из-за последних действий Малигоса мы оказались под осадой. Ты можешь тем не менее отдохнуть здесь под нашей защитой, если она тебе понадобится.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать в храм Драконьего Покоя, |3-6($r). Прости нас за шумиху внизу, из-за последних действий Малигоса мы оказались под осадой. Ты можешь тем не менее отдохнуть здесь под нашей защитой, если она тебе понадобится.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (13026,'Силы Плети обрушились на нас. Мужайтесь и сражайтесь!','Силы Плети обрушились на нас. Мужайтесь и сражайтесь!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Силы Плети обрушились на нас. Мужайтесь и сражайтесь!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Силы Плети обрушились на нас. Мужайтесь и сражайтесь!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (13028,'Мы должны выстоять! Крепись! Выжигай зловредную чуму везде, где найдешь!','Мы должны выстоять! Крепись! Выжигай зловредную чуму везде, где найдешь!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы должны выстоять! Крепись! Выжигай зловредную чуму везде, где найдешь!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мы должны выстоять! Крепись! Выжигай зловредную чуму везде, где найдешь!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13030,'Приветствую, |3-6($c)!$b$bНадеюсь, ты не против немного поработать. Мы были бы очень рады, если бы ты нам $gпомог:помогла;.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приветствую, |3-6($c)!$b$bНадеюсь, ты не против немного поработать. Мы были бы очень рады, если бы ты нам $gпомог:помогла;.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (13031,'Ветер и деревья шепчут о беде – о той, что крадется незримо… Кажется, что эта земля здорова; но здесь происходит что-то, чего мы не видим…') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ветер и деревья шепчут о беде – о той, что крадется незримо… Кажется, что эта земля здорова; но здесь происходит что-то, чего мы не видим…',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (13032,'<Тайрин смотрит перед собой невидящими глазами. Судя по всему, очищение Фодрассила от скверны отняло у друида слишком много сил.>') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','<Тайрин смотрит перед собой невидящими глазами. Судя по всему, очищение Фодрассила от скверны отняло у друида слишком много сил.>',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13034,'Запасы в дорогу? Может быть, освежающий напиток, пока вы смотрите бои?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Запасы в дорогу? Может быть, освежающий напиток, пока вы смотрите бои?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13035,'Нас окружили со всех сторон, и старейшины собираются бежать, оставив эти земли врагу. Мне кажется, это неправильно! Мы должны остаться и сражаться за нашу родину!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Нас окружили со всех сторон, и старейшины собираются бежать, оставив эти земли врагу. Мне кажется, это неправильно! Мы должны остаться и сражаться за нашу родину!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13043,'Добро пожаловать на Серебряную заставу, |3-6($c).$b$bРасполагайся как дома, но не слишком расслабляйся. Тут еще полно опасностей.$b$bЕсли мы хотим выбраться отсюда целыми и невредимыми, всем нужно будет поработать… в том числе тебе.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать на Серебряную заставу, |3-6($c).$b$bРасполагайся как дома, но не слишком расслабляйся. Тут еще полно опасностей.$b$bЕсли мы хотим выбраться отсюда целыми и невредимыми, всем нужно будет поработать… в том числе тебе.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13045,'Ну и в заварушку мы попали.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ну и в заварушку мы попали.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13046,'Эти земли осквернены присутствием Плети с одной стороны и ритуалами Драккари – с другой.$B$BМы твердо держим наши позиции между ними.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эти земли осквернены присутствием Плети с одной стороны и ритуалами Драккари – с другой.$B$BМы твердо держим наши позиции между ними.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`,`text2_0_loc8`,`text2_1_loc8`,`text4_0_loc8`,`text4_1_loc8`,`text5_0_loc8`,`text5_1_loc8`,`text6_0_loc8`,`text6_1_loc8`,`text7_0_loc8`,`text7_1_loc8`) VALUES (13047,'Да хранит тебя Свет!','Да хранит тебя Свет!','Эй, ты там, |3-6($c)! У нас тут бой в разгаре.','Эй, ты там, |3-6($c)! У нас тут бой в разгаре.','Что ты там делаешь?','Что ты там делаешь?','Только быстрее… сражаться здесь не очень-то приятно. Мне нужно быть начеку.','Только быстрее… сражаться здесь не очень-то приятно. Мне нужно быть начеку.','Ты – новый рекрут? Это не предписанная уставом форма.','Ты – новый рекрут? Это не предписанная уставом форма.','Отлично, подкрепление подоспело!','Отлично, подкрепление подоспело!','У тебя для меня сообщение?','У тебя для меня сообщение?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да хранит тебя Свет!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Да хранит тебя Свет!',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Эй, ты там, |3-6($c)! У нас тут бой в разгаре.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Эй, ты там, |3-6($c)! У нас тут бой в разгаре.',`text1_1_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Что ты там делаешь?',`text2_0_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Что ты там делаешь?',`text2_1_loc8`), `text4_0_loc8`=IF(`text4_0_loc8` IS NULL OR `text4_0_loc8`='','Только быстрее… сражаться здесь не очень-то приятно. Мне нужно быть начеку.',`text4_0_loc8`), `text4_1_loc8`=IF(`text4_1_loc8` IS NULL OR `text4_1_loc8`='','Только быстрее… сражаться здесь не очень-то приятно. Мне нужно быть начеку.',`text4_1_loc8`), `text5_0_loc8`=IF(`text5_0_loc8` IS NULL OR `text5_0_loc8`='','Ты – новый рекрут? Это не предписанная уставом форма.',`text5_0_loc8`), `text5_1_loc8`=IF(`text5_1_loc8` IS NULL OR `text5_1_loc8`='','Ты – новый рекрут? Это не предписанная уставом форма.',`text5_1_loc8`), `text6_0_loc8`=IF(`text6_0_loc8` IS NULL OR `text6_0_loc8`='','Отлично, подкрепление подоспело!',`text6_0_loc8`), `text6_1_loc8`=IF(`text6_1_loc8` IS NULL OR `text6_1_loc8`='','Отлично, подкрепление подоспело!',`text6_1_loc8`), `text7_0_loc8`=IF(`text7_0_loc8` IS NULL OR `text7_0_loc8`='','У тебя для меня сообщение?',`text7_0_loc8`), `text7_1_loc8`=IF(`text7_1_loc8` IS NULL OR `text7_1_loc8`='','У тебя для меня сообщение?',`text7_1_loc8`);
