INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13048,'Здесь немножко опаснее, чем ты $gожидал:ожидала;, |3-6($r)?$b$bНе могу сказать, что я удивлен. Я это слышу почти ото всех, кто добирается досюда.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здесь немножко опаснее, чем ты $gожидал:ожидала;, |3-6($r)?$b$bНе могу сказать, что я удивлен. Я это слышу почти ото всех, кто добирается досюда.',`text0_0_loc8`);
