INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13055,'Хей, дорогуша!$B$BСегодня НАШ день… ДЕНЬ ПИРАТА!$B$BМы тут придумали кое-что со стариной Манком, и как только Жуткий Капитан услышала про нашу идею, тут же послала нас сюда!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Хей, дорогуша!$B$BСегодня НАШ день… ДЕНЬ ПИРАТА!$B$BМы тут придумали кое-что со стариной Манком, и как только Жуткий Капитан услышала про нашу идею, тут же послала нас сюда!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13057,'Апана скалится и машет вам рукой, указывая на Жуткого Капитана де Мезу.$B$BПод густыми волосами, покрывающими его мускулистую руку, можно различить татуировку со словом "Магата" в пронзенном стрелой сердце".') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Апана скалится и машет вам рукой, указывая на Жуткого Капитана де Мезу.$B$BПод густыми волосами, покрывающими его мускулистую руку, можно различить татуировку со словом "Магата" в пронзенном стрелой сердце".',`text0_0_loc8`);
