INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13058,'Йо-хо-хо! Якорь тебе в глотку! Якорь!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Йо-хо-хо! Якорь тебе в глотку! Якорь!',`text0_0_loc8`);
