INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13060,'Ой… что-то у меня голова закружилась…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ой… что-то у меня голова закружилась…',`text0_0_loc8`);
