INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13061,'Не приставай ко мне, |3-6($c)! У меня тут горячий цех – надо следить за тем, чтобы эти два котла с пивом не выкипели!$B$BЕсли вкус будет не слишком хорош, мастер Корен Худовар сварит меня там живьем!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не приставай ко мне, |3-6($c)! У меня тут горячий цех – надо следить за тем, чтобы эти два котла с пивом не выкипели!$B$BЕсли вкус будет не слишком хорош, мастер Корен Худовар сварит меня там живьем!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`,`text3_0_loc8`) VALUES (13064,'Отличное пиво! Правда, слегка слабовато, на мой вкус. Я бы добавил немного чесночного душка…','Хорошо получилось! Но мне кажется, оно немного плоское. Давай-ка закруглим его с помощью нескольких мягких глаз василиска…','Неплохо, неплохо… Правда, не хватает перчинки! Может быть, добавить яда скорпида? Точно! Получится то, что надо!','Ага, уже лучше! Но все равно, чего-то не хватает… О, точно! Давай постираем в котле носки недельной давности… Ммм, вкуснятина!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Отличное пиво! Правда, слегка слабовато, на мой вкус. Я бы добавил немного чесночного душка…',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Хорошо получилось! Но мне кажется, оно немного плоское. Давай-ка закруглим его с помощью нескольких мягких глаз василиска…',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Неплохо, неплохо… Правда, не хватает перчинки! Может быть, добавить яда скорпида? Точно! Получится то, что надо!',`text2_0_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Ага, уже лучше! Но все равно, чего-то не хватает… О, точно! Давай постираем в котле носки недельной давности… Ммм, вкуснятина!',`text3_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (13065,'Йо-хо! Сегодня День пирата, знаешь ли… и до восхода солнца Пиратская Бухта МОЯ!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Йо-хо! Сегодня День пирата, знаешь ли… и до восхода солнца Пиратская Бухта МОЯ!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13068,'Истинно, ужасы, которые происходят здесь, превосходят даже те, что мы испытали в Чумных землях.$b$bТеперь силы Плети более могущественны, чем когда-либо.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Истинно, ужасы, которые происходят здесь, превосходят даже те, что мы испытали в Чумных землях.$b$bТеперь силы Плети более могущественны, чем когда-либо.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`,`text2_0_loc8`,`text2_1_loc8`,`text3_0_loc8`,`text3_1_loc8`,`text4_0_loc8`,`text4_1_loc8`,`text5_0_loc8`,`text5_1_loc8`,`text6_0_loc8`,`text6_1_loc8`,`text7_0_loc8`,`text7_1_loc8`) VALUES (13069,'Я так больше не могу…$b$bОни убивают тебя, а потом едят! И это если повезет!','Я так больше не могу…$b$bОни убивают тебя, а потом едят! И это если повезет!','Ты $gдолжен:должна; помочь мне выбраться отсюда, |3-6($r)!$b$bЯ не хочу стать таким, как они!','Ты $gдолжен:должна; помочь мне выбраться отсюда, |3-6($r)!$b$bЯ не хочу стать такой, как они!','Я не могу ни есть, ни спать с тех пор, как попал сюда.$b$bЯ же не просто отрезанный ломоть для Авангарда…','Я не могу ни есть, ни спать с тех пор, как попала сюда.$b$bЯ же не просто отрезанный ломоть для Авангарда…','<хнык> Мой дядя служил в Серебряном Рассвете.$b$bКак у него получалось противостоять этим злобным тварям?','<хнык> Мой дядя служил в Серебряном Рассвете.$b$bКак у него получалось противостоять этим злобным тварям?','Каждый раз, когда я закрываю глаза, я вижу, как силы Плети окружают меня!$b$bМне нужно выбраться отсюда…','Каждый раз, когда я закрываю глаза, я вижу, как силы Плети окружают меня!$b$bМне нужно выбраться отсюда…','Я здесь умру… я это просто знаю.','Я здесь умру… я просто знаю это.','Мы обреченыыыы!!','Мы обреченыыыы!!','Выбирайся отсюда, пока можешь, |3-6($c)!$b$bНам ни за что не победить…','Выбирайся отсюда, пока можешь, |3-6($c)!$b$bНам ни за что не победить…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я так больше не могу…$b$bОни убивают тебя, а потом едят! И это если повезет!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я так больше не могу…$b$bОни убивают тебя, а потом едят! И это если повезет!',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Ты $gдолжен:должна; помочь мне выбраться отсюда, |3-6($r)!$b$bЯ не хочу стать таким, как они!',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Ты $gдолжен:должна; помочь мне выбраться отсюда, |3-6($r)!$b$bЯ не хочу стать такой, как они!',`text1_1_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Я не могу ни есть, ни спать с тех пор, как попал сюда.$b$bЯ же не просто отрезанный ломоть для Авангарда…',`text2_0_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Я не могу ни есть, ни спать с тех пор, как попала сюда.$b$bЯ же не просто отрезанный ломоть для Авангарда…',`text2_1_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','<хнык> Мой дядя служил в Серебряном Рассвете.$b$bКак у него получалось противостоять этим злобным тварям?',`text3_0_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','<хнык> Мой дядя служил в Серебряном Рассвете.$b$bКак у него получалось противостоять этим злобным тварям?',`text3_1_loc8`), `text4_0_loc8`=IF(`text4_0_loc8` IS NULL OR `text4_0_loc8`='','Каждый раз, когда я закрываю глаза, я вижу, как силы Плети окружают меня!$b$bМне нужно выбраться отсюда…',`text4_0_loc8`), `text4_1_loc8`=IF(`text4_1_loc8` IS NULL OR `text4_1_loc8`='','Каждый раз, когда я закрываю глаза, я вижу, как силы Плети окружают меня!$b$bМне нужно выбраться отсюда…',`text4_1_loc8`), `text5_0_loc8`=IF(`text5_0_loc8` IS NULL OR `text5_0_loc8`='','Я здесь умру… я это просто знаю.',`text5_0_loc8`), `text5_1_loc8`=IF(`text5_1_loc8` IS NULL OR `text5_1_loc8`='','Я здесь умру… я просто знаю это.',`text5_1_loc8`), `text6_0_loc8`=IF(`text6_0_loc8` IS NULL OR `text6_0_loc8`='','Мы обреченыыыы!!',`text6_0_loc8`), `text6_1_loc8`=IF(`text6_1_loc8` IS NULL OR `text6_1_loc8`='','Мы обреченыыыы!!',`text6_1_loc8`), `text7_0_loc8`=IF(`text7_0_loc8` IS NULL OR `text7_0_loc8`='','Выбирайся отсюда, пока можешь, |3-6($c)!$b$bНам ни за что не победить…',`text7_0_loc8`), `text7_1_loc8`=IF(`text7_1_loc8` IS NULL OR `text7_1_loc8`='','Выбирайся отсюда, пока можешь, |3-6($c)!$b$bНам ни за что не победить…',`text7_1_loc8`);
