INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13092,'Не стоит так задирать нос!$B$BМогу тебе сообщить, что Ступесты – старинное семейство с давними традициями толчения в ступе.$B$BДа-да!$B$BЛучших алхимиков нет на всем Азероте, да, кстати, и вообще где-либо, могу тебя заверить!$B$BМожет быть, я сейчас ношу звание подмастерья, но в умении я никому не уступаю! Однако приходится выносить такие унижения, чтобы получить место под солнцем.$B$BХотя, может быть, ты здесь затем, чтобы мне помочь?$B$B<Миниатюрный гном нагло улыбается.>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не стоит так задирать нос!$B$BМогу тебе сообщить, что Ступесты – старинное семейство с давними традициями толчения в ступе.$B$BДа-да!$B$BЛучших алхимиков нет на всем Азероте, да, кстати, и вообще где-либо, могу тебя заверить!$B$BМожет быть, я сейчас ношу звание подмастерья, но в умении я никому не уступаю! Однако приходится выносить такие унижения, чтобы получить место под солнцем.$B$BХотя, может быть, ты здесь затем, чтобы мне помочь?$B$B<Миниатюрный гном нагло улыбается.>',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (13093,'Слушай, скажи Швайцеру и Ройтау, что у нас тут все под контролем. Пусть даже не… что?$B$BОни тебя не посылали ко мне? Тогда зачем ты тратишь мое драгоценное время?$B$BУ меня дел по горло!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Слушай, скажи Швайцеру и Ройтау, что у нас тут все под контролем. Пусть даже не… что?$B$BОни тебя не посылали ко мне? Тогда зачем ты тратишь мое драгоценное время?$B$BУ меня дел по горло!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13096,'Ну, что ж. Все равно нам надо протестировать оборудование.$B$BТак… секундочку. Сейчас мы устроим генеральную репетицию.$B$BВсе готовы?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ну, что ж. Все равно нам надо протестировать оборудование.$B$BТак… секундочку. Сейчас мы устроим генеральную репетицию.$B$BВсе готовы?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13097,'Приветствую вас, |3-6($r).$b$bБоюсь, вы должны извинить меня, но я сейчас ужасно занят.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приветствую вас, |3-6($r).$b$bБоюсь, вы должны извинить меня, но я сейчас ужасно занят.',`text0_0_loc8`);
