INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13098,'Время не ждет, $n.Ты $gготов:готова; пройти испытание?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Время не ждет, $n.Ты $gготов:готова; пройти испытание?',`text0_0_loc8`);
