INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13117,'Вот именно этого нам и не хватало – чтобы эти безумные тролли Драккари сбили некрополь Плети у нас в тылу!$B$BКак им это вообще удалось?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вот именно этого нам и не хватало – чтобы эти безумные тролли Драккари сбили некрополь Плети у нас в тылу!$B$BКак им это вообще удалось?',`text0_0_loc8`);
