INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (13118,'Ах, не нужно было мне идти в специалисты-добровольцы. Они постоянно требуют от нас невозможного!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ах, не нужно было мне идти в специалисты-добровольцы. Они постоянно требуют от нас невозможного!',`text0_1_loc8`);
