INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13119,'Быстрее, |3-6($c)!$b$bКлади ингредиенты прямо в горшок. Время не ждет!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Быстрее, |3-6($c)!$b$bКлади ингредиенты прямо в горшок. Время не ждет!',`text0_0_loc8`);
