INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13137,'Омерзительный друг длинноязыких, тебе здесь не место. Уходи из земли Бешеного Сердца, или я призову всякую разную магию, чтобы убить тебя!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Омерзительный друг длинноязыких, тебе здесь не место. Уходи из земли Бешеного Сердца, или я призову всякую разную магию, чтобы убить тебя!',`text0_0_loc8`);
