INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (13139,'Ты станешь моим спасением.$B$BА может быть, моей кончиной.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты станешь моим спасением.$B$BА может быть, моей кончиной.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13147,'Видели ли вы когда-нибудь драконов, подобных этим? Отличное место для охоты.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Видели ли вы когда-нибудь драконов, подобных этим? Отличное место для охоты.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (13155,'Прошу прощения, но мы разливаем наше пиво только для членов клуба "Пиво месяца".','Прошу прощения, но мы разливаем наше пиво только для членов клуба "Пиво месяца".') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Прошу прощения, но мы разливаем наше пиво только для членов клуба "Пиво месяца".',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Прошу прощения, но мы разливаем наше пиво только для членов клуба "Пиво месяца".',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13156,'Это место безопасно, |3-6($r).$b$bВраг был вытеснен с этой территории некоторое время назад.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Это место безопасно, |3-6($r).$b$bВраг был вытеснен с этой территории некоторое время назад.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (13157,'Спасибо, что $gосвободил:освободила; меня, |3-6($r).$b$bМеня все еще немного покачивает от этого яда. Мне кажется, мне лучше остаться здесь, пока мои силы не восстановились.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Спасибо, что $gосвободил:освободила; меня, |3-6($r).$b$bМеня все еще немного покачивает от этого яда. Мне кажется, мне лучше остаться здесь, пока мои силы не восстановились.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (13172,'Благодаря силе нечестивости мы можем повелевать самой смертью!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Благодаря силе нечестивости мы можем повелевать самой смертью!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13173,'Кровь – это жизнь… И управлять жизнью наших врагов так же легко, как пустить кому-нибудь кровь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Кровь – это жизнь… И управлять жизнью наших врагов так же легко, как пустить кому-нибудь кровь.',`text0_0_loc8`);
