INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13174,'Мы то, что приносит промозглый ветер. Ледяной озноб отчаяния… Холодные объятия смерти…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы то, что приносит промозглый ветер. Ледяной озноб отчаяния… Холодные объятия смерти…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13176,'Мы все опечалены тем, как Драккари уничтожают самих себя.$B$BСила, которую они получают, убивая настоящих богов этой земли, эфемерна.$B$BВсе, чем они сейчас пользуются, позднее будет утрачено навеки.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы все опечалены тем, как Драккари уничтожают самих себя.$B$BСила, которую они получают, убивая настоящих богов этой земли, эфемерна.$B$BВсе, чем они сейчас пользуются, позднее будет утрачено навеки.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13177,'Быстро, соберитесь с духом, надо продолжать.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Быстро, соберитесь с духом, надо продолжать.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13179,'Чем дальше, тем сложнее. Стратхольм пылает. Мы должны бросить вызов Плети и пламени, чтобы добраться до Мал\'Ганиса. Приготовьтесь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Чем дальше, тем сложнее. Стратхольм пылает. Мы должны бросить вызов Плети и пламени, чтобы добраться до Мал\'Ганиса. Приготовьтесь.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (13180,'Зим\'Торга может предоставить тебе известную степень защиты, но она была очень ослаблена присутствием Плети и действиями драккари.$B$BНа нашу долю с Ауне выпало наблюдать обломки нашей былой защиты.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Зим\'Торга может предоставить тебе известную степень защиты, но она была очень ослаблена присутствием Плети и действиями драккари.$B$BНа нашу долю с Ауне выпало наблюдать обломки нашей былой защиты.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13255,'Рубиновый дракон в расцвете сил может применить заклятие Мученика, которое в течение короткого времени защищает все дружественные цели, перенаправляя всю враждебную магию на рубинового дракона. Во время действия заклинания могут быть использованы маневры уклонения.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Рубиновый дракон в расцвете сил может применить заклятие Мученика, которое в течение короткого времени защищает все дружественные цели, перенаправляя всю враждебную магию на рубинового дракона. Во время действия заклинания могут быть использованы маневры уклонения.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13261,'Добро пожаловать в лагерь, |3-6($c).') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать в лагерь, |3-6($c).',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13262,'Что именно тебе нужно от Корвия?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что именно тебе нужно от Корвия?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13265,'Подумай обо всем, что тебе довелось повидать за этот день, $n.$b$bБудущее уже предрешено. Изменить ты можешь только свою роль в нем.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Подумай обо всем, что тебе довелось повидать за этот день, $n.$b$bБудущее уже предрешено. Изменить ты можешь только свою роль в нем.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13267,'Круги наверху обороняют самые могущественные слуги Малигоса. В одиночку не стоит и надеяться их одолеть. Мы можем даровать тебе власть призывать драконов из наших выводков. Оседлав дракона, ты сможешь прилететь сюда, в Окулус, и повелевать могущественной магией драконов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Круги наверху обороняют самые могущественные слуги Малигоса. В одиночку не стоит и надеяться их одолеть. Мы можем даровать тебе власть призывать драконов из наших выводков. Оседлав дракона, ты сможешь прилететь сюда, в Окулус, и повелевать могущественной магией драконов.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13270,'Никто не знает Плеть лучше, чем мы, рыцари смерти!$b$bПоверь мне, |3-6($r), огонь легче всего победить при помощи огня…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Никто не знает Плеть лучше, чем мы, рыцари смерти!$b$bПоверь мне, |3-6($r), огонь легче всего победить при помощи огня…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13271,'Полегче со старым Нассом. Он не такой молодой и выносливый, как был когда-то.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Полегче со старым Нассом. Он не такой молодой и выносливый, как был когда-то.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13282,'Хотя мои соотечественники хотели бы, чтобы вы принимали активное участие в происходящем в Зул\'Драке, мы, зандалары, находимся здесь в первую очередь для того, чтобы наблюдать за происходящим и запечатлеть конец империи.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Хотя мои соотечественники хотели бы, чтобы вы принимали активное участие в происходящем в Зул\'Драке, мы, зандалары, находимся здесь в первую очередь для того, чтобы наблюдать за происходящим и запечатлеть конец империи.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13287,'Ты $gготов:готова; встретиться лицом к лицу с Мал\'Ганисом вместе со мной?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты $gготов:готова; встретиться лицом к лицу с Мал\'Ганисом вместе со мной?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13288,'Все готово, можно начинать.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Все готово, можно начинать.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (13289,'Проходи, проходи. Не на что тут смотреть.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Проходи, проходи. Не на что тут смотреть.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (13301,'Мы тут пытаемся взорвать эту стенку, чтобы люди Вика смогли построить новый путь к гавани, а этот безмозглый болван ставит мне палки в колеса. Говорит, я кладу слишком много взрывчатки!$B$BХа! Я работал подрывником, когда он еще под стол пешком ходил! Еще одна задержка – и я его собственными руками в канал спихну, чтобы не мешал мне заниматься моим делом.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мы тут пытаемся взорвать эту стенку, чтобы люди Вика смогли построить новый путь к гавани, а этот безмозглый болван ставит мне палки в колеса. Говорит, я кладу слишком много взрывчатки!$B$BХа! Я работал подрывником, когда он еще под стол пешком ходил! Еще одна задержка – и я его собственными руками в канал спихну, чтобы не мешал мне заниматься моим делом.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (13303,'Плеть – это грязное пятно, оскверняющее эти непорочные земли. Клянусь силой моих создателей, я сокрушу их всех, до последней гнилой косточки!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Плеть – это грязное пятно, оскверняющее эти непорочные земли. Клянусь силой моих создателей, я сокрушу их всех, до последней гнилой косточки!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (13304,'Титаны не за одну ночь жизнь создавали. Процесс был постепенным, требовались серьезные эксперименты и различные циклы повторений.$B$BИменно по этой причине существуют столь хорошо защищенные места, как низина Шолазар.$B$BЧтобы обеспечить безопасность своих экспериментальных площадок, титаны создали механизм защиты. Его разрушительная сила беспримерна, и я ничего не расскажу тебе до тех пор, пока ты не поклянешься в верности моему делу.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Титаны не за одну ночь жизнь создавали. Процесс был постепенным, требовались серьезные эксперименты и различные циклы повторений.$B$BИменно по этой причине существуют столь хорошо защищенные места, как низина Шолазар.$B$BЧтобы обеспечить безопасность своих экспериментальных площадок, титаны создали механизм защиты. Его разрушительная сила беспримерна, и я ничего не расскажу тебе до тех пор, пока ты не поклянешься в верности моему делу.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (13305,'Открывать тайны, подобные этой, смертному существу – граничит с кощунством, но у меня нет выбора.$B$BС тех самых пор, как Фрейя, дочь титанов, оставила меня здесь, у меня была лишь одна задача, и потерпеть неудачу я не могу. Жизнь нужно защитить любой ценой.$B$BЕсть спираль, связующая это место с другим, очень похожим. Именно там можно найти оружие, которое мы ищем.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Открывать тайны, подобные этой, смертному существу – граничит с кощунством, но у меня нет выбора.$B$BС тех самых пор, как Фрейя, дочь титанов, оставила меня здесь, у меня была лишь одна задача, и потерпеть неудачу я не могу. Жизнь нужно защитить любой ценой.$B$BЕсть спираль, связующая это место с другим, очень похожим. Именно там можно найти оружие, которое мы ищем.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13306,'Этот форпост – зона, свободная от шестеренок. Те, кто используют шестеренки при сборе механических устройств, будут подвергнуты безжалостным насмешкам.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Этот форпост – зона, свободная от шестеренок. Те, кто используют шестеренки при сборе механических устройств, будут подвергнуты безжалостным насмешкам.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (13307,'Похоже, тебе пришло в голову то же, что и мне. Ищешь фрукты, а?','Похоже, тебе пришло в голову то же, что и мне. Ищешь фрукты, а?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Похоже, тебе пришло в голову то же, что и мне. Ищешь фрукты, а?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Похоже, тебе пришло в голову то же, что и мне. Ищешь фрукты, а?',`text0_1_loc8`);
