INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13318,'Мохоброд, похоже, тяжело ранен.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мохоброд, похоже, тяжело ранен.',`text0_0_loc8`);
