INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (13331,'Тебе нравится новый дом, что я создала для своих так называемых поклонников?$B$BВ агонии перед моей смертью я прокляла их и затянула вместе с собой в этот ад, созданный моими собственными руками.$B$BЯ думаю, мне стоит наслаждаться их вечными муками, но что я на самом деле хочу, так это отомстить моему бывшему пророку!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Тебе нравится новый дом, что я создала для своих так называемых поклонников?$B$BВ агонии перед моей смертью я прокляла их и затянула вместе с собой в этот ад, созданный моими собственными руками.$B$BЯ думаю, мне стоит наслаждаться их вечными муками, но что я на самом деле хочу, так это отомстить моему бывшему пророку!',`text0_1_loc8`);
