INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (13349,'Добро пожаловать в даларанское бюро регистрации гильдий. Чем могу помочь?','Добро пожаловать в даларанское бюро регистрации гильдий. Чем могу помочь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать в даларанское бюро регистрации гильдий. Чем могу помочь?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Добро пожаловать в даларанское бюро регистрации гильдий. Чем могу помочь?',`text0_1_loc8`);
