INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13352,'Надеюсь, верховный маг оценит, через что я прошел, чтобы Хеминг выполнил свою часть соглашения.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Надеюсь, верховный маг оценит, через что я прошел, чтобы Хеминг выполнил свою часть соглашения.',`text0_0_loc8`);
