INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (13353,'А сейчас держись-ка поближе к Артасу!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','А сейчас держись-ка поближе к Артасу!',`text0_1_loc8`);
