INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13355,'Мы отнимем у них все, рыцарь смерти.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы отнимем у них все, рыцарь смерти.',`text0_0_loc8`);
