INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13359,'Бешеное Сердце захватит землю для себя. Длинноязыкие уйдут, или мы всех их убьем.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Бешеное Сердце захватит землю для себя. Длинноязыкие уйдут, или мы всех их убьем.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13360,'Может быть, волчеры Бешеного Сердца и кажутся извергами, но в глубине души мы добрые и сентиментальные. Ты увидишь, если задержишься надолго – мы хорошо ладим с сильными и умными.$B$BМы просто не любим глупых.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Может быть, волчеры Бешеного Сердца и кажутся извергами, но в глубине души мы добрые и сентиментальные. Ты увидишь, если задержишься надолго – мы хорошо ладим с сильными и умными.$B$BМы просто не любим глупых.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13362,'Чего мне не хватает в росте, я добираю в магии. Я хорошо забочусь о великом камне тумана… большую часть времени.$B$BТупые волосатые…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Чего мне не хватает в росте, я добираю в магии. Я хорошо забочусь о великом камне тумана… большую часть времени.$B$BТупые волосатые…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13363,'Волосатые атакуют нас уже несколько дней. Но великий камень молний по-прежнему в безопасности.$B$BСу-холу пришел к нам на помощь, как и много раз прежде… у волосатых нет ни единого шанса.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Волосатые атакуют нас уже несколько дней. Но великий камень молний по-прежнему в безопасности.$B$BСу-холу пришел к нам на помощь, как и много раз прежде… у волосатых нет ни единого шанса.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13364,'Картак приходит за мясом длинноязыких. Бешеное Сердце обеспечивает, чтобы много мяса было готово.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Картак приходит за мясом длинноязыких. Бешеное Сердце обеспечивает, чтобы много мяса было готово.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text2_0_loc8`,`text3_0_loc8`) VALUES (13365,'Есть причина, по которой мы все еще здесь?','Я так понимаю, тебе что-то нужно.') ON DUPLICATE KEY UPDATE `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Есть причина, по которой мы все еще здесь?',`text2_0_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Я так понимаю, тебе что-то нужно.',`text3_0_loc8`);
