INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text2_0_loc8`,`text3_0_loc8`) VALUES (13366,'Все в порядке?','Хорошо иметь верного товарища по охоте.','Что-то не так?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Все в порядке?',`text0_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Хорошо иметь верного товарища по охоте.',`text2_0_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Что-то не так?',`text3_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`,`text3_0_loc8`) VALUES (13367,'Привет! Ты как? Мы хорошо… угу, хорошо-хорошо. Привет!','Когда-нибудь ты $gспотыкался:спотыкалась; о свои ноги? Мы спотыкались. Как-то больно. Не делай этого, неприятно. Нет.','Привет! Ты на свете всех сильнее, и прекрасней, и все такое. Ты мне нравишься. Давай дружить?','Хочешь, чтобы мы тебе помогли? Чем тебе помочь? Мы хорошо помогаем.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Привет! Ты как? Мы хорошо… угу, хорошо-хорошо. Привет!',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Когда-нибудь ты $gспотыкался:спотыкалась; о свои ноги? Мы спотыкались. Как-то больно. Не делай этого, неприятно. Нет.',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Привет! Ты на свете всех сильнее, и прекрасней, и все такое. Ты мне нравишься. Давай дружить?',`text2_0_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Хочешь, чтобы мы тебе помогли? Чем тебе помочь? Мы хорошо помогаем.',`text3_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13375,'Хороший день для полета, не правда ли?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Хороший день для полета, не правда ли?',`text0_0_loc8`);
