INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13376,'Я узнаю аса с первого взгляда. Еще раз спасибо за спасение моей жизни!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я узнаю аса с первого взгляда. Еще раз спасибо за спасение моей жизни!',`text0_0_loc8`);
