INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13382,'Взгляни на свершенное, рыцарь смерти! Ты принес победу силам Плети!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Взгляни на свершенное, рыцарь смерти! Ты принес победу силам Плети!',`text0_0_loc8`);
