INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`,`text3_0_loc8`,`text4_0_loc8`) VALUES (13391,'Вам, силам Плети, не рады в Зул\'Драке!','Зул\'Драк принадлежит Драккари, $gбратишка:сестренка;. И так будет всегда!','Здесь Плеть и сгинет, ясно?','Наш народ убьет всех приспешников Плети до единого!','Уйди прочь, мерзкий приспешник Плети!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вам, силам Плети, не рады в Зул\'Драке!',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Зул\'Драк принадлежит Драккари, $gбратишка:сестренка;. И так будет всегда!',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Здесь Плеть и сгинет, ясно?',`text2_0_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Наш народ убьет всех приспешников Плети до единого!',`text3_0_loc8`), `text4_0_loc8`=IF(`text4_0_loc8` IS NULL OR `text4_0_loc8`='','Уйди прочь, мерзкий приспешник Плети!',`text4_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13395,'Может, сейчас в это трудно поверить, но чумной котел действительно станет источником заразы, чумы и порчи!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Может, сейчас в это трудно поверить, но чумной котел действительно станет источником заразы, чумы и порчи!',`text0_0_loc8`);
