INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13396,'Как ты смеешь! Убирайся прочь!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Как ты смеешь! Убирайся прочь!',`text0_0_loc8`);
