INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13397,'Чума овладеет Новым Авалоном – это всего лишь вопрос времени.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Чума овладеет Новым Авалоном – это всего лишь вопрос времени.',`text0_0_loc8`);
