INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13402,'Да, мой друг, у Финия есть то, что ты ищешь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да, мой друг, у Финия есть то, что ты ищешь.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13419,'Рыцари Алого ордена…$b$b<Ривендер качает головой.>$b$bОни не такие, как все прочие люди. У меня есть теория, что у них проблемы с высшей нервной деятельностью, поэтому они не в состоянии оценить ситуацию логически и просчитать последствия. Достаточно только упомянуть при них о Свете – и они уже готовы ринуться в бой. При этом в бой они бросаются очертя голову, без оглядки на собственную участь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Рыцари Алого ордена…$b$b<Ривендер качает головой.>$b$bОни не такие, как все прочие люди. У меня есть теория, что у них проблемы с высшей нервной деятельностью, поэтому они не в состоянии оценить ситуацию логически и просчитать последствия. Достаточно только упомянуть при них о Свете – и они уже готовы ринуться в бой. При этом в бой они бросаются очертя голову, без оглядки на собственную участь.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13422,'$n! Я ждал твоего возвращения. Что тебя так задержало, а?$b$bПора завершать обращение Гнилокровных.$b$bПрисоединись ко мне и стань свидетелем создания нашей армии!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','$n! Я ждал твоего возвращения. Что тебя так задержало, а?$b$bПора завершать обращение Гнилокровных.$b$bПрисоединись ко мне и стань свидетелем создания нашей армии!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13425,'Я тяжело ранен, но все же постараюсь помочь, чем сумею. Оставайся внутри моего антимагического барьера, а не то магия послушников растерзает тебя.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я тяжело ранен, но все же постараюсь помочь, чем сумею. Оставайся внутри моего антимагического барьера, а не то магия послушников растерзает тебя.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
