INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (13431,'Это, конечно, не то, на что я рассчитывала, но… По крайней мере, тут тепло.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Это, конечно, не то, на что я рассчитывала, но… По крайней мере, тут тепло.',`text0_1_loc8`);
