INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13438,'Когда-нибудь Реджек стать могучий воин.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Когда-нибудь Реджек стать могучий воин.',`text0_0_loc8`);
