INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (13441,'Приветствую тебя, |3-6($c). Полагаю, ты недавно $gпосетил:посетила; мероприятие Worldwide Invitational? В таком случае, тебе должны были сказать тайный код для получения подарка – Эфеса меча Тираэля.$B$BШепни мне его на ушко, когда захочешь получить свой сувенир.','Приветствую тебя, |3-6($c). Полагаю, ты недавно $gпосетил:посетила; мероприятие Worldwide Invitational? В таком случае, тебе должны были сказать тайный код для получения подарка – Эфеса меча Тираэля.$B$BШепни мне его на ушко, когда захочешь получить свой сувенир.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приветствую тебя, |3-6($c). Полагаю, ты недавно $gпосетил:посетила; мероприятие Worldwide Invitational? В таком случае, тебе должны были сказать тайный код для получения подарка – Эфеса меча Тираэля.$B$BШепни мне его на ушко, когда захочешь получить свой сувенир.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Приветствую тебя, |3-6($c). Полагаю, ты недавно $gпосетил:посетила; мероприятие Worldwide Invitational? В таком случае, тебе должны были сказать тайный код для получения подарка – Эфеса меча Тираэля.$B$BШепни мне его на ушко, когда захочешь получить свой сувенир.',`text0_1_loc8`);
