INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (13445,'Эти чудища убили моего отца и похитили мою сестру. Они за все заплатят!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Эти чудища убили моего отца и похитили мою сестру. Они за все заплатят!',`text0_1_loc8`);
