INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (13449,'Добро пожаловать на мою кухню! Здесь, в Даларане, мы готовим множество наивкуснейших блюд.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Добро пожаловать на мою кухню! Здесь, в Даларане, мы готовим множество наивкуснейших блюд.',`text0_1_loc8`);
