INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13451,'Надеюсь, ты донесешь это до длинноязыких в целости. Они как раз уходят.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Надеюсь, ты донесешь это до длинноязыких в целости. Они как раз уходят.',`text0_0_loc8`);
