INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13452,'В Заиндевелой гавани все еще идет большое сражение.$B$BМожет, у тебя иногда найдется время помочь там?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','В Заиндевелой гавани все еще идет большое сражение.$B$BМожет, у тебя иногда найдется время помочь там?',`text0_0_loc8`);
