INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13454,'Приветствую тебя, |3-6($c)! Порт Штормграда представляет собой впечатляющее зрелище. Особенно если смотреть сверху. Хотелось бы тебе увидеть порт с высоты птичьего полета?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приветствую тебя, |3-6($c)! Порт Штормграда представляет собой впечатляющее зрелище. Особенно если смотреть сверху. Хотелось бы тебе увидеть порт с высоты птичьего полета?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (13455,'Я не думаю, что твой разум способен полностью понять природу магии порталов.$B$BТем не менее ты можешь воспользоваться кристаллом, находящимся за мной, чтобы переместиться в руины под Далараном, что в лесу Хрустальной Песни.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я не думаю, что твой разум способен полностью понять природу магии порталов.$B$BТем не менее ты можешь воспользоваться кристаллом, находящимся за мной, чтобы переместиться в руины под Далараном, что в лесу Хрустальной Песни.',`text0_1_loc8`);
