INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13457,'У тебя есть время? Су-ни научит тебя хорошей песне!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','У тебя есть время? Су-ни научит тебя хорошей песне!',`text0_0_loc8`);
