INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13462,'Налей себе пинту!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Налей себе пинту!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (13467,'Третье кольцо обороняет хитроумный маг-лорд Уром. Он покажется одиноким и беззащитным, но не позволяйте себя обмануть! Уром – могущественный кудесник, командующий целым зверинцем иллюзорных созданий. Ищите его наверху!','Третье кольцо обороняет хитроумный маг-лорд Уром. Он покажется одиноким и беззащитным, но не позволяйте себя обмануть! Уром – могущественный кудесник, командующий целым зверинцем иллюзорных созданий. Ищите его наверху!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Третье кольцо обороняет хитроумный маг-лорд Уром. Он покажется одиноким и беззащитным, но не позволяйте себя обмануть! Уром – могущественный кудесник, командующий целым зверинцем иллюзорных созданий. Ищите его наверху!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Третье кольцо обороняет хитроумный маг-лорд Уром. Он покажется одиноким и беззащитным, но не позволяйте себя обмануть! Уром – могущественный кудесник, командующий целым зверинцем иллюзорных созданий. Ищите его наверху!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (13468,'Впереди ждет самое серьезное испытание. Хранитель энергии Эрегос – весьма могущественный синий дракон. Ты найдешь его наверху, он кружит над верхним ярусом.','Впереди ждет самое серьезное испытание. Хранитель энергии Эрегос – весьма могущественный синий дракон. Ты найдешь его наверху, он кружит над верхним ярусом.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Впереди ждет самое серьезное испытание. Хранитель энергии Эрегос – весьма могущественный синий дракон. Ты найдешь его наверху, он кружит над верхним ярусом.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Впереди ждет самое серьезное испытание. Хранитель энергии Эрегос – весьма могущественный синий дракон. Ты найдешь его наверху, он кружит над верхним ярусом.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (13475,'Ты точно этого хочешь?$B$BПосле того как я сотру знания из твоей памяти, ты их уже не вернешь.','Ты точно этого хочешь?$B$BПосле того как я сотру знания из твоей памяти, ты их уже не вернешь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты точно этого хочешь?$B$BПосле того как я сотру знания из твоей памяти, ты их уже не вернешь.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты точно этого хочешь?$B$BПосле того как я сотру знания из твоей памяти, ты их уже не вернешь.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (13476,'Отлично. Готово.','Отлично. Готово.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Отлично. Готово.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Отлично. Готово.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (13481,'Я никогда не забуду, что ты $gсделал:сделала; для Тассариана. Я навсегда у тебя в долгу.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я никогда не забуду, что ты $gсделал:сделала; для Тассариана. Я навсегда у тебя в долгу.',`text0_1_loc8`);
