INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13517,'Чем Корг может тебе помочь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Чем Корг может тебе помочь?',`text0_0_loc8`);
