INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13525,'Да, мы сокрушим Короля-лича. И наконец-то отомстим.$B$BНо сначала мы должны убедиться, что чума по имени Алый Натиск будет уничтожена раз и навсегда!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да, мы сокрушим Короля-лича. И наконец-то отомстим.$B$BНо сначала мы должны убедиться, что чума по имени Алый Натиск будет уничтожена раз и навсегда!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13531,'<Лорд-командир, смерив вас взглядом, награждает проницательной усмешкой.>$B$BВот это я и хотел от тебя услышать.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Лорд-командир, смерив вас взглядом, награждает проницательной усмешкой.>$B$BВот это я и хотел от тебя услышать.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (13534,'Подумай о всех страданиях, что причинил орден Алых за эти годы. Пытки, фанатичные изуверства, убийства.$B$BЯ не позволю этому продолжаться. Неужели же ты позволишь?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Подумай о всех страданиях, что причинил орден Алых за эти годы. Пытки, фанатичные изуверства, убийства.$B$BЯ не позволю этому продолжаться. Неужели же ты позволишь?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (13540,'Круг хильд священен. Кто бы ни победил, он проведет свою жизнь рядом с Торимом.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Круг хильд священен. Кто бы ни победил, он проведет свою жизнь рядом с Торимом.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (13557,'Здравствуй, |3-6($c)! Я могу предоставить стойло для твоих питомцев и помочь в розыске пропавших любимцев.','Здравствуй, |3-6($c)! Я могу предоставить стойло для твоих питомцев и помочь в розыске пропавших любимцев.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здравствуй, |3-6($c)! Я могу предоставить стойло для твоих питомцев и помочь в розыске пропавших любимцев.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Здравствуй, |3-6($c)! Я могу предоставить стойло для твоих питомцев и помочь в розыске пропавших любимцев.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text1_1_loc8`,`text3_1_loc8`) VALUES (13565,'Не смей задерживать меня, девчонка!$b$bСкоро предстоит сражение!','Ледоклык проявляет великую отвагу, отправляясь в бой без брони.$b$bВозможно, ее пример вселит немного мужества и в тебя, $n.') ON DUPLICATE KEY UPDATE `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Не смей задерживать меня, девчонка!$b$bСкоро предстоит сражение!',`text1_1_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','Ледоклык проявляет великую отвагу, отправляясь в бой без брони.$b$bВозможно, ее пример вселит немного мужества и в тебя, $n.',`text3_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (13572,'Эй, |3-6($c), если у тебя потерялся ключ – я могу помочь найти его!','Эй, |3-6($c), если у тебя потерялся ключ – я могу помочь найти его!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эй, |3-6($c), если у тебя потерялся ключ – я могу помочь найти его!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Эй, |3-6($c), если у тебя потерялся ключ – я могу помочь найти его!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13573,'Ты стоишь перед мастером тайного искусства. Было бы неразумно вызывать меня на поединок. За мной лежит путь, выстланный сгоревшими телами неосторожных.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты стоишь перед мастером тайного искусства. Было бы неразумно вызывать меня на поединок. За мной лежит путь, выстланный сгоревшими телами неосторожных.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (13574,'Жизнь моя и душа переполнены воспоминаниями о мерзостной Орде. Времена печали, отчаяния и жертв прошли. Сердце мое никогда не покинет ярость битвы!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Жизнь моя и душа переполнены воспоминаниями о мерзостной Орде. Времена печали, отчаяния и жертв прошли. Сердце мое никогда не покинет ярость битвы!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
