INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (13584,'Здравствуй, |3-6($c)! Я могу помочь тебе в розыске пропавших питомцев.','Здравствуй, |3-6($c)! Я могу помочь тебе в розыске пропавших питомцев.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здравствуй, |3-6($c)! Я могу помочь тебе в розыске пропавших питомцев.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Здравствуй, |3-6($c)! Я могу помочь тебе в розыске пропавших питомцев.',`text0_1_loc8`);
