INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (13591,'Привет! Хочешь купить рыболовных снастей или, быть может, услышать парочку мудрых советов?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Привет! Хочешь купить рыболовных снастей или, быть может, услышать парочку мудрых советов?',`text0_1_loc8`);
