INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13593,'Слишком долго я блуждал по всему Азероту в погоне за прошлым и тщетных попытках вернуть свой трон. Но, учитывая все те испытания, через которые пришлось пройти Альянсу в мое отсутствие, я не могу не гордиться подобными тебе героями, которые бесстрашно стоят на стороне нашего союза.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Слишком долго я блуждал по всему Азероту в погоне за прошлым и тщетных попытках вернуть свой трон. Но, учитывая все те испытания, через которые пришлось пройти Альянсу в мое отсутствие, я не могу не гордиться подобными тебе героями, которые бесстрашно стоят на стороне нашего союза.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13607,'Ты впустую тратишь мое время. Иди давай, убивай прихвостней Короля-лича, |3-6($c)!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты впустую тратишь мое время. Иди давай, убивай прихвостней Короля-лича, |3-6($c)!',`text0_0_loc8`);
