INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13608,'Как успехи в войне против Короля-лича, |3-6($c)?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Как успехи в войне против Короля-лича, |3-6($c)?',`text0_0_loc8`);
