INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13611,'<Разведчик Зиморожденных пытается подняться на ноги при вашем приближении, но падает обратно на землю, зажимая серьезную рану в боку.>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Разведчик Зиморожденных пытается подняться на ноги при вашем приближении, но падает обратно на землю, зажимая серьезную рану в боку.>',`text0_0_loc8`);
