INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13612,'Вряд ли, $Gдружище:подруга;. Я потерял слишком много крови… живым мне отсюда не выбраться.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вряд ли, $Gдружище:подруга;. Я потерял слишком много крови… живым мне отсюда не выбраться.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13613,'Стая гарпий поднялась из долины. Их вела одна большая, по имени Сирана… Мне было некуда бежать. Они давно не были столь агрессивны… Я не ожидал этого… Я не был готов к нападению… я сам виноват.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Стая гарпий поднялась из долины. Их вела одна большая, по имени Сирана… Мне было некуда бежать. Они давно не были столь агрессивны… Я не ожидал этого… Я не был готов к нападению… я сам виноват.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13614,'Уже поздно… дружище.$B$B<Разведчик из клана Зиморожденных кашляет кровью на снег.>$B$BСразись за меня… с этой дрянью…$B$B<Разведчик из клана Зиморожденных роняет голову на снег, делая свой последний вдох.>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Уже поздно… дружище.$B$B<Разведчик из клана Зиморожденных кашляет кровью на снег.>$B$BСразись за меня… с этой дрянью…$B$B<Разведчик из клана Зиморожденных роняет голову на снег, делая свой последний вдох.>',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13615,'Посмотри по сторонам и оцени разрушения, |3-6($c). Все до единого тролли, жившие здесь, или мертвы, или сбежали на верхние уровни.$B$BНо это еще не самое страшное.$B$BВ отчаянии, оставшиеся в живых драккари принесли в жертву своих собственных богов-животных, чтобы выпить их кровь и обрести невиданное доселе могущество. Хотя им удалось отогнать своей новообретенной силой воинов Плети, результаты оказались катастрофическими. В доказательство этого – древняя империя Зул\'Драк лежит в руинах.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Посмотри по сторонам и оцени разрушения, |3-6($c). Все до единого тролли, жившие здесь, или мертвы, или сбежали на верхние уровни.$B$BНо это еще не самое страшное.$B$BВ отчаянии, оставшиеся в живых драккари принесли в жертву своих собственных богов-животных, чтобы выпить их кровь и обрести невиданное доселе могущество. Хотя им удалось отогнать своей новообретенной силой воинов Плети, результаты оказались катастрофическими. В доказательство этого – древняя империя Зул\'Драк лежит в руинах.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13616,'Не попадайся на глаза, ладно? Я пытаюсь притворяться, что я все еще под контролем Короля-лича!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не попадайся на глаза, ладно? Я пытаюсь притворяться, что я все еще под контролем Короля-лича!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13619,'Герк, Бурр, Даргат – все они покинули нас… Здесь остались лишь Маккеллар и я. Надеюсь, ты с хорошими новостями.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Герк, Бурр, Даргат – все они покинули нас… Здесь остались лишь Маккеллар и я. Надеюсь, ты с хорошими новостями.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13628,'Пожалуйста, сохранять тишина! Малыши засыпать!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Пожалуйста, сохранять тишина! Малыши засыпать!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (13637,'Мы рады приветствовать тебя, |3-6($c).') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мы рады приветствовать тебя, |3-6($c).',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13639,'С моей свободой приходит отмщение шторма!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','С моей свободой приходит отмщение шторма!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13640,'Прежде чем мы начнем, послушай, что я знаю о нашем враге. Тебе лучше быть $gподготовленным:подготовленной;, когда мы будем громить Плеть в чистом поле.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Прежде чем мы начнем, послушай, что я знаю о нашем враге. Тебе лучше быть $gподготовленным:подготовленной;, когда мы будем громить Плеть в чистом поле.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13641,'<Бранн выжидающе смотрит на тебя.>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Бранн выжидающе смотрит на тебя.>',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13642,'Только подумай, какие знания и какая мудрость заперты внутри Ульдуара. Там могут быть даже самые сокровенные тайны жизни!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Только подумай, какие знания и какая мудрость заперты внутри Ульдуара. Там могут быть даже самые сокровенные тайны жизни!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13646,'Боктар считает, что это крушение было несчастным случаем, но лично я полагаю, что мы должны были извлечь из него какой-то урок.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Боктар считает, что это крушение было несчастным случаем, но лично я полагаю, что мы должны были извлечь из него какой-то урок.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (13650,'Яд… мои внутренности горят…','Яд… мои внутренности горят…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Яд… мои внутренности горят…',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Яд… мои внутренности горят…',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13656,'Когда будешь $gготов:готова; я посажу тебя к себе на голову, и мы пойдем в самую гущу Плети в Зул\'Драк. Тебе нужно будет направлять меня, чтобы я громил и уничтожал наших врагов!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Когда будешь $gготов:готова; я посажу тебя к себе на голову, и мы пойдем в самую гущу Плети в Зул\'Драк. Тебе нужно будет направлять меня, чтобы я громил и уничтожал наших врагов!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13658,'Мы влипли по уши, |3-6($r)! Будь осторожнее!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы влипли по уши, |3-6($r)! Будь осторожнее!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`,`text1_1_loc8`,`text2_1_loc8`,`text3_1_loc8`) VALUES (13660,'Я порву тебя в клочья.','Ты бросаешь мне вызов?','Ты не очень-то $gгрозен:грозная;.','Ты думаешь, у тебя хватит на это сил?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я порву тебя в клочья.',`text0_1_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Ты бросаешь мне вызов?',`text1_1_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Ты не очень-то $gгрозен:грозная;.',`text2_1_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','Ты думаешь, у тебя хватит на это сил?',`text3_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (13661,'Рада встрече, сестра по оружию. Я могу помочь тебе вернуть павших товарищей.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Рада встрече, сестра по оружию. Я могу помочь тебе вернуть павших товарищей.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (13663,'Сестра по оружию!$B$BЕшь, пей – и сражайся с новой силой!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Сестра по оружию!$B$BЕшь, пей – и сражайся с новой силой!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13671,'Если тебе больше нечем заняться, поубивай эти штуковины!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если тебе больше нечем заняться, поубивай эти штуковины!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13674,'Что ТЫ здесь делаешь?$B$BПо крайней мере постарайся не путаться под ногами. Я не позволю, чтобы Алый Натиск отвлекали такие типы, как ты.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что ТЫ здесь делаешь?$B$BПо крайней мере постарайся не путаться под ногами. Я не позволю, чтобы Алый Натиск отвлекали такие типы, как ты.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (13678,'Не мешай мне. Я наблюдаю за неумелыми попытками сражаться этих так называемых воинов.$B$BЯ с легкостью одержу победу над всеми ними, и тогда мне позволят служить самому Королю-личу.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Не мешай мне. Я наблюдаю за неумелыми попытками сражаться этих так называемых воинов.$B$BЯ с легкостью одержу победу над всеми ними, и тогда мне позволят служить самому Королю-личу.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13680,'Теперь ты чемпион, $gприятель:подруга;! Думаешь, у тебя есть все, что нужно, чтобы защитить твой титул?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Теперь ты чемпион, $gприятель:подруга;! Думаешь, у тебя есть все, что нужно, чтобы защитить твой титул?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13681,'Этот модуль занят. Пожалуйста, повторите свой запрос позднее.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Этот модуль занят. Пожалуйста, повторите свой запрос позднее.',`text0_0_loc8`);
