INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13682,'Вернись к работе, пока нас не заметил надсмотрщик.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вернись к работе, пока нас не заметил надсмотрщик.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13685,'Эта копия рога Ходира находится в мемориале, посвященном королю Арнгриму и всем остальным, погибшим в битве при Громовержье.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эта копия рога Ходира находится в мемориале, посвященном королю Арнгриму и всем остальным, погибшим в битве при Громовержье.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (13691,'Этот маленький зеленый щенок был полностью бесполезен в шахтах. Ну да неважно, по крайней мере, это станет прекрасной разминкой перед битвой.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Этот маленький зеленый щенок был полностью бесполезен в шахтах. Ну да неважно, по крайней мере, это станет прекрасной разминкой перед битвой.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (13694,'Ты $gпришел:пришла; сюда, чтобы доказать, что ты $gдостоин:достойна; служить Королю-личу?$B$BЭто немного старомодно, не находишь? То, что приходится сражаться и выживать?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты $gпришел:пришла; сюда, чтобы доказать, что ты $gдостоин:достойна; служить Королю-личу?$B$BЭто немного старомодно, не находишь? То, что приходится сражаться и выживать?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (13699,'Я больше не обучаю рыцарей смерти, меня утомили эти слабоумные новички и их постоянные вопросы.$B$BА теперь отвали.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я больше не обучаю рыцарей смерти, меня утомили эти слабоумные новички и их постоянные вопросы.$B$BА теперь отвали.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13701,'Ону\'зун пришел, чтобы вызвать на бой врайкула и утвердить себя в новом качестве.$B$BА потом, когда Ону\'зун будет сражаться в Валхаласе и победит, Ону\'зун станет служить Королю-личу!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ону\'зун пришел, чтобы вызвать на бой врайкула и утвердить себя в новом качестве.$B$BА потом, когда Ону\'зун будет сражаться в Валхаласе и победит, Ону\'зун станет служить Королю-личу!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13707,'Когда-то у меня было все. Слава, состояние, полный комплект лучших гладиаторских доспехов… – и все это я пустил на ветер!$b$bКак только картель поймал меня на договорных поединках… на подтасовке результатов… все пошло псу под хвост!$b$bУ меня не осталось ничего, только вот эти тряпки, да загубленная печень.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Когда-то у меня было все. Слава, состояние, полный комплект лучших гладиаторских доспехов… – и все это я пустил на ветер!$b$bКак только картель поймал меня на договорных поединках… на подтасовке результатов… все пошло псу под хвост!$b$bУ меня не осталось ничего, только вот эти тряпки, да загубленная печень.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13709,'Ты кто?$b$bУбирайся прочь… Я уже на ногах не стою, целый день впахивал на Гаванской дороге. Пора выпить дворфийского эля – и на боковую.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты кто?$b$bУбирайся прочь… Я уже на ногах не стою, целый день впахивал на Гаванской дороге. Пора выпить дворфийского эля – и на боковую.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (13715,'Когда-то у меня был дом в густых лесах Кель\'Таласа. Когда-то у меня была семья, муж… дети. Когда-то я была единым целым с этим миром, живая. Король-лич забрал все это в мгновение ока.$B$BХотя у меня нет возможности нанести ему прямой удар, я отплачу ему за это сторицей!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Когда-то у меня был дом в густых лесах Кель\'Таласа. Когда-то у меня была семья, муж… дети. Когда-то я была единым целым с этим миром, живая. Король-лич забрал все это в мгновение ока.$B$BХотя у меня нет возможности нанести ему прямой удар, я отплачу ему за это сторицей!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13731,'Какое потрясающее открытие! Королевское фармацептическое общество потратило годы на то, чтобы открыть секреты чумы Короля-лича, а я поставил точку в этих исследованиях! $B$BДа, друг мой, это поворотный момент в истории всего мира – несмотря на то, что нам еще многое предстоит узнать. Столько экспериментов надо провести, собрать так много образцов... $B$BНо, во всяком случае, мы можем больше не волноваться по поводу некрополисов – с ними разберется Альянс. Теперь у меня будет гораздо больше времени для работы над чумой и ее тайнами...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Какое потрясающее открытие! Королевское фармацептическое общество потратило годы на то, чтобы открыть секреты чумы Короля-лича, а я поставил точку в этих исследованиях! $B$BДа, друг мой, это поворотный момент в истории всего мира – несмотря на то, что нам еще многое предстоит узнать. Столько экспериментов надо провести, собрать так много образцов... $B$BНо, во всяком случае, мы можем больше не волноваться по поводу некрополисов – с ними разберется Альянс. Теперь у меня будет гораздо больше времени для работы над чумой и ее тайнами...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13733,'Где Зиморожденные, там и орлы. Они были нашими союзниками с тех времен, когда я еще не бродил по этой земле… а я не так уж и юн, $Gпарнишка:девчушка;.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Где Зиморожденные, там и орлы. Они были нашими союзниками с тех времен, когда я еще не бродил по этой земле… а я не так уж и юн, $Gпарнишка:девчушка;.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13734,'Чем могу служить?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Чем могу служить?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13735,'Ну че, как дела?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ну че, как дела?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13737,'Чем могу помочь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Чем могу помочь?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13740,'Мы рады приветствовать тебя – друга и союзника земельников.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы рады приветствовать тебя – друга и союзника земельников.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13748,'Я недостаточно тебе доверяю, чтобы разговаривать о таких вещах.$b$bТы $gдолжен:должна; уважать те испытания, через которые пришлось пройти нашему народу, ту ношу, что нам пришлось вынести…$b$bВозможно, если бы ты $gсделал:сделала; нечто великое для Дун Ниффелема, я бы согласился поделиться с тобой знаниями моего народа.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я недостаточно тебе доверяю, чтобы разговаривать о таких вещах.$b$bТы $gдолжен:должна; уважать те испытания, через которые пришлось пройти нашему народу, ту ношу, что нам пришлось вынести…$b$bВозможно, если бы ты $gсделал:сделала; нечто великое для Дун Ниффелема, я бы согласился поделиться с тобой знаниями моего народа.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13749,'Очень хорошо, кроха-|3-6($c).$b$bХотя тебе предстоит еще многое свершить, чтобы улучшить наши отношения с Торимом, я обязан поделиться с тобой одним секретом.$b$bОбратись ко мне снова, когда будешь $gготов:готова; увидеть то, что ты ищешь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Очень хорошо, кроха-|3-6($c).$b$bХотя тебе предстоит еще многое свершить, чтобы улучшить наши отношения с Торимом, я обязан поделиться с тобой одним секретом.$b$bОбратись ко мне снова, когда будешь $gготов:готова; увидеть то, что ты ищешь.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (13759,'Привет тебе, |3-6($r)! Чем могу помочь?','Привет тебе, |3-6($r)! Чем могу помочь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Привет тебе, |3-6($r)! Чем могу помочь?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Привет тебе, |3-6($r)! Чем могу помочь?',`text0_1_loc8`);
