INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (13761,'Извини, друг. Утвердить приобретение машины могут только офицеры Орды, имеющие соответствующие документы.','Извини, друг. Утвердить приобретение машины могут только офицеры Орды, имеющие соответствующие документы.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Извини, друг. Утвердить приобретение машины могут только офицеры Орды, имеющие соответствующие документы.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Извини, друг. Утвердить приобретение машины могут только офицеры Орды, имеющие соответствующие документы.',`text0_1_loc8`);
