INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13764,'Рад вновь приветствовать тебя!$B$BКороль Грозовое Сердце сообщил мне, что удаляется на некоторое время… печальные воспоминания, вернувшиеся к нему, похоже, принесли с собой счеты, которые нужно свести. Он был очень настойчив, когда просил оставить его одного, поэтому мы, как обычно, уважили его желание.$B$BА пока ответственность за наш клан несу я. Мы, конечно же, по-прежнему рады видеть тебя.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Рад вновь приветствовать тебя!$B$BКороль Грозовое Сердце сообщил мне, что удаляется на некоторое время… печальные воспоминания, вернувшиеся к нему, похоже, принесли с собой счеты, которые нужно свести. Он был очень настойчив, когда просил оставить его одного, поэтому мы, как обычно, уважили его желание.$B$BА пока ответственность за наш клан несу я. Мы, конечно же, по-прежнему рады видеть тебя.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13776,'Ты не таунка. Зачем ты $gпришел:пришла; на священную землю наших павших воинов?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты не таунка. Зачем ты $gпришел:пришла; на священную землю наших павших воинов?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13782,'Оставь меня наедине с моим стыдом, |3-6($r).') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Оставь меня наедине с моим стыдом, |3-6($r).',`text0_0_loc8`);
