INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (13783,'Ох уж эти мужчины… И с ними жить нельзя, и без них тоже нельзя. Нет, можно, конечно – но это так скучно!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ох уж эти мужчины… И с ними жить нельзя, и без них тоже нельзя. Нет, можно, конечно – но это так скучно!',`text0_1_loc8`);
