INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (13784,'Эти рудники – поистине страшное место. По счастью, я не собираюсь оставаться здесь надолго.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Эти рудники – поистине страшное место. По счастью, я не собираюсь оставаться здесь надолго.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (13785,'Медведи – прекрасные существа. Дикие, сильные, яростные в битве – они похожи на нас, сестра.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Медведи – прекрасные существа. Дикие, сильные, яростные в битве – они похожи на нас, сестра.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (13786,'Извини, друг. Боюсь, мы уже пустили в ход все детали, что могли.','Извини, друг. Боюсь, мы уже пустили в ход все детали, что могли.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Извини, друг. Боюсь, мы уже пустили в ход все детали, что могли.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Извини, друг. Боюсь, мы уже пустили в ход все детали, что могли.',`text0_1_loc8`);
