INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (13788,'Меня кто-то звал?..') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Меня кто-то звал?..',`text0_1_loc8`);
