INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13790,'Здрасьте, здрасьте!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здрасьте, здрасьте!',`text0_0_loc8`);
