INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (13792,'Привет, ягодка моя, как хорошо, что ты здесь!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Привет, ягодка моя, как хорошо, что ты здесь!',`text0_1_loc8`);
