INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13793,'Рад встрече, |3-6($c).') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Рад встрече, |3-6($c).',`text0_0_loc8`);
