INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13797,'Мы обнаружили этих протодраконов у бронзового святилища драконов, что на Драконьем Погосте. Мы тотчас же поняли, что это наши братья – наша кровь из далекого прошлого.$B$BПриношу свои извинения, |3-6($c). Я, должно быть, сбил тебя с толку. Я – Пенумбриус из бронзовых драконов. Я принял эту форму для удобства. Гораздо проще общаться и жить среди смертных, когда ты выглядишь так же, как и они.$B$BЧем я могу тебе помочь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы обнаружили этих протодраконов у бронзового святилища драконов, что на Драконьем Погосте. Мы тотчас же поняли, что это наши братья – наша кровь из далекого прошлого.$B$BПриношу свои извинения, |3-6($c). Я, должно быть, сбил тебя с толку. Я – Пенумбриус из бронзовых драконов. Я принял эту форму для удобства. Гораздо проще общаться и жить среди смертных, когда ты выглядишь так же, как и они.$B$BЧем я могу тебе помочь?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (13798,'Привет тебе, $n! Чем могу помочь?','Привет тебе, $n! Чем могу помочь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Привет тебе, $n! Чем могу помочь?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Привет тебе, $n! Чем могу помочь?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13799,'Говори, |3-6($c).') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Говори, |3-6($c).',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13800,'Я достаточно долго скрывался от своей судьбы. Теперь совершенно очевидно, что следует делать.$b$bЛокен должен пасть от моей руки!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я достаточно долго скрывался от своей судьбы. Теперь совершенно очевидно, что следует делать.$b$bЛокен должен пасть от моей руки!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13801,'На какое-то мгновение мне показалось, что ты – это моя возлюбленная Сиф… эта прядь волос… но нет! Этого не может быть… Сиф мертва… мой брат… убил ее!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','На какое-то мгновение мне показалось, что ты – это моя возлюбленная Сиф… эта прядь волос… но нет! Этого не может быть… Сиф мертва… мой брат… убил ее!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13802,'Ульдуар… Я поклялся защищать Ульдуар.$B$BПоклялся защищать Террасу Творцов.$B$BПоклялся защищать соглашение, заключенное между расами холода.$B$BНо я не сделал этого! Я позволил моему брату обмануть меня. Я позволил ему обратить меня против моих союзников. Он обманул меня, обвиняя в смерти Сиф моего дорогого друга, Арнгрима, короля снежных великанов.$B$BКогда я понял, что я натворил… Я… впал в отчаяние.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ульдуар… Я поклялся защищать Ульдуар.$B$BПоклялся защищать Террасу Творцов.$B$BПоклялся защищать соглашение, заключенное между расами холода.$B$BНо я не сделал этого! Я позволил моему брату обмануть меня. Я позволил ему обратить меня против моих союзников. Он обманул меня, обвиняя в смерти Сиф моего дорогого друга, Арнгрима, короля снежных великанов.$B$BКогда я понял, что я натворил… Я… впал в отчаяние.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13803,'Кто ты $gтакой:такая;, $gмаленький:маленькая;? Чтобы приходить и говорить такие слова могучему Ториму…$B$BМне следует… убить тебя!$B$BНо ты $gвывел:вывела; меня из оцепенения. Твое присутствие здесь – это знак!$B$BНе случайно я принял тебя за Сиф. Что бы она обо мне подумала? Я должен подготовиться к битве.$B$BЯ должен отомстить за ее смерть и освободить священные земли титанов от безумия моего брата!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Кто ты $gтакой:такая;, $gмаленький:маленькая;? Чтобы приходить и говорить такие слова могучему Ториму…$B$BМне следует… убить тебя!$B$BНо ты $gвывел:вывела; меня из оцепенения. Твое присутствие здесь – это знак!$B$BНе случайно я принял тебя за Сиф. Что бы она обо мне подумала? Я должен подготовиться к битве.$B$BЯ должен отомстить за ее смерть и освободить священные земли титанов от безумия моего брата!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
