INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (13832,'Ты слишком $gслаб:слаба;, чтобы сражаться на Береге Древних. Возвращайся, когда наберешься опыта.','Ты слишком $gслаб:слаба;, чтобы сражаться на Береге Древних. Возвращайся, когда наберешься опыта.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты слишком $gслаб:слаба;, чтобы сражаться на Береге Древних. Возвращайся, когда наберешься опыта.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты слишком $gслаб:слаба;, чтобы сражаться на Береге Древних. Возвращайся, когда наберешься опыта.',`text0_1_loc8`);
