INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (13833,'Нельзя допустить, чтобы Орда узнала тайны Берега древних и обратила их против нас. Ты поможешь нашим храбрым воинам дать отпор захватчикам?','Нельзя допустить, чтобы Орда узнала тайны Берега древних и обратила их против нас. Ты поможешь нашим храбрым воинам дать отпор захватчикам?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Нельзя допустить, чтобы Орда узнала тайны Берега древних и обратила их против нас. Ты поможешь нашим храбрым воинам дать отпор захватчикам?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Нельзя допустить, чтобы Орда узнала тайны Берега древних и обратила их против нас. Ты поможешь нашим храбрым воинам дать отпор захватчикам?',`text0_1_loc8`);
