INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (13843,'Мы служим Ториму, сестра.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мы служим Ториму, сестра.',`text0_1_loc8`);
