INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (13844,'Всегда приятно встречать таких героев, как ты, на этой забытой земле. Я могу тебе чем-нибудь помочь?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Всегда приятно встречать таких героев, как ты, на этой забытой земле. Я могу тебе чем-нибудь помочь?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (13845,'Приветствую тебя, маг. Могу я продолжить твое посвящение в мир магии?','Приветствую тебя, маг. Могу я продолжить твое посвящение в мир магии?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приветствую тебя, маг. Могу я продолжить твое посвящение в мир магии?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Приветствую тебя, маг. Могу я продолжить твое посвящение в мир магии?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13848,'Да, это скорбный день в истории троллей.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да, это скорбный день в истории троллей.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (13850,'Моей обязанностью будет записать эти трагические события ради блага будущих поколений.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Моей обязанностью будет записать эти трагические события ради блага будущих поколений.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (13853,'Наконец-то подкрепление! Стражи больше не могут сдерживать этот натиск! Вам нужно будет сменить моих воинов и попытаться продержаться как можно дольше. Вот кристаллы контроля, активирующие автоматическую охрану тюрьмы, но их нельзя использовать слишком много раз. У меня есть кристаллы для всей вашей группы, обязательно возьмите их у меня.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Наконец-то подкрепление! Стражи больше не могут сдерживать этот натиск! Вам нужно будет сменить моих воинов и попытаться продержаться как можно дольше. Вот кристаллы контроля, активирующие автоматическую охрану тюрьмы, но их нельзя использовать слишком много раз. У меня есть кристаллы для всей вашей группы, обязательно возьмите их у меня.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (13854,'Ну что, все готовы продолжать? Я приведу в действие этот кристалл, чтобы прикрыть отступление моих стражей.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ну что, все готовы продолжать? Я приведу в действие этот кристалл, чтобы прикрыть отступление моих стражей.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13856,'То, что я теперь делаю для Серебряного Авангарда, может быть рассмотрено в качестве выполнения обязательств. Платы, если тебе угодно. Верховный лорд освободил меня из-под власти Короля-лича и открыл пред всеми нами путь к жизни вечной. Говоря это, я подразумеваю, что наши методы разнятся – и очень сильно. Я и остальные рыцари Черного Клинка помогут Серебряному Авангарду обосноваться в Ледяной Короне, и тогда наши пути разойдутся. Мы расплатимся полностью.$B$BДругая судьба ждет нас.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','То, что я теперь делаю для Серебряного Авангарда, может быть рассмотрено в качестве выполнения обязательств. Платы, если тебе угодно. Верховный лорд освободил меня из-под власти Короля-лича и открыл пред всеми нами путь к жизни вечной. Говоря это, я подразумеваю, что наши методы разнятся – и очень сильно. Я и остальные рыцари Черного Клинка помогут Серебряному Авангарду обосноваться в Ледяной Короне, и тогда наши пути разойдутся. Мы расплатимся полностью.$B$BДругая судьба ждет нас.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13871,'Врайкул мирно отдыхает, погруженный в магический сон.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Врайкул мирно отдыхает, погруженный в магический сон.',`text0_0_loc8`);
