INSERT INTO `locales_npc_text` (`id`,`text1_0_loc8`,`text2_0_loc8`) VALUES (13873,'Аррр! Кому-то придется задать хорошую трепку этим уродам!$B$B<ик!>','Пришло время надрать пару задниц и выпить двойного рома!$B$BА двойного рома почти что и не осталось…') ON DUPLICATE KEY UPDATE `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Аррр! Кому-то придется задать хорошую трепку этим уродам!$B$B<ик!>',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Пришло время надрать пару задниц и выпить двойного рома!$B$BА двойного рома почти что и не осталось…',`text2_0_loc8`);
