INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13896,'Взятие Вершины Рыцарей – лишь первый шаг в долгом и опасном путешествии. Нам еще многое предстоит сделать, прежде чем мы сможем подступиться к цитадели Ледяной Короны.$b$bБез твоей помощи и помощи других героев, подобных тебе, нам не справиться.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Взятие Вершины Рыцарей – лишь первый шаг в долгом и опасном путешествии. Нам еще многое предстоит сделать, прежде чем мы сможем подступиться к цитадели Ледяной Короны.$b$bБез твоей помощи и помощи других героев, подобных тебе, нам не справиться.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
