INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13906,'Кроваво-красный омут внутри глаза клубится, открывая образы огромной армии Плети. Глаз как будто бы начинает тянуться к вам, пробивая себе путь к вашему разуму и заставляя вас инстинктивно отпрянуть. В присутствии этого объекта вам крайне неуютно.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Кроваво-красный омут внутри глаза клубится, открывая образы огромной армии Плети. Глаз как будто бы начинает тянуться к вам, пробивая себе путь к вашему разуму и заставляя вас инстинктивно отпрянуть. В присутствии этого объекта вам крайне неуютно.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (13908,'О чем бы ты ни $gхотел:хотела; попросить, проси скорее.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','О чем бы ты ни $gхотел:хотела; попросить, проси скорее.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (13910,'Теперь мы займемся этим. После такого боя ты, несомненно, заслуживаешь отдыха.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Теперь мы займемся этим. После такого боя ты, несомненно, заслуживаешь отдыха.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (13919,'Мне следовало бы убить тебя на месте, |3-6($r)!$b$bВыкладывай то, что собираешься сказать, и убирайся прочь!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мне следовало бы убить тебя на месте, |3-6($r)!$b$bВыкладывай то, что собираешься сказать, и убирайся прочь!',`text0_0_loc8`);
