INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (13931,'Собирали… информацию… о Плети.$B$BПоявились силы Альянса…$B$BМы затаились – ждали, пока они атакуют ворота… а потом ударили по ним с тыла.$B$BЗажатые между нами… и Плетью… они не выдержали…$B$B$gБраток:Сестричка;… Это было… славное дельце.','Собирали… информацию… о Плети.$B$BПоявились силы Альянса…$B$BМы затаились – ждали, пока они атакуют ворота… а потом ударили по ним с тыла.$B$BЗажатые между нами… и Плетью… они не выдержали…$B$BОх, $gбратик:сестричка;… Это было… славное дельце.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Собирали… информацию… о Плети.$B$BПоявились силы Альянса…$B$BМы затаились – ждали, пока они атакуют ворота… а потом ударили по ним с тыла.$B$BЗажатые между нами… и Плетью… они не выдержали…$B$B$gБраток:Сестричка;… Это было… славное дельце.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Собирали… информацию… о Плети.$B$BПоявились силы Альянса…$B$BМы затаились – ждали, пока они атакуют ворота… а потом ударили по ним с тыла.$B$BЗажатые между нами… и Плетью… они не выдержали…$B$BОх, $gбратик:сестричка;… Это было… славное дельце.',`text0_1_loc8`);
