INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (13947,'Мы атаковали под прикрытием сильной вьюги…$B$BПлеть мы застали врасплох… это была верная победа…$B$BА потом… сзади… словно ниоткуда, появились воины Орды.$B$BЭто стоило нам… всего…','Мы атаковали под прикрытием сильной вьюги…$B$BПлеть мы застали врасплох… это была верная победа…$B$BА потом… сзади… словно ниоткуда, появились воины Орды.$B$BЭто стоило нам… всего…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы атаковали под прикрытием сильной вьюги…$B$BПлеть мы застали врасплох… это была верная победа…$B$BА потом… сзади… словно ниоткуда, появились воины Орды.$B$BЭто стоило нам… всего…',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мы атаковали под прикрытием сильной вьюги…$B$BПлеть мы застали врасплох… это была верная победа…$B$BА потом… сзади… словно ниоткуда, появились воины Орды.$B$BЭто стоило нам… всего…',`text0_1_loc8`);
