INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (13980,'Торговая палата волшебников расположена в северо-западной части Даларана, там находится большинство обитающих в городе наставников профессиональных навыков.','Торговая палата волшебников расположена в северо-западной части Даларана, там находится большинство обитающих в городе наставников профессиональных навыков.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Торговая палата волшебников расположена в северо-западной части Даларана, там находится большинство обитающих в городе наставников профессиональных навыков.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Торговая палата волшебников расположена в северо-западной части Даларана, там находится большинство обитающих в городе наставников профессиональных навыков.',`text0_1_loc8`);
