INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (13983,'Учителей горного дела и торговцев сопутствующими товарами можно найти в офисе сортировочной компании "Все, что блестит", расположенном в Торговой палате волшебников в северо-западной части Даларана.','Учителей горного дела и торговцев сопутствующими товарами можно найти в офисе сортировочной компании "Все, что блестит", расположенном в Торговой палате волшебников в северо-западной части Даларана.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Учителей горного дела и торговцев сопутствующими товарами можно найти в офисе сортировочной компании "Все, что блестит", расположенном в Торговой палате волшебников в северо-западной части Даларана.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Учителей горного дела и торговцев сопутствующими товарами можно найти в офисе сортировочной компании "Все, что блестит", расположенном в Торговой палате волшебников в северо-западной части Даларана.',`text0_1_loc8`);
