INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (13984,'Ювелирные изделия от "Картье и Ко." можно купить в Торговой палате волшебников в северо-западной части Даларана.','Ювелирные изделия от "Картье и Ко." можно купить в Торговой палате волшебников в северо-западной части Даларана.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ювелирные изделия от "Картье и Ко." можно купить в Торговой палате волшебников в северо-западной части Даларана.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ювелирные изделия от "Картье и Ко." можно купить в Торговой палате волшебников в северо-западной части Даларана.',`text0_1_loc8`);
