INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (13986,'К "Аптеке агронома", что в Торговой палате волшебников в северо-западной части Даларана, пристроена оранжерея. Там трудятся лучшие травники в городе.','К "Аптеке агронома", что в Торговой палате волшебников в северо-западной части Даларана, пристроена оранжерея. Там трудятся лучшие травники в городе.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','К "Аптеке агронома", что в Торговой палате волшебников в северо-западной части Даларана, пристроена оранжерея. Там трудятся лучшие травники в городе.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','К "Аптеке агронома", что в Торговой палате волшебников в северо-западной части Даларана, пристроена оранжерея. Там трудятся лучшие травники в городе.',`text0_1_loc8`);
