INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (13990,'Ты, без сомнения, захочешь посетить магазин "Чарующая простота", который находится совсем рядом с Торговой палатой волшебников в северо-западной части Даларана.','Ты, без сомнения, захочешь посетить магазин "Чарующая простота", который находится совсем рядом с Торговой палате волшебников в северо-западной части Даларана.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты, без сомнения, захочешь посетить магазин "Чарующая простота", который находится совсем рядом с Торговой палатой волшебников в северо-западной части Даларана.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты, без сомнения, захочешь посетить магазин "Чарующая простота", который находится совсем рядом с Торговой палате волшебников в северо-западной части Даларана.',`text0_1_loc8`);
