INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (13991,'Учителя, обучающие кулинарному искусству, ждут тебя на кухнях при тавернах Альянса и Орды, находящихся в соответствующих кварталах.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Учителя, обучающие кулинарному искусству, ждут тебя на кухнях при тавернах Альянса и Орды, находящихся в соответствующих кварталах.',`text0_1_loc8`);
