INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (13993,'Ага, ты ищешь заведение "Грязное животное". Это в ордынском квартале под названием "Прибежище Похитителя Солнца" в северо-восточной части города.$B$BМне говорили, что нравы в этом местечке довольно дикие, но зато на кухне работает настоящий гуру кулинарного искусства!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ага, ты ищешь заведение "Грязное животное". Это в ордынском квартале под названием "Прибежище Похитителя Солнца" в северо-восточной части города.$B$BМне говорили, что нравы в этом местечке довольно дикие, но зато на кухне работает настоящий гуру кулинарного искусства!',`text0_1_loc8`);
