INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (13995,'"Аптеку агронома", расположенную в Торговой палате волшебников в северо-западной части Даларана, легко узнать по двери в форме флакона. Пропустить ее просто невозможно!','"Аптеку агронома", расположенную в Торговой палате волшебников в северо-западной части Даларана, легко узнать по двери в форме флакона. Пропустить ее просто невозможно!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','"Аптеку агронома", расположенную в Торговой палате волшебников в северо-западной части Даларана, легко узнать по двери в форме флакона. Пропустить ее просто невозможно!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','"Аптеку агронома", расположенную в Торговой палате волшебников в северо-западной части Даларана, легко узнать по двери в форме флакона. Пропустить ее просто невозможно!',`text0_1_loc8`);
