INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14007,'В городе три банка: банк на севере, торговый банк на юге, и еще один внизу, в Стоках.','В городе три банка: банк на севере, торговый банк на юге, и еще один внизу, в Стоках.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','В городе три банка: банк на севере, торговый банк на юге, и еще один внизу, в Стоках.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','В городе три банка: банк на севере, торговый банк на юге, и еще один внизу, в Стоках.',`text0_1_loc8`);
