INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14022,'Там, к северу от таверны "Ведьма и ворон", что в западной части Стоков, есть гоблинский банк.','Там, к северу от таверны "Ведьма и ворон", что в западной части Стоков, есть гоблинский банк.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Там, к северу от таверны "Ведьма и ворон", что в западной части Стоков, есть гоблинский банк.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Там, к северу от таверны "Ведьма и ворон", что в западной части Стоков, есть гоблинский банк.',`text0_1_loc8`);
