INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14023,'Картель Хитрой Шестеренки заведует ареной в центральных Стоках Даларана.$b$bТам же, в Круге Воли, ты найдешь дуэльные круги.','Картель Хитрой Шестеренки заведует ареной в центральных Стоках Даларана.$b$bТам же, в Круге Воли, ты найдешь дуэльные круги.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Картель Хитрой Шестеренки заведует ареной в центральных Стоках Даларана.$b$bТам же, в Круге Воли, ты найдешь дуэльные круги.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Картель Хитрой Шестеренки заведует ареной в центральных Стоках Даларана.$b$bТам же, в Круге Воли, ты найдешь дуэльные круги.',`text0_1_loc8`);
