INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14024,'В восточной части Стоков есть скат, который выходит наверх неподалеку от площадки Краса.','В восточной части Стоков есть скат, который выходит наверх неподалеку от площадки Краса.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','В восточной части Стоков есть скат, который выходит наверх неподалеку от площадки Краса.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','В восточной части Стоков есть скат, который выходит наверх неподалеку от площадки Краса.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14025,'В западной части Стоков есть скат, который выходит наверх неподалеку от Аметистовой цитадели.','В западной части Стоков есть скат, который выходит наверх неподалеку от Аметистовой цитадели.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','В западной части Стоков есть скат, который выходит наверх неподалеку от Аметистовой цитадели.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','В западной части Стоков есть скат, который выходит наверх неподалеку от Аметистовой цитадели.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14026,'Выбраться из Клоаки можно тремя путями: по Скатам, которые находятся на западе и на востоке, и по туннелю, который ведет вниз, ко дну Даларана.$b$bОднако пользоваться этим туннелем имеет смысл, только если вы умеете летать.','Выбраться из Клоаки можно тремя путями: по Скатам, которые находятся на западе и на востоке, и по туннелю, который ведет вниз, ко дну Даларана.$b$bОднако пользоваться этим туннелем имеет смысл, только если вы умеете летать.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Выбраться из Клоаки можно тремя путями: по Скатам, которые находятся на западе и на востоке, и по туннелю, который ведет вниз, ко дну Даларана.$b$bОднако пользоваться этим туннелем имеет смысл, только если вы умеете летать.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Выбраться из Клоаки можно тремя путями: по Скатам, которые находятся на западе и на востоке, и по туннелю, который ведет вниз, ко дну Даларана.$b$bОднако пользоваться этим туннелем имеет смысл, только если вы умеете летать.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14027,'Добро пожаловать в Клоаку! Могу я тебе помочь? Что ты ищешь?','Добро пожаловать в Клоаку! Могу я тебе помочь? Что ты ищешь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать в Клоаку! Могу я тебе помочь? Что ты ищешь?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Добро пожаловать в Клоаку! Могу я тебе помочь? Что ты ищешь?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14033,'Наши обычаи священны. Мы скорее умрем, чем оставим Торима и присоединимся к таким, как Король-лич!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Наши обычаи священны. Мы скорее умрем, чем оставим Торима и присоединимся к таким, как Король-лич!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14034,'Слишком долго терпел я своего брата. Пришла пора расставить все по местам. Пора уничтожить его и его приверженцев.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Слишком долго терпел я своего брата. Пришла пора расставить все по местам. Пора уничтожить его и его приверженцев.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text1_0_loc8`,`text1_1_loc8`,`text4_0_loc8`,`text4_1_loc8`,`text5_0_loc8`,`text5_1_loc8`) VALUES (14035,'Не раздумывай, |3-6($c).$b$bПросто… просто сделай это!','Не раздумывай, |3-6($c).$b$bПросто… просто сделай это!','Сделай это, |3-6($c). И… и отомсти за меня!','Сделай это, |3-6($c). И… и отомсти за меня!','Прошу тебя, |3-6($r)… Не оставляй никого, кого Плеть могла бы воскресить!','Прошу тебя, |3-6($r)… Не оставляй никого, кого Плеть могла бы воскресить!') ON DUPLICATE KEY UPDATE `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Не раздумывай, |3-6($c).$b$bПросто… просто сделай это!',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Не раздумывай, |3-6($c).$b$bПросто… просто сделай это!',`text1_1_loc8`), `text4_0_loc8`=IF(`text4_0_loc8` IS NULL OR `text4_0_loc8`='','Сделай это, |3-6($c). И… и отомсти за меня!',`text4_0_loc8`), `text4_1_loc8`=IF(`text4_1_loc8` IS NULL OR `text4_1_loc8`='','Сделай это, |3-6($c). И… и отомсти за меня!',`text4_1_loc8`), `text5_0_loc8`=IF(`text5_0_loc8` IS NULL OR `text5_0_loc8`='','Прошу тебя, |3-6($r)… Не оставляй никого, кого Плеть могла бы воскресить!',`text5_0_loc8`), `text5_1_loc8`=IF(`text5_1_loc8` IS NULL OR `text5_1_loc8`='','Прошу тебя, |3-6($r)… Не оставляй никого, кого Плеть могла бы воскресить!',`text5_1_loc8`);
