INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14037,'Просто поверить не могу, что Культ был столь беспечен, что оставил их у себя за спиной!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Просто поверить не могу, что Культ был столь беспечен, что оставил их у себя за спиной!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14038,'Главная слабость Артаса – это его гордыня. И эта слабость растет вместе с его силой. Черный Клинок получит шанс нанести удар бывшему принцу – в этом я не сомневаюсь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Главная слабость Артаса – это его гордыня. И эта слабость растет вместе с его силой. Черный Клинок получит шанс нанести удар бывшему принцу – в этом я не сомневаюсь.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14041,'Чем я могу тебе помочь?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Чем я могу тебе помочь?',`text0_1_loc8`);
