INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14055,'Нас ждет нелегкий путь. Если ты $gуверен:уверена; в своих силах, держись поблизости, пока один из моих отрядов не соберется подниматься в Имирхейм. Им понадобится любая помощь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Нас ждет нелегкий путь. Если ты $gуверен:уверена; в своих силах, держись поблизости, пока один из моих отрядов не соберется подниматься в Имирхейм. Им понадобится любая помощь.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14056,'На "Неустрашимом" каким-то образом оказалось полным полно поломок, и мы не можем отправиться в Нордскол.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','На "Неустрашимом" каким-то образом оказалось полным полно поломок, и мы не можем отправиться в Нордскол.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14061,'Ну и морда у тебя! Все враги разбегутся – и драться не придется.$B$BОдин из моих отрядов вот-вот будет снаряжен и готов к выступлению. Хорош штаны просиживать – вставай в строй и выдвигайся с ними!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ну и морда у тебя! Все враги разбегутся – и драться не придется.$B$BОдин из моих отрядов вот-вот будет снаряжен и готов к выступлению. Хорош штаны просиживать – вставай в строй и выдвигайся с ними!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14063,'Я могу указать тебе путь, $gюноша:девушка;?','Я могу указать тебе путь, $gюноша:девушка;?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я могу указать тебе путь, $gюноша:девушка;?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я могу указать тебе путь, $gюноша:девушка;?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`) VALUES (14064,'От того, какие действия мы тут предпримем, зависят многие жизни. Так что живее выкладывай, |3-6($c), что там у тебя.','Какие новости с полей сражений, |3-6($r)?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','От того, какие действия мы тут предпримем, зависят многие жизни. Так что живее выкладывай, |3-6($c), что там у тебя.',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Какие новости с полей сражений, |3-6($r)?',`text1_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14065,'Этот портал ведет в Пещеры Времени, расположенные глубоко под землей в далеком Танарисе.$b$bВ моей власти отправить тебя туда, если ты этого захочешь.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Этот портал ведет в Пещеры Времени, расположенные глубоко под землей в далеком Танарисе.$b$bВ моей власти отправить тебя туда, если ты этого захочешь.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14066,'Этот портал ведет в Пещеры Времени, расположенные глубоко под землей в далеком Танарисе.$b$bОднако я вынуждена просить тебя не отправляться туда, пока ты не станешь сильнее, чем ныне.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Этот портал ведет в Пещеры Времени, расположенные глубоко под землей в далеком Танарисе.$b$bОднако я вынуждена просить тебя не отправляться туда, пока ты не станешь сильнее, чем ныне.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14067,'Я чую запах пороха, это все бомбы и ракеты! Хочешь отправиться туда и присоединиться к веселью?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я чую запах пороха, это все бомбы и ракеты! Хочешь отправиться туда и присоединиться к веселью?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`,`text3_0_loc8`,`text4_0_loc8`,`text5_0_loc8`,`text6_0_loc8`,`text7_0_loc8`) VALUES (14068,'Голоса говорят со мной.','Я должен повиноваться.','Тебе нужно выбираться отсюда, пока оно и до тебя не добралось!','Это вокруг нас. Это у меня в голове!','Саронит… в этом материале что-то есть!','Здесь что-то есть. В камнях, в самой земле!','Мне нужно выбраться отсюда! Можешь освободить меня?','Ты слышишь, как оно разговаривает у тебя в голове?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Голоса говорят со мной.',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Я должен повиноваться.',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Тебе нужно выбираться отсюда, пока оно и до тебя не добралось!',`text2_0_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Это вокруг нас. Это у меня в голове!',`text3_0_loc8`), `text4_0_loc8`=IF(`text4_0_loc8` IS NULL OR `text4_0_loc8`='','Саронит… в этом материале что-то есть!',`text4_0_loc8`), `text5_0_loc8`=IF(`text5_0_loc8` IS NULL OR `text5_0_loc8`='','Здесь что-то есть. В камнях, в самой земле!',`text5_0_loc8`), `text6_0_loc8`=IF(`text6_0_loc8` IS NULL OR `text6_0_loc8`='','Мне нужно выбраться отсюда! Можешь освободить меня?',`text6_0_loc8`), `text7_0_loc8`=IF(`text7_0_loc8` IS NULL OR `text7_0_loc8`='','Ты слышишь, как оно разговаривает у тебя в голове?',`text7_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14069,'Мы пока в процессе подготовки. В течение некоторого времени мы еще не сможем выступать.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы пока в процессе подготовки. В течение некоторого времени мы еще не сможем выступать.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14070,'Мы почти готовы к отбытию. Дайте нам еще немного времени, чтобы закончить все приготовления.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы почти готовы к отбытию. Дайте нам еще немного времени, чтобы закончить все приготовления.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14071,'Мои парни готовы. Пустим немного врайкульской крови!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мои парни готовы. Пустим немного врайкульской крови!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14072,'В своих путешествиях я изучил выкройку тончайшего плаща.$B$BЭто эпический плащ для заклинателей, повышающий выносливость, силу заклинаний, интеллект и восполняющий ману. Притом этот плащ годится для торговли или обмена. Я ищу кого-нибудь достойного, кого я мог бы обучить шитью этого плаща.$B$BГерой, прошедший все подземелья Нордскола в нормальном режиме и достигший звания "Повелитель подземелий Нордскола", достоин того, чтобы изучить выкройку тончайшего плаща.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','В своих путешествиях я изучил выкройку тончайшего плаща.$B$BЭто эпический плащ для заклинателей, повышающий выносливость, силу заклинаний, интеллект и восполняющий ману. Притом этот плащ годится для торговли или обмена. Я ищу кого-нибудь достойного, кого я мог бы обучить шитью этого плаща.$B$BГерой, прошедший все подземелья Нордскола в нормальном режиме и достигший звания "Повелитель подземелий Нордскола", достоин того, чтобы изучить выкройку тончайшего плаща.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14074,'В разных темных местах побывал я и научился шить мертвенно-хладный плащ.$B$BЭтот эпический плащ для заклинателей увеличивает силу заклинаний, скорость их прочтения и вероятность нанесения критического урона. Я ищу достойного преемника, которого я мог бы обучить шитью этого плаща.$B$BТот, кто выполнил большинство заданий по всему Нордсколу и достиг звания "Хранитель мудрости Нордскола", будет самым подходящим кандидатом для того, чтобы научиться выкройке мертвенно-хладного плаща.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','В разных темных местах побывал я и научился шить мертвенно-хладный плащ.$B$BЭтот эпический плащ для заклинателей увеличивает силу заклинаний, скорость их прочтения и вероятность нанесения критического урона. Я ищу достойного преемника, которого я мог бы обучить шитью этого плаща.$B$BТот, кто выполнил большинство заданий по всему Нордсколу и достиг звания "Хранитель мудрости Нордскола", будет самым подходящим кандидатом для того, чтобы научиться выкройке мертвенно-хладного плаща.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14076,'Поскольку ты $gсведущ:сведуща; в портняжном деле, могу тебе сказать, что мне известны кое-какие особые выкройки. Например тончайшего плаща и плаща смертельной стужи.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Поскольку ты $gсведущ:сведуща; в портняжном деле, могу тебе сказать, что мне известны кое-какие особые выкройки. Например тончайшего плаща и плаща смертельной стужи.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14077,'Эй, ты! Иди сюда! Пируй, пей, отдыхай перед следующей битвой!$b$bНо не вздумай сражаться! Иначе я скормлю тебя своим волкам.','Эй, ты! Иди сюда! Пируй, пей, отдыхай перед следующей битвой!$b$bНо не вздумай сражаться! Иначе я скормлю тебя своим волкам.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эй, ты! Иди сюда! Пируй, пей, отдыхай перед следующей битвой!$b$bНо не вздумай сражаться! Иначе я скормлю тебя своим волкам.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Эй, ты! Иди сюда! Пируй, пей, отдыхай перед следующей битвой!$b$bНо не вздумай сражаться! Иначе я скормлю тебя своим волкам.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14082,'Добро пожаловать в "Чудо чудное"!$B$BПожалуйста, не спешите и с чувством, с толком, с расстановкой походите по нашему магазину, посмотрите на великолепные игрушки для детей и взрослых!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать в "Чудо чудное"!$B$BПожалуйста, не спешите и с чувством, с толком, с расстановкой походите по нашему магазину, посмотрите на великолепные игрушки для детей и взрослых!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14087,'Привет, $gдружище:подруга;. Чем могу помочь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Привет, $gдружище:подруга;. Чем могу помочь?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14088,'Эй, эй, погоди секундочку! Гляжу, у тебя нет собственного летающего скакуна!$B$BВ таком случае ты вряд ли пригодишься местным гоблинам. Кстати, они платят мне за то, что я сдаю напрокат моих собственных верховых животных – практически за бесценок.$B$BНе желаешь воспользоваться моими услугами?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эй, эй, погоди секундочку! Гляжу, у тебя нет собственного летающего скакуна!$B$BВ таком случае ты вряд ли пригодишься местным гоблинам. Кстати, они платят мне за то, что я сдаю напрокат моих собственных верховых животных – практически за бесценок.$B$BНе желаешь воспользоваться моими услугами?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`,`text1_1_loc8`,`text2_1_loc8`) VALUES (14090,'Когда дело доходит до сокровищ, не стесняйся забирать чужое добро. Украденный плод всегда слаще, а бесплатный сыр – всегда бесплатный, каким бы путем он тебе не достался.','Я это называю "скидка трех пальцев". В воровстве самое главное – твои руки… а если они подведут – то всегда выручит ножик под бок, зажатый в той же самой руке.$B$BУмелые ручки стоят дороже золота, запомни хорошенько.','А на этого Короля-лича мне вообще плевать. Большие шишки приходят и уходят, да всегда что-то такое мутят между собой. А потом фортуна крутит колесо – и все, они уходят в историю. Этому царьку тоже не убежать от судьбы.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Когда дело доходит до сокровищ, не стесняйся забирать чужое добро. Украденный плод всегда слаще, а бесплатный сыр – всегда бесплатный, каким бы путем он тебе не достался.',`text0_1_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Я это называю "скидка трех пальцев". В воровстве самое главное – твои руки… а если они подведут – то всегда выручит ножик под бок, зажатый в той же самой руке.$B$BУмелые ручки стоят дороже золота, запомни хорошенько.',`text1_1_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','А на этого Короля-лича мне вообще плевать. Большие шишки приходят и уходят, да всегда что-то такое мутят между собой. А потом фортуна крутит колесо – и все, они уходят в историю. Этому царьку тоже не убежать от судьбы.',`text2_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14095,'Ты найдешь то, что ищешь, в лавке "Еще по сто" в северной части Даларана.','Ты найдешь то, что ищешь, в лавке "Еще по сто" в северной части Даларана.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты найдешь то, что ищешь, в лавке "Еще по сто" в северной части Даларана.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты найдешь то, что ищешь, в лавке "Еще по сто" в северной части Даларана.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14096,'В "Воинствующем мистике" в южной части Даларана вам предложат все, что вашей душе угодно.','В "Воинствующем мистике" в южной части Даларана вам предложат все, что вашей душе угодно.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','В "Воинствующем мистике" в южной части Даларана вам предложат все, что вашей душе угодно.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','В "Воинствующем мистике" в южной части Даларана вам предложат все, что вашей душе угодно.',`text0_1_loc8`);
