INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14097,'"Охотничий прицел" в восточной части Даларана предлагает всем желающим ружья, луки, амуницию и прочее.','"Охотничий прицел" в восточной части Даларана предлагает всем желающим ружья, луки, амуницию и прочее.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','"Охотничий прицел" в восточной части Даларана предлагает всем желающим ружья, луки, амуницию и прочее.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','"Охотничий прицел" в восточной части Даларана предлагает всем желающим ружья, луки, амуницию и прочее.',`text0_1_loc8`);
