INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14098,'В "Полном арсенале", что в юго-восточной части Даларана, продаются все виды оружия ближнего боя.','В "Полном арсенале", что в юго-восточной части Даларана, продаются все виды оружия ближнего боя.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','В "Полном арсенале", что в юго-восточной части Даларана, продаются все виды оружия ближнего боя.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','В "Полном арсенале", что в юго-восточной части Даларана, продаются все виды оружия ближнего боя.',`text0_1_loc8`);
