INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14100,'"Чудо чудное" Джепетто Таратора в западной части Даларана торгует подобным товаром.','"Чудо чудное" Джепетто Таратора в западной части Даларана торгует подобным товаром.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','"Чудо чудное" Джепетто Таратора в западной части Даларана торгует подобным товаром.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','"Чудо чудное" Джепетто Таратора в западной части Даларана торгует подобным товаром.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14101,'Рэд из "Великолепных товаров", что в юго-восточной части Даларана, предлагает на ваш выбор разнообразные хозяйственные припасы.$B$BЕсли вам понадобится нечто более узкоспециализированное, загляните в Торговую палату волшебников. В любом из здешних магазинов имеется в наличии широчайший ассортимент товаров.','Рэд из "Великолепных товаров", что в юго-восточной части Даларана, предлагает на ваш выбор разнообразные хозяйственные припасы.$B$BЕсли вам понадобится нечто более узкоспециализированное, загляните в Торговую палату волшебников. В любом из здешних магазинов имеется в наличии широчайший ассортимент товаров.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Рэд из "Великолепных товаров", что в юго-восточной части Даларана, предлагает на ваш выбор разнообразные хозяйственные припасы.$B$BЕсли вам понадобится нечто более узкоспециализированное, загляните в Торговую палату волшебников. В любом из здешних магазинов имеется в наличии широчайший ассортимент товаров.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Рэд из "Великолепных товаров", что в юго-восточной части Даларана, предлагает на ваш выбор разнообразные хозяйственные припасы.$B$BЕсли вам понадобится нечто более узкоспециализированное, загляните в Торговую палату волшебников. В любом из здешних магазинов имеется в наличии широчайший ассортимент товаров.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14102,'Тележку Айми обычно можно встретить в северной части Даларана, неподалеку от даларанского банка.','Тележку Айми обычно можно встретить в северной части Даларана, неподалеку от даларанского банка.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тележку Айми обычно можно встретить в северной части Даларана, неподалеку от даларанского банка.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Тележку Айми обычно можно встретить в северной части Даларана, неподалеку от даларанского банка.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14103,'"Волшебный зверинец" находится в северо-восточной части Даларана. Товары для ваших любимцев, экзотические верховые животных, а также комфортабельные стойла для них – все ради вашего удовольствия!','"Волшебный зверинец" находится в северо-восточной части Даларана. Товары для ваших любимцев, экзотические верховые животных, а также комфортабельные стойла для них – все ради вашего удовольствия!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','"Волшебный зверинец" находится в северо-восточной части Даларана. Товары для ваших любимцев, экзотические верховые животных, а также комфортабельные стойла для них – все ради вашего удовольствия!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','"Волшебный зверинец" находится в северо-восточной части Даларана. Товары для ваших любимцев, экзотические верховые животных, а также комфортабельные стойла для них – все ради вашего удовольствия!',`text0_1_loc8`);
