INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14104,'Если тебе нужны реагенты и тому подобные товары, отправляйся в "Ведовские сестрички", что в западной части Даларана.$B$BТолько смотри, остерегайся черного кота семейки Мурхед!..','Если тебе нужны реагенты и тому подобные товары, отправляйся в "Ведовские сестрички", что в западной части Даларана.$B$BТолько смотри, остерегайся черного кота семейки Мурхед!..') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если тебе нужны реагенты и тому подобные товары, отправляйся в "Ведовские сестрички", что в западной части Даларана.$B$BТолько смотри, остерегайся черного кота семейки Мурхед!..',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Если тебе нужны реагенты и тому подобные товары, отправляйся в "Ведовские сестрички", что в западной части Даларана.$B$BТолько смотри, остерегайся черного кота семейки Мурхед!..',`text0_1_loc8`);
