INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14105,'В "Великолепных товарах" в южной части Даларана тебе продадут любые потребительские товары.','В "Великолепных товарах" в южной части Даларана тебе продадут любые потребительские товары.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','В "Великолепных товарах" в южной части Даларана тебе продадут любые потребительские товары.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','В "Великолепных товарах" в южной части Даларана тебе продадут любые потребительские товары.',`text0_1_loc8`);
