INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14106,'Яблочкина вместе с его тележкой с фруктами часто можно встретить в юго-западной части Даларана, неподалеку от Серебряного Анклава.','Яблочкина вместе с его тележкой с фруктами часто можно встретить в юго-западной части Даларана, неподалеку от Серебряного Анклава.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Яблочкина вместе с его тележкой с фруктами часто можно встретить в юго-западной части Даларана, неподалеку от Серебряного Анклава.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Яблочкина вместе с его тележкой с фруктами часто можно встретить в юго-западной части Даларана, неподалеку от Серебряного Анклава.',`text0_1_loc8`);
