INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14118,'Тайные знания гоблинской инженерии ничего не рассказывают о том, что же можно сделать, чтобы вещи прекратили взрываться. Но зато в них сказано, как сделать так, чтоб они взрывались именно тогда, когда вам это нужно.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тайные знания гоблинской инженерии ничего не рассказывают о том, что же можно сделать, чтобы вещи прекратили взрываться. Но зато в них сказано, как сделать так, чтоб они взрывались именно тогда, когда вам это нужно.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`) VALUES (14119,'Я – Ксанатавр Свидетель.','Хочешь услышать мою историю?','Тебе есть, что рассказать?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я – Ксанатавр Свидетель.',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Хочешь услышать мою историю?',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Тебе есть, что рассказать?',`text2_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14120,'Я был одним из первых тауренов-друидов, из последнего поколения, успевшего пройти уроки самого Шан\'до Кенария, еще до Легиона, еще до Раскола, когда мир был еще молод. До того, как все изменилось.$B$BКогда мои братья охотились на огромных зверей, я охотился за историями. И этот голод, эта жажда знания открыли для меня культуру друидов. На время этот голод насытился, когда я учился бродить среди деревьев, гор и животных, и слушал их истории.$B$BНо потом пришло время, когда Кенарий покинул нас, и мои братья стали забывать то, чему он нас учил. Я же не мог забыть, да и мне все еще нужно было узнать очень многое о нашем мире.$B$BИ я попрощался с моим народом и отправился далеко за пределы наших земель.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я был одним из первых тауренов-друидов, из последнего поколения, успевшего пройти уроки самого Шан\'до Кенария, еще до Легиона, еще до Раскола, когда мир был еще молод. До того, как все изменилось.$B$BКогда мои братья охотились на огромных зверей, я охотился за историями. И этот голод, эта жажда знания открыли для меня культуру друидов. На время этот голод насытился, когда я учился бродить среди деревьев, гор и животных, и слушал их истории.$B$BНо потом пришло время, когда Кенарий покинул нас, и мои братья стали забывать то, чему он нас учил. Я же не мог забыть, да и мне все еще нужно было узнать очень многое о нашем мире.$B$BИ я попрощался с моим народом и отправился далеко за пределы наших земель.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14121,'Я странствовал весь остаток жизни в поисках знания, встречая такие странные и загадочные расы, которые никто из моего народа никогда не видывал. Я исходил вдоль и поперек весь древний Калимдор до тех пор, пока ни осталось ни одной пяди неизведанной земли на горизонте.$B$BИ все же... слишком многого я еще не знал, когда уже почувствовал приближение моего последнего путешествия, и я оплакивал те невероятные вещи, кои мне не суждено было узнать.$B$BЯ пал духом, жизнь моя подходила к концу, и тогда они нашли меня.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я странствовал весь остаток жизни в поисках знания, встречая такие странные и загадочные расы, которые никто из моего народа никогда не видывал. Я исходил вдоль и поперек весь древний Калимдор до тех пор, пока ни осталось ни одной пяди неизведанной земли на горизонте.$B$BИ все же... слишком многого я еще не знал, когда уже почувствовал приближение моего последнего путешествия, и я оплакивал те невероятные вещи, кои мне не суждено было узнать.$B$BЯ пал духом, жизнь моя подходила к концу, и тогда они нашли меня.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14122,'Бронзовые драконы. Они вытащили меня с края, за которым была смерть, и привели меня к своему повелителю, Ноздорму. Он сказал, что они наблюдали за мной и хотят, чтобы я продолжил свою охоту. Он подарил мне бессмертие, бессмертие свидетеля, наблюдающего со стороны за историей Азерота в качестве одного из его помощников.$B$BЯ – Ксанатавр Свидетель, и в мои обязанности входит сохранение истинной истории Азерота, чтобы она никогда не была забыта.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Бронзовые драконы. Они вытащили меня с края, за которым была смерть, и привели меня к своему повелителю, Ноздорму. Он сказал, что они наблюдали за мной и хотят, чтобы я продолжил свою охоту. Он подарил мне бессмертие, бессмертие свидетеля, наблюдающего со стороны за историей Азерота в качестве одного из его помощников.$B$BЯ – Ксанатавр Свидетель, и в мои обязанности входит сохранение истинной истории Азерота, чтобы она никогда не была забыта.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14123,'Время покажет...') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Время покажет...',`text0_1_loc8`);
