INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14131,'Мы должны избежать еще одной войны с Ордой любой ценой!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мы должны избежать еще одной войны с Ордой любой ценой!',`text0_1_loc8`);
