INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14137,'Мы уже потеряли несколько хороших воинов. Я начинаю сомневаться в том, что это место стоит нашего внимания.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мы уже потеряли несколько хороших воинов. Я начинаю сомневаться в том, что это место стоит нашего внимания.',`text0_1_loc8`);
