INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14177,'Разве она не прекрасна? Видишь, как забрезжила потенциальная выгода?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Разве она не прекрасна? Видишь, как забрезжила потенциальная выгода?',`text0_0_loc8`);
