INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14213,'Эта огромная, сверкающая магическая книга помогает создавать символы заклинаний и способностей. Она всегда находится рядом с учителем начертания в районе Фармацевтов.','Эта огромная, сверкающая магическая книга помогает создавать символы заклинаний и способностей. Она всегда находится рядом с учителем начертания в районе Фармацевтов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эта огромная, сверкающая магическая книга помогает создавать символы заклинаний и способностей. Она всегда находится рядом с учителем начертания в районе Фармацевтов.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Эта огромная, сверкающая магическая книга помогает создавать символы заклинаний и способностей. Она всегда находится рядом с учителем начертания в районе Фармацевтов.',`text0_1_loc8`);
