INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14215,'Быстрее, |3-6($r)! Я устала, и у нас нет времени на реверансы.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Быстрее, |3-6($r)! Я устала, и у нас нет времени на реверансы.',`text0_1_loc8`);
