INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14218,'Вот ты где!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вот ты где!',`text0_0_loc8`);
