INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14221,'Лок\'тар! Ты желаешь послужить Орде на поле битвы?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Лок\'тар! Ты желаешь послужить Орде на поле битвы?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14227,'Ох уж этот Сад чудес. Как забавно наблюдать за тем, как окружающие жертвуют собственным достоинством ради поиска крашеных яиц. Правда, эти штуки действительно обладают любопытной магической аурой...','Ох уж этот Сад чудес. Как забавно наблюдать за тем, как окружающие жертвуют собственным достоинством ради поиска крашеных яиц. Правда, эти штуки действительно обладают любопытной магической аурой...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ох уж этот Сад чудес. Как забавно наблюдать за тем, как окружающие жертвуют собственным достоинством ради поиска крашеных яиц. Правда, эти штуки действительно обладают любопытной магической аурой...',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ох уж этот Сад чудес. Как забавно наблюдать за тем, как окружающие жертвуют собственным достоинством ради поиска крашеных яиц. Правда, эти штуки действительно обладают любопытной магической аурой...',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14228,'И снова пришел в наши края праздник Сада чудес! Так возблагодарим же Свет за чудо возрождения мира.','И снова пришел в наши края праздник Сада чудес! Так возблагодарим же Свет за чудо возрождения мира.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','И снова пришел в наши края праздник Сада чудес! Так возблагодарим же Свет за чудо возрождения мира.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','И снова пришел в наши края праздник Сада чудес! Так возблагодарим же Свет за чудо возрождения мира.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14229,'Леденец! Вот, о чем я говорил! Как же долго я за ним гонялся...','Леденец! Вот, о чем я говорила! Как же долго я за ним гонялась...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Леденец! Вот, о чем я говорил! Как же долго я за ним гонялся...',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Леденец! Вот, о чем я говорила! Как же долго я за ним гонялась...',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14231,'Нет, если кто-то хочет ползать по грязи в поисках крашеных яиц – кто я, чтобы осуждать подобные поступки? Лучше я сколочу состояние на продаже краски и разведении куриц-несушек.','Нет, если кто-то хочет ползать по грязи в поисках крашеных яиц – кто я, чтобы осуждать подобные поступки? Лучше я сколочу состояние на продаже краски и разведении куриц-несушек.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Нет, если кто-то хочет ползать по грязи в поисках крашеных яиц – кто я, чтобы осуждать подобные поступки? Лучше я сколочу состояние на продаже краски и разведении куриц-несушек.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Нет, если кто-то хочет ползать по грязи в поисках крашеных яиц – кто я, чтобы осуждать подобные поступки? Лучше я сколочу состояние на продаже краски и разведении куриц-несушек.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14232,'Настал праздник Сада чудес! Я уже нашел целую кучу яиц! В такую погоду легко отыскать еще больше, не так ли?','Настал праздник Сада чудес! Я уже нашел целую кучу яиц! В такую погоду легко отыскать еще больше, не так ли?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Настал праздник Сада чудес! Я уже нашел целую кучу яиц! В такую погоду легко отыскать еще больше, не так ли?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Настал праздник Сада чудес! Я уже нашел целую кучу яиц! В такую погоду легко отыскать еще больше, не так ли?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14233,'Сад чудес – это время, когда друиды Азерота восхваляют возрождение жизни. Яйца символизируют плодородие и к тому же приносят праздничное настроение всем окружающим. Не так ли?','Сад чудес – это время, когда друиды Азерота восхваляют возрождение жизни. Яйца символизируют плодородие и к тому же приносят праздничное настроение всем окружающим. Не так ли?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Сад чудес – это время, когда друиды Азерота восхваляют возрождение жизни. Яйца символизируют плодородие и к тому же приносят праздничное настроение всем окружающим. Не так ли?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Сад чудес – это время, когда друиды Азерота восхваляют возрождение жизни. Яйца символизируют плодородие и к тому же приносят праздничное настроение всем окружающим. Не так ли?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14234,'Во время праздника Сада чудес мы славим приход весны, возрождение жизни и все такое.','Во время праздника Сада чудес мы славим приход весны, возрождение жизни и все такое.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Во время праздника Сада чудес мы славим приход весны, возрождение жизни и все такое.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Во время праздника Сада чудес мы славим приход весны, возрождение жизни и все такое.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14235,'Настало время восславить возрождение жизни. Эти яйца символизируют отступление зимы и пробуждение всего живого. Наслаждайся весной!','Настало время восславить возрождение жизни. Эти яйца символизируют отступление зимы и пробуждение всего живого. Наслаждайся весной!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Настало время восславить возрождение жизни. Эти яйца символизируют отступление зимы и пробуждение всего живого. Наслаждайся весной!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Настало время восславить возрождение жизни. Эти яйца символизируют отступление зимы и пробуждение всего живого. Наслаждайся весной!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14236,'Ага, $gдружище:подруга;, настала пора радоваться жизни и весне. Много яиц $gнашел:нашла;?','Ага, $gдружище:подруга;, настала пора радоваться жизни и весне. Много яиц $gнашел:нашла;?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ага, $gдружище:подруга;, настала пора радоваться жизни и весне. Много яиц $gнашел:нашла;?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ага, $gдружище:подруга;, настала пора радоваться жизни и весне. Много яиц $gнашел:нашла;?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14237,'Весь этот праздник – сплошная чепуха. Крашеные яйца, "возрождение жизни"... какой бред!','Весь этот праздник – сплошная чепуха. Крашеные яйца, "возрождение жизни"... какой бред!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Весь этот праздник – сплошная чепуха. Крашеные яйца, "возрождение жизни"... какой бред!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Весь этот праздник – сплошная чепуха. Крашеные яйца, "возрождение жизни"... какой бред!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14238,'Приветствую тебя, друг! Ты $gпришел:пришла;, чтобы помочь в бою детям Азерота?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приветствую тебя, друг! Ты $gпришел:пришла;, чтобы помочь в бою детям Азерота?',`text0_0_loc8`);
