INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14240,'Приветствую тебя, |3-6($c).$B$BКогда Крепость Ледяных Оков будет находиться под контролем Альянса, я смогу открыть портал для всех, кто хочет туда попасть.$B$BБитва уже началась. Поспеши в Ледяные Оковы и помоги нашим силам!','Приветствую тебя, |3-6($c).$B$BКогда Крепость Ледяных Оков будет находиться под контролем Альянса, я смогу открыть портал для всех, кто хочет туда попасть.$B$BБитва уже началась. Поспеши в Ледяные Оковы и помоги нашим силам!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приветствую тебя, |3-6($c).$B$BКогда Крепость Ледяных Оков будет находиться под контролем Альянса, я смогу открыть портал для всех, кто хочет туда попасть.$B$BБитва уже началась. Поспеши в Ледяные Оковы и помоги нашим силам!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Приветствую тебя, |3-6($c).$B$BКогда Крепость Ледяных Оков будет находиться под контролем Альянса, я смогу открыть портал для всех, кто хочет туда попасть.$B$BБитва уже началась. Поспеши в Ледяные Оковы и помоги нашим силам!',`text0_1_loc8`);
