INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14249,'Потом тебе надо будет найти Беника Резьбореза. Он находится в центре Квартала Дворфов, возле кузнецов.','Потом тебе надо будет найти Беника Резьбореза. Он находится в центре Квартала Дворфов, возле кузнецов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Потом тебе надо будет найти Беника Резьбореза. Он находится в центре Квартала Дворфов, возле кузнецов.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Потом тебе надо будет найти Беника Резьбореза. Он находится в центре Квартала Дворфов, возле кузнецов.',`text0_1_loc8`);
