INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14250,'Он есть Уолтер Сореф. Работать в Район Разбойников. Делать ключи.','Он есть Уолтер Сореф. Работать в Район Разбойников. Делать ключи.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Он есть Уолтер Сореф. Работать в Район Разбойников. Делать ключи.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Он есть Уолтер Сореф. Работать в Район Разбойников. Делать ключи.',`text0_1_loc8`);
