INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14251,'Если ты ищешь замочника, то рекомендую тебе отправиться в Стоки. Там проходу нет от сомнительных типов.','Если ты ищешь замочника, то рекомендую тебе отправиться в Стоки. Там проходу нет от сомнительных типов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если ты ищешь замочника, то рекомендую тебе отправиться в Стоки. Там проходу нет от сомнительных типов.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Если ты ищешь замочника, то рекомендую тебе отправиться в Стоки. Там проходу нет от сомнительных типов.',`text0_1_loc8`);
