INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (14254,'Гиппогрифы Весприста быстро домчат тебя до места назначения.','Гиппогрифы Весприста быстро домчат тебя до места назначения.','Тебе нужен Вестприст. Он следит за гиппогрифами, которые прилетают к подножию Тельдрассила.','Тебе нужен Вестприст. Он следит за гиппогрифами, которые прилетают к подножию Тельдрассила.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Гиппогрифы Весприста быстро домчат тебя до места назначения.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Гиппогрифы Весприста быстро домчат тебя до места назначения.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Тебе нужен Вестприст. Он следит за гиппогрифами, которые прилетают к подножию Тельдрассила.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Тебе нужен Вестприст. Он следит за гиппогрифами, которые прилетают к подножию Тельдрассила.',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14259,'Наш дом был уничтожен во время Катаклизма.$B$BБольшинство выживших направились на север, чтобы отстроить Лор\'данел, но у нас была причина остаться в этих краях. Мы намереваемся залечить раны и отвоевать руины Аубердина у этих мерзавцев из культа Сумеречного Молота.$B$BЯ надеюсь, что ты тоже присоединишься к нашей борьбе.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Наш дом был уничтожен во время Катаклизма.$B$BБольшинство выживших направились на север, чтобы отстроить Лор\'данел, но у нас была причина остаться в этих краях. Мы намереваемся залечить раны и отвоевать руины Аубердина у этих мерзавцев из культа Сумеречного Молота.$B$BЯ надеюсь, что ты тоже присоединишься к нашей борьбе.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14260,'Я летел на юг в Дарнас, чтобы разыскать там Малфуриона Ярость Бури, но не смог пройти мимо этих несчастных аубердинских беженцев.$B$BОни сражались за правое дело и пострадали в этой битве, поэтому я предложил им свои услуги целителя. $B$BНадеюсь, ты тоже поможешь им по мере сил.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я летел на юг в Дарнас, чтобы разыскать там Малфуриона Ярость Бури, но не смог пройти мимо этих несчастных аубердинских беженцев.$B$BОни сражались за правое дело и пострадали в этой битве, поэтому я предложил им свои услуги целителя. $B$BНадеюсь, ты тоже поможешь им по мере сил.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14261,'Много лет назад я погибла при попытке разобраться с мурлоками, но не смогла завершить свой жизненный путь в объятиях богини, поскольку слишком беспокоилась за родных и близких.$B$BТеперь, когда все они исчезли или погибли, только одно удерживает мою душу на этой земле: месть.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Много лет назад я погибла при попытке разобраться с мурлоками, но не смогла завершить свой жизненный путь в объятиях богини, поскольку слишком беспокоилась за родных и близких.$B$BТеперь, когда все они исчезли или погибли, только одно удерживает мою душу на этой земле: месть.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
