INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14266,'Северный леопард лежит неподвижно.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Северный леопард лежит неподвижно.',`text0_0_loc8`);
