INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14267,'Ледолапый медведь лежит неподвижно.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ледолапый медведь лежит неподвижно.',`text0_0_loc8`);
