INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14271,'Что ты здесь делаешь? Ты $gдолжен:должна; находиться внутри и сражаться с синими драконами!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Что ты здесь делаешь? Ты $gдолжен:должна; находиться внутри и сражаться с синими драконами!',`text0_1_loc8`);
