INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14272,'Знаю, знаю… "Удить рыбу в сточных водах?!" Но ты ведь и не подозреваешь, что тут можно выловить. Слыхал я и истории об акулах, да ты все равно не поверишь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Знаю, знаю… "Удить рыбу в сточных водах?!" Но ты ведь и не подозреваешь, что тут можно выловить. Слыхал я и истории об акулах, да ты все равно не поверишь.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14274,'Здесь лежит тело часового, павшей жертвой элементалей, захвативших город.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Здесь лежит тело часового, павшей жертвой элементалей, захвативших город.',`text0_1_loc8`);
