INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14276,'Трудно представить, кто мог одержать верх над Кайлайис и ее гиппогрифами, но это явно были не элементали.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Трудно представить, кто мог одержать верх над Кайлайис и ее гиппогрифами, но это явно были не элементали.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14281,'Я сужу встречных не по внешности, |3-6($r), а по их отваге и преданности.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я сужу встречных не по внешности, |3-6($r), а по их отваге и преданности.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14284,'Недурно мы вляпались. Уже слишком поздно присоединяться к нашим войскам в Ледяной Короне, и мы застряли между Плетью и Драккари.$B$BЯ говорил верховному лорду, что не стоит идти сюда.$B$BПогляди, чем ты сможешь там помочь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Недурно мы вляпались. Уже слишком поздно присоединяться к нашим войскам в Ледяной Короне, и мы застряли между Плетью и Драккари.$B$BЯ говорил верховному лорду, что не стоит идти сюда.$B$BПогляди, чем ты сможешь там помочь.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14285,'Слышишь, |3-6($c)? Духи стихий возвещают своим плачем о том, что земли эти почти мертвы. Драккари вытягивают силу из своих богов, убивая их ради защиты от Плети.$B$BОни близоруки, и однажды они поплатятся за свои деяния.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Слышишь, |3-6($c)? Духи стихий возвещают своим плачем о том, что земли эти почти мертвы. Драккари вытягивают силу из своих богов, убивая их ради защиты от Плети.$B$BОни близоруки, и однажды они поплатятся за свои деяния.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14286,'Я была уверена, что не увижу ничего более беспощадного, чем битва за Часовню Последней Надежды в Чумных землях.$B$BЯ ошибалась.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я была уверена, что не увижу ничего более беспощадного, чем битва за Часовню Последней Надежды в Чумных землях.$B$BЯ ошибалась.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14289,'<Тело Алиндии слегка покачивается на волнах. Похоже, она умерла уже давно.>','<Тело Алиндии слегка покачивается на волнах. Похоже, она умерла уже давно.>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Тело Алиндии слегка покачивается на волнах. Похоже, она умерла уже давно.>',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','<Тело Алиндии слегка покачивается на волнах. Похоже, она умерла уже давно.>',`text0_1_loc8`);
