INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14290,'<Перевернув тело Баритаса, вы видите ужасную рану на его голове, которая, видимо, и стала причиной его смерти.>','<Перевернув тело Баритаса, вы видите ужасную рану на его голове, которая, видимо, и стала причиной его смерти.>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Перевернув тело Баритаса, вы видите ужасную рану на его голове, которая, видимо, и стала причиной его смерти.>',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','<Перевернув тело Баритаса, вы видите ужасную рану на его голове, которая, видимо, и стала причиной его смерти.>',`text0_1_loc8`);
