INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14292,'<Грондаль тщетно пытается дотянуться до вас, но рука его безжизненно падает, и жизнь медленно покидает его тело.>','<Грондаль тщетно пытается дотянуться до вас, но рука его безжизненно падает, и жизнь медленно покидает его тело.>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Грондаль тщетно пытается дотянуться до вас, но рука его безжизненно падает, и жизнь медленно покидает его тело.>',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','<Грондаль тщетно пытается дотянуться до вас, но рука его безжизненно падает, и жизнь медленно покидает его тело.>',`text0_1_loc8`);
