INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14293,'<В застывшем взгляде Терентиса навеки отразилось выражение скорби, сопровождавшей последние мгновения его жизни.>','<В застывшем взгляде Терентиса навеки отразилось выражение скорби, сопровождавшей последние мгновения его жизни.>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<В застывшем взгляде Терентиса навеки отразилось выражение скорби, сопровождавшей последние мгновения его жизни.>',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','<В застывшем взгляде Терентиса навеки отразилось выражение скорби, сопровождавшей последние мгновения его жизни.>',`text0_1_loc8`);
