INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14295,'<Ночной эльф поворачивается к вам и пытается коснуться вашей руки.>\r\n\r\nДля меня все кончено... Это кара за нашу гордыню... Не медли... может быть, кто-то избежал ужасной участи. Спаси всех, кого сможешь.\r\n\r\n<Ее рука выскальзывает из вашей руки, и вы чувствуете, как жизнь покидает ее.>','<Ночной эльф поворачивается к вам и пытается коснуться вашей руки.>\r\n\r\nДля меня все кончено... Это кара за нашу гордыню... Не медли... может быть, кто-то избежал ужасной участи. Спаси всех, кого сможешь.\r\n\r\n<Ее рука выскальзывает из вашей руки, и вы чувствуете, как жизнь покидает ее.>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Ночной эльф поворачивается к вам и пытается коснуться вашей руки.>\r\n\r\nДля меня все кончено... Это кара за нашу гордыню... Не медли... может быть, кто-то избежал ужасной участи. Спаси всех, кого сможешь.\r\n\r\n<Ее рука выскальзывает из вашей руки, и вы чувствуете, как жизнь покидает ее.>',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','<Ночной эльф поворачивается к вам и пытается коснуться вашей руки.>\r\n\r\nДля меня все кончено... Это кара за нашу гордыню... Не медли... может быть, кто-то избежал ужасной участи. Спаси всех, кого сможешь.\r\n\r\n<Ее рука выскальзывает из вашей руки, и вы чувствуете, как жизнь покидает ее.>',`text0_1_loc8`);
