INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14296,'Так вот, что значит... быть смертным?\r\n\r\n<С этим вопросом на устах Мавралин умирает.>','Так вот, что значит... быть смертным?\r\n\r\n<С этим вопросом на устах Мавралин умирает.>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Так вот, что значит... быть смертным?\r\n\r\n<С этим вопросом на устах Мавралин умирает.>',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Так вот, что значит... быть смертным?\r\n\r\n<С этим вопросом на устах Мавралин умирает.>',`text0_1_loc8`);
