INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14297,'<Подойдя ближе, вы слышите, как Кириллиан с трудом борется за каждый вздох. Но вам кажется, что у него есть шансы выкарабкаться, если помощь придет вовремя.>','<Подойдя ближе, вы слышите, как Кириллиан с трудом борется за каждый вздох. Но вам кажется, что у него есть шансы выкарабкаться, если помощь придет вовремя.>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Подойдя ближе, вы слышите, как Кириллиан с трудом борется за каждый вздох. Но вам кажется, что у него есть шансы выкарабкаться, если помощь придет вовремя.>',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','<Подойдя ближе, вы слышите, как Кириллиан с трудом борется за каждый вздох. Но вам кажется, что у него есть шансы выкарабкаться, если помощь придет вовремя.>',`text0_1_loc8`);
