INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14311,'Ордынцы буквально кишат в этих лесах, |3-6($c). Будь $gосторожен:осторожна;!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ордынцы буквально кишат в этих лесах, |3-6($c). Будь $gосторожен:осторожна;!',`text0_1_loc8`);
