INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14312,'Я выполню все, что поручил мне хозяин, и неважно, какую цену придется заплатить за это. Жизнь маленькой девочки висит на волоске – что может быть важнее?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я выполню все, что поручил мне хозяин, и неважно, какую цену придется заплатить за это. Жизнь маленькой девочки висит на волоске – что может быть важнее?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14313,'Из этих крыс получается на удивление вкусная похлебка.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Из этих крыс получается на удивление вкусная похлебка.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14315,'Добро пожаловать, $gгосподин:госпожа;. Этот лагерь гораздо удобнее, чем тот, в котором мы были раньше.$B$BХорошо, когда есть с кем поболтать. Меня даже обучили кое-каким приемам, чтобы я тоже мог постоять за себя в битве против Орды.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать, $gгосподин:госпожа;. Этот лагерь гораздо удобнее, чем тот, в котором мы были раньше.$B$BХорошо, когда есть с кем поболтать. Меня даже обучили кое-каким приемам, чтобы я тоже мог постоять за себя в битве против Орды.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14316,'Приветствую тебя,|3-6($c). В отличие от сил Орды на юге, наши позиции не так хорошо защищены.$B$BНам пригодится любая помощь в обороне.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Приветствую тебя,|3-6($c). В отличие от сил Орды на юге, наши позиции не так хорошо защищены.$B$BНам пригодится любая помощь в обороне.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14317,'Приветствую вас, герои! Все наши попытки сбить дракониху не увенчались успехом. Нам бы пригодилась ваша помощь. Гарпунных пушек на всех хватит.','Приветствую вас, герои! Все наши попытки сбить дракониху не увенчались успехом. Нам бы пригодилась ваша помощь. Гарпунных пушек на всех хватит.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приветствую вас, герои! Все наши попытки сбить дракониху не увенчались успехом. Нам бы пригодилась ваша помощь. Гарпунных пушек на всех хватит.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Приветствую вас, герои! Все наши попытки сбить дракониху не увенчались успехом. Нам бы пригодилась ваша помощь. Гарпунных пушек на всех хватит.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14319,'Я уж думала, что никогда не смогу освободиться от этого ужасного заклинания! Благодарю тебя за спасение, $gнезнакомец:незнакомка;.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я уж думала, что никогда не смогу освободиться от этого ужасного заклинания! Благодарю тебя за спасение, $gнезнакомец:незнакомка;.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14320,'Прими это в знак моей благодарности, |3-6($c).') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Прими это в знак моей благодарности, |3-6($c).',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14322,'О боги! Я уж отчаялась звать на помощь!$B$BСкорее, освободи меня!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','О боги! Я уж отчаялась звать на помощь!$B$BСкорее, освободи меня!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14324,'Чем могу служить, $gсэр:мадам;?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Чем могу служить, $gсэр:мадам;?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14326,'Смертные, я благодарен вам за свое спасение от пагубы, что витает в этих местах. Хотя я еще не полностью пришел в себя, в моих силах помочь вам в сражении с Йогг-Сароном.\r\n\r\nЯ наделю каждого из вас Стойкостью льдов, которая оградит вас от части урона. Если же кто-то из вас будет близок к гибели, то я заключу его тело в ледяную глыбу, которая убережет его от всех повреждений на короткое время. Но знайте, что заклинания истощают мою силу, и мне надо будет отдохнуть после использования этих возможностей.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Смертные, я благодарен вам за свое спасение от пагубы, что витает в этих местах. Хотя я еще не полностью пришел в себя, в моих силах помочь вам в сражении с Йогг-Сароном.\r\n\r\nЯ наделю каждого из вас Стойкостью льдов, которая оградит вас от части урона. Если же кто-то из вас будет близок к гибели, то я заключу его тело в ледяную глыбу, которая убережет его от всех повреждений на короткое время. Но знайте, что заклинания истощают мою силу, и мне надо будет отдохнуть после использования этих возможностей.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14327,'Приветствую тебя, |3-6($c).') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Приветствую тебя, |3-6($c).',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14334,'Смертные, я благодарен вам за мое спасение от зла, что витает в этих местах. Хотя я еще не полностью пришел в себя, в моих силах помочь вам в сражении с Йогг-Сароном.\r\n\r\nЯ наделю каждого из вас Скоростью разума, увеличивающей скорость атаки ближнего боя и применения заклинаний. К тому же, я могу разрушить матрицы некоторых живых существ, созданных из саронита, снижая скорость их атаки и прочтения заклинаний.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Смертные, я благодарен вам за мое спасение от зла, что витает в этих местах. Хотя я еще не полностью пришел в себя, в моих силах помочь вам в сражении с Йогг-Сароном.\r\n\r\nЯ наделю каждого из вас Скоростью разума, увеличивающей скорость атаки ближнего боя и применения заклинаний. К тому же, я могу разрушить матрицы некоторых живых существ, созданных из саронита, снижая скорость их атаки и прочтения заклинаний.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14335,'Ты $gуверен, что готов:уверена, что готова; к верховому поединку?','Ты $gуверен, что готов:уверена, что готова; к верховому поединку?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты $gуверен, что готов:уверена, что готова; к верховому поединку?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты $gуверен, что готов:уверена, что готова; к верховому поединку?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14336,'Подойди поближе, |3-6($c). Время мое истекает...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Подойди поближе, |3-6($c). Время мое истекает...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14337,'Похоже, смертельно раненный орк потерял сознание.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Похоже, смертельно раненный орк потерял сознание.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14338,'<Безжизненное тело орка ни на что не реагирует...>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Безжизненное тело орка ни на что не реагирует...>',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14339,'Рада видеть тебя, |3-6($c).$B$BПрости, не могу уделить тебе достаточно внимания. У нас тут бой идет, как нетрудно заметить.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Рада видеть тебя, |3-6($c).$B$BПрости, не могу уделить тебе достаточно внимания. У нас тут бой идет, как нетрудно заметить.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14340,'Дай мне знать, когда будешь $gготов:готова; возглавить отряд. У меня еще осталось в тылу несколько верных стражей, так что если тебе будут нужны подкрепления – возвращайся.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Дай мне знать, когда будешь $gготов:готова; возглавить отряд. У меня еще осталось в тылу несколько верных стражей, так что если тебе будут нужны подкрепления – возвращайся.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`,`text2_0_loc8`,`text2_1_loc8`) VALUES (14346,'Я отказываюсь работать, пока эльфы еще тут!','Я отказываюсь работать, пока эльфы еще тут!','Эльфы убили слишком многих рабочих в лесу. Я сижу тут, потому что это безопасное место.','Эльфы убили слишком многих рабочих в лесу. Я сижу тут, потому что это безопасное место.','Я не собираюсь расстаться с жизнью из-за кучи досок!','Я не собираюсь расстаться с жизнью из-за кучи досок!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я отказываюсь работать, пока эльфы еще тут!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я отказываюсь работать, пока эльфы еще тут!',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Эльфы убили слишком многих рабочих в лесу. Я сижу тут, потому что это безопасное место.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Эльфы убили слишком многих рабочих в лесу. Я сижу тут, потому что это безопасное место.',`text1_1_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Я не собираюсь расстаться с жизнью из-за кучи досок!',`text2_0_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Я не собираюсь расстаться с жизнью из-за кучи досок!',`text2_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text
