INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14358,'Быстрее, |3-6($c)! Нельзя тратить ни минуты, иначе Застава Расщепленного дерева падет!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Быстрее, |3-6($c)! Нельзя тратить ни минуты, иначе Застава Расщепленного дерева падет!',`text0_1_loc8`);
