INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14359,'Да славится Штормград и король Ринн!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да славится Штормград и король Ринн!',`text0_0_loc8`);
