INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14362,'Ну надо же, я и не мечтал, что увижу Ульдуар. Но когда Бранн попросил поддержать его экспедицию, как я мог отказать?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ну надо же, я и не мечтал, что увижу Ульдуар. Но когда Бранн попросил поддержать его экспедицию, как я мог отказать?',`text0_0_loc8`);
