INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14363,'Я уж и не надеялся выбраться из этих душных джунглей! А теперь я ведущий конструктор этой экспедиции.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я уж и не надеялся выбраться из этих душных джунглей! А теперь я ведущий конструктор этой экспедиции.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14364,'Может, эти штучки и выглядят как металлолом, зато работают они так, что враги только по сторонам и летают. На головной таран прикрепили электроскопический гипер-конденсатор, и он теперь разряжается небольшими молниями.$B$BДаже турель оснастили противовоздушными ракетами, так что и разрушители им не страшны.','Может, эти штучки и выглядят как металлолом, зато работают они так, что враги только по сторонам и летают. На головной таран прикрепили электроскопический гипер-конденсатор, и он теперь разряжается небольшими молниями.$B$BДаже турель оснастили противовоздушными ракетами, так что и разрушители им не страшны.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Может, эти штучки и выглядят как металлолом, зато работают они так, что враги только по сторонам и летают. На головной таран прикрепили электроскопический гипер-конденсатор, и он теперь разряжается небольшими молниями.$B$BДаже турель оснастили противовоздушными ракетами, так что и разрушители им не страшны.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Может, эти штучки и выглядят как металлолом, зато работают они так, что враги только по сторонам и летают. На головной таран прикрепили электроскопический гипер-конденсатор, и он теперь разряжается небольшими молниями.$B$BДаже турель оснастили противовоздушными ракетами, так что и разрушители им не страшны.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14365,'Здесь мне удалось собрать то, что может считаться величайшим кладезем мудрости Запределья. Даже огромные библиотеки Луносвета и Штормграда бледнеют на фоне этого собрания.$B$BПрошу тебя… листай, читай, порадуй свой ум новыми знаниями. Все книги подписаны и расставлены в алфавитном порядке.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здесь мне удалось собрать то, что может считаться величайшим кладезем мудрости Запределья. Даже огромные библиотеки Луносвета и Штормграда бледнеют на фоне этого собрания.$B$BПрошу тебя… листай, читай, порадуй свой ум новыми знаниями. Все книги подписаны и расставлены в алфавитном порядке.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14367,'Нам повезло: запчастей хватило, чтобы починить этих малышек!$BЧем тебе помочь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Нам повезло: запчастей хватило, чтобы починить этих малышек!$BЧем тебе помочь?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14372,'Чем могу служить, $gсэр:мадам;?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Чем могу служить, $gсэр:мадам;?',`text0_0_loc8`);
