INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14379,'Серебряный союз рад приветствовать тебя на этом турнире. Серебряный Авангард попросил нас составить список желающих принять участие в турнире и начать их тренировку.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Серебряный союз рад приветствовать тебя на этом турнире. Серебряный Авангард попросил нас составить список желающих принять участие в турнире и начать их тренировку.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14383,'Панель управления кажется старинной, хотя время ее и не тронуло. Единственное гнездо, похоже, предназначено для приема больших дисков.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Панель управления кажется старинной, хотя время ее и не тронуло. Единственное гнездо, похоже, предназначено для приема больших дисков.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
