INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14392,'Если мы выиграем турнир во имя Луносвета, нас ждет почет и слава.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Если мы выиграем турнир во имя Луносвета, нас ждет почет и слава.',`text0_1_loc8`);
