INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14393,'Поздравляю, ваш ум стал еще более гибким.','Поздравляю, ваш ум стал еще более гибким.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Поздравляю, ваш ум стал еще более гибким.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Поздравляю, ваш ум стал еще более гибким.',`text0_1_loc8`);
