INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14395,'Мы хотим завоевать известность, славу и право сражаться с Плетью плечом к плечу с нашими братьями из Серебряного Авангарда.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы хотим завоевать известность, славу и право сражаться с Плетью плечом к плечу с нашими братьями из Серебряного Авангарда.',`text0_0_loc8`);
