INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14396,'Король Магни очень надеется, что мы победим в турнире и станем его гордостью. Мы не должны его подвести!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Король Магни очень надеется, что мы победим в турнире и станем его гордостью. Мы не должны его подвести!',`text0_1_loc8`);
