INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14398,'Лучшие воины Гномрегана явились биться на турнире. Пожелай нам удачи!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Лучшие воины Гномрегана явились биться на турнире. Пожелай нам удачи!',`text0_0_loc8`);
