INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14399,'Весь Дарнас с нетерпением ждет нашего выхода на Ристалище.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Весь Дарнас с нетерпением ждет нашего выхода на Ристалище.',`text0_0_loc8`);
