INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14402,'Как только начнется турнир, все увидят триумф Отрекшихся!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Как только начнется турнир, все увидят триумф Отрекшихся!',`text0_0_loc8`);
