INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14403,'Бой будет напряженным, но чемпионы Оргриммара не остановятся ни перед чем.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Бой будет напряженным, но чемпионы Оргриммара не остановятся ни перед чем.',`text0_0_loc8`);
