INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14425,'Приветствую тебя от лица всего Серебряного Авангарда.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Приветствую тебя от лица всего Серебряного Авангарда.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14426,'Никто не строит быстрее, дешевле и надежнее, чем братья Рвизасов!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Никто не строит быстрее, дешевле и надежнее, чем братья Рвизасов!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14428,'Для меня честь помогать Бранну в его исследовании древнего Ульдуара.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Для меня честь помогать Бранну в его исследовании древнего Ульдуара.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14431,'Привет тебе, |3-6($c).$B$BЯ обучаю претендентов искусству верхового поединка.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Привет тебе, |3-6($c).$B$BЯ обучаю претендентов искусству верхового поединка.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`) VALUES (14432,'Чего тебе, жалкий смерт...$b$bА, это ты, |3-6($r)? Чем могу служить?','Да, |3-6($c), что?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Чего тебе, жалкий смерт...$b$bА, это ты, |3-6($r)? Чем могу служить?',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Да, |3-6($c), что?',`text1_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14436,'Здорово, как оно?$B$BХочешь освоить прием "Рывок", |3-6($c)?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здорово, как оно?$B$BХочешь освоить прием "Рывок", |3-6($c)?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14437,'Ну что, приступим! Правильно выполнить "Рывок" на своей коняшке – это тебе не шпорами махать да глотку драть... хотя это тоже весело, не спорю! Но тренировка с манекенами требует более тонкого подхода.$B$BСекрет хорошего рывка в правильно выбранных дистанции и времени. Подъедешь слишком близко – не успеешь набрать скорость, а долгий разгон утомит скакуна. Ну а по поводу выбора верного момента...$B$BПеред ударом надо лишить цель защиты. Поэтому сначала выполни "Удар по щиту", а уж потом делай "Рывок"!$B$BТак же и с настоящим противником – разбивай щит, делай "Рывок", и можешь праздновать победу!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ну что, приступим! Правильно выполнить "Рывок" на своей коняшке – это тебе не шпорами махать да глотку драть... хотя это тоже весело, не спорю! Но тренировка с манекенами требует более тонкого подхода.$B$BСекрет хорошего рывка в правильно выбранных дистанции и времени. Подъедешь слишком близко – не успеешь набрать скорость, а долгий разгон утомит скакуна. Ну а по поводу выбора верного момента...$B$BПеред ударом надо лишить цель защиты. Поэтому сначала выполни "Удар по щиту", а уж потом делай "Рывок"!$B$BТак же и с настоящим противником – разбивай щит, делай "Рывок", и можешь праздновать победу!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14438,'О, я вижу |3-6($c) желает освоить новый прием? Почему бы не начать с "Удара по щиту"?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','О, я вижу |3-6($c) желает освоить новый прием? Почему бы не начать с "Удара по щиту"?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14439,'"Удар по щиту" легко выучить, но сложно применить на практике. Сам по себе он не имеет большого эффекта, но в связке с рывком и выпадом работает великолепно.$B$BНайди мишень для дальнего боя и подбери оптимальную дистанцию для удара по щиту. Оцени, сколько пространства тебе нужно и насколько далеко ты сможешь метнуть копье. $B$BПотом просто брось копье и пробей защиту противника. $B$BЭта тактика всегда работает в верховом поединке: лишить защиты... и нанести решающий удар!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','"Удар по щиту" легко выучить, но сложно применить на практике. Сам по себе он не имеет большого эффекта, но в связке с рывком и выпадом работает великолепно.$B$BНайди мишень для дальнего боя и подбери оптимальную дистанцию для удара по щиту. Оцени, сколько пространства тебе нужно и насколько далеко ты сможешь метнуть копье. $B$BПотом просто брось копье и пробей защиту противника. $B$BЭта тактика всегда работает в верховом поединке: лишить защиты... и нанести решающий удар!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14441,'Обожди немного, $Gдруг:цыпа;. Скоро для тебя найдется работка...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Обожди немного, $Gдруг:цыпа;. Скоро для тебя найдется работка...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14442,'Что есть, то есть. У нас теперь целая куча кристаллов гнили.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что есть, то есть. У нас теперь целая куча кристаллов гнили.',`text0_0_loc8`);
