INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14443,'Значит, болван Дармук больше не облажается! Терпение, $Gдруг:плюшка;. Будет тебе дело...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Значит, болван Дармук больше не облажается! Терпение, $Gдруг:плюшка;. Будет тебе дело...',`text0_0_loc8`);
