INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14444,'Теперь вожди не помешают нам начать атаку! Скоро, уже скоро, $n...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Теперь вожди не помешают нам начать атаку! Скоро, уже скоро, $n...',`text0_0_loc8`);
