INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14445,'Ну, вот и все, $Gдруг:лапа;. Готовься... скоро будет драка!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ну, вот и все, $Gдруг:лапа;. Готовься... скоро будет драка!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14446,'Я был в гостях у родственников, когда Лордерон пал, и... я думал, что никогда не вернусь в Западный Край.$B$BИнтересно, живы ли мои родные. Но еще интереснее – почему меня совершенно не волнует их судьба.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я был в гостях у родственников, когда Лордерон пал, и... я думал, что никогда не вернусь в Западный Край.$B$BИнтересно, живы ли мои родные. Но еще интереснее – почему меня совершенно не волнует их судьба.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14447,'Сильный аромат, исходящий из чаши, напоминает запах трав, смешанный с вонью горелых волос.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Сильный аромат, исходящий из чаши, напоминает запах трав, смешанный с вонью горелых волос.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14453,'Чтобы начать обучение, тебе нужно оседлать турнирное верховое животное.$B$BВозьми копье и найди верховое животное в стойлах рядом с павильоном твоей фракции.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Чтобы начать обучение, тебе нужно оседлать турнирное верховое животное.$B$BВозьми копье и найди верховое животное в стойлах рядом с павильоном твоей фракции.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text1_1_loc8`,`text2_1_loc8`,`text3_1_loc8`,`text4_1_loc8`,`text5_1_loc8`,`text6_1_loc8`,`text7_1_loc8`) VALUES (14454,'Хочешь прокатиться?','Чем могу помочь?','Рада видеть тебя.','Тебе нужен транспорт?','Как дела, |3-6($c)?','Холодная нынче выдалась погода, правда?','Рада видеть, что у тебя все в порядке.') ON DUPLICATE KEY UPDATE `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Хочешь прокатиться?',`text1_1_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Чем могу помочь?',`text2_1_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','Рада видеть тебя.',`text3_1_loc8`), `text4_1_loc8`=IF(`text4_1_loc8` IS NULL OR `text4_1_loc8`='','Тебе нужен транспорт?',`text4_1_loc8`), `text5_1_loc8`=IF(`text5_1_loc8` IS NULL OR `text5_1_loc8`='','Как дела, |3-6($c)?',`text5_1_loc8`), `text6_1_loc8`=IF(`text6_1_loc8` IS NULL OR `text6_1_loc8`='','Холодная нынче выдалась погода, правда?',`text6_1_loc8`), `text7_1_loc8`=IF(`text7_1_loc8` IS NULL OR `text7_1_loc8`='','Рада видеть, что у тебя все в порядке.',`text7_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14455,'Ну и чему я тебя, $Gпешего:пешую;, учить буду?$B$BИди к павильону своей фракции, разживись копьем и коняшкой, а потом будем говорить.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ну и чему я тебя, $Gпешего:пешую;, учить буду?$B$BИди к павильону своей фракции, разживись копьем и коняшкой, а потом будем говорить.',`text0_0_loc8`);
