INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14457,'Эй, |3-6($r), не торопись.$B$BМои товары – только для чемпионов Стальгорна.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эй, |3-6($r), не торопись.$B$BМои товары – только для чемпионов Стальгорна.',`text0_0_loc8`);
