INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14458,'Прими мои извинения, |3-6($r), но только чемпионы Громового Утеса могут покупать мои товары.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Прими мои извинения, |3-6($r), но только чемпионы Громового Утеса могут покупать мои товары.',`text0_0_loc8`);
