INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14460,'Я продаю свои товары только чемпионам Оргриммара.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я продаю свои товары только чемпионам Оргриммара.',`text0_1_loc8`);
