INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14462,'Привет!$B$BПрими мои извинения, но мои товары могут покупать только чемпионы Гномрегана.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Привет!$B$BПрими мои извинения, но мои товары могут покупать только чемпионы Гномрегана.',`text0_1_loc8`);
