INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14464,'Самамба думать, твоя интендантом ошибаться!$B$BМоя продавать только чемпионам Сен\'джина.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Самамба думать, твоя интендантом ошибаться!$B$BМоя продавать только чемпионам Сен\'джина.',`text0_1_loc8`);
