INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14465,'Увы, только чемпионы Луносвета могут приобретать у меня товары.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Увы, только чемпионы Луносвета могут приобретать у меня товары.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14468,'Тише! Не выдавай мое местоположение, когда я на задании. Матас должен знать, что тут происходит.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Тише! Не выдавай мое местоположение, когда я на задании. Матас должен знать, что тут происходит.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14469,'Глупо было считать нас слабыми: последние события только закалили нас. Этим троллям не выстоять – мы покончим с ними сегодня же!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Глупо было считать нас слабыми: последние события только закалили нас. Этим троллям не выстоять – мы покончим с ними сегодня же!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14471,'Отлично справились с этим железным чудищем. Теперь осталось всего несколько препятствий.$B$BКогда разберетесь с громыхающим роботом в конце зала, мы сможем войти в Ульдуар.$B$BЕще мы заметили огромного огнедышащего протодракона и оплавленного великана, но их вы можете обойти.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Отлично справились с этим железным чудищем. Теперь осталось всего несколько препятствий.$B$BКогда разберетесь с громыхающим роботом в конце зала, мы сможем войти в Ульдуар.$B$BЕще мы заметили огромного огнедышащего протодракона и оплавленного великана, но их вы можете обойти.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14474,'Воспитание ядошкуров и умение ездить на них требуют терпения и самоотдачи.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Воспитание ядошкуров и умение ездить на них требуют терпения и самоотдачи.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14476,'Рыцари Серебряного Авангарда полагаются на равновесие и точность, искусно чередуя приемы нападения и защиты.$B$BТем не менее, они легко открываются для рывка, пытаясь создать дистанцию для разгона.$B$BВыполни рывок до того, как рыцарь успеет сделать свой, затем ударь по щиту и порази противника в выпаде.','Рыцари Серебряного Авангарда полагаются на равновесие и точность, искусно чередуя приемы нападения и защиты.$B$BТем не менее, они легко открываются для рывка, пытаясь создать дистанцию для разгона.$B$BВыполни рывок до того, как рыцарь успеет сделать свой, затем ударь по щиту и порази противника в выпаде.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Рыцари Серебряного Авангарда полагаются на равновесие и точность, искусно чередуя приемы нападения и защиты.$B$BТем не менее, они легко открываются для рывка, пытаясь создать дистанцию для разгона.$B$BВыполни рывок до того, как рыцарь успеет сделать свой, затем ударь по щиту и порази противника в выпаде.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Рыцари Серебряного Авангарда полагаются на равновесие и точность, искусно чередуя приемы нападения и защиты.$B$BТем не менее, они легко открываются для рывка, пытаясь создать дистанцию для разгона.$B$BВыполни рывок до того, как рыцарь успеет сделать свой, затем ударь по щиту и порази противника в выпаде.',`text0_1_loc8`);
