INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14487,'Добро пожаловать в обитель Света. Пожалуйста, садитесь. Отдохните от мирских горестей.','Добро пожаловать в обитель Света. Пожалуйста, садитесь. Отдохните от мирских горестей.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать в обитель Света. Пожалуйста, садитесь. Отдохните от мирских горестей.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Добро пожаловать в обитель Света. Пожалуйста, садитесь. Отдохните от мирских горестей.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14488,'Ну, за дело, |3-6($r).$b$bУ нас так мало времени и так много работы.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ну, за дело, |3-6($r).$b$bУ нас так мало времени и так много работы.',`text0_0_loc8`);
