INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14491,'$GПришел:Пришла; послушать проповедь? Скорей занимай самое лучшее место и слушай в оба.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','$GПришел:Пришла; послушать проповедь? Скорей занимай самое лучшее место и слушай в оба.',`text0_0_loc8`);
