INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14492,'Сегодня ты уже $Gпобедил:победила; одного из наших рыцарей, поэтому я не могу принять твой вызов.','Сегодня ты уже $Gпобедил:победила; одного из наших рыцарей, поэтому я не могу принять твой вызов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Сегодня ты уже $Gпобедил:победила; одного из наших рыцарей, поэтому я не могу принять твой вызов.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Сегодня ты уже $Gпобедил:победила; одного из наших рыцарей, поэтому я не могу принять твой вызов.',`text0_1_loc8`);
