INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14494,'Моя госпожа...$b$bЯ не смог ее защитить. Как теперь я могу вернуться в Луносвет?..') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Моя госпожа...$b$bЯ не смог ее защитить. Как теперь я могу вернуться в Луносвет?..',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14495,'Это честь для меня – представлять Серебряный Авангард на турнире.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Это честь для меня – представлять Серебряный Авангард на турнире.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14496,'Активация вторичных оборонных систем приведет к уничтожению неавторизованных форм жизни с помощью орбитальных установок.$B$BВы являетесь неавторизованной формой жизни. Пожалуйста, подтвердите включение.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Активация вторичных оборонных систем приведет к уничтожению неавторизованных форм жизни с помощью орбитальных установок.$B$BВы являетесь неавторизованной формой жизни. Пожалуйста, подтвердите включение.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14497,'Получено разрешение системы безопасности. Вторичные оборонные системы активированы.$B$BЗапасная система отключения оборонных систем может быть задействована с помощью индивидуальных генераторов, расположенных во Дворе.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Получено разрешение системы безопасности. Вторичные оборонные системы активированы.$B$BЗапасная система отключения оборонных систем может быть задействована с помощью индивидуальных генераторов, расположенных во Дворе.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14500,'В северных пределах Ледяной Короны начался Серебряный турнир! Если хочешь, я могу показать тебе дорогу, |3-6($c).$B$BЧем больше претендентов примут участие в соревновании, тем сильнее будут наши войска в походе против Короля-лича.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','В северных пределах Ледяной Короны начался Серебряный турнир! Если хочешь, я могу показать тебе дорогу, |3-6($c).$B$BЧем больше претендентов примут участие в соревновании, тем сильнее будут наши войска в походе против Короля-лича.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14505,'Здравствуй, дитя мое.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здравствуй, дитя мое.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14506,'Не стоило ожидать, что эти грязные тролли вечно будут сохранять перемирие. Нельзя доверять тем, кто потворствует Орде.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Не стоило ожидать, что эти грязные тролли вечно будут сохранять перемирие. Нельзя доверять тем, кто потворствует Орде.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14507,'Кровь и гром, $n!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Кровь и гром, $n!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14508,'Много бед поджидают нас в этом мире, но мы не можем отрицать могущество природы, иначе она сама отринет нас в час нужды. Мы должны помнить уроки прошлого.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Много бед поджидают нас в этом мире, но мы не можем отрицать могущество природы, иначе она сама отринет нас в час нужды. Мы должны помнить уроки прошлого.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14509,'Нельзя стоять на пути природы, даже если ее силы направлены на разрушение.$B$BНо силы, которые грозят уничтожить Темные берега не имеют ничего общего с природой, и потому я не могу позволить') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Нельзя стоять на пути природы, даже если ее силы направлены на разрушение.$B$BНо силы, которые грозят уничтожить Темные берега не имеют ничего общего с природой, и потому я не могу позволить',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14510,'Эй, как дела? Меня зовут Гари, а тебя небось послал Горбольд.\r\n\r\nЕсли ты правда хочешь помочь, слушай внимательно. План простой: я соорудил несколько роботов-ловушек, которые мы разместим неподалеку от поселения мурлоков и включим на обратный отсчет. Они будут мигать и издавать звуки, которые непременно привлекут внимание этих глупых тварей. Мурлоки подойдут к ним поближе – и тут ловушки взорвутся, отправив маленьких мерзавцев в загробный мир.\r\n\r\nЕсли нам удастся избавиться от большинства мурлоков, мы сможем пробраться к кораблям без значительных потерь. Это, впрочем, уже не твоя забота – главное, взорви побольше ластоногих!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эй, как дела? Меня зовут Гари, а тебя небось послал Горбольд.\r\n\r\nЕсли ты правда хочешь помочь, слушай внимательно. План простой: я соорудил несколько роботов-ловушек, которые мы разместим неподалеку от поселения мурлоков и включим на обратный отсчет. Они будут мигать и издавать звуки, которые непременно привлекут внимание этих глупых тварей. Мурлоки подойдут к ним поближе – и тут ловушки взорвутся, отправив маленьких мерзавцев в загробный мир.\r\n\r\nЕсли нам удастся избавиться от большинства мурлоков, мы сможем пробраться к кораблям без значительных потерь. Это, впрочем, уже не твоя забота – главное, взорви побольше ластоногих!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14511,'Пока стихии пытаются разорвать Темные берега на части, я борюсь за выживание дикой природы.$B$BМогу ли я рассчитывать на твою помощь, |3-6($c)?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Пока стихии пытаются разорвать Темные берега на части, я борюсь за выживание дикой природы.$B$BМогу ли я рассчитывать на твою помощь, |3-6($c)?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14514,'Не стой столбом, |3-6($r)...$b$bУ нас полно работы!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не стой столбом, |3-6($r)...$b$bУ нас полно работы!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14517,'Замри, дитя, и ты услышишь древний голос земли. Она кричит от боли.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Замри, дитя, и ты услышишь древний голос земли. Она кричит от боли.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14518,'Хм, хм... Зачем тебе, $gюноша:девочка;, столь мощное средство? Сколько бы противников ты не $gубил:убила; во имя своего Альянса, знай, что в великом круговороте жизни рождение имеет такую же силу, как и смерть. $B$BОну медленно поднимает руки к кроне и достает ничем не примечательную шишку, которую бережно вкладывает вам в руки.$B$BЭто – великая сила.$B$BПрости, я не собирался хвастаться, но...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Хм, хм... Зачем тебе, $gюноша:девочка;, столь мощное средство? Сколько бы противников ты не $gубил:убила; во имя своего Альянса, знай, что в великом круговороте жизни рождение имеет такую же силу, как и смерть. $B$BОну медленно поднимает руки к кроне и достает ничем не примечательную шишку, которую бережно вкладывает вам в руки.$B$BЭто – великая сила.$B$BПрости, я не собирался хвастаться, но...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14520,'Ну-ка, посмотрим, удастся ли нам заморозить врагов на месте...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ну-ка, посмотрим, удастся ли нам заморозить врагов на месте...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14521,'Наш брат сбился с пути. Он сжигает землю, превращает в пар воду и поглощает слишком много воздуха.$B$BПомоги нам вернуть его в состояние равновесия.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Наш брат сбился с пути. Он сжигает землю, превращает в пар воду и поглощает слишком много воздуха.$B$BПомоги нам вернуть его в состояние равновесия.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14523,'<*Гррррр*Гррррр*Гррррр*>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<*Гррррр*Гррррр*Гррррр*>',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14524,'Я ценю твою помощь в защите дикой природы. Надеюсь, мы не опоздали.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я ценю твою помощь в защите дикой природы. Надеюсь, мы не опоздали.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14529,'Уйти отсюда? Что за глупости! Никогда еще за всю свою блистательную карьеру я не бросал только что начатые раскопки! Ну разве что по случайности. Перепутал ямы пару раз. И вообще, что ты $gтакой:такая; и что мы тут делаем?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Уйти отсюда? Что за глупости! Никогда еще за всю свою блистательную карьеру я не бросал только что начатые раскопки! Ну разве что по случайности. Перепутал ямы пару раз. И вообще, что ты $gтакой:такая; и что мы тут делаем?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14532,'Мурлоки. Ха!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мурлоки. Ха!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14534,'Жестокое царство Короля-лича уже заставило обитателей Нордскола пролить море слез. Особенно страдают ни в чем не повинные дети. Если ты друг Оракулов или племени Бешеного Сердца, возьми одного из сироток под опеку, хотя бы на неделю.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Жестокое царство Короля-лича уже заставило обитателей Нордскола пролить море слез. Особенно страдают ни в чем не повинные дети. Если ты друг Оракулов или племени Бешеного Сердца, возьми одного из сироток под опеку, хотя бы на неделю.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`,`text3_0_loc8`,`text4_0_loc8`,`text5_0_loc8`) VALUES (14535,'А можно нам подсохший желток?','Интересно, а у Великих может кончиться место в сумках? Мы дарим им столько блестяшек...','Почему эти люди-собаки спрашивают, жалеем ли мы Лафу? Лафу много болтает, но он наш друг.','Су-$n, а можно у нас тоже будет свисток, чтобы позвать тебя, когда ты нам понадобишься?','Может быть, мы тоже станем |3-4($r), когда вырастем. Как ты думаешь?','А твоих родителей тоже убили люди-собаки?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','А можно нам подсохший желток?',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Интересно, а у Великих может кончиться место в сумках? Мы дарим им столько блестяшек...',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Почему эти люди-собаки спрашивают, жалеем ли мы Лафу? Лафу много болтает, но он наш друг.',`text2_0_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Су-$n, а можно у нас тоже будет свисток, чтобы позвать тебя, когда ты нам понадобишься?',`text3_0_loc8`), `text4_0_loc8`=IF(`text4_0_loc8` IS NULL OR `text4_0_loc8`='','Может быть, мы тоже станем |3-4($r), когда вырастем. Как ты думаешь?',`text4_0_loc8`), `text5_0_loc8`=IF(`text5_0_loc8` IS NULL OR `text5_0_loc8`='','А твоих родителей тоже убили люди-собаки?',`text5_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`,`text3_0_loc8`,`text4_0_loc8`,`text5_0_loc8`) VALUES (14536,'Держись подальше от людей-моржей. Они могут сделать тебе бо-бо.','Кекек возьмет тебя на охоту. Ты будешь приманкой.','Орки смеются над Кекеком и показывают на него пальцем, но однажды Кекек им отомстит.','Знаешь, что? Если Кекек закроет глаза, ты не сможешь его увидеть.','Я поймал трех цыплят на обед. Уверен, ты не $gпоймал:поймала; бы ни одного.','Кекек отобрал любимую игрушку у детеныша длинноязыких. Может быть, она поможет тебе уснуть.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Держись подальше от людей-моржей. Они могут сделать тебе бо-бо.',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Кекек возьмет тебя на охоту. Ты будешь приманкой.',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Орки смеются над Кекеком и показывают на него пальцем, но однажды Кекек им отомстит.',`text2_0_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Знаешь, что? Если Кекек закроет глаза, ты не сможешь его увидеть.',`text3_0_loc8`), `text4_0_loc8`=IF(`text4_0_loc8` IS NULL OR `text4_0_loc8`='','Я поймал трех цыплят на обед. Уверен, ты не $gпоймал:поймала; бы ни одного.',`text4_0_loc8`), `text5_0_loc8`=IF(`text5_0_loc8` IS NULL OR `text5_0_loc8`='','Кекек отобрал любимую игрушку у детеныша длинноязыких. Может быть, она поможет тебе уснуть.',`text5_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14537,'Эти дети остались сиротами после войны, которая разразилась в Низине Шолазар. Ты можешь взять опеку над осиротевшим оракулом или щенком племени Бешеного Сердца. Они будут рады новым друзьям!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Эти дети остались сиротами после войны, которая разразилась в Низине Шолазар. Ты можешь взять опеку над осиротевшим оракулом или щенком племени Бешеного Сердца. Они будут рады новым друзьям!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14538,'Мало сохранить древо, |3-6($r). Ордынцы просто так не отступят...$B$BМы должны уничтожить их!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мало сохранить древо, |3-6($r). Ордынцы просто так не отступят...$B$BМы должны уничтожить их!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14541,'Когда землетрясение разорвало эту землю на части, я служил помощником распорядителя полетов, ухаживал за гиппогрифами. Бедные птички до сих пор не пришли в себя.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Когда землетрясение разорвало эту землю на части, я служил помощником распорядителя полетов, ухаживал за гиппогрифами. Бедные птички до сих пор не пришли в себя.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14543,'Ты чувствуешь?$B$BСкоро наш мир сблизится с миром духов, и наступит День Мертвых. Мы украсим цветами и свечами могилы наших близких, оставим им подношения. Мы хотим поприветствовать их возвращение, пусть и на недолгое время!$B$BИдем со мной! Пускайся в пляс! Давай восславим тех, кто покинул наш мир, но может вернуться в облике призрака, чтобы отведать угощенья и встретиться с теми, кто любит и помнит их.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты чувствуешь?$B$BСкоро наш мир сблизится с миром духов, и наступит День Мертвых. Мы украсим цветами и свечами могилы наших близких, оставим им подношения. Мы хотим поприветствовать их возвращение, пусть и на недолгое время!$B$BИдем со мной! Пускайся в пляс! Давай восславим тех, кто покинул наш мир, но может вернуться в облике призрака, чтобы отведать угощенья и встретиться с теми, кто любит и помнит их.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14544,'Во время празднования Дня мертвых все приходят на кладбища, чтобы порадовать души тех, кого с нами больше нет, и показать им, что они не забыты.$B$BПраздничные мероприятия проходят во всех столицах, где можно отведать угощение, потанцевать, поучаствовать в карнавале и многое другое.','Во время празднования Дня мертвых все приходят на кладбища, чтобы порадовать души тех, кого с нами больше нет, и показать им, что они не забыты.$B$BПраздничные мероприятия проходят во всех столицах, где можно отведать угощение, потанцевать, поучаствовать в карнавале и многое другое.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Во время празднования Дня мертвых все приходят на кладбища, чтобы порадовать души тех, кого с нами больше нет, и показать им, что они не забыты.$B$BПраздничные мероприятия проходят во всех столицах, где можно отведать угощение, потанцевать, поучаствовать в карнавале и многое другое.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Во время празднования Дня мертвых все приходят на кладбища, чтобы порадовать души тех, кого с нами больше нет, и показать им, что они не забыты.$B$BПраздничные мероприятия проходят во всех столицах, где можно отведать угощение, потанцевать, поучаствовать в карнавале и многое другое.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
