INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14552,'Как здорово снова встретиться со своей семьей и пообщаться с друзьями о днях минувших!','Как здорово снова встретиться со своей семьей и пообщаться с друзьями о днях минувших!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Как здорово снова встретиться со своей семьей и пообщаться с друзьями о днях минувших!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Как здорово снова встретиться со своей семьей и пообщаться с друзьями о днях минувших!',`text0_1_loc8`);
