INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14554,'Свинобразы всегда пробирались в наш лагерь, чтобы воровать еду и припасы, но целенаправленные нападения на наши фермы и усадьбы? У такого неистовства должны быть какие-то новые причины.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Свинобразы всегда пробирались в наш лагерь, чтобы воровать еду и припасы, но целенаправленные нападения на наши фермы и усадьбы? У такого неистовства должны быть какие-то новые причины.',`text0_1_loc8`);
