INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14560,'Вспомни годы своего обучения, |3-6($c). У тебя были учителя, к которым ты $gприслушивался:прислушивалась; с уважением, ведь так? Может быть, ты и не $gпроникся:прониклась; к ним личной симпатией, но все равно – они были для тебя авторитетом и источником мудрости. Даже если это не так – попробуй представить себя на моем месте...$b$bКак бы ты $gпоступил:поступила;, если бы вдруг $gпонял:поняла;, что твои наставники не столь мудры, как тебе казалось, и что ты, возможно, знаешь другой путь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вспомни годы своего обучения, |3-6($c). У тебя были учителя, к которым ты $gприслушивался:прислушивалась; с уважением, ведь так? Может быть, ты и не $gпроникся:прониклась; к ним личной симпатией, но все равно – они были для тебя авторитетом и источником мудрости. Даже если это не так – попробуй представить себя на моем месте...$b$bКак бы ты $gпоступил:поступила;, если бы вдруг $gпонял:поняла;, что твои наставники не столь мудры, как тебе казалось, и что ты, возможно, знаешь другой путь?',`text0_0_loc8`);
