INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14562,'Ты $gновенький:новенькая;? Приятно познакомиться. Меня зовут Деллия.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты $gновенький:новенькая;? Приятно познакомиться. Меня зовут Деллия.',`text0_1_loc8`);
