INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14574,'Эй, $gдружище:подруга;, как ты меня $gнашел:нашла;? Надо бы найти убежище понадежнее.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эй, $gдружище:подруга;, как ты меня $gнашел:нашла;? Надо бы найти убежище понадежнее.',`text0_0_loc8`);
