INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14576,'<Глаза Ота Вена, потускневшие и покорные, внезапно вспыхивают воодушевлением. Вы чувствуете, как сила жезла Дартола струится через вас к фурболгу..>$B$BВосстать?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Глаза Ота Вена, потускневшие и покорные, внезапно вспыхивают воодушевлением. Вы чувствуете, как сила жезла Дартола струится через вас к фурболгу..>$B$BВосстать?',`text0_0_loc8`);
