INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14577,'<Глаза Ота Вена загораются странным огнем; он выпрямляется и издает мощный рык, глядя в небеса.>$B$BДА, МЫ БУДЕМ СРАЖАТЬСЯ! МЫ ВОССТАНЕМ ПРОТИВ НАШИХ ПОРАБОТИТЕЛЕЙ!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Глаза Ота Вена загораются странным огнем; он выпрямляется и издает мощный рык, глядя в небеса.>$B$BДА, МЫ БУДЕМ СРАЖАТЬСЯ! МЫ ВОССТАНЕМ ПРОТИВ НАШИХ ПОРАБОТИТЕЛЕЙ!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14579,'Дыши глубже, |3-6($c). Воздух на Громовой вершине разреженный, но зато в нем нет той удушающей пыли, как на земле.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Дыши глубже, |3-6($c). Воздух на Громовой вершине разреженный, но зато в нем нет той удушающей пыли, как на земле.',`text0_0_loc8`);
