INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14580,'Тебе нужна помощь, мой юный друг?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тебе нужна помощь, мой юный друг?',`text0_0_loc8`);
