INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14585,'Ползи, ползи, ползи. Я тебе вот что скажу про Горгала: Горгал ползать не будет!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ползи, ползи, ползи. Я тебе вот что скажу про Горгала: Горгал ползать не будет!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14590,'Эй, босс, вы довольны новой должностью?$B$BМы все считаем, что именно вам удастся сместить этого вонючку Галливикса и получить титул $gторгового магната:торговой магнатши;. Но только чур я вам этого не говорила!$B$BУ нас очень много дел, но мало времени. Надеюсь, что вы готовы!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Эй, босс, вы довольны новой должностью?$B$BМы все считаем, что именно вам удастся сместить этого вонючку Галливикса и получить титул $gторгового магната:торговой магнатши;. Но только чур я вам этого не говорила!$B$BУ нас очень много дел, но мало времени. Надеюсь, что вы готовы!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14591,'Эй, |3-6($r). В последнее время была какая-то прибыль?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эй, |3-6($r). В последнее время была какая-то прибыль?',`text0_0_loc8`);
