INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14593,'Эти обезьяны – настоящая чума!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эти обезьяны – настоящая чума!',`text0_0_loc8`);
