INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14600,'А, вот и $gон:она;... $Gбудущий повелитель:будущая повелительница; стихий! Чему ты хочешь научиться сегодня?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','А, вот и $gон:она;... $Gбудущий повелитель:будущая повелительница; стихий! Чему ты хочешь научиться сегодня?',`text0_0_loc8`);
