INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14601,'Вам не обязательно быть жрецом, чтобы платить десятину. Я с удовольствием приму и ваши деньги, $gгосподин:госпожа;.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Вам не обязательно быть жрецом, чтобы платить десятину. Я с удовольствием приму и ваши деньги, $gгосподин:госпожа;.',`text0_1_loc8`);
