INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14613,'Оглохнуть можно – эта зеленая гарпия не желает умолкнуть ни на минуту. Слушай, я знаю, как водить эту штуку, понятно? Я не идиот!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Оглохнуть можно – эта зеленая гарпия не желает умолкнуть ни на минуту. Слушай, я знаю, как водить эту штуку, понятно? Я не идиот!',`text0_0_loc8`);
