INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14614,'Если бы не я, Борзик уже давно бы врезался прямиком в утес. Балбес криворукий.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Если бы не я, Борзик уже давно бы врезался прямиком в утес. Балбес криворукий.',`text0_1_loc8`);
