INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`,`text2_0_loc8`,`text2_1_loc8`) VALUES (14615,'Прокатимся с ветерком – если ты не боишься пыли.','Прокатимся с ветерком – если ты не боишься пыли.','Держись подальше от края, чемпион. Постарайся не свалиться, ясно?','Держись подальше от края, чемпион. Постарайся не свалиться, ясно?','Я тут работаю.','Я тут работаю.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Прокатимся с ветерком – если ты не боишься пыли.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Прокатимся с ветерком – если ты не боишься пыли.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Держись подальше от края, чемпион. Постарайся не свалиться, ясно?',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Держись подальше от края, чемпион. Постарайся не свалиться, ясно?',`text1_1_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Я тут работаю.',`text2_0_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Я тут работаю.',`text2_1_loc8`);
