INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14616,'<Инженер беспокойно спит на полу.>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Инженер беспокойно спит на полу.>',`text0_0_loc8`);
