INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14617,'Отстань, у меня перерыв.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Отстань, у меня перерыв.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14618,'Добро пожаловать на борт "Зефира"! Вас ожидает самый приятный и плавный полет через Степи. Сядьте поудобнее и наслаждайтесь видами! Ах, нет ничего лучше аромата свежего воздуха, смешанного с запахом горелого масла.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать на борт "Зефира"! Вас ожидает самый приятный и плавный полет через Степи. Сядьте поудобнее и наслаждайтесь видами! Ах, нет ничего лучше аромата свежего воздуха, смешанного с запахом горелого масла.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14619,'Моя звать Толве. Моя за этим местом следить, твоя моя не мешать.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Моя звать Толве. Моя за этим местом следить, твоя моя не мешать.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14621,'Эй, лапочка – наши дирижабли отвезут тебя прямо в Громовой Утес, причем совершенно бесплатно. Кому нужны виверны, когда есть мы, гоблины!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Эй, лапочка – наши дирижабли отвезут тебя прямо в Громовой Утес, причем совершенно бесплатно. Кому нужны виверны, когда есть мы, гоблины!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14622,'Ты представляешь – наконец-то нам разрешили летать по этим краям! Нет ничего лучше путешествий на дирижабле, я прав? И зачем было так волноваться – мы разбили всего один летательный аппарат о скалу во время тестового полета.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты представляешь – наконец-то нам разрешили летать по этим краям! Нет ничего лучше путешествий на дирижабле, я прав? И зачем было так волноваться – мы разбили всего один летательный аппарат о скалу во время тестового полета.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14623,'Чего пялишься, |3-6($r)? $gПришел:Пришла; поиздеваться над пленником?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Чего пялишься, |3-6($r)? $gПришел:Пришла; поиздеваться над пленником?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14625,'Ну? Есть и голова с картой, и сокровище, которое можно выкопать.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ну? Есть и голова с картой, и сокровище, которое можно выкопать.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14628,'Если ты хочешь узнать больше о приготовлении традиционных блюд Пиршества странников, поговори с одной из хозяек.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если ты хочешь узнать больше о приготовлении традиционных блюд Пиршества странников, поговори с одной из хозяек.',`text0_0_loc8`);
