INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14630,'Ты хочешь поучаствовать в Пиршестве странников вместе с нами?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты хочешь поучаствовать в Пиршестве странников вместе с нами?',`text0_0_loc8`);
