INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14633,'Добро пожаловать к пиршественному столу! Пожалуйста, присаживайся!$B$BОтведай наших угощений – наверняка они тебе понравятся.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Добро пожаловать к пиршественному столу! Пожалуйста, присаживайся!$B$BОтведай наших угощений – наверняка они тебе понравятся.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14634,'Добро пожаловать к пиршественному столу! Пожалуйста, присаживайся!$B$BОтведай наших угощений – наверняка они тебе понравятся.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Добро пожаловать к пиршественному столу! Пожалуйста, присаживайся!$B$BОтведай наших угощений – наверняка они тебе понравятся.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14635,'Пиршество странников, подумать только. Я еще могу понять тауренов, которые в очередной раз хотят выразить благодарность и уважение Вождю, но каким боком к этому причастны Отрекшиеся?$B$BМне всегда казалось, что они оставили сентиментальные традиции в прошлой жизни.','Пиршество странников, подумать только. Я еще могу понять тауренов, которые в очередной раз хотят выразить благодарность и уважение Вождю, но каким боком к этому причастны Отрекшиеся?$B$BМне всегда казалось, что они оставили сентиментальные традиции в прошлой жизни.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Пиршество странников, подумать только. Я еще могу понять тауренов, которые в очередной раз хотят выразить благодарность и уважение Вождю, но каким боком к этому причастны Отрекшиеся?$B$BМне всегда казалось, что они оставили сентиментальные традиции в прошлой жизни.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Пиршество странников, подумать только. Я еще могу понять тауренов, которые в очередной раз хотят выразить благодарность и уважение Вождю, но каким боком к этому причастны Отрекшиеся?$B$BМне всегда казалось, что они оставили сентиментальные традиции в прошлой жизни.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14636,'Говорят, Пиршество странников – это повод вспомнить об удаче, которая нам сопутствовала, и поделиться ей с остальными.$B$BНам повезло найти этот мир и его отважных обитателей; мне кажется правильным, что мы делимся своими знаниями и силой с новообретенными союзниками.','Говорят, Пиршество странников – это повод вспомнить об удаче, которая нам сопутствовала, и поделиться ей с остальными.$B$BНам повезло найти этот мир и его отважных обитателей; мне кажется правильным, что мы делимся своими знаниями и силой с новообретенными союзниками.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Говорят, Пиршество странников – это повод вспомнить об удаче, которая нам сопутствовала, и поделиться ей с остальными.$B$BНам повезло найти этот мир и его отважных обитателей; мне кажется правильным, что мы делимся своими знаниями и силой с новообретенными союзниками.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Говорят, Пиршество странников – это повод вспомнить об удаче, которая нам сопутствовала, и поделиться ей с остальными.$B$BНам повезло найти этот мир и его отважных обитателей; мне кажется правильным, что мы делимся своими знаниями и силой с новообретенными союзниками.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14637,'Люди такие бестолковые, что засунь их в драный мешок – даже не найдут, как из него выбраться, но в чем в чем, а в кулинарии они разбираются! Пиршество странников? Я только за!','Люди такие бестолковые, что засунь их в драный мешок – даже не найдут, как из него выбраться, но в чем в чем, а в кулинарии они разбираются! Пиршество странников? Я только за!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Люди такие бестолковые, что засунь их в драный мешок – даже не найдут, как из него выбраться, но в чем в чем, а в кулинарии они разбираются! Пиршество странников? Я только за!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Люди такие бестолковые, что засунь их в драный мешок – даже не найдут, как из него выбраться, но в чем в чем, а в кулинарии они разбираются! Пиршество странников? Я только за!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14639,'Пиршество странников? Скорее, Услада идиотов!$B$BПодумать только, сотни ящиков с едой, и все раздается задаром... задаром! В голове не укладывается.$B$BНаверное, стоит вложить часть средств в разведение индеек... во всяком случае, курицы себя окупили. Откуда, по-твоему, берутся яйца на день Чудесного сада?','Пиршество странников? Скорее, Услада идиотов!$B$BПодумать только, сотни ящиков с едой, и все раздается задаром... задаром! В голове не укладывается.$B$BНаверное, стоит вложить часть средств в разведение индеек... во всяком случае, курицы себя окупили. Откуда, по-твоему, берутся яйца на день Чудесного сада?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Пиршество странников? Скорее, Услада идиотов!$B$BПодумать только, сотни ящиков с едой, и все раздается задаром... задаром! В голове не укладывается.$B$BНаверное, стоит вложить часть средств в разведение индеек... во всяком случае, курицы себя окупили. Откуда, по-твоему, берутся яйца на день Чудесного сада?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Пиршество странников? Скорее, Услада идиотов!$B$BПодумать только, сотни ящиков с едой, и все раздается задаром... задаром! В голове не укладывается.$B$BНаверное, стоит вложить часть средств в разведение индеек... во всяком случае, курицы себя окупили. Откуда, по-твоему, берутся яйца на день Чудесного сада?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14640,'Говорят, Пиршество странников – это повод вспомнить об удаче, которая нам сопутствовала, и поделиться ей с остальными.$B$BМы надеемся, что к празднованию присоединятся все наши великие союзники.','Говорят, Пиршество странников – это повод вспомнить об удаче, которая нам сопутствовала, и поделиться ей с остальными.$B$BМы надеемся, что к празднованию присоединятся все наши великие союзники.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Говорят, Пиршество странников – это повод вспомнить об удаче, которая нам сопутствовала, и поделиться ей с остальными.$B$BМы надеемся, что к празднованию присоединятся все наши великие союзники.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Говорят, Пиршество странников – это повод вспомнить об удаче, которая нам сопутствовала, и поделиться ей с остальными.$B$BМы надеемся, что к празднованию присоединятся все наши великие союзники.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14641,'Пиршество странников так странно контрастирует с человеческой природой... Кто бы мог подумать, что эти себялюбивые людишки способны восхвалять дух единства и щедрости?$B$BМеня это радует. Дарнасу стоит перенять подобную традицию.','Пиршество странников так странно контрастирует с человеческой природой... Кто бы мог подумать, что эти себялюбивые людишки способны восхвалять дух единства и щедрости?$B$BМеня это радует. Дарнасу стоит перенять подобную традицию.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Пиршество странников так странно контрастирует с человеческой природой... Кто бы мог подумать, что эти себялюбивые людишки способны восхвалять дух единства и щедрости?$B$BМеня это радует. Дарнасу стоит перенять подобную традицию.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Пиршество странников так странно контрастирует с человеческой природой... Кто бы мог подумать, что эти себялюбивые людишки способны восхвалять дух единства и щедрости?$B$BМеня это радует. Дарнасу стоит перенять подобную традицию.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14642,'Как хорошо, что орки и таурены стали союзниками, ибо наши сильные стороны дополняют друг друга. Мы так рады участвовать в этом празднике наравне с остальными.$B$BДаже Отрекшиеся – желанные гости за праздничным столом, хотя я так и не понял, что именно они отмечают...','Как хорошо, что орки и таурены стали союзниками, ибо наши сильные стороны дополняют друг друга. Мы так рады участвовать в этом празднике наравне с остальными.$B$BДаже Отрекшиеся – желанные гости за праздничным столом, хотя я так и не поняла, что именно они отмечают...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Как хорошо, что орки и таурены стали союзниками, ибо наши сильные стороны дополняют друг друга. Мы так рады участвовать в этом празднике наравне с остальными.$B$BДаже Отрекшиеся – желанные гости за праздничным столом, хотя я так и не понял, что именно они отмечают...',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Как хорошо, что орки и таурены стали союзниками, ибо наши сильные стороны дополняют друг друга. Мы так рады участвовать в этом празднике наравне с остальными.$B$BДаже Отрекшиеся – желанные гости за праздничным столом, хотя я так и не поняла, что именно они отмечают...',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14643,'Говорят, Пиршество странников – это повод вспомнить об удаче, которая нам сопутствовала, и поделиться ей с остальными.$B$BВ Мулгоре, среди Орды, мы нашли новый дом и обрели друзей, с которыми нам хочется отметить этот день.$B$BХочется надеяться, что к празднованию присоединятся все наши союзники.','Говорят, Пиршество странников – это повод вспомнить об удаче, которая нам сопутствовала, и поделиться ей с остальными.$B$BВ Мулгоре, среди Орды, мы нашли новый дом и обрели друзей, с которыми нам хочется отметить этот день.$B$BХочется надеяться, что к празднованию присоединятся все наши союзники.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Говорят, Пиршество странников – это повод вспомнить об удаче, которая нам сопутствовала, и поделиться ей с остальными.$B$BВ Мулгоре, среди Орды, мы нашли новый дом и обрели друзей, с которыми нам хочется отметить этот день.$B$BХочется надеяться, что к празднованию присоединятся все наши союзники.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Говорят, Пиршество странников – это повод вспомнить об удаче, которая нам сопутствовала, и поделиться ей с остальными.$B$BВ Мулгоре, среди Орды, мы нашли новый дом и обрели друзей, с которыми нам хочется отметить этот день.$B$BХочется надеяться, что к празднованию присоединятся все наши союзники.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14644,'Эти таурены знают толк в еде! Видишь, какие столы накрыли?$B$BОбожраться и не жить... а потом встать из могилы и съесть еще!','Эти таурены знают толк в еде! Видишь, какие столы накрыли?$B$BОбожраться и не жить... а потом встать из могилы и съесть еще!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эти таурены знают толк в еде! Видишь, какие столы накрыли?$B$BОбожраться и не жить... а потом встать из могилы и съесть еще!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Эти таурены знают толк в еде! Видишь, какие столы накрыли?$B$BОбожраться и не жить... а потом встать из могилы и съесть еще!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14647,'На пиршественном столе представлены все пять видов угощений Пиршества странников – по одному напротив каждого стула.$B$BПока ты сидишь за столом, ты можешь лакомиться выбранным блюдом сколько угодно и передавать его своим соседям по столу. Не забывай делиться со своими друзьями!$B$BКак только наешься досыта, ты ощутишь особый прилив сил, который дарует каждое угощение.$B$BВпридачу, если ты отведаешь все пять блюд, на тебя снизойдет дух пиршества!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','На пиршественном столе представлены все пять видов угощений Пиршества странников – по одному напротив каждого стула.$B$BПока ты сидишь за столом, ты можешь лакомиться выбранным блюдом сколько угодно и передавать его своим соседям по столу. Не забывай делиться со своими друзьями!$B$BКак только наешься досыта, ты ощутишь особый прилив сил, который дарует каждое угощение.$B$BВпридачу, если ты отведаешь все пять блюд, на тебя снизойдет дух пиршества!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14648,'На пиршественном столе представлены все пять видов угощений Пиршества странников – по одному напротив каждого стула.$B$BПока ты сидишь за столом, ты можешь лакомиться выбранным блюдом сколько угодно и передавать его своим соседям по столу. Не забывай делиться со своими друзьями!$B$BКак только наешься досыта, ты ощутишь особый прилив сил, который дарует каждое угощение.$B$BВпридачу, если ты отведаешь все пять блюд, на тебя снизойдет дух пиршества!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','На пиршественном столе представлены все пять видов угощений Пиршества странников – по одному напротив каждого стула.$B$BПока ты сидишь за столом, ты можешь лакомиться выбранным блюдом сколько угодно и передавать его своим соседям по столу. Не забывай делиться со своими друзьями!$B$BКак только наешься досыта, ты ощутишь особый прилив сил, который дарует каждое угощение.$B$BВпридачу, если ты отведаешь все пять блюд, на тебя снизойдет дух пиршества!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14649,'<Стоящий перед вами тролль с головы до ног покрыт ранами и шрамами, включая свежий порез, проходящий через все лицо к вспухшей губе.>$b$bПфифет.$b$bКак ты знаешь, тфолли ефдят на яфферах. Пфоблема ф том, фтобы собфать яфферов для тфенирофки. И тут пояфляюфь я. Я – лофец яфферов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Стоящий перед вами тролль с головы до ног покрыт ранами и шрамами, включая свежий порез, проходящий через все лицо к вспухшей губе.>$b$bПфифет.$b$bКак ты знаешь, тфолли ефдят на яфферах. Пфоблема ф том, фтобы собфать яфферов для тфенирофки. И тут пояфляюфь я. Я – лофец яфферов.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14652,'Будь $gостофофен:остофофна; с яфферами, они быфают офень-офень умными.$b$bНа пфофлой неделе двое иф них повалили меня, а тфетий бил палкой.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Будь $gостофофен:остофофна; с яфферами, они быфают офень-офень умными.$b$bНа пфофлой неделе двое иф них повалили меня, а тфетий бил палкой.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14658,'Крендля Набейкармана ты найдешь рядом с платформой дирижаблей на западе Вершины Духов. Мне не нравятся эти гоблинские летающие штуки... но, если тебя не укачивает, то до Оргриммара долетишь благополучно.','Крендля Набейкармана ты найдешь рядом с платформой дирижаблей на западе Вершины Духов. Мне не нравятся эти гоблинские летающие штуки... но, если тебя не укачивает, то до Оргриммара долетишь благополучно.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Крендля Набейкармана ты найдешь рядом с платформой дирижаблей на западе Вершины Духов. Мне не нравятся эти гоблинские летающие штуки... но, если тебя не укачивает, то до Оргриммара долетишь благополучно.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Крендля Набейкармана ты найдешь рядом с платформой дирижаблей на западе Вершины Духов. Мне не нравятся эти гоблинские летающие штуки... но, если тебя не укачивает, то до Оргриммара долетишь благополучно.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14659,'Истинный крестоносец – не просто герой, ведущий битву со злом. Он образец для подражания, защитник слабых, борец за справедливость.$B$BЯ Верховный крестоносец, и мой долг – отправлять подобных людей на свершение достойных подвигов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Истинный крестоносец – не просто герой, ведущий битву со злом. Он образец для подражания, защитник слабых, борец за справедливость.$B$BЯ Верховный крестоносец, и мой долг – отправлять подобных людей на свершение достойных подвигов.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14661,'Некоторые награды достойны только тех героев, которые получили титул Крестоносца, которых превозносит Серебряный Авангард или собственные союзники.$B$BСам Тирион поручил мне найти этих достойных рыцарей и вознаградить по заслугам.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Некоторые награды достойны только тех героев, которые получили титул Крестоносца, которых превозносит Серебряный Авангард или собственные союзники.$B$BСам Тирион поручил мне найти этих достойных рыцарей и вознаградить по заслугам.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14664,'Добро пожаловать, чемпионы! Соберитесь с силами, ибо впереди вас ждут испытания крестоносца!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать, чемпионы! Соберитесь с силами, ибо впереди вас ждут испытания крестоносца!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14665,'Ну что, вы готовы принять первый вызов?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ну что, вы готовы принять первый вызов?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14667,'Мы отобрали самых лучших чудовищ. Таким и проиграть не стыдно.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы отобрали самых лучших чудовищ. Таким и проиграть не стыдно.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14668,'Превосходно! Дайте знать, когда будете готовы к следующей попытке.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Превосходно! Дайте знать, когда будете готовы к следующей попытке.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14669,'Ты еще недостаточно $gсилен:сильна;, чтобы биться на Острове Завоеваний. Возвращайся, когда наберешься опыта.','Ты еще недостаточно $gсилен:сильна;, чтобы биться на Острове Завоеваний. Возвращайся, когда наберешься опыта.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты еще недостаточно $gсилен:сильна;, чтобы биться на Острове Завоеваний. Возвращайся, когда наберешься опыта.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты еще недостаточно $gсилен:сильна;, чтобы биться на Острове Завоеваний. Возвращайся, когда наберешься опыта.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14670,'На Острове Завоеваний много ценных ресурсов, которые не должны попасть в руки Орды. Ты присоединишься к нам на поле боя?','На Острове Завоеваний много ценных ресурсов, которые не должны попасть в руки Орды. Ты присоединишься к нам на поле боя?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','На Острове Завоеваний много ценных ресурсов, которые не должны попасть в руки Орды. Ты присоединишься к нам на поле боя?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','На Острове Завоеваний много ценных ресурсов, которые не должны попасть в руки Орды. Ты присоединишься к нам на поле боя?',`text0_1_loc8`);
