INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14675,'Ты $gготов:готова; сражаться за Альянс, |3-6($c)?','Ты $gготов:готова; сражаться за Альянс, |3-6($c)?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты $gготов:готова; сражаться за Альянс, |3-6($c)?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты $gготов:готова; сражаться за Альянс, |3-6($c)?',`text0_1_loc8`);
