INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14678,'Молодцы! Вы доблестно сражались с этими чудовищами! Правда, я слышал, что следующее испытание будет еще суровее.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Молодцы! Вы доблестно сражались с этими чудовищами! Правда, я слышал, что следующее испытание будет еще суровее.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14679,'Пока нам удается контролировать Лорда Джараксуса, но путы не смогут удерживать его долго.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Пока нам удается контролировать Лорда Джараксуса, но путы не смогут удерживать его долго.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14680,'Скоро вы это выясните. Готовы?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Скоро вы это выясните. Готовы?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`,`text1_1_loc8`,`text2_1_loc8`,`text3_1_loc8`,`text4_1_loc8`,`text5_1_loc8`,`text6_1_loc8`,`text7_1_loc8`) VALUES (14681,'Привет, малыш! Как я выгляжу?','Я так по тебе скучала! Где тебя носило?$B$BНу что, будешь отвечать или просто стоять там?','Тебе нравится мой костюм? Он для вечеринки. Я записала его на твой счет.','Еще один парень приставал ко мне. Какой наглец!$B$BТы поколотишь его, малыш? Спасибо. Я люблю тебя!','Я мечтаю о том дне, когда ты наконец-то окажешься на самом верху. Подумать только, меня будут называть "госпожа торговая принцесса"!$B$BНе говоря уже о том, что я смогу купить все, что захочу!!!','Береги себя. Говорят, что в залив прибыли пираты из Южных морей.$B$BХм, быть может, мне стоит самой сходить и проверить...','Может, устроим романтический пикник на вершине горы Каджаро?$B$BТолько не забудь захватить мое любимое шампанское!','У тебя озорной вид. Что у тебя на уме, малыш?$B$BА?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Привет, малыш! Как я выгляжу?',`text0_1_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Я так по тебе скучала! Где тебя носило?$B$BНу что, будешь отвечать или просто стоять там?',`text1_1_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Тебе нравится мой костюм? Он для вечеринки. Я записала его на твой счет.',`text2_1_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','Еще один парень приставал ко мне. Какой наглец!$B$BТы поколотишь его, малыш? Спасибо. Я люблю тебя!',`text3_1_loc8`), `text4_1_loc8`=IF(`text4_1_loc8` IS NULL OR `text4_1_loc8`='','Я мечтаю о том дне, когда ты наконец-то окажешься на самом верху. Подумать только, меня будут называть "госпожа торговая принцесса"!$B$BНе говоря уже о том, что я смогу купить все, что захочу!!!',`text4_1_loc8`), `text5_1_loc8`=IF(`text5_1_loc8` IS NULL OR `text5_1_loc8`='','Береги себя. Говорят, что в залив прибыли пираты из Южных морей.$B$BХм, быть может, мне стоит самой сходить и проверить...',`text5_1_loc8`), `text6_1_loc8`=IF(`text6_1_loc8` IS NULL OR `text6_1_loc8`='','Может, устроим романтический пикник на вершине горы Каджаро?$B$BТолько не забудь захватить мое любимое шампанское!',`text6_1_loc8`), `text7_1_loc8`=IF(`text7_1_loc8` IS NULL OR `text7_1_loc8`='','У тебя озорной вид. Что у тебя на уме, малыш?$B$BА?',`text7_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14682,'Отлично! Дайте знак, и я освобожу его от сдерживающих чар.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Отлично! Дайте знак, и я освобожу его от сдерживающих чар.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`,`text3_0_loc8`,`text4_0_loc8`,`text5_0_loc8`,`text6_0_loc8`) VALUES (14683,'Я обожаю тебя! Ты мне веришь? Веришь, детка?','Радость моя, где тебя носило? Ты же знаешь, как я волнуюсь, когда ты не даешь о себе знать!','Как тебе мой пресс? Я только что из качалки.$B$BЯ – отличный кусок мяса!','Эти женщины – просто мои друзья.','Мне нравится твой костюм!','Я помню, что обещал тебе это вчера и позавчера. Завтра вечером мы с тобой точно пойдем в какое-нибудь хорошее заведение!','Говорят, что в порт прибыли пираты из Южных морей. Береги себя!$B$BПо слухам, у них есть даже женщины-пираты! Хм, возможно, мне стоит пойти и самому проверить. Ну, просто убедиться, что там тебе ничто не угрожает.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я обожаю тебя! Ты мне веришь? Веришь, детка?',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Радость моя, где тебя носило? Ты же знаешь, как я волнуюсь, когда ты не даешь о себе знать!',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Как тебе мой пресс? Я только что из качалки.$B$BЯ – отличный кусок мяса!',`text2_0_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Эти женщины – просто мои друзья.',`text3_0_loc8`), `text4_0_loc8`=IF(`text4_0_loc8` IS NULL OR `text4_0_loc8`='','Мне нравится твой костюм!',`text4_0_loc8`), `text5_0_loc8`=IF(`text5_0_loc8` IS NULL OR `text5_0_loc8`='','Я помню, что обещал тебе это вчера и позавчера. Завтра вечером мы с тобой точно пойдем в какое-нибудь хорошее заведение!',`text5_0_loc8`), `text6_0_loc8`=IF(`text6_0_loc8` IS NULL OR `text6_0_loc8`='','Говорят, что в порт прибыли пираты из Южных морей. Береги себя!$B$BПо слухам, у них есть даже женщины-пираты! Хм, возможно, мне стоит пойти и самому проверить. Ну, просто убедиться, что там тебе ничто не угрожает.',`text6_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14688,'Ты $gготов:готова; принять первый вызов, |3-6($c)?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты $gготов:готова; принять первый вызов, |3-6($c)?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14689,'Ты желаешь научиться верховой езде?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты желаешь научиться верховой езде?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14690,'Я провел годы, служа в этом захолустном уголке, изучая местность и ожидая благоприятного момента. Наконец, время пришло. Сейчас вся мощь Оргриммара собрана в Азшаре, откуда мы проникнем в Ясеневый лес и получим господство на всем континенте. Добро пожаловать на фронт, |3-6($c).') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я провел годы, служа в этом захолустном уголке, изучая местность и ожидая благоприятного момента. Наконец, время пришло. Сейчас вся мощь Оргриммара собрана в Азшаре, откуда мы проникнем в Ясеневый лес и получим господство на всем континенте. Добро пожаловать на фронт, |3-6($c).',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14692,'<Гиппогриф нетерпеливо хлопает крыльями – он уже готов к бою!>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Гиппогриф нетерпеливо хлопает крыльями – он уже готов к бою!>',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14693,'Да? Что тебе нужно?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Да? Что тебе нужно?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14694,'Проваливай, приятель, иначе кулак старины Чипа Идейла вступит в соприкосновение с твоим лицом!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Проваливай, приятель, иначе кулак старины Чипа Идейла вступит в соприкосновение с твоим лицом!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14695,'Добро пожаловать в Первый банк Кезана, дочернюю компанию банка торговцев Трюмных Вод Южных морей.$B$BЧем могу помочь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать в Первый банк Кезана, дочернюю компанию банка торговцев Трюмных Вод Южных морей.$B$BЧем могу помочь?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14697,'Эй! Похоже, ты $gчеловек:женщина; с хорошим вкусом.$B$BЧем могу помочь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эй! Похоже, ты $gчеловек:женщина; с хорошим вкусом.$B$BЧем могу помочь?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14698,'Крутые блестяшки для крутых клиентов!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Крутые блестяшки для крутых клиентов!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14700,'Смотри, с чем мне приходится работать. Забо может творить чудеса?$B$B<Забо вздыхает.>$B$BДа, да. Забо думает, что сможет с тобой кое-что сделать.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Смотри, с чем мне приходится работать. Забо может творить чудеса?$B$B<Забо вздыхает.>$B$BДа, да. Забо думает, что сможет с тобой кое-что сделать.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14702,'О, ты только посмотри, что сотворил Забо. Это же шедевр!$B$BКонечно, такой костюм нужно было бы продать более достойному клиенту, но, к сожалению, Забо нужны деньги.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','О, ты только посмотри, что сотворил Забо. Это же шедевр!$B$BКонечно, такой костюм нужно было бы продать более достойному клиенту, но, к сожалению, Забо нужны деньги.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14703,'У меня этих солнечных очков завались!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','У меня этих солнечных очков завались!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14705,'Вот, держи. Это мой лучший товар, и я отдаю его задешево!$B$BТы будешь круто смотреться в этих очках!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Вот, держи. Это мой лучший товар, и я отдаю его задешево!$B$BТы будешь круто смотреться в этих очках!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14713,'Нет, я разумное существо, и требую относиться ко мне с уважением. Я могу сварить целебное зелье из мыльной воды и пары одуванчиков, но это не то, чем мне хотелось бы похвастаться.$b$bВ общем, если хочешь что-нибудь купить, поговори с Патрисией.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Нет, я разумное существо, и требую относиться ко мне с уважением. Я могу сварить целебное зелье из мыльной воды и пары одуванчиков, но это не то, чем мне хотелось бы похвастаться.$b$bВ общем, если хочешь что-нибудь купить, поговори с Патрисией.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14723,'Духи стихий мудры. Они были здесь задолго до нас, и будут пребывать в этом мире, когда мы исчезнем с лица земли. Мы должны прислушиваться к ним.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Духи стихий мудры. Они были здесь задолго до нас, и будут пребывать в этом мире, когда мы исчезнем с лица земли. Мы должны прислушиваться к ним.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14724,'Духи стихий окружают нас. Мы всегда должны прислушиваться к их словам. Я видел, что случается, когда мы игнорируем их предупреждения.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Духи стихий окружают нас. Мы всегда должны прислушиваться к их словам. Я видел, что случается, когда мы игнорируем их предупреждения.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14729,'Убирайся прочь, насекомое. Это не твои земли. Не буди во мне зверя.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Убирайся прочь, насекомое. Это не твои земли. Не буди во мне зверя.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14731,'Спасибо за то, что помогли мне разобраться с этими ленивыми кретинами, $gначальник:начальница;.$B$BЯ вам так скажу: теперь, когда мы уже не рабы троллей, нам нужно быть с ними построже.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Спасибо за то, что помогли мне разобраться с этими ленивыми кретинами, $gначальник:начальница;.$B$BЯ вам так скажу: теперь, когда мы уже не рабы троллей, нам нужно быть с ними построже.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14735,'Да, |3-6($c)?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да, |3-6($c)?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14736,'Некоторые искатели приключений не желают получать опыт за свои подвиги, чтобы навсегда закрепиться на том уровне, на котором они находятся сегодня.$B$BЯ могу оказать тебе такую услугу... не за просто так, разумеется.$B$BОднако запомни – как только деньги окажутся у меня в руках, ты больше не будешь получать опыт. Никакой. Никогда.$B$BВпрочем, если ты передумаешь, я могу вернуть все назад – за определенную плату.','Некоторые искатели приключений не желают получать опыт за свои подвиги, чтобы навсегда закрепиться на том уровне, на котором они находятся сегодня.$B$BЯ могу оказать тебе такую услугу... не за просто так, разумеется.$B$BОднако запомни – как только деньги окажутся у меня в руках, ты больше не будешь получать опыт. Никакой. Никогда.$B$BВпрочем, если ты передумаешь, я могу вернуть все назад – за определенную плату.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Некоторые искатели приключений не желают получать опыт за свои подвиги, чтобы навсегда закрепиться на том уровне, на котором они находятся сегодня.$B$BЯ могу оказать тебе такую услугу... не за просто так, разумеется.$B$BОднако запомни – как только деньги окажутся у меня в руках, ты больше не будешь получать опыт. Никакой. Никогда.$B$BВпрочем, если ты передумаешь, я могу вернуть все назад – за определенную плату.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Некоторые искатели приключений не желают получать опыт за свои подвиги, чтобы навсегда закрепиться на том уровне, на котором они находятся сегодня.$B$BЯ могу оказать тебе такую услугу... не за просто так, разумеется.$B$BОднако запомни – как только деньги окажутся у меня в руках, ты больше не будешь получать опыт. Никакой. Никогда.$B$BВпрочем, если ты передумаешь, я могу вернуть все назад – за определенную плату.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14738,'Сегодня вы потрясли всех зрителей на этой арене. Настало время, когда вас признают истинными чемпионами турнира.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Сегодня вы потрясли всех зрителей на этой арене. Настало время, когда вас признают истинными чемпионами турнира.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14739,'Монумент гудит и потрескивает от наполняющей его древней энергии.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Монумент гудит и потрескивает от наполняющей его древней энергии.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14740,'Перед тобой самая современная горная разработка в мире. Только простофили будут долбить в горе проход, чтобы добраться до минералов под ней. Мы передвинули всю гору целиком! Теперь можно просто загребать ценные металлы лопатой.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Перед тобой самая современная горная разработка в мире. Только простофили будут долбить в горе проход, чтобы добраться до минералов под ней. Мы передвинули всю гору целиком! Теперь можно просто загребать ценные металлы лопатой.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14742,'Наконец у нас есть возможность исследовать здешние руины… При условии, что эти крохоборы не окажутся быстрее нас.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Наконец у нас есть возможность исследовать здешние руины… При условии, что эти крохоборы не окажутся быстрее нас.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14745,'В настоящее время меня беспокоят руины, которые окружают озеро Меннар, что к востоку от нас. Тысячи лет назад Академия Меннар была одним из лучших мест для изучения тайных искусств. Это было красивое здание, расположенное террасами вокруг тихого озера. Место для учебы и спокойного созерцания. Именно там мои предки впервые открыли потенциал магической энергии Источника Вечности.$b$bПрости, тебе, наверное, скучно? Вот уже несколько десятков лет я изучаю историю тайной магии и забываю, что не все разделяют мою страсть.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','В настоящее время меня беспокоят руины, которые окружают озеро Меннар, что к востоку от нас. Тысячи лет назад Академия Меннар была одним из лучших мест для изучения тайных искусств. Это было красивое здание, расположенное террасами вокруг тихого озера. Место для учебы и спокойного созерцания. Именно там мои предки впервые открыли потенциал магической энергии Источника Вечности.$b$bПрости, тебе, наверное, скучно? Вот уже несколько десятков лет я изучаю историю тайной магии и забываю, что не все разделяют мою страсть.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14746,'Достаточно сказать, что Академия использовала вновь открытые силы с большой осторожностью – сохранившиеся документы свидетельствуют о том, что маги опасались возникновения зависимости, от которой моя раса страдает и по сей день.$b$bЭти ограничения стали причиной противостояния между магами Меннар и королевы Азшары с ее высокорожденными лакеями, которые с диким рвением искали еще большей власти, пренебрегая осторожностью и углубляясь во все более опасные приложения магического искусства.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Достаточно сказать, что Академия использовала вновь открытые силы с большой осторожностью – сохранившиеся документы свидетельствуют о том, что маги опасались возникновения зависимости, от которой моя раса страдает и по сей день.$b$bЭти ограничения стали причиной противостояния между магами Меннар и королевы Азшары с ее высокорожденными лакеями, которые с диким рвением искали еще большей власти, пренебрегая осторожностью и углубляясь во все более опасные приложения магического искусства.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14747,'В то время, когда Пылающий Легион начал свое вторжение, маги Академии Меннар впали в немилость королевы. Их могущественные силы могли бы быть очень ценными в условиях грядущей войны, но они отказались уступить, когда город пал.$b$bВместо того, чтобы присоединиться к силам сопротивления, они остались в стороне, воздвигнув магические барьеры и превратив свою тихую обитель в крепость. В первые ужасные дни вторжения к Академии Меннар устремились беженцы, и выжившие собрались, чтобы организовать оборону.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','В то время, когда Пылающий Легион начал свое вторжение, маги Академии Меннар впали в немилость королевы. Их могущественные силы могли бы быть очень ценными в условиях грядущей войны, но они отказались уступить, когда город пал.$b$bВместо того, чтобы присоединиться к силам сопротивления, они остались в стороне, воздвигнув магические барьеры и превратив свою тихую обитель в крепость. В первые ужасные дни вторжения к Академии Меннар устремились беженцы, и выжившие собрались, чтобы организовать оборону.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14748,'Выстоять? Против атаки всего авангарда Легиона? Маловероятно!$b$bНет, о том, что случилось дальше, история умалчивает… так как выжить никому не удалось. Яростные демоны оставили после себя лишь руины, которые ты видишь вокруг, и все секреты Академии похоронены в земле Азшары.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Выстоять? Против атаки всего авангарда Легиона? Маловероятно!$b$bНет, о том, что случилось дальше, история умалчивает… так как выжить никому не удалось. Яростные демоны оставили после себя лишь руины, которые ты видишь вокруг, и все секреты Академии похоронены в земле Азшары.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14749,'Мне нравится ход твоих мыслей, |3-6($r)!$b$bДо недавних пор магическая энергия земли Академии привлекала синих драконов, и у меня не было возможности изучить это. Теперь драконы повсюду, но хуже всего то, что эти маленькие зеленокожие дикари хотят разрыть руины и сделать здесь хранилище ракетного топлива! Знания, утраченные десять тысяч лет назад, в одном шаге от того, чтобы быть потерянными безвозвратно. Мы должны действовать быстро.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мне нравится ход твоих мыслей, |3-6($r)!$b$bДо недавних пор магическая энергия земли Академии привлекала синих драконов, и у меня не было возможности изучить это. Теперь драконы повсюду, но хуже всего то, что эти маленькие зеленокожие дикари хотят разрыть руины и сделать здесь хранилище ракетного топлива! Знания, утраченные десять тысяч лет назад, в одном шаге от того, чтобы быть потерянными безвозвратно. Мы должны действовать быстро.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14751,'Ветер яростно завывает на этих утесах, и вся жизнь давно покинула эту часть Ледяной Короны. Однако еще есть надежда на то, что все вернется, и лишь потому я все еще хожу по этой земле. Настанет день, и кроны деревьев будут шуметь над нами.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ветер яростно завывает на этих утесах, и вся жизнь давно покинула эту часть Ледяной Короны. Однако еще есть надежда на то, что все вернется, и лишь потому я все еще хожу по этой земле. Настанет день, и кроны деревьев будут шуметь над нами.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14752,'Гампы разрешили мне стать продавщицей в их магазине! А я так люблю цветы!$B$B<Маленькая Аделина внезапно поворачивается к вам и делает серьезное лицо.>$B$BА ты любишь цветы??') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Гампы разрешили мне стать продавщицей в их магазине! А я так люблю цветы!$B$B<Маленькая Аделина внезапно поворачивается к вам и делает серьезное лицо.>$B$BА ты любишь цветы??',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14757,'Для первого испытания требуется, чтобы ты $gоседлал:оседлала; боевого коня Серебряного Авангарда. Этих скакунов можно найти вдоль стены Колизея.$b$bБыстрее, выбирай коня и возвращайся ко мне.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Для первого испытания требуется, чтобы ты $gоседлал:оседлала; боевого коня Серебряного Авангарда. Этих скакунов можно найти вдоль стены Колизея.$b$bБыстрее, выбирай коня и возвращайся ко мне.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14759,'Магнатавры не так глупы, как кажутся. Присматривать за Гормоком довольно сложно, но не беспокойся – он крепко привязан и никуда не денется до начала состязаний.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Магнатавры не так глупы, как кажутся. Присматривать за Гормоком довольно сложно, но не беспокойся – он крепко привязан и никуда не денется до начала состязаний.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14760,'Я забочусь об этих существах, ведь Гормок не может этого сделать. Не по душе мне эта бойня, но у него хотя бы будет шанс сразиться в бою.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я забочусь об этих существах, ведь Гормок не может этого сделать. Не по душе мне эта бойня, но у него хотя бы будет шанс сразиться в бою.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14761,'Йети – безжалостные, могучие звери, а этот один из самых сильных в своем роде. Мы подмешиваем ему снотворные травы в еду. $b$bНо я не стал бы рассчитывать на то, что он уснет на ринге.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Йети – безжалостные, могучие звери, а этот один из самых сильных в своем роде. Мы подмешиваем ему снотворные травы в еду. $b$bНо я не стал бы рассчитывать на то, что он уснет на ринге.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14762,'Я... Я утратил контроль над шахтами!$B$BПожалуйста, $gгосподин:госпожа;, не увольняйте меня!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я... Я утратил контроль над шахтами!$B$BПожалуйста, $gгосподин:госпожа;, не увольняйте меня!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`,`text3_0_loc8`,`text4_0_loc8`,`text5_0_loc8`) VALUES (14766,'Калифа – ты все еще жива! Найди какое-нибудь укрытие, этим… штукам нет конца!','У меня все еще идет кровь? Я не могу… я больше не могу продолжать. Ты $gвидел:видела; кого-нибудь из верховных магов?','Хм. Полагаю, это последствия магии. Что посеешь – то и пожнешь… Нам всем поможет Элуна.','Калифа! Верховный маг Селвин хотела тебя видеть. Она должна быть где-то поблизости…','Эти существа… их так много. Так много убитых! Посмотри на горящую Азшару. Что сделали высокорожденные?','Почему я не убежал вместе с остальными? Академия окружена. Мы здесь в ловушке.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Калифа – ты все еще жива! Найди какое-нибудь укрытие, этим… штукам нет конца!',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','У меня все еще идет кровь? Я не могу… я больше не могу продолжать. Ты $gвидел:видела; кого-нибудь из верховных магов?',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Хм. Полагаю, это последствия магии. Что посеешь – то и пожнешь… Нам всем поможет Элуна.',`text2_0_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Калифа! Верховный маг Селвин хотела тебя видеть. Она должна быть где-то поблизости…',`text3_0_loc8`), `text4_0_loc8`=IF(`text4_0_loc8` IS NULL OR `text4_0_loc8`='','Эти существа… их так много. Так много убитых! Посмотри на горящую Азшару. Что сделали высокорожденные?',`text4_0_loc8`), `text5_0_loc8`=IF(`text5_0_loc8` IS NULL OR `text5_0_loc8`='','Почему я не убежал вместе с остальными? Академия окружена. Мы здесь в ловушке.',`text5_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`,`text1_1_loc8`,`text2_1_loc8`,`text3_1_loc8`,`text4_1_loc8`,`text5_1_loc8`) VALUES (14767,'Я должна поддерживать эти кристаллы заряженными.','Моя сила… иссякает. Калифа, пожалуйста, скажи мне, что у верховных магов был запасной план…','Я больше не могу удерживать этот щит. Калифа, хоть кто-нибудь из нас сможет пережить это?','Этих существ еще больше! Откуда они появляются? Что происходит в столице?','Калифа! Быстрее – верховный маг Селвин хотела тебя видеть, она сказала, что это срочно. Может быть, мы сможем справиться с этим?','Это все, что я могу сделать, чтобы поддерживать кристаллы заряженными. Найди одного из верховных магов, Калифа! Я едва держусь…') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я должна поддерживать эти кристаллы заряженными.',`text0_1_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Моя сила… иссякает. Калифа, пожалуйста, скажи мне, что у верховных магов был запасной план…',`text1_1_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Я больше не могу удерживать этот щит. Калифа, хоть кто-нибудь из нас сможет пережить это?',`text2_1_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','Этих существ еще больше! Откуда они появляются? Что происходит в столице?',`text3_1_loc8`), `text4_1_loc8`=IF(`text4_1_loc8` IS NULL OR `text4_1_loc8`='','Калифа! Быстрее – верховный маг Селвин хотела тебя видеть, она сказала, что это срочно. Может быть, мы сможем справиться с этим?',`text4_1_loc8`), `text5_1_loc8`=IF(`text5_1_loc8` IS NULL OR `text5_1_loc8`='','Это все, что я могу сделать, чтобы поддерживать кристаллы заряженными. Найди одного из верховных магов, Калифа! Я едва держусь…',`text5_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14770,'<Мерцающий призрак не осознает, что вы здесь. Она погружена в свой собственный мир, в события, которые разыгрались тысячи лет назад.>') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','<Мерцающий призрак не осознает, что вы здесь. Она погружена в свой собственный мир, в события, которые разыгрались тысячи лет назад.>',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14771,'Когда придет время нанести удар по Цитадели Ледяной Короны, я хочу быть в первых рядах!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Когда придет время нанести удар по Цитадели Ледяной Короны, я хочу быть в первых рядах!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14777,'Приветствую, |3-6($c).$B$BВ настоящий момент Крепость Ледяных Оков находится под контролем Орды, и битва уже началась! Торопись поддержать наши войска!','Приветствую, |3-6($c).$B$BВ настоящий момент Крепость Ледяных Оков находится под контролем Орды, и битва уже началась! Торопись поддержать наши войска!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приветствую, |3-6($c).$B$BВ настоящий момент Крепость Ледяных Оков находится под контролем Орды, и битва уже началась! Торопись поддержать наши войска!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Приветствую, |3-6($c).$B$BВ настоящий момент Крепость Ледяных Оков находится под контролем Орды, и битва уже началась! Торопись поддержать наши войска!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14779,'Мы уже давно заботимся об этих червях. Думаю, к началу турнира они будут в прекрасной форме. Кстати, тебе придется сразиться сразу с двумя йормунгарами!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы уже давно заботимся об этих червях. Думаю, к началу турнира они будут в прекрасной форме. Кстати, тебе придется сразиться сразу с двумя йормунгарами!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14781,'Приветствую, |3-6($c).$B$BВ настоящий момент Крепость Ледяных Оков находится под контролем Альянса, и битва уже началась! Торопись поддержать наши войска!','Приветствую, |3-6($c).$B$BВ настоящий момент Крепость Ледяных Оков находится под контролем Альянса, и битва уже началась! Торопись поддержать наши войска!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приветствую, |3-6($c).$B$BВ настоящий момент Крепость Ледяных Оков находится под контролем Альянса, и битва уже началась! Торопись поддержать наши войска!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Приветствую, |3-6($c).$B$BВ настоящий момент Крепость Ледяных Оков находится под контролем Альянса, и битва уже началась! Торопись поддержать наши войска!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14783,'Доброго вам дня, $gсэр:мэм;! Чем могу помочь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Доброго вам дня, $gсэр:мэм;! Чем могу помочь?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14785,'Этот провал в пространственно-временном континиуме выглядит чрезвычайно странно. Перед глазами мелькают различные картины. Только смельчак может отважиться сделать шаг в эту бездну...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Этот провал в пространственно-временном континиуме выглядит чрезвычайно странно. Перед глазами мелькают различные картины. Только смельчак может отважиться сделать шаг в эту бездну...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14787,'Ты! Да, я к тебе обращаюсь!$b$bВзгляни на меня и ощути дрожь волнения, ибо вскоре мир услышит имя Вилфреда Непопамса! Как только я закончу читать заклинание призыва, никто больше не усомнится в моем непревзойденном мастерстве!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты! Да, я к тебе обращаюсь!$b$bВзгляни на меня и ощути дрожь волнения, ибо вскоре мир услышит имя Вилфреда Непопамса! Как только я закончу читать заклинание призыва, никто больше не усомнится в моем непревзойденном мастерстве!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14792,'Приветствую, |3-6($c).$B$BОглядись по сторонам. Не $gзадумывался:задумывалась; ли ты, что все это может значить?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приветствую, |3-6($c).$B$BОглядись по сторонам. Не $gзадумывался:задумывалась; ли ты, что все это может значить?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14793,'Вершительница правосудия Мариэль Чистосердечная попросила нас помочь ей с проведением турнира. Те, кто завоевал звание чемпиона, также должны внести свой вклад в это дело.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Вершительница правосудия Мариэль Чистосердечная попросила нас помочь ей с проведением турнира. Те, кто завоевал звание чемпиона, также должны внести свой вклад в это дело.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14794,'Теперь, когда строительство Колизея Серебряного Авангарда завершено, Вершительница правосудия Мариэль Чистосердечная просит нас помочь ей с организацией и охраной турнира. Правда, она хочет, чтобы мы работали вместе с этими бездельниками из Серебряного союза, а они только путаются у нас под ногами.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Теперь, когда строительство Колизея Серебряного Авангарда завершено, Вершительница правосудия Мариэль Чистосердечная просит нас помочь ей с организацией и охраной турнира. Правда, она хочет, чтобы мы работали вместе с этими бездельниками из Серебряного союза, а они только путаются у нас под ногами.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14795,'Измена! Я погиб…$B$BВиновный заплатит за это! Я обещаю…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Измена! Я погиб…$B$BВиновный заплатит за это! Я обещаю…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14801,'Шепот ветра донес до меня весть о том, что придет |3-6($r)-|3-6($c), $gкоторый:которая; поможет мне в том, с чем не справились многие.$B$BМожет быть, это ты?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Шепот ветра донес до меня весть о том, что придет |3-6($r)-|3-6($c), $gкоторый:которая; поможет мне в том, с чем не справились многие.$B$BМожет быть, это ты?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14803,'А, вот и мой любимый чернокнижник! Какую страшную тайну мне прошептать тебе на этот раз?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','А, вот и мой любимый чернокнижник! Какую страшную тайну мне прошептать тебе на этот раз?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14804,'Мы можем действовать мягко вне поля боя, но только в битве проявляется наша истинная сила.','Мы можем действовать мягко вне поля боя, но только в битве проявляется наша истинная сила.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы можем действовать мягко вне поля боя, но только в битве проявляется наша истинная сила.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мы можем действовать мягко вне поля боя, но только в битве проявляется наша истинная сила.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (14806,'Отличный день для того, чтобы узнать что-нибудь о мистических искусствах. Вы согласны со мной, $gгосподин:госпожа; $n?','Отличный день для того, чтобы узнать что-нибудь о мистических искусствах. Вы согласны со мной, $gгосподин:госпожа; $n?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Отличный день для того, чтобы узнать что-нибудь о мистических искусствах. Вы согласны со мной, $gгосподин:госпожа; $n?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Отличный день для того, чтобы узнать что-нибудь о мистических искусствах. Вы согласны со мной, $gгосподин:госпожа; $n?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14808,'Тебя ждет блестящее будущее, $gмой мальчик:моя девочка;! Чему ты хочешь поучиться сегодня?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тебя ждет блестящее будущее, $gмой мальчик:моя девочка;! Чему ты хочешь поучиться сегодня?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14809,'Я потерпела кораблекрушение и оказалась на острове, который кишмя кишит обезьянами-бомбистками. Что же будет дальше?.. Может, тут еще и вулкан есть?!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я потерпела кораблекрушение и оказалась на острове, который кишмя кишит обезьянами-бомбистками. Что же будет дальше?.. Может, тут еще и вулкан есть?!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14811,'Вы видите меня? Как это вам удается, босс?$B$BПохоже, мне придется поработать над этим.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Вы видите меня? Как это вам удается, босс?$B$BПохоже, мне придется поработать над этим.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14814,'В таком случае я дам сигнал Тириону.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','В таком случае я дам сигнал Тириону.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14815,'Это была жестокая битва. Давно уже мне не приходилось видеть столь яростного сражения. Потрясающе!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Это была жестокая битва. Давно уже мне не приходилось видеть столь яростного сражения. Потрясающе!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14816,'Не могу дождаться! Похоже, все приготовления завершены, и новый раунд вот-вот начнется!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не могу дождаться! Похоже, все приготовления завершены, и новый раунд вот-вот начнется!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14819,'Мы понесли огромные потери, когда готовили ваше следующее испытание!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы понесли огромные потери, когда готовили ваше следующее испытание!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14820,'Валь\'киры действуют потрясающе слаженно. Неудивительно, что захватить их поодиночке довольно сложно.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Валь\'киры действуют потрясающе слаженно. Неудивительно, что захватить их поодиночке довольно сложно.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14821,'Поверьте мне на слово! Вам предстоит сразиться с двумя самыми сильными лейтенантами валь\'кир, прислужниками Артаса!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Поверьте мне на слово! Вам предстоит сразиться с двумя самыми сильными лейтенантами валь\'кир, прислужниками Артаса!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14822,'Я надеюсь, что это вам удастся!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я надеюсь, что это вам удастся!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14824,'Теперь, когда строительство Колизея Серебряного Авангарда завершено, сенешаль просит нас помочь ей с проведением турнира. Те, кто завоевал звание чемпиона, также должны внести свой вклад в это дело.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Теперь, когда строительство Колизея Серебряного Авангарда завершено, сенешаль просит нас помочь ей с проведением турнира. Те, кто завоевал звание чемпиона, также должны внести свой вклад в это дело.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14826,'Когда я проходил обучение стражника в Оргриммаре, Тралл предупреждал нас, что с врагами надо быть бдительным и терпеливым.$b$bНо наги угрожают захватить этот полуостров, а Тралл больше не мой полководец. Настало время пролить кровь, |3-6($c).') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Когда я проходил обучение стражника в Оргриммаре, Тралл предупреждал нас, что с врагами надо быть бдительным и терпеливым.$b$bНо наги угрожают захватить этот полуостров, а Тралл больше не мой полководец. Настало время пролить кровь, |3-6($c).',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`,`text1_1_loc8`,`text2_1_loc8`) VALUES (14827,'Зачем ты мешаешь мне работать? Я жду объяснений!','У тебя должна быть веская причина, чтобы беспокоить меня, ничтожество!','В чем дело? Что тебе нужно от меня, $gничтожный:ничтожная;?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Зачем ты мешаешь мне работать? Я жду объяснений!',`text0_1_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','У тебя должна быть веская причина, чтобы беспокоить меня, ничтожество!',`text1_1_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','В чем дело? Что тебе нужно от меня, $gничтожный:ничтожная;?',`text2_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14828,'Превосходно, вы проявили себя как истинные чемпионы. Если вы примкнете к Серебряному Авангарду, мы обязательно победим Плеть!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Превосходно, вы проявили себя как истинные чемпионы. Если вы примкнете к Серебряному Авангарду, мы обязательно победим Плеть!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14829,'Вы заслужили похвалу из уст самого Тириона. Кстати, вы не заметили – здесь резко похолодало!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вы заслужили похвалу из уст самого Тириона. Кстати, вы не заметили – здесь резко похолодало!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14832,'Не обижайся, но тебе здесь нечего делать. Ступай в укрытие и найди себе безопасное место.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не обижайся, но тебе здесь нечего делать. Ступай в укрытие и найди себе безопасное место.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14834,'Твои старания не будут забыты, $n! Я позабочусь об этом.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Твои старания не будут забыты, $n! Я позабочусь об этом.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14835,'Прости, дитя мое, но ты не можешь познать мудрость древних, а я ничему не могу тебя научить.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Прости, дитя мое, но ты не можешь познать мудрость древних, а я ничему не могу тебя научить.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14839,'Тихо, ни звука! Здесь повсюду воргены.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тихо, ни звука! Здесь повсюду воргены.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14840,'Разумеется, я поделюсь с тобой своими знаниями, особенно если это поможет одолеть воргенов.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Разумеется, я поделюсь с тобой своими знаниями, особенно если это поможет одолеть воргенов.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14841,'Прости, но обучить тебя будет непросто. Потребуются годы ментальной подготовки, чтобы ты $gсмог:смогла; постигнуть всю силу тайной магии.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Прости, но обучить тебя будет непросто. Потребуются годы ментальной подготовки, чтобы ты $gсмог:смогла; постигнуть всю силу тайной магии.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14843,'Клянусь, я тут не при чем. И не смотри на меня так, ясно?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Клянусь, я тут не при чем. И не смотри на меня так, ясно?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14844,'Даже сейчас, в самые темные времена, мудрость Света укажет тебе путь.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Даже сейчас, в самые темные времена, мудрость Света укажет тебе путь.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (14845,'Не бойся. Свет с тобой, |3-6($c). Сегодня тебе ничего не угрожает.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Не бойся. Свет с тобой, |3-6($c). Сегодня тебе ничего не угрожает.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14846,'Возможно, мы их разозлили.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Возможно, мы их разозлили.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14848,'Если бы ты $gмог: могла; хоть на секунду заглянуть в мой разум... тебя свели бы с ума хранящиеся там секреты.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если бы ты $gмог: могла; хоть на секунду заглянуть в мой разум... тебя свели бы с ума хранящиеся там секреты.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14849,'Да, презренное отродье?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да, презренное отродье?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14850,'Добро пожаловать, чемпионы! Вы готовы пройти испытание великого крестоносца? Только самые могучие и умелые рыцари могут принять участие в этих состязаниях. Для начала придется пройти обычное испытание крестоносца.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать, чемпионы! Вы готовы пройти испытание великого крестоносца? Только самые могучие и умелые рыцари могут принять участие в этих состязаниях. Для начала придется пройти обычное испытание крестоносца.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14853,'Испытание великого крестоносца гораздо сложнее обычного испытания. Помимо того, что тебя ожидают более крепкие противники, ты не сможешь совершать более 50 попыток в неделю. Однако после завершения испытания тебя ждет особый сундук с наградами. По-моему, ради этого стоит постараться. Ну что, ты $gготов:готова; испытать свои силы?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Испытание великого крестоносца гораздо сложнее обычного испытания. Помимо того, что тебя ожидают более крепкие противники, ты не сможешь совершать более 50 попыток в неделю. Однако после завершения испытания тебя ждет особый сундук с наградами. По-моему, ради этого стоит постараться. Ну что, ты $gготов:готова; испытать свои силы?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14860,'<Килаг делает знак, чтобы вы говорили шепотом.>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Килаг делает знак, чтобы вы говорили шепотом.>',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14865,'Теперь, когда испытание крестоносца позади, я рекомендую тебе задуматься о том, чтобы пройти испытание великого крестоносца. Пройти его могут только самые сильные и отважные искатели приключений, но их ждет достойная награда!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Теперь, когда испытание крестоносца позади, я рекомендую тебе задуматься о том, чтобы пройти испытание великого крестоносца. Пройти его могут только самые сильные и отважные искатели приключений, но их ждет достойная награда!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14866,'Поздравляю! Когда будете готовы, воспользуйтесь этим порталом в Даларан!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Поздравляю! Когда будете готовы, воспользуйтесь этим порталом в Даларан!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14868,'Вы, двое, будьте осторожны! Нас осталось совсем мало!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вы, двое, будьте осторожны! Нас осталось совсем мало!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14869,'Что?! Ты что думаешь, у меня тут склад этих шахтеров?$B$BНеужели там так опасно?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что?! Ты что думаешь, у меня тут склад этих шахтеров?$B$BНеужели там так опасно?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14871,'Бери ключи и беги к гиролету!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Бери ключи и беги к гиролету!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14873,'Мне было явлено будущее, |3-6($r).$B$BЗемли кентавров будут навеки осквернены, если мы не будем действовать быстро.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мне было явлено будущее, |3-6($r).$B$BЗемли кентавров будут навеки осквернены, если мы не будем действовать быстро.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14874,'Тьфу! Работа гномов, сразу видно.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тьфу! Работа гномов, сразу видно.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14875,'Гоблин? Похоже, мне уже мерещится разная небывальщина. Тром-Ка – и спасибо тебе, малыш!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Гоблин? Похоже, мне уже мерещится разная небывальщина. Тром-Ка – и спасибо тебе, малыш!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text1_0_loc8`,`text3_0_loc8`) VALUES (14879,'Кто бы мог подумать, что после всего пережитого мы окажемся здесь?','Похоже, мы здорово влипли. Сможешь вытащить нас отсюда?') ON DUPLICATE KEY UPDATE `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Кто бы мог подумать, что после всего пережитого мы окажемся здесь?',`text1_0_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Похоже, мы здорово влипли. Сможешь вытащить нас отсюда?',`text3_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text2_1_loc8`,`text3_1_loc8`) VALUES (14880,'Посиди со мной. Пожарим крабов, споем что-нибудь.','Я столько для тебя сделала! А ты что делаешь, чтобы вытащить нас с этого острова?') ON DUPLICATE KEY UPDATE `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Посиди со мной. Пожарим крабов, споем что-нибудь.',`text2_1_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','Я столько для тебя сделала! А ты что делаешь, чтобы вытащить нас с этого острова?',`text3_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14881,'<Гоббер рычит.>$B$BМоя теперь банкир!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Гоббер рычит.>$B$BМоя теперь банкир!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (14888,'Привет! От тебя не пахнет рыбой. Мне нравится.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Привет! От тебя не пахнет рыбой. Мне нравится.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
