INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (14918,'Почтовый ящик стоит в Торговом квартале рядом с дешевым складом гробов, который по какому-то недоразумению назвали таверной.','Почтовый ящик стоит в Торговом квартале рядом с дешевым складом гробов, который по какому-то недоразумению назвали таверной.','Почтовый ящик? Это тебе надо идти к таверне, в центр города. Она на верхнем ярусе.','Почтовый ящик? Это тебе надо идти к таверне, в центр города. Она на верхнем ярусе.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Почтовый ящик стоит в Торговом квартале рядом с дешевым складом гробов, который по какому-то недоразумению назвали таверной.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Почтовый ящик стоит в Торговом квартале рядом с дешевым складом гробов, который по какому-то недоразумению назвали таверной.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Почтовый ящик? Это тебе надо идти к таверне, в центр города. Она на верхнем ярусе.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Почтовый ящик? Это тебе надо идти к таверне, в центр города. Она на верхнем ярусе.',`text1_1_loc8`);
