INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (14926,'$gНашел:Нашла; кого спрашивать про чернокнижников. Иди в Квартал Магов, на внешнее кольцо. И не попадайся мне больше!','$gНашел:Нашла; кого спрашивать про чернокнижников. Иди в Квартал Магов, на внешнее кольцо. И не попадайся мне больше!','Чернокнижники сидят в главном здании Квартала Магов. Надеюсь, ты не воспользуешься этой информацией для того, чтобы создать нам неприятности.','Чернокнижники сидят в главном здании Квартала Магов. Надеюсь, ты не воспользуешься этой информацией для того, чтобы создать нам неприятности.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','$gНашел:Нашла; кого спрашивать про чернокнижников. Иди в Квартал Магов, на внешнее кольцо. И не попадайся мне больше!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','$gНашел:Нашла; кого спрашивать про чернокнижников. Иди в Квартал Магов, на внешнее кольцо. И не попадайся мне больше!',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Чернокнижники сидят в главном здании Квартала Магов. Надеюсь, ты не воспользуешься этой информацией для того, чтобы создать нам неприятности.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Чернокнижники сидят в главном здании Квартала Магов. Надеюсь, ты не воспользуешься этой информацией для того, чтобы создать нам неприятности.',`text1_1_loc8`);
