-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (15110,'Стихии благоволят тебе. Какие знания ты жаждешь обрести?','Стихии благоволят тебе. Какие знания ты жаждешь обрести?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Стихии благоволят тебе. Какие знания ты жаждешь обрести?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Стихии благоволят тебе. Какие знания ты жаждешь обрести?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (15111,'Стихии коварны, друг, и могут натворить много бед, будучи во власти непосвященного. Прости, но я не могу возложить на тебя такую ответственность.','Стихии коварны, друг, и могут натворить много бед, будучи во власти непосвященного. Прости, но я не могу возложить на тебя такую ответственность.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Стихии коварны, друг, и могут натворить много бед, будучи во власти непосвященного. Прости, но я не могу возложить на тебя такую ответственность.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Стихии коварны, друг, и могут натворить много бед, будучи во власти непосвященного. Прости, но я не могу возложить на тебя такую ответственность.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15112,'Я просто счастлив иметь так много верных и преданных учеников. Моя работа была бы невозможной без постоянного притока подопытных кроликов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я просто счастлив иметь так много верных и преданных учеников. Моя работа была бы невозможной без постоянного притока подопытных кроликов.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`,`text3_0_loc8`) VALUES (15117,'Мой командир был жестоко убит прямо на моих глазах, мои братья погибали рядом со мной – я больше не могу воевать. Мне так стыдно, |3-6($c). Я не отомстил за них.','Нам, пехотинцам, приказали снова идти в атаку, прямо на эту стену штыков. Я не могу, |3-6($c). Оружие выскальзывает у меня из рук, ноги не двигаются.$b$bЯ опозорен.','Не смотри на меня, |3-6($r). Я опозорил Орду. Со мной все кончено.','Ни один орк не должен бежать с поля боя, как это сделал я. Оставьте меня наедине с моим позором. О если бы я умер в этой башне! Но я боюсь узнать, что подумают мои потомки о моей трусости.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мой командир был жестоко убит прямо на моих глазах, мои братья погибали рядом со мной – я больше не могу воевать. Мне так стыдно, |3-6($c). Я не отомстил за них.',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Нам, пехотинцам, приказали снова идти в атаку, прямо на эту стену штыков. Я не могу, |3-6($c). Оружие выскальзывает у меня из рук, ноги не двигаются.$b$bЯ опозорен.',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Не смотри на меня, |3-6($r). Я опозорил Орду. Со мной все кончено.',`text2_0_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Ни один орк не должен бежать с поля боя, как это сделал я. Оставьте меня наедине с моим позором. О если бы я умер в этой башне! Но я боюсь узнать, что подумают мои потомки о моей трусости.',`text3_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15119,'Ваш йормунгар может двигаться лишь до тех пор, пока он не показался из-под снега. Как только он вылезает на поверхность, он может использовать мощную атаку ядом, которая игнорирует доспех железного Колосса. Будьте готовы нырнуть под снег, чтобы избегать самых сокрушительных ударов Колосса.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ваш йормунгар может двигаться лишь до тех пор, пока он не показался из-под снега. Как только он вылезает на поверхность, он может использовать мощную атаку ядом, которая игнорирует доспех железного Колосса. Будьте готовы нырнуть под снег, чтобы избегать самых сокрушительных ударов Колосса.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15121,'Еще ни одна команда не отыгрывалась при таком счете!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Еще ни одна команда не отыгрывалась при таком счете!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15123,'Ракетный ускоритель $gпотерял:потеряла;? А по карманам $gхлопал:хлопала;?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ракетный ускоритель $gпотерял:потеряла;? А по карманам $gхлопал:хлопала;?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15126,'Вот эти холмы и тайные тропы – это мой дом. В течение многих лет я здесь охотилась.$b$bНо я никогда не думала, что здесь же я буду участвовать в войне.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Вот эти холмы и тайные тропы – это мой дом. В течение многих лет я здесь охотилась.$b$bНо я никогда не думала, что здесь же я буду участвовать в войне.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15127,'Много лет назад моя деревня была атакована воинами Зловещего Тотема. Боль, гнев, утрата – мое сердце так и не избавилось от этого груза.$b$bТеперь я чувствую себя на своем месте, помогая тем, кто так же, как я лишился своего дома из-за чужой жестокости.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Много лет назад моя деревня была атакована воинами Зловещего Тотема. Боль, гнев, утрата – мое сердце так и не избавилось от этого груза.$b$bТеперь я чувствую себя на своем месте, помогая тем, кто так же, как я лишился своего дома из-за чужой жестокости.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15128,'С этих тайных троп мы можем сеять ужас в стане врага внизу.$b$bНет ничего особо почетного в таких наскоках и отходах, но хороший воин знает, как вывести врага из равновесия.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','С этих тайных троп мы можем сеять ужас в стане врага внизу.$b$bНет ничего особо почетного в таких наскоках и отходах, но хороший воин знает, как вывести врага из равновесия.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15131,'Чего ты хочешь, |3-6($c)?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Чего ты хочешь, |3-6($c)?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15132,'Тролли странно себя ведут, $n. Не нравится мне все это.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тролли странно себя ведут, $n. Не нравится мне все это.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15134,'Я как раз разыскиваю |3-3($c) вроде тебя! Я испытываю новое летающее устройство, и мне очень нужна твоя помощь!\r\n\r\nЗакрепи вот это снаряжение под доспехами. Потом нажми кнопку сбоку и лети куда хочешь!\r\n\r\nТолько не пытайся присвоить себе мое изобретение! Каждый комплект снаряжения снабжен Транспонстером 8000, а панель управления от него остается у меня. Если ты улетишь слишком далеко, транспортер отключит ракету, и ты не сможешь подняться в воздух, пока не вернешься. Все ясно?\r\n\r\nТак-так, куда опять подевался договор об ответственности?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я как раз разыскиваю |3-3($c) вроде тебя! Я испытываю новое летающее устройство, и мне очень нужна твоя помощь!\r\n\r\nЗакрепи вот это снаряжение под доспехами. Потом нажми кнопку сбоку и лети куда хочешь!\r\n\r\nТолько не пытайся присвоить себе мое изобретение! Каждый комплект снаряжения снабжен Транспонстером 8000, а панель управления от него остается у меня. Если ты улетишь слишком далеко, транспортер отключит ракету, и ты не сможешь подняться в воздух, пока не вернешься. Все ясно?\r\n\r\nТак-так, куда опять подевался договор об ответственности?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15135,'Враг превосходит нас численностью, мы отрезаны от Перекрестка и Дуротара. Но каждый орк стоит десяти трусов из Альянса.$b$bМы окружим их и выпотрошим, как свиней.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Враг превосходит нас численностью, мы отрезаны от Перекрестка и Дуротара. Но каждый орк стоит десяти трусов из Альянса.$b$bМы окружим их и выпотрошим, как свиней.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15138,'Драться, да. Умереть? Весьма вероятно. Но мы не уступим им нашей земли, |3-6($c). Пусть мы одеты в лохмотья, а оружие никуда не годится.$b$bНо это наша земля! Наши союзники таурены знают здесь каждую тропинку, каждую расщелину, каждый проход между холмами. Мы спустимся с возвышенности, откуда они будут ждать нас меньше всего, а потом исчезнем в холмах, как фантомы. Страх будет нашим оружием, и мы без устали будем драться с ними.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Драться, да. Умереть? Весьма вероятно. Но мы не уступим им нашей земли, |3-6($c). Пусть мы одеты в лохмотья, а оружие никуда не годится.$b$bНо это наша земля! Наши союзники таурены знают здесь каждую тропинку, каждую расщелину, каждый проход между холмами. Мы спустимся с возвышенности, откуда они будут ждать нас меньше всего, а потом исчезнем в холмах, как фантомы. Страх будет нашим оружием, и мы без устали будем драться с ними.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15139,'О, небо. Похоже, дела плохи.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','О, небо. Похоже, дела плохи.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`,`text2_0_loc8`,`text2_1_loc8`,`text3_0_loc8`,`text3_1_loc8`,`text4_0_loc8`,`text4_1_loc8`,`text5_0_loc8`,`text5_1_loc8`,`text7_0_loc8`,`text7_1_loc8`) VALUES (15140,'Как думаешь, когда мы сможем отправиться? Мне надо возвращаться к работе.','Как думаешь, когда мы сможем отправиться? Мне надо возвращаться к работе.','Откуда берутся все эти трогги? Где там можно жить под землей?','Откуда берутся все эти трогги? Где там можно жить под землей?','Постарайся устроиться поудобнее. Железняк никого не выпустит, пока с троггами не будет покончено.','Постарайся устроиться поудобнее. Железняк никого не выпустит, пока с троггами не будет покончено.','Есть какие-то новости снаружи? Я слышал, тролли тоже разбушевались.','Есть какие-то новости снаружи? Я слышала, тролли тоже разбушевались.','Здесь уже яблоку негде упасть. Я плохо себя чувствую в ограниченных пространствах.','Здесь уже яблоку негде упасть. Я плохо себя чувствую в ограниченных пространствах.','Тебе не кажется, что при землетрясении масштабов катаклизма, последнее место, где тебе захочется быть, это ВНУТРИ?','Тебе не кажется, что при землетрясении масштабов катаклизма, последнее место, где тебе захочется быть, это ВНУТРИ?','Я думал, я навсегда останусь здесь взаперти. Хмельной фестиваль уже начался?','Я думала, я навсегда останусь здесь взаперти. Хмельной фестиваль уже начался?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Как думаешь, когда мы сможем отправиться? Мне надо возвращаться к работе.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Как думаешь, когда мы сможем отправиться? Мне надо возвращаться к работе.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Откуда берутся все эти трогги? Где там можно жить под землей?',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Откуда берутся все эти трогги? Где там можно жить под землей?',`text1_1_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Постарайся устроиться поудобнее. Железняк никого не выпустит, пока с троггами не будет покончено.',`text2_0_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Постарайся устроиться поудобнее. Железняк никого не выпустит, пока с троггами не будет покончено.',`text2_1_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Есть какие-то новости снаружи? Я слышал, тролли тоже разбушевались.',`text3_0_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','Есть какие-то новости снаружи? Я слышала, тролли тоже разбушевались.',`text3_1_loc8`), `text4_0_loc8`=IF(`text4_0_loc8` IS NULL OR `text4_0_loc8`='','Здесь уже яблоку негде упасть. Я плохо себя чувствую в ограниченных пространствах.',`text4_0_loc8`), `text4_1_loc8`=IF(`text4_1_loc8` IS NULL OR `text4_1_loc8`='','Здесь уже яблоку негде упасть. Я плохо себя чувствую в ограниченных пространствах.',`text4_1_loc8`), `text5_0_loc8`=IF(`text5_0_loc8` IS NULL OR `text5_0_loc8`='','Тебе не кажется, что при землетрясении масштабов катаклизма, последнее место, где тебе захочется быть, это ВНУТРИ?',`text5_0_loc8`), `text5_1_loc8`=IF(`text5_1_loc8` IS NULL OR `text5_1_loc8`='','Тебе не кажется, что при землетрясении масштабов катаклизма, последнее место, где тебе захочется быть, это ВНУТРИ?',`text5_1_loc8`), `text7_0_loc8`=IF(`text7_0_loc8` IS NULL OR `text7_0_loc8`='','Я думал, я навсегда останусь здесь взаперти. Хмельной фестиваль уже начался?',`text7_0_loc8`), `text7_1_loc8`=IF(`text7_1_loc8` IS NULL OR `text7_1_loc8`='','Я думала, я навсегда останусь здесь взаперти. Хмельной фестиваль уже начался?',`text7_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15141,'Черт, здесь полно камней!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Черт, здесь полно камней!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15145,'Как поживаешь, |3-6($c)?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Как поживаешь, |3-6($c)?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15146,'Во мраке ночи высоко в небо взметнулись языки пламени. Я потерял все. Все.$b$BЗачем им понадобилось сжигать таверну?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Во мраке ночи высоко в небо взметнулись языки пламени. Я потерял все. Все.$b$BЗачем им понадобилось сжигать таверну?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15147,'<Кельсува не смотрит вам в глаза.>$b$bЯ сбежал в разгар битвы, но только после того, как освободил всех животных из конюшни.$b$bЯ не мог взять их с собой. Они бросились врассыпную и исчезли в дыму…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Кельсува не смотрит вам в глаза.>$b$bЯ сбежал в разгар битвы, но только после того, как освободил всех животных из конюшни.$b$bЯ не мог взять их с собой. Они бросились врассыпную и исчезли в дыму…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`,`text3_0_loc8`,`text4_0_loc8`,`text5_0_loc8`,`text6_0_loc8`,`text7_0_loc8`) VALUES (15148,'Вулканическая лава! Покупайте куски вулканической лавы!','Распродажа вулканической лавы! Лава горячая, только что с горы! Вы хочете лавы – ее есть у меня!','Вулканическая лава по низким ценам! Берите, она вам понравится!','Покупайте вулканическую лаву!.. Кошки ее обожают!','Привезите домой кусочек Катаклизма! Распродажа лавы! Горячая, горячая, ГОРЯЧАЯ ЛАВА!','Вам нужно пресс-папье? Вам нужно чем-то подпереть дверь? Разбить стекло? Бам, бам, БАМ! Куски вулканической лавы!','Вулканическая лава! Миллион и один способ применения. Лава, джезва, сауна, панама...','Вулканическая лава! Уникальное ограниченное предложение! Сертификаты качества и все такое!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вулканическая лава! Покупайте куски вулканической лавы!',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Распродажа вулканической лавы! Лава горячая, только что с горы! Вы хочете лавы – ее есть у меня!',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Вулканическая лава по низким ценам! Берите, она вам понравится!',`text2_0_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Покупайте вулканическую лаву!.. Кошки ее обожают!',`text3_0_loc8`), `text4_0_loc8`=IF(`text4_0_loc8` IS NULL OR `text4_0_loc8`='','Привезите домой кусочек Катаклизма! Распродажа лавы! Горячая, горячая, ГОРЯЧАЯ ЛАВА!',`text4_0_loc8`), `text5_0_loc8`=IF(`text5_0_loc8` IS NULL OR `text5_0_loc8`='','Вам нужно пресс-папье? Вам нужно чем-то подпереть дверь? Разбить стекло? Бам, бам, БАМ! Куски вулканической лавы!',`text5_0_loc8`), `text6_0_loc8`=IF(`text6_0_loc8` IS NULL OR `text6_0_loc8`='','Вулканическая лава! Миллион и один способ применения. Лава, джезва, сауна, панама...',`text6_0_loc8`), `text7_0_loc8`=IF(`text7_0_loc8` IS NULL OR `text7_0_loc8`='','Вулканическая лава! Уникальное ограниченное предложение! Сертификаты качества и все такое!',`text7_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15149,'На нашем родном языке "Уна\'фе" означает "Приют". Но название больше не соответствует действительности. С тех самых пор, как мы основали этот лагерь, эти странные джунгли грозят поглотить нас.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','На нашем родном языке "Уна\'фе" означает "Приют". Но название больше не соответствует действительности. С тех самых пор, как мы основали этот лагерь, эти странные джунгли грозят поглотить нас.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15150,'Они напали на Таурахо, когда самые сильные жители лагеря были на охоте. Каким-то чудом в рядах воинов Альянса образовалась брешь, через которую мне и кое-кому еще удалось вынести детей…$b$b<Таване замолкает, пытаясь не заплакать на глазах у детей.>') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Они напали на Таурахо, когда самые сильные жители лагеря были на охоте. Каким-то чудом в рядах воинов Альянса образовалась брешь, через которую мне и кое-кому еще удалось вынести детей…$b$b<Таване замолкает, пытаясь не заплакать на глазах у детей.>',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15155,'Это похоже на останки Талориена Искателя Рассвета, последнего владельца Кель\'Делара.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Это похоже на останки Талориена Искателя Рассвета, последнего владельца Кель\'Делара.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15157,'Моих сил надолго не хватит, уходим немедленно!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Моих сил надолго не хватит, уходим немедленно!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15158,'Готовься, |3-6($c).$b$bПришла пора положить конец правлению Короля-лича.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Готовься, |3-6($c).$b$bПришла пора положить конец правлению Короля-лича.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15166,'Король-лич слишком близко, $n. Его издевательский голос звучит у меня в голове...$b$bПора заставить его умолкнуть навеки!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Король-лич слишком близко, $n. Его издевательский голос звучит у меня в голове...$b$bПора заставить его умолкнуть навеки!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15170,'Привет! Я представляю Королевскую химическую компанию.$B$BИщешь подработку? Подарок по случаю? Может быть, приятную безделушку для души? У меня найдется все!$B$BНу а если не у меня, то у нашего счастливого талисмана Кви или у милой продавщицы точно есть именно то, что тебе нужно!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Привет! Я представляю Королевскую химическую компанию.$B$BИщешь подработку? Подарок по случаю? Может быть, приятную безделушку для души? У меня найдется все!$B$BНу а если не у меня, то у нашего счастливого талисмана Кви или у милой продавщицы точно есть именно то, что тебе нужно!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15171,'Теперь, когда у нас есть снаряжение, мы сможем вступить в бой.$B$BИдите дальше. Мы встретим вас на месте.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Теперь, когда у нас есть снаряжение, мы сможем вступить в бой.$B$BИдите дальше. Мы встретим вас на месте.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15172,'Я соберу оставшихся рабов и приготовлю к битве. Мы вас догоним на подходах к Повелителю Плети Тиранию.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я соберу оставшихся рабов и приготовлю к битве. Мы вас догоним на подходах к Повелителю Плети Тиранию.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15173,'Когда Таурахо был в безопасности, я натаскивал юных охотников в лесах.$b$bТеперь мы не можем себе позволить такой роскоши. Учиться приходится в бою с настоящим врагом, лагерь которого разбит практически у нас на пороге.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Когда Таурахо был в безопасности, я натаскивал юных охотников в лесах.$b$bТеперь мы не можем себе позволить такой роскоши. Учиться приходится в бою с настоящим врагом, лагерь которого разбит практически у нас на пороге.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15174,'Мы повинуемся вашему командиру, герои. Повелитель Плети нынче вечером будет повержен.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы повинуемся вашему командиру, герои. Повелитель Плети нынче вечером будет повержен.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15182,'Степи могут быть сухими, но на этих равнинах когда-то процветала жизнь. Мы кочевали, охотились, жили за счет земли.$b$bА потом пришел Альянс… беспощадный, сжигающий все на своем пути, убивающий. Теперь мы называем эти земли Кровавыми полями, |3-6($c).$b$bВсе беженцы покинули эти места. Оставшиеся примут бой.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Степи могут быть сухими, но на этих равнинах когда-то процветала жизнь. Мы кочевали, охотились, жили за счет земли.$b$bА потом пришел Альянс… беспощадный, сжигающий все на своем пути, убивающий. Теперь мы называем эти земли Кровавыми полями, |3-6($c).$b$bВсе беженцы покинули эти места. Оставшиеся примут бой.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15188,'Эй, ты! Я не знаю, что тебе нужно и зачем ты за мной $Gувязался:увязалась;, но у меня скоро корабль отходит, и компаньоны мне не нужны!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эй, ты! Я не знаю, что тебе нужно и зачем ты за мной $Gувязался:увязалась;, но у меня скоро корабль отходит, и компаньоны мне не нужны!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15189,'Простите меня. Надо было послушать Утера. Но мне… хотелось убедиться во всем самой. Последний раз взглянуть ему в глаза… Простите.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Простите меня. Надо было послушать Утера. Но мне… хотелось убедиться во всем самой. Последний раз взглянуть ему в глаза… Простите.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15190,'Мы в безопасности… пока что. Его сила возросла десятикратно со времен нашей последней битвы. Чтобы победить Короля-лича, потребуется огромная армия. Куда большая, чем сможет собрать Орда.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мы в безопасности… пока что. Его сила возросла десятикратно со времен нашей последней битвы. Чтобы победить Короля-лича, потребуется огромная армия. Куда большая, чем сможет собрать Орда.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15191,'Я задержусь здесь, пока не прибудет подкрепление, а вы идите дальше. Скоро Артас обнаружит, что мы здесь.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я задержусь здесь, пока не прибудет подкрепление, а вы идите дальше. Скоро Артас обнаружит, что мы здесь.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15195,'Ты $Gуверен:уверена;? Может, еще минутку-другую?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты $Gуверен:уверена;? Может, еще минутку-другую?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15196,'Это Крепость Отчаяния, |3-6($c). Мы ждем здесь благоприятного момента, когда сможем дать отпор Альянсу.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Это Крепость Отчаяния, |3-6($c). Мы ждем здесь благоприятного момента, когда сможем дать отпор Альянсу.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15197,'Сделай это побыстрее, |3-6($c). Вождь прислал меня, чтобы я оценил ситуацию в Степях, и когда я оказался здесь, то обнаружил города в огне и псов Альянса, одержимых желанием убивать.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Сделай это побыстрее, |3-6($c). Вождь прислал меня, чтобы я оценил ситуацию в Степях, и когда я оказался здесь, то обнаружил города в огне и псов Альянса, одержимых желанием убивать.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15200,'Полководец Кровавый Эфес? Приближенное лицо Гарроша?$b$bЕму совершенно необязательно быть здесь, ты же видишь, у меня все под контролем, можешь так ему и передать.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Полководец Кровавый Эфес? Приближенное лицо Гарроша?$b$bЕму совершенно необязательно быть здесь, ты же видишь, у меня все под контролем, можешь так ему и передать.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15201,'Но, эээ, припасы на исходе. И мне, эээ, не хватает рабочей силы. Скажи это Кровавому Эфесу.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Но, эээ, припасы на исходе. И мне, эээ, не хватает рабочей силы. Скажи это Кровавому Эфесу.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15203,'Не задерживайся, он уже почти здесь!$b$bПриходи ко мне на вершину северной башни.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не задерживайся, он уже почти здесь!$b$bПриходи ко мне на вершину северной башни.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15205,'Это здесь. Я чувствую, что когда-то на этом месте разыгралась огромная трагедия; тут до сих пор слышны отголоски прежних страданий. Без сомнений, это место захвачено потусторонними кошмарами.$b$bЧтобы навсегда закрыть этот разлом, через который кошмары проникают в наш мир, мне сначала нужно полностью открыть его. Мне понадобится твоя сила, чтобы противостоять всему, что может попытаться выбраться оттуда.$b$bТы $gготов:готова;?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Это здесь. Я чувствую, что когда-то на этом месте разыгралась огромная трагедия; тут до сих пор слышны отголоски прежних страданий. Без сомнений, это место захвачено потусторонними кошмарами.$b$bЧтобы навсегда закрыть этот разлом, через который кошмары проникают в наш мир, мне сначала нужно полностью открыть его. Мне понадобится твоя сила, чтобы противостоять всему, что может попытаться выбраться оттуда.$b$bТы $gготов:готова;?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15206,'У нас мало времени, |3-6($c). Что тебя задерживает?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','У нас мало времени, |3-6($c). Что тебя задерживает?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15207,'У нас мало времени, герой. Чего тебе нужно?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','У нас мало времени, герой. Чего тебе нужно?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15209,'<Он смотрит на ракету и не может сдержать нервный смешок.>$B$BНу ладно, допустим, я сделал для кого-нибудь парочку ракет. Что дальше? Цену дали хорошую и заплатили вовремя. Вроде, никто от этого не умер. Честная сделка. Что тебе-то с этого?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Он смотрит на ракету и не может сдержать нервный смешок.>$B$BНу ладно, допустим, я сделал для кого-нибудь парочку ракет. Что дальше? Цену дали хорошую и заплатили вовремя. Вроде, никто от этого не умер. Честная сделка. Что тебе-то с этого?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15210,'Слушай, я не знаю, $Gусек:усекла;? Не знаю я!$B$BМне заплатили, чтобы я начинил ракеты реактивом, и я это сделал. Работа сдана, $Gприятель:дамочка;. Ракеты сделаны, упакованы и отосланы. Я только собрался разгуляться на полученные денежки, как ты за мной гоняться $Gначал:начала;. Реактива у меня не осталось, и я понятия не имею, что это за дрянь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Слушай, я не знаю, $Gусек:усекла;? Не знаю я!$B$BМне заплатили, чтобы я начинил ракеты реактивом, и я это сделал. Работа сдана, $Gприятель:дамочка;. Ракеты сделаны, упакованы и отосланы. Я только собрался разгуляться на полученные денежки, как ты за мной гоняться $Gначал:начала;. Реактива у меня не осталось, и я понятия не имею, что это за дрянь.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15211,'Думаешь, я вот так взял и вспомнил?.. Впрочем... слушай. Мне заплатили за то, чтобы я держал рот на замке, но от тебя, я вижу, не отвяжешься. Такого рода неудобство в контракте учтено не было. Я могу нечаянно уронить журнал на пол, так? А ты можешь нечаянно заглянуть в него одним глазком.$B$BЯсно? А теперь отстань от меня наконец!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Думаешь, я вот так взял и вспомнил?.. Впрочем... слушай. Мне заплатили за то, чтобы я держал рот на замке, но от тебя, я вижу, не отвяжешься. Такого рода неудобство в контракте учтено не было. Я могу нечаянно уронить журнал на пол, так? А ты можешь нечаянно заглянуть в него одним глазком.$B$BЯсно? А теперь отстань от меня наконец!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15212,'Вы уже слышали о нашей новой акции "Коллекция Красоты"?$B$BУ официальных талисманов мероприятия вроде меня вы можете приобрести наборы собирателя чудесных оберегов.$B$BИз чудесных оберегов можно делать чудесные браслеты-обереги для друзей и любимых, браслеты также можно обменивать у милых продавщиц на знаки любви.$B$BХит сезона – сделайте чудесный браслет-оберег для своего дорогого лидера, чтобы показать ему свою любовь и уважение!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вы уже слышали о нашей новой акции "Коллекция Красоты"?$B$BУ официальных талисманов мероприятия вроде меня вы можете приобрести наборы собирателя чудесных оберегов.$B$BИз чудесных оберегов можно делать чудесные браслеты-обереги для друзей и любимых, браслеты также можно обменивать у милых продавщиц на знаки любви.$B$BХит сезона – сделайте чудесный браслет-оберег для своего дорогого лидера, чтобы показать ему свою любовь и уважение!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15213,'Все, что знаю – рассказал. Проваливай!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Все, что знаю – рассказал. Проваливай!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15214,'Все, что вы потеряли, Брейзи уже Нашол! Отличная шуточка, правда? Нет? Ну ладно.$B$BТак вот, у меня водятся не только "законные" вещицы. Я продаю ВСЕ, ЧТО ДУШЕ УГОДНО! Абсолютно все!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Все, что вы потеряли, Брейзи уже Нашол! Отличная шуточка, правда? Нет? Ну ладно.$B$BТак вот, у меня водятся не только "законные" вещицы. Я продаю ВСЕ, ЧТО ДУШЕ УГОДНО! Абсолютно все!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15215,'Боль снова захлестывает меня, когда я вижу так близко меч, отнявший у меня жизнь…') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Боль снова захлестывает меня, когда я вижу так близко меч, отнявший у меня жизнь…',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15217,'Благодарю тебя, доблестный воин Орды! Если бы не ты и твои союзники, боевой корабль Альянса разгромил бы нас.$B$BПередохни немного, и мы начнем штурм верхних ярусов цитадели.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Благодарю тебя, доблестный воин Орды! Если бы не ты и твои союзники, боевой корабль Альянса разгромил бы нас.$B$BПередохни немного, и мы начнем штурм верхних ярусов цитадели.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15219,'Я слышал, что мой сын здесь. Говорят, он стал могучим рыцарем смерти и служит Королю-личу. Если это так, то наш род прервется на мне.$B$BМоя задача – принять командование "Молотом Оргрима", подняться на нем к верхним ярусам цитадели Ледяной Короны и уничтожить всю нежить, которая встанет на нашем пути. Мы отчалим, когда вы с союзниками будете готовы.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я слышал, что мой сын здесь. Говорят, он стал могучим рыцарем смерти и служит Королю-личу. Если это так, то наш род прервется на мне.$B$BМоя задача – принять командование "Молотом Оргрима", подняться на нем к верхним ярусам цитадели Ледяной Короны и уничтожить всю нежить, которая встанет на нашем пути. Мы отчалим, когда вы с союзниками будете готовы.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (15221,'Транспортер окутывает призрачное сияние.','Транспортер окутывает призрачное сияние.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Транспортер окутывает призрачное сияние.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Транспортер окутывает призрачное сияние.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15222,'А теперь – к делам военным!$b$bЗа изрезанной оврагами равниной на востоке Альянс собирается наладить воздушное сообщение между своими береговыми крепостями. Они думают построить крепость здесь, в центре Степей. В самом сердце МОИХ Степей.$b$bЭтого не случится.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','А теперь – к делам военным!$b$bЗа изрезанной оврагами равниной на востоке Альянс собирается наладить воздушное сообщение между своими береговыми крепостями. Они думают построить крепость здесь, в центре Степей. В самом сердце МОИХ Степей.$b$bЭтого не случится.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15223,'Это было ужасно, |3-6($c). Меня бесцеремонно выдворили из Оргриммара, чаны со свежими извивающимися конечностями разбили о землю, когда волокли меня через врата.$b$bКак будто я какой-то монстр!$b$bК счастью, у меня есть возможность продолжать исследования здесь, где нет недостатка в свежих трупах.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Это было ужасно, |3-6($c). Меня бесцеремонно выдворили из Оргриммара, чаны со свежими извивающимися конечностями разбили о землю, когда волокли меня через врата.$b$bКак будто я какой-то монстр!$b$bК счастью, у меня есть возможность продолжать исследования здесь, где нет недостатка в свежих трупах.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15224,'<Изо рта Калдера вылезает таракан и быстро прячется обратно внутрь черепа через пустую глазницу.>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Изо рта Калдера вылезает таракан и быстро прячется обратно внутрь черепа через пустую глазницу.>',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15225,'<Видя ваше приближение, Калдер заново прикрепляет свою челюсть, чтобы поговорить с вами.>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Видя ваше приближение, Калдер заново прикрепляет свою челюсть, чтобы поговорить с вами.>',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15226,'<Вы обнаруживаете Калдера, лениво ковыряющим кинжалом в ухе.>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Вы обнаруживаете Калдера, лениво ковыряющим кинжалом в ухе.>',`text0_0_loc8`);
