INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15228,'Убийца.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Убийца.',`text0_0_loc8`);
