INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15233,'Полегче, $gдруг:подруга;. Говоришь, генерал скоро будет?$b$bТеперь у меня ЕСТЬ трофей на стену! Я отвлеку телохранителей, но убить генерала Готорна придется тебе. $GГотов:Готова; к бою?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Полегче, $gдруг:подруга;. Говоришь, генерал скоро будет?$b$bТеперь у меня ЕСТЬ трофей на стену! Я отвлеку телохранителей, но убить генерала Готорна придется тебе. $GГотов:Готова; к бою?',`text0_0_loc8`);
