INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15235,'Палач Таурахо за все заплатит.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Палач Таурахо за все заплатит.',`text0_0_loc8`);
