INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15237,'Да! Грок\'тар Мор\'гар. Бок чой, друг. Эм. Заб-заб!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да! Грок\'тар Мор\'гар. Бок чой, друг. Эм. Заб-заб!',`text0_0_loc8`);
