INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15238,'Хорошо-хорошо. Ух. Готов к р-работе!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Хорошо-хорошо. Ух. Готов к р-работе!',`text0_0_loc8`);
