INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (15239,'Для входа на плато Солнечного Колодца требуется разрешение предводителя следопытов.','Для входа на плато Солнечного Колодца требуется разрешение предводителя следопытов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Для входа на плато Солнечного Колодца требуется разрешение предводителя следопытов.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Для входа на плато Солнечного Колодца требуется разрешение предводителя следопытов.',`text0_1_loc8`);
