INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (15240,'Я провожу тебя к Солнечному Колодцу, когда ты будешь $Gготов:готова;.','Я провожу тебя к Солнечному Колодцу, когда ты будешь $Gготов:готова;.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я провожу тебя к Солнечному Колодцу, когда ты будешь $Gготов:готова;.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я провожу тебя к Солнечному Колодцу, когда ты будешь $Gготов:готова;.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15241,'Я говорил Гар\'дулу не возводить крепость на вершине колонии силитидов.$b$bПослушал он Крогола? Нет!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я говорил Гар\'дулу не возводить крепость на вершине колонии силитидов.$b$bПослушал он Крогола? Нет!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15243,'Моему гению тесно в этой табакерке!$B$BПогоди, это не Азшара?! А что тогда?! Спящий вулкан!$B$BС одной стороны, мне хочется присоединиться к торговому принцу! С другой – я не прочь заняться превращением куриных яиц в смертельное оружие!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Моему гению тесно в этой табакерке!$B$BПогоди, это не Азшара?! А что тогда?! Спящий вулкан!$B$BС одной стороны, мне хочется присоединиться к торговому принцу! С другой – я не прочь заняться превращением куриных яиц в смертельное оружие!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15244,'Когда нас упаковали в Городок-из-табакерки, обещали, что мы окажемся где-то в Азшаре. Это Азшара?$B$BНет, ты мне скажи: зачем создавать Городок-из-табакерки, если его жителям не хватит пищи?! Всего один жалкий птицефикатор? Тьфу!$B$BМы все знаем, чем кончилось дело с микромеханоцыпами!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Когда нас упаковали в Городок-из-табакерки, обещали, что мы окажемся где-то в Азшаре. Это Азшара?$B$BНет, ты мне скажи: зачем создавать Городок-из-табакерки, если его жителям не хватит пищи?! Всего один жалкий птицефикатор? Тьфу!$B$BМы все знаем, чем кончилось дело с микромеханоцыпами!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15246,'Нагнись ко мне, $gдруг:подруга;. Я был ранен во время последнего рейда.$b$b<Ганн мычит от боли, пытаясь изменить положение. Он зажимает рану левой рукой, через его дрожащие пальцы течет кровь.>$b$bКогда дворфы впервые вторглись в Степи, я боролся с ними, лишь нападая на землекопов и выводя из строя их оборудование. Надо было сразу нанести смертельный удар, пока была возможность.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Нагнись ко мне, $gдруг:подруга;. Я был ранен во время последнего рейда.$b$b<Ганн мычит от боли, пытаясь изменить положение. Он зажимает рану левой рукой, через его дрожащие пальцы течет кровь.>$b$bКогда дворфы впервые вторглись в Степи, я боролся с ними, лишь нападая на землекопов и выводя из строя их оборудование. Надо было сразу нанести смертельный удар, пока была возможность.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15248,'Визил Темнила – мастер маскировки!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Визил Темнила – мастер маскировки!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (15251,'Эй, это, конечно, не то чтобы какое-то особенное испытание, но прежде чем отправлять тебя туда, мы должны убедиться в твоих силах.','Эй, это, конечно, не то чтобы какое-то особенное испытание, но прежде чем отправлять тебя туда, мы должны убедиться в твоих силах.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эй, это, конечно, не то чтобы какое-то особенное испытание, но прежде чем отправлять тебя туда, мы должны убедиться в твоих силах.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Эй, это, конечно, не то чтобы какое-то особенное испытание, но прежде чем отправлять тебя туда, мы должны убедиться в твоих силах.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (15252,'Бой в самом разгаре. Наберись терпения.','Бой в самом разгаре. Наберись терпения.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Бой в самом разгаре. Наберись терпения.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Бой в самом разгаре. Наберись терпения.',`text0_1_loc8`);
