INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15256,'Не нравится мне эта "Королевская химическая компания"... совсем не нравится.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не нравится мне эта "Королевская химическая компания"... совсем не нравится.',`text0_0_loc8`);
