INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15257,'Будешь хорошо заботиться о своем оружии – оно будет хорошо заботиться о тебе в ответ.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Будешь хорошо заботиться о своем оружии – оно будет хорошо заботиться о тебе в ответ.',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (15258,'Я не могу помочь тебе. Поговори с Нортретом, если хочешь обучиться мастерству воина.','Я не могу помочь тебе. Поговори с Нортретом, если хочешь обучиться мастерству воина.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я не могу помочь тебе. Поговори с Нортретом, если хочешь обучиться мастерству воина.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я не могу помочь тебе. Поговори с Нортретом, если хочешь обучиться мастерству воина.',`text0_1_loc8`);
