INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (15260,'Я не могу помочь тебе. Поговори с Зен\'таброй, если хочешь обучиться мудрости друидов.','Я не могу помочь тебе. Поговори с Зен\'таброй, если хочешь обучиться мудрости друидов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я не могу помочь тебе. Поговори с Зен\'таброй, если хочешь обучиться мудрости друидов.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я не могу помочь тебе. Поговори с Зен\'таброй, если хочешь обучиться мудрости друидов.',`text0_1_loc8`);
