INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (15263,'Я не могу помочь тебе. Поговори с Соратой, если хочешь обучиться волшебству.','Я не могу помочь тебе. Поговори с Соратой, если хочешь обучиться волшебству.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я не могу помочь тебе. Поговори с Соратой, если хочешь обучиться волшебству.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я не могу помочь тебе. Поговори с Соратой, если хочешь обучиться волшебству.',`text0_1_loc8`);
