INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (15264,'Я не могу помочь тебе. Поговори с Тунари, если хочешь обучиться мудрости жрецов.','Я не могу помочь тебе. Поговори с Тунари, если хочешь обучиться мудрости жрецов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я не могу помочь тебе. Поговори с Тунари, если хочешь обучиться мудрости жрецов.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я не могу помочь тебе. Поговори с Тунари, если хочешь обучиться мудрости жрецов.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15266,'Оруженосец – это правая рука рыцаря. А руки, как ты наверняка знаешь, прежде всего созданы для того, чтобы что-нибудь носить. Таким образом, прежде всего тебе нужно будет носить мою поклажу, добытые сокровища и прочие личные вещи в то время как я осуществляю справедливый суд вокруг. Таскать за собой все это самому – неподобающее рыцарю занятие.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Оруженосец – это правая рука рыцаря. А руки, как ты наверняка знаешь, прежде всего созданы для того, чтобы что-нибудь носить. Таким образом, прежде всего тебе нужно будет носить мою поклажу, добытые сокровища и прочие личные вещи в то время как я осуществляю справедливый суд вокруг. Таскать за собой все это самому – неподобающее рыцарю занятие.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15267,'Очень хорошо. Во-вторых, ты $gдолжен:должна; знать, что нет ничего важнее для рыцаря, чем отвага и доблесть. Он держится за свое благородство так же крепко, как сжимает в руках свое копье. Меч рыцаря остр, но по отношению к своим союзникам рыцарь мягок и учтив.$b$bА теперь скажи мне, $n, $gготов:готова; ли ты дать клятву твердо следовать принципам доблести и отваги?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Очень хорошо. Во-вторых, ты $gдолжен:должна; знать, что нет ничего важнее для рыцаря, чем отвага и доблесть. Он держится за свое благородство так же крепко, как сжимает в руках свое копье. Меч рыцаря остр, но по отношению к своим союзникам рыцарь мягок и учтив.$b$bА теперь скажи мне, $n, $gготов:готова; ли ты дать клятву твердо следовать принципам доблести и отваги?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15268,'Ха! Разве я не сказал только что, $gмилый:милая; $n, что благородство и отвага – это достоинства РЫЦАРЯ? Ты же хочешь быть просто ОРУЖЕНОСЦЕМ. Оруженосцу такая ноша не по силам. Как я уже сказал, единственная тяжелая ноша, которую тебе придется нести, – это мои вещи.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ха! Разве я не сказал только что, $gмилый:милая; $n, что благородство и отвага – это достоинства РЫЦАРЯ? Ты же хочешь быть просто ОРУЖЕНОСЦЕМ. Оруженосцу такая ноша не по силам. Как я уже сказал, единственная тяжелая ноша, которую тебе придется нести, – это мои вещи.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15269,'Продолжаем! Поскольку отвага и благородство – неотъемлемые достоинства рыцаря, а я рыцарь, ты $gдолжен:должна; знать, что все мои стремления являются доблестными. Это так. Я сражаюсь во имя леди Долории, чтобы повсюду прославить ее красоту и величие. А те, кто ставят под сомнение ее красоту, без всякого сомнения – самые мерзкие мои враги и должны быть преданы правосудию.$b$bКонечно, иногда мне случается ошибаться. Мы довольно далеко продвинулись в церемонии посвящения в оруженосцы, а я все еще не выяснил, заслуживаешь ты моей любви или же моего праведного гнева.$b$bСейчас я должен знать, $gсогласен:согласна; ли ты, что леди Долория – бесспорно самая прекрасная леди во всем Азероте?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Продолжаем! Поскольку отвага и благородство – неотъемлемые достоинства рыцаря, а я рыцарь, ты $gдолжен:должна; знать, что все мои стремления являются доблестными. Это так. Я сражаюсь во имя леди Долории, чтобы повсюду прославить ее красоту и величие. А те, кто ставят под сомнение ее красоту, без всякого сомнения – самые мерзкие мои враги и должны быть преданы правосудию.$b$bКонечно, иногда мне случается ошибаться. Мы довольно далеко продвинулись в церемонии посвящения в оруженосцы, а я все еще не выяснил, заслуживаешь ты моей любви или же моего праведного гнева.$b$bСейчас я должен знать, $gсогласен:согласна; ли ты, что леди Долория – бесспорно самая прекрасная леди во всем Азероте?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15272,'Природа не предаст тебя никогда.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Природа не предаст тебя никогда.',`text0_1_loc8`);
