INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15277,'<Максимилиан погружен в молитвы и не замечает вашего присутствия.>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Максимилиан погружен в молитвы и не замечает вашего присутствия.>',`text0_0_loc8`);
