INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15278,'Сложи оружие и обнажи голову. Прежде, чем мы начнем сражаться вместе, выслушай речь, которую я подготовил.$b$b$gГотов:Готова; ли ты?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Сложи оружие и обнажи голову. Прежде, чем мы начнем сражаться вместе, выслушай речь, которую я подготовил.$b$b$gГотов:Готова; ли ты?',`text0_0_loc8`);
