INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (15280,'Не трать времени понапрасну, $Gуважаемый:уважаемая;.$B$BЕсли тебе нужно купить что-нибудь в Королевской химической компании, отправляйся прямиком к милым продавщицам!','Не трать времени понапрасну, $Gуважаемый:уважаемая;.$B$BЕсли тебе нужно купить что-нибудь в Королевской химической компании, отправляйся прямиком к милым продавщицам!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не трать времени понапрасну, $Gуважаемый:уважаемая;.$B$BЕсли тебе нужно купить что-нибудь в Королевской химической компании, отправляйся прямиком к милым продавщицам!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Не трать времени понапрасну, $Gуважаемый:уважаемая;.$B$BЕсли тебе нужно купить что-нибудь в Королевской химической компании, отправляйся прямиком к милым продавщицам!',`text0_1_loc8`);
