INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (15282,'Тебе, кажется, надо кое-что доставить?','Тебе, кажется, надо кое-что доставить?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тебе, кажется, надо кое-что доставить?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Тебе, кажется, надо кое-что доставить?',`text0_1_loc8`);
