INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (15284,'Чем-то пованивает, и на этот раз это уж точно не мои носки.','Чем-то пованивает, и на этот раз это уж точно не мои носки.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Чем-то пованивает, и на этот раз это уж точно не мои носки.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Чем-то пованивает, и на этот раз это уж точно не мои носки.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15287,'Удивительное оружие, не правда ли? Нет, это не дворфийская работа, он гораздо древнее.$B$BПроныры из Похитителей Солнца и Серебряного союза пытаются раскрыть эту тайну. Я уже пишу доклад Бранну.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Удивительное оружие, не правда ли? Нет, это не дворфийская работа, он гораздо древнее.$B$BПроныры из Похитителей Солнца и Серебряного союза пытаются раскрыть эту тайну. Я уже пишу доклад Бранну.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15288,'Задача всякого друида – оберегать природу и сохранять в ней баланс. Но вышло так, что дело всей моей жизни обернулось для меня кошмаром. Я безрассудно посеял семена хаоса... и должен собрать горькие плоды, чтобы хаос не распространился.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Задача всякого друида – оберегать природу и сохранять в ней баланс. Но вышло так, что дело всей моей жизни обернулось для меня кошмаром. Я безрассудно посеял семена хаоса... и должен собрать горькие плоды, чтобы хаос не распространился.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15289,'Я останусь здесь и буду наблюдать, как проходит исцеление. Присматривайся ко всем одиночным животным из этих мест…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я останусь здесь и буду наблюдать, как проходит исцеление. Присматривайся ко всем одиночным животным из этих мест…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15290,'Я долго ждал, пока наступит этот день, герой. Готовы ли твои соратники свершить правосудие над Королем-личом? Мы бросимся в бой по твоему приказу!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я долго ждал, пока наступит этот день, герой. Готовы ли твои соратники свершить правосудие над Королем-личом? Мы бросимся в бой по твоему приказу!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15292,'Бейл Модан… Дворфы…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Бейл Модан… Дворфы…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15293,'Разлом закрыт! Спасибо Кенарию…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Разлом закрыт! Спасибо Кенарию…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15294,'Спасите меня! Там, в горячей воде, все мои вещи!$b$bВсе мои наряды!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Спасите меня! Там, в горячей воде, все мои вещи!$b$bВсе мои наряды!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15295,'Снова ты… Надеюсь, ты не очень веришь в то, что своими действиями сможешь вернуть мне бодрость духа. Я осознал, что без нее мне больше не будет покоя.$b$bЯ хочу увидеть даже их дома разрушенными до основания. Ты $gготов:готова; уничтожить еще больше этих омерзительных убийц?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Снова ты… Надеюсь, ты не очень веришь в то, что своими действиями сможешь вернуть мне бодрость духа. Я осознал, что без нее мне больше не будет покоя.$b$bЯ хочу увидеть даже их дома разрушенными до основания. Ты $gготов:готова; уничтожить еще больше этих омерзительных убийц?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15297,'Я сам нанес себе эту рану. Мне было невыносимо смотреть на мир, где я совершил столько злодеяний, повинуясь Королю-личу.$B$BЭто был мой первый шаг к прощению, и даже если мои грехи слишком велики, я посвящу их искуплению всю оставшуюся жизнь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я сам нанес себе эту рану. Мне было невыносимо смотреть на мир, где я совершил столько злодеяний, повинуясь Королю-личу.$B$BЭто был мой первый шаг к прощению, и даже если мои грехи слишком велики, я посвящу их искуплению всю оставшуюся жизнь.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15301,'Отсюда ты можешь видеть весь масштаб разрушений после катаклизма. Мороз по коже от осознания того, какой наш мир на самом деле хрупкий.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Отсюда ты можешь видеть весь масштаб разрушений после катаклизма. Мороз по коже от осознания того, какой наш мир на самом деле хрупкий.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15302,'Ветер дует с востока, |3-6($c).') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ветер дует с востока, |3-6($c).',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15303,'У меня есть кое-какие мысли, как можно было бы справиться с этим безумием, |3-6($c). $b$bК несчастью, Наралекс настолько сильно разбит случившимся, что отказывается от любых попыток что-либо исправить.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','У меня есть кое-какие мысли, как можно было бы справиться с этим безумием, |3-6($c). $b$bК несчастью, Наралекс настолько сильно разбит случившимся, что отказывается от любых попыток что-либо исправить.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15309,'Мы не должны позволить нашему горю ослабить нас. Наш народ даст достойный отпор захватчикам.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы не должны позволить нашему горю ослабить нас. Наш народ даст достойный отпор захватчикам.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15310,'Наконец-то, подкрепление! Вот тут все бумаги, которые запрашивал Гвоздезуб. Главное, чтобы этим делом кто-нибудь занялся.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Наконец-то, подкрепление! Вот тут все бумаги, которые запрашивал Гвоздезуб. Главное, чтобы этим делом кто-нибудь занялся.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15312,'Моя задача – проверить охотничьи навыки наших новичков.$b$bСейчас тоже. Сегодня нашими жертвами будут свинобразы.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Моя задача – проверить охотничьи навыки наших новичков.$b$bСейчас тоже. Сегодня нашими жертвами будут свинобразы.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15315,'Приветствую, |3-6($c)! Прямо перед тобой Застава Чести, единственное связующее звено между Альянсом, Когтистыми горами и берегом.$b$bДорога очень опасная. Я это знаю по собственному опыту.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приветствую, |3-6($c)! Прямо перед тобой Застава Чести, единственное связующее звено между Альянсом, Когтистыми горами и берегом.$b$bДорога очень опасная. Я это знаю по собственному опыту.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15316,'Я прибыла сюда, чтобы наладить торговлю с нагами. Однако они настроены несколько недружелюбно.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я прибыла сюда, чтобы наладить торговлю с нагами. Однако они настроены несколько недружелюбно.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15317,'Приветствую тебя, |3-6($c). Мы, шаманы, собрались здесь, в Кремневом лагере, чтобы наблюдать за землей и лечить ее раны.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Приветствую тебя, |3-6($c). Мы, шаманы, собрались здесь, в Кремневом лагере, чтобы наблюдать за землей и лечить ее раны.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15318,'Она вернулась. Настал день долгожданной мести.$b$BДай мне знать, как будешь $gготов:готова;. Мы не дадим ей ускользнуть на этот раз.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Она вернулась. Настал день долгожданной мести.$b$BДай мне знать, как будешь $gготов:готова;. Мы не дадим ей ускользнуть на этот раз.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15319,'Вариматас? Нет, он уже давно не появлялся. Наверное, выполняет повеление королевы.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вариматас? Нет, он уже давно не появлялся. Наверное, выполняет повеление королевы.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15320,'Пока Вариматас... в отъезде, меня назначили помощником капитана Брагора.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Пока Вариматас... в отъезде, меня назначили помощником капитана Брагора.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (15321,'Основные силы Подгорода собрались в Лагере Возмездия в Нордсколе, и вождь отправил нас на укрепление защиты города.','Основные силы Подгорода собрались в Лагере Возмездия в Нордсколе, и вождь отправил нас на укрепление защиты города.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Основные силы Подгорода собрались в Лагере Возмездия в Нордсколе, и вождь отправил нас на укрепление защиты города.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Основные силы Подгорода собрались в Лагере Возмездия в Нордсколе, и вождь отправил нас на укрепление защиты города.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15324,'Ты $gхотел:хотела; бы немного подзаработать?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты $gхотел:хотела; бы немного подзаработать?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15325,'Мы пришли в Ун\'Горо с единственной целью – получить прибыль. Мои партнеры вместе со мной всегда открыты к деловому сотрудничеству, если тебе это интересно.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы пришли в Ун\'Горо с единственной целью – получить прибыль. Мои партнеры вместе со мной всегда открыты к деловому сотрудничеству, если тебе это интересно.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15327,'Знаешь ли ты, что когда-то на месте Степей был роскошный лес? Тысячи лет назад, прежде, чем случился первый Раскол, здесь зеленели деревья, и калдорай охраняли это место. Но затем земля материков оказалась разорвана, этот осколок был назван Калимдором, а на месте прекрасной долины образовалась выжженная солнцем равнина.$b$bКогда я узнал это, сердце мое исполнилось печали. Я решил тогда обязательно найти способ заново вырастить здесь леса.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Знаешь ли ты, что когда-то на месте Степей был роскошный лес? Тысячи лет назад, прежде, чем случился первый Раскол, здесь зеленели деревья, и калдорай охраняли это место. Но затем земля материков оказалась разорвана, этот осколок был назван Калимдором, а на месте прекрасной долины образовалась выжженная солнцем равнина.$b$bКогда я узнал это, сердце мое исполнилось печали. Я решил тогда обязательно найти способ заново вырастить здесь леса.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15328,'Изучая здешние края, я обнаружил несколько соединенных между собой пещер, которые протянулись цепью глубоко под землей. Вода, протекающая по ним, проходит под землей через всю иссушенную саванну. Я назвал их Пещерами Стенаний – из-за особого звука, который издают вода и ветер, проходящие сквозь пустоты.$b$bЯ подумал тогда – вот он, способ, с помощью которого я верну этому месту жизнь. Местами эта вода даже прорывалась на поверхность, образуя небольшие зеленые оазисы по всем Степям...если бы она была зачарована, исполнена силы, то жизнь могла бы распространиться таким образом по всей земле.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Изучая здешние края, я обнаружил несколько соединенных между собой пещер, которые протянулись цепью глубоко под землей. Вода, протекающая по ним, проходит под землей через всю иссушенную саванну. Я назвал их Пещерами Стенаний – из-за особого звука, который издают вода и ветер, проходящие сквозь пустоты.$b$bЯ подумал тогда – вот он, способ, с помощью которого я верну этому месту жизнь. Местами эта вода даже прорывалась на поверхность, образуя небольшие зеленые оазисы по всем Степям...если бы она была зачарована, исполнена силы, то жизнь могла бы распространиться таким образом по всей земле.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15329,'Я собирался соединить эти подземные воды напрямую с миром Изумрудного Сна. Вместе со своими последователями, я отправился вглубь Пещер Стенаний, погрузился в медитацию и вошел в Сон. Таким образом это соединение произошло через мое собственное тело.$b$BНо все пошло не так.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я собирался соединить эти подземные воды напрямую с миром Изумрудного Сна. Вместе со своими последователями, я отправился вглубь Пещер Стенаний, погрузился в медитацию и вошел в Сон. Таким образом это соединение произошло через мое собственное тело.$b$BНо все пошло не так.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15331,'Меня спас мой последний ученик, Муйон, вместе с группой путешественников. Все происшествие я считаю неудачей. Только когда произошел катаклизм, я осознал, что раньше мне просто слишком везло!$b$bКогда Степи раскололись на части, огромная масса подземных вод, насыщенная энергией Пещер Стенаний, хлынула на поверхность. Сразу же после этого в Степях появилась буйная растительность, расплодились животные... но этот рост продолжился и дальше, ничем не сдерживаемый, неконтролируемый.$b$bС моей стороны было самонадеянно думать, что я могу влиять на природу. Нужно остановить эту растительность, пока она не поглотила все вокруг.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Меня спас мой последний ученик, Муйон, вместе с группой путешественников. Все происшествие я считаю неудачей. Только когда произошел катаклизм, я осознал, что раньше мне просто слишком везло!$b$bКогда Степи раскололись на части, огромная масса подземных вод, насыщенная энергией Пещер Стенаний, хлынула на поверхность. Сразу же после этого в Степях появилась буйная растительность, расплодились животные... но этот рост продолжился и дальше, ничем не сдерживаемый, неконтролируемый.$b$bС моей стороны было самонадеянно думать, что я могу влиять на природу. Нужно остановить эту растительность, пока она не поглотила все вокруг.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15332,'Чепуха. Я что, нанял слепого оруженосца? Тут повсюду драконы.$b$bМой сосед Искр называет их "динозаврами", но, когда я вижу дракона, я его ни с кем не спутаю. Их нужно убить.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Чепуха. Я что, нанял слепого оруженосца? Тут повсюду драконы.$b$bМой сосед Искр называет их "динозаврами", но, когда я вижу дракона, я его ни с кем не спутаю. Их нужно убить.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15333,'Хороший вопрос.$b$bМожно было бы обойти окрестности горячих источников. Или, может быть, поискать сигнальные огни в горах на западе. В конце концов, проход в Силитус, что находится далеко на севере, далеко не безопасен.$b$bЯ бы проверил именно эти места.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Хороший вопрос.$b$bМожно было бы обойти окрестности горячих источников. Или, может быть, поискать сигнальные огни в горах на западе. В конце концов, проход в Силитус, что находится далеко на севере, далеко не безопасен.$b$bЯ бы проверил именно эти места.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15339,'Ледяная Скорбь: клинок, разрушивший наше королевство…') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ледяная Скорбь: клинок, разрушивший наше королевство…',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15340,'После многочисленных неудачных попыток раздобыть качественные образцы чумы Плети я лично прибыла на фронт, чтобы проследить за работой. Верно говорят: если хочешь, чтобы все было сделано по-твоему...') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','После многочисленных неудачных попыток раздобыть качественные образцы чумы Плети я лично прибыла на фронт, чтобы проследить за работой. Верно говорят: если хочешь, чтобы все было сделано по-твоему...',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15344,'Здесь для тебя ничего нет. Уходи.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Здесь для тебя ничего нет. Уходи.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15346,'Мой повелитель желает видеть тебя.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мой повелитель желает видеть тебя.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`,`text3_0_loc8`) VALUES (15348,'Кто ты $gтакой:такая;? Чего ты хочешь от нашего племени?','Набия, это ты?','Добро пожаловать в наш дом, $gпришелец:пришелица;.','Ты $gпришел:пришла; наблюдать? Хочешь кокос?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Кто ты $gтакой:такая;? Чего ты хочешь от нашего племени?',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Набия, это ты?',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Добро пожаловать в наш дом, $gпришелец:пришелица;.',`text2_0_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Ты $gпришел:пришла; наблюдать? Хочешь кокос?',`text3_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15349,'Некоторым из нас удалось обуздать силу грома. Мы используем ее для того, чтобы защититься от захватчиков, будь то люди, орки или динозавры.$b$bДело в том, что наш гром оглушает всех динозавров.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Некоторым из нас удалось обуздать силу грома. Мы используем ее для того, чтобы защититься от захватчиков, будь то люди, орки или динозавры.$b$bДело в том, что наш гром оглушает всех динозавров.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15350,'Твоя собственная сила важна, но сила племени – важнее. Наше племя не может быть сильнее слабейшего из нас.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Твоя собственная сила важна, но сила племени – важнее. Наше племя не может быть сильнее слабейшего из нас.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15351,'Кровоцветы, что к югу отсюда, питаются мелкими существами вроде лягушек или попугаев. Мы, гориллы, едим кровоцветов. А динозавры едят горилл. Все это естественно и честно.$b$bЛюди и орки тоже охотятся на горилл, но они снимают с нас шкуры и оставляют тело гнить на земле. Поэтому мы нападаем на людей и орков.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Кровоцветы, что к югу отсюда, питаются мелкими существами вроде лягушек или попугаев. Мы, гориллы, едим кровоцветов. А динозавры едят горилл. Все это естественно и честно.$b$bЛюди и орки тоже охотятся на горилл, но они снимают с нас шкуры и оставляют тело гнить на земле. Поэтому мы нападаем на людей и орков.',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15363,'Эти пигмеи лишают меня прибыли!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Эти пигмеи лишают меня прибыли!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15367,'Воин-матик NX-01, уничтожение!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Воин-матик NX-01, уничтожение!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15369,'А вы слышали анекдот о |3-5($r) |3-5($c)? Значит так.$b$bЗаходит как-то |3-6($r) |3-6($c) в пещеру и давай убивать горилл. А вожак горилл ему и говорит: "Эй, что это ты делаешь?!". А |3-6($r) |3-6($c) отвечает: "Мне гоблин приказал".$b$bВожак горилл спрашивает: "А ты всегда делаешь то, что говорят тебе гоблины?". На что |3-6($r) |3-6($c) ему отвечает: "Да, потому что я $gглупый, вонючий:глупая, вонючая; и хожу на двух ногах".$b$bСмешно, да? Хмм... ну, может быть, надо его еще немного доработать...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','А вы слышали анекдот о |3-5($r) |3-5($c)? Значит так.$b$bЗаходит как-то |3-6($r) |3-6($c) в пещеру и давай убивать горилл. А вожак горилл ему и говорит: "Эй, что это ты делаешь?!". А |3-6($r) |3-6($c) отвечает: "Мне гоблин приказал".$b$bВожак горилл спрашивает: "А ты всегда делаешь то, что говорят тебе гоблины?". На что |3-6($r) |3-6($c) ему отвечает: "Да, потому что я $gглупый, вонючий:глупая, вонючая; и хожу на двух ногах".$b$bСмешно, да? Хмм... ну, может быть, надо его еще немного доработать...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15371,'Я Набия, ученица Каз\'горота и его посланница в кратере Ун\'Горо. Меня называют также Наблюдателем.$b$bЯ выполняю здесь работу своего повелителя с того момента, как он покинул Азерот. Было время, когда он придавал форму множеству своих созданий, стоя на этом самом месте.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я Набия, ученица Каз\'горота и его посланница в кратере Ун\'Горо. Меня называют также Наблюдателем.$b$bЯ выполняю здесь работу своего повелителя с того момента, как он покинул Азерот. Было время, когда он придавал форму множеству своих созданий, стоя на этом самом месте.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15372,'Я занимаюсь наблюдениями. Мой долг – следить за Ун\'Горо, и я слежу за всем отсюда.$b$bКроме того, я ставлю эксперименты и записываю их результаты. Эксперименты позволяют мне наблюдать именно за тем, что особенно интересует меня.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я занимаюсь наблюдениями. Мой долг – следить за Ун\'Горо, и я слежу за всем отсюда.$b$bКроме того, я ставлю эксперименты и записываю их результаты. Эксперименты позволяют мне наблюдать именно за тем, что особенно интересует меня.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15373,'Простой тест на связь стимула и реакции. Обычно мое племя не вмешивается в дела Азерота, но здесь в Ун\'Горо мы можем чувствовать себя свободнее. Поскольку кратер Ун\'Горо является экспериментальной территорией титанов, то мы имеем на это право.$b$bНапример, допустим Каз\'горот хочет узнать, что произойдет, если какое-то существо подвергнуть воздействию горячего сернистого источника. Он может тысячелетия провести, ожидая, пока какое-то существо случайно подойдет к источнику и упадет в него. Или может поместить существо в воду самостоятельно.$b$bВ Ун\'Горо мы можем это делать.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Простой тест на связь стимула и реакции. Обычно мое племя не вмешивается в дела Азерота, но здесь в Ун\'Горо мы можем чувствовать себя свободнее. Поскольку кратер Ун\'Горо является экспериментальной территорией титанов, то мы имеем на это право.$b$bНапример, допустим Каз\'горот хочет узнать, что произойдет, если какое-то существо подвергнуть воздействию горячего сернистого источника. Он может тысячелетия провести, ожидая, пока какое-то существо случайно подойдет к источнику и упадет в него. Или может поместить существо в воду самостоятельно.$b$bВ Ун\'Горо мы можем это делать.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15374,'Не совсем так. В действительности, многие существа жили здесь задолго до появления моего повелителя... Но не все.$b$bНесмотря на это, мы беспристрастно наблюдаем за ними всеми.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Не совсем так. В действительности, многие существа жили здесь задолго до появления моего повелителя... Но не все.$b$bНесмотря на это, мы беспристрастно наблюдаем за ними всеми.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15375,'Когда в Азероте произошел Катаклизм, он нарушил механизм маскировки, который скрывал эту террасу. То, что меня найдут разумные расы, стало понятно; вопрос был только во времени.$b$bЧестно говоря, такого варианта развития событий мы не предвидели. В связи с этим нам надо провести еще ряд экспериментов. И ты, $n, будешь моим подопытным кроликом.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Когда в Азероте произошел Катаклизм, он нарушил механизм маскировки, который скрывал эту террасу. То, что меня найдут разумные расы, стало понятно; вопрос был только во времени.$b$bЧестно говоря, такого варианта развития событий мы не предвидели. В связи с этим нам надо провести еще ряд экспериментов. И ты, $n, будешь моим подопытным кроликом.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15376,'Я не имею права отвечать на этот вопрос. Но зато я могу сделать тебе предложение.$b$bНайди Бранна Бронзоборода.$b$bОн уже многое узнал о нас и сейчас на пороге очередного открытия. Помоги ему и, возможно, он поможет тебе узнать то, что тебя интересует.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я не имею права отвечать на этот вопрос. Но зато я могу сделать тебе предложение.$b$bНайди Бранна Бронзоборода.$b$bОн уже многое узнал о нас и сейчас на пороге очередного открытия. Помоги ему и, возможно, он поможет тебе узнать то, что тебя интересует.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15377,'Скоро настанет время, когда мы отвоюем Гилнеас.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Скоро настанет время, когда мы отвоюем Гилнеас.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15379,'Смертные, вы спасли меня от участи худшей, чем гибель. Если бы вы не отняли у чародеев Короля-лича их приспособления, то рано или поздно моя воля была бы сломлена, и я была бы обречена на вечную муку нежизни. Перед вами лежит та, которой повезло меньше: некогда гордая супруга Малигоса, Синдрагоса.$B$BСмертельно раненая после предательства Нелтариона и брошенная умирать в снегах Ледяной Короны, теперь она живет только ненавистью. Тем не менее, за покровом злобы все еще скрывается дух благородной королевы драконов. Я верю, что у души Синдрагосы все еще есть шанс обрести покой.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Смертные, вы спасли меня от участи худшей, чем гибель. Если бы вы не отняли у чародеев Короля-лича их приспособления, то рано или поздно моя воля была бы сломлена, и я была бы обречена на вечную муку нежизни. Перед вами лежит та, которой повезло меньше: некогда гордая супруга Малигоса, Синдрагоса.$B$BСмертельно раненая после предательства Нелтариона и брошенная умирать в снегах Ледяной Короны, теперь она живет только ненавистью. Тем не менее, за покровом злобы все еще скрывается дух благородной королевы драконов. Я верю, что у души Синдрагосы все еще есть шанс обрести покой.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15381,'Приветствую тебя, |3-6($r). Вижу, ты не $gожидал:ожидала; меня тут встретить. Не ты $gодин полон:одна полна; недоумения, и это объяснимо после того, через что вам пришлось пройти из-за моих сородичей.$B$BМного событий отделяет нас от времени разрушения Солнечного Колодца, да мало среди них радостных. Судьбе было угодно дать мне шанс восстановить былое величие нашего рода. Об этом можно долго говорить, и еще больше можно сделать; пойми лишь одно: не все синие драконы винят смертных в тех бедах, что наводнили этот мир.$B$BНекоторые из нас благословлены более глубоким пониманием.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приветствую тебя, |3-6($r). Вижу, ты не $gожидал:ожидала; меня тут встретить. Не ты $gодин полон:одна полна; недоумения, и это объяснимо после того, через что вам пришлось пройти из-за моих сородичей.$B$BМного событий отделяет нас от времени разрушения Солнечного Колодца, да мало среди них радостных. Судьбе было угодно дать мне шанс восстановить былое величие нашего рода. Об этом можно долго говорить, и еще больше можно сделать; пойми лишь одно: не все синие драконы винят смертных в тех бедах, что наводнили этот мир.$B$BНекоторые из нас благословлены более глубоким пониманием.',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`,`text1_1_loc8`) VALUES (15382,'Теперь он покинул нас навсегда, ведь так?$b$bЯ... я чувствую это.','Неужели не было способа его спасти?$b$bБоюсь, я всегда буду задавать себе этот вопрос...') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Теперь он покинул нас навсегда, ведь так?$b$bЯ... я чувствую это.',`text0_1_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Неужели не было способа его спасти?$b$bБоюсь, я всегда буду задавать себе этот вопрос...',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15385,'Приветствую тебя, друг Альянса!$B$BЯ – официальный представитель Прибамбасска, и я делаю все возможное для того, чтобы мы, бедные, угнетенные гномы, могли мирно сосуществовать с картелью Стальной Шестеренки. Возможно, мы даже с пониманием отнесемся к их новым друзьям – ордынским гоблинам. $B$BВ общем, с твоей помощью мы наверняка найдем какое-нибудь дипломатическое решение!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Приветствую тебя, друг Альянса!$B$BЯ – официальный представитель Прибамбасска, и я делаю все возможное для того, чтобы мы, бедные, угнетенные гномы, могли мирно сосуществовать с картелью Стальной Шестеренки. Возможно, мы даже с пониманием отнесемся к их новым друзьям – ордынским гоблинам. $B$BВ общем, с твоей помощью мы наверняка найдем какое-нибудь дипломатическое решение!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15395,'Я даже не знаю, как пользоваться этим оружием... но, полагаю, если я просто буду стоять здесь с грозным видом, воргены предпочтут обойти меня стороной.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я даже не знаю, как пользоваться этим оружием... но, полагаю, если я просто буду стоять здесь с грозным видом, воргены предпочтут обойти меня стороной.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15400,'Ты $gлюбознателен:любознательна;, $gмолодой:молодая:c; |3-6($c). Начертатели могут создавать могущественные карты Таро, хотя и им не дано удерживать в узде свои творения. Все решает судьба.$b$bЕсли тебе удастся собрать полную колоду, приноси ее мне, и я щедро награжу тебя.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты $gлюбознателен:любознательна;, $gмолодой:молодая:c; |3-6($c). Начертатели могут создавать могущественные карты Таро, хотя и им не дано удерживать в узде свои творения. Все решает судьба.$b$bЕсли тебе удастся собрать полную колоду, приноси ее мне, и я щедро награжу тебя.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15403,'Эй, малыш. Ты просто молодчина!$B$BДо встречи на той стороне.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эй, малыш. Ты просто молодчина!$B$BДо встречи на той стороне.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15404,'От всех этих разговоров про еду у меня аппетит разыгрался!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','От всех этих разговоров про еду у меня аппетит разыгрался!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15419,'На ЭТО я не подписывалась! Пигмеи, зомби... Хобарту следует серьезно увеличить мое жалование!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','На ЭТО я не подписывалась! Пигмеи, зомби... Хобарту следует серьезно увеличить мое жалование!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15420,'И только я подумала, что худшее уже позади...') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','И только я подумала, что худшее уже позади...',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15421,'Что мы здесь делаем? Нам же вроде нужно думать о том, как убраться с этого острова?!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что мы здесь делаем? Нам же вроде нужно думать о том, как убраться с этого острова?!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15422,'Городок-из-табакерки – это настоящий шедевр инженерной мысли!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Городок-из-табакерки – это настоящий шедевр инженерной мысли!',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15427,'Конечно, малыш!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Конечно, малыш!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15431,'Да-да, все это очень интересно, но, как видишь, мы тут сражаемся не на жизнь, а на смерть, и эти пигмеи – просто ничто по сравнению с тварью, которая сидит в той пещере!$B$BИ куда подевалась моя безмозглая ассистентка? Вечно ее нет на месте! Наверное, она сейчас сидит где-нибудь и ноет, что никому не интересно, как у нее дела...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да-да, все это очень интересно, но, как видишь, мы тут сражаемся не на жизнь, а на смерть, и эти пигмеи – просто ничто по сравнению с тварью, которая сидит в той пещере!$B$BИ куда подевалась моя безмозглая ассистентка? Вечно ее нет на месте! Наверное, она сейчас сидит где-нибудь и ноет, что никому не интересно, как у нее дела...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15432,'Где угодно, но не здесь...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Где угодно, но не здесь...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15434,'Не понимаю, зачем этим ограм впустую прожигать жизнь, сидя здесь в песках, когда они могли бы присоединиться к Орде и трудиться для нас.$b$bЯ имею в виду, взгляни на них! Если не мы начнем их эксплуатировать, то кто?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Не понимаю, зачем этим ограм впустую прожигать жизнь, сидя здесь в песках, когда они могли бы присоединиться к Орде и трудиться для нас.$b$bЯ имею в виду, взгляни на них! Если не мы начнем их эксплуатировать, то кто?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`,`text3_0_loc8`) VALUES (15435,'Что надо?','Смешной огр.','Моя голоден.','Моя не любить пески.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что надо?',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Смешной огр.',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Моя голоден.',`text2_0_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Моя не любить пески.',`text3_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15444,'Моя помогать мадам гоблину дружить с ограми.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Моя помогать мадам гоблину дружить с ограми.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
