INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15455,'<Несчастный солдат, найденный вами на обочине, выглядит так, как будто ему вспороли живот длинными ножами. Перевернув тело, вы замечаете следы зубов.>$b$b<Могли ли это сделать дикие животные?>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Несчастный солдат, найденный вами на обочине, выглядит так, как будто ему вспороли живот длинными ножами. Перевернув тело, вы замечаете следы зубов.>$b$b<Могли ли это сделать дикие животные?>',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15458,'Сегодня мы свели старые счеты.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Сегодня мы свели старые счеты.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15459,'Посмотри на этот ужас. А мне говорили, что Степи выглядят как… степи.$b$bЭти заросли появились за ночь и уже поглотили мой лагерь и отрезали его от всех дорог!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Посмотри на этот ужас. А мне говорили, что Степи выглядят как… степи.$b$bЭти заросли появились за ночь и уже поглотили мой лагерь и отрезали его от всех дорог!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (15461,'Убирайся вон, |3-6($c). Ты не нужен мне на охоте.','Убирайся вон, |3-6($c). Ты не нужна мне на охоте.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Убирайся вон, |3-6($c). Ты не нужен мне на охоте.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Убирайся вон, |3-6($c). Ты не нужна мне на охоте.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15466,'Итак, ты хочешь найти легендарный меч Песчаной Бури?$b$bТы $gготов:готова; убивать ради Суль\'траз? Обагрить пески кровью? В поисках сокровища и могущества?$b$bЕсли да... Добро пожаловать в пустыню.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Итак, ты хочешь найти легендарный меч Песчаной Бури?$b$bТы $gготов:готова; убивать ради Суль\'траз? Обагрить пески кровью? В поисках сокровища и могущества?$b$bЕсли да... Добро пожаловать в пустыню.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15468,'Я лично приму меры, чтобы Черное Копье получило ту власть, на которую имеет право.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я лично приму меры, чтобы Черное Копье получило ту власть, на которую имеет право.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15471,'Я уж не первый раз застреваю в зарослях вроде этих, где и не повернешься. Где я только не был, $gсынок:дочка;, и задери меня свинобраз – я не собираюсь оканчивать свои дни в этой чаще.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я уж не первый раз застреваю в зарослях вроде этих, где и не повернешься. Где я только не был, $gсынок:дочка;, и задери меня свинобраз – я не собираюсь оканчивать свои дни в этой чаще.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15474,'Знаешь, почему его называют крепким? Потому что когда оно к тебе скатится, уже не до аргументов и разговоров. Не остается ни угрызений совести, ни страха, ни сожалений.$b$bЭто как пивная лавина, которая все сносит на своем пути.$b$bВ общем, оно скатилось и ударилось о здание приюта у подножия холма, а потом нырнуло в грязную лужу, а потом... впрочем, я не помню, чем кончилась эта история. А хочешь посмотреть на татуировку?$b$b<Старый грязный Пит стаскивает штаны.>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Знаешь, почему его называют крепким? Потому что когда оно к тебе скатится, уже не до аргументов и разговоров. Не остается ни угрызений совести, ни страха, ни сожалений.$b$bЭто как пивная лавина, которая все сносит на своем пути.$b$bВ общем, оно скатилось и ударилось о здание приюта у подножия холма, а потом нырнуло в грязную лужу, а потом... впрочем, я не помню, чем кончилась эта история. А хочешь посмотреть на татуировку?$b$b<Старый грязный Пит стаскивает штаны.>',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15475,'Видишь эту пушку, $gпарень:девушка;?$b$b<Старый грязный Пит небрежно размахивает оружием прямо у вас перед лицом.>$b$bЭта самая пушка побывала уже на всех континентах Нордскола. Она спасла больше жизней, чем число, до которого я умею считать! Семь. Как-то "Большой Маки" МакДангл – не младший МакДангл, а его папочка – предлагал мне свою младшую дочку за мою пушку.$b$bСкажу пару слов об Эди – у нее и этой пушки много общего. Рот широкий. Зубы торчат. Дело иметь опасно. Любит неопытных.$b$bТы $gслышал:слышала; историю о том, как молодая Эди поспорила с Чаком Брэндибородом на 25 серебряных, что сможет так ему вдарить, что у него сопли хлынут?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Видишь эту пушку, $gпарень:девушка;?$b$b<Старый грязный Пит небрежно размахивает оружием прямо у вас перед лицом.>$b$bЭта самая пушка побывала уже на всех континентах Нордскола. Она спасла больше жизней, чем число, до которого я умею считать! Семь. Как-то "Большой Маки" МакДангл – не младший МакДангл, а его папочка – предлагал мне свою младшую дочку за мою пушку.$b$bСкажу пару слов об Эди – у нее и этой пушки много общего. Рот широкий. Зубы торчат. Дело иметь опасно. Любит неопытных.$b$bТы $gслышал:слышала; историю о том, как молодая Эди поспорила с Чаком Брэндибородом на 25 серебряных, что сможет так ему вдарить, что у него сопли хлынут?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15476,'Ну вот, а молва-то распространяется быстро. И скоро уже весь Менетил собрался, чтобы посмотреть, сделать ставки. И торговцы фруктами туда же. И все ругались по поводу правил, пока сам мэр не сказал, что кровь считаться не будет.$b$bНу и Чак встал на колени, а она залезла на табурет и КАК ДАСТ ему своей большой толстой ногой... Но я отвлекаюсь от темы. Смысл в том, что на сделку соглашаться не стоило.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ну вот, а молва-то распространяется быстро. И скоро уже весь Менетил собрался, чтобы посмотреть, сделать ставки. И торговцы фруктами туда же. И все ругались по поводу правил, пока сам мэр не сказал, что кровь считаться не будет.$b$bНу и Чак встал на колени, а она залезла на табурет и КАК ДАСТ ему своей большой толстой ногой... Но я отвлекаюсь от темы. Смысл в том, что на сделку соглашаться не стоило.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15477,'Меня не всегда называли Старым грязным Питом.$b$bОднажды, когда я был еще молодым и грязным, я подумал, что смогу произвести впечатление на одну красотку по имени Бэлли тем, как я работаю зубилом.$b$bСтарушка Бэлли! Раньше она была не такая. Крепко сбитая. Со всеми округлостями.$b$bЯ раздобыл глыбу известняка, белого, как ее кожа, и начал вырезать, выбивать то, что, я считал, будет шедевром. Но ошибся в масштабах. И все закончилось огромной... что ты думаешь? Задницей.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Меня не всегда называли Старым грязным Питом.$b$bОднажды, когда я был еще молодым и грязным, я подумал, что смогу произвести впечатление на одну красотку по имени Бэлли тем, как я работаю зубилом.$b$bСтарушка Бэлли! Раньше она была не такая. Крепко сбитая. Со всеми округлостями.$b$bЯ раздобыл глыбу известняка, белого, как ее кожа, и начал вырезать, выбивать то, что, я считал, будет шедевром. Но ошибся в масштабах. И все закончилось огромной... что ты думаешь? Задницей.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15478,'Слышишь, $gпарень:девушка; – задницей! Не слишком-то подходящий подарок для леди. Но ей понравилось. Я предложил отдать ее в местную пивную.$b$bОни называли ее задницей грязного Пита и в конце концов пивную тоже назвали так. А потом пивную сожгли орки, и все, что осталось на сегодняшний день, это моя большая почерневшая задница в куче щебня.$b$b<Старый грязный Пит роняет слезу.>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Слышишь, $gпарень:девушка; – задницей! Не слишком-то подходящий подарок для леди. Но ей понравилось. Я предложил отдать ее в местную пивную.$b$bОни называли ее задницей грязного Пита и в конце концов пивную тоже назвали так. А потом пивную сожгли орки, и все, что осталось на сегодняшний день, это моя большая почерневшая задница в куче щебня.$b$b<Старый грязный Пит роняет слезу.>',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15479,'Про войну – не эту, а ту, когда орки ездили на драконах? Мы с Уистлером решили добраться от Южнобережья до Гавани Менетилов в шлюпке, которую сами вырубили из узловатой сосны, предварительно нализавшись вишневым грогом.$b$bИ вроде мы проделали уже треть пути, так как вокруг нас не было ничего кроме воды, когда я почувствовал, что ноги у меня мокрые.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Про войну – не эту, а ту, когда орки ездили на драконах? Мы с Уистлером решили добраться от Южнобережья до Гавани Менетилов в шлюпке, которую сами вырубили из узловатой сосны, предварительно нализавшись вишневым грогом.$b$bИ вроде мы проделали уже треть пути, так как вокруг нас не было ничего кроме воды, когда я почувствовал, что ноги у меня мокрые.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15480,'Я хочу сказать кое-что об узловатой сосне. У узловатой сосны, $gсынок:дочка;, есть узлы. Узлы – это просто такие большие пустоты в деревьях, из-за чего шлюпки получаются дурацкие, и я обвинил в этом Уистлера. Но у него было свое собственное мнение по поводу моего выбора смолы для шлюпки (мой выбор был – забыть о смоле), так что мы решили решить этот вопрос при помощи выпивки.$b$bКогда закончился грог, я обнаружил, что мы с ним деремся на ножах. Просто так, чтобы размяться.$b$bКороче, до Менетила мы так и не добрались, и я почти уверен, что либо один из нас, либо мы оба потонули.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я хочу сказать кое-что об узловатой сосне. У узловатой сосны, $gсынок:дочка;, есть узлы. Узлы – это просто такие большие пустоты в деревьях, из-за чего шлюпки получаются дурацкие, и я обвинил в этом Уистлера. Но у него было свое собственное мнение по поводу моего выбора смолы для шлюпки (мой выбор был – забыть о смоле), так что мы решили решить этот вопрос при помощи выпивки.$b$bКогда закончился грог, я обнаружил, что мы с ним деремся на ножах. Просто так, чтобы размяться.$b$bКороче, до Менетила мы так и не добрались, и я почти уверен, что либо один из нас, либо мы оба потонули.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15481,'Здесь в Степях можно отлично поохотиться, если кишка у тебя не тонка.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здесь в Степях можно отлично поохотиться, если кишка у тебя не тонка.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15482,'Мы по-прежнему отрезаны от передовой ставки, но благодаря твоим "переговорам" со свинобразами мы сможем освободить дороги ценой небольших усилий.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы по-прежнему отрезаны от передовой ставки, но благодаря твоим "переговорам" со свинобразами мы сможем освободить дороги ценой небольших усилий.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15483,'Капрал неплохой человек, но когда дело доходит до приказов, его взгляды не назвать широкими.$b$bЧто-то происходит со здешними землями, $n. В этом месте не должно быть джунглей!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Капрал неплохой человек, но когда дело доходит до приказов, его взгляды не назвать широкими.$b$bЧто-то происходит со здешними землями, $n. В этом месте не должно быть джунглей!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15484,'Люди видят в ящерах лишь дикость и жестокость, но на самом деле, они по-своему хитры и справедливы. Нам не дано понять это.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Люди видят в ящерах лишь дикость и жестокость, но на самом деле, они по-своему хитры и справедливы. Нам не дано понять это.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15485,'Ты хочешь участвовать в битве с нагами?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты хочешь участвовать в битве с нагами?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15486,'Отойди от меня, чудовище! Не смотри... я ужасно выгляжу!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Отойди от меня, чудовище! Не смотри... я ужасно выгляжу!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15487,'Что ты здесь делаешь? Убирайся прочь!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Что ты здесь делаешь? Убирайся прочь!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15488,'Прежде всего, меня не надо спасать. А во-вторых, даже если бы было надо – я бы не позволила такому чудовищу к себе прикоснуться!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Прежде всего, меня не надо спасать. А во-вторых, даже если бы было надо – я бы не позволила такому чудовищу к себе прикоснуться!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15489,'Я не нежить, понятно? Во всяком случае, буду таковой недолго. Отец спасет меня, я уверена...') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я не нежить, понятно? Во всяком случае, буду таковой недолго. Отец спасет меня, я уверена...',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15490,'Никогда прежде я так не гордился принадлежностью к Черному Копью. Вол\'джин ведет нас к победе.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Никогда прежде я так не гордился принадлежностью к Черному Копью. Вол\'джин ведет нас к победе.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15495,'Как тебя зовут, |3-6($c)? $n?$b$bДобро пожаловать в Степи. Пойдешь на передовую, туда, где разворачиваются самые важные боевые действия на этом континенте. Для меня будет большой честью, если ты поможешь нам.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Как тебя зовут, |3-6($c)? $n?$b$bДобро пожаловать в Степи. Пойдешь на передовую, туда, где разворачиваются самые важные боевые действия на этом континенте. Для меня будет большой честью, если ты поможешь нам.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15496,'Я хочу, чтобы ты $gзнал:знала;, что я очень ценю твою помощь, |3-6($c). Мы здесь деремся не с дикими зверями, а с хитрым и фанатичным неприятелем. Нам надо держаться вместе.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я хочу, чтобы ты $gзнал:знала;, что я очень ценю твою помощь, |3-6($c). Мы здесь деремся не с дикими зверями, а с хитрым и фанатичным неприятелем. Нам надо держаться вместе.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15500,'Это дико! Вол\'джин не бездельничает. Он отомстит морской ведьме.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Это дико! Вол\'джин не бездельничает. Он отомстит морской ведьме.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`,`text2_0_loc8`,`text2_1_loc8`,`text3_0_loc8`,`text3_1_loc8`,`text4_0_loc8`,`text4_1_loc8`,`text5_0_loc8`,`text5_1_loc8`) VALUES (15501,'Эй, $gпарень:девица;, мне тоже принадлежит кусочек этого пирога.','Эй, $gпарень:девица;, мне тоже принадлежит кусочек этого пирога.','Детка, это тебе нужно? Ну так забирай!','Детка, это тебе нужно? Ну так забирай!','Не мешкай, |3-6($c)! Собирай все, что можешь!','Не мешкай, |3-6($c)! Собирай все, что можешь!','Какое тело таурена ни обыщешь – все один бисер и бесполезный мусор. Удалось найти что-нибудь ценное?','Какое тело таурена ни обыщешь – все один бисер и бесполезный мусор. Удалось найти что-нибудь ценное?','Эй, |3-6($c)! Похоже, здесь уже многие побывали, но все затраты времени на поиски чего-либо ценного окупаются.','Эй, |3-6($c)! Похоже, здесь уже многие побывали, но все затраты времени на поиски чего-либо ценного окупаются.','Э-э, ты же сюда не арестовывать нас $gпришел:пришла;, так?','Э-э, ты же сюда не арестовывать нас $gпришел:пришла;, так?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эй, $gпарень:девица;, мне тоже принадлежит кусочек этого пирога.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Эй, $gпарень:девица;, мне тоже принадлежит кусочек этого пирога.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Детка, это тебе нужно? Ну так забирай!',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Детка, это тебе нужно? Ну так забирай!',`text1_1_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Не мешкай, |3-6($c)! Собирай все, что можешь!',`text2_0_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Не мешкай, |3-6($c)! Собирай все, что можешь!',`text2_1_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Какое тело таурена ни обыщешь – все один бисер и бесполезный мусор. Удалось найти что-нибудь ценное?',`text3_0_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','Какое тело таурена ни обыщешь – все один бисер и бесполезный мусор. Удалось найти что-нибудь ценное?',`text3_1_loc8`), `text4_0_loc8`=IF(`text4_0_loc8` IS NULL OR `text4_0_loc8`='','Эй, |3-6($c)! Похоже, здесь уже многие побывали, но все затраты времени на поиски чего-либо ценного окупаются.',`text4_0_loc8`), `text4_1_loc8`=IF(`text4_1_loc8` IS NULL OR `text4_1_loc8`='','Эй, |3-6($c)! Похоже, здесь уже многие побывали, но все затраты времени на поиски чего-либо ценного окупаются.',`text4_1_loc8`), `text5_0_loc8`=IF(`text5_0_loc8` IS NULL OR `text5_0_loc8`='','Э-э, ты же сюда не арестовывать нас $gпришел:пришла;, так?',`text5_0_loc8`), `text5_1_loc8`=IF(`text5_1_loc8` IS NULL OR `text5_1_loc8`='','Э-э, ты же сюда не арестовывать нас $gпришел:пришла;, так?',`text5_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15504,'Я ожидаю, что эта операция пройдет без серьезных происшествий.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я ожидаю, что эта операция пройдет без серьезных происшествий.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15508,'Пока вулкан извергался, всех твоих друзей взял в плен торговый принц Галливикс.$B$BЕсли мы хотим спасти их и выбраться с этого острова, то нам нужно быстро разобраться с силами Альянса.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Пока вулкан извергался, всех твоих друзей взял в плен торговый принц Галливикс.$B$BЕсли мы хотим спасти их и выбраться с этого острова, то нам нужно быстро разобраться с силами Альянса.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15510,'Работать на Джерода не так уж и плохо. Время от времени он, может быть, и выходит из себя, зато платит отлично, а иногда даже подсаживает меня, если я не могу добраться до чего-то на телеге.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Работать на Джерода не так уж и плохо. Время от времени он, может быть, и выходит из себя, зато платит отлично, а иногда даже подсаживает меня, если я не могу добраться до чего-то на телеге.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15511,'Что я могу сделать для тебя?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что я могу сделать для тебя?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15512,'<Страж смерти Симмер выжидающе смотрит на вас.>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Страж смерти Симмер выжидающе смотрит на вас.>',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15514,'Выиграть войну может любой дикарь. Настоящий герой не только побеждает в битве, но еще и добивается мира после падения последней стрелы.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Выиграть войну может любой дикарь. Настоящий герой не только побеждает в битве, но еще и добивается мира после падения последней стрелы.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15515,'Твоя помощь здесь в Степях, $n, неоценима.$b$bС такими героями, как ты, мы защитим Калимдор и добьемся установления мира в наших землях.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Твоя помощь здесь в Степях, $n, неоценима.$b$bС такими героями, как ты, мы защитим Калимдор и добьемся установления мира в наших землях.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15516,'Вождь обещал спасти наш народ и разобраться с Галливиксом, если мы поможем ему победить войска Альянса.$B$BПо-моему, это справедливо. Враг моего друга – мой враг, верно?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Вождь обещал спасти наш народ и разобраться с Галливиксом, если мы поможем ему победить войска Альянса.$B$BПо-моему, это справедливо. Враг моего друга – мой враг, верно?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15518,'Только между нами, боюсь, что наш прекрасный генерал не хочет делать то, что должно быть сделано.$b$bМы имеем дело с Ордой. История говорит о том, что сосуществовать с ними в мире невозможно.$b$bНашей целью должно быть… их полное уничтожение.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Только между нами, боюсь, что наш прекрасный генерал не хочет делать то, что должно быть сделано.$b$bМы имеем дело с Ордой. История говорит о том, что сосуществовать с ними в мире невозможно.$b$bНашей целью должно быть… их полное уничтожение.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15519,'Ты же не $gдумал:думала; что ворген вроде меня умеет готовить стейки.$b$bЯ люблю сырое мясо… Еще дрожащее… Когда кровь из артерий бьет мне в лицо…$b$bО чем мы говорили? Ах, да! В Гилнеасе я был гурманом.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты же не $gдумал:думала; что ворген вроде меня умеет готовить стейки.$b$bЯ люблю сырое мясо… Еще дрожащее… Когда кровь из артерий бьет мне в лицо…$b$bО чем мы говорили? Ах, да! В Гилнеасе я был гурманом.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15524,'Куда-то идешь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Куда-то идешь?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15526,'Чем могу быть полезна?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Чем могу быть полезна?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15527,'Ты $gготов:готова; начать обряд?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты $gготов:готова; начать обряд?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15528,'Мы делаем все, что в наших силах, чтобы помочь земле залечить раны. Это было достаточно трудно и до того, как на нас стали нападать по ночам.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы делаем все, что в наших силах, чтобы помочь земле залечить раны. Это было достаточно трудно и до того, как на нас стали нападать по ночам.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15529,'Я сейчас немного занята, |3-6($c)... $gБудь добр:Будь добра;, зайди попозже.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я сейчас немного занята, |3-6($c)... $gБудь добр:Будь добра;, зайди попозже.',`text0_1_loc8`);
