INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15530,'Наше оборудование в самом деле пострадало здесь!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Наше оборудование в самом деле пострадало здесь!',`text0_1_loc8`);
