INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`,`text3_0_loc8`) VALUES (15531,'Симмер говорит, у Толстяка есть кишки, но нет мозгов. Что он имеет в виду?','Толстяк любит собирать цветы. Собирать цветы все равно что убивать.','Здесь сквозит.','Юхан говорит, Толстяку требуется швея, чтобы починить брюхо.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Симмер говорит, у Толстяка есть кишки, но нет мозгов. Что он имеет в виду?',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Толстяк любит собирать цветы. Собирать цветы все равно что убивать.',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Здесь сквозит.',`text2_0_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Юхан говорит, Толстяку требуется швея, чтобы починить брюхо.',`text3_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15532,'От имени блистательного и все еще нейтрального картеля Хитрой Шестеренки выражаю надежду, что тебе понравится здесь.$b$bЗапомни, в Прибамбасске рады всем! Всем, кроме пиратов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','От имени блистательного и все еще нейтрального картеля Хитрой Шестеренки выражаю надежду, что тебе понравится здесь.$b$bЗапомни, в Прибамбасске рады всем! Всем, кроме пиратов.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15534,'Кровь павших вопиет об отмщении.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Кровь павших вопиет об отмщении.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15535,'Мы не имеем права на промедление. Форт Триумфа должен быть достроен и вооружен, или мы можем оставить всякую надежду на завоевание этого континента.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы не имеем права на промедление. Форт Триумфа должен быть достроен и вооружен, или мы можем оставить всякую надежду на завоевание этого континента.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15536,'Когда меня и моих наемников Громового Молота наняли для обеспечения безопасности Форта Триумфа, я ожидал, что мы будем драться с Ордой.$b$bНо нас осаждают со всех сторон! Гоблины-подрывники, жуки, роющие норы, ящерицы…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Когда меня и моих наемников Громового Молота наняли для обеспечения безопасности Форта Триумфа, я ожидал, что мы будем драться с Ордой.$b$bНо нас осаждают со всех сторон! Гоблины-подрывники, жуки, роющие норы, ящерицы…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15537,'Боевой Шрам – опасное место. Никакое оружие в мире не спасет паровой танк, если его поглощает сама земля.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Боевой Шрам – опасное место. Никакое оружие в мире не спасет паровой танк, если его поглощает сама земля.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15538,'Мои разработки значительно опережают время, $n.$b$bПосмотри на эти чертежи! Это разработки будущего.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мои разработки значительно опережают время, $n.$b$bПосмотри на эти чертежи! Это разработки будущего.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15539,'Конечно, еще нужна доработка. Но все же минитанк – это чудо инженерной мысли.$b$bДля него требуется лишь четверть материалов, необходимых для машины обычного размера, и сделать его может любой! Даже тот, у кого совсем маленькие руки!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Конечно, еще нужна доработка. Но все же минитанк – это чудо инженерной мысли.$b$bДля него требуется лишь четверть материалов, необходимых для машины обычного размера, и сделать его может любой! Даже тот, у кого совсем маленькие руки!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15540,'Картель Трюмных Вод будет вести здесь дела до скончания дней, запомни мои слова.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Картель Трюмных Вод будет вести здесь дела до скончания дней, запомни мои слова.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15543,'Наверное, на этом острове осталось только одно неплохое местечко... и оно прямо рядом с вулканом!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Наверное, на этом острове осталось только одно неплохое местечко... и оно прямо рядом с вулканом!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15550,'Ты идешь туда? Лично я – нет!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты идешь туда? Лично я – нет!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15551,'Опусти монеты.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Опусти монеты.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15552,'Это моя работа, |3-6($c). Генерал занимается обходом, а я несу его знамя и втыкаю его в землю.$b$bНельзя же представить генерала на прогулке без знамени. Это как если бы он вышел без штанов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Это моя работа, |3-6($c). Генерал занимается обходом, а я несу его знамя и втыкаю его в землю.$b$bНельзя же представить генерала на прогулке без знамени. Это как если бы он вышел без штанов.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15554,'Эй! Руки прочь от флага, $gсынок:детка;.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эй! Руки прочь от флага, $gсынок:детка;.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15556,'Все было легко и просто до тех пор, пока эта тупица не появилась здесь, да еще и с целой армией гномов.$b$BГалливикс голову мне снимет, если мы позволим этим мерзким недоумкам опередить нас.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Все было легко и просто до тех пор, пока эта тупица не появилась здесь, да еще и с целой армией гномов.$b$BГалливикс голову мне снимет, если мы позволим этим мерзким недоумкам опередить нас.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15558,'Не прохлаждайся слишком долго – у нас здесь много дел.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не прохлаждайся слишком долго – у нас здесь много дел.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15559,'Так было всегда – драки приводили к убийству, убийства приводили к войнам, и такова была судьба всех наших посетителей.$B$BТеперь если настоящие мужчины хотят подраться, они приходят сюда, и на этом все заканчивается! К обоюдному удовольствию и взаимовыгоде...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Так было всегда – драки приводили к убийству, убийства приводили к войнам, и такова была судьба всех наших посетителей.$B$BТеперь если настоящие мужчины хотят подраться, они приходят сюда, и на этом все заканчивается! К обоюдному удовольствию и взаимовыгоде...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15561,'Я слыхал об этом парне по имени Эрнестуэй из Тернистой долины. Говорят, он охотится на любых животных из спортивного интереса.$b$bСПОРТИВНОГО. Что за идиот, верно? Ты только подумай о чистой прибыли, которая остается разлагаться под солнцем!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я слыхал об этом парне по имени Эрнестуэй из Тернистой долины. Говорят, он охотится на любых животных из спортивного интереса.$b$bСПОРТИВНОГО. Что за идиот, верно? Ты только подумай о чистой прибыли, которая остается разлагаться под солнцем!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15564,'В этом ветролете только одно место, но ведь всегда можно разместиться на фюзеляже. Это абсолютно безопасно.$b$bТы $gготов:готова;?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','В этом ветролете только одно место, но ведь всегда можно разместиться на фюзеляже. Это абсолютно безопасно.$b$bТы $gготов:готова;?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15565,'Это мой помощник.$B$BЧума подействовала на него не так, как на всех нас, но он определенно подвержен ее действию. Он преклонял колено перед Сильваной так же, как ты и я.$b$bПравда, если уж быть совсем честным... мне кажется, он подволакивал колено еще до того, как ступил в палаты Темной Госпожи!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Это мой помощник.$B$BЧума подействовала на него не так, как на всех нас, но он определенно подвержен ее действию. Он преклонял колено перед Сильваной так же, как ты и я.$b$bПравда, если уж быть совсем честным... мне кажется, он подволакивал колено еще до того, как ступил в палаты Темной Госпожи!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15566,'Мы должны спасти всех и убраться отсюда, пока этот вулкан не взорвался по-настоящему!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мы должны спасти всех и убраться отсюда, пока этот вулкан не взорвался по-настоящему!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`) VALUES (15569,'Готовься, |3-6($r).$B$BНаги могут начать атаку в любую минуту.','Этот регион – один из эпицентров катаклизма, который угрожает расколоть наш мир на части.$B$BЕсли нам удастся выжить, мы должны узнать, что было ему причиной.','Нападения на эти корабли были явно не случайными.$B$BМы должны выяснить, какова цель наг.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Готовься, |3-6($r).$B$BНаги могут начать атаку в любую минуту.',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Этот регион – один из эпицентров катаклизма, который угрожает расколоть наш мир на части.$B$BЕсли нам удастся выжить, мы должны узнать, что было ему причиной.',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Нападения на эти корабли были явно не случайными.$B$BМы должны выяснить, какова цель наг.',`text2_0_loc8`);
