INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15572,'Что-нибудь нужно?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что-нибудь нужно?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15578,'Пришло время изгнанникам вернуться.$b$bПусть нашим домом вновь станет Гномреган!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Пришло время изгнанникам вернуться.$b$bПусть нашим домом вновь станет Гномреган!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15580,'Под крышей дома дворфов мы были в безопасности, и мы благодарны им за это. Но теперь, когда царствованию Термоштепселя в Гномрегане пришел конец, эти дни уходят в историю. Слишком долго Гномреган терзали непродуманные последствия нашей ошибки. Взрыв радиационной бомбы уничтожил все шансы на возвращение туда, но теперь у нас есть технологии, с помощью которых мы сможем все исправить!$b$bМы должны справедливо покарать Термоштепселя и забрать то, что по праву принадлежит нам!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Под крышей дома дворфов мы были в безопасности, и мы благодарны им за это. Но теперь, когда царствованию Термоштепселя в Гномрегане пришел конец, эти дни уходят в историю. Слишком долго Гномреган терзали непродуманные последствия нашей ошибки. Взрыв радиационной бомбы уничтожил все шансы на возвращение туда, но теперь у нас есть технологии, с помощью которых мы сможем все исправить!$b$bМы должны справедливо покарать Термоштепселя и забрать то, что по праву принадлежит нам!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15581,'Операция "Гномреган" разделена на несколько этапов.$b$BВ первую очередь мы должны захватить воздушную башню! Тогда наши самолеты обеспечат поддержку с воздуха продвигающимся в Гномреган отрядам.$b$bКроме того, в одном из зданий у входа в Гномреган обнаружен склад боевых роботов. Когда мы их заполучим, уже никто не сможет нас остановить.$b$BИ тогда мы направимся прямиком к Термоштепселю!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Операция "Гномреган" разделена на несколько этапов.$b$BВ первую очередь мы должны захватить воздушную башню! Тогда наши самолеты обеспечат поддержку с воздуха продвигающимся в Гномреган отрядам.$b$bКроме того, в одном из зданий у входа в Гномреган обнаружен склад боевых роботов. Когда мы их заполучим, уже никто не сможет нас остановить.$b$BИ тогда мы направимся прямиком к Термоштепселю!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15585,'Вагонетка готова к отправке.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вагонетка готова к отправке.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15586,'Добро пожаловать на поле боя, |3-6($c)! Сидя целыми днями в крепости, невозможно получить представление о тактической ситуации. Лучше все попробовать на своей шкуре.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать на поле боя, |3-6($c)! Сидя целыми днями в крепости, невозможно получить представление о тактической ситуации. Лучше все попробовать на своей шкуре.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15588,'Ты $gбыл:была; в Бейл Модане? Что там происходит?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты $gбыл:была; в Бейл Модане? Что там происходит?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15589,'Они заплатят, $n. Все они заплатят.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Они заплатят, $n. Все они заплатят.',`text0_0_loc8`);
