INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15629,'Ни землетрясение, ни наводнение, ни любое другое стихийное бедствие не способны заставить меня покинуть службу.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ни землетрясение, ни наводнение, ни любое другое стихийное бедствие не способны заставить меня покинуть службу.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15631,'Нет, честно, как же все эти недотепы попадают в плен? Это абсолютная некомпетентность, вот что я скажу!$B$BПосле таких случаев почти начинаешь стыдиться того, что ты гоблин.$B$BКстати о стыде! Где эта стыдоба, моя ассистентка? Наверняка опять прохлаждается.$B$BО, как тяжела ноша гения! Полагаю, именно мне придется вызволять всех нас из этой переделки.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Нет, честно, как же все эти недотепы попадают в плен? Это абсолютная некомпетентность, вот что я скажу!$B$BПосле таких случаев почти начинаешь стыдиться того, что ты гоблин.$B$BКстати о стыде! Где эта стыдоба, моя ассистентка? Наверняка опять прохлаждается.$B$BО, как тяжела ноша гения! Полагаю, именно мне придется вызволять всех нас из этой переделки.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15632,'Мы здесь, чтобы отдать дань уважения великому лесу и почтить дары Матери-Земли.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы здесь, чтобы отдать дань уважения великому лесу и почтить дары Матери-Земли.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15633,'Ты $gпришел:пришла;, чтобы помочь, |3-6($c)? Эта долина – настоящее бутылочное горлышко. Если мы сможем перекрыть путь поставки припасов, то выиграем время. Оно необходимо нашим товарищам у Древа Жизни, чтобы организовать контрнаступление.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты $gпришел:пришла;, чтобы помочь, |3-6($c)? Эта долина – настоящее бутылочное горлышко. Если мы сможем перекрыть путь поставки припасов, то выиграем время. Оно необходимо нашим товарищам у Древа Жизни, чтобы организовать контрнаступление.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15634,'Я не понимаю, откуда могут поступать эти припасы. Сумеречный Молот каким-то образом нашел способ осадить гору со всех сторон.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я не понимаю, откуда могут поступать эти припасы. Сумеречный Молот каким-то образом нашел способ осадить гору со всех сторон.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15639,'<Похоже, эта механическая горилла сломана.>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Похоже, эта механическая горилла сломана.>',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15641,'Чего ты хочешь, |3-6($r)?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Чего ты хочешь, |3-6($r)?',`text0_1_loc8`);
