INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15642,'Не испугал ли я тебя, |3-6($r)?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не испугал ли я тебя, |3-6($r)?',`text0_0_loc8`);
