INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15643,'Что-то не так, $gприятель:подруга;?.. Никогда прежде не $gвидел:видела; воргена?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что-то не так, $gприятель:подруга;?.. Никогда прежде не $gвидел:видела; воргена?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15648,'Чтоб вы провалились, проклятые каменистые дороги Дуротара! Я бы с радостью оказался где угодно, только не здесь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Чтоб вы провалились, проклятые каменистые дороги Дуротара! Я бы с радостью оказался где угодно, только не здесь.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15652,'Огры клана Гордунни слишком долго опустошали эту землю. Мы должны захватить ее и ее богатства для Орды.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Огры клана Гордунни слишком долго опустошали эту землю. Мы должны захватить ее и ее богатства для Орды.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15653,'Клан Каменного Молота служит Орде!$B$BВо времена основания Оргриммара, когда Калимдор стал новой родиной для нашего народа, герой по имени Рексар победил вождя огрского клана Каменного Молота.$B$BС тех самых пор они служат Орде, и я призвал их сюда, чтобы они сражались против клана Гордуни.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Клан Каменного Молота служит Орде!$B$BВо времена основания Оргриммара, когда Калимдор стал новой родиной для нашего народа, герой по имени Рексар победил вождя огрского клана Каменного Молота.$B$BС тех самых пор они служат Орде, и я призвал их сюда, чтобы они сражались против клана Гордуни.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15661,'<Тело Пшикса безжизненно плавает в воде. Его правая рука все еще сжимает сферу.>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Тело Пшикса безжизненно плавает в воде. Его правая рука все еще сжимает сферу.>',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15662,'<Вы схватили сферу, но рука Пшикса еще крепче обхватила ее. Сфера слегка светится.>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Вы схватили сферу, но рука Пшикса еще крепче обхватила ее. Сфера слегка светится.>',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15664,'Постарайся избегать твердых, покрытых перьями спин гарпий… эти существа очень опасны!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Постарайся избегать твердых, покрытых перьями спин гарпий… эти существа очень опасны!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15665,'Лок\'тар огар, солдат.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Лок\'тар огар, солдат.',`text0_0_loc8`);
