INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15670,'$GПарень:девочка;, мы идем в Оргриммар, а затем к нашему новому дому – Азшаре. Увидимся там!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','$GПарень:девочка;, мы идем в Оргриммар, а затем к нашему новому дому – Азшаре. Увидимся там!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15671,'Мы проделали большой путь, чтобы попасть сюда, малыш. Спасибо тебе!$B$BА теперь давай убираться с этого острова.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мы проделали большой путь, чтобы попасть сюда, малыш. Спасибо тебе!$B$BА теперь давай убираться с этого острова.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15672,'Спаси… бо…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Спаси… бо…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15677,'Вот пример неблагоприятных условий для торговли!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вот пример неблагоприятных условий для торговли!',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15678,'Какой ужас! И как же я теперь буду выкручиваться?$B$BИ кроме того... Гоблины-зомби?!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Какой ужас! И как же я теперь буду выкручиваться?$B$BИ кроме того... Гоблины-зомби?!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15680,'$GМальчик мой:Девочка моя;, у тебя все получилось!$B$BА теперь давай отправляться в Азшару – там я открою новую клинику. Отпуск выдался долгий, и я уже немного поиздержался!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','$GМальчик мой:Девочка моя;, у тебя все получилось!$B$BА теперь давай отправляться в Азшару – там я открою новую клинику. Отпуск выдался долгий, и я уже немного поиздержался!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15681,'У тебя случайно нет плана, как нам выбраться отсюда? Нет?$B$BНу, ладно. Надеюсь, что смерть от горячей лавы – это не очень больно.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','У тебя случайно нет плана, как нам выбраться отсюда? Нет?$B$BНу, ладно. Надеюсь, что смерть от горячей лавы – это не очень больно.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15685,'Рабом я не стану! Ни за что!$B$BЯ вот что скажу: тебе нужно разобраться с этой крысой – торговым принцем!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Рабом я не стану! Ни за что!$B$BЯ вот что скажу: тебе нужно разобраться с этой крысой – торговым принцем!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15688,'Мы идем в Оргриммар и Азшару. Давай выведем эту посудину в море!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы идем в Оргриммар и Азшару. Давай выведем эту посудину в море!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15689,'Брось монеты в корабль, чтобы отойти от гибнущего острова.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Брось монеты в корабль, чтобы отойти от гибнущего острова.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15690,'Давай разберемся с Физзом, прежде чем поднимать паруса. Я бью по голове, а ты – промеж ног!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Давай разберемся с Физзом, прежде чем поднимать паруса. Я бью по голове, а ты – промеж ног!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15691,'Давай раз и навсегда разберемся с этим Ехидом. В Азшаре не хватит места для нас двоих!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Давай раз и навсегда разберемся с этим Ехидом. В Азшаре не хватит места для нас двоих!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`,`text3_0_loc8`,`text3_1_loc8`,`text4_0_loc8`,`text4_1_loc8`,`text5_0_loc8`,`text5_1_loc8`,`text6_0_loc8`,`text6_1_loc8`,`text7_0_loc8`,`text7_1_loc8`) VALUES (15696,'У тебя все получилось! Мы спасены!','У тебя все получилось! Мы спасены!','Мы в самом деле отправляемся в Азшару? А там тоже есть вулкан?','Мы в самом деле отправляемся в Азшару? А там тоже есть вулкан?','На твоем месте я бы держал ухо востро. Ходят слухи, что по твоей вине взорвалась гора Каджаро и вулканы Затерянных островов.$B$BДа, я знаю, это полный бред, но люди обожают сплетни, а ради выгоды и продвижения по службе они готовы втоптать в грязь даже своих героев.','На твоем месте я бы держал ухо востро. Ходят слухи, что по твоей вине взорвалась гора Каджаро и вулканы Затерянных островов.$B$BДа, я знаю, это полный бред, но люди обожают сплетни, а ради выгоды и продвижения по службе они готовы втоптать в грязь даже своих героев.','Выходим из порта, пока вулкан нас тут всех не уничтожил!','Выходим из порта, пока вулкан нас тут всех не уничтожил!','Я жду вашего приказа, $gгосподин:госпожа;!','Я жду вашего приказа, $gгосподин:госпожа;!','Не знаю. Похоже, я буду скучать по этому острову. Здесь было весело.','Не знаю. Похоже, я буду скучать по этому острову. Здесь было весело.','У меня есть идея... давайте на этот раз мы не будем ввязываться в сражения Альянса и Орды.$B$BЕсли никто не против, конечно...','У меня есть идея... давайте на этот раз мы не будем ввязываться в сражения Альянса и Орды.$B$BЭто просто мое предложение.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','У тебя все получилось! Мы спасены!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','У тебя все получилось! Мы спасены!',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Мы в самом деле отправляемся в Азшару? А там тоже есть вулкан?',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Мы в самом деле отправляемся в Азшару? А там тоже есть вулкан?',`text1_1_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','На твоем месте я бы держал ухо востро. Ходят слухи, что по твоей вине взорвалась гора Каджаро и вулканы Затерянных островов.$B$BДа, я знаю, это полный бред, но люди обожают сплетни, а ради выгоды и продвижения по службе они готовы втоптать в грязь даже своих героев.',`text3_0_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','На твоем месте я бы держал ухо востро. Ходят слухи, что по твоей вине взорвалась гора Каджаро и вулканы Затерянных островов.$B$BДа, я знаю, это полный бред, но люди обожают сплетни, а ради выгоды и продвижения по службе они готовы втоптать в грязь даже своих героев.',`text3_1_loc8`), `text4_0_loc8`=IF(`text4_0_loc8` IS NULL OR `text4_0_loc8`='','Выходим из порта, пока вулкан нас тут всех не уничтожил!',`text4_0_loc8`), `text4_1_loc8`=IF(`text4_1_loc8` IS NULL OR `text4_1_loc8`='','Выходим из порта, пока вулкан нас тут всех не уничтожил!',`text4_1_loc8`), `text5_0_loc8`=IF(`text5_0_loc8` IS NULL OR `text5_0_loc8`='','Я жду вашего приказа, $gгосподин:госпожа;!',`text5_0_loc8`), `text5_1_loc8`=IF(`text5_1_loc8` IS NULL OR `text5_1_loc8`='','Я жду вашего приказа, $gгосподин:госпожа;!',`text5_1_loc8`), `text6_0_loc8`=IF(`text6_0_loc8` IS NULL OR `text6_0_loc8`='','Не знаю. Похоже, я буду скучать по этому острову. Здесь было весело.',`text6_0_loc8`), `text6_1_loc8`=IF(`text6_1_loc8` IS NULL OR `text6_1_loc8`='','Не знаю. Похоже, я буду скучать по этому острову. Здесь было весело.',`text6_1_loc8`), `text7_0_loc8`=IF(`text7_0_loc8` IS NULL OR `text7_0_loc8`='','У меня есть идея... давайте на этот раз мы не будем ввязываться в сражения Альянса и Орды.$B$BЕсли никто не против, конечно...',`text7_0_loc8`), `text7_1_loc8`=IF(`text7_1_loc8` IS NULL OR `text7_1_loc8`='','У меня есть идея... давайте на этот раз мы не будем ввязываться в сражения Альянса и Орды.$B$BЭто просто мое предложение.',`text7_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15701,'Вот все и закончилось, босс. Это была большая честь для меня. Я уверена, что скоро мы снова встретимся.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Вот все и закончилось, босс. Это была большая честь для меня. Я уверена, что скоро мы снова встретимся.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`,`text3_0_loc8`,`text4_0_loc8`,`text5_0_loc8`,`text6_0_loc8`,`text7_0_loc8`) VALUES (15711,'Тот\'ал Амун Ри\'Таэль вормос! Вормос! Вормос!','Аль\'та, Аль\'та бормаз. Ни бормаз та\'талл? Оно приближается, оно окутано пламенем, |3-6($r)!','Тень видит. Бо\'аль лал арви К\'тот. Гибель грядет, окутанная языками безмолвного пламени.','Мар\'кова таллоль йе\'тарин, оно знает, оно знает.','Сердце бесконечности охвачено яростью. Не заставляй меня смотреть! Я больше не могу! Я не вынесу этого!','Мы – ничто. Туллал пар\'окот. Фар\'аль, ка\'кэр. Пустота поглотит нас.','<Сумеречный слуга издает булькающие звуки, из его рта идет пена.>','Х\'тон, тьма повсюду, куда достает взор. Х\'тон марвол квалар: бесконечность ночи.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тот\'ал Амун Ри\'Таэль вормос! Вормос! Вормос!',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Аль\'та, Аль\'та бормаз. Ни бормаз та\'талл? Оно приближается, оно окутано пламенем, |3-6($r)!',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Тень видит. Бо\'аль лал арви К\'тот. Гибель грядет, окутанная языками безмолвного пламени.',`text2_0_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Мар\'кова таллоль йе\'тарин, оно знает, оно знает.',`text3_0_loc8`), `text4_0_loc8`=IF(`text4_0_loc8` IS NULL OR `text4_0_loc8`='','Сердце бесконечности охвачено яростью. Не заставляй меня смотреть! Я больше не могу! Я не вынесу этого!',`text4_0_loc8`), `text5_0_loc8`=IF(`text5_0_loc8` IS NULL OR `text5_0_loc8`='','Мы – ничто. Туллал пар\'окот. Фар\'аль, ка\'кэр. Пустота поглотит нас.',`text5_0_loc8`), `text6_0_loc8`=IF(`text6_0_loc8` IS NULL OR `text6_0_loc8`='','<Сумеречный слуга издает булькающие звуки, из его рта идет пена.>',`text6_0_loc8`), `text7_0_loc8`=IF(`text7_0_loc8` IS NULL OR `text7_0_loc8`='','Х\'тон, тьма повсюду, куда достает взор. Х\'тон марвол квалар: бесконечность ночи.',`text7_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15714,'Есть новости? Я пытаюсь поговорить с освобожденными рабами, и от этого у меня раскалывается голова.$B$BОни несут какой-то бред.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Есть новости? Я пытаюсь поговорить с освобожденными рабами, и от этого у меня раскалывается голова.$B$BОни несут какой-то бред.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15725,'Привет, |3-6($c). Уверен, что у тебя куча вопросов.$B$BНу что ж, скажу, что Ройс Шепот Сумрака послал меня в огрскую пещеру за каким-то "Оком Сумерек", и, как ты видишь, ничем хорошим это не кончилось.$B$BЕсли я когда-нибудь доберусь до этого тощего, мерзкого, хитрого ночного эльфа…$B$B<Кристофф беспомощно дергается, его лицо багровеет.>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Привет, |3-6($c). Уверен, что у тебя куча вопросов.$B$BНу что ж, скажу, что Ройс Шепот Сумрака послал меня в огрскую пещеру за каким-то "Оком Сумерек", и, как ты видишь, ничем хорошим это не кончилось.$B$BЕсли я когда-нибудь доберусь до этого тощего, мерзкого, хитрого ночного эльфа…$B$B<Кристофф беспомощно дергается, его лицо багровеет.>',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text3_0_loc8`,`text4_0_loc8`,`text5_0_loc8`,`text6_0_loc8`,`text7_0_loc8`) VALUES (15733,'Чуешь что-нибудь?','Я бы помог тебе, но у меня… аллергия на цепи. Я в сторонке поболтаюсь.','И сколько же я там провисел? Такое чувство, что несколько дней.','Я не советую вот так вот висеть на цепи. Но, если честно, прическа получается что надо.','Огры.$B$BНенавижу огров.','Ты все время болтаешь вместо того, чтобы убивать?','Меньше болтовни, а больше пришибленных огров, лады?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Чуешь что-нибудь?',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Я бы помог тебе, но у меня… аллергия на цепи. Я в сторонке поболтаюсь.',`text1_0_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','И сколько же я там провисел? Такое чувство, что несколько дней.',`text3_0_loc8`), `text4_0_loc8`=IF(`text4_0_loc8` IS NULL OR `text4_0_loc8`='','Я не советую вот так вот висеть на цепи. Но, если честно, прическа получается что надо.',`text4_0_loc8`), `text5_0_loc8`=IF(`text5_0_loc8` IS NULL OR `text5_0_loc8`='','Огры.$B$BНенавижу огров.',`text5_0_loc8`), `text6_0_loc8`=IF(`text6_0_loc8` IS NULL OR `text6_0_loc8`='','Ты все время болтаешь вместо того, чтобы убивать?',`text6_0_loc8`), `text7_0_loc8`=IF(`text7_0_loc8` IS NULL OR `text7_0_loc8`='','Меньше болтовни, а больше пришибленных огров, лады?',`text7_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15738,'Ну? Ты собираешься помочь мне?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ну? Ты собираешься помочь мне?',`text0_0_loc8`);
