INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15741,'<Кристофф ворчит.>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Кристофф ворчит.>',`text0_0_loc8`);
