INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15742,'Голдринн – величайший из древних. Он могуч и целеустремлен… Пусть он будет тебе примером.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Голдринн – величайший из древних. Он могуч и целеустремлен… Пусть он будет тебе примером.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15754,'Я здесь, чтобы изучать духов, магию сил природы. Знахарь Узери послал меня учиться магии у низших существ леса.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я здесь, чтобы изучать духов, магию сил природы. Знахарь Узери послал меня учиться магии у низших существ леса.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15755,'Приветствую тебя, |3-6($c).$B$BГоры обрушились и катаклизм заставил моря затопить Тысячу Игл.$B$BНам срочно нужна твоя помощь!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приветствую тебя, |3-6($c).$B$BГоры обрушились и катаклизм заставил моря затопить Тысячу Игл.$B$BНам срочно нужна твоя помощь!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15756,'Он был хорошим парнем, |3-6($r). Мы с ним плечом к плечу прошли через множество сражений...$B$BЭти твари должны за все заплатить!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Он был хорошим парнем, |3-6($r). Мы с ним плечом к плечу прошли через множество сражений...$B$BЭти твари должны за все заплатить!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15760,'Наши мольбы к Эссине остаются без ответа. Пылающие прислужники Рагнароса прижали нас к самому краю. Если мы не остановим их здесь, от Древа Жизни останется лишь обугленный пень посреди пожарища!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Наши мольбы к Эссине остаются без ответа. Пылающие прислужники Рагнароса прижали нас к самому краю. Если мы не остановим их здесь, от Древа Жизни останется лишь обугленный пень посреди пожарища!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15761,'Нити жизни были оборваны.$B$BСпящие должны быть отмщены.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Нити жизни были оборваны.$B$BСпящие должны быть отмщены.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15769,'У-уй...$B$BЧто-то мне... нехорошо...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','У-уй...$B$BЧто-то мне... нехорошо...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15770,'Спасибо, |3-6($c).$B$BЯ едва там не погибла.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Спасибо, |3-6($c).$B$BЯ едва там не погибла.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15771,'Мы здесь, чтобы сохранить эти земли для нашего народа.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы здесь, чтобы сохранить эти земли для нашего народа.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15772,'$R. Тебе дали задание поговорить со мной? Сколько времени прошло с того дня, когда мой хозяин нашел свою смерть на этих склонах?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','$R. Тебе дали задание поговорить со мной? Сколько времени прошло с того дня, когда мой хозяин нашел свою смерть на этих склонах?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15774,'Приветствую тебя, |3-6($c).$B$BХиджал в огне, и мир, защите которого я посвятила всю свою жизнь, находится на грани забвения.$B$BСкажи мне, $gслышал:слышала; ли ты когда-нибудь о Тирии Чернороге?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Приветствую тебя, |3-6($c).$B$BХиджал в огне, и мир, защите которого я посвятила всю свою жизнь, находится на грани забвения.$B$BСкажи мне, $gслышал:слышала; ли ты когда-нибудь о Тирии Чернороге?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15776,'Десятилетие назад здесь, на вершине горы Хиджал, состоялась величайшая битва. Архимонд Осквернитель во главе полчища демонов напал на Древо Жизни, чтобы забрать себе его силу.$B$BЕго поражение ознаменовало конец нашествия Легиона на Азерот… Но многие из его оскверненных последователей остались здесь.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Десятилетие назад здесь, на вершине горы Хиджал, состоялась величайшая битва. Архимонд Осквернитель во главе полчища демонов напал на Древо Жизни, чтобы забрать себе его силу.$B$BЕго поражение ознаменовало конец нашествия Легиона на Азерот… Но многие из его оскверненных последователей остались здесь.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15777,'И да и нет. Может быть, сейчас он и демон, но когда-то Тирий Чернорог был ночным эльфом. Как и многие из его братьев, он соблазнился обещаниями силы, которые нашептывали ему демоны.$B$BПосле поражения его господина он был захвачен в плен и заточен здесь, на вершине. Его бессмертный дух удерживается здесь священной силой.$B$BНо, возможно, какая-то искорка души еще теплится в нем… Мы должны выяснить это.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','И да и нет. Может быть, сейчас он и демон, но когда-то Тирий Чернорог был ночным эльфом. Как и многие из его братьев, он соблазнился обещаниями силы, которые нашептывали ему демоны.$B$BПосле поражения его господина он был захвачен в плен и заточен здесь, на вершине. Его бессмертный дух удерживается здесь священной силой.$B$BНо, возможно, какая-то искорка души еще теплится в нем… Мы должны выяснить это.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15778,'Моя помощь? Неужели положение настолько серьезно?$B$B<Отблески далекого огня сверкают в жестоких темных глазах Чернорога.>$B$BНазови мне причину, по которой я не должен позволить твоему миру сгореть дотла.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Моя помощь? Неужели положение настолько серьезно?$B$B<Отблески далекого огня сверкают в жестоких темных глазах Чернорога.>$B$BНазови мне причину, по которой я не должен позволить твоему миру сгореть дотла.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15780,'Смертным? Да, я некогда был смертным. И слабым.$B$BТы видишь мои оковы? Это ничто по сравнению с заточением в смертной оболочке.$B$BДаже сейчас сила, дарованная моим хозяином, кипит во мне, жаждет вырваться на свободу.$B$BНет, |3-6($c), я не смертный больше, и даже если остатки моей былой сущности еще тлеют внутри меня, я бы желал их потушить. Твои усилия напрасны, |3-6($r).') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Смертным? Да, я некогда был смертным. И слабым.$B$BТы видишь мои оковы? Это ничто по сравнению с заточением в смертной оболочке.$B$BДаже сейчас сила, дарованная моим хозяином, кипит во мне, жаждет вырваться на свободу.$B$BНет, |3-6($c), я не смертный больше, и даже если остатки моей былой сущности еще тлеют внутри меня, я бы желал их потушить. Твои усилия напрасны, |3-6($r).',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15782,'<Чернорог дергается в своих оковах, в этот раз он явно расстроен.>$B$BИскупление! Ты говоришь так, будто от Пылающего Легиона можно спастись. Удивительная самонадеянность! Как будто ваши старания десять лет назад здесь или все ваши усилия в Запределье принесли хоть какие-нибудь плоды! Они придут, |3-6($r). Они вернутся. А я буду встречать их здесь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Чернорог дергается в своих оковах, в этот раз он явно расстроен.>$B$BИскупление! Ты говоришь так, будто от Пылающего Легиона можно спастись. Удивительная самонадеянность! Как будто ваши старания десять лет назад здесь или все ваши усилия в Запределье принесли хоть какие-нибудь плоды! Они придут, |3-6($r). Они вернутся. А я буду встречать их здесь.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15783,'<Кашляет.>$B$BЯ... умер?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Кашляет.>$B$BЯ... умер?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15785,'…хозяин?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','…хозяин?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15794,'Отлично, мы нашли проход!$b$bНельзя тратить ни минуты. Ты $Gготов:готова;?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Отлично, мы нашли проход!$b$bНельзя тратить ни минуты. Ты $Gготов:готова;?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15796,'Я отзовусь на клич Вол\'джина одной из первых! Ты присоединишься к нам?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я отзовусь на клич Вол\'джина одной из первых! Ты присоединишься к нам?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15802,'Мне думалось, что мое первое путешествие в глубины океана будет мирным и познавательным. Что-то вроде единения с природой...$B$BНо в этом месте природа явно негармонична. Все стихии, окружающие нас, вопиют о возмездии.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мне думалось, что мое первое путешествие в глубины океана будет мирным и познавательным. Что-то вроде единения с природой...$B$BНо в этом месте природа явно негармонична. Все стихии, окружающие нас, вопиют о возмездии.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15806,'Если тебе нужен нетопырь, ты $gпришел:пришла; туда, куда нужно. Я держу здесь всех нетопырей для разведчиков.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если тебе нужен нетопырь, ты $gпришел:пришла; туда, куда нужно. Я держу здесь всех нетопырей для разведчиков.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15808,'Ты $gготов:готова; к войне, |3-6($r)?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты $gготов:готова; к войне, |3-6($r)?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15815,'Верно! Уничтожь четырех элементалей, и я уверен – дверь откроется сама собой. Только остерегайся троггов. Они не подверглись Проклятию плоти, но не стали от этого менее мерзкими и грязными.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Верно! Уничтожь четырех элементалей, и я уверен – дверь откроется сама собой. Только остерегайся троггов. Они не подверглись Проклятию плоти, но не стали от этого менее мерзкими и грязными.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15816,'Мои когти помогут мне проявить себя здесь!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мои когти помогут мне проявить себя здесь!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15818,'Я истинный новатор, крошка! Элементальные технологии. Поиск утраченных знаний и новых ресурсов в недрах Азерота.$B$BЗапомни мое имя.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я истинный новатор, крошка! Элементальные технологии. Поиск утраченных знаний и новых ресурсов в недрах Азерота.$B$BЗапомни мое имя.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15819,'Не знаю как ты, дружище, но у меня водой дышать не выходит.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не знаю как ты, дружище, но у меня водой дышать не выходит.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15820,'И упустить шанс покрасоваться в моем потрясающем, выполненном по особому заказу шлеме? Исключено.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','И упустить шанс покрасоваться в моем потрясающем, выполненном по особому заказу шлеме? Исключено.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15821,'Много усилий уходит на уход за нашими животными и их дрессировку, но это того стоит.$B$BМне никогда не помешают лишние руки.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Много усилий уходит на уход за нашими животными и их дрессировку, но это того стоит.$B$BМне никогда не помешают лишние руки.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15827,'$gЯ рад, что ты здесь, друг мой:Я рад, что ты здесь;!$B$BПожары вынудили животных искать убежища в этой роще. Больше им бежать некуда. Мы должны защитить выживших!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','$gЯ рад, что ты здесь, друг мой:Я рад, что ты здесь;!$B$BПожары вынудили животных искать убежища в этой роще. Больше им бежать некуда. Мы должны защитить выживших!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15828,'Леди Шандриса рассчитывает на меня. Я не подведу ее.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Леди Шандриса рассчитывает на меня. Я не подведу ее.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`,`text3_0_loc8`) VALUES (15829,'Здорово, $gчувак:крошка;! Говорят, ты хочешь занять место торгового принца.$B$BЭто правда?','Я хочу дать по морде этому Чипу! А еще я хочу поцеловать Конфетку!','Кто сказал "вечеринка"?!','Вся эта история с "Каджа-Колой" заставила меня задуматься. Неужели мы хотим, чтобы у наших конкурентов рождались хорошие идеи?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здорово, $gчувак:крошка;! Говорят, ты хочешь занять место торгового принца.$B$BЭто правда?',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Я хочу дать по морде этому Чипу! А еще я хочу поцеловать Конфетку!',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Кто сказал "вечеринка"?!',`text2_0_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Вся эта история с "Каджа-Колой" заставила меня задуматься. Неужели мы хотим, чтобы у наших конкурентов рождались хорошие идеи?',`text3_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`,`text2_1_loc8`) VALUES (15831,'Привет, $gмалыш:милочка;! Что это за слухи ходят про тебя и $gКонфетку:Чипа;?','Тысячелетия назад каджа\'мит сделал нас умными. А вот на троллей он, похоже, не действует. Странно, правда?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Привет, $gмалыш:милочка;! Что это за слухи ходят про тебя и $gКонфетку:Чипа;?',`text0_1_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Тысячелетия назад каджа\'мит сделал нас умными. А вот на троллей он, похоже, не действует. Странно, правда?',`text2_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15834,'Эй, эй! Не причиняй мне вреда! Я один из многих абсолютно безвредных гоблинов, я совсем не из Орды!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эй, эй! Не причиняй мне вреда! Я один из многих абсолютно безвредных гоблинов, я совсем не из Орды!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15836,'Ты смотришь на меня… Ты меня видишь?$B$BПожалуйста, помоги…') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты смотришь на меня… Ты меня видишь?$B$BПожалуйста, помоги…',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15838,'Если мы удержим оборону до прихода Часовых, мы сможем защитить Фералас.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Если мы удержим оборону до прихода Часовых, мы сможем защитить Фералас.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15841,'Катаклизм уничтожил западные горы Тысячи Игл. Южное море хлынуло в пролом и затопило все каньоны.$B$BПрошу тебя, |3-6($c), помоги нам в Новом Таланааре!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Катаклизм уничтожил западные горы Тысячи Игл. Южное море хлынуло в пролом и затопило все каньоны.$B$BПрошу тебя, |3-6($c), помоги нам в Новом Таланааре!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15842,'Катаклизм уничтожил Тысячу Игл, |3-6($c). Ты поможешь нам во время великой беды?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Катаклизм уничтожил Тысячу Игл, |3-6($c). Ты поможешь нам во время великой беды?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15846,'Да пребудут с тобой духи, |3-6($c).') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да пребудут с тобой духи, |3-6($c).',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15847,'Таурены Зловещего Тотема застали нас врасплох. Мы едва держимся.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Таурены Зловещего Тотема застали нас врасплох. Мы едва держимся.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15848,'Как же Зловещий Тотем мог так поступить в этот трудный для нас час?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Как же Зловещий Тотем мог так поступить в этот трудный для нас час?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15849,'Посмотри на это пепелище, |3-6($c)! Лишь кровь и угли повсюду, куда достает глаз.$B$BНо природу не так-то просто погубить. Приложив некоторые усилия, мы сможем пробудить жизнь в этой выжженной земле.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Посмотри на это пепелище, |3-6($c)! Лишь кровь и угли повсюду, куда достает глаз.$B$BНо природу не так-то просто погубить. Приложив некоторые усилия, мы сможем пробудить жизнь в этой выжженной земле.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15850,'Я считала, что Рунический Тотем действует неосмотрительно, устраивая лагерь в этих выжженных землях, и я не собиралась допустить, чтобы верховный друид добирался сюда один.$B$BОн что-то замыслил. Что-то серьезное.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я считала, что Рунический Тотем действует неосмотрительно, устраивая лагерь в этих выжженных землях, и я не собиралась допустить, чтобы верховный друид добирался сюда один.$B$BОн что-то замыслил. Что-то серьезное.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15851,'Твари из племени Зловещего Тотема скоро отправятся к праотцам!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Твари из племени Зловещего Тотема скоро отправятся к праотцам!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15852,'Мой ящер может справиться с КЕМ УГОДНО и ЧЕМ УГОДНО!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мой ящер может справиться с КЕМ УГОДНО и ЧЕМ УГОДНО!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15855,'Повелитель Холода Ахун, должен быть остановлен.\r\n\r\nСейчас он еще обретает форму, освобожденный из тюрьмы стихий безумными сектантами Сумеречного Молота.\r\n\r\nЕсли мы не сможем предотвратить его появление в нашем мире, земля окажется под покровом бесконечной суровой зимы.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Повелитель Холода Ахун, должен быть остановлен.\r\n\r\nСейчас он еще обретает форму, освобожденный из тюрьмы стихий безумными сектантами Сумеречного Молота.\r\n\r\nЕсли мы не сможем предотвратить его появление в нашем мире, земля окажется под покровом бесконечной суровой зимы.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15857,'Кто-то должен остановить Королевскую химическую компанию. Готов поставить свою позолоченную ракету Пустоты, что под маркой бешеных шоколадок для населения они варят в своих лабораториях новую чуму...\r\n\r\nМне бы только найти смельчака, который передаст этим аптекарям повестку в суд! Тогда мы могли бы положить конец их деятельности... а заодно захватить все их активы!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Кто-то должен остановить Королевскую химическую компанию. Готов поставить свою позолоченную ракету Пустоты, что под маркой бешеных шоколадок для населения они варят в своих лабораториях новую чуму...\r\n\r\nМне бы только найти смельчака, который передаст этим аптекарям повестку в суд! Тогда мы могли бы положить конец их деятельности... а заодно захватить все их активы!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15863,'Добро пожаловать в Город Механиков!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать в Город Механиков!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15864,'Этот осколок льда словно бы заставляет слышать потрескивание медленно движущихся ледников, а его холод заставляет думать о бесконечной зиме...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Этот осколок льда словно бы заставляет слышать потрескивание медленно движущихся ледников, а его холод заставляет думать о бесконечной зиме...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15865,'Время Залазана вышло. Острова Эха вновь будут принадлежать троллям Черного Копья!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Время Залазана вышло. Острова Эха вновь будут принадлежать троллям Черного Копья!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15867,'Гоночная баржа Пшикса и Поззика! Подумать только! Я ее построила – а не они. И не Раззерик!$B$BОна должна называться гоночная баржа Джинки!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Гоночная баржа Пшикса и Поззика! Подумать только! Я ее построила – а не они. И не Раззерик!$B$BОна должна называться гоночная баржа Джинки!',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15870,'Поторопись! Тебе необходимо поговорить с Меггакрутом! Если мы не начнем атаку прямо сейчас, то будет слишком поздно.$b$bА мой босс НЕНАВИДИТ опоздания!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Поторопись! Тебе необходимо поговорить с Меггакрутом! Если мы не начнем атаку прямо сейчас, то будет слишком поздно.$b$bА мой босс НЕНАВИДИТ опоздания!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15874,'Пшикс, Поззик, Джинки... Они думают, что спасли нас, но ведь это все я! Я ее построил! Она должна называться гоночная баржа Раззерика!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Пшикс, Поззик, Джинки... Они думают, что спасли нас, но ведь это все я! Я ее построил! Она должна называться гоночная баржа Раззерика!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15876,'Скоро начнется битва за острова Эха. Достаточно древних темных ритуалов исполнил Залазан, воскрешая мертвецов магией вуду.$bНо он знает о наших планах, так что необходимо хорошенько подготовиться.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Скоро начнется битва за острова Эха. Достаточно древних темных ритуалов исполнил Залазан, воскрешая мертвецов магией вуду.$bНо он знает о наших планах, так что необходимо хорошенько подготовиться.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15878,'Это точно те самые, что напали на наши лодки. Но я не вижу никого из наших пропавших ребят. Куда они их увели?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Это точно те самые, что напали на наши лодки. Но я не вижу никого из наших пропавших ребят. Куда они их увели?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15880,'Мне хотелось бы, чтобы мою работу воспринимали всерьез. Если я не вырываю акулам зубы и не завязываю узлом угрей, это не значит, что я занимаюсь ерундой.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мне хотелось бы, чтобы мою работу воспринимали всерьез. Если я не вырываю акулам зубы и не завязываю узлом угрей, это не значит, что я занимаюсь ерундой.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15881,'<Глаза древнего огромны и бездонны.>$B$B<Существо медленно говорит на языке, которого вы не понимаете. По вашей спине пробегают мурашки. Вас охватывает ужас и замешательство.>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Глаза древнего огромны и бездонны.>$B$B<Существо медленно говорит на языке, которого вы не понимаете. По вашей спине пробегают мурашки. Вас охватывает ужас и замешательство.>',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15882,'<Глаза древнего медленно открываются, в них – бездна боли и страха.>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Глаза древнего медленно открываются, в них – бездна боли и страха.>',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15883,'Эй, заходи, у нас тут прохладно!$B$BНалить тебе чего-нибудь? Все равно мне больше нечем тут заняться.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Эй, заходи, у нас тут прохладно!$B$BНалить тебе чего-нибудь? Все равно мне больше нечем тут заняться.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15886,'<Огромные темные глаза древнего смотрят на вас с недоверием.>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Огромные темные глаза древнего смотрят на вас с недоверием.>',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15887,'Лично я считаю, что моему брату давно уже пора что-то сделать с этими гоблинами! Говорят, и катаклизм именно из-за них начался – когда у одного рванул футбомбный мяч!$B$BМы должны избавиться от гоблинов, пока еще не поздно!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Лично я считаю, что моему брату давно уже пора что-то сделать с этими гоблинами! Говорят, и катаклизм именно из-за них начался – когда у одного рванул футбомбный мяч!$B$BМы должны избавиться от гоблинов, пока еще не поздно!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15890,'Ничего бы этого не было, кабы не гномы!$B$BОбщеизвестно, что именно они довели мир до катаклизма с этими своими устройствами расширения пространства и прочей подобной ерундой!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ничего бы этого не было, кабы не гномы!$B$BОбщеизвестно, что именно они довели мир до катаклизма с этими своими устройствами расширения пространства и прочей подобной ерундой!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15892,'Я из кожи вон лезу, чтобы этот корабль не развалился на части, и мне еще приходится терпеть здесь этих баранов вроде Пшикса!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я из кожи вон лезу, чтобы этот корабль не развалился на части, и мне еще приходится терпеть здесь этих баранов вроде Пшикса!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15893,'Нет, этот тип точно доведет меня до белого каления! Неужели кто-то всерьез полагает, что какой-то гоблин в состоянии управлять таким шедевром инженерной мысли, как гоночная баржа?$B$BВсе, на что они способны, – это устраивать всякие взрывы, да и не утруждая себя техникой безопасности!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Нет, этот тип точно доведет меня до белого каления! Неужели кто-то всерьез полагает, что какой-то гоблин в состоянии управлять таким шедевром инженерной мысли, как гоночная баржа?$B$BВсе, на что они способны, – это устраивать всякие взрывы, да и не утруждая себя техникой безопасности!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15897,'Дым и пепел. Если меня не убьет жар, я задохнусь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Дым и пепел. Если меня не убьет жар, я задохнусь.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15901,'Да? В чем дело?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да? В чем дело?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15908,'Хорошая работа, |3-6($c).$B$BТеперь мы с моими людьми готовы к встрече с врагом.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Хорошая работа, |3-6($c).$B$BТеперь мы с моими людьми готовы к встрече с врагом.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15909,'Очень скоро мы встретимся вновь…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Очень скоро мы встретимся вновь…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15911,'Ты $gобязан:обязана; помочь мне! Моя бедная, несчастная Челси...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты $gобязан:обязана; помочь мне! Моя бедная, несчастная Челси...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15914,'Ты ведь потушишь огонь и не позволишь пиратам взять нас на абордаж, правда?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты ведь потушишь огонь и не позволишь пиратам взять нас на абордаж, правда?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15915,'Ну и дела! Ты, значит, потушишь пожар и не дашь пиратам захватить гоночную баржу, да?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ну и дела! Ты, значит, потушишь пожар и не дашь пиратам захватить гоночную баржу, да?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15918,'Пираты, кентавры и Зловещий Тотем – ничего себе!$B$BИ еще, по-моему, я видел ночью какую-то огромную летающую штуковину – такую здоровенную, что она целиком заслонила луну!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Пираты, кентавры и Зловещий Тотем – ничего себе!$B$BИ еще, по-моему, я видел ночью какую-то огромную летающую штуковину – такую здоровенную, что она целиком заслонила луну!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15920,'Неприятности тут поджидают повсюду – но на открытой воде мы в относительной безопасности.$B$BНо вода не защитит нас от того, что я видел прошлой ночью в небе. Это было нечто ужасное... и огромное!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Неприятности тут поджидают повсюду – но на открытой воде мы в относительной безопасности.$B$BНо вода не защитит нас от того, что я видел прошлой ночью в небе. Это было нечто ужасное... и огромное!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15921,'Посвящается тем, кого забрала Плеть в сражениях на Ледяных Пустошах.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Посвящается тем, кого забрала Плеть в сражениях на Ледяных Пустошах.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15922,'Привет, |3-6($c)!$B$BЭти несчастные существа жертвуют всем, чтобы сражаться с культом Сумеречного Молота в этом средоточии тьмы.$B$BЯ сумел вернуть к жизни тех, кто пал.$B$BЕсли тебе понадобится верховая птица, то эти готовы к полету. Обращайся с ними хорошо!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Привет, |3-6($c)!$B$BЭти несчастные существа жертвуют всем, чтобы сражаться с культом Сумеречного Молота в этом средоточии тьмы.$B$BЯ сумел вернуть к жизни тех, кто пал.$B$BЕсли тебе понадобится верховая птица, то эти готовы к полету. Обращайся с ними хорошо!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15931,'Осторожней, друзья. Здесь наверняка есть ловушки, защищающие Повелителя Огня от врагов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Осторожней, друзья. Здесь наверняка есть ловушки, защищающие Повелителя Огня от врагов.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15932,'Привет, $gкрасавчик:дорогуша;. Добро пожаловать в Бар гоночной баржи.$B$BЧего изволите?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Привет, $gкрасавчик:дорогуша;. Добро пожаловать в Бар гоночной баржи.$B$BЧего изволите?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15933,'Приветствую тебя, |3-6($c). Надеюсь, в эти суровые времена такое жилье устроит тебя.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Приветствую тебя, |3-6($c). Надеюсь, в эти суровые времена такое жилье устроит тебя.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15935,'Силы, с которыми мы столкнулись, превосходят армии Сумеречного Молота, Рагнароса и даже Смертокрыла. У нас нет иного выбора, кроме победы. Иначе наш мир обречен.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Силы, с которыми мы столкнулись, превосходят армии Сумеречного Молота, Рагнароса и даже Смертокрыла. У нас нет иного выбора, кроме победы. Иначе наш мир обречен.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15938,'Помоги мне, |3-6($r).$B$BЯ не знаю, сколько еще смогу продержаться...') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Помоги мне, |3-6($r).$B$BЯ не знаю, сколько еще смогу продержаться...',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15942,'Сумеречный Молот для меня – не просто организация. Это моя семья.$B$BПоэтому я позабочусь о том, чтобы ни один недостойный не прошел дальше этапа обучения.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Сумеречный Молот для меня – не просто организация. Это моя семья.$B$BПоэтому я позабочусь о том, чтобы ни один недостойный не прошел дальше этапа обучения.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15943,'Нужно побыстрее найти безопасное место.$B$BСтарине Маку совсем нехорошо.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Нужно побыстрее найти безопасное место.$B$BСтарине Маку совсем нехорошо.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15951,'Эта жара. Эта удушающая жара.$B$BИз-за нее я хочу все крушить.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Эта жара. Эта удушающая жара.$B$BИз-за нее я хочу все крушить.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15952,'А, вот и еще один храбрый герой прошел через портал! Надеюсь, ты $gготов:готова; к схватке, |3-6($c).') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','А, вот и еще один храбрый герой прошел через портал! Надеюсь, ты $gготов:готова; к схватке, |3-6($c).',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15954,'Если мы позволим Сумеречному Молоту открыть такие порталы по всему Азероту, то никакая армия уже не спасет нашу планету. Мы должны уничтожить эту сеть туннелей!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если мы позволим Сумеречному Молоту открыть такие порталы по всему Азероту, то никакая армия уже не спасет нашу планету. Мы должны уничтожить эту сеть туннелей!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15956,'Пламий убит! Нам здесь больше делать нечего.$B$BПросто войди в огненные врата, чтобы вернуться на гору Хиджал, |3-6($c). О вратах я позабочусь сам.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Пламий убит! Нам здесь больше делать нечего.$B$BПросто войди в огненные врата, чтобы вернуться на гору Хиджал, |3-6($c). О вратах я позабочусь сам.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15962,'Тс-с-с! Тихо! Ты нас выдашь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тс-с-с! Тихо! Ты нас выдашь.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15965,'<Хотя тело Изеры перед вами, ее сознание блуждает между этим миром и другим.>') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','<Хотя тело Изеры перед вами, ее сознание блуждает между этим миром и другим.>',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15966,'Ты давно $gбыл:была; в Ясеневом лесу? Как там дела?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты давно $gбыл:была; в Ясеневом лесу? Как там дела?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15970,'Зовут меня все Райан, товар мой покупая! Чего изволишь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Зовут меня все Райан, товар мой покупая! Чего изволишь?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15971,'Мы, друиды-вороны, не слишком годимся для битвы в первых рядах. Мы – воздушные разведчики, шпионы…$B$BНо иногда приятно обагрить когти кровью врага.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мы, друиды-вороны, не слишком годимся для битвы в первых рядах. Мы – воздушные разведчики, шпионы…$B$BНо иногда приятно обагрить когти кровью врага.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15972,'Гляди в оба, |3-6($c). Эти вендиго – злобные твари.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Гляди в оба, |3-6($c). Эти вендиго – злобные твари.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15973,'Эта пещера мне уже осточертела. Не могу дождаться, когда окажусь в Караносе.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эта пещера мне уже осточертела. Не могу дождаться, когда окажусь в Караносе.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15974,'Вендиго – это, конечно, неприятно, но настоящие проблемы у нас с беженцами Мерзлогривов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вендиго – это, конечно, неприятно, но настоящие проблемы у нас с беженцами Мерзлогривов.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15981,'Ты $gдолжен:должна; спасти меня, |3-6($c)! Он сошел с ума – точно тебе говорю! Когда он не смог предотвратить затопление Тысячи Игл, у него совершенно поехала крыша!$B$BТеперь он во всем винит меня и даже говорит, что это из-за меня случился катаклизм. Кажется, он думает, что я на самом деле Смертокрыл, принявший чужое обличье!$B$BПомоги мне!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты $gдолжен:должна; спасти меня, |3-6($c)! Он сошел с ума – точно тебе говорю! Когда он не смог предотвратить затопление Тысячи Игл, у него совершенно поехала крыша!$B$BТеперь он во всем винит меня и даже говорит, что это из-за меня случился катаклизм. Кажется, он думает, что я на самом деле Смертокрыл, принявший чужое обличье!$B$BПомоги мне!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`,`text1_1_loc8`,`text2_1_loc8`,`text3_1_loc8`) VALUES (15982,'Ты ничего от меня не получишь, |3-6($r)!','<Марион громко вскрикивает и смотрит на вас.>','Ваши города падут, |3-6($r)! Вы исчезнете во тьме новой эпохи!','Можешь делать со мной, что угодно. Только знай, что мое имя вырежут на твоем теле перед казнью!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты ничего от меня не получишь, |3-6($r)!',`text0_1_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','<Марион громко вскрикивает и смотрит на вас.>',`text1_1_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Ваши города падут, |3-6($r)! Вы исчезнете во тьме новой эпохи!',`text2_1_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','Можешь делать со мной, что угодно. Только знай, что мое имя вырежут на твоем теле перед казнью!',`text3_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15987,'Ей нужны были яйца. Яйца для ее инкубатора в другом мире.$B$BА одно яйцо… особое яйцо… ей нужно было больше всего.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ей нужны были яйца. Яйца для ее инкубатора в другом мире.$B$BА одно яйцо… особое яйцо… ей нужно было больше всего.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15988,'Она дочь неба, но и тьма сильна в ней. Она из рода Хранителя земли. Ее нельзя победить!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Она дочь неба, но и тьма сильна в ней. Она из рода Хранителя земли. Ее нельзя победить!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15989,'$gГлупый:Глупая:r; |3-6($r)! Мир изменился. Авиана мертва. МЕРТВА! И она никогда не вернется.$B$BСкажи это лесным друидам.$B$BСкоро Сетрия будет править небесами, и она позаботилась о том, чтобы Авиана не смогла восстать. Яйцо принадлежит ей.$B$BТы $gопоздал:опоздала;.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','$gГлупый:Глупая:r; |3-6($r)! Мир изменился. Авиана мертва. МЕРТВА! И она никогда не вернется.$B$BСкажи это лесным друидам.$B$BСкоро Сетрия будет править небесами, и она позаботилась о том, чтобы Авиана не смогла восстать. Яйцо принадлежит ей.$B$BТы $gопоздал:опоздала;.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15991,'Сковать чего-нибудь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Сковать чего-нибудь?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (15995,'Мороженое!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мороженое!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15997,'Чудовище повержено, но мои бесценные воды осквернены! Я должен очистить их.$b$bА ты... если хочешь тут остаться, приготовься сражаться за свою жизнь!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Чудовище повержено, но мои бесценные воды осквернены! Я должен очистить их.$b$bА ты... если хочешь тут остаться, приготовься сражаться за свою жизнь!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (15998,'Приветствую тебя, |3-6($c)! Добро пожаловать в Святилище Авианы, в убежище всех небесных созданий.$B$BСамой Авианы нет с нами, но ее дух и решимость продолжают жить во всех крылатых существах.$B$BПоговори с Чолуной внизу, если тебе интересна история Авианы.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приветствую тебя, |3-6($c)! Добро пожаловать в Святилище Авианы, в убежище всех небесных созданий.$B$BСамой Авианы нет с нами, но ее дух и решимость продолжают жить во всех крылатых существах.$B$BПоговори с Чолуной внизу, если тебе интересна история Авианы.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16001,'Даже и не знаю, что я вообще здесь делаю. У меня нет никакого опыта в составлении контрактов.$B$BРаньше я разносил напитки и тем зарабатывал себе на жизнь, но Дейзи меня разорила. Что ж, наверное, пора начать новую карьеру.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Даже и не знаю, что я вообще здесь делаю. У меня нет никакого опыта в составлении контрактов.$B$BРаньше я разносил напитки и тем зарабатывал себе на жизнь, но Дейзи меня разорила. Что ж, наверное, пора начать новую карьеру.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16003,'Тс-с-с – я здесь! Не высовывайся пока…') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Тс-с-с – я здесь! Не высовывайся пока…',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16004,'Раньше я был билетным контролером на ипподроме. Но ипподрома больше нет – и я потерял работу.$B$BСейчас вот пытаюсь попробовать себя в роли переговорщика. Не поможешь мне с этим? У них есть нефть!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Раньше я был билетным контролером на ипподроме. Но ипподрома больше нет – и я потерял работу.$B$BСейчас вот пытаюсь попробовать себя в роли переговорщика. Не поможешь мне с этим? У них есть нефть!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16007,'Многие опасаются магии крови, считая ее темным и забытым искусством. Этим, и не только этим, она отчасти похожа на магию демонов. Здесь, в разоренных демонами руинах Черных топей, наши исследования магии крови будут весьма успешными.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Многие опасаются магии крови, считая ее темным и забытым искусством. Этим, и не только этим, она отчасти похожа на магию демонов. Здесь, в разоренных демонами руинах Черных топей, наши исследования магии крови будут весьма успешными.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16008,'Можно научить солдата убивать, но нельзя привить ему вкус к убийству. Однако для нас это не проблема. Мои ребята просто сгорают от нетерпения истребить побольше наг. Я сам испытываю подобное чувство.$B$BНам нужно найти выход на поверхность, но для начала немного "пообщаемся" с нагами. Нужно отомстить за наших братьев по оружию.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Можно научить солдата убивать, но нельзя привить ему вкус к убийству. Однако для нас это не проблема. Мои ребята просто сгорают от нетерпения истребить побольше наг. Я сам испытываю подобное чувство.$B$BНам нужно найти выход на поверхность, но для начала немного "пообщаемся" с нагами. Нужно отомстить за наших братьев по оружию.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16010,'Помоги мне, если у меня получится расшевелить хоть одного из этих лентяев, я его заставлю напинать остальным как следует!$B$BУ нас тут ДЕЛ НЕВПРОВОРОТ!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Помоги мне, если у меня получится расшевелить хоть одного из этих лентяев, я его заставлю напинать остальным как следует!$B$BУ нас тут ДЕЛ НЕВПРОВОРОТ!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16014,'Удивительные материалы, просто удивительные. Заменители для всего! Заменители для заменителей. Возможно абсолютно все!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Удивительные материалы, просто удивительные. Заменители для всего! Заменители для заменителей. Возможно абсолютно все!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`) VALUES (16015,'Здесь наша позиция еще более уязвима, |3-6($r).$B$BМы должны как можно скорее найти безопасное убежище!','Мы должны отыскать твоих союзников и выяснить, что здесь затевают наги.$B$BНо сначала надо найти более безопасное место.','Боюсь, то, что мы здесь наблюдали, – лишь вершина айсберга.$B$BЯ никогда раньше не видел, чтобы наги действовали столь дисциплинированно и слаженно.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здесь наша позиция еще более уязвима, |3-6($r).$B$BМы должны как можно скорее найти безопасное убежище!',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Мы должны отыскать твоих союзников и выяснить, что здесь затевают наги.$B$BНо сначала надо найти более безопасное место.',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Боюсь, то, что мы здесь наблюдали, – лишь вершина айсберга.$B$BЯ никогда раньше не видел, чтобы наги действовали столь дисциплинированно и слаженно.',`text2_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16016,'Деревни… нет. Семьи нет. Наги забрали… все.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Деревни… нет. Семьи нет. Наги забрали… все.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16018,'Нам всем нелегко пришлось, но мы справляемся.$B$BТебе нужно засучить рукава и делать, что должно.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Нам всем нелегко пришлось, но мы справляемся.$B$BТебе нужно засучить рукава и делать, что должно.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text2_0_loc8`,`text2_1_loc8`,`text3_0_loc8`) VALUES (16019,'<Толща воды искажает исполненные боли стоны раненого солдата.>','<Толща воды искажает исполненные боли стоны раненого солдата.>','<Раненый, похоже, еще дышит. Его дыхательный пузырь, к счастью, невредим.>','<В боку солдата зияет зловещий глубокий разрез.>','<В боку солдата зияет зловещий глубокий разрез.>','<Похоже, солдат притворился мертвым, чтобы наги оставили его в покое. Это, видимо, спасло ему жизнь.>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Толща воды искажает исполненные боли стоны раненого солдата.>',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','<Толща воды искажает исполненные боли стоны раненого солдата.>',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','<Раненый, похоже, еще дышит. Его дыхательный пузырь, к счастью, невредим.>',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','<В боку солдата зияет зловещий глубокий разрез.>',`text2_0_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','<В боку солдата зияет зловещий глубокий разрез.>',`text2_1_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','<Похоже, солдат притворился мертвым, чтобы наги оставили его в покое. Это, видимо, спасло ему жизнь.>',`text3_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16022,'Души моряков третьей флотилии обречены блуждать по этому берегу. Навечно, |3-6($r). Око Палета забрало наши жизни, и навеки заточило нас в этом болоте.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Души моряков третьей флотилии обречены блуждать по этому берегу. Навечно, |3-6($r). Око Палета забрало наши жизни, и навеки заточило нас в этом болоте.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16024,'Тс-с-с! Мы прятаться здесь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тс-с-с! Мы прятаться здесь.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16025,'Всех, кроме орков, Окрилла неохотно пускает в город, что, однако, не мешает ей заставлять нас работать. Ну и ладно… Мне все равно здесь больше по душе.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Всех, кроме орков, Окрилла неохотно пускает в город, что, однако, не мешает ей заставлять нас работать. Ну и ладно… Мне все равно здесь больше по душе.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16027,'Ты находишься на орочьей территории. Что тебе нужно, |3-6($r)?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты находишься на орочьей территории. Что тебе нужно, |3-6($r)?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16031,'Ты $gдолжен:должна; делать то, что я говорю, |3-6($r). Если мы допустим оплошность, то сыграем на руку Разелиху.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты $gдолжен:должна; делать то, что я говорю, |3-6($r). Если мы допустим оплошность, то сыграем на руку Разелиху.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`) VALUES (16032,'Похоже, угроза, с которой мы столкнулись, куда масштабнее, чем могли предположить Служители Земли.','У этой пещеры скопилось множество наг.$B$BНам очень повезло, что нас не заметили.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Похоже, угроза, с которой мы столкнулись, куда масштабнее, чем могли предположить Служители Земли.',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','У этой пещеры скопилось множество наг.$B$BНам очень повезло, что нас не заметили.',`text1_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`) VALUES (16033,'Наши бойцы... Их всех захватили в плен.','Многие пытались спастись от наг.$B$BЯ единственный, кому удалось...','Не знаю почему, но эти монстры делали все возможное, чтобы сохранить нам жизнь...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Наши бойцы... Их всех захватили в плен.',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Многие пытались спастись от наг.$B$BЯ единственный, кому удалось...',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Не знаю почему, но эти монстры делали все возможное, чтобы сохранить нам жизнь...',`text2_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16034,'Ладно! Амулет берешь, но |3-6($r) Каменистому Озеру помогать.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ладно! Амулет берешь, но |3-6($r) Каменистому Озеру помогать.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16035,'Мы жили под одними волнами, дышали одной водой и почитали одного бога. Почему же наги обратились против нас?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы жили под одними волнами, дышали одной водой и почитали одного бога. Почему же наги обратились против нас?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16037,'Голдринн – древний дух в обличье волка, которого Орда называет "Ло\'гош". Его стойкость и мужество вошли в легенды.$B$BЕго святилище находится к западу отсюда, но после нападения от его стражей нет никаких вестей. Я опасаюсь худшего.$B$BПрежде чем мы сможем двигаться дальше, ты $gдолжен:должна; спасти святилище, узнать, где находится сейчас древний дух, и отразить нападение его врагов.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Голдринн – древний дух в обличье волка, которого Орда называет "Ло\'гош". Его стойкость и мужество вошли в легенды.$B$BЕго святилище находится к западу отсюда, но после нападения от его стражей нет никаких вестей. Я опасаюсь худшего.$B$BПрежде чем мы сможем двигаться дальше, ты $gдолжен:должна; спасти святилище, узнать, где находится сейчас древний дух, и отразить нападение его врагов.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16039,'Авиана – это покинувшая нас стражница небес, богиня-птица, нашедшая свою гибель в схватке с демонами десять тысяч лет назад. Ее святилище расположено к юго-западу от Нордрассила, под ветвями огромного древа.$B$BДруиды-вороны обитают в святилище, и нам нужно их содействие. Ты $gдолжен:должна; помочь им. И помочь Авиане, если она найдет способ вновь вернуться в этот мир…') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Авиана – это покинувшая нас стражница небес, богиня-птица, нашедшая свою гибель в схватке с демонами десять тысяч лет назад. Ее святилище расположено к юго-западу от Нордрассила, под ветвями огромного древа.$B$BДруиды-вороны обитают в святилище, и нам нужно их содействие. Ты $gдолжен:должна; помочь им. И помочь Авиане, если она найдет способ вновь вернуться в этот мир…',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16046,'Здесь, может, не особо уютно, но все же это Каз Модан, это все еще наш дом.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здесь, может, не особо уютно, но все же это Каз Модан, это все еще наш дом.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16047,'Наш город под водами проклятого океана, крепость кишит предателями из клана Черного Железа, а я так сильно ранен, что ничего не могу с этим всем поделать.$B$BПосему – добро пожаловать в гавань Менетилов!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Наш город под водами проклятого океана, крепость кишит предателями из клана Черного Железа, а я так сильно ранен, что ничего не могу с этим всем поделать.$B$BПосему – добро пожаловать в гавань Менетилов!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16050,'Изера послала меня сюда, чтобы установить контакт с духом природы по имени Эссина.$B$BНо древний дух по-прежнему молчит.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Изера послала меня сюда, чтобы установить контакт с духом природы по имени Эссина.$B$BНо древний дух по-прежнему молчит.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16051,'Не мы развязали войну с Ордой – Орда развязала войну с нами.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не мы развязали войну с Ордой – Орда развязала войну с нами.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16053,'Только я подумал, что у нас выдалась передышка, когда мы спаслись от этих ящеров, все стало еще хуже.$B$BОднако что толку ныть. Мы справимся с этим как подобает настоящим дворфам!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Только я подумал, что у нас выдалась передышка, когда мы спаслись от этих ящеров, все стало еще хуже.$B$BОднако что толку ныть. Мы справимся с этим как подобает настоящим дворфам!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16054,'Даже и не спрашивай о ящерах. И не заикайся о них.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Даже и не спрашивай о ящерах. И не заикайся о них.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16055,'Добро пожаловать в наш приют, хоть и далек он от нашего дома, |3-6($c). Жаль, немногое можем мы тебе здесь предложить.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Добро пожаловать в наш приют, хоть и далек он от нашего дома, |3-6($c). Жаль, немногое можем мы тебе здесь предложить.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16057,'Хочешь чего-нибудь купить?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Хочешь чего-нибудь купить?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16058,'Механизм разрушен, да?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Механизм разрушен, да?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16060,'<Похоже, этих детенышей мурлоков здесь кто-то бросил. Скорее всего, им угрожает опасность, и Нептусь наверняка будет благодарен вам, если вы поможете им вернуться в океан, где у них будет шанс спастись от наг.>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Похоже, этих детенышей мурлоков здесь кто-то бросил. Скорее всего, им угрожает опасность, и Нептусь наверняка будет благодарен вам, если вы поможете им вернуться в океан, где у них будет шанс спастись от наг.>',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16061,'Рядовой Реджинальд Поллард,13 отряд пехотных войск Штормграда...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Рядовой Реджинальд Поллард,13 отряд пехотных войск Штормграда...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16062,'Корабли Орды маячили прямо у нас под глазами… Затем из ниоткуда появились щупальца и схватили наше судно… а затем разломили его надвое!$b$bТех, кто выжил и упал в воду, сразу же схватили наги.$b$bЭто произошло около недели назад.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Корабли Орды маячили прямо у нас под глазами… Затем из ниоткуда появились щупальца и схватили наше судно… а затем разломили его надвое!$b$bТех, кто выжил и упал в воду, сразу же схватили наги.$b$bЭто произошло около недели назад.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16063,'Странно... вот уж не думал, что наги будут всеми силами сохранять нам жизнь.$B$BОни делают такие жемчужные пузыри... по одному на человека... в них мы могли дышать.$B$BКаждый день они уводили куда-то пленных...$B$BНикто не возвращался...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Странно... вот уж не думал, что наги будут всеми силами сохранять нам жизнь.$B$BОни делают такие жемчужные пузыри... по одному на человека... в них мы могли дышать.$B$BКаждый день они уводили куда-то пленных...$B$BНикто не возвращался...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16064,'Один воин умудрился вырваться на свободу и расколошматил несколько пузырей... освободил нас.$B$BНекоторые рванули на поверхность... кто-то увидел эту пещеру и устремился к ней.$B$BА доплыл я один...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Один воин умудрился вырваться на свободу и расколошматил несколько пузырей... освободил нас.$B$BНекоторые рванули на поверхность... кто-то увидел эту пещеру и устремился к ней.$B$BА доплыл я один...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16065,'А! Не подходи, |3-6($r)!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','А! Не подходи, |3-6($r)!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16066,'Понятия не имею...$B$BКаждый день они приводили новых пленных. Из Орды, из Альянса...$B$BКого-то тут же забирали... других, как меня, оставляли на неделю... иногда больше.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Понятия не имею...$B$BКаждый день они приводили новых пленных. Из Орды, из Альянса...$B$BКого-то тут же забирали... других, как меня, оставляли на неделю... иногда больше.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16067,'Даже не пытайся, |3-6($r).$B$BБеги отсюда, пока не поздно...$B$BИх слишком много... верная смерть...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Даже не пытайся, |3-6($r).$B$BБеги отсюда, пока не поздно...$B$BИх слишком много... верная смерть...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16069,'Город бурлит. Вместо победного клича Азш\'ир выкрикивают твое имя. Сегодня тебе почет и уважение.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Город бурлит. Вместо победного клича Азш\'ир выкрикивают твое имя. Сегодня тебе почет и уважение.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16070,'Не ожидал, что город удастся захватить так быстро. Похоже, у нас вдосталь времени, чтобы подготовиться к вторжению.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не ожидал, что город удастся захватить так быстро. Похоже, у нас вдосталь времени, чтобы подготовиться к вторжению.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16071,'Заклинания призыва готовы, но они не сработают без тигеля Наз\'жар – источника силы чар. Необходимо получить артефакт.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Заклинания призыва готовы, но они не сработают без тигеля Наз\'жар – источника силы чар. Необходимо получить артефакт.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16072,'Матиас Шоу лично отправил меня на помощь ночным эльфам.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Матиас Шоу лично отправил меня на помощь ночным эльфам.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16074,'Из-за катаклизма в Дун Мороге воцарился хаос. Трогги лезут на поверхность в небывалых количествах, и из-за этого наши давние враги, тролли из племени Мерзлогривов, подступают все ближе к поселениям.$b$bСтальгорн отправил мою команду горных пехотинцев разобраться с проблемами.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Из-за катаклизма в Дун Мороге воцарился хаос. Трогги лезут на поверхность в небывалых количествах, и из-за этого наши давние враги, тролли из племени Мерзлогривов, подступают все ближе к поселениям.$b$bСтальгорн отправил мою команду горных пехотинцев разобраться с проблемами.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16075,'Новая жизнь, родившаяся из пепла старой… Это дар Эссины.$B$BБез тебя этого чуда не произошло бы.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Новая жизнь, родившаяся из пепла старой… Это дар Эссины.$B$BБез тебя этого чуда не произошло бы.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16076,'<Древний поворачивается и смотрит на вас, его глаза огромны. Глядя в них, вы словно погружаетесь в глубокие воды океана.>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Древний поворачивается и смотрит на вас, его глаза огромны. Глядя в них, вы словно погружаетесь в глубокие воды океана.>',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16077,'Когда мы закончим здесь, эти Мерзлогривы будут бояться нас больше, чем троггов. У них не останется другого выхода, кроме как уйти.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Когда мы закончим здесь, эти Мерзлогривы будут бояться нас больше, чем троггов. У них не останется другого выхода, кроме как уйти.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`,`text2_0_loc8`,`text2_1_loc8`,`text3_0_loc8`,`text3_1_loc8`,`text4_0_loc8`,`text4_1_loc8`,`text5_0_loc8`,`text5_1_loc8`,`text6_0_loc8`,`text6_1_loc8`,`text7_0_loc8`,`text7_1_loc8`) VALUES (16078,'Г… Где я? Ты $gодин:одна; из них?','Г… Где я? Ты $gодин:одна; из них?','Все уже кончилось?','Все уже кончилось?','Должен… вернуться… к Железному Лесу!','Должна… вернуться… к Железному Лесу!','Ты не из Сумеречного Молота. Что тут происходит?','Ты не из Сумеречного Молота. Что тут происходит?','Я обгорел. Сильно.','Я обгорела. Сильно.','Сумеречный Молот… Я слышал, как они кричали и бежали… мы перешли в контратаку?','Сумеречный Молот… Я слышала, как они кричали и бежали… мы перешли в контратаку?','Город… разрушен! Мы не можем остановить их.','Город… разрушен! Мы не можем остановить их.','Они открыли порталы на Огненные Просторы… Скажи мне, что еще есть надежда!','Они открыли порталы на Огненные Просторы… Скажи мне, что еще есть надежда!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Г… Где я? Ты $gодин:одна; из них?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Г… Где я? Ты $gодин:одна; из них?',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Все уже кончилось?',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Все уже кончилось?',`text1_1_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Должен… вернуться… к Железному Лесу!',`text2_0_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Должна… вернуться… к Железному Лесу!',`text2_1_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Ты не из Сумеречного Молота. Что тут происходит?',`text3_0_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','Ты не из Сумеречного Молота. Что тут происходит?',`text3_1_loc8`), `text4_0_loc8`=IF(`text4_0_loc8` IS NULL OR `text4_0_loc8`='','Я обгорел. Сильно.',`text4_0_loc8`), `text4_1_loc8`=IF(`text4_1_loc8` IS NULL OR `text4_1_loc8`='','Я обгорела. Сильно.',`text4_1_loc8`), `text5_0_loc8`=IF(`text5_0_loc8` IS NULL OR `text5_0_loc8`='','Сумеречный Молот… Я слышал, как они кричали и бежали… мы перешли в контратаку?',`text5_0_loc8`), `text5_1_loc8`=IF(`text5_1_loc8` IS NULL OR `text5_1_loc8`='','Сумеречный Молот… Я слышала, как они кричали и бежали… мы перешли в контратаку?',`text5_1_loc8`), `text6_0_loc8`=IF(`text6_0_loc8` IS NULL OR `text6_0_loc8`='','Город… разрушен! Мы не можем остановить их.',`text6_0_loc8`), `text6_1_loc8`=IF(`text6_1_loc8` IS NULL OR `text6_1_loc8`='','Город… разрушен! Мы не можем остановить их.',`text6_1_loc8`), `text7_0_loc8`=IF(`text7_0_loc8` IS NULL OR `text7_0_loc8`='','Они открыли порталы на Огненные Просторы… Скажи мне, что еще есть надежда!',`text7_0_loc8`), `text7_1_loc8`=IF(`text7_1_loc8` IS NULL OR `text7_1_loc8`='','Они открыли порталы на Огненные Просторы… Скажи мне, что еще есть надежда!',`text7_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16084,'Она... Она очень старая и мудрая. Поговорив с Неспирой, мы многое узнаем о нагах и о Вайш\'ире.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Она... Она очень старая и мудрая. Поговорив с Неспирой, мы многое узнаем о нагах и о Вайш\'ире.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16085,'Старая таверна пришла в упадок, но из нее может получиться неплохая крепость.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Старая таверна пришла в упадок, но из нее может получиться неплохая крепость.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16089,'Темная сила охватила Пик Каменного Когтя.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Темная сила охватила Пик Каменного Когтя.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16090,'Я не могу понять, что это за место.$B$BДа, эти коридоры служат для перемещения войск, но они усеяны обугленными телами. Некоторые из них частично съедены, но большинство просто сильно изуродовано.$B$BМы на Огненных Просторах, но у меня такое ощущение, что мы перешагнули порог ада.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я не могу понять, что это за место.$B$BДа, эти коридоры служат для перемещения войск, но они усеяны обугленными телами. Некоторые из них частично съедены, но большинство просто сильно изуродовано.$B$BМы на Огненных Просторах, но у меня такое ощущение, что мы перешагнули порог ада.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16094,'Я много раз пытался объяснить Сэлсбери, что не существует возможности превратить его в воргена. Он отказывается слушать. Похоже, он убедил себя в том, что если он сможет завоевать мое доверие, то я открою ему эту тайну.$B$BГномы – очень странный народ.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я много раз пытался объяснить Сэлсбери, что не существует возможности превратить его в воргена. Он отказывается слушать. Похоже, он убедил себя в том, что если он сможет завоевать мое доверие, то я открою ему эту тайну.$B$BГномы – очень странный народ.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16095,'Стойкость Голдринна вошла в легенды.$B$BВоины из разных краев приходят в это святилище, чтобы причаститься столь славной воинской доблести.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Стойкость Голдринна вошла в легенды.$B$BВоины из разных краев приходят в это святилище, чтобы причаститься столь славной воинской доблести.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text1_0_loc8`) VALUES (16097,'От нашего боевого снаряжения здесь мало проку.$B$BСначала необходимо подготовиться...') ON DUPLICATE KEY UPDATE `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','От нашего боевого снаряжения здесь мало проку.$B$BСначала необходимо подготовиться...',`text1_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`) VALUES (16099,'Благодаря твоим усилиям боевой дух наших воинов растет, |3-6($c).','Если мы все-таки выкарабкаемся, я непременно поведаю Адскому Крику о твоем подвиге, |3-6($r).','Я прошел плечом к плечу с этими орками немало битв.$B$BНе завидую наге, которая сюда забредет.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Благодаря твоим усилиям боевой дух наших воинов растет, |3-6($c).',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Если мы все-таки выкарабкаемся, я непременно поведаю Адскому Крику о твоем подвиге, |3-6($r).',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Я прошел плечом к плечу с этими орками немало битв.$B$BНе завидую наге, которая сюда забредет.',`text2_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16100,'Он никогда не сдавался, капитан Железный Лес. Он говорил, что заставит их заплатить за каждую пядь оскверненной земли. Он может быть еще жив!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Он никогда не сдавался, капитан Железный Лес. Он говорил, что заставит их заплатить за каждую пядь оскверненной земли. Он может быть еще жив!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16101,'На качество и количество материалов здесь жаловаться не приходится. Заменители для всего. Заменители для заменителей. Я бы за несколько дней сконструировал водяной болид из водорослей и ракушек!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','На качество и количество материалов здесь жаловаться не приходится. Заменители для всего. Заменители для заменителей. Я бы за несколько дней сконструировал водяной болид из водорослей и ракушек!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16105,'Здесь не так прохладно, как в руинах, и воздух немного влажноват, но все равно я чувствую себя почти как дома.$B$BТебе так не кажется?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здесь не так прохладно, как в руинах, и воздух немного влажноват, но все равно я чувствую себя почти как дома.$B$BТебе так не кажется?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16106,'Не знаю, как тебе, а мне точно не хватает тех материалов, которые просто не переводились в руинах!$B$BИз того, что можно насобирать в этой пещере, я вряд ли смогу сделать даже учебную гранату!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не знаю, как тебе, а мне точно не хватает тех материалов, которые просто не переводились в руинах!$B$BИз того, что можно насобирать в этой пещере, я вряд ли смогу сделать даже учебную гранату!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16107,'Наги.$B$B<Злобношип презрительно плюет на землю.>$B$BЗря они решили, что орков можно заставлять трудиться из-под палки. Они еще пожалеют о том, что не убили нас, когда имели такую возможность.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Наги.$B$B<Злобношип презрительно плюет на землю.>$B$BЗря они решили, что орков можно заставлять трудиться из-под палки. Они еще пожалеют о том, что не убили нас, когда имели такую возможность.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16108,'Добро пожаловать.\r\n\r\nС припасами у нас, увы, негусто, но я помогу тебе всем, чем смогу.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать.\r\n\r\nС припасами у нас, увы, негусто, но я помогу тебе всем, чем смогу.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16111,'Пришел или уже уходишь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Пришел или уже уходишь?',`text0_0_loc8`);
