INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16112,'Стойкость древнего волка воспета в легендах.$B$BПоследуй его примеру, |3-6($c), и победа будет за тобой.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Стойкость древнего волка воспета в легендах.$B$BПоследуй его примеру, |3-6($c), и победа будет за тобой.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16113,'Когда первые животные появились на просторах Азерота, Голдринн уже был там. Он – воплощение духа охотника, того животного инстинкта, который пробуждается, когда зверь чует запах еды или понимает, что его детям грозит беда. Обычно он принимает облик огромного белого волка, свирепого и хитрого.$B$BОн известен любому народу. Орки, например, называют его "Ло\'гош."$B$BДесять тысяч лет назад, когда демоны впервые прорвались в Азерот, Голдринн вместе с другими древними организовал отчаянную оборону.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Когда первые животные появились на просторах Азерота, Голдринн уже был там. Он – воплощение духа охотника, того животного инстинкта, который пробуждается, когда зверь чует запах еды или понимает, что его детям грозит беда. Обычно он принимает облик огромного белого волка, свирепого и хитрого.$B$BОн известен любому народу. Орки, например, называют его "Ло\'гош."$B$BДесять тысяч лет назад, когда демоны впервые прорвались в Азерот, Голдринн вместе с другими древними организовал отчаянную оборону.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16115,'Ло\'гош – это дух охотника, животный инстинкт, наполняющий тебя, когда чувствуешь запах пищи или видишь, как что–то угрожает твоим детям. Он всегда был с нами, всегда был частью Орды. Он в нашей крови и в нашем естестве.$B$BОн появляется в разных обличьях, как в нашем мире, так и здесь. В Азероте он обычно является в облике огромного белого волка, свирепого и хитрого. Ночные эльфы зовут его "Голдринн."$B$BУ них есть легенды о великой битве, случившейся десять тысяч лет тому назад, в которой Ло\'гош сражался с толпами демонов. Хочешь услышать об этом?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ло\'гош – это дух охотника, животный инстинкт, наполняющий тебя, когда чувствуешь запах пищи или видишь, как что–то угрожает твоим детям. Он всегда был с нами, всегда был частью Орды. Он в нашей крови и в нашем естестве.$B$BОн появляется в разных обличьях, как в нашем мире, так и здесь. В Азероте он обычно является в облике огромного белого волка, свирепого и хитрого. Ночные эльфы зовут его "Голдринн."$B$BУ них есть легенды о великой битве, случившейся десять тысяч лет тому назад, в которой Ло\'гош сражался с толпами демонов. Хочешь услышать об этом?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16116,'Десять тысяч лет назад демоны впервые прорвались в этот мир, как некогда в родной мир орков, Дренор. Их легионы наводнили землю. Великие древние хранители Азерота помогли смертным расам организовать отчаянную оборону.$B$BСтойкость, проявленная Ло\'гошем в эти мрачные дни, стала легендарной. Демоны не страшили его. Он врывался в их ряды, с его обнаженных клыков лилась их кровь, под ударами его когтей твари падали десятками…$B$BЕго отвага в этом бою вдохновляет нас всех. Мы должны ставить его себе в пример.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Десять тысяч лет назад демоны впервые прорвались в этот мир, как некогда в родной мир орков, Дренор. Их легионы наводнили землю. Великие древние хранители Азерота помогли смертным расам организовать отчаянную оборону.$B$BСтойкость, проявленная Ло\'гошем в эти мрачные дни, стала легендарной. Демоны не страшили его. Он врывался в их ряды, с его обнаженных клыков лилась их кровь, под ударами его когтей твари падали десятками…$B$BЕго отвага в этом бою вдохновляет нас всех. Мы должны ставить его себе в пример.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16117,'Приветствую, |3-6($c)!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Приветствую, |3-6($c)!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16118,'Светлая Авиана, Повелительница Птиц! Некогда все крылатые существа Азерота присягнули ей на верность, особенно мы, друиды-вороны. Лишь ее милостью мы способны принимать иное обличье и подниматься в небо.$B$BАвиана была прекрасна и ужасна одновременно, подобно огромным хищным птицам, которых она считала своими детьми. Она обитала в ином мире, расположенном в ветвях Г\'ханира Изначального Древа, но иногда появлялась в Азероте в обличье великой крылатой богини.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Светлая Авиана, Повелительница Птиц! Некогда все крылатые существа Азерота присягнули ей на верность, особенно мы, друиды-вороны. Лишь ее милостью мы способны принимать иное обличье и подниматься в небо.$B$BАвиана была прекрасна и ужасна одновременно, подобно огромным хищным птицам, которых она считала своими детьми. Она обитала в ином мире, расположенном в ветвях Г\'ханира Изначального Древа, но иногда появлялась в Азероте в обличье великой крылатой богини.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16119,'<На лицо Чолуны набегает тень.>$B$BДесять тысяч лет тому назад демоны наводнили Азерот – и началась Война древних. Авиана призвала своих детей в небеса и отбросила орды демонов назад. От ее гнева не было спасения.$B$BСотни врагов погибли от ее когтей. Но, в конце концов, ее окружили стражники ужаса, их зазубренные пики вонзились в ее тело…$B$BГоворят, что сама кровь ее бросилась на демонов, прожигая их плоть, даже когда сама она пала на землю.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','<На лицо Чолуны набегает тень.>$B$BДесять тысяч лет тому назад демоны наводнили Азерот – и началась Война древних. Авиана призвала своих детей в небеса и отбросила орды демонов назад. От ее гнева не было спасения.$B$BСотни врагов погибли от ее когтей. Но, в конце концов, ее окружили стражники ужаса, их зазубренные пики вонзились в ее тело…$B$BГоворят, что сама кровь ее бросилась на демонов, прожигая их плоть, даже когда сама она пала на землю.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16120,'В тот день Авиана пала на поле битвы, но расы смертных и оставшиеся древние одержали победу. Первые друиды отыскали ее тело среди многих павших и похоронили его здесь, на самой высокой горе.$B$BОна была предана земле рядом с этим святилищем, в круге священных камней.$B$BИз семени Г\'Ханира выросло Древо Жизни, и это единственное, что осталось от того священного мира, что мог бы безвозвратно сгинуть вместе с ней.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','В тот день Авиана пала на поле битвы, но расы смертных и оставшиеся древние одержали победу. Первые друиды отыскали ее тело среди многих павших и похоронили его здесь, на самой высокой горе.$B$BОна была предана земле рядом с этим святилищем, в круге священных камней.$B$BИз семени Г\'Ханира выросло Древо Жизни, и это единственное, что осталось от того священного мира, что мог бы безвозвратно сгинуть вместе с ней.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16121,'Мы, смертные расы, мало что знаем об Эссине, духе природы, которая скрывается в непроходимых лесных чащах. Она – душа леса, его бьющееся сердце, источник той силы, что дробит камни, поглощает древние руины и наполняет густые чащи таинственностью и страхом. Эссина находится в центре паутины жизни.$B$BНочные эльфы построили в ее честь святилища по всему Калимдору. Ее почитают, это правда… Но никто не понимает.$B$BКак ты думаешь, каково это – узреть, пусть лишь на миг, это могучее древнее создание?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мы, смертные расы, мало что знаем об Эссине, духе природы, которая скрывается в непроходимых лесных чащах. Она – душа леса, его бьющееся сердце, источник той силы, что дробит камни, поглощает древние руины и наполняет густые чащи таинственностью и страхом. Эссина находится в центре паутины жизни.$B$BНочные эльфы построили в ее честь святилища по всему Калимдору. Ее почитают, это правда… Но никто не понимает.$B$BКак ты думаешь, каково это – узреть, пусть лишь на миг, это могучее древнее создание?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16123,'А, Тортолла! Его часто не понимали и всегда, всегда недооценивали. Существа, которые без труда переходят с земли в море и обратно, считают древнего Тортоллу своим покровителем.$B$BДесять тысяч лет назад Пылающий Легион напал на Азерот, и Тортолла был одним из тех древних, кто пошел в бой вместе с Кенарием и смертными расами.$B$BКогда орды демонов ринулись на окруженных защитников, они просто не знали, что делать с Тортоллой. Поначалу они пытались не обращать на него внимания, но его огромный вес и сокрушающие челюсти привели к смерти сотен и сотен врагов…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','А, Тортолла! Его часто не понимали и всегда, всегда недооценивали. Существа, которые без труда переходят с земли в море и обратно, считают древнего Тортоллу своим покровителем.$B$BДесять тысяч лет назад Пылающий Легион напал на Азерот, и Тортолла был одним из тех древних, кто пошел в бой вместе с Кенарием и смертными расами.$B$BКогда орды демонов ринулись на окруженных защитников, они просто не знали, что делать с Тортоллой. Поначалу они пытались не обращать на него внимания, но его огромный вес и сокрушающие челюсти привели к смерти сотен и сотен врагов…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16125,'Дворфы Громового Молота всегда занимались шаманством, но оказаться в морской глубине в кругу Служителей Земли?\r\n\r\nГод назад я бы поверил такому только после полудюжины кружек хорошего эля.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Дворфы Громового Молота всегда занимались шаманством, но оказаться в морской глубине в кругу Служителей Земли?\r\n\r\nГод назад я бы поверил такому только после полудюжины кружек хорошего эля.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`) VALUES (16126,'Наши воины... их всех взяли в плен.','Многие пытались спастись от наг.$B$BЯ единственный, кому удалось...','Непонятно почему, но эти твари идут на все, лишь бы наши солдаты оставались в живых...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Наши воины... их всех взяли в плен.',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Многие пытались спастись от наг.$B$BЯ единственный, кому удалось...',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Непонятно почему, но эти твари идут на все, лишь бы наши солдаты оставались в живых...',`text2_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16127,'Я Гуррок, боец Авангарда Адского Крика.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я Гуррок, боец Авангарда Адского Крика.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16128,'Мы почти догнали их!$b$bПроклятые корабли Альянса… Мы могли бы пробиться в Штормград и потопить их!$b$bТут из ниоткуда взялись гигантские щупальца и схватили наше судно, после чего оно разломилось пополам!$b$bТех, кто выжил и упал в воду, сразу же схватили наги.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы почти догнали их!$b$bПроклятые корабли Альянса… Мы могли бы пробиться в Штормград и потопить их!$b$bТут из ниоткуда взялись гигантские щупальца и схватили наше судно, после чего оно разломилось пополам!$b$bТех, кто выжил и упал в воду, сразу же схватили наги.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16129,'Странно, но наги делали все возможное, чтобы мы не погибли.$B$BНаши камеры были сработаны из особых жемчужин – в них можно дышать, но не более того...$B$BОни сгоняют пленников... куда-то в одно место.$B$BОттуда никто не возвращался...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Странно, но наги делали все возможное, чтобы мы не погибли.$B$BНаши камеры были сработаны из особых жемчужин – в них можно дышать, но не более того...$B$BОни сгоняют пленников... куда-то в одно место.$B$BОттуда никто не возвращался...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16130,'Один из наших вырвался на свободу и раскурочил много камер... мы оказались на свободе – по крайней мере, на короткое время.$B$BКто-то стремглав поплыл на поверхность... кто-то увидел эту пещеру и кинулся к ней.$B$BЯ – единственный выживший...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Один из наших вырвался на свободу и раскурочил много камер... мы оказались на свободе – по крайней мере, на короткое время.$B$BКто-то стремглав поплыл на поверхность... кто-то увидел эту пещеру и кинулся к ней.$B$BЯ – единственный выживший...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16131,'Не знаю, что с ними стало.$B$BПостоянно пригоняли новых пленных. Воины Орды, Альянса – я видел и тех, и других, еле живых.$B$BДолжно быть, их уволокли на другую сторону впадины. А может быть, они погибли.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не знаю, что с ними стало.$B$BПостоянно пригоняли новых пленных. Воины Орды, Альянса – я видел и тех, и других, еле живых.$B$BДолжно быть, их уволокли на другую сторону впадины. А может быть, они погибли.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16132,'Их там столько, что не счесть. А укрепления кажутся неприступными.$B$BЯ не заметил ни одного слабого места, |3-6($r).') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Их там столько, что не счесть. А укрепления кажутся неприступными.$B$BЯ не заметил ни одного слабого места, |3-6($r).',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16138,'Вождь Адский Крик следит за каждым из нас!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вождь Адский Крик следит за каждым из нас!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16140,'Эти земли граничат с владениями Темной Госпожи, $n. Запомни их, через некоторое время они все будут в руках Отрекшихся.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Эти земли граничат с владениями Темной Госпожи, $n. Запомни их, через некоторое время они все будут в руках Отрекшихся.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16142,'Да хранит тебя Темная Госпожа…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да хранит тебя Темная Госпожа…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16143,'Как я могу содержать в таверну в чистоте, когда вокруг творится такое? Может, ты разберешься с этими пигмеями?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Как я могу содержать в таверну в чистоте, когда вокруг творится такое? Может, ты разберешься с этими пигмеями?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16144,'Гоблины-зомби?! Что же будет дальше?.. Может, вулкан взорвется?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Гоблины-зомби?! Что же будет дальше?.. Может, вулкан взорвется?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16147,'Да, Воительница?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Да, Воительница?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16149,'Воительница, вы изволили почтить меня вашим присутствием. Настало ли время провести ритуал?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Воительница, вы изволили почтить меня вашим присутствием. Настало ли время провести ритуал?',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16157,'Чего нужно сделать?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Чего нужно сделать?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16164,'Упс! Это... Здрасьте. Я тут просто ракушку осматривал, эту вот. Все, вперед! Не на что тут глазеть!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Упс! Это... Здрасьте. Я тут просто ракушку осматривал, эту вот. Все, вперед! Не на что тут глазеть!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16165,'У меня тут сложная задачка... с плавающей пятой точкой.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','У меня тут сложная задачка... с плавающей пятой точкой.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16166,'Да откуда я знаю. Может, кость у меня пористая. Может, объем легких чрезмерный. А может, зря я гороховый суп на обед ел.$B$BКак бы то ни было, если я отпущу эту ракушку, то взмою на поверхность, как пузырь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да откуда я знаю. Может, кость у меня пористая. Может, объем легких чрезмерный. А может, зря я гороховый суп на обед ел.$B$BКак бы то ни было, если я отпущу эту ракушку, то взмою на поверхность, как пузырь.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16167,'Ага, и это наследственное. Боюсь, у семейки Ройпоев всегда были проблемы с плавучестью.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ага, и это наследственное. Боюсь, у семейки Ройпоев всегда были проблемы с плавучестью.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16168,'Как-то так, $gмалой:душечка;... с грехом пополам. Одному Тору ведомо, сколько литров морской воды я уже вдохнул.$B$BТы еще не $gвидел:видела;, как я тут отбивался от огнепанцирного краба! Одними пинками да зубами, ей-богу! Схватка века, чтоб меня.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Как-то так, $gмалой:душечка;... с грехом пополам. Одному Тору ведомо, сколько литров морской воды я уже вдохнул.$B$BТы еще не $gвидел:видела;, как я тут отбивался от огнепанцирного краба! Одними пинками да зубами, ей-богу! Схватка века, чтоб меня.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16169,'Помню, когда я еще пешком под стол ходил, другие ребята ныряли прямо на дно Лок Модана, ловили ежей морских, ракушки собирали... А мы с Оскаром торчали на поверхности, ногами воздух молотили – и хоть бы на дюйм удалось погрузиться...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Помню, когда я еще пешком под стол ходил, другие ребята ныряли прямо на дно Лок Модана, ловили ежей морских, ракушки собирали... А мы с Оскаром торчали на поверхности, ногами воздух молотили – и хоть бы на дюйм удалось погрузиться...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16170,'Я несметное количество раз находил прекрасную, манящую жилу где-нибудь на дне озера или реки. Но я был вынужден бесцельно дрейфовать с киркой в руках, наблюдая лишь за тем, как какие-то орки или эльфы ныряют к жиле прямо перед моим носом.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я несметное количество раз находил прекрасную, манящую жилу где-нибудь на дне озера или реки. Но я был вынужден бесцельно дрейфовать с киркой в руках, наблюдая лишь за тем, как какие-то орки или эльфы ныряют к жиле прямо перед моим носом.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16171,'Кабы ты $gзнал:знала;, каково это – вот так застрять тут в Вайш\'ире! Уж сколько рыб приняли меня за водоросль – заплывали под броню, пятки мне щипали.$B$BДа любой дворф от одной щекотки уже взбеленится!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Кабы ты $gзнал:знала;, каково это – вот так застрять тут в Вайш\'ире! Уж сколько рыб приняли меня за водоросль – заплывали под броню, пятки мне щипали.$B$BДа любой дворф от одной щекотки уже взбеленится!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16172,'Вижу, тебе уже опостылело мое нытье. Оно и понятно.$B$BТы просто знай, как тебе повезло с "Морским волком" и способностью плыть в направлении, отличном от "вверх прямой наводкой".') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вижу, тебе уже опостылело мое нытье. Оно и понятно.$B$BТы просто знай, как тебе повезло с "Морским волком" и способностью плыть в направлении, отличном от "вверх прямой наводкой".',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
