INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16179,'Спасибо, что $gвернул:вернула; мне волка.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Спасибо, что $gвернул:вернула; мне волка.',`text0_0_loc8`);
