INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (16180,'Эти стаканчики и алхимические инструменты кто-то использует для проведения экспериментов над различными видами топлива для подводных лодок.','Эти стаканчики и алхимические инструменты кто-то использует для проведения экспериментов над различными видами топлива для подводных лодок.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эти стаканчики и алхимические инструменты кто-то использует для проведения экспериментов над различными видами топлива для подводных лодок.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Эти стаканчики и алхимические инструменты кто-то использует для проведения экспериментов над различными видами топлива для подводных лодок.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16181,'В этом самом лагере люди держали наших соплеменников как узников, как рабов. Я сидел взаперти в этих клетках, я видел своих собратьев в этих колодках, висящими на этих виселицах.$b$bЯ видел Оргрима Молота Рока, нашего предводителя, с ножом в спине.$b$bИ посмотри на нас сейчас. Вот наше наследие: Павший Молот, в котором мы сначала потеряли все и который потом вернули своими собственными руками.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','В этом самом лагере люди держали наших соплеменников как узников, как рабов. Я сидел взаперти в этих клетках, я видел своих собратьев в этих колодках, висящими на этих виселицах.$b$bЯ видел Оргрима Молота Рока, нашего предводителя, с ножом в спине.$b$bИ посмотри на нас сейчас. Вот наше наследие: Павший Молот, в котором мы сначала потеряли все и который потом вернули своими собственными руками.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (16182,'Перед вами несколько небольших образцов рыбьего жира и пустая пробирка. Судя по размерам пробирки, в ней можно смешать примерно пять образцов.$B$BС какого образца вы начнете?','Перед вами несколько небольших образцов рыбьего жира и пустая пробирка. Судя по размерам пробирки, в ней можно смешать примерно пять образцов.$B$BС какого образца вы начнете?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Перед вами несколько небольших образцов рыбьего жира и пустая пробирка. Судя по размерам пробирки, в ней можно смешать примерно пять образцов.$B$BС какого образца вы начнете?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Перед вами несколько небольших образцов рыбьего жира и пустая пробирка. Судя по размерам пробирки, в ней можно смешать примерно пять образцов.$B$BС какого образца вы начнете?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (16183,'Какой образец жира вы добавите следующим?','Какой образец жира вы добавите следующим?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Какой образец жира вы добавите следующим?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Какой образец жира вы добавите следующим?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (16184,'В пробирке два образца жира. Какой вы добавите следующим?','В пробирке два образца жира. Какой вы добавите следующим?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','В пробирке два образца жира. Какой вы добавите следующим?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','В пробирке два образца жира. Какой вы добавите следующим?',`text0_1_loc8`);
