INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (16186,'В пробирке четыре образца, и осталось место еще для одного. Какой образец вы добавите последним?','В пробирке четыре образца, и осталось место еще для одного. Какой образец вы добавите последним?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','В пробирке четыре образца, и осталось место еще для одного. Какой образец вы добавите последним?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','В пробирке четыре образца, и осталось место еще для одного. Какой образец вы добавите последним?',`text0_1_loc8`);
