INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (16188,'С помощью этих пробирок и алхимического оборудования вы сможете экспериментировать с разными видами топлива для подводной лодки.','С помощью этих пробирок и алхимического оборудования вы сможете экспериментировать с разными видами топлива для подводной лодки.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','С помощью этих пробирок и алхимического оборудования вы сможете экспериментировать с разными видами топлива для подводной лодки.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','С помощью этих пробирок и алхимического оборудования вы сможете экспериментировать с разными видами топлива для подводной лодки.',`text0_1_loc8`);
