INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (16190,'Вы открыли новый вид биотоплива! Отнесите его Облину Свистозубу для испытания.','Вы открыли новый вид биотоплива! Отнесите его Облину Свистозубу для испытания.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вы открыли новый вид биотоплива! Отнесите его Облину Свистозубу для испытания.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Вы открыли новый вид биотоплива! Отнесите его Облину Свистозубу для испытания.',`text0_1_loc8`);
