INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16193,'Мы убиваем этих наг десятками, но на месте убитых тут же появляются новые. Как же мы выберемся из этой проклятой пещеры?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы убиваем этих наг десятками, но на месте убитых тут же появляются новые. Как же мы выберемся из этой проклятой пещеры?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16194,'Пусть я сгину в бою, $n, но я заставлю наг заплатить за каждого убитого или порабощенного ими бойца!$b$bПусть другие думают о побеге. Моя забота – отомстить змеям.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Пусть я сгину в бою, $n, но я заставлю наг заплатить за каждого убитого или порабощенного ими бойца!$b$bПусть другие думают о побеге. Моя забота – отомстить змеям.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16195,'Зачем они это делают? Ради жемчуга? В военных целях? Это древнее существо, Неспира, куда могущественнее, чем думают наги. Если им удастся подчинить ее своей воле... ущерб будет огромен.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Зачем они это делают? Ради жемчуга? В военных целях? Это древнее существо, Неспира, куда могущественнее, чем думают наги. Если им удастся подчинить ее своей воле... ущерб будет огромен.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16197,'Нужна твоя помощь, |3-6($c). Мы прорывались сюда с тяжелыми боями, а нагам конца и края не видно.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Нужна твоя помощь, |3-6($c). Мы прорывались сюда с тяжелыми боями, а нагам конца и края не видно.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16199,'Если на твоих руках кровь наг, то ты $gмой союзник:моя союзница;.$b$bДавным-давно я поклялся, что никогда вновь не стану чьим-то рабом, и был верен своему слову, пока мы не попали в плен к Идра\'кессу. Сейчас я с трудом сдерживаю гнев. Я жажду лишь крови... не пищи, не сна и не победы... лишь крови.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если на твоих руках кровь наг, то ты $gмой союзник:моя союзница;.$b$bДавным-давно я поклялся, что никогда вновь не стану чьим-то рабом, и был верен своему слову, пока мы не попали в плен к Идра\'кессу. Сейчас я с трудом сдерживаю гнев. Я жажду лишь крови... не пищи, не сна и не победы... лишь крови.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16200,'Мои раны не исцеляются, |3-6($r). Боюсь, что погибну в брюхе у этой твари, если мы быстро что-то не предпримем.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мои раны не исцеляются, |3-6($r). Боюсь, что погибну в брюхе у этой твари, если мы быстро что-то не предпримем.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16202,'<У вас в голове раздается голос Л\'горека.>$B$BЯ ПОЧТИ… МЕРТВ. ПОМОГИ… ОСТАНОВИТЬ… КУЛЬТ СУМЕРЕЧНОГО МОЛОТА..$B$BСЕКТАНТЫ... ВЫСАСЫВАЮТ МОИ СИЛЫ, ЧТОБЫ… СОЗДАТЬ… ПЕРЕРОЖДЕННЫХ. ЭТО… ВЕЛИКАЯ ОПАСНОСТЬ… ВОЙНА… С НЕПТУЛОНОМ… НЕИЗБЕЖНА.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<У вас в голове раздается голос Л\'горека.>$B$BЯ ПОЧТИ… МЕРТВ. ПОМОГИ… ОСТАНОВИТЬ… КУЛЬТ СУМЕРЕЧНОГО МОЛОТА..$B$BСЕКТАНТЫ... ВЫСАСЫВАЮТ МОИ СИЛЫ, ЧТОБЫ… СОЗДАТЬ… ПЕРЕРОЖДЕННЫХ. ЭТО… ВЕЛИКАЯ ОПАСНОСТЬ… ВОЙНА… С НЕПТУЛОНОМ… НЕИЗБЕЖНА.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16203,'Элементали в ярости. Наги-то тут точно не просто так. Этим тварям чего-то надо.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Элементали в ярости. Наги-то тут точно не просто так. Этим тварям чего-то надо.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16214,'Надо же! Я такое видел, через столькое прошел, и я все еще жив… Я очень везучий гном.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Надо же! Я такое видел, через столькое прошел, и я все еще жив… Я очень везучий гном.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (16216,'Готовить для короля – великая честь. Не хочешь приобщиться великому делу?','Готовить для короля – великая честь. Не хочешь приобщиться великому делу?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Готовить для короля – великая честь. Не хочешь приобщиться великому делу?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Готовить для короля – великая честь. Не хочешь приобщиться великому делу?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16219,'Здесь, в крепости Стражей Пустоты, бывает скучновато. Иногда дворфу просто нужно немного пива, чтобы ненадолго отвлечься от службы.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Здесь, в крепости Стражей Пустоты, бывает скучновато. Иногда дворфу просто нужно немного пива, чтобы ненадолго отвлечься от службы.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16220,'Я всего-то решил немного отдохнуть. Постоянно стоять на страже не так просто, как может показаться, |3-6($r).') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я всего-то решил немного отдохнуть. Постоянно стоять на страже не так просто, как может показаться, |3-6($r).',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16222,'Прости, |3-6($c), я не могу помочь тебе. Ты $gдолжен:должна; найти учителя |3-8($c).') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Прости, |3-6($c), я не могу помочь тебе. Ты $gдолжен:должна; найти учителя |3-8($c).',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16230,'Прости, но я не могу обучать тебя. Ты $gдолжен:должна; найти кого-то, лучше знакомого с твоими умениями.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Прости, но я не могу обучать тебя. Ты $gдолжен:должна; найти кого-то, лучше знакомого с твоими умениями.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16234,'Если нам суждено погибнуть – пусть мы падем в славном бою с нашими ненавистными врагами!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если нам суждено погибнуть – пусть мы падем в славном бою с нашими ненавистными врагами!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16237,'Л\'горек – имя древнего божества, находящегося на другом краю пропасти. С ним что-то происходит.$B$BМы должны положить этому конец, или нам не поздоровится!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Л\'горек – имя древнего божества, находящегося на другом краю пропасти. С ним что-то происходит.$B$BМы должны положить этому конец, или нам не поздоровится!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16238,'Несмотря на все наши усилия, наги все равно атаковали пролом!$B$BМы должны защитить царство воды!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Несмотря на все наши усилия, наги все равно атаковали пролом!$B$BМы должны защитить царство воды!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16239,'Возле Обрыва над бездной кипит битва. Надеюсь, подкрепления, которое прибыло на "Хвате X2", будет достаточно.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Возле Обрыва над бездной кипит битва. Надеюсь, подкрепления, которое прибыло на "Хвате X2", будет достаточно.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16243,'По мне, так пусть икота и плот разберутся с этим полково и щавельно.$B$BЗнамое бремя нам давать отсюда деру, пока мы тут все еще не номер твой. $B$BУлавливаешь, о чем я, моя радость?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','По мне, так пусть икота и плот разберутся с этим полково и щавельно.$B$BЗнамое бремя нам давать отсюда деру, пока мы тут все еще не номер твой. $B$BУлавливаешь, о чем я, моя радость?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16244,'Только между нами, дорогуша, я на такой службе долго не протяну. Еще месяцок – и умываю руки.$B$BОднажды я уже умерла. Второй раз что-то нет желания.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Только между нами, дорогуша, я на такой службе долго не протяну. Еще месяцок – и умываю руки.$B$BОднажды я уже умерла. Второй раз что-то нет желания.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16245,'Помочь первому древнему, Неспире, было нелегко. Второй древний, что напротив нас, – Л\'горек – умирает.$B$BЯ чувствую, как он стонет в агонии. Что-то поглощает его жизненные силы. Но что – и зачем?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Помочь первому древнему, Неспире, было нелегко. Второй древний, что напротив нас, – Л\'горек – умирает.$B$BЯ чувствую, как он стонет в агонии. Что-то поглощает его жизненные силы. Но что – и зачем?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16247,'Эта пучина – сама по себе настоящий кошмар.$B$BВпрочем, по сравнению с битвой у Провала, в которую нам предстоит вступить, это просто бассейн-лягушатник.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Эта пучина – сама по себе настоящий кошмар.$B$BВпрочем, по сравнению с битвой у Провала, в которую нам предстоит вступить, это просто бассейн-лягушатник.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`,`text2_0_loc8`,`text2_1_loc8`,`text3_0_loc8`,`text3_1_loc8`,`text4_0_loc8`,`text4_1_loc8`) VALUES (16250,'Че надо?','Че надо?','Ниче я не скажу!','Ниче я не скажу!','Проваливай.','Проваливай.','О! $GПрибыл наш герой:Прибыла наша героиня;. Я спасен! Угу…','О! $GПрибыл наш герой:Прибыла наша героиня;. Я спасена! Угу…','Хочешь поговорить? Плати.','Хочешь поговорить? Плати.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Че надо?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Че надо?',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Ниче я не скажу!',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Ниче я не скажу!',`text1_1_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Проваливай.',`text2_0_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Проваливай.',`text2_1_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','О! $GПрибыл наш герой:Прибыла наша героиня;. Я спасен! Угу…',`text3_0_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','О! $GПрибыл наш герой:Прибыла наша героиня;. Я спасена! Угу…',`text3_1_loc8`), `text4_0_loc8`=IF(`text4_0_loc8` IS NULL OR `text4_0_loc8`='','Хочешь поговорить? Плати.',`text4_0_loc8`), `text4_1_loc8`=IF(`text4_1_loc8` IS NULL OR `text4_1_loc8`='','Хочешь поговорить? Плати.',`text4_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16256,'Земля страдает… Она просит пощады, |3-6($r), она просит пощады.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Земля страдает… Она просит пощады, |3-6($r), она просит пощады.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (16258,'Прокормить армию Орды не так уж и легко. У меня уйма работы, не хочешь помочь?','Прокормить армию Орды не так уж и легко. У меня уйма работы, не хочешь помочь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Прокормить армию Орды не так уж и легко. У меня уйма работы, не хочешь помочь?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Прокормить армию Орды не так уж и легко. У меня уйма работы, не хочешь помочь?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16259,'Мы должны сделать все возможное, чтобы воссоединить фрагменты столпа мира.$b$bНо сначала мы должны их все отыскать.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мы должны сделать все возможное, чтобы воссоединить фрагменты столпа мира.$b$bНо сначала мы должны их все отыскать.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16260,'Я всю жизнь прожил в Западном Крае, $gбрат:сестра;. Я еще помню дни, когда он был самой процветающей землей по эту сторону Тернистой долины. Эти дни давно миновали.$B$BХотя Братство Справедливости больше не причиняет нам вреда, мы все еще ощущаем последствия его кровавого правления. Более того, наступил самый страшный спад экономики за всю историю. Мы потратили слишком много золота на борьбу с Плетью, поэтому все гражданские остались без работы и жилья.$B$BУгадай, где они теперь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я всю жизнь прожил в Западном Крае, $gбрат:сестра;. Я еще помню дни, когда он был самой процветающей землей по эту сторону Тернистой долины. Эти дни давно миновали.$B$BХотя Братство Справедливости больше не причиняет нам вреда, мы все еще ощущаем последствия его кровавого правления. Более того, наступил самый страшный спад экономики за всю историю. Мы потратили слишком много золота на борьбу с Плетью, поэтому все гражданские остались без работы и жилья.$B$BУгадай, где они теперь?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16262,'О, конечно, она говорила, что это будет простая и приятная прогулка.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','О, конечно, она говорила, что это будет простая и приятная прогулка.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16264,'Даже здесь, под лучами солнца, я ощущаю тьму, которая таится в этих землях.$B$BЭто прекрасно, не так ли?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Даже здесь, под лучами солнца, я ощущаю тьму, которая таится в этих землях.$B$BЭто прекрасно, не так ли?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16265,'Мы рады тому, что наше племя – последнее из лесных троллей, которое служит Орде.$B$BСо временем мы разделаемся с остальными племенами и дворфами, и Внутренние земли будут принадлежать нам.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы рады тому, что наше племя – последнее из лесных троллей, которое служит Орде.$B$BСо временем мы разделаемся с остальными племенами и дворфами, и Внутренние земли будут принадлежать нам.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16269,'Местные тролли хорошо относятся к таким, как я. В конце концов, они говорили с мертвыми еще за столетия до того, как появились Отрекшиеся.$B$BЭто хорошо для бизнеса.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Местные тролли хорошо относятся к таким, как я. В конце концов, они говорили с мертвыми еще за столетия до того, как появились Отрекшиеся.$B$BЭто хорошо для бизнеса.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16270,'В юности мои родные не одобряли моей увлеченности шаманством. В силу своей глупости и горячности я сбежала от них, чтобы заниматься самостоятельно. Вернувшись домой спустя какое-то время, я обнаружила, что мои родители пропали. Мой дом был разрушен. Нам так и не удалось узнать, кто это сделал.\r\n\r\nВсю свою жизнь я пыталась развить свой дар шаманского ясновидения, чтобы заглянуть в прошлое и узнать, что же случилось с моей семьей и найти виновника происшедшего. Мне удалось достичь очень многого. Я научилась концентрироваться на событиях недавнего прошлого, но трагическая история столь давних дней все еще остается для меня загадкой.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','В юности мои родные не одобряли моей увлеченности шаманством. В силу своей глупости и горячности я сбежала от них, чтобы заниматься самостоятельно. Вернувшись домой спустя какое-то время, я обнаружила, что мои родители пропали. Мой дом был разрушен. Нам так и не удалось узнать, кто это сделал.\r\n\r\nВсю свою жизнь я пыталась развить свой дар шаманского ясновидения, чтобы заглянуть в прошлое и узнать, что же случилось с моей семьей и найти виновника происшедшего. Мне удалось достичь очень многого. Я научилась концентрироваться на событиях недавнего прошлого, но трагическая история столь давних дней все еще остается для меня загадкой.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16272,'Джинта\'алор будет нашим. Племя Порочной Ветви – просто никчемные слабаки и предатели, недостойные милости лоа.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Джинта\'алор будет нашим. Племя Порочной Ветви – просто никчемные слабаки и предатели, недостойные милости лоа.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16280,'Закончи приготовления, $n, да побыстрее!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Закончи приготовления, $n, да побыстрее!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16283,'Не мешай орку Драконьей Пасти наслаждаться выпивкой, |3-6($c).$B$BЯ сражался с чудовищами, от которых у тебя волосы дыбом встанут; видел, как погибли мои люди в болотах и руинах Запределья.$B$BВсе. До единого.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не мешай орку Драконьей Пасти наслаждаться выпивкой, |3-6($c).$B$BЯ сражался с чудовищами, от которых у тебя волосы дыбом встанут; видел, как погибли мои люди в болотах и руинах Запределья.$B$BВсе. До единого.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16284,'Что такое, |3-6($c)? Знаешь мое имя?$B$BМожет, тебе еще известно, что я сделал?$B$BЯ Огенеклык из клана Драконьей Пасти. Командовал легионами, летал на спине дракона, был свидетелем падения Грим Батола...$B$BПроклятье на Сумеречный Молот и всех его огров. Взгляни на меня! Все, что мне осталось, – это пустая болтовня и дешевая выпивка.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что такое, |3-6($c)? Знаешь мое имя?$B$BМожет, тебе еще известно, что я сделал?$B$BЯ Огенеклык из клана Драконьей Пасти. Командовал легионами, летал на спине дракона, был свидетелем падения Грим Батола...$B$BПроклятье на Сумеречный Молот и всех его огров. Взгляни на меня! Все, что мне осталось, – это пустая болтовня и дешевая выпивка.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16285,'Сумеречный Молот хочет меня прикончить? Вот ублюдки!$B$BРазумеется, я помогу тебе, |3-6($c). Так, говоришь, тебе нужна карта?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Сумеречный Молот хочет меня прикончить? Вот ублюдки!$B$BРазумеется, я помогу тебе, |3-6($c). Так, говоришь, тебе нужна карта?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16286,'Неважно, что происходит в других местах. Стальгорн не забывает об этих землях, как и о землях Каз Модана.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Неважно, что происходит в других местах. Стальгорн не забывает об этих землях, как и о землях Каз Модана.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16288,'Что ты до сих пор тут делаешь, |3-6($c)?$B$BТебе давно пора быть на Сумеречном нагорье и разбираться с этими проклятыми сектантами.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что ты до сих пор тут делаешь, |3-6($c)?$B$BТебе давно пора быть на Сумеречном нагорье и разбираться с этими проклятыми сектантами.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`) VALUES (16293,'Джессуп Маккри из компании Переносчики гор Маккри к вашим услугам.','Если тебе нужно сдвинуть гору, я могу это сделать. И соорудить гору тоже.','Это не самая большая работа, которую мне приходилось делать, даже и не близко. Этот катаклизм – наверное, лучшее, что с нами случилось!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Джессуп Маккри из компании Переносчики гор Маккри к вашим услугам.',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Если тебе нужно сдвинуть гору, я могу это сделать. И соорудить гору тоже.',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Это не самая большая работа, которую мне приходилось делать, даже и не близко. Этот катаклизм – наверное, лучшее, что с нами случилось!',`text2_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16297,'Эй, |3-6($c)!$b$bЕсть у тебя какие-нибудь прибыльные контракты на примете? Я поделюсь с тобой одной десятой комиссионных. Одной десятой процента!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эй, |3-6($c)!$b$bЕсть у тебя какие-нибудь прибыльные контракты на примете? Я поделюсь с тобой одной десятой комиссионных. Одной десятой процента!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16298,'В чем дело, |3-6($c)?$b$bВ доках поговаривают, что ты что-то разнюхиваешь у меня на строительстве…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','В чем дело, |3-6($c)?$b$bВ доках поговаривают, что ты что-то разнюхиваешь у меня на строительстве…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16303,'В этом нападении нет ничего беспорядочного. Элементали и великаны объединились против нас. Похоже, мы прогневали Теразан, саму Мать-Скалу.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','В этом нападении нет ничего беспорядочного. Элементали и великаны объединились против нас. Похоже, мы прогневали Теразан, саму Мать-Скалу.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16304,'Жрица много знает о Зул\'Гурубе.$b$bЖрица полагает, что тебе нужна помощь.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Жрица много знает о Зул\'Гурубе.$b$bЖрица полагает, что тебе нужна помощь.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16305,'Победа над Шестерямстером преподаст отличный урок Термоштепселю. Гномов Гномрегана не остановить!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Победа над Шестерямстером преподаст отличный урок Термоштепселю. Гномов Гномрегана не остановить!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16311,'Ты смелая, раз попробовала сбежать, молодая Оган\'ака.$B$BПрежде чем ты пойдешь своим путем, позволь мне научить тебя, как прогрызать сети троллей.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты смелая, раз попробовала сбежать, молодая Оган\'ака.$B$BПрежде чем ты пойдешь своим путем, позволь мне научить тебя, как прогрызать сети троллей.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16312,'Ты покидаешь логовища ящеров? Меня отправили охранять этот пост и предотвращать побеги, но... Думаю, я понимаю, почему ты хочешь уйти.$B$BТак и быть. Можешь проходить, но сначала выполни мою просьбу.$B$BУ троллей часто бывает при себе еда для ящеров, а меня уже много дней не кормили. В схватке тебе с ними не справиться, но у тебя довольно малый рост, чтобы стащить для меня еды у одного из тех троллей, что спят в палатках...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты покидаешь логовища ящеров? Меня отправили охранять этот пост и предотвращать побеги, но... Думаю, я понимаю, почему ты хочешь уйти.$B$BТак и быть. Можешь проходить, но сначала выполни мою просьбу.$B$BУ троллей часто бывает при себе еда для ящеров, а меня уже много дней не кормили. В схватке тебе с ними не справиться, но у тебя довольно малый рост, чтобы стащить для меня еды у одного из тех троллей, что спят в палатках...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16313,'Твои успехи достойны восхищения, Оган\'ака. Ты весьма способный молодой ящер... Но самое трудное испытание впереди.$B$BТролли патрулируют мосты, и отвлечь их непросто. Если ты кинешь череп у них на пути, может, они споткнутся и упадут…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Твои успехи достойны восхищения, Оган\'ака. Ты весьма способный молодой ящер... Но самое трудное испытание впереди.$B$BТролли патрулируют мосты, и отвлечь их непросто. Если ты кинешь череп у них на пути, может, они споткнутся и упадут…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16320,'$gТром\'ка, друг:Тром\'ка;! Приятно видеть ветерана кампании Нордскола.$b$bВождь просил меня собрать самых опытных бойцов для предстоящего удара по Сумеречному нагорью.$b$b<Полководец Крогг окидывает вас взглядом.>$b$bТвоя помощь может нам пригодиться. Поговори с Вождем в Оргриммаре, узнай, есть ли у него для тебя задания.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','$gТром\'ка, друг:Тром\'ка;! Приятно видеть ветерана кампании Нордскола.$b$bВождь просил меня собрать самых опытных бойцов для предстоящего удара по Сумеречному нагорью.$b$b<Полководец Крогг окидывает вас взглядом.>$b$bТвоя помощь может нам пригодиться. Поговори с Вождем в Оргриммаре, узнай, есть ли у него для тебя задания.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16321,'В таком городе, как этот, солдат может огрести много неприятностей.$b$bОчень много неприятностей.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','В таком городе, как этот, солдат может огрести много неприятностей.$b$bОчень много неприятностей.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16322,'Спасибо.$B$BВ благодарность я подскажу тебе, как отвлечь вон тех троллей.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Спасибо.$B$BВ благодарность я подскажу тебе, как отвлечь вон тех троллей.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16324,'Ты хочешь сбежать? Пожалуйста. Но сначала запомни вот что.$B$BДержись подальше от троллей. Они тебя не убьют, но схватят и приволокут обратно.$B$BРазговаривай с любым встречным ящером. Они не только научат тебя новым способностям, но и помогут закрепить успехи и вообще облегчат путь из Зул\'Гуруба.$B$BУ тебя уже есть способность "Порыв" – с ее помощью выходи из опасных положений.$B$BА... И держись подальше от воды.$B$BУдачи!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты хочешь сбежать? Пожалуйста. Но сначала запомни вот что.$B$BДержись подальше от троллей. Они тебя не убьют, но схватят и приволокут обратно.$B$BРазговаривай с любым встречным ящером. Они не только научат тебя новым способностям, но и помогут закрепить успехи и вообще облегчат путь из Зул\'Гуруба.$B$BУ тебя уже есть способность "Порыв" – с ее помощью выходи из опасных положений.$B$BА... И держись подальше от воды.$B$BУдачи!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16330,'Что тебе надо?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что тебе надо?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16334,'Добро пожаловать в Гром\'гол, |3-6($c). Пока мы не испортили отношения, хочу тебе сообщить, что не потерплю лентяев в своем лагере. Полагаю, что $gтакой сильный и здоровый:такая сильная и здоровая:r; |3-6($r), как ты, не будет сидеть без дела.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать в Гром\'гол, |3-6($c). Пока мы не испортили отношения, хочу тебе сообщить, что не потерплю лентяев в своем лагере. Полагаю, что $gтакой сильный и здоровый:такая сильная и здоровая:r; |3-6($r), как ты, не будет сидеть без дела.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16335,'Знай, что даже в этом далеком углу мира Адский Крик видит тебя.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Знай, что даже в этом далеком углу мира Адский Крик видит тебя.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16336,'Тролли Тернистой долины недолюбливают Черное Копье. Я не боюсь ни Кровавых Скальпов, ни Дробителей Черепов, и все же... За высокими стенами Гром\'гола я чувствую себя в безопасности.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тролли Тернистой долины недолюбливают Черное Копье. Я не боюсь ни Кровавых Скальпов, ни Дробителей Черепов, и все же... За высокими стенами Гром\'гола я чувствую себя в безопасности.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16337,'Может быть, для меня в Гром\'голе и не так безопасно, как я думал.$B$BТролль должен всегда быть начеку. И везде.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Может быть, для меня в Гром\'голе и не так безопасно, как я думал.$B$BТролль должен всегда быть начеку. И везде.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16338,'<В котле побулькивает варево.>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<В котле побулькивает варево.>',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16339,'<Тролль тихо напевает и смотрит в котел. Похоже, он ранен.>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Тролль тихо напевает и смотрит в котел. Похоже, он ранен.>',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16340,'В джунглях много денег, |3-6($r). Понимаешь?$B$BНет, это не золото и не медь, а шкуры ящеров, минеральные жилы и старинные артефакты троллей.$B$BЛадно, может, среди минеральных жил и попадаются золотые и медные.$B$BНо общую идею ты просекаешь, да?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','В джунглях много денег, |3-6($r). Понимаешь?$B$BНет, это не золото и не медь, а шкуры ящеров, минеральные жилы и старинные артефакты троллей.$B$BЛадно, может, среди минеральных жил и попадаются золотые и медные.$B$BНо общую идею ты просекаешь, да?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16341,'Великий Растахан шлет тебе свой поклон, член Орды.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Великий Растахан шлет тебе свой поклон, член Орды.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`,`text3_0_loc8`) VALUES (16344,'Тебе приходилось бывать в настоящих джунглях, |3-6($r)?$b$bЭто непередаваемые ощущения.','Тернистая долина, дружище. Там прекрасно!','Привет!','Как бы я хотел вернуться туда. Ревущие ящеры, враждующие друг с другом тролли и другие твари из джунглей – куда ни глянь. И все они только и ждут, когда ты их убьешь...$b$b<Борт вздыхает.>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тебе приходилось бывать в настоящих джунглях, |3-6($r)?$b$bЭто непередаваемые ощущения.',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Тернистая долина, дружище. Там прекрасно!',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Привет!',`text2_0_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Как бы я хотел вернуться туда. Ревущие ящеры, враждующие друг с другом тролли и другие твари из джунглей – куда ни глянь. И все они только и ждут, когда ты их убьешь...$b$b<Борт вздыхает.>',`text3_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16345,'Не думаю, что у тебя есть еще отряд в запасе, не так ли? У нас тут хлопот полон рот.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не думаю, что у тебя есть еще отряд в запасе, не так ли? У нас тут хлопот полон рот.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16348,'Сумеречный Молот серьезно досаждает нам.$b$bМы бы сделали что угодно, чтобы выдворить их из нашего дома.$b$bНо наши силы разделены и поэтому нам не справиться.$b$bТак что я наблюдаю…$b$bИ жду…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Сумеречный Молот серьезно досаждает нам.$b$bМы бы сделали что угодно, чтобы выдворить их из нашего дома.$b$bНо наши силы разделены и поэтому нам не справиться.$b$bТак что я наблюдаю…$b$bИ жду…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16362,'Готовьтесь к войне! Мы больше не станем терпеть племя Порочной Ветви!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Готовьтесь к войне! Мы больше не станем терпеть племя Порочной Ветви!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16363,'Мы должны положить конец этой порче, проникшей в Ясеневый лес.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы должны положить конец этой порче, проникшей в Ясеневый лес.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16364,'Не хочешь подраться, $gпарень:подруга;?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Не хочешь подраться, $gпарень:подруга;?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16365,'Подземье было тихим, спокойным местом. Жизнь в нем текла размеренно. Никто никуда не бежал. В те времена я старался стать единым целым с землей и в большой степени мне это удавалось.$b$bПотом появился раненый хранитель Земли. Поначалу он не влиял на баланс. Мы знали о нем, он бывал здесь и раньше. Разлом появился только тогда, когда к нему присоединились сектанты Сумеречного Молота.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Подземье было тихим, спокойным местом. Жизнь в нем текла размеренно. Никто никуда не бежал. В те времена я старался стать единым целым с землей и в большой степени мне это удавалось.$b$bПотом появился раненый хранитель Земли. Поначалу он не влиял на баланс. Мы знали о нем, он бывал здесь и раньше. Разлом появился только тогда, когда к нему присоединились сектанты Сумеречного Молота.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16366,'Когда хранитель Земли стал поправляться, он заболел царившим тут покоем. Миром. Это было незадолго до того, как он натравил на нас каменных драконов.$b$bБез Смертокрыла у них нет цели. Мы можем показать им свою силу. Сделай так, чтобы они вернулись к Матери-Скале.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Когда хранитель Земли стал поправляться, он заболел царившим тут покоем. Миром. Это было незадолго до того, как он натравил на нас каменных драконов.$b$bБез Смертокрыла у них нет цели. Мы можем показать им свою силу. Сделай так, чтобы они вернулись к Матери-Скале.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16373,'Как они посмели взять в плен нашего короля!$b$bМы отобьем Каменный очаг и затем двинемся на передовую, чтобы сокрушить каменных троггов в их собственном доме!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Как они посмели взять в плен нашего короля!$b$bМы отобьем Каменный очаг и затем двинемся на передовую, чтобы сокрушить каменных троггов в их собственном доме!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16374,'Давай заставим этих каменных троггов вернуться обратно под землю, |3-6($r)!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Давай заставим этих каменных троггов вернуться обратно под землю, |3-6($r)!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16376,'<Глин рычит и усмехается.>$b$bНу и молодежь пошла.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Глин рычит и усмехается.>$b$bНу и молодежь пошла.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16378,'Когда ритуал закончится, появится Марнал, и мои люди помогут разделать это нелепое существо.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Когда ритуал закончится, появится Марнал, и мои люди помогут разделать это нелепое существо.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16383,'Когда Смертокрыл проник в наш мир, между ним и Подземьем образовался разлом.$b$bВосстановление столпа мира – это единственный способ стабилизировать разлом.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Когда Смертокрыл проник в наш мир, между ним и Подземьем образовался разлом.$b$bВосстановление столпа мира – это единственный способ стабилизировать разлом.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (16386,'Куда, $gприятель:подружка;?','Куда, $gприятель:подружка;?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Куда, $gприятель:подружка;?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Куда, $gприятель:подружка;?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16387,'Мы, клан Драконьей Пасти, столько страдали... мы потерпели поражение под Грим Батолом... столько великих воинов погибло в Запределье... а теперь еще и в боях с войсками Сумеречного Молота.$B$BПорой я уже не верю в то, что мой клан снова станет великим. Но такие юноши и девушки, как Зела, дарят надежду этому старому мешку с костями.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы, клан Драконьей Пасти, столько страдали... мы потерпели поражение под Грим Батолом... столько великих воинов погибло в Запределье... а теперь еще и в боях с войсками Сумеречного Молота.$B$BПорой я уже не верю в то, что мой клан снова станет великим. Но такие юноши и девушки, как Зела, дарят надежду этому старому мешку с костями.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16388,'Что тебе нужно? Я вообще не должен с тобой разговаривать...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что тебе нужно? Я вообще не должен с тобой разговаривать...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16390,'Осточертело уже сидеть в этой дыре. Надеюсь, что та бумажная крыса, которая задерживает возвращение Даната, получит по заслугам.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Осточертело уже сидеть в этой дыре. Надеюсь, что та бумажная крыса, которая задерживает возвращение Даната, получит по заслугам.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16391,'Эй, я как смотрюсь в этой красной рубашке? Как пушечное мясо?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эй, я как смотрюсь в этой красной рубашке? Как пушечное мясо?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16393,'Добро пожаловать в Заоблачный пик, обитель клана Громового Молота.$B$BВерховный тан Фалстад отбыл в Стальгорн, поэтому ты будешь иметь дело со мной.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать в Заоблачный пик, обитель клана Громового Молота.$B$BВерховный тан Фалстад отбыл в Стальгорн, поэтому ты будешь иметь дело со мной.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16394,'Духи этой земли больше не станут терпеть эту темную магию и жестокие жертвоприношения.$B$BПлемя Порочной Ветви должно уйти!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Духи этой земли больше не станут терпеть эту темную магию и жестокие жертвоприношения.$B$BПлемя Порочной Ветви должно уйти!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16399,'Не будем зря терять время! Нежить уже начала действовать.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не будем зря терять время! Нежить уже начала действовать.',`text0_0_loc8`);
