INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16402,'Ты $gготов:готова; на все, чтобы спасти свое королевство?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты $gготов:готова; на все, чтобы спасти свое королевство?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16412,'Так много бессмысленных потерь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Так много бессмысленных потерь.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16413,'Рыбалка всегда была основным занятием моей семьи. А вот тебе, похоже, не помешает ею заняться. Выполнишь пару поручений рыболова-профи?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Рыбалка всегда была основным занятием моей семьи. А вот тебе, похоже, не помешает ею заняться. Выполнишь пару поручений рыболова-профи?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16418,'Это вам, а это нам. Все поделим пополам.$B$BСсориться не стоит нам – а иначе... В МОРДУ ДАМ! Это снова нам...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Это вам, а это нам. Все поделим пополам.$B$BСсориться не стоит нам – а иначе... В МОРДУ ДАМ! Это снова нам...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16420,'Это, наверное, та шлюпка, о которой говорил капитан Гекельбери Смоттс.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Это, наверное, та шлюпка, о которой говорил капитан Гекельбери Смоттс.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16422,'Мы пришли, чтобы помочь, но, похоже, хоть их благосклонность по отношению к тебе не распространяется на нас.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы пришли, чтобы помочь, но, похоже, хоть их благосклонность по отношению к тебе не распространяется на нас.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`,`text2_0_loc8`,`text2_1_loc8`,`text3_0_loc8`,`text3_1_loc8`,`text4_0_loc8`,`text4_1_loc8`,`text5_0_loc8`,`text5_1_loc8`) VALUES (16425,'Мне нельзя иметь с тобой дело, |3-6($c). Приказ вождя.','Мне нельзя иметь с тобой дело, |3-6($c). Приказ вождя.','У меня нет ничего, что было бы разрешено тебе продать.','У меня нет ничего, что было бы разрешено тебе продать.','Исчезни, |3-6($c)! Не хочу, чтобы видели, что я с тобой общаюсь...','Исчезни, |3-6($c)! Не хочу, чтобы видели, что я с тобой общаюсь...','Уходи, я не желаю, чтобы вождь узнал, что я разговариваю с кем-то из Орды.','Уходи, я не желаю, чтобы вождь узнал, что я разговариваю с кем-то из Орды.','Вам, ордынцам, я ничего не продам. Что, не нравится? Так пойди и обсуди это с вождем!','Вам, ордынцам, я ничего не продам. Что, не нравится? Так пойди и обсуди это с вождем!','Полководец Мор\'гор запретил нам иметь дела с Ордой.$B$B<Торговец злобно сплевывает на землю, но больше говорить на эту тему не желает.>','Полководец Мор\'гор запретил нам иметь дела с Ордой.$B$B<Торговец злобно сплевывает на землю, но больше говорить на эту тему не желает.>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мне нельзя иметь с тобой дело, |3-6($c). Приказ вождя.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мне нельзя иметь с тобой дело, |3-6($c). Приказ вождя.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','У меня нет ничего, что было бы разрешено тебе продать.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','У меня нет ничего, что было бы разрешено тебе продать.',`text1_1_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Исчезни, |3-6($c)! Не хочу, чтобы видели, что я с тобой общаюсь...',`text2_0_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Исчезни, |3-6($c)! Не хочу, чтобы видели, что я с тобой общаюсь...',`text2_1_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Уходи, я не желаю, чтобы вождь узнал, что я разговариваю с кем-то из Орды.',`text3_0_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','Уходи, я не желаю, чтобы вождь узнал, что я разговариваю с кем-то из Орды.',`text3_1_loc8`), `text4_0_loc8`=IF(`text4_0_loc8` IS NULL OR `text4_0_loc8`='','Вам, ордынцам, я ничего не продам. Что, не нравится? Так пойди и обсуди это с вождем!',`text4_0_loc8`), `text4_1_loc8`=IF(`text4_1_loc8` IS NULL OR `text4_1_loc8`='','Вам, ордынцам, я ничего не продам. Что, не нравится? Так пойди и обсуди это с вождем!',`text4_1_loc8`), `text5_0_loc8`=IF(`text5_0_loc8` IS NULL OR `text5_0_loc8`='','Полководец Мор\'гор запретил нам иметь дела с Ордой.$B$B<Торговец злобно сплевывает на землю, но больше говорить на эту тему не желает.>',`text5_0_loc8`), `text5_1_loc8`=IF(`text5_1_loc8` IS NULL OR `text5_1_loc8`='','Полководец Мор\'гор запретил нам иметь дела с Ордой.$B$B<Торговец злобно сплевывает на землю, но больше говорить на эту тему не желает.>',`text5_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16426,'Ничем не могу помочь, |3-6($c). Полководец Мор\'гор меня убьет, если я позволю кому-то из Орды оседлать одного из наших ветрокрылов.$B$BКогда-нибудь... он получит все, что ему причитается...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ничем не могу помочь, |3-6($c). Полководец Мор\'гор меня убьет, если я позволю кому-то из Орды оседлать одного из наших ветрокрылов.$B$BКогда-нибудь... он получит все, что ему причитается...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16427,'Не такое уж плохое место, если только ты не питаешь привязанности к солнечному свету.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не такое уж плохое место, если только ты не питаешь привязанности к солнечному свету.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16429,'Гориллы – удивительные создания. Лучше ночных эльфов, которые делают глупости, например... проигрывают все деньги и попадают в список врагов "Морского волка" Маккинли.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Гориллы – удивительные создания. Лучше ночных эльфов, которые делают глупости, например... проигрывают все деньги и попадают в список врагов "Морского волка" Маккинли.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`,`text3_0_loc8`,`text4_0_loc8`,`text5_0_loc8`) VALUES (16430,'Давай же, |3-6($r). Придумай оправдание.','Парадом тут командует полководец Мор\'гор. Помни об этом.','<Глаза головореза вспыхивают красным огнем.>$B$BОчень надеюсь, ваши жалкие ордынские вояки нападут на нас. Просто руки чешутся пустить им кровь, |3-6($c)!','Ярость! Мощь! Никогда в жизни я не чувствовал себя сильнее.$B$BСкоро ВСЕ в Драконьей Пасти почувствуют себя так же!','Даже не пытайся что-то выкинуть, |3-6($c).$B$B<Головорез сжимает рукоять своего клинка, подобравшись в ожидании, что вы что-нибудь сделаете.>','Полководец Мор\'гор вернет величие клану Драконьей Пасти!$B$BНам эта ваша жалкая Орда ни к чему!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Давай же, |3-6($r). Придумай оправдание.',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Парадом тут командует полководец Мор\'гор. Помни об этом.',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','<Глаза головореза вспыхивают красным огнем.>$B$BОчень надеюсь, ваши жалкие ордынские вояки нападут на нас. Просто руки чешутся пустить им кровь, |3-6($c)!',`text2_0_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Ярость! Мощь! Никогда в жизни я не чувствовал себя сильнее.$B$BСкоро ВСЕ в Драконьей Пасти почувствуют себя так же!',`text3_0_loc8`), `text4_0_loc8`=IF(`text4_0_loc8` IS NULL OR `text4_0_loc8`='','Даже не пытайся что-то выкинуть, |3-6($c).$B$B<Головорез сжимает рукоять своего клинка, подобравшись в ожидании, что вы что-нибудь сделаете.>',`text4_0_loc8`), `text5_0_loc8`=IF(`text5_0_loc8` IS NULL OR `text5_0_loc8`='','Полководец Мор\'гор вернет величие клану Драконьей Пасти!$B$BНам эта ваша жалкая Орда ни к чему!',`text5_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16433,'За появлением в Багровом зале буйной растительности стоят каменные трогги.$b$bЯ чувствую в этом месте странную силу… будь осторожнее.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','За появлением в Багровом зале буйной растительности стоят каменные трогги.$b$bЯ чувствую в этом месте странную силу… будь осторожнее.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
