INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16437,'<Бодунья пытается сообразить, как спуститься вниз по лестнице.>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Бодунья пытается сообразить, как спуститься вниз по лестнице.>',`text0_0_loc8`);
