INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16438,'<Бодунья смотрит на вас большими блестящими черными глазами.>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Бодунья смотрит на вас большими блестящими черными глазами.>',`text0_0_loc8`);
