INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16442,'Выглядит неплохо, но будет еще лучше, если мы ее еще немного подпортим. Чтобы создать видимость последствий сражения. Как считаешь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Выглядит неплохо, но будет еще лучше, если мы ее еще немного подпортим. Чтобы создать видимость последствий сражения. Как считаешь?',`text0_0_loc8`);
