INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16443,'Мои братья сильны, но инертны.$b$bА без движения, борьбы и жестокости ничего не изменится. Сознательно или нет, но наши враги живут по этим правилам. А пассивность моих братьев делает их слабыми и уязвимыми.$b$bНо только не меня. Меня не страшит новое. Я упрусь в землю и сдвину горы. Я воспользуюсь переменами.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мои братья сильны, но инертны.$b$bА без движения, борьбы и жестокости ничего не изменится. Сознательно или нет, но наши враги живут по этим правилам. А пассивность моих братьев делает их слабыми и уязвимыми.$b$bНо только не меня. Меня не страшит новое. Я упрусь в землю и сдвину горы. Я воспользуюсь переменами.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16451,'Ты здесь, чтобы помочь оркам Драконьей Пасти вернуть свою свободу?$B$BПоговори с Зелой – она координатор нашего движения сопротивления!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты здесь, чтобы помочь оркам Драконьей Пасти вернуть свою свободу?$B$BПоговори с Зелой – она координатор нашего движения сопротивления!',`text0_0_loc8`);
