INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16455,'Да, чего тебе надо?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да, чего тебе надо?',`text0_0_loc8`);
