INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16457,'Бочонок грога. Пираты обожают этот напиток.$B$BПробка неплотно сидит в отверстии.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Бочонок грога. Пираты обожают этот напиток.$B$BПробка неплотно сидит в отверстии.',`text0_0_loc8`);
