INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16458,'В бочонке дыра, из которой вытекает грог. Пираты расстроятся...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','В бочонке дыра, из которой вытекает грог. Пираты расстроятся...',`text0_0_loc8`);
