INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16460,'Бочонок пороха. Рядом с ним стоит кувшин с водой.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Бочонок пороха. Рядом с ним стоит кувшин с водой.',`text0_0_loc8`);
