INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16461,'Порох совсем промок. Теперь им не скоро зарядишь пушки.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Порох совсем промок. Теперь им не скоро зарядишь пушки.',`text0_0_loc8`);
