INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16463,'Большущий ящик, до краев наполненный пушечными ядрами. Рядом с ним пристроилась банка с кулинарным жиром.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Большущий ящик, до краев наполненный пушечными ядрами. Рядом с ним пристроилась банка с кулинарным жиром.',`text0_0_loc8`);
