INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16464,'Все тяжелые металлические снаряды смазаны жиром. Теперь команде Фираллона будет непросто их засовывать в пушку.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Все тяжелые металлические снаряды смазаны жиром. Теперь команде Фираллона будет непросто их засовывать в пушку.',`text0_0_loc8`);
