INSERT INTO `locales_npc_text` (`id`,`text1_0_loc8`,`text2_0_loc8`,`text3_0_loc8`,`text4_0_loc8`,`text5_0_loc8`) VALUES (16465,'Отставить!','Ба!','Арр-р!','Ну и ну!','Дорогу!') ON DUPLICATE KEY UPDATE `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Отставить!',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Ба!',`text2_0_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Арр-р!',`text3_0_loc8`), `text4_0_loc8`=IF(`text4_0_loc8` IS NULL OR `text4_0_loc8`='','Ну и ну!',`text4_0_loc8`), `text5_0_loc8`=IF(`text5_0_loc8` IS NULL OR `text5_0_loc8`='','Дорогу!',`text5_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16469,'В этих планах содержатся подробности предстоящего нападения!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','В этих планах содержатся подробности предстоящего нападения!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`,`text3_0_loc8`,`text4_0_loc8`,`text5_0_loc8`) VALUES (16470,'Пришел час расплаты, |3-6($c)!','Ты хочешь помочь свергнуть Мор\'гора?','Зела сказала, что Орда придет на помощь! Что от меня требуется?','Не надо мне никаких доспехов. Дай оружие и скажи, кого нужно убить.','Орда пришла! Очень вовремя здесь появились настоящие лидеры!','Я буду сражаться плечом к плечу, |3-6($c). Ты не пожалеешь, что $gпомог:помогла; нам!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Пришел час расплаты, |3-6($c)!',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Ты хочешь помочь свергнуть Мор\'гора?',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Зела сказала, что Орда придет на помощь! Что от меня требуется?',`text2_0_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Не надо мне никаких доспехов. Дай оружие и скажи, кого нужно убить.',`text3_0_loc8`), `text4_0_loc8`=IF(`text4_0_loc8` IS NULL OR `text4_0_loc8`='','Орда пришла! Очень вовремя здесь появились настоящие лидеры!',`text4_0_loc8`), `text5_0_loc8`=IF(`text5_0_loc8` IS NULL OR `text5_0_loc8`='','Я буду сражаться плечом к плечу, |3-6($c). Ты не пожалеешь, что $gпомог:помогла; нам!',`text5_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`,`text2_0_loc8`,`text2_1_loc8`,`text3_0_loc8`,`text3_1_loc8`,`text4_0_loc8`,`text4_1_loc8`,`text5_0_loc8`,`text5_1_loc8`) VALUES (16471,'Кажется, неудачный я выбрал денек для прекращения истребления гнусных орков.','Кажется, неудачный я выбрала денек для прекращения истребления гнусных орков.','Настал день расплаты, |3-6($c)!','Настал день расплаты, |3-6($c)!','Запишите меня, командир! Я готов сражаться!','Запишите меня, командир! Я готова сражаться!','Сегодня тирании Мор\'гора придет конец.','Сегодня тирании Мор\'гора придет конец.','Началось, |3-6($c)! Революция началась!','Началось, |3-6($c)! Революция началась!','$C! Зела сказала, Орда даст нам оружие. Что у тебя есть?','$C! Зела сказала, Орда даст нам оружие. Что у тебя есть?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Кажется, неудачный я выбрал денек для прекращения истребления гнусных орков.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Кажется, неудачный я выбрала денек для прекращения истребления гнусных орков.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Настал день расплаты, |3-6($c)!',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Настал день расплаты, |3-6($c)!',`text1_1_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Запишите меня, командир! Я готов сражаться!',`text2_0_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Запишите меня, командир! Я готова сражаться!',`text2_1_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Сегодня тирании Мор\'гора придет конец.',`text3_0_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','Сегодня тирании Мор\'гора придет конец.',`text3_1_loc8`), `text4_0_loc8`=IF(`text4_0_loc8` IS NULL OR `text4_0_loc8`='','Началось, |3-6($c)! Революция началась!',`text4_0_loc8`), `text4_1_loc8`=IF(`text4_1_loc8` IS NULL OR `text4_1_loc8`='','Началось, |3-6($c)! Революция началась!',`text4_1_loc8`), `text5_0_loc8`=IF(`text5_0_loc8` IS NULL OR `text5_0_loc8`='','$C! Зела сказала, Орда даст нам оружие. Что у тебя есть?',`text5_0_loc8`), `text5_1_loc8`=IF(`text5_1_loc8` IS NULL OR `text5_1_loc8`='','$C! Зела сказала, Орда даст нам оружие. Что у тебя есть?',`text5_1_loc8`);
