INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16544,'Где бы ни прятались сектанты Сумеречного Молота, мы победим их. Даже в обители стихий они не будут в безопасности.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Где бы ни прятались сектанты Сумеречного Молота, мы победим их. Даже в обители стихий они не будут в безопасности.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16545,'Когда Смертокрыл разбил столп мира, между нашими мирами образовался разлом. Споры и грибы – одно из последствий.$b$bПосмотрим, сможем ли мы с ними справиться.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Когда Смертокрыл разбил столп мира, между нашими мирами образовался разлом. Споры и грибы – одно из последствий.$b$bПосмотрим, сможем ли мы с ними справиться.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16547,'Здравствуй, |3-6($c). Хочешь что-то приобрести?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Здравствуй, |3-6($c). Хочешь что-то приобрести?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16548,'Все приверженцы Гурубаши и Хаккара мертвы. Множество моих собратьев из племени Зандалар вернулись на свою родину.$b$bОтныне мне, Шабалу, и представителям племени Черного Копья в Бамбале предстоит охранять Зул\'Гуруб.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Все приверженцы Гурубаши и Хаккара мертвы. Множество моих собратьев из племени Зандалар вернулись на свою родину.$b$bОтныне мне, Шабалу, и представителям племени Черного Копья в Бамбале предстоит охранять Зул\'Гуруб.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16549,'Этот древний тотем имеет форму летучей мыши. Должно быть, о нем рассказывала Мейвики.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Этот древний тотем имеет форму летучей мыши. Должно быть, о нем рассказывала Мейвики.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16552,'Принц убежал. Это плохо!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Принц убежал. Это плохо!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16553,'Заг-заг.$B$BЧто? Проваливай.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Заг-заг.$B$BЧто? Проваливай.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16555,'Почему ты меня спрашиваешь? Я не знаю ничего о Сумеречном Молоте.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Почему ты меня спрашиваешь? Я не знаю ничего о Сумеречном Молоте.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16556,'<Батрак потеет и дрожит.>$B$BЯ был ... Ну как это... Ох, черт!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Батрак потеет и дрожит.>$B$BЯ был ... Ну как это... Ох, черт!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16557,'<Батрак приходит в ужас.>$B$BНет! Вы выяснили, что новым лидером культа в Оргриммаре стал Сауранок? Он говорил мне, что его тайна никому не известна!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Батрак приходит в ужас.>$B$BНет! Вы выяснили, что новым лидером культа в Оргриммаре стал Сауранок? Он говорил мне, что его тайна никому не известна!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`) VALUES (16558,'Заг-заг!','Оргриммар стал еще сильнее!','Чем я могу помочь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Заг-заг!',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Оргриммар стал еще сильнее!',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Чем я могу помочь?',`text2_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16559,'Привет, |3-6($c)!$B$BОргриммарские воздушные пути – ваша надежная связь со всем миром. Дирижабли северной башни доставят вас в Тернистую долину или Подгород. От южной башни вы сможете отправиться в Громовой утес или даже Нордскол.$B$BУкротитель ветрокрылов Дорас поможет вам добраться в любое место Калимдора... ну в любое из вам известных.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Привет, |3-6($c)!$B$BОргриммарские воздушные пути – ваша надежная связь со всем миром. Дирижабли северной башни доставят вас в Тернистую долину или Подгород. От южной башни вы сможете отправиться в Громовой утес или даже Нордскол.$B$BУкротитель ветрокрылов Дорас поможет вам добраться в любое место Калимдора... ну в любое из вам известных.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`,`text3_0_loc8`,`text4_0_loc8`,`text5_0_loc8`,`text6_0_loc8`) VALUES (16560,'Сектанты? Не знаю. Но какие-то подозрительные личности ошиваются возле южной башни дирижаблей.','Я ничего не знаю, спросите кого-нибудь еще.','Тайный культ? Это те, что устаивают сборища возле южной башни дирижаблей?','Тайный культ? Вы же не из тех подозрительных орков, которые крутятся вокруг южной башни дирижаблей?','Я слишком туп, меня в сектанты не принимают. В детстве мама уронила меня с дирижабля. Я попал под пропеллер. Приземлился головой о камень. Мне скрепили кости головы стальной миской, чтобы она не развалилась.$B$B<Он стучит кулаком по черепу.>$B$BМолния доделала дело.','Я постоянно слышу, как эти странные орки шепчутся у южной башни дирижаблей. Но стоит мне подойти, и они замолкают.','Я не знаю.$B$BНе бей меня!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Сектанты? Не знаю. Но какие-то подозрительные личности ошиваются возле южной башни дирижаблей.',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Я ничего не знаю, спросите кого-нибудь еще.',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Тайный культ? Это те, что устаивают сборища возле южной башни дирижаблей?',`text2_0_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Тайный культ? Вы же не из тех подозрительных орков, которые крутятся вокруг южной башни дирижаблей?',`text3_0_loc8`), `text4_0_loc8`=IF(`text4_0_loc8` IS NULL OR `text4_0_loc8`='','Я слишком туп, меня в сектанты не принимают. В детстве мама уронила меня с дирижабля. Я попал под пропеллер. Приземлился головой о камень. Мне скрепили кости головы стальной миской, чтобы она не развалилась.$B$B<Он стучит кулаком по черепу.>$B$BМолния доделала дело.',`text4_0_loc8`), `text5_0_loc8`=IF(`text5_0_loc8` IS NULL OR `text5_0_loc8`='','Я постоянно слышу, как эти странные орки шепчутся у южной башни дирижаблей. Но стоит мне подойти, и они замолкают.',`text5_0_loc8`), `text6_0_loc8`=IF(`text6_0_loc8` IS NULL OR `text6_0_loc8`='','Я не знаю.$B$BНе бей меня!',`text6_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16562,'Прости, но я не могу обучать тебя.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Прости, но я не могу обучать тебя.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16563,'Выбрав путь мага, ты ступаешь на долгую и трудную дорогу. Многие этого не понимают. Нас нелегко принимает наш собственный народ.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Выбрав путь мага, ты ступаешь на долгую и трудную дорогу. Многие этого не понимают. Нас нелегко принимает наш собственный народ.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16564,'Ты здесь, чтобы помочь Стальгорну, или чтобы весь день таращить на меня глаза?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты здесь, чтобы помочь Стальгорну, или чтобы весь день таращить на меня глаза?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16565,'Гнусные гномы-горлодеры! Ну и вид у тебя. Я боялся, что огромный червь магмы отпугнет посетителей. Но раз уж ты здесь, можешь помочь мне.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Гнусные гномы-горлодеры! Ну и вид у тебя. Я боялся, что огромный червь магмы отпугнет посетителей. Но раз уж ты здесь, можешь помочь мне.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (16569,'Я не могу обучать тебя. Поищи наставника для |3-8($c).','Я не могу обучать тебя. Поищи наставника для |3-8($c).') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я не могу обучать тебя. Поищи наставника для |3-8($c).',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я не могу обучать тебя. Поищи наставника для |3-8($c).',`text0_1_loc8`);
