INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (16570,'Ты хочешь учиться, $gохотник:охотница;?','Ты хочешь учиться, $gохотник:охотница;?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты хочешь учиться, $gохотник:охотница;?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты хочешь учиться, $gохотник:охотница;?',`text0_1_loc8`);
