INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16580,'Зорам\'гар станет новым бастионом на пути наших врагов.$B$BВо славу Орды!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Зорам\'гар станет новым бастионом на пути наших врагов.$B$BВо славу Орды!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16585,'Друиды и часовые предпочитают работать по отдельности, но мы всегда хорошо ладили.$b$bАвтономность и антипатия – это разные вещи.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Друиды и часовые предпочитают работать по отдельности, но мы всегда хорошо ладили.$b$bАвтономность и антипатия – это разные вещи.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16587,'Местные свинобразы слишком опасны, чтобы забывать о них из-за внешней угрозы, |3-6($r). Мой тотем не сможет вечно сдерживать их.$B$BНужно положить конец их преступлениям против природы.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Местные свинобразы слишком опасны, чтобы забывать о них из-за внешней угрозы, |3-6($r). Мой тотем не сможет вечно сдерживать их.$B$BНужно положить конец их преступлениям против природы.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16590,'Прочь. У меня нет ни возможностей, ни склонностей учить тебя.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Прочь. У меня нет ни возможностей, ни склонностей учить тебя.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16592,'Они все прибывают! Не дайте им прорваться! Мы должны спасти как можно больше жителей!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Они все прибывают! Не дайте им прорваться! Мы должны спасти как можно больше жителей!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16593,'Что? Конечно, нет! Я мог бы с легкостью выбраться из этой простой ловушки, но просто слишком занят. Видишь ли, недавно я провел несколько месяцев в брюхе зверя...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что? Конечно, нет! Я мог бы с легкостью выбраться из этой простой ловушки, но просто слишком занят. Видишь ли, недавно я провел несколько месяцев в брюхе зверя...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16594,'Если честно, это произошло не совсем по моей воле, но там мне удалось сделать поистине невероятное открытие. Оказывается, этот зверь мог переварить практически все что угодно без всякого вреда для себя.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если честно, это произошло не совсем по моей воле, но там мне удалось сделать поистине невероятное открытие. Оказывается, этот зверь мог переварить практически все что угодно без всякого вреда для себя.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16597,'Ой! Этот рычаг активирует желчетрон. Да, кстати, если ты случайно найдешь ключ...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ой! Этот рычаг активирует желчетрон. Да, кстати, если ты случайно найдешь ключ...',`text0_0_loc8`);
