INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16613,'Наги просто так не сдадутся. Нужно найти наших друзей и отправиться к врагу.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Наги просто так не сдадутся. Нужно найти наших друзей и отправиться к врагу.',`text0_0_loc8`);
