INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16614,'Я пойду внутрь за Эрунаком, даже если мне придется сделать это в одиночку.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я пойду внутрь за Эрунаком, даже если мне придется сделать это в одиночку.',`text0_0_loc8`);
