INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16615,'Сомнамбулер – величайшая фигура современной археологии. Какие только истории не происходили с ним за всю его сорокалетнюю карьеру... жаль, что теперь он не помнит ни одной.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Сомнамбулер – величайшая фигура современной археологии. Какие только истории не происходили с ним за всю его сорокалетнюю карьеру... жаль, что теперь он не помнит ни одной.',`text0_0_loc8`);
