INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16616,'Мне следует пойти за ним.$b$bЧто может быть хуже встречи с Адским Криком после подобных событий…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мне следует пойти за ним.$b$bЧто может быть хуже встречи с Адским Криком после подобных событий…',`text0_0_loc8`);
