INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (16617,'Также наставники охотников находятся в Ставке командования Старого города и в Квартале дворфов.','Также наставники охотников находятся в Ставке командования Старого города и в Квартале дворфов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Также наставники охотников находятся в Ставке командования Старого города и в Квартале дворфов.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Также наставники охотников находятся в Ставке командования Старого города и в Квартале дворфов.',`text0_1_loc8`);
