INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (16618,'Приют охотников расположен у восточных ворот Старого города.','Приют охотников расположен у восточных ворот Старого города.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приют охотников расположен у восточных ворот Старого города.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Приют охотников расположен у восточных ворот Старого города.',`text0_1_loc8`);
