INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (16619,'Парк?$B$BЕго больше нет. Тебе никто не говорил? Великий дракон Смертокрыл разрушил его, когда пролетал над Штормградом.$B$BНе знаю, как он тут вообще все с землей не сровнял, но слава Свету этого не произошло!','Парк?$B$BЕго больше нет. Тебе никто не говорил? Великий дракон Смертокрыл разрушил его, когда пролетал над Штормградом.$B$BНе знаю, как он тут вообще все с землей не сровнял, но слава Свету этого не произошло!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Парк?$B$BЕго больше нет. Тебе никто не говорил? Великий дракон Смертокрыл разрушил его, когда пролетал над Штормградом.$B$BНе знаю, как он тут вообще все с землей не сровнял, но слава Свету этого не произошло!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Парк?$B$BЕго больше нет. Тебе никто не говорил? Великий дракон Смертокрыл разрушил его, когда пролетал над Штормградом.$B$BНе знаю, как он тут вообще все с землей не сровнял, но слава Свету этого не произошло!',`text0_1_loc8`);
