INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (16620,'Цитадель расположена на севере.$B$BСледуй по каналам на север, пересеки разводной мост, и ты окажешься во дворе цитадели.','Цитадель расположена на севере.$B$BСледуй по каналам на север, пересеки разводной мост, и ты окажешься во дворе цитадели.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Цитадель расположена на севере.$B$BСледуй по каналам на север, пересеки разводной мост, и ты окажешься во дворе цитадели.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Цитадель расположена на севере.$B$BСледуй по каналам на север, пересеки разводной мост, и ты окажешься во дворе цитадели.',`text0_1_loc8`);
