INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (16621,'Тюрьма? Зачем она тебе? Это в центре города к северо-востоку от Квартала Магов.$B$BЕсли ты на самом деле туда собираешься, будь осторожней, я слышал о мятежниках...','Тюрьма? Зачем она тебе? Это в центре города к северо-востоку от Квартала Магов.$B$BЕсли ты на самом деле туда собираешься, будь осторожней, я слышала о мятежниках...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тюрьма? Зачем она тебе? Это в центре города к северо-востоку от Квартала Магов.$B$BЕсли ты на самом деле туда собираешься, будь осторожней, я слышал о мятежниках...',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Тюрьма? Зачем она тебе? Это в центре города к северо-востоку от Квартала Магов.$B$BЕсли ты на самом деле туда собираешься, будь осторожней, я слышала о мятежниках...',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16622,'Прости, но я не могу обучать тебя.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Прости, но я не могу обучать тебя.',`text0_1_loc8`);
