INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (16627,'В ювелирном магазине Денманов, расположенном между Торговым кварталом и каналами, ты найдешь все, что тебе нужно.','В ювелирном магазине Денманов, расположенном между Торговым кварталом и каналами, ты найдешь все, что тебе нужно.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','В ювелирном магазине Денманов, расположенном между Торговым кварталом и каналами, ты найдешь все, что тебе нужно.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','В ювелирном магазине Денманов, расположенном между Торговым кварталом и каналами, ты найдешь все, что тебе нужно.',`text0_1_loc8`);
