INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (16629,'Торговцы реагентами всегда находятся неподалеку от учителей профессий. Другие продавцы рассредоточены по всему городу.$B$BЧто именно тебе нужно?','Торговцы реагентами всегда находятся неподалеку от учителей профессий. Другие продавцы рассредоточены по всему городу.$B$BЧто именно тебе нужно?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Торговцы реагентами всегда находятся неподалеку от учителей профессий. Другие продавцы рассредоточены по всему городу.$B$BЧто именно тебе нужно?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Торговцы реагентами всегда находятся неподалеку от учителей профессий. Другие продавцы рассредоточены по всему городу.$B$BЧто именно тебе нужно?',`text0_1_loc8`);
