INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (16631,'В Ставке командования возле юго-восточных ворот Старого города ты найдешь интендантов.','В Ставке командования возле юго-восточных ворот Старого города ты найдешь интендантов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','В Ставке командования возле юго-восточных ворот Старого города ты найдешь интендантов.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','В Ставке командования возле юго-восточных ворот Старого города ты найдешь интендантов.',`text0_1_loc8`);
