INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (16632,'Городские стойла находятся возле юго-восточных ворот Старого города. Там ты найдешь учителя верховой езды и торговца лошадьми.','Городские стойла находятся возле юго-восточных ворот Старого города. Там ты найдешь учителя верховой езды и торговца лошадьми.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Городские стойла находятся возле юго-восточных ворот Старого города. Там ты найдешь учителя верховой езды и торговца лошадьми.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Городские стойла находятся возле юго-восточных ворот Старого города. Там ты найдешь учителя верховой езды и торговца лошадьми.',`text0_1_loc8`);
