INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (16634,'Знаешь, где найти грифоний насест и распорядителя полетов в Торговом квартале?$B$BПара гномов из клана Громового Молота продает там своих грифонов и даже может научить тебя ездить на них верхом.','Знаешь, где найти грифоний насест и распорядителя полетов в Торговом квартале?$B$BПара гномов из клана Громового Молота продает там своих грифонов и даже может научить тебя ездить на них верхом.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Знаешь, где найти грифоний насест и распорядителя полетов в Торговом квартале?$B$BПара гномов из клана Громового Молота продает там своих грифонов и даже может научить тебя ездить на них верхом.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Знаешь, где найти грифоний насест и распорядителя полетов в Торговом квартале?$B$BПара гномов из клана Громового Молота продает там своих грифонов и даже может научить тебя ездить на них верхом.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`,`text2_0_loc8`,`text2_1_loc8`,`text3_0_loc8`,`text3_1_loc8`,`text4_0_loc8`,`text4_1_loc8`,`text5_0_loc8`,`text5_1_loc8`,`text6_0_loc8`,`text6_1_loc8`,`text7_0_loc8`,`text7_1_loc8`) VALUES (16635,'Ты выглядишь $gизможденным:изможденной;. Что-то не так?','Ты выглядишь $gизможденным:изможденной;. Что-то не так?','Приятно видеть тебя.','Приятно видеть тебя.','ДА!','ДА!','Ты $gнашел:нашла; последний фрагмент?','Ты $gнашел:нашла; последний фрагмент?','Получилось что-нибудь с Теразан?','Получилось что-нибудь с Теразан?','Ты выглядишь $gзадумчивым:задумчивой;. Могу я чем-нибудь помочь тебе?','Ты выглядишь $gзадумчивым:задумчивой;. Могу я чем-нибудь помочь тебе?','Я нужен?','Я нужна?','А я думал, что смогу немного отдохнуть. Глупец.','А я думала, что смогу немного отдохнуть. Наивная.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты выглядишь $gизможденным:изможденной;. Что-то не так?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты выглядишь $gизможденным:изможденной;. Что-то не так?',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Приятно видеть тебя.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Приятно видеть тебя.',`text1_1_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','ДА!',`text2_0_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','ДА!',`text2_1_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Ты $gнашел:нашла; последний фрагмент?',`text3_0_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','Ты $gнашел:нашла; последний фрагмент?',`text3_1_loc8`), `text4_0_loc8`=IF(`text4_0_loc8` IS NULL OR `text4_0_loc8`='','Получилось что-нибудь с Теразан?',`text4_0_loc8`), `text4_1_loc8`=IF(`text4_1_loc8` IS NULL OR `text4_1_loc8`='','Получилось что-нибудь с Теразан?',`text4_1_loc8`), `text5_0_loc8`=IF(`text5_0_loc8` IS NULL OR `text5_0_loc8`='','Ты выглядишь $gзадумчивым:задумчивой;. Могу я чем-нибудь помочь тебе?',`text5_0_loc8`), `text5_1_loc8`=IF(`text5_1_loc8` IS NULL OR `text5_1_loc8`='','Ты выглядишь $gзадумчивым:задумчивой;. Могу я чем-нибудь помочь тебе?',`text5_1_loc8`), `text6_0_loc8`=IF(`text6_0_loc8` IS NULL OR `text6_0_loc8`='','Я нужен?',`text6_0_loc8`), `text6_1_loc8`=IF(`text6_1_loc8` IS NULL OR `text6_1_loc8`='','Я нужна?',`text6_1_loc8`), `text7_0_loc8`=IF(`text7_0_loc8` IS NULL OR `text7_0_loc8`='','А я думал, что смогу немного отдохнуть. Глупец.',`text7_0_loc8`), `text7_1_loc8`=IF(`text7_1_loc8` IS NULL OR `text7_1_loc8`='','А я думала, что смогу немного отдохнуть. Наивная.',`text7_1_loc8`);
