INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16638,'В мой город проникли агенты Сумеречного Молота, и если ничего не предпринять, они полностью заразят его скверной. Прежде чем отправиться на штурм их крепости на нагорье, я должен быть уверен в том, что Штормграду ничто не угрожает.$B$BМне нужны способные агенты – те, кто станет моими глазами и ушами. Ты, например.$B$BХочешь помочь мне защитить Штормград?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','В мой город проникли агенты Сумеречного Молота, и если ничего не предпринять, они полностью заразят его скверной. Прежде чем отправиться на штурм их крепости на нагорье, я должен быть уверен в том, что Штормграду ничто не угрожает.$B$BМне нужны способные агенты – те, кто станет моими глазами и ушами. Ты, например.$B$BХочешь помочь мне защитить Штормград?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16641,'Добро пожаловать в Штормград, |3-6($c).') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать в Штормград, |3-6($c).',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16644,'Эй, милашка! Не поможешь мне намазать спинку лосьоном для загара?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Эй, милашка! Не поможешь мне намазать спинку лосьоном для загара?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16651,'Надеюсь, вы с моим сыном уже успели подружиться ? Он очень общительный.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Надеюсь, вы с моим сыном уже успели подружиться ? Он очень общительный.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16653,'Когда в Штормграде наведут порядок, мы начнем сражаться за Нагорье.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Когда в Штормграде наведут порядок, мы начнем сражаться за Нагорье.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16661,'Мы должны взять то, что принадлежит нам. Иначе нам не выжить.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мы должны взять то, что принадлежит нам. Иначе нам не выжить.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16663,'Алый орден вернется к своим благородным истокам!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Алый орден вернется к своим благородным истокам!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16667,'Говори, когда к тебе обратятся.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Говори, когда к тебе обратятся.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16669,'Мы пытаемся узнать, что же такое важное происходит у Врат Мастеров.$b$bЯ просто знаю, что ничего хорошего от этих несчастных ждать не приходится. Это нечестно! Улики привели нас сюда, а теперь мы не можем даже приблизиться.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мы пытаемся узнать, что же такое важное происходит у Врат Мастеров.$b$bЯ просто знаю, что ничего хорошего от этих несчастных ждать не приходится. Это нечестно! Улики привели нас сюда, а теперь мы не можем даже приблизиться.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16670,'Я – богиня небес. Любой, кто посмеет угрожать моим детям, обречет себя на страдания!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я – богиня небес. Любой, кто посмеет угрожать моим детям, обречет себя на страдания!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16671,'Зови меня Близнецом. Так называет меня Мови.$b$bНет, мы не похожи. Ты что, $gслепой:слепая;? Света ради, она же гном! Мы ведем себя одинаково. Особенно в бою.$b$bА что до моего имени… тебе приходилось слышать о знаменитом семействе Брага из Громового Молота? Пива не хочешь?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Зови меня Близнецом. Так называет меня Мови.$b$bНет, мы не похожи. Ты что, $gслепой:слепая;? Света ради, она же гном! Мы ведем себя одинаково. Особенно в бою.$b$bА что до моего имени… тебе приходилось слышать о знаменитом семействе Брага из Громового Молота? Пива не хочешь?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16672,'Я совершенно уверена, что сектанты Сумеречного Молота обнаружили у Врат Мастеров что-то интересное.$b$bМожет быть, $gтакой опытный:такая милая:c; |3-6($c), как ты, поможет мне?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я совершенно уверена, что сектанты Сумеречного Молота обнаружили у Врат Мастеров что-то интересное.$b$bМожет быть, $gтакой опытный:такая милая:c; |3-6($c), как ты, поможет мне?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16673,'Как уже возможно просветил тебя мой любезный компаньон, мы разыскиваем нечто могущественное и таинственное. И все указывает на Врата Мастеров.$b$bК сожалению, нигилистические сектанты Сумеречного Молота мешают всем нашим попыткам исследовать данную территорию. У меня нет никаких сомнений, что |3-6($c) с такой репутацией, как у тебя, поможет хранителю реликвий в трудный час.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Как уже возможно просветил тебя мой любезный компаньон, мы разыскиваем нечто могущественное и таинственное. И все указывает на Врата Мастеров.$b$bК сожалению, нигилистические сектанты Сумеречного Молота мешают всем нашим попыткам исследовать данную территорию. У меня нет никаких сомнений, что |3-6($c) с такой репутацией, как у тебя, поможет хранителю реликвий в трудный час.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16683,'Что тебе нужно? Не видишь – я убираю помет летучих мышей.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что тебе нужно? Не видишь – я убираю помет летучих мышей.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16686,'Что привело тебя в эти проклятые земли?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Что привело тебя в эти проклятые земли?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16687,'После смерти Короля-лича у меня остались только мои обязанности. Нет больше ни семьи, ни друзей... Только одно.$B$BВойна.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','После смерти Короля-лича у меня остались только мои обязанности. Нет больше ни семьи, ни друзей... Только одно.$B$BВойна.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`,`text3_0_loc8`,`text4_0_loc8`,`text5_0_loc8`,`text6_0_loc8`,`text7_0_loc8`) VALUES (16688,'Это что, очередные газ\'ридианские штучки? С чего ты взял, что мне нужно еще больше этих мерзких поделок? Весь склад забит этой дрянью, только их никто не покупает! И с чего я решил, что кому-то будут нужны статуэтки змей-переростков? Ха!','Я видел шайку Скитальцев Пустоты и их предводителя Калифа Жало Скорпида к югу отсюда. Берегись, кажется, они что-то замышляют!','Я тут бродил по ульям силитидов и видел там самого огромного жука, которого ты только можешь себе представить! Точнее, их было двое. Чертова жара меня доконает... о, смотри, песчаный котенок побежал!','Драконы? Я про них ничего не знаю, хотя одного видел собственными глазами. Большой такой, страшный, уселся у входа в Пещеры Времени и вопил что-то... как же он сказал... про конец всего сущего? Честно говоря, я не прислушивался.','Один мой старый друг Фрокл отправился в Прибамбасск вместе с матросами картеля Трюмных вод, но корабль так и не прибыл в порт назначения. Ходят слухи, что далеко на юге рядом со сбитым летательным аппаратом бродит какой-то сумасшедший гоблин. Я вот и думаю – неужели это он?..','Пока я испытывал в дюнах потенциальную ценность запатентованной сентипарской закуски для силитидов, мне на глаза попалась замечательная сломанная тележка! Я аж залюбовался ею, но тут внезапно из-за камня вылез огромнейший василиск, и мне пришлось уносить ноги. Жаль, что я не смог прихватить ее с собой...','Ты когда-нибудь видел огромные кучи земли, которые буквально ползут по дюнам? Это гигантские черви прокладывают себе путь по Азероту. Уверяю тебя, таких чудовищ не встречал еще ни один искатель приключений. Наверное, было бы здорово сразиться с одним из них!','Когда Катаклизм пронесся по планете, узы, сковывавшие духов стихий по всему Азероту, ослабли, и один из элементалей – Аквамонтос – вырвался на волю. Теперь он доставляет кучу неприятностей пиратам Южных морей!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Это что, очередные газ\'ридианские штучки? С чего ты взял, что мне нужно еще больше этих мерзких поделок? Весь склад забит этой дрянью, только их никто не покупает! И с чего я решил, что кому-то будут нужны статуэтки змей-переростков? Ха!',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Я видел шайку Скитальцев Пустоты и их предводителя Калифа Жало Скорпида к югу отсюда. Берегись, кажется, они что-то замышляют!',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Я тут бродил по ульям силитидов и видел там самого огромного жука, которого ты только можешь себе представить! Точнее, их было двое. Чертова жара меня доконает... о, смотри, песчаный котенок побежал!',`text2_0_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Драконы? Я про них ничего не знаю, хотя одного видел собственными глазами. Большой такой, страшный, уселся у входа в Пещеры Времени и вопил что-то... как же он сказал... про конец всего сущего? Честно говоря, я не прислушивался.',`text3_0_loc8`), `text4_0_loc8`=IF(`text4_0_loc8` IS NULL OR `text4_0_loc8`='','Один мой старый друг Фрокл отправился в Прибамбасск вместе с матросами картеля Трюмных вод, но корабль так и не прибыл в порт назначения. Ходят слухи, что далеко на юге рядом со сбитым летательным аппаратом бродит какой-то сумасшедший гоблин. Я вот и думаю – неужели это он?..',`text4_0_loc8`), `text5_0_loc8`=IF(`text5_0_loc8` IS NULL OR `text5_0_loc8`='','Пока я испытывал в дюнах потенциальную ценность запатентованной сентипарской закуски для силитидов, мне на глаза попалась замечательная сломанная тележка! Я аж залюбовался ею, но тут внезапно из-за камня вылез огромнейший василиск, и мне пришлось уносить ноги. Жаль, что я не смог прихватить ее с собой...',`text5_0_loc8`), `text6_0_loc8`=IF(`text6_0_loc8` IS NULL OR `text6_0_loc8`='','Ты когда-нибудь видел огромные кучи земли, которые буквально ползут по дюнам? Это гигантские черви прокладывают себе путь по Азероту. Уверяю тебя, таких чудовищ не встречал еще ни один искатель приключений. Наверное, было бы здорово сразиться с одним из них!',`text6_0_loc8`), `text7_0_loc8`=IF(`text7_0_loc8` IS NULL OR `text7_0_loc8`='','Когда Катаклизм пронесся по планете, узы, сковывавшие духов стихий по всему Азероту, ослабли, и один из элементалей – Аквамонтос – вырвался на волю. Теперь он доставляет кучу неприятностей пиратам Южных морей!',`text7_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16689,'<Внутри тихо.>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Внутри тихо.>',`text0_0_loc8`);
