INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16694,'Эй! Ты здесь, чтобы помочь Зен\'Кики?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эй! Ты здесь, чтобы помочь Зен\'Кики?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16702,'Я сожгу тут все дотла, чтобы не упасть в глазах Адского Крика!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я сожгу тут все дотла, чтобы не упасть в глазах Адского Крика!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (16705,'Я могу научить тебя кузнечному делу, а также снабдить всеми необходимыми инструментами.$B$BНу, чем могу помочь?','Я могу научить тебя кузнечному делу, а также снабдить всеми необходимыми инструментами.$B$BНу, чем могу помочь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я могу научить тебя кузнечному делу, а также снабдить всеми необходимыми инструментами.$B$BНу, чем могу помочь?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я могу научить тебя кузнечному делу, а также снабдить всеми необходимыми инструментами.$B$BНу, чем могу помочь?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16711,'Ох, спасибо за помощь! С меня хватит превращений... Я буду дальше изучать целительство!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ох, спасибо за помощь! С меня хватит превращений... Я буду дальше изучать целительство!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16712,'Приветствую тебя, юный друг. Приятно вновь встретить благородного путника.$B$BЗабытый Город, прежде известный как Эльдре\'Талас, окончательно осквернен. Я видел, как мои собратья пали под натиском сил тьмы и хаоса. Многие мечтают о том, чтобы это ужасное место было стерто с лица земли.$B$BИ все же Забытый Город следует спасти, смертный. Помоги мне, и, может быть, мы пробудим безграничные силы добра, некогда питавшие это место.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приветствую тебя, юный друг. Приятно вновь встретить благородного путника.$B$BЗабытый Город, прежде известный как Эльдре\'Талас, окончательно осквернен. Я видел, как мои собратья пали под натиском сил тьмы и хаоса. Многие мечтают о том, чтобы это ужасное место было стерто с лица земли.$B$BИ все же Забытый Город следует спасти, смертный. Помоги мне, и, может быть, мы пробудим безграничные силы добра, некогда питавшие это место.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (16714,'Чем я могу быть полезен, дитя земли?','Чем я могу быть полезен, дитя земли?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Чем я могу быть полезен, дитя земли?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Чем я могу быть полезен, дитя земли?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (16715,'Пусть в джунглях мало света, но тамошняя земля плодородна.$B$BПусть духи земли покровительствуют тебе, |3-6($c).','Пусть в джунглях мало света, но тамошняя земля плодородна.$B$BПусть духи земли покровительствуют тебе, |3-6($c).') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Пусть в джунглях мало света, но тамошняя земля плодородна.$B$BПусть духи земли покровительствуют тебе, |3-6($c).',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Пусть в джунглях мало света, но тамошняя земля плодородна.$B$BПусть духи земли покровительствуют тебе, |3-6($c).',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16716,'Гордоки не любить Дагг\'тола, так что он их убивать. Глупые деревья и козлолюди тоже не любить Дагг\'тола, так что он хочет убивать их тоже.$B$BКрошка-|3-6($r) любить Дагг\'тол и помогать ему захватить это место для повелителя? Или Дагг\'толу нужно убивать тебя тоже?$B$BТупые деревья все смотреть на посла Дагг\'тола...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Гордоки не любить Дагг\'тола, так что он их убивать. Глупые деревья и козлолюди тоже не любить Дагг\'тола, так что он хочет убивать их тоже.$B$BКрошка-|3-6($r) любить Дагг\'тол и помогать ему захватить это место для повелителя? Или Дагг\'толу нужно убивать тебя тоже?$B$BТупые деревья все смотреть на посла Дагг\'тола...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16717,'У меня закончились все припасы, а дорогу перегородили орки. Вот уж повезло!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','У меня закончились все припасы, а дорогу перегородили орки. Вот уж повезло!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16719,'<Майор коротко кивает.>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Майор коротко кивает.>',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16720,'Ты уже здесь, $n? Что тебе сказали портовые рабочие?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты уже здесь, $n? Что тебе сказали портовые рабочие?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16726,'Я слишком сильно жажду спасти Эльдре\'Талас, только об этом мои помыслы. Война, распри, служение – ничто не имеет значения, пока этот город не будет в безопасности.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я слишком сильно жажду спасти Эльдре\'Талас, только об этом мои помыслы. Война, распри, служение – ничто не имеет значения, пока этот город не будет в безопасности.',`text0_0_loc8`);
