INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16728,'В Подземье не должно остаться ни единого следа Смертокрыла и его сумеречных сектантов.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','В Подземье не должно остаться ни единого следа Смертокрыла и его сумеречных сектантов.',`text0_1_loc8`);
