INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16729,'Я был в Стальгорне во время захвата – сущий кошмар тогда творился.$B$BНеудивительно, что как только я выхожу из замка, отец начинает с ума сходить от беспокойства.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я был в Стальгорне во время захвата – сущий кошмар тогда творился.$B$BНеудивительно, что как только я выхожу из замка, отец начинает с ума сходить от беспокойства.',`text0_0_loc8`);
