INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16731,'И ЧТО это было?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','И ЧТО это было?',`text0_0_loc8`);
