INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16732,'А?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','А?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16733,'Как тебе удалось добраться сюда пешком и остаться в живых? Только настоящий герой осмелится бросить вызов Забытому Городу.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Как тебе удалось добраться сюда пешком и остаться в живых? Только настоящий герой осмелится бросить вызов Забытому Городу.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (16734,'Айда сюда, приятель… Прочь заботы!$B$BРасслабься телом и душой!','Айда сюда, подруга... Прочь заботы!$B$BРасслабься телом и душой!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Айда сюда, приятель… Прочь заботы!$B$BРасслабься телом и душой!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Айда сюда, подруга... Прочь заботы!$B$BРасслабься телом и душой!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16736,'У меня редкие и мощные материалы.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','У меня редкие и мощные материалы.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16737,'Ты $gпоказал:показала;, на что ты $gспособен:способна;. Ты $gнаходчив:находчива;. Думаю, тебе-то как раз удастся победить червинтов, с которыми не можем справиться мы. Ты отправишься в Гремящие глубины, единственное место, куда мы попасть не можем.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты $gпоказал:показала;, на что ты $gспособен:способна;. Ты $gнаходчив:находчива;. Думаю, тебе-то как раз удастся победить червинтов, с которыми не можем справиться мы. Ты отправишься в Гремящие глубины, единственное место, куда мы попасть не можем.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16743,'Не слушай Алексия. Он сглупил, остался здесь, когда начался мор. А теперь посмотри на него – выглядит не лучше всех этих ужасных отродий. $B$BНо не волнуйся: мы вернем Некроситет и окрестные земли законному наследнику – последнему сыну Барова.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не слушай Алексия. Он сглупил, остался здесь, когда начался мор. А теперь посмотри на него – выглядит не лучше всех этих ужасных отродий. $B$BНо не волнуйся: мы вернем Некроситет и окрестные земли законному наследнику – последнему сыну Барова.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`) VALUES (16744,'Ты же не собираешься снова скрасть мою взрывчатку, а?','Ты только глянь!$B$BЭто ж мечта любого археолога...','Давай договоримся – ты не сбежишь опять с моей взрывчаткой, ладно?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты же не собираешься снова скрасть мою взрывчатку, а?',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Ты только глянь!$B$BЭто ж мечта любого археолога...',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Давай договоримся – ты не сбежишь опять с моей взрывчаткой, ладно?',`text2_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16745,'Ты только глянь!$B$BЭто ж мечта любого археолога...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты только глянь!$B$BЭто ж мечта любого археолога...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16747,'Смотри, я не становлюсь красивее.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Смотри, я не становлюсь красивее.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16748,'Они могут осушать озеро до тех пор, пока оно не превратится в лужу грязи. Но мы все равно будем бороться за то, чтобы оно оставалось нашим.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Они могут осушать озеро до тех пор, пока оно не превратится в лужу грязи. Но мы все равно будем бороться за то, чтобы оно оставалось нашим.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (16749,'Твой мозг не осилил бы моих тайных познаний, |3-6($c).$B$BПоверь мне. Если хочешь чему-то научиться, поговори с кем-то другим.','Твой мозг не осилил бы моих тайных познаний, |3-6($c).$B$BПоверь мне. Если хочешь чему-то научиться, поговори с кем-то другим.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Твой мозг не осилил бы моих тайных познаний, |3-6($c).$B$BПоверь мне. Если хочешь чему-то научиться, поговори с кем-то другим.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Твой мозг не осилил бы моих тайных познаний, |3-6($c).$B$BПоверь мне. Если хочешь чему-то научиться, поговори с кем-то другим.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (16750,'Кто знает, какие страшные вещи творятся в окружающей тьме… вещи, способные довести до безумия.$B$BУж мы-то все знаем. И тебе тоже хочется узнать побольше, приятель?','Кто знает, какие страшные вещи творятся в окружающей тьме… вещи, способные довести до безумия.$B$BУж мы-то все знаем. И тебе тоже хочется узнать побольше, подруга?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Кто знает, какие страшные вещи творятся в окружающей тьме… вещи, способные довести до безумия.$B$BУж мы-то все знаем. И тебе тоже хочется узнать побольше, приятель?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Кто знает, какие страшные вещи творятся в окружающей тьме… вещи, способные довести до безумия.$B$BУж мы-то все знаем. И тебе тоже хочется узнать побольше, подруга?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16754,'Доброго денечка, $gотважный:прелестная:c; |3-6($c). Чем могу служить?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Доброго денечка, $gотважный:прелестная:c; |3-6($c). Чем могу служить?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16755,'Так, посмотрим... Я видел нескольких работяг, которые бежали из вон той шахты. Они говорили что-то про паука. Новые покупатели? Например, заходила Джирали, милая молодая гномка. Она купила топор в два раза больше себя. А, еще заходил волхв Бисп, он интересовался доспехами. Ума не приложу, зачем ему понадобился доспех...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Так, посмотрим... Я видел нескольких работяг, которые бежали из вон той шахты. Они говорили что-то про паука. Новые покупатели? Например, заходила Джирали, милая молодая гномка. Она купила топор в два раза больше себя. А, еще заходил волхв Бисп, он интересовался доспехами. Ума не приложу, зачем ему понадобился доспех...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16756,'Могу я быть полезен?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Могу я быть полезен?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16757,'Это что – допрос? Ты же не один из ребят Фордринга, которые по внутренней безопасности?$B$BХотя все равно – мне скрывать нечего. Сейчас посмотрю в своих записях. На прошлой неделе лейтенант Майнер купил вечернее платье, что показалось мне странным. Что еще... волхв Бисп приобрел несколько дюжин кожаных курток. Зачем они ему, он не объяснил. А, брат Берлингем заглядывал – ему нужен был купальный костюм для поездки в Укрытие Кофельнагель. Вот, собственно, и все.$B$BТеперь, если не возражаешь, я, наконец, уделю внимание покупателям!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Это что – допрос? Ты же не один из ребят Фордринга, которые по внутренней безопасности?$B$BХотя все равно – мне скрывать нечего. Сейчас посмотрю в своих записях. На прошлой неделе лейтенант Майнер купил вечернее платье, что показалось мне странным. Что еще... волхв Бисп приобрел несколько дюжин кожаных курток. Зачем они ему, он не объяснил. А, брат Берлингем заглядывал – ему нужен был купальный костюм для поездки в Укрытие Кофельнагель. Вот, собственно, и все.$B$BТеперь, если не возражаешь, я, наконец, уделю внимание покупателям!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
