INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16759,'Поживем – увидим. Слышала, что волхв Бисп заперся на вершине своей башни, где тот работает над каким-то новым заклинанием.$b$bГоворят, Дель Гаррон хочет уйти в отставку и вернуться на ферму. Может статься, что он уже вернулся..$b$bА еще я слыхала, что по городу бродит $gкакой-то:какая-то:c; |3-6($r)-|3-6($c) и донимает местных жителей всякими вопросами!$b$bЯ просто заигрываю с тобой, $gмилый:милая;. Надеюсь, тебе помогли эти сведения.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Поживем – увидим. Слышала, что волхв Бисп заперся на вершине своей башни, где тот работает над каким-то новым заклинанием.$b$bГоворят, Дель Гаррон хочет уйти в отставку и вернуться на ферму. Может статься, что он уже вернулся..$b$bА еще я слыхала, что по городу бродит $gкакой-то:какая-то:c; |3-6($r)-|3-6($c) и донимает местных жителей всякими вопросами!$b$bЯ просто заигрываю с тобой, $gмилый:милая;. Надеюсь, тебе помогли эти сведения.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16760,'Да не оставит тебя свет, дитя. Чем я могу тебе помочь в такой прекрасный день?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да не оставит тебя свет, дитя. Чем я могу тебе помочь в такой прекрасный день?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16761,'Украденные припасы? Дай подумать...$B$BЯ знаю одну жрицу, Дарию, которая забрала вино, оставшееся после службы на прошлой неделе, но не вылила его, как я просил. Полагаю, она скоро попросит прощения за свой поступок.$B$B<Альфус подмигивает.>$B$BТакже на этой неделе я слышал необычно много признаний от одного мага... Как его звали? Хряп... Ляп... Что-то в этом роде.$B$BНе смею доле тебя задерживать.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Украденные припасы? Дай подумать...$B$BЯ знаю одну жрицу, Дарию, которая забрала вино, оставшееся после службы на прошлой неделе, но не вылила его, как я просил. Полагаю, она скоро попросит прощения за свой поступок.$B$B<Альфус подмигивает.>$B$BТакже на этой неделе я слышал необычно много признаний от одного мага... Как его звали? Хряп... Ляп... Что-то в этом роде.$B$BНе смею доле тебя задерживать.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16762,'Ч-что ты здесь делаешь, |3-6($r)? Разве ты не видишь, что вмешиваешься в дела Серебряного Авангарда?!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ч-что ты здесь делаешь, |3-6($r)? Разве ты не видишь, что вмешиваешься в дела Серебряного Авангарда?!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
