INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16796,'По своим возможностям Братство Света превосходит любую другую организацию и не потерпит никаких выпадов против Света. Мы предпримем все от нас зависящее, чтобы избавить мир от всех грязных тварей, как, например, эта нежить. Нас ничто не остановит.$b$bТы с нами или против нас?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','По своим возможностям Братство Света превосходит любую другую организацию и не потерпит никаких выпадов против Света. Мы предпримем все от нас зависящее, чтобы избавить мир от всех грязных тварей, как, например, эта нежить. Нас ничто не остановит.$b$bТы с нами или против нас?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (16798,'Тебе надо найти Сесеби. Она дрыхнет где-нибудь в теньке возле старика Умбехто, местного рыбака, прямо как настоящая старая тигрица.','Тебе надо найти Сесеби. Она дрыхнет где-нибудь в теньке возле старика Умбехто, местного рыбака, прямо как настоящая старая тигрица.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тебе надо найти Сесеби. Она дрыхнет где-нибудь в теньке возле старика Умбехто, местного рыбака, прямо как настоящая старая тигрица.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Тебе надо найти Сесеби. Она дрыхнет где-нибудь в теньке возле старика Умбехто, местного рыбака, прямо как настоящая старая тигрица.',`text0_1_loc8`);
