INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (16799,'Кузари и Занга наставляют охотников за головами на одном из небольших островков к юго-востоку от этой долины.','Кузари и Занга наставляют охотников за головами на одном из небольших островков к юго-востоку от этой долины.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Кузари и Занга наставляют охотников за головами на одном из небольших островков к юго-востоку от этой долины.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Кузари и Занга наставляют охотников за головами на одном из небольших островков к юго-востоку от этой долины.',`text0_1_loc8`);
