INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (16800,'Они на вершине здоровенного здания в юго-восточном углу долины.','Они на вершине здоровенного здания в юго-восточном углу долины.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Они на вершине здоровенного здания в юго-восточном углу долины.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Они на вершине здоровенного здания в юго-восточном углу долины.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16801,'Чувств нет. Морали нет. Фанатиков нет.$B$BЕсть только Братство.$B$BЗдесь, в той самой часовне, где Утер Светоносный вступил в орден Серебряной Длани, я, Корфакс, Воитель Света, вселю страх в души бесстрашных.$B$BНичто не усмирит мою ярость – ни Алый орден, ни Серебряный Рассвет, ни даже вы, мои братья.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Чувств нет. Морали нет. Фанатиков нет.$B$BЕсть только Братство.$B$BЗдесь, в той самой часовне, где Утер Светоносный вступил в орден Серебряной Длани, я, Корфакс, Воитель Света, вселю страх в души бесстрашных.$B$BНичто не усмирит мою ярость – ни Алый орден, ни Серебряный Рассвет, ни даже вы, мои братья.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (16803,'Крадущийся в тени Зуру, вот кто тебе нужен.$B$BНайдешь его на нижнем этаже того здоровенного здания на юго-востоке.','Крадущийся в тени Зуру, вот кто тебе нужен.$B$BНайдешь его на нижнем этаже того здоровенного здания на юго-востоке.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Крадущийся в тени Зуру, вот кто тебе нужен.$B$BНайдешь его на нижнем этаже того здоровенного здания на юго-востоке.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Крадущийся в тени Зуру, вот кто тебе нужен.$B$BНайдешь его на нижнем этаже того здоровенного здания на юго-востоке.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (16804,'Ку\'нанджи, ночной следопыт, вот кто тебе нужен. Он находится к северу от центрального здания в долине.','Ку\'нанджи, ночной следопыт, вот кто тебе нужен. Он находится к северу от центрального здания в долине.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ку\'нанджи, ночной следопыт, вот кто тебе нужен. Он находится к северу от центрального здания в долине.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ку\'нанджи, ночной следопыт, вот кто тебе нужен. Он находится к северу от центрального здания в долине.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (16805,'Доктор Амбу обычно гуляет по долине, беседуя с людьми и духами стихий.$B$BПоищи его неподалеку от центрального здания.','Доктор Амбу обычно гуляет по долине, беседуя с людьми и духами стихий.$B$BПоищи его неподалеку от центрального здания.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Доктор Амбу обычно гуляет по долине, беседуя с людьми и духами стихий.$B$BПоищи его неподалеку от центрального здания.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Доктор Амбу обычно гуляет по долине, беседуя с людьми и духами стихий.$B$BПоищи его неподалеку от центрального здания.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (16806,'У тебя, кажись, не все дома, раз ты интересуешься такими вещами. Но я тебя не собираюсь останавливать.$B$BАнджари Остроязыкая живет в самом высоком доме долины, возле святилища темных жрецов.','У тебя, кажись, не все дома, раз ты интересуешься такими вещами. Но я тебя не собираюсь останавливать.$B$BАнджари Остроязыкая живет в самом высоком доме долины, возле святилища темных жрецов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','У тебя, кажись, не все дома, раз ты интересуешься такими вещами. Но я тебя не собираюсь останавливать.$B$BАнджари Остроязыкая живет в самом высоком доме долины, возле святилища темных жрецов.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','У тебя, кажись, не все дома, раз ты интересуешься такими вещами. Но я тебя не собираюсь останавливать.$B$BАнджари Остроязыкая живет в самом высоком доме долины, возле святилища темных жрецов.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (16807,'Замджа лучший повар в Оргриммаре. Найдешь ее к югу от центрального здания долины. Если ты вдруг проголодаешься, имей в виду – Батамси продает еду, которую готовит Замджа.','Замджа лучший повар в Оргриммаре. Найдешь ее к югу от центрального здания долины. Если ты вдруг проголодаешься, имей в виду – Батамси продает еду, которую готовит Замджа.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Замджа лучший повар в Оргриммаре. Найдешь ее к югу от центрального здания долины. Если ты вдруг проголодаешься, имей в виду – Батамси продает еду, которую готовит Замджа.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Замджа лучший повар в Оргриммаре. Найдешь ее к югу от центрального здания долины. Если ты вдруг проголодаешься, имей в виду – Батамси продает еду, которую готовит Замджа.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (16808,'Джанди и Зил\'айя живут в хижине к северу от центра долины.$B$BОни помогут тебе с тем, что ты ищешь.','Джанди и Зил\'айя живут в хижине к северу от центра долины.$B$BОни помогут тебе с тем, что ты ищешь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Джанди и Зил\'айя живут в хижине к северу от центра долины.$B$BОни помогут тебе с тем, что ты ищешь.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Джанди и Зил\'айя живут в хижине к северу от центра долины.$B$BОни помогут тебе с тем, что ты ищешь.',`text0_1_loc8`);
