INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (16811,'Худжу и Ксен\'то позаботятся о тебе. Найдешь их в центре долины.','Худжу и Ксен\'то позаботятся о тебе. Найдешь их в центре долины.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Худжу и Ксен\'то позаботятся о тебе. Найдешь их в центре долины.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Худжу и Ксен\'то позаботятся о тебе. Найдешь их в центре долины.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (16813,'Ксан\'Тиш бродит со своими змеями в центре долины, ищи его там.','Ксан\'Тиш бродит со своими змеями в центре долины, ищи его там.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ксан\'Тиш бродит со своими змеями в центре долины, ищи его там.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ксан\'Тиш бродит со своими змеями в центре долины, ищи его там.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16814,'Они напали на нас, когда хлынула вода! Такое впечатление – заранее знали, что случится.$B$BОни должны понести заслуженную кару за все сделанное.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Они напали на нас, когда хлынула вода! Такое впечатление – заранее знали, что случится.$B$BОни должны понести заслуженную кару за все сделанное.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16815,'Если тебе понадобятся реагенты, у меня есть все необходимое.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если тебе понадобятся реагенты, у меня есть все необходимое.',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16816,'Я не могу обучать тебя.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я не могу обучать тебя.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16824,'<Качество, на которое можно полагаться до самого взрывного конца!>$B$B<Опусти бабки, чтобы получить обучение и товары.>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Качество, на которое можно полагаться до самого взрывного конца!>$B$B<Опусти бабки, чтобы получить обучение и товары.>',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16825,'Если хочешь, можешь отдохнуть здесь. Теперь Храм Земли под нашим наблюдением.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если хочешь, можешь отдохнуть здесь. Теперь Храм Земли под нашим наблюдением.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16828,'Это последнее нападение Зловещего Тотема. Раз они не понимают, что поступают неправильно, нам придется уничтожить их как диких зверей.$B$BДа простит нас Мать-Земля.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Это последнее нападение Зловещего Тотема. Раз они не понимают, что поступают неправильно, нам придется уничтожить их как диких зверей.$B$BДа простит нас Мать-Земля.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16830,'<Мать-Скала смотрит на вас. Сквозь вас. Как если бы она глядела прямо вам в душу.>$b$bМоя дочь, Терадрас, скрылась от всех глубоко в хрустальных пещерах Террамока, чтобы оплакать свою потерянную любовь, Зейтара. Туда ворвались бессердечные существа, с телами не из камня, и убили ее.$b$bЕсли раньше у меня и были какие-то основания доверять существам из плоти и крови, то в тот день все они пропали. Но твоя самонадеянность так велика, что ты упорствуешь.$b$bОднажды ты переживешь свою полезность.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','<Мать-Скала смотрит на вас. Сквозь вас. Как если бы она глядела прямо вам в душу.>$b$bМоя дочь, Терадрас, скрылась от всех глубоко в хрустальных пещерах Террамока, чтобы оплакать свою потерянную любовь, Зейтара. Туда ворвались бессердечные существа, с телами не из камня, и убили ее.$b$bЕсли раньше у меня и были какие-то основания доверять существам из плоти и крови, то в тот день все они пропали. Но твоя самонадеянность так велика, что ты упорствуешь.$b$bОднажды ты переживешь свою полезность.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16831,'Извини, похоже, тебе придется поискать наставника где-нибудь в другом месте.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Извини, похоже, тебе придется поискать наставника где-нибудь в другом месте.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16832,'За умеренную плату я обучу тебя основам магии жрецов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','За умеренную плату я обучу тебя основам магии жрецов.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16833,'Чем я могу помочь тебе, |3-6($c)?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Чем я могу помочь тебе, |3-6($c)?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16834,'Нет, но ты можешь поговорить с целителем земли Доросом… большой такой дреней, смотрит, что там осталось от лагеря Сумеречного Молота.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Нет, но ты можешь поговорить с целителем земли Доросом… большой такой дреней, смотрит, что там осталось от лагеря Сумеречного Молота.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16835,'Уцелела лишь небольшая часть их лагеря. Но там все равно могло остаться что-то, что может быть нам полезным.$b$bТебе что-то нужно от меня, |3-6($r)?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Уцелела лишь небольшая часть их лагеря. Но там все равно могло остаться что-то, что может быть нам полезным.$b$bТебе что-то нужно от меня, |3-6($r)?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16836,'У меня ничего для тебя нет.$b$bНо Хегрид собирает припасы Сумеречного Молота, чтобы восполнить недостаток наших. Можешь поговорить с ней.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','У меня ничего для тебя нет.$b$bНо Хегрид собирает припасы Сумеречного Молота, чтобы восполнить недостаток наших. Можешь поговорить с ней.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16839,'Что падает, то я и собираю.$b$bВ последнее время тут было много всяких штук.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что падает, то я и собираю.$b$bВ последнее время тут было много всяких штук.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16840,'Я не могу. Я просто собираю.$b$bТебе может помощь Ибдил. Он чинит.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я не могу. Я просто собираю.$b$bТебе может помощь Ибдил. Он чинит.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16841,'Я чиню то, что сломалось.$b$bВ последнее время столько всего ломалось. Очень много.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я чиню то, что сломалось.$b$bВ последнее время столько всего ломалось. Очень много.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16844,'Вряд ли тебе пригодится что-то из того, что есть у меня.$b$bА вот у Д\'лома в его коллекции, может, что-то и найдется.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вряд ли тебе пригодится что-то из того, что есть у меня.$b$bА вот у Д\'лома в его коллекции, может, что-то и найдется.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16845,'Чем могу помочь, |3-6($c)?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Чем могу помочь, |3-6($c)?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16846,'Как станешь шаманом, ты оставишь все прежние занятия.$B$BЯ раньше недооценивал пользу огненных элементалей. Да и управлять ими легко: плесни водички – и они как шелковые.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Как станешь шаманом, ты оставишь все прежние занятия.$B$BЯ раньше недооценивал пользу огненных элементалей. Да и управлять ими легко: плесни водички – и они как шелковые.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16847,'Сумеречный Молот разрушил множество наших кругов стихий. Некоторые из них захвачены служителями культа и приспособлены для темных ритуалов. Этот круг – последний, и мы защитим его, какие бы ужасы они ни призывали из-под земли.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Сумеречный Молот разрушил множество наших кругов стихий. Некоторые из них захвачены служителями культа и приспособлены для темных ритуалов. Этот круг – последний, и мы защитим его, какие бы ужасы они ни призывали из-под земли.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16848,'Где же эти болваны?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Где же эти болваны?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16849,'Ну да... Нужно ли это Хроми? Думаю, да.$B$BДа, можешь взять. Полистай книгу, в ней ты найдешь сведения об истории Дарроушира и тех событиях, которые привели к смерти многих людей.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ну да... Нужно ли это Хроми? Думаю, да.$B$BДа, можешь взять. Полистай книгу, в ней ты найдешь сведения об истории Дарроушира и тех событиях, которые привели к смерти многих людей.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16850,'Никогда не забывай про логистику. Воины могут победить в битве, но войну выигрывают припасы.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Никогда не забывай про логистику. Воины могут победить в битве, но войну выигрывают припасы.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`,`text2_0_loc8`,`text2_1_loc8`) VALUES (16851,'Я не уверен, что тебе удастся отдохнуть здесь, |3-6($c). Эти орки ни в чем не знают меры.','Я не уверена, что тебе удастся отдохнуть здесь, |3-6($c). Эти орки ни в чем не знают меры.','Пьяный орк – потрясающее зрелище. А вот армию пьяных орков я видел только однажды – и больше не хочу.','Пьяный орк – потрясающее зрелище. А вот армию пьяных орков я видела только однажды – и больше не хочу.','Если бы мне мама сказала, что когда-нибудь настанут такие времена, как сейчас, я бы ей не поверил.','Если бы мне мама сказала, что когда-нибудь настанут такие времена, как сейчас, я бы ей не поверила.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я не уверен, что тебе удастся отдохнуть здесь, |3-6($c). Эти орки ни в чем не знают меры.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я не уверена, что тебе удастся отдохнуть здесь, |3-6($c). Эти орки ни в чем не знают меры.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Пьяный орк – потрясающее зрелище. А вот армию пьяных орков я видел только однажды – и больше не хочу.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Пьяный орк – потрясающее зрелище. А вот армию пьяных орков я видела только однажды – и больше не хочу.',`text1_1_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Если бы мне мама сказала, что когда-нибудь настанут такие времена, как сейчас, я бы ей не поверил.',`text2_0_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Если бы мне мама сказала, что когда-нибудь настанут такие времена, как сейчас, я бы ей не поверила.',`text2_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16858,'Я провел слишком много времени в том городе. Место, конечно, прекрасное, и служить мне там нравилось, но все же я предпочту остаться здесь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я провел слишком много времени в том городе. Место, конечно, прекрасное, и служить мне там нравилось, но все же я предпочту остаться здесь.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16862,'Я двигаюсь в этом направлении. А задержался здесь, в Башне королевской стражи, потому что на дорогах сейчас кишмя кишит всякая живность.$B$BДавай договоримся: ты поможешь мне расчистить путь, а я присоединюсь к твоей группе.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я двигаюсь в этом направлении. А задержался здесь, в Башне королевской стражи, потому что на дорогах сейчас кишмя кишит всякая живность.$B$BДавай договоримся: ты поможешь мне расчистить путь, а я присоединюсь к твоей группе.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16864,'Да, $gпутешественник:путешественница;?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да, $gпутешественник:путешественница;?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16865,'Караван перевозит коробки с припасами торговцев, а также личные вещи Фионы и ее спутников.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Караван перевозит коробки с припасами торговцев, а также личные вещи Фионы и ее спутников.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16866,'Здесь просто рай для археолога!$B$BЖаль, нет времени как следует здесь все исследовать.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здесь просто рай для археолога!$B$BЖаль, нет времени как следует здесь все исследовать.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16867,'Местность тут жуткая! Земля мягкая, словно губка, кругом пни да камни – как будто овсянка в кастрюле взбесилась. В эту грязищу и паровой танк целиком засосет.$B$BВсе наше снаряжение тонет в скользкой мерзости, его топчет Орда!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Местность тут жуткая! Земля мягкая, словно губка, кругом пни да камни – как будто овсянка в кастрюле взбесилась. В эту грязищу и паровой танк целиком засосет.$B$BВсе наше снаряжение тонет в скользкой мерзости, его топчет Орда!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16868,'Ты хочешь вернуться в Вайш\'ир?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты хочешь вернуться в Вайш\'ир?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16869,'Не пугайся. Моя сущность не соответствует моей внешности.$b$bМеня зовут Акридостраз, но ты можешь звать меня Акрайд. Моя королева послала меня сюда, чтобы я остановил Нефариана, и я не сомкну глаз до тех пор, пока моя задача не будет выполнена. Однако, его логово стерегут и другие враги, и мне не справиться одному.$b$bПомоги мне избавиться от них, и ты заслужишь расположение Алекстразы. Может быть, сейчас тебе незнакомо это имя, но однажды ты будешь $gрад:рада;, что $gсделал:сделала; это. Я в этом уверен.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не пугайся. Моя сущность не соответствует моей внешности.$b$bМеня зовут Акридостраз, но ты можешь звать меня Акрайд. Моя королева послала меня сюда, чтобы я остановил Нефариана, и я не сомкну глаз до тех пор, пока моя задача не будет выполнена. Однако, его логово стерегут и другие враги, и мне не справиться одному.$b$bПомоги мне избавиться от них, и ты заслужишь расположение Алекстразы. Может быть, сейчас тебе незнакомо это имя, но однажды ты будешь $gрад:рада;, что $gсделал:сделала; это. Я в этом уверен.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (16870,'Я всегда рад тебя видеть – и твои деньги тоже.','Я всегда рада тебя видеть – и твои деньги тоже.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я всегда рад тебя видеть – и твои деньги тоже.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я всегда рада тебя видеть – и твои деньги тоже.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16871,'Тебе не нужно сражаться со мной, |3-6($r). Я не желаю тебе зла.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тебе не нужно сражаться со мной, |3-6($r). Я не желаю тебе зла.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (16872,'Он застрял, да еще и давление пара упало. Просто катастрофа, а не местность!$B$BТы можешь нас вытащить отсюда?','Он застрял, да еще и давление пара упало. Просто катастрофа, а не местность!$B$BТы можешь нас вытащить отсюда?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Он застрял, да еще и давление пара упало. Просто катастрофа, а не местность!$B$BТы можешь нас вытащить отсюда?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Он застрял, да еще и давление пара упало. Просто катастрофа, а не местность!$B$BТы можешь нас вытащить отсюда?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16873,'Варево в котле бурлит и пенится.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Варево в котле бурлит и пенится.',`text0_0_loc8`);
