INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16874,'Похоже, ничего не происходит. Чумной котел, может быть, испорчен, но выглядит он все так же. Что ты будешь делать?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Похоже, ничего не происходит. Чумной котел, может быть, испорчен, но выглядит он все так же. Что ты будешь делать?',`text0_0_loc8`);
