INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (16883,'Слышал, что ты пришел издалека. Может, желаешь чему-то обучиться?','Слышал, что ты пришла издалека. Может, желаешь чему-то обучиться?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Слышал, что ты пришел издалека. Может, желаешь чему-то обучиться?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Слышал, что ты пришла издалека. Может, желаешь чему-то обучиться?',`text0_1_loc8`);
