INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (16884,'Что? Я тебе кто, |3-6($c)?$B$BВали отсюда!','Что? Я тебе кто, |3-6($c)?$B$BВали отсюда!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что? Я тебе кто, |3-6($c)?$B$BВали отсюда!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Что? Я тебе кто, |3-6($c)?$B$BВали отсюда!',`text0_1_loc8`);
