INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (16886,'Тебе что-то нужно?$B$BЖаль. Ведь я тебе ничем помочь не могу, |3-6($c).','Тебе что-то нужно?$B$BЖаль. Ведь я тебе ничем помочь не могу, |3-6($c).') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тебе что-то нужно?$B$BЖаль. Ведь я тебе ничем помочь не могу, |3-6($c).',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Тебе что-то нужно?$B$BЖаль. Ведь я тебе ничем помочь не могу, |3-6($c).',`text0_1_loc8`);
