INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (16887,'Управление стихиями ради удовольствия и выгоды.$B$BЭто ведь самое главное, верно? Ну, за работу.','Управление стихиями ради удовольствия и выгоды.$B$BЭто ведь самое главное, верно? Ну, за работу.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Управление стихиями ради удовольствия и выгоды.$B$BЭто ведь самое главное, верно? Ну, за работу.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Управление стихиями ради удовольствия и выгоды.$B$BЭто ведь самое главное, верно? Ну, за работу.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (16888,'Послушай, ты даже НЕ ПРЕДСТАВЛЯЕШЬ, чему я вообще учу.$B$BЭто взорвет твой мозг. Я абсолютно серьезен. Иди, поищи себе другую забаву.','Послушай, ты даже НЕ ПРЕДСТАВЛЯЕШЬ, чему я вообще учу.$B$BЭто взорвет твой мозг. Я говорю абсолютно серьезно. Иди, поищи себе другую забаву.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Послушай, ты даже НЕ ПРЕДСТАВЛЯЕШЬ, чему я вообще учу.$B$BЭто взорвет твой мозг. Я абсолютно серьезен. Иди, поищи себе другую забаву.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Послушай, ты даже НЕ ПРЕДСТАВЛЯЕШЬ, чему я вообще учу.$B$BЭто взорвет твой мозг. Я говорю абсолютно серьезно. Иди, поищи себе другую забаву.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16893,'<Портал в другое измерение тихо гудит.>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Портал в другое измерение тихо гудит.>',`text0_0_loc8`);
