INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16901,'Это лучшее огнестрельное оружие во всем Оргриммаре.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Это лучшее огнестрельное оружие во всем Оргриммаре.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16903,'Мы поклялись открыть врата стихий из Штормграда на нагорье, но нам мешают агенты Сумеречного бастиона.$B$BЧто за безумие они затеяли на этот раз?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мы поклялись открыть врата стихий из Штормграда на нагорье, но нам мешают агенты Сумеречного бастиона.$B$BЧто за безумие они затеяли на этот раз?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16906,'Портал открыт! Благодаря тебе теперь мы можем быстро путешествовать между Штормградом и Сумеречным нагорьем.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Портал открыт! Благодаря тебе теперь мы можем быстро путешествовать между Штормградом и Сумеречным нагорьем.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16907,'Нет ничего прекраснее, чем парить в небесах.$B$BНу, разве что сражаться, паря в воздухе, а потом опрокинуть кружечку славного эля!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Нет ничего прекраснее, чем парить в небесах.$B$BНу, разве что сражаться, паря в воздухе, а потом опрокинуть кружечку славного эля!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16908,'Ну, надо было так и сказать! Задай этим сумеречным сектантам перцу и от моего имени, лады?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ну, надо было так и сказать! Задай этим сумеречным сектантам перцу и от моего имени, лады?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16909,'Никому не позволяй говорить, что Плеть побеждена. Слушай... Разве они до сих пор не шарятся по Чумному лесу? Носа не кажут из своих проклятых земель, как испуганное дитя из-под одеяла.$B$BЯ должен сражаться, у меня нет иного выбора. До последнего вздоха я буду биться с ними.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Никому не позволяй говорить, что Плеть побеждена. Слушай... Разве они до сих пор не шарятся по Чумному лесу? Носа не кажут из своих проклятых земель, как испуганное дитя из-под одеяла.$B$BЯ должен сражаться, у меня нет иного выбора. До последнего вздоха я буду биться с ними.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16914,'Этот полуостров будет твоим, |3-6($c).$B$BТы станешь оружием.$B$BТы станешь служителем смерти, проповедующим войну и молящим о ней.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Этот полуостров будет твоим, |3-6($c).$B$BТы станешь оружием.$B$BТы станешь служителем смерти, проповедующим войну и молящим о ней.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16918,'Докладывай!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Докладывай!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16920,'После быстрого осмотра вы приходите к выводу, что этот несчастный скончался несколько часов назад.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','После быстрого осмотра вы приходите к выводу, что этот несчастный скончался несколько часов назад.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16923,'Надо любой ценой остановить Чо\'Галла, пока он не создал совершенное оружие. Даже если это значит, что мы пожертвуем своей жизнью.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Надо любой ценой остановить Чо\'Галла, пока он не создал совершенное оружие. Даже если это значит, что мы пожертвуем своей жизнью.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16928,'Ниче нет лучше, чем кружить над врагом и – бум-бум – кидать в него бомбы!$B$BА еще можно сбросить им на головы стокилограммовых орков. Правда, детка?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ниче нет лучше, чем кружить над врагом и – бум-бум – кидать в него бомбы!$B$BА еще можно сбросить им на головы стокилограммовых орков. Правда, детка?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16929,'А что ж было так не сказать? Быстренько помахайся с Сумеречными, потом вернись сюда – оторвемся!$B$BУ нас с подругой тут милое местечко на берегу. Заходи в гости!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','А что ж было так не сказать? Быстренько помахайся с Сумеречными, потом вернись сюда – оторвемся!$B$BУ нас с подругой тут милое местечко на берегу. Заходи в гости!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16930,'Сама госпожа Ветрокрылая послала меня в качестве связной от Орды между Зелой и кланом Драконьей Пасти. Вместе с новым вождем Гаррошем они пытаются восстановить целостность своих границ.$B$BКак бы то ни было, мы должны покончить с угрозой Сумеречного Молота раз и навсегда. Но, что еще важнее – мы должны не допустить, чтобы Чо\'Галл создал свое совершенное оружие.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Сама госпожа Ветрокрылая послала меня в качестве связной от Орды между Зелой и кланом Драконьей Пасти. Вместе с новым вождем Гаррошем они пытаются восстановить целостность своих границ.$B$BКак бы то ни было, мы должны покончить с угрозой Сумеречного Молота раз и навсегда. Но, что еще важнее – мы должны не допустить, чтобы Чо\'Галл создал свое совершенное оружие.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16939,'Я уже давно наблюдаю за кланом Черного Железа... строю планы, лелею надежды, мечтаю прогнать его и вернуть мои земли.$B$BА клан пусть живет на Черной горе. Надеюсь, когда-нибудь она снова взорвется и поглотит их всех. А мне нужны земли, называющиеся сейчас Пылающими степями, это моя часть Красногорья, которую уничтожил огненный повелитель клана.$B$B$C, я покажу миру, на что я способна. Там, где царили смерть и предательство, я построю королевство мира и справедливости. Я пришла сюда, чтобы силой вернуть себе то, что принадлежит мне по праву.$B$BИ я готова умереть, сражаясь.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я уже давно наблюдаю за кланом Черного Железа... строю планы, лелею надежды, мечтаю прогнать его и вернуть мои земли.$B$BА клан пусть живет на Черной горе. Надеюсь, когда-нибудь она снова взорвется и поглотит их всех. А мне нужны земли, называющиеся сейчас Пылающими степями, это моя часть Красногорья, которую уничтожил огненный повелитель клана.$B$B$C, я покажу миру, на что я способна. Там, где царили смерть и предательство, я построю королевство мира и справедливости. Я пришла сюда, чтобы силой вернуть себе то, что принадлежит мне по праву.$B$BИ я готова умереть, сражаясь.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16941,'Оркам Драконьей Пасти сложно объяснить понятия типа "Сектор обстрела" или "Огонь на подавление".$B$BК счастью, они отлично усвоили, что такое "Огневой мешок" и... ну да... "Убийство".') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Оркам Драконьей Пасти сложно объяснить понятия типа "Сектор обстрела" или "Огонь на подавление".$B$BК счастью, они отлично усвоили, что такое "Огневой мешок" и... ну да... "Убийство".',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16942,'Я запрашивал подкрепление, чтобы удержать берег. А Орда прислала эту мелюзгу с какими-то железными трубочками.$B$B<Гралок бросает презрительный взгляд на ближайших гоблинов.>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я запрашивал подкрепление, чтобы удержать берег. А Орда прислала эту мелюзгу с какими-то железными трубочками.$B$B<Гралок бросает презрительный взгляд на ближайших гоблинов.>',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16943,'Это неприступная крепость, однако враги окружили ее со всех сторон. Так что нам нужно закрепиться здесь, на берегу, а уж потом двигаться дальше.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Это неприступная крепость, однако враги окружили ее со всех сторон. Так что нам нужно закрепиться здесь, на берегу, а уж потом двигаться дальше.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16944,'Мы никогда не забудем того, что Каргат Острорук сделал для Орды. Он был одним из величайших воинов за всю историю, и это признает даже Альянс.$B$BКаргатский экспедиционный корпус был назван в его честь, и я сделаю все для того, чтобы мы могли с гордостью носить его имя. Мы прогоним дворфов Черного Железа и захватим Черную гору и все ее окрестности – ведь эти земли по праву принадлежат Орде.$B$BА ты будешь мечом вождя в его битве с Тауриссаном. Гордись оказанной тебе честью.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы никогда не забудем того, что Каргат Острорук сделал для Орды. Он был одним из величайших воинов за всю историю, и это признает даже Альянс.$B$BКаргатский экспедиционный корпус был назван в его честь, и я сделаю все для того, чтобы мы могли с гордостью носить его имя. Мы прогоним дворфов Черного Железа и захватим Черную гору и все ее окрестности – ведь эти земли по праву принадлежат Орде.$B$BА ты будешь мечом вождя в его битве с Тауриссаном. Гордись оказанной тебе честью.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16945,'Похоже, все нашли дорогу домой. Это прекрасно.$B$BВот, и ты тоже! Не желаешь к нам присоединиться?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Похоже, все нашли дорогу домой. Это прекрасно.$B$BВот, и ты тоже! Не желаешь к нам присоединиться?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`,`text1_1_loc8`,`text2_1_loc8`) VALUES (16946,'Я мечтаю когда-нибудь открыть магазин в часовне Последней Надежды. Боец из меня неважнецкий, но это не значит, что я не могу помочь делу.','Мы с парнями путешествуем вместе совсем недолго, но я уже не могу представить себя без кого-нибудь из них.','Надеюсь, вы уже посмотрели товары в моем караване. Можете брать те, которые нам сейчас без надобности.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я мечтаю когда-нибудь открыть магазин в часовне Последней Надежды. Боец из меня неважнецкий, но это не значит, что я не могу помочь делу.',`text0_1_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Мы с парнями путешествуем вместе совсем недолго, но я уже не могу представить себя без кого-нибудь из них.',`text1_1_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Надеюсь, вы уже посмотрели товары в моем караване. Можете брать те, которые нам сейчас без надобности.',`text2_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`,`text2_1_loc8`) VALUES (16947,'С чего бы ему вот так убегать?','<Фиона сильно расстроена. Похоже, она не в настроении разговаривать.>') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','С чего бы ему вот так убегать?',`text0_1_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','<Фиона сильно расстроена. Похоже, она не в настроении разговаривать.>',`text2_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text2_1_loc8`) VALUES (16948,'Так-так... Смотри, кто пришел!') ON DUPLICATE KEY UPDATE `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Так-так... Смотри, кто пришел!',`text2_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16951,'Гидвин где-то поблизости... Я знаю. Интуиция паладина.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Гидвин где-то поблизости... Я знаю. Интуиция паладина.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16957,'Ты предлагаешь неплохую возможность, |3-6($r). Я поразмыслю над этим.$B$BВсе, хорошо, я подумал. Конечно, присоединюсь к вам – уже и так задержался в часовне Последней Надежды. Как тот гном у писсуара, я должен держать... кхм, нос по ветру! Хе-хе!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты предлагаешь неплохую возможность, |3-6($r). Я поразмыслю над этим.$B$BВсе, хорошо, я подумал. Конечно, присоединюсь к вам – уже и так задержался в часовне Последней Надежды. Как тот гном у писсуара, я должен держать... кхм, нос по ветру! Хе-хе!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16958,'Эй, хозяин. Если нужна помощь в сопровождении каравана, дай старине Бизилю знать.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эй, хозяин. Если нужна помощь в сопровождении каравана, дай старине Бизилю знать.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16961,'Не обращай внимания на беспорядок, мы только обустраиваемся.$B$BТвоему отдыху это никак не помешает! Расслабься, потрать немного денег... здесь есть все – от менял до прачечных и инструкторов по рыбалке.$B$BА если кто-то будет тебе мешать, дай мне знать – я с ними разберусь.$B$BКстати, меня зовут Мида... я местный босс.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Не обращай внимания на беспорядок, мы только обустраиваемся.$B$BТвоему отдыху это никак не помешает! Расслабься, потрать немного денег... здесь есть все – от менял до прачечных и инструкторов по рыбалке.$B$BА если кто-то будет тебе мешать, дай мне знать – я с ними разберусь.$B$BКстати, меня зовут Мида... я местный босс.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16963,'Неплохо найти попутчика. Впереди лежит безлюдная дорога.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Неплохо найти попутчика. Впереди лежит безлюдная дорога.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16965,'Не сейчас.$B$BМне надо кое-что сделать для дамы.$B$BОна не должна таскаться по городу, как старая кляча, особенно если ей придется иметь дело с вождем.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не сейчас.$B$BМне надо кое-что сделать для дамы.$B$BОна не должна таскаться по городу, как старая кляча, особенно если ей придется иметь дело с вождем.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16966,'В Чумной лес мало кто так далеко заходит, в основном одни чудища.$B$BВам чем-нибудь помочь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','В Чумной лес мало кто так далеко заходит, в основном одни чудища.$B$BВам чем-нибудь помочь?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16968,'Ага, иероглифы говорят, что можно заставить механизм заработать.$B$BОсталось лишь понять – как...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ага, иероглифы говорят, что можно заставить механизм заработать.$B$BОсталось лишь понять – как...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16970,'Сигнальная ракета запущена.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Сигнальная ракета запущена.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16973,'У деревьев на нагорье крепкая древесина. А у некоторых... каменная. Я даже и не пытаюсь это понять.$B$BУ нас есть крошшеры с алмазными лезвиями для добычи древесины, но Альянс их постоянно уничтожает.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','У деревьев на нагорье крепкая древесина. А у некоторых... каменная. Я даже и не пытаюсь это понять.$B$BУ нас есть крошшеры с алмазными лезвиями для добычи древесины, но Альянс их постоянно уничтожает.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16975,'Вот уже некоторое время у нашего народа добрые отношения с Громовым Молотом.$b$bНекоторые из нас живут там. Те, кто считает эту землю своим домом и готовы ее защищать.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вот уже некоторое время у нашего народа добрые отношения с Громовым Молотом.$b$bНекоторые из нас живут там. Те, кто считает эту землю своим домом и готовы ее защищать.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (16979,'Даже в наше мирное время, когда Король-лич пал, а правление Кел\'Тузада подошло к концу, Братство существует и действует.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Даже в наше мирное время, когда Король-лич пал, а правление Кел\'Тузада подошло к концу, Братство существует и действует.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16980,'У Хаккара много имен. Одни зовут его Богом Крови, другие – Свежевателем Душ. Но как его ни назови, он – существо, обладающее огромной силой и с очень злыми намерениями по отношению к нашему миру.$b$bВо время полета я обнаружил его храм на ранней стадии строительства и обрушил его в Болото Печали. К сожалению, похоже, что мы лишь помогли племени Атал\'ай, дав им понять, что их попыткам призвать Хаккара не будут мешать. Многие драконы, в чьи обязанности входила охрана замка, были затронуты порчей. И с каждым новым днем присутствие Свежевателя Душ все растет.$b$bЯ не могу справиться с этим один. Но вместе, думаю, мы успеем остановиться это безумие.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','У Хаккара много имен. Одни зовут его Богом Крови, другие – Свежевателем Душ. Но как его ни назови, он – существо, обладающее огромной силой и с очень злыми намерениями по отношению к нашему миру.$b$bВо время полета я обнаружил его храм на ранней стадии строительства и обрушил его в Болото Печали. К сожалению, похоже, что мы лишь помогли племени Атал\'ай, дав им понять, что их попыткам призвать Хаккара не будут мешать. Многие драконы, в чьи обязанности входила охрана замка, были затронуты порчей. И с каждым новым днем присутствие Свежевателя Душ все растет.$b$bЯ не могу справиться с этим один. Но вместе, думаю, мы успеем остановиться это безумие.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16981,'Сейчас, когда парк Штормграда разрушен Смертокрылом, мы вынуждены на время вернуться в Дарнас.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Сейчас, когда парк Штормграда разрушен Смертокрылом, мы вынуждены на время вернуться в Дарнас.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (16982,'Высокорожденные вернулись в этот мир, и вместе с ними вернулись забытые знания.$B$BЧто ты $gпринес:принесла; мне?','Высокорожденные вернулись в этот мир, и вместе с ними вернулись забытые знания.$B$BЧто ты $gпринес:принесла; мне?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Высокорожденные вернулись в этот мир, и вместе с ними вернулись забытые знания.$B$BЧто ты $gпринес:принесла; мне?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Высокорожденные вернулись в этот мир, и вместе с ними вернулись забытые знания.$B$BЧто ты $gпринес:принесла; мне?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (16984,'Если ты ищешь чародея-кузнеца, чтобы дать новую жизнь твоим вещам, маг высокорожденных ждет тебя в своей лавке в квартале магов.','Если ты ищешь чародея-кузнеца, чтобы дать новую жизнь твоим вещам, маг высокорожденных ждет тебя в своей лавке в квартале магов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если ты ищешь чародея-кузнеца, чтобы дать новую жизнь твоим вещам, маг высокорожденных ждет тебя в своей лавке в квартале магов.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Если ты ищешь чародея-кузнеца, чтобы дать новую жизнь твоим вещам, маг высокорожденных ждет тебя в своей лавке в квартале магов.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16986,'Чо\'Галл пытается создать некое оружие, о котором мы имеем лишь смутное представление. Это некий могучий артефакт, оружие, выкованное с помощью силы древнего бога. Мы должны добраться до него раньше, чем Чо\'Галл завершит свое творение.$B$BВсе остальное – дело десятое. Пожертвовать можно кем угодно, включая и нас с тобой.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Чо\'Галл пытается создать некое оружие, о котором мы имеем лишь смутное представление. Это некий могучий артефакт, оружие, выкованное с помощью силы древнего бога. Мы должны добраться до него раньше, чем Чо\'Галл завершит свое творение.$B$BВсе остальное – дело десятое. Пожертвовать можно кем угодно, включая и нас с тобой.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16987,'Ты моего папашу знаешь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты моего папашу знаешь?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (16988,'Бедняжка! Наверное, у тебя совсем не осталось сил.$B$BВот еда и питье. Отдыхай спокойно – здесь ты в безопасности.','Бедняжка! Наверное, у тебя совсем не осталось сил.$B$BВот еда и питье. Отдыхай спокойно – здесь ты в безопасности.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Бедняжка! Наверное, у тебя совсем не осталось сил.$B$BВот еда и питье. Отдыхай спокойно – здесь ты в безопасности.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Бедняжка! Наверное, у тебя совсем не осталось сил.$B$BВот еда и питье. Отдыхай спокойно – здесь ты в безопасности.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (16989,'Ищешь что-нибудь перекусить,|3-6($c)?$B$BИли тебе просто нужно где-нибудь отдохнуть, проветрить старые кости?','Ищешь что-нибудь перекусить,|3-6($c)?$B$BИли тебе просто нужно где-нибудь отдохнуть, проветрить старые кости?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ищешь что-нибудь перекусить,|3-6($c)?$B$BИли тебе просто нужно где-нибудь отдохнуть, проветрить старые кости?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ищешь что-нибудь перекусить,|3-6($c)?$B$BИли тебе просто нужно где-нибудь отдохнуть, проветрить старые кости?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16990,'Как хорошо, что кто-то пришел! Тут творится нечто невообразимое! Невообразимее обычного!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Как хорошо, что кто-то пришел! Тут творится нечто невообразимое! Невообразимее обычного!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16991,'От имени просвещенного и сохраняющего нейтралитет картеля Хитрой Шестеренки приветствуем тебя в Веслотопи! Мы с гордостью носим звание единственного приморского курорта и крупнейшего производителя оружия в Восточных королевствах.$B$BК югу отсюда идет какая-то войнушка, но за городскими стенами царит мир и покой. Так что располагайся, отдыхай, выпей чего-нибудь и не думай о делах. Иначе мои вышибалы быстро напомнят тебе, что значит "нейтральная территория".') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','От имени просвещенного и сохраняющего нейтралитет картеля Хитрой Шестеренки приветствуем тебя в Веслотопи! Мы с гордостью носим звание единственного приморского курорта и крупнейшего производителя оружия в Восточных королевствах.$B$BК югу отсюда идет какая-то войнушка, но за городскими стенами царит мир и покой. Так что располагайся, отдыхай, выпей чего-нибудь и не думай о делах. Иначе мои вышибалы быстро напомнят тебе, что значит "нейтральная территория".',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16995,'Торбен Запрыгуль, инженерные решения по телепортации, к вашим услугам!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Торбен Запрыгуль, инженерные решения по телепортации, к вашим услугам!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (16996,'Привет.$B$BХочешь поставить своих питомцев в стойло или ищешь пропавшего спутника?','Привет.$B$BХочешь поставить своих питомцев в стойло или ищешь пропавшего спутника?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Привет.$B$BХочешь поставить своих питомцев в стойло или ищешь пропавшего спутника?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Привет.$B$BХочешь поставить своих питомцев в стойло или ищешь пропавшего спутника?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (16997,'Привет.$B$BИщешь пропавшего спутника?','Привет.$B$BИщешь пропавшего спутника?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Привет.$B$BИщешь пропавшего спутника?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Привет.$B$BИщешь пропавшего спутника?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (16998,'У нас будет время поговорить, когда мы выберемся на поверхность.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','У нас будет время поговорить, когда мы выберемся на поверхность.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17000,'Привет! Мое имя Тей\'телан Кровавый Взор. Я провел большую часть жизни, обучаясь колдовству и объединяя своих единомышленников эльфов крови в Реликварий.$B$BВидишь ли, по миру рассеяны древние мощные артефакты, и я собираюсь с их помощью освободить мой народ. Я хочу снова сделать эльфов гордым, непобедимым народом.$B$BМагия – удивительная вещь, и я уверяю тебя, что при наличии определенных знаний ею можно пользоваться абсолютно без вреда для себя.$B$BСейчас другие народы Альянса и даже Орда смеются над нами, нашей полуразрушенной столицей, статуями Солнечного Скитальца и многочисленными ошибками, которые мы совершили.$B$BНо скоро этому придет конец.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Привет! Мое имя Тей\'телан Кровавый Взор. Я провел большую часть жизни, обучаясь колдовству и объединяя своих единомышленников эльфов крови в Реликварий.$B$BВидишь ли, по миру рассеяны древние мощные артефакты, и я собираюсь с их помощью освободить мой народ. Я хочу снова сделать эльфов гордым, непобедимым народом.$B$BМагия – удивительная вещь, и я уверяю тебя, что при наличии определенных знаний ею можно пользоваться абсолютно без вреда для себя.$B$BСейчас другие народы Альянса и даже Орда смеются над нами, нашей полуразрушенной столицей, статуями Солнечного Скитальца и многочисленными ошибками, которые мы совершили.$B$BНо скоро этому придет конец.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17002,'Я собрала все что можно среди обломков, но долго тут не продержусь...') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я собрала все что можно среди обломков, но долго тут не продержусь...',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`,`text3_0_loc8`,`text4_0_loc8`) VALUES (17004,'Ты и твои сородичи заплатят за это, |3-6($r).','Ты заодно с этими чудовищами? Значит, и ты когда-нибудь сгоришь дотла!','<Исполинский черный дракон, покрытый разверстыми ранами, пристально и злобно разглядывает вас. Глаза его не мигают.>','<Свирепый черный дракон бьется в цепях. Лучше не подходить к нему близко.>','Мои оковы не так уж нерушимы, |3-6($c). Молись, чтобы не оказаться рядом, когда я примусь мстить.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты и твои сородичи заплатят за это, |3-6($r).',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Ты заодно с этими чудовищами? Значит, и ты когда-нибудь сгоришь дотла!',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','<Исполинский черный дракон, покрытый разверстыми ранами, пристально и злобно разглядывает вас. Глаза его не мигают.>',`text2_0_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','<Свирепый черный дракон бьется в цепях. Лучше не подходить к нему близко.>',`text3_0_loc8`), `text4_0_loc8`=IF(`text4_0_loc8` IS NULL OR `text4_0_loc8`='','Мои оковы не так уж нерушимы, |3-6($c). Молись, чтобы не оказаться рядом, когда я примусь мстить.',`text4_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17005,'Драконы – не просто звери, как свиньи или коровы. В них воплотилась вся сила природы. Могучая... Первозданная.$B$BОбуздать их – все равно что подчинить своей воле целый мир.$B$BВзяться за поводья дракона – значит, принять судьбу в свои руки.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Драконы – не просто звери, как свиньи или коровы. В них воплотилась вся сила природы. Могучая... Первозданная.$B$BОбуздать их – все равно что подчинить своей воле целый мир.$B$BВзяться за поводья дракона – значит, принять судьбу в свои руки.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17006,'Я начала заниматься снадобьями задолго до войн между картелями и не собираюсь останавливаться.$B$BПока есть покупатели, я не уйду из дела!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я начала заниматься снадобьями задолго до войн между картелями и не собираюсь останавливаться.$B$BПока есть покупатели, я не уйду из дела!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17007,'Вот это была огневая мощь! Может быть, в этих мелких гоблинах и вправду что-то есть.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вот это была огневая мощь! Может быть, в этих мелких гоблинах и вправду что-то есть.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17009,'Если тебя послала Кили, сразу говорю – отстань. Надо перебить приспешников Сумеречного культа.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если тебя послала Кили, сразу говорю – отстань. Надо перебить приспешников Сумеречного культа.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17010,'Видишь там, впереди, проход, $gпарень:милая;?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Видишь там, впереди, проход, $gпарень:милая;?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17011,'Это засада.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Это засада.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17012,'О да, $gмой мальчик:девочка моя;! Я уже 4 раза там был.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','О да, $gмой мальчик:девочка моя;! Я уже 4 раза там был.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17013,'Чертовски верно!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Чертовски верно!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17014,'Да-да, уже иду, $gпаренек:милая;. Только пробегусь еще разок по рынку ради развлечения.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да-да, уже иду, $gпаренек:милая;. Только пробегусь еще разок по рынку ради развлечения.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17016,'Хо-хо! Здесь повсюду блестяшки!$B$BТы посмотри, что я тут накопал...$B$BЭто же дыхательная шляпа!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Хо-хо! Здесь повсюду блестяшки!$B$BТы посмотри, что я тут накопал...$B$BЭто же дыхательная шляпа!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17019,'Приветствую тебя, |3-6($r). Я лорд Итар из рода зеленых драконов.$B$BЯ пришел, чтобы освободить мой народ от зла, таящегося в этом храме. Ты мне поможешь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приветствую тебя, |3-6($r). Я лорд Итар из рода зеленых драконов.$B$BЯ пришел, чтобы освободить мой народ от зла, таящегося в этом храме. Ты мне поможешь?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17020,'Видишь? Это моя дыхательная шляпа?$B$BТеперь Бадду не придется сосать моллюсков, о нет...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Видишь? Это моя дыхательная шляпа?$B$BТеперь Бадду не придется сосать моллюсков, о нет...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17024,'Если Верховный совет примет единогласное решение, рамкахены объявят войну Неферсету.$B$BУ нас почти нет шансов, но мой брат должен понять – с приспешниками Смертокрыла невозможны никакие договоренности.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если Верховный совет примет единогласное решение, рамкахены объявят войну Неферсету.$B$BУ нас почти нет шансов, но мой брат должен понять – с приспешниками Смертокрыла невозможны никакие договоренности.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17026,'Ты кто – шакал неферсетов? Теперь они таких посылают выполнять всю грязную работу? Отвечай!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты кто – шакал неферсетов? Теперь они таких посылают выполнять всю грязную работу? Отвечай!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17027,'Все не так уж плохо...$B$BВедь со мной моя дыхательная шляпа!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Все не так уж плохо...$B$BВедь со мной моя дыхательная шляпа!',`text0_0_loc8`);
