INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17030,'Ты нужен для укрепления боевой мощи Орды!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты нужен для укрепления боевой мощи Орды!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17031,'Ты здесь, чтобы помочь? Гора Хиджал пылает!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты здесь, чтобы помочь? Гора Хиджал пылает!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17032,'У этого гигантского кальмара не было ни одного шанса. Орудия "Верна" перезаряжены и готовы к бою... теперь нужно просто ждать.$B$BОн вернется.$B$BВот увидишь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','У этого гигантского кальмара не было ни одного шанса. Орудия "Верна" перезаряжены и готовы к бою... теперь нужно просто ждать.$B$BОн вернется.$B$BВот увидишь.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17033,'Ах… У меня здесь нечасто бывают гости.$b$bПожалуйста, присядь на минутку.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ах… У меня здесь нечасто бывают гости.$b$bПожалуйста, присядь на минутку.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17034,'Альянс нуждается в тебе! Герой, ответь на зов!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Альянс нуждается в тебе! Герой, ответь на зов!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17035,'Ты здесь, чтобы помочь нам? Хиджал объят огнем!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты здесь, чтобы помочь нам? Хиджал объят огнем!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17036,'Видишь вон ту кучу обломков? Это был дом нашей семьи на протяжении пяти поколений.$B$BИ мы его отвоюем.$B$BНас мало... Но мы – Громовой Молот! Ты со мной?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Видишь вон ту кучу обломков? Это был дом нашей семьи на протяжении пяти поколений.$B$BИ мы его отвоюем.$B$BНас мало... Но мы – Громовой Молот! Ты со мной?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17038,'Ты не меня ищешь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты не меня ищешь?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17040,'Отец дал мне пострелять!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Отец дал мне пострелять!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17042,'Какой ужас! Мы возвращаемся после спасения Подземья – и что же видим?$B$BВонючих прихвостней Сумеречного Молота!$B$BХорошо, что ты здесь, наведешь тут порядок!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Какой ужас! Мы возвращаемся после спасения Подземья – и что же видим?$B$BВонючих прихвостней Сумеречного Молота!$B$BХорошо, что ты здесь, наведешь тут порядок!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17051,'На теле дворфа множество ран. Должно быть, приспешники Сумеречного Молота находят особое удовольствие в убийстве дворфов.','На теле дворфа множество ран. Должно быть, приспешники Сумеречного Молота находят особое удовольствие в убийстве дворфов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','На теле дворфа множество ран. Должно быть, приспешники Сумеречного Молота находят особое удовольствие в убийстве дворфов.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','На теле дворфа множество ран. Должно быть, приспешники Сумеречного Молота находят особое удовольствие в убийстве дворфов.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17052,'Надо отдать должное этим, из Сумеречного Молота... Где не хватает умения, там они берут числом и упорством. В нашей последней схватке они себя неплохо показали.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Надо отдать должное этим, из Сумеречного Молота... Где не хватает умения, там они берут числом и упорством. В нашей последней схватке они себя неплохо показали.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17053,'Эти Дунвальды – крепкие ребята, но малость самоуверенные. Мне кажется, что они слишком часто ищут приключений на свою голову.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Эти Дунвальды – крепкие ребята, но малость самоуверенные. Мне кажется, что они слишком часто ищут приключений на свою голову.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17055,'Ха! Мои братья только и ждут случая, чтобы подраться. Я еле-еле их сдерживал до сих пор.$B$BТы с нами?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ха! Мои братья только и ждут случая, чтобы подраться. Я еле-еле их сдерживал до сих пор.$B$BТы с нами?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17061,'Как настоящий Дунвальд. Ты мне нравишься.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Как настоящий Дунвальд. Ты мне нравишься.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17068,'<Устройство затрещало и загудело, когда вы к нему приблизились.>') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','<Устройство затрещало и загудело, когда вы к нему приблизились.>',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17072,'Время пощадило эту гигантскую статую.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Время пощадило эту гигантскую статую.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17073,'Хотя она выглядит довольно древней, время пощадило эту статую.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Хотя она выглядит довольно древней, время пощадило эту статую.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17074,'Судя по цвету, это должен быть Страж.$b$bВы видите небольшую выемку в том месте, куда вставляется пешка.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Судя по цвету, это должен быть Страж.$b$bВы видите небольшую выемку в том месте, куда вставляется пешка.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17075,'Эта красная статуя выглядит точно так же, как пешка-часовой, которую вы держите в руках.$b$bВ статуе видна небольшая выемка, по размеру соответствующая пешке.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эта красная статуя выглядит точно так же, как пешка-часовой, которую вы держите в руках.$b$bВ статуе видна небольшая выемка, по размеру соответствующая пешке.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17080,'Надеюсь кирка у тебя с собой. Тут самое лучшее место, чтобы откопать какой-нибудь древний артефакт.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Надеюсь кирка у тебя с собой. Тут самое лучшее место, чтобы откопать какой-нибудь древний артефакт.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17085,'Когда с кланом Пылающего Клинка было покончено, мы, мастера клинка, поклялись избавить своих соплеменников от власти демонов.$B$BМы добьемся этого, но моя честь по-прежнему взывает к мести.$B$BЯ должен сражаться во славу Орды – и обучать этому других воинов, пока не паду в битве. Это единственный путь для меня.','Когда с кланом Пылающего Клинка было покончено, мы, мастера клинка, поклялись избавить своих соплеменников от власти демонов.$B$BМы добьемся этого, но моя честь по-прежнему взывает к мести.$B$BЯ должна сражаться во славу Орды – и обучать этому других воинов, пока не паду в битве. Это единственный путь для меня.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Когда с кланом Пылающего Клинка было покончено, мы, мастера клинка, поклялись избавить своих соплеменников от власти демонов.$B$BМы добьемся этого, но моя честь по-прежнему взывает к мести.$B$BЯ должен сражаться во славу Орды – и обучать этому других воинов, пока не паду в битве. Это единственный путь для меня.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Когда с кланом Пылающего Клинка было покончено, мы, мастера клинка, поклялись избавить своих соплеменников от власти демонов.$B$BМы добьемся этого, но моя честь по-прежнему взывает к мести.$B$BЯ должна сражаться во славу Орды – и обучать этому других воинов, пока не паду в битве. Это единственный путь для меня.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17086,'Когда с кланом Пылающего Клинка было покончено, мы, мастера клинка, поклялись избавить своих соплеменников от власти демонов.$B$BМы добьемся этого, но моя честь по-прежнему взывает к мести.$B$BЯ должен сражаться во славу Орды – и обучать этому других воинов, пока не паду в битве. Это единственный путь для меня.$B$BНу что, приступим к обучению?','Когда с кланом Пылающего Клинка было покончено, мы, мастера клинка, поклялись избавить своих соплеменников от власти демонов.$B$BМы добьемся этого, но моя честь по-прежнему взывает к мести.$B$BЯ должна сражаться во славу Орды – и обучать этому других воинов, пока не паду в битве. Это единственный путь для меня.$B$BНу что, приступим к обучению?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Когда с кланом Пылающего Клинка было покончено, мы, мастера клинка, поклялись избавить своих соплеменников от власти демонов.$B$BМы добьемся этого, но моя честь по-прежнему взывает к мести.$B$BЯ должен сражаться во славу Орды – и обучать этому других воинов, пока не паду в битве. Это единственный путь для меня.$B$BНу что, приступим к обучению?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Когда с кланом Пылающего Клинка было покончено, мы, мастера клинка, поклялись избавить своих соплеменников от власти демонов.$B$BМы добьемся этого, но моя честь по-прежнему взывает к мести.$B$BЯ должна сражаться во славу Орды – и обучать этому других воинов, пока не паду в битве. Это единственный путь для меня.$B$BНу что, приступим к обучению?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17087,'Охрана банка и сокровищ Орды – занятие куда более приятное, чем торговля всякой всячиной из этой железной клетки.$B$BЯ бы в жизни не поменялся ни с одним из этих заумных гоблинов.','Охрана банка и сокровищ Орды – занятие куда более приятное, чем торговля всякой всячиной из этой железной клетки.$B$BЯ бы в жизни не поменялась ни с одним из этих заумных гоблинов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Охрана банка и сокровищ Орды – занятие куда более приятное, чем торговля всякой всячиной из этой железной клетки.$B$BЯ бы в жизни не поменялся ни с одним из этих заумных гоблинов.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Охрана банка и сокровищ Орды – занятие куда более приятное, чем торговля всякой всячиной из этой железной клетки.$B$BЯ бы в жизни не поменялась ни с одним из этих заумных гоблинов.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17089,'Недавно Сумеречный Молот захватил эти некогда чистые воды, а также все прилегающие к ним земли.$B$BОни осквернили мое озеро. Я мечтаю о том, чтобы их не стало, и я смогла бы его очистить.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Недавно Сумеречный Молот захватил эти некогда чистые воды, а также все прилегающие к ним земли.$B$BОни осквернили мое озеро. Я мечтаю о том, чтобы их не стало, и я смогла бы его очистить.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17091,'Здесь. На этой земле орки и люди годами проливали кровь друг друга. В миле отсюда Каменор – форпост орков для вторжения в наши земли.$B$BЭто там они собирали свои армии задолго до того, как мы узнали об их существовании. Именно здесь начались три войны – начались с атаки на маленький городок Альянса на западе.$B$BТам я родилась. Там погибли мои родители, спасая меня.$B$BНо ни к чему ворошить прошлое... Я здесь, чтобы победить в этой войне.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Здесь. На этой земле орки и люди годами проливали кровь друг друга. В миле отсюда Каменор – форпост орков для вторжения в наши земли.$B$BЭто там они собирали свои армии задолго до того, как мы узнали об их существовании. Именно здесь начались три войны – начались с атаки на маленький городок Альянса на западе.$B$BТам я родилась. Там погибли мои родители, спасая меня.$B$BНо ни к чему ворошить прошлое... Я здесь, чтобы победить в этой войне.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17095,'Привет. Ты здесь недавно, да? Твой дом тоже разрушили? Можешь посидеть со мной, если хочешь.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Привет. Ты здесь недавно, да? Твой дом тоже разрушили? Можешь посидеть со мной, если хочешь.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17097,'Приятно познакомиться, $gюноша:милая девушка;.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приятно познакомиться, $gюноша:милая девушка;.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17098,'Они застали нас врасплох... Накинулись со всех сторон одновременно – появлялись даже из-под земли, с воздуха... Почти все отряды грифонов были рассеяны, и полегло слишком много добрых дворфов.$B$BМы бы все погибли, если бы Киган не собрал нас вместе. Он спас мне жизнь. И теперь, по крайней мере, у нас есть шанс.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Они застали нас врасплох... Накинулись со всех сторон одновременно – появлялись даже из-под земли, с воздуха... Почти все отряды грифонов были рассеяны, и полегло слишком много добрых дворфов.$B$BМы бы все погибли, если бы Киган не собрал нас вместе. Он спас мне жизнь. И теперь, по крайней мере, у нас есть шанс.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17099,'Ты явно не из этих мест. Но для меня это мало что значит. Я готов рисковать жизнью за любого, кто делает свое дело как надо.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты явно не из этих мест. Но для меня это мало что значит. Я готов рисковать жизнью за любого, кто делает свое дело как надо.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17100,'Я пришел сюда много лет назад, чтобы излечить наших проклятых братьев. $B$BМагтур принял меня с распростертыми объятьями. Мы стали лучшими друзьями.$B$BА теперь он умирает на моих глазах.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я пришел сюда много лет назад, чтобы излечить наших проклятых братьев. $B$BМагтур принял меня с распростертыми объятьями. Мы стали лучшими друзьями.$B$BА теперь он умирает на моих глазах.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17102,'Выглядишь так, будто мы сможем на тебе заработать. Как насчет раунда в Горниле Крови, дружок?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Выглядишь так, будто мы сможем на тебе заработать. Как насчет раунда в Горниле Крови, дружок?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17103,'Грифон, кажется, ранен. Возможно, ему поможет магическое исцеление или просто первая помощь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Грифон, кажется, ранен. Возможно, ему поможет магическое исцеление или просто первая помощь.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17104,'Грифон внимательно смотрит на вас, явно чувствуя знакомый запах вашей одежды.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Грифон внимательно смотрит на вас, явно чувствуя знакомый запах вашей одежды.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17105,'Грифон, кажется, попал в ловушку. Однако разбить его оковы, похоже, не составит труда.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Грифон, кажется, попал в ловушку. Однако разбить его оковы, похоже, не составит труда.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17107,'<Видение Изеры колышется перед вами словно во сне. Никто вокруг не замечает ее, и вы чувствуете, что все внимание Изеры сосредоточено на вас.>') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','<Видение Изеры колышется перед вами словно во сне. Никто вокруг не замечает ее, и вы чувствуете, что все внимание Изеры сосредоточено на вас.>',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17108,'<Подобное дымке видение Изеры отвлеченно парит перед вами. Спустя миг оно обращается к вам.>$B$BДолгие годы я видела Авиану в своих снах. Я гадала, вернется ли она когда-то к нам. Боюсь, ее дух потерял часть того света, что наполнял его…$B$BОднако сейчас мы должны в первую очередь думать о спасении горы.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','<Подобное дымке видение Изеры отвлеченно парит перед вами. Спустя миг оно обращается к вам.>$B$BДолгие годы я видела Авиану в своих снах. Я гадала, вернется ли она когда-то к нам. Боюсь, ее дух потерял часть того света, что наполнял его…$B$BОднако сейчас мы должны в первую очередь думать о спасении горы.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17110,'Как здесь прекрасно, правда?$B$BХотя, конечно, немного жарковато и суховато...') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Как здесь прекрасно, правда?$B$BХотя, конечно, немного жарковато и суховато...',`text0_1_loc8`);
