INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17111,'Отец всегда говорил – здоровые парни сильные, но неповоротливые.$B$BЭх, папа, тебе точно никогда не встречался вот такой.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Отец всегда говорил – здоровые парни сильные, но неповоротливые.$B$BЭх, папа, тебе точно никогда не встречался вот такой.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
