INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17117,'<Огромный Древний все еще относится к вам с опаской, но обращается как к союзнику.>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Огромный Древний все еще относится к вам с опаской, но обращается как к союзнику.>',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17118,'По прибытии в Каменор я взяла на себя заботу о Хелгруме. Под моим присмотром он оттачивал свои навыки следопыта... он стал мои постоянным и единственным напарником.$B$BЯ считала себя сильной, думала, никакое горе не сможет меня сломить. Потом я увидела, как люди тыкали мечами в тело Хелгрума... моего единственного... Тогда я поняла, как заблуждалась, но было уже поздно.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','По прибытии в Каменор я взяла на себя заботу о Хелгруме. Под моим присмотром он оттачивал свои навыки следопыта... он стал мои постоянным и единственным напарником.$B$BЯ считала себя сильной, думала, никакое горе не сможет меня сломить. Потом я увидела, как люди тыкали мечами в тело Хелгрума... моего единственного... Тогда я поняла, как заблуждалась, но было уже поздно.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17119,'Я принц Надун из Рамкахена. Племя неферсетов обратилось против других тол\'виров.$B$BПомоги мне бежать – тогда я смогу убедить своего брата короля начать войну с отступниками!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я принц Надун из Рамкахена. Племя неферсетов обратилось против других тол\'виров.$B$BПомоги мне бежать – тогда я смогу убедить своего брата короля начать войну с отступниками!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17126,'Профессии собирателей позволят тебе добывать сырье, которое может быть использовано в профессиях, связанных с изготовлением разных вещей и продуктов. Можно собирать травы, руду, минералы и драгоценные камни, можно снимать шкуры с убитых монстров.\r\n\r\nСобранное сырье можно продавать на аукционе, а можно подобрать такую пару профессий, чтобы уметь создавать из этого сырья продукты или вещи.','Профессии собирателей позволят тебе добывать сырье, которое может быть использовано в профессиях, связанных с изготовлением разных вещей и продуктов. Можно собирать травы, руду, минералы и драгоценные камни, можно снимать шкуры с убитых монстров.\r\n\r\nСобранное сырье можно продавать на аукционе, а можно подобрать такую пару профессий, чтобы уметь создавать из этого сырья продукты или вещи.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Профессии собирателей позволят тебе добывать сырье, которое может быть использовано в профессиях, связанных с изготовлением разных вещей и продуктов. Можно собирать травы, руду, минералы и драгоценные камни, можно снимать шкуры с убитых монстров.\r\n\r\nСобранное сырье можно продавать на аукционе, а можно подобрать такую пару профессий, чтобы уметь создавать из этого сырья продукты или вещи.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Профессии собирателей позволят тебе добывать сырье, которое может быть использовано в профессиях, связанных с изготовлением разных вещей и продуктов. Можно собирать травы, руду, минералы и драгоценные камни, можно снимать шкуры с убитых монстров.\r\n\r\nСобранное сырье можно продавать на аукционе, а можно подобрать такую пару профессий, чтобы уметь создавать из этого сырья продукты или вещи.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17127,'Ремесленные профессии позволяют перерабатывать сырье в предметы, которые ты можешь использовать сам, отдать союзнику или продать на аукционе.\r\n\r\nЗачастую они связаны с определенным типом собирательства или добычи ресурсов, что позволяет обеспечивать себя сырьем самостоятельно. Помимо этого, необходимые материалы можно приобретать на аукционе.','Ремесленные профессии позволяют перерабатывать сырье в предметы, которые ты можешь использовать сама, отдать союзнику или продать на аукционе.\r\n\r\nЗачастую они связаны с определенным типом собирательства или добычи ресурсов, что позволяет обеспечивать себя сырьем самостоятельно. Помимо этого, необходимые материалы можно приобретать на аукционе.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ремесленные профессии позволяют перерабатывать сырье в предметы, которые ты можешь использовать сам, отдать союзнику или продать на аукционе.\r\n\r\nЗачастую они связаны с определенным типом собирательства или добычи ресурсов, что позволяет обеспечивать себя сырьем самостоятельно. Помимо этого, необходимые материалы можно приобретать на аукционе.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ремесленные профессии позволяют перерабатывать сырье в предметы, которые ты можешь использовать сама, отдать союзнику или продать на аукционе.\r\n\r\nЗачастую они связаны с определенным типом собирательства или добычи ресурсов, что позволяет обеспечивать себя сырьем самостоятельно. Помимо этого, необходимые материалы можно приобретать на аукционе.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17128,'Профессия травничество дает возможность находить и собирать разные травы. Их можно продать на аукционе или использовать при изучении профессий алхимия и начертание.\r\n\r\nТравники высокого уровня также могут использовать полученные знания для того, чтобы лечить себя.','Травничество дает возможность находить и собирать разные травы. Их можно продать на аукционе или использовать при овладении профессиями алхимии и начертания.\r\n\r\nТравники высокого уровня также могут использовать полученные знания для того, чтобы лечить себя.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Профессия травничество дает возможность находить и собирать разные травы. Их можно продать на аукционе или использовать при изучении профессий алхимия и начертание.\r\n\r\nТравники высокого уровня также могут использовать полученные знания для того, чтобы лечить себя.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Травничество дает возможность находить и собирать разные травы. Их можно продать на аукционе или использовать при овладении профессиями алхимии и начертания.\r\n\r\nТравники высокого уровня также могут использовать полученные знания для того, чтобы лечить себя.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17129,'Профессия горное дело дает возможность находить и собирать руду, минералы или камни из природных и подземных месторождений. Собранные материалы можно продавать на аукционе или использовать при изучении профессий кузнечное дело, инженерное дело и ювелирное дело.\r\n\r\nПо мере развития профессии горное дело обладатель этой профессии становится сильнее и выносливее.\r\n\r\nДля занятия горным делом потребуется кирка, ее можно купить у торговцев.','Профессия горное дело дает возможность находить и собирать руду, минералы или камни из природных и подземных месторождений. Собранные материалы можно продавать на аукционе или использовать при изучении профессий кузнечное дело, инженерное дело и ювелирное дело.\r\n\r\nПо мере развития профессии горное дело обладатель этой профессии становится сильнее и выносливее.\r\n\r\nДля занятия горным делом потребуется кирка, ее можно купить у торговцев.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Профессия горное дело дает возможность находить и собирать руду, минералы или камни из природных и подземных месторождений. Собранные материалы можно продавать на аукционе или использовать при изучении профессий кузнечное дело, инженерное дело и ювелирное дело.\r\n\r\nПо мере развития профессии горное дело обладатель этой профессии становится сильнее и выносливее.\r\n\r\nДля занятия горным делом потребуется кирка, ее можно купить у торговцев.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Профессия горное дело дает возможность находить и собирать руду, минералы или камни из природных и подземных месторождений. Собранные материалы можно продавать на аукционе или использовать при изучении профессий кузнечное дело, инженерное дело и ювелирное дело.\r\n\r\nПо мере развития профессии горное дело обладатель этой профессии становится сильнее и выносливее.\r\n\r\nДля занятия горным делом потребуется кирка, ее можно купить у торговцев.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17130,'Снятие шкур позволяет снимать и выделывать шкуры убитых монстров. Их можно продавать на аукционе или использовать в качестве сырья для кожевенного производства.\r\n\r\nУмелые скорняки зачастую становится знатоками анатомии, что повышает шанс нанести критический удар по цели.\r\n\r\nДля снятия шкур требуется специальный нож, который можно приобрести у обычных торговцев либо продавцов кожевенных товаров.','Снятие шкур позволяет снимать и выделывать шкуры убитых монстров. Их можно продавать на аукционе или использовать в качестве сырья для кожевенного производства.\r\n\r\nУмелые скорняки зачастую становится знатоками анатомии, что повышает шанс нанести критический удар по цели.\r\n\r\nДля снятия шкур требуется специальный нож, который можно приобрести у обычных торговцев либо продавцов кожевенных товаров.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Снятие шкур позволяет снимать и выделывать шкуры убитых монстров. Их можно продавать на аукционе или использовать в качестве сырья для кожевенного производства.\r\n\r\nУмелые скорняки зачастую становится знатоками анатомии, что повышает шанс нанести критический удар по цели.\r\n\r\nДля снятия шкур требуется специальный нож, который можно приобрести у обычных торговцев либо продавцов кожевенных товаров.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Снятие шкур позволяет снимать и выделывать шкуры убитых монстров. Их можно продавать на аукционе или использовать в качестве сырья для кожевенного производства.\r\n\r\nУмелые скорняки зачастую становится знатоками анатомии, что повышает шанс нанести критический удар по цели.\r\n\r\nДля снятия шкур требуется специальный нож, который можно приобрести у обычных торговцев либо продавцов кожевенных товаров.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17131,'Профессия алхимия дает возможность использовать травы и другие материалы для создания различных полезных эликсиров, зелий, масел, настоев и котлов. Используя эликсиры и настои, вы также получаете различные преимущества.\r\n\r\nПо мере развития профессии алхимия обладатель этой профессии также овладевает навыком трансмутации стихийных материалов и определенных минералов для их использования в других профессиях. Изучать алхимию очень удобно в паре с травничеством, это позволит вам использовать для эликсиров свои собственные травы.','Профессия алхимия дает возможность использовать травы и другие материалы для создания различных полезных эликсиров, зелий, масел, настоев и котлов. Используя эликсиры и настои, вы также получаете различные преимущества.\r\n\r\nПо мере развития профессии алхимия обладатель этой профессии также овладевает навыком трансмутации стихийных материалов и определенных минералов для их использования в других профессиях. Изучать алхимию очень удобно в паре с травничеством, это позволит вам использовать для эликсиров свои собственные травы.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Профессия алхимия дает возможность использовать травы и другие материалы для создания различных полезных эликсиров, зелий, масел, настоев и котлов. Используя эликсиры и настои, вы также получаете различные преимущества.\r\n\r\nПо мере развития профессии алхимия обладатель этой профессии также овладевает навыком трансмутации стихийных материалов и определенных минералов для их использования в других профессиях. Изучать алхимию очень удобно в паре с травничеством, это позволит вам использовать для эликсиров свои собственные травы.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Профессия алхимия дает возможность использовать травы и другие материалы для создания различных полезных эликсиров, зелий, масел, настоев и котлов. Используя эликсиры и настои, вы также получаете различные преимущества.\r\n\r\nПо мере развития профессии алхимия обладатель этой профессии также овладевает навыком трансмутации стихийных материалов и определенных минералов для их использования в других профессиях. Изучать алхимию очень удобно в паре с травничеством, это позволит вам использовать для эликсиров свои собственные травы.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17133,'Наложение чар дает возможность зачаровывать предметы, накладывая на них различные эффекты, распылять предметы и создавать магические жезлы и масла.\r\n\r\nЗачаровыватели с достаточно высоким навыком могут зачаровывать собственные кольца, чего больше не может никто.\r\n\r\nБольшую часть сырья для наложения чар можно получить при помощи распыления предметов – процесса, при котором предмет уничтожается. Поэтому наложение чар очень удобно изучать в паре с портняжным делом, так как при этом вы сможете распылять самостоятельно изготовленные предметы для получения сырья.\r\n\r\nЗачаровыватели также могут накладывать чары на свитки, чтобы продавать чары или сохранять их для использования в будущем. Свитки и другие чародейские предметы можно купить у торговцев.','Наложение чар дает возможность зачаровывать предметы, накладывая на них различные эффекты, распылять предметы и создавать магические жезлы и масла.\r\n\r\nЗачаровыватели с достаточно высоким навыком могут зачаровывать собственные кольца, чего больше не может никто.\r\n\r\nБольшую часть сырья для наложения чар можно получить при помощи распыления предметов – процесса, при котором предмет уничтожается. Поэтому наложение чар очень удобно изучать в паре с портняжным делом, так как при этом вы сможете распылять самостоятельно изготовленные предметы для получения сырья.\r\n\r\nЗачаровыватели также могут накладывать чары на свитки, чтобы продавать чары или сохранять их для использования в будущем. Свитки и другие чародейские предметы можно купить у торговцев.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Наложение чар дает возможность зачаровывать предметы, накладывая на них различные эффекты, распылять предметы и создавать магические жезлы и масла.\r\n\r\nЗачаровыватели с достаточно высоким навыком могут зачаровывать собственные кольца, чего больше не может никто.\r\n\r\nБольшую часть сырья для наложения чар можно получить при помощи распыления предметов – процесса, при котором предмет уничтожается. Поэтому наложение чар очень удобно изучать в паре с портняжным делом, так как при этом вы сможете распылять самостоятельно изготовленные предметы для получения сырья.\r\n\r\nЗачаровыватели также могут накладывать чары на свитки, чтобы продавать чары или сохранять их для использования в будущем. Свитки и другие чародейские предметы можно купить у торговцев.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Наложение чар дает возможность зачаровывать предметы, накладывая на них различные эффекты, распылять предметы и создавать магические жезлы и масла.\r\n\r\nЗачаровыватели с достаточно высоким навыком могут зачаровывать собственные кольца, чего больше не может никто.\r\n\r\nБольшую часть сырья для наложения чар можно получить при помощи распыления предметов – процесса, при котором предмет уничтожается. Поэтому наложение чар очень удобно изучать в паре с портняжным делом, так как при этом вы сможете распылять самостоятельно изготовленные предметы для получения сырья.\r\n\r\nЗачаровыватели также могут накладывать чары на свитки, чтобы продавать чары или сохранять их для использования в будущем. Свитки и другие чародейские предметы можно купить у торговцев.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17134,'Инженерное дело дает вам возможность создавать огромное количество полезных, удивительных и просто чудесных вещей: ружья, прицелы, мотоциклы, механических белок и многое другое. Однако, многими из этих предметов, например, очками, механическими дополнениями к поясам, сапогам, перчаткам и плащам, а также ветролетами сможете пользоваться лишь вы и другие инженеры.\r\n\r\nЧаще всего сырьем для этой профессии служат металлы и материалы, добываемые при помощи горного дела, поэтому удобно осваивать эти две профессии одновременно.\r\n\r\nДля создания многих предметов требуется кузнечный молот. Его и другие необходимые материалы для инженерного дела можно купить у торговцев.','Инженерное дело дает вам возможность создавать огромное количество полезных, удивительных и просто чудесных вещей: ружья, прицелы, мотоциклы, механических белок и многое другое. Однако, многими из этих предметов, например, очками, механическими дополнениями к поясам, сапогам, перчаткам и плащам, а также ветролетами сможете пользоваться лишь вы и другие инженеры.\r\n\r\nЧаще всего сырьем для этой профессии служат металлы и материалы, добываемые при помощи горного дела, поэтому удобно осваивать эти две профессии одновременно.\r\n\r\nДля создания многих предметов требуется кузнечный молот. Его и другие необходимые материалы для инженерного дела можно купить у торговцев.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Инженерное дело дает вам возможность создавать огромное количество полезных, удивительных и просто чудесных вещей: ружья, прицелы, мотоциклы, механических белок и многое другое. Однако, многими из этих предметов, например, очками, механическими дополнениями к поясам, сапогам, перчаткам и плащам, а также ветролетами сможете пользоваться лишь вы и другие инженеры.\r\n\r\nЧаще всего сырьем для этой профессии служат металлы и материалы, добываемые при помощи горного дела, поэтому удобно осваивать эти две профессии одновременно.\r\n\r\nДля создания многих предметов требуется кузнечный молот. Его и другие необходимые материалы для инженерного дела можно купить у торговцев.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Инженерное дело дает вам возможность создавать огромное количество полезных, удивительных и просто чудесных вещей: ружья, прицелы, мотоциклы, механических белок и многое другое. Однако, многими из этих предметов, например, очками, механическими дополнениями к поясам, сапогам, перчаткам и плащам, а также ветролетами сможете пользоваться лишь вы и другие инженеры.\r\n\r\nЧаще всего сырьем для этой профессии служат металлы и материалы, добываемые при помощи горного дела, поэтому удобно осваивать эти две профессии одновременно.\r\n\r\nДля создания многих предметов требуется кузнечный молот. Его и другие необходимые материалы для инженерного дела можно купить у торговцев.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17136,'Ювелирное дело дает вам возможность создавать магические кольца, амулеты, аксессуары и ограненные самоцветы.\r\n\r\nСамоцветы, которые используются в ювелирном деле, можно купить или получить, просеивая руду, добытую при помощи горного дела, поэтому эти две профессии удобно изучать вместе.\r\n\r\nДля создания большинства ювелирных изделий требуется набор ювелира и шлифовальный камень. Эти предметы можно купить у торговцев товарами для ювелиров.','Ювелирное дело дает вам возможность создавать магические кольца, амулеты, аксессуары и ограненные самоцветы.\r\n\r\nСамоцветы, которые используются в ювелирном деле, можно купить или получить, просеивая руду, добытую при помощи горного дела, поэтому эти две профессии удобно изучать вместе.\r\n\r\nДля создания большинства ювелирных изделий требуется набор ювелира и шлифовальный камень. Эти предметы можно купить у торговцев товарами для ювелиров.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ювелирное дело дает вам возможность создавать магические кольца, амулеты, аксессуары и ограненные самоцветы.\r\n\r\nСамоцветы, которые используются в ювелирном деле, можно купить или получить, просеивая руду, добытую при помощи горного дела, поэтому эти две профессии удобно изучать вместе.\r\n\r\nДля создания большинства ювелирных изделий требуется набор ювелира и шлифовальный камень. Эти предметы можно купить у торговцев товарами для ювелиров.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ювелирное дело дает вам возможность создавать магические кольца, амулеты, аксессуары и ограненные самоцветы.\r\n\r\nСамоцветы, которые используются в ювелирном деле, можно купить или получить, просеивая руду, добытую при помощи горного дела, поэтому эти две профессии удобно изучать вместе.\r\n\r\nДля создания большинства ювелирных изделий требуется набор ювелира и шлифовальный камень. Эти предметы можно купить у торговцев товарами для ювелиров.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17137,'Кожевничество дает вам возможность создавать доспехи, плащи, наборы для повышения характеристик доспехов и другие подобные предметы из кожи, шкур и чешуи. Другие материалы, необходимые для занятия кожевничеством, можно купить у торговцев.\r\n\r\nКожевничество удобно изучать вместе со снятием шкур, так как при этом вы всегда будете обеспечены необходимым сырьем. Другие необходимые предметы, как, например, нитки и краски, можно купить у торговцев товарами для кожевников.\r\n\r\nКожевники с достаточным уровнем навыка также могут создавать улучшения для наручей и поножей.','Кожевничество дает вам возможность создавать доспехи, плащи, наборы для повышения характеристик доспехов и другие подобные предметы из кожи, шкур и чешуи. Другие материалы, необходимые для занятия кожевничеством, можно купить у торговцев.\r\n\r\nКожевничество удобно изучать вместе со снятием шкур, так как при этом вы всегда будете обеспечены необходимым сырьем. Другие необходимые предметы, как, например, нитки и краски, можно купить у торговцев товарами для кожевников.\r\n\r\nКожевники с достаточным уровнем навыка также могут создавать улучшения для наручей и поножей.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Кожевничество дает вам возможность создавать доспехи, плащи, наборы для повышения характеристик доспехов и другие подобные предметы из кожи, шкур и чешуи. Другие материалы, необходимые для занятия кожевничеством, можно купить у торговцев.\r\n\r\nКожевничество удобно изучать вместе со снятием шкур, так как при этом вы всегда будете обеспечены необходимым сырьем. Другие необходимые предметы, как, например, нитки и краски, можно купить у торговцев товарами для кожевников.\r\n\r\nКожевники с достаточным уровнем навыка также могут создавать улучшения для наручей и поножей.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Кожевничество дает вам возможность создавать доспехи, плащи, наборы для повышения характеристик доспехов и другие подобные предметы из кожи, шкур и чешуи. Другие материалы, необходимые для занятия кожевничеством, можно купить у торговцев.\r\n\r\nКожевничество удобно изучать вместе со снятием шкур, так как при этом вы всегда будете обеспечены необходимым сырьем. Другие необходимые предметы, как, например, нитки и краски, можно купить у торговцев товарами для кожевников.\r\n\r\nКожевники с достаточным уровнем навыка также могут создавать улучшения для наручей и поножей.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17138,'Портняжное дело позволяет изготавливать доспехи, плащи, одежду, сумки, особые нитки и другие предметы из материалов, которые можно приобрести на аукционе или добыть из монстров-гуманоидов. Кроме того, такие материалы как нитки и краски можно приобрести у продавцов товаров для портных.\r\n\r\nИскусные портные умеют укреплять свои плащи магической вышивкой.\r\n\r\nЗачаровыватели зачастую становятся портными, чтобы распылять созданные ими магические вещи.','Портняжное дело позволяет изготавливать доспехи, плащи, одежду, сумки, особые нитки и другие предметы из материалов, которые можно приобрести на аукционе или добыть из монстров-гуманоидов. Кроме того, такие материалы как нитки и краски можно приобрести у продавцов товаров для портных.\r\n\r\nИскусные портные умеют укреплять свои плащи магической вышивкой.\r\n\r\nЗачаровыватели зачастую становятся портными, чтобы распылять созданные ими магические вещи.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Портняжное дело позволяет изготавливать доспехи, плащи, одежду, сумки, особые нитки и другие предметы из материалов, которые можно приобрести на аукционе или добыть из монстров-гуманоидов. Кроме того, такие материалы как нитки и краски можно приобрести у продавцов товаров для портных.\r\n\r\nИскусные портные умеют укреплять свои плащи магической вышивкой.\r\n\r\nЗачаровыватели зачастую становятся портными, чтобы распылять созданные ими магические вещи.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Портняжное дело позволяет изготавливать доспехи, плащи, одежду, сумки, особые нитки и другие предметы из материалов, которые можно приобрести на аукционе или добыть из монстров-гуманоидов. Кроме того, такие материалы как нитки и краски можно приобрести у продавцов товаров для портных.\r\n\r\nИскусные портные умеют укреплять свои плащи магической вышивкой.\r\n\r\nЗачаровыватели зачастую становятся портными, чтобы распылять созданные ими магические вещи.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17140,'Тебе надо попробовать это пиво.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тебе надо попробовать это пиво.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17142,'Если ты не собираешься тут работать, тебе лучше покинуть территорию раскопок.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если ты не собираешься тут работать, тебе лучше покинуть территорию раскопок.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`,`text2_0_loc8`,`text2_1_loc8`,`text3_0_loc8`,`text3_1_loc8`,`text4_0_loc8`,`text4_1_loc8`,`text5_0_loc8`,`text5_1_loc8`,`text6_0_loc8`,`text6_1_loc8`,`text7_0_loc8`,`text7_1_loc8`) VALUES (17143,'Привет, милашка!','Привет, милашка!','Найдется еще одно местечко?','Найдется еще одно местечко?','Нам не по пути?','Нам не по пути?','Не подбросишь девушку?','Не подбросишь девушку?','Ты сегодня классно выглядишь, Мартек.','Ты сегодня классно выглядишь, Мартек.','О-о! Мартек, можно я отправлюсь с тобой?','О-о! Мартек, можно я отправлюсь с тобой?','Мартек, ты самый храбрый из известных мне орков.','Мартек, ты самый храбрый из известных мне орков.','Спаси меня, Мартек! Ты мне нужен!','Спаси меня, Мартек! Ты мне нужен!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Привет, милашка!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Привет, милашка!',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Найдется еще одно местечко?',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Найдется еще одно местечко?',`text1_1_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Нам не по пути?',`text2_0_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Нам не по пути?',`text2_1_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Не подбросишь девушку?',`text3_0_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','Не подбросишь девушку?',`text3_1_loc8`), `text4_0_loc8`=IF(`text4_0_loc8` IS NULL OR `text4_0_loc8`='','Ты сегодня классно выглядишь, Мартек.',`text4_0_loc8`), `text4_1_loc8`=IF(`text4_1_loc8` IS NULL OR `text4_1_loc8`='','Ты сегодня классно выглядишь, Мартек.',`text4_1_loc8`), `text5_0_loc8`=IF(`text5_0_loc8` IS NULL OR `text5_0_loc8`='','О-о! Мартек, можно я отправлюсь с тобой?',`text5_0_loc8`), `text5_1_loc8`=IF(`text5_1_loc8` IS NULL OR `text5_1_loc8`='','О-о! Мартек, можно я отправлюсь с тобой?',`text5_1_loc8`), `text6_0_loc8`=IF(`text6_0_loc8` IS NULL OR `text6_0_loc8`='','Мартек, ты самый храбрый из известных мне орков.',`text6_0_loc8`), `text6_1_loc8`=IF(`text6_1_loc8` IS NULL OR `text6_1_loc8`='','Мартек, ты самый храбрый из известных мне орков.',`text6_1_loc8`), `text7_0_loc8`=IF(`text7_0_loc8` IS NULL OR `text7_0_loc8`='','Спаси меня, Мартек! Ты мне нужен!',`text7_0_loc8`), `text7_1_loc8`=IF(`text7_1_loc8` IS NULL OR `text7_1_loc8`='','Спаси меня, Мартек! Ты мне нужен!',`text7_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17148,'О, да тут прям все так серьезно, не так ли?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','О, да тут прям все так серьезно, не так ли?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17150,'Должен признать, меня заинтриговал этот амбициозный маленький выскочка.$b$bЯ не хочу торопиться с выводами, но до меня доходили некоторые тревожные слухи...$b$bТолько время покажет, что стоит за его действиями.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Должен признать, меня заинтриговал этот амбициозный маленький выскочка.$b$bЯ не хочу торопиться с выводами, но до меня доходили некоторые тревожные слухи...$b$bТолько время покажет, что стоит за его действиями.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17151,'И что тебя привело в нашу невзрачную компанию?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','И что тебя привело в нашу невзрачную компанию?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17152,'Я не удивлен.$B$BНо вопросов все-таки много...$B$BВсе это оружие нужно для археологических раскопок? А куда потом деваются находки? Кто руководит изысканиями?$B$BНда... похоже, отвечать никто не собирается. Что ж, придется искать ответы самому.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я не удивлен.$B$BНо вопросов все-таки много...$B$BВсе это оружие нужно для археологических раскопок? А куда потом деваются находки? Кто руководит изысканиями?$B$BНда... похоже, отвечать никто не собирается. Что ж, придется искать ответы самому.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17153,'Идиот!$B$BНу вас!$B$BНе замечайт, я концентрайт?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Идиот!$B$BНу вас!$B$BНе замечайт, я концентрайт?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17155,'Поднимем бокалы, мой друг!$B$BВы только взгляните на здешние достопримечательности.$B$BЭти края были сокрыты от всех на протяжении сотен лет.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Поднимем бокалы, мой друг!$B$BВы только взгляните на здешние достопримечательности.$B$BЭти края были сокрыты от всех на протяжении сотен лет.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17156,'Вы только посмотрите, сколько он добыл сокровищ!$B$BНет, его методы, безусловно, я не всегда одобряю, но каковы результаты...$B$BНо лучше об этом и не думать – в конце концов это просто невежливо.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вы только посмотрите, сколько он добыл сокровищ!$B$BНет, его методы, безусловно, я не всегда одобряю, но каковы результаты...$B$BНо лучше об этом и не думать – в конце концов это просто невежливо.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17157,'Мой друг, вы только задумайтесь!$B$BКогда наш маленький хозяин добудет достаточно сокровищ, он станет одной из самых влиятельных фигур Азерота.$B$BЭто благоприятно отразится и на нас.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мой друг, вы только задумайтесь!$B$BКогда наш маленький хозяин добудет достаточно сокровищ, он станет одной из самых влиятельных фигур Азерота.$B$BЭто благоприятно отразится и на нас.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17158,'Разве тут не прекрасно?$B$BИсследовать богом забытые уголки мира с друзьями-товарищами!$B$BЧто может быть лучше?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Разве тут не прекрасно?$B$BИсследовать богом забытые уголки мира с друзьями-товарищами!$B$BЧто может быть лучше?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17161,'Прекрасная тут погодка, не правда ли, |3-6($c)?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Прекрасная тут погодка, не правда ли, |3-6($c)?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17163,'Ой, как здорово!$B$BКомандир такой подтянутый, уверенный, а акцент какой забавный! Должна заметить, он весьма интересный.$B$BНе знаешь, женатый?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ой, как здорово!$B$BКомандир такой подтянутый, уверенный, а акцент какой забавный! Должна заметить, он весьма интересный.$B$BНе знаешь, женатый?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17164,'Считается, что некоторые реликвии в этих краях обладают волшебной силой.$B$BА он просто одержим такими вещами.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Считается, что некоторые реликвии в этих краях обладают волшебной силой.$B$BА он просто одержим такими вещами.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17165,'Извини, |3-6($c).$B$BЯ правда мало что об этом знаю. И если честно – и знать не желаю.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Извини, |3-6($c).$B$BЯ правда мало что об этом знаю. И если честно – и знать не желаю.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17166,'Итак, это |3-6($r)-|3-6($c), о $gкотором:которой:c; я так много слышать, хм?$B$BКак ты знать, тут есть еще айнц обелиск, нужный активировайт...$B$BКогда приходить время восстанавливайт эта древний механизм, ты быть здесь? Запоминайт тебя история?$B$BЭто зависит от твоя воля к сотрудничество.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Итак, это |3-6($r)-|3-6($c), о $gкотором:которой:c; я так много слышать, хм?$B$BКак ты знать, тут есть еще айнц обелиск, нужный активировайт...$B$BКогда приходить время восстанавливайт эта древний механизм, ты быть здесь? Запоминайт тебя история?$B$BЭто зависит от твоя воля к сотрудничество.',`text0_0_loc8`);
