INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`) VALUES (17167,'Говори, что тебе нужно, |3-6($r).','Мы за тобой присматривай, |3-6($r)...','...всегда следить!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Говори, что тебе нужно, |3-6($r).',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Мы за тобой присматривай, |3-6($r)...',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','...всегда следить!',`text2_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17168,'Драконья Пасть стала первым настоящим оплотом Альянса в Бесплодных землях. Несмотря на то, что те находятся между Штормградом и Дун Морогом, эта территория всегда контролировалась Ордой.$b$bЧтобы изменить ситуацию, нужно приступать к активным действиям. Конечно же, нападения драконов на Новый Каргат нам только на руку.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Драконья Пасть стала первым настоящим оплотом Альянса в Бесплодных землях. Несмотря на то, что те находятся между Штормградом и Дун Морогом, эта территория всегда контролировалась Ордой.$b$bЧтобы изменить ситуацию, нужно приступать к активным действиям. Конечно же, нападения драконов на Новый Каргат нам только на руку.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17169,'Я не меньше тебя удивлен повышенным интересом черных драконов к Новому Каргату. Горн упрям и не желает принимать ничью помощь.$b$bНесмотря на это, главный дознаватель Кровавый Взор попросил меня держать ситуацию под контролем.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я не меньше тебя удивлен повышенным интересом черных драконов к Новому Каргату. Горн упрям и не желает принимать ничью помощь.$b$bНесмотря на это, главный дознаватель Кровавый Взор попросил меня держать ситуацию под контролем.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17170,'Мы не должны допустить, чтобы войска Теразан напали на Каменный очаг.$b$bЕсли это произойдет, они украдут центральный фрагмент столпа мира.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы не должны допустить, чтобы войска Теразан напали на Каменный очаг.$b$bЕсли это произойдет, они украдут центральный фрагмент столпа мира.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17172,'Рыбалка, сон и подрывное дело. Что может быть лучше?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Рыбалка, сон и подрывное дело. Что может быть лучше?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17173,'Я проделала этот долгий путь, чтобы поговорить с прославленной пророчицей Драконьей Пасти. Я хотела заглянуть в черное сердце Чо\'Галла прежде, чем раздавлю его в своем кулаке.$B$BНо она ничем не смогла помочь – только вывалила на меня кучу рифмованных загадок. Может быть, ты сможешь разобраться во всей этой чепухе?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я проделала этот долгий путь, чтобы поговорить с прославленной пророчицей Драконьей Пасти. Я хотела заглянуть в черное сердце Чо\'Галла прежде, чем раздавлю его в своем кулаке.$B$BНо она ничем не смогла помочь – только вывалила на меня кучу рифмованных загадок. Может быть, ты сможешь разобраться во всей этой чепухе?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17174,'Саркофаг находится за этими руинами.$B$BПошли!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Саркофаг находится за этими руинами.$B$BПошли!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17175,'Мы слишком долго не придавали должного значения секретам чародейства.$b$bТы здесь для того, чтобы учиться?','Мы слишком долго не придавали должного значения секретам чародейства.$b$bТы здесь для того, чтобы учиться?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы слишком долго не придавали должного значения секретам чародейства.$b$bТы здесь для того, чтобы учиться?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мы слишком долго не придавали должного значения секретам чародейства.$b$bТы здесь для того, чтобы учиться?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17176,'Мы слишком долго не придавали должного значения секретам чародейства.$b$bУвы, но для тебя они так и останутся секретами.','Мы слишком долго не придавали должного значения секретам чародейства.$b$bУвы, но для тебя они так и останутся секретами.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы слишком долго не придавали должного значения секретам чародейства.$b$bУвы, но для тебя они так и останутся секретами.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мы слишком долго не придавали должного значения секретам чародейства.$b$bУвы, но для тебя они так и останутся секретами.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17180,'Прости, |3-6($c)$b$bТвои навыки тайной магии еще недостаточно высоки, чтобы понять магию порталов.','Прости, |3-6($c)$b$bТвои навыки тайной магии еще недостаточно высоки, чтобы понять магию порталов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Прости, |3-6($c)$b$bТвои навыки тайной магии еще недостаточно высоки, чтобы понять магию порталов.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Прости, |3-6($c)$b$bТвои навыки тайной магии еще недостаточно высоки, чтобы понять магию порталов.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17181,'Ты изучаешь чародейские науки, да?$b$bЕсли ты хочешь, я могу обучить тебя магии порталов.','Ты изучаешь чародейские науки, да?$b$bЕсли ты хочешь, я могу обучить тебя магии порталов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты изучаешь чародейские науки, да?$b$bЕсли ты хочешь, я могу обучить тебя магии порталов.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты изучаешь чародейские науки, да?$b$bЕсли ты хочешь, я могу обучить тебя магии порталов.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17187,'Боюсь, я не в силах тебе помочь, |3-6($r). Лучше обратись к Хелин Сталекрылой.','Боюсь, я не в силах тебе помочь, |3-6($r). Лучше обратись к Хелин Сталекрылой.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Боюсь, я не в силах тебе помочь, |3-6($r). Лучше обратись к Хелин Сталекрылой.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Боюсь, я не в силах тебе помочь, |3-6($r). Лучше обратись к Хелин Сталекрылой.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`,`text3_0_loc8`,`text4_0_loc8`,`text5_0_loc8`) VALUES (17189,'Скажите, не могли бы вы на некоторое время встать так, чтобы заслонить своей тенью солнце?$B$BЭто было бы здорово...','Шнотц нашими руками сколачивает себе состояние, а где наша доля?!','Здесь так жарко, работать невозможно – особенно в этой форме.','Мне обещали тут легкие деньги.$B$BЖестокая шутка!','Мы работаем на них как проклятые, а взамен ничего не получаем!','Шнотц нашими руками сколачивает себе состояние, а где наша доля?!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Скажите, не могли бы вы на некоторое время встать так, чтобы заслонить своей тенью солнце?$B$BЭто было бы здорово...',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Шнотц нашими руками сколачивает себе состояние, а где наша доля?!',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Здесь так жарко, работать невозможно – особенно в этой форме.',`text2_0_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Мне обещали тут легкие деньги.$B$BЖестокая шутка!',`text3_0_loc8`), `text4_0_loc8`=IF(`text4_0_loc8` IS NULL OR `text4_0_loc8`='','Мы работаем на них как проклятые, а взамен ничего не получаем!',`text4_0_loc8`), `text5_0_loc8`=IF(`text5_0_loc8` IS NULL OR `text5_0_loc8`='','Шнотц нашими руками сколачивает себе состояние, а где наша доля?!',`text5_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`) VALUES (17192,'Как ты считайт, Кулдык чувствовайт тебя, если он бывайт тут? $B$BА?','После провал ритуал вы есть мой должник, |3-6($r).$B$BА я планировайт получайт майн долг!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Как ты считайт, Кулдык чувствовайт тебя, если он бывайт тут? $B$BА?',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','После провал ритуал вы есть мой должник, |3-6($r).$B$BА я планировайт получайт майн долг!',`text1_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17193,'Слушай, я тут немного принял по поводу нашего спасения и вот что подумал...$B$BЭтих коротышек, которые на нас напрыгнули, следует проучить!$B$BЕсли это им спустить, то скоро каждый честный исследователь, ступивший на эту землю, будет продан в рабство – если не хуже!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Слушай, я тут немного принял по поводу нашего спасения и вот что подумал...$B$BЭтих коротышек, которые на нас напрыгнули, следует проучить!$B$BЕсли это им спустить, то скоро каждый честный исследователь, ступивший на эту землю, будет продан в рабство – если не хуже!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17194,'За этим порталом – Тол Барад.','За этим порталом – Тол Барад.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','За этим порталом – Тол Барад.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','За этим порталом – Тол Барад.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17197,'Я прекрасно знаю, что демоническое присутствие в этом лесу можно вменить в вину моему народу.$b$bИ я не первая высокорожденная, которая пытается исправить эту ошибку. Я благодарю Изумрудный Круг за то, что он принимает мою помощь.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я прекрасно знаю, что демоническое присутствие в этом лесу можно вменить в вину моему народу.$b$bИ я не первая высокорожденная, которая пытается исправить эту ошибку. Я благодарю Изумрудный Круг за то, что он принимает мою помощь.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17208,'<Наездник на грифоне Муллана неподвижен, глаза устремлены вперед, он не замечает вашего присутствия.>','<Наездник на грифоне Муллана неподвижен, глаза устремлены вперед, он не замечает вашего присутствия.>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Наездник на грифоне Муллана неподвижен, глаза устремлены вперед, он не замечает вашего присутствия.>',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','<Наездник на грифоне Муллана неподвижен, глаза устремлены вперед, он не замечает вашего присутствия.>',`text0_1_loc8`);
