INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`,`text2_0_loc8`,`text2_1_loc8`,`text3_0_loc8`,`text3_1_loc8`) VALUES (17212,'Дуглас тебя послал на избиение?','Дуглас тебя послал на избиение?','Хочешь подраться?','Хочешь подраться?','Похоже, ты хочешь чтоб я тебе наподдал...','Похоже, ты хочешь чтоб я тебе наподдал...','На грубость нарываешься?','На грубость нарываешься?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Дуглас тебя послал на избиение?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Дуглас тебя послал на избиение?',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Хочешь подраться?',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Хочешь подраться?',`text1_1_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Похоже, ты хочешь чтоб я тебе наподдал...',`text2_0_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Похоже, ты хочешь чтоб я тебе наподдал...',`text2_1_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','На грубость нарываешься?',`text3_0_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','На грубость нарываешься?',`text3_1_loc8`);
