INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17216,'Тебе нужно разыскать Адама Хоссака. Его контора находится в южной части Квартала Магов, во внутреннем кольце.$B$BЕсли он не занят исследованием окрестностей, то должен быть там.','Тебе нужно разыскать Адама Хоссака. Его контора находится в южной части Квартала Магов, во внутреннем кольце.$B$BЕсли он не занят исследованием окрестностей, то должен быть там.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тебе нужно разыскать Адама Хоссака. Его контора находится в южной части Квартала Магов, во внутреннем кольце.$B$BЕсли он не занят исследованием окрестностей, то должен быть там.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Тебе нужно разыскать Адама Хоссака. Его контора находится в южной части Квартала Магов, во внутреннем кольце.$B$BЕсли он не занят исследованием окрестностей, то должен быть там.',`text0_1_loc8`);
