INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`) VALUES (17229,'Прошу прощения, но я занят больше, чем может показаться на первый взгляд.$B$BВидите ли, моя задача – документировать все открытия командира, которые он сделает.$B$BА они наверняка будут грандиозными!','Я занят: работаю над биографией командира Шнотца.$B$BТак что вы должны меня извинить.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Прошу прощения, но я занят больше, чем может показаться на первый взгляд.$B$BВидите ли, моя задача – документировать все открытия командира, которые он сделает.$B$BА они наверняка будут грандиозными!',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Я занят: работаю над биографией командира Шнотца.$B$BТак что вы должны меня извинить.',`text1_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17231,'Я снабжаю армию Кром\'гара.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я снабжаю армию Кром\'гара.',`text0_0_loc8`);
