INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17232,'На днях они грузили артефакты в лодки.$B$BНикогда в жизни не видела сразу столько золота!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','На днях они грузили артефакты в лодки.$B$BНикогда в жизни не видела сразу столько золота!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17233,'Несколько лет назад я попал здесь в ловушку, когда изучал ветрокрылов. Но когда вырвался на свободу, решил вернуться, чтобы их охранять.$B$BТеперь, с началом катаклизма, Сумеречный Молот стал отлавливать эти священные создания и, что еще ужаснее, уничтожать их.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Несколько лет назад я попал здесь в ловушку, когда изучал ветрокрылов. Но когда вырвался на свободу, решил вернуться, чтобы их охранять.$B$BТеперь, с началом катаклизма, Сумеречный Молот стал отлавливать эти священные создания и, что еще ужаснее, уничтожать их.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`,`text2_0_loc8`,`text2_1_loc8`) VALUES (17235,'Кто ты?','Кто ты?','Выбирайся отсюда, пока тебя не увидели поработители!','Выбирайся отсюда, пока тебя не увидели поработители!','Ты здесь… чтобы спасти меня?','Ты здесь… чтобы спасти меня?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Кто ты?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Кто ты?',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Выбирайся отсюда, пока тебя не увидели поработители!',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Выбирайся отсюда, пока тебя не увидели поработители!',`text1_1_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Ты здесь… чтобы спасти меня?',`text2_0_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Ты здесь… чтобы спасти меня?',`text2_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17239,'ОГО! Я СНОВА ЖИВ! БОЛЬШОЕ СУЩЕСТВО ИЗ БЕЛОГО СВЕТА С КРЫЛЬЯМИ ОЖИВИЛО МЕНЯ! Я СЛУЖУ КОРОЛЕВЕ БАНШИ! ЭЙ!$B$BПОМОГИТЕ!$B$BЭЙ!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','ОГО! Я СНОВА ЖИВ! БОЛЬШОЕ СУЩЕСТВО ИЗ БЕЛОГО СВЕТА С КРЫЛЬЯМИ ОЖИВИЛО МЕНЯ! Я СЛУЖУ КОРОЛЕВЕ БАНШИ! ЭЙ!$B$BПОМОГИТЕ!$B$BЭЙ!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17240,'ХОРОШО! СПАСИБО! Я БУДУ ЗДЕСЬ ПОБЛИЗОСТИ! СПАСИБО! ХОРОШО!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','ХОРОШО! СПАСИБО! Я БУДУ ЗДЕСЬ ПОБЛИЗОСТИ! СПАСИБО! ХОРОШО!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17241,'Я был свидетелем падения Короля-лича. Порождения титанов гибли от моего топора. Я привел Серебряный Авангард к победе над чудовищами Нордскола. Настало время для заключительного испытания. Что у Предгорий Хилсбрада найдется для Оркуса, свергнувшего Короля???') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я был свидетелем падения Короля-лича. Порождения титанов гибли от моего топора. Я привел Серебряный Авангард к победе над чудовищами Нордскола. Настало время для заключительного испытания. Что у Предгорий Хилсбрада найдется для Оркуса, свергнувшего Короля???',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17242,'Мятежники, говоришь? А есть ли опасность, что я погибну или потеряю часть тела?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мятежники, говоришь? А есть ли опасность, что я погибну или потеряю часть тела?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17243,'Ну тогда Оркус возьмется за это! Да!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ну тогда Оркус возьмется за это! Да!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17244,'Посмотри на меня, крестьянин. С ног до головы я увешан наследными ценностями, которые величайшие герои Азерота принесли мне в дар.$b$bТеперь посмотри на себя.$b$bА теперь снова на меня.$b$bДа-да, эта лошадь действительно из звезд.$b$bНу так что за бессмысленные, пригодные лишь для умственно отсталых задания ты мне приготовил?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Посмотри на меня, крестьянин. С ног до головы я увешан наследными ценностями, которые величайшие герои Азерота принесли мне в дар.$b$bТеперь посмотри на себя.$b$bА теперь снова на меня.$b$bДа-да, эта лошадь действительно из звезд.$b$bНу так что за бессмысленные, пригодные лишь для умственно отсталых задания ты мне приготовил?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17245,'Хорошо, хорошо, что дальше?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Хорошо, хорошо, что дальше?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17246,'И это все? Одно задание? Да ты шутишь. Не нужно добыть для тебя медвежьих хвостов? Или, может, есть какие-то редкие цветочки, которые я тебе соберу, а ты сваришь из них галлюциногенное зелье, выпьешь его и насладишься видениями на тему грядущего апокалипсиса? Может, местная колония сусликов доставляет тебе неудобства? Нет? Совсем ничего?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','И это все? Одно задание? Да ты шутишь. Не нужно добыть для тебя медвежьих хвостов? Или, может, есть какие-то редкие цветочки, которые я тебе соберу, а ты сваришь из них галлюциногенное зелье, выпьешь его и насладишься видениями на тему грядущего апокалипсиса? Может, местная колония сусликов доставляет тебе неудобства? Нет? Совсем ничего?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17247,'$gСлышал:Слышала; когда-нибудь о Братстве Тория? Конечно, выглядим мы примерно так же, как те дворфы из ущелья или из глубин Черной горы, но поверь мне, мы совсем другие.$b$bТе негодяи слишком глубоко копают, а теперь еще и прислуживают темным силам: Рагнаросу Повелителю Огня. Мы счастливы, что наши цели и намерения совсем другие, даже если в конечном итоге нам и приходится предотвращать исходящие от тех дворфов проблемы.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','$gСлышал:Слышала; когда-нибудь о Братстве Тория? Конечно, выглядим мы примерно так же, как те дворфы из ущелья или из глубин Черной горы, но поверь мне, мы совсем другие.$b$bТе негодяи слишком глубоко копают, а теперь еще и прислуживают темным силам: Рагнаросу Повелителю Огня. Мы счастливы, что наши цели и намерения совсем другие, даже если в конечном итоге нам и приходится предотвращать исходящие от тех дворфов проблемы.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17248,'Клан Черного Железа с Черной горы ничего от меня не получит. Так же как и те ребята из Братства Тория.$b$bЯ независим и мне это нравится. Но, конечно, я готов выслушать все предложения за определенное вознаграждение…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Клан Черного Железа с Черной горы ничего от меня не получит. Так же как и те ребята из Братства Тория.$b$bЯ независим и мне это нравится. Но, конечно, я готов выслушать все предложения за определенное вознаграждение…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`) VALUES (17251,'Этот парень Шнотц, оказывается, прекрасный бизнесмен.$B$BХорошо, что я успел войти в дело в самом начале.','Мой отец всегда говорил – чтобы стать хорошим инвестором, надо обладать умом, интуицией и смелостью! Прямо скажу, в данном случае я сразу почуял запах денег.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Этот парень Шнотц, оказывается, прекрасный бизнесмен.$B$BХорошо, что я успел войти в дело в самом начале.',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Мой отец всегда говорил – чтобы стать хорошим инвестором, надо обладать умом, интуицией и смелостью! Прямо скажу, в данном случае я сразу почуял запах денег.',`text1_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17252,'Посланника убили!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Посланника убили!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17253,'А кто его знает.$B$BОн нелестно отзывался о здешних делах, но это еще ничего не доказывает.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','А кто его знает.$B$BОн нелестно отзывался о здешних делах, но это еще ничего не доказывает.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17254,'Кто, я?$B$BНу, вряд ли я назвал бы себя профессионалом, если бы... Нет, думаю, нет.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Кто, я?$B$BНу, вряд ли я назвал бы себя профессионалом, если бы... Нет, думаю, нет.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17255,'Что-что? Ну, я...$B$BКогда идет речь об археологических раскопках, не думаю, что надо делать акцент на таких вещах.$B$BЭто, знаете ли, больше подойдет для другого жанра.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что-что? Ну, я...$B$BКогда идет речь об археологических раскопках, не думаю, что надо делать акцент на таких вещах.$B$BЭто, знаете ли, больше подойдет для другого жанра.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17256,'Не трогай, не трогай меня...$B$BЧто вообще происходит?!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Не трогай, не трогай меня...$B$BЧто вообще происходит?!',`text0_1_loc8`);
