INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17257,'Нет! Разумеется, я не в порядке!$B$BЯ никогда раньше не видела труп...') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Нет! Разумеется, я не в порядке!$B$BЯ никогда раньше не видела труп...',`text0_1_loc8`);
