INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17258,'Он, спотыкаясь, вышел из казарм.$B$BЯ звала на помощь, но охранники не обратили на меня ни малейшего внимания!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Он, спотыкаясь, вышел из казарм.$B$BЯ звала на помощь, но охранники не обратили на меня ни малейшего внимания!',`text0_1_loc8`);
