INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17259,'Да, я так и сделаю.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Да, я так и сделаю.',`text0_1_loc8`);
