INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17263,'Кажется, эта пушка направлена прямо на берег. Порох уже засыпан, и фитиль установлен.$B$BКак удобно!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Кажется, эта пушка направлена прямо на берег. Порох уже засыпан, и фитиль установлен.$B$BКак удобно!',`text0_0_loc8`);
