INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17266,'Желаешь обучиться, охотник?','Желаешь обучиться, охотница?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Желаешь обучиться, охотник?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Желаешь обучиться, охотница?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17267,'Не могу поверить, что мы делаем это. Я знаю, присутствие Кальциндера страшит всех нас, но настолько? Разве здесь не территория Служителей Земли?$b$bПочему Братству Тория все время приходится спасать положение?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не могу поверить, что мы делаем это. Я знаю, присутствие Кальциндера страшит всех нас, но настолько? Разве здесь не территория Служителей Земли?$b$bПочему Братству Тория все время приходится спасать положение?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17268,'Добро пожаловать в Братство Тория. Как надзиратель, я отвечаю за все, что здесь происходит. Хотя в основном это и касается добычи металлов, ковки и дел, связанных с охраной, в последнее время мы стали больше похожи на военную организацию… жизнь заставила.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать в Братство Тория. Как надзиратель, я отвечаю за все, что здесь происходит. Хотя в основном это и касается добычи металлов, ковки и дел, связанных с охраной, в последнее время мы стали больше похожи на военную организацию… жизнь заставила.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17276,'Эти воргены – наши пленники. Их судьба в руках главнокомандующего.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эти воргены – наши пленники. Их судьба в руках главнокомандующего.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17278,'Чего тебе надо, ничтожество? Убирайся прочь с моих глаз, пока я тебе не повышибал все зубы своим молотом!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Чего тебе надо, ничтожество? Убирайся прочь с моих глаз, пока я тебе не повышибал все зубы своим молотом!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17279,'Чем могу помочь, $gкрасавчик:красавица;?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Чем могу помочь, $gкрасавчик:красавица;?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17280,'Чего тебе нужно? У меня очень много дел.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Чего тебе нужно? У меня очень много дел.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17281,'Драконы выиграли для нас время и возможность отбить врата у Сумеречного Молота. И лучше нам этот шанс не упускать.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Драконы выиграли для нас время и возможность отбить врата у Сумеречного Молота. И лучше нам этот шанс не упускать.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17291,'Какая радость, |3-6($c).$B$BУ нас так мало посетителей в это время.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Какая радость, |3-6($c).$B$BУ нас так мало посетителей в это время.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17292,'Какая приятная неожиданность!$B$BМы сегодня никого не ждали.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Какая приятная неожиданность!$B$BМы сегодня никого не ждали.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17293,'Бремя ответственности впервые легло на мои плечи. Я должна была предвидеть, что Наркралл не подчинится приказам... А вместо этого мне приходится расхлебывать кашу, которую он заварил.$B$BНе понимаю, как Гаррошу удается удерживать в узде всю эту разношерстную компанию, из которой состоит Орда... Надо было присмотреться к нему получше.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Бремя ответственности впервые легло на мои плечи. Я должна была предвидеть, что Наркралл не подчинится приказам... А вместо этого мне приходится расхлебывать кашу, которую он заварил.$B$BНе понимаю, как Гаррошу удается удерживать в узде всю эту разношерстную компанию, из которой состоит Орда... Надо было присмотреться к нему получше.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17299,'Доброго профессора Стальные Штаны можно найти в Зале Исследователей.','Доброго профессора Стальные Штаны можно найти в Зале Исследователей.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Доброго профессора Стальные Штаны можно найти в Зале Исследователей.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Доброго профессора Стальные Штаны можно найти в Зале Исследователей.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17300,'Чародей-кузнец есть в лавке Гимбла, "Колдовские штучки Чертополуша" – это рядом с укротителем грифонов, у Великой Кузни.$B$BПравда, он один из этих, пропавших высокорожденных эльфов, но это ничего – он тебя не обманет.','Чародей-кузнец есть в лавке Гимбла, "Колдовские штучки Чертополуша" – это рядом с укротителем грифонов, у Великой Кузни.$B$BПравда, он один из этих, пропавших высокорожденных эльфов, но это ничего – он тебя не обманет.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Чародей-кузнец есть в лавке Гимбла, "Колдовские штучки Чертополуша" – это рядом с укротителем грифонов, у Великой Кузни.$B$BПравда, он один из этих, пропавших высокорожденных эльфов, но это ничего – он тебя не обманет.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Чародей-кузнец есть в лавке Гимбла, "Колдовские штучки Чертополуша" – это рядом с укротителем грифонов, у Великой Кузни.$B$BПравда, он один из этих, пропавших высокорожденных эльфов, но это ничего – он тебя не обманет.',`text0_1_loc8`);
