INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17302,'В центральной крепости Аллеи Силы находится делегация из Луносвета. В ее состав входит кровавый эльф по имени Беллок. Он – тот, кто тебе нужен.','В центральной крепости Аллеи Силы находится делегация из Луносвета. В ее состав входит кровавый эльф по имени Беллок. Он – тот, кто тебе нужен.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','В центральной крепости Аллеи Силы находится делегация из Луносвета. В ее состав входит кровавый эльф по имени Беллок. Он – тот, кто тебе нужен.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','В центральной крепости Аллеи Силы находится делегация из Луносвета. В ее состав входит кровавый эльф по имени Беллок. Он – тот, кто тебе нужен.',`text0_1_loc8`);
