INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17303,'Магов можно встретить в Расселине Теней. Один вход находится между аллеями Силы и Мудрости, а второй – в Волоке.','Магов можно встретить в Расселине Теней. Один вход находится между аллеями Силы и Мудрости, а второй – в Волоке.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Магов можно встретить в Расселине Теней. Один вход находится между аллеями Силы и Мудрости, а второй – в Волоке.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Магов можно встретить в Расселине Теней. Один вход находится между аллеями Силы и Мудрости, а второй – в Волоке.',`text0_1_loc8`);
