INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17304,'Осторожнее, |3-6($r).$B$BШнотц в ужасном настроении после провала ритуала.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Осторожнее, |3-6($r).$B$BШнотц в ужасном настроении после провала ритуала.',`text0_0_loc8`);
