INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17305,'Тело посла лежит в луже его собственной крови.$B$BПод разорванной одеждой видны глубокие следы от огромных зубов.$B$BЕще более странно, что раны прижжены, в некоторых местах даже обуглены.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тело посла лежит в луже его собственной крови.$B$BПод разорванной одеждой видны глубокие следы от огромных зубов.$B$BЕще более странно, что раны прижжены, в некоторых местах даже обуглены.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17306,'Мой совет очень прост, |3-6($r).$B$BНе путайся под ногами.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мой совет очень прост, |3-6($r).$B$BНе путайся под ногами.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`) VALUES (17307,'Уходи, |3-6($r).$B$BТы меня абсолютно не интересуешь.','<Посланник усмехается, так и не глянув на вас.>$B$BОтправляйся по своим делам, |3-6($r).','<Человек не обращает на вас никакого внимания. Очевидно, что он не стремится к общению.>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Уходи, |3-6($r).$B$BТы меня абсолютно не интересуешь.',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','<Посланник усмехается, так и не глянув на вас.>$B$BОтправляйся по своим делам, |3-6($r).',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','<Человек не обращает на вас никакого внимания. Очевидно, что он не стремится к общению.>',`text2_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`) VALUES (17308,'Ужасно, все это просто ужасно!$B$BТакой жуткий гул пронесся по всей округе.$B$BБедняга...$B$BПрошу прощения, мне просто необходимо выпить.','Даже и не знаю, что я видел.$B$BТем более все закончилось, прежде чем я что-то понял.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ужасно, все это просто ужасно!$B$BТакой жуткий гул пронесся по всей округе.$B$BБедняга...$B$BПрошу прощения, мне просто необходимо выпить.',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Даже и не знаю, что я видел.$B$BТем более все закончилось, прежде чем я что-то понял.',`text1_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17309,'Какая неприятность!$B$BНу, давайте наводить порядок, что ли?$B$BНе хотелось бы делать больше, чем требуется...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Какая неприятность!$B$BНу, давайте наводить порядок, что ли?$B$BНе хотелось бы делать больше, чем требуется...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17310,'Интересно, конечно, но что сделано, то уж сделано.$B$BА ненужная шумиха нам ни к чему. Это просто глупо!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Интересно, конечно, но что сделано, то уж сделано.$B$BА ненужная шумиха нам ни к чему. Это просто глупо!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17311,'Конечно же, нет!$B$BЯ вложил в это предприятие все свое состояние... А дурная молва еще никому ничего хорошего не принесла.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Конечно же, нет!$B$BЯ вложил в это предприятие все свое состояние... А дурная молва еще никому ничего хорошего не принесла.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17312,'Что вообще происходит?!$B$BВы видели эти раны?!$B$BКто мог ТАКОЕ сделать?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что вообще происходит?!$B$BВы видели эти раны?!$B$BКто мог ТАКОЕ сделать?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17313,'Нет, но мне ничего и видеть не надо, я и так скажу – мы все УМРЕМ!$B$BТы меня слышишь?!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Нет, но мне ничего и видеть не надо, я и так скажу – мы все УМРЕМ!$B$BТы меня слышишь?!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17314,'Тебе легко говорить.$B$BА я на это не подписывался! Надо уезжать отсюда, пока не поздно!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тебе легко говорить.$B$BА я на это не подписывался! Надо уезжать отсюда, пока не поздно!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17315,'<Знаменитость внимательно на вас смотрит.>') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','<Знаменитость внимательно на вас смотрит.>',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`,`text2_0_loc8`,`text2_1_loc8`,`text3_0_loc8`,`text3_1_loc8`,`text4_0_loc8`,`text4_1_loc8`,`text5_0_loc8`,`text5_1_loc8`,`text6_0_loc8`,`text6_1_loc8`,`text7_0_loc8`,`text7_1_loc8`) VALUES (17319,'Мы знакомы? Нет? Но все равно – добро пожаловать в Сумеречный Молот.','Мы знакомы? Нет? Но все равно – добро пожаловать в Сумеречный Молот.','Близится конец всего!','Близится конец всего!','У тебя тут кровь на доспехе. С тобой все в порядке?','У тебя тут кровь на доспехе. С тобой все в порядке?','Еще один новобранец? Ты уже $gдоложился:доложилась; командиру?','Еще один новобранец? Ты уже $gдоложился:доложилась; командиру?','Эй ты, часом, не $gвидал:видала; Гром-Грома? Орка примерно вот такого роста. Нет?$B$BГм... Как сквозь землю провалился. Не иначе, ушел в самоволку.','Эй ты, часом, не $gвидал:видала; Гром-Грома? Орка примерно вот такого роста. Нет?$B$BГм... Как сквозь землю провалился. Не иначе, ушел в самоволку.','В Пустоши к востоку отсюда затевается что-то масштабное.$B$BНу, что бы это ни было, надеюсь, скоро все закончится и нас переведут в более приличное место.','В Пустоши к востоку отсюда затевается что-то масштабное.$B$BНу, что бы это ни было, надеюсь, скоро все закончится и нас переведут в более приличное место.','Смотри в оба. Говорят, этот псих, что нападал на людей, до сих пор рыщет где-то поблизости.','Смотри в оба. Говорят, этот псих, что нападал на людей, до сих пор рыщет где-то поблизости.','Разве не странно, что мы тут держим в плену Магату Зловещий Тотем? Хорошо, хоть все ее тотемы уничтожили.$B$BЯ даже слыхал, что это она отравила Кэрна Кровавое Копыто. Жаль, она не на нашей стороне.','Разве не странно, что мы тут держим в плену Магату Зловещий Тотем? Хорошо, хоть все ее тотемы уничтожили.$B$BЯ даже слыхала, что это она отравила Кэрна Кровавое Копыто. Жаль, она не на нашей стороне.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы знакомы? Нет? Но все равно – добро пожаловать в Сумеречный Молот.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мы знакомы? Нет? Но все равно – добро пожаловать в Сумеречный Молот.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Близится конец всего!',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Близится конец всего!',`text1_1_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','У тебя тут кровь на доспехе. С тобой все в порядке?',`text2_0_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','У тебя тут кровь на доспехе. С тобой все в порядке?',`text2_1_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Еще один новобранец? Ты уже $gдоложился:доложилась; командиру?',`text3_0_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','Еще один новобранец? Ты уже $gдоложился:доложилась; командиру?',`text3_1_loc8`), `text4_0_loc8`=IF(`text4_0_loc8` IS NULL OR `text4_0_loc8`='','Эй ты, часом, не $gвидал:видала; Гром-Грома? Орка примерно вот такого роста. Нет?$B$BГм... Как сквозь землю провалился. Не иначе, ушел в самоволку.',`text4_0_loc8`), `text4_1_loc8`=IF(`text4_1_loc8` IS NULL OR `text4_1_loc8`='','Эй ты, часом, не $gвидал:видала; Гром-Грома? Орка примерно вот такого роста. Нет?$B$BГм... Как сквозь землю провалился. Не иначе, ушел в самоволку.',`text4_1_loc8`), `text5_0_loc8`=IF(`text5_0_loc8` IS NULL OR `text5_0_loc8`='','В Пустоши к востоку отсюда затевается что-то масштабное.$B$BНу, что бы это ни было, надеюсь, скоро все закончится и нас переведут в более приличное место.',`text5_0_loc8`), `text5_1_loc8`=IF(`text5_1_loc8` IS NULL OR `text5_1_loc8`='','В Пустоши к востоку отсюда затевается что-то масштабное.$B$BНу, что бы это ни было, надеюсь, скоро все закончится и нас переведут в более приличное место.',`text5_1_loc8`), `text6_0_loc8`=IF(`text6_0_loc8` IS NULL OR `text6_0_loc8`='','Смотри в оба. Говорят, этот псих, что нападал на людей, до сих пор рыщет где-то поблизости.',`text6_0_loc8`), `text6_1_loc8`=IF(`text6_1_loc8` IS NULL OR `text6_1_loc8`='','Смотри в оба. Говорят, этот псих, что нападал на людей, до сих пор рыщет где-то поблизости.',`text6_1_loc8`), `text7_0_loc8`=IF(`text7_0_loc8` IS NULL OR `text7_0_loc8`='','Разве не странно, что мы тут держим в плену Магату Зловещий Тотем? Хорошо, хоть все ее тотемы уничтожили.$B$BЯ даже слыхал, что это она отравила Кэрна Кровавое Копыто. Жаль, она не на нашей стороне.',`text7_0_loc8`), `text7_1_loc8`=IF(`text7_1_loc8` IS NULL OR `text7_1_loc8`='','Разве не странно, что мы тут держим в плену Магату Зловещий Тотем? Хорошо, хоть все ее тотемы уничтожили.$B$BЯ даже слыхала, что это она отравила Кэрна Кровавое Копыто. Жаль, она не на нашей стороне.',`text7_1_loc8`);
