INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17321,'Полководец Крогг послал меня сюда удерживать фронт. Но он не дал мне солдат.$B$BПосмотри на это! Тут у меня огры. Тут у меня Сумеречный Молот. Тут у меня... Ничего тут у меня нет.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Полководец Крогг послал меня сюда удерживать фронт. Но он не дал мне солдат.$B$BПосмотри на это! Тут у меня огры. Тут у меня Сумеречный Молот. Тут у меня... Ничего тут у меня нет.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17323,'Ото Серая Шкура проводит много времени на Вершине Старейшин, в зале Старейшин. Найди его, и он поможет тебе.','Ото Серая Шкура проводит много времени на Вершине Старейшин, в зале Старейшин. Найди его, и он поможет тебе.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ото Серая Шкура проводит много времени на Вершине Старейшин, в зале Старейшин. Найди его, и он поможет тебе.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ото Серая Шкура проводит много времени на Вершине Старейшин, в зале Старейшин. Найди его, и он поможет тебе.',`text0_1_loc8`);
