INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17327,'Тебе может помочь городская специалистка по чародейской перековке. Ее зовут чародейка Фира, и чаще всего она бывает на Площади Солнца вместе с Седаной и ее учениками.','Тебе может помочь городская специалистка по чародейской перековке. Ее зовут чародейка Фира, и чаще всего она бывает на Площади Солнца вместе с Седаной и ее учениками.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тебе может помочь городская специалистка по чародейской перековке. Ее зовут чародейка Фира, и чаще всего она бывает на Площади Солнца вместе с Седаной и ее учениками.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Тебе может помочь городская специалистка по чародейской перековке. Ее зовут чародейка Фира, и чаще всего она бывает на Площади Солнца вместе с Седаной и ее учениками.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17328,'Может, я непонятно выразилась? Немедленно сними с меня эти цепи!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Может, я непонятно выразилась? Немедленно сними с меня эти цепи!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17330,'Все пошло к черту, |3-6($c)!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Все пошло к черту, |3-6($c)!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17332,'Это проклятые пещеры, дружище. В них полно самой мерзкой джуджу.$B$BДавным-давно, когда на вершине этой горы верховодили сектанты Сумеречного Молота, они бросали в эти пещеры всяких еретиков и прочих недостойных – прямо в пасть черным драконам, которые там обитали.$B$BНикто еще оттуда не возвращался, даже в обличье духа.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Это проклятые пещеры, дружище. В них полно самой мерзкой джуджу.$B$BДавным-давно, когда на вершине этой горы верховодили сектанты Сумеречного Молота, они бросали в эти пещеры всяких еретиков и прочих недостойных – прямо в пасть черным драконам, которые там обитали.$B$BНикто еще оттуда не возвращался, даже в обличье духа.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17333,'Мои поздравления, |3-6($c)!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мои поздравления, |3-6($c)!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17334,'Бодуро Искателя часто можно встретить на Базаре в Нижнем Городе. Попробуй поискать его там.','Бодуро Искателя часто можно встретить на Базаре в Нижнем Городе. Попробуй поискать его там.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Бодуро Искателя часто можно встретить на Базаре в Нижнем Городе. Попробуй поискать его там.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Бодуро Искателя часто можно встретить на Базаре в Нижнем Городе. Попробуй поискать его там.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17336,'Наставница магов высших эльфов Даринесс – самый именитый археолог в этом городе… кроме того, она всегда готов помочь советом.$B$BЕе часто можно застать в Приюте фокусника к северу от центра города, где та любит коротать время, рассказывая хозяевам и завсегдатаям заведения о своих приключениях.','Наставница магов высших эльфов Даринесс – самый именитый археолог в этом городе… кроме того, она всегда готов помочь советом.$B$BЕе часто можно застать в Приюте фокусника к северу от центра города, где та любит коротать время, рассказывая хозяевам и завсегдатаям заведения о своих приключениях.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Наставница магов высших эльфов Даринесс – самый именитый археолог в этом городе… кроме того, она всегда готов помочь советом.$B$BЕе часто можно застать в Приюте фокусника к северу от центра города, где та любит коротать время, рассказывая хозяевам и завсегдатаям заведения о своих приключениях.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Наставница магов высших эльфов Даринесс – самый именитый археолог в этом городе… кроме того, она всегда готов помочь советом.$B$BЕе часто можно застать в Приюте фокусника к северу от центра города, где та любит коротать время, рассказывая хозяевам и завсегдатаям заведения о своих приключениях.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17338,'Здесь не всегда были эти славные поля, |3-6($c). Только благодаря нашей решительности и силе воли ветхие фермы людей превратились в самые большие и самые продуктивные в Лордероне плантации грибов.$b$bА теперь все это может быть потеряно из-за простой случайности!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здесь не всегда были эти славные поля, |3-6($c). Только благодаря нашей решительности и силе воли ветхие фермы людей превратились в самые большие и самые продуктивные в Лордероне плантации грибов.$b$bА теперь все это может быть потеряно из-за простой случайности!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17342,'Ладно, детка! Свет с собой? Держи его крепко, что бы ни случилось.$B$BОдно слово – и я отправлю тебя в царство духов. Духи – они придут к тебе, будут тянуть вниз, во тьму.$B$BОсвети их, эти жуткие создания!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ладно, детка! Свет с собой? Держи его крепко, что бы ни случилось.$B$BОдно слово – и я отправлю тебя в царство духов. Духи – они придут к тебе, будут тянуть вниз, во тьму.$B$BОсвети их, эти жуткие создания!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17345,'Хочешь потренироваться? Ничего не выйдет. Ищи другого наставника.','Хочешь потренироваться? Ничего не выйдет. Ищи другого наставника.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Хочешь потренироваться? Ничего не выйдет. Ищи другого наставника.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Хочешь потренироваться? Ничего не выйдет. Ищи другого наставника.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17346,'Хочешь потренироваться, боец?','Хочешь потренироваться, боец?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Хочешь потренироваться, боец?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Хочешь потренироваться, боец?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17347,'$n, я больше не слышу голосов. Что произошло в пещере?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','$n, я больше не слышу голосов. Что произошло в пещере?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17348,'Ты что, хочешь, чтобы немногое оставшееся от Тысячи Игл полностью уничтожили?$B$BНет?$B$BТогда делай то, что я приказываю.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты что, хочешь, чтобы немногое оставшееся от Тысячи Игл полностью уничтожили?$B$BНет?$B$BТогда делай то, что я приказываю.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17349,'Сюда мы приводим выживших, чтоб подготовить их к санобработке. Отсюда уже рукой подать до поверхности!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Сюда мы приводим выживших, чтоб подготовить их к санобработке. Отсюда уже рукой подать до поверхности!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17350,'Я уверен, вам не нужно лишний раз напоминать о том, что здесь нужно быть начеку.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я уверен, вам не нужно лишний раз напоминать о том, что здесь нужно быть начеку.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17354,'Тут все так растет!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тут все так растет!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17356,'Дворфы Громового Молота – наши смертельные враги. Либо мы, либо они.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Дворфы Громового Молота – наши смертельные враги. Либо мы, либо они.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17357,'Оставь меня в покое.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Оставь меня в покое.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17359,'Я узнавайт, кто сделать предательством!$B$BИ тогда...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я узнавайт, кто сделать предательством!$B$BИ тогда...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`) VALUES (17360,'Если когда-нибудь ты вдруг на самом деле заинтересуешь меня по-настоящему... мой тебе совет – беги.','Глупо было являться сюда, |3-6($r), забыв, какие силы тебя окружают.','Тебе страшно, смертное создание.$B$BЯ чую твой страх.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если когда-нибудь ты вдруг на самом деле заинтересуешь меня по-настоящему... мой тебе совет – беги.',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Глупо было являться сюда, |3-6($r), забыв, какие силы тебя окружают.',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Тебе страшно, смертное создание.$B$BЯ чую твой страх.',`text2_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17361,'Давай все же к делу. Если можно – коротко и ясно.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Давай все же к делу. Если можно – коротко и ясно.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17362,'Король отправляет чужестранца собирать для него сведения? Ты, должно быть, как это... название есть специальное... $R? Да, |3-6($r)-спаситель принца Надуна.$B$BЛично я не видел ни одного неферсета так далеко на севере. Тут и без них забот хватает.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Король отправляет чужестранца собирать для него сведения? Ты, должно быть, как это... название есть специальное... $R? Да, |3-6($r)-спаситель принца Надуна.$B$BЛично я не видел ни одного неферсета так далеко на севере. Тут и без них забот хватает.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17364,'Нет. Это работа шайки Скитальцев Пустыни.$B$BХодят слухи, что они объединились с еще одной бандой на западе и творят что хотят.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Нет. Это работа шайки Скитальцев Пустыни.$B$BХодят слухи, что они объединились с еще одной бандой на западе и творят что хотят.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17365,'Я слышал, ты сейчас из города. Что же ты за странное такое создание.$B$BНе хочешь со мной поговорить?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я слышал, ты сейчас из города. Что же ты за странное такое создание.$B$BНе хочешь со мной поговорить?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17366,'Нет, в Неферсете все спокойно. Вот в Орсисе недавно была жуткая песчаная буря, да.$B$BЯ уж хотел послать королю сообщение об этом, но ты ведь и так расскажешь, да?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Нет, в Неферсете все спокойно. Вот в Орсисе недавно была жуткая песчаная буря, да.$B$BЯ уж хотел послать королю сообщение об этом, но ты ведь и так расскажешь, да?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17367,'Мы долго лелеяли надежду на то, что нам удастся спасти Хранителя земли и его детей. Но вдруг поняли, что эти драконы никогда не смогут искупить свою вину.$B$BПоэтому мы должны вмешаться и остановить разрушение этого мира.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мы долго лелеяли надежду на то, что нам удастся спасти Хранителя земли и его детей. Но вдруг поняли, что эти драконы никогда не смогут искупить свою вину.$B$BПоэтому мы должны вмешаться и остановить разрушение этого мира.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17368,'Ох... Как же мне не хотелось сюда приезжать!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ох... Как же мне не хотелось сюда приезжать!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17370,'Меня ослепила жажда наживы.$B$BА я должен был предвидеть это заранее...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Меня ослепила жажда наживы.$B$BА я должен был предвидеть это заранее...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17371,'Пропали все мои сбережения.$B$BПросто не знаю, что теперь делать.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Пропали все мои сбережения.$B$BПросто не знаю, что теперь делать.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17372,'Это просто невыносимо.$B$BЯ думала, у меня хватит духу... <рыдает>') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Это просто невыносимо.$B$BЯ думала, у меня хватит духу... <рыдает>',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17373,'Я думал, он знает ответы на все вопросы.$B$BНу... надеялся.$B$BА он оказался пустышкой.$B$BКак же я сглупил.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я думал, он знает ответы на все вопросы.$B$BНу... надеялся.$B$BА он оказался пустышкой.$B$BКак же я сглупил.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17374,'Морской конек нетерпеливо плещется.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Морской конек нетерпеливо плещется.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17382,'На столе нет ничего интересного.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','На столе нет ничего интересного.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17383,'На столе лежит несколько кучек припасов. Ты решаешь начать со шкур ворга.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','На столе лежит несколько кучек припасов. Ты решаешь начать со шкур ворга.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17384,'Ты замечаешь ворох шкур ворга, собранных тобой ранее. Они лягут в основу твоего костюма.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты замечаешь ворох шкур ворга, собранных тобой ранее. Они лягут в основу твоего костюма.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17385,'Осматривая стол, ты замечаешь насыщенную обсидианом грязь, собранную тобой ранее в потоках лавы. Она потребуется для покраски твоего маскировочного костюма.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Осматривая стол, ты замечаешь насыщенную обсидианом грязь, собранную тобой ранее в потоках лавы. Она потребуется для покраски твоего маскировочного костюма.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17386,'Наконец, ты находишь нить, способную сшить детали костюма.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Наконец, ты находишь нить, способную сшить детали костюма.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17387,'Ты $gсобрал:собрала; необходимые припасы. Отнеси их Теларону Крутоиглу для пошива костюма.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты $gсобрал:собрала; необходимые припасы. Отнеси их Теларону Крутоиглу для пошива костюма.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17394,'Тебе не сыскать более искусного мастера во всем клане Черного Железа!$b$bКовка, кузнечное или горное дело – все пустое! Из всего металла меня привлекает только иголка да наперсток!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тебе не сыскать более искусного мастера во всем клане Черного Железа!$b$bКовка, кузнечное или горное дело – все пустое! Из всего металла меня привлекает только иголка да наперсток!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17395,'Что там у тебя?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что там у тебя?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17397,'Будь проклята Драконья Пасть!$B$BОни убивают наших птиц, нападают на наши семьи, отнимают наши земли. Мир рушится, но они все равно нападают на нас!$B$BЕсли твой Альянс хочет заручиться поддержкой Громового Молота, есть только один способ сделать это. Остановите. Драконью. Пасть.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Будь проклята Драконья Пасть!$B$BОни убивают наших птиц, нападают на наши семьи, отнимают наши земли. Мир рушится, но они все равно нападают на нас!$B$BЕсли твой Альянс хочет заручиться поддержкой Громового Молота, есть только один способ сделать это. Остановите. Драконью. Пасть.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17398,'<Бланди отрывается от своих чашек.>$B$BАга, точно. Верховный шаман в полях, сражается за Громтар. А я... как это... "Младший шаман".$B$BИ пока его нет, всем... шаманством... занимаюсь я.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Бланди отрывается от своих чашек.>$B$BАга, точно. Верховный шаман в полях, сражается за Громтар. А я... как это... "Младший шаман".$B$BИ пока его нет, всем... шаманством... занимаюсь я.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17399,'Громтар – последняя крепость Громовых Молотов. В наш городок стекаются беженцы, а мой брат пытается организовать его оборону.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Громтар – последняя крепость Громовых Молотов. В наш городок стекаются беженцы, а мой брат пытается организовать его оборону.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17400,'Я из авангарда войск Высокого берега – пытаюсь заручиться поддержкой Громового Молота здесь, в Громтаре.$B$BМне кажется, я мог бы помочь им, но, веришь ли, у них нет ни одного трицикличного реполяризационного устройства? Ни одного!$B$BКак они тут вообще живут?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я из авангарда войск Высокого берега – пытаюсь заручиться поддержкой Громового Молота здесь, в Громтаре.$B$BМне кажется, я мог бы помочь им, но, веришь ли, у них нет ни одного трицикличного реполяризационного устройства? Ни одного!$B$BКак они тут вообще живут?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17401,'Привет, |3-6($c)! Я из авангарда войск Высокого берега – пытаюсь заручиться поддержкой Громового Молота здесь, в Громтаре.$B$BДраконы клана Драконьей Пасти сильно досаждают их грифонам. У меня есть план устройства, которое пригодилось бы Молотам, но для его создания мне нужны материалы. Много материалов.$B$BТы мне поможешь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Привет, |3-6($c)! Я из авангарда войск Высокого берега – пытаюсь заручиться поддержкой Громового Молота здесь, в Громтаре.$B$BДраконы клана Драконьей Пасти сильно досаждают их грифонам. У меня есть план устройства, которое пригодилось бы Молотам, но для его создания мне нужны материалы. Много материалов.$B$BТы мне поможешь?',`text0_0_loc8`);
