INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17406,'В корпусе голема ты находишь несколько пригодных деталей. Похоже, тебе удастся достать лишь одну запчасть.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','В корпусе голема ты находишь несколько пригодных деталей. Похоже, тебе удастся достать лишь одну запчасть.',`text0_0_loc8`);
