INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17407,'Да, чего тебе?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да, чего тебе?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17409,'Я командую всеми войсками Альянса здесь, в Сумеречном нагорье.$B$BЗдесь до сих пор живут независимые кланы Громового Молота. Если мы убедим их встать под знамена Альянса, нас уже никто не остановит! Но враги атакуют со всех сторон. Надеюсь, ты можешь держать в руках оружие, |3-6($c).') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я командую всеми войсками Альянса здесь, в Сумеречном нагорье.$B$BЗдесь до сих пор живут независимые кланы Громового Молота. Если мы убедим их встать под знамена Альянса, нас уже никто не остановит! Но враги атакуют со всех сторон. Надеюсь, ты можешь держать в руках оружие, |3-6($c).',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17410,'Ух ты!$B$BНадо будет как-нибудь повторить.$B$BА сейчас нужно включить работу мозга. Как закончу, догоню.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ух ты!$B$BНадо будет как-нибудь повторить.$B$BА сейчас нужно включить работу мозга. Как закончу, догоню.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17417,'Враг может похоронить под песком целые города. Мы не готовы к такой войне.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Враг может похоронить под песком целые города. Мы не готовы к такой войне.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17418,'Со временем мы заново отстроим это место и возродим его былую славу. Здесь лишь не будет этих надоедливых людишек.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Со временем мы заново отстроим это место и возродим его былую славу. Здесь лишь не будет этих надоедливых людишек.',`text0_0_loc8`);
