INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17419,'Теперь, когда проклятый остров оказался в наших руках, нужно привести его в порядок. Поможешь нам в этом, $n?','Теперь, когда проклятый остров оказался в наших руках, нужно привести его в порядок. Поможешь нам в этом, $n?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Теперь, когда проклятый остров оказался в наших руках, нужно привести его в порядок. Поможешь нам в этом, $n?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Теперь, когда проклятый остров оказался в наших руках, нужно привести его в порядок. Поможешь нам в этом, $n?',`text0_1_loc8`);
