INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17420,'Я не в восторге от блока Д, о котором все только знай и болтают. Перед тем как мы сможем его использовать, нужно кое-что сделать.','Я не в восторге от блока Д, о котором все только знай и болтают. Перед тем как мы сможем его использовать, нужно кое-что сделать.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я не в восторге от блока Д, о котором все только знай и болтают. Перед тем как мы сможем его использовать, нужно кое-что сделать.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я не в восторге от блока Д, о котором все только знай и болтают. Перед тем как мы сможем его использовать, нужно кое-что сделать.',`text0_1_loc8`);
