INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17422,'Добро пожаловать на Тол Барад, |3-6($c). Хватит бить баклуши, давай займемся делом.','Добро пожаловать на Тол Барад, |3-6($c). Хватит бить баклуши, давай займемся делом.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать на Тол Барад, |3-6($c). Хватит бить баклуши, давай займемся делом.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Добро пожаловать на Тол Барад, |3-6($c). Хватит бить баклуши, давай займемся делом.',`text0_1_loc8`);
