INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17425,'Непросто заключить договор с орками Черной горы. Нет, ты только подумай! Это ведь орки Черной горы! У этих вояк на счету битв больше, чем у Агграмара, и они совершают набеги со скалы из черного железа! Хо-хо!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Непросто заключить договор с орками Черной горы. Нет, ты только подумай! Это ведь орки Черной горы! У этих вояк на счету битв больше, чем у Агграмара, и они совершают набеги со скалы из черного железа! Хо-хо!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
