INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17427,'Надо же, как я вовремя!$B$BПолагаю, этого ковботца-Штонца мы еще не раз увидим.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Надо же, как я вовремя!$B$BПолагаю, этого ковботца-Штонца мы еще не раз увидим.',`text0_0_loc8`);
