INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17432,'Это работайт кто-то свой!$B$BПодозревайт любой!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Это работайт кто-то свой!$B$BПодозревайт любой!',`text0_0_loc8`);
