INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17442,'Когда-нибудь я смогу служить Рамкахену.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Когда-нибудь я смогу служить Рамкахену.',`text0_0_loc8`);
