INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17443,'Все! Они пошли в решительное наступление. Бежать некуда. Мы удержим Громтар – или умрем с молотом в руках.$B$BЗа Громовой Молот!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Все! Они пошли в решительное наступление. Бежать некуда. Мы удержим Громтар – или умрем с молотом в руках.$B$BЗа Громовой Молот!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17445,'Лига исследователей и Реликварий похожи друг на друга: наша религия – археология, но мы все утратили истинную веру.\r\n\r\nЧто бы они ни говорили, наши методы не так уж отличаются. Мы – всего лишь их отражение.\r\n\r\nДля того чтобы сделать их подобными нам, не понадобится больших усилий. Нужно всего лишь слегка подтолкнуть их в сторону Тьмы...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Лига исследователей и Реликварий похожи друг на друга: наша религия – археология, но мы все утратили истинную веру.\r\n\r\nЧто бы они ни говорили, наши методы не так уж отличаются. Мы – всего лишь их отражение.\r\n\r\nДля того чтобы сделать их подобными нам, не понадобится больших усилий. Нужно всего лишь слегка подтолкнуть их в сторону Тьмы...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17450,'Видения мутнеют... Как и эти воды.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Видения мутнеют... Как и эти воды.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17451,'Похоже, что за друидами приглядывают сектанты!$b$bСквозь портал ты можешь увидеть Лагерь Дикого Сердца. Войдешь в него – снова окажешься в лагере.$b$bТаким образом, ты сможешь быстро вернуться, когда закончишь все дела здесь.','Похоже, что за друидами приглядывают сектанты!$b$bСквозь портал ты можешь увидеть Лагерь Дикого Сердца. Войдешь в него – снова окажешься в лагере.$b$bТаким образом, ты сможешь быстро вернуться, когда закончишь все дела здесь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Похоже, что за друидами приглядывают сектанты!$b$bСквозь портал ты можешь увидеть Лагерь Дикого Сердца. Войдешь в него – снова окажешься в лагере.$b$bТаким образом, ты сможешь быстро вернуться, когда закончишь все дела здесь.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Похоже, что за друидами приглядывают сектанты!$b$bСквозь портал ты можешь увидеть Лагерь Дикого Сердца. Войдешь в него – снова окажешься в лагере.$b$bТаким образом, ты сможешь быстро вернуться, когда закончишь все дела здесь.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17455,'Что там у тебя, козявка? Не видишь, я занят?!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что там у тебя, козявка? Не видишь, я занят?!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17456,'Просто невыносимо торчать тут с кучей чернокнижников. Этим должен заниматься Кси\'лун, а не я!$b$bНе могу дождаться начала битвы. Мне нужно быть снаружи рядом с драконами.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Просто невыносимо торчать тут с кучей чернокнижников. Этим должен заниматься Кси\'лун, а не я!$b$bНе могу дождаться начала битвы. Мне нужно быть снаружи рядом с драконами.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17457,'Ба, вы посмотрите! Это же $gнаш экзекутор:наша исполнительница наказаний;!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ба, вы посмотрите! Это же $gнаш экзекутор:наша исполнительница наказаний;!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17459,'Асульдар Несокрушимый и другие преподаватели находятся над площадью Странников, рядом с плавильней.','Асульдар Несокрушимый и другие преподаватели находятся над площадью Странников, рядом с плавильней.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Асульдар Несокрушимый и другие преподаватели находятся над площадью Странников, рядом с плавильней.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Асульдар Несокрушимый и другие преподаватели находятся над площадью Странников, рядом с плавильней.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17462,'Добро пожаловать в Лагерь бухты Барадин. Знаю, что сейчас тут не на что посмотреть, но стоит приложить немного усилий, и мы приведем это место в порядок.','Добро пожаловать в Лагерь бухты Барадин. Знаю, что сейчас тут не на что посмотреть, но стоит приложить немного усилий, и мы приведем это место в порядок.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать в Лагерь бухты Барадин. Знаю, что сейчас тут не на что посмотреть, но стоит приложить немного усилий, и мы приведем это место в порядок.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Добро пожаловать в Лагерь бухты Барадин. Знаю, что сейчас тут не на что посмотреть, но стоит приложить немного усилий, и мы приведем это место в порядок.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17463,'Кажется, тут постоянно найдется какая-то работенка. Новые приказы поступают ежедневно в три часа ночи, что очень странно.','Кажется, тут постоянно найдется какая-то работенка. Новые приказы поступают ежедневно в три часа ночи, что очень странно.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Кажется, тут постоянно найдется какая-то работенка. Новые приказы поступают ежедневно в три часа ночи, что очень странно.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Кажется, тут постоянно найдется какая-то работенка. Новые приказы поступают ежедневно в три часа ночи, что очень странно.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17467,'После падения Грим Батола мы, клан Громового Молота, были сами по себе. Весь остальной мир забыл про нас.$B$BОбъединить кланы будет нелегко.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','После падения Грим Батола мы, клан Громового Молота, были сами по себе. Весь остальной мир забыл про нас.$B$BОбъединить кланы будет нелегко.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`) VALUES (17469,'Вместе мы будем творить историю!','Скоро о нас заговорит весь Азерот!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вместе мы будем творить историю!',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Скоро о нас заговорит весь Азерот!',`text1_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17472,'Эти чудовища полагают, что могут безнаказанно разорять МОЙ город?! О, они узнают, что такое правосудие Громового Молота!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эти чудовища полагают, что могут безнаказанно разорять МОЙ город?! О, они узнают, что такое правосудие Громового Молота!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17473,'Если мы не поднимем производительность, Орда может проиграть эту войну. Если Орда проиграет войну, то в лучшем случае нас вышибут пинком под задницу, а в худшем – мы покойники.$b$bНе хотелось бы тебя расстраивать, но все эти приятные вещи, о которых тебе могли рассказать в Роще Шелеста Ветра, вряд ли нас спасут... а вот ударная работа – может.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Если мы не поднимем производительность, Орда может проиграть эту войну. Если Орда проиграет войну, то в лучшем случае нас вышибут пинком под задницу, а в худшем – мы покойники.$b$bНе хотелось бы тебя расстраивать, но все эти приятные вещи, о которых тебе могли рассказать в Роще Шелеста Ветра, вряд ли нас спасут... а вот ударная работа – может.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17477,'Я здесь, чтобы свидетельствовать во имя и истины и памяти о моем хозяине.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я здесь, чтобы свидетельствовать во имя и истины и памяти о моем хозяине.',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17482,'Спасибо за спасение моей жизни! Но не говори ничего Ферли, ладно? Я сказал ей, что сумел сбежать сам!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Спасибо за спасение моей жизни! Но не говори ничего Ферли, ладно? Я сказал ей, что сумел сбежать сам!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17483,'Помалкивай и держись с подветренной стороны.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Помалкивай и держись с подветренной стороны.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17484,'Мало кто из нас жил в этих землях после того, как по ним впервые прошла Коса Элуны. Многим пришлось пережить падение Гилнеаса.$b$bМы поселились в этих лесах, чтобы поддержать их баланс и изучить законы дикой природы. В этих проклятых землях наш проклятый народ стал жить по-новому.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мало кто из нас жил в этих землях после того, как по ним впервые прошла Коса Элуны. Многим пришлось пережить падение Гилнеаса.$b$bМы поселились в этих лесах, чтобы поддержать их баланс и изучить законы дикой природы. В этих проклятых землях наш проклятый народ стал жить по-новому.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17485,'Это задел на будущее. От нашего плана зависит очень многое. Например, свобода Красногорья.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Это задел на будущее. От нашего плана зависит очень многое. Например, свобода Красногорья.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17486,'Я не позволю гнусным оркам снова захватить Красногорье!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я не позволю гнусным оркам снова захватить Красногорье!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
