INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17494,'Слушай, дружище, я бы и рад тебе помочь – честное слово! – но сначала тебе надо завоевать полное доверие гоблинов картеля Трюмных Вод.','Слушай, дружище, я бы и рада тебе помочь – честное слово! – но сначала тебе надо завоевать полное доверие гоблинов картеля Трюмных Вод.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Слушай, дружище, я бы и рад тебе помочь – честное слово! – но сначала тебе надо завоевать полное доверие гоблинов картеля Трюмных Вод.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Слушай, дружище, я бы и рада тебе помочь – честное слово! – но сначала тебе надо завоевать полное доверие гоблинов картеля Трюмных Вод.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17495,'Йоу! Я Колл Ворзатрон, продавец трициклетов.$B$BВыбирай хорошенько, не торопись! Подбери себе такой трициклет, чтобы сердце радовал!$B$BБыстрый как молния... суровый и опасный... трициклет, которым ты будешь гордиться!$B$BКак найдешь такой – дай мне знать, а о цене договоримся!','Йоу! Я Колл Ворзатрон, продавец трициклетов.$B$BВыбирай хорошенько, не торопись! Подбери себе такой трициклет, чтобы сердце радовал!$B$BБыстрый как молния... суровый и опасный... трициклет, которым ты будешь гордиться!$B$BКак найдешь такой – дай мне знать, а о цене договоримся!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Йоу! Я Колл Ворзатрон, продавец трициклетов.$B$BВыбирай хорошенько, не торопись! Подбери себе такой трициклет, чтобы сердце радовал!$B$BБыстрый как молния... суровый и опасный... трициклет, которым ты будешь гордиться!$B$BКак найдешь такой – дай мне знать, а о цене договоримся!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Йоу! Я Колл Ворзатрон, продавец трициклетов.$B$BВыбирай хорошенько, не торопись! Подбери себе такой трициклет, чтобы сердце радовал!$B$BБыстрый как молния... суровый и опасный... трициклет, которым ты будешь гордиться!$B$BКак найдешь такой – дай мне знать, а о цене договоримся!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17496,'Вперед-вперед, на карту поставлено слишком многое.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вперед-вперед, на карту поставлено слишком многое.',`text0_0_loc8`);
