INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17498,'Они на вершине здоровенного здания в юго-восточном углу долины.','Они на вершине здоровенного здания в юго-восточном углу долины.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Они на вершине здоровенного здания в юго-восточном углу долины.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Они на вершине здоровенного здания в юго-восточном углу долины.',`text0_1_loc8`);
