INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17499,'Ты, никак, $gпришел:пришла; учиться рыбу ловить? Или припасы для рыбалки закончились?','Ты, никак, $gпришел:пришла; учиться рыбу ловить? Или припасы для рыбалки закончились?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты, никак, $gпришел:пришла; учиться рыбу ловить? Или припасы для рыбалки закончились?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты, никак, $gпришел:пришла; учиться рыбу ловить? Или припасы для рыбалки закончились?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17500,'Слушай!$B$BА ведь если убрать кристаллы, это все рухнет.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Слушай!$B$BА ведь если убрать кристаллы, это все рухнет.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17503,'Ха!$B$BТебе действительно удалось вызвать песчаную бурю, $n.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ха!$B$BТебе действительно удалось вызвать песчаную бурю, $n.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17504,'Орки Черной горы – моя родня. Мой отец принадлежал к клану Черной горы, как и все мои предки. Моя мать тоже была в этом клане. И я сам тоже являюсь представителем Черной горы.$b$bОднако, прежде всего, я орк. И для меня честь превыше всего.$b$bМой вождь разрешил мне уйти, чтобы дать закончить свою миссию в Пылающих степях. И я не уйду до тех пор, пока не проучу орков Черной горы.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Орки Черной горы – моя родня. Мой отец принадлежал к клану Черной горы, как и все мои предки. Моя мать тоже была в этом клане. И я сам тоже являюсь представителем Черной горы.$b$bОднако, прежде всего, я орк. И для меня честь превыше всего.$b$bМой вождь разрешил мне уйти, чтобы дать закончить свою миссию в Пылающих степях. И я не уйду до тех пор, пока не проучу орков Черной горы.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17505,'Я выполняю волю своего отца и с уважением отношусь к его плану… но у меня есть собственное чувство справедливости. Мне довелось увидеть столько подлости со стороны своих собратьев из клана Черной горы, что хватило бы на тысячу книг. И вот теперь они собираются захватить Красногорье, просто чтобы расширить свои владения.$b$bИх гнусности стоит положить конец. Пришла пора поставить точку в этой истории. И уверяю, это будет история со счастливым концом.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я выполняю волю своего отца и с уважением отношусь к его плану… но у меня есть собственное чувство справедливости. Мне довелось увидеть столько подлости со стороны своих собратьев из клана Черной горы, что хватило бы на тысячу книг. И вот теперь они собираются захватить Красногорье, просто чтобы расширить свои владения.$b$bИх гнусности стоит положить конец. Пришла пора поставить точку в этой истории. И уверяю, это будет история со счастливым концом.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17511,'Дерек Приход Тьмы к вашим услугам!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Дерек Приход Тьмы к вашим услугам!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17512,'Оба! А я и не знал, что у Суллы такой... широкий круг знакомств.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Оба! А я и не знал, что у Суллы такой... широкий круг знакомств.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17513,'Привет, друг!$B$BМеня зовут Рассел, а мое ремесло – музыка. Мы, дворфы Громового Молота, храним память о наших великих героях в своих песнях. Моя лютня дарует бессмертие прославленным воинам.$B$BПослушай мои песни!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Привет, друг!$B$BМеня зовут Рассел, а мое ремесло – музыка. Мы, дворфы Громового Молота, храним память о наших великих героях в своих песнях. Моя лютня дарует бессмертие прославленным воинам.$B$BПослушай мои песни!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17514,'Говори, с чем $gпожаловал:пожаловала;, |3-6($c).') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Говори, с чем $gпожаловал:пожаловала;, |3-6($c).',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17515,'Я уже настроил лютню. Ну что, можем приступать?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я уже настроил лютню. Ну что, можем приступать?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17516,'Начнем! Первый куплет должен быть про милую Фанни, но я все никак не решу, на чем сосредоточиться.$B$BА ты как считаешь, что нам стоит воспеть?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Начнем! Первый куплет должен быть про милую Фанни, но я все никак не решу, на чем сосредоточиться.$B$BА ты как считаешь, что нам стоит воспеть?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17518,'Хм... ладно, это подойдет. Последний куплет! Куплет во славу любви, зовущий Громовой Молот в бой!$B$BКакой эта свадьба запомнится потомкам?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Хм... ладно, это подойдет. Последний куплет! Куплет во славу любви, зовущий Громовой Молот в бой!$B$BКакой эта свадьба запомнится потомкам?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17521,'Осторожно, $gпарень:девочка;. Внизу полно воргов, а в ущелье – орков, так что |3-6($c) вроде тебя может погибнуть в два счета.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Осторожно, $gпарень:девочка;. Внизу полно воргов, а в ущелье – орков, так что |3-6($c) вроде тебя может погибнуть в два счета.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17532,'Хочешь прокатиться с ветерком, дорогуша? Забирайся внутрь. Мы направляемся в Веслотопь, и это маршрут в один конец!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Хочешь прокатиться с ветерком, дорогуша? Забирайся внутрь. Мы направляемся в Веслотопь, и это маршрут в один конец!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17533,'Добро пожаловать, друг Громового Молота!$B$BКирт – это духовный центр нашего народа, место, где представители разных кланов могут встретиться, ничего не опасаясь.$B$BЗдесь мы воздаем почести павшим героям, прежде чем похоронить их вместе с грифонами на вершине Громобой-горы. Там они уходят в небо и вечность.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать, друг Громового Молота!$B$BКирт – это духовный центр нашего народа, место, где представители разных кланов могут встретиться, ничего не опасаясь.$B$BЗдесь мы воздаем почести павшим героям, прежде чем похоронить их вместе с грифонами на вершине Громобой-горы. Там они уходят в небо и вечность.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17535,'Свадьба непременно состоится! Конечно, мне понадобится подарок для молодоженов. Что-нибудь очень ценное.$B$BВедь это наш последний шанс объединить кланы!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Свадьба непременно состоится! Конечно, мне понадобится подарок для молодоженов. Что-нибудь очень ценное.$B$BВедь это наш последний шанс объединить кланы!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17536,'Теперь, когда моя империя мороженого создана, обязательно попробуй мои вкуснейшие творения!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Теперь, когда моя империя мороженого создана, обязательно попробуй мои вкуснейшие творения!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17537,'Эй! Как дела, босс? Мы с Хобартом тут изобретаем кое-какие замечательные штуки на тот случай, если у нас закончится каджа\'мит.$B$BВедь его месторождения истощаются, а когда он совсем закончится, боюсь, что исчезнет и "Каджа-Кола".') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Эй! Как дела, босс? Мы с Хобартом тут изобретаем кое-какие замечательные штуки на тот случай, если у нас закончится каджа\'мит.$B$BВедь его месторождения истощаются, а когда он совсем закончится, боюсь, что исчезнет и "Каджа-Кола".',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17540,'Эй, $gприятель:подруга;! С нами все будет в порядке?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эй, $gприятель:подруга;! С нами все будет в порядке?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17542,'<Гоббер храбрится, но видно, что внутри он сильно напуган.>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Гоббер храбрится, но видно, что внутри он сильно напуган.>',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`,`text1_1_loc8`,`text2_1_loc8`,`text3_1_loc8`,`text4_1_loc8`,`text5_1_loc8`,`text6_1_loc8`) VALUES (17549,'Ну? Че нада?','Со всяким сбродом я не разговариваю!','Тебе до меня, как до луны, лапочка.','Я и в школе с тобой не общалась, и сейчас не собираюсь.','Интересный у тебя... "костюм".','Да. Принеси мне еще выпить, да побыстрее.','Лапка, это вечеринка торгового принца. Вход только по приглашениям!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ну? Че нада?',`text0_1_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Со всяким сбродом я не разговариваю!',`text1_1_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Тебе до меня, как до луны, лапочка.',`text2_1_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','Я и в школе с тобой не общалась, и сейчас не собираюсь.',`text3_1_loc8`), `text4_1_loc8`=IF(`text4_1_loc8` IS NULL OR `text4_1_loc8`='','Интересный у тебя... "костюм".',`text4_1_loc8`), `text5_1_loc8`=IF(`text5_1_loc8` IS NULL OR `text5_1_loc8`='','Да. Принеси мне еще выпить, да побыстрее.',`text5_1_loc8`), `text6_1_loc8`=IF(`text6_1_loc8` IS NULL OR `text6_1_loc8`='','Лапка, это вечеринка торгового принца. Вход только по приглашениям!',`text6_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`,`text1_1_loc8`,`text2_1_loc8`,`text3_1_loc8`,`text4_1_loc8`,`text5_1_loc8`,`text6_1_loc8`,`text7_1_loc8`) VALUES (17550,'Муук?! С чудовищами я не разговариваю. Какая наглость!','Так как вы теперь называетесь? Чудовища? Хобгоблины?$B$BНикак не могу запомнить. Убирайся.','Ты – большое и сильное существо. Но тебе нужно помыться. Пойди и прыгни в бассейн.','О, нет! Нет, мы с тобой не разговаривали!','Откуда эта вонь? А, наверно, это ты.$B$BПроваливай!','Как тебя зовут?$B$BХорошо, что вы, чудовища, не умеете разговаривать. Иначе мне пришлось бы пожаловаться торговому принцу на то, что ты меня раздражаешь.$B$BА теперь проваливай!','Прикоснись ко мне еще раз, и я позабочусь о том, чтобы тебя отправили в шахты!','О, ты просто отвратительное чудовище! Ну почему разные уроды всегда пытаются меня снять?!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Муук?! С чудовищами я не разговариваю. Какая наглость!',`text0_1_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Так как вы теперь называетесь? Чудовища? Хобгоблины?$B$BНикак не могу запомнить. Убирайся.',`text1_1_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Ты – большое и сильное существо. Но тебе нужно помыться. Пойди и прыгни в бассейн.',`text2_1_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','О, нет! Нет, мы с тобой не разговаривали!',`text3_1_loc8`), `text4_1_loc8`=IF(`text4_1_loc8` IS NULL OR `text4_1_loc8`='','Откуда эта вонь? А, наверно, это ты.$B$BПроваливай!',`text4_1_loc8`), `text5_1_loc8`=IF(`text5_1_loc8` IS NULL OR `text5_1_loc8`='','Как тебя зовут?$B$BХорошо, что вы, чудовища, не умеете разговаривать. Иначе мне пришлось бы пожаловаться торговому принцу на то, что ты меня раздражаешь.$B$BА теперь проваливай!',`text5_1_loc8`), `text6_1_loc8`=IF(`text6_1_loc8` IS NULL OR `text6_1_loc8`='','Прикоснись ко мне еще раз, и я позабочусь о том, чтобы тебя отправили в шахты!',`text6_1_loc8`), `text7_1_loc8`=IF(`text7_1_loc8` IS NULL OR `text7_1_loc8`='','О, ты просто отвратительное чудовище! Ну почему разные уроды всегда пытаются меня снять?!',`text7_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`,`text4_0_loc8`,`text5_0_loc8`,`text6_0_loc8`,`text7_0_loc8`) VALUES (17552,'<К вашему изумлению, вылупившийся ящер обращается к вам с вопросом.>$B$B$gПапа:Мама;?!','<К вашему изумлению, вылупившийся ящер обращается к вам.>$B$BЯ голоден… значит, я существую.','<К вашему изумлению вылупившийся ящер обращается к вам с вопросом.>$B$BЧто такое "|3-6($c)"? Вы $gкакой-то:какая-то; глава гоблинов?','<К вашему изумлению, вылупившийся ящер обращается к вам с вопросом.>$B$BПривет. Я только что вылупился из яйца. А ты?','<К вашему изумлению, вылупившийся ящер обращается к вам с вопросом.>$B$BЭто правда, что вы не едите сырое мясо? Любопытно.','<К вашему изумлению, вылупившийся ящер обращается к вам с вопросом.>$B$BУ тебя нет шлема. Это как-то отражается на ваших интеллектуальных способностях?','<К вашему изумлению, вылупившийся ящер обращается к вам с вопросом.>$B$BКончики твоих пальцев тупые и закругленные. Поэтому ты дерешься в бою разными приспособлениями, которые носишь с собой?$B$BКак интересно.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<К вашему изумлению, вылупившийся ящер обращается к вам с вопросом.>$B$B$gПапа:Мама;?!',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','<К вашему изумлению, вылупившийся ящер обращается к вам.>$B$BЯ голоден… значит, я существую.',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','<К вашему изумлению вылупившийся ящер обращается к вам с вопросом.>$B$BЧто такое "|3-6($c)"? Вы $gкакой-то:какая-то; глава гоблинов?',`text2_0_loc8`), `text4_0_loc8`=IF(`text4_0_loc8` IS NULL OR `text4_0_loc8`='','<К вашему изумлению, вылупившийся ящер обращается к вам с вопросом.>$B$BПривет. Я только что вылупился из яйца. А ты?',`text4_0_loc8`), `text5_0_loc8`=IF(`text5_0_loc8` IS NULL OR `text5_0_loc8`='','<К вашему изумлению, вылупившийся ящер обращается к вам с вопросом.>$B$BЭто правда, что вы не едите сырое мясо? Любопытно.',`text5_0_loc8`), `text6_0_loc8`=IF(`text6_0_loc8` IS NULL OR `text6_0_loc8`='','<К вашему изумлению, вылупившийся ящер обращается к вам с вопросом.>$B$BУ тебя нет шлема. Это как-то отражается на ваших интеллектуальных способностях?',`text6_0_loc8`), `text7_0_loc8`=IF(`text7_0_loc8` IS NULL OR `text7_0_loc8`='','<К вашему изумлению, вылупившийся ящер обращается к вам с вопросом.>$B$BКончики твоих пальцев тупые и закругленные. Поэтому ты дерешься в бою разными приспособлениями, которые носишь с собой?$B$BКак интересно.',`text7_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17556,'Насчет Хобарта не беспокойтесь, босс. У него просто небольшой нервный срыв.$B$BЕму было и так нелегко, а тут еще этот катаклизм. Ведь Хобарт был так близок к созданию микромеханоцыпа.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Насчет Хобарта не беспокойтесь, босс. У него просто небольшой нервный срыв.$B$BЕму было и так нелегко, а тут еще этот катаклизм. Ведь Хобарт был так близок к созданию микромеханоцыпа.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17557,'Когда я был еще совсем маленьким, отец учил меня уважать стихии – землю и огонь, ветер и море, ведь они обладают огромной силой, |3-6($c).$B$B<Глаза Грунди сверкают.>$B$BОни гораздо могущественнее, чем ты думаешь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Когда я был еще совсем маленьким, отец учил меня уважать стихии – землю и огонь, ветер и море, ведь они обладают огромной силой, |3-6($c).$B$B<Глаза Грунди сверкают.>$B$BОни гораздо могущественнее, чем ты думаешь.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17558,'Я – псилософ. Это означает, что я умнее тебя. Проходи мимо, пока я не поставил тебе диагноз.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я – псилософ. Это означает, что я умнее тебя. Проходи мимо, пока я не поставил тебе диагноз.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17559,'Ох!$B$BНу наконец-то!$B$BЯ тебя уже несколько дней жду.$B$BОставить старого дворфа на такой жарище... В наше время так не поступали.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ох!$B$BНу наконец-то!$B$BЯ тебя уже несколько дней жду.$B$BОставить старого дворфа на такой жарище... В наше время так не поступали.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17564,'Прочь от меня, поганище!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Прочь от меня, поганище!',`text0_1_loc8`);
