INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17565,'Нежить – это позор Азерота! Все вы должны быть уничтожены!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Нежить – это позор Азерота! Все вы должны быть уничтожены!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17566,'Назад, чудовище. Хочешь драться? Так я побью тебя.$b$bИ любого из вас, монстры. Слышите меня?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Назад, чудовище. Хочешь драться? Так я побью тебя.$b$bИ любого из вас, монстры. Слышите меня?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17567,'Правда?$b$bОтлично. Я не хочу присоединяться к тебе и твоим Отрекшимся. Может быть, я организую свою собственную коалицию Отрекшихся! Может быть, это будут Отрекшиеся с локтями!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Правда?$b$bОтлично. Я не хочу присоединяться к тебе и твоим Отрекшимся. Может быть, я организую свою собственную коалицию Отрекшихся! Может быть, это будут Отрекшиеся с локтями!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17569,'Что… что происходит? Кто ты? Что со мной случилось?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что… что происходит? Кто ты? Что со мной случилось?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17570,'Я… умер?$b$bДа, это правда. Я умер. Это был орк… Он отрубил мне руки и оставил меня умирать.$b$b<Валдред опускает голову и смотрит на свои руки.>$b$bЭто не мои руки! ЭТО НЕ МОИ РУКИ!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я… умер?$b$bДа, это правда. Я умер. Это был орк… Он отрубил мне руки и оставил меня умирать.$b$b<Валдред опускает голову и смотрит на свои руки.>$b$bЭто не мои руки! ЭТО НЕ МОИ РУКИ!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17571,'<Валдред снова смотрит на свои руки.>$b$bВидимо, это моя судьба. Ха! В армии нежити. Почему-то я никогда не думал, что в конце концов буду биться на стороне Отрекшихся.$b$b<Он снова смотрит на вас.>$b$bЧто мне сейчас делать?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Валдред снова смотрит на свои руки.>$b$bВидимо, это моя судьба. Ха! В армии нежити. Почему-то я никогда не думал, что в конце концов буду биться на стороне Отрекшихся.$b$b<Он снова смотрит на вас.>$b$bЧто мне сейчас делать?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17573,'Пираты?! Босс, вы должны разобраться с ними! Они портят всю вечеринку!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Пираты?! Босс, вы должны разобраться с ними! Они портят всю вечеринку!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17574,'Похоже, дело дрянь, босс.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Похоже, дело дрянь, босс.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17575,'Босс, мы должны любым способом добыть миллиард деревянных!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Босс, мы должны любым способом добыть миллиард деревянных!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17576,'Мы должны закончить здесь все дела и доставить вас в доки, пока торговый принц не отчалил!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мы должны закончить здесь все дела и доставить вас в доки, пока торговый принц не отчалил!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17578,'Ах, да... Нам надо поговорить.$B$BДавай попозже, а?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ах, да... Нам надо поговорить.$B$BДавай попозже, а?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17582,'Я готов, так что можно начинать. Но на всякий случай буду держать жениха и невесту поблизости – вдруг Сумеречный Молот решит устроить нам какую-нибудь пакость.$B$BНу что, все готово?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я готов, так что можно начинать. Но на всякий случай буду держать жениха и невесту поблизости – вдруг Сумеречный Молот решит устроить нам какую-нибудь пакость.$B$BНу что, все готово?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17583,'Хватит ли тебе силы и смелости, чтобы справиться с тем, что ждет тебя в подземельях Азерота? Если да, тогда заходи...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Хватит ли тебе силы и смелости, чтобы справиться с тем, что ждет тебя в подземельях Азерота? Если да, тогда заходи...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17585,'Я так понимаю, что Алекстраза выступила против Смертокрыла? Возможно, на этом все и закончится.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я так понимаю, что Алекстраза выступила против Смертокрыла? Возможно, на этом все и закончится.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17586,'Добро пожаловать в деревню Звездопада, $gпутешественник:путешественница;. Ты $gпришел:пришла; нам помочь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать в деревню Звездопада, $gпутешественник:путешественница;. Ты $gпришел:пришла; нам помочь?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17587,'Моя семья многие годы занимается борьбой с насекомыми! Конечно, мы не откажем в помощи.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Моя семья многие годы занимается борьбой с насекомыми! Конечно, мы не откажем в помощи.',`text0_0_loc8`);
