INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17589,'Поздравляю, $gискатель:искательница; приключений.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Поздравляю, $gискатель:искательница; приключений.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17590,'Тебе удалось угодить прямиком в мою ловушку!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Тебе удалось угодить прямиком в мою ловушку!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17594,'Мне сказали, что именно тебя я должен благодарить за исцеление. Спасибо. От всего сердца.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мне сказали, что именно тебя я должен благодарить за исцеление. Спасибо. От всего сердца.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17595,'Все, что нам нужно было сделать – развернуть летное-поле-в-коробке Психходельни и начать сбор данных!$B$BКак можно работать, когда вокруг одни идиоты?!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Все, что нам нужно было сделать – развернуть летное-поле-в-коробке Психходельни и начать сбор данных!$B$BКак можно работать, когда вокруг одни идиоты?!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17598,'Начальство прислало меня сюда, чтобы я расследовал странные происшествия, случившиеся в Пиратской Бухте. Несмотря на не слишком солидную репутацию гоблинов в сфере градостроения, их поселение удивление хорошо выстояло под напором приливной волны.$b$bПолагаю, что тут не обошлось без магии. Возможно, в Пиратской Бухте творится нечто серьезное, |3-6($c)...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Начальство прислало меня сюда, чтобы я расследовал странные происшествия, случившиеся в Пиратской Бухте. Несмотря на не слишком солидную репутацию гоблинов в сфере градостроения, их поселение удивление хорошо выстояло под напором приливной волны.$b$bПолагаю, что тут не обошлось без магии. Возможно, в Пиратской Бухте творится нечто серьезное, |3-6($c)...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17599,'Ты $gготов:готова; покинуть Тернистую долину?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты $gготов:готова; покинуть Тернистую долину?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17600,'Ох, ну почему хоть раз нельзя обойтись без сложностей!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ох, ну почему хоть раз нельзя обойтись без сложностей!',`text0_0_loc8`);
