INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17606,'Круто ты $Gразделался:разделалась; с этими големами, $Gдружище:подруга;.$b$bТеперь проход в хранилище свободен.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Круто ты $Gразделался:разделалась; с этими големами, $Gдружище:подруга;.$b$bТеперь проход в хранилище свободен.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17607,'Я принес весточку от короля Ринна, |3-6($c). Видишь эту доску с призывами героям? Там размещаются все указы короля, обращенные к искателям приключений. В эти неспокойные времена их помощь Альянсу требуется во многих уголках планеты.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я принес весточку от короля Ринна, |3-6($c). Видишь эту доску с призывами героям? Там размещаются все указы короля, обращенные к искателям приключений. В эти неспокойные времена их помощь Альянсу требуется во многих уголках планеты.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17608,'Лок\'тар, |3-6($c). Позади меня находится доска, на которой вывешены приказы военачальника. Прочти их, и ты поймешь, где сможешь принести наибольшую пользу Орде.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Лок\'тар, |3-6($c). Позади меня находится доска, на которой вывешены приказы военачальника. Прочти их, и ты поймешь, где сможешь принести наибольшую пользу Орде.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17611,'Нельзя допустить, чтобы жертвы моих братьев из Серебряного Рассвета стали напрасными. Они верили в Орден, но никто из них не дожил до того дня, когда Свет вернулся в эти земли.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Нельзя допустить, чтобы жертвы моих братьев из Серебряного Рассвета стали напрасными. Они верили в Орден, но никто из них не дожил до того дня, когда Свет вернулся в эти земли.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17615,'Добро пожаловать, $gбрат мой:сестра моя;. Если ты $gпришел:пришла; за знаниями, я буду счастлив обучить тебя.$B$BПока Малфурион лежит в Изумрудном сне, мы – единственные хранители равновесия. Никогда не забывай этого.','Добро пожаловать, $gбрат мой:сестра моя;. Если ты $gпришел:пришла; за знаниями, я буду счастлива обучить тебя.$B$BПока Малфурион лежит в Изумрудном сне, мы – единственные хранители равновесия. Никогда не забывай этого.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать, $gбрат мой:сестра моя;. Если ты $gпришел:пришла; за знаниями, я буду счастлив обучить тебя.$B$BПока Малфурион лежит в Изумрудном сне, мы – единственные хранители равновесия. Никогда не забывай этого.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Добро пожаловать, $gбрат мой:сестра моя;. Если ты $gпришел:пришла; за знаниями, я буду счастлива обучить тебя.$B$BПока Малфурион лежит в Изумрудном сне, мы – единственные хранители равновесия. Никогда не забывай этого.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17616,'$C, наш повелитель Малфурион возвратился из Сна. Он – свет маяка, что указывает нам путь, и мы должны сделать все, что в наших силах, дабы сохранить этот свет.','$C, наш повелитель Малфурион возвратился из Сна. Он – свет маяка, что указывает нам путь, и мы должны сделать все, что в наших силах, дабы сохранить этот свет.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','$C, наш повелитель Малфурион возвратился из Сна. Он – свет маяка, что указывает нам путь, и мы должны сделать все, что в наших силах, дабы сохранить этот свет.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','$C, наш повелитель Малфурион возвратился из Сна. Он – свет маяка, что указывает нам путь, и мы должны сделать все, что в наших силах, дабы сохранить этот свет.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17619,'Камешек подпрыгивает и с надеждой смотрит на вас. Он определенно вас помнит.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Камешек подпрыгивает и с надеждой смотрит на вас. Он определенно вас помнит.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17620,'Покинуть это место труднее, чем я думал.$B$BКуда идти, когда и идти-то, по сути, некуда?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Покинуть это место труднее, чем я думал.$B$BКуда идти, когда и идти-то, по сути, некуда?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17627,'Буровая установка немного заржавела, но все еще действует.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Буровая установка немного заржавела, но все еще действует.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17629,'Почему ты обращаешься ко мне? Да у тебя и близко нет столько золота, сколько у меня.$b$bИди и вращайся в своем кругу, $gприятель:подруга;.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Почему ты обращаешься ко мне? Да у тебя и близко нет столько золота, сколько у меня.$b$bИди и вращайся в своем кругу, $gприятель:подруга;.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17630,'Да, друг мой, все еще намерены. Они не очень хотят передавать свои знания всему нашему роду, но они будут продолжать учить нас, пока мы будем заботиться о процветании всего живого на островах. Уходя, Гонк велел нам связаться с ним, если другие лоа не захотят исполнить обещанное.$B$BНадеюсь, до этого не дойдет... но на всякий случай мы установили связь с ребятами из Круга Кенария.$B$B<Зен\'табра истерически смеется.>$B$B$GВидел:Видела; бы ты рожи этих ночных эльфов...') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Да, друг мой, все еще намерены. Они не очень хотят передавать свои знания всему нашему роду, но они будут продолжать учить нас, пока мы будем заботиться о процветании всего живого на островах. Уходя, Гонк велел нам связаться с ним, если другие лоа не захотят исполнить обещанное.$B$BНадеюсь, до этого не дойдет... но на всякий случай мы установили связь с ребятами из Круга Кенария.$B$B<Зен\'табра истерически смеется.>$B$B$GВидел:Видела; бы ты рожи этих ночных эльфов...',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17631,'Вот уже много лун мы служим духам, и многие из нас научились принимать обличья лоа, которым мы раньше служили. Это сложно объяснить... словно бы сам Изумрудный Сон учит нас наравне с духами-наставниками, приближая нас к цели. $B$BЭто не значит, что мы теперь можем не бояться Залазана. Многие наши братья и сестры погибли от рук его безмозглых прислужников, и все знания духов не уберегли их от его магии. Но мы смогли сохранить жизнь на островах, и когда Вол\'джин вернулся туда с племенем Черного Копья – мы уже знали, как помочь ему свергнуть Залазана.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Вот уже много лун мы служим духам, и многие из нас научились принимать обличья лоа, которым мы раньше служили. Это сложно объяснить... словно бы сам Изумрудный Сон учит нас наравне с духами-наставниками, приближая нас к цели. $B$BЭто не значит, что мы теперь можем не бояться Залазана. Многие наши братья и сестры погибли от рук его безмозглых прислужников, и все знания духов не уберегли их от его магии. Но мы смогли сохранить жизнь на островах, и когда Вол\'джин вернулся туда с племенем Черного Копья – мы уже знали, как помочь ему свергнуть Залазана.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17632,'<Зен\'табра смеется.>$B$BДругие лоа, особенно Ширвалла, не одобрили этот план. Они хотели, чтобы мы продолжали служить только им, а не всем духам. Но Гонк убедил их, что это единственный способ спасти острова и освободить их из-под власти Залазана.$B$BМне кажется, что Гонка не слишком заботит мнение других лоа. Он все время подтрунивает над ними, когда они делятся своими знаниями.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','<Зен\'табра смеется.>$B$BДругие лоа, особенно Ширвалла, не одобрили этот план. Они хотели, чтобы мы продолжали служить только им, а не всем духам. Но Гонк убедил их, что это единственный способ спасти острова и освободить их из-под власти Залазана.$B$BМне кажется, что Гонка не слишком заботит мнение других лоа. Он все время подтрунивает над ними, когда они делятся своими знаниями.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17633,'Безмозглые слуги Залазана в жестокости своей уничтожали все живое на островах, сжигали деревья и вырывали с корнем растения. Гонк просил нас спасти обитателей островов. Он показал нам новый способ поддерживать связь с духами природы, работать вместе с ними, а не просто служить лоа.$B$BЭто было нелегко, но Гонк показал нам, как входить в Изумрудный Сон, чтобы говорить с духами и перенимать их мудрость.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Безмозглые слуги Залазана в жестокости своей уничтожали все живое на островах, сжигали деревья и вырывали с корнем растения. Гонк просил нас спасти обитателей островов. Он показал нам новый способ поддерживать связь с духами природы, работать вместе с ними, а не просто служить лоа.$B$BЭто было нелегко, но Гонк показал нам, как входить в Изумрудный Сон, чтобы говорить с духами и перенимать их мудрость.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17634,'<Зен\'табра наклоняется к вам, сияя клыкастой улыбкой.>$B$BВ том видении я была в джунглях, только еще более диких и непроходимых, а передо мной стоял древний ящер-лоа, о которых я слышала в легендах зандаларов. То был сам Гонк, великий охотник!$B$BДух раптора сказал, что перенес меня в место, именуемое Изумрудным Сном. Магия Залазана пленила его, как и всех остальных духов островов Эха, но Гонк все же смог дотянуться до меня с помощью своей древней силы.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','<Зен\'табра наклоняется к вам, сияя клыкастой улыбкой.>$B$BВ том видении я была в джунглях, только еще более диких и непроходимых, а передо мной стоял древний ящер-лоа, о которых я слышала в легендах зандаларов. То был сам Гонк, великий охотник!$B$BДух раптора сказал, что перенес меня в место, именуемое Изумрудным Сном. Магия Залазана пленила его, как и всех остальных духов островов Эха, но Гонк все же смог дотянуться до меня с помощью своей древней силы.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17635,'<Зен\'табра закрывает глаза и печально качает головой.>$B$BКогда Вол\'джин призвал всех спасаться бегством, мы... мы не смогли присоединиться к остальному племени. Чувство вины погнало нас на юг, на острова, покрытые непроходимыми джунглями. $B$BВ первую же ночь многие из нас погибли в столкновении с дикой природой. Оставшиеся были вынуждены укрыться в глубокой пещере посередине острова, но и во сне мне не было покоя: мне было ниспослано видение!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','<Зен\'табра закрывает глаза и печально качает головой.>$B$BКогда Вол\'джин призвал всех спасаться бегством, мы... мы не смогли присоединиться к остальному племени. Чувство вины погнало нас на юг, на острова, покрытые непроходимыми джунглями. $B$BВ первую же ночь многие из нас погибли в столкновении с дикой природой. Оставшиеся были вынуждены укрыться в глубокой пещере посередине острова, но и во сне мне не было покоя: мне было ниспослано видение!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17636,'Некоторые служили жрецами лоа, другие были шаманами, как Залазан...$B$B<Зен\'табра устремляет взгляд на юг, лицо ее ожесточается.>$B$BМы думали, что прогневали духов, а оказалось, что это Залазан понемногу отрезал нас от общения с ними. Мы знали, что он силен, но не предполагали, что настолько... А когда его вуду достигло других островов... мы не смогли его остановить.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Некоторые служили жрецами лоа, другие были шаманами, как Залазан...$B$B<Зен\'табра устремляет взгляд на юг, лицо ее ожесточается.>$B$BМы думали, что прогневали духов, а оказалось, что это Залазан понемногу отрезал нас от общения с ними. Мы знали, что он силен, но не предполагали, что настолько... А когда его вуду достигло других островов... мы не смогли его остановить.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17637,'<Зен\'табра смеется.>$B$BМы сами распространяем такие слухи, дружище – главным образом для того, чтобы стряхнуть с хвоста Залазана. Так что не верь всему, что слышишь. На самом деле, мы лишь недавно начали постигать тайны друидов, но, думаю, можно сказать, что мы всю жизнь готовились ответить на зов природы...') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','<Зен\'табра смеется.>$B$BМы сами распространяем такие слухи, дружище – главным образом для того, чтобы стряхнуть с хвоста Залазана. Так что не верь всему, что слышишь. На самом деле, мы лишь недавно начали постигать тайны друидов, но, думаю, можно сказать, что мы всю жизнь готовились ответить на зов природы...',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17638,'Большая часть моего отряда погибла при попытке проникнуть в пределы Неферсета.$B$BОтплатить за их смерти – мой долг.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Большая часть моего отряда погибла при попытке проникнуть в пределы Неферсета.$B$BОтплатить за их смерти – мой долг.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17659,'Ничем не могу помочь, |3-6($c).','Ничем не могу помочь, |3-6($c).') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ничем не могу помочь, |3-6($c).',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ничем не могу помочь, |3-6($c).',`text0_1_loc8`);
