INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17661,'Этой операцией командую я.$B$BПоэтому никакого нытья по поводу того, что наш транспорт горит или что враги значительно выше нас. Мы все профессионалы, поэтому будем работать молча и эффективно.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Этой операцией командую я.$B$BПоэтому никакого нытья по поводу того, что наш транспорт горит или что враги значительно выше нас. Мы все профессионалы, поэтому будем работать молча и эффективно.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17662,'<Агент ШРУ находится без сознания.>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Агент ШРУ находится без сознания.>',`text0_0_loc8`);
