INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17665,'Эй, туда лучше не суйся. Последний несчастный |3-6($r) там не выжил.$B$BОх уж этот бедный вкусный |3-6($r)...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эй, туда лучше не суйся. Последний несчастный |3-6($r) там не выжил.$B$BОх уж этот бедный вкусный |3-6($r)...',`text0_0_loc8`);
