INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17696,'Сколько времени тебе потребуется, чтобы развернуть это место?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Сколько времени тебе потребуется, чтобы развернуть это место?',`text0_1_loc8`);
