INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17698,'С точки зрения Света зомби – гоблины они или нет – поганища. Кроме того, они не приносят никакой прибыли.$b$bПо крайней мере пока.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','С точки зрения Света зомби – гоблины они или нет – поганища. Кроме того, они не приносят никакой прибыли.$b$bПо крайней мере пока.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17700,'Создание городской обстановки в природных условиях. Я в восторге!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Создание городской обстановки в природных условиях. Я в восторге!',`text0_1_loc8`);
