INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17702,'Можно ли подкрасться к зомби? Разве они не учуют твои мозги, если подберешься к ним близко?$B$BЕсли так, то половине местных совершенно нечего бояться.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Можно ли подкрасться к зомби? Разве они не учуют твои мозги, если подберешься к ним близко?$B$BЕсли так, то половине местных совершенно нечего бояться.',`text0_1_loc8`);
