INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17710,'Этот Шнотц сумасшедший! Я ни за что не вернусь!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Этот Шнотц сумасшедший! Я ни за что не вернусь!',`text0_0_loc8`);
