INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17712,'Я специализируюсь на двух вещах: маленькое превращаю в большое, а большое в маленькое.$B$BЧем сегодня займемся?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я специализируюсь на двух вещах: маленькое превращаю в большое, а большое в маленькое.$B$BЧем сегодня займемся?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17713,'Победа или смерть, |3-6($c)!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Победа или смерть, |3-6($c)!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17725,'Эти драконы шутить не собираются. Не уверен, что наши желторотики понимают, во что они влипли.$B$BНо ничего, все будет в порядке. Мои парни возьмут командование на себя и выполнят задачу. Все что нам нужно – это немного свободного места.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эти драконы шутить не собираются. Не уверен, что наши желторотики понимают, во что они влипли.$B$BНо ничего, все будет в порядке. Мои парни возьмут командование на себя и выполнят задачу. Все что нам нужно – это немного свободного места.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17726,'Добро пожаловать в Фюзель-на-водах, красивый приморский городок, построенный любителями взрывчатки для любителей взрывчатки.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать в Фюзель-на-водах, красивый приморский городок, построенный любителями взрывчатки для любителей взрывчатки.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17733,'Эта статуя – сплошная головная боль. Я рассчитывала, что нам удастся вытащить ее из воды с помощью крана и пары взрывов. Но Вик полагает, что нужно применить более безопасные методы и закатить ее наверх по скату. $B$BТы посмотри на нее. Она же повернута не той стороной! Ну, затащим мы ее наверх, и что дальше?$B$BПохоже, мы тут надолго застряли...') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Эта статуя – сплошная головная боль. Я рассчитывала, что нам удастся вытащить ее из воды с помощью крана и пары взрывов. Но Вик полагает, что нужно применить более безопасные методы и закатить ее наверх по скату. $B$BТы посмотри на нее. Она же повернута не той стороной! Ну, затащим мы ее наверх, и что дальше?$B$BПохоже, мы тут надолго застряли...',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17735,'Я так хорошо потрудился в порту Штормграда, что, казалось бы, заслужил передышку. Но нет, этому дворфу все мало...$B$BЯ просто хочу как можно быстрее затащить эту статую наверх и поставить на место. Но она все время жалуется и тормозит работу! А если возникают проблемы, то у нее только одно решение – взорвать все к чертовой матери! Честно слово, я бы предпочел работать с гномами или гоблинами – те, по крайней мере, были бы трезвые.$B$BПосмотри на нашу бригаду. Никакой дисциплины! И знаешь, почему? Потому что она подрывает мой авторитет!$B$BПлохое начальство, ленивая бригада... Похоже, эта бодяга затянется надолго.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я так хорошо потрудился в порту Штормграда, что, казалось бы, заслужил передышку. Но нет, этому дворфу все мало...$B$BЯ просто хочу как можно быстрее затащить эту статую наверх и поставить на место. Но она все время жалуется и тормозит работу! А если возникают проблемы, то у нее только одно решение – взорвать все к чертовой матери! Честно слово, я бы предпочел работать с гномами или гоблинами – те, по крайней мере, были бы трезвые.$B$BПосмотри на нашу бригаду. Никакой дисциплины! И знаешь, почему? Потому что она подрывает мой авторитет!$B$BПлохое начальство, ленивая бригада... Похоже, эта бодяга затянется надолго.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17736,'Здесь долгое время был Круг Кенария. Мы, тролли, пришли сюда уже позже.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здесь долгое время был Круг Кенария. Мы, тролли, пришли сюда уже позже.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17740,'Привет, |3-6($c). Мы, дворфы Громового Молота, всегда награждаем наших друзей.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Привет, |3-6($c). Мы, дворфы Громового Молота, всегда награждаем наших друзей.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17741,'В бытность Азшары королевой этот город был одной из эльфийских столиц. В нем сокрыто множество утраченных знаний и древних артефактов колоссального исторического значения.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','В бытность Азшары королевой этот город был одной из эльфийских столиц. В нем сокрыто множество утраченных знаний и древних артефактов колоссального исторического значения.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17742,'Адмирал повел свои войска на одну из баз, что ты $gобследовал:обследовала; для него ранее. Отправляйся за ним.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Адмирал повел свои войска на одну из баз, что ты $gобследовал:обследовала; для него ранее. Отправляйся за ним.',`text0_1_loc8`);
