INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17743,'Капитан повел свои войска на одну из баз, что ты $gобследовал:обследовала; для него ранее. Отправляйся за ним.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Капитан повел свои войска на одну из баз, что ты $gобследовал:обследовала; для него ранее. Отправляйся за ним.',`text0_1_loc8`);
