INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17745,'Прими мои искренние извинения, |3-6($c), но секреты высокорожденных так и останутся для тебя секретами.','Прими мои искренние извинения, |3-6($c), но секреты высокорожденных так и останутся для тебя секретами.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Прими мои искренние извинения, |3-6($c), но секреты высокорожденных так и останутся для тебя секретами.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Прими мои искренние извинения, |3-6($c), но секреты высокорожденных так и останутся для тебя секретами.',`text0_1_loc8`);
