INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17746,'Служи Драконьей Пасти – и тебя щедро наградят, |3-6($c).') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Служи Драконьей Пасти – и тебя щедро наградят, |3-6($c).',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17747,'Современная магия меркнет по сравнению с тем, что могли творить маги прошлого. Но мы, высокорожденные, сохранили кое-какие знания прошлых тысячелетий. Хочешь ли ты изучить что-то новое?','Современная магия меркнет по сравнению с тем, что могли творить маги прошлого. Но мы, высокорожденные, сохранили кое-какие знания прошлых тысячелетий. Хочешь ли ты изучить что-то новое?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Современная магия меркнет по сравнению с тем, что могли творить маги прошлого. Но мы, высокорожденные, сохранили кое-какие знания прошлых тысячелетий. Хочешь ли ты изучить что-то новое?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Современная магия меркнет по сравнению с тем, что могли творить маги прошлого. Но мы, высокорожденные, сохранили кое-какие знания прошлых тысячелетий. Хочешь ли ты изучить что-то новое?',`text0_1_loc8`);
