INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17748,'Халбин Молот Стужи из клана Громового Молота обычно сидит в таверне "Громоварка". Он поможет тебе стать шаманом.','Халбин Молот Стужи из клана Громового Молота обычно сидит в таверне "Громоварка". Он поможет тебе стать шаманом.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Халбин Молот Стужи из клана Громового Молота обычно сидит в таверне "Громоварка". Он поможет тебе стать шаманом.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Халбин Молот Стужи из клана Громового Молота обычно сидит в таверне "Громоварка". Он поможет тебе стать шаманом.',`text0_1_loc8`);
