INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (17759,'Чтобы добраться до рут\'теранской переправы, тебе нужно прийти в Дарнас и воспользоваться порталом в деревню Рут\'теран, расположенную у подножия Тельдрассила.','Чтобы добраться до рут\'теранской переправы, тебе нужно прийти в Дарнас и воспользоваться порталом в деревню Рут\'теран, расположенную у подножия Тельдрассила.','Если тебе нужен гиппогриф, поговори с Фиделио.','Если тебе нужен гиппогриф, поговори с Фиделио.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Чтобы добраться до рут\'теранской переправы, тебе нужно прийти в Дарнас и воспользоваться порталом в деревню Рут\'теран, расположенную у подножия Тельдрассила.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Чтобы добраться до рут\'теранской переправы, тебе нужно прийти в Дарнас и воспользоваться порталом в деревню Рут\'теран, расположенную у подножия Тельдрассила.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Если тебе нужен гиппогриф, поговори с Фиделио.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Если тебе нужен гиппогриф, поговори с Фиделио.',`text1_1_loc8`);
