INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17770,'Высокорожденный верховный маг нанес визит городскому учителю наложения чар. Он может помочь вам с чародейской перековкой предметов.','Высокорожденный верховный маг нанес визит городскому учителю наложения чар. Он может помочь вам с чародейской перековкой предметов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Высокорожденный верховный маг нанес визит городскому учителю наложения чар. Он может помочь вам с чародейской перековкой предметов.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Высокорожденный верховный маг нанес визит городскому учителю наложения чар. Он может помочь вам с чародейской перековкой предметов.',`text0_1_loc8`);
