INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17816,'Тебе надоел твой демонический спутник? Хочешь нового, с более симпатичным именем?\r\n\r\nЗа небольшую плату я могу помочь тебе отделаться от одного из твоих прислужников, чтобы ты $gмог:могла; призвать нового...','Тебе надоел твой демонический спутник? Хочешь нового, с более симпатичным именем?\r\n\r\nЗа небольшую плату я могу помочь тебе отделаться от одного из твоих прислужников, чтобы ты $gмог:могла; призвать нового...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тебе надоел твой демонический спутник? Хочешь нового, с более симпатичным именем?\r\n\r\nЗа небольшую плату я могу помочь тебе отделаться от одного из твоих прислужников, чтобы ты $gмог:могла; призвать нового...',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Тебе надоел твой демонический спутник? Хочешь нового, с более симпатичным именем?\r\n\r\nЗа небольшую плату я могу помочь тебе отделаться от одного из твоих прислужников, чтобы ты $gмог:могла; призвать нового...',`text0_1_loc8`);
