INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17836,'Добро пожаловать на фестиваль Плетеного человека, |3-6($c)! $b$bОтмечая Тыквовин, мы сжигаем фигуру Плетеного человека в знак очищения. Как деревья осенью сбрасывают листья, там и мы должны пройти через освобождение от того, что отжило свое. Страхи, печали, сожаления: все, что тяготит тебя, сгорит в огне, если ты бросишь в него ветку.$B$BВыбирай любую ветку из костра и присоединяйся к нашему празднику!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Добро пожаловать на фестиваль Плетеного человека, |3-6($c)! $b$bОтмечая Тыквовин, мы сжигаем фигуру Плетеного человека в знак очищения. Как деревья осенью сбрасывают листья, там и мы должны пройти через освобождение от того, что отжило свое. Страхи, печали, сожаления: все, что тяготит тебя, сгорит в огне, если ты бросишь в него ветку.$B$BВыбирай любую ветку из костра и присоединяйся к нашему празднику!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17837,'Ты чувствуешь зло, оскверняющее эту землю? Оно исходит из глубин Оплота Теней. Если мы ничего не предпримем, оно поглотит все живое.$B$B<Ночной эльф судорожно глотает воздух, и вы видите на его боку страшную рану.>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты чувствуешь зло, оскверняющее эту землю? Оно исходит из глубин Оплота Теней. Если мы ничего не предпримем, оно поглотит все живое.$B$B<Ночной эльф судорожно глотает воздух, и вы видите на его боку страшную рану.>',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17838,'Только самые отважные и благородные члены племени могут заслужить почесть быть похороненными в Красных скалах.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Только самые отважные и благородные члены племени могут заслужить почесть быть похороненными в Красных скалах.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17840,'Хотя многие борются с огнем, гасят его, а потом вновь зажигают, каждый может выразить свое почтение к нему, |3-6($c). $b$bСлужители Земли относятся к огню с почтением, но не с легкомыслием.$b$bСейчас мы собираемся провести ритуал почитания огня в соответствии с традицией. Ты присоединишься к нам, $n?','Хотя многие борются с огнем, гасят его, а потом вновь зажигают, каждый может выразить свое почтение к нему, |3-6($c). $b$bСлужители Земли относятся к огню с почтением, но не с легкомыслием.$b$bСейчас мы собираемся провести ритуал почитания огня в соответствии с традицией. Ты присоединишься к нам, $n?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Хотя многие борются с огнем, гасят его, а потом вновь зажигают, каждый может выразить свое почтение к нему, |3-6($c). $b$bСлужители Земли относятся к огню с почтением, но не с легкомыслием.$b$bСейчас мы собираемся провести ритуал почитания огня в соответствии с традицией. Ты присоединишься к нам, $n?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Хотя многие борются с огнем, гасят его, а потом вновь зажигают, каждый может выразить свое почтение к нему, |3-6($c). $b$bСлужители Земли относятся к огню с почтением, но не с легкомыслием.$b$bСейчас мы собираемся провести ритуал почитания огня в соответствии с традицией. Ты присоединишься к нам, $n?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17842,'Вы пришли к костру Служителей Земли!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вы пришли к костру Служителей Земли!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17843,'Меня засек один из проклятых джеденарских демонов и хорошенько потрепал меня за бок. Рана выглядит паршиво, но жить буду.$B$BСейчас меня больше беспокоит, как одолеть Совет Теней и не дать ему напасть на наших союзников в Лагере Дикого Сердца. Увы, я не могу сражаться, но ты можешь занять мое место.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Меня засек один из проклятых джеденарских демонов и хорошенько потрепал меня за бок. Рана выглядит паршиво, но жить буду.$B$BСейчас меня больше беспокоит, как одолеть Совет Теней и не дать ему напасть на наших союзников в Лагере Дикого Сердца. Увы, я не могу сражаться, но ты можешь занять мое место.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17849,'Тыквовин на дворе! Надеюсь, тебе нравится этот праздник.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Тыквовин на дворе! Надеюсь, тебе нравится этот праздник.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17855,'Добро пожаловать на Участок Целителей Земли, |3-6($c).') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Добро пожаловать на Участок Целителей Земли, |3-6($c).',`text0_1_loc8`);
