INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`) VALUES (17856,'На что ты смотришь, клыкарролицый?','Арр-р!','Якорь мне в глотку!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','На что ты смотришь, клыкарролицый?',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Арр-р!',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Якорь мне в глотку!',`text2_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17857,'Боюсь, история старины Дункана – невеселая. Я ведь был капитаном на своем собственном корабле, ты знаешь?$b$bА теперь всего лишь одно понижение в должности отделяет меня от звания простого моряка. Не думал, что когда-то мне доведется пережить такое унижение.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Боюсь, история старины Дункана – невеселая. Я ведь был капитаном на своем собственном корабле, ты знаешь?$b$bА теперь всего лишь одно понижение в должности отделяет меня от звания простого моряка. Не думал, что когда-то мне доведется пережить такое унижение.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17859,'Хотя я и тоскую по Гилнеасу, нужно исследовать эти древние руины!','Хотя я и тоскую по Гилнеасу, нужно исследовать эти древние руины!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Хотя я и тоскую по Гилнеасу, нужно исследовать эти древние руины!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Хотя я и тоскую по Гилнеасу, нужно исследовать эти древние руины!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17861,'Жизнь охотника за сокровищами полна опасностей. Не обманывай себя.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Жизнь охотника за сокровищами полна опасностей. Не обманывай себя.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17866,'Наши братья из крепости Барадин, что на Тол Бараде, очень заняты и не всегда располагают временем, когда ты нуждаешься в их помощи. Я же нахожусь здесь круглые сутки для того, чтобы помочь тебе с теми заданиями, которые они могут тебе дать.','Наши братья из крепости Барадин, что на Тол Бараде, очень заняты и не всегда располагают временем, когда ты нуждаешься в их помощи. Я же нахожусь здесь круглые сутки для того, чтобы помочь тебе с теми заданиями, которые они могут тебе дать.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Наши братья из крепости Барадин, что на Тол Бараде, очень заняты и не всегда располагают временем, когда ты нуждаешься в их помощи. Я же нахожусь здесь круглые сутки для того, чтобы помочь тебе с теми заданиями, которые они могут тебе дать.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Наши братья из крепости Барадин, что на Тол Бараде, очень заняты и не всегда располагают временем, когда ты нуждаешься в их помощи. Я же нахожусь здесь круглые сутки для того, чтобы помочь тебе с теми заданиями, которые они могут тебе дать.',`text0_1_loc8`);
