INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17878,'Что ты можешь предложить мне, чтобы я не выгнал тебя со своей кухни?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что ты можешь предложить мне, чтобы я не выгнал тебя со своей кухни?',`text0_0_loc8`);
