INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17880,'Этот телепорт перенесет тебя в лагерь Гром\'гол в Северной Тернистой долине./b/bНу, то есть, обычно он туда переносит./b/bЯ к тому, что иногда вместо телепортации происходит дезинтеграция, и мягкие ткани объекта замещаются зеленым желеобразным составом с неприятным ароматом. Но это бывает редко!/b/b...последнее время.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Этот телепорт перенесет тебя в лагерь Гром\'гол в Северной Тернистой долине./b/bНу, то есть, обычно он туда переносит./b/bЯ к тому, что иногда вместо телепортации происходит дезинтеграция, и мягкие ткани объекта замещаются зеленым желеобразным составом с неприятным ароматом. Но это бывает редко!/b/b...последнее время.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
