INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`,`text1_1_loc8`,`text2_1_loc8`,`text3_1_loc8`) VALUES (17890,'Чем Бвемба может тебе помочь?','Бвемба будет присматривать за тобой.','Мой дух будет хранить тебя, $n.','Не очень-то легко передвигаться в виде духа.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Чем Бвемба может тебе помочь?',`text0_1_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Бвемба будет присматривать за тобой.',`text1_1_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Мой дух будет хранить тебя, $n.',`text2_1_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','Не очень-то легко передвигаться в виде духа.',`text3_1_loc8`);
