INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17891,'Ищешь путь силы, да? А если этот путь окажется таким же проклятым, как и мой?','Ищешь путь силы, да? А если этот путь окажется таким же проклятым, как и мой?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ищешь путь силы, да? А если этот путь окажется таким же проклятым, как и мой?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ищешь путь силы, да? А если этот путь окажется таким же проклятым, как и мой?',`text0_1_loc8`);
