INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17892,'Я иду темным путем, |3-6($c). Тебе не надо следовать за мной.','Я иду темным путем, |3-6($c). Тебе не надо следовать за мной.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я иду темным путем, |3-6($c). Тебе не надо следовать за мной.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я иду темным путем, |3-6($c). Тебе не надо следовать за мной.',`text0_1_loc8`);
