INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17901,'Все караваны, идущие на север, в Ясеневый лес, останавливаются здесь, чтобы отдохнуть и пополнить запасы провианта. Для нас очень важно, чтобы все шло гладко.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Все караваны, идущие на север, в Ясеневый лес, останавливаются здесь, чтобы отдохнуть и пополнить запасы провианта. Для нас очень важно, чтобы все шло гладко.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17904,'Добро пожаловать, $gбрат мой:сестра моя;. Если ты $gпришел:пришла; за знаниями, я буду счастлив обучить тебя.','Добро пожаловать, $gбрат мой:сестра моя;. Если ты $gпришел:пришла; за знаниями, я буду счастлива обучить тебя.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать, $gбрат мой:сестра моя;. Если ты $gпришел:пришла; за знаниями, я буду счастлив обучить тебя.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Добро пожаловать, $gбрат мой:сестра моя;. Если ты $gпришел:пришла; за знаниями, я буду счастлива обучить тебя.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17905,'Если ты жаждешь изучить Старые обычаи, то тут я тебе не помощник.','Если ты жаждешь изучить Старые обычаи, то тут я тебе не помощница.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если ты жаждешь изучить Старые обычаи, то тут я тебе не помощник.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Если ты жаждешь изучить Старые обычаи, то тут я тебе не помощница.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17906,'За воротами города ты найдешь друида Дарета – вероятно, он сможет тебе помочь.$B$BБольшой такой ворген, носит белые кожаные одежды и меха. Мимо точно не пройдешь.','За воротами города ты найдешь друида Дарета – вероятно, он сможет тебе помочь.$B$BБольшой такой ворген, носит белые кожаные одежды и меха. Мимо точно не пройдешь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','За воротами города ты найдешь друида Дарета – вероятно, он сможет тебе помочь.$B$BБольшой такой ворген, носит белые кожаные одежды и меха. Мимо точно не пройдешь.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','За воротами города ты найдешь друида Дарета – вероятно, он сможет тебе помочь.$B$BБольшой такой ворген, носит белые кожаные одежды и меха. Мимо точно не пройдешь.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17907,'Привет! Ищешь кого-нибудь, кто подтянул бы пару винтов или ослабил гайки? Ты $gобратился:обратилась; по адресу.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Привет! Ищешь кого-нибудь, кто подтянул бы пару винтов или ослабил гайки? Ты $gобратился:обратилась; по адресу.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17941,'Уникальные игрушки со всего Азерота! Сделано вручную!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Уникальные игрушки со всего Азерота! Сделано вручную!',`text0_0_loc8`);
