INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17946,'А, вот ты где, $n.$b$bМне срочно необходимо с тобой поговорить.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','А, вот ты где, $n.$b$bМне срочно необходимо с тобой поговорить.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17947,'Добро пожаловать в "Конус холода"! Наше уникальное мороженое заморожено до надлежащего состояния одним из лучших штормградских учеников мага!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать в "Конус холода"! Наше уникальное мороженое заморожено до надлежащего состояния одним из лучших штормградских учеников мага!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17949,'$gГотов:Готова; предстать перед Немесисом? Надеюсь, ты держишь свой тотем наготове.$b$bДай мне знать, когда начать призыв.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','$gГотов:Готова; предстать перед Немесисом? Надеюсь, ты держишь свой тотем наготове.$b$bДай мне знать, когда начать призыв.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17951,'Не мешкай, $n.$b$bАнахронос ждет.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Не мешкай, $n.$b$bАнахронос ждет.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text1_0_loc8`,`text2_0_loc8`,`text3_0_loc8`,`text4_0_loc8`,`text5_0_loc8`,`text6_0_loc8`,`text7_0_loc8`) VALUES (17952,'Этот артефакт кажется неповрежденным, хотя на нем такой слой пыли и грязи, что сложно сказать наверняка. Кажется, в нем не сокрыто особо могущественной магии.','Этот артефакт пережил множество бурь и знатно износился. Сомнительно, что хотя бы часть сил, которые были изначально в него заложены, сохранились.','К этому объекту пристали листья и ветки, указывающие на то, что он мог быть частью гнезда какого-нибудь создания. Больше о нем нельзя сказать ничего определенного.','Вы видите, что на этом объекте вырезаны странные символы. Вероятно, это сделали тролли, когда пытались понять, что же это такое. Не похоже, чтобы они достигли своей цели, поскольку не похоже, чтобы объект обладал какой-либо силой.','Артефакт покрыт таинственными рунами, которые, впрочем, кажется, не действуют.','Этот объект очевидно низкого качества и очень напоминает поддельные артефакты, которые в последнее время наводнили черный рынок.','Вы видите на этом объекте несколько капель высохшей крови. Вероятно, они появились там в результате попыток троллей завладеть этим артефактом. Впрочем, эта штука весьма простая и вред ли стоила того, чтобы за нее бороться.') ON DUPLICATE KEY UPDATE `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Этот артефакт кажется неповрежденным, хотя на нем такой слой пыли и грязи, что сложно сказать наверняка. Кажется, в нем не сокрыто особо могущественной магии.',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Этот артефакт пережил множество бурь и знатно износился. Сомнительно, что хотя бы часть сил, которые были изначально в него заложены, сохранились.',`text2_0_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','К этому объекту пристали листья и ветки, указывающие на то, что он мог быть частью гнезда какого-нибудь создания. Больше о нем нельзя сказать ничего определенного.',`text3_0_loc8`), `text4_0_loc8`=IF(`text4_0_loc8` IS NULL OR `text4_0_loc8`='','Вы видите, что на этом объекте вырезаны странные символы. Вероятно, это сделали тролли, когда пытались понять, что же это такое. Не похоже, чтобы они достигли своей цели, поскольку не похоже, чтобы объект обладал какой-либо силой.',`text4_0_loc8`), `text5_0_loc8`=IF(`text5_0_loc8` IS NULL OR `text5_0_loc8`='','Артефакт покрыт таинственными рунами, которые, впрочем, кажется, не действуют.',`text5_0_loc8`), `text6_0_loc8`=IF(`text6_0_loc8` IS NULL OR `text6_0_loc8`='','Этот объект очевидно низкого качества и очень напоминает поддельные артефакты, которые в последнее время наводнили черный рынок.',`text6_0_loc8`), `text7_0_loc8`=IF(`text7_0_loc8` IS NULL OR `text7_0_loc8`='','Вы видите на этом объекте несколько капель высохшей крови. Вероятно, они появились там в результате попыток троллей завладеть этим артефактом. Впрочем, эта штука весьма простая и вред ли стоила того, чтобы за нее бороться.',`text7_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17956,'Сохраняй спокойствие, $gсмертный:смертная;. Наша совместная работа должна быть плодотворной, ничто не должно мешать ей.$b$bЗдесь многое зависит от того, насколько ясно и рационально ты мыслишь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Сохраняй спокойствие, $gсмертный:смертная;. Наша совместная работа должна быть плодотворной, ничто не должно мешать ей.$b$bЗдесь многое зависит от того, насколько ясно и рационально ты мыслишь.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17960,'Привет тебе, |3-6($c)! Я Тхорк, командую здесь строительством защитных укреплений от имени Вождя.$B$BЯ смотрю, у тебя уже была возможность проявить себя в Перекрестке. Продолжай в том же духе! За Орду!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Привет тебе, |3-6($c)! Я Тхорк, командую здесь строительством защитных укреплений от имени Вождя.$B$BЯ смотрю, у тебя уже была возможность проявить себя в Перекрестке. Продолжай в том же духе! За Орду!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17961,'Ищешь шахтерскую гильдию рудокопов Темной Горы? Это к северу от Великой Кузни.','Ищешь шахтерскую гильдию рудокопов Темной Горы? Это к северу от Великой Кузни.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ищешь шахтерскую гильдию рудокопов Темной Горы? Это к северу от Великой Кузни.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ищешь шахтерскую гильдию рудокопов Темной Горы? Это к северу от Великой Кузни.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (17967,'Кузнеца и его ученика ты найдешь на Террасе Воинов, рядом с продавцами доспехов и оружия.','Кузнеца и его ученика ты найдешь на Террасе Воинов, рядом с продавцами доспехов и оружия.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Кузнеца и его ученика ты найдешь на Террасе Воинов, рядом с продавцами доспехов и оружия.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Кузнеца и его ученика ты найдешь на Террасе Воинов, рядом с продавцами доспехов и оружия.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17972,'Эти тролли все прибывают и прибывают, |3-6($c).') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эти тролли все прибывают и прибывают, |3-6($c).',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17977,'Силы стихий беспощадны. Вряд ли нам удастся удерживать свои позиции в течение долгого времени. По крайней мере, если мы не получим помощь.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Силы стихий беспощадны. Вряд ли нам удастся удерживать свои позиции в течение долгого времени. По крайней мере, если мы не получим помощь.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17980,'Держать паровые танки на ходу – та еще работенка, скажу я тебе! Но должен же кто-то ее выполнять.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Держать паровые танки на ходу – та еще работенка, скажу я тебе! Но должен же кто-то ее выполнять.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`) VALUES (17986,'Это сын Бет\'тилак, Красной Вдовы. Он будет мстить за своих убитых братьев.','Мы стоим в самом центре кладки Бет\'тилак. За этими колоннами, что к северу от нас, ждут ее дети. Они будут яростно защищать ее.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Это сын Бет\'тилак, Красной Вдовы. Он будет мстить за своих убитых братьев.',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Мы стоим в самом центре кладки Бет\'тилак. За этими колоннами, что к северу от нас, ждут ее дети. Они будут яростно защищать ее.',`text1_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17988,'Зандаларов необходимо остановить. Если под их знамена встанут все тролли Азерота, нам не поздоровится.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Зандаларов необходимо остановить. Если под их знамена встанут все тролли Азерота, нам не поздоровится.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17990,'Приветствую тебя, |3-6($c). Повелитель Огня превратил наших собратьев в олицетворение своей огненной ярости. Даже сейчас друиды работают над выполнением его безумного плана по уничтожению Древа Жизни. Но мы не позволим этому произойти.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Приветствую тебя, |3-6($c). Повелитель Огня превратил наших собратьев в олицетворение своей огненной ярости. Даже сейчас друиды работают над выполнением его безумного плана по уничтожению Древа Жизни. Но мы не позволим этому произойти.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17993,'Эта война лежит тяжелым камнем у меня на сердце. Я веду своих людей на смерть. Но если мы не сможем сейчас выстоять против Рагнароса, то как потом сможем мы противостоять Нелтариону?$b$bМы должны сражаться не на жизнь, а на смерть, либо стать свидетелями крушения всего нашего мира.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эта война лежит тяжелым камнем у меня на сердце. Я веду своих людей на смерть. Но если мы не сможем сейчас выстоять против Рагнароса, то как потом сможем мы противостоять Нелтариону?$b$bМы должны сражаться не на жизнь, а на смерть, либо стать свидетелями крушения всего нашего мира.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (17996,'Как убьете жреца и расчистите путь, дайте знать. Я вернусь к кровавому стражу и сообщу ему обо всем.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Как убьете жреца и расчистите путь, дайте знать. Я вернусь к кровавому стражу и сообщу ему обо всем.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (17999,'Ты здесь, чтобы помочь троллям Черного Копья, |3-6($c)?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты здесь, чтобы помочь троллям Черного Копья, |3-6($c)?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18000,'Я эмиссар троллей Черного Копья. Альянсу тоже не избежать опасности, с которой сейчас столкнулись мы. Хочешь помочь Черному Копью, |3-6($r)?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я эмиссар троллей Черного Копья. Альянсу тоже не избежать опасности, с которой сейчас столкнулись мы. Хочешь помочь Черному Копью, |3-6($r)?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18001,'Спасибо тебе, |3-6($c). Я уж начал думать, что моя жизнь закончится на жертвеннике…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Спасибо тебе, |3-6($c). Я уж начал думать, что моя жизнь закончится на жертвеннике…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18004,'От этого места так и несет смертью и жертвоприношениями.$b$bУходи, если не хочешь угодить в клетку.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','От этого места так и несет смертью и жертвоприношениями.$b$bУходи, если не хочешь угодить в клетку.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18005,'Как же хорошо выйти из клетки. Норкани еще отомстит…') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Как же хорошо выйти из клетки. Норкани еще отомстит…',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18006,'Где я? Ты хочешь мне помочь?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Где я? Ты хочешь мне помочь?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18012,'Эти тролли совершили серьезную ошибку, |3-6($c).') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Эти тролли совершили серьезную ошибку, |3-6($c).',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18015,'Спасибо, что вытащили меня из клетки. Кажется, я снова могу нормально мыслить и способна рассказать Вол\'джину обо всем, что я здесь видела и слышала.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Спасибо, что вытащили меня из клетки. Кажется, я снова могу нормально мыслить и способна рассказать Вол\'джину обо всем, что я здесь видела и слышала.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`) VALUES (18024,'Меня прислали сюда проследить за тем, чтобы работа была выполнена вовремя.$b$bВ Пиратской Бухте все еще борются с последствиями цунами.$b$bМеньше всего нам сейчас нужны тролли-повстанцы, тролли-зомби, ядовитые змеи или двинутые пантеры, которые нападают на все, что движется.','В этой экспедиции я представляю интересы Пиратской Бухты.$b$bЕсли все пойдет наперекосяк, нам придется несладко.$b$bМы все еще пытаемся справиться с последствиями катаклизма.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Меня прислали сюда проследить за тем, чтобы работа была выполнена вовремя.$b$bВ Пиратской Бухте все еще борются с последствиями цунами.$b$bМеньше всего нам сейчас нужны тролли-повстанцы, тролли-зомби, ядовитые змеи или двинутые пантеры, которые нападают на все, что движется.',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','В этой экспедиции я представляю интересы Пиратской Бухты.$b$bЕсли все пойдет наперекосяк, нам придется несладко.$b$bМы все еще пытаемся справиться с последствиями катаклизма.',`text1_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`,`text1_1_loc8`,`text2_1_loc8`,`text3_1_loc8`,`text4_1_loc8`,`text5_1_loc8`,`text6_1_loc8`,`text7_1_loc8`) VALUES (18025,'В основе всего лежит инстинкт выживания.','Что есть война, если не попытка сохранить жизнь? Как семечко пытается пробиться сквозь почву, чтобы прорасти, так и мы сражаемся во имя нашего существования.','Приветствую! Ты начинаешь мне нравиться.','Победим ли мы в этой войне? Время покажет.','Как здесь душно! Им никто не говорил, что можно топить поменьше?','Ты мне нравишься. Мы сработаемся.','Многие называют меня старомодной, но дело просто в том, что у меня ученый вид.','А, это снова ты! Думаешь, мы сможем собрать нужное нам подкрепление?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','В основе всего лежит инстинкт выживания.',`text0_1_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Что есть война, если не попытка сохранить жизнь? Как семечко пытается пробиться сквозь почву, чтобы прорасти, так и мы сражаемся во имя нашего существования.',`text1_1_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Приветствую! Ты начинаешь мне нравиться.',`text2_1_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','Победим ли мы в этой войне? Время покажет.',`text3_1_loc8`), `text4_1_loc8`=IF(`text4_1_loc8` IS NULL OR `text4_1_loc8`='','Как здесь душно! Им никто не говорил, что можно топить поменьше?',`text4_1_loc8`), `text5_1_loc8`=IF(`text5_1_loc8` IS NULL OR `text5_1_loc8`='','Ты мне нравишься. Мы сработаемся.',`text5_1_loc8`), `text6_1_loc8`=IF(`text6_1_loc8` IS NULL OR `text6_1_loc8`='','Многие называют меня старомодной, но дело просто в том, что у меня ученый вид.',`text6_1_loc8`), `text7_1_loc8`=IF(`text7_1_loc8` IS NULL OR `text7_1_loc8`='','А, это снова ты! Думаешь, мы сможем собрать нужное нам подкрепление?',`text7_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18026,'Какая же здесь жара! У меня на лбу можно жарить яичницу.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Какая же здесь жара! У меня на лбу можно жарить яичницу.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18028,'Толо… это ты?..') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Толо… это ты?..',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18029,'Этот Малфурион… отправил говорить со мной $gкакого-то:какую-то:r; |3-1($r) – как это похоже на него.$b$bОн всегда был трусом.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Этот Малфурион… отправил говорить со мной $gкакого-то:какую-то:r; |3-1($r) – как это похоже на него.$b$bОн всегда был трусом.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18030,'Это неважно, |3-6($r). Подробности моего прошлого перестали иметь значение после того, как я присоединилась к друидам пламени. Они тебя не касаются.$b$bЯ здесь затем, чтобы обсудить будущее этого мира. И я не собираюсь разговаривать с тобой.$b$bТак что ответь мне, где Малфурион?!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Это неважно, |3-6($r). Подробности моего прошлого перестали иметь значение после того, как я присоединилась к друидам пламени. Они тебя не касаются.$b$bЯ здесь затем, чтобы обсудить будущее этого мира. И я не собираюсь разговаривать с тобой.$b$bТак что ответь мне, где Малфурион?!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18031,'Прекрасно. Пусть Малфурион приходит в Огненные Просторы, и там мы разберемся с ним. Правосудие может подождать несколько дней.$b$b<Глаза Лиары загораются.>$b$bВерховному друиду таурену, впрочем, не так повезет.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Прекрасно. Пусть Малфурион приходит в Огненные Просторы, и там мы разберемся с ним. Правосудие может подождать несколько дней.$b$b<Глаза Лиары загораются.>$b$bВерховному друиду таурену, впрочем, не так повезет.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18032,'Нельзя откладывать нашу атаку на Огненные Просторы. Мы выступим против Фэндрала и Рагнароса сразу же, как только сможем.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Нельзя откладывать нашу атаку на Огненные Просторы. Мы выступим против Фэндрала и Рагнароса сразу же, как только сможем.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`) VALUES (18037,'Эти тролли пришли просить у нас помощи.','Я вообще ничего не понимаю из того, что эти тролли пытаются мне сказать.','Почему бы этим троллям не попытаться решить свои проблемы самостоятельно?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эти тролли пришли просить у нас помощи.',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Я вообще ничего не понимаю из того, что эти тролли пытаются мне сказать.',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Почему бы этим троллям не попытаться решить свои проблемы самостоятельно?',`text2_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18038,'<Тролль присвистывает, глядя на побоище.>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Тролль присвистывает, глядя на побоище.>',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text2_1_loc8`) VALUES (18041,'Поджигатели бушуют вовсю. Будь осторожнее там.') ON DUPLICATE KEY UPDATE `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Поджигатели бушуют вовсю. Будь осторожнее там.',`text2_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text2_1_loc8`) VALUES (18042,'Поджигатели бушуют вовсю. Будь осторожнее там.') ON DUPLICATE KEY UPDATE `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Поджигатели бушуют вовсю. Будь осторожнее там.',`text2_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18043,'Каждый синий дракон всегда будет помнить о сделанном тобой, $n.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Каждый синий дракон всегда будет помнить о сделанном тобой, $n.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18044,'Могила выглядит старой, спокойной и никем не потревоженной.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Могила выглядит старой, спокойной и никем не потревоженной.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18045,'На могиле лежит плита, но разобрать имя погребенного невозможно.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','На могиле лежит плита, но разобрать имя погребенного невозможно.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (18046,'Я могу научить тебя кулинарному искусству.\r\n\r\nТебя это интересует?','Я могу научить тебя кулинарному искусству.\r\n\r\nТебя это интересует?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я могу научить тебя кулинарному искусству.\r\n\r\nТебя это интересует?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я могу научить тебя кулинарному искусству.\r\n\r\nТебя это интересует?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18047,'Ничего себе, да тут и правда жарковато. Мне даже не нужен мой кузнечный горн.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ничего себе, да тут и правда жарковато. Мне даже не нужен мой кузнечный горн.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18048,'На том острове много обсидиана! Я бы отправилась туда и сама, но не могу перейти через мост.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','На том острове много обсидиана! Я бы отправилась туда и сама, но не могу перейти через мост.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18050,'Ах, ну да. Я забрал свечку у этого мелкого паскудника.\r\n\r\nА тебе-то что надо?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ах, ну да. Я забрал свечку у этого мелкого паскудника.\r\n\r\nА тебе-то что надо?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18063,'Помогать леди Праудмур в ее исследованиях – это большая честь для меня. Ведь она самый могущественный человек-маг во всем Азероте!\r\n\r\nТак могу ли я чем-нибудь помочь тебе?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Помогать леди Праудмур в ее исследованиях – это большая честь для меня. Ведь она самый могущественный человек-маг во всем Азероте!\r\n\r\nТак могу ли я чем-нибудь помочь тебе?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18064,'Да будь в этой башне в два раза больше книг, мне бы все равно не хватило. Моя коллекция никогда не будет окончена.\r\n\r\nИтак. Тебе нужна моя помощь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да будь в этой башне в два раза больше книг, мне бы все равно не хватило. Моя коллекция никогда не будет окончена.\r\n\r\nИтак. Тебе нужна моя помощь?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18067,'Ты говоришь, здесь появился чернокнижник? Здесь, в Тераморе?!\r\n\r\nНе может быть. Кто-то должен немедленно сообщить об этом леди Праудмур!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты говоришь, здесь появился чернокнижник? Здесь, в Тераморе?!\r\n\r\nНе может быть. Кто-то должен немедленно сообщить об этом леди Праудмур!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18070,'Осадные машины почти готовы к бою... и я начинаю скучать!\r\n\r\nЭй, ты случайно не инженер? Можешь сравнить эти чертежи?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Осадные машины почти готовы к бою... и я начинаю скучать!\r\n\r\nЭй, ты случайно не инженер? Можешь сравнить эти чертежи?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18072,'Я, знаешь ли, раньше был в Лиге Исследователей.\r\n\r\nНо потом вдруг осознал, что моя единственная страсть – это драгоценные камни!\r\n\r\nБольшие, сверкающие, разноцветные, дорогие мои, как я вас люблю!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я, знаешь ли, раньше был в Лиге Исследователей.\r\n\r\nНо потом вдруг осознал, что моя единственная страсть – это драгоценные камни!\r\n\r\nБольшие, сверкающие, разноцветные, дорогие мои, как я вас люблю!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18075,'<Посох пульсирует от заключенной в нем магической энергии.>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Посох пульсирует от заключенной в нем магической энергии.>',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18076,'Там, в болотах, можно раздобыть отличную кожу, если только действовать с умом. Такая прорва кроколисков… Пожалуй, мы с братом тут задержимся.n\r\nА чем я могу тебе помочь?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Там, в болотах, можно раздобыть отличную кожу, если только действовать с умом. Такая прорва кроколисков… Пожалуй, мы с братом тут задержимся.n\r\nА чем я могу тебе помочь?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
