INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (18090,'Аллена Брайта можно найти на тренировочной площадке у казармы.\r\n\r\nТам он вместе с доктором Густавом ван Склиффом наблюдают за учениями лекарей острова.','Аллена Брайта можно найти на тренировочной площадке у казармы.\r\n\r\nТам он вместе с доктором Густавом ван Склиффом наблюдают за учениями лекарей острова.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Аллена Брайта можно найти на тренировочной площадке у казармы.\r\n\r\nТам он вместе с доктором Густавом ван Склиффом наблюдают за учениями лекарей острова.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Аллена Брайта можно найти на тренировочной площадке у казармы.\r\n\r\nТам он вместе с доктором Густавом ван Склиффом наблюдают за учениями лекарей острова.',`text0_1_loc8`);
