INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (18091,'Я не уверен. Попробуй спросить Калию Гастингс, ее можно найти у доков. Мне говорили, что у нее есть выход на ШРУ.','Я не уверен. Попробуй спросить Калию Гастингс, ее можно найти у доков. Мне говорили, что у нее есть выход на ШРУ.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я не уверен. Попробуй спросить Калию Гастингс, ее можно найти у доков. Мне говорили, что у нее есть выход на ШРУ.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я не уверен. Попробуй спросить Калию Гастингс, ее можно найти у доков. Мне говорили, что у нее есть выход на ШРУ.',`text0_1_loc8`);
