INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (18093,'Да, и… не говори ей, что это я прислал тебя. Ищи женщину в одежде красного цвета на втором уровне центральной башни.\r\n\r\nЕе зовут Редайя Вонт. Но ни в коем случае не упоминай обо мне!','Да, и… не говори ей, что это я прислала тебя. Ищи женщину в одежде красного цвета на втором уровне центральной башни.\r\n\r\nЕе зовут Редайя Вонт. Но ни в коем случае не упоминай обо мне!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да, и… не говори ей, что это я прислал тебя. Ищи женщину в одежде красного цвета на втором уровне центральной башни.\r\n\r\nЕе зовут Редайя Вонт. Но ни в коем случае не упоминай обо мне!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Да, и… не говори ей, что это я прислала тебя. Ищи женщину в одежде красного цвета на втором уровне центральной башни.\r\n\r\nЕе зовут Редайя Вонт. Но ни в коем случае не упоминай обо мне!',`text0_1_loc8`);
