INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (18094,'Поговори с капитаном Ровноступом, его можно найти на втором этаже казармы. Он займется твоим обучением.','Поговори с капитаном Ровноступом, его можно найти на втором этаже казармы. Он займется твоим обучением.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Поговори с капитаном Ровноступом, его можно найти на втором этаже казармы. Он займется твоим обучением.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Поговори с капитаном Ровноступом, его можно найти на втором этаже казармы. Он займется твоим обучением.',`text0_1_loc8`);
