INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (18095,'Алхимик Наретт и Брент Яшмоцвет обучают алхимии и травничеству в небольшом магазинчике. Они смогут тебе помочь.','Алхимик Наретт и Брент Яшмоцвет обучают алхимии и травничеству в небольшом магазинчике. Они смогут тебе помочь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Алхимик Наретт и Брент Яшмоцвет обучают алхимии и травничеству в небольшом магазинчике. Они смогут тебе помочь.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Алхимик Наретт и Брент Яшмоцвет обучают алхимии и травничеству в небольшом магазинчике. Они смогут тебе помочь.',`text0_1_loc8`);
