INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (18096,'У нас сейчас гостит семейство Опушенный Куст, я знаю, что кто-то из них занимается археологией.\r\n\r\nДумаю, жена главы семьи, Фаэна. Впрочем, оба они в каком-то смысле исследователи. Поищи их в таверне.','У нас сейчас гостит семейство Опушенный Куст, я знаю, что кто-то из них занимается археологией.\r\n\r\nДумаю, жена главы семьи, Фаэна. Впрочем, оба они в каком-то смысле исследователи. Поищи их в таверне.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','У нас сейчас гостит семейство Опушенный Куст, я знаю, что кто-то из них занимается археологией.\r\n\r\nДумаю, жена главы семьи, Фаэна. Впрочем, оба они в каком-то смысле исследователи. Поищи их в таверне.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','У нас сейчас гостит семейство Опушенный Куст, я знаю, что кто-то из них занимается археологией.\r\n\r\nДумаю, жена главы семьи, Фаэна. Впрочем, оба они в каком-то смысле исследователи. Поищи их в таверне.',`text0_1_loc8`);
