INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (18103,'Тебе нужен Теоден Мэннерс, его можно найти на вершине башни леди Праудмур.','Тебе нужен Теоден Мэннерс, его можно найти на вершине башни леди Праудмур.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тебе нужен Теоден Мэннерс, его можно найти на вершине башни леди Праудмур.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Тебе нужен Теоден Мэннерс, его можно найти на вершине башни леди Праудмур.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (18104,'У нас сейчас гостит семейство Опушенный Куст, я знаю, что кто-то из них занимается ювелирным делом.\r\n\r\nДумаю, глава семьи, Инго. Впрочем, оба они в каком-то смысле исследователи. Поищи их в таверне.','У нас сейчас гостит семейство Опушенный Куст, я знаю, что кто-то из них занимается ювелирным делом.\r\n\r\nДумаю, глава семьи, Инго. Впрочем, оба они в каком-то смысле исследователи. Поищи их в таверне.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','У нас сейчас гостит семейство Опушенный Куст, я знаю, что кто-то из них занимается ювелирным делом.\r\n\r\nДумаю, глава семьи, Инго. Впрочем, оба они в каком-то смысле исследователи. Поищи их в таверне.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','У нас сейчас гостит семейство Опушенный Куст, я знаю, что кто-то из них занимается ювелирным делом.\r\n\r\nДумаю, глава семьи, Инго. Впрочем, оба они в каком-то смысле исследователи. Поищи их в таверне.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (18105,'Иди в таверну Терамора и найди там братьев Танвеллов. Один из них сможет помочь тебе.','Иди в таверну Терамора и найди там братьев Танвеллов. Один из них сможет помочь тебе.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Иди в таверну Терамора и найди там братьев Танвеллов. Один из них сможет помочь тебе.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Иди в таверну Терамора и найди там братьев Танвеллов. Один из них сможет помочь тебе.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (18106,'Тебе нужен дворф Керик, его можно найти возле тераморской кузни.\r\n\r\nОн пьяница и не особенно церемонится со взрывчаткой, но он вполне дружелюбен и наверняка поделится своими знаниями относительно горного дела.','Тебе нужен дворф Керик, его можно найти возле тераморской кузни.\r\n\r\nОн пьяница и не особенно церемонится со взрывчаткой, но он вполне дружелюбен и наверняка поделится своими знаниями относительно горного дела.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тебе нужен дворф Керик, его можно найти возле тераморской кузни.\r\n\r\nОн пьяница и не особенно церемонится со взрывчаткой, но он вполне дружелюбен и наверняка поделится своими знаниями относительно горного дела.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Тебе нужен дворф Керик, его можно найти возле тераморской кузни.\r\n\r\nОн пьяница и не особенно церемонится со взрывчаткой, но он вполне дружелюбен и наверняка поделится своими знаниями относительно горного дела.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (18107,'Саша Маквинс – вот кто тебе нужен. Иди к стойлам.','Саша Маквинс – вот кто тебе нужен. Иди к стойлам.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Саша Маквинс – вот кто тебе нужен. Иди к стойлам.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Саша Маквинс – вот кто тебе нужен. Иди к стойлам.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (18108,'На втором этаже одного из самых больших зданий Терамора можно найти Тимоти Уортингтона. Тебе к нему.','На втором этаже одного из самых больших зданий Терамора можно найти Тимоти Уортингтона. Тебе к нему.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','На втором этаже одного из самых больших зданий Терамора можно найти Тимоти Уортингтона. Тебе к нему.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','На втором этаже одного из самых больших зданий Терамора можно найти Тимоти Уортингтона. Тебе к нему.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18113,'Какой сегодня странный ветер. По-настоящему странный.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Какой сегодня странный ветер. По-настоящему странный.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18116,'Воины Гурубаши лезут изо всех щелей! Нас здесь зажали, так что мы не получали вестей с внешних застав уже несколько дней.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Воины Гурубаши лезут изо всех щелей! Нас здесь зажали, так что мы не получали вестей с внешних застав уже несколько дней.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`,`text1_1_loc8`,`text2_1_loc8`) VALUES (18124,'Не беспокойся. Со мной багровый плеточник будет в безопасности. Боюсь, ему стоит остаться в Огненных Просторах, по крайней мере пока мы не изучили как следует его поведение.','Какой необычный вид! Сколько у него возможностей! Мне нужно посвятить себя изучению местной флоры и фауны.','Я поглощена своими исследованиями, так что тебе придется позаботиться о плеточнике и научить его всему.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Не беспокойся. Со мной багровый плеточник будет в безопасности. Боюсь, ему стоит остаться в Огненных Просторах, по крайней мере пока мы не изучили как следует его поведение.',`text0_1_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Какой необычный вид! Сколько у него возможностей! Мне нужно посвятить себя изучению местной флоры и фауны.',`text1_1_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Я поглощена своими исследованиями, так что тебе придется позаботиться о плеточнике и научить его всему.',`text2_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18130,'Да, $gсмертный:смертная;?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да, $gсмертный:смертная;?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18135,'<Темная стражница молча смотрит на вас.>') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','<Темная стражница молча смотрит на вас.>',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18137,'Земля под нашими ногами дрожит и стонет. Огненные дожди идут с неба. Все живое задыхается от горячего воздуха. Мы действительно в царстве Повелителя Огня.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Земля под нашими ногами дрожит и стонет. Огненные дожди идут с неба. Все живое задыхается от горячего воздуха. Мы действительно в царстве Повелителя Огня.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18138,'Отдыхать пока рано, дитя. Хиджал держится, но если мы дрогнем перед Повелителем Огня, мы можем все потерять. Да пребудет с нами сила древних.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Отдыхать пока рано, дитя. Хиджал держится, но если мы дрогнем перед Повелителем Огня, мы можем все потерять. Да пребудет с нами сила древних.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18139,'Наши друиды-вороны с трудом держатся в этом плотном воздухе, но огнеястребы, кажется, чувствуют себя отлично.$b$bОни такие же дикие, как и все в этом царстве огня. Хотя надо признать, что по-своему они красивы.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Наши друиды-вороны с трудом держатся в этом плотном воздухе, но огнеястребы, кажется, чувствуют себя отлично.$b$bОни такие же дикие, как и все в этом царстве огня. Хотя надо признать, что по-своему они красивы.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18140,'Когда-нибудь мы сможем возродить эту землю.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Когда-нибудь мы сможем возродить эту землю.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18141,'Нам с трудом удается удерживать позиции. Каждый солдат, способный держать в руках оружие, должен встать в строй.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Нам с трудом удается удерживать позиции. Каждый солдат, способный держать в руках оружие, должен встать в строй.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18142,'Никогда я еще не видел таких пустынных земель.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Никогда я еще не видел таких пустынных земель.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`,`text1_1_loc8`,`text2_1_loc8`,`text3_1_loc8`) VALUES (18143,'Если у тебя есть какие-то вопросы о стражницах – ответы ты получишь на поле битвы.','Кто такие стражницы? Мы – это меткий удар, всегда достигающий цели.','Кто такие стражницы? Это свист клинка, который ты слышишь перед самой своей смертью.','Кто такие стражницы? Это зловещая тишина тьмы.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Если у тебя есть какие-то вопросы о стражницах – ответы ты получишь на поле битвы.',`text0_1_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Кто такие стражницы? Мы – это меткий удар, всегда достигающий цели.',`text1_1_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Кто такие стражницы? Это свист клинка, который ты слышишь перед самой своей смертью.',`text2_1_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','Кто такие стражницы? Это зловещая тишина тьмы.',`text3_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18144,'Мы многим пожертвовали ради того, чтобы взять эту высоту, и теперь нам осталось только оборонять наши позиции. Да, сейчас у нас мало защитников, но мы надеемся, что в будущем нас поддержат сильные союзники.$B$BНастало время проявить смелость.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы многим пожертвовали ради того, чтобы взять эту высоту, и теперь нам осталось только оборонять наши позиции. Да, сейчас у нас мало защитников, но мы надеемся, что в будущем нас поддержат сильные союзники.$B$BНастало время проявить смелость.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18145,'Благодаря тебе нам удалось отстоять эту заставу.$B$BТы $gпривел:привела; в наши ряды ценного союзника, но наши враги тоже не дремлют.$B$BМы должны сражаться до последнего вздоха, иначе все будет потеряно.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Благодаря тебе нам удалось отстоять эту заставу.$B$BТы $gпривел:привела; в наши ряды ценного союзника, но наши враги тоже не дремлют.$B$BМы должны сражаться до последнего вздоха, иначе все будет потеряно.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18148,'Посмотри вокруг. Что ты видишь? Что ты чувствуешь?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Посмотри вокруг. Что ты видишь? Что ты чувствуешь?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18149,'Крылья Авианы, дайте мне силы удержать огонь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Крылья Авианы, дайте мне силы удержать огонь.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18150,'Добро пожаловать, $n. Ты здесь, чтобы присоединиться к нашей атаке на Огненные Просторы?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Добро пожаловать, $n. Ты здесь, чтобы присоединиться к нашей атаке на Огненные Просторы?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18151,'Пока мы готовимся к вторжению, Повелитель Огня посылает своих приспешников, чтобы отбить атаку. Мы не можем сдавать позиции. За нами Древо Жизни.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Пока мы готовимся к вторжению, Повелитель Огня посылает своих приспешников, чтобы отбить атаку. Мы не можем сдавать позиции. За нами Древо Жизни.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18152,'У нас пока еще недостаточно сил, чтобы вторгнуться в Огненные Просторы. Прежде всего мы должны пополнить запасы и укрепить свои силы. Поможешь ли ты нам?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','У нас пока еще недостаточно сил, чтобы вторгнуться в Огненные Просторы. Прежде всего мы должны пополнить запасы и укрепить свои силы. Поможешь ли ты нам?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18153,'То, что происходит сейчас, затронет нас всех. Нам нужна любая помощь. Мы должны объединиться, чтобы выстоять.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','То, что происходит сейчас, затронет нас всех. Нам нужна любая помощь. Мы должны объединиться, чтобы выстоять.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18154,'Есть здесь милые маленькие зверюшки, которым нужна моя помощь?$b$b<Глаза Милуны вспыхивают при этой мысли.>$b$bЯ сейчас же должна обнять зайчонка!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Есть здесь милые маленькие зверюшки, которым нужна моя помощь?$b$b<Глаза Милуны вспыхивают при этой мысли.>$b$bЯ сейчас же должна обнять зайчонка!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18155,'Как идут приготовления?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Как идут приготовления?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18156,'Что? Верховный друид отдыхает.$b$bУверен, он будет благодарен тебе за визит, но сейчас лучше не беспокоить его.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что? Верховный друид отдыхает.$b$bУверен, он будет благодарен тебе за визит, но сейчас лучше не беспокоить его.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18157,'Трудно сказать. Его раны очень серьезны. Даже учитывая то, что он могущественный друид, на его выздоровление уйдет очень много времени.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Трудно сказать. Его раны очень серьезны. Даже учитывая то, что он могущественный друид, на его выздоровление уйдет очень много времени.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18158,'Приветствую, $n. Ты здесь, чтобы помочь? $gОпытный:Опытная:c; |3-6($c) нам всегда пригодится.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Приветствую, $n. Ты здесь, чтобы помочь? $gОпытный:Опытная:c; |3-6($c) нам всегда пригодится.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18159,'Мне нужен кто-то, кто выполнит работу. Могу я рассчитывать на тебя, |3-6($c)?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мне нужен кто-то, кто выполнит работу. Могу я рассчитывать на тебя, |3-6($c)?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (18160,'Приветствую тебя, маг. Могу я продолжить твое посвящение в мир магии?','Приветствую тебя, маг. Могу я продолжить твое посвящение в мир магии?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приветствую тебя, маг. Могу я продолжить твое посвящение в мир магии?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Приветствую тебя, маг. Могу я продолжить твое посвящение в мир магии?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (18162,'У меня сейчас нет времени на проповеди, |3-6($c). Ищи знаний в другом месте.','У меня сейчас нет времени на проповеди, |3-6($c). Ищи знаний в другом месте.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','У меня сейчас нет времени на проповеди, |3-6($c). Ищи знаний в другом месте.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','У меня сейчас нет времени на проповеди, |3-6($c). Ищи знаний в другом месте.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (18163,'Свет дает нам силу и магию, чтобы одержать победу!','Свет дает нам силу и магию, чтобы одержать победу!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Свет дает нам силу и магию, чтобы одержать победу!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Свет дает нам силу и магию, чтобы одержать победу!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`,`text1_1_loc8`,`text2_1_loc8`,`text3_1_loc8`) VALUES (18165,'В основе всего лежит инстинкт выживания.','Что есть война, если не попытка сохранить жизнь? Как семечко пытается пробиться сквозь почву, чтобы прорасти, так и мы сражаемся во имя нашего существования.','Здравствуй! Я занимаюсь изучением растений. У тебя какая-то проблема с местной флорой?','Нет ничего более вдохновляющего, чем цветущие растения!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','В основе всего лежит инстинкт выживания.',`text0_1_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Что есть война, если не попытка сохранить жизнь? Как семечко пытается пробиться сквозь почву, чтобы прорасти, так и мы сражаемся во имя нашего существования.',`text1_1_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Здравствуй! Я занимаюсь изучением растений. У тебя какая-то проблема с местной флорой?',`text2_1_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','Нет ничего более вдохновляющего, чем цветущие растения!',`text3_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (18166,'Прошу прощения, |3-6($c). Мне показалось, ты из достойных, но это ошибка. Уходи. Я делюсь знаниями только с посвященными.','Прошу прощения, |3-6($c). Мне показалось, ты из достойных, но это ошибка. Уходи. Я делюсь знаниями только с посвященными.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Прошу прощения, |3-6($c). Мне показалось, ты из достойных, но это ошибка. Уходи. Я делюсь знаниями только с посвященными.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Прошу прощения, |3-6($c). Мне показалось, ты из достойных, но это ошибка. Уходи. Я делюсь знаниями только с посвященными.',`text0_1_loc8`);
