INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (18172,'Наша стезя подходит лишь для тех, чья воля тверда, а решимость – непоколебима. В тебе, |3-6($c), я не вижу ни того, ни другого.','Наша стезя подходит лишь для тех, чья воля тверда, а решимость – непоколебима. В тебе, |3-6($c), я не вижу ни того, ни другого.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Наша стезя подходит лишь для тех, чья воля тверда, а решимость – непоколебима. В тебе, |3-6($c), я не вижу ни того, ни другого.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Наша стезя подходит лишь для тех, чья воля тверда, а решимость – непоколебима. В тебе, |3-6($c), я не вижу ни того, ни другого.',`text0_1_loc8`);
