INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (18175,'Если тебя интересует обучение, то я не могу помочь тебе.','Если тебя интересует обучение, то я не могу помочь тебе.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если тебя интересует обучение, то я не могу помочь тебе.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Если тебя интересует обучение, то я не могу помочь тебе.',`text0_1_loc8`);
