INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18185,'Мой Го\'эл… поглощенный морской пучиной. Измученный своими собственными желаниями!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мой Го\'эл… поглощенный морской пучиной. Измученный своими собственными желаниями!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18186,'Опять начинается! Го\'эл превратился в живой камень! Мы должны следовать за ним в пещерах Подземья.$b$bУвидев, что Служители Земли сделали для ее царства, Теразан наверняка захочет помочь нам спасти его. А если нет, клянусь, она за все мне ответит!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Опять начинается! Го\'эл превратился в живой камень! Мы должны следовать за ним в пещерах Подземья.$b$bУвидев, что Служители Земли сделали для ее царства, Теразан наверняка захочет помочь нам спасти его. А если нет, клянусь, она за все мне ответит!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18189,'Чувствуешь волшебство в воздухе, |3-6($c)?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Чувствуешь волшебство в воздухе, |3-6($c)?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (18195,'Ты $gпришел:пришла:c;, чтобы присоединиться к битве, |3-6($c)?','Ты $gпришел:пришла:c;, чтобы присоединиться к битве, |3-6($c)?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты $gпришел:пришла:c;, чтобы присоединиться к битве, |3-6($c)?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты $gпришел:пришла:c;, чтобы присоединиться к битве, |3-6($c)?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18200,'Дети любят этот праздник. Некоторые уже ушли собирать сладости, какие-то остались, а некоторые, как вот эти, решили организовать маленькое собственное дело.$b$bИх цель – собрать как можно больше конфет, и они не придумали ничего лучше, чем делиться конфетами с теми, кто поработает на них. Когда я впервые услышала об этом, я рассмеялась, |3-6($c). Но теперь я вижу, как много тех, кто приносит им конфеты, и начинаю беспокоиться.$b$bЭто же прорва сахара. Не думаю, что эти детки когда-нибудь смогут уснуть.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Дети любят этот праздник. Некоторые уже ушли собирать сладости, какие-то остались, а некоторые, как вот эти, решили организовать маленькое собственное дело.$b$bИх цель – собрать как можно больше конфет, и они не придумали ничего лучше, чем делиться конфетами с теми, кто поработает на них. Когда я впервые услышала об этом, я рассмеялась, |3-6($c). Но теперь я вижу, как много тех, кто приносит им конфеты, и начинаю беспокоиться.$b$bЭто же прорва сахара. Не думаю, что эти детки когда-нибудь смогут уснуть.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18201,'Не имеет значения, как далеко это заведет меня. Я не брошу его.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Не имеет значения, как далеко это заведет меня. Я не брошу его.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18202,'Я смогу телепортировать нас только один раз. Убедись, что ты $gготов:готова;. Го\'эл ждет нас на дне океана…') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я смогу телепортировать нас только один раз. Убедись, что ты $gготов:готова;. Го\'эл ждет нас на дне океана…',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18203,'Мы уже достаточно задержались. Позволь нам немедленно сразиться против этого прислужника Рагнароса.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы уже достаточно задержались. Позволь нам немедленно сразиться против этого прислужника Рагнароса.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18204,'Чем скорее мы окажемся подальше от Матери-Скалы, тем лучше. Я не доверяю ей.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Чем скорее мы окажемся подальше от Матери-Скалы, тем лучше. Я не доверяю ей.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18205,'Можешь просмотреть вещи, которые выставлены на аукцион. А захочешь чего-нибудь продать – зови меня!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Можешь просмотреть вещи, которые выставлены на аукцион. А захочешь чего-нибудь продать – зови меня!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18207,'Как он может просто СТОЯТЬ здесь, когда мы боремся с врагами прямо у его ног?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Как он может просто СТОЯТЬ здесь, когда мы боремся с врагами прямо у его ног?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18208,'Соберись. Огненные Просторы – опасное место, даже для $gтакого:такой:r; |3-1($r), как ты.$b$bСообщи мне, когда будешь $gготов:готова;.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Соберись. Огненные Просторы – опасное место, даже для $gтакого:такой:r; |3-1($r), как ты.$b$bСообщи мне, когда будешь $gготов:готова;.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18212,'Конечно, я поделюсь с тобой своими знаниями.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Конечно, я поделюсь с тобой своими знаниями.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18217,'Здесь ты можешь посмотреть лоты, выставленные на аукцион. Если хочешь, я помогу тебе продать какую-нибудь вещь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Здесь ты можешь посмотреть лоты, выставленные на аукцион. Если хочешь, я помогу тебе продать какую-нибудь вещь.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18220,'Чтобы вызволить Тралла из этого места, нам понадобится помощь ВСЕХ стихий. Воины Рагнароса не смогут сравниться с Циклонасом, Гидриасом или даже Теразан.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Чтобы вызволить Тралла из этого места, нам понадобится помощь ВСЕХ стихий. Воины Рагнароса не смогут сравниться с Циклонасом, Гидриасом или даже Теразан.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18222,'Так и есть. Увидимся на горе Хиджал, друг.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Так и есть. Увидимся на горе Хиджал, друг.',`text0_1_loc8`);
