INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18224,'Добро пожаловать в лавку "Загадка". У нас есть тонкие вина и экзотические товары, которых ты не найдешь больше нигде!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Добро пожаловать в лавку "Загадка". У нас есть тонкие вина и экзотические товары, которых ты не найдешь больше нигде!',`text0_0_loc8`);
