INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (18227,'Переписчика Лидио, наставника начертателей, ты найдешь в южной части Возвышенности Алдоров.','Переписчика Лидио, наставника начертателей, ты найдешь в южной части Возвышенности Алдоров.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Переписчика Лидио, наставника начертателей, ты найдешь в южной части Возвышенности Алдоров.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Переписчика Лидио, наставника начертателей, ты найдешь в южной части Возвышенности Алдоров.',`text0_1_loc8`);
