INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (18229,'Техника Михилу ты найдешь на Возвышенности Алдоров.','Техника Михилу ты найдешь на Возвышенности Алдоров.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Техника Михилу ты найдешь на Возвышенности Алдоров.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Техника Михилу ты найдешь на Возвышенности Алдоров.',`text0_1_loc8`);
