INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (18230,'Наставницу травников Джилию ты найдешь в восточной части Возвышенности Алдоров.','Наставницу травников Джилию ты найдешь в восточной части Возвышенности Алдоров.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Наставницу травников Джилию ты найдешь в восточной части Возвышенности Алдоров.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Наставницу травников Джилию ты найдешь в восточной части Возвышенности Алдоров.',`text0_1_loc8`);
