INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (18233,'Ткачиху Аоа ты найдешь в северо-восточной части Возвышенности Алдоров.','Ткачиху Аоа ты найдешь в северо-восточной части Возвышенности Алдоров.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ткачиху Аоа ты найдешь в северо-восточной части Возвышенности Алдоров.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ткачиху Аоа ты найдешь в северо-восточной части Возвышенности Алдоров.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18238,'Если я в чем-то и уверен, так это в том, что на хорошего друга всегда можно положиться. И если в твоей жизни есть такой человек, береги его.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если я в чем-то и уверен, так это в том, что на хорошего друга всегда можно положиться. И если в твоей жизни есть такой человек, береги его.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18239,'Анрен – мой лучший друг. Я не знаю, что бы я делал без него.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Анрен – мой лучший друг. Я не знаю, что бы я делал без него.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18240,'Мы с Толо через многое прошли вместе. И я всегда знаю, что могу положиться на него.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы с Толо через многое прошли вместе. И я всегда знаю, что могу положиться на него.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18242,'Знаешь ли, как много всего требуется для обеспечения армии, $n? Оружие, продовольствие, укрытия, медикаменты… Список можно продолжить.$b$bПрипасы не возникают из воздуха. Если ты хочешь помочь, поговори с Матой Коготь. Она скажет тебе, что делать.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Знаешь ли, как много всего требуется для обеспечения армии, $n? Оружие, продовольствие, укрытия, медикаменты… Список можно продолжить.$b$bПрипасы не возникают из воздуха. Если ты хочешь помочь, поговори с Матой Коготь. Она скажет тебе, что делать.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18243,'Я восстанавливаю силы перед тем, как снова ринуться в бой. И тебе советую сделать то же самое.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Я восстанавливаю силы перед тем, как снова ринуться в бой. И тебе советую сделать то же самое.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18244,'Здешние пауки ростом с меня! Ты знаешь, как справиться с ними?$b$bДа, именно так. Нужен динамит. Много динамита.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Здешние пауки ростом с меня! Ты знаешь, как справиться с ними?$b$bДа, именно так. Нужен динамит. Много динамита.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18247,'Легенда о большом белом олене существует столько, сколько помнят себя таурены. Скорее всего Малорн видел самый рассвет этого мира. Он был древним духом, воплощением чистоты и сил природы!$b$bДавным-давно великие охотники тауренов в полнолуние отправлялись на поиски белого оленя. Считалось, что если увидеть его сияющую шкуру сквозь деревья хотя бы на мгновение, это принесет великую удачу всему племени на целое поколение.$b$bА известно ли тебе, что Малорн был супругом богини луны?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Легенда о большом белом олене существует столько, сколько помнят себя таурены. Скорее всего Малорн видел самый рассвет этого мира. Он был древним духом, воплощением чистоты и сил природы!$b$bДавным-давно великие охотники тауренов в полнолуние отправлялись на поиски белого оленя. Считалось, что если увидеть его сияющую шкуру сквозь деревья хотя бы на мгновение, это принесет великую удачу всему племени на целое поколение.$b$bА известно ли тебе, что Малорн был супругом богини луны?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18248,'Да, Малорн был супругом самой богини луны, которую ночные эльфы называют Элуной. От их союза родился Кенарий, покровитель всех друидов и один из самых могущественных существ в Азероте.$b$bСлушай дальше.$b$bМалорн обладал неимоверной силой природы, но помогал смертным только во времена серьезных невзгод. Приходилось ли тебе слышать о том, что он совершил во время войны Древних?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Да, Малорн был супругом самой богини луны, которую ночные эльфы называют Элуной. От их союза родился Кенарий, покровитель всех друидов и один из самых могущественных существ в Азероте.$b$bСлушай дальше.$b$bМалорн обладал неимоверной силой природы, но помогал смертным только во времена серьезных невзгод. Приходилось ли тебе слышать о том, что он совершил во время войны Древних?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18249,'Сражайся как следует, солдат. Я не хочу твоей смерти.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Сражайся как следует, солдат. Я не хочу твоей смерти.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18250,'Это знаки нашего уважения, за которые заплачено кровью, пролитой в сражениях. Они важны для нашей победы в этой войне.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Это знаки нашего уважения, за которые заплачено кровью, пролитой в сражениях. Они важны для нашей победы в этой войне.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18251,'Чтобы повысить наши шансы на победу в битве против Рагнароса, мы должны собрать союзников, которые присоединятся к нам в выжженных землях Огненных Просторов. Но прежде чем просить их присоединиться к нам – будь они друидами, солдатами или обычными поставщиками продовольствия – нам нужно знать, что предложить им.$b$bДаже горсть этих знаков говорит о том, что ты многого стоишь. Соберешь несколько сотен – и сможешь командовать армиями.$b$bПонимаешь, к чему я веду?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Чтобы повысить наши шансы на победу в битве против Рагнароса, мы должны собрать союзников, которые присоединятся к нам в выжженных землях Огненных Просторов. Но прежде чем просить их присоединиться к нам – будь они друидами, солдатами или обычными поставщиками продовольствия – нам нужно знать, что предложить им.$b$bДаже горсть этих знаков говорит о том, что ты многого стоишь. Соберешь несколько сотен – и сможешь командовать армиями.$b$bПонимаешь, к чему я веду?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18252,'Позади меня находится восходящий поток воздуха, идущий вверх и наружу. Встань в него и просто подпрыгни. Этого должно быть достаточно чтобы добраться до поверхности.$b$bАх, да. И береги голову!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Позади меня находится восходящий поток воздуха, идущий вверх и наружу. Встань в него и просто подпрыгни. Этого должно быть достаточно чтобы добраться до поверхности.$b$bАх, да. И береги голову!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18253,'Разумеется. Кстати, в глубине пещеры есть потоки воздуха поменьше, они работают таким же образом. Со временем ты научишься пользоваться ими, чтобы быстрее перемещаться по пещере или справляться с этими трусливыми поджигателями.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Разумеется. Кстати, в глубине пещеры есть потоки воздуха поменьше, они работают таким же образом. Со временем ты научишься пользоваться ими, чтобы быстрее перемещаться по пещере или справляться с этими трусливыми поджигателями.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18254,'Мортис, конечно, великий специалист, но я поделюсь с тобой тем, что знаю сама.$b$bЭто не птицы. Да, они умеют летать, их крылья покрыты перьями и даже мы сами называем их ястребами, но больше у них с птицами ничего общего. На самом деле гораздо больше они похожи на драконов. Об этом говорит их огненное естество, склонность к одиночеству и – учитывая то, что мы заметили – их интеллект.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мортис, конечно, великий специалист, но я поделюсь с тобой тем, что знаю сама.$b$bЭто не птицы. Да, они умеют летать, их крылья покрыты перьями и даже мы сами называем их ястребами, но больше у них с птицами ничего общего. На самом деле гораздо больше они похожи на драконов. Об этом говорит их огненное естество, склонность к одиночеству и – учитывая то, что мы заметили – их интеллект.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18255,'Не так ли? Впрочем, если говорить о продолжительности их жизни, то им не сравниться с драконами. В нашем мире драконы живут тысячелетиями, а жизни огнеястребов коротки и пролетают мгновенно.$b$bИ хотя мой хозяин говорил мне, что не стоит слишком привязываться к предмету наших исследований, порою мне все равно их жаль. Они ярко горят при жизни, но после смерти их быстро забывают и заменяют другими.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Не так ли? Впрочем, если говорить о продолжительности их жизни, то им не сравниться с драконами. В нашем мире драконы живут тысячелетиями, а жизни огнеястребов коротки и пролетают мгновенно.$b$bИ хотя мой хозяин говорил мне, что не стоит слишком привязываться к предмету наших исследований, порою мне все равно их жаль. Они ярко горят при жизни, но после смерти их быстро забывают и заменяют другими.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18256,'Что сказать? Это пауки. И не те, к которым мы с тобой привыкли, а огненные.$b$bОни кусаются, они плетут паутину, они плюются жгучим ядом… Они захватили моих лучших друзей и держат их в огненных коконах. Ужасные твари.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что сказать? Это пауки. И не те, к которым мы с тобой привыкли, а огненные.$b$bОни кусаются, они плетут паутину, они плюются жгучим ядом… Они захватили моих лучших друзей и держат их в огненных коконах. Ужасные твари.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18257,'Не имеет значения. Не об этих пауках мы должны думать. Их королева, Бет\'тилак – вот от кого исходит главная опасность. Ее крепость из паутины находится на востоке, за нашими землями. Там ее защищает целая армия пауков, и каждый из них готов отдать жизнь за свою королеву.$b$bКроме того, они огромные! Веришь ты или нет, но четырехметровые пауки, которых ты видишь тут, по сравнению с теми просто безобидные малютки. И хоть они не являются союзниками Рагнароса в буквальном смысле слова, они все равно представляют для нас огромную опасность.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не имеет значения. Не об этих пауках мы должны думать. Их королева, Бет\'тилак – вот от кого исходит главная опасность. Ее крепость из паутины находится на востоке, за нашими землями. Там ее защищает целая армия пауков, и каждый из них готов отдать жизнь за свою королеву.$b$bКроме того, они огромные! Веришь ты или нет, но четырехметровые пауки, которых ты видишь тут, по сравнению с теми просто безобидные малютки. И хоть они не являются союзниками Рагнароса в буквальном смысле слова, они все равно представляют для нас огромную опасность.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18258,'Боюсь, не так уж много. Я не друид, я здесь, чтобы командовать войском. Мне кажется странным, что Малфурион решил посадить дерево в самом эпицентре военных действий, но… как я уже говорила, я не друид.$b$bНо вот что я могу тебе сказать. НИЧТО не смогло бы разозлить этих огненных элементалей так сильно, как решение посадить большое зеленое дерево посреди принадлежащих им земель. Если это дерево вырастет, оно будет олицетворять собой надежду для наших войск и нашу силу – для нашего врага.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Боюсь, не так уж много. Я не друид, я здесь, чтобы командовать войском. Мне кажется странным, что Малфурион решил посадить дерево в самом эпицентре военных действий, но… как я уже говорила, я не друид.$b$bНо вот что я могу тебе сказать. НИЧТО не смогло бы разозлить этих огненных элементалей так сильно, как решение посадить большое зеленое дерево посреди принадлежащих им земель. Если это дерево вырастет, оно будет олицетворять собой надежду для наших войск и нашу силу – для нашего врага.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18259,'Десять тысяч лет назад, когда демоны Пылающего Легиона напали на Азерот, Древние сражались рука об руку с расами смертных. Многие из них погибли в этой войне. Кенарий бы тоже мог погибнуть, если бы не его отец, Малорн.$b$bОгромный олень выскочил на поле боя, круша копытами черепа демонов и разрывая своими рогами их огненные тела.$b$bПосле этого в битву вступил Архимонд Осквернитель. После жестокого сражения он схватил Малорна за рога и... сломал ему шею.$b$bНо разве может такая сила, как Малорн, исчезнуть бесследно, пока в мире еще есть жизнь?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Десять тысяч лет назад, когда демоны Пылающего Легиона напали на Азерот, Древние сражались рука об руку с расами смертных. Многие из них погибли в этой войне. Кенарий бы тоже мог погибнуть, если бы не его отец, Малорн.$b$bОгромный олень выскочил на поле боя, круша копытами черепа демонов и разрывая своими рогами их огненные тела.$b$bПосле этого в битву вступил Архимонд Осквернитель. После жестокого сражения он схватил Малорна за рога и... сломал ему шею.$b$bНо разве может такая сила, как Малорн, исчезнуть бесследно, пока в мире еще есть жизнь?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18260,'Дух Го\'эла – вы называете его Траллом – был разбит на части и разбросан по разным царствам стихий.$b$bСлужители Сумеречного Молота надеются таким образом ослабить нас, но этому не бывать. Мы не отречемся от Го\'эла.$b$bОн всем рисковал, чтобы спасти этот мир, и мы тоже должны сделать для него все!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Дух Го\'эла – вы называете его Траллом – был разбит на части и разбросан по разным царствам стихий.$b$bСлужители Сумеречного Молота надеются таким образом ослабить нас, но этому не бывать. Мы не отречемся от Го\'эла.$b$bОн всем рисковал, чтобы спасти этот мир, и мы тоже должны сделать для него все!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18261,'Когда решишь, что пора отправляться в Ульдум, сообщи мне. Мы поговорим с Циклонасом.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Когда решишь, что пора отправляться в Ульдум, сообщи мне. Мы поговорим с Циклонасом.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18262,'Фэндрал Олений Шлем вернулся в качестве... "друида пламени"?$b$bБоюсь, кто-то из нас тоже может быть замешан в этом предательстве!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Фэндрал Олений Шлем вернулся в качестве... "друида пламени"?$b$bБоюсь, кто-то из нас тоже может быть замешан в этом предательстве!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18263,'Да, |3-6($c), ситуация выглядит не лучшим образом. Но все, что ни делается, все к лучшему.$b$b<Несмотря на эти слова, Ноздорму выглядит изможденным, почти больным.>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да, |3-6($c), ситуация выглядит не лучшим образом. Но все, что ни делается, все к лучшему.$b$b<Несмотря на эти слова, Ноздорму выглядит изможденным, почти больным.>',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18264,'Я бы хотел помочь тебе выполнить твое обязательство. Но в стае синих драконов царит смятение. К тому же есть и другие срочные дела здесь, у Древа Жизни, кторые я призван решить…') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я бы хотел помочь тебе выполнить твое обязательство. Но в стае синих драконов царит смятение. К тому же есть и другие срочные дела здесь, у Древа Жизни, кторые я призван решить…',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18265,'Великий шаман пал от руки Фэндрала Оленьего Шлема?$b$bПохоже, речь идет о большой силе. Сила Рагнароса простирается в этом царстве гораздо дальше, чем я думала.$b$bПовелителя Огня нужно остановить!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Великий шаман пал от руки Фэндрала Оленьего Шлема?$b$bПохоже, речь идет о большой силе. Сила Рагнароса простирается в этом царстве гораздо дальше, чем я думала.$b$bПовелителя Огня нужно остановить!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18266,'Снова ты, |3-6($c).$b$bЧто-то случилось?$b$b<Хвост Алисры подрагивает, ее глаза мечут молнии, веки опускаются ниже.>') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Снова ты, |3-6($c).$b$bЧто-то случилось?$b$b<Хвост Алисры подрагивает, ее глаза мечут молнии, веки опускаются ниже.>',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18267,'Тебя прислали Служители Земли?$b$bИсцеление этих земель начинается здесь, у Древа Жизни. Я рад, что ты здесь и увидишь это.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тебя прислали Служители Земли?$b$bИсцеление этих земель начинается здесь, у Древа Жизни. Я рад, что ты здесь и увидишь это.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (18280,'Эфирная техномантия позволяет изменить тайную сущность вещей. Раньше никто и в самых смелых мыслях не мог мечтать о таком. Также за небольшую плату мы берем вещи на хранение в особом карманном измерении. Более подробно тебе все расскажут мои помощники.$B$BИли у тебя есть какая-то вещь и ты хочешь, чтобы я взглянул на нее?','Эфирная техномантия позволяет изменить тайную сущность вещей. Раньше никто и в самых смелых мыслях не мог мечтать о таком. Также за небольшую плату мы берем вещи на хранение в особом карманном измерении. Более подробно тебе все расскажут мои помощники.$B$BИли у тебя есть какая-то вещь и ты хочешь, чтобы я взглянул на нее?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эфирная техномантия позволяет изменить тайную сущность вещей. Раньше никто и в самых смелых мыслях не мог мечтать о таком. Также за небольшую плату мы берем вещи на хранение в особом карманном измерении. Более подробно тебе все расскажут мои помощники.$B$BИли у тебя есть какая-то вещь и ты хочешь, чтобы я взглянул на нее?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Эфирная техномантия позволяет изменить тайную сущность вещей. Раньше никто и в самых смелых мыслях не мог мечтать о таком. Также за небольшую плату мы берем вещи на хранение в особом карманном измерении. Более подробно тебе все расскажут мои помощники.$B$BИли у тебя есть какая-то вещь и ты хочешь, чтобы я взглянул на нее?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`,`text2_0_loc8`,`text2_1_loc8`,`text3_0_loc8`,`text3_1_loc8`) VALUES (18288,'Установка и обслуживание ярмарочных аттракционов – тяжелая работа...','Установка и обслуживание ярмарочных аттракционов – тяжелая работа...','Я не могу пошевелить рукой.','Я не могу пошевелить рукой.','Что-то эта рана все никак не затянется...','Что-то эта рана все никак не затянется...','Чтоб я еще раз в одиночку подготавливал эту пушку.','Чтоб я еще раз в одиночку подготавливала эту пушку.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Установка и обслуживание ярмарочных аттракционов – тяжелая работа...',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Установка и обслуживание ярмарочных аттракционов – тяжелая работа...',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Я не могу пошевелить рукой.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Я не могу пошевелить рукой.',`text1_1_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Что-то эта рана все никак не затянется...',`text2_0_loc8`), `text2_1_loc8`=IF(`text2_1_loc8` IS NULL OR `text2_1_loc8`='','Что-то эта рана все никак не затянется...',`text2_1_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Чтоб я еще раз в одиночку подготавливал эту пушку.',`text3_0_loc8`), `text3_1_loc8`=IF(`text3_1_loc8` IS NULL OR `text3_1_loc8`='','Чтоб я еще раз в одиночку подготавливала эту пушку.',`text3_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (18289,'Вот молоток, а вот – гноллы.$b$bС тебя жетон – и стучи по гноллам на здоровье!','Вот молоток, а вот – гноллы.$b$bС тебя жетон – и стучи по гноллам на здоровье!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вот молоток, а вот – гноллы.$b$bС тебя жетон – и стучи по гноллам на здоровье!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Вот молоток, а вот – гноллы.$b$bС тебя жетон – и стучи по гноллам на здоровье!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (18290,'Ищешь старые паровые танки?$b$bО, у нас есть новехонькие, если тебя это заинтересует.$b$bВообще говоря, аренда пульта управления танком обходится в два жетончика. Но для военнослужащих у нас скидка – с тебя всего один жетон!$b$bКоллектив ярмарки Новолуния благодарен тебе за службу, |3-6($c).','Ищешь старые паровые танки?$b$bО, у нас есть новехонькие, если тебя это заинтересует.$b$bВообще говоря, аренда пульта управления танком обходится в два жетончика. Но для военнослужащих у нас скидка – с тебя всего один жетон!$b$bКоллектив ярмарки Новолуния благодарен тебе за службу, |3-6($c).') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ищешь старые паровые танки?$b$bО, у нас есть новехонькие, если тебя это заинтересует.$b$bВообще говоря, аренда пульта управления танком обходится в два жетончика. Но для военнослужащих у нас скидка – с тебя всего один жетон!$b$bКоллектив ярмарки Новолуния благодарен тебе за службу, |3-6($c).',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ищешь старые паровые танки?$b$bО, у нас есть новехонькие, если тебя это заинтересует.$b$bВообще говоря, аренда пульта управления танком обходится в два жетончика. Но для военнослужащих у нас скидка – с тебя всего один жетон!$b$bКоллектив ярмарки Новолуния благодарен тебе за службу, |3-6($c).',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18291,'Наша задача – уничтожить цитадель Адского Пламени. И начнем мы с бастионов.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Наша задача – уничтожить цитадель Адского Пламени. И начнем мы с бастионов.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18292,'Вождь приказал захватить цитадель Адского Пламени, и первым делом мы разберемся с ее бастионами.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вождь приказал захватить цитадель Адского Пламени, и первым делом мы разберемся с ее бастионами.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18293,'Мы были на волосок от гибели! Нас сбили... Впрочем, мы почти на месте. Еще один рывок – и мы в храме Драконьего Покоя. $GГотов:Готова;?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы были на волосок от гибели! Нас сбили... Впрочем, мы почти на месте. Еще один рывок – и мы в храме Драконьего Покоя. $GГотов:Готова;?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18294,'Кузня крови – воплощение темного прошлого моего народа.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Кузня крови – воплощение темного прошлого моего народа.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18295,'Если ты не прочь поубивать орков и умеешь держать рот на замке – рад, что ты с нами.$B$BЕсли же нет – на восток отсюда есть за-амечательный портальчик, который, по слухам, в это время года просто чу-удесен!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если ты не прочь поубивать орков и умеешь держать рот на замке – рад, что ты с нами.$B$BЕсли же нет – на восток отсюда есть за-амечательный портальчик, который, по слухам, в это время года просто чу-удесен!',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18297,'Наги выкачивают всю воду для собственных нужд, и в результате целые виды гибнут.$B$BЕсли мы ничего не предпримем – та жизнь, что еще осталась в этом умирающем мире, исчезнет навсегда.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Наги выкачивают всю воду для собственных нужд, и в результате целые виды гибнут.$B$BЕсли мы ничего не предпримем – та жизнь, что еще осталась в этом умирающем мире, исчезнет навсегда.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18299,'Эти грибы – совсем другое дело, не то, что те, наверху. Говорят, они приносят мудрость и ясность ума.$B$BПожалуй, я возьму немного с собой в Спореггар...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эти грибы – совсем другое дело, не то, что те, наверху. Говорят, они приносят мудрость и ясность ума.$B$BПожалуй, я возьму немного с собой в Спореггар...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18300,'Возможность изучить флору и фауну Нижетопи выпадает раз в жизни.$B$BПодумать только – ведь совсем недавно я уже считал себя мертвецом, сидя в ящике в Узилище...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Возможность изучить флору и фауну Нижетопи выпадает раз в жизни.$B$BПодумать только – ведь совсем недавно я уже считал себя мертвецом, сидя в ящике в Узилище...',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (18301,'Трое эфириалов-техномантов открыли мастерскую в Штормграде, на набережной к югу от Соборной площади.$b$bНазывается она "Три ветра". Как увидишь странные машины и лиловые огоньки – это она и есть.$b$bОни оказывают как раз те услуги, что тебя интересуют.','Трое эфириалов-техномантов открыли мастерскую в Штормграде, на набережной к югу от Соборной площади.$b$bНазывается она "Три ветра". Как увидишь странные машины и лиловые огоньки – это она и есть.$b$bОни оказывают как раз те услуги, что тебя интересуют.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Трое эфириалов-техномантов открыли мастерскую в Штормграде, на набережной к югу от Соборной площади.$b$bНазывается она "Три ветра". Как увидишь странные машины и лиловые огоньки – это она и есть.$b$bОни оказывают как раз те услуги, что тебя интересуют.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Трое эфириалов-техномантов открыли мастерскую в Штормграде, на набережной к югу от Соборной площади.$b$bНазывается она "Три ветра". Как увидишь странные машины и лиловые огоньки – это она и есть.$b$bОни оказывают как раз те услуги, что тебя интересуют.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18302,'Принц Харамад все твердил, что если я в ближайшее время не найду способ обойти защиту Шаффара, он назначит меня на роль подопытного кролика.$B$BХм? Нет, он не шутил.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Принц Харамад все твердил, что если я в ближайшее время не найду способ обойти защиту Шаффара, он назначит меня на роль подопытного кролика.$B$BХм? Нет, он не шутил.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18303,'Что означает "Олог"? О, это значит, что я изучаю всё подряд! Я знаю больше о любых известных тебе вещах, нежели кто угодно из тех, кого ты уже знаешь и кого еще когда-либо узнаешь.$B$BУстранить барьер Шаффара для меня – пустяк. Если бы только Морфалиус меня послушал, с ним ничего бы не произошло. Вечно он все делает по-своему.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Что означает "Олог"? О, это значит, что я изучаю всё подряд! Я знаю больше о любых известных тебе вещах, нежели кто угодно из тех, кого ты уже знаешь и кого еще когда-либо узнаешь.$B$BУстранить барьер Шаффара для меня – пустяк. Если бы только Морфалиус меня послушал, с ним ничего бы не произошло. Вечно он все делает по-своему.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18304,'Умершие не принадлежат этому миру.$B$BПочему же мы, похоронив их, продолжаем взывать к ним и искать их?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Умершие не принадлежат этому миру.$B$BПочему же мы, похоронив их, продолжаем взывать к ним и искать их?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18307,'У вас нет ни малейшего представления о том, как управлять этим устройством, но при этом вас наполняет ощущение дежа вю, которое вы никак не можете с себя стряхнуть.$B$BВероятно, стоит оставить эту штуку в покое.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','У вас нет ни малейшего представления о том, как управлять этим устройством, но при этом вас наполняет ощущение дежа вю, которое вы никак не можете с себя стряхнуть.$B$BВероятно, стоит оставить эту штуку в покое.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18308,'Местные духи уже давно подвергаются мучениям. Мы хотим лишь покоя...') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Местные духи уже давно подвергаются мучениям. Мы хотим лишь покоя...',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18312,'Я рад снова видеть тебя.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я рад снова видеть тебя.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18313,'Тише, |3-6($r). Я уже давно не являюсь желанным гостем в Сетекке.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Тише, |3-6($r). Я уже давно не являюсь желанным гостем в Сетекке.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18314,'Не беспокойся, |3-6($c). Араккоа не увидят меня за этим барьером.$B$BЯ здесь по делу.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не беспокойся, |3-6($c). Араккоа не увидят меня за этим барьером.$B$BЯ здесь по делу.',`text0_0_loc8`);
