INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18316,'Полководец Калитреш падет!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Полководец Калитреш падет!',`text0_1_loc8`);
