INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18320,'Чем я могу тебе помочь?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Чем я могу тебе помочь?',`text0_1_loc8`);
