INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18324,'Чем я могу тебе помочь?') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Чем я могу тебе помочь?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18325,'Если хочешь добраться до Калитреша, придется сначала разобраться с анжинером Паропуском и Теспией, гидромантом. Иначе дверь в главную камеру не открыть! Как уладишь свои разногласия с этими двоими – пни как следует панель управления и двери откроются. Наверное.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если хочешь добраться до Калитреша, придется сначала разобраться с анжинером Паропуском и Теспией, гидромантом. Иначе дверь в главную камеру не открыть! Как уладишь свои разногласия с этими двоими – пни как следует панель управления и двери откроются. Наверное.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18329,'У Нижнего Города до недавнего времени существовала обширная агентурная сеть в Темном лабиринте.$B$BА теперь все наши шпионы мертвы. Кроме, разве что, меня и То\'гуна.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','У Нижнего Города до недавнего времени существовала обширная агентурная сеть в Темном лабиринте.$B$BА теперь все наши шпионы мертвы. Кроме, разве что, меня и То\'гуна.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18330,'Лидеры Шаттрата не слишком-то скоры на подъем, поэтому мы, жители Нижнего Города, решили заняться Темным лабиринтом самостоятельно.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Лидеры Шаттрата не слишком-то скоры на подъем, поэтому мы, жители Нижнего Города, решили заняться Темным лабиринтом самостоятельно.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18342,'Мы хотели войны.$B$BМы ее получили.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы хотели войны.$B$BМы ее получили.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18347,'Драконы Алекстразы подберут нас на той стороне раскопок. Проверьте оружие – это место прямо-таки воняет засадой.\r\n\r\nДайте знать, как будете готовы выдвигаться.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Драконы Алекстразы подберут нас на той стороне раскопок. Проверьте оружие – это место прямо-таки воняет засадой.\r\n\r\nДайте знать, как будете готовы выдвигаться.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (18348,'Чтобы сыграть, тебе понадобятся жетоны ярмарки Новолуния.$b$bКупить их можно практически везде на территории ярмарки.$b$bЯ просто отмечу продавцов жетонов на твоей карте.','Чтобы сыграть, тебе понадобятся жетоны ярмарки Новолуния.$b$bКупить их можно практически везде на территории ярмарки.$b$bЯ просто отмечу продавцов жетонов на твоей карте.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Чтобы сыграть, тебе понадобятся жетоны ярмарки Новолуния.$b$bКупить их можно практически везде на территории ярмарки.$b$bЯ просто отмечу продавцов жетонов на твоей карте.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Чтобы сыграть, тебе понадобятся жетоны ярмарки Новолуния.$b$bКупить их можно практически везде на территории ярмарки.$b$bЯ просто отмечу продавцов жетонов на твоей карте.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (18352,'Сначала ты даешь мне один игровой жетончик. Взамен я выдаю тебе пульт управления паровым танком.$b$bПосле этого тебе нужно за ограниченное время разнести попадающиеся на поле боя цели в пух и прах. За уничтожение цели ты получаешь одно очко.$b$bОднако не все так просто! На поле боя тебе встретятся враждебные танки и дирижабли. Если они попадут по тебе, твой танк будет поврежден.$b$bКстати, очки сохраняются между играми, так что ничего страшного, если ты взорвешься.','Сначала ты даешь мне один игровой жетончик. Взамен я выдаю тебе пульт управления паровым танком.$b$bПосле этого тебе нужно за ограниченное время разнести попадающиеся на поле боя цели в пух и прах. За уничтожение цели ты получаешь одно очко.$b$bОднако не все так просто! На поле боя тебе встретятся враждебные танки и дирижабли. Если они попадут по тебе, твой танк будет поврежден.$b$bКстати, очки сохраняются между играми, так что ничего страшного, если ты взорвешься.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Сначала ты даешь мне один игровой жетончик. Взамен я выдаю тебе пульт управления паровым танком.$b$bПосле этого тебе нужно за ограниченное время разнести попадающиеся на поле боя цели в пух и прах. За уничтожение цели ты получаешь одно очко.$b$bОднако не все так просто! На поле боя тебе встретятся враждебные танки и дирижабли. Если они попадут по тебе, твой танк будет поврежден.$b$bКстати, очки сохраняются между играми, так что ничего страшного, если ты взорвешься.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Сначала ты даешь мне один игровой жетончик. Взамен я выдаю тебе пульт управления паровым танком.$b$bПосле этого тебе нужно за ограниченное время разнести попадающиеся на поле боя цели в пух и прах. За уничтожение цели ты получаешь одно очко.$b$bОднако не все так просто! На поле боя тебе встретятся враждебные танки и дирижабли. Если они попадут по тебе, твой танк будет поврежден.$b$bКстати, очки сохраняются между играми, так что ничего страшного, если ты взорвешься.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (18353,'Сначала я выдаю тебе ружье в обмен на один игровой жетончик Новолуния.$B$BЗатем ты начинаешь палить из этого ружья по подсвеченным целям.$b$bПопадешь в цель сразу после ее появления – получишь дополнительное очко.$b$bЕсли не успеешь набрать достаточное количество очков за отведенное время или отойдешь в сторону – не проблема: твои очки сохранятся до следующей игры.','Сначала я выдаю тебе ружье в обмен на один игровой жетончик Новолуния.$B$BЗатем ты начинаешь палить из этого ружья по подсвеченным целям.$b$bПопадешь в цель сразу после ее появления – получишь дополнительное очко.$b$bЕсли не успеешь набрать достаточное количество очков за отведенное время или отойдешь в сторону – не проблема: твои очки сохранятся до следующей игры.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Сначала я выдаю тебе ружье в обмен на один игровой жетончик Новолуния.$B$BЗатем ты начинаешь палить из этого ружья по подсвеченным целям.$b$bПопадешь в цель сразу после ее появления – получишь дополнительное очко.$b$bЕсли не успеешь набрать достаточное количество очков за отведенное время или отойдешь в сторону – не проблема: твои очки сохранятся до следующей игры.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Сначала я выдаю тебе ружье в обмен на один игровой жетончик Новолуния.$B$BЗатем ты начинаешь палить из этого ружья по подсвеченным целям.$b$bПопадешь в цель сразу после ее появления – получишь дополнительное очко.$b$bЕсли не успеешь набрать достаточное количество очков за отведенное время или отойдешь в сторону – не проблема: твои очки сохранятся до следующей игры.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18354,'Осторожно. Демоны рыщут совсем рядом с нами.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Осторожно. Демоны рыщут совсем рядом с нами.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (18362,'Приветствую и добро пожаловать!$b$bПортал, что вы видите здесь, перенесет вас на ярмарку.$b$bЕсли у вас есть какие-либо вопросы – я с удовольствием отвечу на них.','Приветствую и добро пожаловать!$b$bПортал, что вы видите здесь, перенесет вас на ярмарку.$b$bЕсли у вас есть какие-либо вопросы – я с удовольствием отвечу на них.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приветствую и добро пожаловать!$b$bПортал, что вы видите здесь, перенесет вас на ярмарку.$b$bЕсли у вас есть какие-либо вопросы – я с удовольствием отвечу на них.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Приветствую и добро пожаловать!$b$bПортал, что вы видите здесь, перенесет вас на ярмарку.$b$bЕсли у вас есть какие-либо вопросы – я с удовольствием отвечу на них.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (18363,'На ярмарке Новолуния вы найдете всевозможные развлечения и аттракционы. Интересуетесь, что вас ожидает в будущем? Обратитесь к нашему предсказателю. Нравится музыка? Посетите концерт. Для любителей рыбалки мы приготовили увлекательное соревнование. Ну а кроме того, мы предлагаем большой выбор игр и прочих развлечений.$b$bМы постоянно добавляем новые аттракционы и зрелища!$b$bИнтересуешься подробностями?','На ярмарке Новолуния вы найдете всевозможные развлечения и аттракционы. Интересуетесь, что вас ожидает в будущем? Обратитесь к нашему предсказателю. Нравится музыка? Посетите концерт. Для любителей рыбалки мы приготовили увлекательное соревнование. Ну а кроме того, мы предлагаем большой выбор игр и прочих развлечений.$b$bМы постоянно добавляем новые аттракционы и зрелища!$b$bИнтересуешься подробностями?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','На ярмарке Новолуния вы найдете всевозможные развлечения и аттракционы. Интересуетесь, что вас ожидает в будущем? Обратитесь к нашему предсказателю. Нравится музыка? Посетите концерт. Для любителей рыбалки мы приготовили увлекательное соревнование. Ну а кроме того, мы предлагаем большой выбор игр и прочих развлечений.$b$bМы постоянно добавляем новые аттракционы и зрелища!$b$bИнтересуешься подробностями?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','На ярмарке Новолуния вы найдете всевозможные развлечения и аттракционы. Интересуетесь, что вас ожидает в будущем? Обратитесь к нашему предсказателю. Нравится музыка? Посетите концерт. Для любителей рыбалки мы приготовили увлекательное соревнование. Ну а кроме того, мы предлагаем большой выбор игр и прочих развлечений.$b$bМы постоянно добавляем новые аттракционы и зрелища!$b$bИнтересуешься подробностями?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (18364,'О, миниатюрные танки? Это одно из самых старых развлечений, которые мы предлагаем.$b$bУ нас есть две арены для танковых сражений.$b$bНа одной из них вам нужно за определенное время уничтожить требуемое количество целей, при этом избегая огня вражеских танков. Чтобы сыграть, вам понадобится один жетончик.$b$bВторая арена – место, где вы можете, если у вас есть свой танк или дирижабль, сразиться с друзьями.','О, миниатюрные танки? Это одно из самых старых развлечений, которые мы предлагаем.$b$bУ нас есть две арены для танковых сражений.$b$bНа одной из них вам нужно за определенное время уничтожить требуемое количество целей, при этом избегая огня вражеских танков. Чтобы сыграть, вам понадобится один жетончик.$b$bВторая арена – место, где вы можете, если у вас есть свой танк или дирижабль, сразиться с друзьями.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','О, миниатюрные танки? Это одно из самых старых развлечений, которые мы предлагаем.$b$bУ нас есть две арены для танковых сражений.$b$bНа одной из них вам нужно за определенное время уничтожить требуемое количество целей, при этом избегая огня вражеских танков. Чтобы сыграть, вам понадобится один жетончик.$b$bВторая арена – место, где вы можете, если у вас есть свой танк или дирижабль, сразиться с друзьями.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','О, миниатюрные танки? Это одно из самых старых развлечений, которые мы предлагаем.$b$bУ нас есть две арены для танковых сражений.$b$bНа одной из них вам нужно за определенное время уничтожить требуемое количество целей, при этом избегая огня вражеских танков. Чтобы сыграть, вам понадобится один жетончик.$b$bВторая арена – место, где вы можете, если у вас есть свой танк или дирижабль, сразиться с друзьями.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (18366,'Гноллобой – это замечательная и веселая игра, в которой от тебя требуется молотить. Нет, не пшеницу. Гноллов.$b$bМы придумали эту игру совсем недавно и, скажу по секрету, она весьма популярна даже у нас самих. Правда, Воржей относится к ней с прохладцей.','Гноллобой – это замечательная и веселая игра, в которой от тебя требуется молотить. Нет, не пшеницу. Гноллов.$b$bМы придумали эту игру совсем недавно и, скажу по секрету, она весьма популярна даже у нас самих. Правда, Воржей относится к ней с прохладцей.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Гноллобой – это замечательная и веселая игра, в которой от тебя требуется молотить. Нет, не пшеницу. Гноллов.$b$bМы придумали эту игру совсем недавно и, скажу по секрету, она весьма популярна даже у нас самих. Правда, Воржей относится к ней с прохладцей.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Гноллобой – это замечательная и веселая игра, в которой от тебя требуется молотить. Нет, не пшеницу. Гноллов.$b$bМы придумали эту игру совсем недавно и, скажу по секрету, она весьма популярна даже у нас самих. Правда, Воржей относится к ней с прохладцей.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (18369,'Для нас очень важно, чтобы все гости нашей ярмарки – и стар, и млад – могли насладиться предлагаемыми нами развлечениями.$b$bНапример, одна из самых простых игр у нас – метание колец. Задача игрока – метнув кольцо, надеть его на ползущую черепашку.$b$bЭто одна из моих любимых игр.','Для нас очень важно, чтобы все гости нашей ярмарки – и стар, и млад – могли насладиться предлагаемыми нами развлечениями.$b$bНапример, одна из самых простых игр у нас – метание колец. Задача игрока – метнув кольцо, надеть его на ползущую черепашку.$b$bЭто одна из моих любимых игр.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Для нас очень важно, чтобы все гости нашей ярмарки – и стар, и млад – могли насладиться предлагаемыми нами развлечениями.$b$bНапример, одна из самых простых игр у нас – метание колец. Задача игрока – метнув кольцо, надеть его на ползущую черепашку.$b$bЭто одна из моих любимых игр.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Для нас очень важно, чтобы все гости нашей ярмарки – и стар, и млад – могли насладиться предлагаемыми нами развлечениями.$b$bНапример, одна из самых простых игр у нас – метание колец. Задача игрока – метнув кольцо, надеть его на ползущую черепашку.$b$bЭто одна из моих любимых игр.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (18370,'Ринлинг заведует тиром.$b$bНичего сложного – всего лишь три мишени. Чем быстрее поражаешь мишень – тем больше очков получаешь.$b$bЭто одна из моих любимых игр.','Ринлинг заведует тиром.$b$bНичего сложного – всего лишь три мишени. Чем быстрее поражаешь мишень – тем больше очков получаешь.$b$bЭто одна из моих любимых игр.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ринлинг заведует тиром.$b$bНичего сложного – всего лишь три мишени. Чем быстрее поражаешь мишень – тем больше очков получаешь.$b$bЭто одна из моих любимых игр.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ринлинг заведует тиром.$b$bНичего сложного – всего лишь три мишени. Чем быстрее поражаешь мишень – тем больше очков получаешь.$b$bЭто одна из моих любимых игр.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (18371,'Настоятельно рекомендую также посетить Воржея. Его предсказания судьбы пользуются огромным успехом.$b$bДа-да, я знаю, он гнолл. Но он – особенный гнолл. Он способен заглянуть в ваше будущее!','Настоятельно рекомендую также посетить Воржея. Его предсказания судьбы пользуются огромным успехом.$b$bДа-да, я знаю, он гнолл. Но он – особенный гнолл. Он способен заглянуть в ваше будущее!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Настоятельно рекомендую также посетить Воржея. Его предсказания судьбы пользуются огромным успехом.$b$bДа-да, я знаю, он гнолл. Но он – особенный гнолл. Он способен заглянуть в ваше будущее!',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Настоятельно рекомендую также посетить Воржея. Его предсказания судьбы пользуются огромным успехом.$b$bДа-да, я знаю, он гнолл. Но он – особенный гнолл. Он способен заглянуть в ваше будущее!',`text0_1_loc8`);
