INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (18372,'Приветствую, |3-6($c), и добро пожаловать на ярмарку Новолуния!$b$bЗдесь тебя ждет столько всяческих развлечений и аттракционов, что может закружиться голова. С теми, кто приходит к нам в первый раз, это частенько бывает. Собственно, я здесь для того, чтобы новичкам было проще освоиться.$B$BЕсли есть вопросы – обращайся.','Приветствую, |3-6($c), и добро пожаловать на ярмарку Новолуния!$b$bЗдесь тебя ждет столько всяческих развлечений и аттракционов, что может закружиться голова. С теми, кто приходит к нам в первый раз, это частенько бывает. Собственно, я здесь для того, чтобы новичкам было проще освоиться.$B$BЕсли есть вопросы – обращайся.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Приветствую, |3-6($c), и добро пожаловать на ярмарку Новолуния!$b$bЗдесь тебя ждет столько всяческих развлечений и аттракционов, что может закружиться голова. С теми, кто приходит к нам в первый раз, это частенько бывает. Собственно, я здесь для того, чтобы новичкам было проще освоиться.$B$BЕсли есть вопросы – обращайся.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Приветствую, |3-6($c), и добро пожаловать на ярмарку Новолуния!$b$bЗдесь тебя ждет столько всяческих развлечений и аттракционов, что может закружиться голова. С теми, кто приходит к нам в первый раз, это частенько бывает. Собственно, я здесь для того, чтобы новичкам было проще освоиться.$B$BЕсли есть вопросы – обращайся.',`text0_1_loc8`);
