INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (18430,'Лорна рассказывала, что $Gнекий храбрец помог:некая отважная девушка помогла; спасти большую часть лошадей.$b$bНу а я решил позаботиться о тех из них, что успешно преодолели морское путешествие – я научился ухаживать за лошадьми у своих родителей, да пребудет с ними Свет.$b$bПодбираешь себе коня?','Лорна рассказывала, что $Gнекий храбрец помог:некая отважная девушка помогла; спасти большую часть лошадей.$b$bНу а я решила позаботиться о тех из них, что успешно преодолели морское путешествие – я научилась ухаживать за лошадьми у своих родителей, да пребудет с ними Свет.$b$bПодбираешь себе коня?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Лорна рассказывала, что $Gнекий храбрец помог:некая отважная девушка помогла; спасти большую часть лошадей.$b$bНу а я решил позаботиться о тех из них, что успешно преодолели морское путешествие – я научился ухаживать за лошадьми у своих родителей, да пребудет с ними Свет.$b$bПодбираешь себе коня?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Лорна рассказывала, что $Gнекий храбрец помог:некая отважная девушка помогла; спасти большую часть лошадей.$b$bНу а я решила позаботиться о тех из них, что успешно преодолели морское путешествие – я научилась ухаживать за лошадьми у своих родителей, да пребудет с ними Свет.$b$bПодбираешь себе коня?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18452,'В начале года мы ненадолго возвращаемся в ваш мир, чтобы помочь тем, кто нуждается в совете, и поприветствовать тех, кто воссоединился с предками.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','В начале года мы ненадолго возвращаемся в ваш мир, чтобы помочь тем, кто нуждается в совете, и поприветствовать тех, кто воссоединился с предками.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (18463,'Ярмарка Новолуния открыта!$b$bЗа скромную мзду я могу перенести тебя туда.$b$bКак тебе эта идея?','Ярмарка Новолуния открыта!$b$bЗа скромную мзду я могу перенести тебя туда.$b$bКак тебе эта идея?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ярмарка Новолуния открыта!$b$bЗа скромную мзду я могу перенести тебя туда.$b$bКак тебе эта идея?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ярмарка Новолуния открыта!$b$bЗа скромную мзду я могу перенести тебя туда.$b$bКак тебе эта идея?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18510,'Это весьма необычное место.$B$BМагия, действие которой я сейчас поддерживаю, чтобы привести энергетические линии в порядок, в обычных условиях разорвала бы мое тело на куски, но я великолепно себя чувствую!') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Это весьма необычное место.$B$BМагия, действие которой я сейчас поддерживаю, чтобы привести энергетические линии в порядок, в обычных условиях разорвала бы мое тело на куски, но я великолепно себя чувствую!',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18512,'Я немного завидую тебе, $Gмаленький:маленькая; |3-6($r). Тебе довелось узреть самое начало возрождения великой империи Азжол-Неруб.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Я немного завидую тебе, $Gмаленький:маленькая; |3-6($r). Тебе довелось узреть самое начало возрождения великой империи Азжол-Неруб.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18521,'Наши враги полагают, что давно выбили нас из ледяных пустошей.$B$BМы покажем им, чем может обернуться подобное заблуждение.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Наши враги полагают, что давно выбили нас из ледяных пустошей.$B$BМы покажем им, чем может обернуться подобное заблуждение.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (18532,'Плеть так быстро все заполоняет, что я не могу понять, как мы еще не проиграли эту войну.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Плеть так быстро все заполоняет, что я не могу понять, как мы еще не проиграли эту войну.',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18550,'Нас защитят тени.\r\n$bПлащ теней делает меня незаметным, и я могу даровать эту магию и вам.\r\n$bОна не сделает нас невидимыми, но если соблюдать определенную дистанцию, враги не смогут нас обнаружить.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Нас защитят тени.\r\n$bПлащ теней делает меня незаметным, и я могу даровать эту магию и вам.\r\n$bОна не сделает нас невидимыми, но если соблюдать определенную дистанцию, враги не смогут нас обнаружить.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18551,'Ни одно существо за пределами этого круга вокруг вас не сможет вас заметить, однако эта иллюзия пропадет, если вы получите урон или начнете кого-либо атаковать.\r\n$bСоветую вам прятаться до моей команды – эти демоны слишком сильны, чтобы атаковать их в лоб.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ни одно существо за пределами этого круга вокруг вас не сможет вас заметить, однако эта иллюзия пропадет, если вы получите урон или начнете кого-либо атаковать.\r\n$bСоветую вам прятаться до моей команды – эти демоны слишком сильны, чтобы атаковать их в лоб.',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18555,'Надо двигаться дальше. Вы готовы?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Надо двигаться дальше. Вы готовы?',`text0_0_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (18559,'Мы ждем экскурсовода.','Мы ждем экскурсовода.','Этого экскурсовода все нет и нет...','Этого экскурсовода все нет и нет...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы ждем экскурсовода.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мы ждем экскурсовода.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Этого экскурсовода все нет и нет...',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Этого экскурсовода все нет и нет...',`text1_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (18560,'Мы просто ждем гида.','Мы просто ждем гида.','Мы надеемся, что экскурсовода долго ждать не придется.','Мы надеемся, что экскурсовода долго ждать не придется.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы просто ждем гида.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Мы просто ждем гида.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Мы надеемся, что экскурсовода долго ждать не придется.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Мы надеемся, что экскурсовода долго ждать не придется.',`text1_1_loc8`);
