INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`,`text1_0_loc8`,`text1_1_loc8`) VALUES (18563,'Если ты – не экскурсовод, оставь нас.','Если ты – не экскурсовод, оставь нас.','Ты экскурсию проводить пришел или просто пялиться на нас? Исчезни.','Ты экскурсию проводить пришел или просто пялиться на нас? Исчезни.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Если ты – не экскурсовод, оставь нас.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Если ты – не экскурсовод, оставь нас.',`text0_1_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Ты экскурсию проводить пришел или просто пялиться на нас? Исчезни.',`text1_0_loc8`), `text1_1_loc8`=IF(`text1_1_loc8` IS NULL OR `text1_1_loc8`='','Ты экскурсию проводить пришел или просто пялиться на нас? Исчезни.',`text1_1_loc8`);
