INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18593,'Хватит прятаться. Пора сразиться с железными дворфами на их поле.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Хватит прятаться. Пора сразиться с железными дворфами на их поле.',`text0_0_loc8`);
