INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18613,'Терпению моего народа пришел конец! Залы Ульдуара будут очищены от скверны!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Терпению моего народа пришел конец! Залы Ульдуара будут очищены от скверны!',`text0_0_loc8`);
