INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18698,'Настало время повеселиться. Все по местам! Пора подстрелить этого дракона.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Настало время повеселиться. Все по местам! Пора подстрелить этого дракона.',`text0_0_loc8`);
