INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (18740,'Мы догоняем дракона! Кажется, я уже вижу его за облаками!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Мы догоняем дракона! Кажется, я уже вижу его за облаками!',`text0_0_loc8`);
