INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (18879,'Ты $gхотел:хотела; перековать предмет? Я больше не оказываю этих услуг.\r\n\r\nВпрочем, тебе могут помочь эфириалы. Ищи их в "Трех ветрах" в Соборном квартале Штормграда.\r\n\r\nДорогу туда тебе укажет любой городской стражник.','Ты $gхотел:хотела; перековать предмет? Я больше не оказываю этих услуг.\r\n\r\nВпрочем, тебе могут помочь эфириалы. Ищи их в "Трех ветрах" в Соборном квартале Штормграда.\r\n\r\nДорогу туда тебе укажет любой городской стражник.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты $gхотел:хотела; перековать предмет? Я больше не оказываю этих услуг.\r\n\r\nВпрочем, тебе могут помочь эфириалы. Ищи их в "Трех ветрах" в Соборном квартале Штормграда.\r\n\r\nДорогу туда тебе укажет любой городской стражник.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Ты $gхотел:хотела; перековать предмет? Я больше не оказываю этих услуг.\r\n\r\nВпрочем, тебе могут помочь эфириалы. Ищи их в "Трех ветрах" в Соборном квартале Штормграда.\r\n\r\nДорогу туда тебе укажет любой городской стражник.',`text0_1_loc8`);
