INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (20624,'Твои кулинарные умения лишь столь же хороши, как твой самый развитый Путь.','Твои кулинарные умения лишь столь же хороши, как твой самый развитый Путь.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Твои кулинарные умения лишь столь же хороши, как твой самый развитый Путь.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Твои кулинарные умения лишь столь же хороши, как твой самый развитый Путь.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (21709,'Извини, но мне нужно выправить дракончику сломанную лапку. Давай поговорим через пару минут?','Извини, но мне нужно выправить дракончику сломанную лапку. Давай поговорим через пару минут?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Извини, но мне нужно выправить дракончику сломанную лапку. Давай поговорим через пару минут?',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Извини, но мне нужно выправить дракончику сломанную лапку. Давай поговорим через пару минут?',`text0_1_loc8`);
-- ruRU; source: alexkulya@revision-unverified:externals/references/alexkulya/db/2026_08_16_world.sql:npc_text_locale | emucoach@revision-unverified:externals/references/emucoach/db/world.sql:locales_npc_text | loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text1_0_loc8`,`text2_0_loc8`,`text3_0_loc8`) VALUES (21955,'Эй ты! Хочешь прокатиться? Запрыгивай на долгонога!','Если желаешь прокатиться до ярмарки, то садись на долгонога!','Добро пожаловать на остров Новолуния! Садись на долгонога, и она тебя мигом довезет до ярмарки!','Чудесные лесные долгоноги! Бесплатная поездка прямо на ярмарку!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эй ты! Хочешь прокатиться? Запрыгивай на долгонога!',`text0_0_loc8`), `text1_0_loc8`=IF(`text1_0_loc8` IS NULL OR `text1_0_loc8`='','Если желаешь прокатиться до ярмарки, то садись на долгонога!',`text1_0_loc8`), `text2_0_loc8`=IF(`text2_0_loc8` IS NULL OR `text2_0_loc8`='','Добро пожаловать на остров Новолуния! Садись на долгонога, и она тебя мигом довезет до ярмарки!',`text2_0_loc8`), `text3_0_loc8`=IF(`text3_0_loc8` IS NULL OR `text3_0_loc8`='','Чудесные лесные долгоноги! Бесплатная поездка прямо на ярмарку!',`text3_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`,`text0_1_loc8`) VALUES (22587,'Разыщите Лиена Фарнера. Он сможет обучить вас любой профессии.','Разыщите Лиена Фарнера. Он сможет обучить вас любой профессии.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Разыщите Лиена Фарнера. Он сможет обучить вас любой профессии.',`text0_0_loc8`), `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Разыщите Лиена Фарнера. Он сможет обучить вас любой профессии.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (22990,'Будьте осторожны, друзья. Предатель уединился во дворе неподалеку отсюда.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Будьте осторожны, друзья. Предатель уединился во дворе неподалеку отсюда.',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_1_loc8`) VALUES (50001,'Да, я ждала твоего возвращения. Недавно я отправила Корру в лес, и она принесла мне жезл Дартола.$B$BКаких трудов стоило его найти, $n... Прошу тебя, впредь обращайся с ним поаккуратнее.') ON DUPLICATE KEY UPDATE `text0_1_loc8`=IF(`text0_1_loc8` IS NULL OR `text0_1_loc8`='','Да, я ждала твоего возвращения. Недавно я отправила Корру в лес, и она принесла мне жезл Дартола.$B$BКаких трудов стоило его найти, $n... Прошу тебя, впредь обращайся с ним поаккуратнее.',`text0_1_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (50002,'Ты меня видишь? Знаешь, сколько времени я ни с кем не общался только потому, что меня никто не мог увидеть? До чего же здорово наконец-то поговорить!$B$BТак тебя, должно быть, прислал кто-то из моих выживших приятелей-наемников, да? Ну конечно!$B$BНо хватит болтовни, у нас с тобой еще куча работы – если, конечно, ты собираешься все уладить и вернуть Лорду Вальтхалаку его дух.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Ты меня видишь? Знаешь, сколько времени я ни с кем не общался только потому, что меня никто не мог увидеть? До чего же здорово наконец-то поговорить!$B$BТак тебя, должно быть, прислал кто-то из моих выживших приятелей-наемников, да? Ну конечно!$B$BНо хватит болтовни, у нас с тобой еще куча работы – если, конечно, ты собираешься все уладить и вернуть Лорду Вальтхалаку его дух.',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (50003,'Это совсем не трудно, $n. Мой старый отряд наемников, Сокрытый Клинок, взялся не за то дело и не в то время.$B$BНас нанял некто Гремник Скороскок, сомнительный гоблин из Пиратской Бухты. Ему зачем-то понадобилась книга заклинаний Лорда Вальтхалака. Или, может, все дело было в какой-то старой вражде? Теперь мы этого уже не узнаем, потому что Гремника недавно растерзали призрачные убийцы Вальтхалака. Когда их много, они очень опасны.$B$BДа, о чем это я?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Это совсем не трудно, $n. Мой старый отряд наемников, Сокрытый Клинок, взялся не за то дело и не в то время.$B$BНас нанял некто Гремник Скороскок, сомнительный гоблин из Пиратской Бухты. Ему зачем-то понадобилась книга заклинаний Лорда Вальтхалака. Или, может, все дело было в какой-то старой вражде? Теперь мы этого уже не узнаем, потому что Гремника недавно растерзали призрачные убийцы Вальтхалака. Когда их много, они очень опасны.$B$BДа, о чем это я?',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (50004,'Да, это правда.$B$BИтак, мы забрались глубоко в верхнюю часть Черной горы, прямо к тамошнему властителю и предводителю. Это было еще до Драккисата. На мой взгляд, не самый умный шаг, но наш командир Антион Хармон всегда любил сложные задачи. $B$BКак ни удивительно, все шло по плану – до того момента, как мы забрали книгу Вальтхалака из его мертвых рук. Вот тогда-то все и пошло кувырком...$B$BМне продолжать? У тебя что-то глаза остекленели.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да, это правда.$B$BИтак, мы забрались глубоко в верхнюю часть Черной горы, прямо к тамошнему властителю и предводителю. Это было еще до Драккисата. На мой взгляд, не самый умный шаг, но наш командир Антион Хармон всегда любил сложные задачи. $B$BКак ни удивительно, все шло по плану – до того момента, как мы забрали книгу Вальтхалака из его мертвых рук. Вот тогда-то все и пошло кувырком...$B$BМне продолжать? У тебя что-то глаза остекленели.',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (50005,'<Бодли подозрительно смотрит на вас, однако продолжает...>$B$BНу вот, значит, книга у нас, и Кормок, наш двухголовый огр-некромант, как-то жутковато посмотрел всеми четырьмя глазами. Нам на самом деле было страшно, потому что глаза его были как мертвые, ну, знаете, как у коров бывает? И вдруг он как бросится, да как сорвет с Вальтхалака амулет!$B$BИ остальные как обезумели: кто кричал, чтобы он его бросил, а кто себе хотел заграбастать...') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','<Бодли подозрительно смотрит на вас, однако продолжает...>$B$BНу вот, значит, книга у нас, и Кормок, наш двухголовый огр-некромант, как-то жутковато посмотрел всеми четырьмя глазами. Нам на самом деле было страшно, потому что глаза его были как мертвые, ну, знаете, как у коров бывает? И вдруг он как бросится, да как сорвет с Вальтхалака амулет!$B$BИ остальные как обезумели: кто кричал, чтобы он его бросил, а кто себе хотел заграбастать...',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (50006,'Эй, тебе вовсе не нужно просить! В любом случае, я почти закончил историю.$B$BИтак, вся компания дерется посреди того здоровенного зала за амулет, а ты же знаешь, какое там эхо! В конце концов амулет разбился на три части, и мы бросили кости, и части разошлись по рукам.$B$BОстальное малость смешалось в голове, но это потому, что ровно в тот момент дух старого Вальтхалака решил проснуться и принялся вызывать всех тех призрачных убийц.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Эй, тебе вовсе не нужно просить! В любом случае, я почти закончил историю.$B$BИтак, вся компания дерется посреди того здоровенного зала за амулет, а ты же знаешь, какое там эхо! В конце концов амулет разбился на три части, и мы бросили кости, и части разошлись по рукам.$B$BОстальное малость смешалось в голове, но это потому, что ровно в тот момент дух старого Вальтхалака решил проснуться и принялся вызывать всех тех призрачных убийц.',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (50007,'Умерь свой пыл!$B$B*Бодли бормочет себе под нос что-то о нетерпеливости живых*$B$BКак я уже говорил, к нам подобрался дух Лорд Вальтхалака и призрачные убийцы, которых он вызвал, балуясь с некромантией. В то время, замечу, мы были не в состоянии дать им отпор, и потому бежали. Я до сих пор помню, как Мор Серое Копыто, один из наших друидов, поскользнулся и упал, уже в нижней части Вершины.$B$BОстальное, как говорится, совсем другая история.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Умерь свой пыл!$B$B*Бодли бормочет себе под нос что-то о нетерпеливости живых*$B$BКак я уже говорил, к нам подобрался дух Лорд Вальтхалака и призрачные убийцы, которых он вызвал, балуясь с некромантией. В то время, замечу, мы были не в состоянии дать им отпор, и потому бежали. Я до сих пор помню, как Мор Серое Копыто, один из наших друидов, поскользнулся и упал, уже в нижней части Вершины.$B$BОстальное, как говорится, совсем другая история.',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (50008,'Потом мы разделились, вот что случилось. Думаю, слишком много дурной крови... это назревало уже давно. И этот амулет оказался как раз последней соломинкой, сломавшей спину кодо.$B$BС тех самых пор слуги Вальтхалака вылавливают нас по одному. Почти все, кто держал в руках кусочек амулета, уже погибли, отравив душу хранившейся в нем частичкой духа Вальтхалака.$B$BПоэтому я рад, что ты здесь, $n. С твоей помощью мы вновь соединим амулет и сможем вернуть его Лорду Вальтхалаку!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Потом мы разделились, вот что случилось. Думаю, слишком много дурной крови... это назревало уже давно. И этот амулет оказался как раз последней соломинкой, сломавшей спину кодо.$B$BС тех самых пор слуги Вальтхалака вылавливают нас по одному. Почти все, кто держал в руках кусочек амулета, уже погибли, отравив душу хранившейся в нем частичкой духа Вальтхалака.$B$BПоэтому я рад, что ты здесь, $n. С твоей помощью мы вновь соединим амулет и сможем вернуть его Лорду Вальтхалаку!',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (50009,'$n! Ты $gвернулся:вернулась;, только чтобы поговорить со мной? Как это мило! Кстати, этот наряд тебе очень идет.$B$BТы не представляешь, как я рад тебя видеть! Иногда мне так одиноко – меня же почти никто не видит. Ты столько $gсделал:сделала; для всех нас, и я никогда этого не забуду! $B$BСпасибо, что $gзаглянул:заглянула;. Будь как дома!') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','$n! Ты $gвернулся:вернулась;, только чтобы поговорить со мной? Как это мило! Кстати, этот наряд тебе очень идет.$B$BТы не представляешь, как я рад тебя видеть! Иногда мне так одиноко – меня же почти никто не видит. Ты столько $gсделал:сделала; для всех нас, и я никогда этого не забуду! $B$BСпасибо, что $gзаглянул:заглянула;. Будь как дома!',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (50010,'Не плачь, $n. К счастью для тебя, в прошлую встречу я настроился на тот амулет и теперь могу призвать его сюда, где бы он ни был.$B$BВот, попробуй поискать у себя в сумках.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не плачь, $n. К счастью для тебя, в прошлую встречу я настроился на тот амулет и теперь могу призвать его сюда, где бы он ни был.$B$BВот, попробуй поискать у себя в сумках.',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (50011,'Нет, $n, не волнуйтесь! Какую часть амулета вы потеряли?$B$BВы смотрели во всех сумках? А в банке?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Нет, $n, не волнуйтесь! Какую часть амулета вы потеряли?$B$BВы смотрели во всех сумках? А в банке?',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (50012,'Не бойтесь, Бодли сделает все в лучшем виде! Посмотрим... угу... вот. Сейчас я призову его, и все!$B$BГлавное – не потеряйте его снова, $n.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Не бойтесь, Бодли сделает все в лучшем виде! Посмотрим... угу... вот. Сейчас я призову его, и все!$B$BГлавное – не потеряйте его снова, $n.',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (50013,'Да, да, успокойся, |3-6($c), не о чем беспокоиться. Нам повезло, когда ты в первый раз $gдал:дала; мне левую часть, я настроил себя на ее волны, так что призвать ее оттуда, где бы ты ее ни $g"потерял":"потеряла";, – не проблема.$B$BВот, возьми и в этот раз постарайся получше о ней заботиться.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Да, да, успокойся, |3-6($c), не о чем беспокоиться. Нам повезло, когда ты в первый раз $gдал:дала; мне левую часть, я настроил себя на ее волны, так что призвать ее оттуда, где бы ты ее ни $g"потерял":"потеряла";, – не проблема.$B$BВот, возьми и в этот раз постарайся получше о ней заботиться.',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (50014,'Надеюсь, ты шутишь. Нет? Ладно, ладно, не паникуй! К счастью, когда я пропитывал его доставленным твоим снадобьем, то и сам на него настроился. Теперь смогу вернуть его, где бы ты его ни $gпотерял:потеряла;.$B$BА ты точно его $gпотерял:потеряла;? Может, получше в сумках поищешь? И в банке?') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Надеюсь, ты шутишь. Нет? Ладно, ладно, не паникуй! К счастью, когда я пропитывал его доставленным твоим снадобьем, то и сам на него настроился. Теперь смогу вернуть его, где бы ты его ни $gпотерял:потеряла;.$B$BА ты точно его $gпотерял:потеряла;? Может, получше в сумках поищешь? И в банке?',`text0_0_loc8`);
-- ruRU; source: loap@revision-unverified:externals/references/loap/db/world_548_20240722.sql:broadcast_text_locale
INSERT INTO `locales_npc_text` (`id`,`text0_0_loc8`) VALUES (50015,'Вот и ты, $n. Приятно видеть, что мои способности к прорицанию и вызову не покинули меня в этом призрачном состоянии.') ON DUPLICATE KEY UPDATE `text0_0_loc8`=IF(`text0_0_loc8` IS NULL OR `text0_0_loc8`='','Вот и ты, $n. Приятно видеть, что мои способности к прорицанию и вызову не покинули меня в этом призрачном состоянии.',`text0_0_loc8`);
